INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('e9c48a87-e968-4679-b782-18ca53b18478', '六份感情契约，妹嫁才是最终答案？【攻略/救赎/后宫/感情/兄妹】', '日常 · 后宫', '🌸', '六份感情契约，妹嫁才是最终答案？【攻略/救赎/后宫/感情/兄妹】', '六份感情契约，妹嫁才是最终答案？【内置文风】

