  border-color: var(--neon-blue);
  color: #eaf8ff;
  box-shadow: 0 0 20px rgba(111, 201, 255, .3), inset 0 0 12px rgba(111, 201, 255, .1);
  text-shadow: 0 0 8px rgba(111, 201, 255, .5);
}

button.primary:hover {
  background: linear-gradient(180deg, rgba(111, 201, 255, .35), rgba(165, 138, 255, .20));
  border-color: #a8dcff;
  box-shadow: 0 0 36px rgba(111, 201, 255, .65), inset 0 0 16px rgba(111, 201, 255, .2);
}

.btns { display: flex; justify-content: center; gap: 14px; margin-top: 28px; flex-wrap: wrap; }

.bar {
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--neon-blue), var(--gold-dim), var(--neon-pink), transparent);
  margin: 24px 0;
  box-shadow: 0 0 8px rgba(111, 201, 255, .4);
  opacity: .8;
}

.cover-icon {
  width: 140px;
  height: 140px;
  margin: 8px auto 22px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cover-icon::before {
  content: "";
  position: absolute;
  inset: 0;
  border: 2px solid rgba(214, 119, 137, .55);
  border-radius: 50%;
  box-shadow:
    0 0 26px rgba(214, 119, 137, .35),
    inset 0 0 26px rgba(214, 119, 137, .15);
  animation: sealPulse 4s ease-in-out infinite;
}

@keyframes sealPulse {
  0%, 100% { transform: scale(1); opacity: .9; }
  50% { transform: scale(1.04); opacity: 1; box-shadow: 0 0 40px rgba(214, 119, 137, .6), inset 0 0 30px rgba(214, 119, 137, .25); }
}

.cover-icon::after {
  content: "";
  position: absolute;
  inset: 16px;
  border: 1px dashed rgba(111, 201, 255, .35);
  border-radius: 50%;
  animation: spinSlow 22s linear infinite;
}

@keyframes spinSlow {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.cover-runes {
  color: var(--red-bright);
  font-size: 46px;
  letter-spacing: 6px;
  position: relative;
  z-index: 2;
  text-shadow: 0 0 14px rgba(214, 119, 137, .8), 0 0 30px rgba(214, 119, 137, .4);
  animation: runesBreath 3.6s ease-in-out infinite;
}

@keyframes runesBreath {
  0%, 100% { transform: scale(1) rotate(0deg); filter: brightness(1); }
  50% { transform: scale(1.06) rotate(-3deg); filter: brightness(1.35); }
}

.char-switch { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-bottom: 22px; }

.char-tab {
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(255,255,255,.025), transparent);
  padding: 8px 16px;
  border-radius: 999px;
  cursor: pointer;
  font-size: 14px;
  color: var(--text-dim);
  letter-spacing: 1px;
  transition: all .3s;
  backdrop-filter: blur(4px);
}

.char-tab:hover {
  color: var(--neon-blue);
  border-color: var(--neon-blue);
  box-shadow: 0 0 14px rgba(111, 201, 255, .3);
}

.char-tab.active {
  color: #0a1018;
  font-weight: 700;
  background: linear-gradient(180deg, #86b8ff, #c8b0ff);
  border-color: var(--neon-blue);
  box-shadow: 0 0 22px rgba(111, 201, 255, .6);
}

.char-card {
  background: linear-gradient(160deg, #0a1219, #060b12);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 24px;
  animation: fadeUp .5s ease both;
  box-shadow: inset 0 0 50px rgba(0,0,0,.6), 0 0 24px rgba(111, 201, 255, .06);
  position: relative;
  overflow: hidden;
}

.char-card::before {
  content: "";
  position: absolute;
  left: 0; right: 0; bottom: 0;
  height: 40%;
  background:
    repeating-linear-gradient(180deg, transparent 0 6px, rgba(111, 201, 255, .04) 6px 7px),
    linear-gradient(180deg, transparent, rgba(60, 100, 150, .12));
  pointer-events: none;
  mask-image: linear-gradient(180deg, transparent, #000);
  -webkit-mask-image: linear-gradient(180deg, transparent, #000);
}

@keyframes fadeUp { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: translateY(0); } }

.char-card h3 { margin-bottom: 16px; position: relative; z-index: 1; }

.char-pic {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-bottom: 20px;
  position: relative;
  z-index: 1;
}

.char-pic img {
  width: 150px;
  height: 150px;
  object-fit: cover;
  border-radius: 50%;
  border: 3px solid rgba(226, 213, 161, .7);
  box-shadow:
    0 0 26px rgba(111, 201, 255, .45),
    0 0 50px rgba(111, 201, 255, .18),
    inset 0 0 20px rgba(0,0,0,.5);
  padding: 3px;
  background: #060b12;
  animation: avatarGlow 4s ease-in-out infinite;
}

@keyframes avatarGlow {
  0%, 100% { box-shadow: 0 0 22px rgba(111, 201, 255, .4), 0 0 40px rgba(111, 201, 255, .15); }
  50% { box-shadow: 0 0 34px rgba(111, 201, 255, .7), 0 0 60px rgba(111, 201, 255, .35); }
}

.persona-btn {
  margin-top: 12px;
  padding: 8px 18px;
  font-size: 14px;
  border-radius: 999px;
  border: 1px solid #6e5c84;
  background: linear-gradient(180deg, rgba(221, 208, 138, .12), rgba(221, 208, 138, .04));
  color: #ddd08a;
  cursor: pointer;
  transition: all .3s;
  letter-spacing: 1px;
}

.persona-btn:hover {
  background: linear-gradient(180deg, rgba(221, 208, 138, .25), rgba(221, 208, 138, .10));
  border-color: #ddd08a;
  color: #fff3c4;
  box-shadow: 0 0 18px rgba(221, 208, 138, .45);
}

.grid-info { display: grid; grid-template-columns: 1fr 1fr; gap: 12px 20px; position: relative; z-index: 1; }

.info-item {
  padding: 9px 0;
  border-bottom: 1px dashed rgba(111, 201, 255, .12);
}

.info-item span { display: block; font-size: 12px; color: var(--text-dim); letter-spacing: 1.5px; margin-bottom: 3px; }
.info-item b { display: block; font-size: 15px; color: var(--text); font-weight: 600; }

.form { display: grid; gap: 16px; max-width: 640px; margin: 0 auto; }

.form label {
  font-size: 14px;
  color: var(--gold-bright);
  letter-spacing: 1.5px;
  display: block;
  margin-bottom: 8px;
  text-shadow: 0 0 8px rgba(226, 213, 161, .2);
}

.form input, .form textarea {
  width: 100%;
  background: var(--bg-deep);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 13px 16px;
  color: var(--text);
  font-family: inherit;
  font-size: 15px;
  transition: all .3s;
}

.form input:focus, .form textarea:focus {
  outline: none;
  border-color: var(--neon-blue);
  box-shadow: 0 0 18px rgba(111, 201, 255, .4), inset 0 0 12px rgba(111, 201, 255, .05);
}

textarea { resize: vertical; min-height: 100px; }

.routes { display: grid; gap: 14px; margin: 26px 0; }

.route {
  padding: 18px 20px;
  border: 1px solid var(--line);
  border-left: 4px solid var(--neon-blue);
  border-radius: 12px;
  background: linear-gradient(160deg, rgba(111, 201, 255, .05), rgba(0,0,0,.25));
  transition: all .3s;
  position: relative;
  overflow: hidden;
  backdrop-filter: blur(4px);
}

.route::after {
  content: "";
  position: absolute;
  top: 0; left: -100%;
  width: 100%; height: 100%;
  background: linear-gradient(90deg, transparent, rgba(111, 201, 255, .10), transparent);
  transition: left .6s;
}

.route:hover::after { left: 100%; }

.route:hover {
  border-left-color: var(--neon-blue);
  transform: translateX(4px);
  box-shadow: 0 0 22px rgba(111, 201, 255, .3);
}

.route h4 { color: #bcdcff; font-size: 17px; letter-spacing: 2px; margin-bottom: 6px; }

.rule-block {
  background: linear-gradient(160deg, #0a1219, #060b12);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 20px;
  margin: 18px 0;
  box-shadow: inset 0 0 30px rgba(0,0,0,.55);
  position: relative;
}

.rule-block::before {
  content: "";
  position: absolute;
  top: 0; left: 0;
  width: 22px; height: 22px;
  background: linear-gradient(135deg, rgba(226, 213, 161, .35) 0%, rgba(226, 213, 161, .35) 49%, transparent 50%);
  border-top-left-radius: 14px;
}

.rule-block h4 { color: #e8dbb2; margin-bottom: 12px; letter-spacing: 1.5px; }

.rule-line {
  padding: 7px 0;
  border-bottom: 1px dashed rgba(111, 201, 255, .12);
  color: var(--text);
  font-size: 15px;
  line-height: 1.7;
}

.rule-line:last-child { border-bottom: none; }

.rule-line.highlight-red {
  color: #ff8fa0;
  font-weight: 700;
  text-shadow: 0 0 10px rgba(255, 107, 122, .55);
}

.start-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin: 20px 0; }

.start-card {
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(255,255,255,.025), rgba(0,0,0,.2));
  padding: 16px 12px;
  border-radius: 12px;
  cursor: pointer;
  text-align: center;
  transition: all .3s cubic-bezier(.22,.9,.2,1);
  color: var(--text-dim);
  position: relative;
  overflow: hidden;
  backdrop-filter: blur(4px);
}

.start-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, currentColor, transparent 70%);
  opacity: 0;
  transition: opacity .3s;
}

.start-card:hover {
  transform: translateY(-4px);
  filter: brightness(1.2);
  box-shadow: 0 8px 22px rgba(0,0,0,.5), 0 0 18px currentColor;
}

.start-card:hover::before { opacity: .1; }

.start-card.active {
  border-color: var(--neon-blue);
  background: linear-gradient(180deg, rgba(111, 201, 255, .18), rgba(111, 201, 255, .06));
  color: #eaf8ff;
  box-shadow: 0 0 22px rgba(111, 201, 255, .5);
  text-shadow: 0 0 8px rgba(111, 201, 255, .5);
}

.start-card.lin { border-color: var(--lin); color: var(--lin); }
.start-card.gu { border-color: var(--gu); color: var(--gu); }
.start-card.su { border-color: var(--su); color: var(--su); }
.start-card.an { border-color: var(--an); color: var(--an); }
.start-card.ye { border-color: var(--ye); color: var(--ye); }
.start-card.wen { border-color: var(--wen); color: var(--wen); }
.start-card.xia { border-color: var(--xia); color: var(--xia); }

.start-card h5 { font-size: 16px; letter-spacing: 2px; margin-bottom: 4px; position: relative; z-index: 1; }
.start-card p { font-size: 13px; color: var(--text-dim); line-height: 1.5; position: relative; z-index: 1; }

.preview {
  background:
    linear-gradient(180deg, rgba(20, 30, 45, .6), rgba(8, 14, 22, .95)),
    #060b12;
  border: 1px solid var(--gold-dim);
  border-radius: 14px;
  padding: 24px;
  line-height: 2;
  white-space: pre-wrap;
  color: var(--text);
  font-size: 15px;
  margin: 20px 0;
  box-shadow:
    inset 0 0 40px rgba(0,0,0,.7),
    0 0 24px rgba(111, 201, 255, .12);
  font-family: "Noto Serif SC", serif;
  position: relative;
}

.preview::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 6px;
  background:
    radial-gradient(circle at 6px 0, transparent 5px, rgba(226, 213, 161, .25) 5px 6px, transparent 6px) repeat-x;
  background-size: 12px 12px;
}

.final-seven { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; margin: 32px 0; }

.dot {
  width: 24px; height: 24px;
  border-radius: 50%;
  filter: drop-shadow(0 0 8px currentColor);
  animation: dotFloat 3.4s ease-in-out infinite;
  position: relative;
}

.dot::after {
  content: "";
  position: absolute;
  inset: -6px;
  border-radius: 50%;
  border: 1px solid currentColor;
  opacity: .4;
  animation: dotRing 2.2s ease-in-out infinite;
}

@keyframes dotRing {
  0%, 100% { transform: scale(1); opacity: .35; }
  50% { transform: scale(1.3); opacity: 0; }
}

.dot:nth-child(1) { animation-delay: 0s; }
.dot:nth-child(2) { animation-delay: .25s; }
.dot:nth-child(3) { animation-delay: .5s; }
.dot:nth-child(4) { animation-delay: .75s; }
.dot:nth-child(5) { animation-delay: 1s; }
.dot:nth-child(6) { animation-delay: 1.25s; }
.dot:nth-child(7) { animation-delay: 1.5s; }

@keyframes dotFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

.dot.lin { background: var(--lin); color: var(--lin); }
.dot.gu { background: var(--gu); color: var(--gu); }
.dot.su { background: var(--su); color: var(--su); }
.dot.an { background: var(--an); color: var(--an); }
.dot.ye { background: var(--ye); color: var(--ye); }
.dot.wen { background: var(--wen); color: var(--wen); }
.dot.xia { background: var(--xia); color: var(--xia); }

.footer-note { text-align: center; color: var(--text-dim); font-size: 13px; margin-top: 26px; }
.hidden { display: none !important; }

@media (max-width: 680px) {
  .grid-info { grid-template-columns: 1fr; }
  .start-grid { grid-template-columns: repeat(2, 1fr); }
  .char-pic img { width: 120px; height: 120px; }
  .cover-icon { width: 110px; height: 110px; }
  .cover-runes { font-size: 36px; }
}
</style>
</head>
