<script>
/* 生成雨丝 */
(function spawnRain(){
  const box = document.getElementById(''rainLayer'');
  const count = 55;
  for(let i = 0; i < count; i++){
    const el = document.createElement(''i'');
    if(Math.random() < 0.35) el.classList.add(''heavy'');
    el.style.left = Math.random() * 100 + ''vw'';
    const dur = (0.6 + Math.random() * 1.2).toFixed(2);
    el.style.animationDuration = dur + ''s'';
    el.style.animationDelay = (Math.random() * 2).toFixed(2) + ''s'';
    el.style.opacity = (0.25 + Math.random() * 0.55).toFixed(2);
    box.appendChild(el);
  }
})();

