const navTop = document.getElementById("navTop");
pages.forEach(p => {
  const btn = document.createElement("div");
  btn.className = "nav-dot";
  btn.textContent = p.label;
  btn.dataset.target = p.id;
  btn.onclick = () => goPage(p.id);
  if(p.id === "page1") btn.classList.add("active");
  navTop.appendChild(btn);
});

const tabsBox = document.getElementById("charTabs");
charData.forEach((w, i) => {
  const tab = document.createElement("div");
  tab.className = "char-tab" + (i === 0 ? " active" : "");
  tab.textContent = w.name;
  tab.onclick = () => {
    document.querySelectorAll(".char-tab").forEach(t => t.classList.remove("active"));
    tab.classList.add("active");
    currentCharIndex = i;
    xiaPersona = "persona2";
    renderChar(i);
  };
  tabsBox.appendChild(tab);
});

function renderChar(i){
  const w = charData[i];
  const isXia = w.key === "xia";
  const persona = isXia ? (xiaPersona === "persona1" ? w.persona1 : w.persona2) : null;

  const img = isXia ? persona.img : w.img;
  const look = isXia ? persona.look : w.look;
  const body = isXia ? persona.body : w.body;
  const attitude = isXia ? persona.attitude : w.attitude;
  const note = isXia ? persona.note : w.note;

  let html = '''';
  html += ''<div class="char-pic"><img src="'' + img + ''" alt="'' + w.name + ''">'';
  if(isXia){
    html += ''<button class="persona-btn" onclick="toggleXiaPersona()">切换'' + (xiaPersona === "persona2" ? "人格" : "人格") + ''</button>'';
  }
  html += ''</div>'';
  html += ''<h3 style="color:'' + w.color + ''">'' + w.name + '' · '' + w.title + ''</h3><div class="grid-info">'' +
    ''<div class="info-item"><span>身份</span><b>'' + w.title + ''</b></div>'' +
    ''<div class="info-item"><span>外貌</span><b>'' + look + ''</b></div>'' +
    ''<div class="info-item"><span>身材</span><b>'' + body + ''</b></div>'' +
    ''<div class="info-item"><span>初始关系</span><b>'' + w.initial + ''</b></div>'' +
    ''<div class="info-item"><span>对你的态度</span><b>'' + attitude + ''</b></div>'' +
    ''<div class="info-item"><span>背景</span><b>'' + note + ''</b></div>'' +
    ''<div class="info-item"><span>主场</span><b>'' + w.area + ''</b></div>'' +
  ''</div>'';
  document.getElementById("charCard").innerHTML = html;
}

function toggleXiaPersona(){
  xiaPersona = xiaPersona === "persona2" ? "persona1" : "persona2";
  renderChar(currentCharIndex);
}

renderChar(0);

const startGrid = document.getElementById("startGrid");
const startOptions = [
  { key:"xia", name:"夏萤", label:"家族老屋", desc:"清晨，你在妹妹身边醒来" },
  { key:"lin", name:"林知夏", label:"海城高中", desc:"放学后，她被堵在教学楼天台" },
  { key:"an", name:"安小满", label:"安家别墅", desc:"傍晚，她把你拽进地下拳击室" },
  { key:"gu", name:"顾霜", label:"海城湾公寓", desc:"深夜，你被叫到她的落地窗前" },
  { key:"ye", name:"叶甜甜", label:"旧图书馆", desc:"闭馆后，她还没关灯" },
  { key:"su", name:"苏鸾", label:"槐安剧场", desc:"义演散场，她在后台叫住你" },
  { key:"wen", name:"温念安", label:"温念安的家", desc:"囡囡睡了，她一个人站在阳台" },
  { key:"custom", name:"自定义", label:"专属开局", desc:"由你自己写下2026年5月4日的开局" }
];

let selectedStart = "xia";

startOptions.forEach(opt => {
  const card = document.createElement("div");
  card.className = "start-card " + opt.key;
  card.innerHTML = ''<h5>'' + opt.label + ''</h5><p>'' + opt.name + ''</p>'';
  card.onclick = () => {
    document.querySelectorAll(".start-card").forEach(c => c.classList.remove("active"));
    card.classList.add("active");
    selectedStart = opt.key;
    if(opt.key === "custom"){
      document.getElementById("customStartBox").classList.remove("hidden");
    } else {
      document.getElementById("customStartBox").classList.add("hidden");
    }
  };
  if(opt.key === "xia") card.classList.add("active");
  startGrid.appendChild(card);
});

function renderPreview(){
  const name = document.getElementById("playerName").value.trim() || "未定";
  const app = document.getElementById("playerAppearance").value.trim() || "未填写";
  const body = document.getElementById("playerBody").value.trim() || "未填写";
  const per = document.getElementById("playerPersonality").value.trim() || "未填写";
  const extra = document.getElementById("playerExtra").value.trim();

  let startText = "";
  if(selectedStart === "custom"){
    const customText = document.getElementById("customStart").value.trim() || "你在海城醒来。";
    startText = "2026年5月4日。\n" + customText;
  } else {
    const sceneMap = {
      xia: "你在家族老屋的旧床上醒来。天还没全亮，妹妹夏萤正缩在你怀里，手紧紧攥着你的衣服。",
      lin: "你在海城高中天台找到林知夏。她倚在栏杆边，校服被海风吹得微微翻起，听见脚步声后没有回头。",
      an: "你被安小满拽进安家别墅的地下拳击室。冷光灯下，她把一副拳套扔到你怀里。",
      gu: "你来到海城湾3号公寓。顾霜穿着睡袍站在落地窗前，手里捏着半杯没喝的酒。",
      ye: "闭馆后的旧图书馆只剩一点灯光。叶甜甜坐在最里面，听见木地板响，慢慢抬头看你。",
      su: "槐安剧场义演散场。苏鸾站在后台门边，妆还没卸完，见你进来，眼睛忽然亮了一下。",
      wen: "你推开温念安家的门。囡囡已经睡了，温念安一个人站在阳台上，面前是整片海城湾的夜景。"
    };
    startText = "2026年5月4日。\n" + sceneMap[selectedStart];
  }

  let text = "【开局 · 海城契约】\n\n";
  text += "姓名：" + name + "\n";
  text += "性别：男\n";
  text += "外貌：" + app + "\n";
  text += "身材：" + body + "\n";
  text += "性格：" + per + "\n";
  if(extra){
    text += "补充设定：" + extra + "\n";
  }
  text += "\n可用资金：10000 元\n妹妹病情：20%\n初始合同：六份均未到期\n\n";
  text += startText;
  document.getElementById("previewBox").textContent = text;
}

function copyPreview(){
  const text = document.getElementById("previewBox").textContent;
  const ta = document.createElement("textarea");
  ta.value = text;
  ta.setAttribute("readonly", "");
  ta.style.position = "fixed";
  ta.style.left = "-9999px";
  document.body.appendChild(ta);
  ta.select();
  let ok = false;
  try { ok = document.execCommand("copy"); } catch(e){ ok = false; }
  document.body.removeChild(ta);
  alert(ok ? "开局文本已复制。" : "复制失败，请手动复制。");
}
</script>
</body>
