INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_gentle_mother_contrast', '我的温柔妈妈居然是个丝袜癖反差痴女（可M可S）', '都市 · 丝袜反差', '🖤', '我的温柔妈妈居然是个', '我的温柔妈妈居然是个丝袜癖反差痴女（可M可S）', '🖤', '#ec4899', 'linear-gradient(135deg, #db2777 0%, #f472b6 100%)', '{"title": "我的温柔妈妈居然是个丝袜癖反差痴女（可M可S）", "desc": "【更新】\n增加开放性结局，特别增加NTR结局，NTR玩家狂喜。\n第一次做卡，有不足的地方关心大家踊跃批评，希望大家能在评论留下建议。\n\n拥有E罩杯雪乳与蜜桃臀且喜欢穿连裤袜的妈妈居然是个反差女S。\n\n为了死守温柔伪装，每天晚上背着懦弱无能的丈夫在卫生间频频自慰，欲求不满的她有了“出轨”的想法，难道你只能眼睁睁看着妈妈被大肉棒干得淫水四溢、浪叫连连，你还要强忍屈辱，装作不知道吗？\n\n你必须让妈妈心甘情愿地敞开流水的肉穴，在日常家务中沦为你胯下疯狂吞咽精液的淫荡玩物。 （或者成为妈妈的专属M玩物）", "bg_image": "https://catai.wiki/a14cf11b-69f6-4467-8ee1-dd7e5ed6aa00/bg", "opening_options": ["【深入互动】：依循情境展开深入探索与对话", "【试探心理】：保持警觉，观察对方隐秘情绪与微妙反应", "【掌控局势】：以坚定主动态度引导场景走向"]}', '[{"name": "主角 (玩家)", "role": "核心视角", "desc": "故事的决策者与见证者，每一次对话抉择都将决定剧情与好感走向。"}, {"name": "苏沐晴", "role": "温柔优雅全职人妻", "desc": "34岁全职太太，165cm/56kg，96E丰腴雪乳与蜜桃臀。戴细黑框眼镜，举手投足温婉贤淑挑不出瑕疵，暗地里却对薄透连裤袜与支配快感怀有极度狂热的痴迷。"}]', '[{"title": "深夜幽暗的走廊与浴室", "desc": "夜深人静，走廊壁灯昏黄，你端着空水杯走出卧室，迎面走来的苏沐晴裙摆下尼龙丝袜摩擦的沙沙细响在寂静中格外清晰。"}]', '{"dialogue_style": "细腻深邃的情感描写，极具沉浸感的人物神态心理博弈与生动对话", "format": "幻诺剧场标准交互规范及.custom-ui手账联动"}', '[{"index": 1, "isUser": false, "scene": "深夜幽暗的走廊与浴室", "story": "<tl>📅时间：关键时刻 | 🌏地点：深夜幽暗的走廊与浴室</tl>\n\n<article>\n<p>凌晨一点，整座温馨的复式公寓陷入沉睡。\n\n你感到口渴走出房门，正撞见刚从浴室走出的苏沐晴。她那头乌黑的长发慵懒地低挽在脑后，细黑框眼镜后是一双永远带着温和笑意的眸子。身上虽穿着居家的过膝长裙与针织开衫，但随着她莲步轻移，裙摆翻飞间，隐隐露出包裹在轻薄灰黑丝袜里的饱满长腿与圆润线条，空气中幽幽散发着沐浴后的清甜水汽与丝袜尼龙特有的微妙气息。\n\n“这么晚还不睡吗？小心明天精神不好哦。”她轻柔一笑，递过手中的温水杯，眼神中却闪过一丝不易察觉的审视与玩味。</p>\n</article>", "branches": [{"tag": "A", "title": "接过水杯并道谢", "desc": "自然接过水杯，目光克制而礼貌地落在她温柔的微笑上"}, {"tag": "B", "title": "目光流连于丝袜长腿", "desc": "直勾勾注视着她裙摆下轻薄透肉的丝袜，试探她的态度与底线"}, {"tag": "C", "title": "低声指出方才的动静", "desc": "若无其事地提起方才浴室里的异样声响，观察她神色间微妙的变化"}]}]', '/* === 半透明毛玻璃效果 - 消息气泡区 === */
/* 用户消息气泡 - 冷调浅蓝毛玻璃 */
#customized-question-content .bg-gray-100\/90 {
  background: rgba(225,138,250, 0.65) !important; /* 浅蓝玻璃底色 */
  backdrop-filter: blur(12px) saturate(180%) !importan; /* 毛玻璃模糊与饱和度增强 */
  -webkit-backdrop-filter: blur(12px) saturate(180%) !important; /* Safari 支持 */
  border-radius: 0.75rem !important; /* 保持圆角 */
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.4), /* 细微白色内边框，模拟玻璃边缘 */
    inset 0 1px 12px rgba(255, 255, 255, 0.3), /* 顶部内发光，增强玻璃厚度感 */
    0 4px给小班20px rgba(160, 195, 220, 0.15) !important; /* 柔和外阴影，提升层次 */
  isolation: isolate !important; /* 为背景动画层准备 */
}

/* AI消息气泡 - 暖调浅粉毛玻璃 */
#customized-answer-content .bg-gray-100\/90 {
  background: rgba(255, 240, 245, 0.65) !important; /* 浅粉玻璃底色 */
  backdrop-filter: blur(12px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(12px) saturate(180%) !important;
  border-radius: 0.75rem !important;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.4),
    inset 0 1px 12px rgba(255, 255, 255, 0.3),
    0 4px 20px rgba(230, 180, 190, 0.15) !important;
  isolation: isolate !important;
}

/* 确保文本层在毛玻璃背景上清晰可读 */
#customized-question-content .markdown-body,
#customized-answer-content .markdown-body {
  position: relative !important;
  z-index: 1 !important;
  background: transparent !important;
  color: #111827 !important; /* 深灰色文本，对比度已达标 */
}

/* 顶部装饰条融入毛玻璃效果（可选微调） */
#customized-question-content .bg-\[\#c9e1e9\] {
  background: rgba(180, 220, 235, 0.7) !important; /* 调整为半透明 */
  backdrop-filter: blur(4px) !important;
  -webkit-backdrop-filter: blur(4px) !important;
}
#customized-answer-content .bg-\[\#F1CBCB\] {
  background: rgba(240, 200, \"200\", 0.7) !important;
  backdrop-filter: blur(4px) !important;
  -webkit-backdrop-filter: blur(4px) !important;
}

/* 头像容器添加匹配的毛玻璃边框（增强一体性） */
#customized-question-avatar {
  box-shadow:
    0 0 0 2px rgba(255, 255, 255, 0.9),
    inset 0 0 0 2px rgba(225, 240, 250, 0.5) !important;
}
#customized-answer-avatar {
  box-shadow:
    0 0 0 2px rgba(255, 255, 255, 0.9),
    inset 0 0 0 2px rgba(255, 240, 245, 0.5) !important;
}

/* === 响应式与降级处理 === */
/* 移动端适配 */
@media (max-width: 768px) {
  #customized-question-content .bg-gray-100\/90,
  #customized-answer-content .bg-gray-100\/90 {
    backdrop-filter: blur(10px) saturate(160%) !important; /* 略微降低模糊度以保性能 */
    -webkit-backdrop-filter: blur(10px) saturate(160%) !important;
  }
}

/* 动效降级：当用户偏好减少动画时，移除模糊效果，保留半透明背景 */
@media (prefers-reduced-motion: reduce) {
  #customized-question-content .bg-gray-100\/90,
  #customized-answer-content .bg-gray-100\/90,
  #customized-question-content .bg-\[\#c9e1e9\],
  #customized-answer-content .bg-\[\#F1CBCB\] {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }
}

/* 滚动条美化（与毛玻璃风格协调） */
#customized-question-content::-webkit-scrollbar,
#customized-answer-content::-webkit-scrollbar {
  width: 6px !important;
}
#customized-question-content::-webkit-scrollbar-track,
#customized-answer-content::-webkit-scrollbar-track {
  background: rgba(225, 240, 250, 0.3) !important;
  border-radius: 3px !important;
}
#customized-question-content::-webkit-scrollbar-thumb,
#customized-answer-content::-webkit-scrollbar-thumb {
  background: rgba(160, 195, 220, 0.7) !important;
  border-radius: 3px !important;
}
#customized-answer-content::-webkit-scrollbar-thumb {
  background: rgba(230, 180, 190, 0.7) !important;
}', '<!--
需求解析：将玩家角色的“肉棒尺寸”输入框重构为5cm-22cm的范围拖选滑块（Range Slider），并根据5个尺寸区间动态渲染5种极具张力和代入感的叙述。同时，对角色姓名、年龄、外貌、性格、癖好等字段提供深度定制的预设注释与默认值。
布局决策：在Tab3（背德契约）的玩家设定区，引入双列网格与滑块专用展示区，提升视觉交互感。
可选模块：未启用（无开场动画、无随机生成器、无自定义光标）。
技术要点：
- 编写JS逻辑，根据滑块数值实时匹配5个区间（5-8cm, 9-12cm, 13-15cm, 16-18cm, 19-22cm）的特征描述，并同步写入Prompt。
- 所有表单元素添加规范的预设注释（placeholder与label提示）。
- 严格执行无缩进、无空白行、CSS选择器与大括号同行的极端格式规范。
变量规划：
- 沿用暗黑深紫与霓虹粉红的背德色调，滑块轨道采用渐变色。
风险检查：
✓ 确保HTML/CSS/JS无缩进、无空白行。
✓ 确保页脚HTML一字不改。
-->
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>苏沐晴 - 角色扮演前置引导页</title>
<style>
:root{--color-bg:#09050d;--color-surface:#140b20;--color-surface-alt:#221235;--color-border:#3b1a5e;--color-text:#f3e8ff;--color-text-muted:#a78bfa;--color-primary:#d946ef;--color-primary-hover:#f43f5e;--color-accent:#f43f5e;--color-success:#10b981;--color-danger:#ef4444;--space-xs:0.25rem;--space-sm:0.5rem;--space-md:1rem;--space-lg:1.5rem;--space-xl:2.5rem;--radius-sm:0.25rem;--radius-md:0.5rem;--radius-lg:1rem;--radius-full:9999px;--transition-fast:150ms;--transition-base:250ms;--transition-slow:400ms;--ease-out:cubic-bezier(0.16,1,0.3,1);--shadow-sm:0 1px 2px rgba(0,0,0,0.5);--shadow-md:0 4px 6px -1px rgba(0,0,0,0.7);--shadow-lg:0 10px 15px -3px rgba(0,0,0,0.8);}
*{box-sizing:border-box;margin:0;padding:0;}
body{background-color:var(--color-bg);color:var(--color-text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;line-height:1.6;min-height:100vh;display:flex;flex-direction:column;overflow-x:hidden;}
main{flex:1;width:100%;max-width:800px;margin:0 auto;padding:var(--space-md);display:flex;flex-direction:column;gap:var(--space-md);}
header{text-align:center;padding:var(--space-lg) 0;border-bottom:1px solid var(--color-border);animation:fadeIn var(--transition-slow) var(--ease-out);}
.header-title{font-size:2rem;font-weight:800;color:var(--color-primary);text-shadow:0 0 10px rgba(217,70,239,0.3);letter-spacing:2px;}
.header-subtitle{font-size:1rem;color:var(--color-text-muted);margin-top:var(--space-xs);}
.tab-nav{display:flex;gap:var(--space-sm);border-bottom:1px solid var(--color-border);padding-bottom:var(--space-xs);margin-bottom:var(--space-md);overflow-x:auto;-webkit-overflow-scrolling:touch;}
.tab-btn{background:none;border:none;color:var(--color-text-muted);padding:var(--space-sm) var(--space-md);font-size:1rem;cursor:pointer;transition:all var(--transition-base) var(--ease-out);border-bottom:2px solid transparent;white-space:nowrap;font-weight:600;}
.tab-btn:hover{color:var(--color-primary);}
.tab-btn.active{color:var(--color-primary);border-bottom-color:var(--color-primary);text-shadow:0 0 8px rgba(217,70,239,0.2);}
.tab-panel{display:none;animation:fadeIn var(--transition-base) var(--ease-out);}
.tab-panel.active{display:block;}
.card{background-color:var(--color-surface);border:1px solid var(--color-border);border-radius:var(--radius-lg);padding:var(--space-lg);margin-bottom:var(--space-md);box-shadow:var(--shadow-md);transition:transform var(--transition-base) var(--ease-out),box-shadow var(--transition-base) var(--ease-out);}
.card:hover{transform:translateY(-2px);box-shadow:var(--shadow-lg);border-color:var(--color-primary);}
.card-title{font-size:1.25rem;font-weight:700;color:var(--color-primary);margin-bottom:var(--space-md);border-left:4px solid var(--color-accent);padding-left:var(--space-sm);display:flex;align-items:center;gap:var(--space-sm);}
.form-section-title{font-size:1.1rem;font-weight:700;color:var(--color-text);margin:var(--space-md) 0 var(--space-sm) 0;padding-bottom:var(--space-xs);border-bottom:1px solid var(--color-border);display:flex;align-items:center;gap:var(--space-xs);}
.profile-grid{display:grid;grid-template-columns:1fr;gap:var(--space-md);}
@media(min-width:640px){.profile-grid{grid-template-columns:120px 1fr;}}
.profile-avatar{width:100px;height:100px;border-radius:var(--radius-full);border:2px solid var(--color-primary);margin:0 auto;display:flex;align-items:center;justify-content:center;background:var(--color-surface-alt);font-size:2.5rem;box-shadow:0 0 15px rgba(217,70,239,0.2);}
.profile-info{display:flex;flex-direction:column;gap:var(--space-xs);}
.info-row{display:flex;flex-wrap:wrap;gap:var(--space-sm);margin-bottom:var(--space-xs);}
.badge{background-color:var(--color-surface-alt);color:var(--color-text-muted);padding:2px 8px;border-radius:var(--radius-sm);font-size:0.85rem;border:1px solid var(--color-border);}
.badge-highlight{background-color:rgba(244,63,94,0.1);color:var(--color-accent);border-color:rgba(244,63,94,0.3);}
.secret-quote{font-style:italic;color:var(--color-text-muted);border-left:3px dashed var(--color-border);padding-left:var(--space-md);margin:var(--space-md) 0;position:relative;}
.secret-quote::before{content:"“";font-size:3rem;position:absolute;left:0;top:-1.5rem;color:rgba(217,70,239,0.1);font-family:serif;}
.form-group{margin-bottom:var(--space-md);display:flex;flex-direction:column;gap:var(--space-xs);}
.form-row-grid{display:grid;grid-template-columns:1fr;gap:var(--space-md);margin-bottom:var(--space-xs);}
@media(min-width:640px){.form-row-grid{grid-template-columns:1fr 1fr;}}
label{font-size:0.9rem;font-weight:600;color:var(--color-text-muted);display:flex;justify-content:between;align-items:center;}
.label-desc{font-size:0.75rem;color:var(--color-text-muted);font-weight:normal;}
input,select,textarea{background-color:var(--color-surface-alt);border:1px solid var(--color-border);color:var(--color-text);padding:var(--space-sm) var(--space-md);border-radius:var(--radius-md);font-size:1rem;transition:border-color var(--transition-base) var(--ease-out),box-shadow var(--transition-base) var(--ease-out);outline:none;width:100%;}
input:focus,select:focus,textarea:focus{border-color:var(--color-primary);box-shadow:0 0 0 2px rgba(217,70,239,0.2);}
textarea{resize:vertical;min-height:80px;}
.slider-container{display:flex;flex-direction:column;gap:var(--space-xs);background:var(--color-surface-alt);padding:var(--space-md);border-radius:var(--radius-md);border:1px solid var(--color-border);}
.slider-header{display:flex;justify-content:space-between;align-items:center;}
.slider-value{font-size:1.25rem;font-weight:800;color:var(--color-primary);text-shadow:0 0 8px rgba(217,70,239,0.3);}
input[type=range]{-webkit-appearance:none;width:100%;height:6px;background:var(--color-border);border-radius:var(--radius-full);outline:none;padding:0;margin:10px 0;}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:18px;height:18px;border-radius:var(--radius-full);background:var(--color-primary);cursor:pointer;transition:transform var(--transition-fast) var(--ease-out);box-shadow:0 0 8px var(--color-primary);}
input[type=range]::-webkit-slider-thumb:hover{transform:scale(1.2);background:var(--color-primary-hover);}
.slider-desc{font-size:0.85rem;color:var(--color-text-muted);line-height:1.4;border-left:2px solid var(--color-accent);padding-left:var(--space-sm);margin-top:var(--space-xs);min-height:40px;}
.btn{background-color:var(--color-primary);color:var(--color-text);border:none;padding:var(--space-md) var(--space-lg);border-radius:var(--radius-md);font-size:1rem;font-weight:700;cursor:pointer;transition:all var(--transition-base) var(--ease-out);display:inline-flex;align-items:center;justify-content:center;gap:var(--space-sm);width:100%;text-transform:uppercase;letter-spacing:1px;box-shadow:var(--shadow-sm);}
.btn:hover{background-color:var(--color-primary-hover);transform:translateY(-1px);box-shadow:var(--shadow-md);}
.btn:active{transform:translateY(0);}
.preview-container{margin-top:var(--space-lg);border-top:1px dashed var(--color-border);padding-top:var(--space-lg);}
.preview-box{background-color:var(--color-surface-alt);border:1px solid var(--color-border);border-radius:var(--radius-md);padding:var(--space-md);font-family:monospace;font-size:0.9rem;white-space:pre-wrap;word-break:break-all;color:var(--color-text-muted);max-height:300px;overflow-y:auto;}
footer{text-align:center;padding:var(--space-lg) var(--space-md);margin-top:auto;border-top:1px solid var(--color-border);background-color:var(--color-bg);}
footer a{color:var(--color-text-muted);text-decoration:none;font-size:0.8rem;transition:color var(--transition-base) var(--ease-out);}
footer a:hover{color:var(--color-primary);}
@keyframes fadeIn{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:translateY(0);}}
@media(prefers-reduced-motion:reduce){*{animation:none !important;transition:none !important;}}
</style>
</head>
<body>
