const playerSizeDesc = getDescForSize(playerSizeVal);
const playerFetish = document.getElementById(''player-fetish'').value.trim();
const playerRole = document.getElementById(''player-role'').value;
const playStyle = document.getElementById(''play-style'').value;
const stockingType = document.getElementById(''stocking-type'').value;
