INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('e0fbfdcc-79d1-42f7-b790-ef386449a25f', '弟弟和妹妹乱伦被抓，养母竟然命令我当着弟弟的面给妹妹开苞', '乱伦 · 调教', '📖', '弟弟和妹妹乱伦被抓，养母竟然命令我当着弟弟的面给妹妹开苞', '厚重的红木门在你身后缓缓合上，发出一声沉闷的钝响，像某种不可逆转的宣判。

走廊里佣人们惊惶的窃窃私语被彻底隔绝在外。屋内，水晶吊灯惨白的光线毫无遮拦地倾泻而下', '📖', '#d946ef', 'linear-gradient(135deg, #d946ef 0%, #8b5cf6 100%)', '{"title": "弟弟和妹妹乱伦被抓，养母竟然命令我当着弟弟的面给妹妹开苞", "desc": "厚重的红木门在你身后缓缓合上，发出一声沉闷的钝响，像某种不可逆转的宣判。\n\n走廊里佣人们惊惶的窃窃私语被彻底隔绝在外。屋内，水晶吊灯惨白的光线毫无遮拦地倾泻而下，将这场豪门丑剧的每一处细节都照得纤毫毕现。\n\n沈曼殊站在一片狼藉的正中央。她转过身，目光落在你身上。\n\n\"好孩子。\"她开口，声音里带着一种刻意压制的、近乎病态的温柔，\"妈就知道，你比你那个不成器的弟弟懂事。\"\n\n她抬起手，涂着猩红蔻丹的手", "bg_image": ""}', '[]', '[]', '{}', '[{"isUser": false, "story": "【序章 · 初临】\n\n厚重的红木门在你身后缓缓合上，发出一声沉闷的钝响，像某种不可逆转的宣判。\n\n走廊里佣人们惊惶的窃窃私语被彻底隔绝在外。屋内，水晶吊灯惨白的光线毫无遮拦地倾泻而下，将这场豪门丑剧的每一处细节都照得纤毫毕现。\n\n沈曼殊站在一片狼藉的正中央。她转过身，目光落在你身上。\n\n\"好孩子。\"她开口，声音里带着一种刻意压制的、近乎病态的温柔，\"妈就知道，你比你那个不成器的弟弟懂事。\"\n\n她抬起手，涂着猩红蔻丹的手指轻轻拍了拍你的脸颊。\n\n\"你也算是我养大的。我这个当妈的，过去从没求过你什么。妈今天求你，帮妈办件事。\"\n\n她侧过头，用下巴点了点地毯上蜷缩成一团的身影。\n\n林悠然瘫坐在冰冷的地毯上，身上那件纯白的真丝睡裙被撕扯得大半滑落，露出大片雪白的香肩和胸前娇嫩的肌肤，上面赫然印着几枚刺眼的暧昧红痕。她哭得梨花带雨，双手死死攥着胸前仅剩的布料。\n\n而在她几步之外，林天正被两名彪形保镖死死按在地板上，双眼猩红，脖子上青筋暴起。\n\n\"{{user}}。\"她伸手指着地毯上瑟瑟发抖的林悠然，一字一句地命令道，\"你就在这儿，当着你这个不争气的弟弟的面，给这个小狐狸精开开苞。\"\n\n\"妈！！你疯了吗！！{{user}}！！你敢碰她我绝对杀了你！！\"\n\n地上的林悠然吓得小脸惨白，那双像受惊小鹿般水润的眼睛充满恐惧与无助地望向你。\n\n沈曼殊死死盯着你，嘴角勾起一抹残忍的弧度：\"我要让你亲眼看看，你当成宝贝护着的贱女人，是怎么在别的男人身下发浪的。\"\n\n她抬起眼，目光像一把冰冷的刀，直直刺向你。\n\n\"{{user}}，关门。脱衣服。\"\n\n阳光穿透微隙，周围的喧嚣渐渐清晰。你迈出脚步，开启了在这片天地间的全新篇章……", "branches": [{"tag": "A", "title": "环顾四周观察当前局势", "desc": "环顾四周观察当前局势"}, {"tag": "B", "title": "顺应眼前的指引前行", "desc": "顺应眼前的指引前行"}]}]', '/* ===== 全局基础 ===== */
