function pScene(el){
var p=el.parentNode,k=p.children;
for(var i=0;i<k.length;i++){k[i].style.background=''rgba(10,8,12,0.6)'';k[i].style.borderColor=''#1c1630'';k[i].style.color=''#8a7a92'';}
el.style.background=''rgba(240,168,168,0.15)'';el.style.borderColor=''#f0a8a8'';el.style.color=''#fff'';
