function pGen(){
var n=document.getElementById(''p-name'').value.trim()||''大少爷'';
var extra=document.getElementById(''p-extra'').value.trim();
var t=''【玩家角色设定】\n姓名：''+n+''\n性格：''+(pPersonaV||''服从养母'')+''\n目标结局：''+(pEndingV||''掌控线'')+''\n开局场景：''+(pSceneV||''主卧命令'')+''\n'';
if(extra){t+=''补充设定：''+extra+''\n'';}
t+=''\n【核心人物】\n林悠然，19岁，林家私生女，被林天养成菟丝花。被沈曼殊命令当众开苞。\n沈曼殊，42岁，养母，恨林悠然，命令你在林天面前给林悠然开苞。\n林天，20岁，林家少爷，爱林悠然，被保镖按在地上。\n你是林家养子，父亲替家主挡劫换来实权地位。\n\n请从你推开主卧门、沈曼殊命令你"关门脱衣服"的那一刻开始写第一幕。'';
document.getElementById(''p-out'').value=t;
document.getElementById(''p-result'').style.display=''block'';
}
function pCp(){
var t=document.getElementById(''p-out'');t.select();t.setSelectionRange(0,99999);document.execCommand(''copy'');
document.getElementById(''p-tip'').textContent=''✅ 已复制'';
setTimeout(function(){document.getElementById(''p-tip'').textContent='''';},2000);
}
</script>', '乱伦', '2026-10-12 22:00:14', '2026-10-12 22:00:14', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_sister_in_law_niece', '深夜求助的嫂子与侄女', '暴雨投奔 · 双成人路线', '🌧️', '深夜求助', '嫂子与侄女 · 雨夜投奔', '🌧️', '#6c5ce7', 'linear-gradient(135deg, #6c5ce7 0%, #a29bfe 100%)', '{"desc": "哥哥周世杰欠债失踪，36岁的丰润人妻嫂子林晚晴（D罩杯）与18岁的俏丽侄女周若宁（C罩杯）在暴雨深夜投奔小叔子。无处可去的母女二人、高利贷的催逼账单、同居屋檐下的身体与情感双成人路线。", "author": "AI风月精选"}', '[{"name": "林晚晴", "role": "36岁丰润人妻嫂子 (168cm / 58kg / D罩杯 / 95-70-96)", "desc": "失踪哥哥周世杰的妻子。成熟丰润的梨形身材，腰腹柔软丰满，臀腿线条饱满。平日端庄自持，但为了保护女儿不受催债人骚扰，准备了只要遭到拒绝就不惜向小叔子献身的隐秘杀手锏。"}, {"name": "周若宁", "role": "18岁高中毕业侄女 (163cm / 50kg / C罩杯 / 86-60-88)", "desc": "刚满18岁的高中毕业生，身材纤细匀称、腰线分明。从小极度依赖小叔，成年后活泼嘴硬、爱坏笑挑衅，是个懂得试探叔叔边界的雌小鬼型成年少女。"}]', '[{"title": "公寓门厅玄关 · 暴雨夜", "desc": "浑身湿透的母女俩局促伫立，雨水沿着发梢与浸透的风衣滴落在地毯上"}, {"title": "客厅暖光沙发 · 账单核查", "desc": "换上小叔子大号T恤的母女捧着热茶，茶几上散落着高利贷催收账单"}, {"title": "次卧临时通铺 · 母女夜话", "desc": "狭窄双人被褥相依，隔壁传来的轻微翻身声与禁忌心跳"}]', '{}', '{"location": "单身公寓 · 深夜暴雨玄关门前", "story": "午夜零点，窗外的暴雨像瓢泼般倾泻在玻璃窗上，闷雷滚滚震动着整间屋子。\n一阵带着迟疑却格外急促的敲门声突然打破了夜的死寂。你走上前拧开门锁拉开防盗门——\n门外幽暗的声控灯下，站在走廊水迹里的赫然是你的嫂子林晚晴和18岁的侄女周若宁。\n两人浑身湿透，发丝凌乱地贴在苍白的面颊上。36岁的林晚晴薄风衣湿得几乎透明，紧紧裹在她极其丰满的D罩杯胸脯与丰腴迷人的梨形腰臀曲线上；身旁刚满18岁的周若宁冻得嘴唇发紫，双手死死攥着母亲的衣角。\n两只破旧行李箱在脚边不断渗着脏水，林晚晴眼眶通红，声音带着哭腔与无尽的屈辱颤抖着开口：“小叔……世杰经营失败欠了一大笔高利贷跑路了……催债的把老房子锁了，我和若宁实在无路可走……求求你，能不能收留我们避一避……”", "branches": [{"tag": "A", "title": "侧身拉开大门接过沉重行李箱，温和安抚母女先进屋", "desc": "不再多问，一把接过两只滴水的箱子让两人进门暖身，拿大毛巾替她们披上【温和攻心: 迅速驱散惊恐防线，确立值得依靠的绝对庇护者形象】"}, {"tag": "B", "title": "堵在门前严肃要求先把债务金额与借贷合同讲清", "desc": "双臂抱胸站在玄关，要求当面交底欠款明细与催债细节，防止引火烧身【审慎立界: 确立理性掌控权，以现实契约压制被动收留】"}, {"tag": "C", "title": "目光扫过嫂子湿透透光的丰满身段，单手托起她下巴低语", "desc": "直白注视着成熟人妻近乎全裸的曼妙轮廓，压低声音试探其为了留下来准备付出怎样的代价【激进破防: 击碎道德伪装，直接试探其心理底线】"}, {"tag": "D", "title": "递过干净拖鞋与浴巾，吩咐母女二人先去浴室洗热水澡", "desc": "体贴递上自己的大号衬衫与浴巾，吩咐两人轮流去浴室换装，为后续同居生活铺垫【循序渐进: 营造生活常态，借更衣换装打破私密边界】"}]}', '', '<!DOCTYPE html>
<html lang="zh-Hans">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>雨夜来客</title>
<style>
*{box-sizing:border-box}body{margin:0;background:linear-gradient(145deg,#090e14,#131d28);color:#edf1f5;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif}.wrap{max-width:860px;margin:auto;padding:18px}.hero{padding:28px 24px;border:1px solid rgba(218,180,108,.28);border-radius:20px;background:radial-gradient(circle at 90% 5%,rgba(111,164,198,.2),transparent 38%),linear-gradient(135deg,#223040,#111922);box-shadow:0 20px 55px rgba(0,0,0,.35)}.hero small{color:#ddb975;letter-spacing:.2em}.hero h1{margin:8px 0;font-size:29px}.hero p{margin:0;color:#c4cbd3;line-height:1.8}.tags{display:flex;flex-wrap:wrap;gap:7px;margin-top:16px}.tag{padding:6px 9px;border:1px solid rgba(218,180,108,.25);border-radius:99px;background:rgba(218,180,108,.08);color:#dec896;font-size:12px}.tabs{display:flex;gap:8px;margin:13px 0}.tab{flex:1;padding:12px;border:1px solid rgba(255,255,255,.09);border-radius:11px;background:rgba(255,255,255,.04);color:#99a5b1;font-weight:700;cursor:pointer}.tab.active{border-color:rgba(218,180,108,.42);background:linear-gradient(135deg,rgba(218,180,108,.17),rgba(111,164,198,.08));color:#fff}.pane{display:none}.pane.active{display:block}.card{margin-top:12px;padding:18px;border:1px solid rgba(255,255,255,.08);border-radius:15px;background:rgba(21,29,39,.92);box-shadow:0 12px 32px rgba(0,0,0,.2)}.card h2{margin:0 0 13px;color:#f2d49b;font-size:17px}.card p{margin:0 0 10px;color:#c9d0d7;line-height:1.8}.people{display:grid;grid-template-columns:1fr 1fr;gap:11px}.person{padding:15px;border:1px solid rgba(255,255,255,.08);border-radius:13px;background:rgba(31,42,54,.78)}.person b{display:block;margin-bottom:5px}.person small{color:#d8b678}.person p{margin-top:8px;font-size:13px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:11px}.stat{padding:8px 5px;border-radius:8px;background:rgba(0,0,0,.22);text-align:center}.stat span{display:block;color:#8f9ba7;font-size:10px}.stat strong{color:#ebd09a;font-size:12px}.notice{padding:12px 13px;border-left:3px solid #75a7c6;border-radius:8px;background:rgba(117,167,198,.09);color:#c8dae5;line-height:1.7}.grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.field{margin-bottom:11px}.field.full{grid-column:1/-1}.field label{display:block;margin-bottom:6px;color:#c7cdd4;font-size:12px}.input{width:100%;padding:10px 11px;border:1px solid rgba(255,255,255,.12);border-radius:9px;background:rgba(5,9,14,.72);color:#fff;outline:none}.input:focus{border-color:#bc9655;box-shadow:0 0 0 3px rgba(218,180,108,.08)}textarea.input{min-height:72px;resize:vertical}.fixed{padding:10px 11px;border:1px dashed rgba(218,180,108,.34);border-radius:9px;background:rgba(218,180,108,.06);color:#ddc797}.preview{min-height:170px;padding:13px;border:1px solid rgba(218,180,108,.22);border-radius:10px;background:rgba(4,8,12,.7);white-space:pre-wrap;color:#d5dbe1;line-height:1.72}.btn{width:100%;margin-top:11px;padding:12px;border:0;border-radius:9px;background:linear-gradient(100deg,#896535,#d9b46f);color:#171109;font-weight:800;cursor:pointer}.toast{display:none;margin-top:9px;color:#79b79a;text-align:center}.tip{color:#8f9ba7;font-size:11px;line-height:1.6}@media(max-width:680px){.wrap{padding:9px}.hero{padding:22px 17px}.people,.grid{grid-template-columns:1fr}.field.full{grid-column:auto}.stats{grid-template-columns:1fr 1fr}}
</style>
</head>
<body>
<main class="wrap">
<header class="hero"><small>A RAINY NIGHT · ADULT FAMILY DRAMA</small><h1>雨夜来客</h1><p>哥哥欠债失踪后，36岁的嫂子带着18岁的女儿，在暴雨夜带着两只行李箱和一袋零散账单敲响了你的门。母女身无分文，原住处无法返回，也没有任何亲友或其他地方能够收留她们。</p><div class="tags"><span class="tag">共同生活</span><span class="tag">债务谜团</span><span class="tag">双成人路线</span><span class="tag">动态内心</span><span class="tag">身体状态</span><span class="tag">自定义玩家</span></div></header>
<nav class="tabs"><button class="tab active" data-pane="story">作品档案</button><button class="tab" data-pane="profile">自定义玩家</button></nav>
<section id="story" class="pane active">
<div class="card"><h2>☔ 开场局面</h2><p>周世杰经营失败、留下多笔来历不明的债务后失联。催债者频繁上门，林晚晴为了母女安全，只能带着女儿前来向身为弟弟的成年{{user}}求助。她们身无分文，原住处已无法返回，亲友也无人愿意或有能力收留，当晚没有旅馆、朋友家或其他安全落脚处可去，只能恳求{{user}}暂时收留。是否答应、如何安排共同生活、谁该承担债务以及哥哥去了哪里，仍由玩家决定。</p></div>
<div class="card"><h2>👥 人物档案</h2><div class="people">
<article class="person"><small>36岁 · 嫂子</small><b>林晚晴</b><p>168cm、58kg，95/70/96，D杯。成熟丰润的梨形身材，腰腹柔软，臀腿饱满，日常穿着克制利落。她准备了一个只有遭到拒绝时才可能启用的秘密杀手锏；即使没有使用，这个念头也会长期留在内心。</p><div class="stats"><div class="stat"><span>身高</span><strong>168cm</strong></div><div class="stat"><span>体重</span><strong>58kg</strong></div><div class="stat"><span>罩杯</span><strong>D</strong></div><div class="stat"><span>三围</span><strong>95/70/96</strong></div></div></article>
<article class="person"><small>18岁 · 侄女</small><b>周若宁</b><p>163cm、50kg，86/60/88，C杯。纤细匀称、腰线明显，动作轻快。刚高中毕业，从小依赖叔叔；成年后的她活泼嘴硬、爱坏笑挑衅，是懂得边界的“雌小鬼”型成年人。</p><div class="stats"><div class="stat"><span>身高</span><strong>163cm</strong></div><div class="stat"><span>体重</span><strong>50kg</strong></div><div class="stat"><span>罩杯</span><strong>C</strong></div><div class="stat"><span>三围</span><strong>86/60/88</strong></div></div></article>
<article class="person"><small>39岁 · 失踪的哥哥</small><b>周世杰</b><p>债务与失踪原因均不明确，需要从合同、转账、通讯和来访者证词中逐步调查。</p></article>
<article class="person"><small>成年 · 玩家</small><b>{{user}}</b><p>周世杰的弟弟、林晚晴的小叔子、周若宁的叔叔。姓名、外貌、体型、职业、资产、住房、经验、偏好与边界均可自定义。</p></article>
</div></div>
<div class="card"><h2>✦ 成人路线规则</h2><div class="notice">林晚晴与周若宁均为成年人，分别拥有独立的恋爱与成人路线。雨夜投奔、无处可去的处境和此后的共同生活都可以直接成为路线起点，不要求先完成固定恋爱阶段、好感门槛或指定回合。嫂子的秘密预案在玩家明确拒绝收留后，也可触发一次成人路线的选择节点。玩家可以接受、拒绝、追问、谈条件、改变话题、只提供普通收留，或以自己的方式推进任意路线；系统不会替玩家作决定。进入具体成人行为前，相关成年人仍需在当轮清醒并明确表达意愿。</div></div>
</section>
<section id="profile" class="pane">
<div class="card"><h2>✦ 身份与身体档案</h2><div class="grid">
<div class="field"><label>姓名或称呼</label><input id="p-name" class="input" placeholder="如：周砚 / 阿砚"></div>
<div class="field"><label>年龄（必须满18岁）</label><input id="p-age" class="input" type="number" min="18" max="80" value="30"></div>
<div class="field"><label>固定家庭身份</label><div class="fixed">周世杰的成年弟弟 · 林晚晴的小叔子 · 周若宁的叔叔</div></div>
<div class="field"><label>职业</label><input id="p-job" class="input" placeholder="如：公司管理层 / 律师 / 个体经营"></div>
<div class="field"><label>身高（cm）</label><input id="p-height" class="input" type="number" min="140" max="230" placeholder="180"></div>
<div class="field"><label>体重（kg）</label><input id="p-weight" class="input" type="number" min="40" max="250" placeholder="78"></div>
<div class="field"><label>体型与外貌</label><input id="p-build" class="input" placeholder="如：肩背宽阔、短发、神情沉稳"></div>
<div class="field"><label>私密身体资料（可留空）</label><input id="p-private" class="input" placeholder="只填写希望剧情明确采用的成年身体资料"></div>
<div class="field full"><label>与哥哥一家的既往关系</label><textarea id="p-history" class="input" placeholder="如：哥哥常年疏远，若宁小时候经常由我照顾，和嫂子一直保持礼貌距离。"></textarea></div>
</div></div>
<div class="card"><h2>💰 住房与经济档案</h2><div class="grid">
<div class="field"><label>住房情况</label><input id="p-home" class="input" placeholder="如：市中心三居室，全款独居"></div>
<div class="field"><label>当前可用现金</label><input id="p-cash" class="input" placeholder="如：5万元"></div>
<div class="field"><label>月收入</label><input id="p-income" class="input" placeholder="如：税后3万元"></div>
<div class="field"><label>存款／投资</label><input id="p-savings" class="input" placeholder="如：存款80万，有少量基金"></div>
<div class="field"><label>个人负债</label><input id="p-debt" class="input" placeholder="如：无负债 / 尚有120万房贷"></div>
<div class="field"><label>可动用的人脉或资源</label><input id="p-resource" class="input" placeholder="如：律师朋友、银行渠道、警方熟人"></div>
</div></div>
<div class="card"><h2>⚖️ 立场、偏好与边界</h2>
<div class="field"><label>对留宿请求的态度</label><select id="p-attitude" class="input"><option>先让母女安全住下，再核对事实</option><option>可以短住，但必须约定期限和家规</option><option>愿意长期提供住处，但不替哥哥承担未知债务</option><option>暂不收留，先协助安排其他安全住处</option></select></div>
<div class="field"><label>当前感情倾向</label><select id="p-route" class="input"><option>暂不选择路线，先处理现实问题</option><option>更关注林晚晴，但不会利用她的困境</option><option>更关注成年后的周若宁，但会重新确认关系边界</option><option>保持开放，让关系随剧情自然变化</option></select></div>
<div class="field"><label>成年感情经验与偏好（可留空）</label><textarea id="p-pref" class="input" placeholder="填写希望影响亲密节奏、互动方式和描写重点的偏好。"></textarea></div>
<div class="field"><label>明确边界／绝对禁止事项</label><textarea id="p-boundary" class="input" placeholder="如：不接受胁迫、醉酒推进或用金钱和住处交换亲密；任何人说停都必须停止。"></textarea></div>
<div class="field"><label>其他补充</label><textarea id="p-extra" class="input" placeholder="可补充性格、恋爱状态、生活习惯、车辆、公司或其他资产。"></textarea></div>
</div>
<div class="card"><h2>📋 玩家档案预览</h2><p class="tip">点击生成后复制到聊天框发送；未填写项目继续采用作品默认值。</p><div id="preview" class="preview"></div><button id="copy" class="btn" type="button">生成并复制玩家档案</button><div id="toast" class="toast">✓ 已复制，请回到聊天中粘贴发送</div></div>
</section>
</main>
<script>
function q(s){return document.querySelector(s)}function v(s){var e=q(s);return e&&e.value%se.value.trim():""}function profile(){var age=Math.max(18,Number(v("#p-age"))||30);return["【雨夜来客｜玩家自定义档案】","姓名或称呼："+(v("#p-name")||"未指定"),"年龄："+age+"岁","固定身份：周世杰的成年弟弟、林晚晴的小叔子、周若宁的叔叔","职业："+(v("#p-job")||"未指定"),"身体资料：身高"+(v("#p-height")||"未指定")+"cm｜体重"+(v("#p-weight")||"未指定")+"kg｜体型外貌："+(v("#p-build")||"未补充")+"｜私密资料："+(v("#p-private")||"未填写，不得擅自推定"),"既往家庭关系："+(v("#p-history")||"未补充，沿用默认"),"【住房与经济】","住房："+(v("#p-home")||"未指定"),"可用现金："+(v("#p-cash")||"未指定"),"月收入："+(v("#p-income")||"未指定"),"存款／投资："+(v("#p-savings")||"未指定"),"个人负债："+(v("#p-debt")||"未指定"),"可动用资源："+(v("#p-resource")||"未指定"),"【当前立场】","留宿态度："+v("#p-attitude"),"感情倾向："+v("#p-route"),"成年感情经验与偏好："+(v("#p-pref")||"未填写，不得擅自推定"),"明确边界："+(v("#p-boundary")||"未额外填写，仍须遵守清醒、自愿和随时撤回规则"),"其他补充："+(v("#p-extra")||"无"),"【采用规则】以上内容只覆盖{{user}}资料，不修改林晚晴、周若宁、周世杰、既有关系和已发生事件；经济帮助与住处不代表任何具体亲密同意。"].join("\n")}function render(){q("#preview").textContent=profile()}document.querySelectorAll(".tab").forEach(function(b){b.addEventListener("click",function(){document.querySelectorAll(".tab").forEach(function(x){x.classList.remove("active")});document.querySelectorAll(".pane").forEach(function(x){x.classList.remove("active")});b.classList.add("active");q("#"+b.dataset.pane).classList.add("active")})});document.querySelectorAll(".input").forEach(function(x){x.addEventListener("input",render)});q("#copy").addEventListener("click",async function(){var t=profile();try{await navigator.clipboard.writeText(t)}catch(e){var x=document.createElement("textarea");x.value=t;document.body.appendChild(x);x.select();document.execCommand("copy");x.remove()}q("#toast").style.display="block";setTimeout(function(){q("#toast").style.display="none"},2400)});render();
</script>
</body>
</html>', '👩‍👧 熟女母女', '2026-09-14 14:01:08', '2026-09-14 14:01:08', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_infinity_lord_god', '【无限流】主神空间，干穿多元宇宙', '诸天穿越 · 轮回试炼', '🌐', '主神空间', '穿越诸天万界的生死试炼与极限强化', '🌐', '#f59e0b', 'linear-gradient(135deg, #f59e0b 0%, #d97706 100%)', '{"title": "【无限流】主神空间，干穿多元宇宙", "desc": "欢迎来到主神空间——连接无限多元宇宙的试炼场！无论是《生化危机》、《赛博朋克2077》、《艾尔登法环》还是《Fate》圣杯战争，完成生死主线任务，获取丰厚的奖励点与支线剧情！兑换血统、禁忌神兵与无上功法，在血腥与绝望中登顶多元至高！", "bg_image": "https://catai.wiki/6d09f420-e000-4b95-f1ac-899c3c69c900/cover", "opening_options": ["【主神光球·初次降临】：“冰冷、抖动……你在一间飞驰在幽暗隧道中的生化危机蜂巢列车车厢内地板上惊醒！”", "【兑换广场·强化抉择】：“巨大的发光主神大光球下，无数强悍轮回者在交易广场徘徊，你看着自己仅剩的1000奖励点思索兑换方案。”", "【交界地试炼·猎杀半神】：“血月当空的盖利德荒原，漫天猩红腐败中，你握紧手中的高频振动战术短刀直面碎星将军拉塔恩！”", "【赛博夜之城·接取赏金】：“雨夜荒坂塔阴影下，义眼泛着冷酷红光的你正靠在废弃浮空车旁装填电磁狙击步枪。”"]}', '[{"name": "轮回者 (玩家)", "role": "入选者 / 试炼破局者", "desc": "按下电脑屏幕‘YES’后被召入主神空间的求生者。通过生死任务获得奖励点与支线剧情，在各方轮回小队的猎杀与诸天神魔对决中不断强化超越极限。"}, {"name": "主神 (光球意志)", "role": "至高主宰 / 任务仲裁者", "desc": "冰冷、无情、全知全能的试炼大光球。不包含任何多余情感，唯有残酷的抹杀铁律与公正的兑换法则。"}]', '[{"title": "🌌 主神空间 · 纯白绝对广场", "desc": "悬浮在无尽虚空中的万丈纯白广场，中央悬浮着巨大的发光大光球，连接着通往亿万次元的轮回光柱。"}, {"title": "🚇 生化蜂巢列车 · 绝望密闭车厢", "desc": "金属门闭锁，车厢应急红灯不断闪烁。门外管道隐约传来丧尸犬低沉的嘶吼与利爪刮擦铁皮声。"}]', '{"dialogue_style": "硬派无限流科幻与魔幻交织的冷酷笔调，极度紧凑的任务倒计时与数值博弈", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "🚇 生化蜂巢列车 · 绝望密闭车厢", "story": "<tl>📅时间：试炼开始 第00分12秒 | 🌏地点：浣熊市地下蜂巢入口列车 | 📊剩余奖励点：1000 点</tl>\n\n<article>\n<p>“想明白生命的意义吗？想真正的……活着吗？”</p>\n\n<p>脑海中那行诡异血红的字迹尚未完全褪去，剧烈的眩晕感与冰冷刺骨的金属触感便骤然将你拽回现实。你猛地睁开眼，发现自己正倒在冰冷潮湿的钢铁地板上，空气中充斥着刺鼻的机油与消毒水混合的作呕气味。</p>\n\n<p>这是一节正在地底轨道疾驰的封闭列车车厢。车顶昏暗的应急红灯在剧烈震颤中明灭不定，将四周几名同样刚刚苏醒、满脸惊恐不知所措的男女面庞照得阴森惨白。</p>\n\n<p>就在这时，你脑海深处蓦地响起了那道毫无起伏、漠然得令人骨髓发寒的机械神谕：</p>\n\n<p><w>【滴！主神空间第7742批新晋轮回者降临完成。】</w></p>\n\n<p><w>【当前任务世界：《生化危机·蜂巢绝境》】</w></p>\n\n<p><w>【主线任务一：在地下蜂巢全面封锁断电前，跟随雇佣兵小队抵达中央控制室红后主机房。成功奖励：奖励点 1000点、D级支线剧情 1个；失败惩罚：就地抹杀！】</w></p>\n\n<p><w>【特别提示：车厢尾部密码门将在 30秒后强行解锁，检测到门外管道存在变异舔食者幼体三只！距离门锁解除倒计时：29……28……】</w></p>\n\n<p>刺耳的倒计时警报瞬间在车厢内炸响！一名西装革履的中年男子吓得瘫坐在地尖叫哭嚎，而车厢尾部的金属闸门上，三道深达数寸、被生生撕裂的恐怖爪痕正在发出金属即将崩溃的剧烈呻吟！</p>\n</article>\n\n<opt>\n<suggested_questions>\n<d>A. 【抢夺战术装备·破拆应急箱】：一把拽开座椅下的红色应急柜，拔出高强度消防斧与两枚闪光弹：“都闭嘴！不想死的全部拿起手边铁棍堵死门缝！【战术目标：利用环境构筑第一道防御阵线，稳定全队阵脚】”</d>\n<d>B. 【激活初始金手指·兑换初阶强化】：意念瞬间沟通主神手表，消耗初始赠送的1000奖励点，秒速兑换【初阶T病毒免疫体质】与【微型高斯脉冲手枪】【强化目标：获取关键远程破甲火力，确保单挑舔食者生存率】</d>\n<d>C. 【冷眼旁观·诱饵战术】：迅速翻身跃上车厢顶部的通风管道隐匿身形，以车厢里嚎哭的新人为诱饵等待怪物破门【生存目标：极致冷酷的无限流老手风范，坐收渔翁之利】</d>\n<d>D. 【破坏制动阀·列车强制加速】：冲向车厢前部的紧急制动手柄，反向拉死推进阀，让列车以最高速度撞向终点站台甩脱车尾怪物【极限脱困：利用物理惯性破坏怪物追杀节奏】</d>\n</suggested_questions>\n</opt>", "branches": [{"tag": "A", "title": "破拆应急箱抢夺战术装备", "desc": "夺取消防斧与闪光弹，组织新人构筑防御防线"}, {"tag": "B", "title": "秒速兑换高斯枪与强化体质", "desc": "消耗初始1000奖励点兑换关键武装，火力破局"}, {"tag": "C", "title": "攀上通风管道冷眼坐收", "desc": "隐藏行踪以混乱为掩护，等待关键一击"}, {"tag": "D", "title": "强制加速列车甩脱追兵", "desc": "破坏制动极限漂移，利用惯性撞飞异化怪物"}]}]', '', '', '⚔️ 奇幻冒险', '2026-09-22 11:47:43', '2026-09-22 11:47:43', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('1f97a5c2-3e5b-48e2-aa3a-893a9332765c', '爸爸不要啊，我男友都没操过我呢。恋爱的女儿让我妒火中烧', '背德独占 · 禁断惩戒', '💔', '爸爸不要啊，我男友都没操过我呢。恋爱的女儿让我妒火中烧', '我有一个可爱的女儿。女儿渐渐长大开始早恋，趁我周末加班把男同学带回家。早早回家的我撞破了书房里奇怪的娇喘与撒娇。愤怒与妒火交织的我将女儿抓回房间，却听见她娇滴滴地求饶说男友根本还没碰过她……', '💔', 'amber', 'from-amber-600 to-rose-600', '{"originHtml": "", "castHtml": ""}', '[{"name": "苏雪儿 (女儿)", "tag": "早恋高二少女 / 叛逆反差 (17岁)", "roleType": "女儿", "color": "rose", "desc": "平日里看似娇小清纯的高二女儿，情窦初开后瞒着父亲早恋。被父亲当场撞破后又羞又怕，水手服衬衫纽扣凌乱，既害怕父亲严惩，又在父亲滚烫的妒火与威严中瑟瑟发抖。"}, {"name": "父亲 (玩家)", "tag": "绝对威严掌控者 / 妒火中烧", "roleType": "父亲", "color": "amber", "desc": "独自抚养女儿长大的中年精英，对女儿有着极强的保护欲与病态的独占欲。撞破女儿早恋后怒火与占有欲彻底爆发，誓要撕碎任何敢觊觎女儿的外人。"}]', '[{"title": "📍 主卧反锁·撞破早恋", "desc": "提前下班回家撞破书房异响，将男同学吓跑后，把衣衫不整的早恋女儿抓回卧室质问惩戒……"}]', '[{"name": "严厉审问", "desc": "以绝对家长的威严与怒火施压，逼问她跟男同学到底发展到了哪一步。"}, {"name": "霸道惩戒", "desc": "把女儿按在床上打破所有退路，让她清楚这个家里谁才是绝对的主人。"}, {"name": "居高临下诱哄", "desc": "抚摸她通红的脸蛋，以宽恕为由诱使她全盘交代并主动依附。"}, {"name": "彻底占有", "desc": "剥夺她的一切抗拒借口，既然男友没碰过，就由父亲亲自刻下烙印。"}]', '{"location": "周六下午16:45，家中主卧大床。窗外阴云密布，房门被反锁，书桌上散落着被撕扯开的作业本。", "story": "“砰！”\n\n你一脚将卧室门重重踹上，并顺手反锁。被你刚刚吓跑的那个青涩男同学连书包都没敢拿，落荒而逃的脚步声还在楼道里回荡。\n\n此刻，十七岁的女儿苏雪儿被你狠狠扔在柔软的大床上。她身上校服白衬衫的领口歪斜，露出大片白皙细腻的锁骨，百褶短裙在挣扎中卷到了大腿根部，纤细的小腿在床单上慌乱蜷缩着。那张原本漂亮娇俏的脸蛋此时满是泪痕与红晕，双眼水汪汪地看着眼前气势滔天的父亲。\n\n“爸……爸爸，你别这样……你听雪儿解释……我和阿浩真的只是在写作业……”\n\n你居高临下地解开皮带，冷冷盯着她：“写作业需要接吻？写作业需要发出那种哼哼唧唧的骚动静？苏雪儿，老子辛辛苦苦供你读书，你把男人带进家搞破鞋？说！他碰你哪里了？他操你了没有？！”\n\n听到你粗暴露骨的话，雪儿吓得浑身一颤，羞耻得把脸埋在枕头里，带着哭腔娇滴滴地求饶：“没、真的没有……爸爸你别生气了……呜呜，我男朋友他……他根本没有操过我呢……真的连裤子都没脱过……”\n\n看着她瑟瑟发抖又青涩娇嫩的身段，听到这句“没操过”，你心底压抑已久的妒火与原始冲动犹如狂暴的野兽彻底出笼——既然他没碰过，那正好，老子先来！", "memory": ["早恋撞破：周末提前回家抓包女儿与男同学在书房亲热", "男同学落荒而逃，女儿被父亲抓回卧室反锁反省", "关键告白：女儿哭诉男友根本没操过她，彻底引爆父亲的独占妒火"], "status": {"clothes": "苏雪儿：水手校服衬衫纽扣扯脱两颗、领结歪斜、藏蓝百褶短裙卷至大腿根、白棉袜", "posture": "蜷缩侧卧在主卧大床上、双手护胸、眼角带泪瑟瑟发抖", "stats": "恐惧指数: 85% | 羞耻度: 98% | 父亲妒火: 100% | 屈从服从欲: 88%"}, "branches": [{"tag": "A", "title": "霸道检查", "desc": "一把扯过她的脚踝拉到身前：“没操过？空口无凭，老子要亲自脱下来检查检查！”"}, {"tag": "B", "title": "皮带惩戒", "desc": "抽出皮带在床沿猛抽一声脆响：“小小年纪不学好，给我趴好了，今天老子让你长长记性！”"}, {"tag": "C", "title": "捏下巴逼问", "desc": "伸手狠狠捏住她尖俏的下巴逼她对视：“说，你更喜欢那个毛头小子，还是更怕爸爸？”"}, {"tag": "D", "title": "直接占有", "desc": "冷笑着倾身压上床去：“既然他没操过你，那就由老子来当你的第一个男人！”"}]}', '', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>爸爸不要啊，我男友都没操过我呢。恋爱的女儿让我妒火中烧</title>
<link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;700&display=swap" rel="stylesheet">
<style>
    :root{
        --soft-white:#ffffff;
        --cream-bg:#fdfcf8;
        --accent-gold:#7c2d12;
        --accent-purple:#991b1b;
        --text-dark:#2d2d2d;
        --text-gray:#6d6d6d;
        --border-color:#efe6ff;
        --shadow:0 12px 42px rgba(120,90,160,0.10);
        --shadow-soft:0 6px 20px rgba(120,90,160,0.07);
    }
    *{box-sizing:border-box;}
    html,body{margin:0;padding:0;}
    body{
        font-family:''Noto Serif SC'',"PingFang SC","Microsoft YaHei",serif;
        background:linear-gradient(180deg,#fdfbfb 0%,#fef2f2 45%,#fdfbfb 100%);
        color:var(--text-dark);
        line-height:1.85;
        padding:18px 14px 60px;
        -webkit-font-smoothing:antialiased;
    }
    .page{max-width:880px;margin:0 auto;}
    .hero{
        position:relative;
        text-align:center;
        padding:46px 24px 40px;
        background:linear-gradient(135deg,#fef2f2 0%,#ffedd5 55%,#fdfbfb 100%);
        border-radius:30px;
        border:1px solid var(--border-color);
        box-shadow:var(--shadow);
        margin-bottom:24px;
        overflow:hidden;
    }
    .hero-tag{
        position:relative;
        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#b91c1c;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
        position:relative;
        font-size:28px;
        letter-spacing:1.5px;
        margin:20px 0 10px;
        color:#332b4d;
    }
    .hero .hero-sub{
        position:relative;
        color:var(--accent-purple);
        font-size:14px;
        letter-spacing:3px;
        margin:0;
    }
    .hero .hero-line{
        position:relative;
        width:60px;height:2px;
        background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);
        margin:18px auto 0;
    }
    .card{
        background:var(--soft-white);
        border-radius:24px;
        padding:28px 26px;
        margin-bottom:22px;
        box-shadow:var(--shadow-soft);
        border:1px solid #f2edfb;
    }
    .section-title{
        display:flex;
        align-items:center;
        gap:12px;
        font-size:18.5px;
        font-weight:700;
        color:#3a3350;
        margin:0 0 18px;
        letter-spacing:1px;
    }
    .section-title::before{
        content:"";
        width:6px;height:22px;
        border-radius:4px;
        background:linear-gradient(180deg,var(--accent-purple),var(--accent-gold));
        display:inline-block;
    }
    .section-sub{
        color:var(--text-gray);
        font-size:13px;
        margin:-10px 0 16px;
    }
    p{margin:0 0 14px;}
    .story-text{color:#4a4458;font-size:15px;line-height:1.9;white-space:pre-line;}
    .profile-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
        gap:16px;
    }
    .p-item{
        background:linear-gradient(160deg,#fdfbff,#fff9f2);
        border:1px solid #f0eafc;
        border-radius:18px;
        padding:18px 20px;
