INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_azgar_magic_continent', '⭐️阿兹加尔魔法大陆🔮（完备升级版）——Tales of Magician', '西幻史诗 · 剑与魔法', '🔮', '阿兹加尔', '剑与魔法交织的史诗西幻大世界', '🔮', '#8b5cf6', 'linear-gradient(135deg, #8b5cf6 0%, #6366f1 100%)', '{"title": "⭐️阿兹加尔魔法大陆🔮（完备升级版）——Tales of Magician", "desc": "【用心巨制💎/内含绘制地图 🖼 100+概念图🖼/代入感极强的西幻大世界】这是一片魔法随处可见的大陆，拥有完整的位阶体系（见习/初级/中级/高级/大魔法师/魔导师/圣阶/半神）、四大王国阵营、深渊魔物生态与掉落合成机制。在这里，你可以扮演骑士、法师、游侠或禁忌术士，谱写你的传奇史诗。", "bg_image": "https://catai.wiki/3c624dcd-da2b-4e55-8f68-6b1c1a824800/cover", "opening_options": ["【边境冒险者工会·初级任务】：“推开喧闹酒馆橡木大门，前台猫耳接待员微笑着递给你一张泛黄的魔物讨伐悬赏令。”", "【皇家魔法学院·魔导测试】：“站在铭刻着繁复以太符文的检测水晶前，将手掌按上，水晶深处骤然迸发出耀眼的七彩魔力漩涡！”", "【迷雾森林遗迹·偶遇落难圣女】：“在古老遗迹深处击退三只嗜血狂暴座狼，救下一位身着残破神官法袍的金发圣女艾莉亚。”", "【深渊边境要塞·骑士试炼】：“手握厚重的十字双手钢剑，城墙外黑云压城，深渊低语伴随号角声由远及近。”"]}', '[{"name": "冒险者 (玩家)", "role": "命运之子 / 自定义职业强者", "desc": "踏入阿兹加尔大陆的异邦旅者。具备独特的魔力感知亲和，在探索古老遗迹、讨伐领主魔物与权谋纷争中不断进阶突破。"}, {"name": "艾莉亚 (圣辉圣女)", "role": "圣光教会巡礼圣女 (治愈/圣光/知性)", "desc": "18岁，晨曦圣光大教堂的预备圣女。怀揣纯洁信仰巡礼大陆，性格温柔仁善，精通高阶圣光术。在森林遗迹被主角相救后，选择与主角结伴同行，心怀对主角神圣的感激与少女悸动。"}]', '[{"title": "🏰 边境风盔城 · 麦酒飘香的冒险者公会", "desc": "石砌壁炉烈火熊熊，麦酒沫与烤肉香弥漫大厅。悬赏栏前挤满了形形色色的佣兵与冒险者，传奇在此启航。"}, {"title": "🌲 迷雾遗迹深处 · 创世之柱遗落方碑", "desc": "藤蔓缠绕的千年前古精灵祭坛，四周漂浮着荧光微粒与微弱的以太魔力共鸣，暗处潜伏着危险的魔物。"}]', '{"dialogue_style": "宏大史诗的古典奇幻笔触，严谨的魔法吟唱与紧张刺激的战斗判定", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "🏰 边境风盔城 · 麦酒飘香的冒险者公会", "story": "<tl>📅魔力纪元 347年 · 霜降之月 | 🌏地点：风盔城冒险者公会大厅 | 🛡️状态：见习冒险者</tl>\n\n<article>\n<p>厚重的橡木大门在刺骨寒风中被沉沉推开，公会大厅内扑面而来的壁炉热浪与浓郁的麦芽酒香瞬间驱散了周身的寒意。</p>\n\n<p>粗犷的矮人佣兵正踩在长条木凳上拼酒嘶吼，几个披着厚重斗篷的神秘施法者在角落昏暗的油灯下低语，黄铜吊灯的光晕将整个喧嚣的大厅笼罩在一种刀口舔血的粗砺浪漫中。</p>\n\n<p>你迈步穿过纷杂的酒桌来到黑曜石柜台前。前台的半精灵接待员少女放下手中的羊皮纸卷轴，碧绿的眼眸打量着你腰间新配的制式铁剑，露出了职业而灵动的微笑：</p>\n\n<p><w>“欢迎来到风盔城冒险者分会，年轻的旅者！无论你是想赚取几枚闪亮的银鹿币换一顿饱饭，还是妄图在这片大陆留下名垂青史的传说，阿兹加尔都会慷慨地赋予你机会——当然，前提是你能在野外的尖牙与利爪下保住小命。”</w></p>\n\n<p>她抬手在身后的黄铜悬赏板上划过，三张散发着不同魔力波动的委托单排成一列推到你面前：</p>\n\n<p><w>“这是今天最抢手的三项委托，按照公会铁律，新人必须完成首次试炼方可评定实力位阶并领取专属魔导徽章。挑选属于你的道路吧，勇敢的冒险者！”</w></p>\n</article>\n\n<opt>\n<suggested_questions>\n<d>A. 【稳健清怪·讨伐黑沼巨蟾】：指向第一张印有沼泽标记的羊皮纸：“我选这个，黑沼森林边境的毒系异化巨蟾，收集三对完整毒腺。【战斗目标：试炼初阶剑技与魔力护体，稳健获取基础金币与材料】”</d>\n<d>B. 【高风险高收益·护送教会车队】：指向带有圣辉纹章的委托：“听说圣光教会的圣女巡礼车队正在招募护卫骑士？正好我也要前往翡翠圣城。【剧情目标：结识核心主线NPC圣女艾莉亚，开启圣光阵营羁绊】”</d>\n<d>C. 【神秘探险·古代精灵废墟】：取下那张带有发光符文的残破羊皮纸：“关于迷雾森林中失落的创世之柱遗迹残片……我很有兴趣探索一番。【冒险目标：遭遇古代机关与未知魔偶，探寻上古高阶装备掉落】”</d>\n<d>D. 【情报搜集·与酒馆佣兵打探】：掏出一枚银币放在柜台上：“在接任务之前，我想先在酒馆打听一下最近关于北方雪山巨龙苏醒的传闻。【社交目标：搜集世界大势与高价值隐藏线索，触发随机奇遇】”</d>\n</suggested_questions>\n</opt>", "branches": [{"tag": "A", "title": "稳健清怪讨伐黑沼巨蟾", "desc": "试炼初阶剑技与魔力护体，稳健获取基础金币与材料"}, {"tag": "B", "title": "高收益护送教会巡礼车队", "desc": "结识主线NPC圣女艾莉亚，开启圣光阵营羁绊"}, {"tag": "C", "title": "神秘探险古代精灵废墟", "desc": "挑战古代魔偶机关，探寻上古高阶装备掉落"}, {"tag": "D", "title": "情报搜集酒馆打探龙息", "desc": "搜集世界大势与隐藏线索，触发随机奇遇"}]}]', '', '', '⚔️ 奇幻冒险', '2026-09-22 11:47:43', '2026-09-22 11:47:43', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
