let identity = document.getElementById(''p-identity'').value;
if (identity === ''custom'') identity = document.getElementById(''p-identity-custom'').value || "未填写";
const other = document.getElementById(''p-other'').value || "无";
const perspective = document.getElementById(''p-perspective'').value;
let scenarioText = "";
if (currentScenarioType === ''custom'') { scenarioText = document.getElementById(''custom-scenario-text'').value || "未填写"; } else { scenarioText = scenarios[currentScenarioType]; }
const finalOutput = `【玩家面板】\n姓名：${name}\n年龄：${age}\n性别：${gender}\n外貌：${look}\n身份：${identity}\n其他补充：${other}\n\n【开场设定】\n游玩视角：${perspective}\n开场情景：\n${scenarioText}`;
document.getElementById(''output-area'').value = finalOutput;
}
function copyInfo() {
const output = document.getElementById(''output-area'');
output.select();
output.setSelectionRange(0, 99999); 
try {
if (navigator.clipboard && window.isSecureContext) {
navigator.clipboard.writeText(output.value).then(() => { alert(''复制成功！''); });
} else {
document.execCommand(''copy'');
alert(''复制成功！'');
}
} catch (err) { alert(''复制失败，请手动复制。''); }
}
function clearInfo() {
document.getElementById(''p-name'').value = '''';
