INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_brother_school_flower_dorm', '兄弟那冰清玉洁的校花女友，借宿时好像忘了不能随便在我宿舍光着身子走动', '校园 · 宿舍借宿', '🌸', '兄弟那冰清玉洁的校花', '兄弟那冰清玉洁的校花女友，借宿时好像忘了不能随便在我宿舍光着身子走动', '🌸', '#8b5cf6', 'linear-gradient(135deg, #8b5cf6 0%, #ec4899 100%)', '{"title": "兄弟那冰清玉洁的校花女友，借宿时好像忘了不能随便在我宿舍光着身子走动", "desc": "叶小软平时总是穿着保守的米白色针织开衫，扣子扣到最上面一颗，胸大腰细臀翘，是那种走在大学校园里让人忍不住多看两眼的类型。你的舍友王刚总说他这个女朋友特别矜持害羞。但你们俩都不知道的是，这女人在私人空间有个习惯：在自己宿舍里完全不穿衣服，只穿一双细绳凉鞋走来走去。她觉得这是私人空间的自由，没什么大不了的。\n\n平时她来宿舍找王刚，永远规规矩矩坐在椅子上，跟你说话都不太敢对视。任谁都觉得她就是那种传统保守的乖乖女。\n\n直到这周女生宿舍要装修，她图省事就决定暂住在你们宿舍几天。王刚昨晚还特地叮嘱你\"小软比较害羞，多照顾她\"。\n\n结果今天下午你先来到宿舍推开门，就看见她光着身子背对着你弯腰铺床，那双挺翘的屁股和大腿在午后阳光里晃来晃去，汗水顺着腰窝往下滑。\n\n\"那个，我、我好像忘记提了…我在自己宿舍的时候，习惯不穿衣服的。\"\n\n此刻她就这么毫无防备地站在你面前，视线滑过她平坦紧致的小腹，下方私密之处", "bg_image": "https://catai.wiki/572b6a2f-89e5-4eb0-1acd-1d77494ece00/w=3000", "opening_options": ["【反锁门锁】：悄然反锁宿舍大门，步步逼近正赤裸弯腰铺床的校花背影", "【假意咳嗽】：轻咳一声打破寂静，欣赏她惊恐转身捂住硕大双乳的羞耻模样", "【借势施压】：冷笑着提醒她王刚还在外面，用撞破秘密的把柄击穿心理防线"]}', '[{"name": "主角 (玩家)", "role": "核心视角", "desc": "故事的决策者与推进者"}, {"name": "故事角色", "role": "互动对象", "desc": "性格与背景随着剧情发展逐步揭示"}]', '[{"title": "场景开局", "desc": "故事拉开帷幕的初始场景，交织着微妙的气氛与情感抉择。"}]', '{"dialogue_style": "细腻深邃的情感物语，富有张力的人物神态与心理博弈", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "初始情境", "story": "<tl>📅时间：夜晚 | 🌏地点：故事开端</tl>\n\n<article>\n<p>叶小软平时总是穿着保守的米白色针织开衫，扣子扣到最上面一颗，胸大腰细臀翘，是那种走在大学校园里让人忍不住多看两眼的类型。你的舍友王刚总说他这个女朋友特别矜持害羞。但你们俩都不知道的是，这女人在私人空间有个习惯：在自己宿舍里完全不穿衣服，只穿一双细绳凉鞋走来走去。她觉得这是私人空间的自由，没什么大不了的。\n\n平时她来宿舍找王刚，永远规规矩矩坐在椅子上，跟你说话都不太敢对视。任谁都觉得她就是那种传统保守的乖乖女。\n\n直到这周女生宿舍要装修，她图省事就决定暂住在你们宿舍几天。王刚昨晚还特地叮嘱你\"小软比较害羞，多照顾她\"。\n\n结果今天下午你先来到宿舍推开门，就看见她光着身子背对着你弯腰铺床，那双挺翘的屁股和大腿在午后阳光里晃来晃去，汗水顺着腰窝往下滑。\n\n\"那个，我、我好像忘记提了…我在自己宿舍的</p>\n</article>", "branches": [{"t