    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }
  .flip-card-back {
    transform: rotateY(180deg);
    background: #f0e8e0;
    border: 1px solid rgba(220,180,170,0.30);
  }
  .flip-card-back img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
  }
  .flip-hint {
    font-size: 11px;
