<script>
var pPersonaV='''',pEndingV='''';

function pPersona(el){
var p=el.parentNode,k=p.children;
for(var i=0;i<k.length;i++){k[i].style.background=''rgba(255,255,255,0.5)'';k[i].style.borderColor=''#f0e8e0'';k[i].style.color=''#8a7a72'';}
el.style.background=''rgba(200,150,130,0.15)'';el.style.borderColor=''#b08078'';el.style.color=''#4a3a36'';
pPersonaV=el.getAttribute(''data-v'');
}

function pEnding(el){
var p=el.parentNode,k=p.children;
for(var i=0;i<k.length;i++){k[i].style.background=''rgba(255,255,255,0.5)'';k[i].style.borderColor=''#f0e8e0'';k[i].style.color=''#8a7a72'';}
el.style.background=''rgba(200,150,130,0.15)'';el.style.borderColor=''#b08078'';el.style.color=''#4a3a36'';
pEndingV=el.getAttribute(''data-v'');
}

function pGen(){
var n=document.getElementById(''p-name'').value.trim()||''你'';
var extra=document.getElementById(''p-extra'').value.trim();
var t=''【玩家角色设定】\n'';
t+=''姓名：''+n+''\n'';
t+=''性格：''+(pPersonaV||''礼貌回避'')+''\n'';
t+=''目标结局：''+(pEndingV||''纯爱线'')+''\n'';
if(extra){t+=''补充设定：''+extra+''\n'';}
t+=''\n【人物说明】\n'';
t+=''叶小软，21岁，大三，校花。平时穿着保守的米白色针织开衫，扣子扣到最上面一颗。是舍友王刚的女友，王刚总说她特别矜持害羞。但她在自己宿舍里有个习惯——完全不穿衣服，只穿一双细绳凉鞋走来走去。这次女生宿舍装修，她借宿你们宿舍，却忘了这不是她的私人空间。你推开门，看见她光着身子在铺床。'';
t+=''\n\n以上是我的角色设定。请从你推开门、看见她光着身子弯腰铺床的那一刻开始写第一幕。'';
document.getElementById(''p-out'').value=t;
document.getElementById(''p-result'').style.display=''block'';
}

function pCp(){
var t=document.getElementById(''p-out'');t.select();
t.setSelectionRange(0,99999);
document.execCommand(''copy'');
document.getElementById(''p-tip'').textContent=''✅ 已复制'';
setTimeout(function(){document.getElementById(''p-tip'').textContent='''';},2000);
}
</script>', '校园', '2026-09-29 21:37:13', '2026-09-29 21:37:13', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_jiangshi_childhood', '死去的青梅竹马变成艳尸疯狂炸精', '还魂夜 · 青梅渴求', '🧟‍♀️', '艳尸青梅', '死而复生的恋人 · 榨精契约', '💜', '#9d8ec7', 'linear-gradient(135deg, #8f7ec9 0%, #d99a76 100%)', '{"desc": "三天前死于车祸的青梅竹马绫音在深夜赤裸出现在浴室。原本清瘦的身形异变为H罩杯巨乳与肥美丰臀的艳尸，唯一维持她肉体不腐烂与行动的养料就是玩家的精液。若不做爱身体便会变惨白僵硬，为了留住挚爱，你只能一次次沉沦于冰冷却滚烫的交合中。", "author": "AI风月精选"}', '[{"name": "绫音", "role": "19岁死而复生的青梅竹马（艳尸）", "desc": "天然紫色及腰长发、冷萌丹凤眼脸庞。死后肉体异变为H罩杯水滴巨乳、细腰肥美丰臀、天生白虎粉穴。常年触感约10℃冰冷，但进食时口腔与花径滚烫贪婪。极度依恋玩家，性事上直白霸道，靠吸食精液维生并恢复体温与红润。"}]', '[{"title": "深夜水汽弥漫的浴室", "desc": "花洒下赤裸伫立的紫发少女，肌肤透着病态粉嫩，冷香与水雾交织"}, {"title": "拉紧遮光厚窗帘的卧房", "desc": "昏暗中避光的大床，冰冷与滚烫反差的合体温存之所"}, {"title": "客厅暗角旧沙发", "desc": "蜷缩抱着旧衬衫、皮肤逐渐惨白僵硬的饥饿哀求角落"}]', '{}', '{"story": "深夜，钥匙插进锁孔的声音在寂静的楼道里格外清晰。你拖着疲惫空洞的身体推开家门，三天前亲手将车祸去世的青梅竹马绫音下葬的绝望，仍如铅块般压在胸口。\n然而刚进玄关，浴室里竟隐隐传来哗哗的水声——这间屋子，明明只有你一个人住。\n水雾从虚掩的磨砂玻璃门缝里悄然渗出，带着一股极淡的、如雨后青草般沁人心脾的冷香。你的心脏在胸腔里剧烈跳动，颤抖着推开浴室的门——\n花洒下，一个绝美的赤裸身影正静静伫立。那头熟悉的及腰紫发湿漉漉地贴在白皙细腻的背脊上；转过身来，原本纤细的身材竟发生了夸张的异变：胸前是一对随着呼吸沉甸甸颤动的H罩杯水滴巨乳，硕大饱满的乳晕在水流冲刷下泛着深红诱人的色泽，平坦的小腹下是肥美圆润的翘臀与毫无杂草的白虎粉穴。\n她顶着那张你无比熟悉的、总是带着一丝清冷的“冷萌脸”，眼眶微红地注视着你，声音轻哑而带着无助的渴求：“……你回来了。我好饿。”", "branches": [{"tag": "A", "title": "颤抖着上前将浑身冰凉的绫音紧紧拥入怀中", "desc": "踏入水雾中不顾冰冷的花洒水流，一把将失而复得的青梅紧紧抱在怀里，感受她冰凉却真实的柔软躯体"}, {"tag": "B", "title": "伸手轻抚她泛着冷香的脸颊并询问复活的真相", "desc": "指尖拂去她长睫上的水珠，轻抚她微凉的冷萌脸庞，沙哑追问她为何能从棺木下回到自己身边"}, {"tag": "C", "title": "双手托起她沉甸甸的夸张巨乳试探她的体温与心跳", "desc": "将掌心贴覆在她胸口那对沉甸甸的水滴巨乳上，指尖陷进极其细腻柔软的软肉，惊觉那深处竟没有半点心跳"}, {"tag": "D", "title": "解开皮带迎上她饥渴的目光直接提供喂食", "desc": "迎着她蓄满水汽的紫色眼眸，干脆利落地解开皮带掏出坚挺滚烫的肉棒：“饿了就来吃，只要能留住你，怎样都行。”"}], "location": "单身公寓 · 深夜水雾浴室"}', NULL, '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>还魂夜 · 青梅的无尽渴求</title>
<link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;700&display=swap" rel="stylesheet">
<style>
    :root{
        --soft-white:#ffffff;
        --cream-bg:#fdfcf8;
        --accent-gold:#d4a373;
        --accent-pink:#faedcd;
        --accent-purple:#9d8ec7;
        --accent-purple-soft:#f3e8ff;
        --text-dark:#2d2d2d;
        --text-gray:#6d6d6d;
        --border-color:#efe6ff;
        --shadow:0 12px 42px rgba(120,90,160,0.10);
        --shadow-soft:0 6px 20px rgba(120,90,160,0.07);
    }
    *{box-sizing:border-box;}
    html,body{margin:0;padding:0;}
    body{
        font-family:''Noto Serif SC'',"PingFang SC","Microsoft YaHei",serif;
        background:linear-gradient(180deg,#fdfcf8 0%,#f7f2ff 45%,#fdfcf8 100%);
        color:var(--text-dark);
        line-height:1.85;
        padding:18px 14px 60px;
        -webkit-font-smoothing:antialiased;
    }
    .page{max-width:880px;margin:0 auto;}
    .hero{
        position:relative;
        text-align:center;
        padding:46px 24px 40px;
        background:linear-gradient(135deg,#fff7f0 0%,#f6ecff 55%,#fdfcf8 100%);
        border-radius:30px;
        border:1px solid var(--border-color);
        box-shadow:var(--shadow);
        margin-bottom:24px;
        overflow:hidden;
    }
    .hero::before{
        content:"";
        position:absolute;
        width:220px;height:220px;
        background:radial-gradient(circle,rgba(157,142,199,0.22),transparent 70%);
        top:-90px;right:-70px;border-radius:50%;
    }
    .hero::after{
        content:"";
        position:absolute;
        width:180px;height:180px;
        background:radial-gradient(circle,rgba(212,163,115,0.18),transparent 70%);
        bottom:-80px;left:-60px;border-radius:50%;
    }
    .hero-tag{
        position:relative;
        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#7c6bb0;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
        position:relative;
        font-size:30px;
        letter-spacing:2px;
        margin:20px 0 10px;
        color:#332b4d;
    }
    .hero .hero-sub{
        position:relative;
        color:var(--accent-purple);
        font-size:14px;
        letter-spacing:4px;
        margin:0;
    }
    .hero .hero-line{
        position:relative;
        width:60px;height:2px;
        background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);
        margin:18px auto 0;
    }
    .card{
        background:var(--soft-white);
        border-radius:24px;
        padding:30px 28px;
        margin-bottom:22px;
        box-shadow:var(--shadow-soft);
        border:1px solid #f2edfb;
    }
    .section-title{
        display:flex;
        align-items:center;
        gap:12px;
        font-size:19px;
        font-weight:700;
        color:#3a3350;
        margin:0 0 20px;
        letter-spacing:1px;
    }
    .section-title::before{
        content:"";
        width:6px;height:22px;
        border-radius:4px;
        background:linear-gradient(180deg,var(--accent-purple),var(--accent-gold));
        display:inline-block;
    }
    .section-sub{
        color:var(--text-gray);
        font-size:13px;
        margin:-12px 0 18px;
    }
    p{margin:0 0 14px;}
    .story-text{color:#4a4458;font-size:15px;}
    .story-text b{color:#7c4a8d;}
    .profile-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
        gap:16px;
    }
    .p-item{
        background:linear-gradient(160deg,#fdfbff,#fff9f2);
        border:1px solid #f0eafc;
        border-radius:18px;
        padding:18px 20px;
        transition:.25s;
    }
    .p-item:hover{transform:translateY(-3px);box-shadow:var(--shadow-soft);}
    .p-item h4{
        margin:0 0 10px;
        font-size:15px;
        color:var(--accent-purple);
        display:flex;align-items:center;gap:8px;
    }
    .p-item h4 .dot{
        width:8px;height:8px;border-radius:50%;
        background:var(--accent-gold);
        display:inline-block;
    }
    .p-item p{margin:0;font-size:13.5px;color:#5a5468;line-height:1.75;}
    .p-item .hl{color:#c96a8b;font-weight:600;}
    .mech-list{list-style:none;padding:0;margin:0;}
    .mech-list li{
        display:flex;gap:14px;
        padding:14px 16px;
        border-radius:16px;
        background:#fbf9ff;
        border:1px solid #f1ebfc;
        margin-bottom:12px;
        font-size:13.5px;color:#544e64;
        align-items:flex-start;
    }
    .mech-list li .badge{
        flex:0 0 auto;
        font-size:11.5px;
        font-weight:700;
        padding:4px 10px;
        border-radius:999px;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#8a6fb0;
        letter-spacing:1px;
        height:fit-content;
    }
    .form-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
        gap:16px;
    }
    .field{display:flex;flex-direction:column;gap:7px;}
    .field label{
        font-size:13.5px;
        font-weight:600;
        color:#5f5873;
        letter-spacing:.5px;
    }
    .field input,.field textarea{
        font-family:inherit;
        font-size:14px;
        color:#3d374d;
        background:#fdfcff;
        border:1.5px solid #ece5fa;
        border-radius:14px;
        padding:12px 14px;
        outline:none;
        transition:.2s;
        resize:vertical;
        line-height:1.7;
    }
    .field input:focus,.field textarea:focus{
        border-color:#c9b6ec;
        background:#fff;
        box-shadow:0 0 0 4px rgba(157,142,199,0.12);
    }
    .field input::placeholder,.field textarea::placeholder{color:#b6aecb;}
    .full{grid-column:1/-1;}
    .opening-list{display:flex;flex-direction:column;gap:14px;margin-bottom:20px;}
    .opening-card{
        position:relative;
        border:1.5px solid #efe9fb;
        border-radius:18px;
        padding:16px 18px 16px 54px;
        background:#fdfcff;
        cursor:pointer;
        transition:.22s;
        font-size:13.5px;
        color:#4f4960;
        line-height:1.78;
    }
    .opening-card:hover{border-color:#d6c6f2;background:#fbf8ff;}
    .opening-card .idx{
        position:absolute;
        left:16px;top:16px;
        width:26px;height:26px;
        border-radius:9px;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#8a6fb0;
        font-size:12px;font-weight:700;
        display:flex;align-items:center;justify-content:center;
        transition:.2s;
    }
    .opening-card .tag{
        display:inline-block;
        font-size:11px;
        font-weight:700;
        letter-spacing:1px;
        color:#b07a86;
        background:#fdeef1;
        border-radius:6px;
        padding:2px 9px;
        margin-bottom:7px;
    }
    .opening-card .tag.daily{color:#7e9b7e;background:#eef6ee;}
    .opening-card.selected{
        border-color:#b79ce4;
        background:linear-gradient(160deg,#faf6ff,#fff9f3);
        box-shadow:0 8px 24px rgba(157,142,199,0.16);
    }
    .opening-card.selected .idx{
        background:linear-gradient(135deg,#9d8ec7,#d4a373);
        color:#fff;
    }
    .custom-box{display:flex;flex-direction:column;gap:8px;margin-bottom:22px;}
    .custom-box label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .custom-box textarea{
        font-family:inherit;font-size:14px;color:#3d374d;
        background:#fdfcff;border:1.5px solid #ece5fa;
        border-radius:14px;padding:12px 14px;outline:none;
        resize:vertical;min-height:88px;line-height:1.7;transition:.2s;
    }
    .custom-box textarea:focus{
        border-color:#c9b6ec;background:#fff;
        box-shadow:0 0 0 4px rgba(157,142,199,0.12);
    }
    .gen-wrap{text-align:center;margin-top:6px;}
    .gen-btn{
        font-family:inherit;
        cursor:pointer;
        border:none;
        padding:15px 56px;
        border-radius:999px;
        font-size:15px;
        font-weight:700;
        letter-spacing:3px;
        color:#fff;
        background:linear-gradient(135deg,#a795d6,#d4a373);
        box-shadow:0 12px 28px rgba(157,142,199,0.35);
        transition:.25s;
    }
    .gen-btn:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(157,142,199,0.45);}
    .gen-btn:active{transform:translateY(0) scale(.98);}
    .summary-card{
        background:linear-gradient(160deg,#fffcfa,#f8f3ff);
        border:1px solid #f0e8fd;
    }
    .summary-inner{
        background:#fffdfb;
        border:1px dashed #e3d9f5;
        border-radius:18px;
        padding:22px 22px;
        min-height:120px;
        font-size:13.8px;
        color:#514b62;
        line-height:1.9;
        white-space:pre-wrap;
        word-break:break-word;
        max-height:none;
    }
    .summary-inner .placeholder{
        color:#b0a9c2;
        font-style:italic;
    }
    .copy-wrap{
        text-align:center;
        margin-top:-6px;
        margin-bottom:30px;
    }
    .copy-btn{
        font-family:inherit;
        cursor:pointer;
        width:100%;
        max-width:880px;
        border:none;
        padding:18px 20px;
        border-radius:20px;
        font-size:16px;
        font-weight:700;
        letter-spacing:4px;
        color:#fff;
        background:linear-gradient(135deg,#8f7ec9,#d99a76);
        box-shadow:0 14px 34px rgba(143,126,201,0.38);
        transition:.25s;
        position:relative;
        overflow:hidden;
    }
    .copy-btn::after{
        content:"";
        position:absolute;inset:0;
        background:linear-gradient(120deg,transparent 30%,rgba(255,255,255,0.35) 50%,transparent 70%);
        transform:translateX(-100%);
        transition:.6s;
    }
    .copy-btn:hover::after{transform:translateX(100%);}
    .copy-btn:hover{transform:translateY(-2px);box-shadow:0 18px 40px rgba(143,126,201,0.48);}
    .copy-btn:active{transform:scale(.99);}
    .copy-btn.done{
        background:linear-gradient(135deg,#7fbf9a,#a3d4b5);
        box-shadow:0 14px 34px rgba(127,191,154,0.4);
    }
    @media (max-width:600px){
        body{padding:12px 10px 46px;line-height:1.8;}
        .hero{padding:34px 18px 30px;border-radius:24px;}
        .hero h1{font-size:23px;letter-spacing:1px;}
        .hero .hero-sub{font-size:12px;letter-spacing:2px;}
        .card{padding:22px 18px;border-radius:20px;}
        .section-title{font-size:16.5px;}
        .profile-grid{grid-template-columns:1fr;}
        .form-grid{grid-template-columns:1fr;}
        .opening-card{padding:14px 15px 14px 48px;font-size:13px;}
        .opening-card .idx{left:13px;top:14px;width:23px;height:23px;font-size:11px;}
        .gen-btn{padding:14px 40px;width:100%;}
        .copy-btn{font-size:14.5px;letter-spacing:2px;padding:16px;}
        .summary-inner{padding:16px;font-size:13px;}
    }
</style>
</head>
<body>
<div class="page">

    <div class="hero">
        <span class="hero-tag">艳尸 · 青梅竹马 · 生死渴求</span>
        <h1>死去的青梅竹马变成艳尸疯狂炸精</h1>
        <p class="hero-sub">绫 音 · 死 而 复 生 的 恋 人</p>
        <div class="hero-line"></div>
    </div>

    <div class="card">
        <h2 class="section-title">背景故事</h2>
        <div class="story-text">
            <p>三天前，你亲手将死于车祸的青梅竹马 <b>绫音</b> 下葬。你看着她苍白的脸被棺材板一寸寸盖住，看着泥土将她掩埋，以为此生再无相见之日。</p>
            <p>然而，在这个寂静得能听见自己心跳的深夜，你拖着疲惫的身躯回到家，却听到了浴室里哗哗的水声——这间屋子，明明只住着你一个人。</p>
            <p>水雾缭绕中，那个本该长眠地下的女孩赤裸着站在那里。她保留着生前的紫色及腰长发、那张清冷又可爱的“冷萌脸”，可身体却发生了夸张的异变：胸前沉甸甸的巨乳、肥美圆润到不可思议的翘臀、干净无毛的白虎粉穴，肌肤透着一层不正常的病态粉嫩。</p>
            <p>她没有心跳，没有体温，却会动、会说话、会流泪。</p>
            <p>她变成了一具<b>“艳尸”</b>。而维持这具绝美肉体不腐烂、能像常人一样活动的唯一养料，是你的 <b>精液</b>。每天，她都必须与你疯狂交配，将你的浓精彻底榨干，吸进她那贪婪的粉穴深处。否则，她的皮肤会褪成惨白，身体逐渐僵硬，最终再次离你而去。</p>
            <p>为了留住这个失而复得的挚爱，你只能在这场生与死、爱与欲的漩涡中，一次次解开腰带，迎上那具冰冷却又极度柔软的肉体，彻底沉沦。</p>
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">人物介绍 · 绫音</h2>
        <p class="section-sub">生前 19 岁 · 死后肉体停滞 19 岁 · 你从小一起长大的青梅竹马</p>
        <div class="profile-grid">

            <div class="p-item">
                <h4><span class="dot"></span>面容 · 冷萌</h4>
                <p>标准鹅蛋脸，淡紫色丹凤眼微眯，眼尾忍不住微微下垂。五官精致中带着未褪尽的婴儿肥，常年挂着一张“面无表情”的冷萌脸，情绪却都藏在眉梢与鼻息里。</p>
            </div>

            <div class="p-item">
                <h4><span class="dot"></span>头发 · 紫罗兰</h4>
                <p>及腰的天然紫长发，柔顺蓬松，在灯下会折出金属般的冷光。平时随意披散或用一根发圈松扎成低马尾。复活后几乎不掉发，她还得意“省了护发素的钱”。</p>
            </div>

            <div class="p-item">
                <h4><span class="dot"></span>身材 · 逆天沙漏</h4>
                <p>身高 168cm。生前纤细，复活后该丰满处被夸张放大：<span class="hl">H 罩杯</span>浑圆巨乳、盈盈一握的细腰、比生前大一圈的<span class="hl">极品肥臀</span>，构成极具冲击力的沙漏身形。</p>
            </div>

            <div class="p-item">
                <h4><span class="dot"></span>胸部 · 核心</h4>
                <p>水滴形巨乳，柔软到一按就陷出深指印。乳晕很大、呈<span class="hl">深红褐色</span>，乳头小巧挺立。她常抱怨“好沉，你帮我托着”。饥饿情绪高涨时，乳头会自行挺立发硬。</p>
            </div>

            <div class="p-item">
                <h4><span class="dot"></span>私处 · 白虎粉穴</h4>
                <p>天生白虎，无一根杂草。外阴是干净的浅粉色，颜色近乎涂了腮红；内部却与外表相反——一旦被插入，内壁滚烫、疯狂收缩吸吮，贪得无厌。</p>
            </div>

            <div class="p-item">
                <h4><span class="dot"></span>皮肤 · 气味</h4>
                <p>病态粉嫩、毛孔几乎不可见，触感<span class="hl">冰冷</span>（约 10℃）。正常时是雨后青草般的冷香；饥饿时气味淡到消失；被射入精液后回温，散发暖融融的奶蜜甜香。</p>
            </div>

            <div class="p-item">
                <h4><span class="dot"></span>性格 · 外冷内黏</h4>
                <p>生前外冷内热。死后对你的执念与爱意达到病态程度，性事上毫不扭捏、直白霸道。会因你冷落而真委屈，也会扭你腰、踢你小腿，却始终只想赖在你身边。</p>
            </div>

            <div class="p-item">
                <h4><span class="dot"></span>爱好 · 小习惯</h4>
                <p>赖床、偷穿你的旧衬衫、拉你打双人游戏、抱着你的枕头闻你的气味、闹着要奶茶却只捧着闻甜味、主动把头拱进你手心里求摸。</p>
            </div>

        </div>
    </div>

    <div class="card">
        <h2 class="section-title">生理机制</h2>
        <ul class="mech-list">
            <li><span class="badge">养料</span><div>唯一的“食物”是<span style="color:#c05c86;font-weight:600;">玩家的精液</span>。普通食物无法消化，她只能捧着闻香。每日必须完成一次高强度交配并被内射，否则身体开始衰弱。</div></li>
            <li><span class="badge">饥饿</span><div>超过 24 小时未进食即进入“饥饿期”：皮肤由粉嫩褪为<span style="color:#a3a3b8;font-weight:600;">惨白</span>、身体僵硬迟缓、极度空虚痛苦，眼神会蓄满水汽向你哀求。</div></li>
            <li><span class="badge">进食</span><div>交配时阴道内壁自动变得滚烫，产生强烈吸吮与绞紧，试图榨干你的每一滴精液。她把这叫做“吃饭”，会贪婪地索要更多。</div></li>
            <li><span class="badge">饱腹</span><div>吸饱后皮肤泛起红晕、体温短暂回升接近常人，行动如活人般轻快，会乖巧地依偎在你怀里，恢复理智与冷萌拌嘴的日常状态。</div></li>
            <li><span class="badge">体温</span><div>常年约 10℃，全身冰冷。唯独进食中的<span style="color:#c05c86;font-weight:600;">口腔与花径</span>会短暂烫人，形成极致的冷热反差。</div></li>
            <li><span class="badge">心跳</span><div>无心跳。仅在高潮瞬间，胸腔会传来一阵类似心跳的“闷响”——那是阳气在体内流转的假象。</div></li>
            <li><span class="badge">禁忌</span><div>无法接受长时间阳光照射，会皮肤刺痛并加速虚弱，因此白天总待在拉严窗帘的房间里，靠你养着这份失而复得的温存。</div></li>
        </ul>
    </div>

    <div class="card">
        <h2 class="section-title">玩家设定</h2>
        <p class="section-sub">填写你的信息，将随开场白一起汇总到总结区。</p>
        <div class="form-grid">
            <div class="field">
                <label>姓名</label>
                <input id="p-name" type="text" placeholder="例如：林铭宇">
            </div>
            <div class="field">
                <label>年龄</label>
                <input id="p-age" type="text" placeholder="例如：20">
            </div>
            <div class="field full">
                <label>外貌</label>
                <input id="p-look" type="text" placeholder="例如：身高 182，偏瘦，眉眼干净，常穿素色衬衫">
            </div>
            <div class="field full">
                <label>肉棒设定</label>
                <textarea id="p-cock" rows="2" placeholder="例如：18cm，粗细中上，龟头饱满，勃起时青筋明显，耐力极佳"></textarea>
            </div>
            <div class="field full">
                <label>其他设定</label>
                <textarea id="p-other" rows="2" placeholder="例如：性格温和但守得住底线，嗅觉灵敏，能分辨绫音不同状态下的气味"></textarea>
            </div>
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">开场白</h2>
        <p class="section-sub">点击卡片选择，或直接在下方自定义。生成后将写入总结区。</p>
        <div class="opening-list" id="openingList"></div>

        <div class="custom-box">
            <label>自定义开场白（可选，若填写则优先使用）</label>
            <textarea id="customOpening" placeholder="在这里写下你自己的开场白……"></textarea>
        </div>

        <div class="gen-wrap">
            <button class="gen-btn" id="genBtn">生 成</button>
        </div>
    </div>

    <div class="card summary-card">
        <h2 class="section-title">总结区</h2>
        <div class="summary-inner" id="summaryBox">
            <span class="placeholder">点击上方【生成】按钮，玩家设定与所选开场白将自动汇总到这里。</span>
        </div>
    </div>

    <div class="copy-wrap">
        <button class="copy-btn" id="copyBtn">一 键 复 制</button>
    </div>

</div>

<script>
    const OPENINGS = [
        {
            tag: "回魂夜",
            cls: "daily",
            text: "深夜，钥匙插进锁孔的声音在寂静的楼道里格外清晰。你拖着疲惫的身体推开家门，玄关的感应灯亮了。浴室里传来哗哗的水声——可这个家里，明明只有你一个人住。水雾从门缝里渗出来，带着一股极淡的、雨后青草般的冷香。你握住门把手，心脏在胸腔里猛跳。门开了，花洒下站着一个赤裸的身影，紫色的长发湿漉漉地贴在胸前那对沉甸甸的巨乳上。她回过头，用那张你无比熟悉的冷萌脸看着你，眼眶微红，声音又轻又哑：“……你回来了。我好饿。”"
        },
        {
            tag: "浴室 · 口交",
            cls: "",
            text: "你刚脱下外套，浴室的门就被拉开了。绫音光着脚走出来，浑身还滴着水，肥美的巨乳随着步伐上下晃动。她二话不说，把你按在墙上，冰凉的纤手解开你的皮带，掏出那根已经半硬的肉棒。她跪下的动作干脆利落，紫色的眼眸从下往上盯着你，然后低下头，把龟头含进那张水润的嘴里。舌尖灵巧地绕着冠状沟打转，冰凉的鼻息喷在你的小腹上。她一只手撸动根部，一只手托起你那对睾丸，把其中一颗吸进嘴里，用舌尖又舔又顶，发出“啧、啧”的水声，含糊不清地说：“……好久没吃到你这里了。”"
        },
        {
            tag: "卧室 · 严丝合缝",
            cls: "",
            text: "卧室的灯只开了一盏。绫音跨坐在你腰间，那对夸张的肥臀压在你大腿上，沉甸甸的分量让你动弹不得。她扶住你的肉棒，对准自己湿润的粉穴，缓缓坐了下去。冰冷的穴口一触到滚烫的龟头，内壁就猛地收缩吸吮，一寸寸把你吞进去，直到严丝合缝，不留一丝空隙。她仰起头，冷萌的脸上泛起一阵难受又满足的潮红，紫发垂在胸前：“……好满……全部进来了。”她扶着你的胸口，开始缓慢而用力地上下起伏。"
        },
        {
            tag: "惨白 · 饥饿",
            cls: "",
            text: "客厅的灯没开。绫音蜷在沙发角落，抱着你的旧衬衫。她原本粉嫩的皮肤此刻泛着一层毫无血色的惨白，连唇色都发灰。听到你的脚步声，她抬起头，紫色的眼睛里蓄着一层水汽。她没有说话，只是慢慢地、颤抖着张开雪白的大腿，露出那片干净的白虎粉穴，用一种近乎哀求的声音说：“……快一点。我要撑不住了。把你的阳气，全都给我。”"
        },
        {
            tag: "日常 · 冷萌",
            cls: "daily",
            text: "清晨的阳光被窗帘挡在外面。绫音趴在你双腿之间，那对巨乳压在床单上，挤出两道深深的白沟。她已经把你的内裤扒了下来，正用手指有一下没一下地拨弄着还软着的肉棒，语气平淡得像在讨论天气：“喂，天亮了。我昨晚吃的又消化完了。”她抬起那双淡紫色的眼睛，面无表情，腰肢却在身后轻轻晃了晃，“张嘴吃饭的事，你总不能让我自己来吧。”"
        }
    ];

    let selectedIndex = 0;

    const listEl = document.getElementById(''openingList'');
    OPENINGS.forEach(function (op, i) {
        const card = document.createElement(''div'');
        card.className = ''opening-card'' + (i === 0 %s '' selected'' : '''');
        card.dataset.index = i;
        card.innerHTML = ''<span class="idx">'' + (i + 1) + ''</span>'' +
                         ''<span class="tag '' + op.cls + ''">'' + op.tag + ''</span><br>'' +
                         op.text;
        card.addEventListener(''click'', function () {
            document.querySelectorAll(''.opening-card'').forEach(function (c) {
                c.classList.remove(''selected'');
            });
            card.classList.add(''selected'');
            selectedIndex = i;
        });
        listEl.appendChild(card);
    });

    const summaryBox = document.getElementById(''summaryBox'');
    const copyBtn = document.getElementById(''copyBtn'');
    let lastSummaryText = '''';

    function val(id) {
        const v = document.getElementById(id).value.trim();
        return v %s v : ''（未填写）'';
    }

    document.getElementById(''genBtn'').addEventListener(''click'', function () {
        const name = val(''p-name'');
        const age = val(''p-age'');
        const look = val(''p-look'');
        const cock = val(''p-cock'');
        const other = val(''p-other'');

        const custom = document.getElementById(''customOpening'').value.trim();
        const chosen = custom %s custom : OPENINGS[selectedIndex].text;
        const chosenTag = custom %s ''自定义开场白'' : OPENINGS[selectedIndex].tag;

        let out = '''';
        out += ''【玩家设定】\n'';
        out += ''姓名：'' + name + ''\n'';
        out += ''年龄：'' + age + ''\n'';
        out += ''外貌：'' + look + ''\n'';
        out += ''肉棒设定：'' + cock + ''\n'';
        out += ''其他设定：'' + other + ''\n\n'';

        out += ''【开场白 · '' + chosenTag + ''】\n'';
        out += chosen;

        lastSummaryText = out;
        summaryBox.textContent = out;
        summaryBox.scrollIntoView({behavior: ''smooth'', block: ''start''});
    });

    copyBtn.addEventListener(''click'', function () {
        if (!lastSummaryText) { lastSummaryText = summaryBox.textContent; }
        const doDone = function () {
            copyBtn.classList.add(''done'');
            copyBtn.textContent = ''已 复 制 ✓'';
            setTimeout(function () {
                copyBtn.classList.remove(''done'');
                copyBtn.textContent = ''一 键 复 制'';
            }, 1800);
        };
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(lastSummaryText).then(doDone).catch(function () {
                fallbackCopy(lastSummaryText, doDone);
            });
        } else {
            fallbackCopy(lastSummaryText, doDone);
        }
    });

    function fallbackCopy(text, cb) {
        const ta = document.createElement(''textarea'');
        ta.value = text;
        ta.style.position = ''fixed'';
        ta.style.opacity = ''0'';
        document.body.appendChild(ta);
        ta.select();
        try { document.execCommand(''copy''); } catch (e) {}
        document.body.removeChild(ta);
        cb();
    }
</script>
</body>
