    background: transparent !important;
    position: relative !important;
    z-index: 1 !important;
}

/* 段落 */
.markdown-body p {
    margin: 0.8em 0 !important;
    padding-left: 12px !important;
    border-left: 2px solid rgba(0, 212, 170, 0.3) !important;
}

/* 标题系列 */
.markdown-body h1,
.markdown-body h2,
.markdown-body h3,
.markdown-body h4,
.markdown-body h5,
.markdown-body h6 {
    color: #006d5b !important;
    font-weight: 700 !important;
    margin: 1.2em 0 0.6em 0 !important;
    padding: 8px 16px !important;
    background: linear-gradient(90deg, rgba(0, 212, 170, 0.1) 0%, transparent 100%) !important;
    border-left: 4px solid #00d4aa !important;
    border-radius: 0 8px 8px 0 !important;
    position: relative !important;
}

.markdown-body h1::before,
.markdown-body h2::before,
.markdown-body h3::before {
    content: ''◆'' !important;
    color: #00d4aa !important;
    margin-right: 8px !important;
    font-size: 0.8em !important;
}

.markdown-body h1 { font-size: 1.6em !important; }
.markdown-body h2 { font-size: 1.4em !important; }
.markdown-body h3 { font-size: 1.2em !important; border-left-color: #00bcd4 !important; }
.markdown-body h4 { font-size: 1.1em !important; border-left-color: #7c4dff !important; }

/* 粗体文本 */
.markdown-body strong,
.markdown-body b {
    color: #00796b !important;
    font-weight: 700 !important;
    padding: 0 4px !important;
    background: rgba(0, 212, 170, 0.1) !important;
    border-radius: 3px !important;
}

/* 斜体文本 */
.markdown-body em,
.markdown-body i {
    color: #5e35b1 !important;
    font-style: italic !important;
}

/* 链接 */
.markdown-body a {
    color: #00bcd4 !important;
    text-decoration: none !important;
    border-bottom: 1px dashed #00bcd4 !important;
    transition: all 0.2s !important;
}

.markdown-body a:hover {
    color: #00d4aa !important;
    border-bottom-style: solid !important;
    background: rgba(0, 212, 170, 0.1) !important;
}

/* ═══════════════════════════════════════════════════════════════
   🔷 代码块 - 机甲控制台
   ═══════════════════════════════════════════════════════════════ */
.markdown-body pre {
    background: linear-gradient(135deg, #e8f5f3 0%, #e3f2fd 100%) !important;
    border: 1px solid rgba(0, 212, 170, 0.4) !important;
    border-left: 4px solid #00d4aa !important;
    border-radius: 0 12px 12px 0 !important;
    padding: 16px !important;
    margin: 16px 0 !important;
    overflow-x: auto !important;
    position: relative !important;
    box-shadow: 
        inset 0 2px 4px rgba(0, 0, 0, 0.03),
        0 2px 8px rgba(0, 212, 170, 0.1) !important;
}

.markdown-body pre::before {
    content: ''[ MECHA_CONSOLE ]'' !important;
    position: absolute !important;
    top: 0 !important;
    right: 0 !important;
    background: linear-gradient(90deg, #00d4aa, #00bcd4) !important;
    color: white !important;
    font-size: 10px !important;
    padding: 2px 10px !important;
    border-radius: 0 12px 0 8px !important;
    font-weight: 600 !important;
    letter-spacing: 1px !important;
}

.markdown-body pre code {
    background: transparent !important;
    color: #1a3a4a !important;
    font-family: ''JetBrains Mono'', ''Fira Code'', ''Consolas'', monospace !important;
    font-size: 13px !important;
    padding: 0 !important;
    border: none !important;
}

/* 行内代码 */
.markdown-body code {
    background: linear-gradient(90deg, rgba(0, 212, 170, 0.15), rgba(0, 188, 212, 0.15)) !important;
    color: #00796b !important;
    padding: 2px 8px !important;
    border-radius: 4px !important;
    font-family: ''JetBrains Mono'', ''Consolas'', monospace !important;
    font-size: 0.9em !important;
    border: 1px solid rgba(0, 212, 170, 0.3) !important;
}

/* ═══════════════════════════════════════════════════════════════
   🔷 引用块 - 通讯面板
   ═══════════════════════════════════════════════════════════════ */
.markdown-body blockquote {
    background: linear-gradient(90deg, rgba(124, 77, 255, 0.08) 0%, rgba(0, 188, 212, 0.05) 100%) !important;
    border: 1px solid rgba(124, 77, 255, 0.2) !important;
    border-left: 4px solid #7c4dff !important;
    border-radius: 0 12px 12px 0 !important;
    margin: 16px 0 !important;
    padding: 12px 16px 12px 20px !important;
    position: relative !important;
    color: #4a148c !important;
}

.markdown-body blockquote::before {
    content: ''📡'' !important;
    position: absolute !important;
    left: -14px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    background: white !important;
    padding: 4px !important;
    border-radius: 50% !important;
    font-size: 16px !important;
    box-shadow: 0 2px 8px rgba(124, 77, 255, 0.3) !important;
}

.markdown-body blockquote p {
    border-left: none !important;
    padding-left: 0 !important;
    margin: 0.4em 0 !important;
}

/* ═══════════════════════════════════════════════════════════════
   🔷 列表 - 系统模块
   ═══════════════════════════════════════════════════════════════ */
.markdown-body ul,
.markdown-body ol {
    padding-left: 24px !important;
    margin: 12px 0 !important;
}

.markdown-body ul li,
.markdown-body ol li {
    margin: 8px 0 !important;
    padding-left: 8px !important;
    position: relative !important;
}

.markdown-body ul li::marker {
    color: #00d4aa !important;
    content: ''▸'' !important;
}

.markdown-body ol li::marker {
    color: #00bcd4 !important;
    font-weight: 700 !important;
}

/* ═══════════════════════════════════════════════════════════════
   🔷 表格 - 数据矩阵（统一样式）
   ═══════════════════════════════════════════════════════════════ */
.markdown-body table {
    width: 100% !important;
    border-collapse: separate !important;
    border-spacing: 0 !important;
    margin: 20px 0 !important;
    background: rgba(255, 255, 255, 0.9) !important;
    border: 2px solid #00d4aa !important;
    border-radius: 12px !important;
    overflow: hidden !important;
    box-shadow: 0 4px 16px rgba(0, 212, 170, 0.15) !important;
}

.markdown-body table thead tr {
    background: linear-gradient(90deg, #00d4aa 0%, #00bcd4 50%, #7c4dff 100%) !important;
}

.markdown-body table th {
    color: white !important;
    font-weight: 700 !important;
    padding: 14px 16px !important;
    text-align: left !important;
    border: none !important;
    font-size: 13px !important;
    letter-spacing: 0.5px !important;
    text-transform: uppercase !important;
}

/* 统一行样式 - 不区分奇偶 */
.markdown-body table tbody tr {
    background: rgba(240, 253, 250, 0.6) !important;
    transition: all 0.2s !important;
}

.markdown-body table tbody tr:hover {
    background: rgba(0, 212, 170, 0.12) !important;
}

.markdown-body table td {
    padding: 12px 16px !important;
    border-bottom: 1px solid rgba(0, 212, 170, 0.2) !important;
    border-right: 1px dashed rgba(0, 212, 170, 0.15) !important;
    color: #1a3a4a !important;
}

.markdown-body table td:last-child {
    border-right: none !important;
}

.markdown-body table tbody tr:last-child td {
    border-bottom: none !important;
}

/* ═══════════════════════════════════════════════════════════════
   🔷 分割线 - 能量通道
   ═══════════════════════════════════════════════════════════════ */
.markdown-body hr {
    border: none !important;
    height: 3px !important;
    background: linear-gradient(90deg, 
        transparent 0%, 
        #00d4aa 15%, 
        #00bcd4 35%,
        #7c4dff 50%,
        #00bcd4 65%,
        #00d4aa 85%, 
        transparent 100%
    ) !important;
    margin: 24px 0 !important;
    border-radius: 2px !important;
    position: relative !important;
}

.markdown-body hr::before {
    content: ''◇◆◇'' !important;
    position: absolute !important;
    left: 50% !important;
    top: 50% !important;
    transform: translate(-50%, -50%) !important;
    background: white !important;
    padding: 0 16px !important;
    color: #00d4aa !important;
    font-size: 12px !important;
    letter-spacing: 4px !important;
}

/* ═══════════════════════════════════════════════════════════════
   🔷 图片 - 全息投影框
   ═══════════════════════════════════════════════════════════════ */
.markdown-body img {
    border: 2px solid #00d4aa !important;
    border-radius: 8px !important;
    box-shadow: 
        0 4px 16px rgba(0, 212, 170, 0.2),
        0 0 0 4px rgba(0, 212, 170, 0.05) !important;
    transition: all 0.3s !important;
    max-width: 100% !important;
}

.markdown-body img:hover {
    transform: scale(1.02) !important;
    box-shadow: 
        0 8px 32px rgba(0, 212, 170, 0.3),
        0 0 20px rgba(0, 188, 212, 0.2) !important;
}

/* ═══════════════════════════════════════════════════════════════
   🔷 底部控制按钮
   ═══════════════════════════════════════════════════════════════ */
.MuiButtonBase-root.MuiButton-root.MuiButton-text.MuiButton-textPrimary {
    color: #00796b !important;
    font-family: ''Consolas'', monospace !important;
    font-size: 11px !important;
    font-weight: 600 !important;
    padding: 4px 10px !important;
    margin: 2px !important;
    background: rgba(0, 212, 170, 0.08) !important;
    border: 1px solid rgba(0, 212, 170, 0.3) !important;
    border-radius: 4px !important;
    transition: all 0.2s !important;
    text-transform: uppercase !important;
    letter-spacing: 0.5px !important;
}

.MuiButtonBase-root.MuiButton-root.MuiButton-text.MuiButton-textPrimary:hover {
    background: rgba(0, 212, 170, 0.2) !important;
    border-color: #00d4aa !important;
    box-shadow: 0 0 10px rgba(0, 212, 170, 0.3) !important;
    color: #004d40 !important;
}

/* 模型名称 */
.MuiTypography-root.MuiTypography-body2.css-6c0gf2 {
    color: #00796b !important;
    font-family: ''Consolas'', monospace !important;
    font-size: 11px !important;
    font-weight: 500 !important;
    padding: 2px 8px !important;
    background: rgba(0, 188, 212, 0.1) !important;
    border-radius: 4px !important;
    border: 1px dashed rgba(0, 188, 212, 0.3) !important;
}

/* Token消耗 */
.text-orange-500 {
    color: #7c4dff !important;
    font-family: ''Consolas'', monospace !important;
    font-weight: 600 !important;
    font-size: 11px !important;
    padding: 2px 6px !important;
    background: rgba(124, 77, 255, 0.08) !important;
    border-radius: 4px !important;
}

/* ═══════════════════════════════════════════════════════════════
   🔷 滚动条美化
   ═══════════════════════════════════════════════════════════════ */
.markdown-body::-webkit-scrollbar,
.markdown-body pre::-webkit-scrollbar {
    width: 8px !important;
    height: 8px !important;
}

.markdown-body::-webkit-scrollbar-track,
.markdown-body pre::-webkit-scrollbar-track {
    background: rgba(0, 212, 170, 0.05) !important;
    border-radius: 4px !important;
}

.markdown-body::-webkit-scrollbar-thumb,
.markdown-body pre::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #00d4aa, #00bcd4) !important;
    border-radius: 4px !important;
}

.markdown-body::-webkit-scrollbar-thumb:hover,
.markdown-body pre::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, #00bcd4, #7c4dff) !important;
}

/* ═══════════════════════════════════════════════════════════════
   🔷 移动端适配
   ═══════════════════════════════════════════════════════════════ */
@media (max-width: 480px) {
    .bg-gray-100\/90.relative.inline-block {
        padding: 12px !important;
        border-radius: 4px 12px 4px 12px !important;
    }
    
    .bg-gray-100\/90.relative.inline-block::before,
    .bg-gray-100\/90.relative.inline-block::after {
        width: 28px !important;
        height: 28px !important;
    }
    
    .markdown-body {
        font-size: 14px !important;
    }
    
    }

/* ═══════════════════════════════════════════════════════════════
   🔷 减少动效模式
   ═══════════════════════════════════════════════════════════════ */
@media (prefers-reduced-motion: reduce) {
    .bg-gray-100\/90.relative.inline-block,
    .bg-gray-100\/90.relative.inline-block:hover {
        transition: none !important;
        transform: none !important;
    }
}

css
/* ═══════════════════════════════════════════════════════════════
   🔷 战术数据条 (Tactical Data Logs) - 稀有度配色方案
   ═══════════════════════════════════════════════════════════════ */

/* === 通用基础样式 === */
[class^="t-"], [class*=" t-"] {
    display: inline-block !important;
    width: 98% !important; /* 稍微留点空隙 */
    padding: 6px 12px !important;
    margin: 4px 0 !important;
    border-radius: 4px !important;
    font-family: ''Consolas'', ''JetBrains Mono'', monospace !important;
    font-size: 14px !important;
    font-weight: 600 !important;
    line-height: 1.5 !important;
    position: relative !important;
    overflow: hidden !important;
    box-shadow: 0 2px 5px rgba(0,0,0,0.05) !important;
    transition: transform 0.2s !important;
}

[class^="t-"]:hover, [class*=" t-"]:hover {
    transform: translateX(4px) !important;
}

/* 左侧光条装饰 (伪元素) */
[class^="t-"]::before, [class*=" t-"]::before {
    content: '''' !important;
    position: absolute !important;
    left: 0 !important;
    top: 0 !important;
    bottom: 0 !important;
    width: 4px !important;
}

/* ⬛ 黑色 (Black) - 深渊/诅咒/机密 */
.t-black {
    background: linear-gradient(90deg, #212121 0%, #424242 100%) !important;
    color: #e0e0e0 !important;
    border: 1px solid #000000 !important;
}
.t-black::before { background: #000000 !important; box-shadow: 0 0 8px rgba(0,0,0,0.8) !important; }

/* ⬜ 灰色 (Gray) - 普通/废弃 */
.t-gray {
    background: rgba(158, 158, 158, 0.15) !important;
    color: #616161 !important;
    border: 1px solid rgba(158, 158, 158, 0.3) !important;
}
.t-gray::before { background: #9e9e9e !important; }

/* ⚪ 白色 (White) - 基础/通用 (高亮修正) */
/* 注意：在浅色背景下，白色文字必须加深色背景或描边，这里采用“银翼白”风格 */
.t-white {
    background: linear-gradient(90deg, #ffffff 0%, #f5f5f5 100%) !important;
    color: #455a64 !important; /* 使用深蓝灰字体以确保可读性 */
    border: 1px solid #cfd8dc !important;
    box-shadow: inset 0 0 10px rgba(255,255,255,0.8) !important;
}
.t-white::before { background: #b0bec5 !important; }

/* 🟢 绿色 (Green) - 优秀/生化 */
.t-green {
    background: rgba(0, 200, 83, 0.1) !important;
    color: #00695c !important; /* 深绿文字确保清晰 */
    border: 1px solid rgba(0, 200, 83, 0.3) !important;
}
.t-green::before { background: #00e676 !important; box-shadow: 0 0 8px rgba(0, 230, 118, 0.4) !important; }

/* 🔵 蓝色 (Blue) - 精良/能量 */
.t-blue {
    background: rgba(41, 121, 255, 0.1) !important;
    color: #0277bd !important;
    border: 1px solid rgba(41, 121, 255, 0.3) !important;
}
.t-blue::before { background: #2979ff !important; box-shadow: 0 0 8px rgba(41, 121, 255, 0.4) !important; }

/* 🌸 粉色 (Pink) - 魅惑/特殊 */
.t-pink {
    background: rgba(255, 64, 129, 0.1) !important;
    color: #c2185b !important;
    border: 1px solid rgba(255, 64, 129, 0.3) !important;
}
.t-pink::before { background: #ff4081 !important; box-shadow: 0 0 8px rgba(255, 64, 129, 0.4) !important; }

/* 🟣 紫色 (Purple) - 史诗/虚空 */
.t-purple {
    background: rgba(170, 0, 255, 0.1) !important;
    color: #7b1fa2 !important;
    border: 1px solid rgba(170, 0, 255, 0.3) !important;
}
.t-purple::before { background: #d500f9 !important; box-shadow: 0 0 8px rgba(213, 0, 249, 0.4) !important; }

/* 🟡 金色 (Gold) - 传说/至尊 */
.t-gold {
    background: linear-gradient(90deg, rgba(255, 215, 0, 0.15) 0%, rgba(255, 160, 0, 0.05) 100%) !important;
    color: #e65100 !important; /* 深橙色文字，防止金色太亮看不清 */
    border: 1px solid rgba(255, 193, 7, 0.5) !important;
    text-shadow: 0 0 1px rgba(255, 160, 0, 0.3) !important;
}
.t-gold::before { background: #ffab00 !important; box-shadow: 0 0 10px rgba(255, 171, 0, 0.6) !important; }

/* 🔴 红色 (Red) - 神话/危险/警告 */
.t-red {
    background: rgba(213, 0, 0, 0.1) !important;
    color: #b71c1c !important;
    border: 1px solid rgba(213, 0, 0, 0.3) !important;
    animation: text-pulse 2s infinite !important; /* 红色稍微带点呼吸感 */
}
.t-red::before { background: #ff1744 !important; box-shadow: 0 0 10px rgba(255, 23, 68, 0.5) !important; }

/* 🌈 彩色 (Rainbow / UR) - 至高/位面级 */
.t-rainbow, .t-ur {
    background: linear-gradient(90deg, rgba(255,95,109,0.14) 0%, rgba(255,195,113,0.14) 25%, rgba(71,230,177,0.14) 50%, rgba(90,184,255,0.14) 75%, rgba(197,108,240,0.14) 100%) !important;
    color: #c2185b !important;
    border: 1px solid rgba(197,108,240,0.6) !important;
    text-shadow: 0 0 1px rgba(255,95,210,0.4) !important;
    animation: t-ur-hue 4s linear infinite !important;
}
.t-rainbow::before, .t-ur::before { background: #ff5fd2 !important; box-shadow: 0 0 10px rgba(255,95,210,0.6) !important; }
@keyframes t-ur-hue { 0% { filter: hue-rotate(0deg); } 100% { filter: hue-rotate(360deg); } }

/* 定义呼吸动画 */
@keyframes text-pulse {
    0% { box-shadow: inset 0 0 0 rgba(255, 23, 68, 0); }
    50% { box-shadow: inset 0 0 10px rgba(255, 23, 68, 0.1); }
    100% { box-shadow: inset 0 0 0 rgba(255, 23, 68, 0); }
}

css
/* ═══════════════════════════════════════════════════════════════
   🔷 GLOBAL INTERFACE - 浅色机甲全息指挥中心
   ═══════════════════════════════════════════════════════════════ */

/* ═══════════════════════════════════════════════════════════════
   🛠️ 顶部栏 (Top Bar) - 战术HUD
   ═══════════════════════════════════════════════════════════════ */
.sticky.w-full.top-0.flex.items-center {
    background: rgba(255, 255, 255, 0.85) !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    border-bottom: 1px solid rgba(0, 212, 170, 0.3) !important;
    box-shadow: 
        0 4px 20px rgba(0, 212, 170, 0.1),
        0 1px 0 rgba(255, 255, 255, 0.5) inset !important;
    z-index: 50 !important;
}

/* 模型选择器 - 芯片卡槽 */
#ai-model-selector .group.flex.items-center,#customized-model-selector .group.flex.items-center{
    background: linear-gradient(90deg, rgba(0, 212, 170, 0.1), rgba(0, 188, 212, 0.05)) !important;
    border: 1px solid rgba(0, 212, 170, 0.3) !important;
    border-radius: 4px !important;
    padding: 4px 12px !important;
    transition: all 0.3s !important;
    clip-path: polygon(10px 0, 100% 0, 100% 100%, 0 100%, 0 10px) !important; /* 切角设计 */
}

#ai-model-selector .group.flex.items-center:hover,#customized-model-selector .group.flex.items-center:hover{
    background: rgba(0, 212, 170, 0.15) !important;
    box-shadow: 0 0 15px rgba(0, 212, 170, 0.2) !important;
    border-color: #00d4aa !important;
}

/* 模型名称 */
#ai-model-selector .truncate.text-\[13px\],#customized-model-selector .truncate.text-\[13px\]{
    color: #00796b !important;
    font-family: ''Consolas'', monospace !important;
    font-weight: 700 !important;
    letter-spacing: 0.5px !important;
    text-transform: uppercase !important;
}

/* 下拉箭头 */
#ai-model-selector .shrink-0.flex.items-center svg,#customized-model-selector .shrink-0.flex.items-center svg{
    color: #00bcd4 !important;
    filter: drop-shadow(0 0 2px rgba(0, 188, 212, 0.5)) !important;
}

/* 设置按钮 - 齿轮核心 */
#header-setting-button {
    color: #7c4dff !important;
    background: rgba(124, 77, 255, 0.05) !important;
    border-radius: 50% !important;
    transition: all 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) !important;
}

#header-setting-button:hover {
    background: rgba(124, 77, 255, 0.15) !important;
    transform: rotate(90deg) scale(1.1) !important;
    box-shadow: 0 0 15px rgba(124, 77, 255, 0.3) !important;
}

/* ═══════════════════════════════════════════════════════════════
   📜 开场白 (Intro) - 任务简报面板
   ═══════════════════════════════════════════════════════════════ */
div.flex.items-center.cursor-pointer.group[class*="border-gray"] {
    background: linear-gradient(to right, #f0fdfa, #ffffff) !important;
    border: 1px solid rgba(0, 188, 212, 0.4) !important;
    border-left: 4px solid #00bcd4 !important;
    border-radius: 4px 12px 12px 4px !important;
    box-shadow: 0 2px 8px rgba(0, 188, 212, 0.1) !important;
}

div.flex.items-center.cursor-pointer.group[class*="border-gray"]:hover {
    transform: translateX(4px) !important;
    box-shadow: 0 4px 12px rgba(0, 188, 212, 0.2) !important;
}

/* 图标染色 */
#ai-model-selector .group.flex.items-center svg:not(.lucide-triangle-alert),#customized-model-selector .group.flex.items-center svg:not(.lucide-triangle-alert){
    color: #00bcd4 !important;
}

/* ═══════════════════════════════════════════════════════════════
   🎮 底部栏 (Bottom Bar) - 驾驶舱主控台
   ═══════════════════════════════════════════════════════════════ */
/* 底部背景渐变 */
.bg-gradient-to-t {
    background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0.9) 60%, rgba(255,255,255,0) 100%) !important;
    backdrop-filter: blur(4px) !important;
}

/* 输入框容器 */
div:has(> div > #ai-chat-input) {
    background: rgba(240, 253, 250, 0.9) !important;
    border: 2px solid #00d4aa !important;
    border-radius: 12px !important;
    box-shadow: 
        0 0 0 4px rgba(0, 212, 170, 0.1),
        0 8px 20px rgba(0, 212, 170, 0.15) !important;
    transition: all 0.3s !important;
    padding: 8px !important;
}

div:has(> div > #ai-chat-input):focus-within {
    border-color: #7c4dff !important;
    box-shadow: 
        0 0 0 4px rgba(124, 77, 255, 0.1),
        0 8px 25px rgba(124, 77, 255, 0.2) !important;
    background: #ffffff !important;
}

/* 主输入框 */
#ai-chat-input {
    color: #1a3a4a !important;
    font-family: ''Consolas'', sans-serif !important;
    font-size: 15px !important;
}

#ai-chat-input::placeholder {
    color: rgba(0, 121, 107, 0.4) !important;
    font-style: italic !important;
}

#ai-chat-input::selection {
    background: rgba(0, 212, 170, 0.3) !important;
    color: #004d40 !important;
}

/* ═══════════════════════════════════════════════════════════════
   📟 分页栏 (Pagination) - 能量节点
   ═══════════════════════════════════════════════════════════════ */
.MuiPaginationItem-root {
    color: #00796b !important;
    border: 1px solid rgba(0, 212, 170, 0.3) !important;
    background: rgba(255, 255, 255, 0.5) !important;
    border-radius: 4px !important; /* 方形节点 */
    font-family: ''Consolas'', monospace !important;
    transition: all 0.2s !important;
}

.MuiPaginationItem-root:hover {
    background: rgba(0, 212, 170, 0.1) !important;
    border-color: #00d4aa !important;
    transform: translateY(-2px) !important;
}

.MuiPaginationItem-root.Mui-selected {
    background: linear-gradient(135deg, #00d4aa, #00bcd4) !important;
    color: white !important;
    border: none !important;
    box-shadow: 0 4px 10px rgba(0, 212, 170, 0.3) !important;
    font-weight: bold !important;
}

/* 跳转输入框 */
.MuiInputBase-input {
    color: #00796b !important;
    font-family: ''Consolas'', monospace !important;
    text-align: center !important;
}

/* ═══════════════════════════════════════════════════════════════
   📡 评论区 (Comments) - 全球通讯网络
   ═══════════════════════════════════════════════════════════════ */
/* 评论区主容器背景 */
div[class*="w-full"][class*="bg-white"][class*="bottom-0"] {
    background-color: #f8fafc !important; /* 极淡的灰蓝色底 */
    background-image: 
        linear-gradient(rgba(0, 212, 170, 0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(0, 212, 170, 0.03) 1px, transparent 1px) !important;
    background-size: 20px 20px !important;
    border-top: 2px solid #00d4aa !important;
}

/* 标题 */
div.text-lg.font-bold {
    color: #1a3a4a !important;
    text-transform: uppercase !important;
    letter-spacing: 1px !important;
    position: relative !important;
    display: inline-block !important;
}

div.text-lg.font-bold::after {
    content: '' [COMM_CHANNEL]'' !important;
    font-size: 12px !important;
    color: #00d4aa !important;
    font-weight: normal !important;
}

/* 评分星星 */
span.MuiRating-iconFilled svg {
    color: #00d4aa !important; /* 激活为机甲绿 */
    filter: drop-shadow(0 0 2px rgba(0, 212, 170, 0.5)) !important;
}

span.MuiRating-iconEmpty svg {
    color: #cfd8dc !important; /* 空星为金属灰 */
}

/* 评论输入框 */
textarea.rc-textarea {
    background: #ffffff !important;
    border: 1px solid rgba(0, 188, 212, 0.3) !important;
    border-radius: 8px !important;
    color: #37474f !important;
    font-family: ''Consolas'', sans-serif !important;
}

textarea.rc-textarea:focus {
    border-color: #7c4dff !important;
    box-shadow: 0 0 0 2px rgba(124, 77, 255, 0.1) !important;
}

/* 发送按钮 - 激活核心 */
div.cursor-pointer.group.flex.items-center.justify-center {
    background: linear-gradient(135deg, #00d4aa, #00bcd4) !important;
    border-radius: 8px !important;
    transition: all 0.3s !important;
}

div.cursor-pointer.group.flex.items-center.justify-center:hover {
    box-shadow: 0 0 15px rgba(0, 212, 170, 0.4) !important;
    transform: scale(1.05) !important;
}

div[data-state="closed"] svg[data-icon="Send03"] {
    color: white !important;
}

/* 评论列表项 - 通讯气泡 */
div.group.ml-0 {
    background: rgba(255, 255, 255, 0.8) !important;
    border: 1px solid rgba(0, 188, 212, 0.2) !important;
    border-radius: 8px !important;
    padding: 12px !important;
    margin-bottom: 12px !important;
    position: relative !important;
    transition: all 0.2s !important;
}

div.group.ml-0:hover {
    border-color: #00d4aa !important;
    box-shadow: 0 4px 12px rgba(0, 212, 170, 0.1) !important;
    background: #ffffff !important;
}

/* 头像 - 能量环绕 */
div.group img.rounded-full {
    border: 2px solid #00d4aa !important;
    padding: 2px !important;
    background: white !important;
}

/* 用户名 */
div.text-sm.text-grey-600 span.font-bold {
    color: #00796b !important;
    font-family: ''Consolas'', monospace !important;
}

/* "(你)" 标签 */
span.text-\[10px\] {
    background: #7c4dff !important;
    color: white !important;
    padding: 1px 6px !important;
    border-radius: 4px !important;
    font-weight: bold !important;
}

/* 评论内容 */
div.break-all {
    color: #37474f !important;
    line-height: 1.6 !important;
    font-size: 14px !important;
}

/* 回复按钮 */
span.cursor-pointer {
    color: #00bcd4 !important;
    font-weight: 600 !important;
    font-size: 12px !important;
    transition: all 0.2s !important;
}

span.cursor-pointer:hover {
    color: #7c4dff !important;
    text-shadow: 0 0 5px rgba(124, 77, 255, 0.3) !important;
}

