/* ═══════════════════════════════════════════════════════════════
   🔷 羁绊NPC卡片 - 机甲全息档案系统
   ═══════════════════════════════════════════════════════════════ */

/* ═══ 卡片主容器 ═══ */
.bond-npc-card {
    background: linear-gradient(135deg, #f8fafc 0%, #f0fdfa 50%, #e0f7fa 100%) !important;
    border: 2px solid transparent !important;
    border-image: linear-gradient(135deg, #00d4aa, #00bcd4, #7c4dff) 1 !important;
    border-radius: 12px !important;
    margin: 16px 0 !important;
    overflow: hidden !important;
    box-shadow: 
        0 8px 32px rgba(0, 212, 170, 0.15),
        inset 0 1px 0 rgba(255, 255, 255, 0.8) !important;
}

/* ═══ Summary标题栏 ═══ */
.bond-npc-card > summary {
    background: linear-gradient(90deg, #00d4aa, #00bcd4, #7c4dff) !important;
    color: white !important;
    font-family: ''Consolas'', ''JetBrains Mono'', monospace !important;
    font-size: 16px !important;
    font-weight: 700 !important;
    padding: 12px 20px !important;
    cursor: pointer !important;
    list-style: none !important;
    position: relative !important;
    text-transform: uppercase !important;
    letter-spacing: 2px !important;
    text-shadow: 0 2px 4px rgba(0,0,0,0.2) !important;
}

.bond-npc-card > summary::-webkit-details-marker {
    display: none !important;
}

.bond-npc-card > summary::before {
    content: ''▶ '' !important;
    transition: transform 0.3s !important;
}

.bond-npc-card[open] > summary::before {
    content: ''▼ '' !important;
}

.bond-npc-card > summary:hover {
    filter: brightness(1.1) !important;
}

/* ═══ 内容区域 ═══ */
.bond-content {
    padding: 16px !important;
    background: rgba(255, 255, 255, 0.6) !important;
}

/* ═══ 各区块样式 ═══ */
.bond-section {
    background: rgba(255, 255, 255, 0.8) !important;
    border: 1px solid rgba(0, 212, 170, 0.2) !important;
    border-left: 4px solid #00d4aa !important;
    border-radius: 0 8px 8px 0 !important;
    margin-bottom: 12px !important;
    padding: 12px 16px !important;
    position: relative !important;
    transition: all 0.3s !important;
}

.bond-section:hover {
    border-color: rgba(0, 212, 170, 0.4) !important;
    box-shadow: 0 4px 12px rgba(0, 212, 170, 0.1) !important;
    background: rgba(255, 255, 255, 0.95) !important;
}

/* 区块标题 */
.section-title {
    font-family: ''Consolas'', monospace !important;
    font-size: 13px !important;
    font-weight: 700 !important;
    color: #00796b !important;
    text-transform: uppercase !important;
    letter-spacing: 1px !important;
    margin-bottom: 10px !important;
    padding-bottom: 6px !important;
    border-bottom: 1px dashed rgba(0, 188, 212, 0.3) !important;
}

/* 区块内文字 */
.bond-section p {
    margin: 0 !important;
    font-size: 13px !important;
    line-height: 1.8 !important;
    color: #37474f !important;
}

.bond-section b {
    color: #00695c !important;
}

/* ═══ 特殊区块样式 ═══ */
/* 隐藏档案区 */
.section-hidden {
    border-left-color: #7c4dff !important;
    background: linear-gradient(90deg, rgba(124, 77, 255, 0.05), rgba(255,255,255,0.8)) !important;
}

.section-hidden .section-title {
    color: #7c4dff !important;
}

/* 记忆库区 */
.section-memory {
    border-left-color: #ff9800 !important;
    background: linear-gradient(90deg, rgba(255, 152, 0, 0.05), rgba(255,255,255,0.8)) !important;
}

.section-memory .section-title {
    color: #e65100 !important;
}

/* ═══ 标签样式 ═══ */
/* 性格标签 */
.tag-personality {
    display: inline-block !important;
    background: linear-gradient(135deg, rgba(0, 212, 170, 0.15), rgba(0, 188, 212, 0.1)) !important;
    color: #00796b !important;
    font-size: 12px !important;
    font-weight: 600 !important;
    padding: 2px 8px !important;
    margin: 2px 4px 2px 0 !important;
    border-radius: 12px !important;
    border: 1px solid rgba(0, 212, 170, 0.3) !important;
}

/* 重要性标签 */
.importance-tag {
    display: inline-block !important;
    background: linear-gradient(135deg, #7c4dff, #536dfe) !important;
