}

.observe-wrap-v2:focus-within .secret-trigger-v2::before {
    animation: none !important;
}

.observe-wrap-v2:focus-within .secret-popup-v2 {
    display: block !important;
    animation: mecha-pop-v2 0.3s ease-out !important;
}

/* ═══ 移动端适配 ═══ */
@media (max-width: 480px) {
    .bond-npc-card > summary {
        font-size: 14px !important;
        padding: 10px 14px !important;
    }
    
    .bond-section {
        padding: 10px 12px !important;
    }
    
    .bond-section p {
        font-size: 12px !important;
    }
    
    .section-title {
        font-size: 12px !important;
    }
    
    .tag-personality {
        font-size: 11px !important;
        padding: 1px 6px !important;
    }
}

