/* ═══════════════════════════════════════════════════════════════
   💗 旮旯给木界面 (Galgame Interface) - Sweet Cyberpunk Mod
   ═══════════════════════════════════════════════════════════════ */

/* 主容器 */
.gal-interface {
    font-family: ''Microsoft YaHei'', ''SimHei'', sans-serif !important;
    margin-top: 10px !important;
    border: 2px solid #ff80ab !important; /* 樱花粉边框 */
    border-radius: 12px !important;
    background: linear-gradient(135deg, #fff0f5 0%, #ffffff 100%) !important; /* 浅粉白渐变 */
    box-shadow: 0 4px 15px rgba(255, 64, 129, 0.2) !important;
    overflow: hidden !important;
}

/* 标题栏 (Summary) */
.gal-header {
    background: linear-gradient(90deg, #ff4081, #ff80ab) !important;
    color: white !important;
    padding: 8px 12px !important;
    font-weight: bold !important;
    font-size: 14px !important;
    letter-spacing: 1px !important;
    cursor: pointer !important;
    list-style: none !important;
    position: relative !important;
}

.gal-header::after {
    content: ''♥'' !important;
    position: absolute !important;
    right: 12px !important;
    animation: gal-heartbeat 1.5s infinite !important;
}

@keyframes gal-heartbeat {
    0% { transform: scale(1); }
    50% { transform: scale(1.3); }
    100% { transform: scale(1); }
}

/* 内容区 */
.gal-body {
    padding: 12px !important;
}

/* 顶部布局 (头像+数值) */
.gal-top-row {
    display: flex !important;
    gap: 12px !important;
    margin-bottom: 12px !important;
    align-items: center !important;
}

/* 头像框 */
.gal-portrait-frame {
    width: 60px !important;
    height: 60px !important;
    border-radius: 50% !important;
    background: #ffebee !important;
    border: 2px solid #ff4081 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    position: relative !important;
    flex-shrink: 0 !important;
}

.gal-avatar-placeholder {
    font-size: 12px !important;
    color: #c2185b !important;
    font-weight: bold !important;
    text-align: center !important;
}

/* 心情光环 */
.gal-mood-ring {
    position: absolute !important;
    top: -4px !important;
    left: -4px !important;
    right: -4px !important;
    bottom: -4px !important;
    border-radius: 50% !important;
    border: 2px dashed #ff80ab !important;
    animation: gal-spin 10s linear infinite !important;
}

@keyframes gal-spin { 100% { transform: rotate(360deg); } }

/* 数值面板 */
.gal-stats-panel {
    flex-grow: 1 !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 6px !important;
}

.gal-stat-row {
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
    font-size: 12px !important;
}

.gal-label {
    width: 85px !important;
    color: #880e4f !important;
    font-weight: bold !important;
}

.gal-bar-bg {
    flex-grow: 1 !important;
    height: 8px !important;
    background: rgba(0,0,0,0.05) !important;
    border-radius: 4px !important;
    overflow: hidden !important;
    border: 1px solid rgba(255, 64, 129, 0.2) !important;
}

.gal-bar-fill {
    height: 100% !important;
    border-radius: 4px !important;
    transition: width 0.5s ease !important;
    position: relative !important;
}

/* 进度条颜色 */
.pink-bar { background: linear-gradient(90deg, #ff80ab, #ff4081) !important; box-shadow: 0 0 8px rgba(255, 64, 129, 0.5) !important; }
.blue-bar { background: linear-gradient(90deg, #80deea, #00bcd4) !important; box-shadow: 0 0 8px rgba(0, 188, 212, 0.5) !important; }
.purple-bar { background: linear-gradient(90deg, #ea80fc, #d500f9) !important; box-shadow: 0 0 8px rgba(213, 0, 249, 0.5) !important; }

.gal-value {
    width: 35px !important;
    text-align: right !important;
    color: #c2185b !important;
    font-family: ''Consolas'', monospace !important;
}

/* 信息网格 */
.gal-info-grid {
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
    gap: 10px !important;
    margin-bottom: 10px !important;
}

.gal-info-box {
    background: rgba(255, 255, 255, 0.6) !important;
    border: 1px solid #ffcdd2 !important;
    border-radius: 8px !important;
    padding: 8px !important;
}

.gal-info-title {
    font-size: 11px !important;
    color: #ff4081 !important;
    text-transform: uppercase !important;
    margin-bottom: 4px !important;
    border-bottom: 1px dashed #ffcdd2 !important;
    padding-bottom: 2px !important;
    font-weight: bold !important;
}

.gal-info-content {
    font-size: 12px !important;
    color: #455a64 !important;
}

.gal-tag {
    display: inline-block !important;
    padding: 2px 6px !important;
    background: #fce4ec !important;
    color: #c2185b !important;
    border-radius: 4px !important;
    font-size: 11px !important;
    margin-right: 4px !important;
}

.gal-text-sm {
    font-size: 11px !important;
    color: #78909c !important;
    margin-top: 4px !important;
    font-style: italic !important;
}

/* 记忆碎片区 */
.gal-event-log {
    background: rgba(243, 229, 245, 0.5) !important;
    border: 1px solid #e1bee7 !important;
    border-radius: 8px !important;
    padding: 8px !important;
}

.gal-log-content {
    font-size: 12px !important;
    color: #6a1b9a !important;
    line-height: 1.6 !important;
}

.gal-check {
    color: #00e676 !important;
    font-weight: bold !important;
    margin-left: 4px !important;
}

/* 移动端适配 */
@media (max-width: 480px) {
    .gal-info-grid {
        grid-template-columns: 1fr !important;
    }
}

css
/* ═══════════════════════════════════════════════════════════════
   🔷 NPC DATABASE - 角色记忆矩阵战术美化
   ═══════════════════════════════════════════════════════════════ */

/* 主容器：数据库外壳 */
.npc-database {
    margin: 15px 0 !important;
    background: rgba(255, 255, 255, 0.6) !important;
    backdrop-filter: blur(10px) !important;
    -webkit-backdrop-filter: blur(10px) !important;
    border: 1px solid rgba(0, 212, 170, 0.3) !important;
    border-radius: 8px !important;
    overflow: hidden !important;
    box-shadow: 0 4px 15px rgba(0, 212, 170, 0.1) !important;
    font-family: ''Consolas'', ''JetBrains Mono'', monospace !important;
}

/* 主标题栏：📂 角色记忆矩阵 */
.npc-database > details > summary {
    background: linear-gradient(90deg, rgba(0, 212, 170, 0.15), rgba(0, 188, 212, 0.05)) !important;
    color: #00796b !important;
    padding: 12px 16px !important;
    font-weight: 700 !important;
    font-size: 14px !important;
    letter-spacing: 1px !important;
    cursor: pointer !important;
    list-style: none !important;
    border-bottom: 1px solid rgba(0, 212, 170, 0.2) !important;
    transition: all 0.3s !important;
    display: flex !important;
    align-items: center !important;
}

.npc-database > details > summary:hover {
    background: rgba(0, 212, 170, 0.25) !important;
    text-shadow: 0 0 8px rgba(0, 212, 170, 0.4) !important;
}

/* NPC卡片容器 */
.npc-card-container {
    padding: 10px !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 8px !important;
}

/* 单个NPC条目：芯片样式 */
.npc-item {
    background: rgba(255, 255, 255, 0.8) !important;
    border: 1px solid rgba(0, 188, 212, 0.2) !important;
    border-radius: 6px !important;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1) !important;
}

.npc-item[open] {
    border-color: #00bcd4 !important;
    box-shadow: 0 0 12px rgba(0, 188, 212, 0.15) !important;
    transform: scale(1.01) !important;
}

/* NPC标题：👤 姓名 · 好感度 */
.npc-item > summary {
    padding: 8px 12px !important;
    font-size: 13px !important;
    font-weight: 600 !important;
    color: #1a3a4a !important;
    cursor: pointer !important;
    list-style: none !important;
    display: flex !important;
    align-items: center !important;
    position: relative !important;
}

.npc-item > summary::before {
    content: ''ID_DATA'' !important;
    position: absolute !important;
    right: 10px !important;
    font-size: 9px !important;
    color: rgba(0, 188, 212, 0.5) !important;
    letter-spacing: 1px !important;
}

/* NPC详细信息区 */
.npc-info {
    padding: 0 12px 12px 12px !important;
    border-top: 1px dashed rgba(0, 188, 212, 0.1) !important;
    animation: slide-down 0.3s ease-out !important;
}

.npc-info p {
    margin: 8px 0 !important;
    font-size: 12px !important;
    color: #455a64 !important;
    line-height: 1.6 !important;
}

.npc-info b {
    color: #00bcd4 !important;
    margin-right: 4px !important;
}

/* 记忆节点列表 */
.memory-list {
    list-style: none !important;
    padding-left: 0 !important;
    margin: 8px 0 0 0 !important;
}

.memory-list li {
    font-size: 12px !important;
    padding: 4px 8px !important;
    margin-bottom: 4px !important;
    background: rgba(124, 77, 255, 0.03) !important;
    border-left: 2px solid #7c4dff !important;
    color: #5e35b1 !important;
    border-radius: 0 4px 4px 0 !important;
}

/* 实时摘要特殊高亮 (✨) */
.memory-list li:last-child {
    border-left-color: #00d4aa !important;
    background: rgba(0, 212, 170, 0.05) !important;
    color: #00796b !important;
    font-style: italic !important;
    animation: pulse-border 2s infinite !important;
}

/* ═══════════════════════════════════════════════════════════════
   ✨ 动效部分
   ═══════════════════════════════════════════════════════════════ */

/* 展开时的下滑动画 */
@keyframes slide-down {
    from { opacity: 0; transform: translateY(-5px); }
    to { opacity: 1; transform: translateY(0); }
}

/* 实时摘要的呼吸效果 */
@keyframes pulse-border {
    0% { border-left-width: 2px; }
    50% { border-left-width: 5px; border-left-color: #00bcd4; }
    100% { border-left-width: 2px; }
}

/* 隐藏默认箭头并自定义 */
.npc-database details summary::-webkit-details-marker {
    display: none !important;
}

.npc-item summary::after {
    content: ''◢'' !important;
    font-size: 8px !important;
    margin-left: auto !important;
    color: #00bcd4 !important;
    transition: transform 0.3s !important;
    margin-right: 60px !important; /* 避开ID_DATA文本 */
}

.npc-item[open] summary::after {
    transform: rotate(180deg) !important;
    color: #7c4dff !important;
}

/* 响应式适配 */
@media (max-width: 480px) {
    .npc-database {
        margin: 10px 0 !important;
    }
    .npc-item summary::after {
        margin-right: 45px !important;
    }
}
