                    { name: "被废弃的触手实验体", items: "几根断裂的触手残肢, 一身破烂的病号服" }
                ],
                talents: [
                    {name: "反物质触手(完全体)", color: "SSS", cost: 60000, desc: "你成为了像杀老师一样的超生物。拥有20马赫的移动速度，无限再生的触手，以及毁灭地球的能量。", type: "exclusive"},
                    {name: "死神的隐匿", color: "SS", cost: 7500, desc: "你是天生的暗杀者。当你不想被发现时，你的存在感会降至零，哪怕站在目标面前，他也看不见你。", type: "exclusive"},
                    {name: "绝对防御形态", color: "S", cost: 3000, desc: "在面临必死攻击时，你可以将身体压缩成一个高密度的球体，核弹都炸不穿，但24小时内无法动弹。", type: "exclusive"},
                    {name: "神之舌(毒鉴别)", color: "B", cost: 400, desc: "你能通过舌头分辨出任何毒素的成分，并能调配出连超生物都能麻痹的特制毒药。", type: "exclusive"},
                    {name: "双枪流(鹰冈流)", color: "A", cost: 850, desc: "你精通各种枪械格斗术，虽然手段卑鄙，但在实战中极为有效，能利用环境进行全方位压制。", type: "exclusive"},
                    {name: "对老师物质亲和", color: "B", cost: 500, desc: "你使用对老师专用武器时，伤害翻倍。这种特殊的橡胶物质在你手中比钢铁还要致命。", type: "exclusive"},
                    {name: "E班的羁绊", color: "C", cost: 200, desc: "当与队友协同作战时，你的各项属性提升20%。团结就是力量，暗杀也是需要配合的。", type: "exclusive"},
                    {name: "理事长的洗脑术", color: "A", cost: 1200, desc: "你拥有极强的语言煽动能力，能通过话术控制他人的思想，让他们陷入疯狂或绝望。", type: "exclusive"},
                    {name: "律(AI辅助)", color: "S", cost: 2500, desc: "你的大脑植入了自律思考固定炮台的AI芯片。拥有超强的计算能力，能瞬间分析出敌人的弱点和弹道。", type: "exclusive"},
                    {name: "触手植入(初期)", color: "A", cost: 1500, desc: "你的后颈植入了触手细胞。虽然会伴随剧痛和发热，但能让你获得超人的力量和反应速度。", type: "exclusive"},
                    {name: "业的恶作剧天赋", color: "C", cost: 180, desc: "你擅长制作各种整蛊道具和陷阱。虽然看起来不正经，但在战斗中往往能起到奇效。", type: "exclusive"},
                    {name: "渚的杀气", color: "S", cost: 2200, desc: "平时像个小绵羊，一旦进入暗杀状态，你会释放出让职业杀手都恐惧的纯粹杀意，瞬间瘫痪对手。", type: "exclusive"},
                    {name: "色诱术(比琪流)", color: "B", cost: 600, desc: "你掌握了伊莉娜老师的真传。能利用美色和语言让敌人放松警惕，然后给予致命一击。", type: "exclusive"},
                    {name: "超生物嗅觉", color: "B", cost: 350, desc: "你的嗅觉能分辨出每个人的情绪味道，甚至能闻出几公里外的甜点香气。", type: "exclusive"},
                    {name: "20马赫反应(伪)", color: "A", cost: 1800, desc: "虽然身体跟不上，但你的动态视力能捕捉到20马赫的移动轨迹，让你在超高速战斗中有一线生机。", type: "exclusive"}
                ]
            },
            {
                name: "39.网球王子",
