                ],
                talents: [
                    {name: "逢魔之力(碎片)", color: "SSS", cost: 50000, desc: "至高至善至强的魔王之力的一小块碎片。拥有支配森罗万象的潜力，可以破坏时空，召唤历代骑士的历史。", type: "exclusive"},
                    {name: "究极空我(黑目)", color: "SS", cost: 9000, desc: "凄厉的战士，招致究极的黑暗。全能力大幅提升，拥有分子操纵能力，但极易失去理智成为只会战斗的杀戮机器。", type: "exclusive"},
                    {name: "危险等级7.0", color: "SS", cost: 8000, desc: "你体内的星云气体极其活跃，超越了人类的极限。无需变身也能肉身打怪，变身后战力更是指数级暴涨。", type: "exclusive"},
                    {name: "昭和改造人体质", color: "S", cost: 3500, desc: "你的身体经过了残酷的改造手术。拥有常人几十倍的骨骼硬度和肌肉力量，不知疲倦，但同时也背负了非人的悲哀。", type: "exclusive"},
                    {name: "极光帷幕", color: "S", cost: 4500, desc: "次元壁的力量。你可以随意穿越空间，甚至穿越平行世界。跑路神技，打不过就摇人或者换个世界。", type: "exclusive"},
                    {name: "奥菲以诺因子", color: "A", cost: 1500, desc: "死后觉醒的进化人类。拥有灰白色的怪人形态，寿命极短但力量强大。攻击可使普通人类沙化。", type: "exclusive"},
                    {name: "镜世界适应", color: "A", cost: 1200, desc: "你可以在镜世界中自由活动而不会被分解。对于想成为龙骑系骑士的人来说，这是必须的前置天赋。", type: "exclusive"},
                    {name: "财团X的赞助", color: "B", cost: 800, desc: "你拥有神秘财团X的资金支持，可以获得各种骑士系统的实验数据和Gaia Memory的试作型。", type: "exclusive"},
                    {name: "硬汉侦探(Hard Boiled)", color: "B", cost: 500, desc: "无论受到多重的伤，你都能咬牙坚持。对精神攻击有极高的抗性，并且总能在绝境中保持冷静。", type: "exclusive"},
                    {name: "平成嘿嘿剑法", color: "C", cost: 300, desc: "虽然动作看起来很滑稽，且伴随着奇怪的音效，但实战效果出奇的好，能让敌人因为困惑而露出破绽。", type: "exclusive"},
                    {name: "不仅是看而已", color: "D", cost: 100, desc: "橘前辈的真传。你非常擅长躲在角落里观察战局，完全隐蔽自己的气息，直到战斗结束。", type: "exclusive"},
                    {name: "骑士踢(基础)", color: "C", cost: 250, desc: "所有骑士的必修课。将全身力量汇聚在脚部，配合重力加速度进行踢击，对怪人有特攻加成。", type: "exclusive"},
                    {name: "可以上的去!", color: "D", cost: 50, desc: "你拥有一辆普通的摩托车，但在你手里，它似乎能冲上任何斜坡和楼梯。", type: "exclusive"},
                    {name: "神之才能(自称)", color: "A", cost: 2000, desc: "你在游戏开发和卡带制作上有着惊人的天赋。只要有材料，你甚至能手搓变身器。副作用是性格会变得极度自恋。", type: "exclusive"},
                    {name: "加速(Clock Up)", color: "S", cost: 3800, desc: "操纵超光速粒子的能力。开启后，周围的一切都会近乎静止，你将在超高速的世界中主宰战场。", type: "exclusive"}
                ]
            },
            {
                name: "43.奥特银河大怪兽之战",
                desc: "怪兽无法无天的星球——波利斯。这里没有奥特曼的庇护，只有狂暴的怪兽和雷奥尼克斯之间的死斗。手持格斗仪，操纵怪兽，成为最强的雷奥尼克斯吧！",
                boss: "贝利亚奥特曼, 雷布朗多星人(精神体), 黑暗铠甲, 究极生命体雷布拉德",
                identities: [
                    { name: "ZAP施派西号维修工", items: "一把万能扳手, 沾满机油的工作服" },
                    { name: "佩丹星人逃兵", items: "损坏的黑色金古桥控制器, 佩丹星军服" },
                    { name: "波利斯行星幸存殖民者", items: "防毒面具, 一块过期的压缩饼干" },
                    { name: "被遗弃的雷奥尼克斯", items: "破碎的格斗仪, 充满憎恨的眼神" },
                    { name: "喜龙号运输船船员", items: "一张星际航图, 船员识别证" }
                ],
                talents: [
                    {name: "雷布朗多遗传因子(觉醒)", color: "SSS", cost: 45000, desc: "你彻底觉醒了雷布朗多的力量，可以变身为雷奥尼克斯格斗形态。所有怪兽在你面前都会感到恐惧，你有潜力支配全宇宙的怪兽。", type: "exclusive"},
                    {name: "千兆格斗仪(Giga Battlenizer)", color: "SS", cost: 12000, desc: "传说中能操纵一百头怪兽的终极神器。不仅能收纳怪兽，其本身也是威力巨大的武器，能发射强大的破坏光线。", type: "exclusive"},
                    {name: "EX进化", color: "S", cost: 5000, desc: "你可以激发怪兽的潜在力量，使其进行EX进化（如EX哥莫拉）。进化后的怪兽皮肤硬化，破坏力大幅提升。", type: "exclusive"},
                    {name: "雷奥尼克斯格斗仪(蓝)", color: "A", cost: 1500, desc: "标准的怪兽操控装置，可以收纳并恢复三只怪兽。拥有此物，你才算正式踏入雷奥尼克斯的战场。", type: "exclusive"},
                    {name: "哥莫拉(幼体)", color: "S", cost: 3500, desc: "古代怪兽哥莫拉的幼崽。虽然现在还很弱小，但潜力巨大，培养得当将成为你最忠实的王牌打手。", type: "exclusive"},
                    {name: "佩丹星科技", color: "A", cost: 2000, desc: "你掌握了佩丹星人的黑色金古桥制造技术。只要有足够的资源，你就能组装出一台无坚不摧的机器人军团。", type: "exclusive"},
                    {name: "宇宙人体质", color: "B", cost: 800, desc: "适应各种恶劣的宇宙环境，不需要氧气也能在真空中生存一段时间，身体素质远超地球人。", type: "exclusive"},
                    {name: "怪兽语言通晓", color: "B", cost: 600, desc: "你无需格斗仪也能理解怪兽的情绪和意图，这让你在野外遭遇野生怪兽时有更高的存活率。", type: "exclusive"},
                    {name: "盘龙号的羁绊", color: "C", cost: 300, desc: "你更容易获得ZAP队员的信任。在关键时刻，可能会有飞船支援你的战斗。", type: "exclusive"},
                    {name: "格斗本能", color: "C", cost: 250, desc: "即使没有武器，你的肉搏能力也相当出色。这在格斗仪丢失或损坏时是保命的关键。", type: "exclusive"},
                    {name: "怪兽图鉴知识", color: "C", cost: 200, desc: "你熟知各种怪兽的弱点和习性。知道打杰顿不能用光线，打雷德王要用巧劲。", type: "exclusive"},
                    {name: "利特拉的羽毛", color: "D", cost: 150, desc: "拥有一只原始怪鸟利特拉作为伙伴。虽然战斗力不强，但飞行速度快，适合侦查。", type: "exclusive"},
                    {name: "运气差", color: "E", cost: -50, desc: "你走路都能踩到怪兽的尾巴，或者飞船总是迫降在怪兽窝旁边。纯粹的倒霉蛋。", type: "exclusive"},
                    {name: "贝利亚的低语", color: "A", cost: -1000, desc: "负面天赋。你的脑海中时常响起贝利亚的诱惑，虽然能获得力量，但精神抗性降低，容易堕入黑暗。", type: "exclusive"},
                    {name: "雷奥尼克斯爆发模式", color: "SS", cost: 7000, desc: "当你的情绪极度激动时，全身会变为赤红色，操控的怪兽全属性暴增，但战斗结束后你会陷入极度虚弱。", type: "exclusive"}
                ]
            },
            {
                name: "44.灌篮高手 (Slam Dunk)",
                desc: "炎热的夏天，湘北高中的篮球馆。这里是属于热血少年的赛场，称霸全国不仅仅是一句口号。对于篮球门外汉来说，这里是残酷的竞技场。",
                boss: "山王工业全员, 泽北荣治, 牧绅一, 森重宽",
                identities: [
                    { name: "和光中学的不良少年", items: "一头染坏的头发, 50次失恋的记录" },
                    { name: "湘北篮球部的一年级新生", items: "擦得锃亮的篮球鞋, 拖把" },
                    { name: "陵南高中的替补", items: "田冈教练的笔记本(复印件), 柠檬切片" },
                    { name: "体育馆的清洁工大爷", items: "一把扫帚, 一串钥匙" },
                    { name: "爱知县的篮球观众", items: "一张全国大赛的门票, 诸星大的应援扇" }
                ],
                talents: [
                    {name: "灌篮高手(樱木)", color: "SSS", cost: 30000, desc: "集超强身体素质、惊人弹跳力、无限体能和天才般的学习能力于一身。你是为了篮球而生的怪物，拥有改变比赛流向的主角光环。", type: "exclusive"},
                    {name: "流川枫的进攻", color: "SS", cost: 9500, desc: "全方位的进攻万花筒。无论是突破、中投、三分还是扣篮，你都无可挑剔。拥有单人凿穿整条防线的实力。", type: "exclusive"},
                    {name: "安西教练的战术", color: "S", cost: 2500, desc: "白发佛的智慧。你能瞬间看穿对手的弱点，并制定出最针对性的战术。全队士气+50%。", type: "exclusive"},
                    {name: "三井寿的投篮", color: "S", cost: 3000, desc: "永不放弃的炎之男。体力越透支，投篮越精准。拥有教科书般的投篮姿势和极强的手感。", type: "exclusive"},
                    {name: "大猩猩的压迫感", color: "A", cost: 1800, desc: "赤木刚宪级别的篮下统治力。只要你站在篮下，就是一道叹息之墙。盖帽成功率大幅提升。", type: "exclusive"},
                    {name: "电光火石", color: "A", cost: 1600, desc: "宫城良田的速度。运球快如闪电，擅长抢断和快攻，是球场上的突击队长。", type: "exclusive"},
                    {name: "皇牌杀手", color: "B", cost: 800, desc: "南烈的防守风格。为了胜利不择手段，擅长用小动作和心理战术干扰对方王牌，甚至造成对方受伤。", type: "exclusive"},
                    {name: "长臂猿", color: "B", cost: 700, desc: "你的臂展远超身高，这让你在抢篮板和防守时拥有天然的优势。", type: "exclusive"},
                    {name: "强力篮板球", color: "C", cost: 400, desc: "控制篮板就能控制比赛。你对球的落点有敏锐的嗅觉，卡位技术一流。", type: "exclusive"},
                    {name: "哼哼防守", color: "C", cost: 300, desc: "樱木花道的绝技。用极快速度在对方面前形成残影墙，虽然看起来很蠢，但能有效干扰对方视线。", type: "exclusive"},
                    {name: "平民上篮", color: "D", cost: 100, desc: "最基础的上篮技巧，虽然不花哨，但胜在稳定，是初学者的必修课。", type: "exclusive"},
                    {name: "柔道高手", color: "C", cost: 200, desc: "青田龙彦的青睐。虽然是打篮球，但你的身体对抗能力极强，擅长在规则允许范围内挤开对手。", type: "exclusive"},
                    {name: "门外汉", color: "E", cost: 0, desc: "你完全不懂篮球规则，经常走步、二运，甚至把球投进自家篮筐。", type: "exclusive"},
                    {name: "泽北的抛投", color: "S", cost: 3200, desc: "日本第一高中生的绝技。面对高大防守者也能轻松得分的高抛上篮，极难被封盖。", type: "exclusive"},
                    {name: "山王的紧逼防守", color: "SS", cost: 8000, desc: "窒息般的零分战术。当你的队伍进行全场紧逼时，对手的失误率提高80%，体力消耗加倍。", type: "exclusive"}
                ]
            },
            {
                name: "45.头文字D",
                desc: "秋名山的深夜，引擎的轰鸣声撕裂寂静。这里是漂移的圣地，公道最速的传说。AE86、GTR、FC...车手们赌上尊严，在险峻的山道上极速狂飙。",
                boss: "藤原文太, 高桥凉介, 须藤京一, 神之手/神之脚",
                identities: [
                    { name: "群马县加油站的打工仔", items: "沾满油污的手套, 只有几百日元的钱包" },
                    { name: "秋名山山顶的观众", items: "对讲机, 一罐热咖啡" },
                    { name: "豆腐店老板的儿子(非拓海)", items: "一辆送货用的破旧自行车, 一板豆腐" },
                    { name: "SpeedStars车队的后勤", items: "备用轮胎, 计时器" },
                    { name: "东京来的飙车族", items: "租来的跑车, 傲慢的态度" }
                ],
                talents: [
                    {name: "藤原境界(Zone)", color: "SSS", cost: 32000, desc: "人车合一的最高境界。在极限状态下，周围的一切都会变慢，你能看见赛道上唯一的“光路”，并本能地做出最完美的过弯操作。", type: "exclusive"},
                    {name: "公道最速理论", color: "SS", cost: 10000, desc: "高桥凉介的赛车哲学。拥有顶级的数据分析能力和战术制定能力，能根据路况、车况和对手心理，计算出必胜的跑法。", type: "exclusive"},
                    {name: "盲眼追击(Blind Attack)", color: "S", cost: 5000, desc: "关灯杀。在黑夜中关闭车灯，利用对手的后视镜盲区瞬间超车。需要极高的胆量和对赛道的绝对记忆。", type: "exclusive"},
                    {name: "惯性漂移", color: "A", cost: 2000, desc: "利用重心转移让车身在入弯前横向滑动。这是高速过弯的基础，也是最具观赏性的技巧。", type: "exclusive"},
                    {name: "排水渠过弯", color: "S", cost: 3500, desc: "利用内侧车轮钩住排水渠，以此抵抗离心力，实现超高速过弯。这是秋名山的必杀技，但也极其毁车。", type: "exclusive"},
                    {name: "四驱系统的咆哮", color: "A", cost: 1800, desc: "岩城清次的风格。完全信赖车辆的性能，全油门过弯。虽然粗暴，但在上坡赛中拥有绝对的优势。", type: "exclusive"},
                    {name: "无手刹漂移", color: "B", cost: 1200, desc: "通过刹车和油门的配合控制车身姿态，比拉手刹更高级，出弯速度更快。", type: "exclusive"},
                    {name: "ABS干扰", color: "B", cost: 900, desc: "通过特殊的刹车技巧，让对手的ABS系统误判，从而打乱对手的节奏。", type: "exclusive"},
                    {name: "机械白痴", color: "D", cost: 50, desc: "你只管开车，完全不懂修车。如果车坏了，你就只能在路边等救援。", type: "exclusive"},
                    {name: "车辆改装大师", color: "A", cost: 1500, desc: "你能精准调校悬挂、引擎和轮胎，让车辆性能发挥到极致。一辆买菜车在你手里也能变成赛车。", type: "exclusive"},
                    {name: "G值抗性", color: "C", cost: 300, desc: "你的身体能承受长时间的高G力，不易晕车，在连续发夹弯中也能保持清醒。", type: "exclusive"},
                    {name: "路怒症", color: "D", cost: -100, desc: "负面天赋。一旦被超车，你就会失去理智，疯狂加速，极易导致车祸。", type: "exclusive"},
                    {name: "神之脚", color: "SS", cost: 8500, desc: "星野好造的油门控制技术。你能极其细腻地控制油门开度，就像在踩钢丝一样，让车辆始终保持在抓地力的极限。", type: "exclusive"},
                    {name: "文太的试驾", color: "S", cost: 4000, desc: "当你双手离开方向盘点烟时，才是你最快的时候。一种极其放松但又极其精准的驾驶状态。", type: "exclusive"},
                    {name: "86的灵魂", color: "B", cost: 600, desc: "你对老旧车型有特殊的亲和力，驾驶旧车时全属性提升20%。", type: "exclusive"}
                ]
            },
                      {
                name: "46.机动战士高达 U.C.宇宙",
                desc: "宇宙世纪（Universal Century），人类向太空移民的时代。地球联邦与吉翁公国的战争泥潭，米诺夫斯基粒子屏蔽了雷达，让战争回归视距内的机动兵器对决。",
                boss: "夏亚·阿兹纳布尔, 哈曼·卡恩, 帕普提马斯·西罗克",
                identities: [
                    { name: "Side 7 殖民卫星的避难平民", items: "一张只有单程的穿梭机票, 一个坏掉的哈罗玩具" },
                    { name: "吉翁公国军新兵", items: "一把扎古机枪的备用弹鼓, 一张写着“吉翁万岁”的家书" },
                    { name: "阿纳海姆电子公司的测试员", items: "未调试好的操作系统盘, 一件沾满机油的工装" },
                    { name: "地球联邦军后勤兵", items: "一箱难吃的压缩饼干, 一份高达的目击报告" },
                    { name: "非法废品回收商", items: "用来切割装甲的激光炬, 一个不知道用途的黑匣子" }
                ],
                talents: [
                    {name: "新人类(Newtype)", color: "SSS", cost: 12000, desc: "人类适应宇宙环境进化出的新感知能力。你能预判敌人的攻击，感应他人的思维，甚至引发物理法则无法解释的精神力场奇迹。", type: "exclusive"},
                    {name: "精神感应框架(共振)", color: "SS", cost: 8000, desc: "封印在机体骨架中的特殊材质。当你的精神达到临界点时，能引发“阿克西斯冲击”级别的奇迹，强行改变物理惯性。", type: "exclusive"},
                    {name: "赤色彗星的极速", color: "SS", cost: 7500, desc: "你拥有常人三倍的反应速度和操作手速。驾驶任何红色的机体时，你的机动性和闪避率额外提升300%。", type: "exclusive"},
                    {name: "强化人体质", color: "S", cost: 2500, desc: "通过药物和催眠强行赋予类似新人类的能力。战斗力极强，但精神极不稳定，且伴随着剧烈的头痛和寿命缩减。", type: "exclusive"},
                    {name: "米诺夫斯基物理学博士", color: "S", cost: 2200, desc: "你精通I力场和米加粒子的应用，能够手搓小型I力场发生器或者改良光束武器的出力。", type: "exclusive"},
                    {name: "王牌驾驶员(联邦/吉翁)", color: "A", cost: 800, desc: "你是在无数次死里逃生中磨练出的老兵，熟练掌握MS的格斗与射击技巧，不是那种开了一次高达就以为自己很行的死小鬼。", type: "exclusive"},
                    {name: "生物电脑接口", color: "A", cost: 900, desc: "你的大脑可以直接处理机体的反馈数据，大幅提升机体的反应速度，就像F91高达那样产生残像。", type: "exclusive"},
                    {name: "高达尼姆合金冶炼术", color: "B", cost: 450, desc: "你掌握了月神钛合金的配方和加工工艺，能制造出轻量化且防御力惊人的装甲板。", type: "exclusive"},
                    {name: "布莱特的弹幕指挥", color: "B", cost: 300, desc: "“左舷弹幕太薄了！”你拥有优秀的舰船指挥能力，能在混乱的战场上维持防线的生存率。", type: "exclusive"},
                    {name: "哈罗维修工", color: "C", cost: 150, desc: "你擅长修理各种球形机器人和辅助AI，虽然不能修高达，但能保证你的辅助设备不掉链子。", type: "exclusive"},
                    {name: "宇宙空间适应", color: "C", cost: 120, desc: "你在无重力环境下行动自如，不会出现空间迷向症，比重力束缚的灵魂强那么一点。", type: "exclusive"},
                    {name: "拉拉·辛的鬼魂", color: "D", cost: 80, desc: "你偶尔能听到一个温柔女性的声音在脑海里说话，这会让你分心，但偶尔也能预警危险。副作用是容易被面具男纠缠。", type: "exclusive"},
                    {name: "吉翁残党", color: "D", cost: 50, desc: "你对吉翁的复兴抱有执念，这让你在联邦控制区寸步难行，但也容易获得旧吉翁军人的帮助。", type: "exclusive"},
                    {name: "殖民卫星坠落后遗症", color: "E", cost: 20, desc: "你亲眼目睹了殖民卫星撞击地球，巨大的心理创伤让你在看到大质量物体坠落时会陷入恐慌瘫痪。", type: "exclusive"},
                    {name: "联邦高层的腐败", color: "E", cost: 10, desc: "你深知联邦内部的黑暗，这让你对任何命令都充满怀疑，士气永远低落，且容易被当作替罪羊。", type: "exclusive"}
                ]
            },
            {
                name: "47.机动战士高达 SEED世界",
                desc: "宇宙纪元（C.E.），调整者（基因改造人类）与自然人之间的种族战争。核能被封印，机体依赖电池，直到核能干扰消除器的出现。",
                boss: "帕特里克·萨拉, 劳·鲁·克鲁泽, 吉尔伯特·迪兰达尔",
                identities: [
                    { name: "海利奥波利斯的工科学生", items: "未完成的作业, 一个便携式编程终端" },
                    { name: "尤尼乌斯7号的幸存者", items: "一条染血的红围巾, 一张破碎的全家福" },
                    { name: "蓝色波斯菊的狂热信徒", items: "反调整者宣传手册, 一把私藏的手枪" },
                    { name: "奥布难民营的孤儿", items: "半瓶浑浊的水, 一颗捡来的粉色哈罗" },
                    { name: "沙漠之虎的游击队杂兵", items: "一条破旧的头巾, 一把简易的火箭筒" }
                ],
                talents: [
                    {name: "超级调整者(Ultimate)", color: "SSS", cost: 15000, desc: "人类基因工程的最高杰作。拥有完美的身体素质、学习能力和反应速度，是注定要站在顶点的存在，但也背负着孤独的宿命。", type: "exclusive"},
                    {name: "SEED爆种", color: "SS", cost: 6000, desc: "Superior Evolutionary Element Destined-factor。在绝境中种子破碎，你的瞳孔收缩，思维加速，瞬间进入绝对理性的战斗状态，全属性大幅提升。", type: "exclusive"},
                    {name: "反中子干扰器(NJC)", color: "SS", cost: 5000, desc: "你掌握了在这个世界解除核能封印的关键技术。拥有无限能源的核动力机体将成为可能，你是战争双方争夺的核心。", type: "exclusive"},
                    {name: "空间认知能力(S级)", color: "S", cost: 2800, desc: "你能完美操控龙骑兵系统（浮游炮），在多维空间中同时锁定几十个目标进行全方位打击，如同指挥一场交响乐。", type: "exclusive"},
                    {name: "调整者(第一代)", color: "A", cost: 1200, desc: "经过基因调整的新人类，免疫大多数疾病，智力和体能远超自然人，但也因此受到自然人的嫉妒和仇视。", type: "exclusive"},
                    {name: "相转移装甲(PS装甲)", color: "A", cost: 1500, desc: "只要有能源，就能通过电压改变装甲相态，免疫几乎所有实体弹药攻击。但要注意能量消耗极快。", type: "exclusive"},
                    {name: "幻象化粒子隐形", color: "B", cost: 600, desc: "利用特殊的粒子覆盖机体，使你在雷达和视觉上完全隐形。适合偷袭，但攻击瞬间会显形。", type: "exclusive"},
                    {name: "OS编写大师", color: "B", cost: 500, desc: "你能在这个世界手搓机体操作系统，让自然人也能流畅驾驶高达，或者让机体做出违背人体工学的动作。", type: "exclusive"},
                    {name: "歌姬的祈祷", color: "C", cost: 180, desc: "你的歌声或话语具有不可思议的感染力，能平复狂暴战士的心情，或者在战场上进行全频道广播洗脑。", type: "exclusive"},
                    {name: "沙漠之虎的咖啡道", color: "C", cost: 120, desc: "你擅长调配各种口味独特的咖啡，虽然大多数人觉得难喝，但能有效提神并获得特定NPC的好感。", type: "exclusive"},
                    {name: "自然人的愤怒", color: "D", cost: 80, desc: "你对调整者怀有本能的敌意，这让你在攻击调整者时攻击力微增，但无法冷静思考，且无法使用任何基因调整技术。", type: "exclusive"},
                    {name: "芙蕾的演技", color: "D", cost: 90, desc: "你擅长利用他人的感情来保护自己，能短暂获得强力保护伞，但最终可能导致众叛亲离。", type: "exclusive"},
                    {name: "基因缺陷(短命)", color: "E", cost: 30, desc: "作为失败的克隆人或调整者，你的端粒过短，经常需要服用药物维持生命，且随时可能暴毙。", type: "exclusive"},
                    {name: "独眼巨人系统的阴影", color: "E", cost: 10, desc: "你曾在微波武器的爆发中幸存，身体内部留下了严重的辐射暗伤，体质极差。", type: "exclusive"},
                    {name: "和平主义者的天真", color: "E", cost: 5, desc: "你在这个残酷的世界里坚持不杀原则，这导致你在战斗中处处受制，极容易被不讲武德的敌人杀死。", type: "exclusive"}
                ]
            },
            {
                name: "48.机动战士高达 00世界",
                desc: "公元2307年，化石燃料枯竭，世界依赖三座轨道电梯的太阳能。私人武装组织“天人”拥有名为高达的机体，试图通过武力根绝战争。",
                boss: "利邦兹·阿尔马克, 亚历杭德罗·科纳, 阿里·阿尔·萨谢斯",
                identities: [
                    { name: "阿扎迪斯坦王国的平民", items: "一本古老的经书, 一个没电的收音机" },
                    { name: "AEU联盟的飞行员", items: "制定式的驾驶手册, 一张未兑现的保险单" },
                    { name: "轨道电梯的低层维护工", items: "高空作业安全绳, 一份高额的人身意外险" },
                    { name: "人革联的超兵实验体", items: "特制的拘束衣, 编号铭牌" },
                    { name: "天人组织的机械师助手", items: "一个这种世界观下随处可见的哈罗, 维修用平板" }
                ],
                talents: [
                    {name: "纯种变革者(Innovator)", color: "SSS", cost: 18000, desc: "在GN粒子的影响下进化出的新人类。拥有连接量子脑波网络的能力，寿命极长，能在高浓度粒子中实现意识共享和超速再生，是即将对话外星生命的存在。", type: "exclusive"},
                    {name: "Trans-Am系统", color: "SS", cost: 7000, desc: "解放GN太阳炉的全部限制，机体变为红色，速度和出力提升三倍以上。结束后机体性能会大幅下降，是拼命的底牌。", type: "exclusive"},
                    {name: "双炉系统(Twin Drive)", color: "SS", cost: 9000, desc: "让两个太阳炉同步运作，产生的粒子量不是相加而是平方级增长。能开启量子化瞬移，甚至切开时空。", type: "exclusive"},
                    {name: "GN太阳炉(原版)", color: "S", cost: 3500, desc: "半永久能源机关，能产生拥有几乎无限能源的GN粒子。不仅能作为动力，还能屏蔽雷达、提供浮空力。", type: "exclusive"},
                    {name: "量子脑波(超兵)", color: "S", cost: 2600, desc: "经过改造的强化人能力，拥有极快的反应速度和双重人格切换能力。能感应周围的脑量子波，但容易头痛。", type: "exclusive"},
                    {name: "VEDA的访问权限(L5)", color: "A", cost: 1800, desc: "你拥有天人超级电脑VEDA的高级权限，能调取世界各地的情报，甚至能在一定程度上干涉审判系统，让敌方高达停机。", type: "exclusive"},
                    {name: "GN粒子护盾", color: "A", cost: 1200, desc: "利用高浓度GN粒子在机体周围形成绝对防御领域，能抵挡绝大多数实体和光束攻击。", type: "exclusive"},
                    {name: "佣兵的直觉", color: "B", cost: 500, desc: "像萨谢斯那样，在战场上拥有野兽般的嗅觉，极其擅长乱战和生存，没有任何道德负担。", type: "exclusive"},
                    {name: "太阳能技师", color: "C", cost: 150, desc: "你精通轨道电梯的太阳能传输技术，懂得如何维护和破坏能源管道。", type: "exclusive"},
                    {name: "拟变革者(量产)", color: "C", cost: 300, desc: "人造的变革者，拥有超越常人的身体素质和量子波连接能力，但缺乏创造性，通常作为消耗品。", type: "exclusive"},
                    {name: "轨道电梯恐高症", color: "E", cost: 10, desc: "在这个依赖轨道电梯的世界，你却有严重的恐高症，无法在这个世界最重要的交通工具上保持清醒。", type: "exclusive"},
                    {name: "GN粒子过敏", color: "E", cost: 20, desc: "接触到GN粒子会导致你皮肤红肿、呼吸困难，而这个世界到处都是这种粒子。", type: "exclusive"},
                    {name: "被世界遗弃", color: "D", cost: 50, desc: "你没有ID，没有国籍，在三大国势力的夹缝中生存，无法享受任何社会福利。", type: "exclusive"},
                    {name: "红色GN-T型太阳炉", color: "D", cost: 100, desc: "拥有拟似太阳炉，虽然能用，但能源有限且释放的红色粒子对人体有害，是一种有毒的力量。", type: "exclusive"},
                    {name: "战术预报员", color: "B", cost: 400, desc: "你擅长分析战场局势，制定战术计划。虽然不能直接提升战斗力，但能提高小队的胜率。", type: "exclusive"}
                ]
            },
            {
                name: "49.新世纪福音战士 (EVA)",
                desc: "第二次冲击后的世界，不明生命体“使徒”来袭。人类建立了NERV，制造了泛用人型决战兵器EVA，试图执行“人类补完计划”。",
                boss: "第1-17使徒, SEELE委员会, 碇源堂",
