                    { name: "NERV本部清洁工", items: "一张L1权限卡, 一瓶抗抑郁药" },
                    { name: "SEELE的底层观察员", items: "刻有死海文书片段的石板照片, 黑色单片眼镜" },
                    { name: "战自卫队士兵", items: "一把对使徒无效的步枪, 绝望的眼神" },
                    { name: "废弃Geofront的流浪者", items: "捡来的LCL液体样本, 生锈的管道扳手" }
                ],
                talents: [
                    {name: "生命之果(S2机关)", color: "SSS", cost: 30000, desc: "使徒的力量源泉。拥有无限的动力，无需脐带电缆即可行动，且赋予持有者极其恐怖的自我再生能力，近乎永生。", type: "exclusive"},
                    {name: "智慧之果(人类补完)", color: "SSS", cost: 28000, desc: "人类的力量源泉。拥有通过科学和理智改写现实的能力，是触发冲击、成神的必要条件之一。", type: "exclusive"},
                    {name: "绝对恐怖领域(AT Field)", color: "SS", cost: 8000, desc: "心之壁的具象化。能防御几乎所有物理和能量攻击（除核弹级以上），也能反转用于撕裂敌人的防御，甚至用来跳跃。", type: "exclusive"},
                    {name: "EVA适格者(高同步率)", color: "S", cost: 3000, desc: "你天生能与EVA机体进行高同步，同步率轻松突破100%，能发挥机体的全部潜能，但也容易在战斗中溶于LCL。", type: "exclusive"},
                    {name: "暴走模式", color: "S", cost: 4000, desc: "当机体失去能源或驾驶员失去意识时触发。机体如野兽般行动，力量速度暴增，不仅能手撕使徒，还能吞噬其S2机关。", type: "exclusive"},
                    {name: "MAGI系统操作员", color: "A", cost: 1200, desc: "你精通超级电脑MAGI的操作逻辑，能利用三台生物电脑进行复杂的战术演算和城市防御系统管理。", type: "exclusive"},
                    {name: "朗基努斯之枪(伪)", color: "A", cost: 2000, desc: "量产机使用的复制品。虽然不如原版能封印神，但依然拥有贯穿AT力场的绝对物理穿透力。", type: "exclusive"},
                    {name: "LCL适应体质", color: "B", cost: 500, desc: "你在充满LCL液体的驾驶舱内感觉像回家一样，能直接在液体中呼吸并保持清醒，精神污染抗性提升。", type: "exclusive"},
                    {name: "加持的西瓜种植术", color: "C", cost: 100, desc: "你懂得在末世废土中种植美味的西瓜，这是在这个压抑世界中难得的治愈技能，能拉近与关键角色的关系。", type: "exclusive"},
                    {name: "企鹅室友", color: "C", cost: 150, desc: "你有一只高智商的新温泉企鹅作为宠物，它能帮你拿啤酒，看家，甚至在关键时刻帮你送东西。", type: "exclusive"},
                    {name: "刺猬的困境", color: "D", cost: 50, desc: "你渴望温暖却又害怕被伤害，这让你在人际交往中极度别扭，难以建立深厚的羁绊，SAN值容易掉。", type: "exclusive"},
                    {name: "精神污染(轻度)", color: "D", cost: 80, desc: "接触过使徒或EVA后留下的后遗症，偶尔会看到幻觉，分不清现实与梦境，精神抗性降低。", type: "exclusive"},
                    {name: "傀儡系统(Dummy Plug)", color: "D", cost: 200, desc: "你的一部分意识被数据化，可以被用来代替驾驶员操作，但这种操作冷酷无情且没有任何人性。", type: "exclusive"},
                    {name: "父亲的忽视", color: "E", cost: 10, desc: "你的上司或长辈完全把你当工具人，这种缺爱感让你在面对哪怕一点点关怀时都会失去判断力。", type: "exclusive"},
                    {name: "第二次冲击幸存者", color: "E", cost: 20, desc: "你在那场灾难中活了下来，但失去了所有亲人，对海洋和红色液体有严重的PTSD。", type: "exclusive"}
                ]
            },
            {
                name: "50.反叛的鲁路修 (Code Geass)",
                desc: "神圣不列颠尼亚帝国侵略世界，日本被剥夺名字成为“11区”。被流放的皇子获得神秘力量Geass，在这个机甲(KMF)横行的世界掀起反叛。",
                boss: "查尔斯·zi·不列颠尼亚, 修奈泽尔, 俾斯麦(圆桌骑士NO.1)",
                identities: [
                    { name: "阿什弗德学园的学生", items: "一份学生会申请书, 11区旅游指南" },
                    { name: "新宿贫民窟的11区人", items: "破旧的身份证(写着Eleven), 一块发霉的面包" },
                    { name: "黑色骑士团的杂兵", items: "一套黑色的制服, 一把简陋的机枪" },
                    { name: "不列颠尼亚军纯血派士兵", items: "擦得锃亮的军靴, 贵族家谱" },
                    { name: "中华联邦的流亡劳工", items: "一本红宝书, 沉重的脚镣" }
                ],
                talents: [
                    {name: "Code(不老不死)", color: "SSS", cost: 25000, desc: "继承了V.V.或C.C.的印记。你获得了真正的不死之身，任何伤害都能复原，且能赋予他人Geass，是世界的观测者。", type: "exclusive"},
                    {name: "Geass(王之力)", color: "SS", cost: 10000, desc: "契约之力。效果随机，如“绝对命令”、“修改记忆”、“预知未来”等。初始只能对一人使用一次或有各种限制，随使用次数进化。", type: "exclusive"},
                    {name: "圆桌骑士级驾驶技术", color: "S", cost: 3500, desc: "你的机甲驾驶技术达到了帝国最强骑士的水准，能驾驶特装机（如兰斯洛特）做出违背物理常识的机动。", type: "exclusive"},
                    {name: "战术指挥(零之智慧)", color: "S", cost: 4000, desc: "你拥有甚至超越鲁路修的战术布局能力，擅长利用地形、人心和崩塌的建筑来逆转战局。", type: "exclusive"},
                    {name: "樱石(Sakuradite)干扰器", color: "A", cost: 1500, desc: "你掌握了干扰樱石运作的技术，能让以樱石为动力的KMF机体瞬间瘫痪，是战场上的大杀器。", type: "exclusive"},
                    {name: "辐射波动装置", color: "A", cost: 1800, desc: "红莲二式的核心武器，能通过抓取释放高周波辐射，瞬间加热并融毁敌机的装甲，近战无敌。", type: "exclusive"},
                    {name: "Geass消除器", color: "B", cost: 800, desc: "一种特殊的装置或能力，能消除Geass施加在人身上的效果，是Geass能力者的天敌。", type: "exclusive"},
                    {name: "罗伊德的改造手艺", color: "B", cost: 600, desc: "你是一个疯狂科学家，擅长魔改机体，只要性能提升，完全不顾驾驶员的死活和舒适度。", type: "exclusive"},
                    {name: "披萨大胃王", color: "C", cost: 100, desc: "你对披萨有无穷的食欲，这能帮你收集必胜客的积分，或者吸引某个不老不死的魔女的注意。", type: "exclusive"},
                    {name: "贵族血统(不列颠)", color: "C", cost: 200, desc: "你拥有帝国的爵位，在占领区享有特权，能轻易获得情报和资源，但也容易成为恐怖分子的目标。", type: "exclusive"},
                    {name: "娜娜莉的笑容", color: "C", cost: 150, desc: "你拥有极其治愈的笑容，能让妹控属性的角色对你言听计从，或者至少不会第一时间杀你。", type: "exclusive"},
                    {name: "Refrain毒瘾", color: "E", cost: 20, desc: "你沉迷于这种让人重温过去美好回忆的毒品，身体虚弱，精神萎靡，为了药可以出卖一切。", type: "exclusive"},
                    {name: "被剥夺的尊严(Eleven)", color: "E", cost: 10, desc: "作为被征服者，你在这个社会寸步难行，随时可能被不列颠士兵羞辱或射杀，没有任何法律保护。", type: "exclusive"},
                    {name: "Geass暴走(无法关闭)", color: "D", cost: 100, desc: "你的Geass力量失控，永久处于开启状态。如果你拥有的是“绝对命令”，那你甚至不敢随便和人说话。", type: "exclusive"},
                    {name: "虚假的记忆", color: "D", cost: 50, desc: "你的记忆被Geass修改过，你现在的身份和生活可能都是假的，这让你在关键时刻会产生认知错乱。", type: "exclusive"}
                ]
            },
                      {
                name: "51.天元突破 红莲螺岩",
                desc: "一个被螺旋力支配的世界。人类被迫居住在地下，地面由兽人统治。只要有气势，就能突破宇宙的限制。钻头是男人的浪漫！",
                boss: "罗杰诺姆, 反螺旋族, 维拉尔",
                identities: [
                    { name: "基哈村的挖洞少年", items: "一把磨损严重的钻头, 一副沾满泥土的护目镜" },
                    { name: "大红莲团的整备士", items: "沾满机油的扳手, 一件画着红莲团标志的破烂披风" },
                    { name: "兽人军的杂兵", items: "一把粗制滥造的石斧, 一个看起来很滑稽的兽人面具" },
                    { name: "利特纳村的幸存者", items: "一把老式猎枪, 一张珍藏的地面风景照片" },
                    { name: "颜面驾驶员学徒", items: "一本写满操作笔记的手册, 一个挂在脖子上的核心钻头复制品" }
                ],
                talents: [
                    {name: "螺旋力(觉醒)", color: "SSS", cost: 50000, desc: "拥有无限进化的可能性。你的气势可以直接转化为力量，打破物理法则，甚至创造物质。绝境是你最强的武器。", type: "exclusive"},
                    {name: "大红莲团之魂", color: "SS", cost: 8000, desc: "你继承了那份''以此钻头突破天际''的意志。在面对不可战胜的强敌时，全属性提升200%，且免疫精神控制。", type: "exclusive"},
                    {name: "颜面驾驶精通", color: "S", cost: 1800, desc: "你是天生的机师。驾驶任何名为''颜面''的机甲时，同步率瞬间达到100%，能发挥出机体极限以上的性能。", type: "exclusive"},
                    {name: "卡米那的墨镜", color: "B", cost: 500, desc: "一副橙色的三角形墨镜。佩戴时，你的领袖气质大幅提升，说出的中二台词会让人热血沸腾。", type: "exclusive"},
                    {name: "优子的狙击术", color: "A", cost: 1200, desc: "超远距离精准打击能力。即使在高速移动的战场上，你也能一枪击中敌人的弱点。", type: "exclusive"},
                    {name: "鼹鼠猪排", color: "C", cost: 50, desc: "基哈村的特产美食。虽然味道一般，但能有效恢复体力，是地下居民的主要蛋白质来源。", type: "exclusive"},
                    {name: "合体(Gattai)", color: "S", cost: 2000, desc: "你可以强行与其他机甲或物体进行合体，夺取其控制权或增强自身机体，虽然过程完全不讲道理。", type: "exclusive"},
                    {name: "螺旋王基因(残)", color: "A", cost: 1500, desc: "你拥有一丝螺旋王的血统，身体素质远超常人，徒手拆机甲不是梦，但容易被反螺旋族侦测到。", type: "exclusive"},
                    {name: "兽人身体", color: "B", cost: 400, desc: "你转生为兽人，拥有强健的体魄和夜视能力，但无法产生螺旋力，且白天容易犯困。", type: "exclusive"},
                    {name: "利龙的黑科技", color: "A", cost: 900, desc: "你掌握了利龙的技术，能用废铜烂铁修理和改造任何高科技设备，甚至给机甲加装不必要的装饰。", type: "exclusive"},
                    {name: "裸眼立体视觉", color: "C", cost: 100, desc: "即使没有雷达，你也能凭肉眼判断出敌人的距离和方位，适合在干扰严重的战场生存。", type: "exclusive"},
                    {name: "反螺旋族的诅咒", color: "E", cost: 10, desc: "你被反螺旋族标记。当你试图进化或变强时，会遭遇莫名的厄运和精神攻击。", type: "exclusive"},
                    {name: "亿万倍增幅", color: "SS", cost: 9000, desc: "在极度愤怒或决意下，你的攻击可以瞬间分裂或巨大化，造成范围性的毁灭打击。", type: "exclusive"},
                    {name: "钻头亲和", color: "C", cost: 150, desc: "你使用钻头类武器时伤害提升，且钻头不会卡在敌人体内。", type: "exclusive"},
                    {name: "相信我", color: "B", cost: 300, desc: "当你对同伴说''相信那个相信你的我''时，同伴的士气和战斗力会短暂提升。", type: "exclusive"}
                ]
            },
            {
                name: "52.攻壳机动队",
                desc: "高度发达的赛博朋克社会。人类通过义体化和电子脑延展肉体与意识，但灵魂（Ghost）的定义却变得模糊。黑客与恐怖主义并存。",
                boss: "傀儡师, 笑脸男, 久世英雄",
                identities: [
                    { name: "新滨市的底层骇客", items: "一台改装过的便携式终端, 几根非法的数据连接线" },
                    { name: "公安九课的后勤人员", items: "一张九课的临时通行证, 一把备用的马特巴左轮手枪" },
                    { name: "义体维修店的学徒", items: "一套精密的义体维修工具, 满手的合成机油" },
                    { name: "来自难民区的孤儿", items: "一件破旧的防雨斗篷, 一块捡来的电子脑芯片" },
                    { name: "大型企业的安保义体人", items: "一身量产型的轻型义体, 一根电击警棍" }
                ],
                talents: [
                    {name: "幽灵(Ghost)", color: "SSS", cost: 45000, desc: "在这个义体化的世界中，你拥有极其强大且独特的灵魂。即使肉体毁灭，你的意识也能在网络中永生，甚至同化他人。", type: "exclusive"},
                    {name: "全身义体化(军用级)", color: "SS", cost: 6000, desc: "除了大脑和脊髓，你的全身都是最顶尖的军用义体。拥有怪力、超高机动性和极强的抗击打能力。", type: "exclusive"},
                    {name: "超威黑客", color: "S", cost: 2500, desc: "你的黑客技术处于世界顶端。攻破防火墙像呼吸一样简单，甚至能在战斗中实时骇入敌人的视觉系统。", type: "exclusive"},
                    {name: "热光学迷彩", color: "A", cost: 1200, desc: "利用光线扭曲技术，你可以实现完美的隐身。不仅视觉不可见，还能屏蔽热成像扫描。", type: "exclusive"},
                    {name: "电子脑硬化症(潜伏)", color: "D", cost: 50, desc: "你的电子脑患有绝症。虽然目前没有症状，但随时可能导致意识封闭或死亡，需要昂贵的药物维持。", type: "exclusive"},
                    {name: "塔奇克马AI", color: "S", cost: 2200, desc: "你拥有一个拥有自我意识的思考战车AI作为伙伴。它忠诚、话唠，且能提供强大的火力支援。", type: "exclusive"},
                    {name: "电子脑", color: "C", cost: 200, desc: "基础的电子脑改造。你可以直接连接网络，进行脑内通讯，但也有被骇入的风险。", type: "exclusive"},
                    {name: "义体排斥反应", color: "E", cost: 20, desc: "你的身体对义体有严重的排斥反应，无法进行高级义体改造，只能维持肉身或使用低级义肢。", type: "exclusive"},
                    {name: "巴特之眼", color: "B", cost: 600, desc: "植入了两颗义眼，拥有变焦、红外、夜视等多种功能，虽然看起来像瓶盖，但非常实用。", type: "exclusive"},
                    {name: "网络潜行者", color: "A", cost: 1000, desc: "你在网络空间如鱼得水，能追踪任何数据痕迹，且极难被反向追踪。", type: "exclusive"},
                    {name: "公安九课特训", color: "A", cost: 1500, desc: "你接受过荒卷大辅的战术指导，精通城市反恐、情报分析和团队协作。", type: "exclusive"},
                    {name: "强化外骨骼", color: "B", cost: 800, desc: "如果你不想完全义体化，这套外骨骼能为你提供不输给义体人的力量和防护。", type: "exclusive"},
                    {name: "替身傀儡", color: "B", cost: 500, desc: "你可以同时控制一具远程义体进行行动，就像控制自己的身体一样，适合侦查和诱敌。", type: "exclusive"},
                    {name: "防壁突破", color: "C", cost: 300, desc: "针对民用级防火墙的特化程序，能快速获取一般的加密情报。", type: "exclusive"},
                    {name: "记忆操作", color: "SS", cost: 7500, desc: "极其危险的技术。你可以篡改、删除甚至伪造他人的记忆，将其变成你的傀儡。", type: "exclusive"}
                ]
            },
            {
                name: "53.心理测量者 (Psycho-Pass)",
                desc: "在西比拉系统的管理下，人类的心理状态和性格倾向被数值化。犯罪系数超过规定值的人会被裁决。这是一个看似完美的乌托邦。",
                boss: "槙岛圣护, 鹿矛围桐斗, 西比拉系统",
                identities: [
                    { name: "公安局刑事课的新人监视官", items: "一把支配者(Dominator), 一个全息投影装置" },
                    { name: "被关押的潜在犯", items: "一套拘束服, 狭窄的隔离单间" },
                    { name: "街头全息图设计师", items: "一套便携式全息投影仪, 各种奇怪的服装数据" },
                    { name: "废弃区划的流浪者", items: "一把生锈的铁管, 一罐过期的合成食品" },
                    { name: "厚生省的无人机操作员", items: "一个操作手柄, 满屏幕的监控画面" }
                ],
                talents: [
                    {name: "免罪体质", color: "SSS", cost: 40000, desc: "你的色相永远纯白。无论你犯下何种罪行，西比拉系统都无法裁定你的犯罪系数。你是系统的盲点，也是它的天敌。", type: "exclusive"},
                    {name: "支配者(Dominator)", color: "S", cost: 3000, desc: "只有监视官和执行官才能使用的特殊武器。连接西比拉系统，根据目标的犯罪系数自动切换模式（麻醉/致死/分解）。", type: "exclusive"},
                    {name: "色相清澈", color: "A", cost: 1000, desc: "你的心理素质极佳，即使目睹惨案，色相也极难浑浊。这让你在社会中畅通无阻，但也可能被视为冷血。", type: "exclusive"},
                    {name: "犯罪心理侧写", color: "A", cost: 1200, desc: "你能通过现场痕迹完美还原罪犯的心理活动和行动路径。但这会导致你的犯罪系数暂时上升。", type: "exclusive"},
                    {name: "格斗术(希拉特)", color: "B", cost: 600, desc: "狡啮慎也擅长的格斗术，注重实战和杀伤力，是对付暴走义体和罪犯的利器。", type: "exclusive"},
                    {name: "全息伪装", color: "C", cost: 200, desc: "你精通全息技术，可以瞬间改变自己的外貌和衣着，甚至覆盖周围环境来迷惑敌人。", type: "exclusive"},
                    {name: "黑市渠道", color: "B", cost: 500, desc: "你能在废弃区划搞到任何违禁品，包括旧时代武器和未被系统监控的通讯设备。", type: "exclusive"},
                    {name: "潜在犯标记", color: "D", cost: 50, desc: "你的犯罪系数常年高于100。虽然你没犯罪，但会被限制自由，且随时可能被支配者处决。", type: "exclusive"},
                    {name: "系统后门", color: "SS", cost: 8500, desc: "你掌握了西比拉系统的一处后门，可以短时间干扰色相扫描或修改监控记录。", type: "exclusive"},
                    {name: "无人机黑客", color: "B", cost: 700, desc: "你可以骇入并控制城市中的巡逻无人机和工程机器人，将其作为你的眼线或武器。", type: "exclusive"},
                    {name: "艺术鉴赏", color: "C", cost: 100, desc: "你对旧时代的文学和艺术有深刻理解。这能帮助你理解那些高智商罪犯的动机。", type: "exclusive"},
                    {name: "头盔男", color: "A", cost: 1500, desc: "你拥有能复制周围人色相的头盔，戴上它，你就可以在扫描仪下隐身，但这容易引发暴乱。", type: "exclusive"},
                    {name: "执行官直觉", color: "B", cost: 800, desc: "作为猎犬的直觉。你能敏锐地察觉到危险和杀意，反应速度快于常人。", type: "exclusive"},
                    {name: "精神药物依赖", color: "D", cost: 30, desc: "你需要定期服用精神药物来维持色相。一旦断药，你的犯罪系数会飙升。", type: "exclusive"},
                    {name: "全知全能的悖论", color: "SS", cost: 7000, desc: "你知道西比拉系统的真相。这让你对世界感到绝望，但也让你拥有了对抗系统的知识。", type: "exclusive"}
                ]
            },
            {
                name: "54.牛仔星际 (Cowboy Bebop)",
                desc: "2071年，人类以太阳系为舞台。赏金猎人（Cowboy）驾驶飞船穿梭于星际间追捕罪犯。伴随着爵士乐，这是一个充满浪漫与忧伤的世界。",
                boss: "比夏斯, 文森特·瓦拉朱, 疯狂皮埃尔",
                identities: [
                    { name: "Bebop号上的临时工", items: "一包青椒肉丝(没有肉), 一把拖把" },
                    { name: "红龙帮的底层打手", items: "一把黑色西装, 一把自动手枪" },
                    { name: "ISSP的腐败警察", items: "一枚警徽, 一叠收受的贿赂金" },
                    { name: "星际卡车司机", items: "一辆重型卡车, 一堆重金属摇滚磁带" },
                    { name: "火星贫民窟的居民", items: "一件破烂的夹克, 一把自制的弹簧刀" }
                ],
                talents: [
                    {name: "截拳道宗师", color: "S", cost: 2800, desc: "像水一样流动。你精通斯派克的格斗术，动作行云流水，能利用环境和对手的力量击败强敌。", type: "exclusive"},
                    {name: "剑鱼II号", color: "SS", cost: 7500, desc: "一艘改装过的高速战机。拥有极高的机动性和火力，是星际空战中的红色闪电。", type: "exclusive"},
                    {name: "数据狗智商", color: "S", cost: 3000, desc: "你拥有艾因那样的超高智商。虽然不会说话，但你的计算能力和逻辑思维堪比超级计算机。", type: "exclusive"},
                    {name: "义眼(过去之眼)", color: "A", cost: 1500, desc: "你的一只眼睛是义眼。你能看到过去发生的事情，或者说，你永远活在过去和现在的交界处。", type: "exclusive"},
                    {name: "爵士魂", color: "SSS", cost: 12000, desc: "无论处境多么危险，你总能保持优雅和节奏感。这种玄学的气场能让你在枪林弹雨中毫发无伤。", type: "exclusive"},
                    {name: "机械臂(杰特)", color: "B", cost: 800, desc: "拥有一条强力的机械义肢，力量惊人，且内置了一些实用的小工具。", type: "exclusive"},
                    {name: "菲的债务", color: "E", cost: 100, desc: "你背负着天文数字的债务。无论你赚多少钱，债主总能找到你，让你永远穷困潦倒。", type: "exclusive"},
                    {name: "红眼(Red Eye)", color: "D", cost: 200, desc: "一种能短时间大幅提升反应速度的毒品。使用后你会战无不胜，但副作用极大，且极易成瘾。", type: "exclusive"},
                    {name: "黑客天才(艾德流)", color: "A", cost: 1800, desc: "你用脚打字都比别人快。只要有网络接口，就没有你进不去的地方，风格古怪但极其高效。", type: "exclusive"},
                    {name: "星际驾驶技术", color: "B", cost: 600, desc: "你熟练驾驶各种民用和军用飞船，即使在相位差空间门中也能平稳飞行。", type: "exclusive"},
                    {name: "赏金猎人执照", color: "C", cost: 150, desc: "合法的捕猎许可。你可以通过抓捕通缉犯换取赏金，还能在警察面前有些面子。", type: "exclusive"},
                    {name: "巴西战舞", color: "B", cost: 500, desc: "一种像舞蹈一样的格斗术，动作华丽且难以预测，非常适合在狭窄空间战斗。", type: "exclusive"},
                    {name: "老式手枪", color: "C", cost: 200, desc: "一把杰里科941或其他经典型号。虽然旧，但保养得很好，是你最值得信赖的伙伴。", type: "exclusive"},
                    {name: "风水大师", color: "C", cost: 100, desc: "你懂得看风水。虽然在太空时代听起来很扯，但有时候真的能帮你避开厄运。", type: "exclusive"},
                    {name: "泰坦战争老兵", color: "A", cost: 1000, desc: "你经历过残酷的泰坦战争。拥有丰富的战场经验和创伤后应激障碍(PTSD)。", type: "exclusive"}
                ]
            },
            {
                name: "55.超时空要塞 (Macross)",
                desc: "歌声、变形战机与三角恋。人类与巨大的外星种族杰特拉帝人接触，展开了星际流浪。文化的力量可以停止战争。",
                boss: "伯多基帝, 格蕾丝·奥康纳, 格佩尼奇",
                identities: [
                    { name: "统合军骷髅小队飞行员", items: "一架VF-1女武神(量产型), 一个飞行头盔" },
                    { name: "中华料理店''娘娘''的打工仔", items: "一套外卖制服, 一辆会飞的外卖摩托" },
                    { name: "杰特拉帝叛逃士兵", items: "一套微缩化后的旧军服, 一张林明美的海报" },
                    { name: "Macross舰桥通讯员", items: "一个通讯耳麦, 一杯永远喝不完的咖啡" },
                    { name: "民间军事公司SMS的新人", items: "一张SMS入职通知书, 一枚象征契约的硬币" }
                ],
                talents: [
                    {name: "银河歌姬的歌声", color: "SSS", cost: 50000, desc: "你的歌声拥有撼动灵魂的力量。能平息暴躁的外星人，干扰敌方通讯，甚至引发Fold波奇迹。你是宇宙的中心。", type: "exclusive"},
                    {name: "可变战机王牌", color: "S", cost: 3000, desc: "你精通VF系列战机的三段变形操作（战斗机/守护者/机器人）。能在在导弹雨中跳舞（板野马戏团）。", type: "exclusive"},
                    {name: "Fold波共鸣", color: "SS", cost: 9000, desc: "你天生能感知Fold波。这让你能与Vajra等外星生物沟通，或者在超时空跳跃中保持清醒。", type: "exclusive"},
                    {name: "杰特拉帝血统", color: "A", cost: 1500, desc: "你拥有巨人的血统。即使微缩化后，身体素质也远超常人。如果恢复原形，你将拥有毁灭性的破坏力。", type: "exclusive"},
                    {name: "微型导弹全弹发射", color: "A", cost: 2000, desc: "你擅长同时锁定数十个目标并释放导弹雨。那种满屏的尾烟是你给敌人最后的礼物。", type: "exclusive"},
                    {name: "文化冲击(Deculture)", color: "C", cost: 300, desc: "当你展示人类文化（如接吻、唱歌）时，能对未接触过文化的外星人造成巨大的精神冲击。", type: "exclusive"},
                    {name: "原始文明遗物", color: "SS", cost: 8000, desc: "你持有一件Protoculture的遗物。它蕴含着未知的科技和力量，可能引来全宇宙的觊觎。", type: "exclusive"},
                    {name: "三角恋主角", color: "B", cost: 1000, desc: "你总是陷入复杂的感情纠葛中。虽然很麻烦，但这能大幅提升你在关键时刻的爆发力。", type: "exclusive"},
                    {name: "声优天赋", color: "C", cost: 200, desc: "你的声音很有感染力，适合成为偶像或通讯员，能提升友军的士气。", type: "exclusive"},
                    {name: "机械整备天才", color: "B", cost: 600, desc: "你能迅速修理受损的女武神战机，甚至进行一些违规的魔改。", type: "exclusive"},
                    {name: "超时空跳跃适应", color: "C", cost: 150, desc: "你不会因为Fold跳跃而产生时差呆滞，能立刻投入战斗。", type: "exclusive"},
                    {name: "反应弹", color: "S", cost: 2500, desc: "你有权限使用这种大威力的反物质武器。一发足以摧毁一艘中型战舰，但数量极其有限。", type: "exclusive"},
                    {name: "菠萝沙拉", color: "E", cost: 10, desc: "当你提到''打完这仗我就回去吃菠萝沙拉''时，你的死亡率提升至99%。著名的死亡Flag。", type: "exclusive"},
                    {name: "Pinpoint Barrier", color: "A", cost: 1200, desc: "针点防御系统。你能熟练操作这种能量护盾，在被击中的瞬间集中防御，无伤挡下致命攻击。", type: "exclusive"},
                    {name: "银河妖精的耳环", color: "B", cost: 800, desc: "雪莉露·诺姆的耳环。佩戴者能获得Fold波增幅，且魅力值大幅上升。", type: "exclusive"}
                ]
            },
                      {
                name: "56.86 -不存在的战区-",
                desc: "圣马格诺利亚共和国的第86区，这里是被剥夺人权的“猪”驾驶着名为“破坏神”的棺材，与帝国无人机军团（Legion）进行必死战斗的地狱。种族歧视、战争与亡灵的低语。",
                boss: "电磁加速炮型(Morpho), 重战车型(Löwe), 瑟琳·比尔肯鲍姆(军团女皇)",
                identities: [
                    { name: "第86区的送葬者", items: "一把磨损的手枪(用于给队友介错), 一个刻有编号的铭牌" },
                    { name: "共和国的白系种指挥官", items: "知觉同步装置(RAID), 一杯昂贵的红茶" },
                    { name: "整备班的老练技师", items: "沾满机油的扳手, 一本写满遗言的旧笔记" },
                    { name: "帝国的亡国贵族", items: "破旧的家徽, 隐藏在废墟中的逃生地图" },
                    { name: "战场上的拾荒者", items: "一个用来装废铁的麻袋, 一把防身的匕首" }
                ],
                talents: [
                    {name: "亡灵之声(异能)", color: "S", cost: 1800, desc: "你能听到军团网络中死者的哀嚎。虽然这会让你san值狂掉，但你能借此精准定位所有敌人的位置，哪怕它们在视野之外。", type: "exclusive"},
                    {name: "知觉同步(Para-RAID)", color: "A", cost: 600, desc: "通过听觉共享意识的技术。你可以与队友进行无延迟的思维沟通，但若同步对象死去，你会感受到死亡瞬间的痛苦。", type: "exclusive"},
                    {name: "破坏神驾驶专精", color: "B", cost: 450, desc: "你熟悉M1A4破坏神的操作逻辑，能在高机动的战斗中保持平衡，把这台‘移动棺材’开出跑车的感觉。", type: "exclusive"},
                    {name: "白系种的傲慢", color: "C", cost: 100, desc: "身为纯血白系种，你在共和国境内拥有极高的社会地位和资源，但你会下意识轻视有色人种，容易拉仇恨。", type: "exclusive"},
                    {name: "军团核心植入", color: "SS", cost: 5500, desc: "你的大脑被替换或融合了军团的中央处理核心。你拥有指挥机械军团的权限，并且身体大部分机械化，几乎不老不死。", type: "exclusive"},
                    {name: "送葬者的枪法", color: "A", cost: 700, desc: "不仅仅是战斗，你更擅长在队友重伤濒死时，用最慈悲的一枪结束他们的痛苦。这种冷酷的精准度在战斗中同样致命。", type: "exclusive"},
                    {name: "异能：超加速", color: "S", cost: 1200, desc: "短时间内让你的神经反应速度提升十倍，世界在你眼中仿佛静止。是驾驶轻型机甲进行近身格斗的神技。", type: "exclusive"},
                    {name: "战地厨师(合成粮)", color: "C", cost: 50, desc: "你能把难吃的合成口粮做得稍微能入口一点，或者用战场上的废料提炼出可饮用的水。生存必备。", type: "exclusive"},
                    {name: "共和国防护壁权限", color: "B", cost: 300, desc: "你拥有共和国首都大门的通行密码和权限，可以在战局崩溃时躲进那个虚伪的伊甸园。", type: "exclusive"},
                    {name: "女武神的加护", color: "SS", cost: 3000, desc: "你被某种命运眷顾，在必死的战场上总能奇迹般生还，并且你的存在能大幅提升周围队友的士气和生存率。", type: "exclusive"},
                    {name: "电磁炮狙击", color: "A", cost: 900, desc: "你掌握了超远距离电磁炮的弹道计算能力，能在视距外对敌方高价值目标进行毁灭性打击。", type: "exclusive"},
                    {name: "黑色死神", color: "SSS", cost: 12000, desc: "你成为了战场上的传说，独自背负所有死去的战友。你的战斗力随着死去的队友数量而指数级上升，你是军团最恐惧的猎手。", type: "exclusive"},
                    {name: "流体纳米装甲", color: "S", cost: 1500, desc: "军团的尖端科技，银色的流体金属覆盖全身，能抵挡重机枪扫射并自动修复损伤，还能变形为利刃。", type: "exclusive"},
                    {name: "无脸者(No Face)", color: "SS", cost: 4000, desc: "你没有过去，没有名字。这种虚无让你免疫精神类攻击，并且在潜入敌后时极难被侦测发现。", type: "exclusive"},
                    {name: "最后的防线", color: "A", cost: 800, desc: "当你的生命值低于30%时，你的防御力和火力全开，进入‘背水一战’状态，持续战斗直到心脏停止。", type: "exclusive"}
                ]
            },
            {
                name: "57.罪恶王冠",
                desc: "被启示录病毒肆虐的日本，GHQ的统治下，人们生活在恐惧中。‘王之能力’可以将人心具象化为虚空（Void）武器。这是一个关于淘汰、进化与救赎的故事。",
