                    { name: "蓝色监狱保洁员", items: "一把拖把, 看着天才们的背影" },
                    { name: "被淘汰的高中生", items: "一张回家的车票, 破碎的梦想" },
                    { name: "Team Z的替补", items: "一件蓝色背心, 一瓶运动饮料" },
                    { name: "天才前锋的跟班", items: "帮老大拿的毛巾, 崇拜的目光" }
                ],
                talents: [
                    {name: "空间认知能力", color: "A", cost: 850, desc: "你拥有上帝视角，能瞬间洞察球场上所有人的位置和空档，是成为核心的大脑。", type: "exclusive"},
                    {name: "直击蹴弹(Direct Shot)", color: "A", cost: 800, desc: "无论球从哪里传来，你都能不调整直接射门。这是在狭小空间内进球的必杀技。", type: "exclusive"},
                    {name: "怪物残片(蜂乐)", color: "S", cost: 2500, desc: "你内心住着一个怪物，踢球风格自由奔放，盘带技巧无人能挡，能创造出意想不到的机会。", type: "exclusive"},
                    {name: "千切的极速", color: "A", cost: 900, desc: "你的瞬间爆发速度无人能及，一旦让你跑起来，没人能追得上你的背影。", type: "exclusive"},
                    {name: "肉体革命(国神)", color: "B", cost: 500, desc: "你拥有钢铁般的肌肉和强悍的左脚射门力量，是球场上的重型坦克。", type: "exclusive"},
                    {name: "Meta Vision (超越视界)", color: "SS", cost: 9000, desc: "你需要不断转头扫描全场，像高维生物一样预知未来几秒的局势，但极度消耗体力。", type: "exclusive"},
                    {name: "Flow (心流状态)", color: "S", cost: 3500, desc: "当你完全沉浸在挑战中时，会进入忘我境界，发挥出超越自身极限的水平。", type: "exclusive"},
                    {name: "马狼的“恶役”", color: "S", cost: 2800, desc: "你踢球极其独断专行，通过吞噬队友的光芒来进球，是球场上的暴君。", type: "exclusive"},
                    {name: "玲王的“复写”", color: "S", cost: 3000, desc: "全能型天才，只要看一眼，你就能以99%的精度模仿任何人的球技。", type: "exclusive"},
                    {name: "凪的“停球”", color: "SS", cost: 8000, desc: "你可以把任何高难度的传球停在最舒服的位置，化腐朽为神奇，创造生命。", type: "exclusive"},
                    {name: "Egoist (利己主义)", color: "SSS", cost: 30000, desc: "你拥有世界第一前锋的绝对自我。为了进球，你可以牺牲一切。你是球场上唯一的主角。", type: "exclusive"},
                    {name: "运气(Luck)", color: "A", cost: 700, desc: "运气也是实力的一部分。你总能在球弹出的瞬间出现在最致命的位置。", type: "exclusive"},
                    {name: "诺亚的“双脚怪”", color: "SS", cost: 9500, desc: "你的左右脚均衡度完美，无论用哪只脚射门，精度和力度都毫无差别。", type: "exclusive"},
                    {name: "猎食者之眼", color: "S", cost: 3200, desc: "专门针对守门员的技能。你能捕捉守门员重心偏移的瞬间，射出必进之球。", type: "exclusive"},
                    {name: "平庸的前锋", color: "E", cost: 20, desc: "你的各项指标都很平均，没有特长。在蓝色监狱，平庸就是原罪，等着被淘汰吧。", type: "exclusive"}
                ]
            },
              {
        name: "101.大圣归来",
        desc: "五行山下沉寂五百年，传说中的齐天大圣已成过往。山妖横行，童男童女失踪，一个名为江流儿的小和尚无意间揭开了封印的一角。这是一个关于信仰、救赎与找回初心的神话世界。",
        boss: "混沌(妖王), 巨灵神, 齐天大圣(解封前)",
        identities: [
            { name: "长安城流浪孤儿", items: "一个破损的皮影戏偶, 半个发霉的馒头" },
            { name: "山妖洞穴的储备粮", items: "一根用来剔牙的骨头, 破烂的麻布衣" },
            { name: "五行山下的采药人", items: "一把生锈的药锄, 一筐枯萎的杂草" },
            { name: "不知名寺庙的小沙弥", items: "一串断了线的木佛珠, 漏风的僧鞋" },
            { name: "被山妖追赶的村民", items: "一只跑丢的草鞋, 满身的泥泞" }
        ],
        talents: [
            {name: "法印压制(诅咒)", color: "E", cost: 50, desc: "你身上带有类似如来的封印，无法使用任何法力，且身体素质比常人更弱，稍微剧烈运动就会手腕剧痛。", type: "exclusive"},
            {name: "山妖嗅觉", color: "C", cost: 120, desc: "长期在山林躲避妖魔，你练就了比狗还灵的鼻子，能闻到一公里内妖气的味道，方便提前跑路。", type: "exclusive"},
            {name: "皮影戏手艺", color: "C", cost: 100, desc: "你拥有一双巧手，能制作栩栩如生的皮影，虽然不能战斗，但在哄骗小孩或特定剧情中或许有奇效。", type: "exclusive"},
            {name: "江流儿的唠叨", color: "D", cost: 80, desc: "你拥有唐僧般的碎碎念能力，能通过不间断的废话让敌人心烦意乱，但大概率会先激怒你的队友。", type: "exclusive"},
            {name: "石猴血脉(稀薄)", color: "B", cost: 500, desc: "你体内有一丝丝灵明石猴的血脉，身体硬度是常人的两倍，普通的刀剑砍在你身上只会留下白印。", type: "exclusive"},
            {name: "土地公的指引", color: "B", cost: 450, desc: "当你迷路时，总会有矮小的土地公钻出来为你指路。虽然他战斗力为零，但他是活地图，知晓哪里有仙桃。", type: "exclusive"},
            {name: "七十二变(残缺)", color: "A", cost: 1200, desc: "你学会了变化的皮毛，可以变成石头、树木等静物，持续十分钟。虽然不能变成苍蝇侦查，但躲避追杀足够了。", type: "exclusive"},
            {name: "筋斗云(伪)", color: "A", cost: 1500, desc: "你无法一个跟头十万八千里，但可以召唤一朵离地三米高的小云彩，以每小时80公里的速度飞行，且非常耗蓝。", type: "exclusive"},
            {name: "定海神针(仿品)", color: "S", cost: 2800, desc: "东海龙宫的量产货，重一千三百五十斤。虽然比不上正版，但也是削铁如泥的神兵，且能随心意变大变小。", type: "exclusive"},
            {name: "火眼金睛(初阶)", color: "S", cost: 3200, desc: "看破一切虚妄与伪装。妖魔鬼怪在你眼中无所遁形，还能发射微弱的金光灼烧敌人视网膜。", type: "exclusive"},
            {name: "法天象地(入门)", color: "SS", cost: 6000, desc: "上古大神通。你可以暂时将身躯巨大化至十米高，力量与防御翻倍，但结束后会虚脱三天三夜。", type: "exclusive"},
            {name: "救命毫毛", color: "SS", cost: 8500, desc: "观音大士赐予的保命底牌。拥有三次绝对防御或绝境逃生的机会，无论多强的攻击都能抵挡一次。", type: "exclusive"},
            {name: "熔岩铠甲", color: "SS", cost: 7500, desc: "从虚空中召唤大圣归来时的熔岩战甲，自带高温灼烧光环，防御力极强，且极其帅气，能大幅提升威慑力。", type: "exclusive"},
            {name: "混沌之噬", color: "SSS", cost: 12000, desc: "妖王混沌的本源力量。你可以张开巨口吞噬万物，将敌人的血肉化为自己的妖力，甚至能吞噬空间。", type: "exclusive"},
            {name: "大圣归来(解封)", color: "SSS", cost: 30000, desc: "挣脱一切束缚！你的力量、速度、法力瞬间恢复至巅峰齐天大圣状态。哪怕是如来佛祖，也别想再压你五百年！", type: "exclusive"}
        ]
    },
    {
        name: "102.魔道祖师",
        desc: "仙门百家，正邪两立。这是一个修仙与鬼道并存的世界。五大世家统治修真界，而乱葬岗的怨气正在积聚。你要面对的不仅是凶尸恶鬼，更是人心难测。",
        boss: "温若寒, 金光瑶, 聂明玦(凶尸)",
        identities: [
            { name: "乱葬岗的走尸候补", items: "一身腐烂的寿衣, 一张被风吹走的镇尸符" },
            { name: "莫家庄的受气仆人", items: "一把扫帚, 一个画着歪扭招阴旗的破布" },
            { name: "云深不知处的犯禁杂役", items: "一本抄写了一半的家规, 一瓶偷来的天子笑空坛" },
            { name: "被温家抓壮丁的平民", items: "一把生锈的铁镐, 脚镣一副" },
            { name: "夷陵街头的疯乞丐", items: "一个破碗, 几根发黑的萝卜" }
        ],
        talents: [
            {name: "恶诅痕(必死)", color: "E", cost: 10, desc: "你身上被种下了恶毒的诅咒，吸引方圆百里的邪祟。除非找到大能解咒，否则你活不过今晚子时。", type: "exclusive"},
            {name: "献舍禁术(残)", color: "D", cost: 200, desc: "你懂得献舍的皮毛，可以燃烧生命力短时间提升力量，但代价是灵魂受损，大概率变成痴呆。", type: "exclusive"},
            {name: "姑苏一杯倒", color: "C", cost: 50, desc: "你的酒量极差，沾酒即醉，但醉酒后你的胆量会无限放大，敢于调戏世家宗主或暴打恶犬。", type: "exclusive"},
            {name: "问灵术(入门)", color: "C", cost: 180, desc: "姑苏蓝氏的秘技。你可以用古琴与亡魂进行简单的“是/否”对话，获取一些模糊的情报。", type: "exclusive"},
            {name: "金丹(平庸)", color: "B", cost: 600, desc: "你拥有一颗普通的金丹，可以御剑飞行，使用基础的符咒。虽然成不了宗师，但在凡人眼中已是仙师。", type: "exclusive"},
            {name: "清心音", color: "B", cost: 550, desc: "你掌握了蓝氏的清心音，吹奏笛子或弹琴可以驱散走尸的凶性，平复队友的走火入魔，辅助神技。", type: "exclusive"},
            {name: "紫电(仿)", color: "A", cost: 1300, desc: "能够化为长鞭的指环，附带强烈的雷电攻击。具有识别夺舍的能力，抽在被夺舍者身上会将其灵魂打出。", type: "exclusive"},
            {name: "云梦江氏剑法", color: "A", cost: 900, desc: "游侠般的剑术，身法灵动轻盈，讲究快准狠。在水边战斗时，你的速度和闪避率提升30%。", type: "exclusive"},
            {name: "温家火阵", color: "S", cost: 2500, desc: "岐山温氏的霸道阵法。你可以召唤烈火焚烧敌人，或者将活人炼化为听命于你的傀儡凶尸。", type: "exclusive"},
            {name: "诡道宗师资质", color: "S", cost: 3500, desc: "你天生适合修习鬼道。无需金丹，便可驾驭怨气。你能将任何死物化为战力，但心性容易受损。", type: "exclusive"},
            {name: "阴虎符(半块)", color: "SS", cost: 8000, desc: "至阴至邪的法宝残片。拥有号令万鬼的能力，一旦祭出，百里内的凶尸皆听你号令，但会遭到全天下追杀。", type: "exclusive"},
            {name: "乱葬岗之主", color: "SS", cost: 7000, desc: "你在充满怨气的地方战斗力翻倍。怨气越重，你的恢复力和攻击力越强，甚至能利用怨气重塑肉身。", type: "exclusive"},
            {name: "朔月与避尘", color: "SS", cost: 6500, desc: "获得蓝氏双璧的剑意传承。你的剑气如冰霜般寒冷，又如明月般皎洁，能斩断世间一切邪祟与执念。", type: "exclusive"},
            {name: "夺舍重生(完美)", color: "SSS", cost: 15000, desc: "并非邪术，而是近乎法则的重生。死亡后，你可以选择任意一具刚死的躯体完美复活，保留所有记忆与能力，且无排斥反应。", type: "exclusive"},
            {name: "陈情一曲", color: "SSS", cost: 20000, desc: "鬼笛陈情，万鬼听令。你的一曲笛音能让天地变色，唤醒沉睡千年的古尸，甚至能逆转阴阳，操纵生死。", type: "exclusive"}
        ]
    },
    {
        name: "103.天官赐福",
        desc: "天界、人界、鬼界。神官们高高在上，鬼王们祸乱一方。这是一个关于飞升与堕落，信仰与执念的故事。太子殿下第三次飞升，而绝境鬼王正在暗中注视。",
        boss: "白无相(白衣祸世), 戚容, 君吾",
        identities: [
            { name: "半月关的饿死鬼", items: "一具干枯的尸体(你自己), 破烂的军服" },
            { name: "皇城脚下的收破烂", items: "一个背篓, 几个空瓶子" },
            { name: "与君山的丑新娘", items: "一件染血的嫁衣, 盖头下的骷髅头" },
            { name: "鬼市的小摊贩", items: "一碗不可名状的鬼汤, 几枚冥币" },
            { name: "仙乐国的遗民", items: "一块生锈的面具碎片, 对太子的诅咒" }
        ],
        talents: [
            {name: "散尽功德(诅咒)", color: "E", cost: 20, desc: "你是个倒霉蛋，无论做什么好事都不会有回报，喝凉水都塞牙。你的运气值为负无穷，走路必踩坑。", type: "exclusive"},
            {name: "若邪绫(破布)", color: "D", cost: 150, desc: "一条有自我意识的白绫，但目前它只想上吊。战斗时它可能会缠住敌人，也可能缠住你的脖子。", type: "exclusive"},
            {name: "通灵阵接入权", color: "C", cost: 100, desc: "你获得了接入上天庭通灵阵的密码。虽然不能发言，但你可以偷听神官们的八卦，获取重要情报。", type: "exclusive"},
            {name: "谢怜的厨艺", color: "C", cost: 50, desc: "你能做出名为‘万紫千红小炒肉’的生化武器。虽然难吃至极，但能对敌人造成巨大的精神和肉体双重打击。", type: "exclusive"},
            {name: "风师扇(仿)", color: "B", cost: 700, desc: "一把能召唤狂风的扇子。虽然威力不及原版，但足以吹飞普通的小鬼，夏天还能用来解暑。", type: "exclusive"},
            {name: "地师铲", color: "B", cost: 650, desc: "明仪的神器复刻版。拥有极强的挖掘能力，能瞬间挖通地道潜入任何结界，是潜行偷袭的神器。", type: "exclusive"},
            {name: "死灵蝶(幼体)", color: "A", cost: 1100, desc: "几只闪烁着银光的蝴蝶。它们能为你侦查环境，传递信息，甚至由于带有尸毒，能对敌人造成微弱伤害。", type: "exclusive"},
            {name: "武神之躯", color: "A", cost: 1500, desc: "你天生神力，武艺超群。精通十八般兵器，近战能力极强，是成为武神的好苗子。", type: "exclusive"},
            {name: "厄命弯刀(投影)", color: "S", cost: 3000, desc: "花城弯刀的投影。虽然只有一只眼睛，但极其护主。攻击时带有极强的煞气，能斩断法宝。", type: "exclusive"},
            {name: "咒枷(封印解除)", color: "S", cost: 2800, desc: "你脖子上的咒枷不仅没有限制法力，反而成为了储存法力的容器。爆发时，可释放出毁天灭地的灵力。", type: "exclusive"},
            {name: "绝境鬼王体质", color: "SS", cost: 8000, desc: "你已在铜炉山蛊城中厮杀而出。只要骨灰不灭，你便不死不灭。拥有极强的再生能力和统御百鬼的威压。", type: "exclusive"},
            {name: "人面疫(抗体)", color: "SS", cost: 6000, desc: "你曾感染过人面疫并存活下来。你对所有瘟疫和诅咒免疫，并且能将自身的血液化为剧毒攻击敌人。", type: "exclusive"},
            {name: "芳心国师剑法", color: "SS", cost: 7500, desc: "一剑定乾坤。这套剑法招招致命，没有任何花哨，专为杀戮而生。对阵法和结界有极强的破坏力。", type: "exclusive"},
            {name: "身在无间，心在桃源", color: "SSS", cost: 25000, desc: "无论身处何种绝境，你的心境永远不会崩塌。免疫一切精神攻击、幻术和心魔。你的信仰之力能直接转化为神力。", type: "exclusive"},
            {name: "天官赐福，百无禁忌", color: "SSS", cost: 35000, desc: "言出法随的顶级神力。你的一句话可以改变因果，让不可能变为可能。运气值锁定为MAX，天道都在帮你。", type: "exclusive"}
        ]
    },
    {
        name: "104.全职高手(动画版)",
        desc: "荣耀，不仅仅是个游戏。这是一个电子竞技成为主流的世界。叶修被驱逐，带着千机伞在第十区重头再来。你的战场是键盘鼠标，也是人心。",
        boss: "韩文清, 王杰希, 喻文州, 游戏系统(难度)",
        identities: [
            { name: "兴欣网吧的保洁员", items: "一把拖把, 一张C区47号的上网卡" },
            { name: "第十区的菜鸟玩家", items: "新手剑, 5个小血瓶" },
            { name: "嘉世俱乐部的看门大爷", items: "一个收音机, 一串钥匙" },
            { name: "神之领域的拾荒者", items: "一个负重极大的背包, 一双跑得快的鞋子" },
            { name: "工作室的代练苦力", items: "一台配置极低的电脑, 一桶泡面" }
        ],
        talents: [
            {name: "手残(晚期)", color: "E", cost: 5, desc: "你的APM只有30，放个技能都要找半天键位。在这个拼手速的世界，你注定只能当个风景党。", type: "exclusive"},
            {name: "网瘾少年", color: "C", cost: 80, desc: "你可以连续三天三夜不睡觉打游戏，精神依然亢奋。在虚拟世界中，你的学习能力提升20%。", type: "exclusive"},
            {name: "垃圾话精通", color: "C", cost: 120, desc: "师从黄少天。你能在战斗中通过文字泡和语音不断干扰对手心态，使其愤怒值上升，判断力下降。", type: "exclusive"},
            {name: "战术素养(入门)", color: "B", cost: 400, desc: "你读过几本兵书，懂得基础的包抄、埋伏和集火。在团队战中，能让队友的配合度稍微提升。", type: "exclusive"},
            {name: "APM 200+", color: "B", cost: 600, desc: "职业选手的门槛手速。你的手指灵活度远超常人，能完成大部分高难度操作，技能衔接流畅。", type: "exclusive"},
            {name: "银武制作天赋", color: "A", cost: 1500, desc: "你对装备编辑器有独特的理解。只要有材料，你就能设计出属性超越橙装的自制银武，虽然成功率不是100%。", type: "exclusive"},
            {name: "遮影步", color: "A", cost: 1200, desc: "高端走位技巧。你能始终保持在对手的视野盲区内进行攻击，让对方有力无处使，只能被动挨打。", type: "exclusive"},
            {name: "龙抬头", color: "S", cost: 2200, desc: "战斗法师的绝技。在伏龙翔天技能释放后，能强行改变龙头的方向，精准命中逃跑的敌人，是逆转局势的神技。", type: "exclusive"},
            {name: "魔术师打法", color: "S", cost: 2800, desc: "王杰希的成名绝技。你的攻击轨迹诡异莫测，完全不按常理出牌，让对手根本无法预测你的下一步行动。", type: "exclusive"},
            {name: "喻文州的预判", color: "S", cost: 2500, desc: "虽然手速不快，但你的意识是顶级的。你能预判对手未来三秒的所有操作，并提前布下陷阱。", type: "exclusive"},
            {name: "千机伞(全形态)", color: "SS", cost: 9000, desc: "荣耀史上最复杂的银武。拥有剑、枪、矛、盾等12种形态，可随时切换。配合散人玩法，能打出无限连击。", type: "exclusive"},
            {name: "斗神意志", color: "SS", cost: 7500, desc: "越战越勇。随着连击数的增加，你的攻击力、攻击速度和移动速度会呈指数级上升，直到无人能挡。", type: "exclusive"},
            {name: "散人全修", color: "SSS", cost: 18000, desc: "你精通荣耀全职业所有低阶技能。没有冷却空窗期，没有技能死角。你一个人就是一支军队。", type: "exclusive"},
            {name: "荣耀教科书", color: "SSS", cost: 25000, desc: "你拥有叶修级别的全知全能。对所有职业、地图、BOSS机制了如指掌。任何战术在你面前都是透明的，你是不可战胜的神。", type: "exclusive"},
            {name: "系统GM权限(伪)", color: "SSS", cost: 50000, desc: "你不仅是玩家，更是数据的操控者。你可以看到隐藏的判定数据，甚至微调爆率和刷新时间，真正的降维打击。", type: "exclusive"}
        ]
    },
    {
        name: "105.尸兄",
        desc: "两个盗墓贼偷来的千年棺木滑进了 H 市的水库，喝过自来水的人全变成了会吞噬同类、不断进化的「尸兄」。丧尸会思考、会用武器、会合体、会耍阴谋；人类靠药剂、内力与十二生肖机器人硬撑。恐怖打底、搞笑破题、热血收尾——从 H 市到京城再到地狱之门。",
        boss: "尸王龙右(不死髅体·天罡气九重), 血莲教主, 六翼圣主, 撒旦(地狱之门), 神皇徐福",
        identities: [
            { name: "H市送水工", items: "一桶被污染的纯净水, 破旧的三轮车" },
            { name: "阳光幼儿园小朋友", items: "一个被咬坏的皮球, 一根棒棒糖" },
            { name: "躲在厕所的宅男", items: "一部没电的手机, 一卷卫生纸" },
            { name: "被感染的保安", items: "一根警棍, 正在变异的左手" },
            { name: "撤离失败的游客", items: "一个坏掉的行李箱, 一张失效的车票" }
        ],
        talents: [
            {name: "病毒携带者(潜伏)", color: "E", cost: 30, desc: "你体内已经有了病毒，虽然还没变异，但随时可能爆发。你的体温偏高，容易吸引其他尸兄的注意。", type: "exclusive"},
            {name: "KW药剂(过期)", color: "D", cost: 180, desc: "你注射了一支过期的强化药剂，力量提升了，但副作用是智商下降，且偶尔会不受控制地跳广场舞。", type: "exclusive"},
            {name: "超市大抢购", color: "C", cost: 80, desc: "你在混乱中练就了极快的搜刮速度。能迅速找到食物和水，并能熟练使用购物车作为冲撞武器。", type: "exclusive"},
            {name: "吐槽能量", color: "C", cost: 60, desc: "白小飞的特质。你在极度恐惧时会疯狂吐槽，这能稍微缓解你的精神压力，并让周围的画风变得奇怪。", type: "exclusive"},
            {name: "钛合金狗眼", color: "B", cost: 500, desc: "你的动态视力极强，能看清尸兄的攻击动作。附带夜视功能，在停电的H市非常实用。", type: "exclusive"},
            {name: "初级武术", color: "B", cost: 450, desc: "你学过几年军体拳或太极。虽然打不过高级尸兄，但对付普通的小丧尸绰绰有余，身手比常人敏捷。", type: "exclusive"},
            {name: "次声波控制", color: "A", cost: 1200, desc: "你能发出特定频率的次声波，干扰低级尸兄的行动，甚至能短暂控制它们为你开路。", type: "exclusive"},
            {name: "杀势", color: "A", cost: 1500, desc: "经历无数杀戮后凝聚的气场。释放杀势可以震慑弱小的敌人，使其动弹不得，也能增强自身的攻击威力。", type: "exclusive"},
            {name: "黑火药配方", color: "S", cost: 2200, desc: "你是个炸弹狂人，能用生活用品制造威力巨大的炸弹。艺术就是爆炸，炸飞那些恶心的怪物吧！", type: "exclusive"},
            {name: "神之基因(开启)", color: "S", cost: 3500, desc: "你的基因锁被打开，拥有无限进化的潜能。受伤后会迅速愈合，并针对伤害来源进化出抗性。", type: "exclusive"},
            {name: "尸王血脉", color: "SS", cost: 8500, desc: "你获得了龙右的血脉。拥有不死之身，极强的感染力和再生力。你可以随意改变身体结构，甚至分裂增殖。", type: "exclusive"},
            {name: "天罡气", color: "SS", cost: 7000, desc: "炎黄特能队的顶级功法。至刚至阳的内力，是一切邪祟病毒的克星。护体罡气能防御重炮轰击。", type: "exclusive"},
            {name: "麒麟真人传承", color: "SS", cost: 7500, desc: "掌握雷法与炼丹术。你的雷电能瞬间将尸兄化为灰烬，炼制的丹药能解百毒，提升功力。", type: "exclusive"},
            {name: "地球意志的加护", color: "SSS", cost: 22000, desc: "你是地球选定的守护者。在这个位面，你的运气、力量、恢复力都得到世界的加持。病毒无法侵蚀你的意志。", type: "exclusive"},
            {name: "超神入化", color: "SSS", cost: 30000, desc: "超越了生物的极限，你进化为了更高维度的存在。你可以操控分子结构，凭空造物，或者瞬间毁灭一座城市。", type: "exclusive"}
        ]
    },
    {
        name: "106.中国惊奇先生",
        desc: "现代都市下隐藏着古老的道法与妖魔。神鬼七杀令重现江湖，僵尸、狐妖、甚至黄大仙都混迹在人群中。这是一个接地气的灵异世界。",
        boss: "黄父鬼, 极道仙师, 金刚尸",
        identities: [
            { name: "帝都地下室的蚁族", items: "一张公交卡, 一包方便面" },
            { name: "火葬场的夜班保安", items: "一个手电筒, 一瓶二锅头" },
            { name: "被黑中介坑的打工仔", items: "一张假合同, 沉重的编织袋" },
            { name: "不知名小道观的扫地工", items: "一把扫帚, 一本破烂的《道德经》" },
            { name: "夜店门口的代驾", items: "一辆折叠电动车, 一个充电宝" }
        ],
        talents: [
            {name: "阴阳眼(不可控)", color: "D", cost: 150, desc: "你能看到鬼魂，但无法控制开关。经常在半夜上厕所时看到不该看的东西，容易被吓出精神病。", type: "exclusive"},
            {name: "纯阳童子身", color: "C", cost: 100, desc: "保持童子身，你的阳气比常人重，普通的小鬼不敢近身。但一旦破身，功力全废。", type: "exclusive"},
            {name: "江湖骗术", color: "C", cost: 80, desc: "你精通看相算命、摸骨测字等忽悠技巧。虽然没法力，但能骗得那些有钱人团团转，解决经济问题。", type: "exclusive"},
            {name: "王小二的厨艺", color: "B", cost: 300, desc: "你能做出极其实惠又好吃的饭菜，深受底层人民喜爱。在特定情况下，能通过美食结交隐藏的大佬。", type: "exclusive"},
            {name: "请神术(低配)", color: "B", cost: 550, desc: "能请来一些孤魂野鬼上身帮忙，比如生前是大力士的鬼。但请神容易送神难，副作用是身体虚弱。", type: "exclusive"},
            {name: "金光咒", color: "A", cost: 1200, desc: "道家八大神咒之一。念动咒语，身体覆盖金光，万法不侵。对物理攻击和法术攻击都有极高的防御力。", type: "exclusive"},
            {name: "五雷正法(掌心雷)", color: "A", cost: 1500, desc: "掌心凝聚雷电，对妖魔鬼怪有极大的克制作用。一掌下去，厉鬼也要魂飞魄散，是近战法师的标配。", type: "exclusive"},
            {name: "赶尸术", color: "A", cost: 1000, desc: "湘西秘术。你可以操控尸体为你作战，或者让尸体自行搬运货物。在尸体多的地方战斗力大增。", type: "exclusive"},
            {name: "神鬼七杀令(前三式)", color: "S", cost: 3500, desc: "太上老君传下的禁术。杀破令、风火令、追魂令。威力巨大，能跨级挑战妖王，但消耗极大。", type: "exclusive"},
            {name: "狐妖媚术", color: "S", cost: 2800, desc: "你拥有九尾狐般的魅力。一颦一笑都能勾人心魄，能控制意志不坚的人为你所用，甚至让敌人自相残杀。", type: "exclusive"},
            {name: "拘灵遣将", color: "SS", cost: 7000, desc: "强制拘押灵体并为人所用。无论是孤魂野鬼还是千年妖灵，都必须服从你的命令。能吞噬灵体增强自身。", type: "exclusive"},
            {name: "神鬼七杀令(全本)", color: "SS", cost: 9500, desc: "掌握全部七式杀令，包括毁天灭地的最后几式。一招既出，神鬼皆杀。足以对抗神明级别的敌人。", type: "exclusive"},
            {name: "黄大仙的幻术", color: "SS", cost: 6500, desc: "顶级的精神控制与幻觉制造。你能让整座城市陷入你编织的梦境中，杀人于无形，真假难辨。", type: "exclusive"},
            {name: "道德天尊亲传", color: "SSS", cost: 28000, desc: "你得到了道教始祖的认可。天地法则为你所用，随手画符皆是神符。你可以借用天道之力镇压一切。", type: "exclusive"},
            {name: "极道魔尊体", color: "SSS", cost: 26000, desc: "集天地怨气与魔气于一身。肉身成圣，万劫不坏。你可以吸收世间一切负面能量无限变强，成为新的魔主。", type: "exclusive"}
        ]
    },
    {
        name: "107.凸变英雄",
        desc: "马桶垫设计师大叔意外获得了超能力，代价是变成了又丑又胖的模样。这是一个关于父爱、守护与无厘头战斗的世界，外星人随时可能入侵。",
        boss: "外星侵略军总司令, 黑化的小敏, 异次元怪兽",
        identities: [
            { name: "马桶垫设计公司的实习生", items: "一支画笔, 一叠被退回的稿纸" },
            { name: "隔壁的老王", items: "一件背心, 一把蒲扇" },
            { name: "被外星人抓走的倒霉蛋", items: "一个外星手铐, 破烂的睡衣" },
            { name: "小区的保安大叔", items: "一根警棍, 一壶茶水" },
            { name: "路过的女高中生", items: "一个书包, 一部手机" }
        ],
        talents: [
            {name: "颜值换战力(被动)", color: "D", cost: 200, desc: "你越丑，战斗力越强。当你丑到让人无法直视时，你将拥有毁灭世界的力量。副作用是注孤生。", type: "exclusive"},
            {name: "马桶垫专精", color: "C", cost: 50, desc: "你对马桶垫的构造了如指掌。能用马桶垫制作陷阱、盾牌甚至回旋镖。虽然听起来很扯，但意外地好用。", type: "exclusive"},
            {name: "嘴炮(无厘头)", color: "C", cost: 100, desc: "你能用毫无逻辑的语言让敌人陷入混乱，甚至让外星人怀疑人生，从而放弃进攻。", type: "exclusive"},
            {name: "老爸的直觉", color: "B", cost: 400, desc: "当你的女儿（或重要的人）遇到危险时，你的感知力提升1000%，能瞬间锁定敌人的位置。", type: "exclusive"},
            {name: "功夫大师(伪)", color: "B", cost: 500, desc: "你通过看功夫电影学会了一些花架子。虽然没有内力，但动作极其帅气，能吓唬住不懂行的敌人。", type: "exclusive"},
            {name: "变身腰带(玩具)", color: "A", cost: 1200, desc: "看似是玩具，其实能让你变身成特摄英雄。拥有增强的力量和防御，还能发射光波，持续时间5分钟。", type: "exclusive"},
            {name: "二次元召唤", color: "A", cost: 1500, desc: "你可以将二次元手办变为真人为你战斗。战斗力取决于手办的精细度和你的中二程度。", type: "exclusive"},
            {name: "超强防御(脂肪)", color: "S", cost: 2500, desc: "你的一身肥肉是最好的铠甲。能反弹子弹，吸收冲击波，甚至能夹住敌人的武器。", type: "exclusive"},
            {name: "文字具象化", color: "S", cost: 3000, desc: "你写出的字或说出的拟声词会变成实体攻击。写个“死”字真的会让人死，喊一声“轰”真的会爆炸。", type: "exclusive"},
            {name: "数据删除", color: "SS", cost: 8000, desc: "你可以像编辑文档一样编辑现实。删除敌人的武器，复制自己的队友，甚至剪切空间。", type: "exclusive"},
            {name: "父爱如山", color: "SS", cost: 9000, desc: "为了守护女儿，你的战斗力没有上限。只要信念足够强，你可以一拳打爆星球，无视任何物理法则。", type: "exclusive"},
            {name: "黑洞胃袋", color: "SS", cost: 6500, desc: "你能吃下任何东西，包括能量波、炸弹、甚至敌人。吃下去的东西会转化为你的能量。", type: "exclusive"},
            {name: "侵略者科技", color: "S", cost: 2800, desc: "你掌握了外星人的核心科技。能制造飞船、激光炮、反重力装置，将地球科技提升五百年。", type: "exclusive"},
            {name: "创世画笔", color: "SSS", cost: 25000, desc: "你手中的笔可以改写世界观。你可以画出新的设定，抹除旧的设定。你是这个漫画世界的作者。", type: "exclusive"},
            {name: "重启世界", color: "SSS", cost: 35000, desc: "当一切无可挽回时，你可以选择重启整个时间线。保留记忆回到过去，改变悲惨的结局。", type: "exclusive"}
        ]
    },
    {
        name: "108.雾山五行",
        desc: "上古时期，妖兽纵横。五行使者镇守雾山，封印麒麟。火行使者闻人翊悬私自打开巨阙神盾，导致小麒麟走失，引发人妖大战。水墨画风下的硬核战斗。",
        boss: "贪嗔痴三兽, 麒麟, 泽漆(暗影)",
        identities: [
            { name: "地膳村的采药人", items: "一个药篓, 一把镰刀" },
            { name: "酒鬼张的学徒", items: "一坛烈酒, 几个空碗" },
            { name: "雾山脚下的迷路旅人", items: "一张看不懂的地图, 干粮" },
            { name: "被妖兽袭击的幸存者", items: "断裂的木棍, 染血的绷带" },
            { name: "五行司的落选弟子", items: "一把未开锋的铁剑, 破碎的令牌" }
        ],
        talents: [
            {name: "五行失衡(绝症)", color: "E", cost: 50, desc: "你体内的五行之气极其混乱，时刻冲突。不仅无法修炼，还伴随着剧痛，寿命极短。", type: "exclusive"},
            {name: "聚气丹(劣质)", color: "D", cost: 150, desc: "强行提升一点灵力的丹药，副作用是拉肚子三天，且经脉受损。适合拼命时使用。", type: "exclusive"},
            {name: "水墨身法", color: "C", cost: 300, desc: "你的移动会在空气中留下墨痕，干扰敌人视线。身法飘逸，如同画中人，闪避率提升。", type: "exclusive"},
            {name: "初级炼药术", color: "C", cost: 200, desc: "地膳村的秘方。能利用麒麟血（如果有）或普通草药制作强化身体的药丸，虽然可能有副作用。", type: "exclusive"},
            {name: "形意拳", color: "B", cost: 500, desc: "模仿动物的拳法。虎鹤双形，刚柔并济。配合灵力使用，能打出不俗的伤害。", type: "exclusive"},
            {name: "挑担者", color: "B", cost: 450, desc: "像鸭子一样的挑担人。看似普通，实则拥有极强的腿部力量和耐力，逃跑速度一流。", type: "exclusive"},
            {name: "火行之力(微弱)", color: "A", cost: 1500, desc: "你能操控火焰，附着在武器上增加伤害。虽然比不上闻人翊悬，但烧死普通妖兽没问题。", type: "exclusive"},
            {name: "水行之力(治愈)", color: "A", cost: 1600, desc: "申屠子夜的能力分支。能用水流治疗伤口，或者制造冰墙防御。团队中的核心辅助。", type: "exclusive"},
            {name: "巨阙神盾(碎片)", color: "S", cost: 3000, desc: "封印麒麟的神盾碎片。拥有极高的防御力，能抵挡妖王的全力一击，并对妖兽有压制作用。", type: "exclusive"},
            {name: "昭神灵力", color: "S", cost: 3500, desc: "通过特殊的面具引出体内的潜能。全属性大幅提升，灵力实体化，但使用过度会燃烧生命。", type: "exclusive"},
            {name: "嗔兽之怒", color: "SS", cost: 7500, desc: "吸收了嗔兽的妖力。愤怒是你力量的源泉。越愤怒，身体越巨大化，攻击越狂暴，能发射破坏光束。", type: "exclusive"},
            {name: "五行归一", color: "SS", cost: 9000, desc: "你精通金木水火土五种属性，并能将其融合。五行相生相克，你可以应对任何属性的敌人。", type: "exclusive"},
            {name: "焕离神火", color: "SS", cost: 8500, desc: "闻人翊悬的绝技。至纯至阳的火焰，能焚烧万物，甚至连空间都能烧穿。对妖兽有绝对的毁灭性。", type: "exclusive"},
            {name: "麒麟之血", color: "SSS", cost: 28000, desc: "你服用了纯正的麒麟血。获得半神之躯，长生不老，万毒不侵。你的灵力无穷无尽，是行走的唐僧肉。", type: "exclusive"},
            {name: "洪荒之力", color: "SSS", cost: 32000, desc: "唤醒上古洪荒的记忆与力量。你即是天地法则的化身，抬手间山河破碎，覆手间万物复苏。", type: "exclusive"}
        ]
    },
    {
        name: "109.镖人",
        desc: "隋末乱世，朝廷暴政，西域风沙。刀马带着孩子小七行走江湖。这里没有魔法，只有刀刀见血的硬派武侠。知世郎的预言，让整个天下动荡不安。",
        boss: "宇文智及, 谛听(组织), 杨广",
        identities: [
            { name: "赤沙镇的乞丐", items: "一个破碗, 一根打狗棒" },
            { name: "被通缉的逃兵", items: "一把卷刃的横刀, 一身破烂甲胄" },
            { name: "西域商队的脚夫", items: "一双磨破的草鞋, 一袋干粮" },
            { name: "隋朝修运河的民夫", items: "一把铁锹, 沉重的枷锁" },
            { name: "不知名客栈的小二", items: "一条毛巾, 一壶劣酒" }
        ],
        talents: [
            {name: "悬赏令(通缉)", color: "E", cost: 50, desc: "你的头像挂满了大街小巷。无论走到哪里都会被官府和赏金猎人追杀，无法进入城镇补给。", type: "exclusive"},
            {name: "断臂(残疾)", color: "D", cost: 100, desc: "你失去了一条手臂，无法使用双手武器，平衡性差。但这也让你更加狠辣，让人轻视你。", type: "exclusive"},
            {name: "沙漠生存", color: "C", cost: 80, desc: "你在大漠中长大，知道哪里有水源，如何躲避沙尘暴。在沙漠地形中，你的耐力消耗减半。", type: "exclusive"},
            {name: "基础刀法", color: "C", cost: 150, desc: "军中流传的基础杀人技。没有花哨的动作，只有劈、砍、刺。简单实用，适合乱战。", type: "exclusive"},
            {name: "听风辨位", color: "B", cost: 400, desc: "你的耳朵能听到极细微的声音，能判断暗器的来向和敌人的数量，防止被偷袭。", type: "exclusive"},
            {name: "马术精通", color: "B", cost: 500, desc: "你与马匹有天生的默契。能在马背上做出高难度动作，骑战能力大幅提升，逃跑也没人追得上。", type: "exclusive"},
            {name: "西域毒术", color: "A", cost: 1200, desc: "你懂得提炼蝎毒、蛇毒。涂抹在兵器上，见血封喉。也能配置解药，是行走江湖的阴招。", type: "exclusive"},
            {name: "十三太保横练", color: "A", cost: 1500, desc: "一身硬气功，刀枪不入。普通的刀剑砍在身上只会发出金属撞击声，除非罩门被破。", type: "exclusive"},
            {name: "刀马的刀", color: "S", cost: 2800, desc: "你领悟了刀马的刀意。出刀极快，专攻要害。头骨、关节，皆可斩断。一人一刀，千军辟易。", type: "exclusive"},
            {name: "知世郎的口才", color: "S", cost: 2500, desc: "花开花落，花落花开。你的语言具有极强的煽动性，能瞬间拉起一支起义军，让百姓为你赴死。", type: "exclusive"},
            {name: "阿育娅的箭术", color: "S", cost: 2200, desc: "百步穿杨，例无虚发。你能同时射出三支箭，精准命中移动目标。在远程压制上无人能敌。", type: "exclusive"},
            {name: "罗刹族血统", color: "SS", cost: 7000, desc: "你拥有食人鬼族的血统。力量巨大，嗜血狂暴。受伤越重，战斗力越强，能徒手撕裂虎豹。", type: "exclusive"},
            {name: "谛听情报网", color: "SS", cost: 6500, desc: "你掌握了谛听组织的情报渠道。天下没有你不知道的秘密。你可以轻易找到敌人的弱点和藏身之处。", type: "exclusive"},
            {name: "天下第一刀", color: "SSS", cost: 20000, desc: "你的刀法已臻化境。不再局限于招式，草木竹石皆可为刀。一刀挥出，带有天地大势，无可阻挡。", type: "exclusive"},
            {name: "改朝换代", color: "SSS", cost: 30000, desc: "你拥有帝王之气。天命所归，各路豪杰纳头便拜。你注定推翻旧王朝，建立属于你的新帝国。", type: "exclusive"}
        ]
    },
    {
        name: "110.偷星九月天",
        desc: "古悉兰王国的遗迹，黑月铁骑的宿命，VV学院的搞笑日常。这是一个拥有第七感（异能）的现代奇幻世界。九月天盗取星空，而K正在策划成神。",
        boss: "K(缪尔五世), 堕天使军团, 黑月铁骑(暴走)",
        identities: [
            { name: "VV学院的清洁工", items: "一把拖把, VV学院校徽(假)" },
            { name: "琉星家的保安", items: "一根电棍, 一本欠债账单" },
            { name: "黑月岛的杂役", items: "一套黑月制服, 一个定位项圈" },
            { name: "波塞冬的难民", items: "一个救生圈, 几块压缩饼干" },
            { name: "考古队的搬运工", items: "一把洛阳铲, 一个古悉兰石碑碎片" }
        ],
        talents: [
            {name: "元素排斥(缺陷)", color: "E", cost: 50, desc: "你的身体无法容纳任何元素力量。强行开发第七感会导致身体崩溃，只能当个普通人。", type: "exclusive"},
            {name: "女仆装癖好", color: "D", cost: 100, desc: "受琉星影响，你穿女仆装时战斗力提升20%，但羞耻度爆表，且容易被当作变态抓起来。", type: "exclusive"},
            {name: "钞能力(负债)", color: "C", cost: 50, desc: "你继承了琉星的巨额债务。虽然没钱，但你拥有极强的抗压能力和打工技能，怎么折腾都死不了。", type: "exclusive"},
            {name: "侦探直觉", color: "C", cost: 120, desc: "你拥有敏锐的观察力，能发现细微的线索。在解谜和追踪怪盗九月天时有奇效。", type: "exclusive"},
            {name: "燕子飞镖", color: "B", cost: 400, desc: "你学会了九月天的飞镖绝技。出手无声，精准度高，还能利用钢丝进行空中移动。", type: "exclusive"},
            {name: "天才黑客", color: "B", cost: 600, desc: "你能入侵大部分网络系统，控制监控，窃取资料。在现代都市战中是不可或缺的后勤支援。", type: "exclusive"},
            {name: "第七感:驭土之术", color: "A", cost: 1500, desc: "破军的招牌能力。能操控土石，制造土墙防御或地刺攻击。虽然平时是个小孩，但关键时刻很靠谱。", type: "exclusive"},
            {name: "第七感:御雷之术", color: "A", cost: 1600, desc: "武曲的能力。操控雷电，速度极快，攻击力高。能瞬间麻痹敌人，或者进行电磁吸附。", type: "exclusive"},
            {name: "第七感:驭火之术", color: "S", cost: 2800, desc: "十月的能力。炽热的火焰能融化钢铁，彼岸花开更是大范围杀伤技。你是火焰的君主。", type: "exclusive"},
            {name: "第七感:驭冰之术", color: "S", cost: 2800, desc: "沧月的能力。绝对零度，冰封千里。你的气场强大到让人不敢直视，女王范儿十足。", type: "exclusive"},
            {name: "地狱之血", color: "SS", cost: 8000, desc: "你体内流淌着恶魔的血液。可以变身为堕天使形态，拥有翅膀和黑暗力量，但容易失去理智。", type: "exclusive"},
            {name: "光之元素", color: "SS", cost: 8500, desc: "九月觉醒后的力量。光速移动，光子化，净化一切黑暗。你是希望的象征，速度快到时间都静止。", type: "exclusive"},
            {name: "八元素融合", color: "SS", cost: 9500, desc: "你尝试融合多种元素力量。虽然极难控制，但一旦成功，能释放出混沌般的毁灭力量。", type: "exclusive"},
            {name: "神之躯(K)", color: "SSS", cost: 30000, desc: "你拥有了缪尔五世的身体。吸收了无数异能者的力量，不死不灭，能适应任何环境，只有神能杀死你。", type: "exclusive"},
            {name: "真神降临", color: "SSS", cost: 40000, desc: "你完全开启了古悉兰的终极秘密。超越了第七感，达到了第八感甚至更高。你可以重塑星球，逆转时空。", type: "exclusive"}
        ]
    },
              {
        name: "111.夏目友人帐",
        desc: "一个充满温柔与忧伤的妖怪世界。拥有强大灵力的少年夏目贵志在归还名字的旅途中，见证了人与妖之间剪不断的羁绊。这里虽美，但对于没有自保能力的偷渡者来说，被妖怪‘吃掉名字’是常有的事。",
        boss: "的场静司, 名取周一, 强大的大妖(如三筱)",
        identities: [
            { name: "被遗忘在废弃神社的流浪儿", items: "半个发霉的馒头, 一件漏风的破旧和服" },
            { name: "的场一门的最底层见习生", items: "几张画歪了的封印符, 一把钝掉的仪式短刀" },
            { name: "森林里的一只卑微小妖", items: "一片可以挡雨的荷叶, 一个装满露水的破葫芦" },
            { name: "偏远山村的孤僻少年", items: "一本涂鸦用的旧笔记本, 一支快用完的铅笔" },
            { name: "妖怪集市上的杂货摊帮工", items: "一根用来驱赶乌鸦的竹竿, 一块脏得看不出颜色的抹布" }
        ],
        talents: [
            {name: "友人帐契约者(伪)", color: "SS", cost: 9500, desc: "你拥有一页仿制的友人帐，可以强行命令名字记录在册的中级以下妖怪一次。这是极其危险的道具，一旦被大妖发现必死无疑。", type: "exclusive"},
            {name: "见妖之眼", color: "C", cost: 180, desc: "你拥有最基础的灵感，能模糊看到妖怪的轮廓。虽然这让你免于无意中冒犯，但也让你成为了某些恶毒妖怪的戏耍目标。", type: "exclusive"},
            {name: "猫咪老师的嫌弃", color: "B", cost: 320, desc: "你身上沾染了高级招财猫（大怪鸟）的气息。低级妖怪不敢靠近你，但由于气息太臭，你很难获得人类的好感度，且容易招致大妖窥视。", type: "exclusive"},
            {name: "除妖师天赋(速成)", color: "A", cost: 850, desc: "你对符咒和阵法有极高的领悟力。虽然起步晚，但你能以极快的速度学会基础封印术，在面对低级妖怪时拥有了一定的自保能力。", type: "exclusive"},
            {name: "玲子的血脉残片", color: "SSS", cost: 32000, desc: "你体内流淌着极微弱的夏目玲子的血脉。这种血脉对妖怪有着致命的吸引力和压制力，即便你什么都不做，大妖也会不自觉地向你聚集。", type: "exclusive"},
            {name: "归还名字的慈悲", color: "S", cost: 1800, desc: "当你尝试归还妖怪名字时，有几率获得对方的‘核心记忆’。这对于你这种偷渡者来说，是收集世界情报、提升锚定值的绝佳手段。", type: "exclusive"},
            {name: "式神役使术", color: "A", cost: 750, desc: "你可以将弱小的纸人转化为临时式神。虽然战斗力一般，但用来侦察和打杂非常方便，是潜入重要场所的必备技能。", type: "exclusive"},
            {name: "灵力威压", color: "B", cost: 400, desc: "你的灵魂强度高于常人，散发出的灵力能让靠近的小妖感到不适。这种不经意间的威慑力能帮你省去很多不必要的低级骚扰。", type: "exclusive"},
            {name: "古书修复师", color: "C", cost: 120, desc: "你擅长修复残破的古籍和画轴。在这个充满秘密的世界里，通过修复古物，你往往能接触到那些隐藏在历史中的禁忌知识。", type: "exclusive"},
            {name: "七辻屋的忠实拥趸", color: "D", cost: 50, desc: "你非常擅长排队购买限量版馒头。虽然这看起来没用，但如果你能用馒头贿赂某个贪吃的招财猫，或许能换来一次保命的机会。", type: "exclusive"},
            {name: "森林语者", color: "B", cost: 380, desc: "你能听懂草木的低语和风的讯息。在野外生存时，大自然会指引你避开危险的妖怪领地，并寻找那些隐藏的珍稀材料。", type: "exclusive"},
            {name: "除妖世家旁支身份", color: "S", cost: 1500, desc: "你拥有一个合法的除妖师家族身份。这让你能接触到除妖师的社交圈和情报网，但也意味着你必须参与那些危险的封印任务。", type: "exclusive"},
            {name: "梦中预警", color: "A", cost: 900, desc: "当危险临近时，你会通过梦境得到预示。虽然预示往往模糊不清，但足够让你在死神降临前做好读档或者逃跑的准备。", type: "exclusive"},
            {name: "因果切断", color: "SS", cost: 7800, desc: "你拥有一种奇特的能力，可以短暂切断自己与当前世界的因果联系。这能让你躲避任何追踪类法术，甚至是命运层面的锁定。", type: "exclusive"},
            {name: "丰月神的祝福", color: "SSS", cost: 25000, desc: "你曾意外获得过神明的注视。土地会为你提供庇护，庄稼会为你丰收。在当前世界，你的运气被锁定在极高水平，极易触发奇遇。", type: "exclusive"}
        ]
    },
    {
        name: "112.虫师",
        desc: "‘虫’，既非动物也非植物，是接近生命本源的异类群体。它们无处不在，却又难以察觉。在这个世界，人类与虫的接触往往伴随着奇妙而残酷的异变。你必须在荒野与村落间求生，探索那些被‘虫’扭曲的生命真相。",
        boss: "禁种之虫, 各种天灾级‘虫’(如常暗), 狩房家守稿人",
        identities: [
            { name: "被‘虫’寄生的流浪汉", items: "一只不断渗出粘液的左手, 一根用来支撑身体的枯木棍" },
            { name: "偏远深山的采药童子", items: "一个破旧的背篓, 一把生锈的采药镰刀" },
            { name: "失去视力的村庄祭司", items: "一根雕刻着奇怪纹路的盲杖, 一个装满灰烬的香囊" },
            { name: "虫师学徒的弃子", items: "一卷写满模糊笔记的羊皮纸, 半瓶快干涸的‘光酒’" },
            { name: "海边贫民窟的渔夫", items: "一张散发着海腥味的破网, 一个长满寄生贝壳的木桶" }
        ],
        talents: [
            {name: "光酒之体", color: "SS", cost: 8200, desc: "你的血液中融合了微量的光酒，这是生命的源泉。你对所有‘虫’都有着致命的吸引力，同时也能通过消耗血液快速治愈任何伤势。", type: "exclusive"},
            {name: "虫之视界", color: "B", cost: 350, desc: "你可以看到常人无法察觉的‘虫’。这让你能提前预知灾难的降临，但长期直视这些生命本源会逐渐侵蚀你的精神理智。", type: "exclusive"},
            {name: "禁种之种", color: "SSS", cost: 45000, desc: "你体内潜伏着传说中能毁灭世界的禁种。它是诅咒也是力量，让你能控制周围的‘虫’，但每使用一次，你离彻底消失就近了一步。", type: "exclusive"},
            {name: "狩房家墨之宿", color: "S", cost: 2100, desc: "你继承了狩房家‘墨’的诅咒。你的身体是知识的载体，能通过书写文字封印‘虫’，这种禁忌的知识让你在虫师中地位崇高。", type: "exclusive"},
            {name: "烟管之息", color: "C", cost: 150, desc: "你掌握了特殊的吸烟技巧，排出的烟雾能驱散大多数低级且有害的‘虫’。虽然对强力‘虫’无效，但却是野外露营的必备神技。", type: "exclusive"},
            {name: "生命频率共振", color: "A", cost: 700, desc: "你可以调整自己的呼吸频率，使其与周围的‘虫’达成一致。这能让你在虫群中行走而不被攻击，甚至能从‘虫’那里获取情报。", type: "exclusive"},
            {name: "荒野生存大师", color: "C", cost: 120, desc: "你精通各种野菜、草药和避险知识。在缺乏物资的古代日本背景下，这项技能能确保你不会因为误食毒蘑菇而无谓地读档。", type: "exclusive"},
            {name: "永恒的回忆", color: "S", cost: 2500, desc: "即使因为‘虫’的作用失去了记忆，你也能通过灵魂深处的烙印找回自我。这对于应对那些专门吞噬记忆的‘虫’来说是神级天赋。", type: "exclusive"},
            {name: "银发之变(初兆)", color: "A", cost: 950, desc: "你的头发开始变白，一只眼睛逐渐失去瞳色。这是成为顶级虫师的征兆，你的体质变得极度寒冷，能冻结那些靠近你的细小虫类。", type: "exclusive"},
            {name: "虫之低语翻译", color: "B", cost: 420, desc: "你能理解‘虫’发出的原始信号。虽然它们没有逻辑，但通过捕捉这些碎片信息，你可以精准定位世界核心因果的发生地。", type: "exclusive"},
            {name: "光脉追踪者", color: "S", cost: 2300, desc: "你能感知地下深处流动的光脉。沿着光脉行走，你的因果锚定速度将大幅提升，且更容易发现那些涉及世界本源的珍稀道具。", type: "exclusive"},
            {name: "异常抗性(虫)", color: "A", cost: 800, desc: "你的免疫系统对‘虫’产生的毒素和寄生有极强的抗性。即便被‘虫’侵入身体，你也能坚持更久，寻找解决之道而非立即暴毙。", type: "exclusive"},
            {name: "采集者之手", color: "C", cost: 180, desc: "你拥有一双极其灵巧且稳定的手。在采集那些稍纵即逝的‘虫’标本或草药时，你的成功率将提升50%，是前期积累积分的好手段。", type: "exclusive"},
            {name: "因果锚定加速", color: "SS", cost: 8800, desc: "你天生具有扰乱世界线的能力。在处理涉及‘虫’的事件时，你获得的锚定经验翻倍，这能让你以极快的速度从E级晋升到A级。", type: "exclusive"},
            {name: "生命本源的馈赠", color: "SSS", cost: 28000, desc: "你曾直视过生命的起点。你不再受生老病死的约束，只要这个世界还有‘虫’存在，你就能通过不断消耗因果值来强行重塑肉身。", type: "exclusive"}
        ]
    },
    {
        name: "113.黑执事",
        desc: "19世纪英国维多利亚女王时期。华丽的贵族社交场下，是黑暗的黑道博弈。恶魔、死神、天使与人类的野心交织在一起。作为偷渡者，你必须在伦敦的浓雾中找到生存之道，或者成为某场契约的祭品。",
        boss: "塞巴斯蒂安, 葬仪屋, 维多利亚女王, 阿修罗",
        identities: [
            { name: "伦敦东区的流浪汉", items: "一叠浸水的废报纸, 一个生锈的空罐头盒" },
            { name: "凡多姆海威领地的割草工", items: "一把磨损严重的镰刀, 一顶满是汗臭的草帽" },
            { name: "苏格兰场的最底层文员", items: "一支分叉的羽毛笔, 一本记录着琐碎案件的记事本" },
            { name: "地下马戏团的打杂工", items: "一个用来装动物粪便的木铲, 一张破烂的演出宣传单" },
            { name: "被遗弃的孤儿院孤儿", items: "一块发硬的黑面包, 一个只有一只眼睛的破烂布偶" }
        ],
        talents: [
            {name: "恶魔契约者(候选)", color: "SS", cost: 9800, desc: "你拥有极度纯粹且绝望的灵魂。你有资格召唤恶魔并签订契约，但这需要付出灵魂作为代价。作为偷渡者，你或许能利用这点玩弄规则。", type: "exclusive"},
            {name: "凡多姆海威的密探", color: "A", cost: 1200, desc: "你接受过专业的间谍训练。擅长潜入、窃听和暗杀。在伦敦的黑暗面，你的人脉和手段能让你迅速积累起最初的资本。", type: "exclusive"},
            {name: "死神视界(伪)", color: "S", cost: 2800, desc: "你能看到每个人头顶的‘走马灯剧场’。虽然无法修改，但通过观看他人的过去，你可以掌握无数秘密和弱点，从而进行欺诈或勒索。", type: "exclusive"},
            {name: "贵族仪态", color: "C", cost: 180, desc: "你天生拥有一种优雅的气质，即使穿着破烂也像个落难贵族。这能让你在进入高级场所时减少被怀疑的几率，更易获得上位者的关注。", type: "exclusive"},
            {name: "超越时代的医学知识", color: "B", cost: 450, desc: "你掌握了一些19世纪尚未普及的医学常识。通过治疗那些贵族无法治愈的‘怪病’，你可以迅速提升自己的社会地位和因果锚定等级。", type: "exclusive"},
            {name: "机械天才", color: "A", cost: 950, desc: "你对蒸汽机和精密机械有超前的理解。你能制造出各种精巧的机关和简易武器，在面对那些超自然生物时，科技是你唯一的底牌。", type: "exclusive"},
            {name: "伦敦黑道人脉", color: "B", cost: 380, desc: "你熟悉伦敦贫民窟的每一个角落。所有的小偷、乞丐和妓女都是你的眼线。在这个情报为王的时代，你就是黑暗中的蜘蛛。", type: "exclusive"},
            {name: "葬仪屋的恶趣味", color: "S", cost: 2200, desc: "你特别擅长讲笑话。如果你能逗笑那位疯狂的葬仪屋，他或许会告诉你一些关于世界本源、死神派遣协会甚至是灵魂的禁忌秘密。", type: "exclusive"},
            {name: "恶魔的嗅觉", color: "A", cost: 1100, desc: "你能分辨出空气中残留的硫磺味和恶魔气息。这能让你在那些非人生物发现你之前，提前做好规避动作或者读档准备。", type: "exclusive"},
            {name: "女王的走狗(潜力)", color: "S", cost: 2500, desc: "你拥有一种能为女王解决‘麻烦’的天赋。通过完成一系列极端任务，你可能获得爵位，从而在因果等级上实现从E到A的跨越。", type: "exclusive"},
            {name: "毒药大师", color: "B", cost: 500, desc: "你精通各种化学毒素的配制。在19世纪，一场‘意外的重病’是除掉竞争对手最优雅的方式。当然，请确保不要毒死你自己。", type: "exclusive"},
            {name: "走马灯干涉术", color: "SSS", cost: 35000, desc: "你拥有极罕见的干涉他人记忆的能力。你可以短暂修改对方走马灯中的一段内容，从而彻底改变一个人的认知和性格。这是神之权柄。", type: "exclusive"},
            {name: "灵魂收割者(实习)", color: "S", cost: 3000, desc: "你获得了一把低级死神镰刀的使用权。虽然你不是死神，但你可以收割那些濒死者的灵魂碎片，并将其转化为系统积分。", type: "exclusive"},
            {name: "因果剥离", color: "SS", cost: 8500, desc: "你可以将自己从某次重大历史事件的因果中强行剥离。即使任务失败导致世界崩塌，你也能毫发无伤地带着遗产回到系统空间。", type: "exclusive"},
            {name: "塞巴斯蒂安的认可", color: "SSS", cost: 50000, desc: "那位完美的执事对你的灵魂产生了浓厚兴趣。他会在不违反契约的前提下为你提供一次‘极致的服务’，这通常意味着绝对的毁灭或救赎。", type: "exclusive"}
        ]
    },
    {
        name: "114.吸血鬼骑士",
        desc: "黑主学院，人类与吸血鬼共存的虚假乐园。日间部是普通学生，夜间部则是美貌而危险的吸血鬼。在这个阶级森严、血统至上的世界，作为底层的你，是沦为血仆，还是成为狩猎者？",
        boss: "玖兰枢, 玖兰李土, 绯樱闲",
        identities: [
            { name: "黑主学院的贫困勤工俭学生", items: "一叠没写完的作业本, 一个干瘪的钱包" },
            { name: "吸血鬼猎人协会的编外杂役", items: "一瓶过期的人工血液, 一根断裂的木桩" },
            { name: "夜间部宿舍的洗碗工", items: "一副被腐蚀的橡胶手套, 一瓶强力去污剂" },
            { name: "流浪在街头的Level E候选人", items: "一个破烂的遮阳帽, 满身的抓痕" },
            { name: "黑市贩卖血液的帮工", items: "一个血迹斑斑的冷藏箱, 一把防身用的折叠刀" }
        ],
        talents: [
            {name: "纯血种血脉(极稀薄)", color: "SS", cost: 9000, desc: "你体内有极微量的纯血种基因。这让你对低级吸血鬼有天然的压制力，但也让你成为了所有吸血鬼眼中最美味、最想掠夺的补药。", type: "exclusive"},
            {name: "猎人之魂", color: "A", cost: 1100, desc: "你拥有成为顶尖吸血鬼猎人的资质。你对血液的渴望有极强的抵抗力，并且能熟练使用各种反吸血鬼武器，战斗力随锚定等级飙升。", type: "exclusive"},
            {name: "血之契约", color: "S", cost: 2600, desc: "你可以通过献祭自己的血液，与一名吸血鬼签订强制契约。对方将成为你的护卫，但契约的稳固程度取决于你的因果锚定等级。", type: "exclusive"},
            {name: "人工血液调配术", color: "C", cost: 120, desc: "你掌握了改良人工血液的方法。通过提供更高质量的替代品，你可以获得吸血鬼的好感，甚至在黑市中赚取大量积分和资源。", type: "exclusive"},
            {name: "隐匿气息", color: "B", cost: 380, desc: "你能完美隐藏自己作为人类的气息，在吸血鬼眼中你就像一块毫无吸引力的石头。这是在夜晚的校园中安全穿行的必备天赋。", type: "exclusive"},
            {name: "血液记忆读取", color: "A", cost: 1300, desc: "当你接触到某人的血液时，能读取其中蕴含的短暂片段。这让你能迅速掌握NPC的秘密，是进行欺诈和情报搜集的利器。", type: "exclusive"},
            {name: "Level E 转换抗性", color: "B", cost: 500, desc: "即便被吸血鬼咬伤，你也不会轻易堕落为丧失理智的Level E。这为你寻找解药或进行读档争取了极其宝贵的时间。", type: "exclusive"},
            {name: "血蔷薇之枪(仿)", color: "S", cost: 3500, desc: "你拥有一把特制的对吸血鬼手枪。虽然威力不及正品，但其子弹附带的净化效果足以让贵族阶级的吸血鬼感到忌惮。", type: "exclusive"},
            {name: "美貌加持", color: "C", cost: 200, desc: "在这个看脸的世界，你的颜值提升了。这让你更容易获得日间部女生的帮助或夜间部吸血鬼的‘怜悯’，虽然这种怜悯往往带着危险。", type: "exclusive"},
            {name: "血统进阶可能", color: "S", cost: 4500, desc: "你拥有突破种族限制的潜力。通过吞噬高等级吸血鬼的血液，你有几率从人类转化为精英吸血鬼，彻底改变你的成长曲线。", type: "exclusive"},
            {name: "玖兰家的秘密线索", color: "A", cost: 900, desc: "你掌握了关于纯血种始祖的一段秘辛。这段信息在关键时刻可以作为保命符，或者作为与玖兰枢进行交易的重要筹码。", type: "exclusive"},
            {name: "绝对冷静", color: "B", cost: 420, desc: "在面对吸血鬼的恐惧威压时，你的心跳和情绪不会有任何波动。这让你能做出最理智的判断，甚至在绝境中反杀对手。", type: "exclusive"},
            {name: "因果掠夺者", color: "SS", cost: 8200, desc: "每当你亲手终结一名重要吸血鬼的生命，你将永久获得其5%的身体属性。这能让你在不断的重生中变得越来越像怪物。", type: "exclusive"},
            {name: "始祖的低语", color: "SSS", cost: 38000, desc: "你能听到沉睡中始祖的声音。他们会赋予你操控影子的能力，这种力量涉及世界的核心法则，足以让整个吸血鬼社会感到颤栗。", type: "exclusive"},
            {name: "命运的红线", color: "SSS", cost: 55000, desc: "你强行修改了世界线，让自己成为了剧情核心的一环。所有重要NPC都会不自觉地被你吸引，你的每一个决定都将改写世界的结局。", type: "exclusive"}
        ]
    },
    {
        name: "115.地狱少女",
        desc: "‘想死一次试试吗？’。午夜零点，只有心怀怨恨的人才能登录的网站——地狱通信。在这里，怨恨可以通过契约消除，但代价是死后灵魂也将坠入地狱。作为一个偷渡者，你将在怨恨的漩涡中寻找机会。",
        boss: "阎魔爱, 三个随从(一目连、骨女、轮入道), 人面蜘蛛",
        identities: [
            { name: "被霸凌的边缘学生", items: "一件被涂鸦的脏校服, 一个坏掉的手机" },
            { name: "背负巨债的打工人", items: "一张催款通知单, 一瓶廉价的速溶咖啡" },
            { name: "地狱通信的传闻搜集者", items: "一本记满都市传说的笔记本, 一台老旧的录音机" },
            { name: "偏僻小镇的落魄神职人员", items: "一本发霉的经书, 一串断掉的念珠" },
            { name: "目睹了禁忌仪式的路人", items: "一副度数不合的眼镜, 一双磨平底的布鞋" }
        ],
        talents: [
            {name: "地狱通信管理员(临时)", color: "SS", cost: 9200, desc: "你拥有干预地狱通信网站的能力。你可以拦截或延迟怨恨请求，甚至在不签订契约的情况下利用地狱的力量，但会引起人面蜘蛛的注意。", type: "exclusive"},
            {name: "怨恨感知", color: "B", cost: 320, desc: "你能感知周围人的怨恨程度。这能让你精准找到那些即将触发‘地狱通信’的目标，从而提前布局，收割因果或者进行干预。", type: "exclusive"},
            {name: "草人替身术", color: "S", cost: 2400, desc: "你可以制作一个草人替身，代你承受一次致命伤害或地狱的拉扯。这是极少数能在这个规则杀世界中保命的遗产继承项。", type: "exclusive"},
            {name: "地狱边缘漫步者", color: "A", cost: 1100, desc: "你的灵魂可以在地狱与现世的夹缝中短暂停留。这让你能躲避现实世界的追踪，并从地狱的彼岸获取那些被诅咒的禁忌情报。", type: "exclusive"},
            {name: "诅咒反弹", color: "A", cost: 1500, desc: "当有人对你使用地狱通信时，你有一定几率将代价反弹给对方。虽然不能完全免除死后的惩罚，但至少能让对方先你一步下地狱。", type: "exclusive"},
            {name: "彼岸花之护", color: "C", cost: 180, desc: "你身上带着彼岸花的香气。这种气息能安抚那些暴走的怨灵，让你在处理灵异事件时拥有更高的初始好感度和安全性。", type: "exclusive"},
            {name: "地狱三随从的友谊", color: "S", cost: 4000, desc: "因为某种特殊原因，一目连、骨女或轮入道中的一位对你产生了兴趣。在非契约状态下，他们可能会为你提供一些微小的帮助。", type: "exclusive"},
            {name: "因果线操纵", color: "SS", cost: 7500, desc: "你可以看到并拨动人与人之间的怨恨连线。通过引导怨恨的流向，你可以玩弄NPC的命运，从而在极短时间内达成S级锚定目标。", type: "exclusive"},
            {name: "地狱少女的怜悯", color: "SSS", cost: 42000, desc: "阎魔爱对你的遭遇产生了一丝共鸣。她会为你破例执行一次非契约的‘流放’，且不收取你的灵魂作为代价。这是改变世界格局的机会。", type: "exclusive"},
            {name: "谎言辩识", color: "C", cost: 150, desc: "在这个充满欺骗和背叛的世界，你能一眼识破对方是否在撒谎。这对于你在复杂的社会关系中生存、寻找真正的怨恨源头至关重要。", type: "exclusive"},
            {name: "罪恶洗涤(伪)", color: "A", cost: 950, desc: "你可以通过消耗大量的系统积分，暂时洗去自己身上的因果罪业。这能让你在地狱少女进行审判时，被判定为‘无罪’而逃过一劫。", type: "exclusive"},
            {name: "午夜零点的登录权", color: "B", cost: 300, desc: "你无需身怀怨恨也能随时登录地狱通信。这让你成为了这个世界的‘中介人’，可以通过贩卖地狱契约来获取大量的局内积分。", type: "exclusive"},
            {name: "灵魂硬币", color: "B", cost: 550, desc: "每当你目睹一个人被流放到地狱，你将获得一枚灵魂硬币。硬币可以在系统商店兑换特殊道具，或者作为下次读档的额外遗产点。", type: "exclusive"},
            {name: "地狱之火操控", color: "S", cost: 3200, desc: "你掌握了地狱之火的皮毛，能烧毁那些物理手段无法处理的灵异产物。这种火焰对灵魂有直接伤害，是面对怨灵时的强力武器。", type: "exclusive"},
            {name: "人面蜘蛛的赌约", color: "SSS", cost: 60000, desc: "你与地狱的主宰进行了一场豪赌。如果你能在这个世界达成SSS级锚定，你将获得地狱的部分权限，甚至能复活那些已经被流放的人。", type: "exclusive"}
        ]
    },
    {
        name: "116.寒蝉鸣泣之时",
        desc: "昭和58年，雏见泽村。在这个看似祥和的村落里，隐藏着名为‘雏见泽症候群’的恐怖疾病和无尽的轮回。蝉鸣声中，惨剧不断上演。作为偷渡者，你必须在疯狂的村民和阴谋中活到祭典结束。",
        boss: "鹰野三四, 入江京介, 园崎魅音(L5状态), 古手梨花(轮回者)",
        identities: [
            { name: "刚搬来雏见泽的转学生", items: "一个印着卡通图案的旧书包, 一把折叠雨伞" },
            { name: "入江诊所的搬运工", items: "一副沾着血迹的医用手套, 一个空的药瓶" },
            { name: "园崎家领地内的伐木工", items: "一把生锈的重型斧头, 一根粗麻绳" },
            { name: "雏见泽分校的杂工", items: "一根用来清理垃圾的铁钩, 一个破了洞的塑料桶" },
            { name: "在村口游荡的流浪汉", items: "一个沾满泥土的破碗, 一张过期的报纸" }
        ],
        talents: [
            {name: "轮回记忆保留", color: "SS", cost: 9900, desc: "你拥有与古手梨花类似的特质，在读档复活后能保留100%的详细记忆。这让你在应对那些突如其来的疯狂和阴谋时拥有绝对的先手权。", type: "exclusive"},
            {name: "L5症候群抗性", color: "A", cost: 1500, desc: "你对雏见泽症候群有极强的免疫力。即便身处极度压抑的环境或被诱导，你也绝不会陷入那种抓破喉咙的疯狂状态，保持绝对理智。", type: "exclusive"},
            {name: "陷阱大师(沙都子传人)", color: "B", cost: 600, desc: "你精通各种因地制宜的陷阱制作。无论是应对村民的围攻还是专业部队的搜捕，这些小技巧往往能产生意想不到的杀伤力。", type: "exclusive"},
            {name: "园崎家的恐惧", color: "A", cost: 1200, desc: "你掌握了一些园崎家不可告人的酷刑秘密。这让你在面对园崎家的势力时拥有一定的威慑力，但也可能让你成为他们第一个要灭口的目标。", type: "exclusive"},
            {name: "入江诊所的特效药", color: "C", cost: 200, desc: "你随身携带几支能暂时缓解L5症状的药剂。在关键时刻，这不仅能救你的命，还能用来安抚那些已经陷入狂乱的重要NPC。", type: "exclusive"},
            {name: "御社神大人的注视", color: "S", cost: 3500, desc: "羽入对你产生了一丝好奇。在某些必死的节点，时间会产生极其微小的停滞，为你提供一次闪避或反击的机会。这种概率极低但极其致命。", type: "exclusive"},
            {name: "柴刀专精", color: "B", cost: 450, desc: "你对各种短柄砍伐工具有着惊人的天赋。当你手握柴刀或类似的利器时，你的攻击速度和精准度将大幅提升，充满了‘萌系’杀气。", type: "exclusive"},
            {name: "阴谋嗅觉", color: "A", cost: 1100, desc: "你能从村民看似平常的对话中嗅出危险的气息。每当有人对你产生杀意，你的后颈会产生强烈的瘙痒感，这是你在这个世界最重要的报警器。", type: "exclusive"},
            {name: "山狗部队训练经验", color: "S", cost: 2800, desc: "你曾秘密接受过山狗部队的基础训练。精通各种枪械使用、战术撤退和隐蔽技巧，在面对村民时，你就是降维打击的特种兵。", type: "exclusive"},
            {name: "社团游戏胜者", color: "C", cost: 150, desc: "你非常擅长各种桌游和心理博弈。这让你能迅速融入前原圭一所在的社团，通过赢得游戏来换取这些核心人物的信任和保护。", type: "exclusive"},
            {name: "因果破碎者", color: "SS", cost: 8500, desc: "你每改变一个人的悲剧命运，就能获得大量的因果点数。如果你能阻止整个村庄的灭亡，你将直接获得SSS级的世界评价。", type: "exclusive"},
            {name: "羽入的羽毛", color: "SSS", cost: 32000, desc: "你拥有一根神明的羽毛，可以让你在当前世界内强行开启一次‘全图视野’，看清所有阴谋者的位置和行动路线。代价是因果值清零。", type: "exclusive"},
            {name: "雏见泽通", color: "D", cost: 80, desc: "你对雏见泽的地形了如指掌。所有的暗道、防空洞和逃生路径都在你脑海中，这让你在被全村追捕时依然能游刃有余。", type: "exclusive"},
            {name: "惨剧触发干涉", color: "S", cost: 3000, desc: "你可以通过一些微小的举动，延迟或取消某个特定‘惨剧’的发生。虽然这可能会引发新的不可测后果，但它是打破轮回的关键。", type: "exclusive"},
            {name: "神杀之愿", color: "SSS", cost: 50000, desc: "你拥有终结这个轮回世界的意志。你可以彻底杀死那些干涉轮回的高维存在，代价是你将永远无法离开这个世界，成为新的秩序守护者。", type: "exclusive"}
        ]
    },
    {
        name: "117.未来日记",
        desc: "为了争夺‘神’的宝座，12位持有能够预知未来的‘未来日记’的人展开了生存游戏。在这个充满背叛、疯狂和爱欲的战场，作为偷渡者的你，是沦为牺牲品，还是成为最后的幸存者？",
        boss: "我妻由乃, 宙斯(Deus Ex Machina), 姆鲁姆鲁",
        identities: [
            { name: "路边被卷入爆炸的倒霉路人", items: "一个碎掉的手机屏, 一只断掉的鞋带" },
            { name: "樱见中学的一名普通学生", items: "一本没写名字的数学作业, 一个半旧的MP3" },
            { name: "被邪教组织洗脑的最底层信徒", items: "一张印着奇怪符号的传单, 一块劣质的木制挂坠" },
            { name: "伦敦街头的流浪杀手学徒", items: "一把生锈的折叠刀, 一张印着目标的照片" },
            { name: "市役所的临时清洁工", items: "一个破烂的扫帚, 一瓶刺鼻的消毒水" }
        ],
        talents: [
            {name: "第13号日记持有者", color: "SS", cost: 9600, desc: "你获得了一部名为‘偷渡者日记’的未来日记。它能预知周围100米内所有因果变动，且不会被其他日记持有者感知到。这是你夺取神位的核心资本。", type: "exclusive"},
            {name: "由乃的迷之好感", color: "S", cost: 4500, desc: "不知为何，我妻由乃对你产生了一种类似‘弟弟/妹妹’的保护欲。只要你不触碰她的底线（雪辉），她将是你这个世界最强的挡箭牌。", type: "exclusive"},
            {name: "观测者视角", color: "A", cost: 1800, desc: "你能看到其他日记持有者的日记内容摘要。这让你在面对他们时拥有绝对的情报优势，能针对性地制造‘DEAD END’。", type: "exclusive"},
            {name: "生存本能(极强)", color: "B", cost: 550, desc: "在面临致命危险时，你的身体会先于大脑做出反应。无论是子弹还是爆炸，你总能以最小的代价避开要害，生存率大幅提升。", type: "exclusive"},
            {name: "心理操控术", color: "A", cost: 1200, desc: "你擅长利用人们对死亡的恐惧进行心理暗示。通过几句简单的诱导，你可以让其他持有者互相残杀，而你则坐收渔翁之利。", type: "exclusive"},
            {name: "爆破专家训练", color: "B", cost: 650, desc: "你对各种简易爆炸物的制作和拆除有着惊人的天赋。在这个动不动就炸大楼的世界，这项技能能让你在攻防两端都极具威胁。", type: "exclusive"},
            {name: "因果点数劫持", color: "SS", cost: 8000, desc: "每当你亲手淘汰一名日记持有者，你可以强行掠夺其日记的部分功能作为你的临时技能，直到当前世界结算为止。", type: "exclusive"},
            {name: "神之代理人(伪)", color: "S", cost: 3000, desc: "宙斯允许你在一定范围内借用他的神力。这让你能短暂停滞时间或修改物理规则，但每次使用都会大幅降低你的因果锚定等级。", type: "exclusive"},
            {name: "电子入侵天才", color: "C", cost: 250, desc: "你精通手机系统和网络协议。你可以通过黑客手段干扰他人的日记接收信号，制造假情报，从而诱导对手走向错误的未来。", type: "exclusive"},
            {name: "绝对冷静的杀意", color: "A", cost: 1400, desc: "在你决定杀人时，你的心率和体温会降至冰点，无法被任何探测设备或直觉感知。你是天生的暗杀者，是所有持有者的噩梦。", type: "exclusive"},
            {name: "姆鲁姆鲁的零食摊", color: "D", cost: 90, desc: "你特别擅长制作美味的甜点。如果你能用这些甜点收买那个贪玩的姆鲁姆鲁，她或许会在规则允许的范围内给你开点小灶。", type: "exclusive"},
            {name: "平行世界干涉", color: "SSS", cost: 48000, desc: "你可以在当前世界召唤一个来自平行时空的‘自己’协助战斗。对方拥有你所有的遗产和技能，存在时间取决于你的精神力上限。", type: "exclusive"},
            {name: "DEAD END 抹除", color: "S", cost: 5000, desc: "当你的日记显示‘DEAD END’时，你可以消耗大量积分强行强行抹除这一结局。世界线会发生剧烈震荡，为你争取到改变命运的5分钟。", type: "exclusive"},
            {name: "因果锚定锁定", color: "SS", cost: 8800, desc: "一旦你达到A级锚定，你的等级将不再因死亡读档而下降。这让你可以在高等级状态下反复尝试各种极端的通关路径。", type: "exclusive"},
            {name: "神位的篡夺者", color: "SSS", cost: 80000, desc: "你掌握了杀死神的方法。在游戏的最后阶段，你可以选择取代宙斯成为新的神，直接掌控这个世界的所有法则和因果。", type: "exclusive"}
        ]
    },
    {
        name: "118.只有神知道的世界",
        desc: "舞岛学园，恋爱游戏的顶尖高手桂木桂马在这里攻略现实中的少女。作为偷渡者，你发现这个世界并不只有恋爱，还有潜伏在少女心灵空隙中的‘驱魂’。你必须在恋爱与战斗之间找到平衡。",
        boss: "旧地狱的恶魔,  Weiss(白亚), 正统恶魔社",
        identities: [
            { name: "学园里的路人甲男同学", items: "一叠没发下去的传单, 一个印着校徽的旧水壶" },
            { name: "游戏厅里的最底层代练", items: "一个磨损严重的摇杆, 几枚生锈的代币" },
            { name: "地狱派遣协会的实习杂役", items: "一个坏掉的驱魂探测器, 一件不合身的制服" },
            { name: "图书馆里的孤僻图书管理员", items: "一本写满不知名笔记的旧书, 一把生锈的钥匙" },
            { name: "在学园祭卖章鱼烧的摊贩", items: "一个油腻腻的围裙, 一把翻动章鱼烧的铁签" }
        ],
        talents: [
            {name: "攻略之神的真传", color: "S", cost: 3200, desc: "你掌握了桂木桂马的部分攻略理论。你能精准识别出少女心灵的‘空隙’，并制定出完美的攻略计划，这对于收割因果极其有效。", type: "exclusive"},
            {name: "驱魂捕捉术(高效)", color: "A", cost: 1200, desc: "你拥有一种特殊的能量网，能比普通恶魔更高效地捕捉被逼出的驱魂。每捕捉一只驱魂，你都能获得可观的系统积分和属性加成。", type: "exclusive"},
            {name: "心灵空隙填补者", color: "B", cost: 500, desc: "你天生擅长安抚他人的负面情绪。即便不进行恋爱攻略，你也能通过友情或关怀填补少女的心灵空隙，稳定世界因果。", type: "exclusive"},
            {name: "2D/3D 视界切换", color: "A", cost: 1500, desc: "你可以将现实世界在你的眼中转化为恋爱养成游戏的界面。所有NPC的好感度、立绘和对话选项都清晰可见，让你立于不败之地。", type: "exclusive"},
            {name: "地狱黑科技装备", color: "S", cost: 2800, desc: "你拥有一套来自新地狱的先进装备，包括隐身斗篷和高速飞行羽衣。这让你在面对旧地狱恶魔时拥有极强的生存和反击能力。", type: "exclusive"},
            {name: "背景板潜行术", color: "C", cost: 180, desc: "你极度缺乏存在感，即便在重要NPC面前走过也不会被察觉。这是偷听机密、收集情报和躲避恶魔搜捕的神级天赋。", type: "exclusive"},
            {name: "因果羁绊收割", color: "SS", cost: 7800, desc: "每当你与一名重要女性角色达成深度羁绊，你将永久获得其一项核心天赋的复制版。多线攻略能让你迅速成为全能型强者。", type: "exclusive"},
            {name: "艾鲁西的迷之料理", color: "D", cost: 50, desc: "你拥有钢铁般的胃，能吃下艾鲁西制作的任何东西。这让你有几率获得地狱生物的体质加成，或者干脆产生某种奇妙的毒素抗性。", type: "exclusive"},
            {name: "女神的祝福(微弱)", color: "S", cost: 4000, desc: "你曾意外帮助过一位寄宿在少女体内的女神。她赋予了你一种神圣力量，能大幅增强你对恶魔魔法的防御力，并提升你的魅力值。", type: "exclusive"},
            {name: "多线程处理大脑", color: "A", cost: 1100, desc: "你能同时处理多个复杂的任务而不出错。无论是同时攻略多名少女，还是在战斗中计算敌人的每一个动作，你都能游刃有余。", type: "exclusive"},
            {name: "旧地狱的禁忌知识", color: "SS", cost: 8500, desc: "你掌握了一些关于地狱重组和驱魂起源的禁忌知识。这让你能与那些古老的恶魔进行交易，甚至在某种程度上操控驱魂的进化。", type: "exclusive"},
            {name: "因果锚定加速器", color: "B", cost: 700, desc: "在这个以情感波动为核心的世界，你的任何社交行为产生的锚定值都提升30%。这让你能比其他偷渡者更快地结束‘蝼蚁’生涯。", type: "exclusive"},
            {name: "结局修改权", color: "SSS", cost: 35000, desc: "你可以在攻略达到终点时，强行修改剧情的结局。无论是悲剧转喜剧，还是让原本离开的人留下，这种权柄涉及世界意志的变更。", type: "exclusive"},
            {name: "FLAG 探测器", color: "C", cost: 220, desc: "你能看到周围即将发生的‘事件标志’。这让你能精准避开那些会导致死亡或失败的恶性FLAG，并主动触发那些有益的奖励FLAG。", type: "exclusive"},
            {name: "诸神黄昏的序曲", color: "SSS", cost: 65000, desc: "你拥有引发世界性变革的力量。你可以选择彻底消灭地狱与人界的隔阂，或者建立新的秩序，你的一举一动都将决定亿万生灵的命运。", type: "exclusive"}
        ]
    },
    {
        name: "119.凉宫春日的忧郁",
        desc: "北高的一名普通高中生凉宫春日，却拥有着连她自己都不知道的、足以随意重塑世界的能力。资讯统合思念体、未来人、超能力者都围绕在她身边。作为偷渡者，你必须在不引起她注意的情况下，在这个极度不稳定的世界生存。",
        boss: "凉宫春日(无意识神), 朝仓凉子, 资讯统合思念体(激进派)",
        identities: [
            { name: "北高的一名普通路人学生", items: "一本写满涂鸦的教科书, 一个过期的午餐盒" },
            { name: "SOS团活动室外的清洁工", items: "一个脏兮兮的拖把, 一桶散发着消毒水味的污水" },
            { name: "闭锁空间里的无名‘神人’", items: "一个半透明的破碎面具, 一双光秃秃的手" },
            { name: "‘机关’里的最底层观测员", items: "一台老旧的信号接收器, 一本厚厚的观测日志" },
            { name: "电脑社里被压榨的社员", items: "一个满是灰尘的键盘, 一张写满BUG的代码单" }
        ],
        talents: [
            {name: "SOS团的秘密成员", color: "SS", cost: 9900, desc: "你成功混入了凉宫春日的视线。虽然你只是个‘打杂的’，但你获得了在这个不正常世界中保持‘常态’的特权，且极易触发核心因果。", type: "exclusive"},
            {name: "资讯操纵(初级)", color: "S", cost: 3000, desc: "你拥有与长门有希类似的资讯操纵能力。虽然只能修改一些微小的物理常数（如摩擦力、重力），但在战斗和逃跑时极具奇效。", type: "exclusive"},
            {name: "闭锁空间适应体", color: "A", cost: 1500, desc: "当凉宫春日心情不好产生闭锁空间时，你不仅能自由出入，还能在其中保持完整的战力和意识，甚至能通过击杀‘神人’获取积分。", type: "exclusive"},
            {name: "存在感抹除(神级)", color: "S", cost: 4500, desc: "你将自己从凉宫春日的‘兴趣名单’中彻底抹除。即便你当着她的面炸掉大楼，她也会自动将其解释为‘普通的自然现象’而不去深究。", type: "exclusive"},
            {name: "未来人的导航仪", color: "B", cost: 600, desc: "你能感知到时空的细微波动。这让你能精准避开那些被封锁的时间节点，或者在混乱的时空跳跃中找到回到‘现在’的正确路径。", type: "exclusive"},
            {name: "超能力爆发(潜力)", color: "A", cost: 1800, desc: "当你处于极度情绪波动时，能释放出足以摧毁闭锁空间的强大能量。虽然使用后会陷入虚弱，但这是你面对资讯体攻击时的唯一反击手段。", type: "exclusive"},
            {name: "吐槽之魂(阿虚传承)", color: "C", cost: 150, desc: "你拥有一种奇特的能力，可以通过‘吐槽’来消解荒诞现实对你的精神冲击。只要你还在吐槽，你的理智值就不会归零。", type: "exclusive"},
            {name: "资讯同步率提升", color: "B", cost: 800, desc: "你与资讯统合思念体的同步率极高。这让你能直接读取世界背景中的底层代码，获取那些连未来人都不知道的禁忌情报。", type: "exclusive"},
            {name: "漫无止境的八月抗性", color: "SS", cost: 8500, desc: "在遭遇时间循环时，你的记忆不会被重置。这让你能在无数次重复中积累技能和属性，是利用世界规则进行‘刷级’的神技。", type: "exclusive"},
            {name: "朝比奈的茶点", color: "D", cost: 60, desc: "你特别擅长品茶。通过与朝比奈实玖瑠交流茶道，你可以获得她的信任，进而接触到关于未来组织的核心机密。", type: "exclusive"},
            {name: "因果锚定异常插件", color: "A", cost: 1200, desc: "由于你是不属于这个世界的资讯，你的锚定速度不受任何逻辑限制。只要你在春日面前露个脸，你的锚定等级就会疯狂跳动。", type: "exclusive"},
            {name: "资讯体反制程序", color: "S", cost: 3500, desc: "你掌握了一套专门针对资讯生命体的干扰代码。这能让那些试图解析你灵魂的资讯体陷入逻辑死循环，为你争取逃生时间。", type: "exclusive"},
            {name: "愿望具现(极微弱)", color: "SSS", cost: 55000, desc: "你无意中窃取了一丝凉宫春日的权能。你的强烈愿望有极小概率直接改变现实。虽然不可控，但在生死关头它是真正的神迹。", type: "exclusive"},
            {name: "三味线的指引", color: "C", cost: 200, desc: "那只花猫偶尔会开口对你说话。它提供的信息往往涉及世界的真相，虽然语气傲慢，但却能帮你避开致命的剧情杀。", type: "exclusive"},
            {name: "世界重塑的见证者", color: "SSS", cost: 90000, desc: "你成为了决定世界走向的关键变量。在春日决定重塑世界时，你可以选择保留哪些部分，或者干脆将自己设定为新世界的‘神’。", type: "exclusive"}
        ]
    },
    {
        name: "120.CLANNAD",
        desc: "光坂小镇，一段关于家族、梦想与成长的故事。在这个看似平凡的世界里，隐藏着名为‘光玉’的奇迹。偷渡者在这里的目标不是战斗，而是通过收集人们的幸福，去触碰那个名为‘幻想世界’的真相。",
        boss: "命运(无形), 这里的BOSS是‘遗憾’与‘死亡’",
        identities: [
            { name: "光坂高中的不良少年", items: "一盒干瘪的香烟, 一个印着骷髅的打火机" },
            { name: "古河面包店的临时搬运工", items: "一个装满滞销面包的纸袋, 一件沾满面粉的外套" },
            { name: "街头流浪的卖艺人", items: "一把断了一根弦的木吉他, 一个破旧的帽子" },
            { name: "光坂小镇的电力维修学徒", items: "一个沉重的工具包, 一双绝缘手套" },
            { name: "废弃工厂里的流浪汉", items: "一个破烂的睡袋, 一个用来取暖的生锈铁桶" }
        ],
        talents: [
            {name: "光玉收集者", color: "SS", cost: 9500, desc: "每当你让一个重要角色获得真正的幸福，你将获得一颗‘光玉’。光玉可以实现任何愿望，包括死而复生或彻底改变世界线的悲剧走向。", type: "exclusive"},
            {name: "幻想世界的链接", color: "S", cost: 3800, desc: "你的意识能偶尔连接到那个荒凉的‘幻想世界’。这让你能与那个世界的少女交流，获取关于生命本源和世界真相的终极情报。", type: "exclusive"},
            {name: "家族的羁绊", color: "A", cost: 1200, desc: "你拥有一种能迅速融入任何家庭的天赋。这种深度的情感联结能为你提供极强的精神防御，并大幅提升你在小镇中的因果锚定等级。", type: "exclusive"},
            {name: "绝对的厨艺天赋(秋生传承)", color: "B", cost: 450, desc: "你做出的食物拥有治愈心灵的力量。通过经营一家小餐馆或在面包店帮忙，你可以迅速收割小镇居民的好感度和锚定点。", type: "exclusive"},
            {name: "悲剧预知", color: "A", cost: 1400, desc: "你能感知到即将发生的悲剧（如疾病、车祸）。虽然无法直接阻止，但它给了你提前布局、寻找光玉救赎的机会。", type: "exclusive"},
            {name: "光坂小镇的守护灵", color: "S", cost: 2500, desc: "小镇的意志在护佑着你。在光坂范围内，你的运气始终保持在极高水平，且更容易触发那些涉及核心剧情的奇遇任务。", type: "exclusive"},
            {name: "强健的体魄(朋也传承)", color: "C", cost: 200, desc: "虽然你是‘蝼蚁’开局，但你拥有远超常人的毅力和耐力。无论生活多么艰苦，你都能坚持下去，这对于前期积累资源至关重要。", type: "exclusive"},
            {name: "演剧部的天才导演", color: "B", cost: 550, desc: "你对戏剧和舞台有着独特的理解。通过组织一场完美的演出，你可以让人们在感悟人生中产生大量的幸福感，从而批量产出光玉。", type: "exclusive"},
            {name: "因果锚定加速(情感向)", color: "A", cost: 1100, desc: "在这个以情感为核心的世界，你的任何社交行为产生的锚定值都提升50%。这让你能以最快速度脱离底层身份，进入核心社交圈。", type: "exclusive"},
            {name: "小镇历史通", color: "D", cost: 70, desc: "你对光坂小镇的每一条街道、每一个传说都了如指掌。这让你在寻找特定人物或逃避某些尴尬场面时拥有天然的优势。", type: "exclusive"},
            {name: "奇迹的观测者", color: "SS", cost: 8200, desc: "你拥有见证奇迹的资格。当奇迹发生时，你可以强行抽取其中的能量，将其转化为永久的遗产点数，带入下一个世界。", type: "exclusive"},
            {name: "心灵感应(微弱)", color: "B", cost: 480, desc: "你能模糊感受到他人的喜怒哀乐。这让你在攻略角色或处理矛盾时总能选出最正确的选项，避免好感度滑坡。", type: "exclusive"},
            {name: "光之螺旋", color: "SSS", cost: 45000, desc: "你掌握了操控光玉能量的方法。你可以强行逆转时间，回到悲剧发生前的任何时刻，且不需要消耗系统的读档机会。", type: "exclusive"},
            {name: "团子大家族之歌", color: "C", cost: 150, desc: "你会唱那首神奇的歌。它能迅速拉近你与古河一家的距离，并让你在精神疲惫时快速恢复理智值和体力。", type: "exclusive"},
            {name: "世界意志的代行者", color: "SSS", cost: 99999, desc: "你成为了光坂小镇意志的化身。你可以决定谁获得幸福，谁遭遇不幸。你在这个世界的存在本身，就是最大的奇迹。", type: "exclusive"}
        ]
    },
                      {
                name: "121.Angel Beats!",
                desc: "一个只有死者才能抵达的死后世界学园。这里聚集着生前抱有遗憾的少年少女，他们为了反抗命运和“神”而组建了死后世界战线（SSS）。在这里虽然不会真正死亡，但若感到满足就会消失（转生）。",
                boss: "立华奏（天使）, 影之NPC, 谜之程序员",
                identities: [
                    { name: "刚苏醒的失忆者", items: "一套死后世界学园制服, 一个空空如也的脑子" },
                    { name: "SSS战线的新人杂兵", items: "一把做工粗糙的土制手枪, 一张战线招募传单" },
                    { name: "NPC学生A", items: "永远写不完的作业本, 一个普通的书包" },
                    { name: "地下兵工厂的苦力", items: "满手的机油污渍, 一把用来铲土的铲子" },
                    { name: "食堂的兼职帮工", items: "一张麻婆豆腐的优惠券, 沾满辣油的围裙" }
                ],
                talents: [
                    {name: "死后体质", color: "C", cost: 150, desc: "在这个世界你是不死之身。无论受到多重的伤，只要过一段时间就能自动复原，但疼痛感是真实的，且衣服不会复原。", type: "exclusive"},
                    {name: "Handsonic(音速手刃)", color: "A", cost: 1200, desc: "利用软件覆写能力在手背生成光剑。虽然是基础技能，但切割力极强，能轻易切开钢铁，有多种形态变化。", type: "exclusive"},
                    {name: "Distortion(扭曲)", color: "S", cost: 1800, desc: "在受到攻击的瞬间扭曲所在的空间，让子弹和物理攻击发生偏转。是绝对防御级别的技能，但需要极高的计算力。", type: "exclusive"},
                    {name: "Harmonics(分身)", color: "SS", cost: 8000, desc: "制造出与本体意识独立的实体分身。分身往往会继承本体某种极端的性格，若无法回收，分身可能会反客为主。", type: "exclusive"},
                    {name: "Angel Player(编程者)", color: "SSS", cost: 25000, desc: "掌握了改写这个世界底层逻辑的软件。你可以像神一样凭空创造武器、改变地形，甚至赋予自己新的技能。", type: "exclusive"},
                    {name: "生前的遗憾", color: "D", cost: 80, desc: "你保留了生前强烈的遗憾。这会让你在这个世界更有动力行动，但如果遗憾被满足，你可能会直接强制超度（Game Over）。", type: "exclusive"},
                    {name: "麻婆豆腐耐性", color: "C", cost: 100, desc: "你的味觉经过特殊强化，能够面不改色地吃下名为“超辣麻婆豆腐”的生化武器，并从中获得极大的满足感。", type: "exclusive"},
                    {name: "GDM死忠粉", color: "B", cost: 300, desc: "作为Girls Dead Monster的狂热粉丝，你在听到她们的摇滚乐时，肾上腺素激增，全属性暂时提升20%。", type: "exclusive"},
                    {name: "由理的领导力", color: "A", cost: 900, desc: "你拥有像仲村由理一样的领袖气质，即使是再荒谬的作战计划，也能忽悠一帮人跟着你一起去送死。", type: "exclusive"},
                    {name: "日向的接球", color: "B", cost: 450, desc: "在关键时刻，你总能像日向一样挺身而出，接住队友（或者各种奇怪东西）的传球，并大概率会因此遭遇不幸。", type: "exclusive"},
                    {name: "影之操纵", color: "SS", cost: 6500, desc: "你可以操纵那些吞噬NPC的黑影。将它们转化为自己的士兵，或者将敌人同化为没有意识的NPC。", type: "exclusive"},
                    {name: "枪械改造(土法)", color: "C", cost: 180, desc: "利用地下的尘土和记忆中的构造，能够凭空捏造出能用的枪械弹药，虽然精度感人，但胜在量大管饱。", type: "exclusive"},
                    {name: "催眠术(伪)", color: "B", cost: 250, desc: "模仿直井文人的技能，能够对意志薄弱的NPC进行简单的心理暗示，让他们把你当成神或者学生会长。", type: "exclusive"},
                    {name: "火箭推进器", color: "A", cost: 700, desc: "在背部生成推进装置，赋予你极高的机动性和飞行能力。配合近战武器使用，效果拔群。", type: "exclusive"},
                    {name: "爱的奇迹", color: "S", cost: 1500, desc: "即使在这个无法生育、没有未来的死后世界，你也能通过真挚的情感引发奇迹，甚至改变世界既定的规则。", type: "exclusive"}
                ]
            },
            {
                name: "122.紫罗兰永恒花园",
                desc: "一个刚结束了漫长战争的大陆。人们利用名为“自动手记人偶”的职业来代写书信，传递真情。这是一个关于爱、战争创伤与语言力量的蒸汽朋克风格世界。",
                boss: "吉尔伯特·布甘比利亚, 迪特福利特, 反和平派激进分子",
                identities: [
                    { name: "莱顿沙夫特里希的退伍伤兵", items: "一枚磨损的军功章, 一根拐杖" },
                    { name: "C.H.邮政公司的见习邮递员", items: "一辆嘎吱作响的自行车, 一大包未送达的信件" },
                    { name: "乡下的文盲农夫", items: "一把锄头, 一封看不懂的家书" },
                    { name: "加尔达利克帝国的战俘", items: "沉重的脚镣, 对战争的仇恨" },
                    { name: "人偶养成学校的落榜生", items: "一支钢笔, 一张不及格的打字测试卷" }
                ],
                talents: [
                    {name: "战争机器", color: "S", cost: 1800, desc: "你曾是战场上的杀戮工具。拥有极其恐怖的近战格斗能力和对杀气的敏锐感知，能徒手撕裂敌人，但情感淡漠。", type: "exclusive"},
                    {name: "义肢适配", color: "B", cost: 400, desc: "你的身体对机械义肢有极好的适应性。装备义肢时，不仅没有排异反应，力量和灵巧度反而比原装肢体更强。", type: "exclusive"},
                    {name: "人偶的打字术", color: "C", cost: 180, desc: "你的手指灵活度惊人，使用打字机时能达到肉眼无法捕捉的速度，且绝不打错字，适合从事文职或精细操作。", type: "exclusive"},
                    {name: "共情能力", color: "A", cost: 800, desc: "你能敏锐地察觉他人话语背后隐藏的真实情感（真心话）。这对于代笔写信或攻略人物有着决定性的作用。", type: "exclusive"},
                    {name: "少佐的胸针", color: "C", cost: 120, desc: "你拥有一个祖母绿色的胸针。虽然没有特殊属性，但看着它能让你在绝望中感到一丝安心，精神抗性微弱提升。", type: "exclusive"},
                    {name: "布甘比利亚家纹", color: "A", cost: 950, desc: "你拥有名门望族的血统或信物。在莱顿沙夫特里希拥有极高的社会地位，军队和贵族都会给你几分薄面。", type: "exclusive"},
                    {name: "战场直觉", color: "B", cost: 500, desc: "在枪林弹雨中磨练出的第六感。能够本能地预判炮击落点和敌人的伏击方向，大大提高生存率。", type: "exclusive"},
                    {name: "语言天才", color: "B", cost: 350, desc: "你精通大陆上各国的语言和方言。无论是外交辞令还是市井黑话，你都能信手拈来，沟通无障碍。", type: "exclusive"},
                    {name: "创伤后应激障碍(PTSD)", color: "D", cost: 50, desc: "战争给你留下了不可磨灭的阴影。听到巨大的声响或看到火光时，你有概率陷入恐慌或暴走状态。", type: "exclusive"},
                    {name: "爱的理解者", color: "SS", cost: 5000, desc: "你深刻理解“爱”的含义。你的文字和话语拥有治愈灵魂的力量，能让最冷酷的杀手流泪，让最深的仇恨化解。", type: "exclusive"},
                    {name: "精良机械臂(金刚石)", color: "S", cost: 1600, desc: "你的双臂被改造为高强度的金刚石机械臂。硬度足以抵挡步枪子弹，握力能捏碎岩石，内置小型火器。", type: "exclusive"},
                    {name: "邮递员的耐力", color: "C", cost: 150, desc: "为了送信，你练就了一双铁脚板。无论翻山越岭还是穿越无人区，你的体能消耗都比常人慢得多。", type: "exclusive"},
                    {name: "绝美声线", color: "C", cost: 200, desc: "你的声音如同天籁，听者会不自觉地对你产生好感。这在交涉、安抚或进行人偶工作时有额外加成。", type: "exclusive"},
                    {name: "和平主义者的信念", color: "A", cost: 600, desc: "你坚信不再需要燃烧。在非战斗状态下，你身上散发着让人平静的气场，敌对阵营的人物也不会轻易攻击你。", type: "exclusive"},
                    {name: "传说中的人偶", color: "SS", cost: 4500, desc: "你的名声传遍大陆，各国皇室都指名要求你代笔。你的名字本身就是一种通行证，能调动巨大的社会资源。", type: "exclusive"}
                ]
            },
            {
                name: "123.辉夜大小姐想让我告白",
                desc: "秀知院学园，云集了未来国家栋梁的精英学校。在这里，恋爱即战争！谁先告白谁就输了！这是一场关于自尊心、头脑战与纯情的恋爱喜剧。",
                boss: "四宫雁庵, 四宫家财团, 早坂爱(全盛期)",
                identities: [
                    { name: "靠奖学金入学的混院学生", items: "破旧的课本, 每天带的便当" },
                    { name: "学生会的一般会计", items: "算盘, 堆积如山的发票" },
                    { name: "四宫家的临时佣人", items: "女仆装/执事服, 严格的保密协议" },
                    { name: "拉面四天王的崇拜者", items: "一碗吃剩的豚骨拉面, 拉面探店笔记" },
                    { name: "桌游部的幽灵部员", items: "奇怪的骰子, 没人玩的桌游" }
                ],
                talents: [
                    {name: "四宫之血", color: "S", cost: 1900, desc: "你拥有四宫家的血统。虽然可能只是旁系，但依然拥有极高的智商和冷酷的商业头脑，以及令人畏惧的眼神。", type: "exclusive"},
                    {name: "真是可爱呢", color: "A", cost: 800, desc: "你擅长在心理战中通过嘲讽、装傻或卖萌来击溃对手的心理防线。这一招对自尊心强的人有特攻。", type: "exclusive"},
                    {name: "恋爱侦探", color: "B", cost: 400, desc: "你像藤原千花一样，对恋爱八卦有着敏锐的嗅觉。虽然给出的建议往往不靠谱，但能大概率触发特殊恋爱事件。", type: "exclusive"},
                    {name: "学年第一的头脑", color: "S", cost: 1500, desc: "你拥有白银御行级别的努力和智力。只要通过拼命学习，你能在任何学术考试中拿第一，但身体负担极重。", type: "exclusive"},
                    {name: "绝对富豪", color: "SS", cost: 6000, desc: "你的家族资产富可敌国。你可以动用私人飞机上学，买下整个游乐园，金钱能解决这个世界99%的问题。", type: "exclusive"},
                    {name: "早坂的女仆术", color: "A", cost: 1200, desc: "你掌握了顶级的女仆/执事技能。包括但不限于格斗、黑客、易容、飙车和泡咖啡。你是全能的辅助角色。", type: "exclusive"},
                    {name: "真男人", color: "B", cost: 600, desc: "像石上优一样，虽然平时看起来阴沉，但在关键时刻能展现出惊人的勇气和正义感，容易获得隐藏角色的好感。", type: "exclusive"},
                    {name: "特训狂魔", color: "C", cost: 180, desc: "为了克服弱点，你能进行非人的特训。虽然过程极其丢脸且痛苦，但最终能掌握如排球、唱Rap等技能。", type: "exclusive"},
                    {name: "混乱之源", color: "C", cost: 150, desc: "你就像桌游部一样，总是能搞出一些打破常规的奇怪游戏或规则，让原本严肃的头脑战变成混沌的闹剧。", type: "exclusive"},
                    {name: "外交官子女", color: "B", cost: 500, desc: "你精通多国语言，拥有海外背景。在处理跨文化交流或涉及外国势力时，你有天然的优势。", type: "exclusive"},
                    {name: "辉夜姬的冰冷", color: "A", cost: 750, desc: "你可以随时切换到“冰雕模式”。在这个状态下，你的理智达到顶峰，免疫一切精神干扰，但无法理解情感。", type: "exclusive"},
                    {name: "拉面通", color: "C", cost: 100, desc: "你对拉面有着神圣的追求。这不仅能让你找到最好吃的店，还能让你通过请客拉面结交各路奇怪的大佬。", type: "exclusive"},
                    {name: "相思病", color: "D", cost: 60, desc: "你无可救药地爱上了某人。这会让你在面对TA时智商归零（降至E级），但在保护TA时战斗力爆表。", type: "exclusive"},
                    {name: "学生会长的威严", color: "A", cost: 900, desc: "佩戴金饰绳时，你拥有统率全校学生的威严。你的命令会被大多数学生无条件执行，是权力的象征。", type: "exclusive"},
                    {name: "超高校级的旁白", color: "SS", cost: 3500, desc: "你能听到世界的旁白声音。这让你能洞悉对手的心理活动（今日胜负），甚至预知接下来的剧情走向。", type: "exclusive"}
                ]
            },
            {
                name: "124.间谍过家家 (Spy x Family)",
                desc: "东国与西国处于冷战状态。为了维护和平，代号“黄昏”的间谍组建了一个虚假家庭。父亲是间谍，母亲是杀手，女儿是超能力者。一个温馨又惊险的家庭喜剧。",
                boss: "多诺万·戴斯蒙, 花园店长, 秘密警察局长",
                identities: [
                    { name: "伊甸学园的平民学生", items: "优雅的校服, 一颗想拿星星的心" },
                    { name: "伯林特市的普通上班族", items: "公文包, 永远做不完的报表" },
                    { name: "不知名组织的低级线人", items: "藏在鞋底的密信, 随时准备跑路的现金" },
                    { name: "被实验的孤儿", items: "编号铭牌, 破旧的玩偶" },
                    { name: "市政府的清洁工", items: "扫帚, 听到了不该听的秘密" }
                ],
                talents: [
                    {name: "读心术(超能力)", color: "SSS", cost: 22000, desc: "像阿尼亚一样，你能直接听到周围人的心声。这是获取情报的神技，但在人多的地方会因为信息过载而流鼻血。", type: "exclusive"},
                    {name: "荆棘公主(杀手)", color: "SS", cost: 9000, desc: "你拥有约尔级别的身体素质。力量大到能踢飞汽车，毒抗极高，擅长使用针状武器进行无声暗杀。", type: "exclusive"},
                    {name: "黄昏(千面间谍)", color: "SS", cost: 9500, desc: "你是全能的间谍大师。易容术达到完美境界，过目不忘，精通战斗、拆弹、心理学和烹饪，几乎没有弱点。", type: "exclusive"},
                    {name: "预知未来(邦德)", color: "S", cost: 1800, desc: "你能看到未来几秒到几分钟的画面片段。这能让你规避致命危险，但未来是可以改变的，且画面可能不完整。", type: "exclusive"},
                    {name: "优雅(Elegance)", color: "A", cost: 800, desc: "你的举止极其优雅，能获得亨德森老师的高度赞赏。在伊甸学园，优雅就是力量，能让你免受很多麻烦。", type: "exclusive"},
                    {name: "秘密警察", color: "A", cost: 1200, desc: "你隶属于东国保安局。拥有极高的拷问技巧和反间谍意识，对姐姐/妹妹有着病态的执着（可选）。", type: "exclusive"},
                    {name: "次子的傲娇", color: "B", cost: 400, desc: "你是大人物的孩子，虽然态度傲慢，但内心单纯。这种反差萌容易吸引奇怪的人（如读心者）的注意。", type: "exclusive"},
                    {name: "杀人料理", color: "D", cost: 50, desc: "你做的饭菜外观正常，但吃下去会导致昏迷甚至濒死体验。适合作为毒药使用，不适合生存。", type: "exclusive"},
                    {name: "情报商网", color: "A", cost: 1000, desc: "像弗兰基一样，你在地下世界有广泛的人脉。只要有钱，你就能搞到任何情报或稀奇古怪的发明。", type: "exclusive"},
                    {name: "雷电之拳", color: "B", cost: 500, desc: "经过特训的必杀技。虽然只是普通的一拳，但因为注入了强烈的情感和回旋力，威力惊人。", type: "exclusive"},
                    {name: "完全记忆", color: "S", cost: 1500, desc: "你拥有照相机般的记忆力。看一眼就能记住复杂的密码本、地图或人员名单，是间谍梦寐以求的天赋。", type: "exclusive"},
                    {name: "花园的修剪术", color: "S", cost: 1700, desc: "你师从传说中的杀手组织“花园”。你的剑术（或剪刀术）登峰造极，能将敌人像杂草一样清除。", type: "exclusive"},
                    {name: "花生爱好者", color: "C", cost: 100, desc: "你对花生有着异常的执着。吃到高品质花生时，心情值回满，全属性微量提升。", type: "exclusive"},
                    {name: "爆破专家", color: "B", cost: 600, desc: "你擅长制造和拆除各种炸弹。甚至能用面粉制造粉尘爆炸，利用环境进行爆破是你的拿手好戏。", type: "exclusive"},
                    {name: "戴斯蒙的威压", color: "SS", cost: 7000, desc: "你拥有极深的城府和让人无法看透的气场。即使什么都不做，周围的人也会对你感到恐惧和敬畏。", type: "exclusive"}
                ]
            },
            {
                name: "125.五等分的新娘",
                desc: "贫穷学霸上杉风太郎被聘为中野家五胞胎的家庭教师。这五个女孩长相一样但性格迥异，且都是濒临留级的笨蛋。这是一场关于学习、成长与选择的恋爱长跑。",
                boss: "中野丸尾, 零奈(过去的回忆), 期末考试",
                identities: [
                    { name: "濒临留级的同班同学", items: "一张0分的试卷, 补习班传单" },
                    { name: "蛋糕店的打工仔", items: "厨师帽, 一盒卖剩下的蛋糕" },
                    { name: "中野家的司机", items: "豪车钥匙, 墨镜" },
                    { name: "风太郎的债主", items: "欠条, 催债的扩音器" },
                    { name: "电影摄制组的龙套", items: "剧本残页, 盒饭" }
                ],
                talents: [
                    {name: "五胞胎感应", color: "S", cost: 1200, desc: "你拥有分辨五胞胎真身的超能力。即使她们换了发型、变了装，你也能通过“爱”一眼认出谁是谁。", type: "exclusive"},
                    {name: "学霸光环", color: "A", cost: 800, desc: "你拥有满分的学力。在教导他人时，能显著提高对方的智力属性，但你的情商可能会因此降低。", type: "exclusive"},
                    {name: "一花的演技", color: "B", cost: 500, desc: "你拥有影后级别的演技。能够完美掩饰自己的真实意图，甚至能模仿他人的声音和举止来搞事。", type: "exclusive"},
                    {name: "二乃的暴走机车", color: "B", cost: 450, desc: "你骑摩托车的技术一流，且性格直率冲动。在恋爱攻势上如同暴走的机车一样势不可挡，擅长直球攻击。", type: "exclusive"},
                    {name: "三玖的变装/历史宅", color: "C", cost: 300, desc: "你精通战国武将知识，且擅长变装潜入。在特定的历史话题或隐秘行动中能发挥奇效。", type: "exclusive"},
                    {name: "四叶的体能", color: "A", cost: 700, desc: "你拥有无限的体力和运动天赋。能轻松帮所有社团当外援，但因为不懂拒绝，容易把自己累垮。", type: "exclusive"},
                    {name: "五月的肉包怪", color: "C", cost: 200, desc: "你的食量惊人，且对美食毫无抵抗力。通过进食可以快速恢复体力和心情，但恩格尔系数极高。", type: "exclusive"},
                    {name: "零奈的伪装", color: "A", cost: 900, desc: "你可以扮演“过去的重要之人”。利用对方的回忆杀，对其造成巨大的心理冲击或好感度修正。", type: "exclusive"},
                    {name: "名医的医术", color: "S", cost: 1500, desc: "继承了中野丸尾的医术。在这个日常世界里，你是能够起死回生的神医，社会地位极高。", type: "exclusive"},
                    {name: "家庭教师的威严", color: "B", cost: 400, desc: "在面对不听话的学生时，你能散发出令人畏惧的气场，强制对方进入学习状态。", type: "exclusive"},
                    {name: "幸运色狼", color: "C", cost: 150, desc: "你总是会因为不可抗力遭遇福利事件（如摔倒、闯入浴室）。虽然能提升好感，但被当成变态的风险也很大。", type: "exclusive"},
                    {name: "照片中的誓言", color: "SS", cost: 3000, desc: "你拥有一张多年前的合照。这是命运的红线，持有它的人注定会与照片中的另一方产生深刻的羁绊。", type: "exclusive"},
                    {name: "绝对味觉", color: "B", cost: 350, desc: "你能分辨出任何料理的细微差别。这在攻略喜欢美食的角色（如五月）时是必杀技。", type: "exclusive"},
                    {name: "熬夜战神", color: "C", cost: 100, desc: "为了学习或打工，你可以连续几天不睡觉而保持精神。虽然会掉头发，但效率翻倍。", type: "exclusive"},
                    {name: "新娘的预知梦", color: "SSS", cost: 12000, desc: "你在梦中看到了未来的婚礼现场。你确切地知道谁是最终的新娘，这将彻底改变你的攻略策略。", type: "exclusive"}
                ]
            },
            {
                name: "126.路人女主的养成方法",
                desc: "御宅族安艺伦也为了制作最强的Galgame，集结了美术天才、轻小说新锐作家和一名不起眼的“路人”少女。这是一个关于创作、梦想与逐渐偏离路人属性的恋爱故事。",
                boss: "红坂朱音, 截稿日, 销量暴死",
                identities: [
                    { name: "丰之崎学园的普通宅男", items: "一堆Galgame光盘, 兼职打工的工资条" },
                    { name: "同人社团的跑腿", items: "社团看板, 卖不出去的同人本" },
                    { name: "红坂朱音的社畜编辑", items: "胃药, 24小时响个不停的手机" },
                    { name: "出海的同班同学", items: "游戏机, 借来的漫画书" },
                    { name: "漫展的彻夜排队者", items: "折叠椅, 能量饮料" }
                ],
                talents: [
                    {name: "路人属性(惠)", color: "SS", cost: 8500, desc: "你的存在感极低。即使站在别人面前也可能被无视，这让你成为最强的潜行者和情报收集者，但容易被遗忘。", type: "exclusive"},
                    {name: "柏木英理的画技", color: "S", cost: 1800, desc: "你拥有英梨梨级别的绘画天赋。你的插画能瞬间抓住宅男的心，但在截稿日前容易陷入自闭和黑化状态。", type: "exclusive"},
                    {name: "霞诗子的文笔", color: "S", cost: 1800, desc: "你拥有霞之丘诗羽级别的写作能力。你的剧本充满毒舌与黑暗，能让人读得胃痛却欲罢不能，擅长病娇描写。", type: "exclusive"},
                    {name: "制作人的热血", color: "A", cost: 800, desc: "像安艺伦也一样，你对二次元有着狂热的爱。你的热情能感染周围的天才，把她们拉入你的坑，组建最强社团。", type: "exclusive"},
                    {name: "红坂朱音的压榨", color: "S", cost: 2000, desc: "你拥有业界大佬的各种手段。能精准发掘新人的潜力，并用非人的手段压榨出她们的极限，虽然会被恨，但能出神作。", type: "exclusive"},
                    {name: "黑长直/金发双马尾特攻", color: "C", cost: 200, desc: "你对特定发型的角色有天然的好感度加成。在攻略对应属性的角色时，选项成功率提升。", type: "exclusive"},
                    {name: "绝对音感(美智留)", color: "B", cost: 600, desc: "你拥有非凡的音乐天赋。无论是作曲还是演奏，都能轻松驾驭，能为游戏创作出灵魂BGM。", type: "exclusive"},
                    {name: "程序猿的爆肝", color: "B", cost: 500, desc: "你精通编程脚本。为了赶进度，你可以连续一周只喝咖啡不睡觉，哪怕修出满屏BUG也能在发布前一秒搞定。", type: "exclusive"},
                    {name: "毒舌属性", color: "C", cost: 150, desc: "你说话带刺，虽然容易得罪人，但对于抖M体质的角色有奇效，且能精准吐槽剧情的不合理之处。", type: "exclusive"},
                    {name: "青梅竹马的败犬光环", color: "D", cost: 100, desc: "你是主角的青梅竹马。虽然开局好感度满，但总是因为犹豫不决而输给天降系，带有悲剧色彩。", type: "exclusive"},
                    {name: "腹黑策士", color: "A", cost: 750, desc: "你表面人畜无害，实则内心算计极深。能够不动声色地操控社团的人际关系，让事情朝着有利于你的方向发展。", type: "exclusive"},
                    {name: "消费观念崩坏", color: "D", cost: 50, desc: "你会毫不犹豫地把生活费全部花在手办和BD上。虽然精神富足，但现实中经常要吃土。", type: "exclusive"},
                    {name: "神之构图", color: "A", cost: 900, desc: "你在摄影或作画时，总能找到最色气、最能挑动人心的角度（如黑丝特写），作品销量保证。", type: "exclusive"},
                    {name: "现实逃避", color: "C", cost: 100, desc: "遇到困难时，你会躲进二次元的世界。虽然能恢复SAN值，但现实问题会越积越多。", type: "exclusive"},
                    {name: "Main Heroine(女主角)", color: "SSS", cost: 15000, desc: "你觉醒了真女主的属性。无论周围的天才多么耀眼，最终剧情都会围绕你展开，你会成为所有人心中无法替代的存在。", type: "exclusive"}
                ]
            },
            {
                name: "127.我的妹妹哪有这么可爱",
                desc: "原本关系冷淡的兄妹，因为哥哥偶然发现了妹妹是隐藏御宅族的秘密而开始有了交集。这是一个关于接纳、亲情（？）以及御宅族在社会中生存的故事。",
                boss: "高坂大介(老爸), 媒体的偏见, 伦理道德",
                identities: [
                    { name: "高坂家的邻居", items: "望远镜, 隔音耳塞" },
                    { name: "秋叶原的女仆咖啡厅顾客", items: "会员卡, 荧光棒" },
                    { name: "不知名的轻小说新人", items: "退稿信, 泡面" },
                    { name: "游戏公司的测试员", items: "满是BUG的游戏盘, 报告书" },
                    { name: "千叶县的普通高中生", items: "自行车, 书包" }
                ],
                talents: [
                    {name: "妹控(Siscon)", color: "S", cost: 2500, desc: "你对妹妹有着超越常理的执着。为了妹妹的愿望，你可以与世界为敌，甚至无视伦理道德。妹妹好感度获取速度翻倍。", type: "exclusive"},
                    {name: "人生咨询", color: "A", cost: 800, desc: "你擅长倾听他人的烦恼并给出（馊）主意。这会触发特定的“人生咨询”事件，是开启角色支线的关键。", type: "exclusive"},
                    {name: "模特的人脉", color: "B", cost: 600, desc: "像桐乃一样，你在模特界或时尚圈有人脉。这让你不仅衣品好，还能接触到上流社会的资源。", type: "exclusive"},
                    {name: "黑猫的诅咒", color: "B", cost: 500, desc: "你拥有中二病属性。能写出充满黑暗设定的设定集，且在使用诅咒（实际上是吐槽）时威力惊人。", type: "exclusive"},
                    {name: "土妹子变身", color: "C", cost: 200, desc: "你平时戴着土气的眼镜，但摘下眼镜稍微打扮一下就是绝世美女/帅哥。拥有双重身份的便利。", type: "exclusive"},
                    {name: "富家千金(沙织)", color: "S", cost: 1800, desc: "你其实是超级财团的大小姐。虽然平时装作普通的阿宅，但只要一个电话，就能调动巨大的财力和人力。", type: "exclusive"},
                    {name: "老爸的铁拳", color: "D", cost: 100, desc: "你的父亲极其严厉且讨厌御宅族。在家中藏匿宅物是一场惊心动魄的谍战，一旦被发现会面临物理制裁。", type: "exclusive"},
                    {name: "神圣黑猫骑士团", color: "C", cost: 150, desc: "你拥有一群忠诚的宅友。虽然战斗力不强，但在网络水军、情报搜集和线下应援方面是一股不可忽视的力量。", type: "exclusive"},
                    {name: "梅鲁鲁的洗脑歌", color: "C", cost: 120, desc: "你精通那首魔性的动画主题曲。唱出来可以对周围人进行精神污染，或者识别同类。", type: "exclusive"},
                    {name: "绫濑的小天使/病娇", color: "A", cost: 1000, desc: "你表面上是温柔的小天使，但对宅文化有极深的偏见。一旦黑化，战斗力（物理）极强，擅长回旋踢。", type: "exclusive"},
                    {name: "游戏高玩", color: "B", cost: 400, desc: "你是各类游戏的顶尖玩家。无论是格斗还是Galgame，你都能轻松通关，这在某些对决中是必胜法宝。", type: "exclusive"},
                    {name: "现充光环", color: "B", cost: 500, desc: "你在学校里是受欢迎的现充。这让你在普通人中有很高的话语权，但需要小心隐藏自己的宅属性。", type: "exclusive"},
                    {name: "限时誓言", color: "SS", cost: 3000, desc: "你与某人立下了“限时情侣”的誓言。在这段时间内，你们的羁绊会急速加深，但期限一到必须面临残酷的选择。", type: "exclusive"},
                    {name: "创作者的共鸣", color: "A", cost: 700, desc: "你能深刻理解同人作品背后的爱。这让你能轻易获得创作者的好感，并获得稀有的绝版周边。", type: "exclusive"},
                    {name: "近亲相爱", color: "SSS", cost: 20000, desc: "打破禁忌的天赋。你无视血缘的阻碍，能够与血亲达成真正的恋爱结局（True End），但这注定是一条充满荆棘的道路。", type: "exclusive"}
                ]
            },
            {
                name: "128.埃罗芒阿老师",
                desc: "高中生轻小说作家和泉正宗，发现自己的家里蹲妹妹竟然就是由于画风色气而闻名的插画师“埃罗芒阿老师”。这是一个围绕轻小说业界的恋爱喜剧。",
                boss: "千寿村征, 山田妖精(销量竞争), 妹妹的房门",
                identities: [
                    { name: "电击文库的底层作家", items: "退稿通知, 烂尾的大纲" },
                    { name: "书店的收银员", items: "条形码扫描枪, 畅销书海报" },
                    { name: "山田妖精豪宅的园丁", items: "修枝剪, 看到全裸妖精的记忆" },
                    { name: "和泉家的远房亲戚", items: "伴手礼, 备用钥匙" },
                    { name: "网络画师的狂热粉", items: "数位板, 满硬盘的涩图" }
                ],
                talents: [
                    {name: "光速码字", color: "A", cost: 800, desc: "你的打字速度快到键盘冒烟。只要有灵感，一天写完一卷轻小说不是梦，是赶稿期的神技。", type: "exclusive"},
                    {name: "色气画风", color: "S", cost: 1500, desc: "你拥有埃罗芒阿老师级别的画技。你画的角色极具诱惑力，能瞬间俘获读者的心，尤其是画不可描述的内容时。", type: "exclusive"},
                    {name: "家里蹲体质", color: "D", cost: 80, desc: "你极度抗拒出门。在房间里时全属性提升，一旦踏出房门，SAN值狂掉，社交能力归零。", type: "exclusive"},
                    {name: "妖精的钞能力", color: "SS", cost: 5000, desc: "像山田妖精一样，你是畅销书作家，家财万贯。你可以买下出版社，或者买下一座岛来写书。", type: "exclusive"},
                    {name: "义妹的洗衣机", color: "C", cost: 150, desc: "你擅长洗衣服（？）。在处理生活琐事上技能点满，能把家里打理得井井有条，是完美的家庭煮夫。", type: "exclusive"},
                    {name: "销量预测", color: "B", cost: 600, desc: "你看一眼大纲就能预测这本书能不能火。这让你在选题材时从不失手，是编辑眼中的摇钱树。", type: "exclusive"},
                    {name: "全裸写作", color: "C", cost: 200, desc: "你在全裸状态下灵感爆发，写作速度和质量大幅提升。但要注意别被警察抓走。", type: "exclusive"},
                    {name: "千寿村征的执着", color: "A", cost: 900, desc: "你对写作有着纯粹而偏执的热爱。为了写出好作品，你不惜牺牲一切，这种气魄能震慑住对手。", type: "exclusive"},
                    {name: "网络直播主", color: "B", cost: 400, desc: "你擅长在网上直播绘画或游戏。拥有大量粉丝，舆论引导能力强，但容易被开盒。", type: "exclusive"},
                    {name: "编辑的催稿", color: "B", cost: 500, desc: "你拥有神乐坂菖蒲那样的催稿能力。能精准找到作者的藏身之处，并用各种手段逼迫他们交稿。", type: "exclusive"},
                    {name: "梦想的共演", color: "S", cost: 1200, desc: "当作家和插画师心意相通时，作品会产生质的飞跃。能触发“动画化”甚至“社会现象级”作品的诞生。", type: "exclusive"},
                    {name: "地板咚", color: "C", cost: 100, desc: "你擅长用脚踩地板发出巨大的声响来表达不满。这是与楼下人交流的特殊摩斯密码。", type: "exclusive"},
                    {name: "绝对清纯", color: "A", cost: 700, desc: "尽管你画的是色气图，但你内心纯洁如白纸。这种反差让你对某些变态角色有天然的防御力。", type: "exclusive"},
                    {name: "料理达人", color: "B", cost: 300, desc: "为了照顾废柴妹妹/哥哥，你练就了一手好厨艺。美味的食物是打开心扉的钥匙。", type: "exclusive"},
                    {name: "业界顶点", color: "SSS", cost: 12000, desc: "你注定成为轻小说界的传说。你的作品将改变业界格局，成为后世教科书般的经典，名利双收。", type: "exclusive"}
                ]
            },
            {
                name: "129.食戟之灵",
                desc: "远月茶寮料理学园，名门料理学校。这里实行残酷的淘汰制，学生们通过“食戟”（料理对决）来解决纠纷。这里的料理美味到让人产生幻觉甚至衣服爆裂（衣襟绽裂）。",
                boss: "薙切蓟, 远月十杰, 神之舌",
                identities: [
                    { name: "远月学园的吊车尾学生", items: "E级退学通知书, 廉价的菜刀" },
                    { name: "大众食堂的帮厨", items: "油腻的头巾, 祖传的调料秘方" },
                    { name: "极星寮的住客", items: "房间钥匙, 私藏的食材" },
                    { name: "WGO的三等执行官", items: "美食手册, 挑剔的舌头" },
                    { name: "深夜料理人学徒", items: "黑市厨具, 违禁香料" }
                ],
                talents: [
                    {name: "神之舌", color: "SSS", cost: 30000, desc: "拥有神赐予的味觉。能分辨出料理中极其细微的味道差异，甚至能尝出厨师的心情。但也因此难以忍受平庸的食物。", type: "exclusive"},
                    {name: "衣襟绽裂(授衣)", color: "SS", cost: 8000, desc: "你的料理美味到能冲击人的精神，让食用者产生爆衣的幻觉（甚至物理爆衣）。这是料理美味度的最高证明。", type: "exclusive"},
                    {name: "幸平流·招待不周", color: "A", cost: 1200, desc: "你擅长用廉价食材做出顶级美味。拥有化腐朽为神奇的能力，且心态极好，遇强则强，永不言败。", type: "exclusive"},
                    {name: "分子料理", color: "S", cost: 2000, desc: "像爱丽丝一样，利用高科技仪器和化学原理进行烹饪。能创造出外观和口感完全颠覆常识的艺术品料理。", type: "exclusive"},
                    {name: "香料达人", color: "A", cost: 1500, desc: "你对香料的运用出神入化。能通过香气直接攻击评委的嗅觉，在还没入口前就先声夺人。", type: "exclusive"},
                    {name: "完美追踪(美作)", color: "A", cost: 1800, desc: "你能完美预测并模仿对手的料理步骤，并在最后一步进行改良超越。是让对手绝望的跟踪狂式战法。", type: "exclusive"},
                    {name: "极星寮的羁绊", color: "B", cost: 600, desc: "你拥有极星寮的伙伴。他们擅长熏制、野味、发酵等各种偏门料理，能为你提供稀有食材和技术支持。", type: "exclusive"},
                    {name: "食戟之灵", color: "B", cost: 500, desc: "在食戟对决中，你的斗志越高，料理的美味度加成越高。在绝境中往往能爆发出超越等级的实力。", type: "exclusive"},
                    {name: "必杀料理(Specialité)", color: "S", cost: 2500, desc: "你拥有一道属于自己的必杀菜品。这道菜凝聚了你的人生和哲学，一旦端出，同级之中几乎无敌。", type: "exclusive"},
                    {name: "黑暗料理界", color: "B", cost: 700, desc: "你掌握着深夜料理人的技术。擅长处理有毒食材或使用违禁调料，料理风格狂野且危险。", type: "exclusive"},
                    {name: "药膳大师", color: "A", cost: 1000, desc: "你的料理具有药用价值。不仅美味，还能调理身体，甚至能治愈某些疾病，深受年长评委喜爱。", type: "exclusive"},
                    {name: "神之鼻", color: "SS", cost: 9000, desc: "你的嗅觉极其灵敏。能闻出食材的产地、新鲜度甚至处理手法，是挑选食材和盲品的神技。", type: "exclusive"},
                    {name: "肌肉烹饪", color: "C", cost: 200, desc: "你做饭时喜欢展示肌肉。虽然有点辣眼睛，但强悍的力量能让你轻松处理坚硬的食材或进行长时间揉面。", type: "exclusive"},
                    {name: "失败作", color: "D", cost: 50, desc: "你经常尝试创新但搞出黑暗料理（如花生酱鱿鱼）。虽然难吃，但偶尔能给对手造成精神污染。", type: "exclusive"},
                    {name: "远月十杰席位", color: "SS", cost: 10000, desc: "你站在了学园的顶点。拥有巨大的权力和资源，可以随意发起食戟，决定学园的规则。", type: "exclusive"}
                ]
            },
            {
                name: "130.约会大作战",
                desc: "名为“空间震”的灾害肆虐世界，其元凶是名为“精灵”的美少女。为了拯救世界（和精灵），男主角必须与她们约会，让她们娇羞！",
                boss: "艾克, 始源精灵, DEM社",
                identities: [
                    { name: "来禅高中的普通学生", items: "校服, 恋爱模拟游戏机" },
                    { name: "AST的新兵", items: "显现装置(量产型), 战术目镜" },
                    { name: "拉塔托斯克的船员", items: "耳机, 选票按钮" },
                    { name: "DEM社的清洁工", items: "拖把, 捡到的魔术师碎片" },
                    { name: "避难所的常客", items: "应急口粮, 空间震警报器" }
                ],
                talents: [
                    {name: "封印之吻", color: "SSS", cost: 28000, desc: "五河士道的特权。通过接吻，你可以封印精灵的灵力并将其储存在自己体内，甚至能借用这些力量战斗。", type: "exclusive"},
                    {name: "天使显现", color: "SS", cost: 10000, desc: "你拥有精灵的力量，能召唤专属的“天使”（武器/防具）。威力巨大，足以对抗军队，但容易引发空间震。", type: "exclusive"},
                    {name: "刻古帝(Zafkiel)", color: "SS", cost: 12000, desc: "时崎狂三的天使。操控时间的能力，包括加速、减速、倒流。虽然消耗寿命，但是最强的功能性能力之一。", type: "exclusive"},
                    {name: "拉塔托斯克司令", color: "S", cost: 2500, desc: "你拥有空中战舰佛拉克西纳斯的指挥权。背后有强大的参谋团为你提供恋爱选项，虽然选项通常很坑。", type: "exclusive"},
                    {name: "显现装置(CR-Unit)", color: "A", cost: 1500, desc: "你装备了高科技的战斗装甲。能让你以人类之躯对抗精灵，拥有随意领域防御和魔力炮击能力。", type: "exclusive"},
                    {name: "攻略之神", color: "A", cost: 1200, desc: "你精通所有Galgame的套路。在现实约会中，总能选出提升好感度的正确选项，哪怕是面对病娇。", type: "exclusive"},
                    {name: "鏖杀公(Sandalphon)", color: "S", cost: 3000, desc: "夜刀神十香的天使。一把巨大的王座之剑，破坏力惊人，能发出毁灭性的剑气，简单粗暴。", type: "exclusive"},
                    {name: "魔王反转", color: "SS", cost: 9500, desc: "当精神陷入极度绝望时，你的灵力会反转为黑暗属性。召唤“魔王”，破坏力倍增，但会失去理智。", type: "exclusive"},
                    {name: "隐居者(Hermit)", color: "B", cost: 800, desc: "四糸乃的能力。擅长冰冻和防御，性格害羞。在雪地或低温环境下战斗力提升，拥有极强的隐蔽性。", type: "exclusive"},
                    {name: "歌姬(Diva)", color: "A", cost: 1000, desc: "诱宵美九的能力。通过声音控制精神，能洗脑大量人类作为傀儡，或者强化队友的属性。", type: "exclusive"},
                    {name: "炎魔(Efreet)", color: "S", cost: 2200, desc: "五河琴里的能力。拥有极强的火焰再生能力，只要哪怕还剩一点灰烬都能复活，但容易失去理智变成杀戮机器。", type: "exclusive"},
                    {name: "赝造魔女(Haniel)", color: "S", cost: 2000, desc: "七罪的能力。能将任何物体变形成其他样子，甚至能伪装成其他精灵并复制其能力，欺诈师的神技。", type: "exclusive"},
                    {name: "最后的之剑", color: "SSS", cost: 35000, desc: "汇聚了所有精灵力量的终极一击。能切开世界，重置因果，是只有在最终决战才能使用的奇迹之力。", type: "exclusive"},
                    {name: "不幸体质", color: "D", cost: 60, desc: "你总是被卷入空间震或精灵的战斗中。虽然危险，但也意味着你有更多机会接触到精灵。", type: "exclusive"},
                    {name: "妹妹的飞踢", color: "C", cost: 100, desc: "每天早上被妹妹飞踢叫醒。虽然会扣血，但能提升抗击打能力，并开启新的一天。", type: "exclusive"}
                ]
            },
                      {
                name: "131.Fate/Stay Night",
                desc: "名为冬木市的舞台，七名魔术师与七名英灵为了争夺万能许愿机“圣杯”而展开的厮杀。正义的伙伴、理想的尽头、此世全部之恶，都在这十天的夜晚中终结。",
                boss: "吉尔伽美什, 言峰绮礼, 赫拉克勒斯, 黑影(安哥拉曼纽)",
                identities: [
                    { name: "私立穗群原学园的普通学生", items: "一个写着名字的书包, 一份没做完的作业" },
                    { name: "冬木市深山町的家庭主妇", items: "刚买的特价鸡蛋, 一把有点钝的菜刀" },
                    { name: "新都商业街的便利店店员", items: "印着便利店Logo的围裙, 过期的便当" },
                    { name: "柳洞寺的扫地僧人", items: "一把竹扫帚, 一串劣质佛珠" },
                    { name: "被卷入瓦斯爆炸的路人", items: "烧焦的衣角, 一张沾血的市民证" }
                ],
                talents: [
                    {name: "魔术回路(堵塞)", color: "D", cost: 50, desc: "你有魔术回路，但完全是堵塞状态，每次强行通魔力都像神经被火烧一样剧痛，效率极低。", type: "exclusive"},
                    {name: "补魔体质", color: "C", cost: 180, desc: "你的体液（血液、唾液等）蕴含微量魔力，可以通过体液交换为从者补充魔力，虽然效率不高但胜在方便。", type: "exclusive"},
                    {name: "投影魔术(伪)", color: "C", cost: 150, desc: "你可以解析物体的结构并用魔力构建出空心的伪物，持续时间很短，且无法模仿神秘度高的物品。", type: "exclusive"},
                    {name: "强化魔术", color: "B", cost: 300, desc: "基础但实用的魔术，能暂时提升物体的硬度或锐利度。用在水管上能敲碎头骨，用在身体上能挡子弹。", type: "exclusive"},
                    {name: "令咒(伪)", color: "B", cost: 400, desc: "你手背上显现出了红色的令咒痕迹，虽然不能命令英灵，但可以作为一次性的大容量魔力结晶使用。", type: "exclusive"},
                    {name: "固有结界(残片)", color: "A", cost: 800, desc: "你拥有心象风景的雏形，虽然无法完全展开结界，但可以将周围几米的空间暂时扭曲成有利于你的环境。", type: "exclusive"},
                    {name: "十二试炼(伪)", color: "A", cost: 1500, desc: "模仿海格力斯宝具的劣化版，给你提供三次复活机会，并且对杀死你一次的攻击产生微弱的抗性。", type: "exclusive"},
                    {name: "燕返(剑技)", color: "S", cost: 2200, desc: "佐佐木小次郎的绝技，利用多重次元曲折现象，在同一时间斩出三刀，造成几乎无法回避的必杀一击。", type: "exclusive"},
                    {name: "无限剑制(咏唱)", color: "S", cost: 2500, desc: "你需要完整的咏唱才能发动。一旦发动，你将置身于插满宝具的荒野，可以随意调用其中的赝品进行轰炸。", type: "exclusive"},
                    {name: "王之财宝(钥匙)", color: "SS", cost: 6000, desc: "你获得了开启巴比伦宝库的钥匙，虽然宝库里的东西不是你的，但你可以随机抽取其中的宝具投掷出去。", type: "exclusive"},
                    {name: "远离尘世的理想乡", color: "SS", cost: 8000, desc: "阿瓦隆的剑鞘。持有它时，只要你还有一口气，伤势就会迅速愈合。展开真名解放可获得绝对防御。", type: "exclusive"},
                    {name: "第三法(天之杯)", color: "SSS", cost: 35000, desc: "灵魂物质化。你获得了无限的魔力源泉，灵魂不灭，肉体可以随意重塑，真正意义上的不老不死。", type: "exclusive"},
                    {name: "此世全部之恶", color: "SSS", cost: 40000, desc: "你成为了圣杯黑泥的受肉容器。拥有无穷的诅咒魔力，可以污染英灵，吞噬生命，是毁灭世界的灾厄。", type: "exclusive"},
                    {name: "黑键投掷心得", color: "C", cost: 120, desc: "教会代行者的基础技能，你能熟练地夹着多把黑键进行投掷，虽然威力一般，但胜在帅气和便携。", type: "exclusive"},
                    {name: "老虫子的刻印虫", color: "E", cost: 10, desc: "间桐脏砚植入的刻印虫。每天都会啃食你的魔力和生命力，带来剧痛，唯一的优点是能让你勉强使用魔术。", type: "exclusive"}
                ]
            },
            {
                name: "132.Fate/Zero",
                desc: "第四次圣杯战争。这是魔术师杀手卫宫切嗣的战场，充满了阴谋、暗杀、背叛与悲剧。这里没有正义，只有为了愿望而不择手段的厮杀。",
                boss: "吉尔伽美什(弓), 迪尔姆德, 兰斯洛特, 克苏鲁海魔",
                identities: [
                    { name: "冬木凯悦酒店的服务生", items: "一套熨烫平整的制服, 酒店万能房卡" },
                    { name: "未远川边的钓鱼佬", items: "一根简易鱼竿, 一个装满蚯蚓的盒子" },
                    { name: "间桐家的下人", items: "一把扫把, 满身的淤青和恐惧" },
                    { name: "圣堂教会的孤儿", items: "一本破旧的圣经, 一块干硬的面包" },
                    { name: "被Caster盯上的儿童", items: "一个红色的皮球, 充满恐惧的眼神" }
                ],
                talents: [
                    {name: "起源弹(一发)", color: "S", cost: 2100, desc: "卫宫切嗣的杀手锏。击中魔术师时，会切断并重接其魔术回路，造成永久性的魔力短路和身体崩溃。", type: "exclusive"},
                    {name: "骑士不死于徒手", color: "S", cost: 2300, desc: "兰斯洛特的宝具能力。你抓到的任何物体（哪怕是树枝或F15战机）都会被魔力侵染，变成D级宝具供你驱使。", type: "exclusive"},
                    {name: "螺湮城教本(残页)", color: "A", cost: 1200, desc: "人皮书的残页。可以召唤并控制小型的水生魔怪，虽然长得恶心，但作为肉盾和骚扰手段非常有效。", type: "exclusive"},
                    {name: "自我强制证文", color: "B", cost: 500, desc: "一种绝对的契约魔术。在羊皮纸上写下的条件，一旦双方同意并注入魔力，违约者将受到死亡诅咒。", type: "exclusive"},
                    {name: "固有时制御", color: "A", cost: 900, desc: "将自身的生物钟加速或减速。可以获得数倍的反应速度和移动速度，但会给肉体带来极大的负担。", type: "exclusive"},
                    {name: "王之酒", color: "C", cost: 150, desc: "吉尔伽美什珍藏的美酒。喝下后可以大幅恢复魔力和体力，还能稍微提升一点领导力和魅力。", type: "exclusive"},
                    {name: "百貌之相", color: "B", cost: 450, desc: "你可以分裂出不同人格和能力的个体，虽然单体战斗力极弱，但用来收集情报和搞后勤是神技。", type: "exclusive"},
                    {name: "风王结界", color: "A", cost: 1000, desc: "缠绕在武器上的高压风暴。可以隐藏武器的真实形态，并在释放时产生强大的风压炮击飞敌人。", type: "exclusive"},
                    {name: "神威车轮(伪)", color: "S", cost: 2800, desc: "征服王的战车仿制品。虽然拉车的牛只是普通公牛，但冲锋起来依然具有碾碎坦克的破坏力。", type: "exclusive"},
                    {name: "肯主任的水银", color: "A", cost: 1500, desc: "月灵髓液。拥有自动索敌、自动防御、自动攻击功能的魔术礼装，攻防一体，是懒人魔术师的福音。", type: "exclusive"},
                    {name: "此世全部之欲(黑泥)", color: "E", cost: 1, desc: "你不小心沾染了圣杯流出的黑泥。每时每刻都要进行精神判定，失败则发疯或被吞噬，成功则获得黑化力量。", type: "exclusive"},
                    {name: "乖离剑(投影)", color: "SS", cost: 9000, desc: "虽然只是投影，但依然具备切裂空间的性质。只能挥动一次，之后就会破碎，威力足以摧毁街区。", type: "exclusive"},
                    {name: "阿瓦隆(剑鞘)", color: "SS", cost: 8500, desc: "Saber的剑鞘。持有者获得不死性，但必须由Saber本人提供魔力才能发挥最大效果，否则只是个强力血瓶。", type: "exclusive"},
                    {name: "虫爷的寄生虫", color: "D", cost: 80, desc: "体内寄生了刻印虫，虽然能辅助施法，但会不断侵蚀你的身体，且让你对间桐脏砚无法反抗。", type: "exclusive"},
                    {name: "愉悦的麻婆豆腐", color: "C", cost: 50, desc: "言峰绮礼最爱的超辣麻婆豆腐。吃下后全身发热，短时间内对寒冷和精神控制有极高的抗性。", type: "exclusive"}
                ]
            },
            {
                name: "133.空之境界",
                desc: "以两仪式和黑桐干也为中心的故事。涉及“直死之魔眼”、“根源”、“起源”等高深概念。这是一个充满都市怪谈、猎奇杀人与哲学思辨的世界。",
                boss: "荒耶宗莲, 浅上藤乃, 两仪式(根源式)",
                identities: [
                    { name: "观布子市的普通高中生", items: "一本教科书, 一个随身听" },
                    { name: "礼园女子学院的学生", items: "一套精致的校服, 一把违禁的小刀" },
                    { name: "伽蓝之洞的访客", items: "一张设计图纸, 一个古董人偶" },
                    { name: "被荒耶宗莲选中的住户", items: "小川公寓的钥匙, 精神恍惚的诊断书" },
                    { name: "黑桐干也的同事", items: "一堆调查文件, 一辆破旧的自行车" }
                ],
                talents: [
                    {name: "直死之魔眼", color: "SSS", cost: 50000, desc: "能够看到事物的“死线”。只要沿着线切割，无论多坚硬的物体、多抽象的概念（如结界、病痛）都能被杀死。", type: "exclusive"},
                    {name: "扭曲之魔眼", color: "S", cost: 3000, desc: "浅上藤乃的能力。视线所及之处，可以将物体进行螺旋状的扭曲。威力巨大，甚至能扭断大桥，但会加重眼疾。", type: "exclusive"},
                    {name: "未来视(预测)", color: "A", cost: 1200, desc: "可以看到短暂未来的景象。虽然不能改变结果，但可以让你提前做好准备，规避致命的危险。", type: "exclusive"},
                    {name: "起源觉醒", color: "SS", cost: 6000, desc: "觉醒了自身的“起源”。你的冲动和能力将完全受起源支配，获得与其相关的绝对力量，但人格会逐渐丧失。", type: "exclusive"},
                    {name: "人偶制作技术", color: "B", cost: 500, desc: "苍崎橙子的技术皮毛。能制作出与真人无异的人偶义肢，甚至能制作出暂存灵魂的备用躯体。", type: "exclusive"},
                    {name: "三重结界", color: "A", cost: 1500, desc: "荒耶宗莲的绝技。不俱、金刚、蛇蝎。分别代表静止、不可破坏和反伤。极强的防御结界。", type: "exclusive"},
                    {name: "双重人格", color: "C", cost: 200, desc: "你拥有两个人格，可以分别学习不同的技能。一个人格休息时，另一个人格可以活动，实现24小时不间断肝。", type: "exclusive"},
                    {name: "无痛症", color: "D", cost: 100, desc: "你感觉不到疼痛。这让你在战斗中无所畏惧，但也让你无法察觉身体的致命损伤，容易暴毙。", type: "exclusive"},
                    {name: "根源的漩涡", color: "SSS", cost: 99999, desc: "连接到了万物的起始与终结之地。你是全知全能的存在，可以改写现实。但大概率会被同化，失去自我。", type: "exclusive"},
                    {name: "卢恩符文(旧)", color: "A", cost: 800, desc: "古老的魔术刻印。刻在石头或物品上可以产生火焰、冰冻、硬化等效果，威力远超现代魔术。", type: "exclusive"},
                    {name: "法式香草冰淇淋", color: "C", cost: 20, desc: "哈根达斯。两仪式最喜欢的口味。如果在正确的时间送给正确的人，可能会获得意想不到的好感度。", type: "exclusive"},
                    {name: "义肢(橙子作)", color: "B", cost: 600, desc: "苍崎橙子制作的高级义肢。不仅灵活性超越肉体，还可以内置藏匿武器或魔术回路，非常实用。", type: "exclusive"},
                    {name: "漂浮灵体质", color: "C", cost: 300, desc: "巫条雾绘的体质。你的灵魂可以脱离肉体在空中漂浮，拥有俯瞰风景的视角，但肉体必须躺在医院。", type: "exclusive"},
                    {name: "杀人冲动", color: "E", cost: 1, desc: "一种难以抑制的想要杀戮的本能。每晚必须进行意志判定，失败则会无差别攻击周围的生物。", type: "exclusive"},
                    {name: "普通人的搜查力", color: "C", cost: 100, desc: "黑桐干也的特技。只要你想找人，就没有找不到的。虽然没有任何战斗力，但在情报收集上堪称神级。", type: "exclusive"}
                ]
            },
            {
                name: "134.月姬",
                desc: "吸血鬼（死徒）与教会代行者暗中争斗的世界。这里有拥有直死之魔眼的远野志贵，有真祖的公主爱尔奎特。夜晚是极其危险的。",
                boss: "罗亚, 尼禄·卡奥斯, 爱尔奎特(暴走), 远野四季",
                identities: [
                    { name: "三咲町的普通高中生", items: "一副厚底眼镜, 一把折叠水果刀" },
                    { name: "远野家的佣人", items: "一套女仆装/执事服, 扫除工具" },
                    { name: "被死徒吸血的受害者", items: "脖子上的牙印, 苍白的皮肤" },
                    { name: "教会的见习修女", items: "十字架项链, 几把未开刃的黑键" },
                    { name: "深夜游荡的醉汉", items: "半瓶劣质酒, 呕吐物" }
                ],
                talents: [
                    {name: "直死之魔眼(点)", color: "SS", cost: 15000, desc: "不仅能看到线，还能看到“点”。刺破点，物体的存在本身就会被抹消。对大脑负担极大，使用过度会烧坏脑子。", type: "exclusive"},
                    {name: "真祖的血统", color: "SSS", cost: 30000, desc: "作为地球的触觉，你拥有无穷的生命力和恢复力。只要地球还在，你就几乎不死。但要时刻忍受吸血冲动。", type: "exclusive"},
                    {name: "兽王之巢", color: "S", cost: 3500, desc: "尼禄·卡奥斯的能力。你的身体由666种野兽的因子组成，可以随意将身体部分变形为各种猛兽进行攻击。", type: "exclusive"},
                    {name: "转生秘术", color: "SS", cost: 5000, desc: "罗亚的秘术。当肉体死亡后，灵魂可以转生到选定的宿主身上，并逐渐吞噬宿主的人格，实现永生。", type: "exclusive"},
                    {name: "死徒化", color: "A", cost: 1000, desc: "你变成了吸血鬼。获得超人的体能和恢复力，可以使用魔眼，但畏惧阳光，必须定期吸食人血。", type: "exclusive"},
                    {name: "七夜暗杀术", color: "A", cost: 1200, desc: "七夜家族的体术。利用墙壁和天花板进行立体机动，动作诡异难以捉摸，专门为了杀人而设计的技巧。", type: "exclusive"},
                    {name: "净眼", color: "B", cost: 400, desc: "可以看到一般人看不到的灵体和不净之物。对于探索灵异事件和规避伏击很有帮助，是魔眼的下位替代。", type: "exclusive"},
                    {name: "咖喱狂热者", color: "C", cost: 50, desc: "你对咖喱有着异常的执着。在吃咖喱时，你的心情会变好，体力和魔力恢复速度提升20%。", type: "exclusive"},
                    {name: "琥珀的药剂", color: "B", cost: 300, desc: "琥珀制作的各种奇怪药剂。有的能治病，有的能让人精神错乱，使用前最好先鉴定一下。", type: "exclusive"},
                    {name: "秋叶的掠夺", color: "A", cost: 1500, desc: "通过视线或接触，强制掠夺对方的热量（生命力）。可以将敌人烧成灰烬，也可以用来补充自己的体力。", type: "exclusive"},
                    {name: "第五法(青)", color: "SSS", cost: 45000, desc: "魔法使苍崎青子的魔法。涉及时间旅行和熵的逆转。你可以借用未来的力量，或者将伤害扔到遥远的未来。", type: "exclusive"},
                    {name: "折叠刀精通", color: "C", cost: 100, desc: "你非常擅长使用折叠刀进行快速切割。配合特殊步伐，能在近身战中发挥出乎意料的杀伤力。", type: "exclusive"},
                    {name: "反转冲动", color: "D", cost: 150, desc: "你的血脉中潜藏着非人的因子。在情绪激动时，可能会发生反转，变成只知道杀戮的怪物。", type: "exclusive"},
                    {name: "千年锁", color: "S", cost: 2000, desc: "希耶尔使用的概念武装。可以将任何不死生物强制束缚并火葬，对死徒和灵体有极大的克制作用。", type: "exclusive"},
                    {name: "洗脑侦探", color: "C", cost: 200, desc: "翡翠的特技。通过极其令人信服（或者说是催眠）的话术，让对方相信你的推理，哪怕那是胡说八道。", type: "exclusive"}
                ]
            },
            {
                name: "135.魔法少女小圆",
                desc: "外表可爱实则绝望的世界。丘比诱导少女签订契约成为魔法少女，对抗魔女。但魔法少女的灵魂宝石一旦污秽，就会变成魔女。奇迹与魔法，都是要付出代价的。",
                boss: "魔女之夜, 丘比(孵化者), 晓美焰(恶魔)",
                identities: [
                    { name: "见泷原中学的转校生", items: "崭新的书包, 丘比的凝视" },
                    { name: "医院里的长期病号", items: "点滴架, 绝望的眼神" },
                    { name: "魔女结界里的迷路者", items: "被扭曲的手机, 惊恐的尖叫" },
                    { name: "资深魔法少女的跟班", items: "备用的悲叹之种, 记录本" },
                    { name: "毫无存在感的路人", items: "一杯喝了一半的红茶, 一张音乐会门票" }
                ],
                talents: [
                    {name: "灵魂宝石", color: "A", cost: 1000, desc: "你的灵魂被实体化为宝石。肉体变得抗揍且无痛，只要宝石不碎就不死。但必须定期净化，否则会变成怪物。", type: "exclusive"},
                    {name: "时间溯行", color: "SSS", cost: 40000, desc: "晓美焰的能力。可以暂停时间，或者重置时间回到某个存档点。这是改变命运的唯一希望，但会积累巨大的因果。", type: "exclusive"},
                    {name: "无限枪制", color: "S", cost: 2500, desc: "巴麻美的能力。可以召唤无数的燧发枪进行齐射，火力覆盖极强。唯一的缺点是容易断头（物理）。", type: "exclusive"},
                    {name: "治愈祈愿", color: "A", cost: 1200, desc: "沙耶香的能力。拥有极强的自愈能力，断肢重生只是小意思。还可以屏蔽痛觉，进行疯狂的战斗。", type: "exclusive"},
                    {name: "圆环之理", color: "SSS", cost: 50000, desc: "鹿目圆的成神概念。你可以接引所有即将魔女化的魔法少女，改写宇宙法则。但你将失去实体，成为概念。", type: "exclusive"},
                    {name: "悲叹之种", color: "B", cost: 500, desc: "魔女死后掉落的黑色宝石。可以用来吸取灵魂宝石的污秽，是魔法少女的续命道具，也能用来交易。", type: "exclusive"},
                    {name: "人鱼魔女形态", color: "E", cost: 1, desc: "你因为绝望而堕落成了魔女。失去理智，只剩下破坏的本能，被困在自己的结界中等待被讨伐。", type: "exclusive"},
                    {name: "丘比的契约", color: "D", cost: 0, desc: "你可以许下一个愿望，代价是成为魔法少女/少年并终身战斗。愿望越大，潜力越大，绝望也越深。", type: "exclusive"},
                    {name: "王之财宝(军火版)", color: "S", cost: 3000, desc: "晓美焰的时停军火库。你可以从异空间取出各种偷来的现代热兵器，从手枪到反舰导弹应有尽有。", type: "exclusive"},
                    {name: "红茶与蛋糕", color: "C", cost: 50, desc: "巴麻美的下午茶套装。在战斗前享用可以缓解紧张情绪，提升士气，Flag立得飞起。", type: "exclusive"},
                    {name: "杏子的长枪", color: "B", cost: 800, desc: "佐仓杏子的武器。多节棍式的长枪，攻击范围极大，还可以制造分身迷惑敌人，适合单挑。", type: "exclusive"},
                    {name: "绝望抗性", color: "A", cost: 1500, desc: "你的精神坚韧如铁。即使面对再大的绝望，你的灵魂宝石也不会轻易浑浊，能坚持更久的战斗。", type: "exclusive"},
                    {name: "使魔召唤", color: "C", cost: 300, desc: "你可以召唤一些弱小的使魔为你侦查或做杂活。它们长得有点抽象，而且只会说奇怪的语言。", type: "exclusive"},
                    {name: "伪街的孩子", color: "B", cost: 600, desc: "魔女结界内的原住民。你对结界构造了如指掌，在结界内战斗时各项属性提升30%。", type: "exclusive"},
                    {name: "恶魔之翼", color: "SS", cost: 12000, desc: "叛逆的物语中恶魔焰的能力。撕裂圆环之理，将神拉下神坛。拥有改写记忆和现实的恐怖力量。", type: "exclusive"}
                ]
            },
            {
                name: "136.光之美少女",
                desc: "传说中的战士PreCure与邪恶组织战斗的世界。虽然是子供向，但肉搏战极其硬核。友情、努力、胜利是这里的主旋律，物理攻击往往比魔法更有效。",
                boss: "各代最终BOSS(如贾酷王, 杜恩), 黑暗化的Precure",
                identities: [
                    { name: "充满活力的初中生", items: "便当盒, 体育课用的运动服" },
                    { name: "异世界来的妖精", items: "毛茸茸的身体, 变身道具(未激活)" },
                    { name: "反派组织的杂兵", items: "奇怪的面具, 随时会被净化的命运" },
                    { name: "总是被卷入战斗的路人", items: "掉落的冰淇淋, 惊讶的表情" },
                    { name: "转校生", items: "神秘的气质, 优秀的运动神经" }
                ],
                talents: [
                    {name: "变身器", color: "A", cost: 1200, desc: "获得变身成为光之美少女的能力。变身后全属性大幅提升，获得飞行、防御盾等基础能力，外貌也会改变。", type: "exclusive"},
                    {name: "物理说服", color: "S", cost: 2000, desc: "Precure的传统艺能。你的拳脚攻击附带净化效果，且威力惊人，能轻易击碎巨石，打到敌人“改邪归正”。", type: "exclusive"},
                    {name: "友情羁绊", color: "B", cost: 600, desc: "当你和队友一起战斗时，双方的全属性提升50%。如果队友倒下，你会爆发出200%的战斗力。", type: "exclusive"},
                    {name: "必杀技(净化)", color: "A", cost: 1500, desc: "释放华丽的光束或冲击波。对邪恶生物有即死判定的净化效果，对普通生物则是高额物理/能量伤害。", type: "exclusive"},
                    {name: "妖精伙伴", color: "C", cost: 300, desc: "获得一只专属妖精。它能提供情报支持，甚至变成你的武器或强化道具，关键时刻还能卖萌。", type: "exclusive"},
                    {name: "无限潜力", color: "SS", cost: 8000, desc: "作为传说中的战士，你的成长上限极高。只要心中有爱和希望，就能不断突破极限，创造奇迹。", type: "exclusive"},
                    {name: "黑化形态", color: "S", cost: 2500, desc: "堕入黑暗面的力量。失去理智但战斗力暴涨，攻击带有腐蚀性，不再受道德约束，适合单干。", type: "exclusive"},
                    {name: "强化形态(超级)", color: "SS", cost: 5000, desc: "在剧场版或后期才能解锁的形态。长出翅膀，衣服变华丽，战斗力呈指数级上升，能单挑BOSS。", type: "exclusive"},
                    {name: "嘴遁(希望)", color: "C", cost: 100, desc: "在战斗中发表关于希望和梦想的演讲。能动摇敌人的意志，甚至让反派洗白，同时为自己回血。", type: "exclusive"},
                    {name: "绝对防御盾", color: "B", cost: 800, desc: "召唤光之护盾。虽然经常被打碎，但在破碎前能抵挡极高强度的攻击，是保护队友的神技。", type: "exclusive"},
                    {name: "跨界召唤", color: "S", cost: 3000, desc: "剧场版限定。可以召唤其他代的光之美少女跨越时空来助战，虽然持续时间短，但人多力量大。", type: "exclusive"},
                    {name: "日常幸运E", color: "D", cost: 50, desc: "你在日常生活中总是倒霉，迟到、摔跤、考试不及格。但这通常是触发剧情和获得变身器的前兆。", type: "exclusive"},
                    {name: "心灵之花", color: "A", cost: 1000, desc: "HeartCatch的能力。你可以看到并将人的心灵之花具象化。既可以用来治疗心理创伤，也可以用来战斗。", type: "exclusive"},
                    {name: "料理达人", color: "C", cost: 80, desc: "你擅长制作甜点。美味的甜点能快速恢复队友的体力和心情，是战斗后必不可少的后勤技能。", type: "exclusive"},
                    {name: "绝望荆棘", color: "D", cost: 120, desc: "被反派种下的诅咒。你的内心容易滋生绝望，吸引怪物袭击，但也让你对黑暗力量有更高的亲和度。", type: "exclusive"}
                ]
            },
            {
                name: "137.少女与战车",
                desc: "将驾驶坦克作为女性传统艺能“战车道”的世界。虽然是开坦克互轰，但神奇的碳素涂层让坦克里的人绝对安全。这里有各种二战名车和魔改战术。",
                boss: "西住美穗(军神模式), 岛田爱里寿, 大学选拔队",
                identities: [
                    { name: "大洗女子学园的学生", items: "水手服, 选修课报名表" },
                    { name: "黑森峰的整备班成员", items: "油腻的扳手, 德系坦克手册" },
                    { name: "真理高中的杂役", items: "一件厚棉袄, 一瓶伏特加(无醇)" },
                    { name: "战车道联盟的工作人员", items: "裁判旗, 规则手册" },
                    { name: "废品回收站的淘宝者", items: "金属探测器, 发现坦克残骸的地图" }
                ],
                talents: [
                    {name: "战车道心得", color: "B", cost: 500, desc: "你掌握了驾驶坦克、装填炮弹、指挥作战的基础技能。在这个世界，这是比化妆更重要的生存技能。", type: "exclusive"},
                    {name: "西住流", color: "S", cost: 2200, desc: "正如钢铁般的纪律和战术。你的指挥风格严谨、冷酷且高效，擅长正面突击和精准打击。", type: "exclusive"},
                    {name: "岛田流", color: "S", cost: 2200, desc: "变幻莫测的战术风格。你擅长利用地形、机动和奇袭，能让对手在不知不觉中陷入包围。", type: "exclusive"},
                    {name: "军神直觉", color: "SS", cost: 6000, desc: "西住美穗的天赋。在绝境中总能发现唯一的胜机，能指挥轻型坦克玩弄重型坦克于股掌之间。", type: "exclusive"},
                    {name: "碳素涂层保护", color: "A", cost: 1500, desc: "规则级防御。只要你在坦克里，无论坦克被炸成什么样，你都只会被熏黑脸，绝对不会死。", type: "exclusive"},
                    {name: "漂移射击", color: "B", cost: 800, desc: "你能驾驶几十吨重的坦克做出跑车般的漂移动作，并在漂移过程中精准命中敌方弱点。", type: "exclusive"},
                    {name: "快速装填", color: "C", cost: 300, desc: "你的装填速度比自动装弹机还快。在近距离狗斗中，这一发炮弹的时间差就是生与死的距离。", type: "exclusive"},
                    {name: "机械通灵", color: "A", cost: 1000, desc: "汽车部的能力。你能听懂引擎的轰鸣，只要有一堆废铁和胶带，你就能修好任何抛锚的坦克。", type: "exclusive"},
                    {name: "以德服人(物理)", color: "C", cost: 200, desc: "你擅长使用德系坦克。虽然容易坏，但火力和装甲都是顶级的。你对德系坦克的故障率有微弱的压制效果。", type: "exclusive"},
                    {name: "苏维埃进行曲", color: "C", cost: 200, desc: "你擅长使用苏系坦克。简单粗暴，数量取胜。在雪地环境中，你的坦克机动性提升30%。", type: "exclusive"},
                    {name: "安齐奥的午餐", color: "D", cost: 50, desc: "比起打仗，你更擅长做意大利面。虽然战斗力不强，但能在战场上举办宴会，提升士气。", type: "exclusive"},
                    {name: "白色死神", color: "S", cost: 2500, desc: "芬兰琴魔的能力。驾驶狙击型坦克时，你的命中率达到100%，且极其擅长隐蔽，是坦克的噩梦。", type: "exclusive"},
                    {name: "CV33超跑", color: "C", cost: 150, desc: "你擅长驾驶超轻型坦克。虽然一炮就挂，但速度极快，能钻下水道，是完美的侦察兵。", type: "exclusive"},
                    {name: "鼠式坦克", color: "A", cost: 1800, desc: "你拥有一辆超重型鼠式坦克。移动堡垒，虽然慢得像乌龟，但正面几乎无敌，能吸引所有火力。", type: "exclusive"},
                    {name: "战车道精神", color: "B", cost: 400, desc: "无论胜败，都要保持礼仪。这种精神能让你在战败后更容易获得对手的尊重和好感，方便挖角。", type: "exclusive"}
                ]
            },
            {
                name: "138.强袭魔女",
                desc: "拥有魔力的少女们穿上“飞行脚”，飞上天空与异形军“涅洛伊”战斗的世界。这里没有裤子（那是死库水！），只有空战、魔法护盾和百合花开。",
                boss: "大型涅洛伊巢穴, 人形涅洛伊, 军队高层的顽固派",
                identities: [
                    { name: "扶桑皇国的乡下少女", items: "家传的治疗药草, 宽松的衣服" },
                    { name: "不列颠尼亚的机械师", items: "沾满油污的手套, 飞行脚图纸" },
                    { name: "501统合战斗航空团的杂兵", items: "一把扫把, 总是被炸毁的基地碎片" },
                    { name: "卡尔斯兰的难民", items: "仅存的照片, 逃难的包裹" },
                    { name: "罗曼尼亚的医护兵", items: "急救箱, 绷带" }
                ],
                talents: [
                    {name: "飞行脚适格者", color: "B", cost: 600, desc: "你拥有启动飞行脚的魔力。穿上它，你就能像螺旋桨飞机一样在天空中自由翱翔和战斗。", type: "exclusive"},
                    {name: "魔法护盾", color: "A", cost: 1200, desc: "魔女的保命技能。展开圆形的魔法盾防御攻击。魔力越强盾越硬，高手甚至能把盾当武器撞人。", type: "exclusive"},
                    {name: "固有魔法(特异功能)", color: "S", cost: 2500, desc: "每位魔女独特的魔法。可能是怪力、千里眼、治疗、雷电或者空间感知，是你赖以成名的绝技。", type: "exclusive"},
                    {name: "震电(飞行脚)", color: "S", cost: 2200, desc: "宫藤芳佳使用的尖端飞行脚。速度极快，爬升率惊人，但对魔力控制要求极高，新手穿上就会坠机。", type: "exclusive"},
                    {name: "治愈魔法", color: "A", cost: 1500, desc: "稀有的治愈能力。只要还有一口气，就能把人救回来。在战场上，你就是队友最想保护的奶妈。", type: "exclusive"},
                    {name: "魔眼(夜视/远视)", color: "B", cost: 800, desc: "坂本美绪的能力（劣化版）。能看穿涅洛伊的核心位置，或者在黑夜中视物，是狙击手的神技。", type: "exclusive"},
                    {name: "多重护盾", color: "SS", cost: 5000, desc: "你可以同时展开多层护盾，甚至将护盾重叠旋转形成绞肉机。攻防一体，单挑大型涅洛伊不是梦。", type: "exclusive"},
                    {name: "魔力暴走", color: "D", cost: 100, desc: "你的魔力极其庞大但难以控制。战斗中容易误伤队友或者炸毁自己的武器，需要长时间训练。", type: "exclusive"},
                    {name: "涅洛伊化", color: "E", cost: 1, desc: "你被涅洛伊感染或同化。身体逐渐金属化，失去人性，最终变成敌人的傀儡。", type: "exclusive"},
                    {name: "空战王牌", color: "A", cost: 1800, desc: "哈特曼般的空战直觉。在枪林弹雨中从容穿梭，总是能咬住敌人的6点钟方向，击坠数破百。", type: "exclusive"},
                    {name: "整备神技", color: "C", cost: 300, desc: "哪怕飞行脚被打得只剩零件，你也能在半小时内把它拼好并调试到最佳状态。", type: "exclusive"},
                    {name: "绝对领域(裤子)", color: "C", cost: 50, desc: "在这个世界，不穿裤子是常识。你获得了对寒冷的抗性，以及在空中做高难度动作时不会走光的被动。", type: "exclusive"},
                    {name: "联合攻击", color: "B", cost: 700, desc: "当你和队友配合时，魔力会产生共鸣，能够释放出威力倍增的合体魔法攻击。", type: "exclusive"},
                    {name: "烈风斩", color: "S", cost: 2800, desc: "坂本美绪的剑技。将魔力注入刀刃，挥出能切开涅洛伊装甲的巨大风刃，近战无敌。", type: "exclusive"},
                    {name: "魔导针", color: "C", cost: 200, desc: "佩琳的技能。虽然不是强大的攻击魔法，但能精准打击敌人的弱点，或者进行大范围的雷击牵制。", type: "exclusive"}
                ]
            },
            {
                name: "139.黑岩射手",
                desc: "分为现实世界与里世界。少女们的心灵烦恼在里世界具象化为残酷的战斗。这里只有无尽的荒野、巨大的机械和沉默的少女。",
                boss: "黑岩射手(暴走), 死亡主宰, 黑金锯手, 战轮妖精",
                identities: [
                    { name: "初中女生", items: "绘本, 烦恼日记" },
                    { name: "心理辅导老师", items: "记录板, 一杯咖啡" },
                    { name: "里世界的杂兵骷髅", items: "生锈的武器, 随时会被碾碎的身体" },
                    { name: "被遗弃的人偶", items: "断掉的手臂, 空洞的眼神" },
                    { name: "迷失在里世界的灵魂", items: "发光的微粒, 恐惧的情绪" }
                ],
                talents: [
                    {name: "岩石巨炮(Black Rock Cannon)", color: "S", cost: 2800, desc: "每秒能发射20发岩石弹的巨炮。还能切换为巨剑模式或加特林模式。简单粗暴的火力压制。", type: "exclusive"},
                    {name: "蓝焰之眼", color: "A", cost: 1500, desc: "左眼燃起蓝色的火焰。全属性大幅提升，进入战斗专注状态，痛觉屏蔽，直到敌人倒下为止。", type: "exclusive"},
                    {name: "死亡镰刀", color: "S", cost: 2600, desc: "死亡主宰的武器。巨大的镰刀，攻击范围极广，且带有死灵属性，能轻易收割杂兵的生命。", type: "exclusive"},
                    {name: "王之锯", color: "S", cost: 2700, desc: "黑金锯手的巨剑。虽然笨重，但每一击都有开山裂石的威力，能粉碎敌人的防御和武器。", type: "exclusive"},
                    {name: "战轮", color: "A", cost: 1800, desc: "战轮妖精的装备。巨大的带刺轮子，既是盾牌也是碾压敌人的战车，机动性极强。", type: "exclusive"},
                    {name: "锁链束缚", color: "B", cost: 800, desc: "从虚空中召唤锁链。可以用来束缚敌人、移动自身或作为防御网。玩法多样，看你操作。", type: "exclusive"},
                    {name: "心灵具象", color: "SS", cost: 6000, desc: "你可以将自己的心理创伤或执念具象化为强大的武器或随从。执念越深，力量越强。", type: "exclusive"},
                    {name: "里世界穿梭", color: "A", cost: 2000, desc: "你可以自由往返于现实与里世界。在现实中解决心理问题，或者在里世界直接消灭烦恼的根源。", type: "exclusive"},
                    {name: "彩虹炮", color: "SSS", cost: 30000, desc: "黑岩射手兽化后的终极技能。威力足以毁灭半个里世界，但使用后会陷入长时间的虚弱。", type: "exclusive"},
                    {name: "机械化改造", color: "B", cost: 1000, desc: "你的身体部分被替换为机械。获得超强的防御力和力量，但会逐渐丧失人类的情感。", type: "exclusive"},
                    {name: "马卡龙狂热", color: "C", cost: 50, desc: "你非常喜欢吃马卡龙。这种甜食能快速恢复你在里世界消耗的精神力。", type: "exclusive"},
                    {name: "痛觉共有", color: "D", cost: 200, desc: "你与现实中的对应体痛觉相连。虽然能感知对方的危险，但战斗时会受到双倍的痛苦干扰。", type: "exclusive"},
                    {name: "超高速再生", color: "A", cost: 2200, desc: "里世界特有的恢复力。只要核心不碎，断肢能在数秒内长好，适合持久战。", type: "exclusive"},
                    {name: "浮游炮台", color: "B", cost: 1200, desc: "召唤悬浮在身后的炮台辅助攻击。虽然单发威力不大，但胜在自动攻击，防不胜防。", type: "exclusive"},
                    {name: "Insane形态", color: "SS", cost: 8000, desc: "狂化。紫色的火焰，巨大的机械臂。战斗力碾压常态，但会无差别攻击视野内的所有生物。", type: "exclusive"}
                ]
            },
            {
                name: "140.RWBY",
                desc: "树不子(Remnant)世界。人类利用“尘晶”与名为“戮兽”的怪物战斗。猎人们挥舞着能变成枪的冷兵器，施展名为“外像力”的超能力。",
                boss: "Salem(塞勒姆), Cinder(馨德), 巨型戮兽(利维坦)",
                identities: [
                    { name: "信标学院的新生", items: "自制变形武器, 卷轴(手机)" },
                    { name: "尘晶店的打工仔", items: "一箱低级尘晶, 扫把" },
                    { name: "白牙组织的底层成员", items: "格林面具, 宣传单" },
                    { name: "擎天王国的士兵", items: "制式步枪, 机械义肢" },
                    { name: "边境村庄的农夫", items: "锄头, 对戮兽的恐惧" }
                ],
                talents: [
                    {name: "外像力(Semblance)", color: "S", cost: 2000, desc: "源自灵魂的独特能力。如红玉的急速、阳的受击蓄力、布蕾克的残影。这是猎人的核心技能。", type: "exclusive"},
                    {name: "元气(Aura)", color: "A", cost: 1000, desc: "灵魂的护盾。能抵挡致命伤害，加速愈合，强化攻击。Aura耗尽前，你基本不会受伤。", type: "exclusive"},
                    {name: "银眼战士", color: "SS", cost: 8000, desc: "传说中的血脉。面对戮兽时，你的眼睛会发出银光，能瞬间石化或消灭巨大的戮兽，对反派有压制力。", type: "exclusive"},
                    {name: "变形武器大师", color: "B", cost: 600, desc: "你精通RWBY特色的武器。也就是“这也是枪”。能熟练使用镰刀狙击枪、拳套散弹枪等复杂武器。", type: "exclusive"},
                    {name: "尘晶操控", color: "B", cost: 800, desc: "你能熟练运用各种属性的尘晶（火、冰、雷、重力）。将其镶嵌在武器或衣物上，打出魔法般的效果。", type: "exclusive"},
                    {name: "弗纳人(Faunus)", color: "B", cost: 500, desc: "你拥有动物特征（如猫耳、猴尾）。获得夜视能力和强于人类的感官，但在人类社会可能受歧视。", type: "exclusive"},
                    {name: "四季少女之力(残)", color: "SS", cost: 7000, desc: "你获得了四季少女的一小部分力量。无需尘晶即可操控自然元素（风雨雷电），拥有飞行能力。", type: "exclusive"},
                    {name: "戮兽化手臂", color: "A", cost: 1500, desc: "Cinder同款。你的手臂被戮兽因子感染，虽然丑陋，但能伸长变形，吸取敌人的力量或魔法。", type: "exclusive"},
                    {name: "不死的诅咒", color: "SSS", cost: 50000, desc: "Salem的诅咒。你是不死的，无论被粉碎多少次都会复原。但这可能意味着永恒的折磨和孤独。", type: "exclusive"},
                    {name: "黑客技术", color: "C", cost: 200, desc: "在这个科技发达的世界，能黑进阿特拉斯军方的网络或控制机器人士兵，往往比挥剑更有用。", type: "exclusive"},
                    {name: "战术指挥", color: "B", cost: 400, desc: "类似Jaune的才能。虽然战斗力不强，但能洞察战场局势，指挥队友打出完美的配合。", type: "exclusive"},
                    {name: "机器身体", color: "A", cost: 1800, desc: "Penny同款。你是个拥有灵魂的机器人。力大无穷，内置各种武器，甚至能发射激光炮，坏了还能修。", type: "exclusive"},
                    {name: "幸运护身符", color: "C", cost: 100, desc: "Qrow的酒壶（误）。能稍微抵消一点Qrow带来的厄运场，或者在关键时刻让你捡回一条命。", type: "exclusive"},
                    {name: "神灯知识", color: "SS", cost: 9000, desc: "知识圣器。每世纪可以回答三个问题。你可以得知这个世界的任何秘密，但无法直接获得力量。", type: "exclusive"},
                    {name: "创造权杖", color: "SS", cost: 9500, desc: "创造圣器。只要有设计图，就能创造出任何东西（例如悬浮城市或传送门），但一次只能造一样。", type: "exclusive"}
                ]
            },
                      {
                name: "141.怪化猫",
                desc: "一个浮世绘风格的诡谲世界，物怪（Mononoke）由人类的因果与执念诞生。只有手持退魔之剑的卖药郎能够斩杀它们，但必须凑齐“形、真、理”三样条件。",
                boss: "座敷童子, 海坊主, 鵺, 卖药郎(金)",
                identities: [
                    { name: "坂井家的底层女佣", items: "一块擦地板的抹布, 充满恐惧的眼神" },
                    { name: "游廓的见习秃", items: "劣质的红胭脂, 一双磨脚的木屐" },
                    { name: "路过的落魄画师", items: "几支秃毛的画笔, 一卷未完成的浮世绘" },
                    { name: "没落武士家的家仆", items: "一把生锈的扫帚, 补丁摞补丁的和服" },
                    { name: "香道世家的学徒", items: "一盒劣质香料, 满手的冻疮" }
                ],
                talents: [
                    {name: "退魔之剑(伪)", color: "S", cost: 1800, desc: "一把仿制的退魔剑，虽然无法像真品那样斩杀大妖，但对付普通的小妖魔绰绰有余。拔剑不需要形真理，只需要你的血。", type: "exclusive"},
                    {name: "天平的感知", color: "A", cost: 900, desc: "你拥有类似卖药郎天平的直觉，能够感知到物怪的距离和大概方位，当物怪靠近时，你的心跳会像铃声一样剧烈。", type: "exclusive"},
                    {name: "形之眼", color: "B", cost: 500, desc: "你能更容易看破物怪的“形”，即它的外观形态和攻击方式，在战斗中能更快找到敌人的弱点。", type: "exclusive"},
                    {name: "真之耳", color: "B", cost: 500, desc: "你能聆听事件的“真”，即事情的真相。在调查线索时，你往往能听到别人忽略的细节。", type: "exclusive"},
                    {name: "理之心", color: "B", cost: 500, desc: "你能洞察物怪的“理”，即它心中的执念和因果。这有助于你理解物怪的成因，从而找到解脱它的方法。", type: "exclusive"},
                    {name: "浮世绘体质", color: "C", cost: 180, desc: "你的身体呈现出独特的二维浮世绘质感，物理攻击对你的伤害略微降低，但你受到的火焰伤害会加倍。", type: "exclusive"},
                    {name: "药箱背负者", color: "C", cost: 150, desc: "你背着一个神奇的小药箱，里面虽然没有退魔剑，但总能掏出一些奇怪的草药和符纸，对应付小病小灾很有效。", type: "exclusive"},
                    {name: "猫妖的诅咒", color: "D", cost: 100, desc: "你曾得罪过猫妖，身上带有淡淡的鱼腥味，容易吸引周围的流浪猫，但也容易被犬类生物攻击。", type: "exclusive"},
                    {name: "无面之人", color: "E", cost: 50, desc: "你没有五官，这让你看起来非常惊悚。虽然不会窒息，但你无法通过常规方式进食和交流，只能用心灵感应（极弱）。", type: "exclusive"},
                    {name: "座敷童子的庇护", color: "S", cost: 1500, desc: "你被座敷童子喜爱，运气极佳。在探索废屋或绝境时，总能莫名其妙地找到生路或宝藏。", type: "exclusive"},
                    {name: "海坊主的恐惧", color: "A", cost: 800, desc: "你对深海和未知的恐惧能具象化为实体攻击，当你在海上时，你的精神力攻击会大幅增强。", type: "exclusive"},
                    {name: "鵺的残片", color: "SS", cost: 6000, desc: "你融合了“鵺”的一小块碎片，拥有了组装香道的能力。你可以通过焚香制造出极其逼真的幻境，甚至能困住S级强者。", type: "exclusive"},
                    {name: "斩魔神意", color: "SSS", cost: 25000, desc: "你彻底领悟了斩魔的真谛。只要你通过调查集齐了对手的“形、真、理”，你可以发动一次因果律级别的斩击，无视防御直接抹杀存在。", type: "exclusive"},
                    {name: "时间静止(结界)", color: "SS", cost: 8000, desc: "你可以张开一个金色的结界，在结界内除你以外的时间流速极度缓慢。这通常是用来进行推理和拔剑准备的。", type: "exclusive"},
                    {name: "多重灵魂", color: "A", cost: 1200, desc: "你的体内居住着另一个性格截然不同的灵魂。在危机时刻，你可以切换灵魂接管身体，免疫精神控制并爆发潜能。", type: "exclusive"}
                ]
            },
            {
                name: "142.绝园的暴风雨",
                desc: "被“始之树”与“绝园之树”支配的世界。魔法不属于人类，而是通过向树献祭文明产物来换取奇迹。逻辑与复仇交织的悲剧舞台。",
                boss: "锁部叶风, 不破真广, 泷川吉野, 绝园之魔法师",
                identities: [
                    { name: "黑铁病隔离区的幸存者", items: "一个防毒面具, 一块发霉的面包" },
                    { name: "锁部一族的边缘族人", items: "一个简易的通信魔具, 一身破旧的祭祀袍" },
                    { name: "被魔法波及的难民", items: "一张家人的合照, 一个沉重的旅行包" },
                    { name: "国防军的底层士兵", items: "一把制式手枪, 一张看不懂的作战地图" },
                    { name: "普通的高中生", items: "一本英语课本, 一个便当盒" }
                ],
                talents: [
                    {name: "绝园的果实(吞噬者)", color: "SS", cost: 7500, desc: "你吞噬了绝园之树的果实，身体素质超越人类极限，拥有极强的再生能力和破坏力，但精神容易被杀戮欲望侵蚀。", type: "exclusive"},
                    {name: "始之树的加护", color: "S", cost: 3000, desc: "你受到始之树的眷顾，运气好到离谱。子弹会绕着你走，从高处掉落会挂在树枝上，世界仿佛都在剧本里保护你。", type: "exclusive"},
                    {name: "防御魔法(锁部式)", color: "A", cost: 1000, desc: "你可以通过献祭文明产物（如手机、汽车）来张开防御结界。献祭的物品科技含量越高，防御力越强。", type: "exclusive"},
                    {name: "高速移动魔法", color: "A", cost: 1000, desc: "利用魔法进行瞬间的高速移动，甚至可以在空中借力。需要消耗随身携带的文明供奉物。", type: "exclusive"},
                    {name: "治愈魔法(需供奉)", color: "B", cost: 600, desc: "只要有足够的文明产物作为祭品，你可以治愈大部分物理创伤。但无法治愈疾病或复活死者。", type: "exclusive"},
                    {name: "魔具制作师", color: "B", cost: 500, desc: "你懂得如何制作简易的魔具，能将魔法封存在物品中供普通人使用，虽然效果不如直接施法，但胜在方便。", type: "exclusive"},
                    {name: "哈姆雷特的引用", color: "C", cost: 180, desc: "你熟读莎士比亚的著作，在引用《哈姆雷特》或《暴风雨》台词时，你的精神抗性和说服力会短暂提升。", type: "exclusive"},
                    {name: "黑铁病抗体", color: "C", cost: 200, desc: "你体内拥有罕见的抗体，不会因为接触绝园之树的果实而化为金属，可以在被黑铁病毁灭的城市中自由行走。", type: "exclusive"},
                    {name: "时间笼中的通信", color: "S", cost: 2200, desc: "你掌握了跨越时空进行通信的技巧，就像叶风在无人岛那样。你可以将信息传递给过去或未来的人，改变因果。", type: "exclusive"},
                    {name: "绝园之剑(仿)", color: "A", cost: 1500, desc: "一把模仿绝园之树力量打造的武器，对始之树的魔法屏障有特攻效果，能够轻易斩断魔法结界。", type: "exclusive"},
                    {name: "逻辑崩坏", color: "D", cost: 120, desc: "你的思维方式极其跳跃，常人无法理解。这让你免疫大部分测谎魔法，但也很难与队友进行正常沟通。", type: "exclusive"},
                    {name: "文明的破坏者", color: "SS", cost: 6500, desc: "你天生适合使用绝园魔法。破坏文明产物时获得的魔力回馈是常人的十倍，随手捏碎一个手机就能释放核爆级的魔法。", type: "exclusive"},
                    {name: "世界的剧本(观测)", color: "SSS", cost: 30000, desc: "你能看到世界的“理”和剧本走向。你意识到这个世界是被某种意志操控的舞台，你可以通过微小的干涉来改写剧本结局。", type: "exclusive"},
                    {name: "复仇的誓言", color: "B", cost: 400, desc: "当你为了复仇而行动时，全属性提升30%。一旦复仇目标消失或放弃复仇，该加成失效并扣除50%当前生命值。", type: "exclusive"},
                    {name: "魔法无效化力场", color: "S", cost: 2800, desc: "你的存在本身就是对魔法的否定。在你周围5米范围内，所有低于A级的魔法都会自动消散。", type: "exclusive"}
                ]
            },
            {
                name: "143.野良神",
                desc: "此岸与彼岸交界的世界。八百万神明依靠人类的愿望而存在，死灵若不被神收为神器，就会堕落为妖。只要有5日元，就能召唤神明。",
                boss: "夜斗, 毗沙门天, 惠比寿, 藤崎浩人",
                identities: [
                    { name: "被妖附体的初中生", items: "沉重的书包, 总是感觉肩膀酸痛" },
                    { name: "神社的勤杂工", items: "一把竹扫帚, 几个供奉用的硬币" },
                    { name: "刚死去的游魂", items: "生前穿的衣服, 逐渐模糊的记忆" },
                    { name: "无名的落魄小神", items: "一个破旧的赛钱箱, 0个信徒" },
                    { name: "高天原的清洁工", items: "一块云朵做的抹布, 能够看到下界的望远镜" }
                ],
                talents: [
                    {name: "祝器(进化)", color: "SS", cost: 8000, desc: "作为神器，你对主人绝对忠诚并赌上性命守护，从而进化为祝器。形态改变，威力剧增，是神明最锋利的獠牙。", type: "exclusive"},
                    {name: "祸津神的体质", color: "S", cost: 3500, desc: "你天生适合斩杀。作为神明，你擅长战斗和毁灭，凡人对你的愿望多为杀戮。战力极强，但容易被高天原排斥。", type: "exclusive"},
                    {name: "一线(境界)", color: "A", cost: 1200, desc: "你能划出彼岸与此岸的界线。这条线能阻挡妖的入侵，除了绝对的力量，几乎无法被物理手段突破。", type: "exclusive"},
                    {name: "神依(凭依)", color: "B", cost: 800, desc: "你可以让神明或灵体附身在自己身上，暂时获得对方的能力。但如果双方波长不合，会对身体造成巨大负担。", type: "exclusive"},
                    {name: "半妖体质", color: "A", cost: 1500, desc: "像壹岐日和一样，你的灵魂容易脱离肉体。灵体状态下你会长出尾巴，体能大幅增强，能闻到神和妖的气味。", type: "exclusive"},
                    {name: "恙的抗性", color: "C", cost: 250, desc: "你对妖魔造成的“恙”（安无）有一定抗性，不会轻易因为接触妖魔而感到刺痛或生病。", type: "exclusive"},
                    {name: "画妖师", color: "S", cost: 2800, desc: "你掌握了用笔墨控制妖魔的技术。你可以通过在面具上画眼来操纵妖魔进行战斗，甚至能给妖魔命名。", type: "exclusive"},
                    {name: "惠比寿的财运", color: "S", cost: 2000, desc: "你拥有极佳的商业头脑和财运。哪怕是在废墟里摆摊，也能赚得盆满钵满。金钱可以用来购买情报或雇佣神明。", type: "exclusive"},
                    {name: "黄泉之语", color: "SS", cost: 5000, desc: "你掌握了伊邪那美统治下的黄泉语言。你可以召唤黄泉丑女为你战斗，或者打开通往黄泉的风穴。", type: "exclusive"},
                    {name: "绝对斩断", color: "SSS", cost: 22000, desc: "配合神器，你可以斩断世间万物，不仅是物理实体，连因果、缘分、诅咒甚至时空都能一刀两断。", type: "exclusive"},
                    {name: "被遗忘者", color: "E", cost: 20, desc: "你的存在感极低，只要离开视线就会被人遗忘。这对刺客是神技，但对渴望社交的人来说是地狱。", type: "exclusive"},
                    {name: "神之社", color: "B", cost: 600, desc: "你拥有一座属于自己的微型神社（哪怕是手办大小）。这让你拥有了正式的神籍，可以前往高天原。", type: "exclusive"},
                    {name: "风穴开启", color: "A", cost: 1800, desc: "你可以强行打开通往妖魔巢穴的风穴。这非常危险，通常用来放逐敌人或者进行自杀式袭击。", type: "exclusive"},
                    {name: "神器修复师", color: "A", cost: 1000, desc: "你懂得如何安抚受伤的神器，通过禊祓仪式清除神器上的恙，防止神明被刺伤。", type: "exclusive"},
                    {name: "换代保留记忆", color: "SS", cost: 9000, desc: "作为神明，当你死去换代重生时，你能够保留上一代的记忆和经验。这是违背天理的能力。", type: "exclusive"}
                ]
            },
            {
                name: "144.终结的炽天使",
                desc: "未知病毒毁灭了成年人，吸血鬼统治了地下世界。幸存的孩子们为了复仇，签订契约使用“鬼咒装备”，甚至触碰禁忌的“终结的炽天使”实验。",
                boss: "费里德·巴特利, 克鲁鲁·采佩西, 柊暮人, 柊筱娅(四镰童子)",
                identities: [
                    { name: "桑吉涅姆的家畜儿童", items: "印着编号的白衣服, 抽血后的针孔" },
                    { name: "帝鬼军的普通士兵", items: "量产型咒术装备, 几支抗毒剂" },
                    { name: "涩谷废墟的拾荒者", items: "一把撬棍, 半瓶过期的罐头" },
                    { name: "吸血鬼贵族的随从", items: "精致的制服, 一个装鲜血的高脚杯" },
                    { name: "百夜孤儿院的幸存者", items: "一张全家福, 隐藏的手枪" }
                ],
                talents: [
                    {name: "终结的炽天使(因子)", color: "SSS", cost: 40000, desc: "你体内被植入了毁灭世界的炽天使基因。一旦觉醒，你会长出黑翼或盐柱，拥有毁灭城市的战力，但会失去人性。", type: "exclusive"},
                    {name: "黑鬼装备(契约)", color: "S", cost: 3200, desc: "你成功与最顶级的“黑鬼”签订了契约。武器威力巨大，但鬼会时刻引诱你暴走，吞噬你的心灵。", type: "exclusive"},
                    {name: "吸血鬼始祖血统", color: "SS", cost: 9000, desc: "你获得了上位始祖的血液，转化为吸血鬼贵族。拥有不死之身、超音速移动和恐怖的怪力，一级武装色霸气。", type: "exclusive"},
                    {name: "鬼咒毒抗性", color: "B", cost: 600, desc: "你对鬼咒装备的诅咒有很高的抗性，可以比常人更长时间地解放武器而不必担心被鬼附身。", type: "exclusive"},
                    {name: "默示录病毒免疫", color: "C", cost: 100, desc: "你天生免疫杀死了全人类成年人的病毒。即使你活到了13岁以上，也不会突然暴毙。", type: "exclusive"},
                    {name: "白夜教的实验体", color: "A", cost: 1500, desc: "你曾是人体实验的幸存者，魔法回路被强行打通。你的咒术释放速度比常人快一倍，但寿命大幅缩减。", type: "exclusive"},
                    {name: "一级武装(吸血鬼)", color: "A", cost: 1200, desc: "你获得了吸血鬼的一级武装武器，这是一种会吸血的活体武器，能发出红色的斩击波，威力随吸血量提升。", type: "exclusive"},
                    {name: "鬼化(半觉醒)", color: "A", cost: 1800, desc: "你可以主动让鬼侵蚀身体的一部分，获得非人的力量。比如让手臂变成鬼爪，能轻易撕裂坦克装甲。", type: "exclusive"},
                    {name: "盐之王权能", color: "SS", cost: 8500, desc: "作为炽天使的一部分，你可以将接触到的物体（包括生物和魔法）瞬间化为盐柱。这是绝对的死亡法则。", type: "exclusive"},
                    {name: "约翰四骑士召唤", color: "B", cost: 800, desc: "你可以控制或召唤野外的怪物“约翰四骑士”为你作战。虽然单体不强，但胜在数量无穷无尽。", type: "exclusive"},
                    {name: "帝鬼军体术", color: "C", cost: 300, desc: "经过军队的严酷训练，你掌握了对抗吸血鬼的基础体术，懂得如何利用地形和团队配合来生存。", type: "exclusive"},
                    {name: "欲望具象化", color: "S", cost: 2500, desc: "你的欲望越强烈，你的鬼咒装备威力就越大。无论是复仇、爱欲还是贪婪，都能转化为纯粹的破坏力。", type: "exclusive"},
                    {name: "克鲁鲁的宠爱", color: "S", cost: 2800, desc: "作为女王的亲信，你享有极高的特权。你可以自由出入吸血鬼都市，甚至能调动部分贵族为你效力。", type: "exclusive"},
                    {name: "罪键的使用权", color: "SS", cost: 7000, desc: "你懂得如何使用禁忌的咒术道具“罪键”，可以强行封印或控制天使级别的存在，但代价通常是献祭队友。", type: "exclusive"},
                    {name: "米迦尔的执念", color: "A", cost: 1000, desc: "为了守护重要的人，你可以无视身体的疼痛和损伤继续战斗。只要头没被砍掉，你就不会停止冲锋。", type: "exclusive"}
                ]
            },
            {
                name: "145.K(K-Project)",
                desc: "现代日本背景下的异能王权战。七位“王权者”头顶悬挂达摩克利斯之剑，统领各自的氏族。赤之暴躁、青之秩序、白银之不变。",
                boss: "周防尊, 宗像礼司, 比水流, 无色之王",
                identities: [
                    { name: "吠舞罗的底层混混", items: "印着火焰标志的滑板, 一根棒球棍" },
                    { name: "Scepter 4的后勤人员", items: "整洁的蓝色制服, 一台数据终端" },
                    { name: "学园岛的普通学生", items: "一台PDA终端, 一份社团申请书" },
                    { name: "绿之氏族的网游玩家", items: "高性能笔记本电脑, 鹦鹉玩偶" },
                    { name: "被无色之王附体的路人", items: "一把小刀, 混乱的记忆" }
                ],
                talents: [
                    {name: "王权者(觉醒)", color: "SSS", cost: 50000, desc: "你被石板选中成为新一代的王。头顶显现达摩克利斯之剑，拥有展开圣域、赋予族人能力和毁灭城市的绝对力量。", type: "exclusive"},
                    {name: "赤之火焰(破坏)", color: "A", cost: 1500, desc: "加入吠舞罗获得的能力。你可以释放出具有极高破坏力的红色火焰，能烧尽一切束缚。性格会变得越来越暴躁。", type: "exclusive"},
                    {name: "青之秩序(拔刀)", color: "A", cost: 1500, desc: "加入Scepter 4获得的能力。可以使用青色的光剑进行精密斩击，擅长防御和束缚。需要严格遵守纪律才能发挥最大威力。", type: "exclusive"},
                    {name: "无色之干涉", color: "SS", cost: 6000, desc: "拥有干涉其他王权者力量的诡异能力。你可以附身他人，甚至在短时间内模仿其他王的能力，是天生的搅局者。", type: "exclusive"},
                    {name: "白银之重力", color: "SS", cost: 7000, desc: "白银之王的能力，你可以自由操控重力。飞行、念动力、甚至制造黑洞般的引力场。此外，你拥有不变的肉体，几乎永生。", type: "exclusive"},
                    {name: "绿之变革(电流)", color: "A", cost: 1200, desc: "加入绿之氏族“Jungle”。你可以操控电流和磁场，甚至能通过网络传输自己的力量，穿墙和物理穿透是家常便饭。", type: "exclusive"},
                    {name: "偏差值修正", color: "B", cost: 500, desc: "作为Scepter 4的一员，你擅长情报分析和数据处理。在战斗中能迅速计算出敌人的攻击轨迹和威斯曼偏差值。", type: "exclusive"},
                    {name: "吠舞罗的羁绊", color: "B", cost: 600, desc: "“No Blood! No Bone! No Ash!” 当队友在身边时，你的全属性提升20%，且痛觉大幅降低。", type: "exclusive"},
                    {name: "达摩克利斯坠落", color: "E", cost: 10, desc: "你的力量极其不稳定，头顶的剑随时可能掉下来毁灭方圆百里。这是必死的诅咒，但在死前能爆发无限能量。", type: "exclusive"},
                    {name: "猫的幻术", color: "S", cost: 2200, desc: "你可以像Neko一样制造大规模的认知幻觉。修改记忆、隐身、改变环境样貌，甚至能让整座城市的人把你当做朋友。", type: "exclusive"},
                    {name: "灰之守护", color: "A", cost: 1000, desc: "灰之王的能力分支，擅长制造绝对防御的雾气。在雾中你可以隐匿身形，并保护队友免受致命伤害。", type: "exclusive"},
                    {name: "黄金之国常路", color: "SS", cost: 8000, desc: "黄金之王的能力，能最大限度地引出人的潜能。你可以看穿任何人的命运和才能，并将其具象化为战斗力。", type: "exclusive"},
                    {name: "石板的低语", color: "S", cost: 3000, desc: "你能听到德累斯顿石板的声音，提前预知王权者的更替和力量的流动。这对在这个世界生存至关重要。", type: "exclusive"},
                    {name: "终端黑客", color: "C", cost: 300, desc: "你精通绿之氏族的网络技术，可以黑入大部分电子设备，通过Jungle APP发布假任务来引导玩家行动。", type: "exclusive"},
                    {name: "剑压威慑", color: "B", cost: 400, desc: "即使不是王，你的气势也足以让普通异能者动弹不得。释放威压时，周围的空气会变得沉重。", type: "exclusive"}
                ]
            },
            {
                name: "146.东京复仇者",
                desc: "不良少年的热血与眼泪。通过握手进行12年前后的时间穿越。为了拯救恋人和伙伴，必须在暴走族“东京卍会”中登上顶峰，改变悲惨的未来。",
                boss: "佐野万次郎(Mikey), 稀咲铁太, 黑川伊佐那, 柴大寿",
                identities: [
                    { name: "总是被勒索的初中生", items: "空空如也的钱包, 满脸的淤青" },
                    { name: "爱美爱主的小喽啰", items: "特攻服, 一辆经常熄火的摩托车" },
                    { name: "沟中五人众的跟班", items: "一包薯片, 少年JUMP漫画" },
                    { name: "芭流霸罗的打手", items: "金属球棒, 飞行员夹克" },
                    { name: "未来死刑囚", items: "橙色囚服, 对过去的悔恨" }
                ],
                talents: [
                    {name: "时间穿越(握手)", color: "SSS", cost: 35000, desc: "你需要一个触发者（如直人），通过握手穿越回12年前的今天。你保留未来的记忆，可以改变过去，从而改写未来。", type: "exclusive"},
                    {name: "黑色冲动", color: "SS", cost: 6000, desc: "像Mikey一样，你内心深处潜藏着无法控制的破坏欲。一旦触发，你的战斗力会呈指数级上升，但会不分敌我地杀戮。", type: "exclusive"},
                    {name: "不屈的意志(花垣)", color: "S", cost: 3000, desc: "无论被打倒多少次，无论受多重的伤，你都能站起来。这种精神感染力能让周围的队友士气爆棚，甚至策反敌人。", type: "exclusive"},
                    {name: "稀咲的谋略", color: "S", cost: 2800, desc: "你的智商和布局能力极高。你擅长操纵人心，利用情报和谎言让强大的不良少年成为你的棋子，兵不血刃地夺取组织。", type: "exclusive"},
                    {name: "喧哗上等(格斗)", color: "A", cost: 1200, desc: "你是天生的打架高手。精通街头格斗技巧，拳脚极重，能一人单挑五十名普通不良少年而不落下风。", type: "exclusive"},
                    {name: "暴走族总长气场", color: "A", cost: 1500, desc: "你天生具有领袖气质。只要你站在那里，数百名不良少年就会对你俯首称臣，为你冲锋陷阵。", type: "exclusive"},
                    {name: "Draken的心", color: "A", cost: 1000, desc: "你拥有强大的内心和道德准则，是团队的良心。在关键时刻能拉住暴走的同伴，战斗力仅次于总长。", type: "exclusive"},
                    {name: "预知未来(片段)", color: "SS", cost: 5000, desc: "在极度紧张时，你能看到几秒钟后的悲剧画面（如谁被刀刺中）。这给你改变瞬间局势的机会。", type: "exclusive"},
                    {name: "摩托车神技", color: "B", cost: 500, desc: "你的机车驾驶技术出神入化，那是你的手足。无论在狭窄巷弄还是高速公路，都没人能追上你的CB250T。", type: "exclusive"},
                    {name: "干架专家(武器)", color: "B", cost: 600, desc: "你擅长使用各种违规武器（甩棍、指虎、砖头）。下手狠辣，专攻要害，是令人闻风丧胆的卑鄙战士。", type: "exclusive"},
                    {name: "天竺的富裕", color: "C", cost: 400, desc: "你拥有雄厚的资金支持，可以轻易摆平警察和收买人心。在不良少年的世界里，钱也是一种强大的武器。", type: "exclusive"},
                    {name: "双龙的羁绊", color: "B", cost: 700, desc: "当你和选定的搭档一起战斗时，默契度达到满值。你们可以背靠背作战，互相弥补死角，战力翻倍。", type: "exclusive"},
                    {name: "传说中的不良", color: "A", cost: 1800, desc: "你是类似黑龙初代那样的传说人物。你的名字本身就能吓退一般的帮派，招募小弟时必定成功。", type: "exclusive"},
                    {name: "耐力怪物", color: "B", cost: 800, desc: "你的抗击打能力异常惊人，即使被钢管击中头部也能保持清醒。这让你在持久战中占据绝对优势。", type: "exclusive"},
                    {name: "梵天的纹身", color: "S", cost: 2500, desc: "你加入了未来的犯罪组织梵天。虽然身处黑暗，但你掌握了枪械使用和黑道运作的规则，是冷酷的执行者。", type: "exclusive"}
                ]
            },
            {
                name: "147.国王排名",
                desc: "一个根据国王的强弱进行排名的世界。聋哑且无力的波吉王子，与影子一族的卡克，踏上了成为最伟大国王的旅程。充满童话色彩却又残酷的成长史。",
                boss: "伯斯王, 米兰乔, 欧肯, 冥府之王德斯哈",
                identities: [
                    { name: "伯斯王国的守门士兵", items: "长矛, 一身沉重的铠甲" },
                    { name: "冥府骑士团成员", items: "漆黑的盔甲, 处刑用的斧头" },
                    { name: "受诅咒的村民", items: "破烂的农具, 无法说话的嘴巴" },
                    { name: "影子一族的幸存者", items: "藏在影子里的身体, 一个偷来的苹果" },
                    { name: "蛇使者的学徒", items: "一篮子毒蛇, 解毒剂" }
                ],
                talents: [
                    {name: "巨人的力量(被夺)", color: "E", cost: 50, desc: "你本该拥有举世无双的巨人力量，但被父亲夺走。你现在身体孱弱，连把剑都举不起来，只能靠闪避生存。", type: "exclusive"},
                    {name: "巨人的力量(完全体)", color: "SSS", cost: 30000, desc: "你继承了伯斯王全部的力量。单手可以挥舞大山，一拳能粉碎城墙，是物理力量的顶点，且对所有毒素免疫。", type: "exclusive"},
                    {name: "德斯帕的教导", color: "S", cost: 2800, desc: "你师从冥府的智者德斯帕。虽然没有力量，但你学会了“让弱者也能战胜强者”的剑术，专攻敌人的弱点和神经。", type: "exclusive"},
                    {name: "影子的效忠", color: "A", cost: 1500, desc: "你获得了一位影子一族的伙伴。他可以藏在你的影子里，变成任何形状（如盾牌、钥匙），是你最忠诚的护卫。", type: "exclusive"},
                    {name: "治愈魔法(希林)", color: "S", cost: 2500, desc: "你拥有强大的治愈魔法，可以瞬间治愈断肢和重伤。但每次施法都会消耗大量的体力，甚至让你虚脱。", type: "exclusive"},
                    {name: "不死的诅咒(欧肯)", color: "SS", cost: 8000, desc: "你获得了不死之身，无论受到什么伤害都会瞬间复原。但代价是失去理智，变成只知道杀戮的怪物。", type: "exclusive"},
                    {name: "神之宝库", color: "SS", cost: 7000, desc: "你可以进入国王排名第一名才能进入的宝库。并在里面挑选一件神器，但这往往伴随着某种疯狂的代价。", type: "exclusive"},
                    {name: "蛇使者", color: "B", cost: 600, desc: "你可以控制巨大的双头蛇进行战斗。蛇不仅是武器，也是侦察兵和交通工具。你需要定期喂食它们鲜肉。", type: "exclusive"},
                    {name: "读唇术", color: "C", cost: 150, desc: "为了生存，你学会了读唇术。即使听不到声音，你也能完美理解别人的对话，甚至能看穿别人的窃窃私语。", type: "exclusive"},
                    {name: "极致闪避", color: "A", cost: 1200, desc: "因为没有力量格挡，你练就了极限的闪避能力。你可以像波吉一样，凭借直觉躲开所有致命攻击，毫发无伤。", type: "exclusive"},
                    {name: "魔镜的低语", color: "A", cost: 2000, desc: "你拥有一面知晓一切的魔镜（米兰乔）。她会给你提供完美的情报和计谋，但也会诱导你走向黑暗。", type: "exclusive"},
                    {name: "冥府雷击", color: "A", cost: 1600, desc: "作为冥府之王的血脉，你可以从手中释放出强大的雷电。这不仅能攻击敌人，还能用来强化自身的神经反应速度。", type: "exclusive"},
                    {name: "勇气的波纹", color: "B", cost: 800, desc: "你的勇气能转化为实质的力量。当你面对不可战胜的强敌仍不退缩时，你的攻击有几率造成暴击。", type: "exclusive"},
                    {name: "野兽沟通", color: "C", cost: 300, desc: "你能听懂动物的语言，并与它们成为朋友。在野外冒险时，你会得到森林生物的帮助。", type: "exclusive"},
                    {name: "四天王的武艺", color: "S", cost: 2200, desc: "你继承了多玛斯或阿庇斯的武艺。无论是剑术大师还是枪术宗师，你都是王国数一数二的战士。", type: "exclusive"}
                ]
            },
            {
                name: "148.工作细胞",
                desc: "人体内部的微观世界。37兆2千亿个细胞在全年无休地工作。红细胞运送氧气，白细胞驱除细菌，血小板修复伤口。每一次擦伤都是一场世界大战。",
                boss: "癌细胞, 金黄色葡萄球菌, 肺炎链球菌, 登革热病毒",
                identities: [
                    { name: "迷路的新人红血球", items: "一箱氧气, 地图(看不懂)" },
                    { name: "总是愤怒的杀手T细胞", items: "写着KILL的帽子, 强壮的肌肉" },
                    { name: "可爱的血小板", items: "凝血因子网, 施工旗帜" },
                    { name: "一般的细胞大叔", items: "自家公寓的钥匙, 复制分裂说明书" },
                    { name: "被寄生的流感细胞", items: "病毒触手, 持续的高热" }
                ],
                talents: [
                    {name: "癌细胞(无限增殖)", color: "SSS", cost: 45000, desc: "你是细胞中的BUG。你可以无视身体规则无限分裂，伪装成正常细胞，消耗大量养分构建自己的堡垒，最终导致机体死亡。", type: "exclusive"},
                    {name: "白血球(游走)", color: "A", cost: 1200, desc: "你可以自由穿梭于血管壁和组织之间（游走）。手持匕首，对细菌和病毒有极强的杀伤力，且自带细菌雷达。", type: "exclusive"},
                    {name: "巨噬细胞(柴刀)", color: "S", cost: 2500, desc: "外表是温柔的女仆，实则是杀戮机器。手持巨大的柴刀或钝器，能微笑着屠杀大量细菌，并承担清理尸体的工作。", type: "exclusive"},
                    {name: "血小板(凝血)", color: "B", cost: 800, desc: "虽然战斗力不强，但你是修复伤口的关键。可以指挥同伴编织纤维蛋白网，封堵巨大的裂口（伤口），改变地形。", type: "exclusive"},
                    {name: "红血球(运送)", color: "C", cost: 200, desc: "你的耐力极好，能在复杂的循环系统中奔跑。负责运送氧气和养分，是维持世界（身体）运转的基石。容易迷路。", type: "exclusive"},
                    {name: "杀手T细胞(必杀)", color: "A", cost: 1500, desc: "经过胸腺学校的魔鬼训练，你是精英战士。擅长徒手格斗，专门识别并处决被病毒感染的细胞，绝不留情。", type: "exclusive"},
                    {name: "B细胞(抗体)", color: "S", cost: 2000, desc: "你不需要近身肉搏，可以发射针对特定敌人的生化导弹（抗体）。一旦锁定敌人弱点，就能进行地毯式轰炸。", type: "exclusive"},
                    {name: "记忆细胞(情报)", color: "B", cost: 600, desc: "你拥有绝对记忆。只要是曾经入侵过的敌人，你都能瞬间调出对方的弱点和应对方案，并预警免疫系统。", type: "exclusive"},
                    {name: "类固醇注射", color: "SS", cost: 6000, desc: "作为外来药物援军，你是毁灭性的机器人。无差别攻击所有异常源，拥有压倒性的破坏力，但副作用是会破坏周围环境。", type: "exclusive"},
                    {name: "乳酸菌的加护", color: "B", cost: 500, desc: "你与肠道内的有益菌共生。它们能为你提供额外的能量，并在关键时刻帮助你抵抗有害菌的入侵。", type: "exclusive"},
                    {name: "NK细胞(活性)", color: "A", cost: 1800, desc: "你独自行动，专门猎杀癌细胞和病毒。笑得越开心，你的战斗力就越强（活性化），拥有极高的机动性。", type: "exclusive"},
                    {name: "肥大细胞(组胺)", color: "C", cost: 300, desc: "你可以释放组胺引起过敏反应（洪水、地震）。虽然本意是驱逐异物，但往往会对世界造成巨大的破坏和混乱。", type: "exclusive"},
                    {name: "树突状细胞(鼓舞)", color: "A", cost: 1000, desc: "你掌握着所有细胞的黑历史照片。通过展示这些照片，你可以极大地活性化免疫细胞，让他们战斗力爆表。", type: "exclusive"},
                    {name: "溶血性贫血", color: "E", cost: 30, desc: "你的红血球非常脆弱，容易破裂死亡。这导致你长期处于缺氧状态，体能极差，随时可能晕倒。", type: "exclusive"},
                    {name: "输血援军", color: "S", cost: 2200, desc: "在危急时刻，你可以召唤来自另一个世界（身体）的大量红血球和血浆支援，瞬间扭转资源枯竭的局面。", type: "exclusive"}
                ]
            },
            {
                name: "149.兽娘动物园",
                desc: "加帕里公园，一个由神秘物质“砂之星”将动物变成人形“朋友”（Friends）的乐园。但吃人的怪物“天蓝怪”也潜伏其中。你是谁？你擅长什么？",
                boss: "巨型天蓝怪, 黑色天蓝怪, 猎人, 轰炸机(过去遗物)",
                identities: [
                    { name: "迷路的背包客", items: "一顶有羽毛的帽子, 地图, 背包" },
                    { name: "大草原的薮猫", items: "一个加帕里馒头, 狩猎游戏玩具" },
                    { name: "图书馆的猫头鹰博士", items: "博士帽, 一本看不懂的书" },
                    { name: "企鹅偶像团体的练习生", items: "麦克风, 演出服" },
                    { name: "负责解说的导游机器人", items: "幸运兽的外壳, 录音设备" }
                ],
                talents: [
                    {name: "砂之星的奇迹", color: "SS", cost: 7000, desc: "你拥有极高浓度的砂之星亲和力。受伤后可以迅速再生，甚至在濒死时发生奇迹般的进化，获得新的形态。", type: "exclusive"},
                    {name: "野性解放", color: "A", cost: 1500, desc: "作为Friends，你可以完全解放原本动物的力量。无论是狮子的咬合力还是猎豹的速度，都能在人形状态下完美发挥。", type: "exclusive"},
                    {name: "天蓝怪猎手", color: "S", cost: 2200, desc: "你精通猎杀天蓝怪（Cerulean）的技巧。攻击必定命中其背后的石块弱点，且能感知到潜伏在地下的敌人。", type: "exclusive"},
                    {name: "加帕里馒头无限", color: "B", cost: 800, desc: "你的背包里似乎永远拿不完加帕里馒头。这不仅是美味的食物，含有砂之星成分，能恢复Friends的体力和伤势。", type: "exclusive"},
                    {name: "人类的智慧(背包)", color: "S", cost: 3000, desc: "在这个动物的世界里，你拥有“人类”的特权。懂得使用火、制造工具、搭建桥梁，这些简单的智慧在这里是神技。", type: "exclusive"},
                    {name: "PPP偶像光环", color: "B", cost: 600, desc: "你拥有偶像般的魅力。当你唱歌跳舞时，周围的Friends会停止争斗，天蓝怪的行动也会变得迟缓。", type: "exclusive"},
                    {name: "幸运兽的指引", color: "C", cost: 200, desc: "你总是能遇到幸运兽（Boss）。它们会为你带路，解释地形，甚至在危急时刻驾驶加帕里巴士带你逃跑。", type: "exclusive"},
                    {name: "夜行性", color: "C", cost: 150, desc: "你在夜晚的视力和战斗力不减反增。适合在夜间进行侦查和偷袭，但在白天会变得嗜睡。", type: "exclusive"},
                    {name: "飞行能力", color: "A", cost: 1200, desc: "作为鸟类Friends，你拥有翅膀。可以在空中自由飞翔，进行高空侦察或空对地攻击，占据绝对的地利。", type: "exclusive"},
                    {name: "毒素抗性", color: "B", cost: 500, desc: "你拥有类似蛇类或特定动物的抗毒体质。不仅不怕毒，甚至能从毒物中摄取营养。", type: "exclusive"},
                    {name: "四神之力(青龙)", color: "SSS", cost: 30000, desc: "你是守护加帕里公园的传说神兽之一。拥有操控天气和水的力量，是公园战力的天花板，但也受到行动限制。", type: "exclusive"},
                    {name: "拟态能力", color: "A", cost: 1000, desc: "你可以像变色龙一样与环境融为一体，或者模仿其他Friends的声音。是潜入和躲避天蓝怪的绝佳能力。", type: "exclusive"},
                    {name: "侦探直觉", color: "B", cost: 400, desc: "你拥有敏锐的观察力，能从脚印和气味中还原事件的经过。没有什么秘密能瞒过你的眼睛。", type: "exclusive"},
                    {name: "砂之星被夺", color: "E", cost: 50, desc: "你的砂之星被天蓝怪吞噬过。导致你偶尔会失去记忆，身体部分区域会变得透明，存在感逐渐消失。", type: "exclusive"},
                    {name: "绝灭种的悲哀", color: "S", cost: 2500, desc: "你是已灭绝动物的Friends。眼神中总是带着忧伤，这赋予了你强大的精神攻击抗性，且在濒死时能爆发回光返照的力量。", type: "exclusive"}
                ]
            },
            {
                name: "150.摇曳露营",
                desc: "一个没有战斗，只有露营、美食和风景的治愈世界。在富士山下搭起帐篷，煮一杯热咖啡。最大的危机是气温骤降和钱包空空。",
                boss: "寒冷的天气, 昂贵的露营装备, 熊(偶尔出现), 期末考试",
                identities: [
                    { name: "独自露营的高中生", items: "一辆摩托车, 单人帐篷, 书本" },
                    { name: "野外社团的新成员", items: "杯面, 睡袋, 充满活力的笑容" },
                    { name: "醉醺醺的顾问老师", items: "一瓶清酒, 烤肉架" },
                    { name: "露营场的管理员", items: "劈柴斧, 巡逻手电筒" },
                    { name: "爱管闲事的姐姐", items: "一辆家用轿车, 暖宝宝" }
                ],
                talents: [
                    {name: "究极抚慰(治愈)", color: "SSS", cost: 20000, desc: "在这个世界，治愈就是最强的力量。你泡的咖啡或做的饭，能瞬间净化S级强者的心灵创伤，消除所有负面状态（包括诅咒）。", type: "exclusive"},
                    {name: "单人露营的寂静", color: "A", cost: 1000, desc: "当你独自一人时，存在感归零，精神力恢复速度提升300%。你可以享受绝对的孤独与宁静，免疫精神干扰。", type: "exclusive"},
                    {name: "摩托车驾照", color: "B", cost: 500, desc: "你拥有驾驶摩托车的技能和一辆Vino小绵羊。这极大地扩展了你的行动范围，让你能到达常人无法到达的秘境。", type: "exclusive"},
                    {name: "野外厨神", color: "S", cost: 2000, desc: "你能用最简陋的锅具和食材，做出五星级美味的料理。这种食物不仅好吃，还能提供长时间的御寒buff。", type: "exclusive"},
                    {name: "抗寒体质", color: "B", cost: 400, desc: "你不怕冷，即使在零下几度的冬天睡在薄睡袋里也能安然入睡。这是冬日露营必备的神技。", type: "exclusive"},
                    {name: "打工战士", color: "C", cost: 200, desc: "你为了买装备练就了超强的打工能力。赚钱速度比常人快一倍，能迅速积累资金购买昂贵的帐篷和睡袋。", type: "exclusive"},
                    {name: "社交牛逼症(抚子)", color: "A", cost: 1200, desc: "你能和任何人（甚至动物）瞬间成为朋友。你的笑容是最好的通行证，蹭饭、蹭车、蹭装备成功率100%。", type: "exclusive"},
                    {name: "松果的问候", color: "C", cost: 50, desc: "地上的松果会对你说“你好”。这没什么实际用处，但能让你捡柴火时心情变好，容易找到干燥的引火物。", type: "exclusive"},
                    {name: "隐形富豪", color: "S", cost: 2500, desc: "你的家境殷实，拥有全套Snow Peak高端露营装备。在露营场你会成为众人羡慕的焦点，舒适度拉满。", type: "exclusive"},
                    {name: "风景摄影师", color: "B", cost: 600, desc: "你擅长捕捉绝美的风景。拍出的照片能换取大量点赞（声望），甚至能通过照片让没去过的人身临其境。", type: "exclusive"},
                    {name: "柴火达人", color: "C", cost: 150, desc: "你懂得如何挑选和劈砍柴火，能生出最完美的篝火。火焰稳定持久，不会突然熄灭或产生大量浓烟。", type: "exclusive"},
                    {name: "恶魔的诱惑(美食)", color: "A", cost: 1500, desc: "你在深夜煮东西的香味能传出十里地。这对饥饿的人来说是无法抗拒的精神攻击，能引诱任何人来到你的帐篷前。", type: "exclusive"},
                    {name: "温泉雷达", color: "B", cost: 700, desc: "你对附近的温泉有超自然的感应。泡温泉能大幅度恢复你的体力和精神，并赋予皮肤光泽。", type: "exclusive"},
                    {name: "雨男/雨女", color: "D", cost: 100, desc: "你一去露营就会下雨或阴天，看不到富士山。这对心情是巨大的打击，但雨中露营也别有一番风味。", type: "exclusive"},
                    {name: "芝麻凛的丸子头", color: "B", cost: 300, desc: "这个发型能作为雷达接收信号，也能在紧急时刻拆下来当做投掷武器（误）。实际上它增加了你的萌度。", type: "exclusive"}
                ]
            },
          {
    name: "151.轻音少女 (K-ON!)",
