                talents: [
                    {name: "北斗神拳(继承者)", color: "SSS", cost: 30000, desc: "一子单传的暗杀拳。点穴、爆头、百裂拳。你已经死了。能从内部破坏敌人，是对抗肉体强者的终极武学。", type: "exclusive"},
                    {name: "南斗圣拳(孤鹫)", color: "SS", cost: 12000, desc: "以手刀斩裂一切的阳拳。你的手指比钢铁更锋利，能将敌人像切菜一样切碎，甚至能切开真空。", type: "exclusive"},
                    {name: "无想转生", color: "SSS", cost: 50000, desc: "北斗神拳的究极奥义。领悟了悲伤之后，化身为虚无。物理攻击无法触碰到你，你就是无敌的存在。", type: "exclusive"},
                    {name: "世纪末霸者(刚拳)", color: "SS", cost: 15000, desc: "拉欧的拳法。不追求技巧，只追求极致的力量和斗气。一拳挥出，天崩地裂，连神都要畏惧。", type: "exclusive"},
                    {name: "北斗有情破颜拳", color: "S", cost: 8000, desc: "托基的慈悲之拳。被击中的人在死前不会感到痛苦，反而会感到极度的愉悦，含笑而终。", type: "exclusive"},
                    {name: "元斗皇拳", color: "S", cost: 9000, desc: "以斗气化为光刃，能从细胞层面消灭敌人。你的拳头能发出金色的光芒，远距离切割物体。", type: "exclusive"},
                    {name: "死兆星的注视", color: "D", cost: 100, desc: "你看到了死兆星，这意味着你的死期将近。全属性下降，但可能会在绝境中爆发回光返照的力量。", type: "exclusive"},
                    {name: "莫西干发型", color: "C", cost: 50, desc: "世纪末暴徒的标准发型。虽然很丑，但在荒野上能吓唬住普通人，加入暴走族更容易。", type: "exclusive"},
                    {name: "巨大的摩托车", color: "B", cost: 600, desc: "一辆改装过的重型机车，在荒漠中是唯一的交通工具，也是碾压敌人的武器。", type: "exclusive"},
                    {name: "经络秘孔知识", color: "A", cost: 2000, desc: "你熟知人体的所有穴位。虽然不会北斗神拳，但也能用简单的指法治疗疾病或让人动弹不得。", type: "exclusive"},
                    {name: "水影心", color: "S", cost: 5000, desc: "只要看过一次对手的拳法，就能模仿并据为己有。这是北斗神拳的奥义之一，让你成为全能战士。", type: "exclusive"},
                    {name: "修罗之国的血统", color: "A", cost: 2500, desc: "你来自战斗之国，天生好战，从学会走路起就开始杀人。战斗本能极强，但缺乏人性。", type: "exclusive"},
                    {name: "魔斗气", color: "SS", cost: 10000, desc: "走火入魔后的邪恶斗气。虽然会侵蚀理智，但能让空间扭曲，让敌人产生幻觉，力量无穷。", type: "exclusive"},
                    {name: "种子的守护者", color: "B", cost: 300, desc: "你坚信未来会有希望。这种信念让你在饥饿和干渴中比常人更能坚持，意志力+100%。", type: "exclusive"},
                    {name: "岩山两斩波", color: "B", cost: 800, desc: "单纯的手刀劈砍，足以劈开岩石和头骨，是初级强者的标志性招式。", type: "exclusive"}
                ]
            },
            {
                name: "167.筋肉人",
                desc: "超人摔角的世界。来自宇宙各地的超人为了正义与友情（还有猪肉盖饭）在擂台上厮杀。这里没有复杂的阴谋，只有热血、汗水和必杀技。",
                boss: "筋肉人(斯古鲁), 恶魔将军, 完美超人始祖",
                identities: [
                    { name: "总是被踩扁的裁判", items: "一件黑白条纹衫, 一个哨子" },
                    { name: "卖猪肉盖饭的小贩", items: "一碗特盛猪肉盖饭, 一条围裙" },
                    { name: "观众席上的解说员", items: "一个麦克风, 一副激动的眼镜" },
                    { name: "被超人破坏的房屋屋主", items: "一张房屋损毁清单, 一块砖头" },
                    { name: "二流超人团体的陪练", items: "满身的淤青, 一个护具" }
                ],
                talents: [
                    {name: "火事场爆发力", color: "SSS", cost: 25000, desc: "当面临绝境或为了友情而战时，你的力量会呈指数级增长，甚至能逆转因果，创造奇迹。", type: "exclusive"},
                    {name: "筋肉爆裂(Kiniku Buster)", color: "S", cost: 4000, desc: "经典的必杀技。锁住敌人的脖子、腰和大腿，从高空落下，对颈椎和脊椎造成毁灭性打击。", type: "exclusive"},
                    {name: "超人强度(1000万)", color: "SS", cost: 8000, desc: "你的基础数值极高，拥有千万级别的超人强度。光是站着就能让低级超人感到窒息。", type: "exclusive"},
                    {name: "恶魔将军的硬度", color: "SS", cost: 10000, desc: "你可以自由控制身体的硬度，最高可达硬度10(钻石)。既能防御一切物理攻击，也能化身为最锋利的刀刃。", type: "exclusive"},
                    {name: "肉帘(Face Flash)", color: "SSS", cost: 20000, desc: "王族特有的能力。掀开面具发出的光芒，不仅能净化邪恶，还能让死去的河流复苏，甚至复活死者。", type: "exclusive"},
                    {name: "友情之力", color: "A", cost: 1500, desc: "队友越多，你的能力越强。当队友为你加油时，你会获得持续的回血和攻击力加成。", type: "exclusive"},
                    {name: "柏林红雨", color: "B", cost: 800, desc: "布罗肯Jr的绝技。手刀挥出红色的雾气，那是敌人的鲜血。带有切割和致盲效果。", type: "exclusive"},
                    {name: "地狱断头台", color: "S", cost: 5000, desc: "恶魔将军的必杀。将敌人踢上高空，然后用膝盖粉碎其颈部。判定极强，几乎无法防御。", type: "exclusive"},
                    {name: "阿修罗三面六臂", color: "A", cost: 2000, desc: "你拥有三张脸和六只手臂，能同时进行三次攻击或防御，全方位无死角。", type: "exclusive"},
                    {name: "牛角飓风", color: "B", cost: 1000, desc: "水牛人的绝技。利用巨大的牛角进行高速旋转冲撞，能贯穿钢铁，威力巨大。", type: "exclusive"},
                    {name: "四次元杀法", color: "A", cost: 2500, desc: "黑洞人的能力。你可以通过影子或身体上的黑洞进入异次元，进行瞬移或将敌人放逐。", type: "exclusive"},
                    {name: "罗宾战法", color: "A", cost: 1800, desc: "罗宾假面传授的战术素养。冷静分析对手弱点，利用环境和心理战取得胜利，不仅靠蛮力。", type: "exclusive"},
                    {name: "大蒜能量", color: "C", cost: 100, desc: "吃下大蒜后，你的体型会巨大化，力量翻倍，但口气会变得很臭，容易被嫌弃。", type: "exclusive"},
                    {name: "超人墓场的通行证", color: "B", cost: 600, desc: "死后可以进入超人墓场打工，只要攒够了工钱就能复活。这是一条宝贵的后路。", type: "exclusive"},
                    {name: "完美无量大数军", color: "SS", cost: 9000, desc: "加入完美超人的阵营。抛弃情感，追求绝对的力量和完美。全属性大幅提升，但无法获得友情之力。", type: "exclusive"}
                ]
            },
            {
                name: "168.圣传",
                desc: "天界，三百年前雷神帝释天谋反，杀天帝而自立。预言中的“六星”将汇聚，在这个华丽而残酷的神话世界里，为了改变命运而战。",
                boss: "帝释天, 阿修罗, 乾达婆王",
                identities: [
                    { name: "天界边境的流浪妖魔", items: "一根断裂的骨头, 破旧的兽皮" },
                    { name: "善见城的侍女", items: "一把孔雀扇, 一瓶在此处并不值钱的香水" },
                    { name: "夜叉族的幸存儿童", items: "族人的骨灰, 一把生锈的小刀" },
                    { name: "被封印在冰里的罪人", items: "永不融化的冰块, 沉重的镣铐" },
                    { name: "占星师的学徒", items: "碎裂的水晶球, 看不懂的星象图" }
                ],
                talents: [
                    {name: "阿修罗的血统", color: "SSS", cost: 35000, desc: "破坏神的血脉。平时天真无邪，一旦觉醒则化身为毁灭世界的红莲之火。拥有最强的魔力和战斗本能。", type: "exclusive"},
                    {name: "修罗刀", color: "SS", cost: 12000, desc: "从阿修罗体内诞生的神剑，只有阿修罗王能使用。它是天界的脊梁，拥有斩断命运的力量。", type: "exclusive"},
                    {name: "星见(预言)", color: "SSS", cost: 20000, desc: "九曜的能力。你能看到未来的轨迹，虽然命运难以改变，但你可以提前布局，寻找那一线生机。", type: "exclusive"},
                    {name: "帝释天的雷电", color: "SS", cost: 15000, desc: "最强武神的力量。操控毁天灭地的雷电，一击便能摧毁一座城池。为了守护想要的东西，不惜堕落为魔。", type: "exclusive"},
                    {name: "夜叉王的剑术", color: "S", cost: 6000, desc: "夜摩刀的使用者。速度极快，剑气能形成真空波。为了守护阿修罗，你的防御力和意志力极强。", type: "exclusive"},
                    {name: "迦楼罗的飞翔", color: "A", cost: 2500, desc: "拥有巨大的金翼，你是天界的空中霸主。能召唤神鸟攻击，且飞行速度无人能及。", type: "exclusive"},
                    {name: "龙王的臂力", color: "A", cost: 3000, desc: "虽然外表年轻，但龙族拥有惊人的怪力，能轻易粉碎岩石。水中作战能力S级。", type: "exclusive"},
                    {name: "乾达婆的琴音", color: "S", cost: 5000, desc: "既是天界的乐师也是最强的战士。你的琴音能以此杀人于无形，制造幻觉，或通过共振粉碎内脏。", type: "exclusive"},
                    {name: "苏摩的灵血", color: "SS", cost: 8000, desc: "全族被灭的悲剧血统。你的血是长生不老的灵药，喝下它的人能获得不死之身。这让你成为众矢之的。", type: "exclusive"},
                    {name: "毗沙门天的盾", color: "A", cost: 4000, desc: "北方将军的防御力。坚不可摧的铠甲和盾牌，能抵挡大部分物理和魔法攻击。", type: "exclusive"},
                    {name: "孔雀的魔眼", color: "SS", cost: 10000, desc: "堕天之眼。拥有紫色的瞳孔，能看穿世间一切真相，使用禁忌的黑魔法，甚至能打开魔界之门。", type: "exclusive"},
                    {name: "俱摩罗天的爆破", color: "B", cost: 1500, desc: "操控火药和爆炸。虽然在神话世界显得格格不入，但破坏力实打实，能制造巨大的混乱。", type: "exclusive"},
                    {name: "天界的乐师", color: "C", cost: 500, desc: "你精通各种乐器，能演奏出安抚灵魂的乐曲，回复队友的精神力。", type: "exclusive"},
                    {name: "善见城的通行证", color: "B", cost: 800, desc: "作为天帝的居所，这里守备森严。拥有通行证能让你自由出入权力中心，获取情报。", type: "exclusive"},
                    {name: "命运的红线", color: "D", cost: 200, desc: "你与六星中的某一位有着剪不断的羁绊。这会让你卷入灭世的漩涡，但也可能成为关键的变数。", type: "exclusive"}
                ]
            },
            {
                name: "169.X战记",
                desc: "1999年，世界末日。天龙（七封印）试图维持现状守护人类，地龙（七御史）试图引发地震毁灭人类让地球重生。神威的选择决定未来。",
                boss: "司狼神威, 桃生封真, 梦见(丁/庚)",
                identities: [
                    { name: "国立竞技场的保安", items: "一个手电筒, 一串钥匙" },
                    { name: "CLAMP学园的小学生", items: "一个巨大的校徽, 一本侦探手册" },
                    { name: "阳光大厦的清洁工", items: "一辆清洁车, 一瓶玻璃水" },
                    { name: "有预知梦能力的少女", items: "一个破碎的护身符, 满脸的泪水" },
                    { name: "国会议事厅的秘书", items: "一叠文件, 一部加密手机" }
                ],
                talents: [
                    {name: "神威之力(神之威严)", color: "SSS", cost: 40000, desc: "决定地球命运的力量。你可以选择成为救世主或灭世主。拥有无限的潜力和改变现实的能力。", type: "exclusive"},
                    {name: "结界(Kekkai)", color: "S", cost: 5000, desc: "制造一个独立的空间，将战斗对现实世界的破坏隔绝。结界破裂时，受到的伤害会反馈给施术者。", type: "exclusive"},
                    {name: "神剑(Shinken)", color: "SS", cost: 12000, desc: "从女性体内诞生的圣剑。它是地球意志的具象化，是对抗末日的唯一武器。拥有斩断结界和灵体的力量。", type: "exclusive"},
                    {name: "梦见(预知梦)", color: "SS", cost: 15000, desc: "丁姬或庚姬的能力。在梦中看到未来的片段。虽然无法完全看清，但能预知大灾难的发生地点。", type: "exclusive"},
                    {name: "阴阳术(皇一门)", color: "A", cost: 3000, desc: "皇昴流的术法。利用符咒和式神进行攻击或防御。对灵体有特效，能反弹诅咒。", type: "exclusive"},
                    {name: "风之操控", color: "A", cost: 2500, desc: "猫依护刃的能力。召唤犬鬼，不仅能操控风刃攻击，还能在受伤时由犬鬼代为承受伤害。", type: "exclusive"},
                    {name: "火之操控", color: "A", cost: 2500, desc: "夏澄火炼的能力。身为特种陪酒女郎，你能操控火焰，虽然射程不远，但爆发力极强。", type: "exclusive"},
                    {name: "水之操控", color: "A", cost: 2500, desc: "苍轨征一朗的能力。作为风水师，你能操控水流和冰，还能感知大地的脉动。", type: "exclusive"},
                    {name: "电磁操控", color: "S", cost: 4000, desc: "八头司飒姬的能力。作为超级电脑，你能操控电缆和电子设备，甚至能黑入全球网络。", type: "exclusive"},
                    {name: "影之使者", color: "SS", cost: 8000, desc: "樱冢星史郎的暗杀术。利用樱花和阴影进行攻击，美丽而残忍。拥有极强的幻术和束缚能力。", type: "exclusive"},
                    {name: "双重人格(封真)", color: "SS", cost: 10000, desc: "当你作为地龙觉醒时，你会变得冷酷无情，能够看穿人心的弱点，并模仿任何人的技能。", type: "exclusive"},
                    {name: "伊势神宫的守护", color: "B", cost: 1000, desc: "鬼咒岚的能力。你的剑术高超，且体内流淌着巫女之血，对邪恶力量有天然的抗性。", type: "exclusive"},
                    {name: "身体液化", color: "A", cost: 3500, desc: "那吒的能力。你的身体是人造的，可以随意液化变形，免疫大部分物理攻击。", type: "exclusive"},
                    {name: "地球的悲鸣", color: "C", cost: 200, desc: "你能听到地球的痛苦，这让你精神压力很大，但也让你能感知到地龙的行动。", type: "exclusive"},
                    {name: "CLAMP学园的资助", color: "B", cost: 5000, desc: "你背后有财阀支持。虽然战斗力不强，但你能调动无限的资金和高科技装备。", type: "exclusive"}
                ]
            },
            {
                name: "170.魔神坛斗士",
                desc: "妖邪界入侵人间。九件铠甲分别代表“仁义礼智信忠孝悌忍”。五位少年穿上铠甲，对抗妖邪帝王阿罗醐。",
                boss: "阿罗醐, 朱天童子, 妖邪四天王",
                identities: [
                    { name: "新宿街头的懵懂少年", items: "一个滑板, 一只宠物白虎(幼崽)" },
                    { name: "被妖邪附体的路人", items: "浑浊的眼神, 无法控制的肢体" },
                    { name: "深山神社的扫地僧", items: "一把竹扫帚, 一本古老的经书" },
                    { name: "妖邪界的底层杂兵", items: "一把生锈的镰刀, 随时会碎的甲壳" },
                    { name: "新闻报道员", items: "一个话筒, 一辆转播车" }
                ],
                talents: [
                    {name: "辉煌帝铠甲(白光)", color: "SSS", cost: 30000, desc: "集合五件铠甲力量召唤出的究极铠甲。代表太阳的力量，能净化一切妖邪。穿上它，你就是无敌的战神。", type: "exclusive"},
                    {name: "烈火之铠(仁)", color: "SS", cost: 10000, desc: "双炎斩！操控火焰的力量。作为队长，你拥有最均衡的能力和最强的爆发力。对热能攻击免疫。", type: "exclusive"},
                    {name: "光轮之铠(礼)", color: "S", cost: 8000, desc: "雷光斩！操控光与雷电。速度最快，能致盲敌人。虽然防御稍弱，但攻击频率极高。", type: "exclusive"},
                    {name: "水浒之铠(信)", color: "S", cost: 8000, desc: "超流破！操控水流。在水中战斗力翻倍。性格冷静，能化解敌人的攻势，以柔克刚。", type: "exclusive"},
                    {name: "金刚之铠(义)", color: "S", cost: 8000, desc: "岩铁碎！操控大地。防御力最强，能制造地震。武器是三叉戟，力量巨大。", type: "exclusive"},
                    {name: "天空之铠(智)", color: "S", cost: 8000, desc: "真空波！操控空气和重力。能在空中飞行，利用气压远程攻击敌人。智商极高，擅长分析。", type: "exclusive"},
                    {name: "阿罗醐的妖气", color: "SS", cost: 12000, desc: "妖邪帝王的力量。能无限再生，吞噬人类的负面情绪增强力量。只要人类有恶念，你就不会真正死亡。", type: "exclusive"},
                    {name: "地灵众的忍术", color: "B", cost: 1500, desc: "妖邪界杂兵的技能。虽然单体不强，但擅长遁地和群殴，生命力顽强。", type: "exclusive"},
                    {name: "迦雄须的指引", color: "A", cost: 2000, desc: "一位神秘锡杖法师的教导。能提升你的精神力，让你在绝境中领悟铠甲的真谛，解锁隐藏技能。", type: "exclusive"},
                    {name: "白炎(老虎)", color: "S", cost: 3500, desc: "拥有一只身披铠甲的巨大白虎作为坐骑和战友。它忠诚无比，战斗力不亚于一件铠甲。", type: "exclusive"},
                    {name: "四天王的魔甲", color: "A", cost: 5000, desc: "你可以选择穿上邪恶四天王的铠甲（鬼魔毒幻）。虽然力量强大，但容易被妖气侵蚀心智。", type: "exclusive"},
                    {name: "武装解除", color: "D", cost: 100, desc: "你的铠甲在受到重创时会自动解体，让你变回普通人。这既是保护机制，也是致命弱点。", type: "exclusive"},
                    {name: "弹簧腿", color: "C", cost: 200, desc: "你的腿部力量惊人，能跳得很高，适合在城市废墟中移动。", type: "exclusive"},
                    {name: "妖邪之门", color: "SS", cost: 9000, desc: "打开连接人间与妖邪界的通道。能召唤无数妖兵助阵，或者将敌人放逐到异世界。", type: "exclusive"},
                    {name: "心的力量", color: "SSS", cost: 15000, desc: "铠甲的本质是心。只要你的仁义礼智信之心不灭，铠甲就能无限进化，甚至修复破损。", type: "exclusive"}
                ]
            },
                      {
                name: "171.天空战记",
                desc: "印度神话风格的异世界“天空界”。创造神梵天失去踪影，破坏神湿婆蠢蠢欲动。身穿“神甲胄”的八部众为了保卫或毁灭世界而战，真言（Mantra）的力量决定一切。",
                boss: "因陀罗, 破坏神湿婆, 不动明王",
                identities: [
                    { name: "天空界边境的难民", items: "一件破烂的麻布长袍, 一块干硬的黑面包" },
                    { name: "提婆神军的下级杂兵", items: "断裂的长矛, 只有半截的护胸甲" },
                    { name: "夜叉王麾下的巡逻兵", items: "磨损的弯刀, 一个用来发信号的号角" },
                    { name: "被流放的苦行僧", items: "一串普通的木质念珠, 记载着模糊经文的树叶" },
                    { name: "人界转生而来的迷途者", items: "一套现代的高中生制服, 一个没电的随身听" }
                ],
                talents: [
                    {name: "流离之魂", color: "E", cost: 50, desc: "你经常感到灵魂与肉体的不协调，仿佛你不属于这个世界，容易在战斗中走神。", type: "exclusive"},
                    {name: "微弱流摩", color: "D", cost: 180, desc: "你体内拥有一丝微弱的流摩（Soma），只能用来点亮指尖或稍微缓解疲劳。", type: "exclusive"},
                    {name: "基础格斗术", color: "C", cost: 250, desc: "天空界士兵通用的格斗技巧，虽然动作朴实，但在战场上能稍微增加一点生存率。", type: "exclusive"},
                    {name: "虔诚之心", color: "C", cost: 300, desc: "你对调和神慧明大师拥有坚定的信仰，这种精神力量能让你稍微抵抗精神攻击。", type: "exclusive"},
                    {name: "风之敏捷", color: "B", cost: 600, desc: "你的动作轻盈如风，虽然不能飞行，但在复杂地形中的移动速度远超常人。", type: "exclusive"},
                    {name: "神甲胄适应性(低)", color: "B", cost: 800, desc: "你的身体素质勉强可以穿戴最低级的神甲胄，虽然无法发挥全部威力，但至少不会被压垮。", type: "exclusive"},
                    {name: "真言诵读(入门)", color: "A", cost: 1200, desc: "你学会了基础的真言发音，可以通过吟唱简单的咒语来强化武器的硬度。", type: "exclusive"},
                    {name: "黑流摩亲和", color: "A", cost: 1500, desc: "你对破坏神的力量感到莫名的亲切，这让你更容易学习暗黑系的法术，但心智容易受到侵蚀。", type: "exclusive"},
                    {name: "八部众候补", color: "S", cost: 2500, desc: "你拥有成为八部众之一的潜力，体内的流摩量是常人的十倍，能够感知到神甲胄的呼唤。", type: "exclusive"},
                    {name: "神甲胄(量产型)", color: "S", cost: 3500, desc: "一套制式的神甲胄，能够将你的流摩转化为实体能量，提供飞行能力和强大的防御力。", type: "exclusive"},
                    {name: "伊诺拉自然之力", color: "S", cost: 4000, desc: "你可以像龙王良马一样，借用自然界的力量（如火、水、木）来增强自己的招式威力。", type: "exclusive"},
                    {name: "修罗魔破拳(残篇)", color: "SS", cost: 6000, desc: "修罗王一平的必杀技残篇，虽然不完整，但仅仅一击就足以粉碎岩石和低级神将的铠甲。", type: "exclusive"},
                    {name: "曼陀罗阵", color: "SS", cost: 8500, desc: "你可以与同伴组成曼陀罗阵，集合众人的流摩，释放出足以封印神明的强大能量。", type: "exclusive"},
                    {name: "梵天神甲胄", color: "SSS", cost: 12000, desc: "传说中创造神梵天的甲胄，拥有统御万物的力量。穿上它，你就是天空界的主宰，光芒足以照亮整个位面。", type: "exclusive"},
                    {name: "调和神转世", color: "SSS", cost: 15000, desc: "你是慧明大师的转世，拥有无穷无尽的金色流摩。你的存在本身就是为了维持世界的平衡，能够净化一切黑流摩。", type: "exclusive"}
                ]
            },
            {
                name: "172.宇宙骑士",
                desc: "被外星生物拉达姆（Radam）侵略的未来地球。人类被改造成“铁加曼”（Tekkaman）作为侵略兵器。这是一个关于亲人相残、失去与遗忘的悲剧世界。",
                boss: "铁加曼欧米茄(健吾), 铁加曼依比路, 拉达姆母舰",
                identities: [
                    { name: "轨道环废墟的幸存者", items: "一个破损的氧气面罩, 半瓶浑浊的循环水" },
                    { name: "联合防卫军的逃兵", items: "一把没有弹药的激光手枪, 一张被血染红的家人照片" },
                    { name: "赤道环附近的拾荒者", items: "一根用来撬门的铁棍, 一个辐射检测仪" },
                    { name: "被拉达姆寄生未遂的植物人", items: "一身满是粘液的病号服, 一个永远无法愈合的伤口" },
                    { name: "外宇宙开发机构的底层研究员", items: "一叠关于拉达姆树的观察报告, 一副破碎的眼镜" }
                ],
                talents: [
                    {name: "基因排斥", color: "E", cost: 100, desc: "你的基因极度排斥外来改造，这意味着你几乎无法接受任何强化手术，注定只能是凡人。", type: "exclusive"},
                    {name: "拉达姆花粉过敏", color: "D", cost: 150, desc: "只要靠近拉达姆树开花的地方，你就会剧烈咳嗽并伴随幻觉，极大降低生存能力。", type: "exclusive"},
                    {name: "旧式机甲驾驶", color: "C", cost: 300, desc: "你熟练掌握旧时代工程机甲的操作，虽然不能对抗拉达姆兽，但用来搬砖逃跑还是没问题的。", type: "exclusive"},
                    {name: "辐射抗性", color: "C", cost: 400, desc: "在被污染的地球表面长期生存，你的身体产生了一定的辐射抗性，能在废墟中活得更久。", type: "exclusive"},
                    {name: "费米子理论精通", color: "B", cost: 700, desc: "你深刻理解费米子武器的原理，能够维修和改良联合防卫军的激光武器。", type: "exclusive"},
                    {name: "拉达姆兽感知", color: "B", cost: 900, desc: "你对拉达姆兽特有的生物电波很敏感，能比雷达更早发现敌人的接近。", type: "exclusive"},
                    {name: "蓝地球号驾驶员", color: "A", cost: 1500, desc: "你是顶尖的飞行员，能够驾驶蓝地球号战机在拉达姆兽群中穿梭，进行精准打击。", type: "exclusive"},
                    {name: "素体体质", color: "A", cost: 1800, desc: "你的身体非常适合被改造成铁加曼，如果被拉达姆捕获，你极大概率不会变成拉达姆兽，而是成为铁加曼素体。", type: "exclusive"},
                    {name: "反物质炮(Sol Tekkaman)", color: "S", cost: 3000, desc: "你拥有一套人类仿制的索尔铁加曼装甲，装备了费米子炮，虽然不如正版，但足以消灭拉达姆兽。", type: "exclusive"},
                    {name: "水晶力场", color: "S", cost: 4500, desc: "作为铁加曼，你可以展开能量力场，免疫常规物理和激光攻击，并在太空中自由飞行。", type: "exclusive"},
                    {name: "反物质炮(Voltekka)", color: "SS", cost: 7000, desc: "正版铁加曼的终极武器。打开肩部的发射口，释放反物质粒子流，瞬间蒸发路径上的一切物质。", type: "exclusive"},
                    {name: "不完全变身", color: "SS", cost: 8000, desc: "你拥有变身铁加曼的能力，但系统不完整。变身时间有限制，且每次变身都会对身体造成巨大负担，甚至缩短寿命。", type: "exclusive"},
                    {name: "超进化(Blaster化)", color: "SSS", cost: 18000, desc: "通过禁忌的技术进行的二次强化。你的力量成倍增长，全身覆盖尖刺装甲，反物质炮威力足以毁灭小型天体，但代价是逐渐丧失记忆和人性。", type: "exclusive"},
                    {name: "拉达姆主脑连接", color: "SSS", cost: 20000, desc: "你直接连接了拉达姆的母舰意识，能够指挥所有的拉达姆兽和下级铁加曼，你是这个绝望世界的新神。", type: "exclusive"},
                    {name: "D-Boy的坚韧", color: "SSS", cost: 12000, desc: "即使身体破碎，记忆消逝，亲人死绝，你依然拥有挥刀的勇气。这种精神力量让你免疫一切精神控制，并在濒死时无限锁血。", type: "exclusive"}
                ]
            },
            {
                name: "173.魔动王(光能使者)",
                desc: "月球内部是一个充满魔法的空心世界“拉比露娜”。邪动族企图通过黑暗九邪神统治世界。只有驾驶魔动王（光能使者）的魔动战士才能拯救月球。",
                boss: "阿古拉曼德, 黑暗大邪神, 邪动族三干部",
                identities: [
                    { name: "月球表面的观光客", items: "一张过期的往返地球船票, 一个氧气不足的太空头盔" },
                    { name: "拉比露娜的长耳族平民", items: "一篮子胡萝卜, 一件粗糙的亚麻长袍" },
                    { name: "邪动帝国的奴隶矿工", items: "一把沉重的十字镐, 脚上带着沉重的铁镣" },
                    { name: "只会变戏法的流浪魔术师", items: "一副缺了几张的扑克牌, 一根会变出假花的魔术棒" },
                    { name: "被通缉的V-梅婆婆助手", items: "一个装满奇怪药草的布袋, 一本看不懂的魔法书" }
                ],
                talents: [
                    {name: "胡萝卜厌恶", color: "E", cost: 50, desc: "你极其讨厌胡萝卜，闻到味道就会浑身无力，这在以胡萝卜为主要作物的长耳族世界是个致命弱点。", type: "exclusive"},
                    {name: "滑板初学者", color: "D", cost: 120, desc: "你勉强能站在喷气滑板上不摔倒，但想要像大地那样在风中疾驰是做不到的。", type: "exclusive"},
                    {name: "长耳族感知", color: "C", cost: 250, desc: "作为长耳族（或混血），你的耳朵能听到极远处的风吹草动，对魔力流动也有一定感知。", type: "exclusive"},
                    {name: "魔动力亲和", color: "C", cost: 350, desc: "你体内蕴含着少量的魔动力，可以驱动一些简单的魔法道具，或者激活古代遗迹的机关。", type: "exclusive"},
                    {name: "格斗陀螺", color: "B", cost: 500, desc: "你精通加斯的格斗技巧，能够使用巨大的陀螺作为武器，攻防一体。", type: "exclusive"},
                    {name: "神圣蜗牛", color: "B", cost: 700, desc: "你获得了一只拉比露娜的神圣蜗牛作为宠物，虽然它跑得慢，但能通过触角进行远程通讯。", type: "exclusive"},
                    {name: "水之魔动战士", color: "A", cost: 1600, desc: "你拥有操纵水之魔动王（波涛使者）的资质。需要在巨大的水面上画出魔法阵才能召唤。", type: "exclusive"},
                    {name: "风之魔动战士", color: "A", cost: 1600, desc: "你拥有操纵风之魔动王（风暴使者）的资质。需要在强风刮起时用弓箭射出魔法阵才能召唤。", type: "exclusive"},
                    {name: "地之魔动战士", color: "A", cost: 1800, desc: "你拥有操纵地之魔动王（光能使者）的资质。需要在平坦的大地上画出巨大的六芒星才能召唤。", type: "exclusive"},
                    {name: "一刀两断·如意神剑", color: "S", cost: 4000, desc: "召唤光能使者的必杀武器。只有在魔动力达到顶峰时才能拔出，拥有切裂黑暗的绝对攻击力。", type: "exclusive"},
                    {name: "超级魔动王形态", color: "S", cost: 5500, desc: "你的魔动王进化为超级形态，脸部模式取消，常驻战斗模式，魔动力输出提升三倍。", type: "exclusive"},
                    {name: "邪动神驾驶", color: "S", cost: 3000, desc: "你投靠了邪动族，获得了一台专属的邪动神。虽然造型丑陋，但火力凶猛，且不需要画魔法阵就能召唤。", type: "exclusive"},
                    {name: "太阳王冠", color: "SS", cost: 8000, desc: "传说中的神器，拥有太阳的力量。佩戴者可以极大幅度增幅魔动力，甚至让死去的魔动王复活。", type: "exclusive"},
                    {name: "究极魔动王", color: "SSS", cost: 15000, desc: "集合了地、水、风三台魔动王的力量合体而成的究极光能使者。拥有太阳神般的威严，一击即可净化整个拉比露娜。", type: "exclusive"},
                    {name: "暗黑大邪神之力", color: "SSS", cost: 16000, desc: "你继承了暗黑大邪神的力量，身体巨大化，拥有毁灭世界的魔力，能够吞噬光与希望。", type: "exclusive"}
                ]
            },
            {
                name: "174.神龙斗士(魔神英雄传)",
                desc: "由神部界的主宰“创界山”构成的世界。多恶达统治了创界山，夺走了彩虹的颜色。救世主战部渡需要一层层净化创界山，恢复彩虹的光芒。",
                boss: "多恶达, 暗黑达, 施巴拉古大师(洗脑版)",
                identities: [
                    { name: "第一界层的普通村民", items: "一把锄头, 一袋被多恶达军抢剩下的种子" },
                    { name: "创界山的观光向导", items: "一面破损的小旗子, 一张过时的创界山地图" },
                    { name: "多恶达军的杂兵", items: "一根电击棒, 一个画着骷髅头的面具" },
                    { name: "被变成动物的居民", items: "原本是人类的意识, 现在的身体是一只鸭子" },
                    { name: "忍部一族的吊车尾忍者", items: "一枚生锈的手里剑, 总是失效的烟雾弹" }
                ],
                talents: [
                    {name: "恐高症", color: "E", cost: 50, desc: "在垂直分布的创界山，恐高症是致命的。每当你向下看时，都会眩晕并失去行动能力。", type: "exclusive"},
                    {name: "路痴", color: "D", cost: 100, desc: "你完全分不清创界山的层级和方向，经常会从第三层迷路走到第一层的多恶达军营里。", type: "exclusive"},
                    {name: "公用电话寻找", color: "C", cost: 200, desc: "你总能在最奇怪的地方找到公用电话，这对召唤战神丸非常重要（如果你认识施巴拉古大师的话）。", type: "exclusive"},
                    {name: "粘土手工艺", color: "C", cost: 250, desc: "你擅长捏粘土，虽然不能像主角一样捏出魔神，但可以捏出一些诱饵来迷惑敌人。", type: "exclusive"},
                    {name: "忍法·火美子流", color: "B", cost: 600, desc: "你学会了火美子的忍术，虽然大部分是搞怪和变出食物，但在关键时刻拥有惊人的逃生能力。", type: "exclusive"},
                    {name: "鸟神丸侦查", color: "B", cost: 700, desc: "你可以召唤空神丸进行侦查，虽然不能合体，但能提供宝贵的空中视野。", type: "exclusive"},
                    {name: "登龙剑", color: "A", cost: 1500, desc: "一把勇者之剑，虽然不是原版，但对邪恶生物有加成伤害，并且是驾驶龙神丸的关键钥匙。", type: "exclusive"},
                    {name: "魔神驾驶技术", color: "A", cost: 1800, desc: "你拥有驾驶魔神的天赋，无论是敌方的杂兵机还是正义的魔神，你上手就能操作。", type: "exclusive"},
                    {name: "必杀·登龙剑", color: "S", cost: 3500, desc: "龙神丸的招牌必杀技。高举长剑，汇聚雷电与光芒，将敌人一刀两断。对黑暗生物一击必杀。", type: "exclusive"},
                    {name: "变身·龙王丸", color: "S", cost: 5000, desc: "龙神丸与空神丸合体后的形态。拥有飞行能力和更强的凤龙剑，是攻守兼备的强力魔神。", type: "exclusive"},
                    {name: "邪虎丸契约", color: "S", cost: 4500, desc: "你获得了虎王的座驾邪虎丸。这台魔神拥有猛兽般的敏捷和变形能力，适合狂野的战斗风格。", type: "exclusive"},
                    {name: "超力变身", color: "SS", cost: 7500, desc: "随着你的勇气提升，你的魔神可以进化为狮子龙神丸、凤凰龙神丸等多种形态，适应各种战场。", type: "exclusive"},
                    {name: "暗黑龙复活", color: "SS", cost: 8000, desc: "你掌握了多恶达的黑暗秘术，可以复活并操控强大的暗黑龙，将创界山笼罩在永恒的黑夜中。", type: "exclusive"},
                    {name: "七色虹光", color: "SSS", cost: 13000, desc: "你体内汇聚了创界山七层彩虹的力量。你的存在本身就能净化邪恶，所有友方魔神全属性提升500%。", type: "exclusive"},
                    {name: "超魔神龙神丸", color: "SSS", cost: 16000, desc: "最终形态的龙神丸，拥有创界山守护神的全部力量。其剑气可以斩断时空，重塑世界的秩序。", type: "exclusive"}
                ]
            },
            {
                name: "175.爆旋陀螺",
                desc: "一个陀螺（Beyblade）决定一切的世界。陀螺不仅是玩具，更是蕴含着“圣兽”力量的武器。陀螺手们通过比赛争夺世界冠军，甚至解决国际争端。",
                boss: "伏尔泰, 拉斯普京, 黑色龙骑士",
                identities: [
                    { name: "社区公园的陀螺新手", items: "一个塑料制的量产陀螺, 一根磨损的拉条" },
                    { name: "陀螺专卖店的店员", items: "一件印着BBA标志的围裙, 一个陀螺维护工具箱" },
                    { name: "被淘汰的测试员", items: "一堆破碎的陀螺零件, 一份被辞退的通知书" },
                    { name: "街头混混陀螺手", items: "一个改装过带锯齿的违规陀螺, 一双露指手套" },
                    { name: "某深山道场的扫地僧", items: "一把竹扫帚, 一个木制的古老陀螺" }
                ],
                talents: [
                    {name: "手抖", color: "E", cost: 50, desc: "你在发射陀螺时总是手抖，导致发射失误（Miss Launch），陀螺根本转不起来，直接判负。", type: "exclusive"},
                    {name: "廉价零件", color: "D", cost: 100, desc: "你的陀螺由劣质塑料制成，稍微碰撞就会解体，根本无法承受高强度的战斗。", type: "exclusive"},
                    {name: "稳定发射", color: "C", cost: 200, desc: "你掌握了标准的发射姿势，能够保证陀螺平稳落地并保持不错的转速。", type: "exclusive"},
                    {name: "零件改装师", color: "C", cost: 300, desc: "你懂得如何搭配攻击环、重力轮和轴心，能组装出性能优于市面量产货的定制陀螺。", type: "exclusive"},
                    {name: "圣兽感知(微弱)", color: "B", cost: 600, desc: "你能隐约感觉到某些陀螺里寄宿着灵魂，这让你在选择原石陀螺时眼光独到。", type: "exclusive"},
                    {name: "跳跃攻击", color: "B", cost: 700, desc: "你练就了特殊的发射技巧，让陀螺能够跳跃躲避攻击或从上方打击对手的弱点。", type: "exclusive"},
                    {name: "青龙位", color: "A", cost: 1500, desc: "你的战斗风格偏向强攻，拥有寄宿青龙系圣兽的资质，擅长旋风攻击和高速移动。", type: "exclusive"},
                    {name: "玄武位", color: "A", cost: 1500, desc: "你的战斗风格偏向防御，拥有寄宿玄武系圣兽的资质，擅长利用水流和坚固的防御耗死对手。", type: "exclusive"},
                    {name: "人机合一", color: "S", cost: 3000, desc: "你与陀螺心意相通。在战斗中，你的精神会投射到陀螺上，像控制自己的手脚一样控制陀螺的轨迹。", type: "exclusive"},
                    {name: "圣兽实体化", color: "S", cost: 4500, desc: "你可以呼唤陀螺中的圣兽现身。巨大的幻影不仅能震慑对手，还能造成实质性的物理破坏（如掀翻竞技场）。", type: "exclusive"},
                    {name: "暗黑圣兽", color: "S", cost: 4000, desc: "你使用窃取或人造的暗黑圣兽。力量强大且狂暴，能吞噬对手圣兽的力量，但会逐渐侵蚀使用者的心智。", type: "exclusive"},
                    {name: "银河暴击", color: "SS", cost: 7000, desc: "传说中的必杀技。引发如同银河爆炸般的能量冲击，不仅能粉碎对手的陀螺，甚至能改变局部的天象。", type: "exclusive"},
                    {name: "次元穿梭", color: "SS", cost: 8000, desc: "你的圣兽拥有撕裂空间的能力，可以让陀螺在异次元中穿梭，进行无法防御的偷袭。", type: "exclusive"},
                    {name: "黄金龙骑士", color: "SSS", cost: 12000, desc: "拥有太古圣兽黄金龙的力量。其力量凌驾于四圣兽之上，能够统御所有的圣兽，是陀螺界的至高存在。", type: "exclusive"},
                    {name: "世界冠军的羁绊", color: "SSS", cost: 11000, desc: "你拥有主角光环般的羁绊力量。队友越多，你的陀螺转速越快，在绝境中必定爆发奇迹，无限旋转。", type: "exclusive"}
                ]
            },
            {
                name: "176.弹珠警察",
                desc: "一个由“弹珠人”构成的世界。这里没有人类，居民都是二头身的机器人。他们腹部装有弹珠发射器，既是生活工具也是战斗武器。正义的白宝与黑宝对抗着黑暗皇帝。",
                boss: "黑暗皇帝, 黑暗王子, 机械四天王",
                identities: [
                    { name: "弹珠市的普通市民", items: "一颗普通的玻璃弹珠, 一张市民身份证" },
                    { name: "采石场的苦力弹珠人", items: "一筐沉重的石料, 磨损严重的腹部发射口" },
                    { name: "黑暗军团的量产杂兵", items: "黑色的制式装甲, 只能连射两发的低级发射器" },
                    { name: "被废弃的旧型号弹珠人", items: "生锈的关节, 漏油的液压管" },
                    { name: "疯狂科学家的实验助手", items: "各种口径的实验弹珠, 一个爆炸过的护目镜" }
                ],
                talents: [
                    {name: "卡弹", color: "E", cost: 50, desc: "你的发射器结构有缺陷，每发射三发弹珠就会卡住一次，在激烈的枪战中这是致命的。", type: "exclusive"},
                    {name: "弹珠丢失", color: "D", cost: 80, desc: "你是个马大哈，经常在战斗关键时刻发现口袋里的弹珠漏光了，只能尴尬地看着敌人。", type: "exclusive"},
                    {name: "快速装填", color: "C", cost: 250, desc: "你练就了单手快速装填弹珠的技巧，能保持火力的持续性，比普通弹珠人射速快30%。", type: "exclusive"},
                    {name: "旋转球", color: "C", cost: 300, desc: "你懂得给弹珠施加旋转，射出的曲线球可以绕过掩体打击躲在后面的敌人。", type: "exclusive"},
                    {name: "双发连射", color: "B", cost: 600, desc: "你的发射器经过改造，可以一次装填两枚弹珠并连续射出，瞬间爆发力倍增。", type: "exclusive"},
                    {name: "重型装甲", color: "B", cost: 800, desc: "你装备了外挂式的重型装甲，虽然移动速度变慢，但能抵挡普通弹珠的攻击。", type: "exclusive"},
                    {name: "白宝的勇气", color: "A", cost: 1500, desc: "你拥有像白宝一样百折不挠的勇气。即使面对巨大的敌人，你的弹珠威力也会随着气势提升。", type: "exclusive"},
                    {name: "黑宝的冷静", color: "A", cost: 1500, desc: "你拥有像黑宝一样冷静的头脑，擅长狙击和战术分析，总能找到敌人的弱点一击必杀。", type: "exclusive"},
                    {name: "超级弹珠战机", color: "S", cost: 3500, desc: "你拥有一台可以驾驶的巨大化弹珠战机。火力、防御和机动性全面提升，是战场上的主宰。", type: "exclusive"},
                    {name: "聚能射击", color: "S", cost: 4000, desc: "你的战机可以进行聚能，发射出巨大的能量弹珠，威力足以摧毁一座小型要塞。", type: "exclusive"},
                    {name: "合体变形", color: "SS", cost: 7000, desc: "你的战机可以与队友的战机合体，变成巨大的战斗机器人，拥有毁天灭地的力量。", type: "exclusive"},
                    {name: "黑暗能源核心", color: "SS", cost: 6500, desc: "你植入了黑暗皇帝的能源核心，拥有无限的弹药和狂暴的攻击力，但会被黑暗意志控制。", type: "exclusive"},
                    {name: "神圣弹珠", color: "SSS", cost: 12000, desc: "传说中只有救世主才能使用的光之弹珠。发射时化作巨大的光龙，净化一切邪恶，重置世界的和平。", type: "exclusive"},
                    {name: "全弹发射·无限模式", color: "SSS", cost: 11000, desc: "解除所有限制器，在一瞬间发射出成千上万发弹珠，形成弹幕风暴，没有任何死角可以躲避。", type: "exclusive"},
                    {name: "弹珠生命赋予", color: "SSS", cost: 15000, desc: "你拥有创造者的能力，可以赋予普通的机械零件以生命，创造出属于你的弹珠人军团。", type: "exclusive"}
                ]
            },
            {
                name: "177.排球少年",
                desc: "一个虽然没有超能力，但每个人都为了“飞翔”而拼尽全力的热血排球世界。乌野高中的“怪人快攻”震惊全国。这里只有汗水、战术和不落的排球。",
                boss: "牛岛若利, 宫侑, 及川彻",
                identities: [
                    { name: "落魄排球社的捡球经理", items: "一个记分牌, 一筐磨损的排球" },
                    { name: "万年替补发球员", items: "一件干净得过分的队服, 一个护膝" },
                    { name: "只有身高的拦网初学者", items: "经常撞到门框的额头, 一双特大号球鞋" },
                    { name: "因伤退役的前王牌", items: "满是绷带的膝盖, 一张旧时的奖状" },
                    { name: "狂热的排球观众", items: "一个应援大喇叭, 满脸的油彩" }
                ],
                talents: [
                    {name: "玻璃膝盖", color: "E", cost: 50, desc: "你的膝盖有陈旧性损伤，剧烈跳跃后有极高概率复发，导致你需要长期休养。", type: "exclusive"},
                    {name: "发球失误", color: "D", cost: 100, desc: "你在发球时总是紧张，不是下网就是出界，是送分童子般的存在。", type: "exclusive"},
                    {name: "鱼跃救球", color: "C", cost: 250, desc: "你掌握了基本的救球动作，能够不顾形象地扑出去接起即将落地的球，虽然姿势不帅但很实用。", type: "exclusive"},
                    {name: "跳飘球", color: "C", cost: 350, desc: "你学会了山口忠的跳飘球，球路飘忽不定，容易让对方接球手判断失误。", type: "exclusive"},
                    {name: "自由人反应", color: "B", cost: 600, desc: "你拥有西谷夕般的反应速度，是球队的守护神，总能在千钧一发之际将球垫起。", type: "exclusive"},
                    {name: "二传手视野", color: "B", cost: 700, desc: "你拥有影山般的球场视野，能瞬间判断出对方拦网的漏洞，并传出最合适的球。", type: "exclusive"},
                    {name: "超高打点", color: "A", cost: 1200, desc: "你的弹跳力惊人，能在拦网手的手指上方扣球，看到“拦网之上的风景”。", type: "exclusive"},
                    {name: "重炮发球", color: "A", cost: 1500, desc: "你拥有及川彻或牛岛若利级别的大力跳发球，球速极快，威力如同加农炮，直接得分率极高。", type: "exclusive"},
                    {name: "怪人快攻", color: "S", cost: 3000, desc: "你与队友拥有绝对的默契（或你是双子），能打出违背物理常识的超速快攻，让拦网完全跟不上。", type: "exclusive"},
                    {name: "绝对王者", color: "S", cost: 4000, desc: "你拥有牛岛若利般的统治力。左撇子，力量碾压，无论面对几人拦网都能强行突破。", type: "exclusive"},
                    {name: "诱饵大师", color: "S", cost: 3500, desc: "你是日向翔阳般的“最强诱饵”。你的跑动能吸引全场的注意力，让队友面对空网得分。", type: "exclusive"},
                    {name: "球场上的国王", color: "SS", cost: 6000, desc: "你的二传技术达到神之领域。你能随心所欲地控制球的落点，甚至能强行激发扣球手的最大潜力。", type: "exclusive"},
                    {name: "小巨人的气魄", color: "SS", cost: 7000, desc: "虽然身材矮小，但你在空中的滞空能力和战术选择无人能敌。你是空中的霸主，绝不低头。", type: "exclusive"},
                    {name: "排球之神眷顾", color: "SSS", cost: 10000, desc: "你进入了“Zone”的状态。一切动作都完美无缺，球场上的一切都在你的预料之中，你是不可战胜的。", type: "exclusive"},
                    {name: "不屈的羁绊", color: "SSS", cost: 11000, desc: "只要球还没有落地，比赛就没有结束。你的队伍拥有无限的体力上限和士气，必定能把不可能的球救回来。", type: "exclusive"}
                ]
            },
            {
                name: "178.Keroro军曹",
                desc: "来自K隆星的青蛙外星人企图侵略蓝星（地球），却寄住在日向家做家务。充满了高达模型（Gunpla）、恶搞和无厘头黑科技的搞笑世界。",
                boss: "日向夏美, 毒蛇(Viper), K隆军总部",
                identities: [
                    { name: "日向家的不速之客", items: "一个被当作人质的吸尘器, 一张藏在天花板的床垫" },
                    { name: "K隆军的逃兵", items: "一把坏掉的Kero球, 一箱过期的宇宙口粮" },
                    { name: "西泽集团的黑衣保镖", items: "一副墨镜, 一个随时准备挡子弹的身体" },
                    { name: "宇宙侦探的助手", items: "一个放大镜, 一本记录着无聊案件的笔记" },
                    { name: "沉迷模型的死宅", items: "一堆未拼装的高达模型盒子, 一把神之手剪钳" }
                ],
                talents: [
                    {name: "湿气过敏", color: "E", cost: 50, desc: "虽然是青蛙外星人，但你对过高的湿度过敏，下雨天会让你变得虚弱无力，甚至长出奇怪的蘑菇。", type: "exclusive"},
                    {name: "家务奴隶", color: "D", cost: 100, desc: "你被植入了做家务的本能。看到脏乱的房间身体就会不受控制地开始打扫，无法进行战斗。", type: "exclusive"},
                    {name: "共鸣", color: "C", cost: 200, desc: "你可以与其他K隆星人进行共鸣（KeroKeroKero...），虽然除了吵闹外没什么实际攻击力，但能增加团队气氛。", type: "exclusive"},
                    {name: "模型制作(专业)", color: "C", cost: 300, desc: "你拥有专业的模型制作技术，拼装速度极快。这对修复某些塑料制的宇宙飞船意外地有用。", type: "exclusive"},
                    {name: "忍者体术", color: "B", cost: 600, desc: "你师从Dororo兵长，掌握了暗杀兵的忍术。可以隐身、飞檐走壁，存在感极低，容易被队友遗忘。", type: "exclusive"},
                    {name: "格斗家之魂", color: "B", cost: 700, desc: "你拥有Giroro伍长般的战斗直觉，精通各种枪械和陷阱布置，是战场上的硬汉。", type: "exclusive"},
                    {name: "双重人格", color: "A", cost: 1200, desc: "像Tamama一样，你平时可爱，但嫉妒时会爆发黑化人格，口吐激光，战斗力瞬间飙升。", type: "exclusive"},
                    {name: "电波系发明", color: "A", cost: 1500, desc: "像Kururu曹长一样，你是个阴险的发明天才。能制造出把人变成动物、交换身体等各种不讲理的黑科技道具。", type: "exclusive"},
                    {name: "蓝星人最强战力", color: "S", cost: 3500, desc: "你拥有日向夏美般的战斗力。只要是为了守护家（或者赶走外星人），你能徒手接导弹，完虐K隆军。", type: "exclusive"},
                    {name: "西泽集团财力", color: "S", cost: 4000, desc: "你拥有西泽桃华般的财力。遇到解决不了的问题？那就买下整个国家，或者雇佣私设军队平推过去。", type: "exclusive"},
                    {name: "安哥尔族审判", color: "SS", cost: 7000, desc: "你是恐怖大王的后裔，拥有“路西法之枪”，可以随意使出1/100威力的默示录击，足以毁灭一颗行星。", type: "exclusive"},
                    {name: "K隆星最强战士", color: "SS", cost: 8000, desc: "你恢复了Keroro军曹巅峰时期的实力。战术指挥、单兵作战能力皆为顶级，不搞怪的时候你就是战神。", type: "exclusive"},
                    {name: "因果律兵器·香蕉皮", color: "SSS", cost: 12000, desc: "搞笑漫画的终极武器。无论多强的敌人踩到你扔的香蕉皮，必定会滑倒并摔个狗吃屎，强制打断一切技能。", type: "exclusive"},
                    {name: "第四面墙突破", color: "SSS", cost: 15000, desc: "你意识到这是一部动画/游戏。你可以直接和旁白对话，甚至修改下一集的剧本预告，从根本上改变剧情走向。", type: "exclusive"},
                    {name: "K隆星侵略完成", color: "SSS", cost: 20000, desc: "你达成了不可能的成就：真正征服了蓝星。所有蓝星人都变成了爆炸头，世界充满了爱与和平（和刚普拉）。", type: "exclusive"}
                ]
            },
            {
                name: "179.乌龙派出所",
                desc: "东京葛饰区龟有公园前派出所。这里有全日本最离谱的巡查长两津勘吉。这不仅是警匪故事，更是关于赚钱、黑科技、怀旧和无尽麻烦的日常。",
                boss: "大原大次郎(所长), 拟宝珠夏春都, 爆龙上校",
                identities: [
                    { name: "葛饰区的倒霉路人", items: "一个刚买就被撞坏的便当, 一辆被征用的自行车" },
                    { name: "派出所的新人女警", items: "一身笔挺的迷你裙警服, 一本交通违章罚单本" },
                    { name: "中川集团的底层员工", items: "一件名牌西装(分期付款), 一辆法拉利(模型的)" },
                    { name: "两津勘吉的债主", items: "一叠厚厚的欠条, 一瓶速效救心丸" },
                    { name: "附近寿司店的学徒", items: "一把磨得发亮的菜刀, 一条沾满鱼腥味的头巾" }
                ],
                talents: [
                    {name: "月光族", color: "E", cost: 50, desc: "你完全存不住钱。只要手里有钱，就会因为各种意外（赌马、被骗、请客）在发薪日当天全部花光。", type: "exclusive"},
                    {name: "所长的怒吼", color: "D", cost: 100, desc: "你天生招黑，总是成为大原所长怒火的发泄对象。听到“两津——！！”的怒吼时，你会陷入短暂的瘫痪。", type: "exclusive"},
                    {name: "自行车特技", color: "C", cost: 200, desc: "你拥有两津般的骑车技术，能骑着破旧的自行车追上跑车，甚至在屋顶上飞驰。", type: "exclusive"},
                    {name: "模型鉴定", color: "C", cost: 300, desc: "你对古董玩具、模型、军品有极高的鉴赏力，能在垃圾堆里发现价值连城的宝贝。", type: "exclusive"},
                    {name: "蟑螂般的生命力", color: "B", cost: 800, desc: "你拥有两津勘吉同款体质。无论是被坦克碾过、从万米高空坠落还是被炸飞，睡一觉就能痊愈。", type: "exclusive"},
                    {name: "野性的直觉", color: "B", cost: 700, desc: "在赚钱机会出现时，你的鼻子会像猎犬一样灵敏。但往往伴随着巨大的风险。", type: "exclusive"},
                    {name: "中川的财力", color: "A", cost: 1800, desc: "你是中川集团的继承人。你的手枪是纯金的，警车是兰博基尼，上班只是为了体验平民生活。", type: "exclusive"},
                    {name: "丽子的美貌", color: "A", cost: 1600, desc: "你拥有秋本丽子般的身材和美貌。不仅能魅惑罪犯，还能让半个警视厅的人为你争风吃醋。", type: "exclusive"},
                    {name: "本田的暴走", color: "S", cost: 3000, desc: "平时唯唯诺诺，一旦骑上摩托车就会性格大变，成为疯狂的暴走族，驾驶技术无人能敌。", type: "exclusive"},
                    {name: "特殊刑事课", color: "S", cost: 3500, desc: "你加入了特殊刑事课。可能是月光刑警、海豚刑警或热裤刑警。拥有极其变态但强力的专属装备。", type: "exclusive"},
                    {name: "拟宝珠缠的武力", color: "S", cost: 4000, desc: "你是拟宝珠家的长女，精通超神田寿司的经营和薙刀术，武力值足以压制暴走的两津。", type: "exclusive"},
                    {name: "商界鬼才", color: "SS", cost: 6000, desc: "你拥有两津的经商头脑（但不包括结局）。任何生意你都能在短时间内做大做强，赚取暴利。", type: "exclusive"},
                    {name: "奥林匹克男", color: "SS", cost: 7000, desc: "你是日暮熟睡男。每四年醒来一次，拥有预知未来的超能力，醒着的时候能解决一切悬案。", type: "exclusive"},
                    {name: "龟有破坏神", color: "SSS", cost: 12000, desc: "你走到哪里，哪里就会毁灭。这种破坏力是概念级的，无论是哥斯拉还是外星舰队，都会被你的霉运克死。", type: "exclusive"},
                    {name: "作者的亲儿子", color: "SSS", cost: 15000, desc: "作为连载40年的主角，你拥有绝对的不死身和重置能力。无论这一集结局多惨，下一集都会像没事人一样重新开始。", type: "exclusive"}
                ]
            },
            {
                name: "180.只有我不在的街道",
                desc: "一个充满悬疑与遗憾的世界。不畅销的漫画家藤沼悟拥有“再上映”的能力，被卷入18年前的连环诱拐杀人案。为了拯救同学和母亲，必须改写过去。",
                boss: "八代学, 诱拐犯, 命运的死循环",
                identities: [
                    { name: "石狩小学的五年级生", items: "一个红色的书包, 一本写着秘密的作文集" },
                    { name: "披萨店的打工仔", items: "一辆送外卖的摩托车, 一张还没画完的漫画原稿" },
                    { name: "被误抓的嫌疑人", items: "一副冰冷的手铐, 一件沾有血迹的外套" },
                    { name: "八代学的学生", items: "一颗糖果, 一辆藏在车库里的汽车" },
                    { name: "想要独自一人的少女", items: "一双破旧的手套, 总是看着公园的圣诞树" }
                ],
                talents: [
                    {name: "口是心非", color: "E", cost: 50, desc: "你经常不小心把心里的吐槽大声说出来，这在需要隐藏身份或意图的悬疑剧中非常尴尬。", type: "exclusive"},
                    {name: "被虐待的阴影", color: "D", cost: 150, desc: "你像雏月加代一样有家庭创伤，性格孤僻，难以信任他人，身上常有淤青。", type: "exclusive"},
                    {name: "敏锐观察力", color: "C", cost: 250, desc: "你能注意到别人忽视的细节，比如违和的眼神、不自然的时间差，这是侦探的基本素养。", type: "exclusive"},
                    {name: "演技派小孩", color: "C", cost: 300, desc: "虽然外表是小学生，但你的内心是成年人。你擅长扮演天真的孩子来套取大人的情报。", type: "exclusive"},
                    {name: "勇气", color: "B", cost: 600, desc: "你拥有直面恐惧的勇气。即使面对连环杀手，你也能为了保护朋友而挺身而出。", type: "exclusive"},
                    {name: "母亲的直觉", color: "B", cost: 800, desc: "像佐知子一样，你拥有“魔女”般的直觉，能一眼看穿谎言和危险，是主角最坚强的后盾。", type: "exclusive"},
                    {name: "再上映(Revival)·被动", color: "A", cost: 1800, desc: "当周围发生致命事故时，你会强制时光倒流1-5分钟。虽然无法控制，但这是改变悲剧的唯一机会。", type: "exclusive"},
                    {name: "法律知识", color: "A", cost: 1200, desc: "你精通法律和刑侦程序，能够利用规则保护自己，或者搜集足以给犯人定罪的铁证。", type: "exclusive"},
                    {name: "蜘蛛丝", color: "S", cost: 3000, desc: "你能看到杀人犯头顶的“蜘蛛丝”。那是他们杀意和破绽的具象化，切断它就能阻止犯罪。", type: "exclusive"},
                    {name: "完美犯罪者", color: "S", cost: 4500, desc: "你拥有八代学般的智商和策划能力。善于利用替罪羊和不在场证明，让自己的双手永远干净。", type: "exclusive"},
                    {name: "再上映·控制", color: "SS", cost: 7000, desc: "你可以主动触发时光倒流，甚至能跨越数年的时间线回到过去（如回到小学时代），彻底改写命运。", type: "exclusive"},
                    {name: "记忆宫殿", color: "SS", cost: 6000, desc: "你拥有过目不忘的记忆力。能够完美复盘18年前的每一个细节，找出当时被忽略的真凶线索。", type: "exclusive"},
                    {name: "英雄的代偿", color: "SSS", cost: 10000, desc: "为了拯救他人，你愿意献祭自己的一切（包括生命或沉睡15年）。这种牺牲精神能引发奇迹，让必死的结局发生逆转。", type: "exclusive"},
                    {name: "只有我不存在的城市", color: "SSS", cost: 12000, desc: "你成为了时间线之外的观测者。你可以任意穿梭于无数个平行世界，寻找那个所有人都能幸福的完美结局。", type: "exclusive"},
                    {name: "未来的漫画家", color: "SSS", cost: 11000, desc: "你的画笔拥有现实扭曲力。你画出的故事会逐渐在现实中应验，你是书写这个世界剧本的神。", type: "exclusive"}
                ]
            },
                      {
                name: "181.尸鬼",
                desc: "外场村，一个被森林包围的封闭村落。酷暑中，村民接连离奇死亡。古老的土葬习俗下，名为‘尸鬼’的复活者正在悄然取代活人。这是一场生存与人性的博弈。",
                boss: "桐敷沙子, 辰巳, 桐敷正志郎",
                identities: [
                    { name: "外场村的一般村民", items: "一把干农活的锄头, 一张写着邻居名字的讣告" },
                    { name: "尾崎医院的护士", items: "一盒不管用的感冒药, 沾着血迹的输液架" },
                    { name: "寺庙的和尚学徒", items: "一本没念完的佛经, 一把用来防身的铁锹" },
                    { name: "刚刚搬来的城市人", items: "搬家留下的纸箱, 对乡村生活不切实际的幻想" },
                    { name: "被尸鬼盯上的猎物", items: "一扇锁不紧的窗户, 脖子上莫名的两个红点" }
                ],
                talents: [
                    {name: "尸鬼体质", color: "S", cost: 1800, desc: "死后复活为尸鬼。畏惧阳光和圣物，必须吸食人血为生，但获得了漫长的寿命和超越常人的怪力。", type: "exclusive"},
                    {name: "人狼血统", color: "SS", cost: 6000, desc: "尸鬼中的变异体。完全保留人类的感官和生理机能（不怕阳光，能吃常人食物），同时拥有尸鬼的超强体能和恢复力。", type: "exclusive"},
                    {name: "狩猎者的直觉", color: "B", cost: 400, desc: "作为一个普通人，你对‘非人’的气息异常敏感，能察觉到混在人群中的尸鬼。", type: "exclusive"},
                    {name: "医生", color: "C", cost: 180, desc: "掌握基础医疗知识，但在面对超自然瘟疫时，你手中的手术刀或许更适合用来攻击。", type: "exclusive"},
                    {name: "土葬传统", color: "D", cost: 50, desc: "你坚信土葬是正途。这让你死后有概率变成尸鬼，但也更容易被从坟里挖出来。", type: "exclusive"},
                    {name: "拖拉机驾驶", color: "C", cost: 120, desc: "在这个交通不便的村子里，会开拖拉机也是一种重要的逃生（或碾压）技能。", type: "exclusive"},
                    {name: "狂信徒", color: "D", cost: 80, desc: "你容易被洗脑。无论是信奉神明还是信奉尸鬼，你都会成为最忠诚的炮灰。", type: "exclusive"},
                    {name: "木桩制作", color: "C", cost: 150, desc: "你擅长削制尖锐的木桩，这是对付吸血生物最原始也最有效的武器。", type: "exclusive"},
                    {name: "夜视能力", color: "B", cost: 300, desc: "你的眼睛适应了黑暗，能在深夜的山林中看清移动的黑影。", type: "exclusive"},
                    {name: "绝望的呐喊", color: "C", cost: 160, desc: "面临死亡时发出的尖叫极其刺耳，有概率引来其他人的注意（或者是更多的怪物）。", type: "exclusive"},
                    {name: "被诅咒的血型", color: "A", cost: 700, desc: "你的血液对尸鬼来说极其美味，容易吸引仇恨；但若你反杀对方，你的血也是最猛烈的毒药。", type: "exclusive"},
                    {name: "寺庙结界(残)", color: "A", cost: 850, desc: "你懂得布置简单的驱魔结界，虽然挡不住强大的辰巳，但能让普通尸鬼无法进门。", type: "exclusive"},
                    {name: "领袖魅力", color: "B", cost: 500, desc: "在这恐慌蔓延的时刻，你的话语能安抚人心，组织起有效的防御或暴动。", type: "exclusive"},
                    {name: "复仇之火", color: "S", cost: 1500, desc: "当亲人被杀害后，你的精神力突破极限，对尸鬼造成的伤害提升100%，且免疫精神控制。", type: "exclusive"},
                    {name: "尸鬼之王(伪)", color: "SS", cost: 5500, desc: "你拥有统御低级尸鬼的能力，能让它们在一定程度上服从你的命令，构建属于你的地下王国。", type: "exclusive"}
                ]
            },
            {
                name: "182.寄生兽",
                desc: "某天夜里，无数孢子降临地球。它们钻入人类大脑，吞噬并取代头部，变成能任意变形的食人怪物。在这个不仅要提防怪物，还要提防‘人类’的世界，什么是真正的‘活着’？",
                boss: "后藤, 田村玲子, 广川刚志",
                identities: [
                    { name: "普通的高中生", items: "沉重的书包, 一副度数很高的眼镜" },
                    { name: "被寄生失败的倒霉蛋", items: "缠着绷带的右手, 经常自言自语的坏习惯" },
                    { name: "专门调查离奇杀人案的刑警", items: "写满线索的记事本, 一把老式左轮手枪" },
                    { name: "黑道组织的底层成员", items: "藏在怀里的弹簧刀, 一身廉价的西装" },
                    { name: "刚发现真相的生物老师", items: "显微镜, 几张令人作呕的细胞切片照片" }
                ],
                talents: [
                    {name: "右获(Migi)", color: "SS", cost: 8000, desc: "寄生在你右手的寄生兽。虽然夺取大脑失败，但它拥有极高的智商和战斗力，是你最可靠的战友。", type: "exclusive"},
                    {name: "头部寄生", color: "S", cost: 2500, desc: "你被寄生兽完全夺取了头部。你不再是人类，必须以人类为食，头部可以变成锋利的刀刃攻击。", type: "exclusive"},
                    {name: "感应波", color: "B", cost: 450, desc: "你能接收到300米内其他寄生兽发出的脑波信号，不仅能索敌，也能以此判断同类。", type: "exclusive"},
                    {name: "超强体质(寄生)", color: "A", cost: 900, desc: "由于体内有寄生细胞混杂，你的心脏更强力，奔跑速度堪比奥运冠军，跳跃力惊人。", type: "exclusive"},
                    {name: "多重寄生(后藤)", color: "SSS", cost: 18000, desc: "你的身体由五只寄生兽统合而成，全身几乎无死角，力量、速度、防御皆为顶尖，是完美的杀戮机器。", type: "exclusive"},
                    {name: "化学投毒", color: "C", cost: 180, desc: "你擅长利用周围的化学试剂。虽然卑鄙，但对付那些怕火、怕酸的生物很有效。", type: "exclusive"},
                    {name: "冷静思考", color: "C", cost: 150, desc: "越是危机时刻越冷静。在面对怪物张开血盆大口时，你能瞬间计算出最佳逃跑路线。", type: "exclusive"},
                    {name: "母性觉醒", color: "A", cost: 1200, desc: "作为寄生兽却理解了‘爱’。为了保护特定目标，你的战斗意志和防御力大幅提升。", type: "exclusive"},
                    {name: "下巴寄生(乔)", color: "S", cost: 2200, desc: "寄生兽夺取了你的下巴和嘴部。虽然不能变成大刀，但咬合力惊人，且保留了人类大脑。", type: "exclusive"},
                    {name: "硬质化防御", color: "A", cost: 800, desc: "能够瞬间硬化身体的一部分抵挡子弹，但面对反坦克武器依然脆弱。", type: "exclusive"},
                    {name: "触手操控", color: "A", cost: 850, desc: "身体可以分裂出多条触手进行中距离攻击，令人防不胜防。", type: "exclusive"},
                    {name: "政治家", color: "B", cost: 500, desc: "你擅长煽动群众和利用规则。哪怕是怪物，只要能为你所用，你也会毫不犹豫地合作。", type: "exclusive"},
                    {name: "含毒铁锈", color: "B", cost: 300, desc: "你知道生锈的铁器对寄生兽是致命的。你的攻击附带‘破伤风’效果，对寄生兽特攻。", type: "exclusive"},
                    {name: "人类的赞歌", color: "SS", cost: 4500, desc: "作为纯粹的人类，你的勇气和智慧让你能做出超越物种极限的反击。全属性在绝境下翻倍。", type: "exclusive"},
                    {name: "环境适应者", color: "C", cost: 140, desc: "无论是下水道还是垃圾场，你都能找到生存之道，并不介意食用过期的食物。", type: "exclusive"}
                ]
            },
            {
                name: "183.亚人",
                desc: "在这个世界，有一种不会死的新人类——‘亚人’。他们外表与常人无异，只有死亡后才会复活。为了巨额赏金，全人类都在猎杀亚人进行非人道的实验。",
                boss: "佐藤, 永井圭(黑化), 美国国防部",
                identities: [
                    { name: "准备高考的高中生", items: "英语单词本, 一部存着妹妹照片的手机" },
                    { name: "厚生劳动省的底层职员", items: "一份亚人捕获指南, 总是打不着的打火机" },
                    { name: "一直在逃亡的流浪汉", items: "捡来的大衣, 半个发霉的面包" },
                    { name: "反亚人特种部队新兵", items: "麻醉枪, 战术背心" },
                    { name: "被关押的实验体", items: "拘束衣, 编号牌" }
                ],
                talents: [
                    {name: "亚人体质(复活)", color: "SS", cost: 9000, desc: "你是不死的。无论受到何种伤害，死亡后都会立即重置身体状态并复活。最大的弱点是麻醉枪。", type: "exclusive"},
                    {name: "黑色幽灵(IBM)", color: "S", cost: 3500, desc: "你能召唤常人看不见的黑色物质人形战斗。它力大无穷，但只能持续几分钟，且不一定听话。", type: "exclusive"},
                    {name: "IBM粒子浓度(高)", color: "A", cost: 1500, desc: "你体内的IBM粒子浓度极高，能更频繁地召唤幽灵，甚至能连续召唤多体。", type: "exclusive"},
                    {name: "尖叫(定身)", color: "A", cost: 1200, desc: "发出特殊的尖叫声，能让听到的人类暂时瘫痪。对耳塞佩戴者无效。", type: "exclusive"},
                    {name: "断肢传送", color: "S", cost: 2800, desc: "利用亚人复活机制，砍下自己的手扔进无法进入的区域，然后自杀，从手的位置复活。神技。", type: "exclusive"},
                    {name: "特种作战精通", color: "B", cost: 600, desc: "精通各种枪械和CQB战术。在与不死怪物的战斗中，精准的枪法是基础。", type: "exclusive"},
                    {name: "冷血理性", color: "B", cost: 550, desc: "为了生存可以抛弃一切人性。这种极度的理性让你在制定战术时没有任何心理负担。", type: "exclusive"},
                    {name: "黑客技术", color: "B", cost: 400, desc: "能入侵政府网络修改户籍信息或查看监控，这对逃亡者来说至关重要。", type: "exclusive"},
                    {name: "麻醉抗性(微)", color: "C", cost: 200, desc: "你的代谢速度很快，麻醉药对你的效果持续时间减半。", type: "exclusive"},
                    {name: "自杀熟练工", color: "D", cost: 100, desc: "你克服了对死亡的恐惧。为了重置状态，你可以毫不犹豫地给自己脑袋来一枪。", type: "exclusive"},
                    {name: "飞行IBM", color: "SS", cost: 6500, desc: "变异的黑色幽灵，长有翅膀，可以带你进行空中机动。极其稀有。", type: "exclusive"},
                    {name: "无限洪流(Flood)", color: "SSS", cost: 25000, desc: "在极度情绪波动下产生的‘洪流’现象。无数黑色幽灵如海啸般涌出，无差别吞噬眼前的一切。", type: "exclusive"},
                    {name: "战术指挥(佐藤流)", color: "S", cost: 3000, desc: "游戏玩家般的战斗思维。利用断臂、飞机撞大楼等疯狂手段达成战术目标。", type: "exclusive"},
                    {name: "痛觉屏蔽", color: "C", cost: 250, desc: "既然死都不怕，痛又算什么？战斗中无视疼痛影响。", type: "exclusive"},
                    {name: "器官贩卖渠道", color: "D", cost: 150, desc: "你知道哪里能把多余的器官换成钱。对于亚人来说，这简直是无本万利。", type: "exclusive"}
                ]
            },
            {
                name: "184.杀戮都市",
                desc: "本来应该死掉的人，被召集到一个房间，面对一个黑球‘GANTZ’。穿上紧身衣，拿起科幻武器，去猎杀外星人吧。攒够100分，你就能获得自由……或者更强的力量。",
                boss: "滑瓢, 军神, 吸血鬼(冰川)",
