                ],
                talents: [
                    {name: "GANTZ强化服", color: "S", cost: 3200, desc: "黑球提供的紧身衣。能赋予常人数十倍的力量和跳跃力，能抵挡重击。缺点是耐久度耗尽后会流出液体失效。", type: "exclusive"},
                    {name: "X-Gun", color: "A", cost: 1200, desc: "基础手枪。有延迟爆炸的特性，可以透视锁定目标。威力足以炸碎小型外星人。", type: "exclusive"},
                    {name: "Y-Gun", color: "A", cost: 1200, desc: "捕捉枪。发射三个能量球捆住目标并传送到未知空间。对付不死之身的敌人很有效。", type: "exclusive"},
                    {name: "GANTZ战刀", color: "A", cost: 1500, desc: "可以伸长的黑色战刀，锋利度极高，能切开大部分外星人的甲壳。", type: "exclusive"},
                    {name: "重力枪(H-Gun)", color: "S", cost: 4000, desc: "从上方施加极大的重力压杀敌人。范围攻击，能瞬间将敌人压成肉饼。", type: "exclusive"},
                    {name: "硬汉体质(冈八郎)", color: "A", cost: 1800, desc: "经过极限锻炼的肉体。即使没有强化服，也能与低级外星人肉搏。", type: "exclusive"},
                    {name: "超能力(念力)", color: "SS", cost: 7500, desc: "极少数人拥有的天赋。能用念力撕碎人体，挡下子弹。使用过度会流鼻血。", type: "exclusive"},
                    {name: "吸血鬼体质", color: "S", cost: 3500, desc: "纳米机械改造人。拥有极高的速度和力量，能从背部长出骨翼刀刃，弱点是强光。", type: "exclusive"},
                    {name: "100分菜单:强力武器", color: "SS", cost: 9000, desc: "解锁更高级的装备，如巨型机甲（Gantz Robot）或飞行摩托，战力质的飞跃。", type: "exclusive"},
                    {name: "100分菜单:复活", color: "S", cost: 5000, desc: "拥有复活记忆库中死者的权限。这是团队维系的关键。", type: "exclusive"},
                    {name: "多面手", color: "B", cost: 600, desc: "能熟练使用各种GANTZ武器，切换自如，不会出现不知如何开枪的尴尬。", type: "exclusive"},
                    {name: "生存本能", color: "B", cost: 500, desc: "在被外星人围攻时，总能找到唯一的生路。运气也是实力的一部分。", type: "exclusive"},
                    {name: "二刀流", color: "B", cost: 450, desc: "擅长使用双刀流战斗，配合强化服的速度，能像切菜一样处理杂兵。", type: "exclusive"},
                    {name: "真理之钥", color: "SSS", cost: 30000, desc: "接触到了黑球背后的‘真理’。你理解了灵魂、复制与维度的奥秘，能一定程度上干涉传送机制。", type: "exclusive"},
                    {name: "好色之心", color: "D", cost: 50, desc: "为了在妹子面前耍帅，你的战斗力会莫名提升，但也会因此陷入险境。", type: "exclusive"}
                ]
