                    {name: "大剑(Claymore)", color: "B", cost: 600, desc: "组织特制的巨剑，刻有你的印记。极重，削铁如泥，是你唯一的依靠。", type: "exclusive"},
                    {name: "妖力解放(10%)", color: "B", cost: 500, desc: "瞳孔变色，力量速度提升。这是安全的界限。", type: "exclusive"},
                    {name: "妖力解放(50%)", color: "A", cost: 1200, desc: "身体部分变异，战力暴涨。在这个状态下战斗太久会无法变回人类。", type: "exclusive"},
                    {name: "觉醒者", color: "SS", cost: 8000, desc: "彻底释放妖力，变成了食人的怪物。拥有巨大的身躯和恐怖的力量，但失去了人类之心。", type: "exclusive"},
                    {name: "深渊者", color: "SSS", cost: 25000, desc: "觉醒者中的顶点，拥有统治一片大陆的力量。你的存在本身就是天灾。", type: "exclusive"},
                    {name: "高速剑", color: "S", cost: 3000, desc: "通过控制妖力让手臂超高速挥动，瞬间斩出数百剑，肉眼无法捕捉。", type: "exclusive"},
                    {name: "风斩", color: "A", cost: 1800, desc: "极快的一剑，甚至不需要接触敌人，仅凭剑压就能切裂目标。", type: "exclusive"},
                    {name: "妖气同调", color: "S", cost: 2500, desc: "能控制自己的妖气与对手同步，从而预判对手的动作，甚至通过接触干扰对手妖力。", type: "exclusive"},
                    {name: "再生能力", color: "A", cost: 2000, desc: "只要不是脑袋被砍掉，断手断脚都能消耗妖力再生。攻击型战士通常不具备此能力。", type: "exclusive"},
                    {name: "妖气感知(广域)", color: "B", cost: 800, desc: "能感知数公里外的妖气流动，精准定位每一只妖魔的位置。", type: "exclusive"},
                    {name: "双子实验体", color: "SS", cost: 7000, desc: "通过精神同调，你可以将觉醒的冲动转移给双胞胎姐妹，从而在保持人形的情况下使用觉醒者的力量。", type: "exclusive"},
                    {name: "食尘者", color: "B", cost: 400, desc: "通过极低限度地使用妖力并吃土一般的假死状态，来躲避强敌的侦查。", type: "exclusive"},
                    {name: "幻影(米里雅)", color: "S", cost: 2800, desc: "瞬间爆发极高速度留下的残影，让敌人分不清虚实。", type: "exclusive"},
                    {name: "斩风剑(花剑)", color: "A", cost: 1600, desc: "拥有极高柔韧性的剑术，能绕过敌人的防御进行攻击。", type: "exclusive"}
                ]
