                    {name: "谈判专家(洛克)", color: "A", cost: 1500, desc: "在这个暴力都市，你的舌头比枪更好用。能在几大势力间周旋，把死局说活。", type: "exclusive"},
                    {name: "重武器精通", color: "A", cost: 1600, desc: "巴雷特反器材狙击枪、M60机枪、RPG……只要是重家伙，你都能玩得转。", type: "exclusive"},
                    {name: "电锯狂人", color: "B", cost: 800, desc: "你喜欢用电锯解决问题。虽然声音大，但威慑力十足，且难以格挡。", type: "exclusive"},
                    {name: "伪钞鉴别", color: "C", cost: 200, desc: "在罗阿那普拉，认不出假钱是会饿死的。你一眼就能看出美金的真伪。", type: "exclusive"},
                    {name: "杀手双子", color: "S", cost: 3000, desc: "你和你的搭档配合默契，利用孩童的外表降低敌人警惕，然后用斧头和重机枪进行屠杀。", type: "exclusive"},
                    {name: "日本刀术(银次)", color: "A", cost: 1800, desc: "连子弹都能切开的居合斩。在狭窄空间内，你是无敌的。", type: "exclusive"},
                    {name: "CIA情报网", color: "B", cost: 1000, desc: "你能调动CIA的情报资源，获取目标的动向和弱点。", type: "exclusive"},
                    {name: "朗姆酒抗性", color: "C", cost: 100, desc: "千杯不醉。在黄旗酒吧，这是获取情报和结交朋友的基础能力。", type: "exclusive"},
                    {name: "法外狂徒", color: "D", cost: 50, desc: "你在任何国家的通缉名单上。这让你在文明社会寸步难行，但在罗阿那普拉如鱼得水。", type: "exclusive"},
                    {name: "黄金左轮", color: "A", cost: 1300, desc: "虽然浮夸，但这把枪的威力不容小觑。更重要的是，它代表了某种身份。", type: "exclusive"}
                ]
            },
            {
                name: "189.军火女王",
                desc: "蔻蔻·海克梅迪亚，一位年轻的军火商人，带着她的私人部队周游世界。她的目标是‘世界和平’，而手段是贩卖武器。这是一个关于战争、生意和宏大计划的故事。",
                boss: "蔻蔻, 乔治·布莱克(CIA), 陈国明",
                identities: [
                    { name: "HCLI公司的私兵", items: "SIG突击步枪, 无线电耳麦" },
                    { name: "深山里的少年兵", items: "AK-47, 仇恨的眼神" },
                    { name: "CIA外勤特工", items: "格洛克手枪, 窃听器" },
                    { name: "被卷入战乱的难民", items: "一双破鞋, 家人的照片" },
                    { name: "军火设计师", items: "图纸, 笔记本电脑" }
                ],
                talents: [
                    {name: "世界蛇(Jormungand)", color: "SSS", cost: 45000, desc: "一个疯狂的计划：利用量子计算机控制全球的天空和物流，强制实现世界和平。掌握它，你就掌握了世界的命脉。", type: "exclusive"},
                    {name: "少年兵(约拿)", color: "S", cost: 3200, desc: "自幼在战场长大的孩子。对危险有野兽般的直觉，身形矮小灵活，是天生的战士。", type: "exclusive"},
                    {name: "军火商人", color: "A", cost: 2000, desc: "你拥有庞大的军火销售网络。只要有钱，核弹头以外的东西你都能搞到。", type: "exclusive"},
                    {name: "海豹突击队(雷姆)", color: "A", cost: 1800, desc: "顶尖特种兵的战斗素养。无论是潜入、爆破还是狙击，你都是专家级。", type: "exclusive"},
                    {name: "狙击女王(鲁兹)", color: "A", cost: 1600, desc: "你的狙击枪法精准无比，特别擅长打屁股（非致命部位），或者一枪爆头。", type: "exclusive"},
                    {name: "近身格斗(法尔梅)", color: "S", cost: 2500, desc: "独眼女战士的刀法。近身战中，你能用军刀轻易压制持枪的敌人。", type: "exclusive"},
                    {name: "量子计算天才", color: "SS", cost: 8000, desc: "你拥有编写‘世界蛇’级别代码的能力。在这个信息化战争时代，你比一支军队更可怕。", type: "exclusive"},
                    {name: "炸弹魔", color: "B", cost: 700, desc: "你精通各种爆炸物的制作和拆除。艺术就是爆炸！", type: "exclusive"},
                    {name: "驾驶精通", color: "B", cost: 500, desc: "从跑车到运输机，没有你开不动的交通工具。逃跑必备。", type: "exclusive"},
                    {name: "多语言精通", color: "C", cost: 150, desc: "精通八国语言。对于满世界跑的军火商来说，这是基本功。", type: "exclusive"},
                    {name: "无表情面具", color: "C", cost: 120, desc: "无论内心如何波动，脸上永远挂着营业式的微笑。让人猜不透你的想法。", type: "exclusive"},
                    {name: "炮兵指挥", color: "B", cost: 600, desc: "擅长指挥迫击炮或火炮进行火力覆盖。", type: "exclusive"},
                    {name: "情报分析(稻草人)", color: "A", cost: 1400, desc: "作为CIA的情报官，你能从细枝末节中分析出敌人的战略意图。", type: "exclusive"},
                    {name: "绝对忠诚", color: "B", cost: 400, desc: "对蔻蔻的绝对忠诚让你免疫大部分精神诱惑和离间计。", type: "exclusive"},
                    {name: "山地战专家", color: "B", cost: 550, desc: "在复杂地形中作战有额外加成，擅长利用地形伏击。", type: "exclusive"}
                ]
            },
            {
                name: "190.全金属狂潮",
                desc: "这是一个黑科技泛滥的平行世界。巨型人型兵器‘AS’主宰战场。神秘组织‘汞合金’在暗中操纵世界，而佣兵组织‘秘银’则是对抗他们的利刃。",
                boss: "雷纳德, 九龙, 贝利亚",
                identities: [
                    { name: "阵代高中的转学生", items: "学生证, 藏在鞋底的手枪" },
                    { name: "秘银的AS驾驶员", items: "驾驶服, 强袭机兵操作手册" },
                    { name: "汞合金的研究员", items: "白大褂, 存有黑科技数据的U盘" },
                    { name: "深海潜艇的声呐员", items: "耳机, 咖啡" },
                    { name: "被卷入的普通女高中生", items: "纸扇, 惊人的吐槽能力" }
                ],
                talents: [
                    {name: "耳语者(Whispered)", color: "SS", cost: 9500, desc: "你的脑海中藏着超越时代的黑科技知识（黑技术）。你能理解并制造Lambda Driver等超常规武器，但精神负荷极大。", type: "exclusive"},
                    {name: "Lambda Driver(羊肉系统)", color: "SSS", cost: 30000, desc: "将驾驶员的意念转化为物理力量的系统。能产生无形的力场挡下炮弹，或发出冲击波粉碎一切。相信即是力量。", type: "exclusive"},
                    {name: "AS驾驶专精", color: "A", cost: 1200, desc: "你能熟练驾驶第三代AS（如M9）。操作行云流水，能做出人类般的战术动作。", type: "exclusive"},
                    {name: "战争狂人(相良宗介)", color: "A", cost: 1500, desc: "专业的佣兵素养。精通爆破、陷阱、枪械。但在和平社会中是个彻底的常识白痴。", type: "exclusive"},
                    {name: "ECS隐形系统", color: "S", cost: 2800, desc: "电磁迷彩系统。开启后，你的机体或载具将进入光学隐形状态，无法被雷达和肉眼侦测。", type: "exclusive"},
                    {name: "丹奴之子船长", color: "SS", cost: 7000, desc: "你是天才舰长泰莎。能指挥超级潜艇‘丹奴之子’，拥有极高的战术预判能力。", type: "exclusive"},
                    {name: "九龙的执念", color: "S", cost: 3500, desc: "如同毒蛇般的生命力。即使被打成筛子也能活下来，并对特定的敌人抱有扭曲的执着。", type: "exclusive"},
                    {name: "堕天使(贝利亚)", color: "SS", cost: 8500, desc: "拥有飞行能力和最强Lambda Driver的机体。你是空中的霸主，几乎无敌。", type: "exclusive"},
                    {name: "纸扇吐槽", color: "C", cost: 100, desc: "当身边的人做出缺乏常识的行为时，你的纸扇攻击必中且暴击，能强制打断对方行动。", type: "exclusive"},
                    {name: "AI伙伴(AL)", color: "S", cost: 3000, desc: "搭载在机体上的拥有自我意识的AI。它不仅是辅助，更是能帮你接管战斗的伙伴。", type: "exclusive"},
                    {name: "单分子切割刀", color: "B", cost: 800, desc: "AS配备的近战武器，利用单分子技术，能像切豆腐一样切开坦克装甲。", type: "exclusive"},
                    {name: "妖精之眼", color: "A", cost: 1800, desc: "能够观测到Lambda Driver力场波动的装置，是反制黑科技的关键。", type: "exclusive"},
                    {name: "超长距离狙击", color: "A", cost: 1600, desc: "配合AS的火控系统，能进行数公里外的精准狙击。", type: "exclusive"},
                    {name: "化学阉割", color: "D", cost: 50, desc: "为了执行任务，你可能需要服用抑制激素的药物，导致情感淡漠。", type: "exclusive"},
                    {name: "头发里的微型炸弹", color: "B", cost: 400, desc: "在头发或牙齿里藏有微型炸药，用于自杀或最后的反击。", type: "exclusive"}
                ]
            },
                      {
                name: "191.灼眼的夏娜",
                desc: "红世使徒与火雾战士厮杀的战场。世界充满了肉眼不可见的“磷子”和被吞噬存在之力后留下的火炬。在这个世界，名为“存在”的概念就是一切。",
                boss: "祭礼之蛇·坂井悠二, 赫卡特, 亚拉斯特尔(天罚神)",
                identities: [
                    { name: "御崎高中的即将消失的火炬", items: "残缺的记忆碎片, 正在慢慢变透明的手臂" },
                    { name: "外界宿的底层后勤人员", items: "一把刻有自在法的扫帚, 几瓶恢复存在之力的药剂" },
                    { name: "流浪的低级红世使徒", items: "吞噬人类灵魂的吸管, 一个破旧的玩偶外壳" },
                    { name: "想要复仇的新手火雾战士", items: "与其签订契约的低级红世魔王(吊坠), 一把未开锋的匕首" },
                    { name: "天道宫的扫地机器人", items: "一块抹布, 对威尔艾米娜的恐惧记忆" }
                ],
                talents: [
                    {name: "天壤劫火(契约)", color: "SSS", cost: 32000, desc: "与红世真正的魔神“亚拉斯特尔”签订契约。你能使用足以焚烧万物的天火，但代价是你的肉体可能无法承受而毁灭。这是弑神的力量。", type: "exclusive"},
                    {name: "零时迷子(宝具)", color: "SS", cost: 9000, desc: "传说中的宝具，每到午夜零时，持有者的存在之力就会完全恢复。这意味着你拥有了无限的魔力源泉，是成为强者的基石。", type: "exclusive"},
                    {name: "贽殿遮那(大太刀)", color: "S", cost: 1800, desc: "一把能够抵抗红世之王自在法的最坚固利器。它不仅锋利无比，还能作为施展火焰自在法的绝佳媒介。", type: "exclusive"},
                    {name: "封绝(自在法)", color: "C", cost: 180, desc: "展开一个与现实世界因果隔离的结界。在结界内，时间静止，凡人无法察觉，且破坏的一切都能在解除时用存在之力修复。", type: "exclusive"},
                    {name: "存在之力感知", color: "D", cost: 80, desc: "你能敏锐地察觉到周围存在之力的流动，判断谁是人类，谁是伪装的火炬或使徒。防止被偷袭的基础技能。", type: "exclusive"},
                    {name: "银(自在法)", color: "S", cost: 1600, desc: "召唤银色的火焰，具有极强的束缚和切割能力。这是为了处决红世魔王而开发出的特化型自在法。", type: "exclusive"},
                    {name: "吸血鬼(大剑)", color: "A", cost: 900, desc: "著名的双手大剑，拥有通过斩击吞噬敌人存在之力的特性。越战越强，但小心别被剑的贪婪反噬。", type: "exclusive"},
                    {name: "达摩克利斯之剑(卫星)", color: "C", cost: 150, desc: "虽然听起来很厉害，但其实只是一个能发射激光的浮游炮宝具，操作复杂且容易被打下来。", type: "exclusive"},
                    {name: "玻璃坛(宝具)", color: "S", cost: 1900, desc: "能够观测整个世界、定位任何特定对象的侦查宝具。在情报战中具有绝对的战略价值。", type: "exclusive"},
                    {name: "火焰之翼", color: "B", cost: 450, desc: "从背后喷射出火焰形成的翅膀，赋予你高速飞行的能力。不仅帅气，还能在空中进行立体机动战斗。", type: "exclusive"},
                    {name: "吞食都市(禁术)", color: "SS", cost: 7500, desc: "极度邪恶的自在法，瞬间将一座城市内所有生灵的存在之力吞噬殆尽。虽然能获得庞大力量，但会立刻成为世界公敌。", type: "exclusive"},
                    {name: "梅隆(哈密瓜包)狂热", color: "C", cost: 120, desc: "你对哈密瓜包有着异常的执着。食用哈密瓜包后，你的心情会变好，全属性微量提升持续1小时。", type: "exclusive"},
                    {name: "只有火炬的悲伤", color: "D", cost: 60, desc: "作为火炬，你的存在感很低，容易被敌人忽视，但也容易被队友遗忘。每天需要消耗少量存在之力维持生命。", type: "exclusive"},
                    {name: "红世之王(血统)", color: "A", cost: 1200, desc: "你不再是人类，而是来自红世的居民。拥有漫长的寿命和强大的肉体力量，但需要定期吞噬存在之力。", type: "exclusive"},
                    {name: "真红(火焰)", color: "B", cost: 500, desc: "你能操控具有“审判”属性的真红之火，对邪恶和负面能量生物造成额外伤害。", type: "exclusive"}
                ]
            },
            {
                name: "192.零之使魔",
                desc: "哈尔凯尼亚大陆，魔法师贵族统治着平民。虚无的传说在阴影中涌动，异世界的武器与魔法交织。",
                boss: "始祖布利弥尔, 约瑟夫(疯王), 远古神之头脑(巨龙)",
                identities: [
                    { name: "托里斯汀魔法学院的平民女仆", items: "一套洗得发白的女仆装, 擦鞋工具" },
                    { name: "被召唤的异世界少年(无外挂版)", items: "一部没电的手机, 一身奇怪的运动服" },
                    { name: "阿尔比昂的逃兵", items: "一把卷刃的长剑, 藏在靴子里的半块黑面包" },
                    { name: "日耳曼尼亚的雇佣兵", items: "染血的皮甲, 一袋沉甸甸的金币(假的)" },
                    { name: "魔法学院的差生", items: "一根总是爆炸的魔杖, 满是红叉的试卷" }
                ],
                talents: [
                    {name: "神之左手(刚达鲁夫)", color: "S", cost: 1900, desc: "传说中的使魔印记。你可以熟练使用任何武器（包括从未见过的异世界枪械、战斗机），并拥有超人的体能。", type: "exclusive"},
                    {name: "虚无魔法(使用者)", color: "SS", cost: 8800, desc: "凌驾于四系魔法之上的始祖魔法。你可以施放“爆炸”、“解除”、“传送”等干涉法则的咒语，威力足以毁灭军队。", type: "exclusive"},
                    {name: "德鲁弗林格(智慧之剑)", color: "A", cost: 800, desc: "一把拥有自我意识的生锈长剑。虽然看起来破旧，但它知晓许多古代秘密，且坚不可摧，能附着魔法。", type: "exclusive"},
                    {name: "神之右手(温达鲁夫)", color: "S", cost: 1800, desc: "传说中的使魔印记。你可以驯服并指挥任何幻兽，哪怕是远古巨龙也会听从你的号令。同时能强化幻兽的能力。", type: "exclusive"},
                    {name: "神之头脑(缪奥兹尼特尼特恩)", color: "S", cost: 1950, desc: "传说中的使魔印记。赋予你极高的魔法道具制作天赋，能将任何魔法物品的效果增幅数倍，甚至制造核弹级魔导器。", type: "exclusive"},
                    {name: "零之露易丝(爆破)", color: "C", cost: 180, desc: "你施放任何魔法都有99%的几率失败并引发爆炸。虽然很丢人，但这爆炸的威力其实不容小觑。", type: "exclusive"},
                    {name: "四系魔法精通(三角级)", color: "B", cost: 600, desc: "你是难得的魔法天才，精通火、水、风、土四系魔法，达到了三角级法师的水平，足以在军队中担任指挥官。", type: "exclusive"},
                    {name: "M72反坦克火箭筒", color: "B", cost: 350, desc: "来自异世界的“魔杖”。对于不知道热武器恐怖的法师来说，这一发足以击碎他们的护盾和高傲。", type: "exclusive"},
                    {name: "零式战斗机(废弃)", color: "A", cost: 700, desc: "一架来自异世界的二战战斗机。如果你有刚达鲁夫的能力，它就是天空中的霸主；否则它就是一堆废铁。", type: "exclusive"},
                    {name: "魅惑之药", color: "C", cost: 150, desc: "魔法学院违禁品。能让喝下的人在短时间内疯狂爱上第一眼看到的人。慎用，容易引发修罗场。", type: "exclusive"},
                    {name: "土块之芙凯(魔像术)", color: "B", cost: 550, desc: "你擅长制造巨大的土石魔像进行战斗。只要站在大地上，你就有源源不断的卫兵。", type: "exclusive"},
                    {name: "水精灵之戒", color: "A", cost: 950, desc: "水精灵安德巴利的力量碎片。能大幅增强水系魔法威力，并赋予持有者在水中自由行动和伪装的能力。", type: "exclusive"},
                    {name: "虚无的咏唱者", color: "SS", cost: 6000, desc: "你不需要使魔，自身就能通过漫长的咏唱调动虚无之力。只要给你足够的时间，你能改写现实。", type: "exclusive"},
                    {name: "贵族的荣耀", color: "C", cost: 120, desc: "身为贵族，你的自尊心极强。在面对平民时气势压制+10%，但在受到侮辱时容易失去理智。", type: "exclusive"},
                    {name: "双月之夜的狂乱", color: "D", cost: 80, desc: "在两个月亮重合的夜晚，你的魔力会暴走，全属性提升但难以控制魔法的准头。", type: "exclusive"}
                ]
            },
            {
                name: "193.旋风管家",
                desc: "一个充满了误会、欠债、豪宅和超展开的世界。虽然看似日常，但隐藏着能毁灭世界的王玉和各种超人管家。",
                boss: "三千院帝, 雅典娜(天王州), 米克诺斯迷宫的魔物",
                identities: [
                    { name: "身负1亿5千万债务的打工仔", items: "一张签了名的器官贩卖合同, 圣诞老人的玩偶服" },
                    { name: "白皇学院的吊车尾学生", items: "不及格的试卷, 一把坏掉的竹刀" },
                    { name: "三千院家的临时园丁", items: "一把剪刀, 被球球(老虎)咬破的裤子" },
                    { name: "为了梦想离家出走的漫画家", items: "沾满墨水的G笔, 一叠被编辑退回的原稿" },
                    { name: "以前是杀手的便利店店员", items: "过期的便当, 藏在收银台下的手枪" }
                ],
                talents: [
                    {name: "欠债管家体质", color: "S", cost: 1500, desc: "你的肉体经过地狱般的磨练，拥有不死小强般的生命力。无论被车撞、被雷劈还是被导弹炸，你总能活下来打工还债。", type: "exclusive"},
                    {name: "王玉(诅咒)", color: "SS", cost: 7000, desc: "蕴含着能实现愿望但会扭曲命运的力量。持有者可以开启通往王城的道路，但也可能被吸干灵魂。是通往神之领域的钥匙。", type: "exclusive"},
                    {name: "必杀·黑龙波(伪)", color: "C", cost: 180, desc: "虽然只是模仿漫画里的招式，但凭借你的气势和怪力，竟然真的能打出黑色的冲击波。对中二病患者特攻。", type: "exclusive"},
                    {name: "女装大佬", color: "B", cost: 300, desc: "当你穿上女装时，魅力值突破天际，能魅惑S级以下的男性角色，甚至连你自己都会产生性别认知障碍。", type: "exclusive"},
                    {name: "白皇学院制服", color: "C", cost: 200, desc: "这不仅是一件校服，更是身份的象征。穿上它，你在这个世界会被认为是“上流社会”的一员，虽然后果自负。", type: "exclusive"},
                    {name: "剑圣的真传", color: "A", cost: 1200, desc: "你继承了传说中剑圣的剑术。能够斩断钢铁、劈开子弹，甚至能用剑气切开衣服而不伤皮肤。", type: "exclusive"},
                    {name: "不幸体质", color: "D", cost: 50, desc: "你就像个倒霉磁铁。走在路上会被花盆砸，买彩票永远差一位。但也因此锻炼了你的闪避能力。", type: "exclusive"},
                    {name: "神之手(漫画)", color: "C", cost: 150, desc: "你画漫画的速度极快，且能画出让人看一眼就沉迷的同人本。在秋叶原地区声望崇拜。", type: "exclusive"},
                    {name: "修女的驱魔术", color: "B", cost: 450, desc: "虽然那个修女很不靠谱，但你学会了真正的驱魔术。对幽灵和恶灵有极大的杀伤力。", type: "exclusive"},
                    {name: "球球(白老虎)", color: "A", cost: 800, desc: "三千院家的宠物。虽然看起来可爱，但它是一头能咬碎骨头的猛兽。你可以召唤它协助战斗。", type: "exclusive"},
                    {name: " 24小时全能管家", color: "A", cost: 600, desc: "你会做饭、洗衣、修理家电、驾驶飞机、拆除炸弹。除了赚钱，你几乎无所不能。", type: "exclusive"},
                    {name: "黑椿(魔剑)", color: "S", cost: 2200, desc: "一把会吞噬持有者灵魂以换取力量的魔剑。如果不小心使用，你会变成只知道杀戮的怪物。", type: "exclusive"},
                    {name: "只有误会的世界", color: "C", cost: 100, desc: "你说的话总是被人曲解。你说“我要保护你”，对方听到的是“我要永远占有你”。容易建立奇怪的后宫。", type: "exclusive"},
                    {name: "SP的墨镜", color: "D", cost: 30, desc: "戴上后存在感归零，变成完美的背景板路人。适合潜入和逃跑。", type: "exclusive"},
                    {name: "三千院的财力", color: "SS", cost: 5000, desc: "虽然不是你的钱，但你获得了随意调动三千院财团资源的权限。用钱砸死敌人不再是梦想。", type: "exclusive"}
                ]
            },
            {
                name: "194.出包王女",
                desc: "戴比路克星王女降临地球，引发了一系列跨越银河的恋爱喜剧。这里充满了外星科技、杀手和不可思议的物理法则。",
                boss: "奇多·路西翁·戴比路克(银河王), 涅墨西斯, 黑暗(全盛期)",
                identities: [
                    { name: "彩南高中的纯情男生", items: "一本写着暗恋对象名字的日记, 总是被掀开的裙子(误)" },
                    { name: "戴比路克星的皇家护卫", items: "一把激光枪, 对王女的绝对忠诚" },
                    { name: "银河系的流浪杀手", items: "变身伪装器, 悬赏令" },
                    { name: "想要研究人类的外星科学家", items: "奇怪的绿色药水, 触手样本" },
                    { name: "结城家的浴室瓷砖", items: "防滑垫, 每天都能看到福利" }
                ],
                talents: [
                    {name: "神摔(梨斗摔)", color: "SSS", cost: 15000, desc: "因果律级别的被动技能。无论你在何时何地跌倒，都会精准地扑向最近的异性，并造成不可描述的接触。无视物理防御和闪避。", type: "exclusive"},
                    {name: "戴比路克王族血统", color: "SS", cost: 6000, desc: "拥有统治银河的力量。你的体能、恢复力都是怪物级别的。尾巴是你的力量源泉，也是敏感点。", type: "exclusive"},
                    {name: "全身变形武器(Trans)", color: "S", cost: 2500, desc: "你可以将身体的任何部位变成冷兵器或钝器。这是宇宙第一杀手“金色暗影”的招牌技能。", type: "exclusive"},
                    {name: "佩克(变装机器人)", color: "B", cost: 400, desc: "一个拥有自我意识的徽章，可以根据你的意愿瞬间为你换上任何款式的衣服（虽然经常没电导致爆衣）。", type: "exclusive"},
                    {name: "费洛蒙体质", color: "A", cost: 1000, desc: "你天生散发着吸引异性的气息，植物系外星人甚至会想把你吃掉。攻略S级以下角色难度减半。", type: "exclusive"},
                    {name: "天才发明家", color: "S", cost: 2200, desc: "你拥有拉拉级别的发明头脑，能制造出“跳跳瓦普君”、“顺风耳君”等功能离谱的道具，但通常会有羞耻的副作用。", type: "exclusive"},
                    {name: "古手川的纪律委员袖章", color: "C", cost: 150, desc: "佩戴后，你对“不知廉耻”的行为极其敏感，攻击力+20%，但容易陷入自我攻略的傲娇状态。", type: "exclusive"},
                    {name: "植物操控(西连寺)", color: "B", cost: 500, desc: "你能与植物沟通，并控制藤蔓进行攻击或防御。在森林地形战斗力翻倍。", type: "exclusive"},
                    {name: "暗物质操控(涅墨西斯)", color: "SS", cost: 7500, desc: "你可以自由操控暗物质，改变形状、质地，甚至创造出拥有独立意识的分身。这是宇宙中极其危险的能力。", type: "exclusive"},
                    {name: "风纪委员的铁拳", color: "C", cost: 120, desc: "当你大喊“不知廉耻”时，下一次攻击必定暴击。对变态类敌人有额外伤害加成。", type: "exclusive"},
                    {name: "梦梦的后宫计划书", color: "A", cost: 800, desc: "一本详细记载了如何建立和谐后宫的指南。阅读后，你的情商大幅提升，能有效化解修罗场。", type: "exclusive"},
                    {name: "御门老师的医术", color: "B", cost: 450, desc: "作为外星医生，你的治疗手段虽然粗暴且带有实验性质，但效果拔群。能治疗大部分地球疾病和外星病毒。", type: "exclusive"},
                    {name: "尾巴弱点(诅咒)", color: "D", cost: 100, desc: "虽然你有强大的力量，但尾巴一旦被抓住，你就会全身无力，任人摆布。致命的弱点。", type: "exclusive"},
                    {name: "虚拟潜行游戏机", color: "C", cost: 200, desc: "可以进入RPG游戏世界的装置。如果不通关就无法出来，且痛觉是真实的。练级的好地方。", type: "exclusive"},
                    {name: "银河级歌姬", color: "A", cost: 700, desc: "你的歌声能传遍银河，拥有洗涤心灵、平息战争甚至控制精神的力量。", type: "exclusive"}
                ]
            },
            {
                name: "195.天降之物",
                desc: "和平的空美町，天空中悬浮着未知的“西纳普斯”。人造天使们带着悲伤的宿命降临，为了爱与自由而战。",
                boss: "空之主(米诺斯), 混沌(Chaos), 西纳普斯防御系统",
                identities: [
                    { name: "空美町的种田大叔", items: "一把锄头, 一袋刚摘的黄瓜" },
                    { name: "好色的樱井智树式学生", items: "各色各样的胖次(收藏品), 偷窥用的望远镜" },
                    { name: "西纳普斯的量产型人造天使", items: "未激活的翅膀, 编号项圈" },
                    { name: "正在做怪梦的科学家", items: "量子力学笔记, 蝴蝶标本" },
                    { name: "深山里的隐居猎人", items: "老式猎枪, 捕兽夹" }
                ],
                talents: [
                    {name: "乌拉诺斯系统(天王星)", color: "SSS", cost: 25000, desc: "伊卡洛斯的最终兵器。拥有变形为巨大战舰的能力，搭载了足以毁灭国家的火力。一击即可抹平地图。", type: "exclusive"},
                    {name: "万能卡片", color: "S", cost: 2200, desc: "一次性消耗品，但极为强大。写上愿望，就能在一定限度内改变现实（如瞬间移动、获得金钱、改变天气）。", type: "exclusive"},
                    {name: "铭刻(Imprinting)", color: "B", cost: 500, desc: "作为主人，你可以与人造天使进行铭刻。获得天使的绝对忠诚，并能通过锁链共享痛觉或传输能量。", type: "exclusive"},
                    {name: "宙斯盾(Aegis)", color: "SS", cost: 8000, desc: "绝对防御圈。能展开抵挡几乎所有物理和能量攻击的球形护盾。只要护盾不破，你就是无敌的。", type: "exclusive"},
                    {name: "阿尔忒弥斯(导弹)", color: "A", cost: 1200, desc: "永久追尾空对空导弹。一旦锁定目标，就会追击到天涯海角。你可以一次性发射数十枚。", type: "exclusive"},
                    {name: "阿波罗(最终兵器)", color: "SS", cost: 9500, desc: "一把巨大的火焰弓箭，射出的箭矢威力等同于核弹，能瞬间蒸发一片区域。副作用是消耗巨大。", type: "exclusive"},
                    {name: "可变式羽翼系统", color: "A", cost: 800, desc: "赋予你超音速飞行的能力。无论是空中狗斗还是长途奔袭，你都是天空的王者。", type: "exclusive"},
                    {name: "黑客入侵(电子战)", color: "S", cost: 1600, desc: "电子战用人造天使妮姆芙的能力。你可以入侵任何电子设备，甚至改写敌方人造天使的程序。", type: "exclusive"},
                    {name: "超振动光子剑(Chrysaor)", color: "A", cost: 1000, desc: "阿斯特雷亚的武器。能切开光子层面的防御，配合你的怪力，近战几乎无坚不摧。", type: "exclusive"},
                    {name: "潘多拉(进化)", color: "SS", cost: 7000, desc: "自我进化程序。当你受到致命伤害或陷入绝境时，能力值会呈指数级暴涨，适应并克服当前的困境。", type: "exclusive"},
                    {name: "西纳普斯的居民", color: "A", cost: 900, desc: "你拥有天空人的血统，寿命极长，智力超群，可以使用西纳普斯的高科技设备。", type: "exclusive"},
                    {name: "变态的执着", color: "C", cost: 150, desc: "为了看到胖次，你可以爆发出超越人类极限的速度和耐力。在特定情境下全属性+50%。", type: "exclusive"},
                    {name: "量子转换器", color: "B", cost: 600, desc: "能将非生命物体进行量子重组，例如把废铁变成黄金。是赚取积分的好帮手。", type: "exclusive"},
                    {name: "绝对服从项圈", color: "C", cost: 200, desc: "带上它的人无法违抗命令。虽然有点不人道，但对于控制俘虏很有效。", type: "exclusive"},
                    {name: "梦境潜入", color: "S", cost: 1800, desc: "你可以进入他人的梦境，并在梦中杀死对方的精神。在梦中你是全能的神。", type: "exclusive"}
                ]
            },
            {
                name: "196.High School DxD",
                desc: "神魔乱舞的世界。恶魔、天使、堕天使三足鼎立，传说中的龙在天际咆哮。神器（Sacred Gear）是凡人逆天的关键。",
                boss: "666兽(Trihexa), 列泽维姆·李维安·路西法, 伟大之红(Great Red)",
                identities: [
                    { name: "驹王学园的好色高中生", items: "一本色情杂志, 隐藏的神器(未觉醒)" },
                    { name: "迷失的驱魔师", items: "一把光之剑, 破损的圣经" },
                    { name: "堕天使总督的下级干部", items: "黑色羽翼(单翼), 光之长枪" },
                    { name: "吉蒙里眷属的士兵(Pawn)", items: "恶魔棋子(士兵), 莉雅丝的签名照" },
                    { name: "教会洗脑的圣剑使用者", items: "圣剑碎片, 狂热的信仰" }
                ],
                talents: [
                    {name: "赤龙帝的笼手(Boosted Gear)", color: "SSS", cost: 30000, desc: "神灭具之一，寄宿着二天龙之一德莱格的灵魂。每10秒力量倍增一次，理论上可以无限强化，直至弑神。", type: "exclusive"},
                    {name: "白龙皇的光翼(Divine Dividing)", color: "SSS", cost: 30000, desc: "神灭具之一，寄宿着阿白昂的灵魂。每10秒减半对手的力量并加到自己身上。还能扭曲空间。", type: "exclusive"},
                    {name: "恶魔棋子(转生)", color: "A", cost: 1000, desc: "你被转生为恶魔。根据棋子不同获得不同能力（战车高防高攻，骑士高速，僧侣高魔）。畏惧光属性。", type: "exclusive"},
                    {name: "黄昏的圣枪", color: "SS", cost: 9500, desc: "最强神灭具，曾刺穿耶稣身体的长枪。拥有绝对的“神性”克制，能抹杀一切神魔。", type: "exclusive"},
                    {name: "魔王利维坦血统", color: "SS", cost: 6000, desc: "继承了旧魔王的血脉，拥有极高的魔力亲和度和水、冰系魔法天赋，但也继承了傲慢。", type: "exclusive"},
                    {name: "乳龙帝的奥义(洋葱)", color: "C", cost: 200, desc: "通过触摸女性胸部来读取思想或传达心意。虽然很变态，但在情报战中意外地有用。", type: "exclusive"},
                    {name: "圣剑创造(Blade Blacksmith)", color: "S", cost: 2200, desc: "可以制造出各种属性的魔剑和圣剑。你是战场的军火库，能针对敌人的弱点制造武器。", type: "exclusive"},
                    {name: "绝雾(Dimension Lost)", color: "SS", cost: 8000, desc: "上位神灭具。能制造出连神都无法逃脱的异次元迷雾，随意阻断空间和视线。", type: "exclusive"},
                    {name: "堕天使的血脉", color: "B", cost: 500, desc: "你拥有黑色的羽翼，能操纵光之长枪。介于神圣与邪恶之间，对两者的抗性都不错。", type: "exclusive"},
                    {name: "不死鸟之泪", color: "A", cost: 800, desc: "菲尼克斯家的特产。只要没死透，喝下去就能瞬间满血复活。极其珍贵的保命道具。", type: "exclusive"},
                    {name: "狮子王的战斧", color: "S", cost: 2000, desc: "神灭具。一把拥有自我意识的巨大战斧，能将受到的攻击转化为自身的力量并反击。", type: "exclusive"},
                    {name: "木场佑斗的魔剑创造", color: "A", cost: 1200, desc: "虽然不及圣剑创造，但你能快速制造大量魔剑进行投掷或陷阱布置，速度极快。", type: "exclusive"},
                    {name: "加斯帕的时间停止", color: "SS", cost: 8500, desc: "邪眼的能力。能强制停止视野内物体的时间。虽然初期难以控制，但成长后是无解的控场技。", type: "exclusive"},
                    {name: "龙神化(霸龙)", color: "SSS", cost: 28000, desc: "透支生命开启的禁手模式。获得二天龙全盛时期的力量，足以匹敌魔王。代价是生命力被急速吞噬。", type: "exclusive"},
                    {name: "乳语翻译", color: "D", cost: 50, desc: "你能听懂兵藤一诚关于欧派的各种黑话。这让你能更好地与赤龙帝沟通（如果你想的话）。", type: "exclusive"}
                ]
            },
            {
                name: "197.我们仍未知道那天所看见的花的名字",
                desc: "一个关于童年、遗憾和救赎的故事。虽然没有硝烟，但情感的冲击力足以击碎灵魂。面码的幽灵在等待着大家的和解。",
                boss: "过去的心理阴影(全员), 松雪集(女装版), 无法实现的愿望",
                identities: [
                    { name: "秩父市的家里蹲高中生", items: "未通关的游戏机, 一件印着地底人的T恤" },
                    { name: "超和平Busters的边缘成员", items: "一枚生锈的徽章, 一本写满秘密的日记" },
                    { name: "面码的远房亲戚", items: "供奉用的线香, 一张黑白照片" },
                    { name: "秘密基地的非法入侵者", items: "手电筒, 捡来的色情杂志" },
                    { name: "面码父亲的同事", items: "咖喱配料, 佛珠" }
                ],
                talents: [
                    {name: "幽灵视界(阴阳眼)", color: "A", cost: 800, desc: "你能看到死去的灵魂。在这个世界，这意味着你能看见面码；在其他世界，这是侦查灵体的神技。", type: "exclusive"},
                    {name: "绝对催泪弹(Secret Base)", color: "S", cost: 2500, desc: "当那首BGM响起时，周围所有生物进入“回忆杀”状态，战意全消，泪流满面。强制解除敌对状态3分钟。", type: "exclusive"},
                    {name: "超和平Busters徽章", color: "C", cost: 150, desc: "象征着永远的友谊。佩戴者与队友的连携攻击伤害+20%，且不会被精神类魔法控制。", type: "exclusive"},
                    {name: "蒸糕制作大师", color: "D", cost: 80, desc: "你能做出极其美味的蒸糕。虽然不能杀敌，但能极大地回复食用者的SAN值（精神力）。", type: "exclusive"},
                    {name: "女装癖(雪集)", color: "C", cost: 200, desc: "当你穿上白色连衣裙并戴上假发时，你的速度和敏捷提升，但智力大幅下降，容易做出疯狂举动。", type: "exclusive"},
                    {name: "火箭烟花制作", color: "B", cost: 400, desc: "你掌握了制作大型烟花的技术。在战斗中，这可以转化为制作土制炸弹和信号弹的能力。", type: "exclusive"},
                    {name: "寻找面码", color: "SS", cost: 5000, desc: "一种因果律般的寻人能力。无论目标躲在哪里（甚至是异位面），你都能感知到他/她的方位。", type: "exclusive"},
                    {name: "昔日的羁绊", color: "A", cost: 1000, desc: "召唤昔日伙伴的幻影助战。伙伴越多，力量越强。这是友情的奇迹之力。", type: "exclusive"},
                    {name: "家里蹲的耐力", color: "D", cost: 60, desc: "你习惯了长时间不运动和熬夜。对疲劳和饥饿的抗性微量提升。", type: "exclusive"},
                    {name: "波波的环球旅行经验", color: "B", cost: 350, desc: "你拥有极其丰富的野外生存和打工经验。在任何恶劣环境下都能找到食物和住所。", type: "exclusive"},
                    {name: "鹤子的绘画", color: "C", cost: 120, desc: "你擅长素描和观察。能快速画出敌人的弱点分布图，辅助队友进攻。", type: "exclusive"},
                    {name: "鸣子的指甲油", color: "D", cost: 40, desc: "涂上特制的指甲油，你的魅力微量提升，且指甲变得坚硬如铁，可以作为暗器。", type: "exclusive"},
                    {name: "最后的捉迷藏", color: "S", cost: 2000, desc: "当你喊出“藏好了吗”时，所有敌人强制进入隐蔽状态；喊出“找到了”时，暴露的敌人受到精神重创。", type: "exclusive"},
                    {name: "无尽的夏日", color: "A", cost: 1500, desc: "将环境强制变为炎热的夏天。火属性魔法威力+50%，冰属性威力-50%。", type: "exclusive"},
                    {name: "转世投胎的承诺", color: "SS", cost: 8000, desc: "死亡后有50%几率直接转生为该世界的新生儿，保留记忆。真正的复活神技。", type: "exclusive"}
                ]
            },
            {
                name: "198.龙与虎",
                desc: "眼神凶恶的龙儿与掌中萌虎大河的恋爱修罗场。虽然是校园恋爱，但木刀和拳头也是交流的一部分。",
                boss: "逢坂大河(暴走), 栉枝实乃梨(黑化), 高须泰子(醉酒)",
