                    { name: "泰子酒吧的常客", items: "一瓶廉价威士忌, 欠条" },
                    { name: "北村祐作的学生会跟班", items: "学生会袖章, 眼睛布" },
                    { name: "被大河袭击过的路人", items: "创可贴, 被木刀打断的雨伞" }
