                    { name: "宫园薰的狂热粉丝", items: "小提琴独奏会门票, 一束波斯菊" },
                    { name: "滕和音乐厅的清洁工", items: "拖把, 捡到的琴弦" },
                    { name: "有马公生的竞争对手", items: "昂贵的钢琴, 对公生的嫉妒心" },
                    { name: "住在公生隔壁的青梅竹马", items: "创可贴, 垒球棒" }
                ],
                talents: [
                    {name: "联觉(Synesthesia)", color: "S", cost: 2500, desc: "你能看到声音的颜色和形状。在战斗中，这表现为能预判音波攻击，甚至通过演奏具象化出彩色的冲击波。", type: "exclusive"},
                    {name: "绝对音感", color: "A", cost: 1000, desc: "你能分辨出任何声音的频率。这让你能听出敌人的心跳变化、机械故障声，甚至是谎言的音调。", type: "exclusive"},
                    {name: "悲剧主角光环", color: "SS", cost: 7000, desc: "你注定会遭遇悲剧，但因此获得极高的人气和世界意志的关注。在濒死状态下，爆发力提升1000%。", type: "exclusive"},
                    {name: "人性节拍器", color: "C", cost: 300, desc: "你的节奏感精准到毫秒。在团队配合中，你能完美协调队友的攻击节奏，形成无缝连招。", type: "exclusive"},
                    {name: "母亲的诅咒(心魔)", color: "D", cost: 100, desc: "负面天赋。在关键时刻，你会听到母亲的责骂声，导致听不见声音或身体僵硬。需要强大的意志克服。", type: "exclusive"},
                    {name: "爱之悲(小提琴)", color: "A", cost: 1200, desc: "一把充满感情的小提琴。演奏此曲时，能让听到的人陷入极度悲伤，丧失战斗意志。", type: "exclusive"},
                    {name: "黑猫(幻影)", color: "B", cost: 500, desc: "一只只有你能看见的黑猫。它会引导你找到关键道具或避开危险，但也代表着不祥。", type: "exclusive"},
                    {name: "卡努蕾(甜点)", color: "E", cost: 30, desc: "薰最爱的点心。虽然只是食物，但送给特定角色能大幅提升好感度。", type: "exclusive"},
                    {name: "再一次合奏", color: "SS", cost: 6500, desc: "复活类技能。能让一名刚死去的队友以灵魂形态存在10分钟，进行最后一次完美的配合。", type: "exclusive"},
                    {name: "色彩爆发", color: "S", cost: 2000, desc: "当你的情绪达到顶点时，周围的世界会变成绚丽的彩色。全场友方单位精神力回满，解除所有控制。", type: "exclusive"},
                    {name: "只有黑白的世界", color: "E", cost: 10, desc: "诅咒。你的世界失去了颜色。虽然压抑，但也让你对光影的变化更加敏感。", type: "exclusive"},
                    {name: "乐谱记忆", color: "C", cost: 150, desc: "过目不忘。不仅是乐谱，任何情报看一眼就能记住。抄作业和背地图的神技。", type: "exclusive"},
                    {name: "钢琴师的手指", color: "B", cost: 400, desc: "你的手指灵活度极高，适合拆弹、开锁、结印等精细操作。", type: "exclusive"},
                    {name: "谎言的代价", color: "A", cost: 1500, desc: "你可以说出一个成真的谎言，但代价是消耗自己的生命力。谎言越大，代价越大。", type: "exclusive"},
                    {name: "四月的樱花", color: "C", cost: 200, desc: "召唤漫天樱花瓣。虽然没有伤害，但极美，能制造视觉干扰。", type: "exclusive"}
                ]
            },
                      {
                name: "201.水果篮子",
                desc: "一个关于诅咒、羁绊与救赎的世界。数百年前的约定化作十二生肖的诅咒，束缚着草摩家族的成员。被异性拥抱就会变身，只有解开诅咒才能获得真正的自由。",
                boss: "草摩慊人, 草摩红野, 草摩藉真",
                identities: [
                    { name: "海原高校的普通学生", items: "一个磨损严重的书包, 一本写满笔记的课本" },
                    { name: "草摩家的外围佣人", items: "一套整洁的日式工作服, 一把用来扫落叶的竹扫帚" },
                    { name: "住在帐篷里的流浪者", items: "一顶漏风的蓝色小帐篷, 一张全家福照片" },
                    { name: "被霸凌的转校生", items: "一双被藏起来的室内鞋, 一个画满涂鸦的课桌" },
                    { name: "草摩本家的守卫", items: "一个无线电对讲机, 一身黑色的安保制服" }
                ],
                talents: [
                    {name: "生肖附身(猫)", color: "SS", cost: 8800, desc: "你被猫妖附身。虽然不属于十二生肖，但拥有极其敏捷的身手和野兽般的直觉。代价是被异性拥抱会变身，且被本家当做怪物排斥。", type: "exclusive"},
                    {name: "神之宠爱(诅咒)", color: "SSS", cost: 15000, desc: "你是连接十二生肖羁绊的''神''。所有被生肖附身的人在生理上无法违抗你的命令。你拥有绝对的支配权，但也承受着所有人的负面情感。", type: "exclusive"},
                    {name: "十二生肖(鼠)", color: "S", cost: 1800, desc: "你被鼠妖附身，拥有极其聪明的头脑和灵活的身手。在草摩家族中地位较高，容易获得特权，但身体素质较弱。", type: "exclusive"},
                    {name: "十二生肖(牛)", color: "A", cost: 1200, desc: "你被牛妖附身，拥有常人难以企及的怪力。性格固执但坚韧，黑白发色是你的特征。变身后是一头小牛。", type: "exclusive"},
                    {name: "波长同调", color: "B", cost: 500, desc: "你的电波很容易与他人对上，能够快速感知到他人的情绪变化，这让你在处理人际关系时如鱼得水。", type: "exclusive"},
                    {name: "妈妈的教诲", color: "C", cost: 150, desc: "你记忆中母亲的教诲能让你在绝望时保持乐观。无论遇到什么困难，你都能笑着说''没关系''。", type: "exclusive"},
                    {name: "格斗术真传", color: "A", cost: 800, desc: "你师从草摩家的武术师范，掌握了精湛的徒手格斗技巧，能够轻松击倒比自己强壮的对手。", type: "exclusive"},
                    {name: "超强直觉", color: "B", cost: 450, desc: "你拥有野兽般的直觉，能够察觉到周围人的恶意或者即将到来的危险，甚至能看穿别人的伪装。", type: "exclusive"},
                    {name: "治愈系笑容", color: "C", cost: 180, desc: "你的笑容拥有神奇的感染力，能够平复他人内心的躁动和不安，容易获得NPC的好感度。", type: "exclusive"},
                    {name: "家务全能", color: "C", cost: 120, desc: "无论是做饭、洗衣还是打扫卫生，你都达到了专业级别。这是在任何世界生存的基础技能。", type: "exclusive"},
                    {name: "记忆封印术", color: "S", cost: 1500, desc: "掌握了草摩家秘传的催眠术，可以强行消除普通人关于变身秘密的记忆，甚至能修改部分认知。", type: "exclusive"},
                    {name: "十二生肖(龙)", color: "S", cost: 1600, desc: "你被海马(龙)附身。虽然变身后只是小海马，但你拥有转化形态的能力，且在家族中备受呵护。", type: "exclusive"},
                    {name: "笨拙的温柔", color: "C", cost: 100, desc: "你虽然不善言辞，经常把事情搞砸，但你笨拙的善意总能传达给真正懂你的人。", type: "exclusive"},
                    {name: "红叶的小提琴", color: "B", cost: 300, desc: "你拥有极高的音乐天赋，拉出的小提琴曲能引起听众的共鸣，甚至能短暂安抚暴走的情绪。", type: "exclusive"},
                    {name: "羁绊斩断者", color: "SSS", cost: 12000, desc: "你拥有打破数百年来诅咒锁链的力量。你可以选择解除某个人的生肖诅咒，让他重获自由，但这会激怒''神''。", type: "exclusive"}
                ]
            },
            {
                name: "202.蜂蜜与四叶草",
                desc: "滨田山美术大学的青春群像剧。在这个充满松节油味道的世界里，才华与迷茫并存。每个人都在寻找属于自己的四叶草，关于单恋、自我实现与成长的故事。",
                boss: "花本修司, 藤原类二, 滨田山美大理事长",
                identities: [
