                    { name: "面临毕业的留级生", items: "一堆未完成的草稿, 一张催缴学费的通知单" },
                    { name: "事务所的加班社畜", items: "一瓶强效眼药水, 一个在此刻显得多余的颈椎枕" },
                    { name: "陶艺工作室学徒", items: "沾满泥土的围裙, 一双粗糙的手" },
                    { name: "建筑系的天才学生", items: "一卷精密的建筑图纸, 一把昂贵的比例尺" }
                ],
                talents: [
                    {name: "精灵般的才华", color: "SS", cost: 6000, desc: "你拥有被艺术之神亲吻过的天赋。你的画作能直击灵魂，展现出令人窒息的美感，但也让你显得与世俗格格不入。", type: "exclusive"},
                    {name: "寻找四叶草", color: "SSS", cost: 11000, desc: "概念级天赋。你总能在绝望的命运中找到唯一的幸福解法。这不仅是运气，更是一种因果律层面的幸福引导。", type: "exclusive"},
                    {name: "绝对音感", color: "A", cost: 900, desc: "你对声音极其敏感，能分辨出极其细微的音调差异。这在音乐创作或调试设备时是神技。", type: "exclusive"},
                    {name: "雕塑之手", color: "B", cost: 600, desc: "你的双手极其灵巧且有力，能将木头、石头或粘土塑造成任何你想象中的形状，赋予死物生命感。", type: "exclusive"},
                    {name: "暴走青春", color: "C", cost: 150, desc: "当你骑上自行车或奔跑时，体力消耗减半，速度提升。适合在迷茫时发泄情绪或进行长途旅行。", type: "exclusive"},
                    {name: "建筑结构洞察", color: "A", cost: 1200, desc: "你只需看一眼就能理解建筑物的结构和承重点。这不仅有助于设计，拆迁（破坏）起来也更有效率。", type: "exclusive"},
                    {name: "金钱黑洞(负面)", color: "D", cost: 50, desc: "不管你赚多少钱，总会因为各种意外（如请客、损坏公物、买昂贵材料）而花光。你永远处于贫困线。", type: "exclusive"},
                    {name: "厨艺大师", color: "B", cost: 400, desc: "你能用廉价的食材做出豪华的盛宴。在贫穷的美大生活中，你是朋友们眼中的救世主。", type: "exclusive"},
                    {name: "单恋雷达", color: "C", cost: 120, desc: "你能敏锐地察觉到谁喜欢谁，形成复杂的人物关系图。虽然对战斗没用，但对吃瓜很有帮助。", type: "exclusive"},
                    {name: "不倒翁体质", color: "B", cost: 550, desc: "无论遭遇多少次失败或打击，你都能迅速调整心态重新站起来。精神抗性大幅提升。", type: "exclusive"},
                    {name: "神秘的巨款", color: "S", cost: 1800, desc: "你的口袋里总是莫名其妙地出现一笔巨款，来源合法但成谜。这让你有资本去追求纯粹的艺术。", type: "exclusive"},
                    {name: "时间静止的画作", color: "SS", cost: 7500, desc: "你画出的作品能捕捉瞬间的永恒。观看者会陷入短暂的精神恍惚，仿佛时间被冻结在画框之中。", type: "exclusive"},
                    {name: "疯狂的灵感", color: "A", cost: 1000, desc: "灵感来袭时你会进入狂热状态，全属性提升，不知疲倦地创作，直到作品完成或身体崩溃。", type: "exclusive"},
                    {name: "温柔的守护者", color: "B", cost: 350, desc: "你擅长照顾他人，在他人的眼中你自带柔光滤镜，容易获得性格敏感者的信任。", type: "exclusive"},
                    {name: "流浪者的背包", color: "C", cost: 180, desc: "你习惯了漂泊，背包里总是能掏出刚好需要的生存工具，野外生存能力大幅提升。", type: "exclusive"}
                ]
            },
            {
                name: "203.好想告诉你",
                desc: "北幌高中的纯爱物语。因为外表阴沉而被叫做''贞子''的黑沼爽子，与爽朗少年风早翔太的故事。这是一个关于误解被解开、心意相通的温柔世界。",
                boss: "荒井一市(阿瓶), 黑沼爽子(觉醒版), 风早翔太",
                identities: [
                    { name: "北幌高中的同班同学", items: "一个写着名字的铅笔盒, 一本借来的漫画书" },
                    { name: "爽子家附近的邻居", items: "一袋自家种的蔬菜, 一把除草用的镰刀" },
