                    { name: "正在备考的高三生", items: "厚厚的一叠试卷, 一瓶提神的咖啡" }
                ],
                talents: [
                    {name: "贞子气场", color: "A", cost: 1200, desc: "你天生自带阴沉恐怖的气场，靠近你的人会感到寒意，周围温度自动下降。可以用来吓退胆小的敌人。", type: "exclusive"},
                    {name: "爽朗之风", color: "S", cost: 1800, desc: "你拥有100%的爽朗度，笑容能净化周围的空气。所到之处，所有人对你的好感度初始值大幅提升。", type: "exclusive"},
                    {name: "纯净之心", color: "SS", cost: 5000, desc: "你拥有一颗纤尘不染的心灵。免疫所有精神类污染和魅惑技能，你的真诚能感化最顽固的敌人。", type: "exclusive"},
                    {name: "传言粉碎机", color: "B", cost: 400, desc: "任何关于你的谣言在面对你的实际行动时都会不攻自破。你拥有极高的信誉度修正能力。", type: "exclusive"},
                    {name: "学霸笔记", color: "C", cost: 180, desc: "你整理的笔记逻辑清晰，重点突出。阅读你的笔记能大幅提升学习效率，甚至能作为教导他人的技能书。", type: "exclusive"},
                    {name: "通灵体质(伪)", color: "B", cost: 300, desc: "虽然你没有灵力，但大家深信你能通灵。利用这种误解，你可以通过装神弄鬼来达成一些目的。", type: "exclusive"},
                    {name: "种花圣手", color: "C", cost: 150, desc: "你种下的植物生长速度加快，且品质极佳。在校园花坛种花能意外地触发隐藏剧情。", type: "exclusive"},
                    {name: "迟钝光环", color: "D", cost: 80, desc: "你对恋爱氛围极其迟钝。这能让你免疫大部分色诱攻击，但也可能让你错过关键的情感攻略路线。", type: "exclusive"},
                    {name: "真诚的眼泪", color: "B", cost: 500, desc: "当你流泪时，周围的人会产生强烈的愧疚感和保护欲。这是一种强力的社交控制手段。", type: "exclusive"},
                    {name: "阿瓶的直觉", color: "A", cost: 850, desc: "像荒井老师一样，虽然看似不靠谱，但在关键时刻拥有野兽般准确的直觉，能避开致命危险。", type: "exclusive"},
                    {name: "无论如何都要传达", color: "S", cost: 1600, desc: "当你想传达心意时，世界会为你助攻。所有阻碍你说话的噪音、意外都会暂时消失，确保你的声音被听到。", type: "exclusive"},
                    {name: "千鹤的义气", color: "B", cost: 600, desc: "你极重情义，为了朋友可以两肋插刀。当你为了保护同伴而战时，痛觉减弱，力量提升。", type: "exclusive"},
                    {name: "绫音的谋略", color: "A", cost: 1100, desc: "你精通人际关系的微妙变化，擅长察言观色和布局。能轻易看穿绿茶手段并进行反击。", type: "exclusive"},
                    {name: "除灵之盐", color: "C", cost: 100, desc: "你随身携带的盐似乎真的有点效果，能驱散微弱的负面状态或带来一点心理安慰。", type: "exclusive"},
                    {name: "命运的红线", color: "SSS", cost: 12000, desc: "你能看到人与人之间连接的红线。你可以尝试切断或连接这些线，从而操纵他人的姻缘与命运。", type: "exclusive"}
                ]
