                    {name: "鲨鱼锯齿", color: "C", cost: 200, desc: "你拥有一口锋利的锯齿牙，这让你看起来有点凶，但很有特色。咬合力惊人，性格往往比较激进。", type: "exclusive"},
                    {name: "肌肉控", color: "B", cost: 300, desc: "你对肌肉有着狂热的迷恋和鉴赏力。一眼就能看出对方的肌肉状态和身体素质，能制定完美的训练计划。", type: "exclusive"},
                    {name: "完美起跳", color: "A", cost: 800, desc: "你的反应神经极快，总能在发令枪响的瞬间做出完美的起跳入水动作，抢占先机。", type: "exclusive"},
                    {name: "理论派泳者", color: "B", cost: 500, desc: "你通过精密的计算和理论来优化泳姿。虽然缺乏一点灵性，但胜在稳定和高效，很少失误。", type: "exclusive"},
                    {name: "接力羁绊", color: "S", cost: 2200, desc: "在混合接力比赛中，如果看到队友游出的''从未见过的景色''，你的全能力值提升50%，爆发力惊人。", type: "exclusive"},
                    {name: "蝶泳专精", color: "A", cost: 1000, desc: "你的肩部力量和柔韧性极佳，专精于蝶泳。在水中如同蝴蝶般起舞，节奏感极强。", type: "exclusive"},
                    {name: "仰泳达人", color: "A", cost: 1000, desc: "你擅长仰泳，能在水中保持完美的流线型。你的爆发力主要集中在腿部和腰部。", type: "exclusive"},
                    {name: "蛙泳高手", color: "A", cost: 1000, desc: "你精通蛙泳技术，虽然速度不是最快，但耐力极好，且动作极其标准，如同教科书一般。", type: "exclusive"},
                    {name: "鲭鱼爱好者", color: "D", cost: 50, desc: "你对鲭鱼有着异常的执着，每顿饭都想吃鲭鱼。这可能导致营养不均衡，但能给你带来心理满足。", type: "exclusive"},
                    {name: "心眼(水下)", color: "B", cost: 600, desc: "即使在浑浊的水中或闭着眼睛，你也能感知到周围的水流变化和对手的位置。", type: "exclusive"},
                    {name: "人鱼线", color: "C", cost: 150, desc: "你拥有完美的人鱼线和腹肌。这不仅增加了魅力值，也代表了你强大的核心力量。", type: "exclusive"},
                    {name: "未来的奥林匹克", color: "SSS", cost: 12000, desc: "你拥有站在世界顶端的潜质。你的成长上限极高，每一次挫折都会让你进化，最终游向世界舞台。", type: "exclusive"},
                    {name: "弟控/兄控", color: "C", cost: 100, desc: "你对兄弟有着强烈的保护欲或依赖感。这成为你前进的动力，但也可能是你的软肋。", type: "exclusive"},
                    {name: "美丽的水", color: "S", cost: 1800, desc: "你的泳姿极具美感，仿佛在水中作画。观众会被你的泳姿吸引而忘记比赛结果，产生强烈的视觉冲击。", type: "exclusive"}
                ]
            },
            {
                name: "208.弦音 -风舞高中弓道部-",
                desc: "以弓道为题材的青春物语。''弦音''是指箭离弦时发出的声音。在寂静的道场中，少年们通过弓道直面自己的内心，寻找属于自己的那一记完美的''弦音''。",
                boss: "二阶堂永亮, 泷川雅贵, 鸣宫凑",
                identities: [
                    { name: "风舞高中的新生", items: "一只普通的护胸, 一双白色的足袋" },
                    { name: "桐先高中的候补队员", items: "一件紫色的弓道服, 一把备用的弓弦" },
                    { name: "夜多之森弓道场的扫地工", items: "一把竹扫帚, 一个装满茶水的保温杯" },
                    { name: "弓具店的学徒", items: "一盒松香, 修理弓具的工具包" },
                    { name: "放弃弓道的前选手", items: "一把落满灰尘的和弓, 满手的茧子" }
                ],
                talents: [
                    {name: "天籁弦音", color: "SS", cost: 7500, desc: "你射出的箭离弦之音清脆悦耳，如同天籁。这声音能穿透人心，驱散迷茫，代表着极其完美的射型。", type: "exclusive"},
                    {name: "早气(心病)", color: "D", cost: 100, desc: "弓道选手的噩梦。你在会未完成瞄准动作前就无法控制地将箭射出。极难克服的心理障碍，命中率大幅下降。", type: "exclusive"},
                    {name: "正射必中", color: "S", cost: 2500, desc: "你深刻理解弓道的真谛。只要你的身姿、心态正确，箭就一定会中靶。这是一种因果律般的命中补正。", type: "exclusive"},
                    {name: "鹰之眼", color: "A", cost: 1200, desc: "你拥有极佳的视力，能清晰地看清28米外的靶心纹路。即使在光线不佳的环境下也能精准瞄准。", type: "exclusive"},
                    {name: "静心明镜", color: "B", cost: 600, desc: "当你站上射位时，能迅速排除一切杂念，进入心如止水的状态。免疫外界的噪音和干扰。", type: "exclusive"},
                    {name: "斜面起弓", color: "B", cost: 500, desc: "你掌握了斜面起弓的流派技巧。动作流畅自然，省力且美观，适合力量稍弱但技巧高超的选手。", type: "exclusive"},
                    {name: "强弓使用者", color: "A", cost: 900, desc: "你拥有强大的臂力和背肌，能拉开张力极大的强弓。箭矢飞行速度快，穿透力强，受风的影响小。", type: "exclusive"},
                    {name: "体配达人", color: "C", cost: 200, desc: "你的行走进退、跪坐起立等基本动作完美无瑕。在礼仪审查中能获得满分，给人以庄重的美感。", type: "exclusive"},
                    {name: "复仇的执念", color: "B", cost: 700, desc: "你为了打败某个人而练习弓道。这种执念让你在面对特定对手时专注度提升，但也容易让你心态失衡。", type: "exclusive"},
                    {name: "优秀的弽", color: "C", cost: 300, desc: "你拥有一只非常贴合你手型的鹿皮手套(弽)。它能保护你的手指，并让放箭更加干脆利落。", type: "exclusive"},
                    {name: "风之读", color: "A", cost: 1100, desc: "你能感知到微风的流动。在室外道场比赛时，你能本能地修正瞄准点，利用风而不是对抗风。", type: "exclusive"},
                    {name: "五重十文字", color: "S", cost: 2000, desc: "你的射型完全符合''五重十文字''的古法标准。这是弓道的理想形态，能最大程度发挥弓的威力。", type: "exclusive"},
                    {name: "共鸣射击", color: "SSS", cost: 10500, desc: "你的射击节奏能带动整个团队。当你是团队核心时，所有队员的命中率和心态都会被你正面影响，全员超常发挥。", type: "exclusive"},
                    {name: "雅先生的指导", color: "A", cost: 1500, desc: "你得到了名师的指点。不仅技术突飞猛进，更能学会如何处理心理问题，将''早气''转化为武器。", type: "exclusive"},
                    {name: "弓神附体", color: "SS", cost: 8000, desc: "在极少数时刻，你仿佛被弓神附体。无论怎么射都能中靶心(皆中)，箭矢仿佛长了眼睛。", type: "exclusive"}
                ]
            },
            {
                name: "209.钻石王牌",
                desc: "青道高中的棒球圣地。为了甲子园的梦想，少年们挥洒汗水与泪水。这里是投手与击球手的战场，每一球都赌上了夏天的荣耀。",
                boss: "成宫鸣, 轰雷市, 泽村荣纯(完全体)",
                identities: [
                    { name: "青道高中的二军成员", items: "一件满是泥土的练习服, 一个磨损的棒球手套" },
                    { name: "棒球部的经理", items: "一本记录分数的记分册, 一箱柠檬蜂蜜渍" },
                    { name: "看台上的吹奏部员", items: "一把小号, 一张应援曲谱" },
                    { name: "不仅名高中的王牌投手", items: "一颗签名的棒球, 一条擦汗的毛巾" },
                    { name: "球探", items: "一个测速枪, 一个记录潜力的平板电脑" }
                ],
                talents: [
                    {name: "七彩变化球", color: "SS", cost: 9000, desc: "你的手指极其灵活，能投出多种变化球。卡特、变速、曲球信手拈来，让击球手眼花缭乱，无法捉摸。", type: "exclusive"},
                    {name: "怪癖球质", color: "S", cost: 2800, desc: "你投出的直球在进入本垒板时会发生不规则的位移。虽然球速可能不快，但极难被打出安打。", type: "exclusive"},
                    {name: "轰雷般的挥棒", color: "S", cost: 3000, desc: "你的挥棒速度和力量惊人，挥棒时伴随着破风声。只要击中球心，基本就是本垒打。简直是人型大炮。", type: "exclusive"},
                    {name: "精密控球", color: "A", cost: 1500, desc: "你能将球精准地投进好球带的九宫格角落。虽然球威一般，但能通过压线球玩弄击球手的心态。", type: "exclusive"},
                    {name: "捕手的头脑", color: "A", cost: 1800, desc: "你拥有战术大师般的头脑。能记住对手的击球习惯，通过配球引导击球手挥棒落空，掌控全场节奏。", type: "exclusive"},
                    {name: "不动的一棒", color: "B", cost: 800, desc: "作为开路先锋，你拥有极高的上垒率。选球眼光毒辣，脚程快，一旦上垒就能扰乱投手的节奏。", type: "exclusive"},
                    {name: "恶魔安打", color: "B", cost: 700, desc: "你擅长将坏球破坏成界外球，不断消耗投手的球数和体力，直到等到好打的球为止。极其难缠。", type: "exclusive"},
                    {name: "强肩豪打", color: "B", cost: 900, desc: "你的肩膀力量极强，外野回传球如激光般精准快速，能直接刺杀本垒。打击力量同样不可小觑。", type: "exclusive"},
                    {name: "王牌的责任感", color: "A", cost: 1200, desc: "背负王牌背号时，你的心态会变得无比坚韧。危机局面下能力值上升，绝不轻易让出投手丘。", type: "exclusive"},
                    {name: "魔球(卡特球·改)", color: "S", cost: 2500, desc: "你练就了一种独特的魔球，在击球手挥棒的瞬间急剧向内角钻入，极易折断球棒或造成内野滚地。", type: "exclusive"},
                    {name: "大嗓门应援", color: "C", cost: 100, desc: "你在场上的吼声极大，能有效提振己方士气，干扰对手心态。虽然有点吵，但是个好气氛组。", type: "exclusive"},
                    {name: "触击大师", color: "C", cost: 300, desc: "你无论面对多快的球都能稳稳地摆出短棒，将球触击到防守死角。是战术执行的关键人物。", type: "exclusive"},
                    {name: "甲子园之子", color: "SSS", cost: 15000, desc: "你是为了大场面而生的。在甲子园这种顶级赛场上，你的所有属性提升200%，仿佛有棒球之神眷顾。", type: "exclusive"},
                    {name: "落合教练的指导", color: "B", cost: 600, desc: "你学会了从职业选手的角度思考问题。虽然看起来冷酷功利，但能最快地提升技术和胜率。", type: "exclusive"},
                    {name: "二游间铁壁", color: "A", cost: 1400, desc: "你与搭档组成的二游防线坚不可摧。无论是多么刁钻的滚地球，你们都能通过默契配合完成双杀。", type: "exclusive"}
                ]
            },
            {
                name: "210.飙速宅男",
                desc: "千叶县总北高中的自行车竞技部。为了连接那件黄色的队服，宅男小野田坂道踏上了公路赛的赛道。这是关于踏频、爬坡、冲刺与男人间约定的热血故事。",
                boss: "御堂筋翔, 卷岛裕介, 真波山岳",
                identities: [
                    { name: "总北高中的一年级部员", items: "一辆妈妈淑女车(改装), 一件秋叶原限定T恤" },
                    { name: "箱根学园的后援会成员", items: "一面巨大的应援旗, 一个扩音喇叭" },
                    { name: "京都伏见的普通队员", items: "一辆标准公路车, 剃光的平头" },
                    { name: "自行车店老板", items: "一套维修工具, 几条备用内胎" },
                    { name: "公路赛的狂热观众", items: "一瓶运动饮料, 一个写着''加油''的扇子" }
                ],
                talents: [
                    {name: "高回转踏频", color: "SS", cost: 8000, desc: "你的双腿如同电动马达。能轻松维持极高的踏频，即使在陡峭的山坡上也能笑着加速，且膝盖负荷极小。", type: "exclusive"},
                    {name: "御堂筋的执念", color: "S", cost: 3000, desc: "为了胜利可以抛弃一切，包括尊严和肉体。你的身体可以扭曲成诡异的姿态以减少风阻，爆发力极强。", type: "exclusive"},
                    {name: "风之翼(天使)", color: "S", cost: 2800, desc: "你擅长利用风向。在顺风时仿佛长出了翅膀，能感知风的流动来节省体力或进行突围。爬坡如飞。", type: "exclusive"},
                    {name: "肉弹战车", color: "A", cost: 1500, desc: "你拥有庞大的体型和肌肉量。在平路冲刺时如同坦克般不可阻挡，能轻易撞开试图卡位的对手。", type: "exclusive"},
                    {name: "山神(蜘蛛)", color: "A", cost: 1800, desc: "你擅长大幅度摇车的爬坡方式，如同蜘蛛般在坡道上起舞。这种独特的节奏让对手难以跟随。", type: "exclusive"},
                    {name: "公主姬的歌声", color: "B", cost: 600, desc: "当你唱起《Love Hime》的主题曲时，踏频自动提升30，精神亢奋，疲劳感暂时消失。宅男的力量！", type: "exclusive"},
                    {name: "野兽嗅觉", color: "B", cost: 500, desc: "你能凭直觉判断出终点线的位置和最佳的冲刺时机。如同野兽捕猎般精准。", type: "exclusive"},
                    {name: "无声骑行", color: "A", cost: 1200, desc: "你的骑行姿态完美，没有多余的动作。能悄无声息地跟在对手身后，在对方松懈的瞬间发动突袭。", type: "exclusive"},
                    {name: "团队的支柱", color: "B", cost: 800, desc: "作为副将或队长，你拥有极强的统率力。能合理分配队伍体力，制定战术，并在关键时刻拉回掉队的队友。", type: "exclusive"},
                    {name: "直线鬼", color: "A", cost: 1600, desc: "你是为了直线冲刺而生的怪物。一旦看到终点线，身体就会解除限制，爆发出超越人类极限的速度。", type: "exclusive"},
                    {name: "人体气动学", color: "C", cost: 300, desc: "你懂得如何调整姿势来最小化风阻。虽然姿势可能有点丑，但在这个速度至上的世界里非常实用。", type: "exclusive"},
                    {name: "补给达人", color: "C", cost: 150, desc: "你擅长在高速骑行中进行补给，能快速吃下能量棒或喝水，确保体力条永不归零。", type: "exclusive"},
                    {name: "最后的三公里", color: "SSS", cost: 11000, desc: "在比赛的最后阶段，你的所有属性翻倍。无论之前多么疲惫，此刻你就是赛道上最速的存在。", type: "exclusive"},
                    {name: "名为自行车的翅膀", color: "SS", cost: 7000, desc: "当你骑上自行车时，你感到真正的自由。这种精神共鸣让你的车仿佛有了生命，机械故障率降为0。", type: "exclusive"},
                    {name: "肌肉弹丸", color: "B", cost: 400, desc: "你可以将全身肌肉压缩像弹簧一样，在瞬间释放出巨大的爆发力，用于起步或摆脱纠缠。", type: "exclusive"}
                ]
            },
            {
                name: "200.NANA",
                desc: "东京的繁华与寂寞，摇滚乐与烟草味。两个名字都叫NANA的女孩，在梦想与现实的洪流中挣扎。",
                boss: "巧(Takumi), 狗仔队, 命运的捉弄",
                identities: [
                    { name: "上京追梦的乡下少女", items: "一张单程车票, 存折里的少量现金" },
                    { name: "BLAST乐队的临时工", items: "搬运音响的推车, 乐队应援毛巾" },
                    { name: "TRAPNEST的狂热粉", items: "偷拍的照片, 荧光棒" },
                    { name: "707室的房东", items: "一串钥匙, 催租单" },
                    { name: "Jackson汉堡店店员", items: "油腻的围裙, 汉堡优惠券" }
                ],
                talents: [
                    {name: "莲花纹身", color: "C", cost: 250, desc: "手臂上的莲花纹身。象征着对某人的执念。魅力+10，对摇滚乐手有好感加成。", type: "exclusive"},
                    {name: "绝世歌喉(娜娜)", color: "S", cost: 2200, desc: "拥有穿透灵魂的嗓音。你的歌声能引发听众的共鸣，甚至引发群体狂热（Buff/Debuff）。", type: "exclusive"},
                    {name: "贝斯演奏(莲)", color: "A", cost: 1200, desc: "顶级的贝斯技巧。你的演奏能控制心跳的节奏，甚至用低频声波震碎玻璃。", type: "exclusive"},
                    {name: "烟瘾(Black Stones)", color: "E", cost: 50, desc: "你离不开烟。抽烟时冷静度+20%，但不抽烟时会焦躁不安，全属性下降。", type: "exclusive"},
                    {name: "草莓杯子", color: "D", cost: 80, desc: "一对可爱的草莓杯子。摆在家里能增加居住者的羁绊值，防止背叛。", type: "exclusive"},
                    {name: "巧的控制欲", color: "A", cost: 1500, desc: "你拥有极强的掌控局面的能力。能冷静地利用任何人达成目的，虽然会被人讨厌，但效率极高。", type: "exclusive"},
                    {name: "奈奈的妄想", color: "C", cost: 150, desc: "你经常陷入恋爱妄想。虽然容易被骗，但这种乐观精神让你对精神攻击有很高的抗性。", type: "exclusive"},
                    {name: "朋克精神", color: "B", cost: 500, desc: "叛逆的灵魂。对精神控制、洗脑等负面状态有50%的豁免率。越是逆境，斗志越高。", type: "exclusive"},
                    {name: "狗仔队的嗅觉", color: "B", cost: 400, desc: "你擅长挖掘秘密。在这个世界能挖到明星绯闻，在其他世界能挖到敌人的弱点情报。", type: "exclusive"},
                    {name: "破碎的红线", color: "S", cost: 1800, desc: "一种诅咒也是武器。你能斩断两人之间的因果（缘分），让亲密战友反目成仇。", type: "exclusive"},
                    {name: "南京锁", color: "C", cost: 200, desc: "佩戴在脖子上的锁。防御力微量提升，象征着束缚与归属。", type: "exclusive"},
                    {name: "雪地里的等待", color: "D", cost: 100, desc: "你在寒冷环境下的耐受力提升。擅长伏击和守株待兔。", type: "exclusive"},
