    {
        name: "220.饥饿游戏",
        desc: "施惠国建立在废墟之上，为了惩罚叛乱，每年都要举办饥饿游戏。24名贡品互相厮杀，只有一人能存活。这是一个娱乐至死的残酷世界。",
        boss: "斯诺总统, 游戏设计师, 职业贡品小队, 变种狼人",
        identities: [
            { name: "第12区的挖煤矿工", items: "一把煤铲, 满肺的煤灰" },
            { name: "第11区的果园采摘工", items: "一个篮子, 极度营养不良" },
            { name: "都城的底层造型师助理", items: "一盒化妆粉, 浮夸的衣服" },
            { name: "竞技场里的无名贡品", items: "一身训练服, 站在起跑点上" },
            { name: "第13区的地下难民", items: "统一的灰色连体衣, 严格的配给卡" }
        ],
        talents: [
            {name: "嘲笑鸟象征", color: "SSS", cost: 28000, desc: "你成为了反叛精神的图腾。你的存在能点燃所有区域的怒火，推翻施惠国的统治。", type: "exclusive"},
            {name: "凯特尼斯的箭术", color: "S", cost: 2600, desc: "百发百中的神射手，无论是狩猎还是杀人。在森林地形中战斗力翻倍。", type: "exclusive"},
            {name: "职业贡品训练", color: "A", cost: 1500, desc: "从小接受杀人训练，精通各种冷兵器，体格强壮，毫无道德负担。", type: "exclusive"},
            {name: "比塔的伪装术", color: "B", cost: 600, desc: "你可以利用泥巴、颜料将自己完美融入环境，哪怕敌人从身边走过也发现不了。", type: "exclusive"},
            {name: "赞助人的礼物", color: "S", cost: 2200, desc: "你拥有极高的人气，在危急时刻，总会有昂贵的空投物资（药、武器、食物）送到你面前。", type: "exclusive"},
            {name: "第13区军事战术", color: "A", cost: 1200, desc: "接受过严格的军事化管理和战术训练，擅长爆破、黑客和特种作战。", type: "exclusive"},
            {name: "致命草药学", color: "B", cost: 500, desc: "你知道如何利用竞技场中的植物制造致命毒药，或者识别出像夜锁那样的剧毒浆果。", type: "exclusive"},
            {name: "芬尼克的三叉戟", color: "A", cost: 900, desc: "精通三叉戟的使用，同时也擅长编织渔网陷阱，水战能力极强。", type: "exclusive"},
            {name: "力场护盾手环", color: "S", cost: 2500, desc: "都城的高科技产物，可以抵挡数次致命攻击，是保命的神器。", type: "exclusive"},
            {name: "乔安娜的狂怒", color: "B", cost: 700, desc: "擅长使用斧头，性格疯狂，越是受伤战斗力越强，且擅长脱衣战术迷惑敌人。", type: "exclusive"},
            {name: "科技猎狗控制", color: "A", cost: 1800, desc: "你可以干扰或控制竞技场最后投放的变种生物，让它们转而攻击其他贡品。", type: "exclusive"},
            {name: "听觉敏锐", color: "C", cost: 200, desc: "鲁的技能，能听到极其细微的声音，并能通过模仿鸟叫传递暗号。", type: "exclusive"},
            {name: "面包师的力量", color: "C", cost: 300, desc: "常年揉面带来的惊人臂力，虽然看起来笨重，但在近身肉搏中不容小觑。", type: "exclusive"},
            {name: "爱情戏码", color: "C", cost: 150, desc: "擅长在镜头前表演悲剧爱情，能博取观众同情，增加获得赞助的几率。", type: "exclusive"},
            {name: "暴雨求生", color: "D", cost: 100, desc: "在恶劣天气下生存能力提升，体温流失速度减慢。", type: "exclusive"}
        ]
    },
                      {
                name: "221.移动迷宫",
                desc: "一个被巨大石墙包围的林间空地，每晚迷宫都会改变结构。WCKD组织为了应对耀斑病毒，将免疫的青少年投入此处进行残酷的实验。",
                boss: "艾娃·佩吉, 鬼火兽, 詹森",
                identities: [
                    { name: "刚上送得箱的新人(Greenie)", items: "失忆的大脑, 一套粗布衣物" },
                    { name: "在迷宫里迷路的行者", items: "断裂的跑鞋, 记录了一半的迷宫地图" },
                    { name: "WCKD实验室的底层清洁工", items: "一张低级门禁卡, 沾满血迹的拖把" },
                    { name: "焦土带的狂人(感染初期)", items: "一把生锈的砍刀, 抑制狂躁的药片(仅剩两粒)" },
                    { name: "右臂组织的哨兵", items: "一把老式狙击步枪, 破损的无线电" }
                ],
                talents: [
                    {name: "耀斑病毒(潜伏)", color: "E", cost: 50, desc: "你已经感染了致命的耀斑病毒。虽然暂时没有发作，但理智会随着时间慢慢丧失，最终变成嗜血的狂人。", type: "exclusive"},
                    {name: "断腿", color: "D", cost: 100, desc: "你的腿骨曾经断裂且愈合不良。移动速度永久降低30%，在迷宫中这基本等于死刑。", type: "exclusive"},
                    {name: "种植能手", color: "C", cost: 120, desc: "你在林间空地负责农作物。能分辨哪些植物能吃，哪些有毒，保证自己不会饿死。", type: "exclusive"},
                    {name: "建筑师思维", color: "C", cost: 150, desc: "你擅长搭建简易避难所，并能快速利用周围环境制作路障。", type: "exclusive"},
                    {name: "行者体能", color: "B", cost: 400, desc: "你拥有惊人的耐力和爆发力，能够连续奔跑一整天而不力竭，是探索迷宫的基础。", type: "exclusive"},
                    {name: "过目不忘(地图)", color: "B", cost: 500, desc: "你只要看一眼迷宫的结构，就能在脑海中构建出3D模型，并且不会忘记路线。", type: "exclusive"},
                    {name: "鬼火兽血清", color: "B", cost: 600, desc: "你注射过解药，对鬼火兽的蛰刺毒素有一定抗性，被刺后存活率提升50%。", type: "exclusive"},
                    {name: "机械黑客", color: "A", cost: 800, desc: "你能破解WCKD的低级电子锁和生物机械技术，甚至能短暂干扰鬼火兽的行动。", type: "exclusive"},
                    {name: "心灵感应(伪)", color: "A", cost: 900, desc: "你和某个特定的同伴拥有心灵连接，可以在一定范围内无声交流，共享视野。", type: "exclusive"},
                    {name: "免疫者体质", color: "S", cost: 1500, desc: "你的血液中含有能够抵抗耀斑病毒的酶。在这个世界，你是行走的解药，也是各方势力争夺的对象。", type: "exclusive"},
                    {name: "WCKD高级权限", color: "S", cost: 1800, desc: "你拥有WCKD的高级生物识别码，可以控制迷宫的墙体开合，甚至调动实验室资源。", type: "exclusive"},
                    {name: "鬼火兽控制芯片", color: "S", cost: 2000, desc: "你手里有一个从鬼火兽体内挖出的控制单元，能让你操纵一只鬼火兽为你战斗。", type: "exclusive"},
                    {name: "预知梦(实验体)", color: "SS", cost: 5000, desc: "作为特殊实验体，你能在梦中看到未来的片段。这能让你规避必死的陷阱，但会消耗大量精神力。", type: "exclusive"},
                    {name: "生物机械改造", color: "SS", cost: 6000, desc: "你的身体经过WCKD的深度改造，拥有金属骨骼和内置武器，力量和防御力远超人类。", type: "exclusive"},
                    {name: "迷宫主宰", color: "SSS", cost: 12000, desc: "你彻底理解了迷宫的算法本质。你可以随意重组迷宫结构，甚至将迷宫具象化作为武器攻击敌人。", type: "exclusive"}
                ]
            },
            {
                name: "222.暮光之城",
                desc: "阴雨连绵的福克斯小镇，隐藏着吸血鬼与狼人的古老契约。永生的诱惑与血液的渴望交织，跨越种族的禁忌之恋背后是沃尔图里家族的审判。",
                boss: "阿罗, 凯厄斯, 马库斯, 维多利亚",
                identities: [
                    { name: "福克斯高中的转校生", items: "一辆经常熄火的皮卡, 一本生物课本" },
                    { name: "奎鲁特保留地的原住民", items: "图腾挂饰, 可以在森林里快速穿行的靴子" },
                    { name: "沃尔图里家族的血袋", items: "苍白的脸色, 脖子上明显的针孔" },
                    { name: "西雅图的流浪吸血鬼", items: "沾满干涸血迹的夹克, 一双红色的隐形眼镜" },
                    { name: "拉普什海滩的冲浪者", items: "冲浪板, 并不知情的狼人远亲血统" }
                ],
                talents: [
                    {name: "鲜血渴望(诅咒)", color: "E", cost: 100, desc: "你对血液有着无法抑制的渴望，但身体却无法消化血液。每次吸血都会导致剧烈的呕吐和虚弱。", type: "exclusive"},
                    {name: "阳光过敏", color: "D", cost: 150, desc: "虽然不会像传统吸血鬼那样灰飞烟灭，但你在阳光下会感到全身灼烧般的疼痛，全属性下降50%。", type: "exclusive"},
                    {name: "冰冷肌肤", color: "C", cost: 180, desc: "你的体温极低，皮肤像大理石一样坚硬冰冷。防御力微量提升，但容易被人类察觉异常。", type: "exclusive"},
                    {name: "动物亲和", color: "C", cost: 200, desc: "森林里的动物不会畏惧你，这让你更容易进行狩猎（无论是作为素食吸血鬼还是人类）。", type: "exclusive"},
                    {name: "狼人体质(未觉醒)", color: "B", cost: 500, desc: "你的体温偏高，愈合速度快，拥有变身的潜质。目前只能表现为力气比常人大一些。", type: "exclusive"},
                    {name: "魅惑气息", color: "B", cost: 600, desc: "你身上散发着一种让异性（无论是人类还是吸血鬼）着迷的信息素，容易获得他人的好感。", type: "exclusive"},
                    {name: "追踪者", color: "B", cost: 700, desc: "像詹姆斯一样，一旦你锁定了猎物，就能感知到对方的大致方位，不死不休。", type: "exclusive"},
                    {name: "情绪控制", color: "A", cost: 1000, desc: "类似贾斯帕的能力，你可以感知并微调周围人的情绪，平复冲突或煽动暴怒。", type: "exclusive"},
                    {name: "预知未来(碎片)", color: "A", cost: 1500, desc: "类似爱丽丝的能力，但只能看到极其短暂且模糊的未来碎片，且容易因决策改变而失效。", type: "exclusive"},
                    {name: "痛苦幻觉", color: "S", cost: 1800, desc: "类似简的能力，只需注视目标，就能让对方的大脑产生全身骨骼碎裂般的剧痛，无视防御。", type: "exclusive"},
                    {name: "感官剥夺", color: "S", cost: 2000, desc: "类似亚历克的能力，可以切断目标的视觉、听觉和触觉，使其陷入彻底的黑暗与麻木。", type: "exclusive"},
                    {name: "读心术", color: "S", cost: 2200, desc: "类似爱德华的能力，可以听到周围人心里的声音。强度取决于精神力，对意志坚定者效果减弱。", type: "exclusive"},
                    {name: "狼人变身(阿尔法血统)", color: "SS", cost: 5000, desc: "作为狼人首领的血脉，你变身后的体型更巨大，可以命令其他狼人，且能强制压制吸血鬼。", type: "exclusive"},
                    {name: "精神护盾", color: "SS", cost: 6000, desc: "类似贝拉的能力，你拥有绝对的精神防御，任何直接作用于精神的超能力（读心、痛苦等）对你无效，且可扩展保护他人。", type: "exclusive"},
                    {name: "半吸血鬼混血儿", color: "SSS", cost: 15000, desc: "类似蕾妮斯梅的存在。你拥有吸血鬼的永生和坚硬皮肤，却保有心跳和人类的成长性。你可以通过触摸让人看到你的记忆，且打破了种族界限。", type: "exclusive"}
                ]
            },
            {
                name: "223.神秘博士",
                desc: "时间与空间的无限冒险。蓝色的警亭TARDIS穿梭于宇宙，时间领主与Dalek、赛博人的战争从未停歇。只要听到那嗡嗡的声音，你就知道博士来了。",
                boss: "戴立克皇, 赛博统领, 哭泣天使, 掌权者(Master)",
                identities: [
                    { name: "21世纪伦敦的普通店员", items: "一部诺基亚手机, 刚好路过爆炸现场的倒霉体质" },
                    { name: "UNIT的底层士兵", items: "红色的贝雷帽, 一把对付外星人毫无用处的步枪" },
                    { name: "火炬木小组的茶水员", items: "记忆消除药丸(过期的), 沾满咖啡渍的文件" },
                    { name: "被困在过去的时间旅行者", items: "坏掉的时间手镯, 一本写满未来彩票号码的笔记" },
                    { name: "赛博工厂的待改造人类", items: "编号手环, 耳边不断响起的“升级”指令" },
                ],
                talents: [
                    {name: "时间感知障碍", color: "E", cost: 50, desc: "你无法正确感知时间的流逝，经常分不清过去、现在和未来，容易在时间旅行中彻底疯掉。", type: "exclusive"},
                    {name: "甚至没有名字", color: "D", cost: 100, desc: "你的存在感极低，就像博士的某些路人甲同伴，死了连历史都不会记得。", type: "exclusive"},
                    {name: "万能如意卡(假)", color: "C", cost: 150, desc: "一张空白的卡片，你试图模仿博士的精神纸，但只能骗骗智商极低的生物。", type: "exclusive"},
                    {name: "音速起子(损坏)", color: "C", cost: 200, desc: "只能用来拧螺丝或者偶尔让灯泡闪烁一下，关键时刻绝对掉链子。", type: "exclusive"},
                    {name: "历史知识库", color: "B", cost: 400, desc: "你熟知地球的历史节点，知道哪些人不能杀，哪些事件不能改，避免造成时间悖论。", type: "exclusive"},
                    {name: "同伴体质", color: "B", cost: 600, desc: "你拥有吸引博士注意的特质，运气极好，总能在必死局面中等到TARDIS的救援。", type: "exclusive"},
                    {name: "赛博人改造部件", color: "A", cost: 800, desc: "你的部分身体被赛博化，拥有金属外壳和电击握力，但失去了部分情感。", type: "exclusive"},
                    {name: "哭泣天使的诅咒", color: "A", cost: 900, desc: "你的体内封印着一只哭泣天使的影像。你可以短暂借用它的速度，但必须时刻盯着镜子里的自己。", type: "exclusive"},
                    {name: "涡流操作员", color: "S", cost: 1500, desc: "你拥有操作TARDIS的天赋，虽然不能像博士那样精通，但至少能把飞船开到正确的星球。", type: "exclusive"},
                    {name: "戴立克护盾", color: "S", cost: 1800, desc: "你装备了戴立克的单兵能量护盾，能融化子弹并抵挡绝大多数能量武器的攻击。", type: "exclusive"},
                    {name: "固定时间点", color: "SS", cost: 4000, desc: "你的存在成为了历史的一个固定点（如杰克上校）。你无法真正死亡，每次死后都会复活，直到宇宙尽头。", type: "exclusive"},
                    {name: "变色龙拱门", color: "SS", cost: 5000, desc: "你可以重写自己的生物结构，将自己伪装成任何物种（包括人类），连DNA扫描都无法识破。", type: "exclusive"},
                    {name: "时间领主再生", color: "SSS", cost: 20000, desc: "拥有12次重生的机会。濒死时全身细胞重组，改变外貌和性格，满血复活。你是最后的加里弗雷人。", type: "exclusive"},
                    {name: "TARDIS之心", color: "SSS", cost: 25000, desc: "你直视了时间漩涡。你拥有操纵时间、空间和物质的神级能力，但这会迅速烧毁你的肉体。", type: "exclusive"},
                    {name: "现实炸弹", color: "SSS", cost: 30000, desc: "达沃斯的终极武器设计图。能够解除原子间的结合力，从根本上抹除现实。只有疯子才会使用它。", type: "exclusive"}
                ]
            },
            {
                name: "224.神探夏洛克",
                desc: "现代伦敦，贝克街221B。这不仅是智商的角斗场，更是犯罪与正义的灰色地带。咨询侦探与犯罪界的拿破仑在阴影中博弈。",
                boss: "吉姆·莫里亚蒂, 夏尔·奥古斯都·马格努森, 欧洛丝·福尔摩斯",
                identities: [
                    { name: "苏格兰场的实习警员", items: "警官证, 永远跟不上节奏的笔记本" },
                    { name: "贝克街流浪汉小分队成员", items: "破烂的大衣, 几个便士" },
                    { name: "巴茨医院的验尸官助手", items: "解剖刀, 装着不明切片的培养皿" },
                    { name: "莫里亚蒂网络的外围跑腿", items: "一部只能接听的黑莓手机, 一个装着定时炸弹的包裹" },
                    { name: "受害者的家属", items: "一张寻人启事, 绝望的眼泪" }
                ],
                talents: [
                    {name: "平庸之智(诅咒)", color: "E", cost: 50, desc: "你是那条金鱼。在这个天才遍地的世界，你的智商只能让你成为被操纵的棋子，死都不知道怎么死的。", type: "exclusive"},
                    {name: "盲目崇拜", color: "D", cost: 100, desc: "你是福尔摩斯的脑残粉，容易被他的言论误导，或者为了模仿他而陷入危险。", type: "exclusive"},
                    {name: "伦敦活地图", color: "C", cost: 150, desc: "你是出租车司机级别的认路高手，知道伦敦每一条小巷和监控死角。", type: "exclusive"},
                    {name: "法医鉴识", color: "C", cost: 200, desc: "擅长从尸体上获取信息，死亡时间、死因、凶器类型，尸体对你来说就是一本书。", type: "exclusive"},
                    {name: "军医背景", color: "B", cost: 500, desc: "像华生一样，你拥有战场急救经验和不错的手枪射击能力，心理素质过硬。", type: "exclusive"},
                    {name: "黑客技术", color: "B", cost: 600, desc: "能够入侵伦敦的监控系统和一般的政府数据库，获取情报。", type: "exclusive"},
                    {name: "演技派", color: "B", cost: 700, desc: "你可以完美地扮演各种社会角色，从流浪汉到贵族，骗过大多数人的眼睛。", type: "exclusive"},
