                    {name: "水分流失", color: "E", cost: 50, desc: "你的身体锁不住水分。在沙漠星球，这意味着你必须喝双倍的水，或者死得比谁都快。", type: "exclusive"},
                    {name: "香料成瘾", color: "D", cost: 150, desc: "长期接触香料导致成瘾。虽然眼睛变蓝了，但一旦断供，你会极其痛苦地死去。", type: "exclusive"},
                    {name: "沙行步", color: "C", cost: 200, desc: "模仿沙漠生物的无规律行走方式，避免引起沙虫的震动感知。", type: "exclusive"},
                    {name: "晶牙匕首格斗", color: "C", cost: 250, desc: "弗雷曼人的格斗术。使用沙虫牙齿制成的匕首，招招致命，不留后路。", type: "exclusive"},
                    {name: "屏蔽场格斗", color: "B", cost: 600, desc: "适应个人护盾的特殊格斗术。懂得“慢剑杀人”，只有缓慢的攻击才能穿透护盾。", type: "exclusive"},
                    {name: "门泰特计算", color: "B", cost: 800, desc: "你受过人脑计算机的训练。拥有超强的数据分析和逻辑推演能力，能辅助战略决策。", type: "exclusive"},
                    {name: "真言师(音言)", color: "A", cost: 1200, desc: "通过调整声音的音调和频率，你可以强迫听到的人无条件服从你的命令。", type: "exclusive"},
                    {name: "甚至更强的代谢", color: "A", cost: 1500, desc: "你的身体能分解几乎所有毒药。在这个充满暗杀的世界，这是最好的保命符。", type: "exclusive"},
                    {name: "香料预知(初级)", color: "S", cost: 3000, desc: "大量摄入香料后，你能看到模糊的未来路径，在星际航行中找到安全的路线。", type: "exclusive"},
                    {name: "姐妹会格斗术", color: "S", cost: 3500, desc: "贝尼·杰瑟里特的秘传武术。能控制每一块肌肉，瞬间爆发极高速度，甚至转换体内毒素。", type: "exclusive"},
                    {name: "沙虫骑士", color: "SS", cost: 6000, desc: "你拥有召唤和骑乘巨大沙虫的能力。在沙漠中，你拥有一支无敌的重装甲部队。", type: "exclusive"},
                    {name: "基因记忆", color: "SS", cost: 7000, desc: "你可以访问祖先的记忆。千万年来无数人的智慧和经验都为你所用。", type: "exclusive"},
                    {name: "魁萨茨·哈德拉克", color: "SSS", cost: 30000, desc: "你是跨越时空的超级存在。同时存在于过去、现在和未来。你能看见无数条时间线，并选择唯一的那条。", type: "exclusive"},
                    {name: "神帝形态", color: "SSS", cost: 35000, desc: "你与沙虫幼体共生，在这个过程中获得了几千年的寿命、坚不可摧的皮肤和超越人类的力量。", type: "exclusive"},
                    {name: "原子武器库", color: "SSS", cost: 40000, desc: "你掌握了家族的原子弹库存。虽然公约禁止使用，但这威慑力足以让你成为星球霸主。", type: "exclusive"}
                ]
            },
            {
                name: "230.疯狂的麦克斯",
                desc: "核战后的废土，水和燃油比生命更珍贵。军阀割据，改装车在荒漠上狂飙。这是一个崇尚V8引擎、暴力美学和铬色喷漆的疯狂世界。",
                boss: "不死老乔, 狄门特斯, 子弹农场主, 食人者",
                identities: [
                    { name: "堡垒的战争男孩(War Boy)", items: "铬色喷漆, 爆炸长矛" },
                    { name: "种母(Breeder)", items: "白色的纱裙, 贞操带" },
                    { name: "汽油镇的奴隶", items: "沉重的铁链, 一桶原油" },
                    { name: "荒原上的拾荒者", items: "双管猎枪(没子弹), 蜥蜴干" },
                    { name: "秃鹫帮的驾驶员", items: "满是尖刺的改装车, 俄语纹身" }
                ],
                talents: [
                    {name: "辐射病", color: "E", cost: 50, desc: "你的身上长满了肿瘤，寿命减半。在这个废土世界，这是常态，但依然致命。", type: "exclusive"},
                    {name: "O型血包", color: "D", cost: 100, desc: "你是万能供血者。你会像麦克斯一样被挂在车头，给生病的战争男孩输血。", type: "exclusive"},
                    {name: "机械修理(废土)", color: "C", cost: 200, desc: "你能用废铁、胶带和口水修好任何发动机。在车坏了就等于死的世界，这是神技。", type: "exclusive"},
                    {name: "驾驶专精", color: "C", cost: 250, desc: "无论是重型卡车还是摩托，你都能驾驭。懂得如何在沙暴中保持方向。", type: "exclusive"},
                    {name: "狂暴之路", color: "B", cost: 600, desc: "在载具追逐战中，你的肾上腺素飙升，反应速度提升50%，且感觉不到疼痛。", type: "exclusive"},
                    {name: "爆炸长矛投掷", color: "B", cost: 700, desc: "战争男孩的绝技。你能精准地将爆炸长矛投掷到敌车的油箱或驾驶室，见证烟花。", type: "exclusive"},
                    {name: "狙击手(福瑞奥莎)", color: "A", cost: 1000, desc: "哪怕只有一只手，哪怕没有瞄准镜，你也能在高速移动的车上击毙远处的驾驶员。", type: "exclusive"},
                    {name: "废土战神", color: "A", cost: 1200, desc: "类似麦克斯。极强的格斗能力和生存直觉。只要有一口气在，就能反杀。", type: "exclusive"},
                    {name: "V8引擎崇拜", color: "S", cost: 2000, desc: "当你驾驶V8引擎车辆时，仿佛有神灵庇佑。车辆性能提升100%，且几乎不会故障。", type: "exclusive"},
                    {name: "英灵殿的召唤", color: "S", cost: 2500, desc: "主动技能。喷上铬色喷漆，大喊“见证我”！接下来的一击威力提升500%，但大概率会同归于尽。", type: "exclusive"},
                    {name: "堡垒之主", color: "SS", cost: 5000, desc: "类似不死老乔。你掌握着地下水源和农作物。你控制着资源的命脉，被废土人视为神明。", type: "exclusive"},
                    {name: "战争钻井车", color: "SS", cost: 6000, desc: "你拥有一辆武装到牙齿的重型战争卡车。它是移动的堡垒，足以碾碎任何拦路的小车。", type: "exclusive"},
                    {name: "绿色之地坐标", color: "SSS", cost: 15000, desc: "你脑中有未被污染的“绿色之地”的确切位置。这是废土上唯一的希望，也是最大的宝藏。", type: "exclusive"},
                    {name: "废土救世主", color: "SSS", cost: 20000, desc: "你拥有净化水源和土壤的能力。你走到哪里，哪里就会长出植物。你将终结这个疯狂的时代。", type: "exclusive"},
                    {name: "金属风暴", color: "SSS", cost: 25000, desc: "你可以控制金属。在废土上，这意味着你可以瞬间拆解敌人的车辆，或者用废铁构筑钢铁长城。", type: "exclusive"}
                ]
            },
                      {
                name: "231.王牌特工 (Kingsman)",
                desc: "一个隐藏在裁缝店背后的绅士特工世界。‘礼仪成就不凡之人’是这里的信条，高科技间谍装备与英式优雅并存，但疯狂的反派总试图用某种信号毁灭全人类。",
                boss: "里奇蒙·瓦伦丁, 波比·亚当斯, 查理·赫斯基",
                identities: [
