                boss: "殷寿(纣王), 妲己(九尾狐), 申公豹",
                identities: [
                    { name: "冀州城下的奴隶苦工", items: "沉重的石头, 监工的鞭痕" },
                    { name: "朝歌城的祭祀牺牲品", items: "被捆绑的绳索, 绝望的眼神" },
                    { name: "质子旅的马夫", items: "马鞭, 一身马粪味" },
                    { name: "摘星楼的修建工匠", items: "一把锤子, 随时会被推下去的高度" },
                    { name: "被妲己吸食魂魄的宫女", items: "干枯的身体, 散落的首饰" }
                ],
                talents: [
                    {name: "质子旅战阵", color: "B", cost: 600, desc: "你受过严格的骑射训练。与同伴在一起时，士气高涨，骑术和箭术大幅提升。", type: "exclusive"},
                    {name: "九尾狐妖力", color: "SS", cost: 7500, desc: "你被九尾狐附身或赐予力量。拥有不死之身，极强的自愈能力，以及魅惑人心的妖术。", type: "exclusive"},
                    {name: "殷寿的野心(PUA大师)", color: "S", cost: 2000, desc: "你拥有极强的煽动性语言能力。能让你的部下视你为父亲，心甘情愿为你去死，为你弑父。", type: "exclusive"},
                    {name: "封神榜(未解封)", color: "SSS", cost: 25000, desc: "女娲留下的神器。虽然你现在打不开，但它能吸纳死者的灵魂。持有它，你就是三界争夺的焦点。", type: "exclusive"},
                    {name: "昆仑仙法(初级)", color: "A", cost: 1500, desc: "姜子牙传授的基础法术。可以使用符咒定身、搬运重物，或者短暂开启天眼。", type: "exclusive"},
                    {name: "雷震子血统", color: "S", cost: 3200, desc: "你面如青靛，背生双翅，力大无穷。虽然长得丑，但你是空中霸主，能操控雷电。", type: "exclusive"},
                    {name: "饕餮巨兽", color: "SS", cost: 5000, desc: "你可以召唤或变身为上古巨兽饕餮。吞噬一切，体型如山，但容易失去理智。", type: "exclusive"},
                    {name: "比干七窍玲珑心", color: "S", cost: 2800, desc: "你的心脏拥有看破一切虚妄妖邪的能力。妲己在你面前无所遁形。但挖出来就会死。", type: "exclusive"},
                    {name: "鬼侯剑", color: "A", cost: 1800, desc: "一把锋利无比的宝剑，曾属于东伯侯。它渴望饮血，在战场上能发挥出惊人的杀气。", type: "exclusive"},
                    {name: "占卜龟甲", color: "C", cost: 300, desc: "西伯侯姬昌的技能。你可以通过龟甲占卜吉凶，虽然不能改变命运，但能让你趋吉避凶。", type: "exclusive"},
                    {name: "水遁术", color: "B", cost: 500, desc: "姜子牙的逃跑绝技。只要有水的地方，你就能瞬间移动一段距离，保命神技。", type: "exclusive"},
                    {name: "移魂术", color: "A", cost: 1200, desc: "申公豹的邪术。你可以控制死尸或石狮子为你战斗，甚至短暂转移自己的意识。", type: "exclusive"},
                    {name: "天下共主气运", color: "SSS", cost: 18000, desc: "你拥有成为人皇的潜质。各路神仙都会忍不住想帮你，百姓会自发拥戴你。你就是天命。", type: "exclusive"},
                    {name: "蒙眼射箭", color: "B", cost: 400, desc: "即使双眼被蒙住，你也能凭听觉和直觉射中目标。这是对信任的终极考验。", type: "exclusive"},
                    {name: "弑父诅咒", color: "D", cost: 200, desc: "在这个世界，你总是面临杀死父亲或被父亲杀死的伦理困境。你的命运与父权纠缠不清。", type: "exclusive"}
                ]
            },
            {
                name: "239.西游记 (86版/大话西游)",
                desc: "经典的东方神话巅峰。九九八十一难，妖魔鬼怪横行。这里有天庭、地府、龙宫，有长生不老的唐僧肉，也有大闹天宫的齐天大圣。",
                boss: "如来佛祖, 玉皇大帝, 牛魔王, 六耳猕猴",
                identities: [
                    { name: "花果山的小猴子", items: "一个桃子, 抓虱子的手" },
                    { name: "狮驼岭被抓的凡人", items: "一口蒸笼, 绝望的泪水" },
                    { name: "天庭御马监的马夫", items: "一把草料, 弼马温的旧官服" },
                    { name: "女儿国的落胎泉守卫", items: "一瓢泉水, 贪婪的眼神" },
                    { name: "高老庄的家丁", items: "一把钉耙(农用), 猪妖的婚贴" }
                ],
                talents: [
                    {name: "七十二变", color: "SS", cost: 9000, desc: "孙悟空的看家本领。可以变人、变物、变动物，还能躲避三灾利害。虽然尾巴有时候藏不住。", type: "exclusive"},
                    {name: "筋斗云", color: "S", cost: 5000, desc: "一个筋斗十万八千里。三界之内，速度第一。逃跑、追击、搬救兵的神技。", type: "exclusive"},
                    {name: "长生不老肉(唐僧体质)", color: "S", cost: 6000, desc: "你的肉吃一口能长生不老。这让你成为所有妖怪的目标，但也意味着你拥有极强的佛缘和不死护体。", type: "exclusive"},
                    {name: "火眼金睛", color: "A", cost: 3000, desc: "在八卦炉里熏出来的。能看破一切妖魔鬼怪的伪装，但怕烟熏。", type: "exclusive"},
                    {name: "九齿钉耙", color: "A", cost: 2500, desc: "太上老君打造的神兵，实战威力其实不输金箍棒。尤其适合筑地和打群架。", type: "exclusive"},
                    {name: "三昧神风", color: "S", cost: 3500, desc: "黄风怪的绝技。一口气吹出去，天昏地暗，连孙悟空的火眼金睛都受不了。", type: "exclusive"},
                    {name: "人种袋", color: "SS", cost: 7000, desc: "弥勒佛的法宝。往天上一抛，多少人都能装进去。无视等级的强力控制。", type: "exclusive"},
                    {name: "紧箍咒(控制权)", color: "A", cost: 2000, desc: "你掌握了紧箍咒的念法。可以控制戴着紧箍的强者（如孙悟空），让他痛不欲生，听命于你。", type: "exclusive"},
                    {name: "袖里乾坤", color: "SS", cost: 8000, desc: "镇元大仙的绝技。袖子一挥，连人带马装进去，孙悟空都逃不掉。地仙之祖的威严。", type: "exclusive"},
                    {name: "金刚不坏之身", color: "SS", cost: 8500, desc: "吃了无数蟠桃金丹练就的身体。刀枪不入，水火不侵，雷打不动。只能用炼丹炉炼。", type: "exclusive"},
                    {name: "叫名字敢答应吗", color: "S", cost: 4000, desc: "紫金红葫芦/羊脂玉净瓶。只要叫对方名字，对方答应，就会被吸进去化为脓水。", type: "exclusive"},
                    {name: "芭蕉扇(真)", color: "S", cost: 3800, desc: "一扇熄火，二扇生风，三扇下雨。专门克制火系法术，也能把人扇飞八万四千里。", type: "exclusive"},
                    {name: "法天象地", color: "SS", cost: 6500, desc: "变身成万丈高的巨人，力量成倍增长，如同开天辟地的盘古。大场面专用。", type: "exclusive"},
                    {name: "定身术", color: "B", cost: 800, desc: "指着对方喊‘定’。对付小妖百试百灵，对付大妖只能定住一瞬间。", type: "exclusive"},
                    {name: "佛祖压帖", color: "SSS", cost: 20000, desc: "五指山上的那张帖子。拥有绝对的封印力量，可以镇压世间一切妖猴，无论他多强。", type: "exclusive"}
                ]
            },
            {
                name: "240.大话西游",
                desc: "解构的神话，时空的错乱。这里有至尊宝，有紫霞仙子，有一万年的誓言。这是一个关于爱情、宿命和错过的悲喜剧世界。",
                boss: "牛魔王, 观音菩萨, 孙悟空(觉醒前/后)",
                identities: [
                    { name: "五岳山斧头帮的小喽啰", items: "一把钝斧头, 斗鸡眼" },
                    { name: "盘丝洞的看门小妖", items: "一张蜘蛛网, 总是被踩扁" },
                    { name: "沙漠里的瞎子", items: "一副墨镜, 偷看洗澡的欲望" },
                    { name: "被牛魔王抓去婚礼的乐师", items: "一个唢呐, 吓得尿裤子" },
                    { name: "至尊宝的心脏", items: "一滴眼泪, 椰子的外壳" }
                ],
                talents: [
                    {name: "月光宝盒", color: "SSS", cost: 50000, desc: "穿越时空的神器。对着月亮喊‘波若波罗密’，你可以回到过去。但你永远不知道会回到哪一刻，也无法改变注定的悲剧。", type: "exclusive"},
                    {name: "紫青宝剑", color: "S", cost: 4000, desc: "紫霞仙子的佩剑。只有你的意中人才能拔出。拔出它，你就开启了一段注定心痛的缘分。", type: "exclusive"},
                    {name: "一生所爱(BGM)", color: "A", cost: 1500, desc: "当这首歌响起时，全场进入悲伤氛围。敌人的攻击欲望降低，你的防御力归零，但精神境界升华。", type: "exclusive"},
                    {name: "大话痨(唐僧版)", color: "S", cost: 3000, desc: "你的唠叨是精神攻击。能把小妖说到自杀，把神仙说到崩溃。‘人是人他妈生的，妖是妖他妈生的...’", type: "exclusive"},
                    {name: "移形换影大法", color: "B", cost: 800, desc: "你可以和别人互换身体。虽然经常出bug（比如换成了狗），但关键时刻能躲避致命一击。", type: "exclusive"},
                    {name: "七伤拳", color: "C", cost: 400, desc: "先伤己后伤人。打一拳自己吐血，但如果打中了斗鸡眼，威力倍增。", type: "exclusive"},
                    {name: "爱你一万年", color: "SS", cost: 6000, desc: "最强的情话谎言。说出这段话时，可以100%欺骗女性角色的感情，让她们为你放下武器，甚至为你去死。", type: "exclusive"},
                    {name: "金箍(宿命)", color: "SSS", cost: 15000, desc: "戴上它，你拥有齐天大圣的力量，但必须断绝七情六欲。不戴金箍救不了她，戴上金箍爱不了她。", type: "exclusive"},
                    {name: "紫霞的铃铛", color: "A", cost: 2000, desc: "摇晃铃铛，可以摄人心魄，让人产生幻觉。也是召唤紫霞仙子的信物。", type: "exclusive"},
                    {name: "隐身符(山寨版)", color: "D", cost: 100, desc: "二当家的隐身符。大部分时候是失灵的，只有关键部位（或者不想隐身的时候）会隐身。", type: "exclusive"},
                    {name: "三颗痣", color: "B", cost: 500, desc: "脚底板的三颗痣。这是孙悟空转世的标志。拥有它，你会不断遇到给你三颗痣的人，觉醒前世记忆。", type: "exclusive"},
                    {name: "香蕉皮滑倒术", color: "C", cost: 200, desc: "你扔出的香蕉皮必定让人滑倒。哪怕是神仙踩到了也得摔个狗吃屎。搞笑但实用。", type: "exclusive"},
                    {name: "牛魔王的叉子", color: "A", cost: 2500, desc: "巨大的钢叉，威力惊人。能召唤小妖，还能用来烤全羊。", type: "exclusive"},
                    {name: "青霞/紫霞双魂", color: "S", cost: 3500, desc: "你的身体里住着两个灵魂。白天是神仙，晚上是恶魔（或者相反）。性格分裂，战力加倍。", type: "exclusive"},
                    {name: "城墙上的武士", color: "B", cost: 600, desc: "你拥有夕阳武士的刀法和傲气。虽然看起来像个凡人，但那一吻能解开孙悟空的心结。", type: "exclusive"}
                ]
            },
              {
        name: "241.捉妖记",
        desc: "人与妖共存的奇幻古代世界。妖王更迭，天师横行。在这个世界，妖不再是单纯的怪物，它们有血有肉，甚至比人更重情义。而人界的天师堂则以捕杀妖物为业，各方势力暗流涌动。",
        boss: "葛千户, 妖王(老/新), 宋天荫(后期)",
        identities: [
            { name: "永宁村的痴呆村民", items: "一套破旧的麻布衣, 一个藏着烂果子的布袋" },
            { name: "天师堂的一钱天师", items: "一枚生锈的铜钱, 一张画坏的定身符" },
            { name: "顺天府的底层捕快", items: "一把缺口的腰刀, 一双磨破的官靴" },
            { name: "登仙楼后厨的切菜工", items: "一把沾满腥味的菜刀, 一条油腻的围裙" },
            { name: "流浪的卖艺人", items: "一面破锣, 一只只有三条腿的猴子" }
        ],
        talents: [
            {name: "天师血脉(稀薄)", color: "B", cost: 500, desc: "你的祖上曾出过二钱天师，这让你对妖气有一丝微弱的感应，但也仅限于此，遇到大妖还是得跑。", type: "exclusive"},
            {name: "烹饪宗师(妖)", color: "A", cost: 750, desc: "你掌握了处理妖物食材的顶尖技艺，无论是煎炒烹炸，都能将妖肉的能量最大化，且无毒副作用。", type: "exclusive"},
            {name: "纸人替身术", color: "S", cost: 2200, desc: "剪纸成兵，赋予纸人短暂的生命。虽然战斗力一般，但在探路、替死、迷惑敌人方面有奇效。", type: "exclusive"},
            {name: "妖语通晓", color: "C", cost: 180, desc: "你能听懂妖族的语言，这在大多数时候能救你一命，或者让你听到它们在讨论怎么吃你。", type: "exclusive"},
            {name: "缝纫大师", color: "C", cost: 120, desc: "你擅长缝补衣物，甚至能用特殊的针线缝合妖皮，制作简易的伪装道具。", type: "exclusive"},
            {name: "萝卜妖的祝福", color: "SS", cost: 6000, desc: "你曾无意中帮助过小妖王胡巴，获得了它的祝福。你的运气大幅提升，且在面对植物系妖物时有天然亲和力。", type: "exclusive"},
            {name: "斩妖刀法(残篇)", color: "B", cost: 400, desc: "天师堂的基础刀法，虽然只有前三式，但对付E级的小妖已经绰绰有余。", type: "exclusive"},
            {name: "披皮术", color: "S", cost: 3000, desc: "一种邪恶的秘术，可以完整剥下生物的皮囊并穿在身上，完美伪装成对方，连气息都能模拟。", type: "exclusive"},
            {name: "怀胎体质(男)", color: "SS", cost: 8000, desc: "极其特殊的体质，男人也能怀妖胎。虽然过程痛苦，但生下的妖物将视你为至亲，成为最强助力。", type: "exclusive"},
            {name: "金钱诱惑", color: "C", cost: 150, desc: "你对金钱极其敏感，总能在大街上捡到铜板，或者在交易中占到便宜。", type: "exclusive"},
            {name: "符咒精通(初级)", color: "A", cost: 900, desc: "你学会了绘制基本的定身符和火焰符，虽然成功率只有50%，但关键时刻能翻盘。", type: "exclusive"},
            {name: "葛千户的改造术", color: "S", cost: 2800, desc: "你掌握了部分生物改造知识，可以将妖的肢体移植到人身上，获得强大的力量，但会逐渐丧失人性。", type: "exclusive"},
            {name: "飞天锁链", color: "A", cost: 850, desc: "你熟练掌握天师常用的飞爪锁链，能像蜘蛛侠一样在建筑间移动，或远距离束缚敌人。", type: "exclusive"},
            {name: "万妖之王(伪)", color: "SSS", cost: 32000, desc: "你体内移植了上一代妖王的妖丹，拥有统御百妖的潜力，但也时刻面临被妖丹反噬的风险。", type: "exclusive"},
            {name: "奶奶的假牙", color: "D", cost: 50, desc: "一副并不合嘴的假牙，除了咬人有点疼之外，没有任何特殊作用。", type: "exclusive"}
        ]
    },
    {
        name: "242.狄仁杰系列(徐克版)",
        desc: "大唐盛世下的诡谲暗影。这是一个充满奇幻色彩的武侠探案世界。通天浮屠高耸入云，赤焰金龟、鳌皇、封魔族等奇异事物层出不穷。朝堂之上武后弄权，江湖之中奇人异士辈出。",
        boss: "武则天, 裴东来, 沙陀忠(黑化)",
        identities: [
            { name: "大理寺的扫地杂役", items: "一把秃了毛的扫帚, 沾满灰尘的粗布衣" },
            { name: "通天浮屠的搬砖苦力", items: "沉重的石块, 满手的血泡" },
            { name: "鬼市的无名乞丐", items: "一个破碗, 浑身散发的腐臭味" },
            { name: "金吾卫的守夜卒", items: "一盏快没油的灯笼, 一把生锈的腰刀" },
            { name: "洛阳城郊的卖炭翁", items: "一车卖不出去的黑炭, 满面尘灰烟火色" }
        ],
        talents: [
            {name: "亢龙锏(仿品)", color: "S", cost: 2800, desc: "一把仿造的亢龙锏，虽然没有原版的听风辨位之能，但材质坚硬，且不仅是兵器，更是破解机关的钥匙。", type: "exclusive"},
            {name: "腹语术", color: "B", cost: 300, desc: "鬼市通用的交流技巧，不用张嘴也能说话，适合在潜行或被点穴时传递信息。", type: "exclusive"},
            {name: "赤焰金龟毒", color: "SS", cost: 7500, desc: "你体内潜伏着这种恐怖的毒素，见光即燃。若能控制，你的血液将是世界上最可怕的燃烧弹。", type: "exclusive"},
            {name: "易容缩骨法", color: "A", cost: 1200, desc: "江湖奇术，能改变容貌和身形。在波云诡谲的洛阳城，这是保命的最佳手段。", type: "exclusive"},
            {name: "神探直觉", color: "S", cost: 2500, desc: "模仿狄仁杰的思维方式，你总能在杂乱无章的线索中找到最关键的那一环，逻辑推理能力大幅提升。", type: "exclusive"},
            {name: "西域幻术", color: "A", cost: 1500, desc: "封魔族的秘传幻术，能制造逼真的幻象迷惑敌人，甚至造成精神伤害。", type: "exclusive"},
            {name: "针灸解毒", color: "B", cost: 450, desc: "你掌握了一套特殊的针法，能暂时压制大部分毒素的发作，为你争取寻找解药的时间。", type: "exclusive"},
            {name: "水下闭气", color: "C", cost: 180, desc: "由于长期在水下作业，你能在水中闭气超过十分钟，且行动自如。", type: "exclusive"},
            {name: "鳌皇之血", color: "SSS", cost: 26000, desc: "你沐浴过巨型海怪鳌皇的血液，皮肤坚硬如铁，力量无穷，且对水系法术免疫。", type: "exclusive"},
            {name: "读唇术", color: "C", cost: 120, desc: "你能通过观察别人的嘴唇动作解读出他们在说什么，是刺探情报的神技。", type: "exclusive"},
            {name: "移魂大法", color: "SS", cost: 6800, desc: "一种高深的精神控制术，能短时间控制意志薄弱者的行动，甚至修改其记忆。", type: "exclusive"},
            {name: "工部机关术", color: "A", cost: 950, desc: "参与过通天浮屠建造的经验，让你精通各种机关陷阱的布置与破解。", type: "exclusive"},
            {name: "狂暴化(裴东来式)", color: "B", cost: 600, desc: "虽然你是白化病患者，但愤怒能让你爆发出超越常人的速度和力量，代价是事后极度虚弱。", type: "exclusive"},
            {name: "方术火药", color: "A", cost: 800, desc: "你掌握了赤焰金龟毒液与火药混合的配方，制造出的炸弹威力惊人且无法用水扑灭。", type: "exclusive"},
            {name: "皇室威仪", color: "S", cost: 2100, desc: "你身上带有一丝武则天的霸气，能让普通NPC不自觉地臣服，甚至能震慑低级野兽。", type: "exclusive"}
        ]
    },
    {
        name: "243.画皮",
        desc: "妖术与人性交织的东方魔幻世界。九霄美狐，披人皮而行。这是一个关于爱、欲望、牺牲与背叛的故事。妖想变成人，人却往往比妖更像鬼。",
        boss: "小唯(九霄美狐), 蜥蜴精, 捉妖师庞勇",
