            {name: "榛子酥过敏", color: "D", cost: 20, desc: "吃了榛子酥会呼吸困难，除了证明你是林殊外，是个纯粹的弱点。", type: "exclusive"},
            {name: "辩才无碍", color: "A", cost: 1000, desc: "朝堂论辩无敌手，能把黑的说成白的，单靠嘴炮就能气死敌方谋士。", type: "exclusive"}
        ]
    },
    {
        name: "247.甄嬛传",
        desc: "清宫极致的内斗生态。紫禁城不仅是皇宫，更是修罗场。一句话、一个眼神都可能招致杀身之祸。这里没有硝烟，但比战场更残酷。在这个“甄学”宇宙，活下去就是胜利。",
        boss: "雍正(皇上), 皇后(乌拉那拉氏), 华妃",
        identities: [
            { name: "御膳房的烧火太监", items: "一根吹火筒, 满脸的煤灰" },
            { name: "碎玉轩的粗使宫女", items: "一把扫帚, 冻红的双手" },
            { name: "辛者库的洗衣奴才", items: "一盆冰冷的脏水, 满是冻疮的手" },
            { name: "太医院的抓药学徒", items: "一个小戥子, 几包草药" },
            { name: "冷宫的疯癫弃妃", items: "一件破旧的宫装, 一个破布娃娃" }
        ],
        talents: [
            {name: "宫斗冠军(甄嬛)", color: "SSS", cost: 38000, desc: "集美貌、智慧、才情、狠辣于一身。你拥有看穿一切阴谋的洞察力和绝地反击的手段，天生的太后命。", type: "exclusive"},
            {name: "欢宜香抗性", color: "S", cost: 2500, desc: "你对麝香等会导致不孕的药物有极强的辨识能力和抗性，这是在后宫保住子嗣的关键。", type: "exclusive"},
            {name: "华妃的跋扈", color: "A", cost: 1800, desc: "强大的气场威压，虽然容易拉仇恨，但在打压低位嫔妃和奴才时效果拔群，赏“一丈红”时无需理由。", type: "exclusive"},
            {name: "安陵容的调香", color: "S", cost: 3000, desc: "顶级的制香与用毒高手。能用香料控制人的情绪、引诱动物甚至杀人于无形。", type: "exclusive"},
            {name: "温太医的守护", color: "A", cost: 2000, desc: "你拥有极高的医术，尤其是妇科圣手。不仅能救人，还能配置各种假死药、迷情药。", type: "exclusive"},
            {name: "皇后的头风", color: "D", cost: 100, desc: "一到关键时刻就会头痛发作，虽然痛苦，但也是博取皇帝同情和逃避责任的好借口。", type: "exclusive"},
            {name: "打胎队长", color: "S", cost: 2800, desc: "精通各种让嫔妃流产的手段，从食物相克到惊吓冲撞，你是皇嗣存活率的最大杀手。", type: "exclusive"},
            {name: "苏培盛的圆滑", color: "A", cost: 1500, desc: "做人的极致艺术。你能在这个吃人的皇宫里左右逢源，谁都不得罪，谁都愿意给你几分薄面。", type: "exclusive"},
            {name: "惊鸿舞", color: "B", cost: 800, desc: "绝美的舞姿，能在宴会上瞬间抓住皇帝的眼球，大幅提升受宠概率。", type: "exclusive"},
            {name: "三阿哥的长高", color: "D", cost: 10, desc: "你长高了。这除了让皇帝觉得你蠢之外，没有任何用处。", type: "exclusive"},
            {name: "滴血验亲(作弊)", color: "S", cost: 3200, desc: "你掌握了在水中动手脚的技巧，能随意控制滴血验亲的结果，这是混淆皇室血脉的神技。", type: "exclusive"},
            {name: "纯元周边", color: "SS", cost: 6000, desc: "你长得像纯元皇后，或者声音像，或者才艺像。这是在这个世界最大的外挂，但也可能成为替身悲剧。", type: "exclusive"},
            {name: "剪秋的忠诚", color: "B", cost: 500, desc: "你会获得一个绝对忠诚的心腹，为了你她敢去给甄嬛下毒，哪怕受尽酷刑也不会出卖你。", type: "exclusive"},
            {name: "胧月的助攻", color: "A", cost: 1200, desc: "善于利用孩子的身份撒谎或解围，关键时刻的一句“皇额娘推了熹娘娘”能定乾坤。", type: "exclusive"},
            {name: "果郡王的笛声", color: "B", cost: 600, desc: "吹得一手好笛子，能吸引文艺女青年的注意，但也容易招来杀身之祸（绿帽子警告）。", type: "exclusive"}
        ]
    },
    {
        name: "248.武林外传",
        desc: "同福客栈的解构武侠世界。七侠镇，同福客栈。这里没有血雨腥风，只有柴米油盐和插科打诨。但别小看这里，卧虎藏龙，随便一个跑堂的都可能是传说中的高手。",
        boss: "公孙乌龙, 上官云顿, 姬无命",
        identities: [
            { name: "同福客栈门口的乞丐(小米)", items: "一根打狗棒, 一个破碗" },
            { name: "七侠镇的捕快燕小六的跟班", items: "一把唢呐, 一条红腰带" },
            { name: "对面怡红楼的倒茶伙计", items: "一条毛巾, 一盘瓜子" },
            { name: "经常来吃饭的钱掌柜", items: "一身绸缎衣服, 一个怕老婆的眼神" },
            { name: "路过的江湖骗子", items: "几本假秘籍, 一贴狗皮膏药" }
        ],
        talents: [
            {name: "葵花点穴手", color: "S", cost: 3500, desc: "指如疾风，势如闪电。老白成名绝技，能定住人身，也能解穴。除了对付无双这种没有穴位的，基本无解。", type: "exclusive"},
            {name: "排山倒海", color: "A", cost: 2800, desc: "惊涛掌的一招，威力巨大，虽然小郭经常拍在柱子上，但真打在人身上也是骨断筋折。", type: "exclusive"},
            {name: "子曾经曰过", color: "B", cost: 600, desc: "秀才的嘴遁。通过长篇大论的哲学道理，能把姬无命这种高手活活说死，造成精神崩溃。", type: "exclusive"},
            {name: "佟湘玉的抠门", color: "C", cost: 300, desc: "极致的经营管理能力。你能从石头里榨出油来，任何财务漏洞都逃不过你的眼睛。", type: "exclusive"},
            {name: "李大嘴的菜刀", color: "B", cost: 500, desc: "玄铁菜刀，削铁如泥。配合大嘴的刀法，既能做菜也能砍人，还有“必胜必胜”的buff。", type: "exclusive"},
            {name: "衡山剑法(莫小贝版)", color: "C", cost: 400, desc: "虽然是乱舞，但偶尔能使出几招精妙的剑法。作为衡山派掌门，你有潜力学会真正的衡山绝学。", type: "exclusive"},
            {name: "降龙十巴掌", color: "A", cost: 1200, desc: "丐帮绝学降龙十八掌的……低配版？小米传授的掌法，虽然名字好笑，但威力不容小觑。", type: "exclusive"},
            {name: "免死金牌", color: "SS", cost: 8000, desc: "太祖御赐的金牌，真正的保命神器。在这个世界，官府和江湖都要给几分面子。", type: "exclusive"},
            {name: "关中大侠虚名", color: "C", cost: 100, desc: "虽然是买来的或者误打误撞得来的，但这个名号能吓退一些不知底细的小毛贼。", type: "exclusive"},
            {name: "易容术(老白版)", color: "B", cost: 800, desc: "能化妆成各种人，甚至包括太监和老太太，是行走江湖、躲避捕快的必备技能。", type: "exclusive"},
            {name: "画画技能", color: "C", cost: 150, desc: "能画出连亲妈都认不出来的通缉令，或者画一本《侠客行》漫画。", type: "exclusive"},
            {name: "隔空打穴", color: "SS", cost: 7500, desc: "公孙乌龙的绝技，不需要接触身体就能点穴，射程远，防不胜防。", type: "exclusive"},
            {name: "移魂大法(摄魂术)", color: "S", cost: 3000, desc: "能催眠别人，让人说出真话或者做出奇怪的举动（比如以为自己是只鸡）。", type: "exclusive"},
            {name: "我是谁(哲学)", color: "SSS", cost: 12000, desc: "触及世界本源的哲学思考。你能通过追问“我是谁，我从哪里来”，让敌人的自我意识崩塌。", type: "exclusive"},
            {name: "好折凳", color: "D", cost: 50, desc: "七大武器之首，藏在民居之中，随手可得。坐着舒服，打人顺手。", type: "exclusive"}
        ]
    },
    {
        name: "249.爱情公寓",
        desc: "都市情景剧世界。两间公寓，一群年轻人。这里充满了无厘头的搞笑、致敬（抄袭？）和不可思议的黑科技。逻辑在这里经常下线，但快乐是真的。",
        boss: "T-800(胡一菲梦境), 决战紫禁之巅的吕布, 蟑螂鼠",
        identities: [
            { name: "楼下酒吧的酒保", items: "一个调酒壶, 一张账单" },
            { name: "送外卖的快递员", items: "一个外卖箱, 一辆电动车" },
            { name: "曾小贤电台的实习生", items: "一副耳机, 一叠没人看的稿子" },
            { name: "关谷神奇的助手", items: "一支画笔, 一堆废纸" },
            { name: "公寓的维修工", items: "一个工具箱, 一脸无奈" }
        ],
        talents: [
            {name: "弹一闪", color: "SSS", cost: 30000, desc: "胡一菲的必杀技。无视物理防御，必定暴击，能瞬间秒杀任何碳基生物，甚至能切断钢板。", type: "exclusive"},
            {name: "吕子乔的肾宝", color: "A", cost: 1500, desc: "一瓶神奇的饮料，喝了之后精力无限，味道好极了。能让你在几天几夜的派对中保持亢奋。", type: "exclusive"},
            {name: "唐氏表演法则", color: "B", cost: 600, desc: "唐悠悠的独门绝技。show time！无论在什么场合，你都能强行加戏，并让周围人配合你的演出。", type: "exclusive"},
            {name: "一口盐汽水", color: "C", cost: 200, desc: "陈美嘉的口头禅攻击。虽然是精神攻击，但能有效降低对方的智商和士气。", type: "exclusive"},
            {name: "如来神掌(吕子乔版)", color: "S", cost: 2800, desc: "虽然只有几招，但每一掌都威力惊人，能把人打飞出公寓。副作用是使用后会欠下巨额人情债。", type: "exclusive"},
            {name: "张伟的律政先锋", color: "D", cost: 50, desc: "作为律师，你打官司基本没赢过，但作为倒霉蛋，你的生命力极其顽强，小强本强。", type: "exclusive"},
            {name: "爱森公寓黑科技", color: "SS", cost: 8500, desc: "你能制造出各种不符合科学原理的发明，比如如意金箍棒、寻龙尺、或者能穿越时空的洗衣机。", type: "exclusive"},
            {name: "曾小贤的眉毛舞", color: "C", cost: 100, desc: "极具嘲讽效果的表情动作，能瞬间拉满仇恨值。", type: "exclusive"},
            {name: "关谷的切腹", color: "B", cost: 400, desc: "当你犯错时，摆出切腹的架势能迅速获得他人的原谅（因为大家都知道你不敢真切）。", type: "exclusive"},
            {name: "飞行棋大师", color: "C", cost: 150, desc: "你精通飞行棋的各种规则和潜规则，能在无聊的周末消磨几十个小时的时间。", type: "exclusive"},
            {name: "决战紫禁之巅", color: "S", cost: 3500, desc: "在特定时刻（如屋顶决斗），你能化身为吕布或服部半藏，获得超凡的战斗力。", type: "exclusive"},
            {name: "数学白痴(美嘉)", color: "D", cost: 20, desc: "一七得七，二七四十八...你的数学计算能力为零，但这反而让你对数字陷阱免疫。", type: "exclusive"},
            {name: "僚机光环", color: "A", cost: 1000, desc: "作为僚机，你能完美配合主力输出（搭讪），大幅提升成功率。", type: "exclusive"},
            {name: "雷哥的威慑", color: "B", cost: 500, desc: "虽然你个子小，但气场两米八，能用言语霸凌比你强壮得多的对手。", type: "exclusive"},
            {name: "公寓不死身", color: "SS", cost: 7000, desc: "作为主角团一员，无论受多重的伤（比如被弹一闪打飞），下一集（第二天）都会满血复活。", type: "exclusive"}
        ]
    },
    {
        name: "250.仙剑奇侠传(剧版)",
        desc: "御剑乘风来，除魔天地间。这是一个凄美的仙侠世界。女娲后人的宿命，蜀山的道义，拜月教的阴谋。这里有御剑飞行，有五灵法术，更有让人意难平的悲剧结局。",
        boss: "拜月教主, 水魔兽, 邪剑仙(若含三代)",
        identities: [
            { name: "余杭镇的小二", items: "一条抹布, 一把木剑" },
            { name: "仙灵岛的扫地丫鬟", items: "一把扫帚, 一个莲蓬" },
            { name: "苏州城的街头混混", items: "几个铜板, 一本破书" },
            { name: "蜀山派的入门弟子", items: "一把铁剑, 一身道袍" },
            { name: "苗疆的普通蛊师", items: "一只低级蛊虫, 一个竹筒" }
        ],
        talents: [
            {name: "女娲血脉", color: "SSS", cost: 45000, desc: "大地之母的传承。拥有至高无上的灵力，能驾驭五灵，召唤风雨，甚至牺牲自己拯救苍生。注定背负沉重宿命。", type: "exclusive"},
            {name: "御剑术", color: "A", cost: 2500, desc: "蜀山派基础也是核心的法术。以气御剑，千里之外取人首级，更能踏剑飞行，遨游九天。", type: "exclusive"},
            {name: "万剑诀", color: "S", cost: 5000, desc: "召唤万千剑气，如雨点般落下。大范围高伤害技能，清场神技。", type: "exclusive"},
            {name: "酒神咒", color: "SS", cost: 9000, desc: "酒剑仙传授的绝技。喝得越醉威力越大，召唤酒神虚影给予敌人毁灭性打击。一生只能用九次。", type: "exclusive"},
            {name: "飞龙探云手", color: "B", cost: 800, desc: "李家祖传绝技，能在战斗中神不知鬼不觉地偷取敌人的物品或金钱，发家致富全靠它。", type: "exclusive"},
            {name: "五灵仙术", color: "A", cost: 3000, desc: "精通雷、风、水、火、土五种属性的法术，能针对敌人的弱点进行打击。", type: "exclusive"},
            {name: "醉仙望月步", color: "B", cost: 1200, desc: "身法如醉酒般飘忽不定，极难被击中，且能增加连击概率。", type: "exclusive"},
            {name: "天罡战气", color: "A", cost: 1500, desc: "短时间内大幅提升攻击力，是爆发输出的必备buff。", type: "exclusive"},
            {name: "蛊术精通", color: "B", cost: 1000, desc: "苗疆秘术，能驱使各种蛊虫进行攻击、治疗或控制，让人防不胜防。", type: "exclusive"},
            {name: "一线牵", color: "C", cost: 300, desc: "能感知到系着另一端红线之人的位置和安危，是寻找队友的神器。", type: "exclusive"},
            {name: "拜月的科学", color: "SS", cost: 8500, desc: "你理解了地球是圆的。这种超越时代的认知让你拥有看破世界本质的能力，法力深不可测。", type: "exclusive"},
            {name: "魔剑/镇妖剑", color: "SS", cost: 10000, desc: "获得一把上古神兵的认可。魔剑嗜血，镇妖剑破邪，得其一可横行天下。", type: "exclusive"},
            {name: "阿奴的贪吃", color: "D", cost: 50, desc: "你总是很饿，需要消耗大量食物，但吃饱了之后灵力恢复速度加快。", type: "exclusive"},
            {name: "比武招亲", color: "C", cost: 200, desc: "如果你赢了比武招亲，你能获得一个强力的伴侣（林月如级别），但也要承担相应的情债。", type: "exclusive"},
            {name: "十年之约", color: "S", cost: 10, desc: "一个并没有什么实际属性加成，但会让全服玩家泪目的被动技能。你的故事将被传唱。", type: "exclusive"}
        ]
    },
                      {
                name: "251.花千骨",
                desc: "一个六界共存的仙侠世界，以长留仙山为尊。神器、妖神之力与师徒虐恋是这里的主旋律。每个人都有执念，每一把剑都有故事。",
                boss: "花千骨(妖神), 白子画, 杀阡陌, 东方彧卿",
                identities: [
                    { name: "长留新进弟子", items: "一把未开锋的木剑, 一块代表身份的宫木" },
                    { name: "异朽阁的侍从", items: "一个诡异的面具, 一本记录着无数秘密的账簿" },
                    { name: "七杀殿的小妖", items: "一瓶散发着腥味的毒药, 一面画着圣君画像的旗帜" },
                    { name: "蜀山派幸存弟子", items: "一本残缺的蜀山剑谱, 几张威力低微的道符" },
                    { name: "人间落第书生", items: "一个破旧的书箱, 一盏忽明忽暗的灯笼" }
                ],
                talents: [
                    {name: "天煞孤星(命格)", color: "SS", cost: 8000, desc: "你生来便是不仅克父克母，甚至克死身边所有亲近之人的绝世凶命。虽然注定孤独，但你的血液对花草有枯萎之效，且极易吸引妖魔。", type: "exclusive"},
                    {name: "洪荒之力(封印)", color: "SSS", cost: 45000, desc: "上古妖神的全部力量封印在你体内。一旦解封，你将成为毁天灭地的存在，六界无人能敌，但代价是失去理智和被世人唾弃。", type: "exclusive"},
                    {name: "长留上仙亲传", color: "S", cost: 3500, desc: "你被长留掌门破格收为徒弟，拥有最好的修炼资源和断念剑的使用权。你的起点是无数人修行的终点。", type: "exclusive"},
                    {name: "异朽君的交易", color: "A", cost: 1200, desc: "你与异朽阁主达成了某种契约，可以支付代价（如寿命、感官）来换取这世间任何你想知道的秘密或情报。", type: "exclusive"},
                    {name: "杀姐姐的宠爱", color: "S", cost: 2800, desc: "魔君杀阡陌看你顺眼，把你当做妹妹/弟弟般宠溺。在七杀殿范围内，你可以横着走，且随时能召唤魔君护短。", type: "exclusive"},
                    {name: "流光琴(仿品)", color: "B", cost: 450, desc: "一把模仿上古神器流光琴制作的乐器，虽然无法净化妖神，但弹奏出的音波足以震慑普通的妖魔鬼怪。", type: "exclusive"},
                    {name: "验生石", color: "C", cost: 100, desc: "一块与你生命相连的石头。虽然不能战斗，但它能精准反映你的生命状态，是你在这个危险世界存活的警示器。", type: "exclusive"},
                    {name: "糖宝灵虫", color: "A", cost: 900, desc: "你拥有一只由凤凰眼泪凝结而成的灵虫，它不仅可爱叫你娘亲/爹爹，还是六界通晓万物的百科全书。", type: "exclusive"},
                    {name: "蜀山剑法(入门)", color: "C", cost: 180, desc: "蜀山派的基础御剑术，虽然招式平平，但胜在根基扎实，是修仙问道的敲门砖。", type: "exclusive"},
                    {name: "生死劫", color: "D", cost: 50, desc: "你命中注定会遇到一个是你‘生死劫’的人。爱上他/她会让你万劫不复，修为尽毁，是个极大的隐患。", type: "exclusive"},
                    {name: "香草气息", color: "C", cost: 120, desc: "你的身体散发着一种特殊的异香，能吸引蝴蝶和无害的小动物，让你在野外不至于太寂寞。", type: "exclusive"},
                    {name: "断念残剑", color: "B", cost: 500, desc: "一把曾经是神兵利器，如今却断裂的残剑。即便如此，其锋利程度依然削铁如泥，且残留着上仙的剑意。", type: "exclusive"},
                    {name: "蓬莱富豪", color: "B", cost: 300, desc: "你出生在富甲天下的蓬莱岛，虽然修为不高，但你拥有“钞能力”，能用灵石砸死低级对手。", type: "exclusive"},
                    {name: "销魂钉之痛", color: "D", cost: 20, desc: "你曾受过销魂钉的刑罚，虽然活了下来，但每逢阴雨天全身骨骼便会剧痛无比，严重影响战斗状态。", type: "exclusive"},
                    {name: "不老不死(诅咒)", color: "SS", cost: 7500, desc: "你获得了某种诅咒般的不朽，不会老去也不会自然死亡，但必须承受永恒的孤独和看着亲人离去的痛苦。", type: "exclusive"}
                ]
            },
            {
                name: "252.三生三世十里桃花",
                desc: "四海八荒，青丘帝姬与九重天太子的三世情缘。上神遍地走，渡劫如喝水。这是一个讲究辈分、种族和历劫的古风神话世界。",
                boss: "夜华, 擎苍, 墨渊, 东华帝君, 折颜",
                identities: [
                    { name: "青丘的一只小狐狸", items: "一根漂亮的狐狸毛, 几颗用来磨牙的野果" },
                    { name: "天宫的扫地仙娥", items: "一把扫尽尘埃的扫帚, 一块只能通行外围的令牌" },
                    { name: "翼族的巡逻士兵", items: "一把黑色的长矛, 一对还没长硬的翅膀" },
                    { name: "昆仑虚的洒扫童子", items: "一个装满泉水的葫芦, 一本看不懂的道经" },
                    { name: "凡间历劫的落魄贵族", items: "一块残缺的玉佩, 一身洗得发白的锦衣" }
                ],
                talents: [
                    {name: "九尾狐血统", color: "SS", cost: 8500, desc: "青丘皇族的尊贵血统。你天生拥有九条命，且容貌绝世，魅惑天成，是四海八荒第一等的仙胎。", type: "exclusive"},
                    {name: "上神劫数", color: "S", cost: 3000, desc: "你命中注定要历经一场情劫才能飞升上神。虽然过程痛苦万分，甚至要跳诛仙台，但渡过之后便是天地间的强者。", type: "exclusive"},
                    {name: "十里桃花醉", color: "A", cost: 600, desc: "你拥有折颜上神亲传的酿酒手艺。你酿造的桃花醉不仅美味，还能略微提升修为，是送礼结交大能的神器。", type: "exclusive"},
                    {name: "玉清昆仑扇(缘分)", color: "S", cost: 2500, desc: "这把威力巨大的法器似乎对你有莫名的亲切感。只要你轻轻一挥，便能卷起狂风，震退千军万马。", type: "exclusive"},
                    {name: "东皇钟(封印)", color: "SSS", cost: 40000, desc: "毁天灭地的上古神器。你掌握着开启或封印它的法门，一旦祭出，便是要拉着整个世界陪葬的节奏。", type: "exclusive"},
                    {name: "素素的眼纱", color: "D", cost: 30, desc: "一条白色的眼纱，佩戴后你的视力会受到极大阻碍，但能让你在黑暗中感知到周围的情绪波动。", type: "exclusive"},
                    {name: "龙族威压", color: "A", cost: 1500, desc: "作为天族龙脉的旁支，你天生带有一股威压，能让水族生物对你俯首称臣，且在水中战力倍增。", type: "exclusive"},
                    {name: "司音的易容术", color: "B", cost: 400, desc: "你掌握了高超的易容技巧，哪怕是变成男儿身混入昆仑虚，一般的上仙也难以识破你的真身。", type: "exclusive"},
                    {name: "结魄灯", color: "SS", cost: 6000, desc: "天族圣物，能汇聚凡人或仙人的魂魄。只要有一丝气息尚存，你就能利用此灯将其复活，逆转生死。", type: "exclusive"},
                    {name: "翼族黑翼", color: "B", cost: 550, desc: "你背生双翼，拥有极快的飞行速度和空中作战能力，但会被天族视为异类而遭到排挤。", type: "exclusive"},
                    {name: "凤九的断尾", color: "C", cost: 200, desc: "你拥有一种决绝的勇气，关键时刻可以牺牲自己身体的一部分来换取在三生石上刻字（改变命运）的机会。", type: "exclusive"},
                    {name: "糯米团子", color: "C", cost: 100, desc: "你长得极其可爱，人见人爱花见花开，哪怕是冷酷的夜华君看到你也会忍不住想抱一抱。", type: "exclusive"},
                    {name: "墨渊的阵法心得", color: "A", cost: 1800, desc: "你偶然得到了战神墨渊关于阵法的一页手记，足以让你布置出困住上仙的强大阵法。", type: "exclusive"},
                    {name: "诛仙台戾气", color: "D", cost: 80, desc: "你曾在诛仙台边缘徘徊，沾染了那里的戾气。虽然伤敌一千自损八百，但你的攻击带有腐蚀仙骨的效果。", type: "exclusive"},
                    {name: "三生石留名", color: "S", cost: 3200, desc: "你的名字奇迹般地出现在三生石上，这意味着你在这个世界拥有一段注定无法被斩断的姻缘。", type: "exclusive"}
                ]
            },
            {
                name: "253.香蜜沉沉烬如霜",
                desc: "花界、天界、魔界、鸟族四界纷争。陨丹断情，霜花绝爱。这是一个关于爱恨纠葛、身世之谜和五行法术绚烂的仙侠世界。",
                boss: "旭凤(魔尊), 润玉(天帝), 荼姚(天后), 穷奇",
                identities: [
                    { name: "花界的一颗葡萄精", items: "一滴甘露, 几片遮羞的葡萄叶" },
                    { name: "天界栖梧宫的侍卫", items: "一身亮银甲胄, 一把制式长枪" },
                    { name: "魔界忘川河畔的摆渡人", items: "一艘破旧的小船, 一盏引魂灯" },
                    { name: "鸟族穗禾公主的侍女", items: "几根孔雀羽毛, 一盒精致的胭脂" },
                    { name: "人间圣医族的族人", items: "一个药篓, 一套银针" }
                ],
                talents: [
                    {name: "六瓣霜花(真身)", color: "SS", cost: 8200, desc: "你的真身乃是六瓣霜花，花神之女。天生拥有操纵冰雪和植物的能力，且容貌倾国倾城，但极易招惹桃花债。", type: "exclusive"},
                    {name: "陨丹(灭情)", color: "S", cost: 3500, desc: "你体内服有陨丹，断情绝爱，不知情为何物。这让你在修炼一途心无旁骛，进展神速，但也让你在人际交往中显得冷酷无情。", type: "exclusive"},
                    {name: "凤凰涅槃", color: "SS", cost: 9000, desc: "拥有凤凰血脉，能在死亡烈火中重生。每次涅槃后，你的灵力都会大幅度暴涨，是真正的不死鸟。", type: "exclusive"},
                    {name: "应龙之体", color: "S", cost: 7000, desc: "夜神润玉同款血脉。你可以布星挂夜，操控水系法术，在夜晚战斗力会有显著加成，但性格容易变得偏执。", type: "exclusive"},
                    {name: "寰谛凤翎", color: "A", cost: 2000, desc: "凤凰一族最珍贵的护身法宝。在危急时刻，它会自动张开结界，替你抵挡一次致命的攻击。", type: "exclusive"},
                    {name: "穷奇之力(封印)", color: "SS", cost: 6500, desc: "上古凶兽穷奇的力量被封印在你体内。释放时可获得毁天灭地的肉体力量和瘟疫毒气，但极难控制。", type: "exclusive"},
                    {name: "花界种花术", color: "C", cost: 150, desc: "你能让枯木逢春，瞬间催熟各种花草果蔬。在这个世界，这不仅是生存技能，也是讨好女神的绝技。", type: "exclusive"},
                    {name: "琉璃净火", color: "S", cost: 4000, desc: "天后荼姚的独门绝技，佛门圣火，专烧人元神。威力霸道无比，是天界最强火系法术之一。", type: "exclusive"},
                    {name: "魇兽之梦", color: "B", cost: 600, desc: "你能像魇兽一样吞噬和吐出他人的梦境。这让你能轻易窥探他人的秘密，或者制造幻境困住敌人。", type: "exclusive"},
                    {name: "魔界极光", color: "B", cost: 500, desc: "你掌握了魔界特有的极光法术，绚丽夺目且带有极强的迷幻效果，适合用来逃跑或控制战场。", type: "exclusive"},
                    {name: "水神半魂", color: "A", cost: 1800, desc: "你继承了前代水神的一半神魂，对于水系法术有着天然的亲和力，能制造出温柔而坚韧的水盾。", type: "exclusive"},
                    {name: "红莲业火", color: "A", cost: 2200, desc: "地狱深处的火焰，虽然不如琉璃净火霸道，但附着性极强，一旦沾染便难以熄灭，直至烧尽罪孽。", type: "exclusive"},
                    {name: "锦觅的葡萄干", color: "C", cost: 50, desc: "你随身带着一些葡萄干，虽然没什么大用，但在关键时刻送给别人吃，可能会增加意想不到的好感度。", type: "exclusive"},
                    {name: "鸟族身法", color: "C", cost: 200, desc: "身轻如燕，行动敏捷。虽然不能长途飞行，但在短距离腾挪转移上有着得天独厚的优势。", type: "exclusive"},
                    {name: "天帝金丹", color: "SS", cost: 5500, desc: "一颗集结了天帝毕生修为的金丹。吞服后修为暴涨，但若身体强度不够，很有可能爆体而亡。", type: "exclusive"}
                ]
            },
            {
                name: "254.庆余年(剧版)",
                desc: "一个拥有现代记忆的灵魂穿越到古代庆国。权谋、狙击枪、机器人五竹、四大宗师。这是披着古装皮的科幻废土故事。",
                boss: "庆帝(大宗师), 五竹(神庙使者), 四顾剑, 苦荷, 陈萍萍",
                identities: [
                    { name: "澹州的一名私生子", items: "一块黑布眼罩(仿), 一个神秘的箱子(空)" },
                    { name: "监察院一处文书", items: "一叠加密的情报, 一把藏在袖子里的匕首" },
                    { name: "北齐锦衣卫", items: "飞鱼服, 绣春刀, 一块北齐腰牌" },
                    { name: "庆国户部的小吏", items: "算盘, 账本, 一袋碎银子" },
                    { name: "神庙外的苦修者", items: "破烂的斗篷, 一根枯木杖" }
                ],
                talents: [
                    {name: "霸道真气", color: "SS", cost: 7000, desc: "庆帝同款内功，霸道无比。修炼此功者真气如洪流，破坏力惊人，但若无王道之气调和，容易经脉尽断。", type: "exclusive"},
                    {name: "巴雷特M82A1(箱中物)", color: "SSS", cost: 30000, desc: "来自上个文明的终极单兵武器。在冷兵器时代，这就是神的裁决。一枪在手，大宗师也要绕道走。", type: "exclusive"},
                    {name: "五竹的镭射眼", color: "SSS", cost: 35000, desc: "摘下眼罩，你眼中射出的彩虹光束能瞬间切割一切物质。这是神庙使者的终极杀招，非死即伤。", type: "exclusive"},
                    {name: "现代记忆(穿越者)", color: "S", cost: 2500, desc: "你拥有完整的现代社会记忆。你能背诵红楼梦，懂得制造肥皂玻璃，甚至知道什么是“人人平等”。这是最大的思想武器。", type: "exclusive"},
                    {name: "诗仙附体", color: "B", cost: 500, desc: "你脑子里装着唐诗宋词三百首。在这个文化断层的世界，你随便吟两句就能成为文坛大家，名扬天下。", type: "exclusive"},
                    {name: "监察院提司腰牌", color: "A", cost: 1200, desc: "一块代表着监察院最高权力的腰牌。见牌如见院长，拥有先斩后奏的特权，能调动监察院的暗探。", type: "exclusive"},
                    {name: "费介的毒术", color: "A", cost: 1500, desc: "作为毒仙的传人，你精通天下万毒。无论是下毒还是解毒，你都是行家，能让敌人在不知不觉中毙命。", type: "exclusive"},
                    {name: "四顾剑意", color: "S", cost: 5000, desc: "一种极致的杀意剑法，顾前不顾后，置之死地而后生。每一剑都是为了杀人而挥，威力足以匹敌大宗师。", type: "exclusive"},
                    {name: "天一道心法", color: "A", cost: 2000, desc: "苦荷国师的绝学，讲究顺应自然，生生不息。此功法恢复能力极强，能让你在持久战中立于不败之地。", type: "exclusive"},
                    {name: "王启年的轻功", color: "B", cost: 800, desc: "虽然战斗力不强，但这逃跑的功夫天下无双。只要你想跑，基本上没人能追得上你，保命神技。", type: "exclusive"},
                    {name: "滕子京的忠诚", color: "C", cost: 300, desc: "你拥有一种让人死心塌地追随的人格魅力。你的伙伴会为了保护你，甘愿挡下必死的一刀。", type: "exclusive"},
                    {name: "叶轻眉的日记", color: "S", cost: 2800, desc: "一本记录着神庙秘密和世界真相的日记。得到它，你就掌握了这个世界的终极秘密，但也意味着被庆帝追杀。", type: "exclusive"},
                    {name: "范思辙的经商头脑", color: "C", cost: 200, desc: "你对钱有着敏锐的嗅觉。任何东西在你眼里都能变成生意，能在短时间内积累大量财富。", type: "exclusive"},
                    {name: "流云散手", color: "S", cost: 4500, desc: "叶流云的绝技，如行云流水般潇洒，却暗藏杀机。这是一种将身法与掌法完美结合的武学。", type: "exclusive"},
                    {name: "神庙守护兽(全息)", color: "A", cost: 1800, desc: "你能召唤出一个来自神庙的全息投影怪兽。虽然没有实体攻击力，但足以吓退不知情的古代人。", type: "exclusive"}
                ]
            },
            {
                name: "255.狂飙",
                desc: "京海市，20年的扫黑除恶斗争。卖鱼贩高启强的黑化之路，刑警安欣的执着坚守。这是一个充满江湖气、权钱交易和人性博弈的现实主义世界。",
                boss: "高启强(强盛集团), 徐江, 赵立冬, 泰叔",
                identities: [
                    { name: "旧厂街卖鱼的小贩", items: "一把杀鱼刀, 一辆破旧的电动车" },
                    { name: "市局刑侦支队的新警", items: "警官证, 一副手铐" },
                    { name: "建工集团的工地马仔", items: "安全帽, 一根钢管" },
                    { name: "白金瀚夜总会的服务生", items: "托盘, 一套不合身的小西装" },
                    { name: "莽村的村民", items: "拆迁合同, 一把锄头" }
                ],
                talents: [
                    {name: "孙子兵法(读破)", color: "S", cost: 2500, desc: "你反复研读《孙子兵法》，深谙权谋之道。在黑白两道的博弈中，你总能看透局势，借刀杀人，步步为营。", type: "exclusive"},
                    {name: "干嚼咖啡", color: "B", cost: 300, desc: "在高压环境下，你习惯干嚼咖啡粉来保持清醒和狠劲。这能让你在紧张的对峙中气场压过对手。", type: "exclusive"},
                    {name: "老默的棒棒糖", color: "A", cost: 1500, desc: "当你含着棒棒糖时，你的暗杀成功率提升100%。你是一个莫得感情的杀手，告诉老默，我想吃鱼了。", type: "exclusive"},
                    {name: "泰叔的茶具", color: "B", cost: 600, desc: "你拥有一套名贵的茶具和泡茶手艺。在茶桌上，你能轻易平息各方大佬的怒火，或者在谈笑间划分地盘。", type: "exclusive"},
                    {name: "安欣的轴劲", color: "S", cost: 2000, desc: "你拥有一种近乎偏执的正义感和坚持。这种力量能保护你在20年的黑暗中不被腐蚀，并最终等到光明的到来。", type: "exclusive"},
                    {name: "大嫂的气场", color: "A", cost: 1200, desc: "陈书婷同款气场。你只需一个眼神，就能让桀骜不驯的黑帮分子乖乖听话。你是大哥背后的那个女人/男人。", type: "exclusive"},
                    {name: "冻鱼武器", color: "C", cost: 150, desc: "你擅长使用冷冻的咸鱼作为钝器。这种武器随处可见，杀伤力不俗，且事后可以煮了吃，毁灭证据。", type: "exclusive"},
                    {name: "李有田的五菱宏光", color: "B", cost: 500, desc: "你驾驶面包车的技术出神入化，能在山路上进行排水渠过弯。但切记，不要去招惹刹车失灵。", type: "exclusive"},
                    {name: "保护伞(赵立冬)", color: "SS", cost: 6000, desc: "你背后站着京海市的高层领导。只要不是捅破天的大事，总有人会出面帮你摆平，让你在京海横行霸道。", type: "exclusive"},
                    {name: "疯驴子的经验", color: "C", cost: 200, desc: "你混迹江湖多年，一眼就能看出谁是警察卧底。虽然你总是要遭罪，但你的生存本能极强。", type: "exclusive"},
                    {name: "绝症诊断书", color: "D", cost: 50, desc: "你拥有一张绝症诊断书。这让你做事无所顾忌，因为反正也没几天好活了，这种亡命徒心态最让人恐惧。", type: "exclusive"},
                    {name: "莽村拆迁款", color: "A", cost: 1000, desc: "你手里握着莽村的巨额拆迁项目。这是各方势力争夺的肥肉，既是财富的源泉，也是招致杀身之祸的根源。", type: "exclusive"},
                    {name: "录音笔(证据)", color: "S", cost: 3000, desc: "你手里掌握着关键人物的犯罪录音。这是你的护身符，也是你的催命符，用得好能扳倒大佬，用不好就得死。", type: "exclusive"},
                    {name: "过山峰的狠辣", color: "A", cost: 1400, desc: "你是外地来的职业杀手，行事不讲规矩，心狠手辣。你的出现往往意味着京海市要血流成河。", type: "exclusive"},
                    {name: "指导组的尚方宝剑", color: "SS", cost: 7000, desc: "你是省里派下来的扫黑督导组成员。你代表着国家的意志，拥有彻查一切的权力，是所有黑恶势力的终结者。", type: "exclusive"}
                ]
            },
            {
                name: "256.白夜追凶",
                desc: "津港市，双胞胎兄弟互换身份昼夜追凶。哥哥关宏峰是神探，弟弟关宏宇是通缉犯。这是一个硬汉派、高智商、充满悬疑的刑侦世界。",
                boss: "叶方舟, 娃娃脸杀手, 幕后黑手(渗透警队高层)",
                identities: [
                    { name: "长丰支队编外顾问", items: "手电筒, 现场勘查手套" },
                    { name: "背负命案的通缉犯", items: "假身份证, 一顶鸭舌帽" },
                    { name: "津港市的外卖员", items: "电动车, 外卖箱(可能藏着尸块)" },
                    { name: "法医助理", items: "解剖刀, 验尸报告" },
                    { name: "酒吧驻唱歌手", items: "吉他, 一杯烈酒" }
                ],
                talents: [
                    {name: "黑夜恐惧症", color: "D", cost: -100, desc: "你患有严重的黑暗恐惧症，在黑暗环境中会产生幻觉甚至休克。这迫使你必须在天黑前交接身份。", type: "exclusive"},
                    {name: "双子神探(兄弟齐心)", color: "SS", cost: 6500, desc: "你和你的双胞胎兄弟拥有完美的心灵感应和配合。你们共享身份，白天是神探，晚上是武力值爆表的打手。", type: "exclusive"},
                    {name: "关宏峰的侧写", color: "S", cost: 3000, desc: "你拥有极强的犯罪心理侧写能力。只需看一眼现场，就能在脑海中重构犯罪过程，精准画出嫌疑人画像。", type: "exclusive"},
                    {name: "关宏宇的格斗术", color: "A", cost: 1500, desc: "特种兵级别的格斗技巧。你擅长徒手搏击和使用冷兵器，在近身肉搏中鲜有对手，是队伍里的武力担当。", type: "exclusive"},
                    {name: "周巡的咆哮", color: "B", cost: 500, desc: "你的嗓门巨大，气场暴躁。审讯时，你的怒吼能击溃嫌疑人的心理防线；带队时，你的魄力能镇住全场。", type: "exclusive"},
                    {name: "高亚楠的法医眼", color: "A", cost: 1200, desc: "尸体在你眼里会说话。你能从细微的尸斑、伤口走向判断出死亡时间和凶器，为破案提供关键证据。", type: "exclusive"},
                    {name: "韩彬的逻辑", color: "SS", cost: 5000, desc: "你拥有近乎妖孽的逻辑思维和冷静。你游走在法律边缘，既能帮助破案，也能策划完美的犯罪，是个危险的盟友。", type: "exclusive"},
                    {name: "213灭门案线索", color: "S", cost: 2800, desc: "你掌握着灭门惨案的关键物证。这是解开主角冤屈的钥匙，但也意味着你会成为幕后黑手的头号清除目标。", type: "exclusive"},
                    {name: "刘音的酒吧", color: "C", cost: 300, desc: "你经营着一家消息灵通的酒吧。这里是三教九流汇聚之地，也是你交换身份、获取情报的安全屋。", type: "exclusive"},
                    {name: "指纹伪造术", color: "B", cost: 800, desc: "你精通如何提取和伪造指纹。在这个讲究证据的世界，这项技能能帮你嫁祸他人，或者洗脱嫌疑。", type: "exclusive"},
                    {name: "渗透者名单", color: "SS", cost: 7000, desc: "一份记录着犯罪组织渗透进警队高层的名单。拥有它，你就握住了津港市的命脉，但也站在了悬崖边上。", type: "exclusive"},
                    {name: "胖子的黑客技术", color: "A", cost: 1000, desc: "虽然体型肥胖，但你在网络世界是神。你能入侵监控系统，追踪手机信号，是现代刑侦不可或缺的技术支援。", type: "exclusive"},
                    {name: "外卖小哥的地图", color: "C", cost: 100, desc: "你对津港市的大街小巷了如指掌。无论是逃跑路线还是藏身之处，没有人比你更熟悉这座城市的毛细血管。", type: "exclusive"},
                    {name: "支队长的信任", color: "B", cost: 600, desc: "你赢得了支队长的绝对信任。在关键时刻，他会为你顶住上级压力，给你争取宝贵的查案时间。", type: "exclusive"},
                    {name: "老虎(肺鱼)", color: "C", cost: 50, desc: "你养了一条叫‘老虎’的肺鱼。看着它，你能获得内心的平静，并在独处时思考出案件的突破口。", type: "exclusive"}
                ]
            },
            {
                name: "257.法医秦明",
                desc: "龙番市，法医秦明、刑警林涛、助手大宝组成的铁三角。万劫不复有鬼手，太平人间存佛心。这是一个重口味、硬核法医学的刑侦世界。",
                boss: "清道夫, 连环杀手, 心理变态者",
                identities: [
                    { name: "龙番市公安局法医科科长", items: "勘查箱, 止语的口罩" },
                    { name: "刑警队大队长", items: "配枪, 一双跑烂的运动鞋" },
                    { name: "痕检科实习生", items: "放大镜, 鲁米诺试剂" },
                    { name: "被卷入案件的记者", items: "相机, 录音笔" },
                    { name: "下水道疏通工", items: "疏通机, 防毒面具" }
                ],
                talents: [
                    {name: "鬼手佛心", color: "SS", cost: 6000, desc: "秦明专属天赋。你拥有一双能让死者开口说话的手，和一颗悲天悯人的心。无论尸体腐烂成什么样，你都能还原真相。", type: "exclusive"},
                    {name: "人形警犬(大宝)", color: "A", cost: 1200, desc: "你的嗅觉异常灵敏，能闻出常人忽略的气味（如地沟油、特殊的化学试剂）。在案发现场，你比警犬还好使。", type: "exclusive"},
                    {name: "林涛的行动力", color: "A", cost: 1000, desc: "只要锁定了嫌疑人，就没有你抓不到的。你的体能、枪法和驾驶技术都是警队顶尖，是法医最坚实的后盾。", type: "exclusive"},
                    {name: "微表情分析", color: "B", cost: 600, desc: "通过观察嫌疑人的微表情，你能判断他是否撒谎。虽然不能作为直接证据，但能为审讯提供精准的突破方向。", type: "exclusive"},
                    {name: "法医百科全书", color: "S", cost: 2500, desc: "你熟背所有法医学著作。从尸斑发展到昆虫演替，从毒物反应到骨骼鉴定，你是行走的法医学数据库。", type: "exclusive"},
                    {name: "洁癖(强迫症)", color: "D", cost: -50, desc: "你有严重的洁癖和强迫症。这让你在工作中一丝不苟，但也让你在面对脏乱差环境时san值狂掉，甚至影响行动。", type: "exclusive"},
                    {name: "裁缝的剪刀", color: "B", cost: 400, desc: "你不仅擅长缝合尸体，也擅长缝纫衣物。这双灵巧的手在处理精细证物或修复破碎尸体时有奇效。", type: "exclusive"},
                    {name: "清道夫的伪装", color: "S", cost: 3000, desc: "你精通如何消除犯罪痕迹。如果你想隐藏，哪怕是秦明也难以找到你的破绽。这是一种危险的反侦察能力。", type: "exclusive"},
                    {name: "尸语者", color: "SS", cost: 5000, desc: "一种超自然的直觉。当你触碰尸体时，脑海中会闪过死者生前最后的画面片段。这是科学无法解释的天赋。", type: "exclusive"},
                    {name: "油爆奇案食谱", color: "C", cost: 100, desc: "你能在解剖完腐尸后面不改色地吃下小龙虾。这种强大的心理素质和胃口，让你在任何恶心环境下都能保持战斗力。", type: "exclusive"},
                    {name: "颅骨复原术", color: "A", cost: 1500, desc: "只要有一颗头骨，你就能利用泥塑复原死者生前的容貌。这是确认无名尸源的大杀器。", type: "exclusive"},
                    {name: "沉浸式推理", color: "B", cost: 800, desc: "你能完全代入凶手的视角，模拟犯罪过程。虽然这让你看起来像个精神病，但往往能发现被忽略的盲点。", type: "exclusive"},
                    {name: "无菌手套", color: "C", cost: 50, desc: "随身携带的无菌手套。戴上它，你的专业度+10，且能防止指纹污染现场，是专业人士的标配。", type: "exclusive"},
                    {name: "水上浮尸鉴定", color: "B", cost: 700, desc: "你专精于溺亡案件。对于水流、浮尸肿胀程度、藻类分布有深入研究，能精准判断落水点和死亡时间。", type: "exclusive"},
                    {name: "第四根肋骨", color: "C", cost: 200, desc: "你对人体骨骼了如指掌，知道人体的每一处弱点。在近身格斗中，你能精准打击对方要害，一击制敌。", type: "exclusive"}
                ]
            },
            {
                name: "258.灵魂摆渡",
                desc: "444号便利店，连接阴阳两界的驿站。鬼差赵吏、阴阳眼夏冬青、九天玄女娅。这是一个充满温情、恐怖与哲理的灵异单元剧世界。",
                boss: "冥王阿茶, 蚩尤, 饕餮, 豪姬",
                identities: [
                    { name: "444号便利店夜班店员", items: "红制服, 一双能看见鬼的眼睛" },
                    { name: "游荡在人间的孤魂", items: "一件生前的遗物, 一股执念" },
                    { name: "冥界的鬼差", items: "灭魂枪, 黑色吉普车" },
                    { name: "精神病院的病人", items: "病号服, 画满符咒的墙壁" },
                    { name: "昆仑的下位神", items: "洁白羽衣, 一把光剑" }
                ],
                talents: [
                    {name: "阴阳眼(蚩尤之眼)", color: "SSS", cost: 35000, desc: "夏冬青同款眼睛。你不仅能看见鬼魂，这双眼睛里还封印着魔神蚩尤的力量。一旦觉醒，三界都要颤抖。", type: "exclusive"},
                    {name: "灵魂摆渡人", color: "S", cost: 3000, desc: "赵吏的职业。你拥有穿梭阴阳两界的能力，可以使用灭魂枪消灭恶鬼，也可以引渡亡魂去往冥界。", type: "exclusive"},
                    {name: "九天玄女之力", color: "SS", cost: 8000, desc: "来自昆仑的天女之力。虽然被限制，但你拥有极强的战斗本能，能感知神谕，且对鬼魂有天然的压制力。", type: "exclusive"},
                    {name: "冥王阿茶的青睐", color: "SS", cost: 7500, desc: "冥界之主看你顺眼。你可以借用冥界的力量，甚至召唤鬼兵鬼将为你作战，但小心别被她玩弄于股掌之间。", type: "exclusive"},
                    {name: "长生不老药(伪)", color: "A", cost: 2000, desc: "一种能让人肉体不腐的药物，但灵魂会逐渐枯竭。你可以用它来制造傀儡，或者延续垂死之人的生命。", type: "exclusive"},
                    {name: "鬼丹", color: "B", cost: 600, desc: "由厉鬼精华凝聚而成的丹药。吞噬后可大幅增强灵力，但副作用是容易被怨气侵蚀，变得嗜血。", type: "exclusive"},
                    {name: "便利店结界", color: "B", cost: 500, desc: "你能在一定范围内制造出类似444号便利店的结界。在结界内，鬼魂无法伤害你，且你的灵力恢复速度加倍。", type: "exclusive"},
                    {name: "织女的诅咒", color: "A", cost: 1500, desc: "一个迷宫般的诅咒空间。你可以将敌人困在其中，让他们在无尽的恐惧和迷路中精神崩溃。", type: "exclusive"},
                    {name: "五公子(饕餮)的食欲", color: "S", cost: 4000, desc: "你拥有饕餮的吞噬能力。你能吃下任何东西（包括鬼魂和法宝）并将其转化为自己的力量，但永远感到饥饿。", type: "exclusive"},
                    {name: "古琴盲女的音波", color: "B", cost: 800, desc: "通过弹奏古琴，你能发出控制鬼魂的音波。既能安抚暴躁的怨灵，也能将其震得魂飞魄散。", type: "exclusive"},
                    {name: "药师的契约", color: "A", cost: 1200, desc: "你可以与人类签订契约，用他们最珍贵的东西（如亲情、爱情、感官）来交换实现愿望的能力。", type: "exclusive"},
                    {name: "豪姬的玩偶术", color: "S", cost: 2800, desc: "一种邪恶的泰山府君祭秘术。你可以将人的灵魂封印在玩偶中，或者夺舍他人的身体，实现另类的永生。", type: "exclusive"},
                    {name: "深夜食堂", color: "C", cost: 200, desc: "你擅长做关东煮。你的食物能温暖鬼魂冰冷的身体，让他们愿意向你吐露生前的秘密。", type: "exclusive"},
                    {name: "犀角香", color: "C", cost: 300, desc: "生犀不敢烧，燃之有异香，沾衣带，人能与鬼通。这是一种能让你在没有阴阳眼的情况下看见鬼魂的道具。", type: "exclusive"},
                    {name: "泰山府君祭", color: "SSS", cost: 40000, desc: "传说中能等价交换灵魂的最高祭祀。只要付出足够的代价，你甚至能从泰山府君手中抢回已死之人的灵魂。", type: "exclusive"}
                ]
            },
            {
                name: "259.终极一班",
                desc: "金时空，芭乐高中。KO榜、战力指数、异能行者。这是一个热血中二、充满特效和摇滚乐的校园异能世界。",
                boss: "黑龙, 叶赫那拉·思偍, 狄阿布罗魔尊, 疯龙",
                identities: [
                    { name: "终极一班的转学生", items: "一把奇怪的兵器, KO榜排名的纹身" },
                    { name: "芭乐高中的麻瓜学生", items: "厚重的课本, 经常被勒索的钱包" },
                    { name: "武力裁决所的武尸", items: "绿色面具, 毫无生气的眼神" },
                    { name: "拔魔岛的战士", items: "拔魔斩, 绝缘体质" },
                    { name: "东城卫的吉他手", items: "电吉他, 鬼战音叉" }
                ],
                talents: [
                    {name: "遇强则强(汪大东)", color: "SS", cost: 7500, desc: "你的体质特殊，对手越强，你的战力指数飙升得越高。只要不被秒杀，你总能爆发出超越极限的力量反败为胜。", type: "exclusive"},
                    {name: "龙纹鏊(护主)", color: "S", cost: 3000, desc: "一口平底锅形状的神兵。它具有灵性，能自动护主，反弹敌人的攻击，且遇强则强，是打架做饭两不误的神器。", type: "exclusive"},
                    {name: "亚瑟王的石中剑", color: "SS", cost: 6000, desc: "锁剑石中封印着剑魔。拔下锁剑石，你将获得极强的魔性力量，战力指数暴涨，但容易被剑魔控制心智。", type: "exclusive"},
                    {name: "小雨的左拳", color: "S", cost: 3500, desc: "你的右拳虽然普通，但左拳拥有核弹般的威力。一拳下去，战力指数瞬间爆发十倍，但使用后会虚脱。", type: "exclusive"},
                    {name: "KO.1战力", color: "S", cost: 5000, desc: "你拥有破万点的基础战力指数。在高校界，你是传说的存在，光是释放战力力场就能压得普通异能行者动弹不得。", type: "exclusive"},
                    {name: "武尸毒", color: "B", cost: 800, desc: "你体内潜伏着武尸毒。这让你不惧疼痛，身体如钢铁般坚硬，但如果不定期服用解药，会彻底沦为杀人机器。", type: "exclusive"},
                    {name: "拔魔战士", color: "A", cost: 2500, desc: "来自拔魔岛的技艺。你没有战力指数，但天生克制魔物。你的拔魔斩能无视防御，直接斩杀魔化异能行者。", type: "exclusive"},
                    {name: "铁克无极(终极铁克人)", color: "SSS", cost: 40000, desc: "十二时空最强的异能体质。你集结了风火雷电雨五种原位异能，手持铁克无极，是维护时空秩序的终极兵器。", type: "exclusive"},
                    {name: "鬼龙/鬼凤(双重人格)", color: "A", cost: 1800, desc: "你体内住着一个狂拽酷炫的第二人格。当你撕下封龙贴，战力指数会暴增，性格也会变得极度嚣张和好战。", type: "exclusive"},
                    {name: "神行者步法", color: "A", cost: 2000, desc: "神行九转，令人抓狂。你的速度快到可以戏弄时间，敌人连你的衣角都摸不到，是游击战的巅峰身法。", type: "exclusive"},
                    {name: "洗魂曲", color: "S", cost: 3200, desc: "叶赫那拉家的镇魔三部曲之一。弹奏此曲可以洗去魔化异能行者的魔性，废掉他们的武功，是专门针对魔道的杀招。", type: "exclusive"},
                    {name: "断肠人的摊位", color: "C", cost: 150, desc: "你经营着一个神秘的摊位，能做出各种诡异但美味的食物（如大肠面线）。你消息灵通，是江湖情报中心。", type: "exclusive"},
                    {name: "金笔点龙", color: "SS", cost: 8000, desc: "一本预言未来的漫画书。虽然看的人会头痛欲裂，但它记录了过去未来的一切。拥有它，你就拥有了剧本。", type: "exclusive"},
                    {name: "跨时空手机", color: "B", cost: 500, desc: "一部能联系其他时空（如铁时空、银时空）的手机。这让你能呼叫外援，或者获取其他时空的黑科技。", type: "exclusive"},
                    {name: "速还针", color: "B", cost: 600, desc: "一种细如牛毛的暗器，能封锁敌人的战力指数。虽然杀伤力不大，但阴人效果一流，让人防不胜防。", type: "exclusive"}
                ]
            },
            {
                name: "260.霹雳布袋戏",
                desc: "苦境中原，三教先天，武林争霸。素还真、一页书、叶小钗。这是一个诗号震天、偶戏武侠、神魔乱舞的高武世界。",
                boss: "弃天帝, 波旬, 厄祸, 八歧邪神, 死神",
                identities: [
                    { name: "琉璃仙境的扫地童子", items: "一把拂尘, 一壶莲花茶" },
                    { name: "魔界的小兵", items: "鬼面具, 一把魔刀" },
                    { name: "儒门天下的儒生", items: "一把折扇, 一本论语" },
                    { name: "退隐江湖的铸剑师", items: "铁锤, 一块稀有矿石" },
                    { name: "苦境中原的无辜路人", items: "包袱, 一脸惊恐(随时会被余波震死)" }
                ],
                talents: [
                    {name: "素还真(清香白莲)", color: "SSS", cost: 50000, desc: "半神半圣亦半仙，全儒全道是全贤。你拥有绝顶的智慧和武学，精通医卜星相，且拥有无数化身和复活手段，是苦境的支柱。", type: "exclusive"},
                    {name: "一页书(百世经纶)", color: "SSS", cost: 48000, desc: "笑尽英雄。你拥有刚猛无铸的佛门极招（如天龙吼），性格嫉恶如仇。只要你出场，基本上反派就要倒霉了。", type: "exclusive"},
                    {name: "叶小钗(刀狂剑痴)", color: "SS", cost: 8500, desc: "你无法言语，但你的刀剑替你说话。你领悟了心剑之境，意志力极其顽强，是素还真最坚定的战友。", type: "exclusive"},
                    {name: "弃天帝(毁灭之神)", color: "SSS", cost: 100000, desc: "异度魔界创始魔皇。你拥有毁灭世界的神力（神之手、神之焰），凡人无法直视你的威光。你的降临意味着末日。", type: "exclusive"},
                    {name: "三教顶峰(先天)", color: "SS", cost: 9000, desc: "你拥有儒道释三教顶峰的修为。无论是疏楼龙宿的华丽、剑子仙迹的幽默还是佛剑分说的杀生为护生，你都是武林的一方霸主。", type: "exclusive"},
                    {name: "化光遁术", color: "A", cost: 2000, desc: "布袋戏特色。打不过就化作一道光飞走。这是一种极高明的逃生术，让你在面对强敌时总能留得青山在。", type: "exclusive"},
                    {name: "诗号气场", color: "B", cost: 500, desc: "出场自带BGM和诗号。在你念诗期间，敌人会莫名其妙地停止攻击听你念完，且你的全属性提升20%。", type: "exclusive"},
                    {name: "吸元大法", color: "S", cost: 3500, desc: "你可以吸取他人的功力为己用。在苦境，这是一个快速变强但也极易入魔的法门，通常是反派标配。", type: "exclusive"},
                    {name: "铸剑神术", color: "A", cost: 1500, desc: "你精通铸造神兵利器。无论是斩龙的刀还是诛神的剑，只要有材料，你都能打造出来，引来无数高手争抢。", type: "exclusive"},
                    {name: "复活甲(素氏)", color: "SS", cost: 7000, desc: "你掌握了某种复活秘术（如莲花化身、换心术）。在这个便当满天飞的世界，这简直是第二条命。", type: "exclusive"},
                    {name: "魔佛波旬(三体)", color: "SS", cost: 9500, desc: "你拥有三位一体的形态（智、力、速）。三人合体时天下无敌，分开时也能独当一面，极难被彻底消灭。", type: "exclusive"},
                    {name: "八部龙神火", color: "S", cost: 4000, desc: "一页书的禁招。召唤八条火龙焚烧一切，威力足以毁天灭地，但对施术者身体负担极大。", type: "exclusive"},
                    {name: "琉璃仙境房产", color: "C", cost: 1000, desc: "你拥有琉璃仙境的居住权。这里风景优美，灵气充沛，但经常会被各路反派拆迁，维修费极高。", type: "exclusive"},
                    {name: "前辈(高危职业)", color: "D", cost: 50, desc: "你被尊称为‘前辈’。在苦境，这通常意味着你是用来衬托新人的垫脚石，死亡率极高。", type: "exclusive"},
                    {name: "狂龙八斩法", color: "A", cost: 1800, desc: "乱世狂刀的绝学。刀法霸道狂放，配合狮头宝刀，能斩断一切阻碍，尽显男儿热血。", type: "exclusive"}
                ]
            },
                      {
                name: "261.红楼梦",
                desc: "金陵十二钗的悲剧轮回，钟鸣鼎食之家的末路。这是一个由情债、家族政治和封建礼教编织的牢笼。表面是烈火烹油之盛，内里是白骨如山之悲。",
                boss: "警幻仙子, 贾母(家族意志), 皇帝(皇权)",
                identities: [
                    { name: "大观园倒夜香的粗使丫鬟", items: "一个充满异味的木桶, 一身打补丁的粗布衣裳" },
                    { name: "贾府旁支被遗忘的穷亲戚", items: "一件洗得发白的旧长衫, 一张写着借钱理由的草稿" },
                    { name: "宁国府马棚里的马夫", items: "一把掉毛的马刷, 一身洗不掉的马粪味" },
                    { name: "被拐子拐卖的戏班学徒", items: "一根练功用的木棍, 满身的淤青" },
                    { name: "铁槛寺门口的乞丐", items: "一个缺角的破碗, 一根用来驱狗的打狗棒" }
                ],
                talents: [
                    {name: "绛珠仙草(残根)", color: "SS", cost: 8000, desc: "你前世是灵河岸边的绛珠草，虽无黛玉之才情，但天生拥有极高的灵性与对草木的亲和力，眼泪能洗涤灵魂。", type: "exclusive"},
                    {name: "通灵宝玉(碎片)", color: "S", cost: 3500, desc: "你出生时口含一块碎玉，虽不及正品，但能辟邪除祟，偶尔能预知家族的兴衰祸福，对精神攻击有抗性。", type: "exclusive"},
                    {name: "王熙凤的算盘", color: "A", cost: 900, desc: "你拥有杀伐决断的管理才能和精明的经济头脑，能从石头里榨出油来，管理领地或店铺时收益翻倍。", type: "exclusive"},
                    {name: "刘姥姥的处世智慧", color: "B", cost: 400, desc: "大智若愚，能屈能伸。在面对比自己地位高的人时，极易获得对方的好感或怜悯，从而化险为夷。", type: "exclusive"},
                    {name: "冷香丸体质", color: "A", cost: 1200, desc: "你自幼服用秘方，身体散发异香，对热毒类疾病和火焰伤害有极高抗性，且气质清冷，易吸引异性。", type: "exclusive"},
                    {name: "诗词歌赋(精通)", color: "B", cost: 300, desc: "在这个文采即是面子的世界，你出口成章，能通过诗会迅速提升社会地位，获得贵族赏识。", type: "exclusive"},
                    {name: "焦大的醉骂", color: "C", cost: 150, desc: "当你喝醉时，敢于说出别人不敢说的真话，虽然容易挨打，但有几率震慑住心虚的小人。", type: "exclusive"},
                    {name: "红楼梦断(诅咒)", color: "E", cost: 50, desc: "黑色天赋。你注定会经历家破人亡的惨剧，所有亲近之人都将离你而去，命运多舛。", type: "exclusive"},
                    {name: "风月宝鉴(背面)", color: "S", cost: 2500, desc: "你持有风月宝鉴，只能看背面。虽然画面恐怖，但能通过观想骷髅红粉来治疗绝症，甚至吸取他人的生命力。", type: "exclusive"},
                    {name: "太虚幻境引路人", color: "SSS", cost: 15000, desc: "你能自由出入太虚幻境，查阅金陵十二钗的判词，甚至改写生死簿上的定数，掌握命运的因果律。", type: "exclusive"},
                    {name: "贾府厨艺", color: "C", cost: 120, desc: "你掌握了茄鲞等繁琐菜式的做法，能做出顶级的贵族美食，是讨好权贵和恢复体力的绝佳手段。", type: "exclusive"},
                    {name: "戏子身段", color: "B", cost: 250, desc: "你拥有极佳的柔韧性和伪装能力，擅长易容和模仿他人声音，适合潜入和刺杀。", type: "exclusive"},
                    {name: "醉金刚的义气", color: "C", cost: 180, desc: "你虽然地位低微，但义薄云天，容易结交江湖上的奇人异士，关键时刻能得到意外的帮助。", type: "exclusive"},
                    {name: "秦可卿的托梦", color: "A", cost: 750, desc: "你在睡梦中能预见家族未来的重大危机，获得提前布局的时间，智力属性获得大幅加成。", type: "exclusive"},
                    {name: "补天石遗志", color: "SSS", cost: 20000, desc: "你体内觉醒了娲皇补天石的真正力量，拥有重塑世界规则的潜能，无视一切位面压制。", type: "exclusive"}
                ]
            },
            {
                name: "262.水浒传",
                desc: "北宋末年，奸臣当道，民不聊生。这是一个忠义与背叛并存、大碗喝酒大块吃肉的江湖世界。天罡地煞星辰下凡，掀起腥风血雨。",
                boss: "高俅, 蔡京, 方腊, 曾头市史文恭",
                identities: [
                    { name: "阳谷县卖炊饼的侏儒", items: "一担沉重的炊饼挑子, 一顶绿油油的帽子" },
                    { name: "孟州牢城的配军", items: "沉重的枷锁, 杀威棒留下的伤痕" },
                    { name: "十字坡人肉包子铺的伙计", items: "一把磨得飞快的剔骨刀, 一盆不明肉馅" },
                    { name: "生辰纲被劫后的逃兵", items: "断裂的朴刀, 满身的冷汗" },
                    { name: "东京街头的泼皮", items: "一身赖皮气, 几个偷来的铜板" }
                ],
                talents: [
                    {name: "天魁星(呼保义)", color: "SS", cost: 9000, desc: "天生的领袖气质，能让英雄豪杰纳头便拜。无论你做什么，总有人觉得你是为了大义，极易组建势力。", type: "exclusive"},
                    {name: "倒拔垂杨柳(神力)", color: "S", cost: 3200, desc: "拥有花和尚鲁智深般的怪力，能徒手撼动巨树，力量属性突破人类极限，近战破坏力惊人。", type: "exclusive"},
                    {name: "神行太保(甲马)", color: "A", cost: 850, desc: "绑上甲马符，日行八百里。你的移动速度极快，适合侦查、逃跑和突袭，无视地形阻碍。", type: "exclusive"},
                    {name: "入云龙道法", color: "SS", cost: 7500, desc: "掌握公孙胜的五雷天心正法，能呼风唤雨，召唤黄巾力士，在这个低魔世界属于降维打击。", type: "exclusive"},
                    {name: "黑旋风(狂暴)", color: "A", cost: 1500, desc: "进入战斗状态后理智下降，痛觉消失，攻击力大幅提升。双斧在手，如绞肉机般收割战场。", type: "exclusive"},
                    {name: "智多星(谋略)", color: "S", cost: 2800, desc: "算无遗策，擅长布局和阴谋。能轻易看穿敌人的陷阱，并制定出绝户计，智力属性极高。", type: "exclusive"},
                    {name: "浪里白条(水性)", color: "B", cost: 500, desc: "在水中如履平地，能在水下闭气极长时间，水战能力翻倍，能凿穿敌人的战船。", type: "exclusive"},
                    {name: "鼓上蚤(轻功)", color: "B", cost: 450, desc: "身轻如燕，擅长飞檐走壁和偷盗。能潜入戒备森严的府邸，盗取关键任务物品。", type: "exclusive"},
                    {name: "蒙汗药专精", color: "C", cost: 200, desc: "你精通各类迷药的配置和下毒手法，能让人在不知不觉中倒下，是行走江湖的阴招。", type: "exclusive"},
                    {name: "好汉歌(BGM)", color: "C", cost: 100, desc: "当你大吼一声时，气势提升，周围友军士气大振，恐惧感消除。", type: "exclusive"},
                    {name: "潘金莲的诱惑", color: "B", cost: 300, desc: "魅力属性大幅提升，对异性有极强的吸引力，但也容易招惹杀身之祸和流言蜚语。", type: "exclusive"},
                    {name: "五虎将(骑术)", color: "A", cost: 1000, desc: "精通马战，人马合一。在骑乘状态下，冲锋威力剧增，能万军丛中取敌将首级。", type: "exclusive"},
                    {name: "神医安道全", color: "S", cost: 2200, desc: "只要还有一口气，就能救回来。精通金针刺穴和外科手术，能移除大部分负面状态（包括黥刑）。", type: "exclusive"},
                    {name: "九天玄女天书", color: "SSS", cost: 25000, desc: "获得宋江梦中所得的天书三卷，记载了究极的兵法阵图和改朝换代的神术，通晓天机。", type: "exclusive"},
                    {name: "替天行道(大义)", color: "SS", cost: 6000, desc: "你的行动被赋予正义性，击杀恶人或贪官时获得双倍经验和声望，且不受官府通缉的负面影响。", type: "exclusive"}
                ]
            },
            {
                name: "263.三国演义",
                desc: "东汉末年分三国，烽火连天不休。这是一个英雄辈出、谋士如云的时代。权谋、兵法、武勇，三者得一可安天下。",
                boss: "曹操, 司马懿, 左慈, 吕布",
                identities: [
                    { name: "黄巾军溃败后的流民", items: "一条黄头巾(残), 半个发霉的馒头" },
                    { name: "洛阳城外的樵夫", items: "一把钝斧头, 一捆卖不出去的柴火" },
                    { name: "徐州被屠城后的幸存孤儿", items: "带血的布娃娃, 满腔的仇恨" },
                    { name: "袁术军中的伙头兵", items: "一口大黑锅, 只有稀粥的粮袋" },
                    { name: "荆州乡下的私塾书童", items: "几卷残破竹简, 一支秃笔" }
                ],
                talents: [
                    {name: "乱世奸雄(曹操)", color: "SS", cost: 8800, desc: "宁教我负天下人。极高的统御力和政治手腕，多疑但能识人。对精神控制类技能免疫，麾下将领不易背叛。", type: "exclusive"},
                    {name: "武圣(关羽)", color: "SS", cost: 8500, desc: "义薄云天，刀法通神。前三刀攻击力暴击率100%，拥有“温酒斩华雄”的气势，对敌方将领产生威慑。", type: "exclusive"},
                    {name: "卧龙(诸葛亮)", color: "SSS", cost: 12000, desc: "多智近妖。能夜观天象，借东风，摆八卦阵。智力属性满值，所有计谋成功率极大提升，能逆天改命。", type: "exclusive"},
                    {name: "鬼神之勇(吕布)", color: "S", cost: 4000, desc: "人中吕布，马中赤兔。单挑无敌，全属性大幅提升，但在计谋面前防御力降低，容易中美人计。", type: "exclusive"},
                    {name: "仁德(刘备)", color: "A", cost: 1800, desc: "哭出江山。极高的魅力和亲和力，容易触发隐藏剧情和招募名将，运气属性极高，总能逢凶化吉。", type: "exclusive"},
                    {name: "闭月(貂蝉)", color: "A", cost: 1500, desc: "倾国倾城，能施展连环计。对男性角色有绝对的魅惑控制力，能引发敌对势力内部的争斗。", type: "exclusive"},
                    {name: "神医(华佗)", color: "S", cost: 2500, desc: "掌握青囊书，能进行开颅手术。治疗效果惊人，能制作麻沸散，大幅提升军队的伤兵回复率。", type: "exclusive"},
                    {name: "冢虎(司马懿)", color: "SS", cost: 8200, desc: "鹰视狼顾，极度隐忍。随着时间推移，全属性缓慢增长。擅长防守反击，寿命极长，能熬死所有对手。", type: "exclusive"},
                    {name: "古之恶来(典韦)", color: "A", cost: 1200, desc: "忠诚的护卫，步战无双。当主公受到威胁时，攻击力和防御力翻倍，死战不退。", type: "exclusive"},
                    {name: "七步成诗(曹植)", color: "B", cost: 400, desc: "文采斐然，能在极短时间内通过文字创作获得灵感或解开谜题，容易获得文官集团的好感。", type: "exclusive"},
                    {name: "火计精通", color: "B", cost: 600, desc: "你对火攻有独到心得，在使用火类计谋或法术时，伤害范围和持续时间大幅增加。", type: "exclusive"},
                    {name: "藤甲兵(防御)", color: "B", cost: 500, desc: "装备藤甲，刀枪不入，物理防御极高。但极度畏火，受到火属性攻击时伤害翻倍。", type: "exclusive"},
                    {name: "太平要术(残卷)", color: "S", cost: 3000, desc: "张角所传道法，能撒豆成兵，符水治病。能蛊惑人心，快速在大规模人群中建立信仰。", type: "exclusive"},
                    {name: "锦帆贼(甘宁)", color: "A", cost: 1100, desc: "水陆两栖作战精通，擅长劫营和夜战。佩戴铃铛时，能对敌人造成心理压力，降低敌方士气。", type: "exclusive"},
                    {name: "传国玉玺(伪)", color: "C", cost: 200, desc: "一块仿制的玉玺，虽然没有真品的神力，但能用来诈骗诸侯，或者在关键时刻当做板砖砸人。", type: "exclusive"}
                ]
            },
            {
                name: "264.西游记 (原著)",
                desc: "四大部洲，神佛漫天。这是一个妖魔吃人、神仙冷漠的残酷神话世界。长生不老是所有存在的终极追求，取经之路满是算计。",
                boss: "如来佛祖, 玉皇大帝, 太上老君, 狮驼岭三魔",
                identities: [
                    { name: "五行山下的土地公", items: "一根烂拐杖, 几个供奉的野果" },
                    { name: "车迟国的苦力和尚", items: "沉重的砖石, 破烂的僧袍" },
                    { name: "狮驼岭的人类食材", items: "被洗剥干净的身体, 绝望的眼神" },
                    { name: "高老庄的倒插门长工", items: "一把钉耙(农具), 一身力气" },
                    { name: "东海龙宫的巡海夜叉(临时工)", items: "一把分水叉, 丑陋的面具" }
                ],
                talents: [
                    {name: "齐天大圣(灵明石猴)", color: "SSS", cost: 50000, desc: "天产石猴，不在五行中。拥有金刚不坏之身，火眼金睛，七十二变。战斗力随怒气无限攀升，敢于挑战天庭。", type: "exclusive"},
                    {name: "九转金丹", color: "S", cost: 4500, desc: "太上老君炼制的仙丹。服用后立地成仙，全属性暴涨，获得长生不老之躯，法力生生不息。", type: "exclusive"},
                    {name: "天蓬元帅(水军统领)", color: "SS", cost: 8000, desc: "掌管八万水军，精通三十六变。虽然好色懒惰，但在水中战斗力极强，且皮糙肉厚，抗击打能力一流。", type: "exclusive"},
                    {name: "卷帘大将(忠诚)", color: "A", cost: 1500, desc: "沉默寡言，绝对忠诚。在保护目标时，防御力提升300%。擅长水战，拥有流沙河掌控权。", type: "exclusive"},
                    {name: "唐僧肉(体质)", color: "S", cost: 3000, desc: "你的血肉具有长生不老的功效，极度吸引妖魔鬼怪。虽然自身战力极低，但运气极好，总有贵人相助。", type: "exclusive"},
                    {name: "三昧真火", color: "SS", cost: 7500, desc: "红孩儿的绝技，水扑不灭的真火。对灵魂和肉体造成双重灼烧，能烧穿金身，极具破坏力。", type: "exclusive"},
                    {name: "袖里乾坤", color: "SS", cost: 9000, desc: "镇元大仙的神通。袖袍一展，可装天地万物。最强的控制技能，一旦被收进去，大罗金仙也难逃。", type: "exclusive"},
                    {name: "紧箍咒(控制)", color: "A", cost: 2000, desc: "掌握紧箍咒的念法，能对佩戴紧箍的目标造成无法忍受的剧痛，绝对控制强力随从。", type: "exclusive"},
                    {name: "女儿国河水", color: "C", cost: 300, desc: "喝下后会怀孕，无论男女。这是一种诡异的因果律武器，能让强大的敌人瞬间失去战斗力。", type: "exclusive"},
                    {name: "地煞七十二变", color: "S", cost: 5000, desc: "变化无穷，躲避三灾。能变成任何看到的事物，并获得其特性。潜入、侦查、逃生的神技。", type: "exclusive"},
                    {name: "筋斗云", color: "S", cost: 4000, desc: "一个筋斗十万八千里。世间最快的移动手段，能瞬间脱离战场，或在世界各地穿梭。", type: "exclusive"},
                    {name: "人参果(半个)", color: "A", cost: 2500, desc: "草还丹，闻一闻活三百六十岁，吃一个活四万七千岁。大幅增加寿命和潜能，治愈一切暗伤。", type: "exclusive"},
                    {name: "白骨精的画皮", color: "B", cost: 800, desc: "能通过吸食精气维持美貌，擅长伪装和离间计。死后可舍弃皮囊逃生，极难彻底杀死。", type: "exclusive"},
                    {name: "六耳猕猴(聆听)", color: "SSS", cost: 30000, desc: "善聆音，能察理，知前后，万物皆明。能窃听三界内的一切秘密，甚至模仿对手的技能。", type: "exclusive"},
                    {name: "大威天龙(法海乱入)", color: "A", cost: 1200, desc: "虽然画风不对，但你掌握了极强的降妖除魔手段。对妖族伤害加成200%，且自带BGM威慑。", type: "exclusive"}
                ]
            },
            {
                name: "265.聊斋志异",
                desc: "狐仙鬼怪，书生梦境。这是一个阴阳界限模糊的世界。破庙、荒坟、深山古刹，皆有异类栖息。人心往往比鬼神更可怕。",
                boss: "黑山老妖, 普渡慈航, 画皮鬼, 罗刹海市龙王",
                identities: [
                    { name: "郭北县的穷书生", items: "一盏快没油的灯笼, 几本湿透的经书" },
                    { name: "兰若寺外的拾荒者", items: "一个装死人骨头的坛子, 一把辟邪的桃木剑(假)" },
                    { name: "被狐妖吸干精气的路人", items: "干瘪的身体, 恍惚的精神" },
                    { name: "崂山脚下的求道者", items: "一本穿墙术(失败版), 满头的大包" },
                    { name: "罗刹海市的丑陋商人", items: "面目可憎的面具, 一袋不值钱的珍珠" }
                ],
                talents: [
                    {name: "九尾狐血统", color: "SS", cost: 7000, desc: "青丘狐族皇室血脉。天生魅惑众生，拥有九条命。精通幻术和火系法术，能号令群妖。", type: "exclusive"},
                    {name: "阴阳眼", color: "B", cost: 500, desc: "能看到常人看不见的鬼魂和妖气。虽然容易被惊吓，但也让你能提前发现危险，与鬼神沟通。", type: "exclusive"},
                    {name: "画皮(伪装)", color: "A", cost: 1200, desc: "你需要定期描绘人皮来维持外貌。能完美伪装成任何人，甚至模仿其气息，是完美的间谍天赋。", type: "exclusive"},
                    {name: "倩女幽魂(羁绊)", color: "S", cost: 2500, desc: "你拥有一种特殊的体质，极易吸引美丽的女鬼/男鬼依附。虽然会损耗阳气，但能获得强力的灵体守护。", type: "exclusive"},
                    {name: "崂山道术", color: "A", cost: 1500, desc: "掌握穿墙、隐身、剪纸成兵等实用法术。虽然威力不如正统仙法，但胜在诡异多变，防不胜防。", type: "exclusive"},
                    {name: "判官笔(仿)", color: "SS", cost: 6000, desc: "能勾画生死，对灵体造成毁灭性打击。写下名字可对目标造成诅咒伤害，甚至将其打入十八层地狱。", type: "exclusive"},
                    {name: "婴宁的笑声", color: "C", cost: 200, desc: "你的笑声具有感染力，能化解尴尬和敌意。爱笑的人运气不会太差，能稍微提升福源。", type: "exclusive"},
                    {name: "辟邪书卷", color: "B", cost: 400, desc: "你读过的圣贤书自带浩然正气。在面对低级鬼怪时，大声朗读文章能将其震退或灼伤。", type: "exclusive"},
                    {name: "罗刹海市审美", color: "C", cost: 150, desc: "在这个颠倒的世界，越丑越尊贵。你在丑陋生物眼中魅力无穷，容易在异类国度获得高位。", type: "exclusive"},
                    {name: "黑山老妖(契约)", color: "S", cost: 3500, desc: "你出卖灵魂给黑山老妖，换取了控制万千冤魂的能力。能召唤鬼卒大军，但死后灵魂将永受折磨。", type: "exclusive"},
                    {name: "席方平的意志", color: "A", cost: 1000, desc: "刚正不阿，死不低头。即便是阎王老子也敢告。精神抗性极高，无视威压和恐惧，对审判类技能免疫。", type: "exclusive"},
                    {name: "促织王(蟋蟀)", color: "C", cost: 100, desc: "你擅长捕捉和培养蟋蟀。在这个荒诞的世界，一只极品蟋蟀可能换来万贯家财，甚至官位。", type: "exclusive"},
                    {name: "索命梵音", color: "SS", cost: 6500, desc: "普渡慈航的妖术。通过诵经发出魔音，让听到的人陷入幻觉，被吸干血肉。大规模杀伤性音波攻击。", type: "exclusive"},
                    {name: "辛十四娘(仙缘)", color: "S", cost: 2800, desc: "拥有修成正果的潜质。虽然是妖身，但心存善念，行善积德可快速提升修为，最终飞升成仙。", type: "exclusive"},
                    {name: "狼妖变身", color: "B", cost: 600, desc: "能变身为凶残的狼妖，力量和敏捷大幅提升，但会变得嗜血。适合夜间战斗。", type: "exclusive"}
                ]
            },
            {
                name: "266.封神演义",
                desc: "商周更替，阐截争锋。这是一个法宝乱飞、阵法通天的仙侠末世。圣人之下皆蝼蚁，凡人军队只是炮灰。",
                boss: "鸿钧老祖, 通天教主, 元始天尊, 纣王(被妖狐魅惑)",
                identities: [
                    { name: "朝歌城外的奴隶苦工", items: "沉重的石块, 监工的鞭痕" },
                    { name: "羑里监狱的狱卒", items: "一把钥匙, 一碗给囚犯的剩饭" },
                    { name: "东海边的采珠人", items: "一把骨刀, 避水珠(劣质)" },
                    { name: "陈塘关的守门小兵", items: "生锈的长矛, 破烂的皮甲" },
                    { name: "截教外门弟子的童子", items: "一把扫帚, 偷学的一句口诀" }
                ],
                talents: [
                    {name: "三头六臂", color: "S", cost: 3500, desc: "哪吒的战斗形态。能同时使用六件兵器，攻击频率和防御面大幅增加，近战无死角。", type: "exclusive"},
                    {name: "八九玄功", color: "SSS", cost: 18000, desc: "杨戬的护体神功。肉身成圣，金刚不坏，万法不侵。拥有七十二变和极强的恢复能力，近战法师的巅峰。", type: "exclusive"},
                    {name: "打神鞭(伪)", color: "SS", cost: 6000, desc: "姜子牙的法宝仿品。对拥有神籍或封神榜上有名者造成巨额真实伤害，无视防御。", type: "exclusive"},
                    {name: "五色神光(孔宣)", color: "SSS", cost: 25000, desc: "圣人之下第一人。五色神光无物不刷，能收走敌人的任何法宝和兵器，强制解除武装。", type: "exclusive"},
                    {name: "土行孙(地行术)", color: "A", cost: 1200, desc: "只要脚踏大地，就能瞬间潜入地下移动。偷袭、刺杀、逃跑的神技，但要注意指地成钢符。", type: "exclusive"},
                    {name: "十绝阵图(残)", color: "S", cost: 4000, desc: "掌握部分十绝阵的布置方法。能利用地形布置杀阵，坑杀比自己强大的敌人。", type: "exclusive"},
                    {name: "申公豹的嘴", color: "A", cost: 1500, desc: "道友请留步。因果律武器，被你叫住的人往往会倒大霉。极高的忽悠能力，能把死人说活，活人说死。", type: "exclusive"},
                    {name: "雷震子双翼", color: "A", cost: 1000, desc: "背生风雷双翅，拥有极快的飞行速度和操控风雷的能力。空中作战优势巨大。", type: "exclusive"},
                    {name: "封神榜(无名)", color: "E", cost: 50, desc: "黑色天赋。你注定要死一次才能上榜成神。在肉身死亡前，运势极差，如同衰神附体。", type: "exclusive"},
                    {name: "落宝金钱(仿)", color: "S", cost: 3000, desc: "能击落敌人的法宝，但每次使用需要消耗大量的金钱或气运。氪金玩家的神技。", type: "exclusive"},
                    {name: "比干玲珑心", color: "SS", cost: 7000, desc: "七窍玲珑心，天生圣人。拥有看破一切幻术和谎言的能力，智力极高，但身体虚弱，且不能听见“无心”二字。", type: "exclusive"},
                    {name: "炮烙之刑(抗性)", color: "C", cost: 200, desc: "你曾经历过酷刑而不死，对火焰和疼痛有极高的耐受力，意志坚定。", type: "exclusive"},
                    {name: "酒池肉林", color: "C", cost: 150, desc: "在享受美食和美色时，恢复速度加倍。容易沉迷享乐，降低警惕性。", type: "exclusive"},
                    {name: "诛仙剑气(一道)", color: "SS", cost: 8500, desc: "体内封印着一道通天教主的诛仙剑气。释放时可斩断万物，甚至切开空间，但是一次性用品。", type: "exclusive"},
                    {name: "哪吒莲花身", color: "S", cost: 4500, desc: "魂魄依附于莲花，免疫所有针对灵魂的攻击和瘟疫毒素。没有血肉之躯的弱点。", type: "exclusive"}
                ]
            },
            {
                name: "267.镜花缘",
                desc: "海外异国，百花仙子。这是一个充满奇幻色彩和讽刺意味的世界。君子国、女儿国、两面国，光怪陆离。",
                boss: "武则天(心月狐), 百花仙子, 甚至连神兽都算不上",
                identities: [
                    { name: "两面国的乞丐", items: "两张不同的面具, 破烂的长袍" },
                    { name: "女儿国的男宠", items: "胭脂水粉, 锁链" },
                    { name: "君子国的奸商", items: "没人要的劣质商品, 一本《道德经》" },
                    { name: "黑齿国的牙医", items: "黑色的染料, 拔牙钳" },
                    { name: "海外荒岛的流浪者", items: "一块破木板, 几个野果" }
                ],
                talents: [
                    {name: "百花转世", color: "SS", cost: 6500, desc: "你是百花仙子之一转世。在花开时节或花丛中，全属性大幅提升。能操控植物，酿造百花酒。", type: "exclusive"},
                    {name: "两面三刀", color: "B", cost: 500, desc: "两面国特技。正面和善，背面阴险。你在进行背刺攻击时，伤害翻倍。擅长伪装情绪。", type: "exclusive"},
                    {name: "君子之风", color: "A", cost: 1000, desc: "在君子国熏陶出的气质。好让不争，反而能获得更多。交易时对方会主动降价，战斗时对方可能手下留情。", type: "exclusive"},
                    {name: "女儿国体质", color: "A", cost: 1200, desc: "男性体质大幅阴柔化，但敏捷和柔韧性提升。对女性角色的亲和力极高，容易被女性领袖看重。", type: "exclusive"},
                    {name: "多九公的博学", color: "B", cost: 600, desc: "见多识广，通晓海外各国的风土人情和弱点。自带翻译功能，能识别各种奇异生物。", type: "exclusive"},
                    {name: "无肠国饭量", color: "C", cost: 150, desc: "吃什么拉什么，完全不吸收。虽然永远处于饥饿状态，但也免疫绝大多数食物中毒。", type: "exclusive"},
                    {name: "穿胸国体质", color: "B", cost: 400, desc: "胸口有个大洞。心脏位置偏移，免疫针对心脏的致命一击。方便被人提着走。", type: "exclusive"},
                    {name: "黑齿美白", color: "C", cost: 100, desc: "你的牙齿漆黑如墨，在黑齿国被视为绝世美男/美女。但在其他地方可能会吓到人。", type: "exclusive"},
                    {name: "御风而行", color: "A", cost: 1500, desc: "能驾驭清风飞行，虽然速度不快，但姿态优雅。适合长途旅行和跨越海峡。", type: "exclusive"},
                    {name: "才女琴棋书画", color: "S", cost: 2000, desc: "精通四艺，能以琴音杀人，以棋局困敌，以书画成真。全方位的辅助和控制能力。", type: "exclusive"},
                    {name: "泣红亭主", color: "SS", cost: 7000, desc: "掌握命运悲剧的力量。能通过书写悲剧故事，让现实向着悲剧方向发展，操纵因果。", type: "exclusive"},
                    {name: "小蓬莱仙缘", color: "S", cost: 3000, desc: "有几率误入仙境，获得仙草或仙器。福源极高，容易触发隐藏奇遇。", type: "exclusive"},
                    {name: "聂耳国听力", color: "B", cost: 350, desc: "耳朵极大，能听到极远处的风吹草动。优秀的侦查能力，但害怕噪音攻击。", type: "exclusive"},
                    {name: "翼民国血统", color: "A", cost: 900, desc: "头长得像鸟，身长翅膀。天生的飞行种族，俯冲攻击威力巨大。", type: "exclusive"},
                    {name: "帝王之相(武则天)", color: "SSS", cost: 15000, desc: "拥有女皇威仪。能镇压一切男性角色的气场，号令天下。在政治斗争中立于不败之地。", type: "exclusive"}
                ]
            },
            {
                name: "268.天龙八部",
                desc: "北宋年间，宋辽夏大理并立。无人不冤，有情皆孽。这是一个武学巅峰与身世悲剧交织的世界。",
                boss: "扫地僧, 萧峰, 虚竹, 段誉, 天山童姥",
                identities: [
                    { name: "丐帮的八袋弟子(净衣派)", items: "一根打狗棒(仿), 破烂的百纳衣" },
                    { name: "星宿派的炮灰弟子", items: "一包化功散, 随时准备拍马屁的锣鼓" },
                    { name: "大理段氏的家臣", items: "一根钓鱼竿, 几块普洱茶砖" },
                    { name: "少林寺的烧火僧", items: "一本看不懂的经书, 一根烧火棍" },
                    { name: "聚贤庄的无名游侠", items: "一把卷刃的钢刀, 一碗断头酒" }
                ],
                talents: [
                    {name: "六脉神剑(段誉)", color: "SSS", cost: 18000, desc: "无形剑气，指哪打哪。机关枪般的远程输出，无视防御。但前期时灵时不灵，需要高深内力支持。", type: "exclusive"},
                    {name: "北冥神功(吸星)", color: "SS", cost: 9000, desc: "海纳百川，有容乃大。能吸取他人的内力为己用，内力越深厚防御越强。成长性极高的外挂。", type: "exclusive"},
                    {name: "降龙十八掌(萧峰)", color: "SS", cost: 8500, desc: "刚猛无俦，天下第一阳刚掌法。自带BGM，音响里没人能打败你。越战越勇，气势碾压。", type: "exclusive"},
                    {name: "斗转星移(慕容复)", color: "S", cost: 4000, desc: "以彼之道，还施彼身。能反弹敌人的招式和伤害。不仅是防御神技，更是借力打力的巅峰。", type: "exclusive"},
                    {name: "生死符(控制)", color: "A", cost: 2000, desc: "天山童姥绝技。将酒水化为薄冰打入穴道，求生不得求死不能。绝对的控制和拷问手段。", type: "exclusive"},
                    {name: "凌波微步", color: "S", cost: 3500, desc: "依卦象而行，动无常则。在战斗中几乎无法被击中，且走路就能增长内力。", type: "exclusive"},
                    {name: "易筋经", color: "SSS", cost: 15000, desc: "武学总纲，化腐朽为神奇。能洗髓伐毛，消除一切内伤和隐患，让任何平庸武学发挥出巨大威力。", type: "exclusive"},
                    {name: "小无相功", color: "S", cost: 3000, desc: "道家高深内功。能模拟天下任何武功，且威力更胜原版。只要知道招式，就能瞬间学会。", type: "exclusive"},
                    {name: "冰蚕寒毒", color: "A", cost: 1500, desc: "游坦之奇遇。体内蕴含至阴至寒的剧毒内力，触之即冻，攻击自带强力减速和持续伤害。", type: "exclusive"},
                    {name: "八荒六合唯我独尊功", color: "SS", cost: 7000, desc: "返老还童，长生不老。每三十年需重修一次，期间极度虚弱。但全盛时期威力无穷。", type: "exclusive"},
                    {name: "神木王鼎", color: "B", cost: 800, desc: "星宿派至宝。能吸引毒虫，辅助修炼毒功。是成为用毒高手的捷径，但容易被反噬。", type: "exclusive"},
                    {name: "枯荣禅功", color: "A", cost: 1800, desc: "半枯半荣，亦枯亦荣。防御力极强，能通过假死骗过敌人，对火焰抗性极高。", type: "exclusive"},
                    {name: "曼陀罗山庄园艺", color: "C", cost: 150, desc: "你精通茶花种植，能做花肥。虽然对战斗无用，但能讨好王夫人，获得进入琅嬛玉洞的机会。", type: "exclusive"},
                    {name: "四大恶人(恶名)", color: "B", cost: 500, desc: "恶名远扬。正派人士见你就打，但邪派人士对你敬畏有加。容易接取暗杀任务。", type: "exclusive"},
                    {name: "扫地僧(悟性)", color: "SSS", cost: 20000, desc: "大智若愚，看破红尘。拥有看穿一切武学破绽的慧眼，三尺气墙防御无敌。", type: "exclusive"}
                ]
            },
            {
                name: "269.笑傲江湖",
                desc: "正邪不两立，权谋胜武功。这是一个没有绝对正义，只有利益交换的政治江湖。五岳剑派内斗不止，日月神教野心勃勃。",
                boss: "东方不败, 任我行, 岳不群, 左冷禅",
                identities: [
                    { name: "福威镖局的趟子手", items: "一面破镖旗, 一匹瘦马" },
                    { name: "华山派的扫地杂役", items: "一把大扫帚, 偷看到的剑谱残页" },
                    { name: "黑木崖下的哑巴仆人", items: "一篮绣花针, 无法说话的嘴" },
                    { name: "恒山派的俗家弟子", items: "一串佛珠, 几瓶天香断续胶" },
                    { name: "衡山城里的卖艺人", items: "一把二胡, 悲惨的身世" }
                ],
                talents: [
                    {name: "葵花宝典(残)", color: "SS", cost: 9500, desc: "欲练此功，必先自宫。速度快到极致，如鬼似魅。一枚绣花针可破万法。代价是失去繁衍能力。", type: "exclusive"},
                    {name: "独孤九剑", color: "SSS", cost: 16000, desc: "无招胜有招。只攻不守，破尽天下武功。对使用兵器的敌人有绝对压制力，悟性要求极高。", type: "exclusive"},
                    {name: "吸星大法", color: "S", cost: 4000, desc: "任我行绝学。强行吸取他人内力，但存在反噬风险，需要异种真气调和。速成高手的捷径。", type: "exclusive"},
                    {name: "辟邪剑法", color: "S", cost: 5000, desc: "葵花宝典的简化版。同样需要自宫。剑招诡异迅捷，前期无敌，适合快速复仇。", type: "exclusive"},
                    {name: "紫霞神功", color: "A", cost: 2000, desc: "华山九功，第一紫霞。运功时脸上紫气缭绕，爆发力强，能化解异种真气，养生效果佳。", type: "exclusive"},
                    {name: "笑傲江湖曲", color: "A", cost: 1200, desc: "琴箫合奏，曲洋刘正风绝响。能通过音乐干扰敌人心智，或治疗内伤。遇到知音时战力翻倍。", type: "exclusive"},
                    {name: "五毒教蛊术", color: "B", cost: 800, desc: "蓝凤凰亲传。擅长下蛊和解毒，能控制毒虫攻击。虽然正面战斗力不强，但阴人无敌。", type: "exclusive"},
                    {name: "君子剑(伪君子)", color: "A", cost: 1500, desc: "岳不群真传。表面正气凛然，满口仁义道德，背地里阴险毒辣。极易欺骗正道人士获得信任。", type: "exclusive"},
                    {name: "寒冰真气", color: "S", cost: 2500, desc: "左冷禅自创。至阴至寒，专门克制吸星大法。被击中者经脉冻结，行动迟缓。", type: "exclusive"},
                    {name: "田伯光的轻功", color: "B", cost: 600, desc: "万里独行。短距离爆发移动极快，擅长在狭小空间腾挪。虽然名声不好，但逃命一流。", type: "exclusive"},
                    {name: "桃谷六仙(嘴遁)", color: "C", cost: 300, desc: "六张嘴一起说话，逻辑混乱，能把对手吵晕甚至吵死。精神污染攻击。", type: "exclusive"},
                    {name: "冲灵剑法", color: "C", cost: 150, desc: "青梅竹马的剑法。威力一般，但能勾起令狐冲的回忆，对特定剧情人物有奇效。", type: "exclusive"},
                    {name: "易筋经(方证版)", color: "SS", cost: 8000, desc: "少林正宗，中正平和。化解一切异种真气的反噬，是修炼吸星大法后的唯一救命稻草。", type: "exclusive"},
                    {name: "日月神教教主", color: "SS", cost: 7000, desc: "千秋万载，一统江湖。拥有极强的号召力，服用三尸脑神丹的部下绝对忠诚。", type: "exclusive"},
                    {name: "酒鬼体质", color: "C", cost: 100, desc: "越喝越精神。喝酒后疼痛感降低，胆量增加，容易和令狐冲成为兄弟。", type: "exclusive"}
                ]
            },
            {
                name: "270.神雕侠侣",
                desc: "情花之毒，十六年约。这是一个关于等待、残缺和家国情怀的世界。蒙古铁骑压境，襄阳城岌岌可危。",
                boss: "金轮法王, 忽必烈, 李莫愁, 公孙止",
                identities: [
                    { name: "绝情谷的采花仆人", items: "一篮情花(有毒), 绝情丹(半颗)" },
                    { name: "古墓派门口的弃婴", items: "一块玉佩, 几瓶玉蜂浆" },
                    { name: "襄阳城的守城死士", items: "一把卷刃的长枪, 一封家书" },
                    { name: "全真教被欺负的道童", items: "一本入门剑谱, 满脸灰尘" },
                    { name: "蒙古军营的汉人奴隶", items: "沉重的脚镣, 一把喂马的草料" }
                ],
                talents: [
                    {name: "玄铁重剑(剑意)", color: "SS", cost: 8800, desc: "重剑无锋，大巧不工。需要极大的臂力，每一击都带有粉碎效果。一力降十会，无视花哨招式。", type: "exclusive"},
                    {name: "黯然销魂掌", color: "SS", cost: 9000, desc: "杨过自创。只有在极度悲伤时才能发挥最大威力。威力堪比降龙十八掌，招式匪夷所思。", type: "exclusive"},
                    {name: "龙象般若功", color: "S", cost: 5000, desc: "密宗护法神功。每练一层，力量增加一龙一象之力。大成后拥有十龙十象之力，近战碾压。", type: "exclusive"},
                    {name: "玉女心经", color: "A", cost: 2500, desc: "古墓派绝学。专门克制全真武功。需要两人合练（或特殊方法）。身法轻灵，出招极快。", type: "exclusive"},
                    {name: "左右互搏", color: "S", cost: 3500, desc: "周伯通绝技。一心二用，双手同时使出不同武功。相当于两个人打一个人，瞬间爆发力翻倍。", type: "exclusive"},
                    {name: "九阴真经(残)", color: "SS", cost: 7500, desc: "天下武学总纲。虽然不全，但包含移魂大法、解穴秘诀等实用技能。内力增长极快。", type: "exclusive"},
                    {name: "蛤蟆功", color: "A", cost: 2000, desc: "欧阳锋绝学。以静制动，蓄力爆发。受到攻击时自动反击，威力巨大，但样子不太雅观。", type: "exclusive"},
                    {name: "冰魄银针", color: "B", cost: 800, desc: "李莫愁暗器。剧毒无比，中者立毙。针身细小，极难防御。是杀人越货的利器。", type: "exclusive"},
                    {name: "神雕伙伴", color: "S", cost: 3000, desc: "拥有一只通人性的大雕作为伙伴。能飞行载人，辅助战斗，还能指导你修炼重剑。", type: "exclusive"},
                    {name: "情花毒(体质)", color: "E", cost: 100, desc: "黑色天赋。体内潜伏情花毒，动情即痛。限制了你的感情线，但也能以此要挟他人。", type: "exclusive"},
                    {name: "弹指神通", color: "A", cost: 1500, desc: "黄药师绝技。指力通神，可远距离点穴或击碎兵器。优雅从容，高手风范。", type: "exclusive"},
                    {name: "打狗棒法", color: "S", cost: 2800, desc: "丐帮镇帮之宝。招式精妙绝伦，专打恶狗。配合心法，是技巧流的巅峰。", type: "exclusive"},
                    {name: "裘千尺的枣核钉", color: "B", cost: 600, desc: "口吐枣核，威力如子弹。出其不意，防不胜防。适合在被束缚或失去双手时使用。", type: "exclusive"},
                    {name: "襄阳守卫者", color: "A", cost: 1200, desc: "侠之大者，为国为民。在保卫据点或城市时，全属性提升20%，且容易获得官方势力支持。", type: "exclusive"},
                    {name: "五轮大转", color: "A", cost: 1800, desc: "金轮法王招式。操控金银铜铁铅五个轮子进行远程切割。攻防一体，难以近身。", type: "exclusive"}
                ]
            },
                      {
                name: "271.倚天屠龙记",
                desc: "元朝末年，群雄并起。武林至尊，宝刀屠龙，号令天下，莫敢不从，倚天不出，谁与争锋。江湖与江山的争夺交织，正邪两道的界限模糊不清。",
                boss: "张无忌, 成昆, 波斯三使, 元兵精锐",
                identities: [
                    { name: "蝴蝶谷的采药童子", items: "一个小药锄, 一筐普通的草药" },
                    { name: "明教洪水旗的普通教众", items: "一个喷水筒, 一件破损的明教教服" },
                    { name: "武当山下的烧火道童", items: "一根烧火棍, 一本读不懂的道经" },
                    { name: "大都街头的落魄乞丐", items: "一个缺口的破碗, 一根打狗棒的仿品" },
                    { name: "峨眉派的男性杂役", items: "一把扫帚, 一块擦剑布" }
                ],
                talents: [
                    {name: "寒毒入体(玄冥)", color: "黑色", cost: 50, desc: "你自幼身中玄冥神掌的寒毒，每日午夜寒毒发作，痛苦难当，寿命极短，体质极差。", type: "exclusive"},
                    {name: "优柔寡断", color: "灰色", cost: 100, desc: "你在面对感情和大事时总是犹豫不决，容易错失良机，甚至被他人利用。", type: "exclusive"},
                    {name: "粗通医理", color: "白色", cost: 150, desc: "你跟随胡青牛学过几天皮毛，能识别常见草药，治疗简单的跌打损伤。", type: "exclusive"},
                    {name: "九阳残卷(少林)", color: "蓝色", cost: 800, desc: "你无意中习得了少林九阳功的一部分，内力根基扎实，对于阴寒武功有一定抵抗力。", type: "exclusive"},
                    {name: "乾坤大挪移(第一层)", color: "紫色", cost: 1500, desc: "你悟性极高，练成了乾坤大挪移第一层，能初步运劲用力，激发自身潜力。", type: "exclusive"},
                    {name: "倚天剑气(残)", color: "绿色", cost: 300, desc: "你曾近距离感受过倚天剑的剑气，对剑道有了一丝感悟，剑法威力小幅提升。", type: "exclusive"},
                    {name: "明教教义", color: "白色", cost: 120, desc: "你熟读明教教义，在面对明教中人时，更容易获得好感或避免杀身之祸。", type: "exclusive"},
                    {name: "武当梯云纵(入门)", color: "蓝色", cost: 700, desc: "你偷学了武当派的轻功绝学，虽然只是入门，但攀高走低已如履平地。", type: "exclusive"},
                    {name: "圣火令神功(残篇)", color: "紫色", cost: 1800, desc: "你获得了刻有波斯武学的圣火令碎片，招式怪异无比，令人防不胜防。", type: "exclusive"},
                    {name: "太极真意(雏形)", color: "金色", cost: 8000, desc: "你观摩张三丰演练太极拳，领悟了以柔克刚、后发制人的武学至理。", type: "exclusive"},
                    {name: "九阴白骨爪(速成)", color: "蓝色", cost: 600, desc: "你修炼了周芷若版本的速成九阴白骨爪，威力阴毒，但容易走火入魔。", type: "exclusive"},
                    {name: "狮吼功(震慑)", color: "绿色", cost: 400, desc: "你的嗓门极大，运足中气大吼一声，能让普通人短暂失神。", type: "exclusive"},
                    {name: "屠龙刀(伪)", color: "灰色", cost: 180, desc: "一把仿造的屠龙刀，虽然沉重锋利，但没有磁性，也不能号令天下。", type: "exclusive"},
                    {name: "九阳神功(完整)", color: "红色", cost: 30000, desc: "天下至刚至阳的内功，百毒不侵，金刚不坏，内力生生不息，是所有阴寒武功的克星。", type: "exclusive"},
                    {name: "武穆遗书(兵法)", color: "金色", cost: 9000, desc: "岳飞留下的兵法奇书，得此书者可运筹帷幄，决胜千里，拥有争夺天下的资本。", type: "exclusive"}
                ]
            },
            {
                name: "272.鹿鼎记",
                desc: "清朝康熙年间，一个出身市井的混混韦小宝，凭借机智和运气，在朝廷、天地会、神龙教之间周旋。这是一个反武侠的世界，权谋与厚黑学比武功更重要。",
                boss: "康熙, 洪安通, 鳌拜, 陈近南",
                identities: [
                    { name: "丽春院的倒茶龟公", items: "一条脏毛巾, 一壶劣质茶水" },
                    { name: "皇宫御膳房的小太监", items: "一把切菜刀, 半个偷藏的馒头" },
                    { name: "天地会青木堂的马夫", items: "一根马鞭, 一个天地会的腰牌(低级)" },
                    { name: "神龙教的白衣少年", items: "一包化尸粉(微量), 一本神龙教条" },
                    { name: "扬州街头的小混混", items: "两颗灌铅的骰子, 一把石灰粉" }
                ],
                talents: [
                    {name: "目不识丁", color: "黑色", cost: 20, desc: "你大字不识一个，不仅无法阅读秘籍，连看告示都会会错意，极易被文人欺骗。", type: "exclusive"},
                    {name: "贪财好色", color: "灰色", cost: 150, desc: "你对金钱和美色没有抵抗力，极易因此中计或背叛，但也容易融入腐败环境。", type: "exclusive"},
                    {name: "市井智慧", color: "绿色", cost: 350, desc: "你精通溜须拍马、见风使舵，在复杂的官场和江湖混战中总能保住小命。", type: "exclusive"},
                    {name: "神行百变(全本)", color: "金色", cost: 9500, desc: "铁剑门木桑道人的绝技，天下第一逃跑轻功，滑如泥鳅，只要想跑，没人抓得住你。", type: "exclusive"},
                    {name: "化骨绵掌(阴毒)", color: "紫色", cost: 1800, desc: "假太后毛东珠的绝学，中掌者外表无伤，全身骨骼却会慢慢碎裂，阴毒无比。", type: "exclusive"},
                    {name: "满语精通", color: "白色", cost: 100, desc: "你精通满语，在清朝官场和皇宫中能听懂许多机密，获得满人好感。", type: "exclusive"},
                    {name: "火枪射击(熟练)", color: "蓝色", cost: 600, desc: "你熟练掌握火枪的使用，在这个武功逐渐没落的时代，火枪往往比刀剑更管用。", type: "exclusive"},
                    {name: "含沙射影(暗器)", color: "蓝色", cost: 750, desc: "一种精巧的机括暗器，藏在胸前，出其不意发射毒针，令人防不胜防。", type: "exclusive"},
                    {name: "金钟罩(鳌拜版)", color: "紫色", cost: 1900, desc: "鳌拜横练的硬气功，刀枪不入，力大无穷，寻常兵器难伤分毫。", type: "exclusive"},
                    {name: "赌术精通", color: "绿色", cost: 250, desc: "你精通各种赌术和出千技巧，能通过赌博快速积累财富，或与人拉近关系。", type: "exclusive"},
