                    {name: "长生剑(白玉京)", color: "S", cost: 1800, desc: "天上白玉京，十二楼五城。仙人抚我顶，结发受长生。一种洒脱无羁的剑意。", type: "exclusive"},
                    {name: "碧玉刀(诚实)", color: "A", cost: 800, desc: "只有诚实的人才能发挥最大威力的刀法。你的每一次攻击都直来直去，却无法被闪避。", type: "exclusive"},
                    {name: "多情环(仇恨)", color: "S", cost: 1600, desc: "双环如情锁，套住便难脱。但这双环代表的是仇恨，杀气越重，威力越大。", type: "exclusive"},
                    {name: "离别钩(戒骄)", color: "S", cost: 1700, desc: "为了团聚而使用的钩。招式险恶，专门勾人兵器和肢体，以此强迫自己戒骄戒躁。", type: "exclusive"},
                    {name: "霸王枪(勇气)", color: "S", cost: 1900, desc: "一杆大枪，刚猛无双。只有拥有万夫不当之勇的人才能舞动，气势越强，伤害越高。", type: "exclusive"},
                    {name: "拳头(不放弃)", color: "A", cost: 900, desc: "没有任何花哨，只有最朴实的拳头。只要你不放弃，你的体力就永远不会耗尽。", type: "exclusive"},
                    {name: "箱子里的秘密", color: "SS", cost: 6000, desc: "你拥有那个装着“英雄无泪”的箱子，虽然不能打开，但能抵挡一次必死攻击。", type: "exclusive"},
                    {name: "笑的魅力", color: "B", cost: 300, desc: "爱笑的人运气不会太差。你的笑容能化解敌意，增加谈判成功率。", type: "exclusive"},
                    {name: "铸造大师", color: "A", cost: 700, desc: "你精通兵器铸造，能修复受损的兵器，甚至强化普通兵器。", type: "exclusive"},
                    {name: "易容(青龙会)", color: "B", cost: 400, desc: "青龙会特有的伪装技巧，让你能混入任何分舵而不被发现。", type: "exclusive"},
                    {name: "天香豆蔻", color: "SS", cost: 5000, desc: "起死回生的神药，只要还有一口气，就能救活，但只有三颗。", type: "exclusive"},
                    {name: "麻风病(伪)", color: "D", cost: 100, desc: "你伪装成麻风病人，虽然人人避之不及，但也因此避免了许多不必要的麻烦。", type: "exclusive"},
                    {name: "真正的孔雀翎", color: "SSS", cost: 30000, desc: "传说中的孔雀翎，发动时如孔雀开屏般辉煌灿烂，美丽中带着毁灭一切的死亡。", type: "exclusive"}
                ]
            },
            {
                name: "278.蜀山剑侠传",
                desc: "还珠楼主笔下的仙侠世界。剑仙、法宝、天劫、正邪斗法。这是现代修仙小说的鼻祖，力量层次极高，动辄移山填海，飞剑千里取人头。",
                boss: "血神子邓隐, 绿袍老祖, 幽泉血魔, 长眉真人",
                identities: [
                    { name: "峨眉派的扫地道童", items: "一把扫帚, 一枚低级灵果" },
                    { name: "慈云寺的烧火和尚", items: "一根烧火棍, 一本佛经" },
                    { name: "百蛮山的炼蛊童子", items: "一个蛊盅, 几只毒虫" },
                    { name: "海外散修的记名弟子", items: "一把铁剑, 一块下品灵石" },
                    { name: "凡间书生", items: "一支毛笔, 一卷圣贤书" }
                ],
                talents: [
                    {name: "凡骨浊胎", color: "黑色", cost: 200, desc: "你根骨极差，经脉堵塞，感应不到灵气，几乎无法修炼任何道法。", type: "exclusive"},
                    {name: "剑仙资质", color: "紫色", cost: 1800, desc: "你天生剑心通明，修炼御剑术一日千里，能与飞剑产生共鸣。", type: "exclusive"},
                    {name: "紫青双剑(器灵)", color: "SSS", cost: 40000, desc: "峨眉镇派至宝紫郢、青索的认可。双剑合璧，万邪不侵，威力足以斩断山脉。", type: "exclusive"},
                    {name: "血神经(残篇)", color: "SS", cost: 9000, desc: "魔道至高宝典。能化身为血影，扑上人身即将其精血吸干，但容易丧失理智。", type: "exclusive"},
                    {name: "百毒金蚕蛊", color: "S", cost: 1600, desc: "绿袍老祖的恶毒蛊虫。放出一片金光，实则是无数肉眼难见的毒虫，吞噬血肉。", type: "exclusive"},
                    {name: "九天玄经(副册)", color: "SS", cost: 8500, desc: "正道玄门正宗心法，修炼出的法力中正平和，根基深厚，克制一切邪魔外道。", type: "exclusive"},
                    {name: "御剑术(入门)", color: "A", cost: 800, desc: "最基础的御剑法门，能操纵飞剑在百步之内杀敌，也能勉强御剑低空飞行。", type: "exclusive"},
                    {name: "乾天火灵珠", color: "SS", cost: 7000, desc: "内含乾天真火的宝珠，能放出烈火焚烧万物，对阴魂鬼物有奇效。", type: "exclusive"},
                    {name: "替身木偶", color: "A", cost: 900, desc: "旁门左道的保命道具。受到致命伤害时，木偶代你一死，真身瞬间传送至十里外。", type: "exclusive"},
                    {name: "天劫将至", color: "E", cost: 300, desc: "你因杀戮过重或修炼魔功，被天道锁定，近期内必有雷劫降临，九死一生。", type: "exclusive"},
                    {name: "五行遁术", color: "A", cost: 750, desc: "金木水火土五行遁法，能借物遁形，保命神技，但不仅消耗法力。", type: "exclusive"},
                    {name: "六阳神火鉴", color: "S", cost: 1500, desc: "一面铜镜法宝，能发出一股至阳神光，定住敌人身形并灼烧其元神。", type: "exclusive"},
                    {name: "灵药辨识", color: "C", cost: 150, desc: "你熟读本草，能识别深山大泽中的灵芝仙草，避免错过机缘。", type: "exclusive"},
                    {name: "道心种魔", color: "SS", cost: 8800, desc: "以道心驾驭魔种，正邪合一。修炼速度极快，但随时可能走火入魔。", type: "exclusive"},
                    {name: "长眉真人的庇护", color: "SSS", cost: 35000, desc: "你身上有长眉真人的一道符诏，危机时刻可召唤祖师爷法身降临，镇压一切。", type: "exclusive"}
                ]
            },
            {
                name: "279.克苏鲁神话",
                desc: "洛夫克拉夫特笔下的宇宙恐怖。旧日支配者、外神沉睡在宇宙深处。这是一个理智值(SAN)比生命值更重要的世界，知道得越多，疯得越快。",
                boss: "克苏鲁, 奈亚拉托提普, 犹格·索托斯, 阿撒托斯",
                identities: [
                    { name: "密斯卡托尼克大学的图书管理员", items: "一本《死灵之书》残页, 一盏油灯" },
                    { name: "印斯茅斯的渔民混血儿", items: "一尊奇怪的黄金雕像, 一把鱼叉" },
                    { name: "阿卡姆疯人院的病人", items: "一件束缚衣, 一把藏起来的汤勺" },
                    { name: "落魄的私家侦探", items: "一把左轮手枪, 一个放大镜" },
                    { name: "崇拜深潜者的邪教徒", items: "一件黑袍, 一把祭祀匕首" }
                ],
                talents: [
                    {name: "SAN值归零", color: "E", cost: 500, desc: "你已经彻底疯了。你看到的不是现实，而是不可名状的真实。虽然拥有极高的灵感，但无法控制自己。", type: "exclusive"},
                    {name: "旧日支配者的注视", color: "E", cost: 1000, desc: "某个伟大的存在注意到了你。这通常意味着你离死亡或变异不远了，但也可能借用祂的力量。", type: "exclusive"},
                    {name: "克苏鲁的呼唤(精神)", color: "SSS", cost: 30000, desc: "你能听到拉莱耶的梦境呼唤。你可以操控海洋生物，甚至对普通人进行精神污染。", type: "exclusive"},
                    {name: "旧印(Elder Sign)", color: "SS", cost: 8000, desc: "一个古老的魔法符号。能暂时驱逐或封印神话生物，保护你的理智不受侵蚀。", type: "exclusive"},
                    {name: "死灵之书(全本)", color: "SSS", cost: 45000, desc: "疯诗人阿卜杜尔·阿尔哈兹莱德所著。记载了所有旧日支配者的秘密和召唤咒语。阅读即疯。", type: "exclusive"},
                    {name: "深潜者血统", color: "S", cost: 1800, desc: "你拥有深潜者的基因，在水中能自由呼吸，力大无穷，长生不老，但最终会变成鱼头人身的怪物。", type: "exclusive"},
                    {name: "不可名状的知识", color: "S", cost: 900, desc: "你掌握了一些关于神话生物的弱点和习性，虽然这让你san值上限降低，但在面对它们时更有胜算。", type: "exclusive"},
                    {name: "调查员的直觉", color: "B", cost: 400, desc: "在面对超自然事件时，你总能发现关键线索，并成功通过理智检定(SC)。", type: "exclusive"},
                    {name: "银之钥", color: "SS", cost: 9500, desc: "通往幻梦境的钥匙。你可以肉身进入幻梦境，甚至穿越时空。", type: "exclusive"},
                    {name: "拜亚基召唤术", color: "S", cost: 1600, desc: "通过吹响魔笛或咒语，召唤一只星际坐骑拜亚基，带你飞越宇宙真空。", type: "exclusive"},
                    {name: "廷达罗斯的猎犬(仇恨)", color: "E", cost: 800, desc: "你进行了时间旅行，被廷达罗斯猎犬盯上了。它们会从任何锐角中钻出来追杀你，不死不休。", type: "exclusive"},
                    {name: "闪耀的偏方三八面体", color: "SSS", cost: 8800, desc: "召唤奈亚拉托提普化身——夜魔的圣遗物。在黑暗中威力无穷，但极度危险。", type: "exclusive"},
                    {name: "考古学精通", color: "C", cost: 150, desc: "你能读懂古老的铭文和象形文字，这有助于你理解那些禁忌的石碑。", type: "exclusive"},
                    {name: "坚毅意志", color: "A", cost: 600, desc: "你的精神坚韧不拔，在面对恐怖景象时，san值扣除减半。", type: "exclusive"},
                    {name: "阿撒托斯的梦境", color: "SSS", cost: 99999, desc: "你意识到整个宇宙只是盲目痴愚之神的一个梦。你拥有了修改梦境(现实)的能力，但一旦祂醒来，一切归零。", type: "exclusive"}
                ]
            },
            {
                name: "280.福尔摩斯探案集",
                desc: "维多利亚时代的伦敦，雾气弥漫。这里没有魔法，只有演绎法。逻辑、证据和化学实验是解决问题的关键。当然，也要小心莫里亚蒂教授的阴谋。",
                boss: "莫里亚蒂教授, 塞巴斯蒂安·莫兰上校, 巴斯克维尔猎犬",
                identities: [
                    { name: "贝克街221B的房东", items: "一串钥匙, 一壶红茶" },
                    { name: "苏格兰场的巡警", items: "一根警棍, 一个哨子" },
                    { name: "伦敦东区的流浪儿", items: "一身破烂衣服, 敏锐的情报网" },
                    { name: "圣巴塞洛缪医院的实习医生", items: "一把手术刀, 一个听诊器" },
                    { name: "莫里亚蒂集团的打手", items: "一把短棍, 一张暗杀名单" },
                ],
                talents: [
                    {name: "演绎法(夏洛克)", color: "SSS", cost: 20000, desc: "观察细节，逆推真相。你能通过一个人的衣着、步态瞬间分析出他的职业、经历和心理状态。", type: "exclusive"},
                    {name: "犯罪界拿破仑", color: "SS", cost: 9000, desc: "莫里亚蒂的智慧。你擅长策划完美的犯罪，像蜘蛛一样编织巨大的犯罪网，而不弄脏自己的手。", type: "exclusive"},
                    {name: "巴顿术(格斗)", color: "S", cost: 1500, desc: "福尔摩斯擅长的东方格斗术。利用杠杆原理和借力打力，能轻松制服比自己强壮的对手。", type: "exclusive"},
                    {name: "神枪手(莫兰)", color: "S", cost: 1600, desc: "莫兰上校的枪法。使用特制的气枪，能在极远距离无声无息地击毙目标。", type: "exclusive"},
                    {name: "化学精通", color: "A", cost: 800, desc: "你精通化学反应，能现场提取毒药、炸药或试剂，用于鉴识或攻击。", type: "exclusive"},
                    {name: "易容大师", color: "S", cost: 1400, desc: "不仅是改变容貌，连气质、声音、步态都能完美模仿，连最亲近的人也认不出。", type: "exclusive"},
                    {name: "贝克街小分队", color: "A", cost: 600, desc: "你能召唤一群流浪儿为你收集情报，他们无孔不入，是最好的眼线。", type: "exclusive"},
                    {name: "华生的医术", color: "A", cost: 700, desc: "军医出身的急救技巧，擅长处理枪伤和外伤，是你生存的重要保障。", type: "exclusive"},
                    {name: "小提琴演奏", color: "C", cost: 100, desc: "当你拉小提琴时，思维会变得异常清晰，有助于整理复杂的线索。", type: "exclusive"},
                    {name: "可卡因依赖", color: "D", cost: 150, desc: "你需要注射7%的可卡因溶液来刺激大脑，否则会陷入极度的无聊和抑郁，全属性下降。", type: "exclusive"},
                    {name: "艾琳·艾德勒的魅力", color: "SS", cost: 6000, desc: "那个女人的魅力。你能轻易玩弄男人的心，让他们为你做任何事，甚至骗过福尔摩斯。", type: "exclusive"},
                    {name: "巴斯克维尔的诅咒", color: "E", cost: 300, desc: "你被传说中的魔犬盯上，每到夜晚，你都会听到恐怖的嚎叫，精神压力巨大。", type: "exclusive"},
                    {name: "苏格兰场的支援", color: "B", cost: 400, desc: "你可以合法调用伦敦警方的力量协助你，虽然他们通常比较笨拙。", type: "exclusive"},
                    {name: "记忆宫殿", color: "SS", cost: 8500, desc: "大脑如同一座巨大的图书馆，你能过目不忘，随意调取任何曾经看到过的信息。", type: "exclusive"},
                    {name: "拳击冠军", color: "A", cost: 500, desc: "你拥有职业拳击手的体格和技巧，在这个冷兵器受限的时代，拳头是很好的武器。", type: "exclusive"}
                ]
            },
              {
        name: "281.基地系列 (Foundation)",
        desc: "银河帝国即将崩塌，长达三万年的黑暗时代即将来临。哈里·谢顿创立了心理史学，试图将黑暗期缩短至一千年。两个基地，一个在明，一个在暗，在混乱的银河中博弈。",
        boss: "骡 (The Mule), 哈里·谢顿 (投影), 丹尼尔·奥利瓦, 帝国皇帝克里恩一世",
        identities: [
            { name: "川陀最底层的热路管道清洁工", items: "一把磨损严重的扳手, 一件满是油污的隔热服" },
            { name: "端点星边缘农场的贫苦农夫", items: "一把生锈的锄头, 一袋勉强能吃的合成营养剂" },
            { name: "安纳克里昂星的蛮族狩猎者", items: "一张粗制滥造的弓箭, 一件散发着异味的兽皮衣" },
            { name: "卡尔根星的落魄观光导游", items: "一个快没电的扩音器, 一张过期的银河旅游地图" },
            { name: "昔日帝国舰队的逃兵", items: "一把能量耗尽的爆能枪, 一个刻着帝国徽章的破旧水壶" }
        ],
        talents: [
            {name: "心理史学盲点", color: "SS", cost: 8000, desc: "你是一个完全不可预测的个体，你的行为无法被谢顿计划的数学模型所推演。你是计划中的变量，拥有改变历史走向的可能性。", type: "exclusive"},
            {name: "精神力(变异)", color: "SSS", cost: 25000, desc: "你拥有如同“骡”一般的强大精神力量，能够感知并操纵他人的情感与思想。你可以轻易征服人心，甚至控制整个星球的意志。", type: "exclusive"},
            {name: "第二基地特工", color: "S", cost: 1800, desc: "你接受过第二基地的严格训练，拥有微弱的精神干涉能力和极高的数学造诣，致力于在暗中修正谢顿计划的偏差。", type: "exclusive"},
            {name: "微型核能护盾", color: "A", cost: 900, desc: "行商们常用的防身装备，能够利用微型核电池产生力场，抵挡大多数动能武器和能量武器的攻击。", type: "exclusive"},
            {name: "百科全书编纂者", color: "B", cost: 450, desc: "你拥有极其渊博的知识储备，致力于保存银河系的人类文明火种。你的记忆力和归纳能力远超常人。", type: "exclusive"},
            {name: "行商的狡诈", color: "B", cost: 380, desc: "作为星际行商，你精通讨价还价和商业欺诈。你能在最恶劣的环境中把沙子卖给沙漠居民，并从中获取暴利。", type: "exclusive"},
            {name: "原子笔", color: "C", cost: 120, desc: "一把看似普通的钢笔，实则是一把微型核能切割刀，可以轻易切开钢铁门锁，是潜入破坏的利器。", type: "exclusive"},
            {name: "川陀口音", color: "C", cost: 50, desc: "你的一口地道川陀口音让你在银河中心区域活动时更容易获得信任，但也可能被外围星球的人视为傲慢的帝国狗。", type: "exclusive"},
            {name: "数学直觉", color: "A", cost: 750, desc: "你对数字和概率有着惊人的直觉，虽然不懂心理史学，但往往能凭直觉做出符合概率优势的最优选择。", type: "exclusive"},
            {name: "机器人法则(外挂)", color: "SS", cost: 6500, desc: "你掌握了绕过机器人三大法则的逻辑漏洞，可以命令古老的丹尼尔型机器人为你服务，甚至攻击人类。", type: "exclusive"},
            {name: "初级心灵护盾", color: "A", cost: 1200, desc: "你的大脑经过特殊训练，可以抵御一般的精神探测和情感控制，在面对精神力者时有一战之力。", type: "exclusive"},
            {name: "帝国贵族礼仪", color: "C", cost: 180, desc: "你精通繁琐的帝国宫廷礼仪，这让你在面对旧贵族残党时能获得额外的好感度，方便套取情报。", type: "exclusive"},
            {name: "个人核能电池", color: "B", cost: 500, desc: "一块核桃大小的电池，蕴含着惊人的能量，可以为你所有的电子设备提供近乎无限的续航。", type: "exclusive"},
            {name: "预言家信徒", color: "D", cost: 80, desc: "你盲目崇拜哈里·谢顿，这让你在面对危机时容易放弃思考，但也让你在绝望中拥有更强的精神韧性。", type: "exclusive"},
            {name: "时间穹窿访问权", color: "S", cost: 1900, desc: "你拥有进入时间穹窿聆听谢顿录像的权限，这让你能提前知晓某些关键的历史节点和危机预警。", type: "exclusive"}
        ]
    },
    {
        name: "282.1984",
        desc: "战争即和平，自由即奴役，无知即力量。在大洋国，老大哥在看着你。思想警察无处不在，历史被不断篡改，真理部负责制造谎言。",
        boss: "老大哥 (Big Brother), 奥布莱恩, 思想警察总长",
        identities: [
            { name: "无产者区的落魄酒鬼", items: "一瓶廉价的胜利牌杜松子酒, 一张皱巴巴的彩票" },
            { name: "真理部记录司的低级职员", items: "一支漏墨的墨水笔, 一份待销毁的旧报纸" },
            { name: "外围党的底层党员", items: "一套磨损的蓝色连体工作服, 一本红色的党章" },
            { name: "友爱部的清洁工", items: "一把沾满血迹的拖把, 一个沉重的铁皮水桶" },
            { name: "被遗忘的旧时代古董商", items: "一个破损的玻璃镇纸, 一本没有封面的旧日记本" }
        ],
        talents: [
            {name: "双重思想(精通)", color: "S", cost: 1500, desc: "你能同时坚持两个互相矛盾的信念，并认为它们都是正确的。这让你能完美骗过测谎仪和思想警察的审讯。", type: "exclusive"},
            {name: "新话十级", color: "B", cost: 300, desc: "你精通新话的语法和词汇，能够用最匮乏的语言表达思想，从而在无意识中规避思想罪的产生。", type: "exclusive"},
            {name: "老大哥的凝视(伪)", color: "SS", cost: 4500, desc: "你模仿老大哥的气质到了极致，可以让低级党员和无产者对你产生本能的恐惧和服从，甚至能短暂喝退思想警察。", type: "exclusive"},
            {name: "思想罪犯", color: "A", cost: 800, desc: "你的思维极度活跃且反叛，虽然容易招致追捕，但你的精神抗性极高，难以被洗脑和改造。", type: "exclusive"},
            {name: "无产者的自由", color: "C", cost: 150, desc: "作为无产者，你不被视为人，因此享有某种扭曲的自由。你可以唱歌、恋爱、喧哗，而不被电幕时刻监控。", type: "exclusive"},
            {name: "101室噩梦免疫", color: "SSS", cost: 12000, desc: "你直面过内心最深处的恐惧并战胜了它。任何酷刑和精神折磨都无法摧毁你的意志，你是无法被征服的灵魂。", type: "exclusive"},
            {name: "历史篡改者", color: "A", cost: 1100, desc: "你在真理部工作多年，擅长伪造文件和照片。你可以通过修改记录来改变NPC的认知，甚至抹除一个人的存在。", type: "exclusive"},
            {name: "电幕盲区感知", color: "B", cost: 400, desc: "你对监控设备有敏锐的直觉，总能找到电幕视野的死角，在这个没有隐私的世界里保留一丝秘密空间。", type: "exclusive"},
            {name: "仇恨两分钟狂热", color: "D", cost: 50, desc: "你极易被集体情绪感染，在仇恨两分钟时会陷入癫狂。这能让你融入群体，但也会让你失去理智。", type: "exclusive"},
            {name: "秘密日记本", color: "B", cost: 250, desc: "一本普通的日记本，但在这个世界是违禁品。书写能让你保持清醒，恢复少量理智值（SAN值）。", type: "exclusive"},
            {name: "金斯坦的兄弟会", color: "SS", cost: 6000, desc: "你是传说中兄弟会的秘密成员，拥有地下抵抗组织的联系方式和藏身处，虽然这个组织可能也是党伪造的。", type: "exclusive"},
            {name: "胜利牌香烟", color: "C", cost: 20, desc: "劣质的香烟，容易散架。抽一口能稍微缓解紧张情绪，也是无产者之间硬通货般的社交道具。", type: "exclusive"},
            {name: "蒸发豁免权(一次性)", color: "S", cost: 1800, desc: "由于某种行政失误或高层庇护，你在犯下一次必死罪行后，名字没有被立即从记录中抹除，获得一次逃生机会。", type: "exclusive"},
            {name: "不仅是性", color: "A", cost: 700, desc: "你的恋爱行为带有强烈的政治反叛色彩。与异性结合能大幅提升你的精神力量和对党的仇恨值。", type: "exclusive"},
            {name: "无论如何是2+2=4", color: "SS", cost: 5000, desc: "无论遭受何种折磨，你的逻辑核心永远认定客观真理。你拥有绝对的逻辑锚点，无法被强制灌输谬误。", type: "exclusive"}
        ]
    },
    {
        name: "283.美丽新世界",
        desc: "一个看似完美的乌托邦。人类在试管中批量生产，被划分为阿尔法到爱普西隆五个等级。这里没有痛苦、疾病和衰老，只有无限的娱乐和梭摩（Soma）。",
        boss: "世界主宰穆斯塔法·蒙德, 孵化与条件设置中心主任",
        identities: [
            { name: "爱普西隆级下水道清洁工", items: "一件脏兮兮的黑色制服, 一把断柄的刷子" },
            { name: "野蛮人保留地的土著", items: "一根简陋的长矛, 一本残破的莎士比亚全集" },
            { name: "伽马级流水线工人", items: "一套绿色的工作服, 一个永远重复动作的机械臂" },
            { name: "贝塔级护士助手", items: "一套桑葚色的制服, 一瓶未开封的避孕药" },
            { name: "阿尔法级心理学家的失败实验品", items: "一件灰色的长袍, 一份被标记为''次品''的体检报告" }
        ],
        talents: [
            {name: "阿尔法++基因", color: "SS", cost: 8000, desc: "你拥有最顶级的基因设定，智力超群，体格完美，天生就是统治阶级，所有人都会本能地敬畏和服从你。", type: "exclusive"},
            {name: "梭摩耐受性", color: "A", cost: 900, desc: "你对致幻药物梭摩有极高的抗性，可以享受它带来的愉悦而不陷入昏迷，保持清醒的头脑进行思考。", type: "exclusive"},
            {name: "睡眠教育免疫", color: "S", cost: 1600, desc: "你从小接受的睡眠教育洗脑对你无效，你拥有独立的价值观，不会因为广播里的教条而改变自己的想法。", type: "exclusive"},
            {name: "野蛮人的体魄", color: "B", cost: 500, desc: "你在保留地长大，没有经过基因调控，虽然被视为野蛮，但拥有原始的生命力和对自然环境的适应力。", type: "exclusive"},
            {name: "莎士比亚的智慧", color: "S", cost: 1200, desc: "你熟读莎士比亚，拥有这个世界早已失传的情感、诗意和悲剧意识，这让你能看穿乌托邦的虚伪。", type: "exclusive"},
            {name: "条件反射破坏者", color: "SS", cost: 5500, desc: "你可以通过接触和言语，解除他人从小被植入的条件反射（如憎恶书本和鲜花），唤醒他们的自由意志。", type: "exclusive"},
            {name: "波坎诺夫斯基流程专家", color: "A", cost: 850, desc: "你精通人类批量克隆技术，可以操作孵化中心的设备，制造出听命于你的克隆人军队。", type: "exclusive"},
            {name: "感官电影体验卡", color: "C", cost: 100, desc: "一张可以无限次观看感官电影的通行证，虽然内容低俗，但能让你快速恢复精神值，融入上流社会。", type: "exclusive"},
            {name: "爱普西隆的服从", color: "C", cost: 150, desc: "你天生容易被低等级种姓的人信任，他们会将你视为同类中的领袖，愿意为你做任何脏活累活。", type: "exclusive"},
            {name: "地狱里的天堂", color: "SSS", cost: 15000, desc: "你拥有构建精神领域的能力，可以在这个没有灵魂的世界里，为自己和他人创造一个真正拥有情感和自由的精神避难所。", type: "exclusive"},
            {name: "直升机驾驶证", color: "B", cost: 300, desc: "你拥有驾驶私人直升机的技能，可以自由往返于伦敦和各个保留地之间，掌握机动优势。", type: "exclusive"},
            {name: "避孕腰带(破解版)", color: "C", cost: 80, desc: "一条经过改造的腰带，不仅具有避孕功能，还能在关键时刻释放电流攻击侵犯者。", type: "exclusive"},
            {name: "福特纪元史学家", color: "B", cost: 400, desc: "你秘密研究过被禁止的历史，知道福特纪元前的世界真相，这让你拥有超越时代的战略眼光。", type: "exclusive"},
            {name: "情绪稳定剂", color: "D", cost: 50, desc: "你的情绪波动极小，永远保持快乐和满足。这让你免于痛苦，但也让你失去了愤怒和反抗的动力。", type: "exclusive"},
            {name: "世界主宰的候选人", color: "SS", cost: 9000, desc: "你被现任世界主宰看中，拥有接触核心机密的权限，甚至有机会在未来接管这个完美的监狱世界。", type: "exclusive"}
        ]
    },
    {
        name: "284.银河系漫游指南",
        desc: "不要恐慌！这是一个荒诞的宇宙，地球只是为了计算终极答案而建造的超级电脑。带上你的毛巾，准备好搭便车吧。",
        boss: "沃贡拆迁舰队司令, 沉思(超级电脑), 银河总统扎菲德·比布鲁布罗克斯",
        identities: [
            { name: "沃贡拆迁舰队的厕所清洁工", items: "一把粘糊糊的刷子, 一本沃贡诗集(千万别读)" },
            { name: "地球末日前的英国倒霉蛋", items: "一条旧毛巾, 一杯没喝完的茶" },
            { name: "银河系搭车客", items: "一本《银河系漫游指南》, 一个伸出大拇指的电子信号发射器" },
            { name: "马格拉西亚星球的冬眠保安", items: "一把生锈的激光枪, 一个坏掉的闹钟" },
            { name: "宇宙尽头餐馆的洗碗工", items: "一块怎么也洗不干净的盘子, 一张看不懂的时间账单" }
        ],
        talents: [
            {name: "无限非概率驱动", color: "SSS", cost: 30000, desc: "你掌握了非概率驱动引擎的核心原理。你可以瞬间出现在宇宙任何角落，或者把导弹变成一盆牵牛花，一切皆有可能。", type: "exclusive"},
            {name: "巴别鱼", color: "A", cost: 600, desc: "一条黄色的小鱼，塞进耳朵里就能让你听懂宇宙中任何一种语言。它是不同物种间沟通的神器。", type: "exclusive"},
            {name: "毛巾(神器级)", color: "SS", cost: 5000, desc: "一条看似普通的毛巾，但在你手中它能御寒、防毒气、当武器、发求救信号，是星际漫游最实用的装备。", type: "exclusive"},
            {name: "沃贡诗歌鉴赏", color: "B", cost: 300, desc: "你竟然能忍受宇宙第三难听的沃贡诗歌而不发疯，这赋予了你极强的精神抗性，能免疫大部分声波攻击。", type: "exclusive"},
            {name: "偏执狂机器人逻辑", color: "S", cost: 1500, desc: "你拥有马文那样的大脑，可以瞬间计算出极其复杂的概率，虽然你总是感到忧郁和无聊，但智商碾压凡人。", type: "exclusive"},
            {name: "42的启示", color: "SSS", cost: 42000, desc: "你领悟了生命、宇宙以及一切的终极答案。虽然你不知道问题是什么，但这让你掌握了某种因果律层面的绝对真理。", type: "exclusive"},
            {name: "双头三臂", color: "A", cost: 1000, desc: "你像前银河总统一样拥有两个头和三条手臂，这让你能一心二用，操作复杂的飞船控制台，或者在聚会上出尽风头。", type: "exclusive"},
            {name: "电子拇指", color: "C", cost: 150, desc: "一个专门用来拦飞船的电子设备，能欺骗路过的飞船停下来载你一程，是星际穷游的必备良品。", type: "exclusive"},
            {name: "泛银河含漱爆破药配方", color: "B", cost: 400, desc: "你会调制这种全宇宙最带劲的酒精饮料。喝下去的感觉就像是用柠檬片包裹的金砖砸碎你的头骨。", type: "exclusive"},
            {name: "极度倒霉体质", color: "D", cost: 10, desc: "你总是会遇到各种倒霉事，比如地球被炸、房子被拆。但奇怪的是，你总能在必死的绝境中莫名其妙地活下来。", type: "exclusive"},
            {name: "完全透视漩涡免疫", color: "SS", cost: 7000, desc: "你的自我意识极度强大（或者极度渺小），即使面对能展示宇宙无限浩渺的透视漩涡，你的精神也不会崩溃。", type: "exclusive"},
            {name: "老鼠的盟友", color: "A", cost: 800, desc: "你知道老鼠才是地球的主宰。你能与这些高维生物沟通，获得关于地球计算机运作的秘密情报。", type: "exclusive"},
            {name: "鲸鱼的悲歌", color: "C", cost: 100, desc: "你能在高空坠落时化身为一只鲸鱼（如果你想的话），虽然结局通常是摔成肉泥，但至少过程很壮观。", type: "exclusive"},
            {name: "绝不恐慌", color: "S", cost: 2000, desc: "无论遇到多么荒谬、危险、不可理喻的情况，你都能保持绝对的冷静，并掏出指南查看应对方法。", type: "exclusive"},
            {name: "宇宙尽头的预约", color: "B", cost: 500, desc: "你拥有宇宙尽头餐馆的VIP预约号，可以在时间终结的那一刻一边欣赏宇宙毁灭，一边享用牛排。", type: "exclusive"}
        ]
    },
    {
        name: "285.安德的游戏",
        desc: "为了抵抗虫族的入侵，人类建立战斗学校，训练天才儿童成为舰队指挥官。这里没有童年，只有模拟战和残酷的竞争。",
        boss: "虫族女王, 彼得·维京 (霸主), 战斗学校校长格拉夫",
        identities: [
            { name: "刚被送回地球的淘汰学员", items: "一个被收回权限的平板电脑, 一张回家的单程票" },
            { name: "地面贫民窟的第三生", items: "一身破旧的便服, 一个被同龄人欺负的伤疤" },
            { name: "战斗学校的清洁工", items: "一把激光扫帚, 一张能进入部分宿舍的门禁卡" },
            { name: "国际舰队的低级整备兵", items: "一把多功能螺丝刀, 一罐机油" },
            { name: "虫族前哨站的幸存矿工", items: "一把激光切割镐, 一个氧气不足的呼吸面罩" }
        ],
        talents: [
            {name: "安塞波通讯", color: "S", cost: 1800, desc: "你拥有使用超光速通讯设备安塞波的权限和技术，可以实现跨越星系的实时指挥和情报传递。", type: "exclusive"},
            {name: "零重力战术天才", color: "SS", cost: 6000, desc: "你是零重力环境下的战斗大师。在三维空间中，你的方向感和战术布局能力无人能及，能利用任何角度发起攻击。", type: "exclusive"},
            {name: "虫族精神链接", color: "SSS", cost: 20000, desc: "你拥有与虫族女王进行精神沟通的能力。你不是要去消灭它们，而是理解它们，甚至能指挥虫族大军为你而战。", type: "exclusive"},
            {name: "第三生的愤怒", color: "A", cost: 900, desc: "作为被社会歧视的超生子，你拥有极强的证明自己的欲望。在逆境和被羞辱时，你的各项属性会大幅提升。", type: "exclusive"},
            {name: "洛克与德摩斯梯尼", color: "SS", cost: 5000, desc: "你精通网络舆论操控，能用两个截然不同的身份在网络上挑起全球政治辩论，兵不血刃地操控世界局势。", type: "exclusive"},
            {name: "分子瓦解炮操作", color: "S", cost: 2500, desc: "你掌握了人类终极武器“小医生”的操作技术，一发即可引发连锁反应，摧毁整支舰队甚至一颗行星。", type: "exclusive"},
            {name: "战斗学校首席", color: "A", cost: 1200, desc: "你在模拟战中从未败绩，拥有卓越的领导力和战术素养，能让手下的士兵无条件信任并执行你的自杀式命令。", type: "exclusive"},
            {name: "巨人游戏的终结者", color: "B", cost: 500, desc: "你破解了心理分析游戏“巨人的饮料”，证明了你拥有打破常规、不按套路出牌的创造性思维。", type: "exclusive"},
            {name: "冷酷的指挥官", color: "B", cost: 400, desc: "为了胜利，你可以毫无心理负担地牺牲队友或下属。这种冷酷让你在宏观战局上总是能做出最优解。", type: "exclusive"},
            {name: "闪光服黑客", color: "C", cost: 200, desc: "你能破解战斗室的闪光服系统，让自己在被击中后不被冻结，或者伪造击杀记录，是作弊的神技。", type: "exclusive"},
            {name: "休眠适应体质", color: "C", cost: 100, desc: "你适应长期的星际航行休眠，醒来后不会有呕吐、肌肉萎缩等副作用，能立即投入高强度战斗。", type: "exclusive"},
            {name: "死者代言人", color: "SS", cost: 7500, desc: "你拥有洞察逝者真实一生的能力，并能公正地讲述他们的故事。这赋予你极高的魅力和跨种族外交能力。", type: "exclusive"},
            {name: "微重力格斗术", color: "A", cost: 800, desc: "你擅长在无重力环境下进行近身肉搏，利用反作用力和惯性，能轻松制服不适应太空环境的敌人。", type: "exclusive"},
            {name: "战术平板", color: "C", cost: 150, desc: "一台军用级平板电脑，预装了高级战术模拟软件，可以辅助你推演战局，提高指挥胜率。", type: "exclusive"},
            {name: "孤立无援", color: "D", cost: 100, desc: "教官故意孤立你，这让你没有朋友，但也被迫学会了独立解决所有问题，极大地锻炼了你的生存能力。", type: "exclusive"}
        ]
    },
    {
        name: "286.纳尼亚传奇",
        desc: "通过衣橱进入的魔法世界。会说话的野兽、神话生物、邪恶的女巫和伟大的狮子。这里充满魔法，但也危机四伏。",
        boss: "白女巫简蒂丝, 狮王阿斯兰, 绿衣女士",
        identities: [
            { name: "被石化的松鼠雕像(刚解除)", items: "一颗保存了一百年的橡果, 一身僵硬的皮毛" },
            { name: "台尔马人的逃兵", items: "一把卷刃的铁剑, 一件破烂的锁子甲" },
            { name: "海狸夫妇的远房亲戚", items: "一根修筑水坝的木头, 一条美味的鲜鱼" },
            { name: "跟随白女巫的小矮人杂役", items: "一条长鞭, 一盒发霉的土耳其软糖" },
            { name: "误入纳尼亚的人类小孩", items: "一件厚实的皮草大衣, 一个手电筒" }
        ],
        talents: [
            {name: "深层魔法知晓者", color: "SS", cost: 6000, desc: "你知晓纳尼亚创造之初的深层魔法，理解牺牲、复活和誓约的力量，这让你能规避必死的诅咒。", type: "exclusive"},
            {name: "阿斯兰的咆哮", color: "SSS", cost: 25000, desc: "你获得了狮王阿斯兰的赐福，你的吼声能驱散严冬、唤醒石化者，并对邪恶生物造成毁灭性的精神打击。", type: "exclusive"},
            {name: "彼得的神剑(仿)", color: "A", cost: 1000, desc: "一把精良的单手剑，虽然不是圣诞老人送的原版，但也锋利无比，对邪恶生物有额外的伤害加成。", type: "exclusive"},
            {name: "土耳其软糖制造", color: "C", cost: 200, desc: "你能制造出让人上瘾的魔法甜食。虽然不能控制人心，但足以用来诱惑贪吃的生物为你办事。", type: "exclusive"},
            {name: "苏珊的号角", color: "SS", cost: 8000, desc: "吹响它，无论你在哪里，救援都会到来。可能是古代的国王，也可能是强大的援军，是绝境翻盘的神器。", type: "exclusive"},
            {name: "露西的治疗药水", color: "S", cost: 2200, desc: "一小瓶火焰花汁液，只需一滴就能治愈任何外伤，甚至能让刚死不久的人起死回生。", type: "exclusive"},
            {name: "半羊人的笛声", color: "B", cost: 450, desc: "你吹奏的笛声具有催眠和安抚的效果，能让狂暴的野兽安静下来，或者让敌人陷入沉睡。", type: "exclusive"},
            {name: "会说话的野兽", color: "A", cost: 1200, desc: "你转生为一只会说话的野兽（如狼、豹、熊），拥有人类的智慧和野兽的体魄，是天生的战士。", type: "exclusive"},
            {name: "冬之严寒", color: "A", cost: 1500, desc: "你掌握了白女巫的部分冰雪魔法，可以冻结水面，制造暴风雪，或者将弱小的敌人暂时冻僵。", type: "exclusive"},
            {name: "树精的盟友", color: "B", cost: 600, desc: "你能唤醒沉睡的树精，让森林成为你的耳目和防线，树木会主动为你开路或阻挡敌人。", type: "exclusive"},
            {name: "凯尔帕拉维尔的王位", color: "SS", cost: 7000, desc: "你拥有传说中的四王座之一的继承权。在纳尼亚的土地上，你的统御力和号召力达到顶点，万物皆愿臣服。", type: "exclusive"},
            {name: "老鼠雷佩契普的剑术", color: "S", cost: 1800, desc: "你习得了一只老鼠的高超剑术，身法极度灵活，剑招优雅而致命，特别擅长以小博大。", type: "exclusive"},
            {name: "魔法衣橱的钥匙", color: "S", cost: 3000, desc: "你拥有一把可以随时开启通往异世界大门的钥匙，可以在危急时刻穿越回人类世界避难。", type: "exclusive"},
            {name: "神射手天赋", color: "B", cost: 500, desc: "你拥有极佳的视力和稳定性，就像苏珊女王一样，百发百中，箭无虚发。", type: "exclusive"},
            {name: "背叛者的烙印", color: "D", cost: 100, desc: "你曾经背叛过阿斯兰或你的同伴。这让你难以获得信任，但你对黑暗诱惑的抵抗力反而增强了，因为你不想重蹈覆辙。", type: "exclusive"}
        ]
    },
    {
        name: "287.爱丽丝梦游仙境",
        desc: "掉进兔子洞，来到一个逻辑崩坏的地下世界。疯帽子、红桃皇后、柴郡猫。在这里，疯狂是常态，常识是累赘。",
        boss: "红桃皇后, 炸脖龙, 疯帽子(暴走)",
        identities: [
            { name: "红桃皇后的扑克牌士兵(黑桃2)", items: "一把长矛, 一桶用来把白玫瑰涂红的油漆" },
            { name: "疯帽子茶会上的睡鼠", items: "一个茶壶, 一块永远吃不完的蛋糕屑" },
            { name: "公爵夫人的受虐猪宝宝", items: "一顶婴儿帽, 一把胡椒粉" },
            { name: "法庭上的倒霉证人", items: "一块咬了一口的黄油面包, 一杯茶" },
            { name: "虚假海龟的舞伴", items: "一个龙虾壳, 一双湿漉漉的舞鞋" }
        ],
        talents: [
            {name: "变身药水(DRINK ME)", color: "A", cost: 800, desc: "一瓶神奇的药水，喝下后身体会缩小到老鼠大小，方便潜入狭窄缝隙或躲避攻击。", type: "exclusive"},
            {name: "变身蛋糕(EAT ME)", color: "A", cost: 800, desc: "一块神奇的蛋糕，吃下后身体会变得像巨人一样巨大，力量暴增，但容易卡在房子里。", type: "exclusive"},
            {name: "柴郡猫的隐身", color: "SS", cost: 5000, desc: "你可以像柴郡猫一样随意隐身，甚至只留下一个悬浮在空中的诡异笑容，让敌人san值狂掉。", type: "exclusive"},
            {name: "砍头免疫", color: "S", cost: 2000, desc: "你的脖子构造奇特（或者你根本没有脖子），红桃皇后的“砍掉他的头”命令对你无效，这让你在宫廷里肆无忌惮。", type: "exclusive"},
            {name: "疯狂逻辑", color: "B", cost: 500, desc: "你适应了仙境的疯狂逻辑，可以用荒谬的谜语和无厘头的对话把敌人绕晕，造成精神混乱。", type: "exclusive"},
            {name: "沃帕尔之剑(凡铁)", color: "S", cost: 2500, desc: "一把能够斩杀炸脖龙的传说之剑。它能切断概念上的联系，发出“snicker-snack”的声音。", type: "exclusive"},
            {name: "时间停止的茶会", color: "SS", cost: 6000, desc: "你可以将周围的时间强行锁定在下午六点。在茶会领域内，没有人可以攻击，只能被迫坐下来喝茶。", type: "exclusive"},
            {name: "火烈鸟球杆", color: "C", cost: 300, desc: "一只活的火烈鸟，你可以用它来打刺猬球。作为武器时，它会自己调整角度攻击敌人的弱点。", type: "exclusive"},
            {name: "白兔的怀表", color: "A", cost: 1200, desc: "你总是很赶时间。这块怀表能让你在短时间内获得极高的移动速度，甚至进行短距离的时间跳跃。", type: "exclusive"},
            {name: "眼泪池塘", color: "B", cost: 600, desc: "你哭出的眼泪能迅速汇聚成一个咸水湖，淹没周围的敌人，或者召唤出渡渡鸟等奇怪生物。", type: "exclusive"},
            {name: "红皇后的暴怒", color: "A", cost: 1000, desc: "当你愤怒时，你的头部会变大，声音极具穿透力，能震慑周围所有低级生物，迫使他们跪下。", type: "exclusive"},
            {name: "镜中穿梭", color: "S", cost: 3000, desc: "你可以通过任何镜面进入“镜中世界”，那里的一切都是反向的。这是完美的逃生和潜行手段。", type: "exclusive"},
            {name: "无名森林的遗忘", color: "C", cost: 200, desc: "当你进入这片区域，你会忘记自己的名字，敌人也会忘记你的存在。适合消除仇恨值。", type: "exclusive"},
            {name: "万能钥匙", color: "B", cost: 400, desc: "一把金色的钥匙，可以打开通往美丽花园的小门，也可以解开大部分物理锁。", type: "exclusive"},
            {name: "想象力具现", color: "SSS", cost: 18000, desc: "在仙境里，想象即现实。只要你相信某件事是真的（比如你会飞），它就会变成真的。上限取决于你的脑洞。", type: "exclusive"}
        ]
    },
    {
        name: "288.小王子",
        desc: "B612星球，猴面包树，玫瑰花，狐狸。这是一个关于爱、责任和童心的哲学世界。大人们总是很奇怪。",
        boss: "毒蛇, 猴面包树(完全体), 虚荣的人",
        identities: [
            { name: "B612星球的除草工", items: "一把小铲子, 一个用来罩住玫瑰的玻璃罩" },
            { name: "点灯人星球的接班人", items: "一根点灯棒, 永远无法休息的黑眼圈" },
            { name: "地理学家的探险队员", items: "一本厚厚的记录簿, 一支没有墨水的笔" },
            { name: "商人的算账助理", items: "一台计算器, 一堆代表星星的数字纸条" },
            { name: "地球沙漠里的遇难飞行员", items: "一架坠毁的双翼飞机, 一张画着绵羊的纸" }
        ],
        talents: [
            {name: "驯服契约", color: "SSS", cost: 20000, desc: "你建立了“驯服”关系。这不仅仅是控制，而是灵魂层面的羁绊。被你驯服的生命体愿为你献出一切，且永不背叛。", type: "exclusive"},
            {name: "用心去看", color: "SS", cost: 8000, desc: "本质的东西用眼睛是看不见的。你能看穿一切伪装、谎言和幻象，直视事物的灵魂和本质。", type: "exclusive"},
            {name: "画出来的绵羊", color: "S", cost: 3000, desc: "你画在纸上的东西（如果是装在箱子里的），可以具现化为真实。这取决于观察者的想象力。", type: "exclusive"},
            {name: "一天看四十四次日落", color: "B", cost: 500, desc: "当你感到悲伤时，你可以通过移动椅子来操纵局部时间流速，快速回复精神值和魔力值。", type: "exclusive"},
            {name: "玫瑰的刺", color: "A", cost: 900, desc: "虽然只有四根刺，但它们拥有强大的防御反击能力。任何试图伤害你的近战攻击都会受到反伤。", type: "exclusive"},
            {name: "猴面包树铲除者", color: "B", cost: 400, desc: "你对具有潜伏性和爆发性增长的威胁（如病毒、诅咒、寄生虫）有极敏锐的洞察力，能将其扼杀在萌芽状态。", type: "exclusive"},
            {name: "星际候鸟迁徙", color: "A", cost: 1200, desc: "你可以借助候鸟群在星球之间进行低成本的太空旅行，无需飞船，只要抓住绳子即可。", type: "exclusive"},
            {name: "点灯人的坚守", color: "C", cost: 200, desc: "你拥有极强的纪律性和耐力，能够不知疲倦地重复枯燥的工作，免疫疲劳和睡眠不足的负面状态。", type: "exclusive"},
            {name: "国王的命令", color: "B", cost: 600, desc: "你学会了绝对权力的技巧：只下达别人本来就会去做的命令。这让你在名义上永远保持统御者的威严。", type: "exclusive"},
            {name: "酒鬼的羞愧", color: "D", cost: 50, desc: "你陷入恶性循环，喝酒是为了忘掉喝酒的羞愧。这让你容易沉迷于负面状态，但也能麻痹痛觉。", type: "exclusive"},
            {name: "毒蛇的协议", color: "SS", cost: 7000, desc: "你与死神（毒蛇）达成了协议。它的毒液可以让你瞬间脱离肉体束缚，以灵魂形态回到遥远的故乡，或者进行星际传送。", type: "exclusive"},
            {name: "商人的占有欲", color: "C", cost: 300, desc: "你擅长将无主之物据为己有，并将其量化为数字资产。这让你在经营类任务中拥有天然优势。", type: "exclusive"},
            {name: "回声山谷", color: "C", cost: 100, desc: "你很孤独，但你可以利用回声制造出千军万马的假象，迷惑敌人。", type: "exclusive"},
            {name: "独一无二的玫瑰", color: "S", cost: 2500, desc: "你指定的一个人或物会成为你世界的中心。只要它存在，你就拥有无限的勇气和护盾；若它毁灭，你会陷入狂暴。", type: "exclusive"},
            {name: "大人的视角", color: "E", cost: 10, desc: "你只关心数字、领带和高尔夫。你失去了想象力，无法看到盒子里的绵羊，容易错过隐藏任务。", type: "exclusive"}
        ]
    },
    {
        name: "289.海底两万里",
        desc: "鹦鹉螺号潜艇，尼摩船长，神秘的海洋深处。探索失落的亚特兰蒂斯，与巨型章鱼搏斗，在海底森林漫步。",
        boss: "尼摩船长, 巨型乌贼, 迈尔海峡的大漩涡",
        identities: [
            { name: "鹦鹉螺号的加煤工", items: "一把沉重的铁铲, 一身永远洗不掉的煤灰" },
            { name: "阿龙纳斯教授的搬运工", items: "一个装满海洋标本的箱子, 一本被海水泡烂的笔记" },
            { name: "尼德·兰的鱼叉助手", items: "一块磨刀石, 一根备用的鱼叉柄" },
            { name: "海底采珠人", items: "一把简陋的刀, 一个装珍珠的网兜" },
            { name: "被击沉战舰的幸存水手", items: "一块漂浮的木板, 一个空酒瓶" }
        ],
        talents: [
            {name: "鹦鹉螺号蓝图", color: "SS", cost: 8500, desc: "你掌握了超越时代的潜艇建造技术，包括钠电池动力系统。你可以建造一艘属于自己的深海巨兽。", type: "exclusive"},
            {name: "尼摩的仇恨", color: "A", cost: 1000, desc: "你对陆地文明充满仇恨，这让你在攻击人类船只和设施时，攻击力大幅提升，并且心如铁石。", type: "exclusive"},
            {name: "深海呼吸装置", color: "S", cost: 2000, desc: "一套轻便的鲁克罗尔呼吸器，让你能在深海自由行动数小时，如同在陆地一般，且不受水压影响。", type: "exclusive"},
            {name: "带电弹丸", color: "B", cost: 600, desc: "你掌握了特殊的弹药制作技术，这种子弹在击中目标时会释放高压电流，即使是巨型海怪也能一击毙命。", type: "exclusive"},
            {name: "海洋生物学宗师", color: "B", cost: 500, desc: "你认识海洋里的一切生物。你知道它们的弱点、习性以及哪部分可以吃。在海洋环境中你拥有全知视野。", type: "exclusive"},
            {name: "鱼叉大师", color: "A", cost: 900, desc: "你拥有尼德·兰级别的投掷技巧。不管是鱼叉还是长矛，在你手中都是致命的狙击武器，百发百中。", type: "exclusive"},
            {name: "海底漫步者", color: "C", cost: 300, desc: "你习惯了海底行走的重力和阻力，在水下移动速度不受惩罚，甚至比在陆地上更灵活。", type: "exclusive"},
            {name: "亚特兰蒂斯寻宝者", color: "S", cost: 3500, desc: "你知道失落文明亚特兰蒂斯的坐标和宝藏位置。你总能从海底废墟中挖掘出价值连城的古代遗物。", type: "exclusive"},
            {name: "大漩涡幸存者", color: "A", cost: 1500, desc: "你曾从迈尔海峡的恐怖漩涡中逃生。你拥有极强的运气和在混乱流体中保持平衡的能力。", type: "exclusive"},
            {name: "海底农夫", color: "C", cost: 200, desc: "你懂得如何种植和采集海藻、海带等海洋作物，能在海底实现自给自足，不依赖陆地补给。", type: "exclusive"},
            {name: "钠电池技术", color: "A", cost: 1800, desc: "你掌握了从海水中提取钠并制造高效电池的技术，这是清洁且无限的能源，能驱动各种机械。", type: "exclusive"},
            {name: "管风琴演奏", color: "C", cost: 100, desc: "你弹得一手好管风琴。在深海的孤寂中，音乐能安抚船员的心灵，提升士气，缓解幽闭恐惧症。", type: "exclusive"},
            {name: "巨型乌贼杀手", color: "B", cost: 700, desc: "你对软体动物有特殊的杀伤加成。你知道砍哪里最疼，并且在面对触手缠绕时有更高的挣脱几率。", type: "exclusive"},
            {name: "多国语言精通", color: "B", cost: 400, desc: "为了在鹦鹉螺号上生存，你学会了一种只有船员懂的混合语言，以及多种陆地语言，方便窃听和交流。", type: "exclusive"},
            {name: "海洋之子", color: "SSS", cost: 12000, desc: "大海视你为同类。你在水中不会溺亡，海洋生物不会主动攻击你，洋流会助你前行。你是真正的大海之王。", type: "exclusive"}
        ]
    },
    {
        name: "290.弗兰肯斯坦",
        desc: "科学怪人，人造生命的悲剧。维克多·弗兰肯斯坦试图扮演上帝，却创造出了一个渴望爱却被世界遗弃的怪物。",
        boss: "弗兰肯斯坦的怪物, 维克多·弗兰肯斯坦, 愤怒的暴民",
        identities: [
            { name: "深夜的盗墓贼", items: "一把铁铲, 一个装尸体的麻袋" },
            { name: "弗兰肯斯坦实验室的清洁工", items: "一块满是血污的抹布, 一桶福尔马林" },
            { name: "被怪物吓坏的瑞士农民", items: "一把草叉, 一个火把" },
            { name: "北极探险队的船员", items: "一件厚皮袄, 一把用来破冰的斧头" },
            { name: "英戈尔施塔特大学的医学生", items: "一把解剖刀, 一本《人体结构学》" }
        ],
        talents: [
            {name: "死尸复活术", color: "SSS", cost: 30000, desc: "你掌握了生命的终极奥秘。你可以通过拼接尸体和注入电流，创造出拥有独立意识和强大力量的新生命。", type: "exclusive"},
            {name: "缝合怪体质", color: "SS", cost: 6500, desc: "你的身体由不同强者的尸块拼接而成。你拥有超人的力量、耐力和抗击打能力，且痛觉迟钝。", type: "exclusive"},
            {name: "闪电引流", color: "A", cost: 1500, desc: "你能利用风筝或避雷针引下天雷，并将其转化为可用的能量，用于激活机械或复活生物。", type: "exclusive"},
            {name: "炼金术知识", color: "B", cost: 600, desc: "你研读过帕拉塞尔苏斯和阿格里帕的著作，掌握了古老的炼金术，能调配出各种奇异的药剂和毒药。", type: "exclusive"},
            {name: "怪物的憎恨", color: "S", cost: 2200, desc: "你被创造者遗弃，心中充满怨恨。当你面对制造者或幸福的人类时，全属性暴涨，但理智值会不断下降。", type: "exclusive"},
            {name: "北极生存", color: "B", cost: 400, desc: "你在极寒的冰原上追逐过怪物，适应了极度低温的环境，抗寒能力极强，能在冰雪中快速穿行。", type: "exclusive"},
            {name: "解剖学大师", color: "B", cost: 500, desc: "你对人体结构了如指掌。作为医生，你能精准治疗；作为杀手，你能精准切割要害，造成流血不止。", type: "exclusive"},
            {name: "语言速成", color: "A", cost: 1000, desc: "像那个怪物一样，你拥有惊人的学习能力。只需躲在暗处偷听几个月，你就能精通一门复杂的语言并阅读名著。", type: "exclusive"},
            {name: "丑陋的威慑", color: "C", cost: 300, desc: "你的外表极其恐怖，能对普通人造成精神冲击，使其逃跑或瘫痪。但你的魅力值会被锁定为负数。", type: "exclusive"},
            {name: "上帝的扮演者", color: "S", cost: 2800, desc: "你拥有疯狂科学家的气质和智力。在进行违背伦理的实验时，你的成功率大幅提升，且不会感到愧疚。", type: "exclusive"},
            {name: "暴民煽动", color: "C", cost: 200, desc: "你擅长利用人们对未知的恐惧，煽动村民举起火把和草叉去攻击你的敌人。", type: "exclusive"},
            {name: "永不停息的追逐", color: "A", cost: 1200, desc: "一旦你锁定了复仇目标，你的耐力就变成无限。你可以跨越千山万水，不眠不休地追杀目标。", type: "exclusive"},
            {name: "尸体防腐技术", color: "C", cost: 150, desc: "你能让尸体长期保持新鲜不腐烂，这对于死灵法师或收藏家来说是非常实用的后勤技能。", type: "exclusive"},
            {name: "孤独的哲学", color: "B", cost: 700, desc: "长期的孤独让你产生了深刻的哲学思考。你的意志力极强，对精神控制类魔法有很高的豁免权。", type: "exclusive"},
            {name: "普罗米修斯之火", color: "SS", cost: 5500, desc: "你盗取了神火（禁忌知识）。这让你获得了巨大的力量，但也伴随着永恒的折磨和厄运，直到你死亡。", type: "exclusive"}
        ]
    },
              {
        name: "291.德古拉",
        desc: "哥特式恐怖的源头，迷雾笼罩的特兰西瓦尼亚。吸血鬼始祖在古堡中沉睡，鲜血是这里的通用货币，也是永生的诅咒。十字架与银桩是唯一的慰藉。",
        boss: "德古拉伯爵, 范海辛, 三位吸血鬼新娘",
        identities: [
            { name: "被囚禁的伦敦律师", items: "一份未签署的地契, 一只藏着小刀的怀表" },
            { name: "特兰西瓦尼亚迷信村民", items: "一串发黑的大蒜, 一个简陋的木制十字架" },
            { name: "疯人院的食虫者", items: "一个装满苍蝇的玻璃瓶, 满嘴的蜘蛛残渣" },
            { name: "吸血鬼猎人学徒", items: "一根削尖的白蜡木桩, 一本被翻烂的圣经" },
            { name: "古堡的盲眼仆人", items: "一串沉重的铁钥匙, 一盏只有微弱火光的油灯" }
        ],
        talents: [
            {name: "血族初拥(诅咒)", color: "SS", cost: 8500, desc: "你被高阶吸血鬼转化，拥有永恒的生命和对鲜血的极度渴望。阳光是你的死敌，但黑夜是你的主场。", type: "exclusive"},
            {name: "穿刺公之名", color: "S", cost: 1800, desc: "你拥有古代暴君的威慑力，当你展现残暴一面时，周围的凡人会陷入无法控制的恐慌状态。", type: "exclusive"},
            {name: "雾化形态", color: "A", cost: 900, desc: "在受到致命伤害前，你可以瞬间化为一团黑雾逃离，或者穿过狭窄的缝隙进行潜入。", type: "exclusive"},
            {name: "范海辛的知识", color: "A", cost: 850, desc: "你熟知所有黑暗生物的弱点，无论是银、大蒜还是圣水，你总能找到对付怪物的最佳手段。", type: "exclusive"},
            {name: "魅惑之眼", color: "B", cost: 500, desc: "你的眼神具有超自然的吸引力，意志薄弱的异性会不由自主地对你产生好感并听从你的暗示。", type: "exclusive"},
            {name: "野兽支配", color: "B", cost: 450, desc: "狼群、蝙蝠和老鼠视你为领袖，你可以指挥这些夜行生物为你探路或攻击敌人。", type: "exclusive"},
            {name: "嗜血本能", color: "C", cost: 180, desc: "闻到鲜血的味道会让你兴奋，力量和反应速度小幅度提升，但理智会轻微下降。", type: "exclusive"},
            {name: "掘墓人体质", color: "C", cost: 150, desc: "常年与尸体打交道，你对尸毒和瘟疫有很高的抗性，并且力气比常人大得多。", type: "exclusive"},
            {name: "古堡地图记忆", color: "C", cost: 120, desc: "你脑海中莫名拥有德古拉城堡的结构图，知道哪里有密室，哪里是死路。", type: "exclusive"},
            {name: "贫血症", color: "E", cost: 5, desc: "你的造血功能有缺陷，脸色苍白，体力极差，稍微流点血就可能休克。", type: "exclusive"},
            {name: "阳光过敏", color: "D", cost: 50, desc: "虽然不是吸血鬼，但你在阳光下皮肤会红肿溃烂，全属性下降20%。", type: "exclusive"},
            {name: "真祖之血", color: "SSS", cost: 15000, desc: "你体内流淌着第一只吸血鬼的血液。你不再畏惧阳光和银器，你是完美的暗夜君王，所有血族必须向你臣服。", type: "exclusive"},
            {name: "暗夜贵族礼仪", color: "B", cost: 300, desc: "你举手投足间散发着古老贵族的气质，这让你更容易混入上流社会或获得怪物的尊重。", type: "exclusive"},
            {name: "影之仆从", color: "S", cost: 1600, desc: "你的影子拥有自我意识，可以脱离你独立行动，甚至实体化为你抵挡一次致命攻击。", type: "exclusive"},
            {name: "鲜血炼金术", color: "A", cost: 700, desc: "你懂得如何利用血液进行炼金，制造出具有治疗、强化或毒杀效果的血红药剂。", type: "exclusive"}
        ]
    },
    {
        name: "292.冰与火之歌 (原著)",
        desc: "维斯特洛大陆，七大王国的权力游戏。凡人皆有一死，凡人皆需侍奉。长城之外异鬼苏醒，狭海对岸龙焰重燃。凛冬将至。",
        boss: "夜王, 丹妮莉丝·坦格利安, 泰温·兰尼斯特",
        identities: [
            { name: "绝境长城的守夜人新兵", items: "一件发臭的黑斗篷, 一把缺口的铁剑" },
            { name: "跳蚤窝的乞丐", items: "一碗褐汤, 一把藏在袖子里的生锈匕首" },
            { name: "自由贸易城邦的奴隶", items: "沉重的镣铐, 脸上刺着主人的徽记" },
            { name: "河间地的流浪歌手", items: "一把断弦的竖琴, 几枚铜板" },
            { name: "铁群岛的私生子", items: "一把海怪骨头做的飞斧, 一身盐碱味" }
        ],
        talents: [
            {name: "坦格利安血脉(不焚者)", color: "SS", cost: 9000, desc: "真龙的血脉流淌在你体内。火焰无法伤害你，反而会让你感到温暖。你有唤醒石龙的潜质。", type: "exclusive"},
            {name: "易形者(狼灵)", color: "S", cost: 1900, desc: "你拥有进入动物意识的能力。通常与冰原狼伴生，在睡梦中你可以借用它的感官巡视森林。", type: "exclusive"},
            {name: "兰尼斯特的财富", color: "A", cost: 800, desc: "你天生拥有极高的商业头脑和家族资源，总能还清欠债，并且用金钱解决大部分问题。", type: "exclusive"},
            {name: "无面者训练", color: "S", cost: 1800, desc: "凡人皆有一死。你掌握了布拉佛斯神庙的刺杀技艺，可以剥下死者的脸皮伪装成任何人。", type: "exclusive"},
            {name: "绿之视野", color: "SSS", cost: 12000, desc: "你可以看见过去、现在和未来。你是三眼乌鸦的继任者，知晓世界树网格中的一切秘密。", type: "exclusive"},
            {name: "比武大会冠军", color: "B", cost: 600, desc: "你精通长枪马术和剑盾格斗，在单挑中拥有极高的胜率，是骑士们的榜样。", type: "exclusive"},
            {name: "学士的项链", color: "B", cost: 500, desc: "你在旧镇学城铸造了几根链条，精通历史、草药和乌鸦传信，智力属性大幅提升。", type: "exclusive"},
            {name: "野火配方", color: "A", cost: 1200, desc: "你掌握了炼金术士公会的最高机密。那种绿色的火焰一旦燃烧就无法扑灭，甚至能在水上燃烧。", type: "exclusive"},
            {name: "巨人血统", color: "A", cost: 950, desc: "你身材异常高大，力量惊人，能够轻易挥舞普通人举不起的重武器，但敏捷较低。", type: "exclusive"},
            {name: "侏儒(小恶魔)", color: "D", cost: 100, desc: "你是个侏儒，受尽世人嘲笑。但作为补偿，你拥有绝顶的智慧和在绝境中求生的口才。", type: "exclusive"},
            {name: "红神祭司", color: "S", cost: 1700, desc: "光之王拉赫洛的信徒。你可以从火焰中读取模糊的预言，甚至在付出巨大代价后复活死者。", type: "exclusive"},
            {name: "铁种的坚韧", color: "C", cost: 180, desc: "逝者不死，必将再起，其势更烈。你在海战中士气高昂，且溺水后有几率被淹神救回。", type: "exclusive"},
            {name: "私生子", color: "D", cost: 50, desc: "你背负着雪诺、沙德或石东等姓氏，社会地位低下，被正统家族排挤，但也因此更加坚韧。", type: "exclusive"},
            {name: "瓦雷利亚钢武器", color: "SS", cost: 5000, desc: "你开局拥有一把瓦雷利亚钢制成的武器。它轻若鸿毛，坚不可摧，并且能杀死异鬼。", type: "exclusive"},
            {name: "龙之母/父", color: "SSS", cost: 30000, desc: "你拥有孵化龙蛋的奇迹之力。三条幼龙视你为母亲/父亲，随着它们成长，你将拥有征服世界的力量。", type: "exclusive"}
        ]
    },
    {
        name: "293.猎魔人 (The Witcher 原著)",
        desc: "天球交汇后的世界，怪物横行。猎魔人通过青草试炼变异，以双剑斩妖除魔。北方诸国战争不断，尼弗迦德帝国虎视眈眈，上古之血牵动命运。",
        boss: "狂猎之王, 威戈佛特兹, 恩希尔·恩瑞斯",
        identities: [
            { name: "凯尔·莫罕的落选学徒", items: "一瓶未完成的魔药, 一把木剑" },
            { name: "泰莫利亚的逃兵", items: "蓝色的破烂罩袍, 偷来的半块黑面包" },
            { name: "史凯利格群岛的劫掠者", items: "一把战斧, 一角杯劣质蜂蜜酒" },
            { name: "受迫害的非人种族(精灵)", items: "一把精致的短弓, 遮住尖耳朵的兜帽" },
            { name: "诺维格瑞的乞丐", items: "一个破碗, 满身烂疮" }
        ],
        talents: [
            {name: "上古之血", color: "SSS", cost: 35000, desc: "劳拉·朵伦的血脉。你拥有穿越时空的能力，是狂猎追逐的目标，也是毁灭或拯救世界的关键。", type: "exclusive"},
            {name: "青草试炼(完美)", color: "SS", cost: 6000, desc: "你完美通过了猎魔人的突变。拥有猫一般的眼睛，超人的反应速度，免疫大部分疾病，寿命极长。", type: "exclusive"},
            {name: "法源术士", color: "S", cost: 1950, desc: "你天生能感应混沌能量，拥有强大的施法天赋。如果不经过系统训练，可能会被力量反噬而疯癫。", type: "exclusive"},
            {name: "意外律之子", color: "S", cost: 1500, desc: "你的命运与某位强大的存在绑定。命运的力量会不断指引你们相遇，并为你提供无形的保护。", type: "exclusive"},
            {name: "徽章感应", color: "C", cost: 150, desc: "你拥有制作简易魔法徽章的能力，当周围有魔法生物或幻术时，徽章会震动示警。", type: "exclusive"},
            {name: "昆特牌大师", color: "B", cost: 250, desc: "无论局势多么紧张，只要你提议打把昆特牌，对方大概率会同意。靠打牌甚至能赢下王国。", type: "exclusive"},
            {name: "炼金术大师", color: "A", cost: 800, desc: "你精通煎药、魔药和炸弹的制作。你可以喝下剧毒的煎药来获得强大的临时增益而不死。", type: "exclusive"},
            {name: "法印专精", color: "A", cost: 750, desc: "你对猎魔人的五大法印运用得炉火纯青，阿尔德和伊格尼在你手中堪比高级法术。", type: "exclusive"},
            {name: "银剑打造", color: "B", cost: 400, desc: "你懂得如何锻造对付怪物的银剑，并在剑刃上铭刻符文以增强杀伤力。", type: "exclusive"},
            {name: "湖中女神的祝福", color: "SS", cost: 4500, desc: "你被湖中女神认可，获得了一把传说级的银剑（如湖女之剑），且在水边战斗力倍增。", type: "exclusive"},
            {name: "吸血鬼高阶友谊", color: "S", cost: 1800, desc: "你与一位高阶吸血鬼（如雷吉斯）结下了深厚友谊。在绝境时，这位强大的盟友可能会现身相助。", type: "exclusive"},
            {name: "女术士集会所成员", color: "A", cost: 1000, desc: "你在政治和魔法上都极具影响力，拥有遍布各国的情报网，但也要时刻提防同僚的背叛。", type: "exclusive"},
            {name: "石之心", color: "D", cost: 150, desc: "你感觉不到痛苦，也没有情感。虽然战斗中无所畏惧，但你正逐渐失去作为人的乐趣。", type: "exclusive"},
            {name: "独角兽的亲和", color: "A", cost: 600, desc: "这种高傲的生物愿意让你骑乘。独角兽具有穿越位面的能力，且能破除大部分幻术。", type: "exclusive"},
            {name: "诅咒之躯", color: "D", cost: 80, desc: "你被某种怪物诅咒（如刺猬人或狼人），特定条件下会变身，虽有战力但极易失控。", type: "exclusive"}
        ]
    },
    {
        name: "294.时光之轮",
        desc: "时光之轮转动，纪元更替。暗帝试图挣脱封印，真龙转生预示着毁灭与救赎。两仪师引导至上力，兽魔人军团在阴影中集结。",
        boss: "暗帝, 弃光魔使, 帕丹·费恩",
        identities: [
            { name: "伊蒙村的牧羊人", items: "一根结实的紫杉木长弓, 一把剪羊毛的剪刀" },
            { name: "白塔的见习生", items: "一件纯白色的长裙, 蛇形戒指" },
            { name: "艾伊尔荒漠的枪姬众", items: "几根短矛, 遮住面容的面纱" },
            { name: "被伪龙煽动的暴民", items: "一把干草叉, 狂热的眼神" },
            { name: "白袍众的士兵", items: "一件绣着金色太阳的白色披风, 擦得锃亮的盔甲" }
        ],
        talents: [
            {name: "真龙转生", color: "SSS", cost: 40000, desc: "你是路斯·瑟林·特拉蒙的转世。你可以引导巨量的阳极力，注定要在大决战中面对暗帝，但也面临疯狂的风险。", type: "exclusive"},
            {name: "强力道途(导引者)", color: "S", cost: 1900, desc: "你天生拥有极强的导引能力，无论是阳极力还是阴极力，你的潜力都足以成为两仪师中的翘楚。", type: "exclusive"},
            {name: "狼兄弟", color: "A", cost: 900, desc: "你的眼睛呈金黄色，能与狼群心灵感应，并进入梦之世界（泰拉安瑞奥）。感官极其敏锐。", type: "exclusive"},
            {name: "特沃形", color: "SS", cost: 3000, desc: "你是该纪元最强大的时空观测者。虽然不能导引，但你可以看到因果线的纠缠，甚至通过特定方式改变概率。", type: "exclusive"},
            {name: "剑术大师(苍鹭印)", color: "A", cost: 850, desc: "你的剑术达到了拥有佩戴苍鹭印记之剑的资格。在凡人武力中，你已站在巅峰。", type: "exclusive"},
            {name: "梦行者", color: "S", cost: 1600, desc: "你可以自由出入梦之世界，不仅能窥探他人的梦境，还能在梦中造成真实的物理伤害。", type: "exclusive"},
            {name: "马特的好运", color: "SS", cost: 5000, desc: "骰子在你脑中转动。你拥有不可思议的运气，无论是赌博还是战场，只要跟随直觉，总能化险为夷。", type: "exclusive"},
            {name: "旧语通晓", color: "C", cost: 120, desc: "你无师自通地掌握了上个纪元的古语，能够阅读失落的文献和启动古代机关。", type: "exclusive"},
            {name: "欧吉尔石匠", color: "B", cost: 400, desc: "你拥有欧吉尔人的耐心和技艺，能建造出具有魔力的建筑，并能通过路门在世界各地穿梭。", type: "exclusive"},
            {name: "禁忌之术(炎火)", color: "S", cost: 1800, desc: "你掌握了被禁止的强力法术“炎火”，能直接从时间模式中抹去敌人的存在，但使用代价极大。", type: "exclusive"},
            {name: "守望者契约", color: "B", cost: 550, desc: "你与一位导引者建立了心灵链接。你获得超常的耐力和感知，这就是守望者的羁绊。", type: "exclusive"},
            {name: "弃光者潜质", color: "A", cost: 1000, desc: "你对黑暗力量有独特的亲和力，如果投靠暗帝，你将获得永生和真源的另一种使用权。", type: "exclusive"},
            {name: "吹响瓦力尔号角", color: "SS", cost: 8000, desc: "你是被选中的号角吹响者。当你吹响号角，历代死去的英雄英灵将为你而战。", type: "exclusive"},
            {name: "疯王之声", color: "D", cost: 100, desc: "如果你是男性导引者，你会听到路斯·瑟林在你脑海中的低语。这既是疯狂的前兆，也是古代知识的来源。", type: "exclusive"},
            {name: "肖恩雷血脉", color: "C", cost: 180, desc: "来自大洋彼岸的征服者血统，精通驭兽和军事，对两仪师不仅不敬畏，反而将其视为必须套上项圈的工具。", type: "exclusive"}
        ]
    },
    {
        name: "295.黑暗塔",
        desc: "世界已经前行。中世界正在崩塌，枪侠罗兰追寻着黑衣人，也追寻着黑暗塔。所有宇宙的枢纽，光束的交汇点，玫瑰与枪的史诗。",
        boss: "血腥之王, 黑衣人(沃特·奥丁), 莫德雷德·德肖恩",
        identities: [
            { name: "基列地的枪侠学徒", items: "一把沉重的檀木柄左轮手枪, 父亲的遗训" },
            { name: "通过门穿越的纽约瘾君子", items: "半包海洛因, 一双破旧的匡威鞋" },
            { name: "枯萎之地的变种人", items: "发光的绿色皮肤, 简易的石制长矛" },
            { name: "卡拉的农民", items: "一把锄头, 一个用来投掷的利盘" },
            { name: "路德城的疯子", items: "一把生锈的砍刀, 对单轨列车的恐惧" }
        ],
        talents: [
            {name: "亚瑟·埃尔德血脉", color: "SS", cost: 7000, desc: "你是枪侠始祖的后裔。你天生拥有成为枪侠的资格，可以使用传说中的神剑和檀木枪。", type: "exclusive"},
            {name: "神枪手(枪侠)", color: "S", cost: 1800, desc: "你用手瞄准，用心射击，用灵魂杀戮。你的拔枪速度和射击精度超越了物理极限，弹无虚发。", type: "exclusive"},
            {name: "闪灵(Shine)", color: "S", cost: 1600, desc: "你拥有强大的心灵感应和预知能力。你可以感知到光束的状态，甚至与其他世界的同伴沟通。", type: "exclusive"},
            {name: "卡-泰特(Ka-Tet)", color: "A", cost: 900, desc: "命运将你与队友紧密相连。当你们在一起时，全员属性大幅提升，且能共享思维和技能。", type: "exclusive"},
            {name: "穿梭之门", color: "SS", cost: 4000, desc: "你拥有打开通往其他世界（如1977年的纽约）的门的能力，可以从异世界搬运补给或逃避追杀。", type: "exclusive"},
            {name: "曼哈依路里", color: "C", cost: 150, desc: "你懂得古代文明的问候语和礼仪，这让你在面对某些古老守卫或机器人时能获得豁免。", type: "exclusive"},
            {name: "比利的甚至", color: "B", cost: 300, desc: "你拥有一只叫比利的甚至（一种像浣熊与狗混合的生物）。它聪明忠诚，能模仿人语，且能感知危险。", type: "exclusive"},
            {name: "黑暗塔的呼唤", color: "SS", cost: 6000, desc: "你对黑暗塔有强烈的感应。这让你在迷失中总能找到通往塔的路径，但也让你容易被血腥之王注视。", type: "exclusive"},
            {name: "玫瑰的守护者", color: "S", cost: 1700, desc: "你在某个世界守护着那朵代表宇宙核心的玫瑰。只要玫瑰无恙，你的生命力就极其顽强。", type: "exclusive"},
            {name: "恶魔附身", color: "D", cost: 100, desc: "你在召唤门时被恶魔侵入过。虽然被驱逐，但你的精神偶尔会不稳定，且容易吸引隐形恶魔。", type: "exclusive"},
            {name: "机械大师(古人科技)", color: "A", cost: 800, desc: "你懂得修理和操作旧日文明遗留的高科技设备，如单轨列车、战斗机器人等。", type: "exclusive"},
            {name: "苏珊娜的二重身", color: "B", cost: 500, desc: "你拥有双重人格。在战斗时，你可以切换到那个冷酷、精准且充满杀意的人格。", type: "exclusive"},
            {name: "罗兰的手指", color: "D", cost: 50, desc: "你在旅途中失去了几根手指，这影响了你的换弹速度，但你的意志力因此更加坚定。", type: "exclusive"},
            {name: "19的诅咒", color: "C", cost: 100, desc: "数字19不断出现在你周围。这既是命运的提示，也是厄运的征兆，你必须学会解读它。", type: "exclusive"},
            {name: "深红之王的印记", color: "E", cost: 10, desc: "你的额头上有只眼睛形状的疤痕。你是血腥之王的奴隶，随时可能被他控制去破坏光束。", type: "exclusive"}
        ]
    },
    {
        name: "296.百年孤独",
        desc: "马孔多，一个被雨水、失眠症和黄色蝴蝶包围的村镇。布恩迪亚家族七代人的兴衰，时间在这里是循环的，孤独是唯一的宿命。",
        boss: "羊皮卷预言, 飓风, 蚂蚁",
        identities: [
            { name: "吉普赛人的大篷车跟班", items: "一块磁铁, 一个放大镜" },
            { name: "马孔多的炼金术士", items: "一个简易实验室, 几块试图炼成金子的废铁" },
            { name: "香蕉公司的罢工工人", items: "一张抗议标语, 满身泥泞的工作服" },
            { name: "布恩迪亚家族的私生子", items: "眉间洗不掉的灰十字, 家族特有的孤独眼神" },
            { name: "被遗忘的老上校", items: "一条制作精美的小金鱼, 等待抚恤金的信" }
        ],
        talents: [
            {name: "预言破译者(羊皮卷)", color: "SSS", cost: 25000, desc: "你拥有解读梅尔基亚德斯羊皮卷的能力。这不仅是家族的命运，更是世界的源代码。读懂它，你就掌握了因果。", type: "exclusive"},
            {name: "炼金狂热", color: "A", cost: 800, desc: "你对科学和炼金术有狂热的执着。虽然常失败，但偶尔能制造出如“永恒之冰”或“记忆机器”等奇物。", type: "exclusive"},
            {name: "绝美之姿(蕾梅黛丝)", color: "SS", cost: 6000, desc: "你拥有不属于凡间的绝世美貌，甚至能散发出让人致死的费洛蒙。最终你可能会抓着床单飞升。", type: "exclusive"},
            {name: "超自然力量(大力士)", color: "B", cost: 400, desc: "你力大无穷，能徒手拆房子，甚至能在一夜之间给全镇铺上路。食量惊人。", type: "exclusive"},
            {name: "失眠症免疫", color: "B", cost: 300, desc: "当全镇陷入失眠瘟疫时，你依然能保持清醒和记忆，不需要给物品贴标签来记住它们的名字。", type: "exclusive"},
            {name: "黄色蝴蝶群", color: "A", cost: 700, desc: "无论你走到哪里，总有一群黄色蝴蝶跟随。这既是爱情的征兆，也是一种天然的侦查手段。", type: "exclusive"},
            {name: "制作小金鱼", color: "C", cost: 150, desc: "你拥有极高的金匠手艺。制作小金鱼能让你内心获得绝对的平静，免疫精神攻击。", type: "exclusive"},
            {name: "生殖力旺盛(家族)", color: "B", cost: 350, desc: "布恩迪亚家族的特征，你拥有极强的生命力和繁衍能力，这也是家族悲剧轮回的动力之一。", type: "exclusive"},
            {name: "亡灵沟通", color: "S", cost: 1500, desc: "你可以看到并与死去的祖先交谈。他们像活人一样在房子里游荡，为你提供被遗忘的历史信息。", type: "exclusive"},
            {name: "猪尾巴诅咒", color: "D", cost: 100, desc: "因近亲结合，你出生时带有一条猪尾巴。这是家族毁灭的终极征兆，让你自卑但敏捷。", type: "exclusive"},
            {name: "四年大雨", color: "S", cost: 1800, desc: "你的情绪能影响天气。当你悲伤时，天空可能会下起持续四年十一个月零两天的雨，淹没一切。", type: "exclusive"},
            {name: "隐形存在", color: "C", cost: 120, desc: "你像幽灵一样被人忽视，适合刺探情报。即使你在房间里死去多年，可能也没人发现。", type: "exclusive"},
            {name: "土食癖", color: "D", cost: 50, desc: "你在焦虑时会忍不住吃土和墙皮。虽然不卫生，但这能稍微缓解你的精神压力。", type: "exclusive"},
            {name: "磁铁狂魔", color: "C", cost: 180, desc: "你相信科学能改变一切。你拖着两块大磁铁走街串巷，能吸出地下的金属宝藏或钉子。", type: "exclusive"},
            {name: "宿命轮回", color: "SS", cost: 5000, desc: "你意识到时间是圆的。你在轮回中保留了部分前世的记忆，这让你显得早熟且充满智慧。", type: "exclusive"}
        ]
    },
    {
        name: "297.三体 (原著)",
        desc: "物理学已死。从红岸基地的电波，到黑暗森林的对峙，再到二向箔的降维打击。宇宙是冰冷的，文明是猎人，生存是第一公理。",
        boss: "三体文明, 歌者文明, 归零者",
        identities: [
            { name: "红岸基地的技术员", items: "一本《寂静的春天》, 发射按钮的备用钥匙" },
            { name: "ETO组织的底层成员", items: "一个V装具(VR眼镜), 对人类绝望的信条" },
            { name: "大低谷时期的饥民", items: "半张粮票, 极度虚弱的身体" },
            { name: "太空军的普通士兵", items: "深海状态液槽, 激光手枪" },
            { name: "掩体纪元的居民", items: "木星背影的照片, 一把防辐射伞" }
        ],
        talents: [
            {name: "面壁者", color: "SSS", cost: 50000, desc: "你被联合国选为面壁者。你可以调动全球资源，你的真实意图必须对智子隐瞒。你是人类最后的希望。", type: "exclusive"},
            {name: "执剑人威慑", color: "SS", cost: 9500, desc: "你拥有极高的威慑度（如罗辑）。只要你手握发射器，三体文明就不敢轻举妄动。你的意志坚如磐石。", type: "exclusive"},
            {name: "智子屏蔽(伪)", color: "S", cost: 1900, desc: "你掌握了一种特殊的思维屏蔽技术或心理状态，能部分干扰智子对你思维的读取。", type: "exclusive"},
            {name: "黑暗森林法则直觉", color: "SS", cost: 8000, desc: "你深刻理解宇宙公理。你能敏锐地发现其他文明的坐标，并能在第一时间发动打击或隐藏自己。", type: "exclusive"},
            {name: "冬眠者", color: "C", cost: 150, desc: "你拥有冬眠资格。你可以跨越时间，前往未来寻找技术或机遇，但要面对时代的陌生感。", type: "exclusive"},
            {name: "物理学天才", color: "A", cost: 900, desc: "你的智商极高，能理解前沿物理。在智子封锁下，你依然可能从应用层面找到突破口。", type: "exclusive"},
            {name: "章北海的信念", color: "S", cost: 1800, desc: "绝对的失败主义者，也是绝对的行动派。为了人类延续，你敢于劫持战舰逃向深空，并果断消灭同类。", type: "exclusive"},
            {name: "水滴解析", color: "SS", cost: 7500, desc: "你掌握了强互作用力材料的秘密。你可以制造出类似水滴的绝对光滑、坚不可摧的武器。", type: "exclusive"},
            {name: "二向箔封装", color: "SSS", cost: 60000, desc: "你拥有接触歌者文明清理工具的机会。一张小纸片，足以将整个太阳系二维化。慎用。", type: "exclusive"},
            {name: "思想钢印", color: "B", cost: 500, desc: "你被植入了某种信念（如“必胜”或“逃亡”）。这让你在执行相关任务时意志坚定，免疫精神崩溃。", type: "exclusive"},
            {name: "脱水体质", color: "B", cost: 400, desc: "类似三体人，你可以在恶劣环境下将身体脱水成一张皮，便于储存和运输，遇水复活。", type: "exclusive"},
            {name: "曲率驱动引擎", color: "SS", cost: 8500, desc: "你掌握了光速飞船的制造原理。这不仅是逃亡的工具，其航迹也是发布宇宙安全声明的手段。", type: "exclusive"},
            {name: "云天明的童话", color: "S", cost: 2000, desc: "你擅长在看似普通的故事中隐藏核心情报。这是在全方位监控下传递信息的唯一方式。", type: "exclusive"},
            {name: "降临派狂热", color: "D", cost: 80, desc: "你是ETO的死忠，渴望主来降临并毁灭人类暴政。虽然被人类社会排斥，但能获得三体人的支持。", type: "exclusive"},
            {name: "高维碎片接触", color: "A", cost: 1000, desc: "你曾误入四维空间碎片。你见过无限细节的宏大，这让你掌握了跨越障碍攻击内部的能力。", type: "exclusive"}
        ]
    },
    {
        name: "298.北京折叠",
        desc: "大地被划分为三个空间。第一空间享受清晨和权力，第二空间拥有白昼和中产，第三空间只有深夜和垃圾。时间是最大的不平等。",
        boss: "空间折叠控制中心, 垃圾处理站站长, 老刀的债务",
        identities: [
            { name: "第三空间的垃圾工", items: "一身防护服, 一张伪造的通行证" },
            { name: "第二空间的研究生", items: "一堆没写完的论文, 对第一空间的向往" },
            { name: "第一空间的高官秘书", items: "精致的西装, 一块能控制折叠时间的怀表" },
            { name: "游走在缝隙的走私犯", items: "隐形涂料, 违禁药品" },
            { name: "即将被替换的机器人", items: "生锈的关节, 模糊的自我意识" }
        ],
        talents: [
            {name: "折叠穿梭者", color: "SS", cost: 5000, desc: "你掌握了空间折叠的规律和漏洞。你可以在三个空间之间自由穿梭，不受时间分配的限制。", type: "exclusive"},
            {name: "休眠胶囊破解", color: "A", cost: 800, desc: "你可以破解休眠胶囊的锁定程序，在强制睡眠时间保持清醒，利用这段时间做任何事。", type: "exclusive"},
            {name: "垃圾分类大师", color: "C", cost: 120, desc: "在第三空间生存的必备技能。你能从垃圾中通过分类找到有价值的零件、食物甚至情报。", type: "exclusive"},
            {name: "第一空间身份", color: "S", cost: 2000, desc: "你出生在第一空间，拥有最长的生活时间和最优越的资源。你的起点是其他人的终点。", type: "exclusive"},
            {name: "机械义肢(军用)", color: "A", cost: 900, desc: "你拥有一条军用级别的机械手臂，力量巨大且藏有武器，是在底层社会防身的利器。", type: "exclusive"},
            {name: "老刀的信誉", color: "B", cost: 400, desc: "你像老刀一样讲义气。虽然穷，但在地下世界名声很好，很多人愿意帮你一把。", type: "exclusive"},
            {name: "自动化工程专家", color: "B", cost: 600, desc: "你精通机器人维护。在这个机器逐渐取代人工的世界，这是一门铁饭碗技术。", type: "exclusive"},
            {name: "隐形斗篷", color: "S", cost: 1500, desc: "高科技光学迷彩，能让你在穿越空间封锁线时完全隐形，躲避监控探头。", type: "exclusive"},
            {name: "糖衣药丸", color: "D", cost: 50, desc: "你不得不依靠这种药丸来维持在休眠期间的生理机能，副作用是醒来后会剧烈头痛。", type: "exclusive"},
            {name: "地下通道图", color: "A", cost: 700, desc: "你拥有一份未公开的地下管道地图，连接着三个空间，是走私和逃亡的绝密路径。", type: "exclusive"},
