    ],
    talents: [
        {name: "龙神血脉(觉醒)", color: "SSS", cost: 50000, desc: "集金龙王与银龙王于一身，万兽之神。能压制所有兽武魂，掌控所有元素，肉身无敌，注定统治宇宙。", type: "exclusive"},
        {name: "星际指挥官", color: "A", cost: 800, desc: "你在星战推演中拥有极高的天赋，能指挥庞大的舰队进行协同作战，是成为联邦舰长的最佳人选。", type: "exclusive"},
        {name: "天圣裂渊戟(投影)", color: "SS", cost: 7000, desc: "深渊圣君神器的投影，拥有无视防御的特性。攻击时附带深渊吞噬效果，是近战大杀器。", type: "exclusive"},
        {name: "生命亲和体质", color: "S", cost: 1600, desc: "你在永恒之树旁修炼速度提升十倍，生命能量会主动滋养你的身体，几乎百毒不侵，长寿无疆。", type: "exclusive"},
        {name: "寻宝兽契约", color: "A", cost: 1200, desc: "你与一只寻宝兽签订了契约，它能帮你发现附近的天材地宝，还能帮你掩盖气息，模拟幻境。", type: "exclusive"},
        {name: "战舰驾驶王牌", color: "B", cost: 500, desc: "无论是战机还是护卫舰，你都能开出花来。在星际空战中，你的存活率和击坠数远超常人。", type: "exclusive"},
        {name: "锻造宗师(神级)", color: "SS", cost: 5500, desc: "你能进行天锻，将金属赋予神性，是制作神级斗铠和战舰核心的关键人物，全联邦的座上宾。", type: "exclusive"},
        {name: "空之虫空间掌控", color: "S", cost: 2500, desc: "你获得了空之虫的认可，掌握极强的空间属性，能进行长距离瞬移，甚至制造空间陷阱。", type: "exclusive"},
        {name: "三十三天翼僚机", color: "B", cost: 300, desc: "你是三十三天翼实验班的一员，虽然不是主力，但拥有极强的团队配合能力和集体荣誉感。", type: "exclusive"},
        {name: "龙骑士候补", color: "A", cost: 900, desc: "你的体质适合与龙族签订契约，在天龙星上有机会获得上位龙族的青睐，成为强大的龙骑士。", type: "exclusive"},
        {name: "深红位面吞噬", color: "SS", cost: 8000, desc: "你拥有深红之母的部分特性，可以通过吞噬生命和能量来无限进化，但容易迷失自我，成为吞噬怪物。", type: "exclusive"},
        {name: "翠魔鸟武魂", color: "A", cost: 750, desc: "专食龙脑的凶残武魂，速度极快，穿透力极强，是龙族和高防御对手的克星。", type: "exclusive"},
        {name: "超神级机甲图纸", color: "S", cost: 3000, desc: "你脑中记载着一套未完成的超神级机甲设计图，一旦造出，单机即可对抗神级强者。", type: "exclusive"},
        {name: "元素剥离", color: "S", cost: 2100, desc: "你能强制剥离周围环境或对手的元素力量，使其无法施展元素类技能，绝对的法师克星。", type: "exclusive"},
        {name: "冻千秋的颜值", color: "C", cost: 100, desc: "你拥有极高的颜值，深蓝色的长发和眼眸让你在人群中格外显眼，魅力值拉满。", type: "exclusive"}
    ]
},
{
    name: "304.斗破苍穹",
    desc: "这里是属于斗气的世界，没有花俏艳丽的魔法，有的，仅仅是繁衍到巅峰的斗气！炼药师身份尊贵，异火毁天灭地。",
    boss: "萧炎(炎帝), 魂天帝, 药尘(药老), 美杜莎女王",
    identities: [
        { name: "乌坦城萧家废柴旁支", items: "低级斗之气功法, 几枚金币" },
        { name: "塔戈尔沙漠蛇人男宠", items: "精美的镣铐, 蛇毒解药" },
        { name: "云岚宗扫地杂役", items: "扫帚, 云岚宗制服(破损)" },
