        { name: "青山镇的小医仙助手", items: "采药镰刀, 基础草药图鉴" }
    ],
    talents: [
        {name: "焚决(完整版)", color: "SSS", cost: 40000, desc: "传说中的功法，可以通过吞噬异火来无限进化。虽然起步低，但潜力无限，是通往斗帝的捷径。", type: "exclusive"},
        {name: "灵魂感知力(境)", color: "S", cost: 2200, desc: "天生灵魂力量强大，达到灵境或天境，是成为高阶炼药师的必要条件，感知敏锐，可施展魂技。", type: "exclusive"},
        {name: "厄难毒体", color: "SS", cost: 8500, desc: "无需修炼，只需服毒即可提升斗气。万毒不侵但全身是毒，最终会因毒气反噬而亡，所过之处生灵涂炭。", type: "exclusive"},
        {name: "碧蛇三花瞳", color: "S", cost: 2800, desc: "天生奇异眼瞳，能够强行控制蛇类魔兽，甚至能在瞳孔空间中温养魔兽，吸收其斗气反馈自身。", type: "exclusive"},
        {name: "异火榜排名19:青莲地心火", color: "S", cost: 3500, desc: "生于大地深处的火焰，历经千年磨砺。能引发火山喷发，威力巨大，对炼药有极大加成。", type: "exclusive"},
        {name: "斗帝血脉(稀薄)", color: "A", cost: 1500, desc: "远古八族的后裔，虽然血脉稀薄，但修炼速度仍远超常人，且更容易突破瓶颈，开启族纹。", type: "exclusive"},
        {name: "紫云翼(飞行斗技)", color: "B", cost: 450, desc: "玄阶中级飞行斗技，能让你在未达到斗王级别时就拥有飞行的能力，逃跑和赶路的利器。", type: "exclusive"},
        {name: "八极崩(暗劲)", color: "B", cost: 350, desc: "玄阶高级斗技，近身攻击力极强，练至大成可含八重暗劲，在攻击后延迟爆发，令人防不胜防。", type: "exclusive"},
        {name: "天妖凰族血脉", color: "A", cost: 1100, desc: "魔兽界的至尊家族血脉，肉身强横，速度极快，拥有传承记忆和高阶魔兽的威压。", type: "exclusive"},
        {name: "净莲妖火(残图)", color: "C", cost: 200, desc: "一份不知所云的残破地图，记载着异火榜排名第三的净莲妖火的信息，集齐前毫无用处。", type: "exclusive"},
        {name: "炼药师天赋", color: "A", cost: 900, desc: "你对火木属性斗气掌控细腻，精神力出众，炼制丹药的成功率和品质极高，赚钱能力一流。", type: "exclusive"},
        {name: "佛怒火莲(感悟)", color: "SS", cost: 6000, desc: "你领悟了融合不同火焰的技巧，能制造出毁灭性的爆炸莲花。火焰越强，威力越恐怖，越级杀敌必备。", type: "exclusive"},
        {name: "吸掌/吹火掌", color: "C", cost: 100, desc: "玄阶低级斗技，虽不强，但在战斗中灵活运用可产生奇效，如吸过对手武器或吹散毒雾。", type: "exclusive"},
        {name: "虚无吞炎(子火)", color: "S", cost: 3200, desc: "异火榜第二的子火，拥有吞噬万物之能，可吞噬天地能量供养己身，极难熄灭。", type: "exclusive"},
        {name: "魔兽山脉生存专家", color: "C", cost: 120, desc: "你在魔兽山脉混迹多年，熟悉各种魔兽习性，懂得如何隐藏气息和寻找水源，生存率极高。", type: "exclusive"}
    ]
},
{
    name: "305.武动乾坤",
    desc: "大炎王朝，天玄大陆。元力修行的世界，符师以精神力引动天地。八大祖符掌控天地规则，异魔皇企图染指位面。",
    boss: "林动(武祖), 绫清竹, 应欢欢(冰主), 异魔皇",
    identities: [
        { name: "青阳镇林家分家子弟", items: "通背拳拳谱(残), 一株低级灵药" },
        { name: "炎城符师会打杂", items: "废弃符纸, 精神力磨盘(微型)" },
        { name: "大荒郡被遗弃的婴儿", items: "破烂襁褓, 兽骨项链" },
        { name: "道宗荒殿记名弟子", items: "道宗道袍, 荒劲修炼法" },
        { name: "乱魔海捕鱼少年", items: "鱼叉, 避水珠(劣质)" }
    ],
    talents: [
        {name: "祖石(神秘石符)", color: "SSS", cost: 38000, desc: "远古神物，拥有提炼灵药、完善功法、推演武学的功能。内含天妖貂灵魂，是屌丝逆袭的神器。", type: "exclusive"},
        {name: "吞噬祖符(认可)", color: "SS", cost: 9000, desc: "八大祖符之一，掌管吞噬之力。能吞噬天地元力、精神力甚至生机，化为己用，拥有最持久的战斗力。", type: "exclusive"},
        {name: "大荒囚天指", color: "S", cost: 2500, desc: "半造化武学，一指囚天地，五指动乾坤。威力惊人，需要极强的肉身和元力支撑。", type: "exclusive"},
        {name: "青天化龙诀", color: "S", cost: 3000, desc: "顶尖炼体武学，修炼后肉身堪比龙族，可化身为半龙形态，力量防御暴增，附带青龙威压。", type: "exclusive"},
        {name: "本命灵符(天符师)", color: "A", cost: 1200, desc: "你天生精神力变异，本命灵符品质极高，在符师一道上前途无量，能刻画高级符阵。", type: "exclusive"},
        {name: "雷霆祖符(残印)", color: "A", cost: 1600, desc: "你体内有一丝雷霆祖符的印记，对雷属性元力亲和度极高，攻击附带麻痹效果，速度如雷。", type: "exclusive"},
        {name: "天妖貂血脉(混血)", color: "A", cost: 1000, desc: "你拥有一部分霸主级妖兽天妖貂的血脉，空间天赋极佳，性格桀骜不驯，肉身强悍。", type: "exclusive"},
        {name: "冰主轮回印", color: "SS", cost: 7500, desc: "你是远古冰主的轮回碎片转世，冰属性天赋绝顶，觉醒后修为一日千里，但情感会逐渐淡漠。", type: "exclusive"},
        {name: "古漩符印", color: "B", cost: 400, desc: "能将本命符印化为漩涡，增强对精神力的吸收和回复速度，是符师持续作战的保障。", type: "exclusive"},
        {name: "泥丸宫变异", color: "B", cost: 350, desc: "你的泥丸宫比常人更广阔坚固，能容纳更多精神力，不易被精神冲击震碎。", type: "exclusive"},
        {name: "纯元丹土豪", color: "A", cost: 800, desc: "你开局自带大量纯元丹，这是修炼和交易的硬通货，让你起步阶段资源不愁。", type: "exclusive"},
        {name: "九天太清宫琴音", color: "B", cost: 500, desc: "你精通音律攻击，能以琴音扰乱敌人心神或辅助队友，是极佳的控场技能。", type: "exclusive"},
        {name: "位面之胎感应", color: "SSS", cost: 25000, desc: "你与天玄大陆的位面之胎有神秘联系，能调动位面之力压制对手，在本土作战几乎无敌。", type: "exclusive"},
        {name: "造化武碑名额", color: "C", cost: 200, desc: "你拥有进入大荒古碑参悟造化武学的资格，能否领悟高等武学全看机缘。", type: "exclusive"},
        {name: "精神力实质化", color: "A", cost: 1400, desc: "你的精神力凝练程度极高，可以直接化为刀剑兵器进行物理攻击，令人防不胜防。", type: "exclusive"}
    ]
},
{
    name: "306.大主宰",
