        {name: "一气化三清", color: "SSS", cost: 35000, desc: "绝世神通，能分出两个与本体实力完全相同的分身。三位一体，修炼速度三倍，战力三倍，堪称BUG。", type: "exclusive"},
        {name: "大日不灭身(法身)", color: "S", cost: 3000, desc: "原始法身万古不朽身的基础版本。修炼出大日之阳，防御力惊人，生命力顽强，越战越勇。", type: "exclusive"},
        {name: "灵阵师天赋(宗师)", color: "S", cost: 2000, desc: "你在灵阵一道天赋卓绝，心眼已开，能瞬间布置出复杂的高级灵阵，以弱胜强的关键手段。", type: "exclusive"},
        {name: "九幽雀血脉链接", color: "A", cost: 1200, desc: "你与神兽九幽雀共享生命，能借用其不死火的力量，且在重伤时可借助其涅槃之力恢复。", type: "exclusive"},
        {name: "大浮屠诀", color: "A", cost: 1500, desc: "浮屠古族核心功法，修炼出的灵力浑厚霸道，具有封印特性，对邪族有克制作用。", type: "exclusive"},
        {name: "战阵师资质", color: "A", cost: 1000, desc: "你能将千万人的战意汇聚于一身，化为战意之灵。军队数量越多，你的力量越恐怖。", type: "exclusive"},
        {name: "洛神法身(残)", color: "S", cost: 2500, desc: "洛神族至高法身，极美且极强。虽然残缺，但仍拥有操控洛河之力，净化邪恶，攻防兼备。", type: "exclusive"},
        {name: "诛魔王令牌", color: "B", cost: 500, desc: "大千宫颁发的令牌，代表你击杀过大量域外邪族，在各大势力中享有特权和折扣。", type: "exclusive"},
        {name: "灵路试炼资格", color: "C", cost: 200, desc: "你被选中参加灵路试炼，虽然无法使用灵力，但能磨练意志和战斗技巧，是强者的摇篮。", type: "exclusive"},
        {name: "苍穹榜留名(潜质)", color: "SSS", cost: 50000, desc: "你拥有超脱圣品的潜力，注定要在苍穹榜上留下全名，调动整个大千世界之力，成为世界守护者。", type: "exclusive"},
        {name: "域外邪族魔气", color: "D", cost: 50, desc: "你被邪气侵蚀，虽然战力提升，但容易失控，且被大千世界主流势力所不容，人人喊打。", type: "exclusive"},
        {name: "龙凤体", color: "SS", cost: 6000, desc: "融合了真龙与真凤的精血，肉身成圣，拥有龙之力量与凤之速度，恢复力极强。", type: "exclusive"},
        {name: "大须弥魔柱", color: "S", cost: 2800, desc: "太古凶器，煞气冲天。挥舞间可震碎虚空，非意志坚定者无法驾驭，容易被煞气反噬。", type: "exclusive"},
        {name: "灵虫师", color: "B", cost: 350, desc: "擅长培育和操控灵虫，能用虫群侦查、攻击或吞噬敌人灵力，手段诡异。", type: "exclusive"}
    ]
},
{
    name: "307.遮天",
    desc: "登天路，踏歌行，弹指遮天。九龙拉棺开启大世。荒古圣体、混沌体争霸帝路。生命禁区蛰伏着古代至尊，黑暗动乱随时降临。",
    boss: "叶凡(叶天帝), 狠人大帝, 无始大帝, 帝尊",
    identities: [
        { name: "泰山脚下的游客", items: "智能手机, 奔驰车钥匙" },
        { name: "灵墟洞天采药童子", items: "药篓, 基础百草液" },
        { name: "北域源矿的矿奴", items: "沉重的镣铐, 沾血的矿镐" },
        { name: "荒古世家旁系弟子", items: "家族令牌(低级), 几斤源" },
        { name: "地球昆仑遗族", items: "残破古卷, 祖传玉佩" }
    ],
    talents: [
        {name: "荒古圣体", color: "SS", cost: 9900, desc: "人族最强战体，肉身无双，万法不侵，血液金色，克制异象。但被天地诅咒，修炼消耗资源极大，难以成道。", type: "exclusive"},
        {name: "先天道胎", color: "SS", cost: 9000, desc: "天生近道，与道合真。修炼速度极快，悟性逆天，挥手间道法自然，是天地宠儿。", type: "exclusive"},
        {name: "混沌体(残)", color: "SSS", cost: 45000, desc: "古今第一体质，万道相融。哪怕是残缺版，也能演化万法，肉身与元神皆完美无瑕，注定成帝。", type: "exclusive"},
        {name: "九秘(皆字秘)", color: "S", cost: 3500, desc: "神话时代九大天尊秘术之一，可触发十倍战力叠加。虽然触发概率看脸，但一旦触发，足以逆行伐仙。", type: "exclusive"},
        {name: "源天师传承", color: "S", cost: 2800, desc: "掌握寻源定脉之术，能看穿石皮切出神源，更能调动山川大势对敌，在有龙脉之地战力倍增。", type: "exclusive"},
        {name: "吞天魔功", color: "SS", cost: 8500, desc: "狠人大帝所创，可吞噬各种特殊体质本源来成就己身。进境神速但有干天和，举世皆敌。", type: "exclusive"},
        {name: "行字秘(极速)", color: "S", cost: 3000, desc: "世间极速，涉及时间领域。练至大成可暂停时间，万军丛中过，片叶不沾身。", type: "exclusive"},
        {name: "万物母气根源", color: "SS", cost: 7000, desc: "天地初开的精粹，一缕可压塌山脉。用来锻造证道之器，坚不可摧，随主人一同成长。", type: "exclusive"},
        {name: "神王体", color: "A", cost: 1800, desc: "东荒神体，异象''海上生明月''。体质强横，恢复力强，大成后可叫板大帝。", type: "exclusive"},
        {name: "不死神药(果实)", color: "S", cost: 2500, desc: "你曾误食一枚不死神药果实，寿元大增，体内残留庞大药力，多次助你死里逃生，重塑根基。", type: "exclusive"},
        {name: "虚空经(残篇)", color: "A", cost: 1200, desc: "虚空大帝的帝经残篇，记载了虚空大术。精通空间之道，杀人于无形，逃跑第一。", type: "exclusive"},
        {name: "绿铜块(神秘)", color: "SS", cost: 5000, desc: "成仙鼎的碎片，寄宿在苦海中。虽然平时不动，但关键时刻能挡住极道帝兵一击，镇压己身气运。", type: "exclusive"},
        {name: "天璇步法", color: "B", cost: 400, desc: "老疯子传下的步法，缩地成寸，虽然不如行字秘，但在同阶中已是顶尖身法。", type: "exclusive"},
        {name: "斗字秘(演化)", color: "S", cost: 3200, desc: "攻伐第一秘术，能模拟演化世间一切攻伐圣术，化繁为简，一击必杀。", type: "exclusive"},
        {name: "苦海种金莲", color: "A", cost: 1500, desc: "轮海秘境最强异象之一，金莲摇曳，万法不侵，能定住对手神力，压制力极强。", type: "exclusive"}
    ]
},
{
    name: "308.完美世界",
    desc: "一粒尘可填海，一根草斩尽日月星辰。大荒之中，万族争霸。荒天帝独断万古，上苍之上血染苍穹。至尊骨、重瞳谱写不败神话。",
    boss: "石昊(荒天帝), 柳神, 尸骸仙帝, 安澜",
    identities: [
        { name: "石村喝奶娃", items: "兽奶罐, 原始真解(入门)" },
        { name: "虚神界精神体", items: "精神力碎片, 记录石碑" },
        { name: "补天阁新晋弟子", items: "补天术残篇, 弟子剑" },
        { name: "百断山原住民", items: "断裂的骨棒, 灵药残根" },
        { name: "异域帝族奴仆", items: "黑暗枷锁, 堕落血脉" }
    ],
    talents: [
        {name: "至尊骨(再生)", color: "SSS", cost: 48000, desc: "天生至尊，骨上刻有原始宝术。哪怕被挖走，再生出的至尊骨会更加强大，蕴含轮回或上苍劫光之力。", type: "exclusive"},
        {name: "重瞳", color: "SS", cost: 9500, desc: "上古圣人异象，眼内双瞳。能看破一切虚妄，放慢对手动作，拥有毁灭之光和造化生机，开天辟地。", type: "exclusive"},
        {name: "他化自在法(雏形)", color: "SSS", cost: 50000, desc: "无上大法，可化过去、现在、未来，化他人为己用。虽然只是雏形，已具备无敌之资，群战无敌。", type: "exclusive"},
        {name: "柳神法(嫩芽)", color: "SS", cost: 8000, desc: "柳神的传承，拥有极强的生命恢复力。只要尚存一滴血、一块骨，便能浴火重生，且攻伐凌厉。", type: "exclusive"},
        {name: "鲲鹏宝术(散手)", color: "S", cost: 3500, desc: "十凶宝术之一，掌阴阳，控水火。入海为鲲，力大无穷；化天为鹏，极速无双。攻防一体。", type: "exclusive"},
        {name: "原始真解(神引篇)", color: "S", cost: 3000, desc: "不修宝术，只修符文骨文最本源的力量。化腐朽为神奇，奠定最强根基，同阶肉身无敌。", type: "exclusive"},
        {name: "十口洞天(合一)", color: "SS", cost: 7000, desc: "打破极限，修出十口洞天并将其合一，形成唯一神环。万法不侵，压制一切领域力量。", type: "exclusive"},
        {name: "草字剑诀", color: "S", cost: 3200, desc: "太古三大剑诀之一，一株草斩尽日月星辰。剑气锋锐无匹，无物不斩，攻击力极致。", type: "exclusive"},
        {name: "朱厌宝术", color: "A", cost: 1500, desc: "精通七十二变，三头六臂。肉身金刚不坏，力大无穷，近战搏杀的顶级宝术。", type: "exclusive"},
        {name: "打神石", color: "A", cost: 1200, desc: "你拥有一块打神石，专打人头，百发百中，无视防御。虽然杀伤力有限，但侮辱性极强。", type: "exclusive"},
        {name: "真龙血脉(稀薄)", color: "A", cost: 1800, desc: "十凶之首真龙的后裔，肉身举世无双，龙吟一出万兽臣服，潜力巨大。", type: "exclusive"},
        {name: "黑暗物质侵蚀", color: "D", cost: 100, desc: "你接触过黑暗源头，虽然实力暴涨，但神智偶尔会混乱，有堕入黑暗成为怪物的风险。", type: "exclusive"},
        {name: "雷帝宝术(残)", color: "S", cost: 2800, desc: "驾驭九天劫雷，代天刑罚。雷道极致，攻击速度最快，对邪祟有绝对克制。", type: "exclusive"},
        {name: "吃货属性", color: "C", cost: 80, desc: "不管是纯血生灵还是太古遗种，在你眼里都是食材。吃掉它们能快速增长神力。", type: "exclusive"},
        {name: "小塔契约", color: "SS", cost: 6000, desc: "混沌至宝小塔与你暂结契约，只要提供天材地宝，它就能帮你出手，镇压世间一切敌。", type: "exclusive"}
    ]
},
{
    name: "309.圣墟",
    desc: "后文明时代，灵气复苏。异果现世，枷锁崩断。楚风在破败中崛起，走上场域进化之路，探寻轮回路的尽头。",
    boss: "楚风(罐天帝), 妖妖, 九道一, 诡异始祖",
    identities: [
        { name: "太行山脚下的觉醒者", items: "通讯器, 一枚变异野果" },
        { name: "天神生物实验体", items: "编号铭牌, 基因药剂" },
        { name: "龙虎山道士", items: "桃木剑, 残破呼吸法" },
        { name: "域外降临者的仆从", items: "星际翻译器, 能量块" },
        { name: "大梦净土试炼者", items: "安魂香, 精神秘技" }
    ],
    talents: [
        {name: "盗引呼吸法", color: "SSS", cost: 42000, desc: "究极呼吸法，可提炼天地间最本源的能量，强化体质，进化神速。更是场域大师的必修课。", type: "exclusive"},
        {name: "石罐(神秘)", color: "SSS", cost: 50000, desc: "来历不明的石罐，万法不侵，可遮蔽天机，连始祖都无法推演。内部有奇异空间，能种出绝世异果。", type: "exclusive"},
        {name: "场域宗师天赋", color: "SS", cost: 8000, desc: "你对山川地势、磁场纹络有超凡的感知。挥手间布下杀阵，改天换地，借天地之力杀敌。", type: "exclusive"},
        {name: "大雷音弓(仿)", color: "A", cost: 1500, desc: "一把威力巨大的合金弓，配合雷电属性异能，可超视距射杀枷锁境强者，附带雷鸣轰炸。", type: "exclusive"},
        {name: "牛魔拳", color: "B", cost: 400, desc: "大力牛魔族的拳法，刚猛霸道。配合呼吸法使用，拳风如雷，能震碎山石，近战利器。", type: "exclusive"},
        {name: "火眼金睛", color: "S", cost: 3000, desc: "看穿虚妄，透视地表，识别场域纹络。更能射出金色光束伤人神魂，是探索名山大川的神技。", type: "exclusive"},
        {name: "花粉进化路亲和", color: "S", cost: 2200, desc: "你吸收异果花粉的效率极高，且极少产生副作用或发生诡变，进化之路比常人平坦得多。", type: "exclusive"},
        {name: "形意拳真解", color: "A", cost: 1000, desc: "古武术的巅峰，演化十二形。不仅是杀伐之术，更能引动体内血气，挣断枷锁。", type: "exclusive"},
        {name: "金刚琢(粗胚)", color: "SS", cost: 6500, desc: "用稀有母金打磨的兵器，虽未成型，但重若千钧，无坚不摧，且具有定住兵器、套取万物的特性。", type: "exclusive"},
        {name: "不死鸟血脉(觉醒)", color: "SS", cost: 7500, desc: "拥有浴火重生的能力，火焰威力绝伦。每次濒死复活，实力都会大幅跃升，生命力顽强。", type: "exclusive"},
        {name: "精神力实质化", color: "A", cost: 1800, desc: "精神力强大到干涉现实，可御物杀敌，或直接冲击敌人大脑，杀人于无形。", type: "exclusive"},
        {name: "星空骑士呼吸法", color: "A", cost: 1200, desc: "域外大势力的呼吸法，虽然霸道残忍，但对肉身打磨效果极佳，适合杀戮中成长。", type: "exclusive"},
        {name: "妖妖的指点", color: "S", cost: 2800, desc: "你曾得到过星空下第一美女妖妖的虚影指点，眼界开阔，同阶战斗技巧无敌。", type: "exclusive"},
        {name: "轮回土", color: "S", cost: 3500, desc: "来自轮回路的泥土，点燃后产生的烟雾可庇护灵魂，甚至能让死者短暂显灵，诡异莫测。", type: "exclusive"},
        {name: "人贩子恶名", color: "C", cost: 50, desc: "你像楚风一样喜欢敲闷棍、卖圣子圣女。虽然名声臭，但能从各族天骄身上勒索到大量资源。", type: "exclusive"}
    ]
},
{
    name: "310.凡人修仙传",
    desc: "凡人修仙，风云再起。时空穿梭，轮回逆转。韩立手持掌天瓶，纵横人、灵、仙三界。人心险恶，修仙路漫漫，唯有谨慎方能长生。",
    boss: "韩立(韩老魔), 南宫婉, 墨居仁, 轮回殿主",
    identities: [
        { name: "七玄门记名弟子", items: "眨眼剑法秘籍, 小绿瓶(伪)" },
        { name: "黄枫谷炼气期修士", items: "低阶储物袋, 青元剑诀(前三层)" },
        { name: "乱星海捕妖修士", items: "法器鱼叉, 避水符" },
        { name: "魔道六宗底层炮灰", items: "聚魂幡(无魂), 血炼功法" },
        { name: "落云宗炼丹童子", items: "炼丹炉, 灵草残渣" }
    ],
    talents: [
        {name: "掌天瓶(真)", color: "SSS", cost: 60000, desc: "夺天地造化之至宝。能凝聚绿液，催熟万年灵药。只要有种子，你就有无限的资源，资质再差也能堆成仙。", type: "exclusive"},
        {name: "四属性伪灵根", color: "D", cost: 100, desc: "资质极差，修炼速度慢如蜗牛。若无大机缘，筑基无望。但胜在五行法术都能学一点。", type: "exclusive"},
        {name: "天灵根(单一属性)", color: "SS", cost: 8000, desc: "修仙界的宠儿，修炼速度极快，结丹期前无瓶颈。各派争抢的天才，但也容易夭折。", type: "exclusive"},
        {name: "青元剑诀(全本)", color: "S", cost: 3000, desc: "木属性顶级功法，附带青元剑芒、护体剑盾。大成后可施展大庚剑阵，杀伐凌厉，攻防一体。", type: "exclusive"},
        {name: "大衍决(前四层)", color: "S", cost: 2500, desc: "专修神识的秘术，能让神识远超同阶，并分化出数百份神识操控傀儡。群战、探路必备。", type: "exclusive"},
        {name: "噬金虫(幼虫)", color: "SS", cost: 7000, desc: "上古奇虫，无物不噬，水火不侵。一旦培养成群，连真仙都要避其锋芒，最强的打手。", type: "exclusive"},
        {name: "韩跑跑的谨慎", color: "S", cost: 2000, desc: "你获得了韩立的真传，行事极其低调，杀人必毁尸灭迹，遇事不对立马跑路，生存率提升1000%。", type: "exclusive"},
        {name: "梵圣真魔功", color: "SS", cost: 6500, desc: "人妖魔三界合一的炼体神功。可变身三头六臂，肉身强横无比，力拔山河，但修炼过程痛苦异常。", type: "exclusive"},
        {name: "辟邪神雷", color: "S", cost: 3500, desc: "金雷竹释放的金色雷电，是一切魔道、鬼物的克星。拥有此雷，魔道修士见你如见鬼神。", type: "exclusive"},
        {name: "风雷翅", color: "A", cost: 1500, desc: "利用风雷属性妖兽材料炼制的飞行法宝，速度极快，并附带雷遁术，是杀人越货、逃跑保命的利器。", type: "exclusive"},
        {name: "傀儡术精通", color: "B", cost: 600, desc: "你擅长制作和操控傀儡，只要材料足够，你能拉起一支不仅不怕死、还能自爆的傀儡大军。", type: "exclusive"},
        {name: "虚天鼎(仿)", color: "A", cost: 1800, desc: "通天灵宝的仿制品，内含乾蓝冰焰，可困敌、炼宝。虽然不如正品，但在人界已是顶级宝物。", type: "exclusive"},
        {name: "乱星海海图", color: "C", cost: 150, desc: "详细记载了乱星海各岛屿、妖兽分布及传送阵位置的地图，是你在乱星海闯荡的指南针。", type: "exclusive"},
        {name: "长春功", color: "C", cost: 50, desc: "木属性基础功法，胜在平和中正，延年益寿，且有驻颜效果，是转修其他功法的良好基础。", type: "exclusive"},
        {name: "墨大夫的医术", color: "B", cost: 300, desc: "凡俗界的顶尖医术，能治愈大部分外伤和毒伤，也能配制各种毒药和迷药，阴人必备。", type: "exclusive"}
    ]
},
              {
        name: "311.仙逆",
        desc: "顺为凡，逆则仙，只在心中一念间。这是一个残酷的修真界，弱肉强食是唯一的法则。古神、古妖、古魔三族争霸，天运子算计苍生。",
        boss: "天运子, 拓森, 戮默, 王林(煞星)",
        identities: [
            { name: "恒岳派记名弟子", items: "一件灰色的杂役道袍, 一个装着山泉水的葫芦" },
            { name: "赵国凡人书生", items: "几卷破损的圣贤书, 一个考取功名的执念" },
            { name: "藤家城旁系族人", items: "一块刻着藤字的木牌, 一把低阶飞剑" },
            { name: "域外战场的游魂", items: "无实体的身躯, 对生灵气息的渴望" },
            { name: "炼魂宗的炼魂幡主", items: "一面破损的魂幡, 几只凶戾的主魂" }
        ],
        talents: [
            {name: "天逆珠(无主)", color: "SSS", cost: 50000, desc: "逆天改命的至宝，内含五行空间与时间流速加成。虽然现在没有司徒南，但它本身就是通往踏天之路的钥匙。", type: "exclusive"},
            {name: "古神血脉(王族)", color: "SSS", cost: 32000, desc: "继承了道古烨莫的血脉，肉身成圣，力大无穷。眉心星点旋转之时，星空都要为之颤抖。", type: "exclusive"},
            {name: "极境神识", color: "SS", cost: 9000, desc: "同阶无敌的代名词。虽然以后修炼艰难，容易暴毙，但在同境界内，你的神识一出，谁与争锋？", type: "exclusive"},
            {name: "禁制本源", color: "SS", cost: 7500, desc: "你对禁制拥有超乎常人的理解，挥手间山崩地裂，禁制成阵。这是破除上古遗迹的必备神技。", type: "exclusive"},
            {name: "蚊兽王(幼体)", color: "S", cost: 4500, desc: "一只变异的蚊兽，拥有进化成金色蚊王的潜力。它的口器无物不破，是你杀人越货的好帮手。", type: "exclusive"},
            {name: "杀戮道心", color: "S", cost: 3000, desc: "你天生适合修魔，杀的人越多，煞气越重，修为增长越快。但要小心迷失在杀戮之中。", type: "exclusive"},
            {name: "呼风唤雨(残篇)", color: "A", cost: 1500, desc: "仙帝青霖的神通之一。虽然只是残篇，但施展出来足以在低阶修士中横着走，化风化雨，杀人无形。", type: "exclusive"},
            {name: "从容(心境)", color: "A", cost: 800, desc: "泰山崩于前而色不变。在任何绝境下都能保持绝对冷静，这种心境是修真者最宝贵的财富。", type: "exclusive"},
            {name: "引力术(大圆满)", color: "B", cost: 400, desc: "将最基础的引力术练到了极致，甚至能产生一丝斥力。别小看基础法术，关键时刻能救命。", type: "exclusive"},
            {name: "丹药大师", color: "B", cost: 600, desc: "你精通草木之变，炼丹成功率远超常人。在这个嗑药升级的世界，你会很受欢迎。", type: "exclusive"},
            {name: "含沙射影", color: "C", cost: 180, desc: "一种阴毒的法宝炼制图谱，可以藏在袖子里偷袭敌人，专破护身灵光。", type: "exclusive"},
            {name: "辟谷丹(一瓶)", color: "C", cost: 50, desc: "一瓶劣质的辟谷丹，能让你在闭关时不用担心饿死。修仙者的基础口粮。", type: "exclusive"},
            {name: "修真入门手记", color: "D", cost: 20, desc: "某位散修的修炼心得，上面记载了一些基础的吐纳之法，错漏百出，但聊胜于无。", type: "exclusive"},
            {name: "灵根(杂)", color: "D", cost: 100, desc: "五行缺五行的废柴灵根，修炼速度慢如蜗牛，基本上注定只能当个凡人。", type: "exclusive"},
            {name: "天煞孤星", color: "E", cost: 10, desc: "诅咒类天赋。你身边的人都会倒霉甚至横死。虽然你可能因此活下来，但注定孤独一生。", type: "exclusive"}
        ]
    },
    {
        name: "312.求魔",
        desc: "魔前一叩三千年，回首凡尘不做仙。这是一个关于塑冥族、蛮族与命运抗争的悲怆世界。这里没有绝对的对错，只有执着。",
        boss: "帝天, 苏轩衣, 灭生老人, 玄葬",
        identities: [
