            {name: "完美道基", color: "SS", cost: 10000, desc: "无瑕无垢的筑基，断绝了天地法则的压制。你的灵力比同阶浑厚十倍，越阶挑战如喝水。", type: "exclusive"},
            {name: "铜镜(复制)", color: "SS", cost: 15000, desc: "神秘的铜镜，只要放入灵石，就能复制万物（甚至丹药、法宝）。但要小心它会爆那啥...", type: "exclusive"},
            {name: "妖尊血脉", color: "S", cost: 5000, desc: "你体内流淌着妖尊的血液，可以随意在人与妖之间转换，修炼妖法事半功倍。", type: "exclusive"},
            {name: "一纸因果", color: "S", cost: 3500, desc: "欠债还钱，天经地义。你可以通过写下欠条来强行建立因果，让敌人不得不还你东西。", type: "exclusive"},
            {name: "彼岸花毒", color: "A", cost: 1800, desc: "你体内寄生着彼岸花，虽然危险，但也能作为大杀器。花开之时，万物凋零。", type: "exclusive"},
            {name: "金乌化身", color: "A", cost: 2000, desc: "你可以化身为上古金乌，操控太阳真火，焚烧万物，速度极快。", type: "exclusive"},
            {name: "无耻之徒", color: "B", cost: 500, desc: "你的脸皮极厚，擅长坑蒙拐骗。在修真界，脸皮厚有时候比修为高更管用。", type: "exclusive"},
            {name: "炼丹天赋(炸炉)", color: "C", cost: 150, desc: "你炼丹经常炸炉，但炸出的黑丹往往有奇效（比如剧毒、致幻）。", type: "exclusive"},
            {name: "凝气三层", color: "C", cost: 250, desc: "开局拥有凝气三层的修为，可以使用基础法术，比凡人强多了。", type: "exclusive"},
            {name: "灵石(十块)", color: "C", cost: 100, desc: "十块下品灵石，修真界的硬通货。省着点花，够你买把像样的飞剑了。", type: "exclusive"},
            {name: "欠条(一堆)", color: "D", cost: 30, desc: "你欠了一屁股债，每天都有人追杀你讨债。这迫使你不得不变强（或者跑路）。", type: "exclusive"},
            {name: "贪财", color: "D", cost: 50, desc: "你对灵石有着病态的执着，看到钱就走不动路，容易落入陷阱。", type: "exclusive"},
            {name: "书呆子", color: "E", cost: 10, desc: "你只会死读书，不懂变通。在尔虞我诈的修真界，这种性格活不过三集。", type: "exclusive"},
            {name: "飞行术", color: "B", cost: 300, desc: "掌握了御风而行的技巧，虽然不如飞剑快，但胜在灵活。", type: "exclusive"}
        ]
