        talents: [
            {name: "宿命之环(恩赐)", color: "SSS", cost: 48000, desc: "来自外神的直接恩赐。你可以抽取过去、现在、未来的力量，甚至重启一段命运。代价是理智的丧失。", type: "exclusive"},
            {name: "红祭司(战争)", color: "SS", cost: 20000, desc: "战争的主宰。你可以组建军队，链接众人的力量，掀起席卷世界的战火。只有最强硬的男人才能登顶。", type: "exclusive"},
            {name: "原初魔女(灾难)", color: "SS", cost: 20000, desc: "散播瘟疫、绝望与灾难。你的魅力无人能挡，你的诅咒无孔不入。无论是男是女，最终都将臣服。", type: "exclusive"},
            {name: "舞蹈家(祭祀)", color: "S", cost: 4500, desc: "通过诡异的舞蹈沟通不可名状的存在，借取力量。每跳一次舞，你离疯狂就更近一步。", type: "exclusive"},
            {name: "挑衅者", color: "A", cost: 1200, desc: "你擅长激怒敌人，让他们失去理智，露出破绽。嘴炮也是一种强大的武器。", type: "exclusive"},
            {name: "纵火家", color: "A", cost: 1800, desc: "你可以操纵火焰，制造爆炸。在特里尔的下水道里，你是最危险的存在。", type: "exclusive"},
            {name: "受难者", color: "S", cost: 3000, desc: "你可以代替他人承受伤害和诅咒，也可以将伤害转移。痛苦是你力量的源泉。", type: "exclusive"},
            {name: "阴谋家", color: "B", cost: 800, desc: "你擅长布局和算计，能在复杂的局势中找到最优解。脑子好使比拳头硬更重要。", type: "exclusive"},
            {name: "咸鱼突刺", color: "C", cost: 200, desc: "从某位咸者那里学来的招式，看似滑稽，实则迅猛。附带精神污染效果。", type: "exclusive"},
            {name: "法语精通", color: "C", cost: 100, desc: "你精通因蒂斯语（法语），在特里尔生活和社交的必备技能。", type: "exclusive"},
            {name: "地下墓穴地图", color: "B", cost: 400, desc: "特里尔庞大地下迷宫的部分地图，标记了一些安全屋和危险区域。", type: "exclusive"},
            {name: "污染抗性(微弱)", color: "D", cost: 150, desc: "你对精神污染有一点点抵抗力，能比常人多坚持几秒钟不疯。", type: "exclusive"},
            {name: "穷困潦倒", color: "D", cost: 50, desc: "由于某种原因，你身无分文，甚至负债累累。这迫使你不得不去冒险。", type: "exclusive"},
            {name: "容易被骗", color: "E", cost: 10, desc: "你太单纯了，容易相信别人的话。在这个充满诈骗师的世界，你就是待宰的肥羊。", type: "exclusive"},
            {name: "猎人本能", color: "B", cost: 500, desc: "对陷阱、痕迹和危险有敏锐的直觉。", type: "exclusive"}
        ]
    },
    {
        name: "317.全职高手",
        desc: "荣耀，不是一个人的游戏。叶修被驱逐后，带着千机伞重返巅峰。这是一个关于电竞、热血与技术的世界。",
        boss: "周泽楷, 韩文清, 王杰希, 叶修(斗神)",
        identities: [
            { name: "兴欣网吧网管", items: "一张荣耀账号卡(首版), 一包烟" },
            { name: "微草战队青训生", items: "魔道学者账号卡, 训练室钥匙" },
            { name: "蓝雨战队狂剑士", items: "重剑账号卡, 话痨属性" },
            { name: "霸图公会精英", items: "拳法家账号卡, 对叶修的仇恨" },
            { name: "神之领域拾荒者", items: "忍者账号卡, 极高的手速" }
        ],
        talents: [
            {name: "千机伞(银武)", color: "SS", cost: 8000, desc: "自制银武的巅峰之作。拥有十二种形态，可根据战局随意切换。配合散人玩法，变幻莫测，没有冷却死角。", type: "exclusive"},
            {name: "散人(全职)", color: "SSS", cost: 15000, desc: "精通全职业低阶技能。虽然没有高伤大招，但连招无限，快节奏压制让对手毫无还手之力。需要极高的操作水平。", type: "exclusive"},
            {name: "龙抬头", color: "S", cost: 3500, desc: "战斗法师的高级微操技巧。伏龙翔天打空后，通过极其复杂的操作强行改变龙头方向。这是神级选手的证明。", type: "exclusive"},
            {name: "魔术师打法", color: "S", cost: 3200, desc: "王杰希的成名绝技。诡异莫测的飞行轨迹和技能释放，完全违背常理，让对手无法预判。", type: "exclusive"},
            {name: "枪王(周泽楷)", color: "S", cost: 3000, desc: "神枪手的极致操作。华丽的体术与射击结合，无死角火力覆盖。一人即是一支军队。", type: "exclusive"},
            {name: "手速(500+)", color: "A", cost: 1800, desc: "你的APM（手速）突破天际，能在一秒内完成极其复杂的操作。这是职业大神的基础。", type: "exclusive"},
            {name: "战术大师", color: "A", cost: 2000, desc: "你拥有极高的战术素养，擅长指挥团队，利用地图和规则坑杀对手。心脏战术心。", type: "exclusive"},
            {name: "垃圾话(黄少天)", color: "B", cost: 600, desc: "你的文字泡攻击力极强，能通过大量的废话干扰对手的判断和心态。精神攻击MAX。", type: "exclusive"},
            {name: "副本攻略", color: "B", cost: 500, desc: "你脑子里装着所有副本的极限通关攻略。无论是刷记录还是抢首杀，都易如反掌。", type: "exclusive"},
            {name: "网游老鸟", color: "C", cost: 200, desc: "你熟悉荣耀的所有基础设定和任务流程，练级效率极高，知道哪里有隐藏BOSS。", type: "exclusive"},
            {name: "账号卡(满级)", color: "C", cost: 300, desc: "一张满级的普通账号卡，装备一般，但省去了练级的枯燥时间。", type: "exclusive"},
            {name: "近视眼", color: "D", cost: 50, desc: "长时间对着电脑让你视力下降。如果不戴眼镜，屏幕上的技能特效会让你眼花。", type: "exclusive"},
            {name: "熬夜修仙", color: "D", cost: 80, desc: "你习惯通宵打游戏，白天精神萎靡。身体素质较差，容易生病。", type: "exclusive"},
            {name: "手残", color: "E", cost: 20, desc: "你的手速很慢，反应迟钝。在竞技场里只有被虐的份，只能玩玩牧师或者召唤师。", type: "exclusive"},
            {name: "运气E", color: "E", cost: 10, desc: "你刷副本永远不出橙装，ROLL点永远不过10。非酋的眼泪。", type: "exclusive"}
        ]
    },
    {
        name: "318.盗墓笔记",
        desc: "七星鲁王、怒海潜沙、云顶天宫。吴邪、张起灵、王胖子铁三角探寻终极的秘密。比鬼神更可怕的，是人心。",
        boss: "西王母, 汪家, 它, 万奴王",
        identities: [
            { name: "吴家铺子的小伙计", items: "一本拓本, 几个黑驴蹄子" },
            { name: "潘家园的倒爷", items: "鉴宝放大镜, 一串假古董" },
            { name: "神秘的张家族人", items: "发丘指(未练成), 失魂症诊断书" },
            { name: "阿宁队伍的佣兵", items: "冲锋枪, 战术背心" },
            { name: "考古队实习生", items: "笔记本, 刷子" }
        ],
        talents: [
            {name: "麒麟血(纯)", color: "SSS", cost: 35000, desc: "张起灵同款血脉。百毒不侵，虫蚁退避。你的血是墓里最强的驱虫剂和解毒药，甚至能震慑千年粽子。", type: "exclusive"},
            {name: "终极秘密", color: "SS", cost: 15000, desc: "你知晓青铜门后的终极秘密。这让你成为了多方势力争夺或灭口的对象，但也赋予了你某种超然的地位。", type: "exclusive"},
            {name: "鬼玺", color: "SS", cost: 8000, desc: "调令阴兵的神器。在特定地点，你可以召唤阴兵借道，打开青铜门。这是通往地底深渊的钥匙。", type: "exclusive"},
            {name: "发丘指", color: "S", cost: 4000, desc: "双指奇长，力大无穷。可以轻易破解墓室机关，甚至直接夹断敌人的喉咙。探墓必备神技。", type: "exclusive"},
            {name: "听雷定穴", color: "S", cost: 3500, desc: "通过听雷声的回音来判断地下结构和墓葬位置。这是一种极其罕见且高深的风水秘术。", type: "exclusive"},
            {name: "黑金古刀", color: "A", cost: 2500, desc: "一把由陨铁打造的神兵，沉重无比，锋利异常。专砍粽子和异兽。", type: "exclusive"},
            {name: "鉴宝眼", color: "A", cost: 1200, desc: "你一眼就能看出古董的真伪和年代。在古玩行当里，这双眼睛就是印钞机。", type: "exclusive"},
            {name: "机关术精通", color: "B", cost: 800, desc: "你熟悉历朝历代的墓葬机关，无论是连环翻板还是流沙陷阱，都难不倒你。", type: "exclusive"},
            {name: "黑驴蹄子(陈年)", color: "C", cost: 150, desc: "对付僵尸的土办法，虽然不一定管用，但拿着总比空手强。记得塞进嘴里。", type: "exclusive"},
            {name: "洛阳铲", color: "C", cost: 100, desc: "盗墓贼的标准装备。一铲子下去，带上来的土能告诉你下面有没有货。", type: "exclusive"},
            {name: "吴邪体质", color: "D", cost: 200, desc: "开棺必起尸的邪门体质。虽然运气极差，但也总是能逢凶化吉（全靠队友）。", type: "exclusive"},
            {name: "尸蟞丹副作用", color: "D", cost: 300, desc: "你曾服下尸蟞丹，虽然获得了长生，但如果不定期去陨玉，就会变成禁婆。", type: "exclusive"},
            {name: "密闭恐惧症", color: "E", cost: 20, desc: "在狭窄黑暗的墓道里，你会呼吸困难，san值狂掉。这简直是盗墓贼的死穴。", type: "exclusive"},
            {name: "路痴", color: "E", cost: 10, desc: "在迷宫般的古墓里，你永远找不到出口。只能跟着别人走。", type: "exclusive"},
            {name: "战术指挥", color: "B", cost: 600, desc: "在危机时刻能冷静指挥队伍撤退或反击，像三叔一样老练。", type: "exclusive"}
        ]
    },
    {
        name: "319.鬼吹灯",
        desc: "人点烛，鬼吹灯。摸金校尉、搬山道人、卸岭力士、发丘天官。胡八一与雪莉杨探寻十六字阴阳风水秘术的奥秘。",
        boss: "精绝女王, 尸香魔芋, 献王, 观山太保",
        identities: [
