        ],
        talents: [
            {name: "唤魔经", color: "SSS", cost: 45000, desc: "辰家家传玄功。修炼此功，体内会产生魔性，最终唤醒远祖战魂。虽然强大，但容易迷失自我，变成杀戮机器。", type: "exclusive"},
            {name: "内天地(种子)", color: "SSS", cost: 40000, desc: "开辟一方独立的小世界。随着修为增长，内天地可以演化为真实世界。你是世界的主宰，调动世界之力镇压敌人。", type: "exclusive"},
            {name: "逆天七魔刀", color: "SS", cost: 15000, desc: "以生命为代价劈出的七刀，一刀比一刀强。七刀出，神魔哭。这是同归于尽的禁忌绝学。", type: "exclusive"},
            {name: "后羿弓", color: "SS", cost: 12000, desc: "上古神器，需以生命精气拉开。一箭射出，可追星逐月，射杀神魔。远程核打击。", type: "exclusive"},
            {name: "神魔图(残)", color: "S", cost: 8000, desc: "太极神魔图的残片，拥有生死流转之力。可以磨灭敌人的灵识，也可以防御极强的攻击。", type: "exclusive"},
            {name: "擒龙手", color: "S", cost: 3000, desc: "失传的绝学，隔空取物，凝聚光掌擒拿巨龙。近战法师的招牌技能。", type: "exclusive"},
            {name: "玄武甲", color: "A", cost: 2500, desc: "神兽玄武的甲壳炼制而成，防御力惊人。穿上它，你就是打不死的小强。", type: "exclusive"},
            {name: "困天索", color: "A", cost: 2200, desc: "传说中能困住上天的绳索。虽然是仿品，但困住同阶修士绰绰有余。", type: "exclusive"},
            {name: "东方武者体质", color: "B", cost: 800, desc: "你拥有纯正的东方武者血统，修炼真气速度快，肉身强悍，能够释放护体罡气。", type: "exclusive"},
            {name: "魔法免疫(低)", color: "B", cost: 1000, desc: "你的身体对西方魔法有一定抗性。火球术打在你身上就像挠痒痒。", type: "exclusive"},
            {name: "龙骑士契约", color: "C", cost: 500, desc: "你拥有成为龙骑士的资质，可以与亚龙甚至巨龙签订契约，并肩作战。", type: "exclusive"},
            {name: "痞子气", color: "D", cost: 50, desc: "你说话做事像个流氓，容易拉仇恨。但也可能因此结交到一些性格豪爽的朋友（如紫金神龙）。", type: "exclusive"},
            {name: "复活后遗症", color: "D", cost: 100, desc: "你刚从坟墓里爬出来，记忆缺失，身体僵硬。需要一段时间恢复。", type: "exclusive"},
            {name: "天谴之人", color: "E", cost: 20, desc: "你被上天诅咒，修炼进阶时雷劫比别人强十倍。活下来的几率渺茫。", type: "exclusive"},
            {name: "大胃王", color: "C", cost: 80, desc: "你需要消耗大量食物来维持身体机能，容易饿。", type: "exclusive"}
        ]
    },
              {
        name: "321.长生界",
        desc: "一个被遗忘的战场，祖神陨落之地。这里有裹尸布缠身的神秘人，有背负天碑的修者，也有在这个虚幻与真实交织的世界中挣扎求生的蝼蚁。武道极致，神通盖世。",
        boss: "异界祖神, 鸿钧, 乱古五雄",
        identities: [
            { name: "九州死城外的枯骨", items: "一截不知名强者的指骨, 一块破碎的裹尸布" },
            { name: "龙岛上的失忆修者", items: "一把卷刃的铁剑, 一枚伴生的龙形玉佩" },
            { name: "南荒蛮族的少年", items: "一根兽骨打磨的狼牙棒, 一罐用来涂抹身体的兽血" },
            { name: "被家族遗弃的废柴", items: "一本残缺的基础内功, 一封退婚书" },
            { name: "长生大陆的落魄商贩", items: "一辆吱呀作响的推车, 几块毫无灵气的石头" }
        ],
        talents: [
            {name: "天碑玄法(残)", color: "S", cost: 2800, desc: "你参悟了一面天碑上的部分刻图，掌握了以此锻造神体的方法，虽然残缺，但足以让你肉身成圣。", type: "exclusive"},
            {name: "珂珂的零食", color: "B", cost: 400, desc: "你偷藏了几枚雪白小兽爱吃的灵果，虽然没有逆天功效，但能快速恢复灵力和伤势。", type: "exclusive"},
            {name: "八臂恶龙血脉", color: "A", cost: 900, desc: "你拥有上古凶兽的稀薄血脉，战斗时可幻化出多条手臂，力量倍增，性格也会变得暴躁。", type: "exclusive"},
            {name: "神魔图(仿)", color: "SS", cost: 6500, desc: "你拥有一卷仿制的阵图，虽不如真品能封印祖神，但困住一般的高手绰绰有余，内含乾坤。", type: "exclusive"},
            {name: "武祖真经(起手式)", color: "S", cost: 2500, desc: "武祖留下的基础武道真意，没有任何花哨，只有最极致的杀伐之力，近战无敌。", type: "exclusive"},
            {name: "黄泥台(碎片)", color: "SSS", cost: 12000, desc: "传说中那是祖神血肉铸就的圣物。即便只有指甲盖大小的一块，也能让你万法不侵，镇压诸天。", type: "exclusive"},
            {name: "伴生战剑(虚影)", color: "A", cost: 850, desc: "你的灵魂中寄宿着一柄战剑的虚影，能发出凌厉的剑气，对灵魂体有奇效。", type: "exclusive"},
            {name: "不死门徒", color: "C", cost: 180, desc: "你学过一些邪门的养尸之法，可以将尸体炼制成听话的傀儡，虽然恶心但很实用。", type: "exclusive"},
            {name: "雪白小兽的亲和", color: "SS", cost: 8000, desc: "你身上有一种让天地灵兽都感到亲切的气息，容易获得神兽幼崽的青睐，甚至能听懂兽语。", type: "exclusive"},
            {name: "古神荒漠的诅咒", color: "E", cost: 50, desc: "你曾误入禁地，每到月圆之夜，你的皮肤会干裂如枯木，全属性下降50%，痛不欲生。", type: "exclusive"},
            {name: "三皇镜(伪)", color: "A", cost: 700, desc: "一面古朴的铜镜，可以照破虚妄，看穿敌人的伪装和隐身，关键时刻能反射一次能量攻击。", type: "exclusive"},
            {name: "北斗七星封印", color: "S", cost: 2200, desc: "你掌握了一种强大的封印术，可以借用星辰之力封印对手的修为，持续时间视双方差距而定。", type: "exclusive"},
            {name: "燧人钻(火种)", color: "SS", cost: 7500, desc: "文明的火种，永不熄灭。你可以操控这种神火，焚烧万物，对阴邪之物有毁灭性打击。", type: "exclusive"},
            {name: "遁去的一", color: "SSS", cost: 30000, desc: "大道五十，天衍四九。你是那个变数。你的命运无法被推演，你总能在必死的局中找到唯一的生机。", type: "exclusive"},
            {name: "祖龙皮囊", color: "S", cost: 3200, desc: "你披着一张完整的人皮，实则是祖龙蜕下的皮，防御力惊人，且能掩盖自身一切气息。", type: "exclusive"}
        ]
    },
    {
        name: "322.盘龙",
        desc: "玉兰大陆，魔兽横行。这是一个魔法与斗气并存的世界，强者可以成神，拥有永恒的生命。四大至高位面和七大神位面等待着强者的探索。",
        boss: "奥古斯塔, 贝鲁特, 鸿蒙",
        identities: [
            { name: "乌山镇的平民少年", items: "一把破旧的石雕刻刀, 一块普通的石头" },
            { name: "芬莱城的落魄贵族", items: "一枚生锈的家族徽章, 一把装饰用的细剑" },
            { name: "魔兽山脉的低级佣兵", items: "一柄缺口的双手大剑, 一袋廉价的止血粉" },
            { name: "黑暗教廷的狂信徒", items: "一本黑暗教典, 一瓶劣质的毒药" },
            { name: "恩斯特学院的杂工", items: "一把扫帚, 一本被丢弃的初级魔法笔记" }
        ],
        talents: [
            {name: "盘龙戒指(破损)", color: "SS", cost: 9000, desc: "一枚看似普通的戒指，里面沉睡着一个曾经的圣域强者灵魂（德林爷爷），能指导你地系魔法。", type: "exclusive"},
            {name: "龙血战士血脉(稀薄)", color: "A", cost: 800, desc: "四大终极战士血脉之一。虽然稀薄，但只要喝下活龙血，就有机会觉醒变身，肉身极强。", type: "exclusive"},
            {name: "地系魔法亲和(超等)", color: "S", cost: 2500, desc: "你对大地元素有着无与伦比的亲和力，施展地系魔法速度极快，威力是常人的数倍。", type: "exclusive"},
            {name: "噬神鼠天赋", color: "SSS", cost: 28000, desc: "贝鲁特的种族天赋。你的牙齿无坚不摧，甚至能吞噬神格来强化自身，肉身防御堪比主神器。", type: "exclusive"},
            {name: "灵魂变异(双系)", color: "SS", cost: 8500, desc: "亿万中无一的奇迹。你可以融合两种不同系的法则玄奥，威力呈几何级数增长，成神后拥有意志威能。", type: "exclusive"},
            {name: "平刀流雕刻术", color: "C", cost: 150, desc: "一种独特的石雕技艺，能让你在雕刻时进入''忘我''境界，有助于提升精神力。", type: "exclusive"},
            {name: "紫血软剑", color: "A", cost: 750, desc: "一柄薄如蝉翼的软剑，曾是神级强者的武器，虽然封印了大部分威能，但依然锋利无比。", type: "exclusive"},
            {name: "命运规则(入门)", color: "S", cost: 3000, desc: "最神秘的规则之一。你对命运有着模糊的感应，可以偶尔预知危险，或通过语言影响他人的运气。", type: "exclusive"},
            {name: "主神之力(一滴)", color: "SS", cost: 5000, desc: "蕴含主神威能的一滴能量液。使用后短时间内实力暴涨百倍，神级以下触之即死。", type: "exclusive"},
            {name: "老鼠的朋友", color: "C", cost: 120, desc: "你特别招老鼠喜欢，能指挥普通的影鼠为你探路或偷窃物品。", type: "exclusive"},
            {name: "死神傀儡", color: "A", cost: 600, desc: "一个用特殊金属打造的傀儡，只要输入斗气就能行动，不知疼痛，是最好的肉盾。", type: "exclusive"},
            {name: "生命源珠", color: "S", cost: 2100, desc: "蕴含庞大生命力的宝珠，只要没被瞬间轰成渣，就能持续修复你的身体，几乎是不死之身。", type: "exclusive"},
            {name: "大圆满潜质", color: "SSS", cost: 35000, desc: "你的悟性突破天际，在法则融合上没有瓶颈。只要时间足够，你注定成为各系法则的大圆满上位神。", type: "exclusive"},
            {name: "黑鲁的契约", color: "B", cost: 350, desc: "你拥有一只黑纹云豹作为魔兽伙伴，虽然它现在还很弱小，但速度极快，适合偷袭。", type: "exclusive"},
            {name: "位面监狱囚徒", color: "D", cost: 80, desc: "你来自戈巴达位面监狱，身上带着令人厌恶的血腥气，容易被位面监守者针对，但也更狠辣。", type: "exclusive"}
        ]
    },
    {
        name: "323.星辰变",
        desc: "潜龙大陆，修真为尊。凡人界、仙魔妖界、神界，层层递进。这是一个关于流星泪与体内宇宙演变的故事，功法决定了你的上限。",
        boss: "雷罚天尊, 飘羽天尊, 鸿蒙",
        identities: [
            { name: "云雾山庄的仆人", items: "一把扫落叶的扫帚, 一本《强身诀》" },
            { name: "潜龙大陆的先天高手", items: "一把精钢长剑, 一本下品修真功法" },
            { name: "海底修妖世界的杂鱼", items: "一根珊瑚刺, 一块下品元灵石" },
            { name: "蓬莱仙域的散修", items: "一把低级飞剑, 几张初级符箓" },
            { name: "凡人界的落魄书生", items: "一支毛笔, 一卷圣贤书" }
        ],
        talents: [
            {name: "流星泪(一半)", color: "SS", cost: 9500, desc: "生命神王死后凝聚的能量精华。它能瞬间修复你极重的伤势，并时刻滋养你的灵魂，让你领悟空间法则。", type: "exclusive"},
            {name: "通天图(三块)", color: "S", cost: 3200, desc: "神秘的功法引导图。练习上面的动作可以大幅改造身体，为你修炼《星辰变》打下完美基础。", type: "exclusive"},
            {name: "黑羽鹰(幼崽)", color: "A", cost: 850, desc: "变异的神兽后代，拥有鹏魔皇的血脉。速度极快，成长潜力巨大，是你忠实的空中坐骑。", type: "exclusive"},
            {name: "焱炽铁", color: "B", cost: 300, desc: "一种珍贵的炼器材料，质地坚硬且带有火属性，是打造上品灵器的极佳材料。", type: "exclusive"},
            {name: "星辰变功法", color: "SSS", cost: 30000, desc: "不修金丹元婴，而是演化体内宇宙。行星、恒星、黑洞、原点...直至开辟一方世界，直指大道。", type: "exclusive"},
            {name: "傀儡炼制术", color: "A", cost: 650, desc: "澜叔传授的技艺。你能炼制出实力强大的金丹期甚至元婴期傀儡，只要晶石足够，它们永不疲倦。", type: "exclusive"},
            {name: "外功宗师", color: "C", cost: 180, desc: "你无法修炼内功，但将肉体力量练到了极致。单手碎石，力举千斤，是凡人界的巅峰。", type: "exclusive"},
            {name: "姜澜界(第一层)", color: "SS", cost: 8000, desc: "神王炼制的空间神器。里面时间流速是外界的十倍，且灵气浓郁，是修炼作弊器。", type: "exclusive"},
            {name: "万兽谱(第一层)", color: "S", cost: 2600, desc: "一件可以奴役妖兽的神器。目前开启的第一层里关押着大量天妖级别的妖兽，听从你的号令。", type: "exclusive"},
            {name: "火睛水猿血脉", color: "A", cost: 900, desc: "上级神兽血脉，力大无穷，水火不侵，狂暴状态下战力倍增。", type: "exclusive"},
            {name: "瞬移(伪)", color: "S", cost: 2400, desc: "你对空间法则有了一丝感悟，可以进行短距离的瞬间移动，保命神技。", type: "exclusive"},
            {name: "极品元灵石", color: "B", cost: 400, desc: "蕴含极其纯净能量的石头，一颗足以让凡人直接筑基，或者瞬间补满金丹期的灵力。", type: "exclusive"},
            {name: "炼器宗师天赋", color: "A", cost: 700, desc: "你对火焰和材料的掌控炉火纯青，炼制出的法宝往往带有额外的特殊属性。", type: "exclusive"},
            {name: "天尊的祝福", color: "SSS", cost: 40000, desc: "来自至高天尊的关注。你的气运逆天，走路都能踢到神器，遇到必死之局也会有高人相救。", type: "exclusive"},
            {name: "迷神图卷", color: "SS", cost: 6000, desc: "记录了神界迷神殿的地图和安全路径。那是无数神人都向往的宝库，里面全是神器。", type: "exclusive"}
        ]
    },
    {
        name: "324.吞噬星空",
        desc: "地球经历RR病毒肆虐后进入大涅槃时期。武者与怪兽厮杀，古文明遗迹现世。而这只是浩瀚宇宙的冰山一角，宇宙国、不朽神灵、宇宙之主俯瞰众生。",
