            { name: "远东军的半兽人战士", items: "一把巨大的战斧, 一袋风干肉" },
            { name: "魔族王国的贵族私兵", items: "一把弯刀, 一匹战马" },
            { name: "流风家的斥候", items: "一张十字弩, 几个烟雾弹" },
            { name: "上都城的平民", items: "一个菜篮子, 几枚铜板" }
        ],
        talents: [
            {name: "光明王(称号)", color: "SSS", cost: 40000, desc: "你继承了紫川秀的称号。你在远东拥有至高无上的威望，半兽人视你为神，人类视你为救世主，统帅力MAX。", type: "exclusive"},
            {name: "修罗王(帝林)", color: "SS", cost: 8000, desc: "冷血、理智、残酷。你在指挥作战时没有任何感情波动，为了胜利可以牺牲一切，敌军闻风丧胆。", type: "exclusive"},
            {name: "紫川之虎(斯特林)", color: "SS", cost: 8000, desc: "忠诚与勇猛的化身。你的个人战力极强，且治军严明，你的部队士气永远高昂，死战不退。", type: "exclusive"},
            {name: "半兽人力士", color: "A", cost: 900, desc: "你拥有半兽人的强壮体魄，力大无穷，皮糙肉厚，是战场上的绞肉机。", type: "exclusive"},
            {name: "流风霜的智谋", color: "S", cost: 3000, desc: "大陆第一名将的智慧。你精通兵法韬略，总能以弱胜强，算无遗策。", type: "exclusive"},
            {name: "左加明王的武功", color: "S", cost: 3500, desc: "三百年前第一高手的绝学。内力深厚，招式精妙，单挑几乎无敌。", type: "exclusive"},
            {name: "秀字营编制", color: "A", cost: 1200, desc: "你拥有一支绝对忠诚的特种部队。他们装备精良，训练有素，只听从你一人的命令。", type: "exclusive"},
            {name: "魔神皇的卡丹", color: "B", cost: 500, desc: "魔族公主的信物。持有它，你在魔族领地可以畅通无阻，甚至能调动部分魔族军队。", type: "exclusive"},
            {name: "无赖战法", color: "C", cost: 200, desc: "紫川秀早期的战术。打得过就打，打不过就跑，偷袭、下毒、挖坑，无所不用其极。", type: "exclusive"},
            {name: "名将的直觉", color: "A", cost: 850, desc: "你在战场上拥有敏锐的嗅觉，能准确判断敌人的主攻方向和薄弱环节。", type: "exclusive"},
            {name: "紫川参星的隐忍", color: "S", cost: 2500, desc: "老阴比的天赋。你极善于伪装自己，让人看不透你的真实意图，关键时刻给予致命一击。", type: "exclusive"},
            {name: "强弓手天赋", color: "B", cost: 350, desc: "你擅长使用长弓，臂力惊人，百步穿杨，是战场上的狙击手。", type: "exclusive"},
            {name: "半兽人狂化", color: "A", cost: 700, desc: "在极度愤怒时，你的各项属性翻倍，但会失去理智，不分敌我地攻击。", type: "exclusive"},
            {name: "贵族礼仪", color: "C", cost: 100, desc: "你精通上流社会的礼仪，能轻松混入贵族圈子，获取情报或拉拢关系。", type: "exclusive"},
            {name: "战马精通", color: "C", cost: 150, desc: "你是天生的骑兵。无论多烈性的马，在你胯下都温顺如绵羊，骑战能力大幅提升。", type: "exclusive"}
        ]
    },
                      {
                name: "331.佣兵天下",
                desc: "艾米诺尔大陆风起云涌，这是个魔法与剑、巨龙与骑士共舞的史诗时代。小佣兵团的传奇从此开始，在这场神与人的博弈中，书写属于凡人的荣耀。",
                boss: "父神, 龙神, 死神, 邪魔王",
                identities: [
