                ],
                talents: [
                    {name: "因果缠身", color: "E", cost: 30, desc: "你身上背负着巨大的因果业力，喝凉水都塞牙。在杀劫中，你绝对是第一个被算计死用来填劫数的倒霉蛋。", type: "exclusive"},
                    {name: "根骨奇差", color: "E", cost: 10, desc: "你的身体就像漏斗，根本存不住灵气。在这个灵气充沛的地仙界，你也只能当个强壮点的凡人。", type: "exclusive"},
                    {name: "旁门左道", color: "C", cost: 180, desc: "你精通一些养鬼、炼尸的小法术。虽然登不上大雅之堂，但在低端局里阴人还是很好用的。", type: "exclusive"},
                    {name: "星辰淬体", color: "C", cost: 200, desc: "你懂得接引星光淬炼身体的法门，虽然进度缓慢，但胜在稳健，肉身比一般修士要强横一些。", type: "exclusive"},
                    {name: "化血神刀(仿)", color: "B", cost: 450, desc: "你炼制了一把仿制的化血神刀，虽然没有正品的威力，但只要划破敌人的皮肤，就能让其血液坏死。", type: "exclusive"},
                    {name: "截教遗泽", color: "B", cost: 500, desc: "你意外得到了一篇截教门人的修炼残篇，讲究有教无类，修炼速度极快，但容易根基不稳。", type: "exclusive"},
                    {name: "七十二变(残)", color: "A", cost: 950, desc: "你学会了地煞七十二变中的几种变化，可以变成石头、大树或者小动物，是躲避追杀和侦查的神技。", type: "exclusive"},
                    {name: "第二元神", color: "A", cost: 1200, desc: "你炼制出了第二元神，相当于多了一条命。在本体死亡时，可以将意识转移到第二元神上重生。", type: "exclusive"},
                    {name: "巫族血脉(稀薄)", color: "A", cost: 1100, desc: "你体内有一丝上古巫族的血脉，天生肉身强横，力大无穷，不修元神，只修肉身，近战能力恐怖。", type: "exclusive"},
                    {name: "十二都天神煞大阵(角)", color: "S", cost: 1950, desc: "你掌握了十二都天神煞大阵的一角阵纹，可以召唤出一尊祖巫虚影助战，煞气冲天，鬼神辟易。", type: "exclusive"},
                    {name: "定海神珠(伪)", color: "S", cost: 1800, desc: "你拥有定海神珠的仿制品，虽然只有一颗，但砸人极疼，且内部蕴含一个小空间，可以用来储物或困敌。", type: "exclusive"},
                    {name: "盘古烙印", color: "SS", cost: 9000, desc: "你灵魂深处有一丝盘古开天辟地的烙印。这让你在修炼肉身玄功时一日千里，拥有以力证道的潜力。", type: "exclusive"},
                    {name: "混沌钟声", color: "SS", cost: 9500, desc: "你曾聆听过混沌钟的响声，领悟了时空法则的皮毛。你可以短暂地定住周围的时间和空间，立于不败之地。", type: "exclusive"},
                    {name: "圣人算计", color: "SS", cost: 8500, desc: "你拥有堪比圣人的算计能力，能够从无数因果线中找到对自己最有利的一条，把所有人都玩弄于股掌之间。", type: "exclusive"},
                    {name: "以力证道", color: "SSS", cost: 40000, desc: "你选择了最艰难也是最强大的证道之路。不斩三尸，不修功德，只凭自身法力破开天道，成就混元无极大罗金仙。", type: "exclusive"}
                ]
            },
            {
                name: "335.龙蛇演义",
                desc: "只杀敌，不表演的武术。这是一个国术流的巅峰世界，明劲、暗劲、化劲、丹劲、罡劲，直到打破虚空，见神不坏。王超的拳，是打出来的真理。",
                boss: "GOD首领, 巴立明, 王超, 唐紫尘",
                identities: [
                    { name: "公园里晨练的高中生", items: "一套宽松的校服, 一双磨平了底的球鞋" },
                    { name: "黑市拳坛的肉靶子", items: "满身的淤青, 一瓶廉价的跌打酒" },
                    { name: "武馆里的扫地学徒", items: "一把扫帚, 一本偷看来的拳谱" },
                    { name: "退役的特种兵保安", items: "一把战术匕首, 一张褪色的军人证" },
                    { name: "唐人街的洗碗工", items: "一双粗糙的大手, 一条脏围裙" }
                ],
                talents: [
                    {name: "身体虚弱", color: "E", cost: 10, desc: "你从小体弱多病，走几步路都喘。在这个讲究身体素质的国术世界，你连站桩都站不稳。", type: "exclusive"},
                    {name: "动作僵硬", color: "E", cost: 5, desc: "你的肢体协调性极差，打起拳来像是在跳机械舞。任何高难度的发力动作对你来说都是不可能完成的任务。", type: "exclusive"},
                    {name: "站桩入门", color: "C", cost: 120, desc: "你掌握了马步站桩的要领，下盘稳固，气血运行比常人顺畅。虽然还没练出劲力，但身体素质已超常人。", type: "exclusive"},
                    {name: "铁砂掌(粗浅)", color: "C", cost: 150, desc: "你用绿豆和铁砂练过手，手掌粗糙坚硬，一巴掌下去能拍碎红砖。但要注意药酒护理，否则手会废掉。", type: "exclusive"},
                    {name: "明劲巅峰", color: "B", cost: 400, desc: "你已经练透了全身的骨骼肌肉，一拳打出，空气炸响，千金难买一声响。你的每一击都蕴含着整劲。", type: "exclusive"},
                    {name: "听劲", color: "B", cost: 350, desc: "你通过推手练习，掌握了听劲的技巧。在与人接触的瞬间，能感知到对方重心的变化和发力的方向。", type: "exclusive"},
                    {name: "暗劲勃发", color: "A", cost: 800, desc: "你领悟了暗劲的奥秘，心意一动，毛孔开合，劲力透体而入。打人如挂画，伤人内脏于无形之中。", type: "exclusive"},
                    {name: "钓蟾劲", color: "A", cost: 900, desc: "你掌握了道家练气的秘法，呼吸之间腹部如蟾蜍鼓荡，能够极大地增强内脏的承受力和爆发力。", type: "exclusive"},
                    {name: "虎豹雷音", color: "A", cost: 950, desc: "你通过特殊的发声技巧，震荡骨髓，以此来洗髓换血。你的骨骼坚硬如铁，造血功能极其强大。", type: "exclusive"},
                    {name: "化劲宗师", color: "S", cost: 1800, desc: "你全身敏感如羽毛，一羽不能加，蝇虫不能落。任何攻击临身，都能被你顺势化解，周身无处不发力。", type: "exclusive"},
                    {name: "抱丹坐胯", color: "S", cost: 1950, desc: "你能将全身的气血和劲力浓缩在丹田一点，瞬间爆发出来。这一击的威力，足以开碑裂石，人尽敌国。", type: "exclusive"},
                    {name: "金刚不坏(肉身)", color: "SS", cost: 6000, desc: "你的肉身修炼到了极致，不漏气血，不漏神意。皮肤坚韧如牛皮，肌肉如钢丝，普通的刀枪难伤分毫。", type: "exclusive"},
                    {name: "至诚之道", color: "SS", cost: 7500, desc: "你的精神修为达到了至诚之道，可以前知。在危险降临之前，你就会产生心血来潮的感应，从而避开死劫。", type: "exclusive"},
                    {name: "打破虚空", color: "SS", cost: 8500, desc: "你的精神与肉体高度统一，打破了人体极限的枷锁。你可以短暂地滞空，甚至在这末法时代展现出近乎神通的能力。", type: "exclusive"},
                    {name: "见神不坏", color: "SSS", cost: 30000, desc: "你对自己身体的掌控达到了入微的境界，能内视并控制体内的每一个穴窍和细胞。你就是行走的人体神明，寿元大增。", type: "exclusive"}
                ]
            },
            {
                name: "336.阳神",
                desc: "世间是一个大苦海，肉身是船，灵魂是船里的人。这是一个神魂修仙与人仙武道并存的世界。洪易读圣贤书，修过去未来，以此岸渡彼岸。",
                boss: "洪玄机, 梦神机, 虚易, 杨盘",
                identities: [
                    { name: "玉京城的落魄书生", items: "一本泛黄的论语, 一支秃笔" },
                    { name: "大禅寺的逃亡小沙弥", items: "半卷烧焦的经书, 一个紫金钵盂" },
                    { name: "边军的斥候", items: "一把强弓, 一袋狼牙箭" },
                    { name: "狐族的伴读书童", items: "一盏青灯, 几本志怪小说" },
                    { name: "海外蛮夷的奴隶", items: "沉重的脚镣, 采珠的工具" }
                ],
                talents: [
                    {name: "神魂受损", color: "E", cost: 20, desc: "你的神魂曾经受到过惊吓或创伤，极其不稳定。夜晚不敢出门，稍微遇到一点阴风就会头痛欲裂。", type: "exclusive"},
                    {name: "肉身孱弱", color: "E", cost: 10, desc: "典型的百无一用是书生，手无缚鸡之力。在这个武道昌盛的世界，你可能连一只看门狗都打不过。", type: "exclusive"},
                    {name: "夜游神魂", color: "C", cost: 180, desc: "你的神魂已经可以出窍，在夜间自由活动。虽然没有什么攻击力，但用来侦查情报或者吓唬凡人还是不错的。", type: "exclusive"},
                    {name: "武道先天", color: "C", cost: 200, desc: "你打通了全身经脉，踏入了先天武师的境界。呼吸悠长，力大如牛，在凡俗军队中可以担任百人敌的猛将。", type: "exclusive"},
                    {name: "观想之法", color: "B", cost: 400, desc: "你掌握了一门高深的观想法，可以通过观想特定的神魔形象来壮大神魂，抵御外界的干扰和魔头。", type: "exclusive"},
                    {name: "牛魔大力拳", color: "B", cost: 350, desc: "你习得了大禅寺的基础筑基拳法，练皮肉，练筋骨。你的肉身结实紧致，力量是同级武者的两倍。", type: "exclusive"},
                    {name: "鬼仙(尸解)", color: "A", cost: 1000, desc: "你虽然肉身已死，但神魂修成了鬼仙，可以夺舍重生。虽然失去了进一步提升的可能，但也算另类的长生。", type: "exclusive"},
                    {name: "雷劫念头", color: "A", cost: 1200, desc: "你的神魂度过了雷劫，念头纯阳，晶莹剔透。每一个念头都可以化为独立的个体，拥有强大的法力和智慧。", type: "exclusive"},
                    {name: "人仙之身", color: "A", cost: 1100, desc: "你肉身成圣，换血洗髓，踏入人仙境界。气血如狼烟直冲云霄，一声大吼就能震散鬼仙的神魂。", type: "exclusive"},
                    {name: "过去弥陀经", color: "S", cost: 2000, desc: "你修炼了过去弥陀经，神魂坚固不可摧毁。只要还有一个念头尚存，你就能重新凝聚神魂，近乎不死。", type: "exclusive"},
                    {name: "现在如来经", color: "S", cost: 2000, desc: "你掌握了现在如来经的总纲，肉身拥有掌握现在的力量，统摄周身穴窍，力量无穷无尽，霸道绝伦。", type: "exclusive"},
                    {name: "未来无生经", color: "SS", cost: 7000, desc: "你修炼了未来无生经，可以集众生愿力，凝聚身外化身。你能推演未来，趋吉避凶，让信仰你的人为你提供源源不断的力量。", type: "exclusive"},
                    {name: "造化之舟图纸", color: "SS", cost: 8500, desc: "你拥有神器之王造化之舟的建造图纸。只要有足够的资源，你就能打造出这艘横渡苦海的巨舰，撞碎一切阻碍。", type: "exclusive"},
                    {name: "粉碎真空", color: "SS", cost: 9500, desc: "你的肉身修炼到了极致，粉碎了真实与虚幻的界限。你的身体就是最强的神器，可以硬抗阳神强者的攻击。", type: "exclusive"},
                    {name: "阳神", color: "SSS", cost: 45000, desc: "神魂修炼的终点，纯阳无阴，聚散随心，千变万化。你的念头可以化为一个世界，你就是世间唯一的真神。", type: "exclusive"}
                ]
            },
            {
                name: "337.永生",
                desc: "吃人流的巅峰。肉身秘境，神通秘境，长生秘境，永生秘境。方寒告诉你，只要胆子大，神仙也敢吃。三千大道，大命运术，永生之门。",
                boss: "华天都, 玲珑仙尊, 造化仙王, 电母天君",
                identities: [
                    { name: "羽化门的喂马家丁", items: "一把刷马的刷子, 一本偷藏的九窍金丹残渣" },
                    { name: "地底魔人的混血儿", items: "一根骨刺, 一身洗不掉的魔气" },
                    { name: "归虚海域的散修", items: "一个破损的储物袋, 一把下品飞剑" },
                    { name: "太一门的杂役弟子", items: "一把扫帚, 一块刻着灾难的木牌" },
                    { name: "龙木星的土著居民", items: "一块充满灵气的木头, 一张简陋的弓" }
                ],
                talents: [
                    {name: "丹田破碎", color: "E", cost: 20, desc: "你的丹田破碎，无法储存法力。在这个法力至上的世界，你注定只能当一个凡人，任人宰割。", type: "exclusive"},
                    {name: "贪婪成性", color: "E", cost: 10, desc: "你对力量和宝物有着病态的渴望，这往往会让你失去理智，冲进明显的陷阱，或者得罪不该得罪的大人物。", type: "exclusive"},
                    {name: "九窍金丹(药力)", color: "C", cost: 180, desc: "你服用过九窍金丹，虽然大部分药力浪费了，但心脏多了一窍，气血运转极快，精力无穷，肉身潜力巨大。", type: "exclusive"},
                    {name: "精神力过人", color: "C", cost: 160, desc: "你的脑域开发度比常人高，记忆力和领悟力超群。学习任何武功和神通都事半功倍，有望踏入神通秘境。", type: "exclusive"},
                    {name: "五帝大魔神通(残)", color: "B", cost: 500, desc: "你学会了五帝大魔神通中的一种，虽然不完整，但威力依然惊人。你可以操控五行元气，碾压同级对手。", type: "exclusive"},
                    {name: "蛟龙血肉", color: "B", cost: 450, desc: "你曾食用过蛟龙的血肉，身体坚韧度大幅提升，拥有龙象之力。普通的刀剑砍在你身上只能留下一道白印。", type: "exclusive"},
                    {name: "法力无边", color: "A", cost: 1000, desc: "你的法力品质极高，且容量是同阶修士的十倍。你可以肆无忌惮地释放神通，完全不用担心法力枯竭。", type: "exclusive"},
                    {name: "大吞噬术", color: "A", cost: 1500, desc: "你掌握了三千大道中的大吞噬术，可以吞噬一切元气、法宝甚至敌人的血肉来强化自身。吃得越多，变得越强。", type: "exclusive"},
                    {name: "不死之身", color: "A", cost: 1800, desc: "你修成了长生秘境的不死之身，只要头颅不灭，身体任何部位被斩断都能瞬间重生，生命力顽强如蟑螂。", type: "exclusive"},
                    {name: "黄泉图(器灵)", color: "S", cost: 2500, desc: "你得到了绝品道器黄泉图的认可，拥有忘情水和轮回之盘的辅助。你可以洗刷一切法宝的印记，建立轮回通道。", type: "exclusive"},
                    {name: "大因果术", color: "S", cost: 2800, desc: "你精通大因果术，因果报应，丝毫不爽。你可以通过因果线攻击敌人，或者斩断自己的因果，躲避算计。", type: "exclusive"},
                    {name: "三十三天造化神拳", color: "SS", cost: 8000, desc: "你掌握了造化仙王的绝学，每一拳都蕴含着造化的奥义。你可以打出三十三倍战力，毁天灭地，重塑乾坤。", type: "exclusive"},
                    {name: "世界之树幼苗", color: "SS", cost: 9000, desc: "你体内融合了世界之树的幼苗，可以沟通仙界，汲取纯阳元气。你是神族的天敌，可以将其炼化为神通果实。", type: "exclusive"},
                    {name: "小宿命术", color: "SS", cost: 9500, desc: "你领悟了命运的一丝真谛，可以通过燃烧寿命来换取强大的力量。虽然代价高昂，但在拼命时无人能敌。", type: "exclusive"},
                    {name: "大命运术", color: "SSS", cost: 50000, desc: "三千大道总纲，排名第一的神通。你掌握了命运的喉咙，言出法随，无所不能。连永生之门都要向你敞开。", type: "exclusive"}
                ]
            },
            {
                name: "338.圣王",
                desc: "神象镇狱劲，以气引神，以神成象。人体由八亿四千万微粒组成，每一颗微粒都是一头巨象。杨奇的霸道，是镇压地狱，主宰诸神。",
                boss: "傲天, 诛仙王, 梵神, 大祭司",
                identities: [
                    { name: "丰饶大陆的落魄少爷", items: "一枚被退婚的信物, 一身被雷劈过的焦痕" },
                    { name: "天位学院的杂役学生", items: "一本基础气功书, 一个用来扫地的扫把" },
                    { name: "悬空山的妖族奴隶", items: "沉重的项圈, 一身鞭痕" },
                    { name: "泰皇学府的炮灰弟子", items: "一把断剑, 一张破损的护身符" },
                    { name: "未来世界的机械战士残骸", items: "半个机械眼球, 一块能量耗尽的电池" }
                ],
                talents: [
                    {name: "经脉寸断", color: "E", cost: 20, desc: "你的经脉全部断裂，无法修炼任何气功。在这个力量至上的世界，你就是一个彻底的废人，只能苟且偷生。", type: "exclusive"},
                    {name: "厄运缠身", color: "E", cost: 15, desc: "你仿佛被命运女神抛弃，走路摔跤，喝水塞牙。任何好运都会绕着你走，任何倒霉事都会找上你。", type: "exclusive"},
                    {name: "气功天才", color: "C", cost: 180, desc: "你对气功的感悟远超常人，修炼速度极快。普通人需要十年才能练成的气功，你只需要一年就能大成。", type: "exclusive"},
                    {name: "雷霆抗性", color: "C", cost: 150, desc: "你天生对雷霆力量有抗性，甚至可以吸收微弱的雷电来淬炼身体。在雷雨天修炼，你的进度会倍增。", type: "exclusive"},
                    {name: "恶魔血统", color: "B", cost: 400, desc: "你拥有一半的地狱恶魔血统，肉身强横，性格残忍。在黑暗环境中，你的战斗力会大幅提升。", type: "exclusive"},
                    {name: "天使之翼(伪)", color: "B", cost: 500, desc: "你通过某种秘法移植了一对光翼，虽然不能像真正的天使那样飞行，但可以短暂滑翔，并增加光系气功威力。", type: "exclusive"},
                    {name: "传奇变", color: "A", cost: 1000, desc: "你突破了夺命境，踏入了传奇境界。你掌握了法则的力量，可以操控天地元气，寿命大大延长。", type: "exclusive"},
                    {name: "大圣境界", color: "A", cost: 1500, desc: "你成就了大圣，拥有移山填海的伟力。你的领域坚不可摧，在这个位面中，你就是一方霸主。", type: "exclusive"},
                    {name: "地狱之门", color: "A", cost: 1800, desc: "你可以召唤出地狱之门，从中召唤出无穷无尽的恶魔大军为你作战。只要地狱不空，你的军团就不灭。", type: "exclusive"},
                    {name: "诸神印记(碎片)", color: "S", cost: 3000, desc: "你得到了一块微小的诸神印记碎片，虽然不完整，但依然能让你统御诸神，镇压恶魔，拥有无上的威严。", type: "exclusive"},
                    {name: "吞天王符箓", color: "S", cost: 2800, desc: "你收集到了吞天王的符箓，可以化身混沌古蛇，吞噬一切。无论是能量、法宝还是世界，都是你的食物。", type: "exclusive"},
                    {name: "命运之轮", color: "SS", cost: 9000, desc: "你凝练出了命运之轮，可以看穿命运的轨迹。你可以拨动命运的琴弦，让敌人的攻击落空，让自己永远处于有利位置。", type: "exclusive"},
                    {name: "万界王图", color: "SS", cost: 9500, desc: "你掌握了万界王图的钥匙，可以自由穿梭于诸天万界。你拥有一个独立的世界作为后盾，资源取之不尽。", type: "exclusive"},
                    {name: "无无级意志", color: "SS", cost: 8500, desc: "你的精神意志达到了无无级，无生无灭，无始无终。没有任何精神攻击能伤害你，你的一念之间就能生灭世界。", type: "exclusive"},
                    {name: "神象镇狱劲", color: "SSS", cost: 50000, desc: "主宰级气功，以气引神，以神成象。觉醒八亿四千万微粒，每一颗微粒都是巨象之力。手摘星辰，脚踏地狱，吼落日月。", type: "exclusive"}
                ]
            },
            {
                name: "339.全职法师",
                desc: "魔法取代了科学，但世界依然残酷。妖魔在安界外虎视眈眈，法师是人类的守护者。莫凡天生双系，在这个魔法为尊的世界，走出了自己的全职之路。",
                boss: "黑教廷红衣主教, 撒朗, 胡夫, 海底帝王",
                identities: [
                    { name: "博城的一名普通高中生", items: "一本魔法基础理论书, 一张模拟考卷" },
                    { name: "城市猎妖队的替补队员", items: "一把特制的匕首, 一个通讯器" },
                    { name: "黑教廷的底层蓝衣执事", items: "一件蓝色斗篷, 一瓶狂暴之泉" },
                    { name: "古都亡灵区的拾荒者", items: "一包大蒜, 一个护身符" },
                    { name: "帕特农神庙的杂役", items: "一瓶圣水, 一束橄榄枝" }
                ],
                talents: [
                    {name: "魔法绝缘体", color: "E", cost: 20, desc: "你的星尘完全无法觉醒，对魔法元素没有任何亲和力。在这个世界，你只能做一个生活在底层的普通人。", type: "exclusive"},
                    {name: "星子把控困难", color: "E", cost: 10, desc: "你的精神力极差，把控星子就像抓泥鳅一样困难。别人释放魔法只需一秒，你需要一分钟，战斗中必死无疑。", type: "exclusive"},
                    {name: "初阶觉醒", color: "C", cost: 150, desc: "你成功觉醒了第一系魔法（如火、雷、冰等），虽然只是初阶，但也让你脱离了凡人的范畴，拥有了战斗力。", type: "exclusive"},
                    {name: "灵级星尘魔器", color: "C", cost: 200, desc: "你拥有一个灵级星尘魔器，可以大幅缩短你的冥修时间，让你的修炼速度比同龄人快上一倍。", type: "exclusive"},
                    {name: "天生灵种", color: "B", cost: 500, desc: "你觉醒的魔法系天生附带灵种，威力是普通魔法的2-3倍，且附带特殊效果（如燃烧、麻痹、冻结）。", type: "exclusive"},
                    {name: "掌控力超群", color: "B", cost: 450, desc: "你对魔法的掌控力极强，可以随意改变魔法的形态和轨迹。你的火球可以拐弯，你的风刃可以回旋。", type: "exclusive"},
                    {name: "高阶法师", color: "A", cost: 1200, desc: "你已经晋升为高阶法师，掌握了星座级魔法。你可以释放出覆盖大范围的毁灭性魔法，是战场上的炮台。", type: "exclusive"},
                    {name: "统领级召唤兽", color: "A", cost: 1100, desc: "你的召唤系魔法极其强大，契约了一只统领级妖魔。它皮糙肉厚，攻击力强悍，甚至能独自对抗一支军队。", type: "exclusive"},
                    {name: "暗影系高阶", color: "A", cost: 1000, desc: "你是暗影系的专家，擅长潜行和刺杀。在夜色中，你是无形的死神，没有任何人能逃过你的追杀。", type: "exclusive"},
                    {name: "天生双系", color: "S", cost: 2500, desc: "你在每次觉醒时都能觉醒两个系。这意味着你的手段比别人多一倍，魔法组合千变万化，同阶无敌。", type: "exclusive"},
                    {name: "超阶满修", color: "S", cost: 3000, desc: "你达到了超阶满修的境界，距离禁咒只差一步。你可以构建星宫，释放出毁天灭地的超阶魔法。", type: "exclusive"},
                    {name: "恶魔系化身", color: "SS", cost: 8000, desc: "你通过某种实验获得了恶魔系的力量。变身后，你的实力暴涨数十倍，拥有统领级妖魔的体魄和魔法的毁灭力。", type: "exclusive"},
                    {name: "图腾守护者", color: "SS", cost: 7500, desc: "你是一只古老图腾兽的守护者，可以借用图腾的力量。图腾兽是人类古老的盟友，拥有对抗帝王级妖魔的潜力。", type: "exclusive"},
                    {name: "罹难者", color: "SS", cost: 8500, desc: "你是天生的罹难者，体内蕴含着过于庞大的魔法力量，甚至会失控引发灾难。但若能控制，你就是人形核弹。", type: "exclusive"},
                    {name: "全系禁咒", color: "SSS", cost: 40000, desc: "你打破了魔法的规则，全系皆修至禁咒境界。你可以独立施展禁咒，无需引导。你是人类最强的法神，妖魔帝王的噩梦。", type: "exclusive"}
                ]
            },
            {
                name: "340.大王饶命",
                desc: "灵气复苏的时代，吕树依靠负面情绪收集系统，怼人变强。这是一个充满了段子、热血与星辰大海的世界。星图亮起，万物皆可为剑。",
                boss: "傀儡师, 聂廷, 吕神, 卡洛儿",
                identities: [
                    { name: "洛城外国语学校的学生", items: "一箱煮好的茶叶蛋, 几个硬币" },
                    { name: "天罗地网的F级觉醒者", items: "一块黑色的身份牌, 一把制式长剑" },
                    { name: "遗迹中的探险者", items: "一个指南针, 一袋压缩饼干" },
                    { name: "黑市里的二道贩子", items: "几颗低级灵石, 一本假秘籍" },
                    { name: "海外某组织的间谍", items: "一本伪造的护照, 一个窃听器" }
                ],
                talents: [
                    {name: "资质平庸", color: "E", cost: 10, desc: "你的修炼资质极差，哪怕灵气复苏了，你也吸不进几口。看着别人觉醒异能，你只能在旁边喊666。", type: "exclusive"},
                    {name: "嘴笨", color: "E", cost: 5, desc: "在这个靠怼人赚负面情绪值的世界，你竟然嘴笨！这不仅让你少了很多乐趣，还让你在这个世界显得格格不入。", type: "exclusive"},
                    {name: "力量觉醒(F级)", color: "C", cost: 120, desc: "你觉醒了最基础的力量系异能，力气比普通人大一些，能扛起几袋大米。虽然不强，但好歹也是个觉醒者。", type: "exclusive"},
                    {name: "元素感知", color: "C", cost: 150, desc: "你对某种元素（如火、水）有微弱的感知能力，可以用来点烟或者冰镇饮料。战斗作用有限，但生活便利。", type: "exclusive"},
                    {name: "剑道天赋", color: "B", cost: 450, desc: "你对剑术有着极高的悟性，随手挥出的剑招都带有几分韵味。在灵气复苏初期，你可以凭借剑术越级挑战。", type: "exclusive"},
                    {name: "洗髓果实", color: "B", cost: 500, desc: "你吃下过洗髓果实，体质得到了极大的改善，排出了杂质。你的修炼速度大幅提升，皮肤也变得更好了。", type: "exclusive"},
                    {name: "C级高手", color: "A", cost: 900, desc: "你的实力达到了C级，能够灵气外放，形成护体罡气。在普通人眼中，你已经是超人般的存在。", type: "exclusive"},
                    {name: "尸狗/伏矢(飞剑)", color: "A", cost: 1200, desc: "你温养出了属于自己的飞剑（如尸狗或伏矢），心意相通，千里之外取人首级。飞剑一出，谁与争锋。", type: "exclusive"},
                    {name: "水系异能(B级)", color: "A", cost: 1000, desc: "你觉醒了强大的水系异能，达到了B级。你可以操控大量水流进行攻击或防御，在有水的地方战斗力倍增。", type: "exclusive"},
                    {name: "天罗职位", color: "S", cost: 2200, desc: "你是天罗地网的一方天罗，拥有极高的权力和资源。你可以调动大量觉醒者，且自身实力至少是A级。", type: "exclusive"},
                    {name: "神藏境", color: "S", cost: 2500, desc: "你开启了人体神藏，实力踏入A级巅峰。你的身体机能达到了人类极限，举手投足间都有莫大的威能。", type: "exclusive"},
                    {name: "星图功法", color: "SS", cost: 8500, desc: "你修炼了吕树同款的星图功法，点亮星辰，获得星辰之力。你的每一拳都带着星辰的重量，且拥有专属的星辰剑气。", type: "exclusive"},
                    {name: "暗图之主", color: "SS", cost: 9000, desc: "你觉醒了暗图，与吕小鱼一样可以拘役魂魄。你可以收集强者的魂魄为你作战，组建一支亡灵大军。", type: "exclusive"},
                    {name: "世界树", color: "SS", cost: 9500, desc: "你拥有世界树的幼苗或枝桠，可以源源不断地提供生命力和灵气。它是世界的根基，能让你立于不败之地。", type: "exclusive"},
                    {name: "负面情绪系统", color: "SSS", cost: 50000, desc: "你拥有了传说中的系统，可以通过收集别人的负面情绪值来抽奖和兑换物品。只要你够贱，你就能无限变强。", type: "exclusive"}
                ]
            },
                      {
                name: "341.牧神记",
                desc: "大墟的残老村，延康的变法，无忧乡的迷梦。这是一个“神为人用”的时代，霸体秦牧从黑暗中走出，以凡人之躯，打破诸神亘古不变的统治，重塑天地立心。",
                boss: "太帝, 昊天尊, 弥罗宫主人",
                identities: [
                    { name: "大墟弃民", items: "一块刻着奇怪符文的玉佩, 一身破烂的兽皮衣" },
                    { name: "延康国太学博士", items: "几卷未写完的变法策论, 一支用秃了的毛笔" },
                    { name: "西土阵法师学徒", items: "几块劣质的阵石, 一张画错的阵图" },
                    { name: "上苍虚伪的神人", items: "一身光鲜亮丽但虚假的神铠, 收集信仰的香炉" },
                    { name: "残老村的误入者", items: "被药师毒翻的野兽肉, 只有一只腿的板凳" }
                ],
                talents: [
                    {name: "霸体(伪)", color: "SSS", cost: 50000, desc: "虽然是村长骗你的，但你信了，它就是真的！只要你拥有打破心中神的勇气，你就是举世无双的霸体，普通拳也能打出神通效果。", type: "exclusive"},
                    {name: "九胚胎元功", color: "SS", cost: 8000, desc: "延康变法的核心功法之一，能够让你的元神拥有多种形态和属性，适应任何复杂的战斗环境，是成神的基础。", type: "exclusive"},
                    {name: "神眼(封印)", color: "S", cost: 2500, desc: "你的眉心竖眼中封印着古神的力量，虽然目前只能用来夜视和看穿低级幻术，但解封之日必将震动天地。", type: "exclusive"},
                    {name: "瘸子的腿功", color: "A", cost: 800, desc: "偷天换日，神行无影。你学到了残老村瘸子爷爷的一点皮毛，逃跑速度一流，顺手牵羊的本事更是出神入化。", type: "exclusive"},
                    {name: "药师的毒经", color: "A", cost: 850, desc: "你掌握了以毒攻毒的精髓，能配置出连神魔都忌惮的毒药，当然，也能治好大部分常规伤势。", type: "exclusive"},
                    {name: "画道入门", color: "B", cost: 400, desc: "跟随聋子爷爷学习的画技，虽然画不出真实世界，但画个门用来穿墙或者画个饼充饥还是没问题的。", type: "exclusive"},
                    {name: "打铁技巧", color: "C", cost: 150, desc: "哑巴爷爷教你的打铁手艺，你的臂力惊人，能够将普通的凡铁锻造成锋利的兵器。", type: "exclusive"},
                    {name: "大育天魔经(残)", color: "S", cost: 2200, desc: "天魔教的镇教神功，虽然你只得到了一部分，但那种随心所欲、不拘一格的魔道真意让你在战斗中变幻莫测。", type: "exclusive"},
                    {name: "延康变法支持者", color: "C", cost: 100, desc: "你坚信变法能改变世界，这让你在面对守旧派势力时，精神意志格外坚定，不易被神威压垮。", type: "exclusive"},
                    {name: "灵胎壁破壁者", color: "B", cost: 300, desc: "你成功打破了灵胎壁，灵气运行效率比常人高出数倍，修炼速度大幅提升。", type: "exclusive"},
                    {name: "古神血脉(稀薄)", color: "A", cost: 1200, desc: "你体内流淌着一丝微弱的古神血液，天生神力，肉身防御力极强，但容易招来天劫。", type: "exclusive"},
                    {name: "剑丸掌控", color: "B", cost: 500, desc: "你懂得如何操纵剑丸，使其化作漫天剑雨，虽然威力不如剑神，但清杂兵效率极高。", type: "exclusive"},
                    {name: "传送神通", color: "S", cost: 2100, desc: "你掌握了极其复杂的传送算学，只要给你足够的时间计算坐标，你可以传送到世界的任何角落（偶尔会卡在墙里）。", type: "exclusive"},
                    {name: "造化之术", color: "SS", cost: 7500, desc: "涉及生命本质的造化之道，你可以修复破碎的肉身，甚至改变物种的形态，是真正的大神通。", type: "exclusive"},
                    {name: "不易神通", color: "SS", cost: 9000, desc: "物质不易，精神不易。你的状态被恒定，受到的伤害会快速回溯，极难被彻底杀死。", type: "exclusive"}
                ]
            },
            {
                name: "342.从前有座灵剑山",
                desc: "末法时代的修仙界，九州大陆。这里没有苦大仇深，只有智商碾压和无下限的吐槽。王陆与王舞这对师徒，正在用他们独特的方式诠释什么是“专业冒险者”。",
                boss: "仙王夏宇, 堕仙, 苍澜",
                identities: [
                    { name: "王家村的陪读书童", items: "一包过期的辣条, 一本《升仙大会攻略(伪)》" },
                    { name: "灵剑派外门扫地僧", items: "一把扫不干净落叶的扫帚, 一个用来偷窥的望远镜" },
                    { name: "万仙盟的底层办事员", items: "一堆处理不完的文件, 一个刻着“忍”字的茶杯" },
                    { name: "军皇山的逃兵", items: "一把断刃的军刀, 一身染血的破甲" },
                    { name: "驭兽宗的铲屎官", items: "一把巨大的铲子, 一身洗不掉的异味" }
                ],
                talents: [
                    {name: "空灵根(绝世)", color: "SSS", cost: 40000, desc: "修仙界最顶级的灵根，也是最废柴的灵根。灵气亲和度满级，但存不住灵气。除非你有《无相功》，否则只能当个吉祥物。", type: "exclusive"},
                    {name: "智商碾压", color: "SS", cost: 6000, desc: "你的智力超群，逻辑思维能力爆表。在面对修仙界的各种谜题和陷阱时，你能像看弱智一样看穿它们。", type: "exclusive"},
                    {name: "无相剑骨(雏形)", color: "SS", cost: 7000, desc: "虽然还没练成无相剑骨，但你的骨骼惊奇，抗击打能力极强，脸皮厚度也随之增加，防御力点满。", type: "exclusive"},
                    {name: "专业冒险者", color: "A", cost: 800, desc: "你熟读《冒险者手册》，对于如何卡BUG、利用规则漏洞、搜刮NPC财产有着深刻的理解。", type: "exclusive"},
                    {name: "知性(吐槽)", color: "C", cost: 100, desc: "你拥有敏锐的槽点捕捉能力，每一句吐槽都能直击灵魂，偶尔能对敌人造成精神暴击。", type: "exclusive"},
                    {name: "星辰剑典(残篇)", color: "S", cost: 2500, desc: "引动星辰之力的强大剑法，虽然只有残篇，但威力依然惊人，尤其是在夜晚战斗时。", type: "exclusive"},
                    {name: "九州地理通", color: "B", cost: 300, desc: "你熟知九州大陆的地理风貌，知道哪里有隐藏副本，哪里是绝对禁区，生存率大幅提升。", type: "exclusive"},
                    {name: "厨艺(灵食)", color: "A", cost: 600, desc: "你能将普通的食材烹饪成带有灵气的灵食，虽然味道可能很奇怪（比如仰望星空派），但效果拔群。", type: "exclusive"},
                    {name: "学霸光环", color: "B", cost: 450, desc: "在学习新的法术和功法时，你的领悟速度是常人的两倍，考试永远是满分（如果修仙界有考试的话）。", type: "exclusive"},
                    {name: "桃花运(劫)", color: "D", cost: 50, desc: "你很有异性缘，但往往伴随着修罗场和柴刀结局，请谨慎处理你的人际关系。", type: "exclusive"},
                    {name: "剑灵亲和", color: "A", cost: 900, desc: "你天生容易获得剑灵的好感，哪怕是一把生锈的铁剑，也愿意为你展现出最强的一面。", type: "exclusive"},
                    {name: "混沌体质", color: "S", cost: 3000, desc: "你的体质特殊，可以兼容多种属性的灵气，虽然修炼速度慢，但上限极高，不容易走火入魔。", type: "exclusive"},
                    {name: "金手指(伪)", color: "C", cost: 200, desc: "你总觉得自己是主角，随身带着“老爷爷”，其实那只是你精神分裂产生的幻听。", type: "exclusive"},
                    {name: "算盘精", color: "B", cost: 350, desc: "你对灵石极其敏感，做生意从不亏本，能从最吝啬的掌门手里抠出经费。", type: "exclusive"},
                    {name: "先天剑气", color: "S", cost: 2800, desc: "你体内孕育着一道先天剑气，关键时刻可以释放出来，威力足以秒杀同阶敌人。", type: "exclusive"}
                ]
            },
            {
                name: "343.修真聊天群",
                desc: "现代都市背景下的修真故事。误入“九州一号群”的宋书航，在各位前辈的关爱（迫害）下，开启了飙车、渡劫、手扶拖拉机大赛的奇幻人生。",
                boss: "胖球大佬(九幽主宰), 儒家圣人(执念), 天道白",
                identities: [
                    { name: "江南大学的普通学生", items: "一部电量永远不足的手机, 一本《五年高考三年模拟》" },
                    { name: "不知名门派的弃徒", items: "一把断裂的桃木剑, 一本发黄的《基础炼气决》" },
                    { name: "送快递的修士", items: "一辆改装过的电动车, 一箱未送达的灵石包裹" },
                    { name: "误食丹药的普通人", items: "一张医院的洗胃单, 身体里乱窜的热流" },
                    { name: "九州一号群的潜水员", items: "一个等级很低的QQ号, 满屏幕的“前辈666”" }
                ],
                talents: [
                    {name: "松鼠航的体质", color: "SS", cost: 6500, desc: "一种神奇的体质，虽然总是遇到各种危险和大佬的“关爱”，但总能化险为夷，并且升级速度快得不讲道理。", type: "exclusive"},
                    {name: "一次性飞剑(版004)", color: "B", cost: 400, desc: "白前辈出品的简易飞剑，速度极快但是一次性的，且刹车系统经常失灵，使用前请写好遗书。", type: "exclusive"},
                    {name: "圣光啊(物理)", color: "A", cost: 900, desc: "你学会了西方修炼体系的圣光术，但不知为何你的圣光带有极强的物理打击感，能把人砸晕。", type: "exclusive"},
                    {name: "手扶拖拉机驾驶证", color: "C", cost: 120, desc: "你精通手扶拖拉机的驾驶技术，甚至能在手扶拖拉机大赛中跑出音爆，是飙车党的新星。", type: "exclusive"},
                    {name: "鉴定术(修聊版)", color: "S", cost: 3000, desc: "付出惨痛的代价（通常是流血）来鉴定物品或生物的信息。代价越大，获得的信息越详细。", type: "exclusive"},
                    {name: "功德蛇美人(幼体)", color: "SS", cost: 8000, desc: "你的功德之力具象化为一条蛇美人，她能帮你防御、翻译古文，甚至在你讲冷笑话时负责捧哏。", type: "exclusive"},
                    {name: "核心世界(种子)", color: "SSS", cost: 35000, desc: "你体内拥有一个独立的小世界雏形，可以种植灵药、存放物品，甚至在危急时刻躲进去避难。", type: "exclusive"},
                    {name: "三十三兽先天一气功", color: "S", cost: 2600, desc: "一套完整的修真功法，能模拟三十三种灵兽的特性，打下无比坚实的道基，附带伪装妖兽的能力。", type: "exclusive"},
                    {name: "儒家金刚身", color: "A", cost: 1000, desc: "儒家的高深炼体功法，让你的身体如金刚般坚硬，同时散发着浩然正气，对邪祟有克制作用。", type: "exclusive"},
                    {name: "怀孕凝视(体验版)", color: "S", cost: 2200, desc: "儒家圣人的绝学（被玩坏版），瞪谁谁怀孕（体验分娩之痛），无论男女老少，是控制敌人的神技。", type: "exclusive"},
                    {name: "天劫亲和度(负)", color: "D", cost: 80, desc: "天劫似乎特别喜欢你，每次渡劫都会变异成现代化武器或者组团来袭，请自求多福。", type: "exclusive"},
                    {name: "白前辈的好运(蹭)", color: "SS", cost: 9000, desc: "你只要待在气运之子身边，就能蹭到惊人的好运，走路捡宝不是梦，但也要承担相应的风险（平地摔）。", type: "exclusive"},
                    {name: "寸头术", color: "C", cost: 50, desc: "你掌握了给任何人剃寸头的技术，速度极快，是得罪人的好手段。", type: "exclusive"},
                    {name: "真实的幻象", color: "S", cost: 2400, desc: "你能将幻象具现化，虽然只有一瞬间，但足以欺骗敌人的感官，甚至造成真实的伤害。", type: "exclusive"},
                    {name: "九幽灵力", color: "A", cost: 1100, desc: "你可以吸收和使用九幽世界的混乱灵力，但这会侵蚀你的理智，使用需谨慎。", type: "exclusive"}
                ]
            },
            {
                name: "344.无限恐怖",
                desc: "想明白生命的意义吗？想真正的……活着吗？郑查进入主神空间，在生化危机、异形、咒怨等恐怖片世界中轮回，开启基因锁，挑战恶魔队，探寻主神的真相。",
                boss: "复制体郑查, 楚轩(入魔), 主神(核心程序)",
                identities: [
                    { name: "刚进入主神空间的白领", items: "一套不合身的西装, 一张过期的信用卡" },
                    { name: "资深者的造人(肉盾)", items: "一身廉价的防弹衣, 一把没有子弹的冲锋枪" },
                    { name: "被放弃的炮灰新人", items: "一块发霉的面包, 极度恐惧的眼神" },
                    { name: "精神病院的逃跑患者", items: "一件束缚衣, 一把偷来的手术刀" },
                    { name: "退役的特种兵", items: "一把磨损的军刺, 创伤后应激障碍(PTSD)" }
                ],
                talents: [
                    {name: "基因锁(一阶)", color: "A", cost: 1500, desc: "恢复远古人类的战斗本能。开启时极度冷静，能感知危险，身体掌控力大幅提升，但结束后会极其虚弱。", type: "exclusive"},
                    {name: "基因锁(二阶)", color: "S", cost: 3500, desc: "解放身体潜能，能够自由控制肌肉、神经和内分泌。力量和反应速度暴增，但对身体负担极大。", type: "exclusive"},
                    {name: "基因锁(三阶)", color: "S", cost: 5500, desc: "开发脑域，模拟他人的思维方式。你可以模拟智者的布局，或者模拟强者的战斗技巧，但容易迷失自我。", type: "exclusive"},
                    {name: "基因锁(四阶初)", color: "SS", cost: 9000, desc: "微观控制，入微之境。你可以控制每一个细胞，重组基因，修复致命伤，甚至在战斗中进化。", type: "exclusive"},
                    {name: "内力(混元)", color: "B", cost: 500, desc: "中正平和的内家真气，能够强化身体素质，作为驱动轻功和武技的基础能量，兼容性好。", type: "exclusive"},
                    {name: "血族血统(男爵)", color: "B", cost: 600, desc: "拥有吸血鬼的基础能力，恢复力增强，寿命延长，可以使用血能攻击，但惧怕阳光和银器。", type: "exclusive"},
                    {name: "念动力(初级)", color: "A", cost: 1200, desc: "用精神力干涉物质世界。目前只能移动小物体或形成念力护盾，随着精神力增强，威力无上限。", type: "exclusive"},
                    {name: "蜘蛛侠变异", color: "B", cost: 800, desc: "被变异蜘蛛咬伤后获得的能力。拥有蜘蛛感应、爬墙能力和超强力量，还能发射蛛丝。", type: "exclusive"},
                    {name: "T病毒强化", color: "C", cost: 300, desc: "经过T病毒改造但未丧尸化。痛觉削弱，力量和耐力提升，对病毒有一定抗性，但皮肤变得苍白。", type: "exclusive"},
                    {name: "纳戒(仿)", color: "C", cost: 200, desc: "主神出品的空间存储道具，只有一立方米的空间，但对于轮回者来说，能装下弹药和食物就是救命的。", type: "exclusive"},
                    {name: "审判之矛(碎片)", color: "S", cost: 2800, desc: "传说中神器的碎片，投掷后必定命中目标，并造成巨大的灵类伤害，对鬼怪类敌人有奇效。", type: "exclusive"},
                    {name: "虎魄刀(封印)", color: "SS", cost: 7500, desc: "上古魔神蚩尤的佩刀，煞气冲天。每一刀都能劈开空气，甚至吞噬使用者的灵魂，需要极强的意志力驾驭。", type: "exclusive"},
                    {name: "精灵射手血统", color: "A", cost: 1000, desc: "拥有精灵族的优雅和敏捷，视力极佳，弓箭专精。附带自然亲和，在森林环境中战斗力翻倍。", type: "exclusive"},
                    {name: "扎古驾驶技术", color: "C", cost: 150, desc: "你学会了驾驶机动战士高达中的扎古，虽然主神空间里不一定有高达给你开，但机械操控力通用。", type: "exclusive"},
                    {name: "重生十字章", color: "S", cost: 3000, desc: "一次性的保命道具。佩戴者在任务世界死亡后，可以原地满状态复活一次，相当于多了一条命。", type: "exclusive"}
                ]
            },
            {
                name: "345.惊悚乐园",
                desc: "这不仅仅是游戏，这是一场关于恐惧的试炼。封不觉在神经连接游戏《惊悚乐园》中，以失去恐惧的“觉哥”之名，探索数据维度的秘密，挑战神魔的赌局。",
                boss: "伍迪, 衍生者(红), 系统(主脑)",
                identities: [
                    { name: "失去恐惧感的玩家", items: "一件初始的病号服, 一个永远显示为0的惊吓值" },
                    { name: "工作室的职业打金员", items: "一把磨损的矿镐, 一背包的低级材料" },
                    { name: "追求刺激的休闲玩家", items: "一身花里胡哨的时装, 一个用来拍照的相机" },
                    { name: "被数据侵蚀的NPC", items: "一段错乱的代码, 一个重复发布的任务" },
                    { name: "地狱前线的粉丝", items: "一张觉哥的签名照, 一本《侦探小说全集》" }
                ],
                talents: [
                    {name: "惊吓值清零", color: "SSS", cost: 20000, desc: "你失去了恐惧这种情绪。在任何恐怖场景下，你的心跳都不会加速，这让你能保持绝对冷静，但也少了预警机制。", type: "exclusive"},
                    {name: "灵识(侦查)", color: "A", cost: 1000, desc: "你开启了灵识专精，能够看到数据流、鬼魂以及隐藏的线索。你的侦查能力远超常人，能发现剧本的破绽。", type: "exclusive"},
                    {name: "召唤精通", color: "S", cost: 2200, desc: "你擅长召唤系技能，能召唤出各种奇怪的生物为你战斗（比如那只贱贱的猫），虽然它们不一定听话。", type: "exclusive"},
                    {name: "格斗专精(E级)", color: "C", cost: 150, desc: "基础的格斗技巧，让你在没有武器时也能用拳头解决问题。动作标准，但缺乏实战经验。", type: "exclusive"},
                    {name: "射击专精(B级)", color: "B", cost: 600, desc: "你对枪械有天生的手感，无论是手枪还是狙击枪，在你手中都能指哪打哪，换弹速度极快。", type: "exclusive"},
                    {name: "医疗专精(C级)", color: "C", cost: 300, desc: "你懂得基础的急救知识，能快速处理伤口，使用回血道具的效果提升，是团队中的奶妈预备役。", type: "exclusive"},
                    {name: "器械专精(A级)", color: "A", cost: 1200, desc: "只要是机械构造的物品，你都能快速上手。拆弹、开锁、驾驶载具样样精通，甚至能临时拼装武器。", type: "exclusive"},
                    {name: "诡辩", color: "B", cost: 400, desc: "你的口才极佳，擅长忽悠NPC，甚至能说服BOSS放你一马。逻辑鬼才，能把黑的说成白的。", type: "exclusive"},
                    {name: "数据视角", color: "SS", cost: 8000, desc: "你能看到世界的底层代码。墙壁不再是墙壁，而是0和1的集合。你可以利用这一点穿墙或修改物品属性（极耗体能）。", type: "exclusive"},
                    {name: "死亡扑克", color: "S", cost: 2500, desc: "你拥有一套带有特殊效果的扑克牌，每一张牌都能化作利刃或炸弹，且用完自动回收。", type: "exclusive"},
                    {name: "魂意(觉醒)", color: "SS", cost: 7000, desc: "你的意志具象化为特殊能量，根据你的性格形成独特的战斗风格。这是强者与弱者的分水岭。", type: "exclusive"},
                    {name: "管钳(神器)", color: "B", cost: 500, desc: "一把看似普通的管钳，但在你手中是物理学圣剑。敲击头部有几率造成眩晕，且永不磨损。", type: "exclusive"},
                    {name: "阿斯克勒庇俄斯之杖", color: "S", cost: 3000, desc: "传说中的医神之杖，拥有强大的治疗能力，甚至能复活刚死不久的队友，但冷却时间极长。", type: "exclusive"},
                    {name: "SCP基金会收容物", color: "A", cost: 1500, desc: "你随机携带一件安全级的SCP物品，效果未知且奇特（比如无限披萨盒），使用得当能逆转局势。", type: "exclusive"},
                    {name: "吐槽能量", color: "D", cost: 100, desc: "你的吐槽能转化为微弱的能量，用来点亮手电筒或者给手机充电，聊胜于无。", type: "exclusive"}
                ]
            },
            {
                name: "346.我在修仙界长生不死",
                desc: "修仙界太危险，只有苟才是王道。方夕拥有“长生道果”，寿命无限，但他从不浪。打不过就跑，跑不过就躲到下界，熬死敌人再去坟头蹦迪。",
                boss: "妖族大圣, 化神老怪, 天道(残缺)",
                identities: [
                    { name: "长生不死的凡人", items: "一张看不出岁月的脸庞, 一本记录仇人的小本本" },
                    { name: "修仙家族的边缘旁支", items: "一块劣质的身份玉牌, 几颗下品灵石" },
                    { name: "坊市里的灵农", items: "一把灵锄, 一袋低级灵米种子" },
                    { name: "躲在凡间的武林盟主", items: "一本凡俗武功秘籍, 一把削铁如泥的宝剑" },
                    { name: "穿越两界的倒爷", items: "一个装满修仙特产的储物袋, 一些现代工艺品" },
                ],
                talents: [
                    {name: "长生道果(伪)", color: "SSS", cost: 50000, desc: "你拥有无限的寿命，岁月无法在你身上留下痕迹。只要不被杀，你就能活到天荒地老。这是苟道的基石。", type: "exclusive"},
                    {name: "枯荣诀", color: "S", cost: 3000, desc: "一门极其适合种田和养生的功法。能控制草木枯荣，催熟灵药，且气息内敛，极难被看穿修为。", type: "exclusive"},
                    {name: "两界穿梭", color: "SS", cost: 9000, desc: "你可以在两个不同的世界（如修仙界和凡俗界）之间自由穿梭。打不过就换个世界躲起来，降维打击。", type: "exclusive"},
                    {name: "苟道中人", color: "B", cost: 500, desc: "你行事极其谨慎，从不立于危墙之下。凡事谋定而后动，习惯留亿手底牌，生存率极高。", type: "exclusive"},
                    {name: "易容术(宗师)", color: "A", cost: 1200, desc: "你的易容术出神入化，不仅能改变容貌，还能改变骨骼和气息，连神识都难以分辨真假。", type: "exclusive"},
                    {name: "灵植夫天赋", color: "B", cost: 600, desc: "你对种植灵药有着独到的天赋，种出的灵药品质极高，是赚取灵石、积累资源的最佳手段。", type: "exclusive"},
                    {name: "阵法宗师", color: "S", cost: 2800, desc: "你精通各种防御和困杀阵法。你的洞府被布置得固若金汤，连只苍蝇都飞不进去。", type: "exclusive"},
                    {name: "傀儡术", color: "A", cost: 1500, desc: "你擅长制作和操控傀儡。战斗时让傀儡先上，自己在后面放冷枪，安全系数满满。", type: "exclusive"},
                    {name: "敛息术(圆满)", color: "A", cost: 1000, desc: "你可以完美收敛全身气息，把自己伪装成一块石头或者一棵树，是躲避追杀的神技。", type: "exclusive"},
                    {name: "制符大师", color: "B", cost: 700, desc: "你绘制符箓的成功率极高。战斗时直接扔出一大把符箓，用钱砸死对手。", type: "exclusive"},
                    {name: "妖魔树种", color: "S", cost: 2500, desc: "你种下了一颗妖魔树，它可以吞噬血肉成长，为你提供强大的生命力和木系神通。", type: "exclusive"},
                    {name: "时间掌控(微弱)", color: "SS", cost: 7500, desc: "你对时间法则有一丝感悟，能让周围的时间流速短暂变慢，高手过招，这一瞬就是生死。", type: "exclusive"},
                    {name: "凡俗武道巅峰", color: "C", cost: 200, desc: "在灵气稀薄的地方，你的武道修为足以横扫千军，是前期保命的重要手段。", type: "exclusive"},
                    {name: "仇恨转移", color: "B", cost: 400, desc: "你擅长祸水东引，在惹了麻烦后能迅速把锅甩给别人，自己置身事外。", type: "exclusive"},
                    {name: "耐得住寂寞", color: "C", cost: 100, desc: "你可以闭关修炼几十年不出门，心态平稳，不会因为无聊而走火入魔。", type: "exclusive"}
                ]
            },
            {
                name: "347.道诡异仙",
                desc: "别信！别信！这里是疯子的世界。李火旺分不清现实与幻觉，心素的身份让他成为唐僧肉。坐忘道在狂笑，监天司在吃人，骰子落地，是生是死？",
                boss: "巴虺, 坐忘道(红中), 司命",
                identities: [
                    { name: "清风观的药引", items: "一身满是血污的道袍, 几颗黑乎乎的丹药" },
                    { name: "精神病院的重症患者", items: "一瓶抗精神病药物, 束缚带" },
                    { name: "监天司的替补百户", items: "一把绣春刀, 一块刻着“监”字的腰牌" },
                    { name: "正德寺的和尚", items: "一串人骨念珠, 一本看不懂的经书" },
                    { name: "坐忘道的骗子", items: "一张红中麻将牌, 一张千人千面" }
                ],
                talents: [
                    {name: "心素(迷惘)", color: "SSS", cost: 45000, desc: "你是连接真假世界的桥梁。你的血肉能让人成仙（变成怪物），你的幻觉能干涉现实。你分不清什么是真，什么是假。", type: "exclusive"},
                    {name: "大千录", color: "SS", cost: 8500, desc: "一本邪门的功法，通过自残来换取力量。献祭自己的痛苦、器官甚至寿命，召唤不可名状的存在降临。", type: "exclusive"},
                    {name: "苍蜣登阶", color: "S", cost: 3500, desc: "通过极度的痛苦来提升境界。你越痛苦，力量越强。这是一种求死不能的修炼方式。", type: "exclusive"},
                    {name: "坐忘道(耍)", color: "A", cost: 1500, desc: "你信奉“真作假时假亦真”。你擅长欺骗，不仅骗人，连天道都骗。只要有人信，谎言就能成真。", type: "exclusive"},
                    {name: "红中老大", color: "S", cost: 3000, desc: "你获得了坐忘道红中的传承，拥有极高的幻术造诣和混乱的思维，能在混乱中寻找生机。", type: "exclusive"},
                    {name: "丹阳子(附身)", color: "SS", cost: 7000, desc: "你的身体里住着一个成仙（成煞）的老道士。他会不断在你耳边絮叨，教你邪法，但也可能夺舍你。", type: "exclusive"},
                    {name: "游老爷", color: "B", cost: 600, desc: "你能召唤游老爷助战，这些不可见的诡异生物喜食血肉，虽然强大，但容易反噬主人。", type: "exclusive"},
                    {name: "袄景教火法", color: "A", cost: 1200, desc: "通过燃烧自己的皮肤和血肉来释放火焰。威力巨大，但对自己也是一种酷刑。", type: "exclusive"},
                    {name: "精神分裂", color: "C", cost: 100, desc: "你拥有多重人格，这让你对精神攻击有极高的抗性，但也让你经常对着空气自言自语。", type: "exclusive"},
                    {name: "现代知识(幻)", color: "B", cost: 400, desc: "你拥有现代世界的记忆，但在诡异世界里，这些知识可能变成某种扭曲的神通或诅咒。", type: "exclusive"},
                    {name: "监天司刑具", color: "B", cost: 500, desc: "你精通各种刑具的使用，能给敌人带来极致的痛苦，从而削弱他们的意志。", type: "exclusive"},
                    {name: "黑太岁", color: "S", cost: 2800, desc: "你融合了黑太岁，拥有极强的再生能力，断肢重生是小儿科，但身体会长出奇怪的触手。", type: "exclusive"},
                    {name: "骰子(命运)", color: "SS", cost: 8000, desc: "一颗决定命运的骰子。投出大点数，万事如意；投出小点数，万劫不复。这是赌徒的终极手段。", type: "exclusive"},
                    {name: "李火旺的同情", color: "D", cost: 50, desc: "你引起了李火旺的注意，这通常意味着你离死不远了，或者会卷入更大的麻烦。", type: "exclusive"},
                    {name: "易牙烹饪术", color: "A", cost: 900, desc: "一种邪恶的烹饪术，以人为材，做出的菜肴能增加修为，但会丧失人性。", type: "exclusive"}
                ]
            },
            {
                name: "348.万族之劫",
                desc: "诸天万族亡我人族之心不死！苏宇从梦境中醒来，为了守护父亲和人族，修神文，开窍穴，化身万族收割机，在诸天战场杀出一片朗朗乾坤。",
                boss: "万族皇者, 时光之主, 死灵帝君",
                identities: [
                    { name: "大夏文明学府的新生", items: "一本《万族语基础》, 一枚初级神文" },
                    { name: "诸天战场的炮灰兵", items: "一把制式长刀, 一块染血的军牌" },
                    { name: "柳城的小居民", items: "一个安稳的家, 对万族的仇恨" },
                    { name: "多神文系的传人", items: "被压制的意志力, 老师的嘱托" },
                    { name: "猎天阁的白面具", items: "一张遮掩气息的面具, 各种情报卷轴" }
                ],
                talents: [
                    {name: "时光册(仿)", color: "SSS", cost: 40000, desc: "能够吞噬万族精血，开启对应种族的图鉴，获得该种族的天赋技。这是万族之劫的根源，也是最强的外挂。", type: "exclusive"},
                    {name: "多神文一道", color: "SS", cost: 8000, desc: "你可以勾勒多枚神文，并将其组合成战技。神文越多，战力越强，但对意志力要求极高。", type: "exclusive"},
                    {name: "开窍狂魔", color: "S", cost: 3000, desc: "你的身体窍穴极易开启。别人开几个窍就是天才，你开几百个窍组成大阵，肉身成圣。", type: "exclusive"},
                    {name: "扩神锤", color: "A", cost: 1500, desc: "专门锤炼意志力的功法。虽然过程极其痛苦，脑袋像要炸开一样，但能快速提升精神力上限。", type: "exclusive"},
                    {name: "万族语精通", color: "B", cost: 500, desc: "你精通诸天万族的语言，能听懂敌人的战术安排，甚至用语言激怒对方，引发神文共鸣。", type: "exclusive"},
                    {name: "死灵亲和", color: "S", cost: 2500, desc: "你可以在死灵界自由行走，死气对你的侵蚀减半。甚至能召唤死灵君主为你作战。", type: "exclusive"},
                    {name: "合窍法", color: "SS", cost: 7000, desc: "将多个窍穴合二为一，爆发力倍增。这是通往无敌强者的必经之路。", type: "exclusive"},
                    {name: "文明师天赋", color: "A", cost: 1200, desc: "你对神文的感悟力极强，能快速勾勒出“杀”、“血”、“雷”等强力攻击神文。", type: "exclusive"},
                    {name: "噬魂诀", color: "S", cost: 2200, desc: "通过吞噬敌人的灵魂碎片来壮大自己的意志力，虽然有精神分裂的风险，但成长速度极快。", type: "exclusive"},
                    {name: "铸兵师", color: "B", cost: 800, desc: "你擅长铸造兵器，能将神文融入兵器中，打造出拥有特殊能力的文兵。", type: "exclusive"},
                    {name: "食铁兽血脉", color: "A", cost: 1000, desc: "你拥有食铁兽的血脉，防御力惊人，可以通过吞噬金属来强化肉身，还能变身萌物卖萌。", type: "exclusive"},
                    {name: "天渊诅咒", color: "D", cost: 100, desc: "你身上带有天渊族的诅咒，运气变差，容易遭到意外攻击，但也让你对诅咒类法术有抗性。", type: "exclusive"},
                    {name: "阳窍开启", color: "S", cost: 2800, desc: "你开启了特殊的阳窍，生命力极其旺盛，恢复速度是常人的十倍，简直是打不死的小强。", type: "exclusive"},
                    {name: "诈骗大师", color: "B", cost: 400, desc: "你擅长伪装身份，今天你是仙族，明天你是魔族。在万族之间左右逢源，坑蒙拐骗。", type: "exclusive"},
                    {name: "人主印(碎)", color: "SS", cost: 9000, desc: "拥有人主大印的一块碎片，能镇压气运，对人族有天然的压制力和号召力。", type: "exclusive"}
                ]
            },
            {
                name: "349.全球高武",
                desc: "地窟入侵，武道崛起。方平重生，带着财富转化气血的系统，从阳城走出。为了守护家人和地球，他下地窟，炸王庭，平定三界动乱。",
                boss: "地窟真王, 天帝, 种子",
                identities: [
                    { name: "阳城一中的高三学生", items: "一张武科报名表, 几颗气血丹" },
                    { name: "魔武的刺头新生", items: "一把合金长刀, 一张欠条" },
                    { name: "地窟守夜人", items: "一身破损的作战服, 一枚勋章" },
                    { name: "邪教的潜伏者", items: "一本洗脑手册, 一瓶毒药" },
                    { name: "京武的精英学员", items: "一把长枪, 傲气凌人的眼神" }
                ],
                talents: [
                    {name: "财富系统(系统)", color: "SSS", cost: 50000, desc: "只要有钱（资源），就能无限转化气血和精神力。这是最简单粗暴的挂，氪金就能变强！", type: "exclusive"},
                    {name: "三次淬骨", color: "S", cost: 3000, desc: "在非武者阶段完成三次淬骨，基础气血远超常人，同阶无敌，是成为宗师的潜力股。", type: "exclusive"},
                    {name: "精神力具现", color: "SS", cost: 8000, desc: "你的精神力极其强大，可以具现出房屋、武器甚至小世界。精神不灭，肉身不死。", type: "exclusive"},
                    {name: "金骨", color: "S", cost: 3500, desc: "全身骨骼淬炼成金色，坚不可摧。八品金身强者的标志，能硬抗热武器轰炸。", type: "exclusive"},
                    {name: "平乱刀法", color: "A", cost: 1200, desc: "方平自创的刀法，讲究一往无前，爆发力极强。一刀劈出，气血如龙，专斩地窟武者。", type: "exclusive"},
                    {name: "地窟语", color: "C", cost: 100, desc: "你精通地窟语言，能伪装成地窟人类，混入敌方城池刺探情报或搞破坏。", type: "exclusive"},
                    {name: "不灭物质", color: "SS", cost: 7500, desc: "高品武者才能诞生的能量，能瞬间修复肉身损伤。只要还有一口气，就能瞬间满血复活。", type: "exclusive"},
                    {name: "能源石亲和", color: "B", cost: 500, desc: "你对高纯度能源石有特殊的感应，在地窟中挖矿效率极高，是发家致富的好手。", type: "exclusive"},
                    {name: "御空飞行", color: "A", cost: 1000, desc: "七品宗师的标志能力。摆脱地心引力，翱翔天际，机动性大幅提升。", type: "exclusive"},
                    {name: "本源道", color: "SS", cost: 9000, desc: "踏入本源道，你的武道之路更加宽广。每走一步，实力都会翻倍增长，但也伴随着迷失的风险。", type: "exclusive"},
                    {name: "忽悠神技", color: "B", cost: 400, desc: "继承了方平的忽悠能力，能在战场上动摇敌人军心，甚至把敌人忽悠瘸了。", type: "exclusive"},
                    {name: "炸矿狂魔", color: "A", cost: 1500, desc: "你擅长引爆地窟的能源矿脉，制造惊天大爆炸，与敌人同归于尽（如果你跑得快的话）。", type: "exclusive"},
                    {name: "收敛气息", color: "B", cost: 600, desc: "你可以将气血波动完全收敛，伪装成普通人，是扮猪吃虎的必备技能。", type: "exclusive"},
                    {name: "猫的挂件", color: "S", cost: 2800, desc: "你获得了苍猫的好感，能借用它的神器（如钓鱼竿、锅），还能蹭到各种天材地宝。", type: "exclusive"},
                    {name: "复生武者", color: "S", cost: 2200, desc: "你是上古强者的转世身，觉醒后拥有前世的战斗经验和功法，修炼速度极快。", type: "exclusive"}
                ]
            },
            {
                name: "350.深空彼岸",
                desc: "旧术已死，新术当立？王煊不信邪。在科技与神话交织的时代，他修炼旧术，走进内景地，在现世与仙界的缝隙中，寻找列仙回归的真相。",
                boss: "红衣女妖仙, 郑元天, 真实之地主宰",
                identities: [
                    { name: "旧术实验班的学生", items: "一本泛黄的《金刚功》, 几颗养生丸" },
                    { name: "新术财阀的保镖", items: "一支基因药剂, 一套外骨骼装甲" },
                    { name: "探险队的幸存者", items: "一块奇异的陨石碎片, 一把激光手枪" },
                    { name: "内景地的误入者", items: "精神力残留的幻象, 对现实的疏离感" },
                    { name: "从大幕后归来的真仙残魂", items: "破碎的元神, 想要夺舍的欲望" }
                ],
                talents: [
                    {name: "精神领域(内景地)", color: "SSS", cost: 48000, desc: "你可以主动开启内景地，这里时间流速极慢，灵气充沛。在里面修炼一年，外面只过一瞬，是作弊级的修炼场所。", type: "exclusive"},
                    {name: "金刚功(圆满)", color: "S", cost: 3000, desc: "道教护法神功，修炼到圆满境界，肉身金刚不坏，气血如汞浆，能硬抗飞剑和子弹。", type: "exclusive"},
                    {name: "第一杀阵(图)", color: "SS", cost: 8500, desc: "上古第一杀阵的阵图，虽然残缺，但一旦布置出来，连真仙都能绞杀，杀气冲霄。", type: "exclusive"},
                    {name: "斩神旗", color: "SS", cost: 7000, desc: "专斩元神的金色小旗。对付灵体和精神攻击有奇效，一摇之下，神魂俱灭。", type: "exclusive"},
                    {name: "养生主", color: "A", cost: 1500, desc: "一种高深的养生秘术，能调理身体，修复暗伤，延年益寿，是修炼旧术的基础。", type: "exclusive"},
                    {name: "陨石异力", color: "B", cost: 800, desc: "你接触过神秘陨石，体内拥有特殊的异力（如雷电、火焰），能配合武道施展出超凡攻击。", type: "exclusive"},
                    {name: "钓鱼佬(因果)", color: "S", cost: 2500, desc: "你继承了王煊的钓鱼技巧，能从大幕后的仙界“钓”出宝物甚至仙人，但小心钓出大恐怖。", type: "exclusive"},
                    {name: "精神出窍", color: "A", cost: 1200, desc: "你的精神可以脱离肉体，夜游千里。在精神层面战斗力极强，无视物理防御。", type: "exclusive"},
                    {name: "炉火纯青的新术", color: "B", cost: 600, desc: "你接受过顶级的新术改造，基因完美，身体素质极强，且没有旧术的瓶颈。", type: "exclusive"},
                    {name: "地仙泉水", color: "S", cost: 2000, desc: "你随身带有一瓶地仙泉水，喝一口就能恢复全部灵力和体力，是持久战的保障。", type: "exclusive"},
                    {name: "剑仙胚子", color: "A", cost: 1000, desc: "你对剑道有超乎寻常的领悟力，能驾驭飞剑千里取人头，剑气纵横。", type: "exclusive"},
                    {name: "大幕后的注视", color: "D", cost: 100, desc: "你被列仙盯上了，他们渴望回归现世，可能会试图夺舍你，或者通过你干涉现实。", type: "exclusive"},
                    {name: "混元之体", color: "SS", cost: 8000, desc: "肉身与精神完美融合，无漏无缺。对各种能量的抗性极高，是成仙作祖的好苗子。", type: "exclusive"},
                    {name: "旧术宗师指导", color: "B", cost: 500, desc: "你曾得到过旧术宗师的指点，少走了很多弯路，基础极其扎实。", type: "exclusive"},
                    {name: "现世纠错", color: "S", cost: 2800, desc: "你掌握了对抗现世规则压制的方法，能在超凡退潮的时代，依然保持强大的战力。", type: "exclusive"}
                ]
            },
              {
        name: "351.灵山",
        desc: "一个充满绝望与阴谋的西游后传世界。诸佛消失，妖魔横行，灵山脚下白骨累累。这不是你熟悉的西游，而是关于‘道’与‘魔’的残酷辩证。",
        boss: "无天佛祖, 燃灯古佛(圆寂态), 孙悟空(舍利姿态)",
        identities: [
            { name: "狮驼岭脚下的骷髅若", items: "一截不知名的大腿骨, 一块遮羞的破布" },
            { name: "祭赛国被挖心的士兵", items: "锈迹斑斑的长矛, 还在滴血的空胸膛" },
            { name: "灵山脚下的扫地僧", items: "一把秃了毛的扫帚, 一本被虫蛀的经书" },
            { name: "车迟国的落魄道士", items: "断裂的桃木剑, 几张画废的符纸" },
            { name: "女儿国的男性干尸", items: "干瘪的子母河水袋, 一缕枯黄的长发" }
        ],
        talents: [
            {name: "六耳猕猴血脉(残)", color: "SS", cost: 7500, desc: "善聆音，能察理，知前后，万物皆明。虽然血脉稀薄，但能看破大部分虚妄和伪装，甚至偷学对方技能。", type: "exclusive"},
            {name: "丈六金身(碎片)", color: "S", cost: 3200, desc: "佛门至高护体神功的残篇。发动时皮肤化为暗金色，大幅度豁免物理和法术伤害，但会消耗大量生命力。", type: "exclusive"},
            {name: "紧箍咒(控制器)", color: "A", cost: 900, desc: "你掌握了紧箍咒的念法，虽然不能控制孙悟空，但对精神力低于你的目标能造成剧烈头痛和控制效果。", type: "exclusive"},
            {name: "人种袋(仿品)", color: "S", cost: 2500, desc: "黄眉老祖法宝的低劣仿品。能将E级到C级的敌人强行吸入袋中困住一时三刻，内部化尸水腐蚀性极强。", type: "exclusive"},
            {name: "舍利子亲和", color: "SSS", cost: 18000, desc: "你是天生的万佛之祖候选人。对于散落在天地间的十七颗舍利子有着致命的吸引力，能借用舍利子的力量。", type: "exclusive"},
            {name: "九齿钉耙精通", color: "B", cost: 400, desc: "你对重型长柄武器有独特理解，挥舞时带有破甲效果，且在面对妖族时伤害有小幅加成。", type: "exclusive"},
            {name: "地煞七十二变(前三变)", color: "A", cost: 1200, desc: "学会了通幽、驱神、担山三术。虽然只是皮毛，但在生存和逃跑上有着奇效。", type: "exclusive"},
            {name: "避水诀", color: "C", cost: 150, desc: "基础法术，能在水下自由呼吸和行动，不会被水压挤死，是探索水下洞府的必备技能。", type: "exclusive"},
            {name: "锦襕袈裟(破损)", color: "B", cost: 550, desc: "曾经是唐僧的宝物，现在虽然破旧，但仍能辟火、防虫，且能微弱增加佩戴者的威严。", type: "exclusive"},
            {name: "白龙马的耐力", color: "C", cost: 180, desc: "你的耐力惊人，负重长途奔袭不知疲倦，且在受伤后恢复速度比常人快一倍。", type: "exclusive"},
            {name: "黑莲印记", color: "SS", cost: 8000, desc: "你被无天佛祖选中，额头带有黑莲印记。修习魔道功法速度加倍，但会被正道人士不死不休地追杀。", type: "exclusive"},
            {name: "谛听之耳", color: "S", cost: 2800, desc: "只要伏地听闻，便能知晓方圆百里内的风吹草动，甚至能听到人心的恶意。", type: "exclusive"},
            {name: "袖里乾坤(入门)", color: "S", cost: 3000, desc: "镇元大仙的绝技。你的袖子内藏一个小空间，可以收取物品或敌人的兵器，目前空间只有衣柜大小。", type: "exclusive"},
            {name: "定海神针铁屑", color: "A", cost: 850, desc: "你拥有一小撮金箍棒蹭下来的铁屑，将其融入武器中，可使武器重量暴增，且坚不可摧。", type: "exclusive"},
            {name: "无骨舍利(伪)", color: "SSS", cost: 35000, desc: "你本身就是一颗伪造的无骨舍利。在死亡时可以引发毁灭性的大爆炸，或者选择涅槃重生(每世界限一次)。", type: "exclusive"}
        ]
    },
    {
        name: "352.搜神记/蛮荒记",
        desc: "上古大荒，神魔共舞。三皇五帝，五族争霸。这是一个充满了山海经异兽、太古神功和原始野性的世界。力量至上，弱肉强食。",
        boss: "烛龙, 拓拔野, 蚩尤, 神农",
        identities: [
            { name: "蜃楼城的落魄难民", items: "一碗发霉的米饭, 一件破烂的麻衣" },
            { name: "东海流波山的采珠人", items: "一把劣质的骨刀, 一颗普通的珍珠" },
            { name: "昆仑山的采药童子", items: "一个小药锄, 满身洗不掉的药味" },
            { name: "南荒蛮族的奴隶", items: "沉重的石镣铐, 满背的鞭痕" },
            { name: "雷泽的独行猎手", items: "一张兽筋弓, 三支骨箭" }
        ],
        talents: [
            {name: "神农百草体", color: "SS", cost: 9000, desc: "尝百草而不死。你对所有毒素免疫，且能通过吞噬草药快速提升修为，血液具有极强的解毒和治疗功效。", type: "exclusive"},
            {name: "五行真气(火)", color: "A", cost: 1500, desc: "天生亲和火元素，修炼火属性功法事半功倍，攻击附带灼烧效果，不惧严寒。", type: "exclusive"},
            {name: "御兽诀(残)", color: "B", cost: 500, desc: "懂得与野兽沟通的技巧，能驯服E级到D级的野兽作为战斗伙伴，但对异兽无效。", type: "exclusive"},
            {name: "裂天兕之力", color: "S", cost: 3500, desc: "拥有上古凶兽裂天兕的一丝血脉。力大无穷，皮肤坚硬如铁，发狂时能撞碎山岩。", type: "exclusive"},
            {name: "种玉功(初层)", color: "S", cost: 2800, desc: "极为诡异的功法。能将他人作为炉鼎，种下玉种，吸取对方的精气神为己用，极其阴毒。", type: "exclusive"},
            {name: "刹那芳华", color: "SSS", cost: 25000, desc: "控制时间的禁术。能让局部时间加速或减缓，甚至让红颜瞬间白发。代价是消耗自己的寿命。", type: "exclusive"},
            {name: "补天石碎片", color: "SS", cost: 8500, desc: "女娲补天遗留的五彩石碎片。佩戴在身可大幅增加气运，且能缓慢修复受损的灵魂和根基。", type: "exclusive"},
            {name: "龙神血脉(觉醒)", color: "SSS", cost: 30000, desc: "你拥有纯正的龙神血脉。可化身为龙，呼风唤雨，统御水族，肉身成圣，是天地间的霸主。", type: "exclusive"},
            {name: "长生诀(木)", color: "A", cost: 1200, desc: "木族顶尖功法的基础篇。生命力极其顽强，只要头颅不碎，肢体断裂皆可再生。", type: "exclusive"},
            {name: "断浪刀法", color: "C", cost: 200, desc: "水族战士的基础刀法，在水中施展威力倍增，能借助水流之力卸掉敌人的劲力。", type: "exclusive"},
            {name: "千里眼(伪)", color: "B", cost: 450, desc: "你的视力极佳，能看清千米之外的蚊虫翅膀，是侦查和射箭的神技。", type: "exclusive"},
            {name: "赶山鞭", color: "S", cost: 3200, desc: "传说中的宝物。挥动时能改变地形，移山填海，制造地震，是对抗大规模军队的利器。", type: "exclusive"},
            {name: "九尾狐魅惑", color: "A", cost: 1000, desc: "青丘九尾狐的天赋。你的一颦一笑都带有天然的魅惑效果，意志不坚定者会甘愿为你赴死。", type: "exclusive"},
            {name: "息壤(一捧)", color: "SS", cost: 7800, desc: "生生不息的神土。这一捧土可以化为巨大的土墙防御，或者用来培育神级药草。", type: "exclusive"},
            {name: "无锋剑意", color: "A", cost: 1300, desc: "重剑无锋，大巧不工。你领悟了重剑的奥义，攻击不再依赖锋利，而是纯粹的力量压制。", type: "exclusive"}
        ]
    },
    {
        name: "353.昆仑",
        desc: "宋末元初，家国破碎。这是‘算’与‘术’的巅峰，数学与武学的完美结合。梁萧以算入道，演绎出一段波澜壮阔的江湖史诗。",
        boss: "梁萧, 萧千绝, 公羊羽, 九如",
        identities: [
            { name: "天机宫的扫地童子", items: "一把算盘, 一本入门算经" },
            { name: "蒙古军营的汉人马夫", items: "一根马鞭, 满身马粪味" },
            { name: "钱塘江边的弄潮儿", items: "一条短裤, 一身精悍的肌肉" },
            { name: "大宋皇宫的落魄画师", items: "一支秃笔, 几张沾墨的宣纸" },
            { name: "西域商队的骆驼客", items: "一个水囊, 一把弯刀" }
        ],
        talents: [
            {name: "周流六虚功(天元)", color: "SSS", cost: 28000, desc: "借用天地八种自然之力（天、地、山、泽、水、火、风、雷）。若能驾驭，便是陆地神仙；若失控，则爆体而亡。", type: "exclusive"},
            {name: "释厄剑气", color: "S", cost: 3500, desc: "公羊羽的绝学。将内力高度压缩后爆发，剑气如虹，无坚不摧，专破各类护体真气。", type: "exclusive"},
            {name: "天机算术", color: "SS", cost: 8000, desc: "你精通高等数学与天文地理。能通过计算预判敌人的招式轨迹，甚至推演阵法的生门所在。", type: "exclusive"},
            {name: "鲸息功", color: "A", cost: 1200, desc: "模仿鲸鱼呼吸的内功。回气速度极快，且能在水中闭气数个时辰，内力悠长深厚。", type: "exclusive"},
            {name: "碧微箭", color: "B", cost: 600, desc: "以指力弹出极细微的劲气，伤人于无形。专门攻击敌人的穴道，令人防不胜防。", type: "exclusive"},
            {name: "太乙分光剑", color: "A", cost: 1500, desc: "利用光影错觉的剑法。剑招虚实难辨，敌人往往在眼花缭乱中中剑倒地。", type: "exclusive"},
            {name: "公羊剑胎", color: "SS", cost: 7500, desc: "你在体内养出一口剑胎。人剑合一，不需要手持兵器，身体任何部位都能释放出凌厉剑气。", type: "exclusive"},
            {name: "数术天才", color: "B", cost: 300, desc: "你对数字极度敏感。心算速度堪比计算机，在破解机关和阵法时有天然优势。", type: "exclusive"},
            {name: "三三步", color: "C", cost: 200, desc: "一种奇特的步法，暗合九宫八卦。虽然不快，但总能在方寸之间避开敌人的致命攻击。", type: "exclusive"},
            {name: "苦肉计", color: "C", cost: 100, desc: "你善于忍受痛苦，并能利用伤势博取同情或让敌人放松警惕，关键时刻反戈一击。", type: "exclusive"},
            {name: "两仪剑法", color: "B", cost: 500, desc: "合乎阴阳之道的剑法。攻守兼备，若有同伴配合双剑合璧，威力可提升至A级。", type: "exclusive"},
            {name: "穷儒酸气", color: "D", cost: 50, desc: "你读书读傻了，满口之乎者也。虽然让人厌烦，但偶尔能用大道理把一些低智商敌人绕晕。", type: "exclusive"},
            {name: "机关术(精通)", color: "A", cost: 1000, desc: "你精通墨家与天机宫的机关术。能制造连弩、木牛流马等器械，也能瞬间拆解敌人的机关陷阱。", type: "exclusive"},
            {name: "星罗散手", color: "B", cost: 450, desc: "如星罗棋布般的掌法。招式繁多，虚虚实实，专门用来封锁敌人的退路。", type: "exclusive"},
            {name: "万物归元", color: "SSS", cost: 32000, desc: "和谐之道的终极体现。你能将异种真气、毒素、甚至物理冲击全部转化为自身的能量。", type: "exclusive"}
        ]
    },
    {
        name: "354.沧海",
        desc: "昆仑之后，沧海横流。三百年前的恩怨，黑天劫与天道苍苍。这是一个追寻‘道’与‘劫’的世界，武学已近乎神通。",
        boss: "陆渐, 谷神, 万归藏, 虞照",
        identities: [
            { name: "日本渔村的流浪儿", items: "一件破渔衣, 几条咸鱼" },
            { name: "西城卫队的杂役", items: "一把扫帚, 西城的身份木牌" },
            { name: "东岛的低级弟子", items: "一把木剑, 一本入门心法" },
            { name: "明朝官军的小卒", items: "一杆长枪, 破旧的棉甲" },
            { name: "海商船上的水手", items: "缆绳一根, 劣质朗姆酒" }
        ],
        talents: [
            {name: "黑天书(劫奴)", color: "S", cost: 2000, desc: "修炼此功者为‘劫奴’，能借用‘劫主’的内力，修炼速度极快。但生死操于劫主之手，且受‘黑天劫’折磨。", type: "exclusive"},
            {name: "黑天书(劫主)", color: "SS", cost: 8500, desc: "修炼此功者为‘劫主’，能随意抽取劫奴的内力为己用，并控制劫奴的生死。是绝对的上位者。", type: "exclusive"},
            {name: "太虚眼", color: "SSS", cost: 26000, desc: "看破世间一切虚妄与破绽。无论是武功招式还是阵法禁制，在你眼中都如掌上观纹，毫无秘密。", type: "exclusive"},
            {name: "周流六虚功(谐之道)", color: "SSS", cost: 30000, desc: "达到了万物和谐的境界。不再被八种力量反噬，而是随意转化，举手投足间引动天地之威。", type: "exclusive"},
            {name: "神农药体", color: "A", cost: 1600, desc: "常年浸泡药浴，身体抗毒性极强，且恢复力惊人。血液可以作为解毒剂使用。", type: "exclusive"},
            {name: "大金刚神力", color: "S", cost: 3200, desc: "佛门护法神功。力大无穷，金刚不坏。练至深处，一拳可碎城墙，肉身硬抗神兵利器。", type: "exclusive"},
            {name: "九龙神火罩", color: "A", cost: 2000, desc: "西城绝学之一。能释放出高温气墙防御，反弹敌人的攻击，并附带灼烧伤害。", type: "exclusive"},
            {name: "碧海潮生曲", color: "B", cost: 800, desc: "以音律扰乱敌人心智。内力深厚者可让人气血翻涌，内力低微者直接经脉寸断。", type: "exclusive"},
            {name: "龟镜", color: "SS", cost: 7000, desc: "算无遗策的神器。每天可进行一次吉凶占卜，准确率极高，能让你避开必死的杀局。", type: "exclusive"},
            {name: "商道奇才", color: "C", cost: 250, desc: "你拥有经商的天赋。能低买高卖，快速积累财富，在任何世界都不用为钱发愁。", type: "exclusive"},
            {name: "水战精通", color: "B", cost: 400, desc: "在水面上战斗力不减反增。熟悉各种水战器械和船只操作，是海战的好手。", type: "exclusive"},
            {name: "隐忍", color: "C", cost: 150, desc: "你极擅长隐藏自己的情绪和意图。即使面对杀父仇人也能笑脸相迎，等待最佳复仇时机。", type: "exclusive"},
            {name: "他心通(残)", color: "A", cost: 1800, desc: "能模糊感应到周围人的情绪波动。虽然读不出具体想法，但能判断对方是否有敌意。", type: "exclusive"},
            {name: "千鳞铁甲", color: "B", cost: 600, desc: "一件防御力极强的宝甲。能抵挡普通刀剑的劈砍，但对内力渗透的防御较差。", type: "exclusive"},
            {name: "天子望气术(入门)", color: "S", cost: 3800, desc: "观察天地人三才之气。能看到敌人的气机流动，预判其下一步动作，甚至截断其气运。", type: "exclusive"}
        ]
    },
    {
        name: "355.希灵帝国",
        desc: "跨越多元宇宙的宏大史诗。帝国舰队纵横虚空，审查官维护文明秩序。这是一个关于皇帝、女神、以及各种奇葩外星人的故事。",
        boss: "陈俊, 珊多拉, 希尔维亚, 叮当",
        identities: [
            { name: "地球K市的倒霉学生", items: "一本暑假作业, 一个旧手机" },
            { name: "宏世界的数据幽灵", items: "一段乱码, 无法触碰实体的身体" },
            { name: "帝国附庸文明的矿工", items: "激光挖掘机, 能量配给卡" },
            { name: "废土星球的拾荒者", items: "盖革计数器, 一袋发光的蘑菇" },
            { name: "影子城的临时工", items: "扫把, 虚空清洁剂" }
        ],
        talents: [
            {name: "虚空引擎(民用版)", color: "SS", cost: 9500, desc: "能小范围修改现实规则。虽然不能无中生有，但能做到‘让子弹拐弯’或‘让水燃烧’这种程度的操作。", type: "exclusive"},
            {name: "精神连接(链路)", color: "A", cost: 1200, desc: "接入希灵精神网络。可以与同伴进行无延迟的心灵通话，共享视野，甚至分担精神伤害。", type: "exclusive"},
            {name: "幽能亲和", color: "S", cost: 3000, desc: "你适应了深渊与神性的混合能量。可以使用幽能进行攻击，破坏力极大，带有腐蚀和同化效果。", type: "exclusive"},
            {name: "希灵军规(背诵)", color: "C", cost: 100, desc: "你熟背帝国军规。在遇到希灵正规军时，能通过对暗号获得友军身份，避免被当成土著清理。", type: "exclusive"},
            {name: "量产型主机", color: "B", cost: 600, desc: "你的大脑植入了辅助计算芯片。逻辑分析能力大幅提升，能快速学习语言和操作各种高科技设备。", type: "exclusive"},
            {name: "世界仲裁机关(残)", color: "SSS", cost: 40000, desc: "你拥有一个世界管理系统的残骸。能对低级文明降下‘天罚’，或者局部重置世界状态。", type: "exclusive"},
            {name: "叮当的神术", color: "S", cost: 3500, desc: "生命女神的神术。只要还有一口气，就能把你奶回来。副作用是偶尔会变成马赛克或者长出奇怪的东西。", type: "exclusive"},
            {name: "维斯卡狂暴", color: "A", cost: 2200, desc: "进入红瞳狂暴状态。毁灭欲望高涨，全属性大幅提升，疼痛感消失，直到敌人或自己倒下。", type: "exclusive"},
            {name: "泡泡的资讯操作", color: "SS", cost: 8000, desc: "能直接读取和修改电子设备的数据。在这个信息化时代，你就是网络的神。", type: "exclusive"},
            {name: "帝国合金装甲", color: "A", cost: 1500, desc: "一套单兵作战装甲。防御力极强，自带维生系统和小型能量护盾，能适应真空环境。", type: "exclusive"},
            {name: "虚空生物体质", color: "SSS", cost: 50000, desc: "你是非资讯的虚空生物。免疫大部分法则抹杀，可以在世界之外的虚空中生存，是世界的‘毒’也是‘药’。", type: "exclusive"},
            {name: "吐槽能量转化", color: "B", cost: 500, desc: "一种因果律技能。你的吐槽越精准犀利，就能转化为越强的精神能量攻击敌人。", type: "exclusive"},
