            {name: "琅琊榜首", color: "A", cost: 1500, desc: "名满天下。你的名声能让你在任何势力中都受到礼遇，容易招募到人才。", type: "exclusive"},
            {name: "火寒毒(变异)", color: "S", cost: 2800, desc: "身中奇毒，虽然体弱多病，但换来了易容换貌和极其敏锐的感知力，且百毒不侵。", type: "exclusive"},
            {name: "靖王的执拗", color: "B", cost: 600, desc: "认死理。一旦认定的事情绝不回头，意志力极强，很难被说服或动摇。", type: "exclusive"},
            {name: "悬镜司审讯术", color: "B", cost: 800, desc: "夏江的手段。能撬开任何人的嘴，获取情报。手段残忍，效率极高。", type: "exclusive"},
            {name: "蒙挚的武力", color: "S", cost: 3500, desc: "大梁第一高手的武学天赋。精通各种兵器和拳脚，正面对抗鲜有敌手。", type: "exclusive"},
            {name: "妙音坊曲艺", color: "C", cost: 300, desc: "宫羽的琴技。能通过音乐传递信息，或者安抚/挑拨听众的情绪。", type: "exclusive"},
            {name: "易容术", color: "B", cost: 500, desc: "精妙的化妆技巧。能改变面容和声音，潜入敌营如入无人之境。", type: "exclusive"},
            {name: "水牛", color: "C", cost: 100, desc: "像水牛一样强壮和倔强。体力充沛，耐力极好，就是脑子有时候转不过弯。", type: "exclusive"},
            {name: "琅琊阁情报", color: "A", cost: 2000, desc: "你拥有查询琅琊阁情报的权限。只要付得起代价，就能知道天下任何秘密。", type: "exclusive"},
            {name: "滑族秘术", color: "A", cost: 1200, desc: "璇玑公主的传承。擅长魅惑、操纵人心和布置连环计，是后宫争斗的利器。", type: "exclusive"},
            {name: "私炮房火药", color: "B", cost: 700, desc: "掌握黑火药的制作和爆破技术。能制造意外事故，或者在战斗中造成范围伤害。", type: "exclusive"},
            {name: "情义千秋", color: "SS", cost: 7500, desc: "你的人格魅力极强。朋友和部下会对你死心塌地，绝不背叛，哪怕面对死亡。", type: "exclusive"}
        ]
    },
                      {
                name: "361.塞尔达传说 (Zelda)",
                desc: "海拉鲁大陆，一个被古老传说和循环宿命缠绕的奇幻世界。三角力量的争夺从未停止，灾厄盖侬的怨念在大地徘徊。这里有古老的希卡科技、神秘的神庙和广阔的荒野。",
                boss: "灾厄盖侬, 加农多夫, 黑暗林克, 终焉者",
                identities: [
                    { name: "海拉鲁平原的波克布林奴隶", items: "一根断裂的树枝, 一块发臭的兽肉" },
                    { name: "卡卡利科村的养鸡人", items: "一袋鸡饲料, 一个被鸡啄破的草帽" },
                    { name: "依盖队的底层杂兵", items: "一把生锈的镰刀, 一串香蕉" },
                    { name: "卓拉领地的清理工", items: "一把刷满青苔的刷子, 总是湿漉漉的破布衣" },
                    { name: "双子驿站的马粪清理员", items: "一把断齿的草叉, 一身洗不掉的马粪味" }
                ],
                talents: [
                    {name: "三角力量·勇氣(觉醒)", color: "SSS", cost: 45000, desc: "被女神选中的证明。无论面对何种绝境或恐惧，你都能保持绝对的冷静与勇气，拥有斩断黑暗的潜质，是世界的救世主。", type: "exclusive"},
                    {name: "大师之剑(认可)", color: "SS", cost: 8000, desc: "驱魔之剑不再排斥你的触碰。虽然你还不能完全发挥它的威力，但这把剑本身就是对邪恶力量的绝对克星。", type: "exclusive"},
                    {name: "希卡石板(完整)", color: "S", cost: 3500, desc: "古代希卡族的科技结晶。拥有时停、磁力、造冰、炸弹等多种符文能力，是解谜和战斗的万能工具。", type: "exclusive"},
                    {name: "米法的手护", color: "S", cost: 3200, desc: "卓拉英杰米法的治愈力量。当你受到致命伤害时，会瞬间完全恢复生命值并增加额外上限，但有很长的冷却时间。", type: "exclusive"},
                    {name: "林克时间(子弹时间)", color: "A", cost: 1500, desc: "当你进行完美闪避或在空中拉弓时，你眼中的世界会变得极度缓慢，让你能在一瞬间打出成吨的伤害。", type: "exclusive"},
                    {name: "英杰服(复制品)", color: "B", cost: 450, desc: "仿造英杰服制作的衣物，虽然没有原版的强大防御，但能让你看到敌人的生命值数值。", type: "exclusive"},
                    {name: "滑翔伞技术", color: "C", cost: 180, desc: "你掌握了利用滑翔伞御风而行的技巧，只要有高低差和耐力，天空就是你的捷径。", type: "exclusive"},
                    {name: "盾反精通", color: "A", cost: 900, desc: "你掌握了在攻击即将命中的瞬间挥盾弹反的绝技，甚至能将守护者的激光原路反射回去。", type: "exclusive"},
                    {name: "野炊料理人", color: "C", cost: 120, desc: "你擅长在野外用各种奇怪的素材烹饪。做出的料理虽然卖相一般，但恢复体力的效果比生吃强多了。", type: "exclusive"},
                    {name: "呀哈哈的面具", color: "B", cost: 300, desc: "当你靠近隐藏的克洛格（呀哈哈）时，面具会摇晃发出声响。对于寻找隐藏资源有奇效。", type: "exclusive"},
                    {name: "卓拉游泳术", color: "B", cost: 500, desc: "像卓拉族一样在水中自由穿梭，甚至能逆流而上攀登瀑布，水战能力大幅提升。", type: "exclusive"},
                    {name: "鼓隆族怪力", color: "A", cost: 850, desc: "你拥有了鼓隆族般的怪力，可以轻松举起巨大的岩石或重型武器，对矿石类敌人有特效。", type: "exclusive"},
                    {name: "利特族风神跃", color: "A", cost: 800, desc: "你可以利用身边的气流凭空跳起很高的高度，在战斗中占据制空权。", type: "exclusive"},
                    {name: "古代兵器耐性", color: "B", cost: 600, desc: "你的身体经过微弱的古代能量改造，对守护者等古代兵器造成的激光伤害有较高的抗性。", type: "exclusive"},
                    {name: "血月共鸣", color: "D", cost: 80, desc: "每当血月降临，你的情绪会变得狂躁，攻击力微弱提升，但理智会下降，容易被怪物当成同类。", type: "exclusive"}
                ]
            },
            {
                name: "362.超级马力欧 (Mario)",
                desc: "蘑菇王国，一个色彩斑斓却充满危险的世界。库巴军团时刻威胁着王国的和平，水管连接着无数奇异的区域。这里有神奇的蘑菇、危险的食人花和无尽的跳跃。",
                boss: "库巴, 库巴二世, 卡美克, 瓦里奥",
                identities: [
                    { name: "1-1关卡的第一个栗宝宝", items: "两条短腿, 一张容易被踩扁的脸" },
                    { name: "库巴城堡的岩浆清理工", items: "一把耐热铲子, 一双被烫出水泡的脚" },
                    { name: "被遗忘的问号砖块", items: "一枚生锈的金币, 坚硬的外壳" },
                    { name: "幽灵鬼屋的受气包幽灵", items: "一看到人就害羞捂脸的本能, 虚无的身体" },
                    { name: "下水道的清理工学徒", items: "一把通马桶的皮搋子, 一身绿色的工装裤" }
                ],
                talents: [
                    {name: "无敌星之力", color: "SSS", cost: 38000, desc: "触碰无敌星后的状态。在短时间内，你对所有伤害免疫，并且触碰到的任何敌人都将被秒杀。这是绝对的规则级力量。", type: "exclusive"},
                    {name: "1UP蘑菇(复活)", color: "SS", cost: 6500, desc: "极其稀有的绿蘑菇。在这个死亡如家常便饭的世界，它能为你提供一次额外的生命，让你在死亡处原地复活。", type: "exclusive"},
                    {name: "超级跳跃", color: "B", cost: 400, desc: "你的腿部肌肉构造异于常人，可以轻松跳起自身身高数倍的高度，并且能通过踩踏敌人头部造成伤害。", type: "exclusive"},
                    {name: "火焰花体质", color: "A", cost: 1200, desc: "你的身体充满了火元素，可以从手中投掷出在地面弹跳的火球，对植物类和冰系敌人有奇效。", type: "exclusive"},
                    {name: "狸猫变身", color: "S", cost: 2800, desc: "长出尾巴和耳朵，你可以挥动尾巴攻击，甚至在助跑后短暂飞行。最强的是可以变成地藏石像躲避一切攻击。", type: "exclusive"},
                    {name: "巨大蘑菇", color: "S", cost: 2500, desc: "使用后体型瞬间变得巨大无比，可以踩碎一切砖块和障碍物，单纯的体型碾压。", type: "exclusive"},
                    {name: "凯皮附身", color: "SS", cost: 7500, desc: "来自帽子国的神奇能力。你可以将帽子扔到敌人头上，从而控制对方的身体和能力，是潜入和解谜的神技。", type: "exclusive"},
                    {name: "水管工钻探", color: "C", cost: 150, desc: "你对管道有天生的亲和力，可以钻进任何足够大的管道中，并在复杂的地下管网中快速移动。", type: "exclusive"},
                    {name: "龟壳防御", color: "B", cost: 350, desc: "背上长出坚硬的龟壳。缩入壳中时防御力大增，还能像保龄球一样高速旋转撞击敌人。", type: "exclusive"},
                    {name: "耀西的舌头", color: "A", cost: 1100, desc: "你的舌头可以伸得很长，能够吞下比自己小的敌人或物品，并将其转化为蛋投掷出去。", type: "exclusive"},
                    {name: "冰冻花体质", color: "A", cost: 1200, desc: "与火焰花相对，你可以投掷冰球将敌人冻成冰块。被冻住的敌人可以作为平台或投掷物。", type: "exclusive"},
                    {name: "黄得发亮的金币", color: "C", cost: 200, desc: "你的运气略微提升，在破坏砖块或击败敌人时，更容易掉落通用的货币。", type: "exclusive"},
                    {name: "幽灵化", color: "B", cost: 600, desc: "你可以暂时让身体变得虚无，穿过墙壁或躲避物理攻击，但此时极其畏惧强光。", type: "exclusive"},
                    {name: "库巴的喷火", color: "S", cost: 2200, desc: "拥有库巴一族的血统，可以从口中喷出持续的高温火焰，威力远超普通火球。", type: "exclusive"},
                    {name: "毒蘑菇体质", color: "D", cost: 50, desc: "你的血液中含有毒素，触碰你的人会受伤，但你自己也会持续处于虚弱状态，体型比常人更小。", type: "exclusive"}
                ]
            },
            {
                name: "363.银河战士 (Metroid)",
                desc: "充满未知与恐惧的深空孤星。鸟人族的遗迹掩盖着X寄生体和密特罗德的威胁，星际海盗在暗处窥视。这里是孤独猎人的战场，唯有最强的战士才能生存。",
                boss: "母脑(Mother Brain), 利德雷, 黑暗萨姆斯, 密特罗德女王",
                identities: [
                    { name: "泽贝斯星的酸液池清理工", items: "一套严重腐蚀的防护服, 一个漏气的氧气罐" },
                    { name: "星际海盗的实验体废料", items: "断裂的镣铐, 身体上不知名的注射孔" },
                    { name: "联邦军团的炮灰士兵", items: "一把卡壳的能量枪, 一块破碎的身份牌" },
                    { name: "SR388星的遇难矿工", items: "一把激光镐, 仅剩半小时的维生系统" },
                    { name: "鸟人族遗迹的清扫机器人", items: "快没电的电池, 只能发出噪音的发声单元" },
                ],
                talents: [
                    {name: "鸟人族DNA(觉醒)", color: "SSS", cost: 32000, desc: "全宇宙最强战士的基因蓝图。赋予你超乎常理的身体素质、适应任何环境的能力，以及操控鸟人族神级科技的权限。", type: "exclusive"},
                    {name: "密特罗德体质(吸收)", color: "SS", cost: 9000, desc: "你拥有了宇宙最强掠食者密特罗德的特性。可以通过触碰吸取敌人的生命能量，但也因此极度畏惧寒冷。", type: "exclusive"},
                    {name: "能量装甲(Varia Suit)", color: "S", cost: 4000, desc: "鸟人族的战斗装甲。提供极高的防御力，完全免疫高温和酸液环境，是探索恶劣星球的必备之物。", type: "exclusive"},
                    {name: "变形球模式", color: "A", cost: 1500, desc: "你可以将身体蜷缩成一个直径一米的球体，在狭窄通道中高速滚动，并能放置炸弹进行跳跃。", type: "exclusive"},
                    {name: "X寄生体抗性", color: "SS", cost: 7000, desc: "你的细胞中融合了密特罗德的遗传信息，是全宇宙唯一能免疫X寄生体感染并将其吸收的存在。", type: "exclusive"},
                    {name: "螺旋攻击", color: "S", cost: 3000, desc: "在跳跃旋转时，你的周身会被高能电浆覆盖，任何触碰你的敌人都将被粉碎，攻防一体的绝技。", type: "exclusive"},
                    {name: "冰冻光束", color: "A", cost: 1800, desc: "你的攻击附带绝对零度的冻气，可以将敌人冻结成踏板，也是克制密特罗德的唯一手段。", type: "exclusive"},
                    {name: "等离子光束", color: "A", cost: 2000, desc: "发射出能穿透敌人的高温等离子体，无视大部分常规装甲，对生物目标造成毁灭性打击。", type: "exclusive"},
                    {name: "重力服功能", color: "S", cost: 3500, desc: "使你在水中或失重环境中行动自如，完全不受阻力影响，并大幅提升防御力。", type: "exclusive"},
                    {name: "超级导弹", color: "B", cost: 800, desc: "你可以发射威力巨大的震荡导弹，能炸开特殊的红色闸门，对大型BOSS造成重创。", type: "exclusive"},
                    {name: "钩索光束", color: "B", cost: 600, desc: "发射一条能量鞭，可以抓住远处的特殊节点进行荡跃，或者强行扯下敌人的盾牌。", type: "exclusive"},
                    {name: "扫描面罩", color: "C", cost: 300, desc: "战术分析目镜，可以瞬间扫描生物弱点、破解电子锁、记录环境信息，情报就是生命。", type: "exclusive"},
                    {name: "加速器(Speed Booster)", color: "A", cost: 1600, desc: "当你在直线奔跑一段时间后，会进入超音速状态，无坚不摧，甚至可以利用动能进行“凤凰之舞”飞行。", type: "exclusive"},
                    {name: "幻影斗篷", color: "B", cost: 900, desc: "利用艾昂能量折射光线，进入完全隐形状态，但移动会消耗大量能量。", type: "exclusive"},
                    {name: "菲宗辐射病", color: "D", cost: 100, desc: "你被放射性物质菲宗感染，虽然攻击力大幅提升，但生命值会持续扣除，且精神处于崩溃边缘。", type: "exclusive"}
                ]
            },
            {
                name: "364.火焰纹章 (Fire Emblem)",
                desc: "剑与魔法的战棋大陆，诸国林立，战火纷飞。龙族、人类与神祗的命运交织。这里讲究兵种相克，策略为王，每一次死亡都是永久的离别。",
                boss: "暗黑龙·梅迪乌斯, 邪龙·索蒙布尔, 暴走蕾亚, 黑暗神",
                identities: [
                    { name: "边境村庄的替补民兵", items: "一把卷刃的铁枪, 破烂的布甲" },
                    { name: "被山贼洗劫后的幸存孤儿", items: "半个发霉的面包, 父母的遗物吊坠" },
                    { name: "教会修道院的扫地杂役", items: "一把扫帚, 一本看不懂的经书" },
                    { name: "战败国的逃兵", items: "没有徽章的盾牌, 腿上的箭伤" },
                    { name: "黑市商人的搬运工", items: "沉重的货物箱, 一枚假金币" }
                ],
                talents: [
                    {name: "炎之纹章(觉醒)", color: "SSS", cost: 40000, desc: "世界根源的力量。你拥有开启异界之门、逆转时间、弑杀神明的潜力。你是天选的王者，注定统一大陆。", type: "exclusive"},
                    {name: "神祖之血", color: "SS", cost: 8500, desc: "流淌着女神索谛斯的血液。你拥有极长的寿命，能使用天帝之剑等神圣武器，并能听到女神的神谕。", type: "exclusive"},
                    {name: "龙之石(玛纳克特)", color: "S", cost: 3800, desc: "你并非人类，而是龙族后裔。通过龙石可以变身为巨龙，拥有毁灭性的吐息和坚硬的龙鳞。", type: "exclusive"},
                    {name: "再移动(Canto)", color: "B", cost: 600, desc: "骑兵与飞行单位的绝技。在攻击或行动后，你可以利用剩余的移动力继续移动，打了就跑，极其赖皮。", type: "exclusive"},
                    {name: "天空(奥义)", color: "S", cost: 2500, desc: "英雄艾克的绝技。先发动“太阳”吸取敌人生命，再发动“月光”无视敌人防御，攻防一体的究极剑技。", type: "exclusive"},
                    {name: "必杀一击(Crit)", color: "A", cost: 1200, desc: "你极其擅长寻找敌人的弱点。攻击时有高概率造成3倍伤害，发动时伴随着特殊的特写和光效。", type: "exclusive"},
                    {name: "良成长", color: "A", cost: 1500, desc: "村民类角色的神技。虽然初始能力低下，但你升级时各项属性提升的概率极高，后期必成战神。", type: "exclusive"},
                    {name: "远距离反击", color: "S", cost: 2200, desc: "无论敌人从多远的地方发起攻击，你都能无视距离进行反击。这是强者的绝对领域。", type: "exclusive"},
                    {name: "武器节约", color: "C", cost: 300, desc: "你使用武器非常爱惜，有很高概率不消耗武器耐久度。在神器耐久有限的世界里非常实用。", type: "exclusive"},
                    {name: "舞娘之舞", color: "A", cost: 1800, desc: "通过神秘的舞蹈，可以让已经行动过的友军再次行动。战术价值极高的辅助能力。", type: "exclusive"},
                    {name: "重甲特库", color: "B", cost: 500, desc: "你穿着厚重的铠甲，对物理攻击的防御力极高，但移动缓慢且极其畏惧魔法和破甲武器。", type: "exclusive"},
                    {name: "天马骑士资质", color: "B", cost: 700, desc: "你被纯洁的天马认可，可以骑乘它们在空中作战，无视地形障碍，但极度畏惧弓箭。", type: "exclusive"},
                    {name: "纹章士戒指", color: "SS", cost: 7500, desc: "寄宿着过往英雄灵体的戒指。戴上它，你可以与英雄“结合”，使用他们的强力技能和武器。", type: "exclusive"},
                    {name: "支援S", color: "C", cost: 200, desc: "你很容易与他人建立深厚的羁绊。当你与好感度高的伙伴站在一起时，双方的战斗力都会大幅提升。", type: "exclusive"},
                    {name: "该死的乱数", color: "D", cost: 50, desc: "你的命运被奇怪的概率支配。明明有99%的命中率却经常打空，或者被敌人1%的暴击率秒杀。", type: "exclusive"}
                ]
            },
            {
                name: "365.星之卡比 (Kirby)",
                desc: "波普之星，一个看似粉嫩可爱实则战力崩坏的世界。这里生活着能吞噬一切的粉色恶魔。梦境与现实交错，古神与机械共存。",
                boss: "梦魇, 零(Zero), 冥王哈迪斯, 终焉·虚无",
                identities: [
                    { name: "噗噗噗之国的瓦豆鲁迪路人", items: "一根长矛, 一张没有嘴的脸" },
                    { name: "帝帝帝城堡的搬运工", items: "沉重的木箱, 随时被大王锤飞的觉悟" },
                    { name: "魅塔骑士战舰的整备兵", items: "一把扳手, 恐高症诊断书" },
                    { name: "波普之星的苹果树农夫", items: "一篮维斯比苹果, 怕火的本能" },
                    { name: "镜之迷宫的迷路者", items: "碎裂的镜片, 永远走不出的地图" }
                ],
                talents: [
                    {name: "无限胃袋(吞噬)", color: "SSS", cost: 42000, desc: "你的体内连接着一个黑洞宇宙。可以吸入任何物体、能量甚至概念，并将其消化或转化为自己的力量。", type: "exclusive"},
                    {name: "复制能力(Copy)", color: "SS", cost: 8800, desc: "吞噬敌人后，你可以完美解析并获得对方的核心能力，并瞬间换装。是全能战士的基础。", type: "exclusive"},
                    {name: "超级新星(Super Nova)", color: "SSS", cost: 35000, desc: "奇迹果实的力量。你的吸力增强亿万倍，连巨大的BOSS、地形甚至时空本身都能吸入腹中。", type: "exclusive"},
                    {name: "魅塔骑士剑术", color: "S", cost: 3200, desc: "银河最强剑士的技艺。超高速的连斩、龙卷风斩击和穿梭空间的瞬移，以此剑守护荣耀。", type: "exclusive"},
                    {name: "帝帝帝大锤", color: "A", cost: 1500, desc: "一把巨大的木槌，虽然沉重但威力惊人。蓄力后可以打出产生火焰的强力一击，还能用来打桩。", type: "exclusive"},
                    {name: "瓦豆鲁迪的勤勉", color: "C", cost: 150, desc: "虽然没有任何特殊能力，但你拥有极强的执行力和忠诚度，无论多繁重的工作都能任劳任怨地完成。", type: "exclusive"},
                    {name: "马克西姆番茄", color: "A", cost: 1000, desc: "带有M标记的神奇番茄。无论受了多重的伤，吃下去就能瞬间完全恢复体力。", type: "exclusive"},
                    {name: "弯刀能力", color: "B", cost: 500, desc: "你可以投掷回旋镖般的弯刀，不仅能切割敌人，还能割断绳索、携带道具回来。", type: "exclusive"},
                    {name: "烈火能力", color: "B", cost: 600, desc: "全身包裹火焰冲刺，或者喷出火柱。不仅能攻击，还能点燃引信，解开谜题。", type: "exclusive"},
                    {name: "麦克风(全屏攻击)", color: "S", cost: 2800, desc: "虽然你五音不全，但你的歌声是毁灭性的声波武器。使用次数有限，但每次都能清空全屏的小怪。", type: "exclusive"},
                    {name: "UFO能力", color: "S", cost: 3000, desc: "极其稀有的能力。变成UFO自由飞行，拥有蓄力激光、穿透光束等多种强力武器。", type: "exclusive"},
                    {name: "睡觉能力", color: "C", cost: 50, desc: "当场睡着。虽然看起来没用，但在某些版本中可以稍微恢复体力，主要是为了卖萌。", type: "exclusive"},
                    {name: "魔古洛亚的谎言", color: "A", cost: 2000, desc: "你擅长欺骗和利用他人为你收集能量，甚至能欺骗单纯的主角为你打倒守护巨龙。", type: "exclusive"},
                    {name: "机器人装甲(Robobot)", color: "SS", cost: 7000, desc: "哈尔特曼公司的科技结晶。驾驶这台机甲，你可以扫描敌人并获得更强大的机甲版复制能力，粉碎一切。", type: "exclusive"},
                    {name: "暗物质侵蚀", color: "D", cost: 120, desc: "你被暗物质附身，虽然获得了飞行和黑魔法能力，但身体会长出一只巨大的独眼，且逐渐失去自我。", type: "exclusive"}
                ]
            },
            {
                name: "366.动物森友会 (Animal Crossing)",
                desc: "看似温馨的无人岛移居计划，实则是资本家狸克操控的房贷地狱。这里有拟人化的动物邻居，有四季变换，但你需要不断赚钱还债，否则永远只是帐篷客。",
                boss: "狸克(Tom Nook), 恐怖的狼蛛/蝎子, 伪造名画的狐利",
                identities: [
                    { name: "刚下飞机的负债人", items: "一个简陋的帐篷, 巨额房贷账单" },
                    { name: "博物馆的化石清洁工", items: "一把小刷子, 对猫头鹰的恐惧" },
                    { name: "大头菜市场的投机失败者", items: "一堆烂掉的大头菜, 空空的钱包" },
                    { name: "无人岛的杂草清理员", items: "拔不完的杂草, 一双手套" },
                    { name: "狐利的黑船苦力", items: "一幅假的《蒙娜丽莎》, 摇摇晃晃的甲板" }
                ],
                talents: [
                    {name: "岛屿创世神(岛建)", color: "SSS", cost: 28000, desc: "你获得了修改地形的权限。可以随意铲平山丘、填平河流、铺设道路。在这个世界，你就是造物主。", type: "exclusive"},
                    {name: "金道具图纸", color: "S", cost: 3000, desc: "掌握了制作金色工具的技艺。金铲子、金钓竿等拥有极高的耐久度，是劳作的神器。", type: "exclusive"},
                    {name: "铃钱大亨", color: "A", cost: 1500, desc: "你对经济极其敏感，能预测大头菜的股市波动，轻松实现财富自由，让狸克都对你点头哈腰。", type: "exclusive"},
                    {name: "动物语十级", color: "B", cost: 500, desc: "你可以毫无障碍地与所有动物居民交流，轻易获得他们的照片和传家宝，甚至能指挥他们做事。", type: "exclusive"},
                    {name: "口袋收纳术", color: "S", cost: 2200, desc: "你的口袋连接着亚空间。可以将巨大的家具、鲨鱼、甚至整棵树塞进裤兜里，负重几乎无限。", type: "exclusive"},
                    {name: "西施惠的广播", color: "B", cost: 800, desc: "你掌握了全岛广播的权力。你说的话就是岛屿的规则，可以用来发布命令或操纵舆论。", type: "exclusive"},
                    {name: "摇钱树种植", color: "A", cost: 1200, desc: "你种下的钱袋必定会长成摇钱树，产出三倍的收益。这是打破能量守恒的敛财手段。", type: "exclusive"},
                    {name: "昆虫图鉴大师", color: "C", cost: 300, desc: "你对昆虫的习性了如指掌，即使是极其稀有的黄金鬼也好，大力神也好，都能轻松捕捉。", type: "exclusive"},
                    {name: "鱼类图鉴大师", color: "C", cost: 300, desc: "只要看鱼影的大小和游动方式，你就能知道那是什么鱼。钓鲨鱼对你来说就像喝水一样简单。", type: "exclusive"},
                    {name: "K.K.的吉他", color: "B", cost: 600, desc: "当你弹奏吉他时，周围的生物会不由自主地停下来聆听，心情变好，甚至能暂时消除敌意。", type: "exclusive"},
                    {name: "撑杆跳", color: "C", cost: 100, desc: "利用撑杆，你可以轻松跨越河流，前往岛屿的任何角落，无需桥梁。", type: "exclusive"},
                    {name: "设计我的家(魔法)", color: "A", cost: 1800, desc: "在室内，你可以凭空移动家具，改变墙纸地板，甚至扩展房间空间，完全无视物理规则。", type: "exclusive"},
                    {name: "流星许愿", color: "S", cost: 2500, desc: "当你对着流星许愿时，第二天海滩上必定会出现稀有的星星碎片，那是制作魔法棒的材料。", type: "exclusive"},
                    {name: "狸克的催债", color: "D", cost: 200, desc: "你背负着无法偿还的债务。狸克的阴影时刻笼罩着你，让你无法离开岛屿，且赚到的钱会自动扣除一部分。", type: "exclusive"},
                    {name: "蜂群体质", color: "D", cost: 100, desc: "你摇树时必定掉下马蜂窝，且必定被蛰。你的脸永远是肿的，药膏对你无效。", type: "exclusive"}
                ]
            },
            {
                name: "367.斯普拉遁 (Splatoon)",
                desc: "人类灭绝后的未来，海洋生物进化统治陆地。这是一个充满潮流、墨水和地盘争夺的世界。乌贼娘和章鱼娘们用墨水枪进行着体育竞技般的战争。",
                boss: "DJ奥克塔维奥, 熊先生(Grizz), 3号(被控制), 秩序/混沌之神",
                identities: [
                    { name: "尚兴广场的打工仔", items: "一件过时的T恤, 熊先生商会的招募传单" },
                    { name: "下水道的章鱼逃兵", items: "一副破碎的护目镜, 对阳光的不适" },
                    { name: "武器店的试射靶子", items: "满身的墨水痕迹, 破损的防御背心" },
                    { name: "鲑鱼跑的底层搬蛋工", items: "一把平底锅, 随时可能被鲑鱼吃掉的恐惧" },
                    { name: "过气的街头涂鸦艺人", items: "干涸的喷漆罐, 没人看的画板" }
                ],
                talents: [
                    {name: "色域支配(S级)", color: "SSS", cost: 30000, desc: "你不仅能喷射墨水，还能从概念上改写区域的“颜色”。在你的颜色领域内，你全知全能，敌人寸步难行。", type: "exclusive"},
                    {name: "超级跳跃(Super Jump)", color: "A", cost: 1200, desc: "你可以化身乌贼形态，瞬间弹射起飞，精准降落在队友身边，是支援和逃跑的神技。", type: "exclusive"},
                    {name: "墨水潜行", color: "B", cost: 500, desc: "在己方颜色的墨水中，你可以潜入地下高速移动，隐蔽身形，并快速恢复墨水储量。", type: "exclusive"},
                    {name: "大招充能(Special)", color: "S", cost: 2500, desc: "你的涂地效率极高。当涂抹面积达到一定程度，可以释放“赞气弹”、“多重导弹”等毁灭性大招。", type: "exclusive"},
                    {name: "真格身法(雷神步)", color: "A", cost: 1800, desc: "顶尖高手的身法。利用极短的潜行和射击切换，在敌人的弹雨中穿梭自如，仿佛在跳舞。", type: "exclusive"},
                    {name: "熊先生的非法改装", color: "S", cost: 2800, desc: "你获得了熊先生商会的违禁武器。射速、威力、墨水消耗都经过魔改，破坏力惊人但极不稳定。", type: "exclusive"},
                    {name: "偶像气场(潮色姐妹)", color: "A", cost: 2000, desc: "你的存在本身就是潮流。当你登场时，背景音乐会改变，友军士气大振，全能力提升。", type: "exclusive"},
                    {name: "鲑鱼卵收集者", color: "C", cost: 300, desc: "你对金鲑鱼卵有特殊的感应。在鲑鱼跑模式中，你能比别人背负更多的蛋，且不影响移动速度。", type: "exclusive"},
                    {name: "主武器性能提升", color: "B", cost: 600, desc: "你的装备上插满了技能碎片。攻击力增加至99.9，刚好能比别人少打一枪击杀敌人。", type: "exclusive"},
                    {name: "忍者乌贼", color: "B", cost: 800, desc: "在墨水中潜行时完全消除波纹和飞沫。你是无声的刺客，敌人直到死都不知道你在哪里。", type: "exclusive"},
                    {name: "复活惩罚", color: "D", cost: 150, desc: "虽然你能复活，但每次复活所需的时间比常人长一倍，且大招槽会清空。这是对菜鸟的惩罚。", type: "exclusive"},
                    {name: "水溶性体质", color: "D", cost: 500, desc: "在这个世界，掉进水里是致命的。你的身体一碰到大量的水就会直接溶解，必须时刻远离水面。", type: "exclusive"},
                    {name: "喷射背包", color: "A", cost: 1600, desc: "开启后利用墨水喷射飞在空中，手持爆破枪对地面进行轰炸，结束后会自动回到起飞点。", type: "exclusive"},
                    {name: "防爆盾(雨帘)", color: "C", cost: 400, desc: "投掷一个能生成墨水雨帘的装置，阻挡敌人的攻击，是阵地战的利器。", type: "exclusive"},
                    {name: "最后的一分钟(BGM)", color: "SS", cost: 6000, desc: "当比赛/战斗进入最后倒计时，那首著名的BGM会在你脑海响起。此时你的全属性翻倍，进入绝地翻盘模式。", type: "exclusive"}
                ]
            },
            {
                name: "368.异度神剑 (Xenoblade)",
                desc: "巨神与机神，两具在无尽海洋中对立的太古神骸。人类、机神兵、异刃在巨神的身体上繁衍生息与厮杀。这是一个关于因果律、神剑与斩断宿命的宏大世界。",
                boss: "赞扎, 埃格尔, 灭(Malos), 执政官Z",
                identities: [
                    { name: "9号殖民地的废品回收员", items: "一块机神兵的残骸, 一把扳手" },
                    { name: "机神界的量产脸孔机甲", items: "被抹去的人类记忆, 冰冷的机械躯体" },
                    { name: "阿卡狄亚的难民", items: "破旧的教团长袍, 一块核心水晶碎片" },
                    { name: "都市的迷路诺彭", items: "一袋虽然好吃但很贵的食物, 欠债账单" },
                    { name: "收容所的御刃者候补", items: "失败的协调记录, 缠着绷带的手臂" }
                ],
                talents: [
                    {name: "蒙纳多(Monado)", color: "SSS", cost: 50000, desc: "斩断神明之剑。拥有预知未来、斩断因果、重塑世界的能力。持有者必须拥有强大的意志力，否则会被力量吞噬。", type: "exclusive"},
                    {name: "天之圣杯(光/焰)", color: "SSS", cost: 48000, desc: "作为御刃者，你协调了传说中的天之圣杯。拥有因果律兵器级别的力量，可以随意修改物理法则，进行光速战斗。", type: "exclusive"},
                    {name: "未来视(Vision)", color: "SS", cost: 9000, desc: "你可以看见几秒到几分钟后的毁灭性未来。这给你改变命运、拯救同伴的机会，打破既定的因果。", type: "exclusive"},
                    {name: "衔尾蛇连结(Ouroboros)", color: "SS", cost: 8500, desc: "与心灵相通的搭档融合，变身为巨大的衔尾蛇形态。拥有无限的战技使用权和极强的再生能力，是反抗命运的力量。", type: "exclusive"},
                    {name: "御刃者资质", color: "A", cost: 2000, desc: "你有资格触碰核心水晶并唤醒异刃。异刃将赋予你武器和魔法，与你共享生命，成为你最亲密的战友。", type: "exclusive"},
                    {name: "机神界人身体", color: "A", cost: 2500, desc: "你的身体大部分由机械构成，寿命极长，无需进食，能直接连接和控制机神兵网络。", type: "exclusive"},
                    {name: "诺彭族的商才", color: "B", cost: 800, desc: "虽然身体圆滚滚且说话带嗼，但你是天生的奸商。总能以最低价买入，最高价卖出，且血量意外的厚。", type: "exclusive"},
                    {name: "破防-倒地-浮空-猛击", color: "S", cost: 3500, desc: "你精通这套究极连招。只要敌人露出破绽，你就能将其无限控制在空中直到死，掉落大量战利品。", type: "exclusive"},
                    {name: "连锁攻击(Chain Attack)", color: "SS", cost: 6000, desc: "冻结时间，指挥所有队友进行轮番轰炸。伤害倍率可以无限叠加，打出天文数字般的伤害。", type: "exclusive"},
                    {name: "食人种(Flesh Eater)", color: "S", cost: 3000, desc: "作为异刃，你融合了人类的细胞。虽然力量更强且不再受核心限制，但你的寿命变得有限且需要承受巨大的痛苦。", type: "exclusive"},
                    {name: "以太流操控", color: "B", cost: 1200, desc: "你可以感知和操控空气中的以太能量，用于强化身体、施放法术或驱动机械。", type: "exclusive"},
                    {name: "幸运七(Lucky Seven)", color: "S", cost: 4000, desc: "诺亚的魔剑。拔刀后拥有切断一切防御的能力，甚至能切断次元，概率即死。", type: "exclusive"},
                    {name: "海恩塔皇族血统", color: "A", cost: 1800, desc: "头顶长有翅膀的长寿种族。拥有极高的以太亲和力，擅长魔法，但有着变成泰坦怪物的基因诅咒。", type: "exclusive"},
                    {name: "取消攻击", color: "B", cost: 600, desc: "在攻击命中的瞬间发动下一个技能，消除后摇并增加伤害。节奏感是战斗的关键。", type: "exclusive"},
                    {name: "路痴诅咒", color: "D", cost: 100, desc: "在这个立体地图极度复杂的世界，你永远找不到路。导航线会把你带进悬崖或死胡同。", type: "exclusive"}
                ]
            },
            {
                name: "369.战神 (God of War)",
                desc: "从希腊的奥林匹斯山到北欧的九界。这是一个神明残暴、凡人如蝼蚁的世界。斯巴达亡魂奎托斯用鲜血铺就了弑神之路，现在他带着儿子在北欧寻求安宁。",
                boss: "宙斯, 阿瑞斯, 奧丁, 索尔, 巴德尔",
                identities: [
                    { name: "斯巴达训练营的淘汰者", items: "断裂的木矛, 满背的鞭痕" },
                    { name: "米德加尔特的冻僵尸体", items: "破烂的皮毛, 一把生锈的斧头" },
                    { name: "赫尔海姆的游荡亡魂", items: "冰冷的锁链, 无尽的悔恨" },
                    { name: "阿斯加德的英灵殿侍从", items: "永远擦不完的酒杯, 听着英灵吹牛" },
                    { name: "辛德里作坊的扫地学徒", items: "矮人的铁锤(拿不动), 金属废料" }
                ],
                talents: [
                    {name: "斯巴达之怒(Spartan Rage)", color: "SS", cost: 9500, desc: "源自血脉深处的极致愤怒。开启后你将无视痛觉，力量与速度暴增，每一拳都能撼动山岳，甚至手撕神明。", type: "exclusive"},
                    {name: "神之血统(半神)", color: "SSS", cost: 38000, desc: "你是主神留下的私生子。拥有近乎永恒的寿命、极其强悍的肉体和某种特定的神权（如雷电、力量、速度）。", type: "exclusive"},
                    {name: "利维坦之斧(寒冰)", color: "S", cost: 4500, desc: "一把注入了冰霜之力的传奇战斧。投掷后可以随时召回手中，每一击都能冻结敌人。", type: "exclusive"},
                    {name: "混沌之刃(火焰)", color: "S", cost: 4800, desc: "连接着地狱锁链的双刀。攻击范围极大，附带原初之火，是杀戮与痛苦的象征，一旦拿起便难以放下。", type: "exclusive"},
                    {name: "密米尔的智慧", color: "S", cost: 3000, desc: "你拥有最聪明的人的头脑（或头颅）。知晓九界的一切秘密、弱点和传说，是完美的战术顾问。", type: "exclusive"},
                    {name: "阿特柔斯的语言天赋", color: "B", cost: 800, desc: "你能瞬间学会并解读任何古老的语言和符文，这是解开谜题和与古老生物沟通的关键。", type: "exclusive"},
                    {name: "矮人的锻造术", color: "A", cost: 2000, desc: "你掌握了布罗克和辛德里的手艺。可以利用稀有材料打造或强化神级装备，甚至能制作弑神武器。", type: "exclusive"},
                    {name: "女武神的双翼", color: "A", cost: 2500, desc: "获得瓦尔基里的羽翼。虽然不能长久飞行，但能进行极速冲刺和空中格挡，身法如电。", type: "exclusive"},
                    {name: "世界树之露", color: "B", cost: 1200, desc: "饮用后永久提升某项身体素质（力量、防御、运气等）。在这个世界，嗑药变强是常识。", type: "exclusive"},
                    {name: "盾牌反击(金钟罩)", color: "B", cost: 900, desc: "在攻击即将临身的瞬间举盾，不仅能无伤挡下攻击，还能制造冲击波弹飞周围的敌人。", type: "exclusive"},
                    {name: "复活石", color: "A", cost: 1500, desc: "一块刻有魔法符文的石头。当你倒下时，阿特柔斯（或队友）可以使用它让你满血复活一次。", type: "exclusive"},
                    {name: "奥丁的渡鸦眼", color: "C", cost: 400, desc: "你可以通过奥丁的渡鸦观察远处的情况，但要小心，奥丁也在通过它们注视着你。", type: "exclusive"},
                    {name: "QTE之王", color: "C", cost: 200, desc: "在处决敌人时，你的反应速度极快。总是能精准地按下提示键，以最残暴的方式撕碎敌人。", type: "exclusive"},
                    {name: "父慈子孝", color: "D", cost: 100, desc: "在这个世界，父子关系极其紧张。你总是会卷入弑父或杀子的悲剧宿命之中。", type: "exclusive"},
                    {name: "德罗普尼尔长矛", color: "S", cost: 4200, desc: "可以无限复制的长矛。投掷后刺入敌人体内，随后可以引爆，造成巨大的风属性伤害。", type: "exclusive"}
                ]
            },
            {
                name: "370.最后生还者 (The Last of Us)",
                desc: "虫草菌爆发后的末世。人类文明崩塌，感染者横行。比怪物更可怕的是幸存的人类。资源极度匮乏，每一颗子弹、每一块砖头都关乎生死。",
                boss: "巨无霸(Bloater), 鼠王(Rat King), 暴徒首领, 人性的黑暗",
                identities: [
                    { name: "隔离区的走私客马仔", items: "一把只有3发子弹的手枪, 伪造的配给卡" },
                    { name: "废弃地铁站的感染者(刚变异)", items: "撕裂的衣服, 仅存的一丝人类意识" },
                    { name: "火萤组织的底层哨兵", items: "损坏的对讲机, 一块狗牌" },
                    { name: "杰克逊定居点的巡逻员", items: "一把猎枪, 一匹老马" },
                    { name: "西雅图雨林的疤脸帮信徒", items: "一把弓箭, 脸上自残的伤疤" }
                ],
                talents: [
                    {name: "完全免疫体(艾莉)", color: "SSS", cost: 35000, desc: "你是奇迹。你的大脑与虫草菌共生，无论被咬多少次都不会变异。你的血是全人类的疫苗希望，也是各方争夺的目标。", type: "exclusive"},
                    {name: "聆听模式(Listen Mode)", color: "A", cost: 1800, desc: "通过极度的专注，你可以透过墙壁“听”到敌人的轮廓和动作。在潜行暗杀中，这就是透视挂。", type: "exclusive"},
                    {name: "板砖大师", color: "C", cost: 300, desc: "你投掷砖头和酒瓶的技术出神入化。必定能砸晕敌人，为你创造处决或逃跑的机会。板砖在手，天下我有。", type: "exclusive"},
                    {name: "乔尔的身手", color: "S", cost: 2800, desc: "老练幸存者的战斗本能。近战凶狠残暴，枪法精准，擅长利用环境处决敌人，为了生存不择手段。", type: "exclusive"},
                    {name: "手工达人", color: "B", cost: 600, desc: "你可以用剪刀、胶带和酒精快速制作医疗包、燃烧瓶和土制炸弹。变废为宝是末世生存的核心。", type: "exclusive"},
                    {name: "循声者伪装", color: "B", cost: 900, desc: "你掌握了模仿感染者叫声和行动的技巧，甚至能涂抹孢子在身上，短时间内混入感染者群中而不被发现。", type: "exclusive"},
                    {name: "艾比的肌肉", color: "A", cost: 1500, desc: "经过高强度的训练，你拥有了超越常人的力量和体格。近战肉搏能打爆感染者的头，抗击打能力极强。", type: "exclusive"},
                    {name: "弓箭精通", color: "B", cost: 800, desc: "在这个需要安静的世界，弓箭是最好的武器。你射得准，且能回收箭矢，杀人于无声。", type: "exclusive"},
                    {name: "孢子抗性(弱)", color: "C", cost: 400, desc: "你的肺部经过轻微变异，能在充满孢子的区域坚持更长时间才需要防毒面具，但仍会被咬伤感染。", type: "exclusive"},
                    {name: "拾荒者直觉", color: "C", cost: 200, desc: "你总能发现别人忽略的抽屉、柜子里的物资。在这个一颗螺丝都珍贵的世界，这是神技。", type: "exclusive"},
                    {name: "弹簧刀制作", color: "C", cost: 150, desc: "你擅长打磨简易刀具。虽然是一次性的，但它是暗杀循声者和打开隐藏门的唯一工具。", type: "exclusive"},
                    {name: "高尔夫球杆(噩梦)", color: "D", cost: 50, desc: "当你手持高尔夫球杆时，攻击力提升，但会引来极大的仇恨，并且容易引发悲剧性的复仇故事。", type: "exclusive"},
                    {name: "鼠王之力", color: "SS", cost: 8000, desc: "你融合了多种感染者的特征。力量巨大，且身体分离出的小感染者可以作为你的僚机。你是行走的生化灾难。", type: "exclusive"},
                    {name: "复仇的执念", color: "A", cost: 1200, desc: "当你的亲友被杀时，你进入修罗模式。不惜跨越半个美国也要追杀凶手，期间意志力和生存力大幅提升。", type: "exclusive"},
                    {name: "吉他演奏", color: "C", cost: 100, desc: "你会弹吉他。在绝望的末世旅途中，一首《Future Days》能抚慰心灵，恢复San值。", type: "exclusive"}
                ]
            },
                      {
                name: "371.神秘海域 (Uncharted)",
                desc: "现代世界的边缘，隐藏着无数失落的古文明宝藏。这里是探险家、雇佣兵和盗贼的乐园，充满了古老的机关、致命的诅咒和贪婪的人心。",
                boss: "佐兰·拉扎雷维奇, 拉夫·阿德勒, 娜汀·罗斯, 阿萨夫",
                identities: [
                    { name: "博物馆夜班保安", items: "一支快没电的手电筒, 一本关于海盗历史的廉价平装书" },
                    { name: "被黑吃黑的走私贩", items: "一把空弹夹的手枪, 一张只有一半的藏宝图复印件" },
                    { name: "考古学教授的各种倒霉助教", items: "一把磨损的考古铲, 满是泥土的笔记本" },
                    { name: "海岸线搜救队志愿者", items: "急救包, 信号枪" },
                    { name: "拍卖行清洁工", items: "一串万能钥匙, 一个不起眼的古董硬币" }
                ],
                talents: [
                    {name: "跑酷大师", color: "B", cost: 400, desc: "无论是在崩塌的遗迹还是飞驰的火车上，你都能如履平地。攀爬速度提升，且在此过程中几乎不会失手坠落。", type: "exclusive"},
                    {name: "内森的强运", color: "SS", cost: 8000, desc: "主角光环般的运气。当你失足坠崖时，总有一根树枝能挂住你；当你被包围时，地板总会恰好塌陷让你逃生。", type: "exclusive"},
                    {name: "古文明语言通晓", color: "C", cost: 150, desc: "你能瞬间解读大部分失落文明的文字和谜题，这是解开机关的关键。", type: "exclusive"},
                    {name: "神射手(手枪)", color: "A", cost: 600, desc: "在使用手枪时，你的精准度极高，能够轻易打爆远处的丙烷罐或敌人的头盔。", type: "exclusive"},
                    {name: "近身格斗术(街头)", color: "C", cost: 180, desc: "不讲武德的打法，擅长利用环境物体砸人，或者在潜行时从背后扭断敌人的脖子。", type: "exclusive"},
                    {name: "黄金之乡的诅咒", color: "S", cost: 1800, desc: "你携带埃尔多拉多的诅咒金币。虽然会让你变得暴躁且皮肤溃烂，但你获得了不死之身和恐怖的怪力。", type: "exclusive"},
                    {name: "香巴拉的树液", color: "A", cost: 1200, desc: "饮下这种蓝色树液，你的伤口会迅速愈合，体能大幅增强，但长期使用会导致理智丧失。", type: "exclusive"},
                    {name: "德雷克的笔记", color: "B", cost: 300, desc: "一本画满涂鸦的笔记本，里面记载了无数宝藏的线索和解谜提示，能让你少走弯路。", type: "exclusive"},
                    {name: "苏利文的口才", color: "C", cost: 120, desc: "你擅长用花言巧语化解危机，或者在讨价还价时占据上风。当然，主要是为了骗人。", type: "exclusive"},
                    {name: "载具驾驶精通", color: "C", cost: 160, desc: "从吉普车到水上摩托，甚至是武装直升机，你都能上手操作，虽然最后通常会坠毁。", type: "exclusive"},
                    {name: "第六感(危险)", color: "A", cost: 700, desc: "在陷阱触发或敌人偷袭的前一秒，你会感到背脊发凉，从而做出本能的闪避。", type: "exclusive"},
                    {name: "乌巴城的幻觉毒素", color: "S", cost: 1500, desc: "你掌握了提炼这种致幻剂的方法。能让敌人陷入最深层的恐惧中自相残杀。", type: "exclusive"},
                    {name: "海盗王的宝剑", color: "A", cost: 900, desc: "艾弗里的佩剑，锋利无比，且在与贪婪之人战斗时似乎更具威力。", type: "exclusive"},
                    {name: "再生能力(守护者)", color: "SS", cost: 7500, desc: "你获得了香巴拉守护者的体质，普通的子弹无法杀死你，只有爆炸或摧毁头部才能阻止你。", type: "exclusive"},
                    {name: "宝藏猎人的直觉", color: "SSS", cost: 12000, desc: "概念级能力。你不需要地图，直觉会指引你走向价值连城的宝物，或者……走向足以毁灭世界的灾难。", type: "exclusive"}
                ]
            },
            {
                name: "372.地平线：零之曙光 (Horizon)",
                desc: "旧文明毁灭千年后的地球，大自然重新接管了城市废墟，但主宰生态链的却是巨大的机械生物。原始部落与高科技遗物共存。",
                boss: "HADES(哈迪斯), 赫淮斯托斯, 泰达拉, 幽魂主宰",
                identities: [
                    { name: "诺拉族的被逐者", items: "一把粗糙的木弓, 三支燧石箭" },
                    { name: "卡尔加的采石工", items: "一把沉重的镐头, 几块劣质的太阳石" },
                    { name: "奥斯拉姆的废铁拾荒者", items: "一根撬棍, 一袋生锈的螺丝" },
                    { name: "巴努克的萨满学徒", items: "涂满蓝色颜料的兽皮, 一根能够发出微弱电火花的导线" },
                    { name: "旧日遗迹的探险者尸体", items: "一个早已没电的Focus, 一张发黄的旧世界照片" }
                ],
                talents: [
                    {name: "Focus(全息眼镜)", color: "S", cost: 1500, desc: "旧时代的个人终端。能扫描机械兽的弱点、路径，透视墙壁，并记录大量旧世界的数据。", type: "exclusive"},
                    {name: "覆盖指令(基础)", color: "B", cost: 500, desc: "你掌握了入侵机械生物核心的方法。可以将小型的观察者或昂步者转化为你的坐骑或盟友。", type: "exclusive"},
                    {name: "机械兽猎人", color: "C", cost: 180, desc: "你熟悉各种机械兽的习性，知道拆卸哪个零件能让它们瘫痪，或者哪里是它们的燃料罐。", type: "exclusive"},
                    {name: "神射手(弓箭)", color: "A", cost: 800, desc: "即使在高速移动中，你也能同时射出三支箭，精准命中机械兽微小的光学镜头。", type: "exclusive"},
                    {name: "织盾者战甲", color: "SS", cost: 8000, desc: "旧世界的终极单兵护甲。生成能量护盾吸收所有伤害，只要不被持续集火，你就是无敌的。", type: "exclusive"},
                    {name: "盖亚的祝福(克隆体)", color: "SSS", cost: 25000, desc: "你是伊丽莎白·索贝克的基因克隆体。拥有最高级别的生物识别权限，可以控制零之曙光计划的所有核心设施。", type: "exclusive"},
                    {name: "赛伦斯的知识", color: "A", cost: 1200, desc: "你拥有关于机械网络和旧日历史的渊博知识，擅长利用技术手段欺诈和操纵他人。", type: "exclusive"},
                    {name: "雷霆牙之心", color: "S", cost: 2200, desc: "你移植了雷霆牙的动力核心。拥有恐怖的爆发力，能使用重型武器如圆盘发射器而不感到吃力。", type: "exclusive"},
                    {name: "隐身猎手", color: "B", cost: 450, desc: "你擅长在草丛中隐匿气息，即使是机械兽的雷达也难以发现静止不动的你。", type: "exclusive"},
                    {name: "工匠大师", color: "C", cost: 160, desc: "你能利用机械兽的残骸现场制作陷阱、绊索和各种属性的箭矢。", type: "exclusive"},
                    {name: "法罗机器控制权", color: "SS", cost: 9000, desc: "你掌握了古代战车（死之信使/泰坦平台）的控制代码。能唤醒并指挥这些毁灭旧世界的恶魔。", type: "exclusive"},
                    {name: "巴努克萨满之歌", color: "A", cost: 1000, desc: "通过特殊的声波频率，你可以安抚发狂的机械兽，甚至在短时间内控制它们为你作战。", type: "exclusive"},
                    {name: "攀爬岩壁", color: "C", cost: 100, desc: "你的指力惊人，只要有凸起的地方，哪怕是悬崖峭壁或机械兽的长颈，你都能爬上去。", type: "exclusive"},
                    {name: "烈日鹰的视野", color: "B", cost: 350, desc: "你的视力极佳，能看清数公里外的动静，且在强光下不会眩晕。", type: "exclusive"},
                    {name: "劣化者病毒", color: "S", cost: 1800, desc: "你携带这种古老的黑客病毒。接触任何机械都会使其狂暴化并攻击周围的一切生物。", type: "exclusive"}
                ]
            },
            {
                name: "373.对马岛之魂 (Ghost of Tsushima)",
                desc: "13世纪末，蒙古帝国东征。对马岛陷入战火，武士的荣誉在残酷的战争面前显得苍白无力。为了保卫家园，必须化身为从冥府归来的战鬼。",
                boss: "赫通汗, 志村大人(理念冲突), 龙三",
                identities: [
                    { name: "落难的农民", items: "一把镰刀, 一袋大米" },
                    { name: "金田城的逃兵", items: "断裂的武士刀, 破损的具足" },
                    { name: "流浪的僧侣", items: "一串佛珠, 治疗用的草药包" },
                    { name: "海边的采珠女", items: "一把尖锐的剥贝刀, 潜水用的配重石" },
                    { name: "蒙古军营的苦力", items: "沉重的镣铐, 满身的鞭痕" }
                ],
                talents: [
                    {name: "境井家传刀", color: "A", cost: 1200, desc: "一把传世名刀。虽然有些磨损，但在你手中能发挥出斩断钢铁的威力，且对蒙古兵有威慑力。", type: "exclusive"},
                    {name: "战鬼架势", color: "SS", cost: 6000, desc: "当你无伤击杀数人后进入的恐怖状态。此时你的每一刀都是必杀，敌人会因恐惧而瘫软在地。", type: "exclusive"},
                    {name: "对峙(拔刀术)", color: "S", cost: 2500, desc: "极致的居合斩。在敌人攻击的一瞬间出刀，一击必杀，且能连续斩杀数名冲上来的敌人。", type: "exclusive"},
                    {name: "流水架势", color: "B", cost: 400, desc: "专为克制持盾敌人设计的剑术。如同流水般连绵不绝的重击，能轻易破开防御。", type: "exclusive"},
                    {name: "磐石架势", color: "B", cost: 400, desc: "克制剑客的基础架势。稳如磐石，刺击迅猛，能有效压制挥舞刀剑的敌人。", type: "exclusive"},
                    {name: "疾风架势", color: "B", cost: 400, desc: "克制长枪兵的架势。利用踢击和灵活的步法，让长兵器使用者无法近身。", type: "exclusive"},
                    {name: "月之架势", color: "B", cost: 400, desc: "克制狂暴兵的架势。包含旋转攻击和踢击，能打断大型敌人的攻势。", type: "exclusive"},
                    {name: "暗器精通(苦无/烟雾弹)", color: "C", cost: 200, desc: "你擅长使用各种卑鄙但有效的道具。苦无破防，烟雾弹隐身，为了胜利不择手段。", type: "exclusive"},
                    {name: "决心(复活)", color: "A", cost: 1500, desc: "只要你的意志（决心槽）未耗尽，即使受到致命伤也能瞬间站起来，并恢复部分体力。", type: "exclusive"},
                    {name: "神之引导(风)", color: "S", cost: 3000, desc: "风会为你指引方向。无论是寻找任务目标，还是发现隐藏的神社和温泉，风都知道答案。", type: "exclusive"},
                    {name: "天之一刀", color: "A", cost: 1800, desc: "传说中的绝技。快到看不见的斩击，无法被格挡，能对强敌造成巨大伤害。", type: "exclusive"},
                    {name: "怒之舞", color: "A", cost: 1800, desc: "如同鬼魅般的连续斩击，瞬间在战场上移动并斩杀三个目标。", type: "exclusive"},
                    {name: "紫电一闪", color: "B", cost: 600, desc: "在刀刃上缠绕火焰（需配合火油），能点燃敌人并造成恐慌。", type: "exclusive"},
                    {name: "百合子的毒术", color: "S", cost: 2200, desc: "你学会了制作致命的毒药和致幻剂。吹箭能让敌人吐血而亡或发狂攻击同伴。", type: "exclusive"},
                    {name: "境井仁的仁之道", color: "SSS", cost: 15000, desc: "你打破了武士的枷锁，融合了武士的技艺与战鬼的手段。你是对马岛的守护神，你的名字本身就是一种武器。", type: "exclusive"}
                ]
            },
            {
                name: "374.血源诅咒 (Bloodborne)",
                desc: "维多利亚风格的古都亚楠，因“血疗”而闻名，也因兽化病而堕落。古神在梦境中低语，猎人们在血月的夜晚展开无尽的狩猎。",
                boss: "第一猎人杰尔曼, 星辰钟塔的玛利亚, 孤儿科斯, 月之魔物",
                identities: [
                    { name: "外乡的绝症患者", items: "一封写着''寻找苍白之血''的字条, 满身的病痛" },
                    { name: "亚楠中心广场的暴徒", items: "一把火把, 一把生锈的干草叉" },
                    { name: "治愈教会的低级修士", items: "黑色的教会服饰, 一瓶浑浊的采血瓶" },
                    { name: "旧亚楠的幸存者", items: "防尘面罩, 几颗解毒药丸" },
                    { name: "该隐赫斯特的仆人", items: "一把贵族用的拆信刀, 擦得锃亮的银器" }
                ],
                talents: [
                    {name: "猎人印记", color: "S", cost: 2000, desc: "你与猎人梦境连接。死亡并非终结，你会从梦境中醒来。但这可能是一个更深层的噩梦。", type: "exclusive"},
                    {name: "锯肉刀(技巧)", color: "B", cost: 350, desc: "你熟练掌握变形武器的使用。锯齿对野兽有奇效，且能流畅地在长柄与短柄模式间切换攻击。", type: "exclusive"},
                    {name: "内脏暴击(陶氏)", color: "A", cost: 1200, desc: "在敌人攻击瞬间用枪反击使其失衡，然后徒手撕裂其内脏。能造成巨量伤害并恢复大量生命值。", type: "exclusive"},
                    {name: "虚血回复(Rally)", color: "A", cost: 1500, desc: "受到伤害后的短时间内，如果你能反击敌人，就能利用溅射的血液恢复刚才失去的生命值。鼓励进攻。", type: "exclusive"},
                    {name: "灵视(Insight)", color: "SS", cost: 5000, desc: "你看到了世界的真相。这让你能发现隐形的古神生物，但也让你更容易陷入疯狂（Frenzy）。", type: "exclusive"},
                    {name: "古神之血(输血)", color: "C", cost: 150, desc: "你接受了血疗。体质增强，伤病痊愈，但你对鲜血的渴望在增加，兽化的风险也在潜伏。", type: "exclusive"},
                    {name: "伊碧塔斯的预兆", color: "S", cost: 2500, desc: "你可以短暂召唤古神的触手进行攻击。这是接触奥术真理的证明。", type: "exclusive"},
                    {name: "老猎人的骨头", color: "B", cost: 800, desc: "使用后，你的闪避动作会变成瞬移般的残影，速度快到肉眼无法捕捉。", type: "exclusive"},
                    {name: "月光圣剑", color: "SS", cost: 7000, desc: "路德维希的导师。这把剑平时平平无奇，但注入奥术能量后会发出青绿色的月光，释放毁灭性的光波。", type: "exclusive"},
                    {name: "科斯寄生虫", color: "S", cost: 3000, desc: "必须配合“乳草”符文使用。你的手臂变成触手，攻击模式完全改变，充满未知的奥术力量。", type: "exclusive"},
                    {name: "兽化条纹", color: "A", cost: 1000, desc: "当你连续攻击时，兽性会觉醒。攻击力大幅提升，但防御力会大幅下降。这是一把双刃剑。", type: "exclusive"},
                    {name: "加农炮", color: "B", cost: 600, desc: "虽然消耗巨大的水银子弹，但这玩意儿一发就能把巨大的怪兽轰飞。这就是男人的浪漫。", type: "exclusive"},
                    {name: "星辰之瞳", color: "SSS", cost: 20000, desc: "你正在飞升成为幼年古神。你开始理解高维度的存在，能够操纵梦境和现实的边界。", type: "exclusive"},
                    {name: "该隐赫斯特的血刀", color: "A", cost: 1300, desc: "千阴武士刀。通过自残染血，刀刃会变形并造成极高的血质伤害，专杀猎人。", type: "exclusive"},
                    {name: "人偶的关怀", color: "C", cost: 100, desc: "在梦境中，无论你变成什么样，人偶都会温柔地对待你。这是你在这个疯狂世界唯一的心理慰藉。", type: "exclusive"}
                ]
            },
            {
                name: "375.黑暗之魂 (Dark Souls)",
                desc: "火之时代即将终结，世界被不死人的诅咒笼罩。罗德兰大陆上，昔日的神祗已经疯狂或离去，只有不死人还在为了传火或灭火而挣扎。",
                boss: "薪王葛温, 亚尔特留斯, 无名王者, 吞噬神明的艾尔德利奇",
                identities: [
                    { name: "不死院的囚徒", items: "折断的直剑, 一个写着不明文字的玩偶" },
                    { name: "底层下水道的弃尸", items: "满身的毒斑, 一块发霉的苔藓球" },
                    { name: "太阳教的狂信徒", items: "画着太阳的破盾, 一枚太阳徽章" },
                    { name: "彼海姆的魔法学徒", items: "一根断裂的法杖, 只能施放光亮术的卷轴" },
                    { name: "卡塔利纳的冒险者", items: "看起来像洋葱的头盔碎片, 一杯特殊的酒" }
                ],
                talents: [
                    {name: "黑暗之环(不死诅咒)", color: "S", cost: 2000, desc: "你无法真正死去。每次死亡都会在篝火处重生，但会失去所有灵魂，且逐渐活尸化，失去理智。", type: "exclusive"},
                    {name: "原素瓶", color: "A", cost: 1200, desc: "不死人的宝物。装有能在篝火处自动补充的金色液体，喝下后能瞬间恢复大量伤势。", type: "exclusive"},
                    {name: "翻滚无敌帧", color: "S", cost: 3000, desc: "这不科学，但很黑魂。你在翻滚的一瞬间是完全无敌的，可以穿过巨剑、龙息甚至魔法。", type: "exclusive"},
                    {name: "弹反(Parry)", color: "A", cost: 1500, desc: "在敌人攻击即将命中的瞬间挥动盾牌，将其攻击弹开并造成巨大的硬直，随后可以进行处决。", type: "exclusive"},
                    {name: "深渊漫步", color: "SS", cost: 6000, desc: "你拥有亚尔特留斯的戒指。可以在深渊中行走而不被吞噬，对深渊生物有特攻。", type: "exclusive"},
                    {name: "咒术之火", color: "B", cost: 500, desc: "不需要智力也不需要信仰，只要有手套就能使用的火焰魔法。简单粗暴，威力不俗。", type: "exclusive"},
                    {name: "雷枪", color: "A", cost: 1000, desc: "阳光战士的奇迹。投掷出一道金色的雷电长枪，对古龙和重甲敌人有极高的伤害。", type: "exclusive"},
                    {name: "哈维尔的戒指", color: "B", cost: 800, desc: "极大提升你的负重能力。让你能穿着像石头一样重的铠甲还能灵活翻滚。", type: "exclusive"},
                    {name: "人性", color: "C", cost: 200, desc: "黑色的精魂。捏碎它可以恢复肉身状态，提升抗性和物品掉落率，也是某种黑暗力量的源泉。", type: "exclusive"},
                    {name: "结晶魔法", color: "S", cost: 2500, desc: "白龙希斯研究的禁忌魔法。威力巨大但会降低最大法力值，且结晶媒介容易损坏。", type: "exclusive"},
                    {name: "狼骑士大剑", color: "A", cost: 1400, desc: "对深渊生物有额外伤害。可以使用特殊的战技，如狼跳斩和回旋斩。", type: "exclusive"},
                    {name: "王魂(碎片)", color: "SSS", cost: 30000, desc: "你拥有一部分最初的王魂（如死亡、生命、光）。这让你拥有成为薪王甚至超越神祗的潜质。", type: "exclusive"},
                    {name: "宝箱怪的伪装", color: "C", cost: 300, desc: "你可以伪装成一个宝箱。贪婪的冒险者靠近时，你可以一口咬掉他们的头。", type: "exclusive"},
                    {name: "红灵入侵", color: "A", cost: 1000, desc: "你可以使用红眼眸入侵其他世界（玩家或NPC）。杀死宿主可以获得人性和灵魂。", type: "exclusive"},
                    {name: "防火女的灵魂", color: "SS", cost: 5000, desc: "你可以强化原素瓶，甚至在某些条件下，你可以看到并终结火之时代。", type: "exclusive"}
                ]
            },
            {
                name: "376.艾尔登法环 (Elden Ring)",
                desc: "在“交界地”，艾尔登法环破碎，半神们为了争夺碎片发动了战争。作为“褪色者”，你被赐福指引，重返这片土地，目标是成为艾尔登之王。",
                boss: "女武神玛莲妮亚, 碎星拉塔恩, 黑剑玛利喀斯, 拉达冈/艾尔登之兽",
                identities: [
                    { name: "漂流墓地的无名尸体", items: "一根指头圣印记(断裂), 褪色的记忆" },
                    { name: "史东薇尔城的扫地僧", items: "一把普通的扫帚, 偷偷藏起来的葛瑞克士兵头盔" },
                    { name: "雷亚卢卡利亚学院的辍学生", items: "辉石魔砾卷轴, 傻笑的面具" },
                    { name: "盖利德的腐败幸存者", items: "满身的猩红腐败脓包, 一把匕首" },
                    { name: "火山官邸的仆从", items: "拷问器具, 对大蛇的恐惧" }
                ],
                talents: [
                    {name: "赐福的指引", color: "S", cost: 2000, desc: "金色的光芒会为你指引主线方向。你可以在赐福点休息、升级、调整时间。你是被选中的人。", type: "exclusive"},
                    {name: "灵马托雷特", color: "A", cost: 1500, desc: "一匹可以凭空召唤的幽灵马。能在险峻的地形二段跳，是你在这个巨大世界探索的唯一依靠。", type: "exclusive"},
                    {name: "骨灰召唤(仿身泪滴)", color: "SS", cost: 8000, desc: "消耗生命值召唤一个和你一模一样的分身。它会使用你所有的装备和技能，甚至比你更肉。", type: "exclusive"},
                    {name: "战灰系统", color: "B", cost: 600, desc: "你可以随意更换武器的战技和属性质变。让一把大剑拥有滑步，或者让匕首释放重力波。", type: "exclusive"},
                    {name: "名刀月隐", color: "S", cost: 3500, desc: "法师梦寐以求的太刀。战技“隙间月影”出招极快，光波伤害高且削韧极强，专治各种多动症。", type: "exclusive"},
                    {name: "猩红腐败(抗性/释放)", color: "SS", cost: 7000, desc: "这种恐怖的真菌病毒能腐蚀半神。你对其有极高抗性，甚至能使用腐败吐息攻击敌人。", type: "exclusive"},
                    {name: "彗星亚兹勒", color: "S", cost: 3000, desc: "传说中的激流魔法。只要蓝量够，能在几秒钟内蒸发Boss的血条，俗称“龟派气功”。", type: "exclusive"},
                    {name: "亵渎圣剑", color: "A", cost: 2500, desc: "火山大蛇的遗物。战技“掠夺火焰”能吸取敌人的生命值，推图神器。", type: "exclusive"},
                    {name: "命定之死", color: "SSS", cost: 15000, desc: "黑剑的力量。你的攻击会减少敌人生命上限并持续扣血。这是连神都能杀死的火焰。", type: "exclusive"},
                    {name: "猎犬步法", color: "A", cost: 1200, desc: "短暂的隐身瞬移。无敌帧极长，机动性极高，能让你像鬼魅一样戏耍敌人。", type: "exclusive"},
                    {name: "大卢恩", color: "SS", cost: 5000, desc: "击败半神获得的法环碎片。激活后能提供巨大的属性加成，是成王的证明。", type: "exclusive"},
                    {name: "癫火", color: "S", cost: 4000, desc: "混乱与疯狂的火焰。能从眼睛射出激光，虽然会让自己发狂，但威力惊人，且能烧毁黄金树。", type: "exclusive"},
                    {name: "死眠少女的拥抱", color: "C", cost: 100, desc: "这很温暖，但会扣除你5%的生命上限。除此之外，也许能开启某些隐藏剧情。", type: "exclusive"},
                    {name: "壶战士的友谊", color: "B", cost: 300, desc: "你和亚历山大是好兄弟。他会在关键时刻帮你打架，甚至把他身体里的内容物送给你。", type: "exclusive"},
                    {name: "星星时代", color: "SSS", cost: 20000, desc: "你选择了菈妮。开启群星时代，让黄金律法终结。你将与暗月公主一起踏上千年的星空旅程。", type: "exclusive"}
                ]
            },
            {
                name: "377.只狼：影逝二度 (Sekiro)",
                desc: "日本战国末期，苇名国。剑圣苇名一心病重，内忧外患。独臂忍者“狼”为了营救拥有“龙胤”血统的主人九郎，踏上了斩断不死的修罗之路。",
                boss: "剑圣苇名一心, 怨恨之鬼, 义父(枭), 樱龙",
                identities: [
                    { name: "苇名城的杂兵", items: "一把破斗笠, 一把容易折断的太刀" },
                    { name: "仙峰寺的扫地僧", items: "一根木棍, 一本看不懂的经书" },
                    { name: "坠落之谷的猴子", items: "一把偷来的火枪, 一颗柿子" },
                    { name: "平田宅邸的家仆", items: "一个灭火用的水桶, 一把扫帚" },
                    { name: "地牢里的实验体", items: "变红的眼睛, 疯狂的低语" }
                ],
                talents: [
                    {name: "龙胤之力(回生)", color: "S", cost: 3000, desc: "你死后可以原地复活一次。这是不死的诅咒，代价是周围的人会患上龙咳病。", type: "exclusive"},
                    {name: "忍义手", color: "A", cost: 1500, desc: "多功能的机械义肢。可以安装手里剑、斧头、喷火筒、鞭炮、雨伞盾等多种忍具。", type: "exclusive"},
                    {name: "完美弹刀(打铁)", color: "SS", cost: 5000, desc: "不论对方是人是鬼是神，只要有实体攻击，你都能用刀完美格挡，积累对方的躯干值进行忍杀。", type: "exclusive"},
                    {name: "识破(看破)", color: "A", cost: 1000, desc: "针对突刺攻击的绝技。一脚踩住敌人的兵器，造成巨大躯干伤害，极具侮辱性。", type: "exclusive"},
                    {name: "雷电奉还", color: "S", cost: 2500, desc: "面对雷电攻击时，跳起接雷并在落地前反打回去。专治各种玩雷的BOSS。", type: "exclusive"},
                    {name: "不死斩(拜泪)", color: "SS", cost: 6000, desc: "红色的太刀。能杀死虫附体等不死生物，释放出的剑气（奥义·不死斩）威力惊人。", type: "exclusive"},
                    {name: "苇名流剑法", color: "B", cost: 600, desc: "登峰造极的斩击技艺。包括一文字斩、十字斩等，讲究快、准、狠。", type: "exclusive"},
                    {name: "仙峰寺拳法", color: "B", cost: 500, desc: "配合糖果使用的体术。能通过叩拜和腿法积攒功德（金钱和道具率）。", type: "exclusive"},
                    {name: "雾鸦羽毛", color: "A", cost: 900, desc: "忍具之一。受到攻击时化作羽毛消失并移动到任意方向，完美的保命和反击手段。", type: "exclusive"},
                    {name: "修罗化", color: "SSS", cost: 12000, desc: "你杀戮过多，被怨恨之火吞噬。虽然失去了理智，但获得了焚烧一切的业火力量。", type: "exclusive"},
                    {name: "钩绳", color: "C", cost: 200, desc: "义手功能。能让你在屋顶、树枝间飞檐走壁，机动性拉满。", type: "exclusive"},
                    {name: "从天而降的忍杀", color: "B", cost: 400, desc: "只要你在敌人上方且未被发现，无论多强的敌人（非BOSS），都能一击必杀。", type: "exclusive"},
                    {name: "夜叉戮糖", color: "A", cost: 800, desc: "大幅提升攻击力，但生命值减半。不是你死就是我亡的拼命道具。", type: "exclusive"},
                    {name: "源之宫的笛声", color: "S", cost: 2000, desc: "能吸取敌人的精气（年岁），使其变得衰老无力。对非人类生物无效。", type: "exclusive"},
                    {name: "米娘的萩饼", color: "C", cost: 50, desc: "虽然只是普通的食物，但这是变若之子亲手做的，充满了温暖的心意，能缓慢回血。", type: "exclusive"}
                ]
            },
            {
                name: "378.光环 (Halo)",
                desc: "26世纪，人类与名为“星盟”的外星宗教联盟爆发星际战争。为了生存，也是为了解开神秘环状人造天体“Halo”的秘密，士官长挺身而出。",
                boss: "悲怆先知, 塔塔罗斯, 尸脑兽(Gravemind), 343罪恶火花",
                identities: [
                    { name: "UNSC陆战队炮灰", items: "MA5突击步枪, 几个随时会用完的弹夹" },
                    { name: "致远星的平民", items: "一张撤离飞船的船票(已过期), 家人的照片" },
                    { name: "星盟咕噜人(Unggoy)", items: "等离子手枪, 甲烷呼吸背罐" },
                    { name: "ODST空降兵", items: "消音冲锋枪, 漆黑的单兵空降舱" },
                    { name: "被遗弃的AI碎片", items: "损坏的数据芯片, 疯狂的逻辑循环" }
                ],
                talents: [
                    {name: "斯巴达二期强化", color: "SS", cost: 8000, desc: "骨骼陶瓷化、肌肉密度增强、反应速度如闪电。你是人类最完美的战争机器。", type: "exclusive"},
                    {name: "雷神锤动力甲(MJOLNIR)", color: "S", cost: 5000, desc: "提供能量护盾、力量增幅和HUD界面。只有斯巴达战士才能穿戴，普通人穿上会骨折。", type: "exclusive"},
                    {name: "Cortana(AI伴侣)", color: "SS", cost: 7000, desc: "最先进的智能AI。能骇入任何外星系统，为你提供战术分析，还能陪你聊天解闷。", type: "exclusive"},
                    {name: "能量护盾", color: "A", cost: 1500, desc: "星盟科技。能吸收一定量的伤害，破盾后需找掩体恢复。是生存的关键。", type: "exclusive"},
                    {name: "能量剑精通", color: "A", cost: 1200, desc: "星盟精英的标志性武器。一击必杀的近战突刺，配合隐身装置更是恐怖。", type: "exclusive"},
                    {name: "洪魔感染体质", color: "SSS", cost: 15000, desc: "你成为了尸脑兽的一部分或拥有了控制洪魔的能力。能同化任何有机生物，拥有蜂巢意识。", type: "exclusive"},
                    {name: "先行者科技权限", color: "S", cost: 4000, desc: "被系统识别为“回收者”。你可以操作光环、方舟等先行者超级武器。", type: "exclusive"},
                    {name: "疣猪号驾驶", color: "B", cost: 500, desc: "无论地形多烂，你都能开着这辆越野车漂移，并且让机枪手有稳定的射击角度。", type: "exclusive"},
                    {name: "双持武器", color: "B", cost: 600, desc: "你可以双手各持一把轻型武器（如冲锋枪或等离子步枪），火力加倍，但无法扔雷。", type: "exclusive"},
                    {name: "重力锤", color: "A", cost: 1800, desc: "鬼面兽的武器。一锤下去能产生重力波，把载具都掀翻。近战霸主。", type: "exclusive"},
                    {name: "针刺枪(追踪)", color: "B", cost: 700, desc: "发射粉红色的追踪晶体。打在敌人身上积累到一定数量会发生超级爆炸。", type: "exclusive"},
                    {name: "隐身迷彩", color: "A", cost: 1300, desc: "光学迷彩球。使用后短时间内完全隐身，适合潜入或逃命。", type: "exclusive"},
                    {name: "ODST空降技术", color: "C", cost: 300, desc: "地狱伞兵的绝活。哪怕是从轨道直接空投到战场中心，你也能活着钻出空降舱。", type: "exclusive"},
                    {name: "星盟护盾发生器", color: "B", cost: 900, desc: "便携式掩体。扔在地上生成一个半圆形的能量盾，关键时刻能救命。", type: "exclusive"},
                    {name: "运气(士官长)", color: "SSS", cost: 10000, desc: "正如Cortana所说，你和其他斯巴达最大的区别就是运气。这在战场上比什么都重要。", type: "exclusive"}
                ]
            },
            {
                name: "379.战争机器 (Gears of War)",
                desc: "锡拉星上，人类为了争夺伊姆能源打了79年，结果地底冒出了名为“兽族”的怪物。事变日后，人类文明濒临灭绝，只剩下肌肉猛男和电锯枪。",
                boss: "兰姆将军, 司寇将军, 米拉女王, 荧光兽利维坦",
                identities: [
                    { name: "刚入伍的维安士兵", items: "一把卡壳的骑兵步枪, 狗牌" },
                    { name: "被遗忘的游民(Stranded)", items: "一把短管散弹枪, 一罐过期的豆子" },
                    { name: "兽族苦工", items: "一把手枪, 随时准备自爆的疯狂" },
                    { name: "贾克机器人的维修工", items: "焊枪, 备用电池" },
                    { name: "E-Day幸存者", items: "全家福照片, 对地底的恐惧" }
                ],
                talents: [
                    {name: "骑兵突击步枪(电锯)", color: "A", cost: 1200, desc: "链锯枪。不仅是优秀的步枪，近战时启动链锯能直接将兽族锯成两半，血腥且解压。", type: "exclusive"},
                    {name: "完美上弹(Active Reload)", color: "S", cost: 2000, desc: "在换弹时精准卡点，不仅换弹速度极快，还能让这一梭子子弹的伤害大幅提升。", type: "exclusive"},
                    {name: "掩体滑行", color: "B", cost: 600, desc: "你可以像磁铁一样吸附在掩体上，并在掩体间快速滑行移动。这是在这场战争活下来的基础。", type: "exclusive"},
                    {name: "黎明之锤", color: "SS", cost: 6000, desc: "卫星轨道激光武器。需要在露天使用，定位后降下毁灭性的光柱，能烧尽一切，包括巨大的钻地兽。", type: "exclusive"},
                    {name: "纳什散弹枪", color: "A", cost: 1000, desc: "近战神器。一枪就能把兽族轰成碎肉。虽然射程短，但在掩体战中是无敌的存在。", type: "exclusive"},
                    {name: "兽族血统", color: "B", cost: 800, desc: "你的皮肤更坚硬，力量更大，能在地底环境中看清东西，还能听懂兽族的语言。", type: "exclusive"},
                    {name: "机械弓", color: "A", cost: 1500, desc: "发射带有高爆弹头的箭矢。蓄力后精准度极高，射中后延迟爆炸，专治躲在掩体后的敌人。", type: "exclusive"},
                    {name: "维安政府战士体质", color: "B", cost: 500, desc: "这里的战士脖子比大腿粗。你拥有极其夸张的肌肉力量，能穿着重甲狂奔，被子弹打中也像没事一样。", type: "exclusive"},
                    {name: "倒地复活", color: "C", cost: 200, desc: "只要不被处决或炸碎，倒地后队友摸一下就能满血复活。甚至可以自己爬到安全地方。", type: "exclusive"},
                    {name: "荧光族变异", color: "S", cost: 3000, desc: "被伊姆能源感染。死后会剧烈爆炸，平时攻击带有腐蚀性，但理智会逐渐丧失。", type: "exclusive"},
                    {name: "布雷克手枪", color: "C", cost: 300, desc: "虽然是手枪，但威力堪比麦格农。不仅能爆头，还能当近战钝器砸碎脑袋。", type: "exclusive"},
                    {name: "兽族萨满咏唱", color: "A", cost: 1200, desc: "能治愈周围的兽族单位，甚至复活倒地的同伴。优先击杀目标。", type: "exclusive"},
                    {name: "巨龙兽骑乘", color: "SS", cost: 5000, desc: "你可以驯服并骑乘这种巨大的飞行怪兽，在这个充满硝烟的天空中成为霸主。", type: "exclusive"},
                    {name: "马库斯的头巾", color: "C", cost: 50, desc: "戴上它，你说话的声音会变得沙哑低沉，且对脏话的词汇量大幅增加。", type: "exclusive"},
                    {name: "多姆的牺牲", color: "SSS", cost: 10000, desc: "为了拯救队友，你愿意驾驶卡车撞向油罐。这种绝对的牺牲精神会触发奇迹，逆转必死的战局。", type: "exclusive"}
                ]
            },
            {
                name: "380.刺客信条 (Assassin''s Creed)",
                desc: "历史是他们的游乐场。刺客兄弟会与圣殿骑士团跨越千年的暗战。万物皆虚，万事皆允。通过Animus，你将重温祖先的记忆。",
                boss: "罗德里戈·波吉亚, 查尔斯·李, 海尔森·肯威, 沃伦·韦迪克",
                identities: [
                    { name: "Abstergo公司的保洁员", items: "门禁卡, 拖把" },
                    { name: "文艺复兴时期的乞丐", items: "破碗, 几枚弗罗林金币" },
                    { name: "加勒比海的醉酒水手", items: "朗姆酒瓶, 弯刀" },
                    { name: "法国大革命的暴徒", items: "三色旗, 干草叉" },
                    { name: "古埃及的奴隶", items: "莎草纸, 简陋的石器" }
                ],
                talents: [
                    {name: "袖剑(Hidden Blade)", color: "A", cost: 1200, desc: "刺客的标志。藏在手腕下的利刃，杀人于无形。也是断指仪式的象征（早期）。", type: "exclusive"},
                    {name: "信仰之跃", color: "B", cost: 500, desc: "无论多高，只要下面有稻草堆、树叶堆或水面，你跳下去就毫发无伤。物理学的奇迹。", type: "exclusive"},
                    {name: "鹰眼视觉", color: "S", cost: 2500, desc: "特殊的第六感。能高亮显示敌人（红）、盟友（蓝）和目标（金）。能看穿伪装和隐藏的痕迹。", type: "exclusive"},
                    {name: "伊甸碎片(金苹果)", color: "SSS", cost: 20000, desc: "先行者的神器。能控制人心、制造幻象、发射能量波，甚至改写现实。拥有它就拥有统治世界的力量。", type: "exclusive"},
                    {name: "混入人群", color: "C", cost: 200, desc: "只要周围有三个以上的人，你就能完美融入其中，让追兵瞬间丢失目标。", type: "exclusive"},
                    {name: "狂战士吹箭", color: "A", cost: 800, desc: "让敌人陷入疯狂，攻击周围的一切。制造混乱的最佳工具，你可以趁机溜走或看戏。", type: "exclusive"},
                    {name: "达芬奇的飞行器", color: "B", cost: 1000, desc: "简易的滑翔翼。虽然需要利用火堆的热气流上升，但能让你在文艺复兴的空中翱翔。", type: "exclusive"},
                    {name: "寒鸦号(战船)", color: "SS", cost: 6000, desc: "一艘全副武装的双桅横帆船。拥有侧舷炮、迫击炮和撞角。你是加勒比海的无冕之王。", type: "exclusive"},
                    {name: "刺客大师套装", color: "A", cost: 1500, desc: "轻便且防御力不俗的兜帽装。增加潜行能力，且看起来非常帅气。", type: "exclusive"},
                    {name: "连杀系统", color: "S", cost: 1800, desc: "一旦你成功反杀一人，接下来的攻击都是一击必杀的处决动画，直到没人敢靠近你。", type: "exclusive"},
                    {name: "Animus同步率", color: "C", cost: 100, desc: "你与祖先的同步率越高，能解锁的记忆和技能就越多。但也容易产生出血效应。", type: "exclusive"},
                    {name: "先行者血统", color: "SS", cost: 5000, desc: "你拥有高浓度的伊苏人DNA。天生拥有鹰眼，且能抵抗伊甸碎片的精神控制。", type: "exclusive"},
                    {name: "斯巴达踢", color: "B", cost: 600, desc: "这不刺客，但这很斯巴达。一脚把人踹飞几米远，高处地形杀的神技。", type: "exclusive"},
                    {name: "绳枪", color: "B", cost: 400, desc: "工业革命的产物。能让你瞬间拉上屋顶，极大提升跑酷效率。", type: "exclusive"},
                    {name: "兄弟会召唤", color: "A", cost: 1200, desc: "吹个口哨，一群刺客小弟就会从天而降帮你解决敌人，或者制造骚乱掩护你。", type: "exclusive"}
                ]
            },
          {
    name: "381.侠盗猎车手 (GTA)",
    desc: "一个充满了讽刺、犯罪与金钱的现代都市开放世界。在这里，法律只是建议，只有火力与美金才是硬道理。洛圣都的阳光下掩盖着无数肮脏的交易。",
    boss: "FIB腐败探员, 德温·维斯顿, 埃文·赫兹, 军队",
    identities: [
        { name: "贫民窟帮派混混", items: "一把磨损的手枪, 一袋劣质毒品, 一辆甚至打不着火的自行车" },
        { name: "好麦坞过气演员", items: "一瓶抗抑郁药, 一本没人看的剧本, 欠债的信用卡" },
        { name: "码头走私工人", items: "一把撬棍, 一个装有走私名表的背包, 叉车驾驶证" },
        { name: "落魄的前银行劫匪", items: "一个破旧的面具, 一把未装弹的霰弹枪, 过去的辉煌回忆" },
        { name: "FIB底层线人", items: "一支录音笔, 随时会被出卖的恐惧, 一辆不起眼的轿车" }
    ],
    talents: [
        {name: "通缉等级(五星)", color: "E", cost: 10, desc: "【致命诅咒】你进入世界时即背负五星通缉。全城的警察、特警、甚至军队都在追杀你，坦克和直升机将是你的见面礼。", type: "exclusive"},
        {name: "路怒症", color: "D", cost: 80, desc: "你驾驶时极易被激怒，不仅会疯狂按喇叭，还有大概率直接掏枪射击其他司机，引来不必要的麻烦。", type: "exclusive"},
        {name: "载具直觉", color: "C", cost: 150, desc: "你不需要钥匙就能通过接线启动大部分普通车辆，偷车对你来说就像开自家门一样简单。", type: "exclusive"},
        {name: "好麦坞人脉", color: "C", cost: 180, desc: "你认识一些娱乐圈的人，可以通过他们洗白少量的黑钱，或者进入一些高端派对。", type: "exclusive"},
        {name: "专业车手", color: "B", cost: 500, desc: "无论是超跑还是垃圾车，在你手里都能开出F1的感觉。你能在高速逆行中完美避开所有车辆。", type: "exclusive"},
        {name: "武器专家(重型)", color: "B", cost: 650, desc: "你精通加特林、RPG等重型武器的使用，能最大限度地发挥火力和压制力，且移动惩罚降低。", type: "exclusive"},
        {name: "飞行执照(军用)", color: "A", cost: 1200, desc: "你不仅会开飞机，还能熟练驾驶战斗机和武装直升机，进行精确的空中打击和特技飞行。", type: "exclusive"},
        {name: "子弹时间(驾驶)", color: "A", cost: 1500, desc: "富兰克林的特殊能力。在驾驶载具时，你可以让时间变慢，从而在极限车流中穿梭或进行精确射击。", type: "exclusive"},
        {name: "狂暴模式", color: "S", cost: 1800, desc: "崔佛的特殊能力。激活后，你受到的伤害大幅降低，造成的伤害大幅提升，进入一种不可阻挡的杀戮状态。", type: "exclusive"},
        {name: "莱斯特的联络方式", color: "S", cost: 1900, desc: "你可以随时联系这位策划大师。他能帮你消除通缉星级、定位目标位置，甚至策划完美的抢劫方案。", type: "exclusive"},
        {name: "暴君Mk2(召唤权)", color: "SS", cost: 5500, desc: "你可以召唤一辆配备追踪导弹的飞行摩托。它是洛圣都天空的恶霸，但这会让你成为全图玩家的公敌。", type: "exclusive"},
        {name: "天基炮打击", color: "SS", cost: 8000, desc: "你拥有一次性使用轨道炮打击地面任意目标的权限。无法躲避，无法防御，纯粹的毁灭。", type: "exclusive"},
        {name: "无限复活(被动模式)", color: "SS", cost: 9500, desc: "你在非攻击状态下可以进入虚化状态，免疫所有物理和爆炸伤害，但同时也无法攻击他人。", type: "exclusive"},
        {name: "HESOYAM(作弊码)", color: "SSS", cost: 25000, desc: "传说中的咒语。咏唱后瞬间恢复满生命、满护甲，并获得25万美元现金，且修复当前载具。冷却时间极长。", type: "exclusive"},
        {name: "导演模式", color: "SSS", cost: 40000, desc: "你获得了修改世界参数的权限。你可以改变天气、重力、行人行为，甚至让自己无敌或拥有爆炸子弹。", type: "exclusive"}
    ]
},
{
    name: "382.荒野大镖客 (Red Dead Redemption)",
    desc: "1899年的美国，蛮荒的西部时代迎来了黄昏。工业文明的铁蹄正在碾碎旧时代的亡命之徒。这是关于救赎、忠诚与背叛的悲歌。",
    boss: "迈卡·贝尔, 平克顿侦探事务所, 达奇(崩溃版), 联邦军队",
    identities: [
        { name: "即将被绞死的囚犯", items: "一套囚服, 脖子上勒得死紧的麻绳" },
        { name: "瓦伦丁的马厩帮工", items: "一把草叉, 一身马粪味, 几个烂苹果" },
        { name: "被抢劫的倒霉旅人", items: "被洗劫一空的马车, 一件破损的西装, 一张借据" },
        { name: "奥德里斯科帮派的炮灰", items: "一把卡壳的左轮, 一瓶劣质威士忌, 随时会被亚瑟爆头的命运" },
        { name: "沼泽地的夜行者", items: "脸上涂满白灰, 一把生锈的砍刀, 诡异的口哨声" }
    ],
    talents: [
        {name: "肺结核(晚期)", color: "E", cost: 20, desc: "【致命诅咒】你的肺部已经严重感染。体力上限减半，剧烈运动会咳血，生命正在倒计时。", type: "exclusive"},
        {name: "通缉(死活不论)", color: "D", cost: 100, desc: "你的赏金高达5000美元。赏金猎人会源源不断地追杀你，城镇对你关闭大门。", type: "exclusive"},
        {name: "牛仔体魄", color: "C", cost: 160, desc: "适应了风餐露宿的生活。你对寒冷和炎热的抗性提高，能够长时间骑马而不感到疲惫。", type: "exclusive"},
        {name: "赌徒运气", color: "C", cost: 180, desc: "你在打德州扑克或21点时运气极佳，总能摸到关键牌，是赚取旅费的好手段。", type: "exclusive"},
        {name: "马术大师", color: "B", cost: 400, desc: "任何马匹在你胯下都能发挥出120%的速度和耐力。你可以进行急转弯、急停和马上射击等高难度动作。", type: "exclusive"},
        {name: "草药大师", color: "B", cost: 450, desc: "你能识别所有西部植物。制作的强效补剂能瞬间恢复生命、体力和死神之眼，效果翻倍。", type: "exclusive"},
        {name: "双枪游侠", color: "A", cost: 800, desc: "你精通双持左轮射击，射速极快且精度不减。在近距离交火中，你就是一台绞肉机。", type: "exclusive"},
        {name: "传说动物猎手", color: "A", cost: 900, desc: "你对顶级掠食者有特殊的感知。猎杀传说动物后，你可以利用其皮毛制作拥有特殊属性加成的装备。", type: "exclusive"},
        {name: "死神之眼(初级)", color: "S", cost: 1800, desc: "时间在你眼中变慢。你可以标记多个目标，然后在一瞬间连续射击，百发百中。", type: "exclusive"},
        {name: "帮派领袖魅力", color: "S", cost: 2000, desc: "类似达奇的演讲能力。你能轻易煽动人心，让追随者为你赴汤蹈火，哪怕那是“最后一次计划”。", type: "exclusive"},
        {name: "死神之眼(完全体)", color: "SS", cost: 6000, desc: "不仅能减缓时间，还能看到敌人身上的弱点（心脏、大脑）。每一枪都是必定暴击的致死打击。", type: "exclusive"},
        {name: "亚瑟的日记本", color: "SS", cost: 7500, desc: "这不仅是一本日记，它记录了这一路的人性光辉。持有者能极大提升NPC的好感度，甚至感化反派。", type: "exclusive"},
        {name: "荣誉值系统(具现)", color: "SS", cost: 8500, desc: "你的行为会直接影响世界反馈。高荣誉值让你受到神佑（子弹避开要害），低荣誉值让你攻击附带恐怖的威慑力。", type: "exclusive"},
        {name: "西部传说(套装)", color: "SSS", cost: 15000, desc: "完成了所有挑战后的终极奖励。全属性大幅提升，免疫大部分环境伤害，你是这片土地真正的传说。", type: "exclusive"},
        {name: "时代洪流(工业化)", color: "SSS", cost: 20000, desc: "你掌握了超越时代的工业力量。你可以提前在这个西部世界部署马克沁机枪阵地甚至装甲车，碾压旧时代的战术。", type: "exclusive"}
    ]
},
{
    name: "383.赛博朋克2077",
    desc: "2077年的夜之城，高科技与低生活的结合体。巨型企业掌控一切，街头充满了赛博疯子。在这里，不仅要活下去，还要活得像个传奇。",
    boss: "亚当·重锤, 荒坂三郎(意识体), 军用科技高层, 赛博精神病(完全体)",
    identities: [
        { name: "清道夫手中的肉票", items: "被摘除义眼的空眼眶, 冰浴缸, 一身血迹" },
        { name: "流浪者家族的弃子", items: "一辆报废的雷霆车, 一把自制手枪, 荒野的尘土" },
        { name: "公司底层的加班狗", items: "严重过劳的神经系统, 随时会被远程关闭的义体, 巨额债务" },
        { name: "街头混混", items: "一把螳螂刀(劣质版), 一包合成兴奋剂, 帮派涂鸦罐" },
        { name: "超梦体验剪辑师", items: "一台便携式超梦编辑台, 几个非法黑超梦, 严重的电子眼疲劳" }
    ],
    talents: [
        {name: "赛博精神病(潜伏)", color: "E", cost: 150, desc: "【致命诅咒】你的义体负荷已达极限。每当情绪激动或战斗时，都有概率失去理智，无差别攻击周围一切。", type: "exclusive"},
        {name: "排异反应", color: "D", cost: 120, desc: "你的身体对义体适应性极差。安装任何义体都会导致持续的疼痛和属性下降，且无法使用高级义体。", type: "exclusive"},
        {name: "街头黑客", color: "C", cost: 180, desc: "掌握基础的快速破解。可以远程干扰敌人的视觉、过载他们的武器或打开简单的电子门锁。", type: "exclusive"},
        {name: "冷血", color: "C", cost: 190, desc: "杀戮让你冷静。每击杀一名敌人，你的移动速度和护甲都会短暂提升，可叠加。", type: "exclusive"},
        {name: "技术专家", color: "B", cost: 550, desc: "你可以制作史诗级武器和装备，并能从废料中回收高级组件。科技武器在你手中能穿墙击杀。", type: "exclusive"},
        {name: "二段跳(强化肌腱)", color: "B", cost: 600, desc: "腿部义体改造。你可以进行空中跳跃，到达常人无法企及的高度，或在战斗中灵活走位。", type: "exclusive"},
        {name: "螳螂刀(传说)", color: "A", cost: 1200, desc: "手臂内置的致命折叠刀刃。攻速极快，附带热能伤害，且能进行长距离的飞扑处决。", type: "exclusive"},
        {name: "单分子线", color: "A", cost: 1250, desc: "看似细线，实则能切割分子。攻击范围极大，能悄无声息地肢解成群的敌人。", type: "exclusive"},
        {name: "斯安威斯坦(千替4型)", color: "S", cost: 2500, desc: "脊柱植入体。激活后，你的时间感官加速至极致（子弹时间），在敌人眼中你就是一道残影。", type: "exclusive"},
        {name: "网络接入仓(四相涟漪)", color: "S", cost: 2800, desc: "顶级的黑客设备。你可以让整个建筑的敌人瞬间自杀、义体过热或视觉重启，赛博法师的标配。", type: "exclusive"},
        {name: "强尼·银手的记忆", color: "SS", cost: 6000, desc: "你的脑子里住着一个摇滚恐怖分子。虽然他很吵，但他能接管你的身体进行战斗，并提供关于荒坂塔的绝密情报。", type: "exclusive"},
        {name: "Relic芯片(生物永生)", color: "SS", cost: 8500, desc: "虽然正在重写你的神经，但它也让你在受到致命伤时能够重启大脑。只要芯片不毁，你就很难彻底死亡。", type: "exclusive"},
        {name: "亚当·重锤的义体库", color: "SS", cost: 9000, desc: "你获得了全身96%的义体化改造权限且无精神病副作用。你是一辆人形坦克，也是噩梦的具象化。", type: "exclusive"},
        {name: "黑墙突破者", color: "SSS", cost: 30000, desc: "你能自由进出赛博空间的“黑墙”，操控那些被封印的流窜AI。你的黑客攻击附带即死效果，连荒坂的防火墙也如纸般脆弱。", type: "exclusive"},
        {name: "夜之城传奇", color: "SSS", cost: 35000, desc: "你在这个世界拥有绝对的声望。所有帮派敬畏你，公司试图拉拢你。你的名字本身就是一种货币，甚至能改写大公司的结局。", type: "exclusive"}
    ]
},
{
    name: "384.巫师3 (The Witcher)",
    desc: "一个怪物、魔法与政治阴谋交织的黑暗奇幻世界。天球交汇带来了异世界的魔物，猎魔人是为了赏金而猎杀怪物的变种人，但人心往往比怪物更险恶。",
    boss: "狂猎之王(艾瑞汀), 迪拉夫(高阶吸血鬼), 镜子大师(刚特·欧迪姆), 林中夫人",
    identities: [
        { name: "威伦的战乱孤儿", items: "一个被啃了一半的土豆, 躲避食尸鬼的藏身洞, 破烂的麻布衣" },
        { name: "诺维格瑞的乞丐", items: "一个破碗, 永恒之火教会的施舍券, 满身虱子" },
        { name: "史凯利格的落难水手", items: "一块浮木, 被塞壬抓伤的伤口, 冻僵的四肢" },
        { name: "凯尔莫罕的试炼失败者", items: "被青草试炼摧毁的身体, 一把未开刃的钢剑, 猎魔人的笔记" },
        { name: "尼弗迦德逃兵", items: "被撕掉徽章的盔甲, 一匹老马, 逃兵的烙印" }
    ],
    talents: [
        {name: "青草试炼(失败)", color: "E", cost: 50, desc: "【致命诅咒】你的身体在突变中崩溃。虽然活了下来，但神经受损，经常剧痛，且无法使用法印。", type: "exclusive"},
        {name: "怪物诅咒", color: "D", cost: 150, desc: "你被某种怪物（如妖灵或狼人）标记。在夜晚你的能力会下降，且容易吸引怪物的仇恨。", type: "exclusive"},
        {name: "昆特牌大师", color: "C", cost: 180, desc: "在这个世界，打牌能解决大部分问题。你拥有一套强力卡组，且总能诱导别人和你打牌赌钱。", type: "exclusive"},
        {name: "草药学知识", color: "C", cost: 160, desc: "你能分辨制作魔药和剑油的草药。这让你在面对特定怪物时能制作出针对性的毒药。", type: "exclusive"},
        {name: "猎魔人感官", color: "B", cost: 450, desc: "你的听觉和嗅觉极度敏锐。能追踪几英里外的气味，看到常人看不见的足迹和线索。", type: "exclusive"},
        {name: "法印精通(伊格尼)", color: "B", cost: 600, desc: "你专精于火焰法印。能喷射出融化盔甲的高温火焰流，对畏火的怪物造成毁灭性打击。", type: "exclusive"},
        {name: "剑术(拜年剑法)", color: "A", cost: 1100, desc: "熊学派的强力重击技巧。蓄力后的一击能无视防御，直接劈开盾牌和怪物的硬皮，且带有击倒效果。", type: "exclusive"},
        {name: "剑术(剑舞)", color: "A", cost: 1150, desc: "猫学派的速攻技巧。你可以化身为旋转的刀刃风暴，对周围所有敌人进行高频率的连续切割。", type: "exclusive"},
        {name: "突变诱发物(红色)", color: "S", cost: 2200, desc: "顶级的攻击型突变。植入后，你的攻击力大幅提升，且每次击杀都会暂时增加肾上腺素获取。", type: "exclusive"},
        {name: "高等吸血鬼血统", color: "SS", cost: 7000, desc: "你不再是凡人。你拥有极强的再生能力，能化身雾气或蝙蝠，只有同类才能真正杀死你。", type: "exclusive"},
        {name: "上古之血(未觉醒)", color: "SS", cost: 8500, desc: "希里的血脉。你拥有穿越时空的能力，可以在战斗中进行短距离瞬移（闪现），戏耍敌人。", type: "exclusive"},
        {name: "湖中之剑(阿隆戴特)", color: "SS", cost: 9000, desc: "传说中的银剑。每次击中敌人都会充能，满层后必定暴击且伤害永久提升。它是为了杀戮而生的神器。", type: "exclusive"},
        {name: "镜子大师的契约", color: "SSS", cost: 25000, desc: "你与刚特·欧迪姆达成了某种交易。你可以操控时间（暂停时间），甚至许愿获得任何世俗之物，但代价由你决定让谁支付。", type: "exclusive"},
        {name: "狂猎之主", color: "SSS", cost: 30000, desc: "你接管了狂猎军团。你可以召唤白霜冻结整个战场，并指挥幽灵骑士团为你冲锋，你是末日的先锋。", type: "exclusive"}
    ]
},
{
    name: "385.上古卷轴 (The Elder Scrolls)",
    desc: "泰姆瑞尔大陆，一个剑与魔法的史诗世界。巨龙回归，魔神窥视，帝国内战。在这里，你可以是拯救世界的龙裔，也可以是毁灭一切的魔神信徒。",
    boss: "奥杜因(世界吞噬者), 米拉贝克(初代龙裔), 哈孔大君, 魔神大衮",
    identities: [
        { name: "海尔根刑场的死刑犯", items: "一身囚服, 就在断头台旁边, 刚看到的巨龙阴影" },
        { name: "冬堡学院的扫地学徒", items: "一把扫帚, 一本看不懂的魔法书, 极度畏寒" },
        { name: "裂谷城的扒手", items: "一把匕首, 几个偷来的金币, 盗贼工会的通缉令" },
        { name: "雪漫城的乞丐", items: "一身破布, 只能睡在风区, 无论问谁都要一枚金币" },
        { name: "暗黑兄弟会的俘虏", items: "被蒙着头, 双手被缚, 面前有三个人质" }
    ],
    talents: [
        {name: "膝盖中箭", color: "E", cost: 10, desc: "【致命诅咒】你曾经是个冒险者，直到膝盖中了一箭。你的移动速度永久减半，无法奔跑和跳跃。", type: "exclusive"},
        {name: "吸血鬼(饥渴)", color: "D", cost: 150, desc: "你感染了吸血鬼病毒且处于饥饿状态。阳光会灼烧你的皮肤，不吸血就会极其虚弱，且会被卫兵攻击。", type: "exclusive"},
        {name: "开锁大师", color: "C", cost: 180, desc: "只要有一根发卡，就没有你开不了的门。从监狱牢门到领主的宝箱，都在你的掌握之中。", type: "exclusive"},
        {name: "潜行(幻影)", color: "C", cost: 200, desc: "当你蹲下时，你的存在感大幅降低。只要不发出大声响，哪怕在敌人眼皮底下他们也看不见你。", type: "exclusive"},
        {name: "炼金术士", color: "B", cost: 500, desc: "你知道如何将巨人的脚趾和小麦混合成价值连城的药水。无论是恢复还是毒杀，都在一瓶药剂之间。", type: "exclusive"},
        {name: "召唤系(元素)", color: "B", cost: 650, desc: "你可以召唤火元素或冰霜元素为你作战。它们忠诚且强大，是最好的肉盾和输出。", type: "exclusive"},
        {name: "幻术系(狂暴)", color: "A", cost: 1000, desc: "你可以悄无声息地释放法术，让一群敌人自相残杀，而你只需在一旁看戏。", type: "exclusive"},
        {name: "潜行弓箭手", color: "A", cost: 1200, desc: "这个世界最强的职业流派。蹲下、拉弓、暴击。你能在敌人发现你之前清空整个地牢。", type: "exclusive"},
        {name: "龙吼(不卸之力)", color: "S", cost: 2500, desc: "Fus-Ro-Dah！用声音释放巨大的冲击波，能将敌人、物体甚至巨龙吹飞，造成物理和坠落伤害。", type: "exclusive"},
        {name: "龙吼(龙之形态)", color: "S", cost: 2800, desc: "让巨龙的力量充盈全身。你的防御力、攻击力大幅提升，且龙吼冷却时间大幅缩短。", type: "exclusive"},
        {name: "魔神神器(瓦巴杰克)", color: "SS", cost: 6000, desc: "疯神谢尔格拉的法杖。效果完全随机：可能把敌人变成鸡，可能治疗敌人，也可能直接秒杀。充满了混乱的乐趣。", type: "exclusive"},
        {name: "吸血鬼大君形态", color: "SS", cost: 7500, desc: "你可以变身为恐怖的吸血鬼大君。拥有飞行能力、吸血魔法和念力抓取，是黑夜的霸主。", type: "exclusive"},
        {name: "龙裔血脉(完全觉醒)", color: "SSS", cost: 28000, desc: "你拥有不朽龙魂。杀死的龙会被你吸取灵魂以解锁更多龙吼。你对巨龙有天然的压制力，天生的王者。", type: "exclusive"},
        {name: "奇姆(CHIM)", color: "SSS", cost: 50000, desc: "你意识到这只是一个梦（游戏），并掌握了修改梦境的能力。类似控制台代码，你可以修改现实，删除敌人，甚至重塑世界。", type: "exclusive"}
    ]
},
{
    name: "386.辐射 (Fallout)",
    desc: "核战争后的废土世界。避难所、变种人、钢铁兄弟会。这里充满了辐射、荒诞的黑色幽默和残酷的生存法则。战争，战争从未改变。",
    boss: "法兰克·荷瑞根, 凯撒, 学院圣父, 辐光种(发光海)",
    identities: [
        { name: "刚出避难所的小白", items: "蓝黄紧身衣, 10mm手枪, 几瓶纯净水" },
        { name: "超级变种人的储备粮", items: "被关在笼子里, 身上有辐射溃烂, 一个隐藏的发卡" },
        { name: "废土拾荒者", items: "一把管钳, 几发瓶盖, 严重的辐射病" },
        { name: "钢铁兄弟会学徒尸体旁的幸存者", items: "损坏的激光步枪, 半件T-60动力甲部件, 狗牌" },
        { name: "钻石城的报童", items: "几份公报, 棒球棒, 对合成人的恐惧" }
    ],
    talents: [
        {name: "辐射病(晚期)", color: "E", cost: 30, desc: "【致命诅咒】你的最大生命值被辐射占据了80%。稍微靠近辐射源就会死亡，且属性大幅下降。", type: "exclusive"},
        {name: "药物成瘾", color: "D", cost: 100, desc: "你对杰特、赛柯等药物严重成瘾。如果不定期服用，全属性会暴跌，且会出现幻觉。", type: "exclusive"},
        {name: "废土求生专家", color: "C", cost: 150, desc: "吃蟑螂肉、喝马桶水对你来说是家常便饭，且回复量增加，受到辐射减少。", type: "exclusive"},
        {name: "神秘人", color: "C", cost: 200, desc: "在V.A.T.S攻击时，有几率出现一位手持左轮的神秘人帮你瞬间秒杀敌人，然后消失。", type: "exclusive"},
        {name: "动力甲驾驶", color: "B", cost: 550, desc: "你受过正规训练，能熟练驾驶动力装甲，不会因为行动笨拙而摔倒，且能发挥其最大防御力。", type: "exclusive"},
        {name: "能量武器专家", color: "B", cost: 600, desc: "激光和等离子武器在你手中威力大增。你能将敌人化为一堆灰烬或绿色的粘液。", type: "exclusive"},
        {name: "尸鬼体质", color: "A", cost: 1200, desc: "你免疫辐射，甚至辐射能治疗你的伤口。但你的外表会变得丑陋，且会被正常人类歧视。", type: "exclusive"},
        {name: "V.A.T.S系统(避难所科技)", color: "S", cost: 2500, desc: "避难所辅助瞄准系统。你可以暂停时间，精确选择敌人的身体部位进行射击，且暴击率极高。", type: "exclusive"},
        {name: "幸运10", color: "S", cost: 2800, desc: "这就是“主角光环”。你会莫名其妙地猜对密码，敌人的子弹会卡壳，开箱子全是神装。", type: "exclusive"},
        {name: "胖子核弹发射器(无限弹药)", color: "SS", cost: 8000, desc: "你拥有一把微型核弹发射器，且弹药箱似乎通向异次元。你是行走的核威慑，只要你不怕炸死自己。", type: "exclusive"},
        {name: "自由至尊(控制权)", color: "SS", cost: 9500, desc: "你可以指挥那台巨大的反共机器人。它眼部发射激光，投掷核弹，高喊口号碾碎一切阻碍。", type: "exclusive"},
        {name: "G.E.C.K.(伊甸园创造器)", color: "SSS", cost: 30000, desc: "这不仅仅是净化水源。它拥有重塑物质的能力，能在瞬间将一片死寂的废土转化为生机勃勃的乐园（或毁灭它）。", type: "exclusive"},
        {name: "控制台(player.additem)", color: "SSS", cost: 45000, desc: "你触碰到了世界的底层代码。你可以凭空刷出任何武器、弹药、瓶盖，甚至修改自己的属性。你是废土的神。", type: "exclusive"}
    ]
},
{
    name: "387.质量效应 (Mass Effect)",
    desc: "未来的银河系，人类加入了星际议会。但古老的机械种族“收割者”每隔五万年就会收割所有高等有机文明。这是一场关于团结与存亡的太空歌剧。",
    boss: "收割者霸主(Harbinger), 萨伦, 幻影人, 收集者将军",
    identities: [
        { name: "神堡的贫民区难民", items: "过期的营养膏, 一把自制匕首, 对巴塔瑞人的仇恨" },
        { name: "欧米伽的一名雇佣兵", items: "磨损的复仇者步枪, 破损的护盾发生器, 埃利奥的契约" },
        { name: "星联海军陆战队新兵", items: "标准N7护甲(E级), 制式手枪, 第一次上太空的呕吐袋" },
        { name: "被塞伯鲁斯绑架的实验体", items: "植入体排斥反应, 拘束衣, 逃跑的决心" },
        { name: "克洛根人的试管弃婴", items: "基因缺陷, 只有一把霰弹枪, 对基因噬体病毒的恐惧" }
    ],
    talents: [
        {name: "基因噬体", color: "E", cost: 50, desc: "【种族诅咒】如果你是克洛根人，你的后代存活率极低。这让你背负沉重的心理负担，且被其他种族警惕。", type: "exclusive"},
        {name: "教化(初期)", color: "D", cost: 150, desc: "收割者的低语开始侵蚀你的意志。你偶尔会听到奇怪的声音，对收割者产生莫名的崇拜感。", type: "exclusive"},
        {name: "万用工具(黑客)", color: "C", cost: 180, desc: "手腕上的全息电脑。能远程超载敌人的护盾，或者骇入炮塔让其倒戈。", type: "exclusive"},
        {name: "战术斗篷", color: "C", cost: 200, desc: "光学迷彩技术。激活后隐形，且下一次攻击伤害大幅提升。渗透者的最爱。", type: "exclusive"},
        {name: "异能(奇点)", color: "B", cost: 600, desc: "制造一个微型黑洞，将周围的敌人吸入并浮空，让他们成为活靶子。", type: "exclusive"},
        {name: "异能(冲锋)", color: "B", cost: 650, desc: "先锋的神技。化作一道蓝光瞬间撞向敌人，恢复护盾并造成巨大冲击。高风险高回报。", type: "exclusive"},
        {name: "N7特种兵训练", color: "A", cost: 1200, desc: "星联最高级别的特种部队训练。精通所有枪械，体能极限，拥有极高的战术素养和领导力。", type: "exclusive"},
        {name: "楷模/叛逆气场", color: "A", cost: 1300, desc: "你的言语拥有极强的煽动力。楷模能化敌为友，叛逆能威慑群雄。甚至能说死最终BOSS。", type: "exclusive"},
        {name: "普洛仙信标知识", color: "S", cost: 2800, desc: "你的脑中被灌输了上一代文明的知识。虽然让你头痛欲裂，但你知道收割者的弱点和催化剂的秘密。", type: "exclusive"},
        {name: "诺曼底号(指挥权)", color: "SS", cost: 8500, desc: "你拥有全银河最先进的隐形护卫舰及其精英船员。这是你的移动基地，也是对抗收割者的尖刀。", type: "exclusive"},
        {name: "收割者改造", color: "SS", cost: 9000, desc: "你接受了收割者的技术改造但保留了自我。拥有坚不可摧的甲壳和毁灭性的激光眼，半人半机械的怪物。", type: "exclusive"},
        {name: "擎天炉(Crucible)", color: "SSS", cost: 40000, desc: "大规模杀伤性武器的蓝图与核心。启动后，可以选择控制、合成或毁灭全银河系的合成生命（包括收割者）。", type: "exclusive"},
        {name: "薛帕德指挥官", color: "SSS", cost: 50000, desc: "你就是传奇本身。你拥有团结全银河系所有种族的能力。只要你站在这里，希望就不会熄灭。", type: "exclusive"}
    ]
},
{
    name: "388.龙腾世纪 (Dragon Age)",
    desc: "塞达斯大陆，一个被枯潮威胁的魔幻世界。法师被圣殿骑士看管，灰袍守护者对抗暗裔，精灵备受压迫。这里没有绝对的善恶，只有艰难的抉择。",
    boss: "大恶魔(古神), 考瑞菲亚斯, 索拉斯(恐惧之狼), 影界恶魔",
    identities: [
        { name: "费雷登的逃难农夫", items: "一把草叉, 被暗裔烧毁的家园, 染病的狗" },
        { name: "法师塔的学徒", items: "法师长袍, 只有火花术的法杖, 圣殿骑士的严密监视" },
        { name: "城市精灵仆人", items: "一把扫帚, 顺从的眼神, 藏在袖子里的小刀" },
        { name: "矮人无民者", items: "被刺字的脸, 捡来的破烂盔甲, 无论是地底还是地上都被歧视" },
        { name: "深坑通路的敢死队", items: "一把断斧, 满身暗裔之血, 必死的决心" }
    ],
    talents: [
        {name: "静谧者", color: "E", cost: 50, desc: "【灵魂诅咒】你被切断了与影界的联系。没有情感，没有魔法，像个活死人一样只会执行命令。", type: "exclusive"},
        {name: "枯潮感染", color: "D", cost: 120, desc: "你吞下了暗裔的血但没成为灰袍。你会慢慢变成食尸鬼，听到古神的呼唤，最终失去理智。", type: "exclusive"},
        {name: "血魔法(初级)", color: "C", cost: 200, desc: "禁忌的魔法。你可以通过割伤自己消耗生命值来施法，威力比普通魔法大，但会招来恶魔和圣殿骑士。", type: "exclusive"},
        {name: "吟游诗人", color: "C", cost: 180, desc: "你的歌声和故事能鼓舞队友，或者在战斗中迷惑敌人。同时你也擅长间谍活动和暗杀。", type: "exclusive"},
        {name: "灰袍守护者", color: "B", cost: 600, desc: "喝下暗裔之血并幸存。你能感知暗裔的存在，且在对抗大恶魔时是唯一能彻底杀死它们的人。代价是寿命缩短。", type: "exclusive"},
        {name: "圣殿骑士能力", color: "B", cost: 650, desc: "专门克制法师。你可以驱散魔法，燃烧法师的法力值，并对恶魔造成额外伤害。依靠服用利瑞姆矿石维持。", type: "exclusive"},
        {name: "掠夺者", color: "A", cost: 1100, desc: "狂战士风格。生命值越低，攻击力越高。你可以吞噬敌人的尸体来回复生命，战斗风格极其残暴。", type: "exclusive"},
        {name: "奥术战士", color: "A", cost: 1250, desc: "古代精灵的战斗技巧。用法力值代替力量穿戴重甲，用法力值代替生命抵挡伤害。全副武装的法师坦克。", type: "exclusive"},
        {name: "影界裂隙印记", color: "S", cost: 3000, desc: "审判官的能力。你可以打开或关闭影界裂隙，甚至在战斗中撕开裂隙将敌人放逐或造成巨大精神伤害。", type: "exclusive"},
        {name: "灵之本源", color: "SS", cost: 7000, desc: "你像温恩或正义一样，体内寄宿着一个善良的灵体。它能让你死而复生，并提供强大的治疗和辅助能力。", type: "exclusive"},
        {name: "古神之魂", color: "SS", cost: 9000, desc: "你吸收了乌瑞米耶或其他古神的灵魂碎片。你拥有甚至能挑战造物主的潜力，是暗裔和灰袍共同恐惧的存在。", type: "exclusive"},
        {name: "恐惧之狼的力量", color: "SSS", cost: 35000, desc: "索拉斯的力量。你可以石化敌人，剥离他们的灵魂，甚至拥有撕裂帷幕、重塑世界的权柄。", type: "exclusive"},
        {name: "泰坦之心", color: "SSS", cost: 40000, desc: "你获得了大地深处泰坦的认可。你可以操控地震，甚至让整座山脉为你而战。你是大地的化身。", type: "exclusive"}
    ]
},
{
    name: "389.生化奇兵 (BioShock)",
    desc: "从海底的销魂城到天空的哥伦比亚，这里是乌托邦的梦想与噩梦。基因改造剂(质体)泛滥，哲学与疯狂共舞。没有神，没有国王，只有人。",
    boss: "安德鲁·瑞恩, 弗兰克·方丹, 康斯托克先知, 鸣禽(Songbird)",
    identities: [
        { name: "坠机幸存者", items: "一件湿透的毛衣, 一个写着坐标的纸条, 恐惧的眼神" },
        { name: "销魂城的修补工", items: "一把大扳手, 几个EVE注射器, 满身油污" },
        { name: "极乐城的清洁工", items: "一把扫帚, 对爱国者机器人的恐惧, 种族隔离的受害者" },
        { name: "疯狂的整容医生助手", items: "沾血的手术刀, 几个失败的标本, 精神错乱的笔记" },
        { name: "小妹妹的保护者(失败品)", items: "生锈的铆钉枪, 笨重的潜水服头盔, 对亚当物质的渴望" }
    ],
    talents: [
        {name: "质体成瘾", color: "E", cost: 60, desc: "【基因诅咒】过度使用质体导致基因崩溃。你的外表开始变异，精神不稳定，必须不断摄入亚当物质才能维持理智。", type: "exclusive"},
        {name: "深海恐惧", color: "D", cost: 100, desc: "在销魂城这种海底城市，你时刻处于恐慌状态。听到漏水声会让你属性下降，无法集中注意力。", type: "exclusive"},
        {name: "扳手专家", color: "C", cost: 150, desc: "你用扳手打人的技术炉火纯青。配合身体强化药剂，你的一扳手能敲碎修补者的脑壳。", type: "exclusive"},
        {name: "黑客(水管工)", color: "C", cost: 180, desc: "你擅长通过连接水管小游戏来骇入机器。不仅能打开保险箱，还能让安保机器人为你服务。", type: "exclusive"},
        {name: "质体(电击)", color: "B", cost: 500, desc: "指尖放出高压电。能麻痹敌人，或者电击水面造成范围伤害。是控制敌人的基础神技。", type: "exclusive"},
        {name: "质体(焚烧)", color: "B", cost: 550, desc: "响指一打，烈火燎原。能点燃漏油，融化冰块，对血肉之躯造成持续伤害。", type: "exclusive"},
        {name: "质体(催眠)", color: "A", cost: 1000, desc: "你可以扔出费洛蒙瓶，让大老爹（Big Daddy）误以为你是小妹妹，从而为你死战到底。", type: "exclusive"},
        {name: "大老爹套装", color: "A", cost: 1500, desc: "穿上这套传奇潜水服。防御力极高，配备巨大的钻头。你是销魂城最坚固的堡垒。", type: "exclusive"},
        {name: "伊丽莎白的裂隙", color: "S", cost: 3000, desc: "你可以像伊丽莎白一样，从平行世界拉取物体。比如凭空变出弹药、医疗包，甚至是一挺机枪炮塔。", type: "exclusive"},
        {name: "活力(脱缰野马)", color: "S", cost: 2500, desc: "哥伦比亚的异能。你能将敌人击飞到空中并悬浮，让他们在无助中被你像打靶一样消灭。", type: "exclusive"},
        {name: "鸣禽召唤", color: "SS", cost: 8000, desc: "你可以用特殊的笛子召唤那只巨大的机械鸟。它能摧毁飞艇，撕碎建筑，是天空城的终极兵器。", type: "exclusive"},
        {name: "瑞恩的基因钥匙", color: "SS", cost: 7000, desc: "“这所城市属于你”。你拥有销魂城的最高权限，所有炮塔不会攻击你，你可以控制城市的复活装置。", type: "exclusive"},
        {name: "量子叠加态", color: "SSS", cost: 35000, desc: "像路特斯兄妹一样。你同时存在于所有可能性中。你可以瞬间移动，预知所有结局，甚至是不死之身。", type: "exclusive"},
        {name: "灯塔守护者", color: "SSS", cost: 45000, desc: "总有一座灯塔，总有一个人，总有一座城市。你洞悉了多元宇宙的循环，可以随意穿越到任何平行世界的哥伦比亚或销魂城。", type: "exclusive"}
    ]
},
{
    name: "390.合金装备 (Metal Gear)",
    desc: "战术谍报动作游戏的巅峰。核威慑、纳米机器、克隆人与雇佣兵。这是一个关于反战、基因宿命与“爱国者”控制世界的宏大故事。",
    boss: "液态蛇(Liquid Snake), 巨型机甲(Metal Gear REX/RAY), 参议员阿姆斯特朗, 赛格(The Boss)",
    identities: [
        { name: "影子摩西岛的杂兵", items: "FAMAS步枪, 容易受惊的对讲机, 基因治疗后的副作用" },
        { name: "外层天堂的童兵", items: "一把AK47, 战乱的创伤, 只有一颗子弹的项链" },
        { name: "被抛弃的克隆实验体", items: "加速衰老的基因, 医院病号服, 模糊的记忆" },
        { name: "私人军事公司(PMC)的炮灰", items: "SOP系统植入, 廉价的防弹衣, 被控制的情感" },
        { name: "大贝壳平台的清洁工", items: "拖把, 门禁卡(Level 1), 对忍者雷电的目击报告" }
    ],
    talents: [
        {name: "FOXDIE病毒", color: "E", cost: 100, desc: "【命运诅咒】你体内携带针对特定基因的死神病毒。虽然你可能免疫，但你会不自觉地杀死身边的特定目标，成为移动的瘟疫。", type: "exclusive"},
        {name: "加速衰老", color: "D", cost: 150, desc: "作为克隆人，你的端粒酶过短。你的身体会比常人老得快得多，体能巅峰期极短。", type: "exclusive"},
        {name: "CQC(近身格斗术)", color: "C", cost: 250, desc: "大首领(Big Boss)创立的格斗术。摔投、锁喉、夺枪一气呵成。在近身战中你几乎是无敌的。", type: "exclusive"},
        {name: "纸箱潜行", color: "C", cost: 100, desc: "这不仅是纸箱，这是信仰。只要躲在纸箱里，敌人智商就会降低，哪怕你在路中间移动他们也会觉得是风吹的。", type: "exclusive"},
        {name: "富尔顿回收系统", color: "B", cost: 600, desc: "你可以用气球把晕倒的敌人、集装箱甚至吉普车直接吊上天回收。万物皆可回收，是组建军队的神技。", type: "exclusive"},
        {name: "SOP系统(黑客)", color: "B", cost: 700, desc: "你可以骇入敌人的纳米机器，锁定他们的武器，甚至让他们产生幻觉或失去战斗意志。", type: "exclusive"},
        {name: "高频村雨刀", color: "A", cost: 1300, desc: "雷电的武器。通过高频振动，它能切开坦克装甲、直升机甚至Metal Gear的腿。削铁如泥。", type: "exclusive"},
        {name: "光学迷彩(章鱼)", color: "A", cost: 1500, desc: "老蛇的战衣。能模仿周围环境的纹理和颜色，让你与背景完美融合，达到99%的隐身指数。", type: "exclusive"},
        {name: "纳米机器(阿姆斯特朗)", color: "S", cost: 3000, desc: "“Nanomachines, son!” 受到物理打击时皮肤瞬间硬化。你可以徒手接住高频刀，一拳打爆机甲。", type: "exclusive"},
        {name: "静静的狙击能力", color: "S", cost: 2800, desc: "通过皮肤呼吸，拥有超人的视力和稳定性。能射中几公里外飞行员的眉心，且能隐身和快速移动。", type: "exclusive"},
        {name: "Metal Gear REX(驾驶权)", color: "SS", cost: 9000, desc: "驾驶这台双足核搭载战车。配备轨道炮、激光和导弹。它是冷战恐惧的具象化，拥有毁灭世界的能力。", type: "exclusive"},
        {name: "爱国者AI权限", color: "SS", cost: 9500, desc: "你获得了控制世界经济、军事和信息的AI系统的后门。你可以操纵战争，控制舆论，成为幕后的神。", type: "exclusive"},
        {name: "大首领的传奇", color: "SSS", cost: 40000, desc: "你拥有Big Boss的全部能力和魅力。全世界的士兵都会视你为弥赛亚，愿意为你建立“无国界军队”。", type: "exclusive"}
    ]
},
                      {
                name: "391.鬼泣 (Devil May Cry)",
                desc: "一个哥特风格的现代世界，恶魔与人类共存。斯巴达之子经营着名为''Devil May Cry''的事务所。风格评价（Style）是战斗的核心，华丽地消灭恶魔是这里的生存法则。",
                boss: "魔帝蒙德斯, 维吉尔, 阿尔戈萨克斯, 尤里曾",
                identities: [
                    { name: "红墓市的披萨店外卖员", items: "一盒刚出炉的特大号披萨, 一辆快散架的摩托车" },
                    { name: "崇拜恶魔的教团低级信徒", items: "一本写满疯言疯语的祷告书, 一件纯白的长袍" },
                    { name: "恶魔猎人事务所的清洁工", items: "一把拖把, 一张被拖欠工资的账单" },
                    { name: "被恶魔附体的倒霉路人", items: "一只不受控制的左手, 满口袋的镇静剂" },
                    { name: "地下黑市的情报贩子", items: "一个加密的通讯器, 一张恶魔出没地点的地图" }
                ],
                talents: [
                    {name: "半魔血统(觉醒)", color: "SS", cost: 8000, desc: "你流淌着斯巴达的血脉。拥有极强的恢复力和力量，且具备变身''魔人化(Devil Trigger)''的潜力，变身后各项数值暴涨。", type: "exclusive"},
                    {name: "阎魔刀(认可)", color: "SSS", cost: 15000, desc: "能够分离人与魔、切割空间的次元之刃。只有渴望力量且被刀选中的人才能使用。拥有开启地狱之门的能力。", type: "exclusive"},
                    {name: "风格切换系统", color: "S", cost: 1800, desc: "你可以像但丁一样在骗术师、剑圣、皇家护卫、枪神四种风格中自由切换，适应任何战场环境。", type: "exclusive"},
                    {name: "叛逆之剑(碎片)", color: "A", cost: 900, desc: "斯巴达留下的魔剑碎片，虽然不完整，但依然削铁如泥，并且对恶魔有特殊的杀伤力。", type: "exclusive"},
                    {name: "黑檀木与白象牙(仿品)", color: "B", cost: 400, desc: "著名的双枪仿制品，虽然没有无限子弹的魔力，但射速极快，且经过特殊改造能发射大口径子弹。", type: "exclusive"},
                    {name: "皇家护卫(入门)", color: "B", cost: 500, desc: "你学会了利用瞬间格挡来抵消伤害的技巧。虽然还做不到完美释放，但能保住小命。", type: "exclusive"},
                    {name: "二段跳", color: "C", cost: 150, desc: "违背物理法则的能力，你可以在空中踩踏空气进行第二次跳跃，机动性大幅提升。", type: "exclusive"},
                    {name: "挑衅嘲讽", color: "C", cost: 100, desc: "你擅长在战斗中嘲讽敌人，虽然会拉满仇恨，但成功闪避攻击后能快速回复魔力或体力。", type: "exclusive"},
                    {name: "红魂石磁铁", color: "C", cost: 120, desc: "你对红魂石有种天然的吸引力，击杀怪物后掉落的红魂石会自动飞向你。", type: "exclusive"},
                    {name: "尼禄的机械臂(Overture)", color: "A", cost: 750, desc: "妮可制作的对魔特化义肢，能释放强力的电击冲击波。属于消耗品，容易损坏。", type: "exclusive"},
                    {name: "维吉尔的诗集", color: "D", cost: 50, desc: "一本写着威廉·布莱克诗句的书。除了让你看起来更有逼格和emo之外，没什么实际卵用。", type: "exclusive"},
                    {name: "恶魔右臂", color: "A", cost: 850, desc: "你的右臂发生了恶魔化变异，拥有巨大的握力和投技判定，能抓住远处的敌人。", type: "exclusive"},
                    {name: "真魔人化(Sin DT)", color: "SSS", cost: 30000, desc: "超越普通魔人的究极形态。释放出毁灭性的力量，能够飞行、瞬移，并释放黑洞般的攻击。", type: "exclusive"},
                    {name: "暴风雨(Agni & Rudra)", color: "S", cost: 1200, desc: "寄宿着风与火之力的双刀。虽然威力强大，但这两把刀非常话痨，如果你受不了它们的废话就别买。", type: "exclusive"},
                    {name: "无限魔力(作弊码)", color: "SS", cost: 9999, desc: "你的魔力源源不断，可以无限维持魔人化状态或肆意释放大招。这是破坏平衡的力量。", type: "exclusive"}
                ]
            },
            {
                name: "392.生化危机 (Resident Evil 游戏)",
                desc: "被T病毒和其他生化武器肆虐的世界。丧尸横行，变异生物潜伏在暗处。安布雷拉公司的阴影笼罩全球，生存恐怖是这里的主旋律。",
                boss: "阿尔伯特·威斯克, 暴君(T-103), 追踪者(Nemesis), 威廉·柏金(G)",
                identities: [
                    { name: "浣熊市警局(RPD)的新人警员", items: "一把只有10发子弹的手枪, 一个对讲机" },
                    { name: "安布雷拉公司的底层研究员", items: "一张白色的门禁卡, 一份未完成的病毒实验报告" },
                    { name: "即将被处决的S.T.A.R.S成员", items: "一把格斗匕首, 一件防弹背心" },
                    { name: "浣熊市的普通市民", items: "一根棒球棍, 一张逃离城市的路线图" },
                    { name: "BSAA的一名外勤士兵", items: "一把突击步枪, 几个急救喷雾" }
                ],
                talents: [
                    {name: "T病毒完美融合者", color: "SS", cost: 7000, desc: "你是爱丽丝那样的特例。感染T病毒后不仅没有变成丧尸，反而获得了超人的体能和念动力。", type: "exclusive"},
                    {name: "G病毒变异体(不可控)", color: "S", cost: 1500, desc: "你注射了G病毒，拥有无限进化的可能性和极强的再生能力。但随着进化，你会逐渐失去人性变成怪物。", type: "exclusive"},
                    {name: "衔尾蛇病毒(Uroboros)", color: "S", cost: 1800, desc: "筛选优等基因的病毒。若适配成功，你将获得触手化攻击能力和极高的再生力；若失败，化为一滩黑泥。", type: "exclusive"},
                    {name: "寄生虫(Las Plagas)", color: "A", cost: 800, desc: "你体内寄宿着普拉卡寄生虫，虽然保留了智力，但绝对服从教主的命令。大幅提升身体素质。", type: "exclusive"},
                    {name: "马格南精通", color: "A", cost: 600, desc: "你对大口径左轮手枪有独特的理解，使用马格南时后坐力减半，爆头率提升50%。", type: "exclusive"},
                    {name: "草药合成大师", color: "C", cost: 180, desc: "你能将红、绿、黄三种草药进行完美配比，制作出完全恢复体力并提升生命上限的药剂。", type: "exclusive"},
                    {name: "体术大师(里昂流)", color: "B", cost: 450, desc: "擅长回旋踢和背摔。当敌人处于硬直状态时，你能发动强力体术攻击，往往能一击必杀。", type: "exclusive"},
                    {name: "开锁宗师", color: "C", cost: 150, desc: "你是“开锁王”吉尔的传人。只要有一根铁丝，就没有你打不开的门和箱子。", type: "exclusive"},
                    {name: "墨带与打字机", color: "C", cost: 200, desc: "一种形而上的能力。当你找到打字机时，你可以进行一次完美的精神休息，消除所有疲劳和恐惧。", type: "exclusive"},
                    {name: "威斯克的瞬移", color: "S", cost: 1900, desc: "利用超高速移动产生的视觉残留效果。你可以瞬间移动到敌人身后进行攻击，宛如鬼魅。", type: "exclusive"},
                    {name: "霉菌感染者(伊森体质)", color: "SS", cost: 6000, desc: "你的身体由霉菌构成。断手断脚只需要用洗手液接回去就行，几乎无法被物理手段彻底杀死。", type: "exclusive"},
                    {name: "暴君束缚衣", color: "B", cost: 300, desc: "一件极其沉重但防御力惊人的大衣。穿上后移动速度大幅下降，但能抵挡小口径枪械射击。", type: "exclusive"},
                    {name: "四次元置物箱", color: "A", cost: 1000, desc: "你拥有一个连接次元空间的箱子，无论你在哪里，都可以从中存取物品。", type: "exclusive"},
                    {name: "火箭筒(无限弹药)", color: "SSS", cost: 25000, desc: "通关奖励级别的神器。一把拥有无限弹药的四管火箭筒，没有什么是一发解决不了的，如果有，就两发。", type: "exclusive"},
                    {name: "豆腐模式", color: "D", cost: 100, desc: "你的身体变成了一块巨大的豆腐。虽然防御力极低，但你会说关西腔，并且受击时会发出奇怪的声音。", type: "exclusive"}
                ]
            },
            {
                name: "393.寂静岭 (Silent Hill)",
                desc: "一个被浓雾笼罩的美国小镇，表世界是荒废的城镇，里世界则是铁锈与血肉构成的地狱。这里是心理投射的具象化，你面对的怪物源于你内心的罪恶。",
                boss: "三角头(Pyramid Head), 圣母神(God), 阿蕾莎(Alessa)",
                identities: [
                    { name: "迷路的游客", items: "一张无法定位的地图, 一个快没电的手电筒" },
                    { name: "寻找妻子的丈夫", items: "一封亡妻的信, 满心的愧疚" },
                    { name: "寂静岭教会的孤儿", items: "一个奇怪的护身符, 对某种仪式的模糊记忆" },
                    { name: "卡车司机", items: "一把扳手, 一瓶喝了一半的威士忌" },
                    { name: "私家侦探", items: "一把左轮手枪, 一个记录着线索的笔记本" }
                ],
                talents: [
                    {name: "阿蕾莎的黑暗面", color: "SSS", cost: 20000, desc: "你与阿蕾莎的黑暗力量共生。你可以随意操控里世界的转换，召唤铁丝网和怪物处决敌人。", type: "exclusive"},
                    {name: "三角大刀", color: "S", cost: 1800, desc: "处刑者三角头的标志性武器。极其沉重，挥舞起来能轻易斩断钢铁和肉体，对罪人有特攻。", type: "exclusive"},
                    {name: "收音机(预警)", color: "C", cost: 150, desc: "当怪物靠近时，这台坏掉的收音机会发出刺耳的白噪音。噪音越大，怪物越近，越强。", type: "exclusive"},
                    {name: "里世界适应性", color: "B", cost: 400, desc: "你在里世界中不会因为精神污染而发疯。那里的铁锈味和血腥味反而让你感到安心。", type: "exclusive"},
                    {name: "护士的诡异舞步", color: "C", cost: 200, desc: "你模仿无脸护士的行动模式。在光线静止时你会僵直，但当灯光闪烁时，你的移动速度和攻击诡异莫测。", type: "exclusive"},
                    {name: "梅塔特隆印章", color: "A", cost: 900, desc: "强力的护身符。能够驱散低级的邪灵，并在一定程度上抵抗神之胎的侵蚀。", type: "exclusive"},
                    {name: "罪恶具象化", color: "A", cost: 1000, desc: "你能将敌人的内疚和罪恶具象化为怪物攻击他们自己。敌人心理越阴暗，受到的伤害越高。", type: "exclusive"},
                    {name: "UFO结局", color: "SS", cost: 5000, desc: "你掌握了召唤外星人的方法。在绝境中，你可以呼叫飞碟把所有人和怪物都吸走，强行结束当前剧情。", type: "exclusive"},
                    {name: "生锈的水管", color: "D", cost: 50, desc: "寂静岭最常见的武器。虽然普通，但在绝望中它是你唯一能依赖的伙伴。容易折断。", type: "exclusive"},
                    {name: "迷雾行者", color: "B", cost: 350, desc: "在浓雾中你的视野不受影响，并且可以隐匿自己的脚步声，像幽灵一样行动。", type: "exclusive"},
                    {name: "21圣礼", color: "S", cost: 1600, desc: "你掌握了沃尔特的邪恶仪式知识。通过献祭受害者，你可以获得不死之身和操控幽灵的能力。", type: "exclusive"},
                    {name: "红色存盘点", color: "C", cost: 180, desc: "你总能发现墙上红色的奇怪符号。盯着它看可以恢复精神值，并记录当前的身体状态。", type: "exclusive"},
                    {name: "神之胎(未孵化)", color: "SS", cost: 8500, desc: "你的体内孕育着“神”。这给你带来无穷的痛苦，但也赋予你操控现实和毁灭世界的力量。", type: "exclusive"},
                    {name: "罗比兔玩偶服", color: "C", cost: 120, desc: "一件沾血的粉色兔子玩偶服。穿上它会让人感到不寒而栗，能恐吓低智商的生物。", type: "exclusive"},
                    {name: "医院地图", color: "D", cost: 30, desc: "一张Brookhaven医院的地图。上面用红笔画满了乱七八糟的标记，只有你能看懂。", type: "exclusive"}
                ]
            },
            {
                name: "394.最终幻想7 (FF7)",
                desc: "魔晄能源驱动的工业奇幻世界。神罗公司抽取星球生命力，雪崩组织与之对抗。杰诺瓦细胞、古代种传说与萨菲罗斯的陨石危机交织。",
                boss: "萨菲罗斯, 杰诺瓦(Jenova), 宝条博士, 究极兵器(Ultima Weapon)",
                identities: [
                    { name: "米德加贫民窟的居民", items: "一朵卖不出去的花, 一个破旧的收音机" },
                    { name: "神罗的一般士兵", items: "一把制式机枪, 一个印着神罗Logo的头盔" },
                    { name: "雪崩组织的底层成员", items: "一个自制的炸弹, 一条红色的头带" },
                    { name: "五台的忍者学徒", items: "一枚巨大的手里剑, 一本忍术卷轴" },
                    { name: "金碟游乐场的服务员", items: "一套陆行鸟玩偶服, 一张终身免费入场券" }
                ],
                talents: [
                    {name: "杰诺瓦细胞(S计划)", color: "SS", cost: 7500, desc: "你被植入了萨菲罗斯同款的杰诺瓦细胞。拥有拟态能力、极强的生命力和对星之力的感应，但也容易被重聚。", type: "exclusive"},
                    {name: "魔晄眼(SOLDIER证明)", color: "A", cost: 800, desc: "经过魔晄浸泡的眼睛，瞳孔呈现奇异的蓝绿色。身体素质远超常人，能看到魔力的流动。", type: "exclusive"},
                    {name: "极限技(Limit Break)", color: "S", cost: 1500, desc: "在受到大量伤害积攒怒气后，能爆发出超越身体极限的必杀技。技能威力随愤怒程度提升。", type: "exclusive"},
                    {name: "古代种血统(赛特拉)", color: "SS", cost: 6000, desc: "你是星球的原住民后裔。能与星球对话，引导生命之流，并发动威力巨大的神圣魔法(Holy)。", type: "exclusive"},
                    {name: "魔石槽(Materia Slot)", color: "C", cost: 200, desc: "你的武器或防具上开有槽位，可以装备魔石来使用魔法或技能。槽位越多，潜力越大。", type: "exclusive"},
                    {name: "召唤魔石：圆桌骑士", color: "SSS", cost: 18000, desc: "最强的召唤兽魔石。召唤亚瑟王与十二骑士进行轮番轰炸，造成毁灭性的多段伤害。", type: "exclusive"},
                    {name: "召唤魔石：巴哈姆特·零式", color: "S", cost: 2500, desc: "从外太空召唤巴哈姆特，释放足以摧毁地表的百万核爆攻击(Tera Flare)。", type: "exclusive"},
                    {name: "全斩(Slash-All)", color: "B", cost: 450, desc: "一种高级剑术技巧。你的普通攻击可以同时攻击视野内的所有敌人，效率极高。", type: "exclusive"},
                    {name: "敌技(Enemy Skill)", color: "A", cost: 700, desc: "特殊的魔石能力。只要被敌人的技能击中过一次，你就能学会并永久掌握该技能。", type: "exclusive"},
                    {name: "蒂法的格斗术", color: "A", cost: 650, desc: "赞甘流格斗术的真传。擅长快速连击和掌机破坏(Dolphin Blow)，拥有极高的爆发力。", type: "exclusive"},
                    {name: "文森特的变身", color: "S", cost: 1600, desc: "基于混沌(Chaos)因子的改造。你可以变身为不同形态的怪物，拥有飞行、喷火或近战撕裂的能力。", type: "exclusive"},
                    {name: "陆行鸟骑术", color: "C", cost: 120, desc: "你精通陆行鸟的驾驭技巧。无论是黄金陆行鸟还是黑色陆行鸟，都能带你翻山越岭。", type: "exclusive"},
                    {name: "巴雷特的加特林臂", color: "B", cost: 500, desc: "你的右臂被改造成了多管机枪。虽然失去了抓握能力，但获得了强大的远程火力压制。", type: "exclusive"},
                    {name: "黑魔石(Meteor)", color: "SSS", cost: 30000, desc: "召唤巨大的陨石撞击星球。这是毁灭世界的禁忌魔法，只有疯子才会使用它。", type: "exclusive"},
                    {name: "神罗总裁的钞能力", color: "A", cost: 1200, desc: "虽然你没有战斗力，但你拥有调动神罗军队和资源的权限。金钱就是力量。", type: "exclusive"}
                ]
            },
            {
