                    {name: "克苏鲁之盾", color: "B", cost: 400, desc: "赋予你冲刺能力，并在撞击敌人时造成伤害和无敌帧，专家模式的神器。", type: "exclusive"},
                    {name: "吸血飞刀", color: "S", cost: 2200, desc: "投掷出的飞刀造成伤害后会为你吸血，站撸BOSS不是梦，只要你不被秒杀。", type: "exclusive"},
                    {name: "神圣闪避", color: "A", cost: 1200, desc: "穿戴神圣套，你在攻击敌人后会获得一次完全免疫伤害的闪避机会，容错率极高。", type: "exclusive"},
                    {name: "泰拉瑞亚物理学", color: "C", cost: 150, desc: "你可以二段跳，甚至在云朵上行走，掉落伤害可以通过带个马蹄铁来消除。", type: "exclusive"},
                    {name: "海盗船坐骑", color: "S", cost: 1800, desc: "召唤一艘飞行的海盗船，虽然不够灵活，但速度极快且无限飞行。", type: "exclusive"},
                    {name: "混乱之脑", color: "B", cost: 500, desc: "受到伤害时有几率迷惑敌人并闪避攻击，虽然看脸，但关键时刻能救命。", type: "exclusive"},
                    {name: "灾厄模组(Calamity)", color: "SSS", cost: 35000, desc: "你开启了灾厄模式，面对的是神明吞噬者等变态BOSS，但你也拥有了弑神的武器和怒气条。", type: "exclusive"},
                    {name: "猪鲨公爵的翅膀", color: "A", cost: 1400, desc: "拥有极好的飞行性能，且在液体中移动速度不减反增。", type: "exclusive"},
                    {name: "丛林生长", color: "C", cost: 180, desc: "你的攻击附带毒素，且在丛林环境中生命回复速度加快。", type: "exclusive"},
                    {name: "旅商的帽子", color: "C", cost: 100, desc: "你总能遇到旅商，并且他卖的都是好东西（比如同伴方块或王朝木）。", type: "exclusive"},
                    {name: "最后棱镜", color: "SS", cost: 7000, desc: "法师的终极武器。汇聚成一条毁灭性的光束，耗蓝极快，但能瞬间融化一切。", type: "exclusive"},
                    {name: "召唤师巅峰", color: "S", cost: 2800, desc: "你的召唤栏位+10，身后跟着一支军队，你只需要躲避，剩下的交给小弟。", type: "exclusive"},
                    {name: "大师模式圣物", color: "B", cost: 300, desc: "击败BOSS后会掉落金色的圣物雕像，除了好看和发光外，是荣耀的证明。", type: "exclusive"},
                    {name: "重铸：传说", color: "A", cost: 1000, desc: "你的所有武器在获得时自动获得“传说”、“神级”或“虚幻”的最佳前缀。", type: "exclusive"}
                ]
            },
            {
                name: "419.饥荒 (Don''t Starve)",
                desc: "一个哥特画风的残酷生存世界。你被恶魔麦斯威尔传送到了永恒领域。黑暗、饥饿、精神崩溃（SAN值）是最大的敌人。四季轮转，巨鹿和熊獾在等着你。",
                boss: "暗影查理, 远古织影者, 龙蝇, 巨鹿",
                identities: [
                    { name: "第一天晚上的威尔逊", items: "还没长出来的胡子, 一个火把" },
                    { name: "精神崩溃的温蒂", items: "枯萎的花朵, 正在攻击队友的阿比盖尔" },
                    { name: "饿肚子的沃尔夫冈", items: "干瘪的肌肉, 极度恐惧黑暗" },
                    { name: "被蜘蛛围攻的韦伯", items: "几个蜘蛛腺体, 只有10点血" },
                    { name: "烧家的薇洛", items: "打火机, 一片灰烬的基地" }
                ],
                talents: [
                    {name: "黑暗恐惧症", color: "E", cost: 10, desc: "你在黑暗中SAN值下降速度加倍，且查理（黑夜怪物）会提前攻击你。", type: "exclusive"},
                    {name: "挑食", color: "D", cost: 30, desc: "你只吃新鲜的料理，拒绝吃生的食物或怪兽肉，否则会大幅扣血扣SAN。", type: "exclusive"},
                    {name: "威尔逊的胡子", color: "C", cost: 100, desc: "你会长出胡子，冬天可以保暖，刮下来还能做复活肉像。", type: "exclusive"},
                    {name: "大力士状态", color: "A", cost: 1200, desc: "当你吃饱时，体型变大，攻击力翻倍，但饥饿速度也会加快。", type: "exclusive"},
                    {name: "阿比盖尔之花", color: "S", cost: 1800, desc: "你可以召唤幽灵姐妹阿比盖尔协助战斗，她拥有群体攻击能力，是刷蜘蛛和蜜蜂的神器。", type: "exclusive"},
                    {name: "女武神战歌", color: "A", cost: 1000, desc: "你只吃肉，但战斗时会吸血吸蓝，还能制作提供防御和攻击光环的头盔与长矛。", type: "exclusive"},
                    {name: "WX-78的系统升级", color: "S", cost: 2000, desc: "你可以吃齿轮来永久提升三维上限，被雷劈中会过载加速并发光。", type: "exclusive"},
                    {name: "植物人", color: "B", cost: 600, desc: "你可以通过消耗自身状态来催熟植物，不被植物主动攻击，但容易着火。", type: "exclusive"},
                    {name: "恶魔人变身", color: "S", cost: 1600, desc: "在满月或吃下怪兽肉后变身海狸/鹿/鹅，拥有夜视和高战斗力，但无法使用物品。", type: "exclusive"},
                    {name: "老奶奶的魔法书", color: "SS", cost: 5000, desc: "你精通各种魔法书：催熟植物、召唤触手、让鸟儿沉睡。只是不能睡觉且读书扣SAN。", type: "exclusive"},
                    {name: "厨师的调味锅", color: "B", cost: 500, desc: "你拥有专属锅具和调料，做出的食物有额外BUFF，且做饭效率极高。", type: "exclusive"},
                    {name: "灵魂跳跃(沃拓克斯)", color: "S", cost: 2200, desc: "你可以收集生物死亡掉落的灵魂，用于瞬移或治疗队友，不需要吃普通食物。", type: "exclusive"},
                    {name: "时间管理大师(旺达)", color: "SS", cost: 6000, desc: "你的生命就是年龄。你可以倒流时间来回复状态，或使用老年状态打出极高爆发。", type: "exclusive"},
                    {name: "复活肉像", color: "A", cost: 1500, desc: "你懂得制作肉像的黑魔法，只要肉像存在，死亡后即可在肉像处复活。", type: "exclusive"},
                    {name: "打包术", color: "C", cost: 200, desc: "你可以将巨大的建筑打包在口袋里随身携带，随时安家。", type: "exclusive"},
                    {name: "影怪无视", color: "A", cost: 1100, desc: "当你的SAN值低时，影怪不会主动攻击你，甚至你可以控制它们。", type: "exclusive"},
                    {name: "远古科技解锁", color: "S", cost: 2500, desc: "你无需靠近远古伪科学站就能制作铥矿装备和唤星者法杖。", type: "exclusive"},
                    {name: "永恒领域的主宰", color: "SSS", cost: 30000, desc: "你取代了麦斯威尔坐在王座上，拥有控制这个世界规则的能力，但也永远被束缚。", type: "exclusive"},
                    {name: "切斯特(狗箱)", color: "B", cost: 400, desc: "你拥有眼骨，一只可爱的移动箱子怪物会永远跟着你，帮你背东西。", type: "exclusive"},
                    {name: "火女的打火机", color: "C", cost: 150, desc: "自带无限耐久的打火机，免疫火焰伤害，SAN值低时会忍不住放火。", type: "exclusive"}
                ]
            },
            {
                name: "420.传说之下 (Undertale)",
                desc: "很久以前，人类与怪物爆发战争，怪物被封印在地底。一个人类孩子掉落到了地底世界。这里独特的战斗系统允许你攻击或宽恕。你的选择决定了结局：屠杀(Genocide)或和平(Pacifist)。",
                boss: "Sans (审判者), Asgore (国王), Photoshop Flowey (精污花), Asriel Dreemurr",
                identities: [
                    { name: "刚掉下来的决心人类", items: "一根木棍, 一条绷带" },
                    { name: "雪镇的骷髅兄弟粉丝", items: "意大利面, 蓝色卫衣" },
                    { name: "废墟里的迷路灵魂", items: "蜗牛派, 破旧的玩具刀" },
                    { name: "核心里的受雇佣兵", items: "空枪, MTT品牌的汉堡" },
                    { name: "真实验室的融合怪", items: "融化的身体, 痛苦的记忆" }
                ],
                talents: [
                    {name: "LV 1 (LOVE)", color: "C", cost: 100, desc: "你的暴力指数为1。你很容易受伤害，但你拥有一颗善良的心，容易结交朋友。", type: "exclusive"},
                    {name: "决心 (Determination)", color: "SSS", cost: 50000, desc: "打破生死的界限。只要你拥有决心，死亡后可以读取存档（SAVE/LOAD），甚至重置（RESET）整个世界。", type: "exclusive"},
                    {name: "蓝色灵魂(重力)", color: "A", cost: 1200, desc: "你的灵魂变为蓝色，受到重力影响，可以在战斗中进行跳跃躲避骨头攻击。", type: "exclusive"},
                    {name: "绿色灵魂(格挡)", color: "A", cost: 1200, desc: "你的灵魂变为绿色，不能移动，但可以举盾格挡来自四个方向的矛。", type: "exclusive"},
                    {name: "Sans的审判眼", color: "SS", cost: 8000, desc: "你可以操控重力，召唤骨头和龙骨炮（Gaster Blaster），并拥有业报伤害（KR），对罪恶之人造成持续伤害。", type: "exclusive"},
                    {name: "鱼姐的战意", color: "S", cost: 2500, desc: "当你为了保护他人而战时，决心爆发，拒绝死亡，变身为不死图腾般的战士。", type: "exclusive"},
                    {name: "羊妈的火焰魔法", color: "B", cost: 600, desc: "你可以召唤温和的火球，主要用于烹饪派或驱赶敌人，不想造成致命伤。", type: "exclusive"},
                    {name: "蜘蛛烘焙术", color: "C", cost: 200, desc: "你可以制作昂贵的蜘蛛甜甜圈，吃了可以回复大量HP，还能避免蜘蛛的攻击。", type: "exclusive"},
                    {name: "MTT的收视率", color: "A", cost: 1000, desc: "你的战斗变成了一场表演。你的动作越华丽，收视率越高，你能获得的奖励和防御力就越高。", type: "exclusive"},
                    {name: "花花的存档读档", color: "SS", cost: 9000, desc: "在主角到来之前，你曾拥有存档读档的能力。虽然现在不稳定，但仍能预知部分未来。", type: "exclusive"},
                    {name: "屠杀线LV 20", color: "SS", cost: 7000, desc: "你杀死了所有怪物，LOVE达到满级。你的攻击力一击必杀，HP极高，但你失去了灵魂。", type: "exclusive"},
                    {name: "真·和平大使", color: "S", cost: 3000, desc: "你拥有绝对的亲和力，无论多么凶恶的敌人，你都能通过“行动”选项感化他们，达成零杀通关。", type: "exclusive"},
                    {name: "提米盔甲", color: "SSS", cost: 15000, desc: "支付了巨额学费后获得的终极盔甲。每死一次价格降低，穿上后几乎无敌，攻击力也大幅提升。", type: "exclusive"},
                    {name: "传说中的神器(狗剩)", color: "C", cost: 50, desc: "一个被狗咬过的神器，使用了之后只会填满你的物品栏，除了卖萌一无是处。", type: "exclusive"},
                    {name: "Gaster的追随者", color: "S", cost: 2200, desc: "你存在于时空的夹缝中，偶尔会出现，知晓世界的真相和被遗忘的博士。", type: "exclusive"},
                    {name: "七彩灵魂", color: "SSS", cost: 30000, desc: "你集齐了七个人类灵魂，化身为神。你可以破坏屏障，拥有无限的力量和防御。", type: "exclusive"},
                    {name: "空枪(Empty Gun)", color: "B", cost: 500, desc: "虽然没有子弹，但如果你的射击时机完美（暴击），能造成惊人的伤害。", type: "exclusive"},
                    {name: "只会说冷笑话", color: "D", cost: 30, desc: "你忍不住要讲关于骨头的冷笑话，这会让Papyrus抓狂，但能逗笑Sans。", type: "exclusive"},
                    {name: "皇家卫队的训练", color: "B", cost: 400, desc: "你接受过正规训练，懂得如何识别气味（像狗一样）和使用斧头。", type: "exclusive"},
                    {name: "Chara的附身", color: "SS", cost: 6500, desc: "当你看到999999伤害时，那个堕落的孩子接管了你的身体。你成为了纯粹的杀戮机器。", type: "exclusive"}
                ]
            },
              {
        name: "421.空洞骑士",
        desc: "一个早已陨落的昆虫王国——圣巢。瘟疫与梦境交织，地下深处埋藏着古老的秘密。这里只有无尽的战斗、跳跃与受苦。",
        boss: "辐光, 纯粹容器, 梦魇之王格林",
        identities: [
            { name: "遗忘十字路的躯壳", items: "破损的面具, 几枚吉欧" },
            { name: "泪城避雨的贵族尸骸", items: "湿透的华服, 一把生锈的旧钉" },
            { name: "深邃巢穴的迷路冒险者", items: "用完的照明灯, 满身的蜘蛛咬痕" },
            { name: "愚人斗兽场的观众", items: "一张被揉烂的门票, 对鲜血的渴望" },
            { name: "水晶山峰的挖掘工", items: "一把矿镐, 逐渐结晶化的皮肤" }
        ],
        talents: [
            {name: "虚空之心(残片)", color: "SS", cost: 9000, desc: "深渊的本质，能够统御虚空。虽然只是残片，但你已经不再被阴影攻击，甚至能命令弱小的暗影生物。", type: "exclusive"},
            {name: "纯粹骨钉技艺", color: "S", cost: 2500, desc: "骨钉贤者亲传的剑术。包含旋风斩、冲刺斩和强力劈砍。你的每一次攻击都势大力沉，足以击碎甲壳。", type: "exclusive"},
            {name: "复仇之魂", color: "A", cost: 800, desc: "利用灵魂力量释放出的白色冲击波。虽然消耗灵魂，但能穿透墙壁和敌人，是远程打击的利器。", type: "exclusive"},
            {name: "蛾翼披风", color: "B", cost: 500, desc: "用某种发光的丝线编织而成，允许你在空中进行一次水平冲刺，是在这个充满刺的地下世界存活的关键。", type: "exclusive"},
            {name: "帝王之翼", color: "A", cost: 1200, desc: "苍白之王赐予的二段跳能力。这双发光的虚幻翅膀能让你抵达常人无法触及的高处。", type: "exclusive"},
            {name: "聚集(灵魂回复)", color: "C", cost: 200, desc: "通过长时间的专注，消耗体内的灵魂来修复身体的伤口。但在聚集时你无法移动，极易被打断。", type: "exclusive"},
            {name: "萨满之石", color: "A", cost: 750, desc: "不仅能增强法术的威力，还能显著增大法术的判定范围。对于法师流派来说是核心护符。", type: "exclusive"},
            {name: "快速劈砍", color: "S", cost: 2200, desc: "你的挥剑速度快得惊人，能在短时间内倾泻出暴风雨般的攻击，真正的DPS神器。", type: "exclusive"},
            {name: "骄傲印记", color: "A", cost: 900, desc: "螳螂部落的信物，大幅增加你骨钉的攻击距离。一寸长一寸强，让你在安全距离风筝敌人。", type: "exclusive"},
            {name: "苦痛荆棘", color: "C", cost: 150, desc: "当你受到伤害时，身体周围会自动爆发出黑色的荆棘触手反击敌人。虽然伤害不高，但看着解气。", type: "exclusive"},
            {name: "指南针", color: "SSS", cost: 15000, desc: "在这个错综复杂的地下迷宫中，只有它能告诉你“你在哪”。对于路痴来说，它比神话级武器更重要。", type: "exclusive"},
            {name: "易碎力量", color: "B", cost: 400, desc: "大幅提升攻击力，但极其脆弱。一旦你死亡，这个护符就会碎裂消失。高风险高回报。", type: "exclusive"},
            {name: "梦之钉", color: "S", cost: 3000, desc: "能够切割梦境的武器。不造成物理伤害，但能读取生物的思想，并从敌人身上抽取大量的灵魂。", type: "exclusive"},
            {name: "苍白矿石", color: "B", cost: 600, desc: "稀有的锻造材料，虽然不能直接使用，但只要找到钉子匠，就能把你的武器提升一个档次。", type: "exclusive"},
            {name: "简单的钥匙", color: "C", cost: 180, desc: "能打开圣巢中各种简单的锁。有时候，一把钥匙就是通往新区域或新NPC的唯一途径。", type: "exclusive"},
            {name: "腐臭蛋", color: "D", cost: 50, desc: "散发着令人作呕的气味。虽然看起来像垃圾，但在某些特定的NPC那里可能换到点好处，或者用来赎回阴影。", type: "exclusive"},
            {name: "幼虫之歌", color: "C", cost: 160, desc: "受到伤害时回复少量灵魂。对于经常挨打的新手来说，这是确保持续回血的永动机。", type: "exclusive"},
            {name: "蜂巢之血", color: "A", cost: 1100, desc: "你的血液变成了蜂蜜。受到伤害后，最近一次损失的生命值会在一段时间后自动恢复。跑酷神器。", type: "exclusive"},
            {name: "锋利之影", color: "A", cost: 1000, desc: "你的暗影冲刺现在具有攻击判定，不仅能穿过敌人，还能造成相当于骨钉的伤害。", type: "exclusive"},
            {name: "吸虫之巢", color: "B", cost: 550, desc: "将你的复仇之魂变成一大群扭曲的吸虫。近距离爆发伤害极高，但那画面实在太掉SAN值了。", type: "exclusive"},
            {name: "发光子宫", color: "C", cost: 190, desc: "消耗灵魂自动孵化出这种自爆小苍蝇攻击敌人。虽然伤害一般，但在挂机或处理杂兵时很方便。", type: "exclusive"},
            {name: "国王神像", color: "C", cost: 250, desc: "苍白之王的塑像，除了卖给文物搜寻者换点钱之外，没什么实际用途，但做工很精美。", type: "exclusive"},
            {name: "神居调谐器", color: "SS", cost: 8000, desc: "允许你进入诸神的堂屋，挑战圣巢历史上所有强者的梦境形态。只有最疯狂的战士才会追求这个。", type: "exclusive"},
            {name: "感染气球", color: "D", cost: 30, desc: "体内充满了橙色的瘟疫气体，一碰就炸。除了自杀式袭击，实在想不出有什么用。", type: "exclusive"},
            {name: "左特之口", color: "E", cost: 10, desc: "你获得了“灰色王子”左特的话痨属性。你会不停地用难听的声音念叨这一百条戒律，直到队友崩溃。", type: "exclusive"},
            {name: "梦门", color: "A", cost: 1300, desc: "消耗1点梦境精华，设置一个传送点，并随时传送回去。在这个没有快速旅行的世界里简直是神技。", type: "exclusive"},
            {name: "水晶之心", color: "B", cost: 650, desc: "你可以通过蓄力进行超远距离的水平飞行，直到撞到墙壁。小心别飞进刺里。", type: "exclusive"},
            {name: "伊斯玛的眼泪", color: "B", cost: 700, desc: "这滴酸液抗性泪水能让你在酸水中游泳而不会受到伤害。探索下水道和雾之峡谷的必备品。", type: "exclusive"},
            {name: "黑卵的封印", color: "SSS", cost: 20000, desc: "你成为了新的容器。你将独自一人被封印在黑卵之中，容纳所有的瘟疫，以此拯救世界。这是一种伟大的牺牲。", type: "exclusive"},
            {name: "虚空卷须", color: "S", cost: 2800, desc: "你的身体可以短暂地化为纯粹的虚空触手，对周围进行大范围的横扫攻击，随后重组。", type: "exclusive"}
        ]
    },
    {
        name: "422.极乐迪斯科",
        desc: "瑞瓦肖，一个被灰域包围的破碎城市。这里没有魔法，只有意识形态的战争、酒精、迪斯科和无尽的内心独白。",
        boss: "灰域, 极乐世界本身, 你的前妻",
        identities: [
            { name: "马丁内斯的罢工工人", items: "一块板砖, 满腔的阶级怒火" },
            { name: "野松公司的谈判代表助理", items: "精致的钢笔, 虚伪的笑容" },
            { name: "落魄的地下狂欢者", items: "荧光涂料, 听力受损的耳朵" },
            { name: "诅咒商业区的流浪汉", items: "半瓶朗姆酒, 奇怪的领带" },
            { name: "RCM警局的实习警员", items: "写满字的记事本, 借来的警徽" }
        ],
        talents: [
            {name: "内陆帝国(通灵)", color: "SS", cost: 7500, desc: "你的想象力极其丰富，甚至能与无生命的物体对话。领带会给你提建议，垃圾桶会告诉你秘密。", type: "exclusive"},
            {name: "神圣而可怕的空气", color: "SSS", cost: 18000, desc: "你不仅是侦探，你是迪斯科的化身，是旧时代的幽灵。你的存在本身就能扭曲周围人的现实认知。", type: "exclusive"},
            {name: "逻辑(天才)", color: "S", cost: 3200, desc: "你的大脑像一台精密的计算机。你能瞬间分析出案件的矛盾点，构建出完美的推理链条。", type: "exclusive"},
            {name: "钢筋铁骨", color: "A", cost: 1500, desc: "你的身体素质好得不科学。即使酗酒、嗑药、挨打，你依然能站起来，甚至能徒手把门撞开。", type: "exclusive"},
            {name: "瑞瓦肖民族主义", color: "C", cost: 250, desc: "你对这片土地有着扭曲的热爱。在对抗外来势力时，你的士气会高涨，但容易变得排外。", type: "exclusive"},
            {name: "康米主义思维", color: "B", cost: 600, desc: "你坚信历史唯物主义，虽然现在看起来像是失败了，但你总是能从宏观经济角度批判现状。", type: "exclusive"},
            {name: "超级巨星警探", color: "B", cost: 500, desc: "你认为自己是摇滚明星。这种盲目的自信让你在社交场合无往不利，虽然大家看你像个傻子。", type: "exclusive"},
            {name: "苍白(灰域)适应性", color: "S", cost: 4000, desc: "你能在吞噬世界的“灰域”中保持理智更长时间。这是一种极其罕见的特质，通常属于那些已经疯了的人。", type: "exclusive"},
            {name: "标新立异", color: "A", cost: 1200, desc: "你的行为完全不可预测。这种混乱的能量让你总能发现常人忽略的线索，或者搞砸一切。", type: "exclusive"},
            {name: "食髓知味", color: "D", cost: 100, desc: "你对酒精和药物的抗性极低，一旦沾染就无法自拔。虽然能短暂提升属性，但长期来看是毁灭性的。", type: "exclusive"},
            {name: "天人感应(Shivers)", color: "SS", cost: 8200, desc: "你能听到城市的呼吸。瑞瓦肖的风、雨、街道都在向你低语，告诉你此时此刻城市另一端发生的事。", type: "exclusive"},
            {name: "五感发达", color: "B", cost: 450, desc: "你的视觉、听觉和嗅觉极其敏锐。你能闻出嫌疑人身上的廉价香水味，或者看到地毯上的微小脚印。", type: "exclusive"},
            {name: "能说会道(Rhetoric)", color: "A", cost: 1100, desc: "你是天生的辩论家。你能用复杂的政治术语把人绕晕，或者用尖锐的讽刺击碎对方的防线。", type: "exclusive"},
            {name: "同理心", color: "A", cost: 1000, desc: "你能敏锐地察觉到他人的情绪波动。这让你在审讯时能准确把握对方的心理防线。", type: "exclusive"},
            {name: "恐怖领带", color: "C", cost: 220, desc: "一条花色极其丑陋的领带，但在关键时刻，它似乎能给你带来某种奇怪的好运，或者只是单纯的心理安慰。", type: "exclusive"},
            {name: "未知的费洛蒙", color: "B", cost: 550, desc: "你身上散发着一种让人想要亲近又想要远离的气味。这让你在异性面前有着奇怪的魅力。", type: "exclusive"},
            {name: "末日警探", color: "C", cost: 300, desc: "你坚信世界即将毁灭。这种悲观主义让你在面对灾难时反而异常冷静，因为你早就预料到了。", type: "exclusive"},
            {name: "平克顿侦探社培训", color: "B", cost: 700, desc: "你接受过专业的私家侦探训练。虽然比不上RCM的野路子，但在跟踪和窃听方面很有一手。", type: "exclusive"},
            {name: "旧伤复发", color: "E", cost: 50, desc: "你的腿部或背部有旧伤，在阴雨天会剧烈疼痛，严重影响你的行动能力和士气。", type: "exclusive"},
            {name: "强光手电筒", color: "C", cost: 120, desc: "一把警用手电筒。在探索黑暗的地下室或废弃建筑时必不可少，还能用来晃瞎敌人的眼睛。", type: "exclusive"},
            {name: "金属探测器", color: "C", cost: 180, desc: "能帮你找到埋藏在地下的硬币或废金属。对于一个穷困潦倒的侦探来说，这是重要的收入来源。", type: "exclusive"},
            {name: "指节铜环", color: "B", cost: 350, desc: "街头斗殴的神器。当你决定用暴力解决问题时，它能让你的拳头更有说服力。", type: "exclusive"},
            {name: "撬棍", color: "B", cost: 400, desc: "物理开锁的终极工具。不仅能撬开箱子和门，也是一把不错的钝器。", type: "exclusive"},
            {name: "收音机", color: "C", cost: 150, desc: "一台老式收音机，能收听到警局的频道，或者是充满杂音的迪斯科音乐。", type: "exclusive"},
            {name: "道德家", color: "C", cost: 200, desc: "你总是追求中庸之道，不做任何激进的决定。这让你看起来很稳重，但也极其无聊。", type: "exclusive"},
            {name: "超自由主义", color: "B", cost: 650, desc: "你认为金钱就是一切。你的所有行动都是为了搞钱，这让你在商业谈判中极具优势。", type: "exclusive"},
            {name: "相位移动(Bug)", color: "S", cost: 5000, desc: "你似乎卡在了现实的贴图里。你可以偶尔穿过墙壁，或者瞬间移动到屋顶。这是世界的漏洞。", type: "exclusive"},
            {name: "金·曷城的信任", color: "SS", cost: 9500, desc: "你获得了金警督的完全信任。在这个疯狂的世界里，有一个绝对可靠、冷静且支持你的搭档，比什么都重要。", type: "exclusive"},
            {name: "失忆症", color: "D", cost: 80, desc: "你彻底忘记了自己是谁，甚至忘记了人类的基本常识。但这也许是一个重新开始的好机会。", type: "exclusive"},
            {name: "极乐世界的真理", color: "SSS", cost: 30000, desc: "你理解了这个世界的本质——它只是一个巨大的、缓慢腐烂的思维产物。你可以改写部分现实。", type: "exclusive"}
        ]
    },
    {
        name: "423.传送门 (Portal)",
        desc: "光圈科技的地下实验室。这里只有白色的墙壁、致命的机关、谎言蛋糕，以及一个想要杀死你的AI——GLaDOS。",
        boss: "GLaDOS, 惠特利, 炮塔大军",
        identities: [
            { name: "刚苏醒的测试对象", items: "橙色连体囚服, 长期休眠后的眩晕感" },
            { name: "光圈科技的前员工", items: "一张过期的ID卡, 满腹的牢骚" },
            { name: "躲在天花板里的幸存者", items: "一罐豆子罐头, 画满涂鸦的墙壁" },
            { name: "被废弃的测试机器人", items: "断裂的机械臂, 总是卡顿的语音模块" },
            { name: "维护区的清洁工", items: "一把拖把, 对白色凝胶的恐惧" }
        ],
        talents: [
            {name: "传送门枪(ASHPD)", color: "SS", cost: 9500, desc: "光圈科技手持传送门设备。能在任意白色表面打开橙色和蓝色两个传送门。掌握动量守恒，你就是神。", type: "exclusive"},
            {name: "长脚高空掉落靴", color: "S", cost: 4000, desc: "能够完全吸收从任意高度坠落的冲击力。没有它，你在第一个测试室就会摔成肉泥。", type: "exclusive"},
            {name: "重量同伴方块", color: "A", cost: 1500, desc: "一个画着爱心的金属方块。它不会说话，但它是你在这个孤独地狱里唯一的朋友。甚至能帮你挡子弹。", type: "exclusive"},
            {name: "蓝色凝胶(排斥)", color: "B", cost: 800, desc: "涂有这种凝胶的表面会让你像弹簧一样跳得极高。小心别在狭窄的地方使用，会撞头。", type: "exclusive"},
            {name: "橙色凝胶(加速)", color: "B", cost: 800, desc: "这种凝胶能让摩擦力消失。在上面奔跑能让你瞬间达到极高的速度，配合传送门能飞越鸿沟。", type: "exclusive"},
            {name: "白色凝胶(转换)", color: "A", cost: 1200, desc: "这种月球岩石提取物能把任何表面变成可以开启传送门的面板。战术价值极高。", type: "exclusive"},
            {name: "炮塔黑客技术", color: "A", cost: 1000, desc: "你掌握了重新编程机枪炮塔的技术。让它们把枪口对准敌人，或者干脆唱起歌来。", type: "exclusive"},
            {name: "GLaDOS的土豆形态", color: "C", cost: 300, desc: "在这个形态下，超级AI GLaDOS只能依靠一颗土豆供电。虽然嘴依然很毒，但毫无威胁，还能当军师。", type: "exclusive"},
            {name: "蛋糕(谎言)", color: "E", cost: 1, desc: "一个看起来很美味的黑森林蛋糕。但它是一个谎言，你永远也吃不到它。", type: "exclusive"},
            {name: "动量直觉", color: "B", cost: 600, desc: "你对物理法则有天生的直觉。你能瞬间计算出进出门的角度和速度，完成不可能的空中飞跃。", type: "exclusive"},
            {name: "热能光束盘", color: "C", cost: 400, desc: "一种能够重定向高能激光的装置。既可以用来解谜，也可以用来烧穿敌人的护甲。", type: "exclusive"},
            {name: "硬光桥技术", color: "B", cost: 700, desc: "你可以召唤或利用半透明的硬光桥。既可以作为行走的道路，也可以作为阻挡攻击的护盾。", type: "exclusive"},
            {name: "牵引光束", color: "B", cost: 700, desc: "一种蓝色的漏斗状力场，能让你在其中无视重力移动。虽然速度慢，但很安全。", type: "exclusive"},
            {name: "神经毒素抗性", color: "A", cost: 1100, desc: "经过长期暴露，你对GLaDOS最喜欢的致命神经毒素产生了一定的抗性。能让你多活几分钟。", type: "exclusive"},
            {name: "核心性格球(惠特利)", color: "D", cost: 150, desc: "一个设计初衷就是为了产生蠢主意的AI核心。带上它会降低你的智商，但偶尔能误打误撞。", type: "exclusive"},
            {name: "螳螂人血统", color: "C", cost: 250, desc: "早期测试的失败产物。你长出了螳螂的前臂。虽然看起来很恶心，但格斗能力不错。", type: "exclusive"},
            {name: "燃烧柠檬", color: "B", cost: 500, desc: "凯文·约翰逊发明的易燃柠檬。别要生活给你的柠檬，把柠檬炸回去！能烧毁房子。", type: "exclusive"},
            {name: "光圈科技水下呼吸器", color: "C", cost: 200, desc: "虽然这里大部分是室内，但在有毒废水中，这个装置能救你一命。", type: "exclusive"},
            {name: "无声步伐", color: "B", cost: 450, desc: "你的长脚靴经过改装，走路完全没有声音。这对于躲避听声辨位的炮塔非常有用。", type: "exclusive"},
            {name: "月球岩石中毒", color: "E", cost: 50, desc: "长期接触月球岩石粉末导致你的肺部受损。你会不停咳嗽，体力上限降低。", type: "exclusive"},
            {name: "空间折叠感知", color: "S", cost: 3000, desc: "在使用传送门数千次后，你的大脑适应了非欧几里得几何。你不会再因为空间变换而晕眩。", type: "exclusive"},
            {name: "光圈科技AI权限", color: "SSS", cost: 25000, desc: "你获得了设施的最高管理员权限。你可以控制整个实验室的结构变换，甚至命令GLaDOS。", type: "exclusive"},
            {name: "机械臂义肢", color: "A", cost: 1300, desc: "一只光圈科技生产的多功能机械手，力量巨大，且内置了多种接口工具。", type: "exclusive"},
            {name: "火箭炮塔", color: "A", cost: 1400, desc: "能够发射火箭弹的高级炮塔。虽然锁定时间长，但威力足以炸碎玻璃和混凝土。", type: "exclusive"},
            {name: "流体动力学精通", color: "C", cost: 350, desc: "你非常擅长利用管道传输各种凝胶和方块，是解谜的好手。", type: "exclusive"},
            {name: "老鼠人涂鸦指引", color: "B", cost: 550, desc: "你总能发现前人留下的隐藏涂鸦。这些涂鸦往往指出了监控死角和逃生路线。", type: "exclusive"},
            {name: "纳米机器人修复", color: "S", cost: 3500, desc: "体内的纳米机器人会在你脱离战斗后快速修复身体损伤。这是测试对象能活这么久的原因。", type: "exclusive"},
            {name: "光圈科技午餐盒", color: "C", cost: 100, desc: "里面只有难吃的脱水食物，但能保证你在这个封闭设施里不会饿死。", type: "exclusive"},
            {name: "爱心方块的低语", color: "D", cost: 120, desc: "你开始听到方块在说话。这说明你的理智值正在下降，但有时候方块是对的。", type: "exclusive"},
            {name: "永恒测试", color: "SS", cost: 8000, desc: "你被诅咒永远进行测试，但也因此获得了不死性。只要测试没结束，你就不会真正死亡。", type: "exclusive"}
        ]
    },
    {
        name: "424.半衰期 (Half-Life)",
        desc: "黑山事件后，地球被跨维度帝国“联合军”占领。这里是反抗军的战场，充满猎头蟹、僵尸和高科技压迫。",
        boss: "联合军顾问, 尼赫伦特, G-Man",
        identities: [
            { name: "黑山基地的幸存科学家", items: "白大褂, 满脑子的物理公式" },
            { name: "17号城市的顺民", items: "蓝色囚服, 一罐难喝的水" },
            { name: "反抗军的新兵", items: "一把冲锋枪, 破旧的防弹背心" },
            { name: "联合军国民护卫队(CP)", items: "防毒面具, 电击棍" },
            { name: "莱温霍姆的疯神父", items: "一把猎枪, 各种机关陷阱" }
        ],
        talents: [
            {name: "HEV防护服(MK V)", color: "SS", cost: 8800, desc: "戈登·弗里曼同款。提供防弹、防辐射、防毒功能，内置吗啡注射系统和语音助手。物理学家的战甲。", type: "exclusive"},
            {name: "零点能量场牵引器(重力枪)", color: "S", cost: 4500, desc: "能够吸取并高速弹射物体。无论是锯片、油桶还是手雷，在你手中都是致命武器。甚至能抓取敌人。", type: "exclusive"},
            {name: "物理学圣剑(撬棍)", color: "A", cost: 1200, desc: "一把红色的撬棍。它能敲碎箱子，也能敲碎外星人的头骨。在这个世界里，它是绝对力量的象征。", type: "exclusive"},
            {name: "猎头蟹宠物(去喙)", color: "B", cost: 600, desc: "一只被切除了攻击器官的猎头蟹，像小狗一样听话。虽然长得吓人，但能帮你预警敌人。", type: "exclusive"},
            {name: "联合军生化改造", color: "A", cost: 1500, desc: "你的身体经过了联合军的改造，痛觉被抑制，力量和反应速度大幅提升，但逐渐失去人性。", type: "exclusive"},
            {name: "蚁狮费洛蒙", color: "S", cost: 3200, desc: "一种能够控制凶残蚁狮群的信息素球。拥有它，你就拥有一支不知疲倦的虫族大军。", type: "exclusive"},
            {name: "克莱纳的传送技术", color: "A", cost: 2000, desc: "虽然不太稳定，但你掌握了局部的空间传送技术。这在逃离联合军包围时非常有用。", type: "exclusive"},
            {name: "盖革计数器直觉", color: "C", cost: 250, desc: "你能在没有仪器的情况下感知到周围的辐射水平。在这个充满核废料的世界很有用。", type: "exclusive"},
            {name: "马格南左轮精通", color: "B", cost: 800, desc: "你使用左轮手枪的技巧出神入化，能够一枪精准爆头。这种大口径武器是对付重甲敌人的利器。", type: "exclusive"},
            {name: "藤壶怪伪装", color: "C", cost: 300, desc: "你学会了利用藤壶怪的长舌头进行垂直移动，或者设下陷阱让敌人被吞噬。", type: "exclusive"},
            {name: "Strider(三脚机甲)驾驶", color: "A", cost: 1800, desc: "你掌握了驾驶联合军巨型三脚机甲的技术。那种居高临下扫射一切的感觉简直无敌。", type: "exclusive"},
            {name: "弗地冈人能量束", color: "S", cost: 3500, desc: "你学会了弗地冈人的能量引导术，能从双手发射绿色的闪电，不仅能攻击还能给电池充电。", type: "exclusive"},
            {name: "G-Man的关注", color: "SSS", cost: 30000, desc: "那个提着公文包的神秘人注意到了你。他可能会在必死之局中救你一次，但代价是你必须为他工作。", type: "exclusive"},
            {name: "蜂巢枪", color: "B", cost: 900, desc: "外星生物武器，能发射自动追踪敌人的飞虫。子弹无限且自动回复，非常适合巷战。", type: "exclusive"},
            {name: "暗能量球", color: "S", cost: 2800, desc: "一种极其不稳定的高能球体。一旦发射，会在房间内疯狂弹跳并蒸发接触到的一切有机物。", type: "exclusive"},
            {name: "医疗包依赖", color: "D", cost: 100, desc: "你对HEV防护服的医疗系统产生依赖，如果长时间不注射吗啡或回复生命，你会出现戒断反应。", type: "exclusive"},
            {name: "联合军狙击弩", color: "A", cost: 1100, desc: "发射红热的钢筋，能把敌人钉在墙上。无声且致命，是暗杀者的最爱。", type: "exclusive"},
            {name: "猎头蟹僵尸伪装", color: "C", cost: 200, desc: "通过特殊的涂装和动作，你可以混入僵尸群中而不被攻击。但要小心别被队友打了。", type: "exclusive"},
            {name: "狗(Dog)的护卫", color: "SS", cost: 9000, desc: "艾利博士制造的巨型机器人保镖。虽然名字叫狗，但它能单挑装甲车，是你最忠诚的盾牌。", type: "exclusive"},
            {name: "Xen水晶共鸣", color: "B", cost: 700, desc: "你对来自Xen维度的水晶有特殊的感应，能利用它们引发小规模的共振级联现象。", type: "exclusive"},
            {name: "城市巷战专家", color: "B", cost: 500, desc: "在17号城市的废墟中练就的身手，擅长利用掩体、地雷和诡雷进行游击战。", type: "exclusive"},
            {name: "联合军飞锯黑客", color: "C", cost: 350, desc: "你能重新编程那些烦人的飞锯机器人，让它们围绕着你旋转，切割靠近的敌人。", type: "exclusive"},
            {name: "长跳模组", color: "A", cost: 1000, desc: "HEV防护服的附件，允许你进行极远距离的跳跃。在平台跳跃和快速突进时必不可少。", type: "exclusive"},
            {name: "沉默的主角", color: "C", cost: 150, desc: "你极其不爱说话。奇怪的是，这反而让NPC更愿意把所有秘密都告诉你。", type: "exclusive"},
            {name: "微波炉意面事故", color: "E", cost: 10, desc: "你总是会把微波炉里的食物炸开。这会激怒周围的科学家，降低好感度。", type: "exclusive"},
            {name: "抑制力场干扰器", color: "A", cost: 1600, desc: "能让你穿过联合军的能量屏障，或者让敌人的武器暂时失效。", type: "exclusive"},
            {name: "Tau加农炮", color: "S", cost: 3800, desc: "实验性武器，能发射高能粒子束。蓄力射击甚至能利用反作用力让你飞起来。", type: "exclusive"},
            {name: "时间静止(G-Man体验卡)", color: "SS", cost: 12000, desc: "短暂地进入G-Man的时间夹缝。你可以自由移动，而周围的一切都静止不动。", type: "exclusive"},
            {name: "猎枪士兵", color: "B", cost: 650, desc: "你掌握了双管猎枪的使用技巧，能在近距离造成毁灭性的打击。", type: "exclusive"},
            {name: "反物质反应堆知识", color: "A", cost: 2200, desc: "你懂得如何操作和破坏核心反应堆。这在关键时刻是谈判的筹码。", type: "exclusive"}
        ]
    },
    {
        name: "425.黑神话：悟空",
        desc: "西游之后的黑暗神话世界。天命人踏上重走西游路，收集大圣根器。这里妖魔横行，神佛虚伪，只有手中的棍子是真实的。",
        boss: "二郎神, 黄眉, 大圣残躯",
        identities: [
            { name: "花果山的小猴子", items: "一颗桃子, 一根木棍" },
            { name: "黑风山的巡山小妖", items: "一面破锣, 狼牙棒" },
            { name: "小西天的盲眼僧人", items: "一串佛珠, 破旧的袈裟" },
            { name: "盘丝洞的被捕猎户", items: "断掉的弓箭, 满身蛛网" },
            { name: "火焰山的焦尸", items: "未燃尽的余火, 痛苦的执念" }
        ],
        talents: [
            {name: "定身法", color: "S", cost: 3500, desc: "“定！”指尖一点，让敌人瞬间动弹不得。无论是打断技能还是争取输出时间，都是神技。", type: "exclusive"},
            {name: "聚形散气(隐身)", color: "S", cost: 3200, desc: "留在一个假身吸引火力，本体化为不可见的烟雾移动。破隐一击能造成巨额伤害。", type: "exclusive"},
            {name: "铜头铁臂", color: "A", cost: 1500, desc: "瞬间将身体金属化，弹开敌人的攻击并造成硬直。高手以此来无伤弹反。", type: "exclusive"},
            {name: "身外身法(毫毛)", color: "SS", cost: 9000, desc: "拔一把毫毛，变出无数个分身群殴敌人。虽然分身脆皮，但胜在人多势众，场面极其壮观。", type: "exclusive"},
            {name: "大圣根器(眼看喜)", color: "SS", cost: 8000, desc: "六根之一，赋予你洞察弱点和暴击的能力。你能看穿妖怪的本质，招招致命。", type: "exclusive"},
            {name: "七十二变(化身)", color: "S", cost: 5000, desc: "你可以变身成击败过的妖怪，使用它们的技能和血条。多一条命，多一种战术。", type: "exclusive"},
            {name: "如意金箍棒(仿)", color: "A", cost: 2500, desc: "虽然不是定海神针本尊，但依然重达千斤，且能随心意变长变短。物理超度首选。", type: "exclusive"},
            {name: "识破(见切)", color: "A", cost: 1800, desc: "在敌人攻击的瞬间闪避并反击，能看破敌人的招式。高风险高回报的战斗技巧。", type: "exclusive"},
            {name: "安身法(画地为牢)", color: "B", cost: 800, desc: "用棍子在地上画个圈。圈内回血、回蓝、增加棍势。只要不出圈，你就是安全的。", type: "exclusive"},
            {name: "立棍式", color: "B", cost: 600, desc: "将棍子竖起，整个人爬到棍顶躲避地面攻击。还能蓄力打出强力的下劈。", type: "exclusive"},
            {name: "戳棍式", color: "B", cost: 600, desc: "像长枪一样使用棍子，快速突刺。攻击距离远，适合风筝和打断。", type: "exclusive"},
            {name: "劈棍式", color: "B", cost: 600, desc: "最朴实无华的招式，蓄力重劈。也是伤害最高的一击，力劈华山。", type: "exclusive"},
            {name: "广智(赤潮)变身", color: "A", cost: 1200, desc: "变身为狼妖广智，手持火刀。攻击附带燃烧效果，且动作敏捷，是前期推图利器。", type: "exclusive"},
            {name: "幽魂(大头)精魄", color: "B", cost: 500, desc: "召唤大头和尚的幻影，用巨大的铁头撞击敌人。虽然前摇长，但削韧极高，能把BOSS撞倒。", type: "exclusive"},
            {name: "葫芦(恢复)", color: "C", cost: 300, desc: "你的药瓶。可以装各种酒，不仅回血，配合泡酒物还能提供各种BUFF。", type: "exclusive"},
            {name: "避火罩", color: "A", cost: 1000, desc: "法宝之一，开启后免疫所有火属性伤害，并在周围形成火环烧伤敌人。打火焰山必备。", type: "exclusive"},
            {name: "定风珠", color: "A", cost: 1000, desc: "法宝之一，能定住狂风。专门克制那些喜欢乱飞或者放龙卷风的BOSS。", type: "exclusive"},
            {name: "绣花针", color: "A", cost: 1000, desc: "法宝之一，专破百眼魔君的金光阵。也能作为自动攻击的浮游炮使用。", type: "exclusive"},
            {name: "藕丝步云履", color: "S", cost: 3000, desc: "大圣套装之一。穿上它，身轻如燕，闪避距离和无敌帧大幅增加。", type: "exclusive"},
            {name: "锁子黄金甲", color: "S", cost: 3200, desc: "大圣套装之一。防御力惊人，且在暴击时能减少法术冷却。", type: "exclusive"},
            {name: "凤翅紫金冠", color: "S", cost: 3000, desc: "大圣套装之一。增加法力上限，让你能更频繁地使用定身法。", type: "exclusive"},
            {name: "救命毫毛", color: "SS", cost: 7000, desc: "观音赐予的保命符。当你生命值归零时，自动复活并恢复一定状态。每场战斗限一次。", type: "exclusive"},
            {name: "火眼金睛", color: "SS", cost: 8500, desc: "能看穿一切伪装和隐身。在面对会分身或隐形的妖魔时，它们在你眼中无所遁形。", type: "exclusive"},
            {name: "法天象地", color: "SSS", cost: 35000, desc: "大神通。身躯化为万丈高，力量无穷无尽。能与巨型神魔肉搏，每一脚都能踏碎山河。", type: "exclusive"},
            {name: "土地公的指引", color: "C", cost: 150, desc: "每到一个新地方，总能遇到土地公公教你法术或指路。虽然他很矮，但很有用。", type: "exclusive"},
            {name: "缩地青符", color: "C", cost: 100, desc: "不管你在哪里，使用它就能瞬间回到最近的土地庙。防止死在半路丢魂。", type: "exclusive"},
            {name: "禁字法", color: "S", cost: 4000, desc: "封印所有法术，将所有法力值转化为攻击力。纯粹的物理流派，一棍超人。", type: "exclusive"},
            {name: "玲珑内丹", color: "B", cost: 400, desc: "提升生命、法力或气力的上限。是修行的基础资源。", type: "exclusive"},
            {name: "龙鳞战袍", color: "A", cost: 1400, desc: "用龙鳞编制的战甲，对雷电属性有极高的抗性。亢金龙掉落。", type: "exclusive"},
            {name: "大圣残姿", color: "SSS", cost: 28000, desc: "你继承了孙悟空死后的战斗本能。即使没有意识，身体也会自动做出最完美的战斗反应。", type: "exclusive"}
        ]
    },
    {
        name: "426.原神 (Genshin Impact)",
        desc: "提瓦特大陆，七种元素交汇之地。你作为旅行者，游历七国，寻找失散的亲人，并揭开“天理”的真相。",
        boss: "天理维系者, 愚人众执行官, 深渊教团",
        identities: [
            { name: "蒙德城的冒险家", items: "冒险家手册, 甜甜花酿鸡" },
            { name: "璃月港的矿工", items: "铁镐, 一块石珀" },
            { name: "稻妻的反抗军武士", items: "打刀, 破旧的甲胄" },
            { name: "须弥教令院的学生", items: "虚空终端, 写不完的论文" },
            { name: "枫丹廷的潜水员", items: "潜水头盔, 异色重甲蟹能力" }
        ],
        talents: [
            {name: "神之眼(自选元素)", color: "S", cost: 5000, desc: "被神明注视的证明。获得控制火、水、风、雷、草、冰、岩中一种元素的力量。这是强者的入场券。", type: "exclusive"},
            {name: "邪眼(愚人众)", color: "A", cost: 2000, desc: "用魔神残渣制造的伪神之眼。力量强大但会透支生命。如果你没有神之眼，这是获得力量的捷径。", type: "exclusive"},
            {name: "元素视野", color: "C", cost: 200, desc: "能看到周围事物的元素痕迹。找宝箱、追踪怪物、解谜都离不开它。", type: "exclusive"},
            {name: "风之翼", color: "B", cost: 500, desc: "蒙德特产的滑翔翼。让你能从高处滑翔，是探索大世界的必备工具。注意体力消耗。", type: "exclusive"},
            {name: "便携式营养袋", color: "C", cost: 300, desc: "能装两种食物，战斗中一键进食回血。再也不用打开背包暂停吃鸡了。", type: "exclusive"},
            {name: "命之座(六命)", color: "SSS", cost: 30000, desc: "你的命运星图完全点亮。技能等级大幅提升，机制发生质变，获得毁天灭地的力量。", type: "exclusive"},
            {name: "尘歌壶", color: "A", cost: 1500, desc: "仙人赠送的壶中洞天。里面有一个属于你的小世界，可以盖房、种地、养老婆。", type: "exclusive"},
            {name: "元素爆发(Q)", color: "S", cost: 2500, desc: "积攒能量释放的终极技能。无敌帧、大范围伤害、特效拉满。这就是你的大招。", type: "exclusive"},
            {name: "钟离的护盾", color: "SS", cost: 8000, desc: "岩王帝君同款玉璋护盾。全元素减抗，厚度惊人。有了它，你就可以忘记闪避键了。", type: "exclusive"},
            {name: "雷电将军的奶香一刀", color: "SS", cost: 9000, desc: "无想的一刀。极致的雷元素爆发，能斩断空间。没有任何防御能挡住这一击。", type: "exclusive"},
            {name: "纳西妲的读心术", color: "A", cost: 1800, desc: "利用草元素连接意识，能听到NPC的心声。对于收集情报和剧情理解非常有帮助。", type: "exclusive"},
            {name: "荒星(垫脚石)", color: "B", cost: 600, desc: "召唤一个岩造物荒星。除了砸人，主要用途是垫脚爬山，或者压住机关。", type: "exclusive"},
            {name: "莫娜的虚实流动", color: "B", cost: 800, desc: "化身为水流在地面快速移动。能过河，速度快，还带嘲讽效果。", type: "exclusive"},
            {name: "班尼特的点赞领域", color: "S", cost: 3500, desc: "美妙旅程。在领域内大幅回血并增加巨额攻击力。唯一的缺点是你可能会变得很倒霉。", type: "exclusive"},
            {name: "提米的朋友", color: "D", cost: 50, desc: "你不会惊吓到桥上的鸽子。但如果你当着提米的面杀鸽子，这个天赋会失效。", type: "exclusive"},
            {name: "应急食品(派蒙)", color: "C", cost: 1000, desc: "一个会飞的小向导。虽然战斗力为零，但她能帮你接话茬，还能在关键时刻当向导（或者储备粮）。", type: "exclusive"},
            {name: "深渊法师护盾", color: "A", cost: 1200, desc: "对应元素的护盾，如果不使用克制元素很难打破。让你体验当BOSS的感觉。", type: "exclusive"},
            {name: "遗迹守卫导弹", color: "B", cost: 900, desc: "你的背部可以发射六枚追踪导弹。虽然准头一般，但火力覆盖很猛。", type: "exclusive"},
            {name: "七天神像传送", color: "S", cost: 4000, desc: "你可以像旅行者一样使用传送锚点和七天神像。在这个巨大的世界里，这是神的权能。", type: "exclusive"},
            {name: "料理精通", color: "C", cost: 150, desc: "你做出的食物有几率变成“美味的”版本，效果翻倍。甚至能做出专属特色料理。", type: "exclusive"},
            {name: "元素反应精通", color: "S", cost: 3200, desc: "你深刻理解蒸发、融化、超载等反应机制。你的攻击能触发多重反应，伤害指数级上升。", type: "exclusive"},
            {name: "风神巴巴托斯的摸鱼", color: "D", cost: 10, desc: "你非常擅长逃避工作和喝酒。这不会增加战斗力，但能让你心情愉悦。", type: "exclusive"},
            {name: "若陀龙王体质", color: "SS", cost: 8500, desc: "你拥有如同山岳般的生命值和防御力。能够根据环境切换元素属性。", type: "exclusive"},
            {name: "丝柯克的教导", color: "SS", cost: 7000, desc: "来自深渊的极意。你学会了如何运用深渊力量而不被侵蚀，战力远超普通神之眼持有者。", type: "exclusive"},
            {name: "四方之网", color: "C", cost: 250, desc: "能捕捉大世界的小动物放入尘歌壶。对于收集癖来说是神器。", type: "exclusive"},
            {name: "浪船", color: "B", cost: 500, desc: "一艘可以召唤的小船，配备有重炮和加速功能。出海探险必备。", type: "exclusive"},
            {name: "圣遗物(双暴满分)", color: "SS", cost: 6000, desc: "一套全部分数加在暴击和爆伤上的极品圣遗物。这是阳寿换来的力量。", type: "exclusive"},
            {name: "天理的维系", color: "SSS", cost: 35000, desc: "你获得了空间方块化的能力。可以封印神明，重塑地形。你是规则的制定者。", type: "exclusive"},
            {name: "纠缠之缘", color: "A", cost: 1600, desc: "一种粉红色的石头，据说能召唤异世界的伙伴。但由于概率问题，通常只能召唤出一堆垃圾武器。", type: "exclusive"},
            {name: "地脉之花", color: "B", cost: 400, desc: "击败敌人后，你可以消耗体力具现出地脉之花，从中获取金币或经验书。", type: "exclusive"}
        ]
    },
    {
        name: "427.崩坏3",
        desc: "被崩坏能侵蚀的世界。女武神们驾驶休伯利安号，为了世界上所有的美好而战。这里有律者、机甲和无尽的刀片。",
        boss: "终焉之律者, 凯文·卡斯兰娜, 奥托·阿波卡利斯",
        identities: [
            { name: "圣芙蕾雅学园的学生", items: "校服, 训练用手枪" },
            { name: "天命总部的清洁工", items: "扫帚, 对主教的盲目崇拜" },
            { name: "逆熵的机甲维修师", items: "扳手, 泰坦机甲模型" },
            { name: "长空市的幸存者", items: "防毒面具, 崩坏能检测仪" },
            { name: "世界蛇的底层干部", items: "灰色斗篷, 奇怪的纹身" }
        ],
        talents: [
            {name: "女武神装甲(白练)", color: "C", cost: 500, desc: "基础款装甲，提供基本的防护和身体强化。虽然是B级女武神用的，但也比普通人强。", type: "exclusive"},
            {name: "律者核心(拟)", color: "SS", cost: 9500, desc: "拥有律者的部分权能。无论是空之律者的空间，还是雷之律者的雷电，都足以毁灭城市。", type: "exclusive"},
            {name: "圣痕(全套)", color: "S", cost: 4000, desc: "背部浮现的历史人物灵魂印记。提供巨额的属性加成和特殊技能。虽然有点疼，但很强。", type: "exclusive"},
            {name: "崩坏能抗性(高)", color: "A", cost: 1500, desc: "你能在高浓度崩坏能环境中生存而不死士化。这是成为适格者的基本条件。", type: "exclusive"},
            {name: "时空断裂", color: "S", cost: 3000, desc: "极限闪避时触发。周围的时间流速变慢，只有你能自由行动。反击的最佳时刻。", type: "exclusive"},
            {name: "神之键(天火圣裁)", color: "SS", cost: 8000, desc: "破坏力最强的神之键。第0额定功率能发动“天火出鞘”，威力巨大但会烧死使用者。如果你不是卡斯兰娜，慎用。", type: "exclusive"},
            {name: "泰坦机甲驾驶", color: "B", cost: 800, desc: "逆熵科技震撼人心！你可以召唤并驾驶一台泰坦机甲，用铁拳教做人。", type: "exclusive"},
            {name: "虚数属性", color: "A", cost: 2000, desc: "你的存在形式转变为虚数。对物理攻击有高抗性，且在核心未被击破前是不死的。", type: "exclusive"},
            {name: "量子属性", color: "A", cost: 2000, desc: "你可以进入量子叠加态，穿透物体，进行量子塌缩攻击。", type: "exclusive"},
            {name: "人为崩落", color: "SS", cost: 8500, desc: "融合战士的终极形态。释放体内的崩坏兽基因，化身为怪物，获得超越极限的力量，但可能丧失理智。", type: "exclusive"},
            {name: "犹大的誓约", color: "S", cost: 5000, desc: "女武神犹大，发射光矛禁锢敌人。不管你用什么装甲，背着犹大你就是C位。", type: "exclusive"},
            {name: "休伯利安号舰长", color: "B", cost: 1000, desc: "你拥有这艘空中战舰的指挥权。虽然主要是用来当后勤和运输，但也能呼叫轨道轰炸。", type: "exclusive"},
            {name: "奥托的智谋", color: "S", cost: 3500, desc: "你拥有那个活了500年的男人的智慧。为了目的不择手段，总能制定出最完美的计划。", type: "exclusive"},
            {name: "卡斯兰娜枪斗术", color: "B", cost: 600, desc: "一种把双枪当锤子砸人的奇怪格斗术。虽然看起来不靠谱，但伤害很高。", type: "exclusive"},
            {name: "爱衣·休伯利安(AI)", color: "C", cost: 400, desc: "包菜头AI助手。能帮你黑入系统，管理战舰，或者在抽卡时偷你的水晶。", type: "exclusive"},
            {name: "往世乐土门票", color: "A", cost: 1200, desc: "允许你进入往世乐土，与前文明的十三英桀交谈，获取刻印的力量。", type: "exclusive"},
            {name: "真我之境", color: "SS", cost: 7000, desc: "爱莉希雅的权能。创造一个水晶般的领域，在这里你就是主角，所有攻击都会变得华丽且致命。", type: "exclusive"},
            {name: "识之律者的权能", color: "S", cost: 4500, desc: "修改意识。你可以让人产生幻觉，或者直接用精神攻击把人打成傻子。“我将在你的脑海里炸响！”", type: "exclusive"},
            {name: "崩坏兽基因(帝王级)", color: "A", cost: 2500, desc: "通过手术植入的强力基因。大幅强化身体素质，获得操控冰、火或雷的能力。", type: "exclusive"},
            {name: "吼姆玩偶", color: "D", cost: 50, desc: "一个黄色的奇怪玩偶。除了卖萌和作为投掷物，也许能吸引布洛妮娅的注意。", type: "exclusive"},
            {name: "血骑士·月煌", color: "A", cost: 2200, desc: "德丽莎的弑神装甲。进入狂热状态，攻击速度极快，且造成流血效果。", type: "exclusive"},
            {name: "理之律者摩托", color: "S", cost: 3800, desc: "重装小兔变形！骑上浮空摩托进行漂移射击。是每个男人的浪漫。", type: "exclusive"},
            {name: "终焉之力", color: "SSS", cost: 40000, desc: "跨越时间，重塑世界。这是神的力量，能够终结崩坏的轮回。", type: "exclusive"},
            {name: "黑渊白花", color: "S", cost: 4800, desc: "创生与凋零的神之键。既能瞬间治愈必死的伤势，也能一击分解敌人的身体。", type: "exclusive"},
            {name: "赤鸢仙人(寸劲)", color: "A", cost: 1800, desc: "符华上仙的武学。寸劲开天，每一拳都蕴含着千年的功力，无视防御。", type: "exclusive"},
            {name: "量子之海适应", color: "B", cost: 900, desc: "你可以在量子之海中自由行动，不会迷失方向或被分解。", type: "exclusive"},
            {name: "武装人偶", color: "B", cost: 700, desc: "跟随你战斗的小型人偶。虽然伤害不高，但能提供回血、破盾等辅助效果。", type: "exclusive"},
            {name: "崩坏结晶", color: "C", cost: 300, desc: "升级武器的必备材料。虽然不能吃，但是硬通货。", type: "exclusive"},
            {name: "无限噬界之蛇", color: "SS", cost: 8200, desc: "梅比乌斯的刻印。通过召唤物和无限叠加的BUFF，达成理论上的无限伤害。", type: "exclusive"},
            {name: "空中劈叉", color: "E", cost: 5, desc: "某个休伯利安清洁工的绝技。除了展示柔韧性，毫无用处。", type: "exclusive"}
        ]
    },
    {
        name: "428.崩坏：星穹铁道",
        desc: "银河列车穿梭于星海之间。星神、令使、星核猎手。这是一个关于开拓、毁灭与存护的太空歌剧。",
        boss: "纳努克(毁灭), 幻胧, 星核猎手",
        identities: [
            { name: "空间站的防卫科员", items: "激光枪, 呜呜伯" },
            { name: "贝洛伯格的下层区矿工", items: "机械镐, 地髓取暖器" },
            { name: "仙舟罗浮的云骑军", items: "阵刀, 飞剑" },
            { name: "匹诺康尼的逐梦客", items: "入梦池, 忆质饮料" },
            { name: "星际和平公司的推销员", items: "信用点刷卡机, 永远挂着的假笑" }
        ],
        talents: [
            {name: "星核(体内)", color: "SSS", cost: 35000, desc: "万界之癌。你体内封印着一颗星核，拥有毁灭星球的潜能，也是各个势力争夺的焦点。", type: "exclusive"},
            {name: "命途(开拓)", color: "S", cost: 3000, desc: "踏上开拓命途。你的力量来自于探索未知和连接世界。越是冒险，你越强大。", type: "exclusive"},
            {name: "令使级战力", color: "SS", cost: 15000, desc: "你获得了某位星神的瞥视，借用其部分权能。你是银河中的顶尖战力，一人即是军队。", type: "exclusive"},
            {name: "光锥(五星)", color: "A", cost: 2000, desc: "凝固的记忆片段。装备后大幅提升你的属性，并赋予特殊被动。这是力量的具象化。", type: "exclusive"},
            {name: "弱点击破", color: "B", cost: 800, desc: "你能看穿敌人的属性弱点（物理、火、冰等）。击破弱点会让敌人陷入瘫痪并受到巨额伤害。", type: "exclusive"},
            {name: "终结技(插队)", color: "A", cost: 1500, desc: "无论现在是谁的回合，你都可以强行插入释放大招。这就是回合制的规则破坏者。", type: "exclusive"},
            {name: "存护之盾", color: "A", cost: 1800, desc: "杰帕德或琥珀王的庇护。生成极厚的护盾，嘲讽敌人攻击自己，保护队友。", type: "exclusive"},
            {name: "丰饶之种", color: "SS", cost: 9000, desc: "药师的赐福。你获得了极其恐怖的再生能力，甚至能断肢重生，但也可能堕入魔阴身。", type: "exclusive"},
            {name: "巡猎的极速", color: "S", cost: 3200, desc: "岚的加护。你的速度快到产生残影，在别人行动一次的时间里，你可以行动两三次。", type: "exclusive"},
            {name: "虚无的负面状态", color: "A", cost: 2200, desc: "你擅长给敌人施加持续伤害（DoT）、减防、减速。让敌人在痛苦中慢慢死去。", type: "exclusive"},
            {name: "欢愉的追加攻击", color: "S", cost: 2800, desc: "阿哈真有面子！你的攻击有几率触发额外的连击。运气好的话，你可以一直打下去。", type: "exclusive"},
            {name: "智识的群攻", color: "B", cost: 1200, desc: "博识尊的逻辑。你的攻击能覆盖所有敌人。对付杂兵海效率极高。", type: "exclusive"},
            {name: "同谐的辅助", color: "B", cost: 1000, desc: "希佩的歌声。你可以大幅提升队友的攻击、速度和能量回复。最好的辅助。", type: "exclusive"},
            {name: "帝弓司命的一箭", color: "SS", cost: 12000, desc: "召唤巡猎星神的光矢。对单体目标造成毁灭性的打击，专门用来射杀丰饶孽物。", type: "exclusive"},
            {name: "星穹列车车票", color: "C", cost: 500, desc: "登上列车的凭证。你可以随列车进行星际跃迁，去往任何有轨道的地方。", type: "exclusive"},
            {name: "界域定锚", color: "B", cost: 600, desc: "快速传送装置。只要你激活过，就能随时传送回定锚点。还能顺便回满血。", type: "exclusive"},
            {name: "奇物(银河大乐透)", color: "C", cost: 300, desc: "摧毁可破坏物后有几率获得奇物，但也有极小几率让你全队丝血。赌狗的最爱。", type: "exclusive"},
            {name: "垃圾桶翻找者", color: "D", cost: 50, desc: "你对垃圾桶有着莫名的执念。总能在里面找到奇怪的道具、信用点或者崇高道德的赞许。", type: "exclusive"},
            {name: "自动战斗(AI)", color: "C", cost: 200, desc: "开启后身体自动托管战斗。虽然有时候会乱放技能，但省力气。", type: "exclusive"},
            {name: "秘技点", color: "B", cost: 400, desc: "战斗开始前释放特殊技能。可以先手冻结、隐身或者加BUFF。赢在起跑线上。", type: "exclusive"},
            {name: "黑塔的人偶", color: "A", cost: 1100, desc: "你可以召唤黑塔人偶转圈圈。“转圈圈~”对半血以下的敌人造成追加伤害。", type: "exclusive"},
            {name: "手机(短信)", color: "C", cost: 100, desc: "宇宙通用的通讯器。每天都会收到各种角色的骚扰短信，偶尔能接到任务。", type: "exclusive"},
            {name: "以太战线玩家", color: "B", cost: 550, desc: "你能捕捉并控制以太灵（怪物）进行战斗。宝可梦大师竟是我自己。", type: "exclusive"},
            {name: "钟表把戏", color: "A", cost: 1300, desc: "匹诺康尼的技术。调节NPC的情绪（镇静、欢欣、悲郁、愤懑），以此改变剧情走向或套取情报。", type: "exclusive"},
            {name: "筑城者的意志", color: "B", cost: 900, desc: "在极寒环境中，你的防御力和意志力大幅提升。为了守护贝洛伯格！", type: "exclusive"},
            {name: "持明龙尊之力(残)", color: "S", cost: 4000, desc: "饮月君的力量。驾驭水龙，造成虚数伤害。虽然不完整，但依然霸道。", type: "exclusive"},
            {name: "星际和平公司黑卡", color: "A", cost: 2500, desc: "无限透支额度的信用卡。在这个商业化的宇宙里，钱就是超能力（托帕认证）。", type: "exclusive"},
            {name: "迷因病毒抗性", color: "B", cost: 700, desc: "你对各种通过信息传播的模因病毒有抗性。不容易被洗脑或陷入疯狂。", type: "exclusive"},
            {name: "相位灵火", color: "S", cost: 3500, desc: "一种能够穿越相位的火焰，无视防御直接燃烧敌人的灵魂。", type: "exclusive"},
            {name: "帕姆的列车长帽", color: "D", cost: 80, desc: "虽然很可爱，但戴上它你会忍不住想要打扫卫生，并且对不守规矩的乘客发火。", type: "exclusive"}
        ]
    },
    {
        name: "429.王者荣耀",
        desc: "王者大陆，机关术与魔道并存。英雄们在峡谷中集结，为了各自的信念而战。推塔、打团、五杀。",
        boss: "风暴龙王, 主宰, 帝俊",
        identities: [
            { name: "长安城的治安官", items: "令牌, 机关手铐" },
            { name: "稷下学院的学子", items: "机关翼, 课本" },
            { name: "长城守卫军的小兵", items: "长矛, 粗糙的干粮" },
            { name: "三分之地的水兵", items: "铁链, 艨艟模型" },
            { name: "云中漠地的流浪者", items: "弯刀, 骆驼" }
        ],
        talents: [
            {name: "复活甲(贤者的庇护)", color: "S", cost: 4500, desc: "死亡后2秒原地复活，恢复部分生命值。每局游戏只能生效两次，这是真正的第二条命。", type: "exclusive"},
            {name: "名刀·司命", color: "A", cost: 2000, desc: "受到致命伤害时，进入短暂的无敌状态并增加移速。极限反杀的神器。", type: "exclusive"},
            {name: "辉月(金身)", color: "A", cost: 1800, desc: "主动技能：免疫所有伤害和控制1.5秒，但无法移动。用来躲避致命大招。", type: "exclusive"},
            {name: "破军", color: "S", cost: 3000, desc: "大幅增加攻击力。对生命值低于50%的敌人造成额外伤害。斩杀残血的终极装备。", type: "exclusive"},
            {name: "闪现", color: "B", cost: 800, desc: "向指定方向瞬间位移一段距离。无论是追杀还是逃跑，都是最实用的召唤师技能。", type: "exclusive"},
            {name: "惩击(寒冰)", color: "B", cost: 600, desc: "对野怪造成真实伤害。升级后可对英雄使用，造成减速。打野必备。", type: "exclusive"},
            {name: "净化", color: "B", cost: 700, desc: "解除自身所有负面和控制效果，并免疫控制持续1.5秒。这波不慌，我有净化。", type: "exclusive"},
            {name: "李白的青莲剑歌", color: "S", cost: 3500, desc: "化身为剑气，对范围内敌人飞速穿梭斩击。释放期间不可被选中。十步杀一人，千里不留行。", type: "exclusive"},
            {name: "铠的魔铠", color: "S", cost: 3200, desc: "召唤魔铠附身，全属性大幅提升，格挡伤害。开启大招后，智商降低，战斗力爆表，专治各种花里胡哨。", type: "exclusive"},
            {name: "大乔的电梯(宿命之海)", color: "A", cost: 2500, desc: "召唤法阵，将队友瞬间传送回泉水补满状态。配合大招传送回来，实现永动机战术。", type: "exclusive"},
            {name: "东皇太一的堕神契约", color: "SS", cost: 6000, desc: "压制敌人，双方都无法动弹且共享伤害。专治一切秀儿，你强任你强，东皇加张良。", type: "exclusive"},
            {name: "鲁班七号的扫射", color: "A", cost: 1500, desc: "每次使用技能后，普攻变为强力扫射，造成百分比伤害。只要输出环境好，坦克也得融化。", type: "exclusive"},
            {name: "蔡文姬的思无邪", color: "B", cost: 1200, desc: "弹奏胡笳琴，为周围队友持续恢复生命值。移动泉水，团战毒瘤。", type: "exclusive"},
            {name: "韩信的跳跳", color: "B", cost: 1000, desc: "拥有多段位移技能。偷塔、反野、逃跑，没人能抓得住你。", type: "exclusive"},
            {name: "武则天的生杀予夺", color: "SS", cost: 8500, desc: "在所有敌方英雄脚下召唤法阵，造成伤害和晕眩。全图流大招，人民币玩家的象征。", type: "exclusive"},
            {name: "红蓝BUFF", color: "C", cost: 400, desc: "红BUFF增加普攻减速和真伤，蓝BUFF减少冷却和回蓝。前期节奏的关键。", type: "exclusive"},
            {name: "河道之灵", color: "D", cost: 100, desc: "一只值钱的小怪。虽然没什么战斗力，但为了抢它，往往会引发一级团。", type: "exclusive"},
            {name: "草丛隐身", color: "C", cost: 200, desc: "只要进入草丛，敌人就看不见你。是蹲人阴人的基础战术。", type: "exclusive"},
            {name: "风暴龙王BUFF", color: "SSS", cost: 20000, desc: "获得雷电护盾和真实伤害闪电。这是终结比赛的力量，拿到基本就赢了。", type: "exclusive"},
            {name: "疾跑之靴", color: "C", cost: 300, desc: "脱战后大幅增加移动速度。支援游走必备。", type: "exclusive"},
            {name: "魔女斗篷", color: "B", cost: 900, desc: "获得一个吸收法术伤害的护盾。对抗法师的各种爆发。", type: "exclusive"},
            {name: "不祥征兆", color: "B", cost: 900, desc: "受到攻击时减少攻击者的攻速和移速。物理防御装首选。", type: "exclusive"},
            {name: "泣血之刃(吸血)", color: "A", cost: 1400, desc: "造成物理伤害时回复生命值。只要不被秒，就能一直吸回来。", type: "exclusive"},
            {name: "痛苦面具", color: "A", cost: 1300, desc: "技能命中附带当前生命值百分比伤害。折磨流法师的核心装。", type: "exclusive"},
            {name: "瑶的附身", color: "B", cost: 800, desc: "变成灵体附身在队友身上，提供真实护盾。可以挂机吃零食，也叫“挂件”。", type: "exclusive"},
            {name: "百里守约的狙击", color: "A", cost: 1600, desc: "超远距离狙击，伤害极高。但需要预判，且瞄准时会有红线提示。", type: "exclusive"},
            {name: "防御塔机制", color: "S", cost: 4000, desc: "你可以在身边召唤一座防御塔。攻击力极高，且优先攻击敌方英雄。塔在人在！", type: "exclusive"},
