            {name: "戴森球蓝图", color: "SS", cost: 9000, desc: "你的脑海中拥有一套完整的戴森球建造图纸。只要资源足够，你就能构建出包裹恒星的巨构，获得无限的能量。", type: "exclusive"},
            {name: "伊卡洛斯·轻量级", color: "S", cost: 3500, desc: "你获得了一台轻型工业机甲。虽然没有原版那么强大，但具备飞行、深海作业和基础的激光武器，自带微型核聚变电池。", type: "exclusive"},
            {name: "行星物流系统", color: "S", cost: 2800, desc: "你可以召唤一座行星物流塔。它能够跨越地域瞬间传输你背包里的物品，只要你在世界各地建立了接收端。空间背包的终极形态。", type: "exclusive"},
            {name: "黑雾科技解析", color: "A", cost: 1500, desc: "你掌握了敌对势力“黑雾”的技术。你可以制造并操控黑雾的战斗单位，甚至将黑雾巢穴转化为你的能量来源。", type: "exclusive"},
            {name: "量化强迫症", color: "C", cost: 100, desc: "你对数字极其敏感。在进行生产或修炼时，你能精确计算出效率最高的配比，绝不浪费哪怕1秒的时间或1点法力。", type: "exclusive"},
            {name: "翘曲航行引擎", color: "SS", cost: 6000, desc: "赋予你肉身或载具进行光速航行的能力。你可以折叠空间，在几秒钟内跨越数光年的距离。星辰大海，近在咫尺。", type: "exclusive"},
            {name: "无限矿脉探测", color: "B", cost: 500, desc: "你的双眼能看穿地层，直接看到地下蕴藏的所有资源及其储量。对于寻找稀有矿物（如单极磁石）有奇效。", type: "exclusive"},
            {name: "太阳帆弹射技术", color: "A", cost: 1200, desc: "你可以制造并从手掌中发射微型太阳帆。成千上万的太阳帆在空中组成阵列，既能作为护盾反射激光，也能收集太阳能。", type: "exclusive"},
            {name: "引力透镜", color: "B", cost: 600, desc: "利用引力聚焦光线。在战斗中，你可以通过聚焦环境光线产生高温激光束；在修炼时，可以聚集星光加速能量吸收。", type: "exclusive"},
            {name: "卡西米尔晶体体质", color: "A", cost: 1000, desc: "你的身体结构发生了变异，如同卡西米尔晶体一般稳定且高效。对空间撕裂类攻击有极高的抗性，且能利用量子涨落恢复能量。", type: "exclusive"},
            {name: "光子组合器", color: "C", cost: 200, desc: "你能将光子进行简单的物理组合。这让你能制造出硬光全息投影，用来迷惑敌人或作为临时的踏脚石。", type: "exclusive"},
            {name: "氢气分馏专精", color: "C", cost: 150, desc: "你擅长处理流体。在处理任何液体或气体能量时，你的损耗率极低，并且能从中提炼出更纯净的重氢同位素。", type: "exclusive"},
            {name: "电磁涡轮心脏", color: "B", cost: 450, desc: "你的心脏被替换为了生物电磁涡轮。不仅供血能力极强，还能在剧烈运动时产生电流，麻痹接触你的敌人。", type: "exclusive"},
            {name: "垃圾佬的直觉", color: "D", cost: 50, desc: "在任何废墟中，你总能一眼看到最有价值的垃圾。虽然听起来不体面，但这确实是初期致富的法宝。", type: "exclusive"}
        ]
    },
    {
        name: "443.太吾绘卷",
        desc: "相枢乱世，神州陆沉。你作为太吾传人，手持伏虞剑柄，在随机生成的江湖中习武、联姻、斗蛐蛐。面对入魔的众生，是拯救还是毁灭？",
        boss: "相枢, 染魔的剑冢BOSS(如大玄凝、衣以侯), 唯我性格的掌门",
        identities: [
            { name: "太吾村的傻子", items: "一根不知名的木棍, 满身泥巴" },
            { name: "刚出谷的太吾传人", items: "伏虞剑柄(破损), 太吾村建设图纸" },
            { name: "少林寺的烧火僧", items: "一根烧火棍, 一本被虫蛀的长拳秘籍" },
            { name: "璇女派的杂役男弟子", items: "一把扫帚, 即使在门派内也被视作空气" },
            { name: "五仙教的试毒童子", items: "满身毒疮, 一罐未知的毒虫" }
        ],
        talents: [
            {name: "太吾传承(真)", color: "SSS", cost: 35000, desc: "你拥有完整的太吾传承。你可以学习天下所有门派的武功而无视门派限制，并且死后可以将修为和资质传给下一代（夺舍）。", type: "exclusive"},
            {name: "伏虞剑柄(解封)", color: "SS", cost: 8000, desc: "神剑伏虞的剑柄。对所有入魔者有绝对的压制力。你可以用它净化入魔的NPC，将其收入麾下，或者直接敲碎他们的天灵盖。", type: "exclusive"},
            {name: "天人造化(资质)", color: "S", cost: 2800, desc: "你的六维属性（膂力、灵敏等）和技艺资质全部为神级。学什么都是一遍过，看一眼就能举一反三，真正的武学奇才。", type: "exclusive"},
            {name: "促织王(三王)", color: "A", cost: 1500, desc: "你开局自带一只“促织王”（如八败、真三色）。在这个斗蛐蛐比人命重要的世界里，这只虫子能让你赢得万贯家财和掌门的青睐。", type: "exclusive"},
            {name: "男生女相/女生男相", color: "B", cost: 500, desc: "你的样貌绝美且雌雄莫辨。这让你能混入只收特定性别的门派（如璇女派或少林寺），学习那些禁忌的绝学。", type: "exclusive"},
            {name: "无根之人", color: "C", cost: 200, desc: "你...缺少了一些部件。但正因如此，你修炼纯阳或极阴类功法时速度极快，且心无杂念，不会走火入魔。", type: "exclusive"},
            {name: "沛然决", color: "B", cost: 400, desc: "太吾村的基础内功，虽然基础，但中正平和，内力深厚。它能为你提供大量的内力上限，是前期最好的打底功法。", type: "exclusive"},
            {name: "相枢入邪", color: "A", cost: 1000, desc: "你主动接纳了一部分相枢的邪气。你的攻击变得疯狂且致命，所有属性大幅提升，但每个月心性都会向“唯我”偏移，容易众叛亲离。", type: "exclusive"},
            {name: "神一品菜谱", color: "S", cost: 2200, desc: "你掌握了传说中的厨艺。你做出的菜肴不仅美味，还能改变NPC的立场，甚至让生死仇敌在饭桌上跟你结拜兄弟。", type: "exclusive"},
            {name: "血犼教义", color: "C", cost: 300, desc: "你精通血犼教的邪法。可以通过杀人来提升功法威力，或者通过折磨他人来获得快感和心情恢复。极度邪恶。", type: "exclusive"},
            {name: "界青门暗杀术", color: "A", cost: 900, desc: "你是指哪打哪的杀手。你可以接受委托暗杀特定的NPC，并且拥有极高的隐匿能力，杀人于无形，事了拂衣去。", type: "exclusive"},
            {name: "铸剑山庄恩义", color: "B", cost: 600, desc: "你与铸剑山庄关系极好。你可以随意使用他们的神兵利器，并且能让他们为你打造一把专属的、带有特殊词条的武器。", type: "exclusive"},
            {name: "杂学宗师", color: "B", cost: 500, desc: "你不仅懂武功，还精通琴棋书画、医卜星象。这让你在江湖行走时能触发无数奇遇，甚至通过辩论让敌人羞愧而死。", type: "exclusive"},
            {name: "轮回台", color: "SS", cost: 7500, desc: "你掌握了修建轮回台的秘法。可以将前世的属性叠加到今生。只要你死得够多，理论上你可以造出一个全属性999的怪物。", type: "exclusive"},
            {name: "一月一更", color: "D", cost: 10, desc: "你的时间流逝速度极慢，每个月都要经历漫长的等待。这是一种折磨，但也给了你更多的思考时间。", type: "exclusive"}
        ]
    },
    {
        name: "444.鬼谷八荒",
        desc: "山海经背景的开放世界修仙。凡人逆天改命，从炼气筑基到羽化登仙。宗门林立，妖兽横行，双修、仇杀、拍卖会，演绎真实的修仙界。",
        boss: "刑天, 冥妖, 登仙境大能, 极难度的开局野猪",
        identities: [
            { name: "被退婚的废材少年", items: "一封休书, 一枚古朴的戒指(里面好像有动静)" },
            { name: "刚入门的外门弟子", items: "宗门制式长剑, 十块下品灵石" },
            { name: "散修尸体旁的拾荒者", items: "一本残缺的火球术, 几颗回血丹" },
            { name: "合欢宗的炉鼎", items: "艳丽的服饰, 身体亏空的debuff" },
            { name: "山贼寨里的肉票", items: "绳索, 恐惧的心理阴影" }
        ],
        talents: [
            {name: "三红开局", color: "SSS", cost: 38000, desc: "天选之子！你同时拥有三个神级先天气运（如武圣转世+鬼谷外门+人族圣体）。出生即巅峰，攻击力、悟性、幸运值全部拉满。", type: "exclusive"},
            {name: "双修大法", color: "A", cost: 1200, desc: "你精通阴阳调和之道。通过与异性（或同性）修士双修，你可以快速获得修为和道点。你的魅力值极高，没人能拒绝你的请求。", type: "exclusive"},
            {name: "剑痴", color: "S", cost: 2500, desc: "你为剑而生。剑法资质+50，剑法熟练度获取速度+100%。所有剑法神通的冷却时间减少20%。万剑归宗不是梦。", type: "exclusive"},
            {name: "老而弥坚", color: "A", cost: 800, desc: "你的年龄越大，防御力越高。在这个动辄闭关几十年的修仙界，只要你苟得住，熬成老头子后你就是最硬的龟壳。", type: "exclusive"},
            {name: "天妒英才", color: "D", cost: -500, desc: "你的悟性极高，但寿命极短，且运气极差。出门容易踩狗屎，渡劫成功率减半。这是对天才的诅咒。", type: "exclusive"},
            {name: "穿越者", color: "B", cost: 600, desc: "你拥有现代人的思维。悟性+20，对于人际关系的把握（送礼、拍马屁）更加精准，能快速在宗门内混得风生水起。", type: "exclusive"},
            {name: "媚骨", color: "S", cost: 2000, desc: "魅力值锁定为900（仙姿）。无论走到哪里，都会有NPC主动送药、送书、甚至送身。但也容易招惹嫉妒和变态的追求者。", type: "exclusive"},
            {name: "大能转世", color: "SS", cost: 9000, desc: "你保留了前世登仙境的一丝神识。在突破大境界时，成功率100%，并且必定刷出红色的逆天改命词条。", type: "exclusive"},
            {name: "炼丹宗师", color: "B", cost: 500, desc: "你擅长炼丹，炸炉概率极低。在这个嗑药升级的世界，掌握了丹药就掌握了经济命脉，你可以靠卖药成为首富。", type: "exclusive"},
            {name: "风灵月影护体", color: "SSS", cost: 50000, desc: "来自神秘宗门“风灵月影”的加护。你可以修改现实规则（开启修改器），实现锁血、秒杀、物品不减。但这会严重破坏世界的因果，可能引来系统抹杀。", type: "exclusive"},
            {name: "脚底抹油", color: "C", cost: 150, desc: "逃跑成功率100%。在修仙界，活着才是硬道理。打不过就跑，不丢人，留得青山在不怕没柴烧。", type: "exclusive"},
            {name: "咸猪手", color: "C", cost: 200, desc: "你可以偷窃NPC的物品。虽然会降低好感度，但如果你手速够快，甚至能偷走大能的本命法宝。风险与收益并存。", type: "exclusive"},
            {name: "一诺千金", color: "S", cost: 1800, desc: "开局自带一个对你忠贞不渝的道侣。这个道侣资质极高，会陪你成长，是你最坚实的后盾（软饭硬吃）。", type: "exclusive"},
            {name: "水力四射", color: "A", cost: 1100, desc: "逆天改命词条。你的攻击有概率触发水柱滋射，自动追踪敌人。清图神技，让你在副本里像个洒水车一样横冲直撞。", type: "exclusive"},
            {name: "兵刃专精", color: "B", cost: 700, desc: "使用刀/剑/枪神通时，无需达成前置条件（如不需要积攒剑意）。这让你的大招可以起手就放，爆发力极强。", type: "exclusive"}
        ]
    },
    {
        name: "445.了不起的修仙模拟器",
        desc: "硬核修仙。建立门派，规划风水，炼丹炼器。从凡人到真仙，需要度过无数天劫。这里讲究五行生克，稍有不慎便是走火入魔，满门灭绝。",
        boss: "天劫, 烛龙, 凶凤, 蛟龙, 攻山的魔教长老",
        identities: [
            { name: "太一门灭门幸存者", items: "掌门遗物, 一颗筑基丹" },
            { name: "山下的樵夫", items: "斧头, 几块灵木" },
            { name: "流浪的孤儿", items: "单薄的衣物, 极高的机缘(以此补偿悲惨身世)" },
            { name: "被妖兽追杀的富家子", items: "大量金银(修仙界无用), 一块玉佩" },
            { name: "轮回逆转者", items: "前世的记忆碎片, 极其虚弱的身体" }
        ],
        talents: [
            {name: "一品金丹", color: "SS", cost: 12000, desc: "你的结丹品质必定为一品。金丹品质决定了修仙的上限，一品金丹意味着你拥有成仙的入场券，灵气容量是凡人的百倍。", type: "exclusive"},
            {name: "风水大师", color: "A", cost: 1500, desc: "你一眼就能看穿环境的五行风水。你能摆出“大吉”的房间，利用环境生克来加速修炼，甚至利用风水阵法杀敌。", type: "exclusive"},
            {name: "天眷之体", color: "S", cost: 3000, desc: "天道宠儿。你的机缘值极高，出门就能捡到天材地宝，渡劫时天劫威力降低30%，且更容易触发顿悟。", type: "exclusive"},
            {name: "龙血者", color: "A", cost: 2000, desc: "你食用了龙肉或拥有龙族血统。身体强韧度极高，耐热耐寒，寿命悠长。但情绪容易失控，需要心境修炼来压制。", type: "exclusive"},
            {name: "长生经", color: "B", cost: 800, desc: "一本注重养生和寿命的功法。虽然战斗力不强，但能让你活得更久。只要活得久，就能熬死敌人，或者等到机缘。", type: "exclusive"},
            {name: "器灵共鸣", color: "S", cost: 2500, desc: "你能听到法宝中器灵的声音。炼器成功率大幅提升，且能发挥出法宝200%的威力，甚至能唤醒沉睡的上古神器。", type: "exclusive"},
            {name: "九转金丹直指", color: "SS", cost: 9500, desc: "你脑海中有一条通往九转金丹的完美修炼路径。你知道在什么天气、什么地点、吃什么药、用什么功法能达成完美结丹。", type: "exclusive"},
            {name: "偷天诀", color: "SSS", cost: 30000, desc: "逆天而行的功法。通过献祭寿命或其他代价，强行夺取天地的造化。可以瞬间提升修为，但因果极重，容易招致天谴。", type: "exclusive"},
            {name: "种田能手", color: "C", cost: 200, desc: "你种植灵药的速度和产量加倍。在修仙界，财侣法地，财排第一。你会种药，就是最大的财主。", type: "exclusive"},
            {name: "极寒/极热体质", color: "B", cost: 400, desc: "你天生适应极端的温度。这让你可以在极寒的冰原或极热的火山修炼特殊的功法，而不必担心被冻死或热死。", type: "exclusive"},
            {name: "神识寄托", color: "S", cost: 2800, desc: "你可以将神识寄托在物品上。即使肉身被毁，只要物品不灭，你就能夺舍重生。真正的保命神技。", type: "exclusive"},
            {name: "符箓通灵", color: "B", cost: 600, desc: "你画的符箓效果提升50%。无论是神行符、避寒符还是天师降魔符，在你手中都能发挥出越级的效果。", type: "exclusive"},
            {name: "心境圆满", color: "A", cost: 1000, desc: "你的心境坚如磐石，永远维持在满值。修炼速度不受心境阻碍，且永远不会走火入魔或产生执念。", type: "exclusive"},
            {name: "外门领袖", color: "C", cost: 300, desc: "你擅长管理凡人弟子。能让外门弟子工作效率提升，不知疲倦地为你砍树、挖矿、盖房子。", type: "exclusive"},
            {name: "吃货", color: "D", cost: 50, desc: "你吃得很多，容易饿。但在修仙界，这意味着你能吃下更多的灵食，通过吃来增加属性，只要你吃得起。", type: "exclusive"}
        ]
    },
    {
        name: "446.摩尔庄园",
        desc: "红鼻子小摩尔的快乐家园。看似低幼，实则包含了骑士团、黑森林、魔法与科技。在这里，种田、养拉姆、装修房子是主流，但也要小心RK的恶作剧和黑魔法。",
        boss: "RK(亦正亦邪), 黑暗魔法师, 捷克王子(黑化版)",
        identities: [
            { name: "刚搬进庄园的新居民", items: "新手装扮, 几颗摩尔豆, 一只普通拉姆" },
            { name: "么么公主的皇家侍卫", items: "骑士长枪, 皇家骑士铠甲" },
            { name: "淘淘乐街的打工仔", items: "宠物店传单, 打工赚来的零钱" },
            { name: "黑森林探险队遗孤", items: "破损的探险帽, 一张藏宝图碎片" },
            { name: "拉姆学院的吊车尾", items: "考鸭蛋的试卷, 一只不听话的拉姆" }
        ],
        talents: [
            {name: "超级拉姆(年费)", color: "SS", cost: 5000, desc: "尊贵的象征！你的拉姆进化为超级拉姆，拥有飞行能力，能进入所有隐藏地图，购买专属道具，并且在任何任务中都有特权。", type: "exclusive"},
            {name: "摩尔豆大亨", color: "A", cost: 1200, desc: "你拥有极高的商业头脑。在庄园里做任何生意（卖鱼、卖农作物）都能获得双倍摩尔豆。有钱就是任性，买光服装店！", type: "exclusive"},
            {name: "皇家骑士团长", color: "S", cost: 2500, desc: "你拥有骑士团的最高指挥权。战斗力极强，精通剑术和盾牌防御。在对抗黑森林怪物时，攻击力翻倍。", type: "exclusive"},
            {name: "RK的怪盗技艺", color: "S", cost: 2200, desc: "你习得了怪盗RK的潜行和捣蛋技巧。可以神不知鬼不觉地拿走别人的宝物，或者在别人的庄园里留下恶作剧涂鸦。", type: "exclusive"},
            {name: "拉姆语十级", color: "B", cost: 500, desc: "你能听懂拉姆的所有语言。这让你能发现拉姆们藏起来的秘密宝藏，或者指挥野生拉姆为你战斗。", type: "exclusive"},
            {name: "魔法师传承", color: "A", cost: 1500, desc: "你继承了魔法马车的力量。可以使用变身魔法、传送魔法，甚至召唤元素精灵。在摩尔庄园，魔法是解决难题的万能钥匙。", type: "exclusive"},
            {name: "顶级农场主", color: "C", cost: 300, desc: "你的农场作物生长速度加快50%，且永远不会枯萎或被虫蛀。你是庄园里的粮食大亨，大家都来偷你的菜。", type: "exclusive"},
            {name: "SMC全职业满级", color: "SS", cost: 6000, desc: "向导、警官、记者、消防员...你拥有所有SMC职业的满级执照。这意味着你拥有全套的职业技能和工资收入。", type: "exclusive"},
            {name: "黑森林通行证", color: "B", cost: 600, desc: "你对黑森林的路径了如指掌，不会迷路，也不会被荆棘伤害。你是探索危险区域的最佳向导。", type: "exclusive"},
            {name: "么么公主的密友", color: "A", cost: 1000, desc: "你和么么公主关系极好。可以随意进出城堡，甚至调动皇家资源。但要小心被其他摩尔嫉妒。", type: "exclusive"},
            {name: "瑞琪的剑术指导", color: "B", cost: 800, desc: "你曾接受过团长瑞琪的指导。剑术扎实，正义感爆棚，对邪恶生物有天然的压制力。", type: "exclusive"},
            {name: "时光机", color: "SSS", cost: 20000, desc: "来自未来的科技。你可以穿越回摩尔庄园的过去（08/09版本），体验那些绝版的剧情和任务，找回失落的记忆。", type: "exclusive"},
            {name: "装修大师", color: "C", cost: 200, desc: "你擅长布置小屋。你的小屋魅力值极高，每天都能吸引大量摩尔来参观，为你提供源源不断的人气值。", type: "exclusive"},
            {name: "滑雪冠军", color: "D", cost: 100, desc: "你在摩尔拉雅雪山的滑雪比赛中未尝一败。虽然对战斗没用，但很帅，能赢得小摩尔们的崇拜。", type: "exclusive"},
            {name: "绝版家具收藏家", color: "S", cost: 1800, desc: "你拥有无数绝版家具（如龙蛋、捷克王子的床）。这些东西价值连城，有些甚至带有特殊的魔法效果。", type: "exclusive"}
        ]
    },
    {
        name: "447.赛尔号",
        desc: "无尽能源枯竭，赛尔机器人踏上宇宙探险。精灵对战是核心。谱尼、雷伊、索伦森...这里有数千种精灵。属性克制、PP值、个体值、性格，构成了复杂的对战系统。",
        boss: "谱尼(完全体), 索伦森, 宇宙海盗首领, 咤克斯",
        identities: [
            { name: "刚出厂的NoNo机器人", items: "初级胶囊, 初始精灵三选一(水火草)" },
            { name: "海盗杂兵", items: "黑暗胶囊, 一只被改造的暗影系精灵" },
            { name: "赫尔卡星的遗迹守护者", items: "雷电残能, 古代机械零件" },
            { name: "流浪的精灵训练师", items: "一背包的伤药, 几只满级但低天赋的精灵" },
            { name: "赛尔号飞船维修工", items: "扳手, 备用燃料电池" }
        ],
        talents: [
            {name: "圣灵谱尼之光", color: "SSS", cost: 45000, desc: "你获得了精灵王谱尼的加护。全属性免疫异常状态，拥有多条命，并且可以使用圣灵系技能净化一切黑暗。种族值突破天际。", type: "exclusive"},
            {name: "雷伊的雷神天明闪", color: "SS", cost: 8500, desc: "你习得了雷神的终极绝招。攻击威力极大，且有极高概率造成4倍伤害。配合雷伊的瞬雷天闪，你是速度与爆发的代名词。", type: "exclusive"},
            {name: "欧皇(瞬杀特性)", color: "S", cost: 3000, desc: "你的所有攻击都有3%-5%的概率直接秒杀对方，无视血量和防御。在BOSS战中，这就是创造奇迹的神技。", type: "exclusive"},
            {name: "超No特权", color: "A", cost: 1200, desc: "你拥有超能NoNo的权限。可以随时随地恢复精灵体力，飞行，加速孵化精元，领取每周礼包。", type: "exclusive"},
            {name: "属性克制大师", color: "B", cost: 600, desc: "你对属性克制表倒背如流。在战斗中，你造成的克制伤害提升50%，受到的微弱伤害减少50%。", type: "exclusive"},
            {name: "精灵胶囊必中", color: "S", cost: 2500, desc: "你扔出的精灵胶囊捕捉率提升至100%（仅限可捕捉精灵）。再也不用担心把稀有精灵打死或者让它跑了。", type: "exclusive"},
            {name: "个体值31", color: "A", cost: 1500, desc: "你培育的所有精灵，其个体值必定为满值（31）。无需繁琐的基因重组，你的精灵天生就是最强的。", type: "exclusive"},
            {name: "索伦森的暗影之力", color: "SS", cost: 8000, desc: "你掌握了魔君索伦森的力量。可以使用混沌/暗影系技能，复活死去的精灵，甚至制造精灵的复制体（逆势麒麟等）。", type: "exclusive"},
            {name: "先制+3", color: "S", cost: 2200, desc: "你的所有技能优先度+3。在回合制游戏中，先手意味着控制和压制。天下武功，唯快不破。", type: "exclusive"},
            {name: "战神联盟羁绊", color: "A", cost: 1800, desc: "你能随时召唤战神联盟（雷伊、盖亚、卡修斯、布莱克、缪斯）助战。虽然有冷却时间，但这五位是宇宙正义的象征。", type: "exclusive"},
            {name: "火焰辅助", color: "B", cost: 400, desc: "你可以根据需要切换火焰buff：绿火（强化攻击）、蓝火（回血）、紫火（高伤）。打BOSS必备。", type: "exclusive"},
            {name: "皮皮的同情", color: "C", cost: 100, desc: "使用技能“手下留情”时，必定保留对方1点血。这是捕捉精灵的基础，也是最实用的技能之一。", type: "exclusive"},
            {name: "米咔光线", color: "B", cost: 500, desc: "你的随身精灵是米咔。它平时很萌，但在关键时刻能进化为光之惩戒·米瑞斯，爆发出惊人的战斗力。", type: "exclusive"},
            {name: "年费精灵契约", color: "SS", cost: 7000, desc: "你拥有一只当年的年费精灵（如圣光灵神、启灵元神）。这些精灵通常拥有打破规则的机制，是PVP和PVE的王者。", type: "exclusive"},
            {name: "刻印激活", color: "B", cost: 800, desc: "你可以为精灵装备全属性+50的超级刻印。这让你的精灵面板属性远超同级野生精灵。", type: "exclusive"}
        ]
    },
    {
        name: "448.洛克王国",
        desc: "魔法与宠物的世界。小洛克们在魔法学院学习，捕捉宠物，挑战八大徽章。虽然画风可爱，但深层剧情涉及恩佐的复活禁术和噩梦力量。",
        boss: "恩佐, 噩梦, 库拉, 黑暗圣母",
        identities: [
            { name: "魔法学院新生", items: "魔法杖, 咕噜球, 迪莫" },
            { name: "威廉古堡的幽灵", items: "破旧的披风, 吓人的面具" },
            { name: "人鱼湾的守护者", items: "避水珠, 水系宠物蛋" },
            { name: "暗黑基地的潜伏者", items: "黑魔法书残页, 恶魔叮" },
            { name: "弃之宝岛的拾荒者", items: "垃圾分类手册, 变异的宠物" }
        ],
        talents: [
            {name: "圣龙骑士", color: "SSS", cost: 36000, desc: "你是传说中的圣龙骑士。拥有驾驭神宠“阿布”的力量，能够使用光系最强魔法，净化一切黑暗。你是王国的救世主。", type: "exclusive"},
            {name: "恩佐的黑魔法", color: "SS", cost: 8500, desc: "你偷学了恩佐的禁忌魔法。可以复活死去的宠物（变成僵尸宠），或者强行控制他人的宠物。力量强大，但会被正道追杀。", type: "exclusive"},
            {name: "瓦斯叮当(催眠)", color: "S", cost: 2000, desc: "你拥有神宠瓦斯叮当，且必定先手催眠。在回合制里，让对手睡到死是最脏的套路。配合“生命火焰”，控场无敌。", type: "exclusive"},
            {name: "上古龙王血脉", color: "SS", cost: 9000, desc: "你拥有上古龙王的血统。龙系技能威力+50%，且能听懂龙语，号令天下龙族。你可以骑乘夏奈等龙族飞行。", type: "exclusive"},
            {name: "VIP5特权", color: "A", cost: 1200, desc: "你是尊贵的LULU VIP。拥有专属的飞行器、每周礼包、随身仓库和回血功能。去哪里都能享受打折。", type: "exclusive"},
            {name: "迪莫的光辉", color: "S", cost: 2500, desc: "你的初始伙伴是迪莫。它拥有无限的进化可能（圣光迪莫、皇家圣光...）。每次你遇到绝境，它都会进化救主。", type: "exclusive"},
            {name: "呱呱十八般武艺", color: "A", cost: 1500, desc: "你精通呱呱的所有修行。逍遥呱呱、少林呱呱、富贵呱呱...这只兔子能打能抗能控，是全能型的战士。", type: "exclusive"},
            {name: "冰龙王的极寒", color: "S", cost: 2800, desc: "你得到了冰龙王的传承。可以使用绝对零度冻结敌人，或者制造冰墙防御。在冰系地图战斗力翻倍。", type: "exclusive"},
            {name: "炼金术士", color: "B", cost: 600, desc: "你擅长炼金。可以将普通的材料合成珍贵的药剂或进化道具。甚至能炼制出改变宠物性格的性格果。", type: "exclusive"},
            {name: "音速犬代练", color: "C", cost: 200, desc: "你拥有一只满级音速犬，配招回光返照。这是带小号升级的神器，一招秒怪，刷级效率极高。", type: "exclusive"},
            {name: "避水咒/飞行咒", color: "C", cost: 150, desc: "你精通基础魔法。可以自由在水下呼吸，或骑着扫帚飞行。探索地图的必备技能。", type: "exclusive"},
            {name: "草系催眠粉", color: "B", cost: 400, desc: "你擅长使用草系宠物的异常状态粉末。催眠、寄生、中毒，素质三连，慢慢磨死强大的BOSS。", type: "exclusive"},
            {name: "萌系加成", color: "D", cost: 50, desc: "你长得很可爱。NPC对你的初始好感度较高，容易接到隐藏任务，或者被反派轻视从而反杀。", type: "exclusive"},
            {name: "通天塔征服者", color: "A", cost: 1000, desc: "你曾通关通天塔。拥有极强的PVE策略头脑，知道如何针对各种机制怪。获得大量经验果实和装备。", type: "exclusive"},
            {name: "神草系打击", color: "S", cost: 2200, desc: "你拥有蹦神等神草系宠物。高爆发、高回复，是打BOSS的利器，尤其是针对那些血厚防高的敌人。", type: "exclusive"}
        ]
    },
    {
        name: "449.暖暖系列",
        desc: "奇迹大陆，一个换装即是战斗的世界。搭配之力决定一切。无论是国家战争还是街头斗殴，都通过比拼穿搭来解决。小心那些为了设计图不择手段的人。",
        boss: "尼德霍格(黑夜秩序), 铁蔷薇搭配师团, 欲望之神",
        identities: [
            { name: "苹果联邦的服装设计系学生", items: "素描本, 几块便宜的布料" },
            { name: "信鸽王国的落魄贵族", items: "旧式繁复礼服, 家族徽章" },
            { name: "云端帝国的织女", items: "刺绣针线, 汉服图纸" },
            { name: "废墟孤岛的程序员", items: "电子护目镜, 荧光材质布料" },
            { name: "荒原共和国的流浪者", items: "图腾饰品, 粗布披风" }
        ],
        talents: [
            {name: "绝世搭配师", color: "SSS", cost: 30000, desc: "你拥有看透“美”的本质的能力。无论题目多么刁钻，你都能瞬间搭配出S级高分评价。你的搭配能引发天地异象，甚至物理击退敌人。", type: "exclusive"},
            {name: "有生之年(套装)", color: "SS", cost: 9000, desc: "你开局自带一套“有生之年”系列（如冰风战歌、星之海）。这套衣服自带极高的属性加成和华丽度，光是穿上它就能震慑全场。", type: "exclusive"},
            {name: "大喵的吐槽", color: "B", cost: 500, desc: "你身边跟着一只会说话的猫。虽然它嘴很欠，总爱吃五花肉，但它能精准提示关卡的属性要求（简约/清纯等），是通关作弊器。", type: "exclusive"},
            {name: "设计师之影(李尔里德)", color: "SS", cost: 8500, desc: "你拥有最强设计师李尔里德的卡牌。在战斗中召唤他的力量，可以瞬间提升全属性搭配力，并获得“甜美”属性的极致加成。", type: "exclusive"},
            {name: "暖暖的衣柜", color: "S", cost: 4000, desc: "你拥有一个四次元衣柜，里面塞满了数万件衣服。无论什么风格（洛丽塔、军装、古风、比基尼），你都能随手掏出来。", type: "exclusive"},
            {name: "荧光之灵", color: "A", cost: 1200, desc: "你装备了强大的荧光之灵（如海樱的回忆）。它能为你提供额外的分数加成，并在关键时刻释放特殊技能，如除去对手的干扰。", type: "exclusive"},
            {name: "技能：挑剔的目光", color: "B", cost: 600, desc: "你擅长攻击对手的穿搭缺陷。使用该技能可以大幅降低对手的分数，让对方心态崩坏。PVP神技。", type: "exclusive"},
            {name: "技能：免疫挑剔", color: "B", cost: 600, desc: "你拥有强大的心理素质。可以完全免疫一次对手的“挑剔的目光”攻击，保护自己的分数不被扣除。", type: "exclusive"},
            {name: "废墟科技眼", color: "A", cost: 1000, desc: "来自废墟孤岛的植入体。能数字化显示每一件衣服的属性数值（华丽S、活泼A等），让你能进行最科学的搭配。", type: "exclusive"},
            {name: "信鸽女王的气场", color: "S", cost: 2200, desc: "你拥有女王般的气场。在“华丽”和“优雅”属性的对决中，你的基础分提升50%，且容易让对手感到自卑。", type: "exclusive"},
            {name: "云端古韵", color: "A", cost: 1500, desc: "你精通云端风格。在“古风”、“清纯”类题目中无敌。且你能自己设计制作精美的汉服，受到NPC追捧。", type: "exclusive"},
            {name: "莉莉斯童话", color: "A", cost: 1500, desc: "你拥有童话般的可爱气质。在“可爱”、“甜美”类题目中无敌。小动物和小孩会天然亲近你。", type: "exclusive"},
            {name: "北地战意", color: "B", cost: 800, desc: "你的风格硬朗帅气。在“保暖”、“中性风”或战争主题的搭配中表现出色。你的衣服甚至真的具有防弹功能。", type: "exclusive"},
            {name: "幻之阁欧皇", color: "S", cost: 2500, desc: "你的运气极好。每次在幻之阁抽奖，必定出限定闪耀部件。你是所有非酋玩家的公敌。", type: "exclusive"},
            {name: "服装进化手艺", color: "C", cost: 300, desc: "你能将普通的衣服改造成更高级的形态（珍稀/华丽）。变废为宝，是平民玩家逆袭的关键。", type: "exclusive"}
        ]
    },
    {
        name: "450.绝区零",
        desc: "新艾利都，也是最后的大都市。空洞灾害吞噬了世界，以骸横行。你是绳匠，引导代理人在空洞中探索，寻找旧世界的遗产，对抗以太腐蚀。",
        boss: "尼尼微, 杜拉罕, 强袭型以骸, 零号空洞核心",
        identities: [
            { name: "六分街的录像店店员", items: "邦布插头, 一盘旧时代录像带" },
            { name: "白祇重工的临时工", items: "建筑安全帽, 冲击钻" },
            { name: "维多利亚家政的见习生", items: "除尘掸, 优雅的制服" },
            { name: "狡兔屋的欠债人", items: "一大叠账单, 逃跑用的运动鞋" },
            { name: "空洞调查协会的新人", items: "萝卜(空洞地图), 以太适性测试表" }
        ],
        talents: [
            {name: "法厄同(传奇绳匠)", color: "SSS", cost: 32000, desc: "你是传说中的绳匠“法厄同”。你拥有特殊的“同步”能力，能通过邦布完美指挥代理人战斗，且在空洞中永远不会迷路，能看到所有隐藏路径。", type: "exclusive"},
            {name: "以太适性99%", color: "SS", cost: 8800, desc: "你的身体对以太能量有极高的适应性。在空洞中不会累积侵蚀值（压力值），甚至能吸收以太能量强化自身。你是天生的空洞行者。", type: "exclusive"},
            {name: "S级邦布", color: "S", cost: 3500, desc: "你拥有一只定制的S级邦布（如巴特勒或鲨牙布）。它不仅能卖萌，还能在战斗中提供强大的火力支援或治疗，甚至释放连携技。", type: "exclusive"},
            {name: "冰属性异常专精", color: "A", cost: 1800, desc: "你擅长使用冰属性攻击。能快速打出“冻结”和“霜寒”效果，控制敌人并增加其受到的暴击伤害。艾伦乔的好搭档。", type: "exclusive"},
            {name: "失衡大师", color: "S", cost: 2500, desc: "你的攻击极其沉重，削韧能力极强。能迅速将敌人打入“失衡”状态，触发连携攻击。在你的攻势下，BOSS动都动不了。", type: "exclusive"},
            {name: "维多利亚家政服务", color: "A", cost: 1500, desc: "你加入了维多利亚家政。虽然工作危险，但你学会了优雅地杀戮。物理/电属性伤害提升，且拥有极高的闪避反击技巧。", type: "exclusive"},
            {name: "白祇重工机械臂", color: "A", cost: 1500, desc: "你装备了重型机械臂。火属性伤害提升，拥有护盾技能。虽然攻速慢，但每一击都势大力沉，能扛能打。", type: "exclusive"},
            {name: "狡兔屋的运气", color: "B", cost: 800, desc: "像妮可一样，虽然总是欠债，但总能化险为夷。金币获取量+20%，在空洞中更容易捡到稀有的旧世界遗物。", type: "exclusive"},
            {name: "极限闪避", color: "S", cost: 2200, desc: "你的反应速度极快。触发极限闪避的判定窗口变大，闪避成功后进入子弹时间，并获得攻击力加成。", type: "exclusive"},
            {name: "鸣徽猎人", color: "B", cost: 600, desc: "你在空洞中更容易获得稀有的“鸣徽”（Buff）。这让你在探索过程中能叠加出变态的属性组合，越战越强。", type: "exclusive"},
            {name: "拉面店常客", color: "C", cost: 150, desc: "你和拉面店老板关系好。进空洞前吃的拉面效果翻倍（如攻击力+30%），且持续时间无限。", type: "exclusive"},
            {name: "改装W-音擎", color: "B", cost: 700, desc: "你擅长改装武器核心。你的音擎基础攻击力更高，且带有特殊的被动效果（如攻击回能）。", type: "exclusive"},
            {name: "侵蚀抗性", color: "C", cost: 300, desc: "你对侵蚀症状有抗性。即使压力值满了，出现负面buff的概率也会降低，或者负面效果减半。", type: "exclusive"},
            {name: "金手指(黑客)", color: "A", cost: 1200, desc: "你精通骇入技术。可以开启空洞中的密码门，或者骇入敌方机械单位使其倒戈。Rain都要喊你一声大神。", type: "exclusive"},
            {name: "录像店老板", color: "D", cost: 50, desc: "你拥有一家录像店。虽然对战斗没帮助，但你可以通过经营店铺获得稳定的丁尼收入，还能看片消遣。", type: "exclusive"}
        ]
    },
