        { name: "九良岛采石场矿工", items: "一把磨损严重的十字镐, 一顶带有探照灯的安全帽" },
        { name: "遭到怪兽袭击的难民", items: "一张破损的全家福照片, 一个装有应急食品的背包" },
        { name: "不知名古代遗迹考察员", items: "一本写满奇怪符号的笔记, 一个快没电的手电筒" },
        { name: "网络新闻社的实习记者", items: "一台老旧的数码相机, 一张只有背影的巨人照片" }
    ],
    talents: [
        {name: "超古代战士基因(觉醒)", color: "SSS", cost: 32000, desc: "你体内流淌着纯正的超古代光之巨人基因，是真正能够变成光的人。拥有此天赋，你注定成为拯救世界的救世主，拥有无限的进化潜力。", type: "exclusive"},
        {name: "黑暗支配者的眷顾", color: "SSS", cost: 35000, desc: "你被邪神加坦杰厄选中，拥有操控黑雾和恐惧的能力。你可以召唤佐加军团，甚至在绝望中化身为毁灭世界的魔神。", type: "exclusive"},
        {name: "闪耀环身盾", color: "SS", cost: 9000, desc: "集合了全人类希望之光而形成的无敌防御。在关键时刻，你可以将这些光芒转化为力量，免疫一切负面状态并大幅提升全属性。", type: "exclusive"},
        {name: "胜利神光棒(真)", color: "SS", cost: 8500, desc: "超古代文明留下的变身神器，能够将光遗传因子转化为实体化的光之巨人。持有者可以变身为迪迦奥特曼，拥有复合、空中、强力三种形态。", type: "exclusive"},
        {name: "GUTS王牌飞行员", color: "S", cost: 1800, desc: "你拥有超越新城和对缘的驾驶技术，能够驾驶胜利飞燕号做出各种反物理机动，并且奇迹般地从未坠机。", type: "exclusive"},
        {name: "基里艾洛德人之魂", color: "S", cost: 1500, desc: "你拥有精神生命体基里艾洛德人的力量，可以附身人类，甚至巨大化变为炎魔战士。你极度渴望引导（统治）愚蠢的人类。", type: "exclusive"},
        {name: "麦格斯动力系统专家", color: "A", cost: 800, desc: "你深刻理解八尾博士开发的麦格斯动力系统，能够将其改装应用到各种武器或载具上，释放出毁灭性的光粒子能量。", type: "exclusive"},
        {name: "超能力(桐野)", color: "A", cost: 950, desc: "你拥有强大的预知能力和心灵感应，能够看穿怪兽的弱点和出现的地点，甚至能直接与奥特曼进行心灵对话。", type: "exclusive"},
        {name: "怪兽追踪器", color: "B", cost: 300, desc: "TPC最新研发的便携式雷达，能够探测到方圆五十公里内的异常生物反应，让你在怪兽出现前提前跑路。", type: "exclusive"},
        {name: "胜利海帕枪", color: "C", cost: 180, desc: "GUTS队员的标准配备，发射激光束。虽然对大怪兽像挠痒痒，但对付缩小外星人或防身绰绰有余。", type: "exclusive"},
        {name: "坠机体质", color: "E", cost: 10, desc: "一种被诅咒的体质。无论你驾驶什么飞行器，只要遇到怪兽，你有99%的概率会被击落。好消息是你总能跳伞成功。", type: "exclusive"},
        {name: "光遗传因子(微弱)", color: "B", cost: 400, desc: "你体内有一丝极其微弱的超古代基因，虽然不足以变身，但能让你在接触光之巨人石像时产生微弱的共鸣。", type: "exclusive"},
        {name: "齐杰拉花粉抗性", color: "B", cost: 350, desc: "你的精神意志极其坚定，能够抵抗齐杰拉花粉带来的极乐幻觉，在全人类沉沦时保持清醒。", type: "exclusive"},
        {name: "怪兽语翻译机", color: "C", cost: 150, desc: "堀井队员发明的泛语言翻译机，能够让你听懂怪兽的叫声。虽然大部分时候它们只是在喊‘痛’或者‘饿’。", type: "exclusive"},
        {name: "TPC格斗术", color: "C", cost: 120, desc: "经过TPC严格训练的近身格斗技巧，融合了柔道、空手道和擒拿术，足以对付普通的宇宙人侵略者。", type: "exclusive"},
        {name: "黑暗巨人契约", color: "SS", cost: 7000, desc: "你与黑暗三人组签订了契约，获得了使用黑暗力量的资格。你可以变身为黑暗巨人，但这会不断侵蚀你的理智。", type: "exclusive"},
        {name: "静止光线", color: "A", cost: 600, desc: "希尔巴贡的同族能力，虽然你没有视力缺陷，但你能发射定身光线，让敌人短时间内无法行动。", type: "exclusive"},
        {name: "虚幻的引导者", color: "D", cost: 80, desc: "你总觉得自己是神的使者，喜欢站在高处发表演讲。除了招人烦和容易被怪兽踩死外，没什么大用。", type: "exclusive"},
        {name: "迪迦之地守护者", color: "B", cost: 250, desc: "你熟悉金字塔周边的地形，并且在金字塔区域内，你的各项身体素质会得到微弱的增幅。", type: "exclusive"},
        {name: "等离子光束", color: "A", cost: 700, desc: "你能从手掌释放出高热的等离子光束，威力足以熔穿坦克的装甲，是加库玛能力的弱化版。", type: "exclusive"},
        {name: "机械岛改造技术", color: "S", cost: 1200, desc: "你掌握了机械岛哥布纽的自我修复和合体技术，可以将普通的金属改造成具有半生命特征的机械兵器。", type: "exclusive"},
        {name: "吸血鬼体质(休拉诺斯)", color: "A", cost: 650, desc: "你被吸血怪兽感染，畏惧阳光，但在夜晚拥有极快的速度和怪力，可以通过吸血恢复生命值。", type: "exclusive"},
        {name: "奥比克之锅", color: "B", cost: 450, desc: "一口神奇的锅，可以把人吞进去传送到指定地点，或者制造出一片漆黑的恐惧领域。", type: "exclusive"},
        {name: "露露耶遗迹地图", color: "S", cost: 2000, desc: "记载了超古代遗迹露露耶详细构造的地图，虽然那里充满了黑暗佐加，但也埋藏着无数超古代巨人的石像。", type: "exclusive"},
        {name: "希望之光(碎片)", color: "A", cost: 1000, desc: "孩子们心中的光芒凝聚而成的碎片。在绝境中，这块碎片能为你提供一次瞬间恢复满状态的机会。", type: "exclusive"},
        {name: "戴西斯星系人伪装", color: "C", cost: 100, desc: "你可以伪装成戴西斯星系人，虽然长得像个铁皮桶，但能混入外星侵略者的内部获取情报。", type: "exclusive"},
        {name: "亚特迪斯号整备员", color: "B", cost: 300, desc: "你拥有维护TPC最强战舰亚特迪斯号的资格，能够接触到麦格斯炮的核心代码。", type: "exclusive"},
        {name: "超古代怪兽召唤", color: "S", cost: 2200, desc: "你拥有唤醒沉睡怪兽的笛子，可以控制一只B级以下的超古代怪兽为你作战，持续时间十分钟。", type: "exclusive"},
        {name: "加库玛的石化光线", color: "A", cost: 750, desc: "能够发射将物体变成石头的蓝色光线。对生物同样有效，但消耗巨大的能量。", type: "exclusive"},
        {name: "真理的探索者", color: "C", cost: 160, desc: "你对超自然现象有极强的好奇心，这使你更容易发现隐藏的任务线索，但也更容易陷入危险。", type: "exclusive"}
    ]
},
{
    name: "462.银河奥特曼 (Ultraman Ginga)",
    desc: "所有奥特曼和怪兽变成了人偶的未来世界。降星小学隐藏着巨大的秘密，手持银河火花的少年将决定未来的命运，时间停止与未来科技是这个世界的主题。",
    boss: "黑暗路基艾尔, 维克特利·路基艾尔, 艾塔尔加",
    identities: [
        { name: "降星小学的转学生", items: "一个沉重的书包, 一本未完成的暑假作业" },
        { name: "后山的非法露营者", items: "一顶漏风的帐篷, 一个捡来的怪兽人偶(未实体化)" },
        { name: "被废弃校舍的巡逻保安", items: "一把生锈的手电筒, 一串打不开任何门的钥匙" },
        { name: "路过的摄影爱好者", items: "一台拍立得相机, 几张模糊的流星照片" },
        { name: "镇上的便利店店员", items: "一件印着银河神社的T恤, 一箱过期的泡面" }
    ],
    talents: [
        {name: "银河火花(被选中者)", color: "SSS", cost: 30000, desc: "来自未来的光之道具。你可以通过它将火花人偶实体化，甚至变身为来自未来的银河奥特曼，掌握银河穿击光线等七色必杀技。", type: "exclusive"},
        {name: "黑暗火花(持有者)", color: "SSS", cost: 30000, desc: "拥有停止时间能力的黑暗道具。你可以将生物变成火花人偶，或者将人偶实体化为受你控制的黑暗傀儡，最终目标是停止一切生命的时间。", type: "exclusive"},
        {name: "维克特利水晶之核", color: "SS", cost: 8000, desc: "地底世界的能量源泉。你拥有操控大地能量的能力，可以施展维克特利姆射线，并能感应地底怪兽的动向。", type: "exclusive"},
        {name: "实体化：泰罗奥特曼(人偶)", color: "S", cost: 2500, desc: "你拥有泰罗奥特曼的火花人偶。虽然因为某种原因不能完全巨大化，但你可以利用他的念力进行战斗和侦查。", type: "exclusive"},
        {name: "怪兽武装(Ultrans)", color: "S", cost: 2200, desc: "你可以将怪兽人偶扫描进变身器，将怪兽身体的一部分（如EX雷德王的拳头）武装在自己右臂上，获得怪兽的能力。", type: "exclusive"},
        {name: "谢帕顿圣剑", color: "SS", cost: 7500, desc: "由地底圣兽谢帕顿化身而成的水晶圣剑，蕴含着强大的维克特利姆能量，能够斩断黑暗，施展V字斩击。", type: "exclusive"},
        {name: "钢铁杀手(一条寺友也)", color: "S", cost: 2000, desc: "你拥有操纵高科技机器人‘钢铁杀手’的权限。这台机器火力全开时足以匹敌奥特曼，拥有强大的导弹和激光武器。", type: "exclusive"},
        {name: "黑暗路基艾尔的低语", color: "A", cost: 900, desc: "你的内心容易被黑暗侵蚀，但同时也能听到黑暗路基艾尔的指示，更容易找到隐藏的高级火花人偶。", type: "exclusive"},
        {name: "火花人偶收集家", color: "B", cost: 400, desc: "你对火花人偶有特殊的感应能力，能够轻易发现散落在各地的怪兽人偶，是收集癖玩家的必备天赋。", type: "exclusive"},
        {name: "降星镇的守护", color: "C", cost: 150, desc: "在降星镇范围内，你的幸运值小幅提升，遇到致命危险时更容易被路过的奥特曼救下。", type: "exclusive"},
        {name: "地底人的格斗术", color: "B", cost: 350, desc: "源自地底世界维克特利安的古武术，动作刚猛有力，擅长利用地形进行反击，非常适合近身肉搏。", type: "exclusive"},
        {name: "切布尔星人的科技树", color: "A", cost: 1200, desc: "你掌握了切布尔星人的部分黑科技，能够制造安德鲁博特或者强化怪兽人偶，甚至融合出五帝王。", type: "exclusive"},
        {name: "银河慰藉", color: "A", cost: 800, desc: "银河奥特曼的治愈技能。你可以释放柔和的光芒，平复怪兽的愤怒，或者治愈友军的伤势。", type: "exclusive"},
        {name: "瞬间移动(银河)", color: "S", cost: 1500, desc: "利用银河水晶的力量，你可以在短距离内进行瞬间移动，在战斗中戏耍敌人或快速脱离战场。", type: "exclusive"},
        {name: "超级融合(Super Grand King)", color: "SS", cost: 6000, desc: "你掌握了错误的融合方法，可以将多个怪兽人偶强行融合，制造出拥有毁灭性力量的超级古兰特王。", type: "exclusive"},
        {name: "斯特利姆手镯", color: "SS", cost: 7000, desc: "泰罗奥特曼给予的力量。装备后，你可以使用奥特六兄弟的所有光线技能，是全能的远程炮台。", type: "exclusive"},
        {name: "黑暗实体化", color: "B", cost: 500, desc: "你能够使用黑暗虚拟火花进行实体化，虽然变身后的怪兽眼睛是红色的且容易暴走，但战力不俗。", type: "exclusive"},
        {name: "UPG特种装备", color: "C", cost: 200, desc: "UPG队员的制式装备，包括智能手枪和防护服。虽然科技含量不如GUYS，但胜在轻便耐用。", type: "exclusive"},
        {name: "磁力怪兽(安东拉)之力", color: "A", cost: 650, desc: "你通过实体化安东拉，获得了操纵磁力的能力，可以吸引金属物体或者干扰电子设备的运行。", type: "exclusive"},
        {name: "时间冻结(伪)", color: "S", cost: 2800, desc: "模仿黑暗路基艾尔的能力，你可以让周围的时间流逝变慢30%，持续5秒。这在高手对决中是致命的优势。", type: "exclusive"},
        {name: "银河穿击光线(体验版)", color: "A", cost: 1000, desc: "你可以在不完全变身的情况下，从手中发射出小型的银河穿击光线，威力相当于一枚反坦克导弹。", type: "exclusive"},
        {name: "双重实体化", color: "S", cost: 1800, desc: "你拥有强大的精神力，可以同时控制两个实体化的火花人偶进行战斗，形成二打一的局面。", type: "exclusive"},
        {name: "魔神艾塔尔加的时空城", color: "SS", cost: 9500, desc: "你拥有召唤时空城投影的能力，可以制造出复杂的幻境迷宫，困住敌人并召唤过去的恐惧幻影。", type: "exclusive"},
        {name: "银河S波", color: "C", cost: 120, desc: "一种特殊的通讯波段，只有拥有银河火花或维克特利火花的人才能接收到，适合秘密联络。", type: "exclusive"},
        {name: "千兆战斗仪(复制品)", color: "A", cost: 1500, desc: "虽然是复制品，但依然能控制最多三只怪兽，并能释放出威力尚可的闪电攻击。", type: "exclusive"},
        {name: "黑暗路基艾尔的复活碎片", color: "B", cost: 450, desc: "一块散发着黑气的碎片，持有它会不断扣除生命值，但能大幅提升你的暗属性技能威力。", type: "exclusive"},
        {name: "维克特利姆加农", color: "S", cost: 2100, desc: "利用维克特利水晶作为能源的超级大炮，虽然充能时间长，但一击足以粉碎一座小山。", type: "exclusive"},
        {name: "银河火花枪", color: "S", cost: 1600, desc: "银河奥特曼的近战武器，蓝色的能量长枪，可以轻易刺穿怪兽坚硬的皮肤。", type: "exclusive"},
        {name: "人偶修复师", color: "C", cost: 180, desc: "你懂得如何修复受损的火花人偶，让那些战败后破损的人偶重新焕发生机。", type: "exclusive"},
        {name: "未来的希望", color: "D", cost: 50, desc: "你坚信未来是可以改变的。这种乐观的心态让你在面对绝望时，San值下降速度减半。", type: "exclusive"}
    ]
},
{
    name: "463.宇宙英雄之超银河传说 (Mega Monster Battle)",
    desc: "怪兽主宰的荒凉宇宙。雷奥尼克斯之间的死斗，贝利亚奥特曼的越狱与复仇，赛罗奥特曼的横空出世。这是属于怪兽使和奥特战士的战场。",
    boss: "贝利亚奥特曼, 百体怪兽贝柳多拉, 雷布拉德星人(精神体)",
    identities: [
        { name: "ZAP SPACY的维修工", items: "一把多功能扳手, 一件沾满油污的橙色队服" },
        { name: "哈玛行星的流浪者", items: "一件破烂的斗篷, 一块发霉的压缩饼干" },
        { name: "被遗弃的雷奥尼克斯", items: "一个破损的格斗仪, 一只濒死的皮古蒙" },
        { name: "光之国的见习警备队员", items: "一把训练用的光线枪, 一个奥特胶囊" },
        { name: "怪兽墓场的拾荒者", items: "一个防辐射面具, 一根用来翻找尸体的金属棍" }
    ],
    talents: [
        {name: "雷布拉德遗传因子(觉醒)", color: "SSS", cost: 33000, desc: "你是天生的雷奥尼克斯之王。拥有控制所有怪兽的潜力，甚至能变身为雷布拉德星人形态，统御宇宙怪兽军团。", type: "exclusive"},
        {name: "吉加格斗仪(Giga Battle Nizer)", color: "SS", cost: 9000, desc: "能控制一百只怪兽的终极格斗仪，贝利亚的专属武器。除了强大的物理攻击力，还能释放毁灭性的贝利亚死亡之镰。", type: "exclusive"},
        {name: "赛罗双镖(Zero Sluggers)", color: "SS", cost: 8500, desc: "赛罗奥特曼的头镖力量。你可以通过意念操控两把锋利无比的能量飞镖，切割万物，并能组合成赛罗双重剑。", type: "exclusive"},
        {name: "雷奥尼克斯格斗仪", color: "S", cost: 2500, desc: "标准的怪兽操控设备。允许你收服并控制三只怪兽进行战斗，随着你的成长，格斗仪也会进化，增强怪兽战力。", type: "exclusive"},
        {name: "哥莫拉(EX进化)", color: "S", cost: 2800, desc: "你的初始怪兽是古代怪兽哥莫拉，并且拥有进化为EX哥莫拉的潜力，全身皮肤硬化，拥有无坚不摧的超振动波。", type: "exclusive"},
        {name: "贝利亚之血", color: "A", cost: 1200, desc: "你被注入了贝利亚的黑暗基因，身体素质大幅提升，但也变得嗜血狂暴。在濒死时可能黑化暴走。", type: "exclusive"},
        {name: "等离子火花塔的能量", color: "SSS", cost: 28000, desc: "你接触过光之国的人工太阳核心。体内蕴含着无穷的光之能量，可以复活亡者，或者释放出毁灭星系的火花传说。", type: "exclusive"},
        {name: "盘龙号驾驶技术", color: "B", cost: 400, desc: "你精通宇宙飞船的驾驶，尤其是盘龙号这种大型运输舰，能在陨石带中穿梭自如，并发射佩丹元素炮。", type: "exclusive"},
        {name: "扎拉布星人的伪装", color: "B", cost: 500, desc: "你可以完美伪装成奥特曼或其他宇宙人，虽然不能复制技能，但足以欺骗大多数人的眼睛，制造混乱。", type: "exclusive"},
        {name: "怪兽墓场通行证", color: "C", cost: 200, desc: "你熟悉怪兽墓场的空间乱流规律，可以在这个亡灵聚集之地自由出入，寻找稀有的怪兽尸体或灵魂。", type: "exclusive"},
        {name: "雷奥尼克斯爆发模式", color: "A", cost: 1500, desc: "当你极度愤怒时，全身会变为红色，怪兽的攻击力翻倍，但你会失去理智，直到战斗结束或力竭。", type: "exclusive"},
        {name: "机械奥特兄弟制造图纸", color: "S", cost: 2000, desc: "萨罗梅星人的科技结晶。只要有足够的资源，你可以制造出机械赛文、机械初代等量产型兵器。", type: "exclusive"},
        {name: "利特拉的火焰", color: "C", cost: 300, desc: "你可以召唤原始怪鸟利特拉作为支援，虽然它很脆弱，但它的火球攻击能有效干扰敌人，且飞行速度极快。", type: "exclusive"},
        {name: "佩丹星人科技", color: "A", cost: 1000, desc: "你掌握了佩丹星人的黑色金古桥技术，可以制造或修复这种强大的合体机器人，拥有极高的防御力。", type: "exclusive"},
        {name: "宇宙拳法", color: "B", cost: 350, desc: "雷欧奥特曼传授的格斗技巧，强调实战和杀伤力。即使是人类形态，也能一拳打碎岩石。", type: "exclusive"},
        {name: "百体怪兽融合(残)", color: "SS", cost: 7500, desc: "贝柳多拉的一部分力量。你可以将多只怪兽的尸体融合在一起，制造出一只畸形的缝合怪兽，战力取决于素材质量。", type: "exclusive"},
        {name: "奥特胶囊(赛文)", color: "A", cost: 800, desc: "诸星团使用的胶囊怪兽乌英达姆。你可以随时召唤它出来助战，虽然有时候它会因为害怕而逃跑。", type: "exclusive"},
        {name: "雷布拉德的附身", color: "S", cost: 1800, desc: "你可以短暂借用雷布拉德星人的精神力量，大幅增强念动力，甚至能控制意志薄弱的敌人。", type: "exclusive"},
        {name: "终极战斗仪防御", color: "A", cost: 900, desc: "你学会了使用格斗仪进行格挡的技巧，能够抵挡光线技能的直击，是雷奥尼克斯保命的关键。", type: "exclusive"},
        {name: "艾莫利姆光线(学习版)", color: "B", cost: 450, desc: "你模仿赛文奥特曼，学会了从额头释放光线。虽然威力只有原版的十分之一，但胜在发射速度快。", type: "exclusive"},
        {name: "怪兽猎人", color: "C", cost: 150, desc: "你对怪兽的习性了如指掌，知道每一只怪兽的弱点部位（如尾巴、角、发光器官），攻击时暴击率提升。", type: "exclusive"},
        {name: "K76星云特训", color: "A", cost: 1100, desc: "你曾在雷欧的指导下进行过地狱般的特训，拥有钢铁般的意志和身体，对物理攻击有很高的抗性。", type: "exclusive"},
        {name: "赛罗的修行甲", color: "B", cost: 600, desc: "一套限制力量的铠甲，虽然会降低你的速度和攻击力，但提供了极高的防御力，解除后全属性爆发。", type: "exclusive"},
        {name: "等离子火花碎片", color: "S", cost: 2300, desc: "一块散发着温暖光芒的碎片，能持续恢复持有者的生命值，并对周围的黑暗生物造成持续伤害。", type: "exclusive"},
        {name: "布鲁顿的四次元能力", color: "SS", cost: 6500, desc: "你控制了四次元怪兽布鲁顿，获得了操纵空间的能力，可以瞬移、制造幻象或将敌人放逐到异次元。", type: "exclusive"},
        {name: "纳克尔星人的谋略", color: "B", cost: 250, desc: "你拥有纳克尔星人的阴险智慧，擅长制定针对敌人弱点的作战计划，并利用暗杀手段解决问题。", type: "exclusive"},
        {name: "宇宙空间适应", color: "C", cost: 100, desc: "你的身体经过改造，可以在真空中短暂生存，并且不需要呼吸氧气，适应各种恶劣的行星环境。", type: "exclusive"},
        {name: "杰顿的一兆度火球(伪)", color: "S", cost: 2600, desc: "你培育的杰顿能发射超高热火球。虽然达不到真正的一兆度，但足以瞬间蒸发一片湖泊。", type: "exclusive"},
        {name: "雷奥尼克斯决斗规则", color: "D", cost: 50, desc: "你必须遵守雷奥尼克斯的决斗神圣规则。在真正的决斗中，你无法使用卑鄙手段，但胜利后获得的经验值翻倍。", type: "exclusive"},
        {name: "光之国的救援信号", color: "C", cost: 120, desc: "一个紧急发信器。在危急时刻按下，有极小概率召唤路过的奥特战士前来救援。", type: "exclusive"}
    ]
},
{
    name: "464.铠甲勇士系列 (Armor Hero)",
    desc: "光影与五行的战场。异能兽、幽冥魔、欧克瑟肆虐人间，铠甲勇士们借助光影石、阿瑞斯科技或元素力量合体，维护世间正义。",
    boss: "黑魔兽, 路法大帝, 欧克瑟之王, 黑暗帝皇",
    identities: [
        { name: "幸福饺子馆的帮厨", items: "一根擀面杖, 一件沾满面粉的围裙" },
        { name: "ERP研究室的清洁工", items: "一张门禁卡(低级), 一个扫把" },
        { name: "巴王集团的保安", items: "一根橡胶警棍, 一套制服" },
        { name: "希望市的快递员", items: "一辆电动车, 一箱未送达的快递" },
        { name: "流浪的钢琴师", items: "一本破旧的乐谱, 一张光影村后人的老照片" }
    ],
    talents: [
        {name: "五行血统(纯)", color: "SSS", cost: 35000, desc: "你拥有最纯正的五行血统，能够召唤终极铠甲——帝皇侠。你掌握天道之力，能控制五行万物，是无敌的存在。", type: "exclusive"},
        {name: "修罗铠甲召唤权", color: "SSS", cost: 32000, desc: "银河系最强铠甲。只有具备最强之气（正气或邪气）的人才能召唤。拥有操纵时间、空间和万物的法力，战力无上限。", type: "exclusive"},
        {name: "火之炎龙铠甲", color: "SS", cost: 8000, desc: "五行铠甲之一，代表火。能力平均且强大，拥有烈焰刀和烈焰弓，必杀技‘封魔斩’能封印一切异能兽。", type: "exclusive"},
        {name: "刑天铠甲(战神烈火)", color: "SS", cost: 8500, desc: "阿瑞斯星的刑罚铠甲。升级为战神烈火剑模式后，攻击力爆表，拥有‘天地战神斩’，能斩断一切邪恶。", type: "exclusive"},
        {name: "雷霆雅塔莱斯", color: "SS", cost: 8800, desc: "汇聚了雷、火、水、土、风五大元素力量的终极铠甲。代表地球的意志，拥有极快的速度和毁灭性的元素攻击。", type: "exclusive"},
        {name: "光影石(随机)", color: "S", cost: 2500, desc: "你获得了一颗随机的光影石（金木水火土）。如果你具备相应的血统，即可召唤对应的光影铠甲。", type: "exclusive"},
        {name: "庚金刚杵", color: "S", cost: 2200, desc: "阿瑞斯星球的镇星之宝。能重构生物的分子结构，增强意能。持有者可以大幅提升铠甲的战斗力。", type: "exclusive"},
        {name: "意能修炼法", color: "A", cost: 1500, desc: "一套专门修炼意能的秘籍。意能越强，铠甲的威力就越大，甚至能开发出新的必杀技。", type: "exclusive"},
        {name: "异能兽体质", color: "B", cost: 500, desc: "你被改造成了异能兽，拥有坚硬的皮肤和怪力，但畏惧光影铠甲的必杀技，且长相丑陋。", type: "exclusive"},
        {name: "欧克瑟病毒抗体", color: "C", cost: 200, desc: "你体内拥有特殊的抗体，免疫丧暴病毒的感染，不会变成欧克瑟，是末世生存的必备被动。", type: "exclusive"},
        {name: "ERP卫星支援", color: "A", cost: 1200, desc: "你拥有调用ERP卫星的权限，可以进行瞬间传送、武器补充和能量恢复，是铠甲勇士最坚强的后盾。", type: "exclusive"},
        {name: "阿瑞斯伏魔术", color: "B", cost: 600, desc: "路法大帝掌握的阿瑞斯密术，包含各种封印、诅咒和强化魔法，适合法师型玩家。", type: "exclusive"},
        {name: "土之地虎铠甲", color: "A", cost: 1800, desc: "代表土的铠甲，跳跃力惊人。虽然常被调侃为充话费送的，但裂地劈的威力不容小觑。", type: "exclusive"},
        {name: "幽冥魔血统", color: "B", cost: 450, desc: "你拥有幽冥魔的血统，可以使用魔法和遁地术，拥有极长的寿命，但必须服从路法的命令。", type: "exclusive"},
        {name: "南博市首富", color: "C", cost: 300, desc: "你拥有巨大的财富，可以购买各种高科技装备，甚至投资开发人造铠甲，钞能力也是一种超能力。", type: "exclusive"},
        {name: "禅定印", color: "S", cost: 2000, desc: "光影铠甲的高级技能。发动后可以暂停周围的时间，虽然持续时间短，但足以决定胜负。", type: "exclusive"},
        {name: "酷雷伏铠甲", color: "A", cost: 1600, desc: "以防御力和力量著称的元素铠甲，代表峭之酷雷伏。拥有绝峭防御，适合充当团队坦克。", type: "exclusive"},
        {name: "拿瓦铠甲", color: "A", cost: 1700, desc: "拥有熔焰力量的攻击型铠甲，代表焰之拿瓦。攻击附带高额火焰伤害，必杀技熔焰螺旋拳。", type: "exclusive"},
        {name: "封魔盒", color: "SS", cost: 6000, desc: "封印了五大暗影护法的盒子。持有者可以释放暗影护法为你战斗，或者利用其中的黑暗能量强化自身。", type: "exclusive"},
        {name: "幸福饺子馆配方", color: "C", cost: 100, desc: "你掌握了做出让人感到幸福的饺子的秘方。食用者会暂时忘却烦恼，微量恢复意能。", type: "exclusive"},
        {name: "虚拟战斗室权限", color: "B", cost: 350, desc: "你可以随时进入虚拟战斗室进行训练，在不受伤的情况下提升战斗技巧和意能等级。", type: "exclusive"},
        {name: "黑犀侠的防御", color: "A", cost: 900, desc: "你拥有黑犀铠甲般的防御力，皮肤坚如钢铁，擅长使用水甲盾进行反击。", type: "exclusive"},
        {name: "风鹰腿", color: "B", cost: 500, desc: "你习得了风鹰侠的腿法，出腿速度极快，能够在空中进行多段踢击。", type: "exclusive"},
        {name: "雪獒之力", color: "A", cost: 850, desc: "你拥有雪獒侠的怪力，攻击附带震慑效果，每一拳都能打出破甲伤害。", type: "exclusive"},
        {name: "巴豆的黑客技术", color: "C", cost: 250, desc: "你拥有顶级的黑客技术，可以入侵交通网络、修改监控录像，甚至瘫痪敌人的电子设备。", type: "exclusive"},
        {name: "光之帝皇战龙", color: "SS", cost: 7500, desc: "帝皇侠的专属坐骑。一条巨大的光之机械龙，拥有毁灭性的龙息，可以带你飞入太空。", type: "exclusive"},
        {name: "驮拏多铠甲", color: "A", cost: 1650, desc: "代表飓风的铠甲，拥有极快的速度和飞行能力，擅长利用狂风进行远程打击。", type: "exclusive"},
        {name: "茨纳米铠甲", color: "A", cost: 1650, desc: "代表海啸的铠甲，擅长以柔克刚，能够利用水元素化解敌人的攻击并进行反击。", type: "exclusive"},
        {name: "贪系幽冥魔(紫冥)", color: "B", cost: 400, desc: "你属于紫冥分队，擅长使用幻术和超能力，能够制造分身迷惑敌人。", type: "exclusive"},
        {name: "向阳体质", color: "S", cost: 2800, desc: "你像向阳一样，不需要光影石也能直接召唤帝皇铠甲，但这对身体负担极大，且容易暴走。", type: "exclusive"}
    ]
},
{
    name: "465.超兽武装系列 (Ultra Beast Force)",
    desc: "七大平行宇宙的轮回。信念决定现实，异能量是核心。超兽战士们驾驶机甲，穿梭于不同宇宙，在冥王与雪皇的哲学博弈中寻找平衡。",
    boss: "冥王, 雪皇, 鬼谷(鬼王), 云蝠军团",
    identities: [
        { name: "第一平行宇宙的中学生", items: "一个篮球, 一本关于平行宇宙的科幻小说" },
        { name: "第二平行宇宙的白龙族奴隶", items: "一副沉重的脚镣, 一块用来挖掘的石头" },
        { name: "第三平行宇宙的金象族士兵", items: "一把长矛, 一面刻着鲸鲨王印记的盾牌" },
        { name: "第四平行宇宙的云蝠军团小兵", items: "一套飞行夜视仪, 绝对服从命令的洗脑芯片" },
        { name: "第五平行宇宙的冥界守卫", items: "一把黑色的长戟, 一身漆黑的铠甲" }
    ],
    talents: [
        {name: "超兽神合体(核心)", color: "SSS", cost: 30000, desc: "你拥有主导超兽神合体的能力。能够汇聚七大超兽的力量，召唤出维持宇宙平衡的终极机甲——超兽神，战力无限接近宇宙真理。", type: "exclusive"},
        {name: "冥王的玄冥黑洞", color: "SSS", cost: 35000, desc: "强者的极致。你可以制造并操控巨大的黑洞，吞噬一切物质和能量，甚至封印雪皇级别的强者。缺点是容易把自己也关进去。", type: "exclusive"},
        {name: "雪皇的白雪圣辉", color: "SSS", cost: 35000, desc: "爱的极致。释放出覆盖星系的圣光，能治愈一切伤痛，也能用光芒瞬间蒸发敌人。你的异能量充满了爱，但也容易因为爱而变得伪善。", type: "exclusive"},
        {name: "异能量(S级)", color: "S", cost: 2500, desc: "你拥有高达3个黑洞当量的异能量。这足以让你召唤强大的超兽，并在平行宇宙中自由穿梭。", type: "exclusive"},
        {name: "云蝠阵(指挥权)", color: "SS", cost: 8000, desc: "你掌握了夜凌云的云蝠阵奥义。可以汇聚成千上万云蝠士兵的异能量于一身，爆发出毁天灭地的攻击。", type: "exclusive"},
        {name: "玄武号飞船", color: "SS", cost: 7500, desc: "拥有自我意识和超高防御力的飞船。它能带你穿越时空，提供异能量补给，并拥有强大的防御系统。", type: "exclusive"},
        {name: "火麟飞的武装", color: "A", cost: 1800, desc: "幻麟武装。你可以召唤红色麒麟机甲，擅长近战格斗，必杀技‘火云诀’能释放出高热火焰。", type: "exclusive"},
        {name: "天羽的武装", color: "A", cost: 1800, desc: "凤羽武装。你可以召唤粉色凤凰机甲，拥有极高的机动性和飞行能力，必杀技‘幻天诀’。", type: "exclusive"},
        {name: "龙戬的武装", color: "A", cost: 1800, desc: "龙战武装。你可以召唤蓝色青龙机甲，擅长冰系攻击，必杀技‘寒影诀’能冻结敌人。", type: "exclusive"},
        {name: "泰雷的武装", color: "A", cost: 1800, desc: "雷象武装。你可以召唤金色雷象机甲，拥有强大的力量和防御，必杀技‘奔雷诀’能引发地震和雷电。", type: "exclusive"},
        {name: "夜凌云的武装", color: "S", cost: 2200, desc: "云蝠武装。你可以召唤紫色蝙蝠机甲，拥有音波攻击和隐形能力，必杀技‘亡月劫’。", type: "exclusive"},
        {name: "鲸鲨王的武装", color: "S", cost: 2100, desc: "鲸鲨武装。你可以召唤蓝色鲸鲨机甲，拥有黑洞吸噬能力，必杀技‘海啸劫’。", type: "exclusive"},
        {name: "狮王的武装", color: "S", cost: 2300, desc: "绝地雄狮武装。你可以召唤金色狮子机甲，拥有霸道的物理攻击力，必杀技‘七伤劫’。", type: "exclusive"},
        {name: "蝎子王的武装", color: "A", cost: 1900, desc: "毒蝎武装。你可以召唤紫色蝎子机甲，擅长毒素攻击和敏捷作战，必杀技‘红尘劫’。", type: "exclusive"},
        {name: "永恒轮回记忆", color: "SS", cost: 6000, desc: "你保留了十万年轮回的记忆。这意味着你知晓所有人的弱点和命运走向，是打破轮回的关键。", type: "exclusive"},
        {name: "玄易子的蛇板", color: "B", cost: 500, desc: "一个绿色的悬浮滑板，速度极快，是逃跑和赶路的神器。附带玄易子的哲学语录播放功能。", type: "exclusive"},
        {name: "元空灭", color: "SS", cost: 9000, desc: "玄易子的终极绝招。燃烧生命制造元空灭，将自己和敌人强行带入异次元空间，同归于尽的招式。", type: "exclusive"},
        {name: "信念之力", color: "C", cost: 200, desc: "在这个世界，信念决定异能量。你的意志越坚定，你的战斗力就越强。适合热血笨蛋型主角。", type: "exclusive"},
        {name: "鬼谷的伪装", color: "A", cost: 1200, desc: "你擅长伪装成正人君子，能够轻易骗取他人的信任，并在背后捅刀子。附带技能‘惊魂星云’。", type: "exclusive"},
        {name: "Baboo的治疗", color: "B", cost: 400, desc: "你身边跟着一只精灵Baboo，它能为你提供异能量恢复和治疗，虽然它经常闯祸。", type: "exclusive"},
        {name: "时空穿梭(单次)", color: "S", cost: 2000, desc: "你拥有一次不依赖飞船进行时空穿梭的能力，可以回到十万年前或前往十万年后，改变历史。", type: "exclusive"},
        {name: "异能量侦测", color: "C", cost: 100, desc: "你能感知周围生物的异能量数值，准确判断敌我差距，避免去送死。", type: "exclusive"},
        {name: "狼族血统", color: "B", cost: 350, desc: "你拥有冥界狼族的血统，在黑暗环境中战斗力提升，性格坚韧不拔，对冥王绝对忠诚。", type: "exclusive"},
        {name: "白虎族血统", color: "B", cost: 350, desc: "你拥有雪皇白虎族的血统，在光芒下战斗力提升，性格高傲，坚信爱能感化一切。", type: "exclusive"},
        {name: "星云体(雏形)", color: "SS", cost: 8500, desc: "强者证明。你能够召唤出巨大的星云体作战，战力是普通超兽的数十倍，但消耗巨大的异能量。", type: "exclusive"},
        {name: "哲学辩论大师", color: "D", cost: 80, desc: "你擅长用‘已有的事后必再有，已行的事后必再行’等骚话干扰敌人的心智，让对方陷入哲学思考而停止攻击。", type: "exclusive"},
        {name: "寒冰死气", color: "A", cost: 900, desc: "龙戬的特殊能力。你可以释放出极寒的死气，降低敌人的速度，甚至冻结时间流速。", type: "exclusive"},
        {name: "火云决(改良版)", color: "A", cost: 1000, desc: "经过改良的火云决，不需要异能锁也能释放，虽然威力稍弱，但胜在瞬发。", type: "exclusive"},
        {name: "你是我的敌人", color: "E", cost: 50, desc: "被动诅咒。无论你走到哪里，总会被人误认为是敌人。在超兽世界，这可能意味着你会被两边一起打。", type: "exclusive"},
        {name: "平衡法则", color: "S", cost: 2800, desc: "你领悟了宇宙平衡的真谛。当你的对手比你强时，你的异能量会临时提升；比你弱时，会下降。", type: "exclusive"}
    ]
},
{
    name: "466.熊出没系列 (Boonie Bears)",
    desc: "看似平静的狗熊岭，实则隐藏着超越时代的黑科技和远古秘密。光头强与熊大熊二的日常背后，是平行时空、外星文明与史前巨兽的碰撞。",
    boss: "天才威, 夺宝军团首领, 团子(山神形态), 狂野大陆AI",
    identities: [
        { name: "狗熊岭的伐木工学徒", items: "一把生锈的电锯, 一本《伐木工自我修养》" },
        { name: "迷路的城市游客", items: "一个没信号的手机, 一包快吃完的薯片" },
        { name: "森林里的松鼠", items: "几颗松果, 极其灵敏的听觉" },
        { name: "被遗弃的马戏团动物", items: "一个彩球, 一身褪色的演出服" },
        { name: "神秘的森林护林员", items: "一个望远镜, 一本记录着稀有动物的笔记" }
    ],
    talents: [
        {name: "光头强的发明天赋", color: "SSS", cost: 30000, desc: "因果律级别的科研能力。只要有废铁和垃圾，你能造出任何东西，从缩小灯到时空穿梭机，且无视能量守恒定律。", type: "exclusive"},
        {name: "山神团子的庇护", color: "SSS", cost: 32000, desc: "白熊山神的眷顾。你可以召唤巨大的山神团子，拥有操控冰雪、火山和大地之力的神级力量，愤怒时可毁灭世界。", type: "exclusive"},
        {name: "金鹿角的生命之力", color: "SS", cost: 9000, desc: "奇幻空间的神器。拥有复活万物、净化心灵和操控植物的能力。持有它，你就是森林的绝对主宰。", type: "exclusive"},
        {name: "熊大熊二的羁绊", color: "S", cost: 2500, desc: "当你有同伴在场时，智商和力量大幅提升。你可以像熊大一样足智多谋，或者像熊二一样力大无穷且运气爆棚。", type: "exclusive"},
        {name: "天才威的采集器", color: "S", cost: 2200, desc: "高科技采集枪。可以抽取任何生物的能力因子（如速度、力量、放电），并将其赋予自己或机械兽。", type: "exclusive"},
        {name: "变形记缩小手电", color: "SS", cost: 7000, desc: "一把可以将人或物体无限缩小的手电筒。进入微观世界后，你将面对巨大的昆虫，但也拥有了潜入任何地方的能力。", type: "exclusive"},
        {name: "狂野大陆变身手环", color: "A", cost: 1800, desc: "基因科技的结晶。你可以随意变身成任何动物，获得其能力（如鹰的飞行、豹的速度），甚至可以进行超级变身。", type: "exclusive"},
        {name: "吉吉国王的权杖", color: "B", cost: 500, desc: "虽然只是一根木棍，但在猴群中拥有至高无上的权威。你可以指挥森林里的猴子为你收集情报或骚扰敌人。", type: "exclusive"},
        {name: "赵琳的探险笔记", color: "C", cost: 200, desc: "记录了狗熊岭及周边地区所有稀有动物和地形的笔记。拥有它，你就拥有了活点地图，不会在森林迷路。", type: "exclusive"},
        {name: "阿布的外星科技", color: "SS", cost: 8000, desc: "来自莱尔特族的高科技。包含反重力飞船、能量护盾和记忆消除器。你可以利用这些科技碾压地球文明。", type: "exclusive"},
        {name: "伐木机器人的核心", color: "A", cost: 1200, desc: "光头强制造的超级伐木机器人的核心。你可以将其植入任何机械中，赋予其强大的动力和伐木（战斗）程序。", type: "exclusive"},
        {name: "纳雅的射箭术", color: "A", cost: 1000, desc: "鹿族少女的箭术。百发百中，且你的箭矢附带森林魔法，可以追踪敌人或在命中后生出藤蔓束缚目标。", type: "exclusive"},
        {name: "肥波的敏锐直觉", color: "B", cost: 400, desc: "像猫一样敏锐。你能察觉到周围潜伏的危险，并在第一时间爬上树。也是偷吃食物的好手。", type: "exclusive"},
        {name: "李老板的电话", color: "D", cost: 100, desc: "一个永远会催你交货的电话。虽然很烦，但如果你完成了任务，李老板真的会给你发各种黑科技装备。", type: "exclusive"},
        {name: "原始时代的勇气", color: "B", cost: 350, desc: "来自原始时代的野性力量。在面对巨兽时，你不会感到恐惧，反而会激发体内的战斗本能。", type: "exclusive"},
        {name: "钢铁侠战甲(光头强版)", color: "S", cost: 2800, desc: "光头强用废铜烂铁敲出来的战甲。虽然外观简陋，但拥有飞行、激光炮和怪力，防御力惊人。", type: "exclusive"},
        {name: "萝卜头的挖掘术", color: "C", cost: 150, desc: "你拥有地鼠般的挖掘速度，可以在地下快速穿行，建造复杂的地下迷宫，是潜行和逃跑的神技。", type: "exclusive"},
        {name: "蹦蹦的八卦网", color: "C", cost: 120, desc: "松鼠蹦蹦的情报网。你可以从森林里的任何小动物口中得知最新的八卦和情报。", type: "exclusive"},
        {name: "马戏团的杂技", color: "C", cost: 180, desc: "黑风传授的杂技。你拥有极高的身体柔韧性和平衡感，能在树枝间跳跃如飞。", type: "exclusive"},
        {name: "洞洞幺的飞行翼", color: "B", cost: 300, desc: "天才威助手的装备。一个小型的飞行背包，虽然载重有限，但机动性极高，适合侦查。", type: "exclusive"},
        {name: "重返地球的机甲", color: "SS", cost: 8500, desc: "结合了外星科技和地球垃圾的终极机甲。拥有太空作战能力，火力足以摧毁一颗小行星。", type: "exclusive"},
        {name: "美食猎人", color: "B", cost: 250, desc: "你对美食有极强的执念。这让你能发现隐藏的食材，并且做出的食物能大幅恢复体力和心情。", type: "exclusive"},
        {name: "图图的古武术", color: "A", cost: 900, desc: "猫头鹰图图传授的古老武术。动作诡异莫测，擅长点穴和借力打力，专克蛮力型对手。", type: "exclusive"},
        {name: "超级粘合剂", color: "C", cost: 80, desc: "光头强的发明之一。一旦粘上，除非用特制解药，否则绝对分不开。控制敌人的神器。", type: "exclusive"},
        {name: "空气炮", color: "B", cost: 450, desc: "能发射强力压缩空气的手枪。无形无色，击退效果极强，且不会造成致命伤（适合正派）。", type: "exclusive"},
        {name: "东北话专精", color: "E", cost: 10, desc: "你精通纯正的东北话。在这个世界，这能让你更容易获得NPC（尤其是熊大熊二）的好感。", type: "exclusive"},
        {name: "倒霉体质", color: "D", cost: 50, desc: "你像光头强一样倒霉。走路摔跤，喝水塞牙。但这种体质也让你练就了金刚不坏之身。", type: "exclusive"},
        {name: "森林之友", color: "A", cost: 1500, desc: "你是大自然的朋友。森林里的动物不会主动攻击你，甚至会在你危难时挺身而出。", type: "exclusive"},
        {name: "垃圾分类大师", color: "C", cost: 60, desc: "你擅长垃圾分类。这让你在翻找垃圾堆时，能更有效率地找到有用的零件或道具。", type: "exclusive"},
        {name: "团子的愤怒", color: "S", cost: 2600, desc: "当你受到重伤时，有几率召唤山神团子的投影，释放一次全屏冰冻攻击。", type: "exclusive"}
    ]
},
{
    name: "467.猪猪侠系列 (GG Bond)",
    desc: "一个充满童话色彩但内核热血的多元宇宙。从最初的魔法智慧球到五灵卫，猪猪侠永远是那个爱吃棒棒糖的英雄。这里有魔法、武术、机甲和赛车。",
    boss: "超人强(早期), 黑暗之王, 魇魔王, 巴罗",
    identities: [
        { name: "望子成龙小学的留级生", items: "一个超级棒棒糖, 一本不及格的试卷" },
        { name: "迷糊老师的实验助手", items: "一副爆炸头假发, 一瓶不知名的药水" },
        { name: "积木世界的居民", items: "一身方块状的衣服, 几块备用的积木零件" },
        { name: "五灵卫训练营的新兵", items: "一个基础五灵锁, 一本变身手册" },
        { name: "深海之城的清洁工", items: "一套潜水服, 一个清理海藻的铲子" }
    ],
    talents: [
        {name: "五灵王之力(终极)", color: "SSS", cost: 33000, desc: "集合了金木水火土五种元素的最强力量。你可以变身为五灵王，拥有统治童话世界的力量，但需要极强的意志力控制暴走。", type: "exclusive"},
        {name: "超级棒棒糖(无限)", color: "SS", cost: 8000, desc: "猪猪侠的标志性道具。食用后，你的力量、速度和防御力在短时间内提升1000%，且拥有无限续杯的能力。", type: "exclusive"},
        {name: "降龙十巴掌", color: "S", cost: 2500, desc: "猪猪侠的绝世武功。至刚至阳的掌法，每一掌都带有龙形气劲，打得越久威力越大，专治各种不服。", type: "exclusive"},
        {name: "五灵锁(主角版)", color: "S", cost: 2800, desc: "能够变身为铁拳虎、神木猿、冰封鹿、火焰鹤、石甲熊的高级变身器。每种形态都有独特的技能和必杀技。", type: "exclusive"},
        {name: "开天宝剑", color: "SS", cost: 7500, desc: "积木世界的传说武器。拥有劈开天地的力量，对黑暗生物有极大的克制作用，是击败终极BOSS的关键。", type: "exclusive"},
        {name: "迷糊老师的发明", color: "A", cost: 1500, desc: "你可以随机获得迷糊老师的一项发明。可能是无敌的机甲，也可能是会爆炸的闹钟，充满了不确定性。", type: "exclusive"},
        {name: "猪猪开天宝剑(机甲)", color: "SS", cost: 8500, desc: "超星萌宠中的终极机甲形态。结合了所有特工的力量，拥有斩断星辰的威力，防御力也是顶级的。", type: "exclusive"},
        {name: "魔龙王血统", color: "S", cost: 2200, desc: "你拥有反派魔龙王的血统，擅长使用黑暗魔法和龙息，肉体力量极强，但容易被正义之气克制。", type: "exclusive"},
        {name: "竞速小英雄赛车", color: "A", cost: 1200, desc: "一辆拥有自我意识的超级赛车。速度极快，可以进行变形和发射武器，适合在赛车主题的世界观中使用。", type: "exclusive"},
        {name: "菲菲的公主光环", color: "B", cost: 500, desc: "你拥有菲菲公主的气质，容易获得NPC的帮助，且擅长治愈魔法和防御屏障。", type: "exclusive"},
        {name: "超人强的自负", color: "C", cost: 200, desc: "你像超人强一样强壮且自恋。虽然这让你容易轻敌，但你的物理攻击力和抗击打能力确实是顶尖的。", type: "exclusive"},
        {name: "波比的拍马屁", color: "D", cost: 100, desc: "你精通阿谀奉承之道。这让你在加入反派阵营时能快速晋升，或者在被抓时保住小命。", type: "exclusive"},
        {name: "小呆呆的鼻涕泡", color: "A", cost: 1000, desc: "大智若愚的神技。你的鼻涕泡可以困住敌人，甚至能反弹攻击。你的混乱逻辑能免疫精神控制。", type: "exclusive"},
        {name: "光明守卫者", color: "S", cost: 2000, desc: "你被选为光明守卫者，拥有纯净的光明力量，可以净化被黑暗侵蚀的五灵卫，大幅提升对暗属性敌人的伤害。", type: "exclusive"},
        {name: "黑暗拼装术", color: "B", cost: 600, desc: "积木世界的禁术。你可以将任何物体强行拆解并重新拼装，制造出怪异的积木怪兽为你战斗。", type: "exclusive"},
        {name: "元灵锁", color: "A", cost: 1600, desc: "比五灵锁更高级的变身器。可以让你与元灵签订契约，变身为更加帅气和强大的元素战士。", type: "exclusive"},
        {name: "猪猪侠的运气", color: "S", cost: 2600, desc: "绝对的主角光环。无论遇到多大的危险，你总能化险为夷，并且莫名其妙地完成任务。", type: "exclusive"},
        {name: "深海积木", color: "C", cost: 300, desc: "一种特殊的积木材料，在水中坚硬无比，可以用来建造潜艇或水下基地。", type: "exclusive"},
        {name: "铁拳虎·金刚铁拳", color: "A", cost: 900, desc: "铁拳虎形态的必杀技。汇聚全身力量于右拳，打出金色的虎形冲击波，无坚不摧。", type: "exclusive"},
        {name: "冰封鹿·绝对零度", color: "A", cost: 950, desc: "冰封鹿形态的必杀技。瞬间冻结周围的一切，制造有利于自己的冰雪场地。", type: "exclusive"},
        {name: "火焰鹤·烈焰之舞", color: "A", cost: 950, desc: "火焰鹤形态的必杀技。在空中飞舞并撒下漫天火雨，造成大范围的持续伤害。", type: "exclusive"},
        {name: "石甲熊·大地之盾", color: "A", cost: 950, desc: "石甲熊形态的必杀技。召唤巨大的岩石盾牌，抵挡S级以下的所有攻击。", type: "exclusive"},
        {name: "神木猿·木藤缠绕", color: "A", cost: 950, desc: "神木猿形态的必杀技。召唤巨大的藤蔓束缚敌人，并吸取其体力。", type: "exclusive"},
        {name: "X元素", color: "SS", cost: 7000, desc: "一种神秘的未知元素。融合了它，你的能力会发生变异，获得超越五行的特殊力量，如空间或重力。", type: "exclusive"},
        {name: "玫瑰王子(黑化)", color: "S", cost: 2300, desc: "你拥有玫瑰王子的剑术和优雅，但在黑化状态下，你的攻击带有诅咒效果，且不知疼痛。", type: "exclusive"},
        {name: "希望之光", color: "S", cost: 2100, desc: "汇聚了童话世界居民希望的光芒。能驱散一切黑暗迷雾，大幅提升全队属性。", type: "exclusive"},
        {name: "零食大礼包", color: "E", cost: 20, desc: "一包永远吃不完的零食。虽然不能增加战斗力，但能让你保持快乐，防止抑郁。", type: "exclusive"},
        {name: "普利斯教授的阴谋", color: "B", cost: 400, desc: "你拥有普利斯教授的智慧，擅长制造混乱和利用他人，适合智力型反派玩家。", type: "exclusive"},
        {name: "超星特工手表", color: "C", cost: 150, desc: "具备通讯、扫描、传送等功能的智能手表，是星际特工的标准装备。", type: "exclusive"},
        {name: "阿五的陪伴", color: "B", cost: 350, desc: "你拥有一只名为阿五的超星萌宠，它可以变形为武器或载具，是你最忠实的伙伴。", type: "exclusive"}
    ]
},
{
    name: "468.果宝特攻系列 (Fruity Robo)",
    desc: "水果江湖，机甲争霸。这是一个充满武侠气息的水果世界，橙留香、菠萝吹雪、陆小果三人组驾驶果宝机甲，对抗东方求败和四大恶贼。",
    boss: "东方求败, 龟太公, 魔霸天王, 乱臣贼子",
    identities: [
        { name: "果冻武术学院的杂役", items: "一把扫把, 一本《葵花宝典》(残卷)" },
        { name: "花果山的普通游客", items: "一个相机, 一篮水果" },
        { name: "四大恶贼的小兵", items: "一把量产型水果刀, 一个印着‘恶’字的头巾" },
        { name: "水果加工厂的工人", items: "一副手套, 一箱罐头" },
        { name: "七色彩莲池的守护者(实习)", items: "一根荷叶茎, 一瓶池水" }
    ],
    talents: [
        {name: "果宝战神合体", color: "SSS", cost: 32000, desc: "集结七大果宝机甲的力量，合体成为无敌的果宝战神。手持巨大的金色长剑，拥有斩断山河的威力，是正义的终极象征。", type: "exclusive"},
        {name: "魔霸天王合体", color: "SSS", cost: 31000, desc: "东方求败与四大恶贼的终极合体。拥有极强的黑暗力量和防御力，必杀技‘魔能爆裂’能摧毁一座城市。", type: "exclusive"},
        {name: "香橙战宝(升级版)", color: "SS", cost: 8000, desc: "橙留香的专属机甲。拥有极高的攻击力和正义之心，必杀技‘天外飞鲜’威力巨大，且随着驾驶者热血程度提升。", type: "exclusive"},
        {name: "菠萝战宝(升级版)", color: "SS", cost: 8000, desc: "菠萝吹雪的专属机甲。擅长双刀流和速度战，必杀技‘菠萝蜜多斩’，帅气与实力并存。", type: "exclusive"},
        {name: "小果战宝(升级版)", color: "SS", cost: 8000, desc: "陆小果的专属机甲。配备双枪，虽然驾驶者经常不靠谱，但运气极好，必杀技‘爱果者导弹’自带追踪。", type: "exclusive"},
        {name: "七色彩莲之力", color: "SSS", cost: 28000, desc: "水果世界的生命之源。拥有净化一切邪恶、复活枯萎植物和治愈重伤的能力。持有者将成为水果世界的守护神。", type: "exclusive"},
        {name: "移花接木大法", color: "S", cost: 2500, desc: "一种神奇的武功。可以将受到的攻击转移给别人，或者是交换双方的位置，是保命和坑人的神技。", type: "exclusive"},
        {name: "含笑半步癫", color: "B", cost: 500, desc: "天下第一奇毒。中毒者走半步就会大笑而死（其实是全身麻痹）。是行走江湖、杀人越货的必备良药。", type: "exclusive"},
        {name: "陆小果的运气", color: "S", cost: 2600, desc: "因果律级别的强运。你随便乱按按钮都能打出暴击，迷路也能找到宝藏，闭着眼睛开枪也能命中敌人。", type: "exclusive"},
        {name: "菠萝吹雪的经商头脑", color: "C", cost: 200, desc: "你拥有极佳的商业头脑，能把稻草卖成金条。在这个需要钱升级机甲的世界，这是非常实用的天赋。", type: "exclusive"},
        {name: "方丈的教诲", color: "B", cost: 350, desc: "你时不时会说出几句充满哲理（废话）的台词，这能提升队友的士气，或者让敌人陷入短暂的懵逼状态。", type: "exclusive"},
        {name: "草莓战宝", color: "A", cost: 1800, desc: "上官子怡的机甲。擅长剑术和敏捷作战，必杀技‘莓力四射剑’，是女性玩家的首选。", type: "exclusive"},
        {name: "蜜桃战宝", color: "A", cost: 1800, desc: "梨花诗的机甲。拥有飞行能力和优雅的剑法，必杀技‘惊天蜜桃杀’。", type: "exclusive"},
        {name: "葡萄战宝", color: "A", cost: 1800, desc: "花如意的机甲。使用双弓，远程输出能力强，必杀技‘如意金箍棒’（其实是箭）。", type: "exclusive"},
        {name: "集结号", color: "C", cost: 150, desc: "吹响集结号，可以召唤附近的果宝特攻机甲前来支援。当然，他们来不来得看心情。", type: "exclusive"},
        {name: "麒麟臂", color: "A", cost: 1000, desc: "你的右臂拥有麒麟之力，力量是常人的十倍，驾驶机甲时能提升近战攻击力。", type: "exclusive"},
        {name: "爆裂王", color: "S", cost: 2200, desc: "火龙果的机甲。拥有强大的火力和防御，必杀技‘爆裂拳’。", type: "exclusive"},
        {name: "海鲨王", color: "S", cost: 2200, desc: "斜眼狼的机甲。擅长水中作战，必杀技‘鲨王钻’。", type: "exclusive"},
        {name: "重炮王", color: "S", cost: 2200, desc: "刀疤脸的机甲。拥有超远程的火炮打击能力，必杀技‘重炮轰击’。", type: "exclusive"},
        {name: "龟太公的阴谋", color: "A", cost: 1200, desc: "你拥有龟太公的城府，擅长易容和欺骗，能够利用规则漏洞击败比自己强大的对手。", type: "exclusive"},
        {name: "椰子尊", color: "S", cost: 2300, desc: "疯清扬方丈的机甲。拥有深不可测的内力，必杀技‘椰子微波’。", type: "exclusive"},
        {name: "西瓜尊", color: "S", cost: 2300, desc: "英雄师父的机甲。使用双锤，力量极大，必杀技‘西瓜流星锤’。", type: "exclusive"},
        {name: "香蕉尊", color: "S", cost: 2300, desc: "无极师父的机甲。速度极快，必杀技‘香蕉回旋镖’。", type: "exclusive"},
        {name: "山竹尊", color: "S", cost: 2300, desc: "夜燕老师的机甲。身法轻盈，必杀技‘落英缤纷’。", type: "exclusive"},
        {name: "青梅竹马", color: "C", cost: 100, desc: "你和某位主角是青梅竹马。这能让你更容易获得机甲的使用权，但也更容易被反派绑架。", type: "exclusive"},
        {name: "水果营养液", color: "D", cost: 50, desc: "一瓶神奇的饮料。喝下去后瞬间恢复体力，是驾驶机甲持久战的必备补给。", type: "exclusive"},
        {name: "解构主义台词", color: "E", cost: 10, desc: "你经常打破第四面墙，吐槽剧情。这虽然不能杀敌，但能让你在观众（玩家）心中获得很高的人气。", type: "exclusive"},
        {name: "古龙文风", color: "D", cost: 20, desc: "你说话简短有力。你的刀很快。你的剑更冷。这能提升你的装逼指数。", type: "exclusive"},
        {name: "水果忍者", color: "B", cost: 400, desc: "你精通切水果的技巧。在面对水果形态的敌人时，你的暴击率翻倍。", type: "exclusive"},
        {name: "机甲维修术", color: "B", cost: 300, desc: "你懂得如何快速修理受损的果宝机甲，保证在战斗中不会掉链子。", type: "exclusive"}
    ]
},
{
    name: "469.喜羊羊与灰太狼系列 (Pleasant Goat)",
    desc: "青青草原的生存法则。从狼抓羊的单元剧到跨种族联盟的史诗冒险。这里有灰太狼的黑科技、羊村的智慧防御，以及地底、天空、未来的广阔世界。",
    boss: "黑大帅, 苦瓜大王, 狼将军, 剔博士, 机械羊",
    identities: [
        { name: "羊村的小学生", items: "一个书包, 一根棒棒糖" },
        { name: "狼堡的灰太狼表弟", items: "一件破旧的狼皮大衣, 一本《抓羊一百法》" },
        { name: "青青草原的包包大人手下", items: "一根警棍, 一本草原法典" },
        { name: "地底世界的居民", items: "一个矿灯, 一把铲子" },
        { name: "天空之城的云巨人", items: "一朵云彩, 一个巨大的浇水壶" }
    ],
    talents: [
        {name: "灰太狼的发明能力", color: "SSS", cost: 31000, desc: "全宇宙最强的发明家之一。只要有剧情需要，你可以发明出天气控制器、时光机、克隆机等神器。唯一的弱点是老婆的平底锅。", type: "exclusive"},
        {name: "喜羊羊的智慧", color: "SSS", cost: 30000, desc: "智力天花板。你总能在绝境中想出破局的方法，无论是破解机关还是战术指挥，都是神级的存在。", type: "exclusive"},
        {name: "不死之身(搞笑漫)", color: "SS", cost: 9000, desc: "规则级能力。无论被炸飞、被压扁还是被烧焦，你都能在下一集（或几秒后）完好无损地回来。你喊出‘我一定会回来的’时触发。", type: "exclusive"},
        {name: "机械羊化", color: "S", cost: 2500, desc: "你将自己改造成机械羊。拥有红外视觉、火箭推进器和强大的计算能力，失去了痛觉，但也失去了部分情感。", type: "exclusive"},
        {name: "红太狼的平底锅", color: "SS", cost: 8000, desc: "因果律武器。无视防御，必定命中，且造成巨大的物理伤害和眩晕效果。连灰太狼这种不死之身都怕。", type: "exclusive"},
        {name: "懒羊羊的运气", color: "S", cost: 2600, desc: "傻羊有傻福。你总能误打误撞地躲过陷阱，或者在睡觉时捡到宝物。你的睡梦罗汉拳也是一绝。", type: "exclusive"},
        {name: "沸羊羊的力量", color: "A", cost: 1200, desc: "草原健身达人。你拥有强壮的体魄和怪力，擅长拳击和摔跤，是近战肉搏的好手。", type: "exclusive"},
        {name: "美羊羊的魅力", color: "B", cost: 500, desc: "你的外表可爱，容易让敌人（尤其是雄性）放松警惕，不忍心攻击你。擅长烹饪和装饰。", type: "exclusive"},
        {name: "慢羊羊的发明(不稳定)", color: "A", cost: 1500, desc: "你可以发明各种道具，但往往伴随着副作用（如爆炸、变小、长出蜗牛壳）。智商虽高，但行动迟缓。", type: "exclusive"},
        {name: "暖羊羊的盘羊血统", color: "A", cost: 1000, desc: "你拥有盘羊的怪力，且性格温和。如果你预言了什么坏事，通常都会灵验（乌鸦嘴属性）。", type: "exclusive"},
        {name: "潇洒哥的画个圈圈", color: "B", cost: 400, desc: "虽然你是个蛋，但你可以诅咒敌人。虽然大部分时候没用，但你的不死光环和合体能力很强。", type: "exclusive"},
        {name: "黑大帅的闪电", color: "S", cost: 2200, desc: "皮蛋的力量。你可以释放黑色的闪电，控制他人，或者进行瞬间移动。性格傲娇。", type: "exclusive"},
        {name: "狼将军的芯片", color: "SS", cost: 7500, desc: "植入体内的强化芯片。可以大幅提升各项身体机能，并赋予你使用雷、火、冰等元素力量的能力。", type: "exclusive"},
        {name: "奇力(异国大营救)", color: "S", cost: 2800, desc: "你觉醒了奇力。可能是风、雷、冰、火、重力等。这是在这个魔法篇章中战斗的核心力量。", type: "exclusive"},
        {name: "篮球巨星(筐出胜利)", color: "A", cost: 1800, desc: "你拥有NBA级别的篮球技术。你的‘超负荷’技能能让你在球场上快如闪电，投出必进的超远三分。", type: "exclusive"},
        {name: "小灰灰的卖萌", color: "C", cost: 300, desc: "你的萌度爆表，能瞬间融化敌人的心，让最凶残的狼也变成奶爸。是和平交涉的神技。", type: "exclusive"},
        {name: "食人鱼军团", color: "B", cost: 600, desc: "你可以召唤河里的食人鱼攻击落水的敌人。在这个世界，掉进河里通常比在岸上更危险。", type: "exclusive"},
        {name: "泰哥的肌肉", color: "C", cost: 250, desc: "你像泰哥一样强壮，喜欢展示肌肉。虽然有点自恋，但战斗力不容小觑，且会老虎吼。", type: "exclusive"},
        {name: "包包大人的裁决", color: "A", cost: 1100, desc: "你是草原的执法者。你可以将犯规的人流放到空中监狱。你的额头月亮在愤怒时会变黑，战力飙升。", type: "exclusive"},
        {name: "古古怪界变身", color: "B", cost: 550, desc: "你可以变身为古古怪界的生物，获得特殊能力，如蜜蜂的刺、兔子的跳跃等。", type: "exclusive"},
        {name: "嘻哈火车的驾驶", color: "C", cost: 150, desc: "你会驾驶嘻哈火车。这辆火车能变形、飞行，是穿越不同区域的重要载具。", type: "exclusive"},
        {name: "跨种族友谊", color: "S", cost: 2000, desc: "你坚信羊狼和平。这让你能同时获得羊村和狼堡的支援，触发‘羊狼合作，天下无敌’的羁绊效果。", type: "exclusive"},
        {name: "蕉太狼的香蕉", color: "D", cost: 80, desc: "你只吃香蕉。这让你免受羊肉的诱惑，能和羊群和平共处。你的力气很大，但性格憨厚。", type: "exclusive"},
        {name: "七大恶狼召唤", color: "A", cost: 1600, desc: "作为狼族统帅，你可以召唤七大恶狼（如夜太狼、白眼狼等）助战。虽然他们经常帮倒忙。", type: "exclusive"},
        {name: "超级芯片(剔博士)", color: "SS", cost: 8200, desc: "能够象形化的超级芯片。你可以将任何物体变成武器或工具，拥有改写现实的恐怖能力。", type: "exclusive"},
        {name: "守护者装备", color: "S", cost: 2400, desc: "羊村守护者的专属装备。如喜羊羊的风之剑、美羊羊的弓箭等，拥有元素加成。", type: "exclusive"},
        {name: "青青草原疾跑", color: "C", cost: 120, desc: "你在草原地形上的移动速度提升50%。毕竟每天都要跑路（或追羊）。", type: "exclusive"},
        {name: "替身草人", color: "B", cost: 350, desc: "当你受到致命伤害时，自动替换为一个草人，本体瞬移到安全位置。冷却时间较长。", type: "exclusive"},
        {name: "实验室爆炸抗性", color: "C", cost: 200, desc: "由于经常经历实验室爆炸，你对火与冲击波有很高的抗性，脸黑了洗洗就好。", type: "exclusive"},
        {name: "智羊羊的遗产", color: "SS", cost: 7000, desc: "喜羊羊父亲留下的高科技装备和资料。包含外太空科技，能让你瞬间成为顶尖科学家。", type: "exclusive"}
    ]
},
{
    name: "470.蛊真人 (Reverend Insanity)",
    desc: "养蛊、炼蛊、用蛊。这是一个残酷的修仙世界，没有道德，只有利益。人是万物之灵，蛊是天地之精。在这个世界，为了永生，你可以牺牲一切。",
    boss: "天庭(龙公, 紫薇仙子), 影宗(魔尊幽魂), 巨阳仙尊, 乐土亚仙尊",
    identities: [
        { name: "古月山寨的凡人奴仆", items: "一身粗布麻衣, 一块干硬的馒头" },
        { name: "被家族流放的旁系少年", items: "一只一转酒虫, 几块元石" },
        { name: "魔道散修的弟子", items: "一本残缺的血道秘籍, 一把人骨炼制的匕首" },
        { name: "商队里的护卫", items: "一只二转铁皮蛊, 一把精钢刀" },
        { name: "中洲门派的外门弟子", items: "一块门派令牌, 一只一转纸鹤蛊" }
    ],
    talents: [
        {name: "春秋蝉(重生)", color: "SSS", cost: 50000, desc: "红莲魔尊的本命蛊，宙道奇蛊。当你死亡时，它能带着你的意志逆流光阴长河，回到过去。这是逆天改命、知晓未来的终极外挂，但有失败风险。", type: "exclusive"},
        {name: "九转尊者资质", color: "SSS", cost: 45000, desc: "你拥有成就九转蛊尊的潜力。你的才情、毅力和气运都是当世顶尖，注定要无敌于天下，打破宿命。", type: "exclusive"},
        {name: "至尊仙胎蛊", color: "SSS", cost: 48000, desc: "人祖传说中的蛊虫。一旦使用，你将获得至尊仙体，道痕互不排斥，可以兼修所有流派，且恢复力惊人，是魔尊幽魂的毕生杰作。", type: "exclusive"},
        {name: "智慧蛊", color: "SS", cost: 9500, desc: "九转智道蛊虫。它能散发出智慧光晕，沐浴其中能让你思维无限加速，推演蛊方、杀招如喝水般简单，但需要消耗寿命。", type: "exclusive"},
        {name: "十绝体(随机)", color: "SS", cost: 8000, desc: "你拥有十绝体之一（如北冥冰魄体、太日阳莽体）。修炼速度极快，战力远超同阶，但若无相应蛊虫压制，会因窍壁破碎而自爆。", type: "exclusive"},
        {name: "血道宗师", color: "S", cost: 2800, desc: "你对血道有极深的领悟。血道速成且战力强，擅长以战养战，恢复力极强。但你是全天下的公敌，会被正道追杀。", type: "exclusive"},
        {name: "炼道准无上大宗师", color: "SS", cost: 9000, desc: "你在炼蛊一道上达到了登峰造极的境界。天地万物皆可炼，你可以轻松炼制出仙蛊，甚至将人炼成蛊。", type: "exclusive"},
        {name: "力道流派(上古)", color: "A", cost: 1500, desc: "你走的是上古力道流派。不修真元，只修肉身。一力降十会，拥有搬山填海的恐怖怪力。", type: "exclusive"},
        {name: "智道算计", color: "S", cost: 2500, desc: "你心思深沉，擅长推演布局。在战斗前你已经算计好了对手的每一步，能以弱胜强，玩弄世人于股掌之间。", type: "exclusive"},
        {name: "梦道先驱", color: "SS", cost: 7500, desc: "你掌握了新时代的流派——梦道。你可以进入梦境探索，提升境界，或者将敌人拉入梦境杀死。在梦道未昌盛前，你几乎无敌。", type: "exclusive"},
        {name: "甲等空窍", color: "A", cost: 1200, desc: "你拥有九成九的真元海。修炼速度极快，真元恢复力强，是成为强者的基础资本。", type: "exclusive"},
        {name: "酒虫(一转)", color: "C", cost: 200, desc: "珍稀蛊虫。能提纯真元，让你拥有一转巅峰的真元质量，在前期对拼中占据绝对优势。", type: "exclusive"},
        {name: "定仙游", color: "SS", cost: 8500, desc: "六转宇道仙蛊。只要是你去过或者看到过景象的地方，无论多远，心念一动即可瞬间到达。逃跑、偷袭神技。", type: "exclusive"},
        {name: "人如草芥", color: "D", cost: 50, desc: "你的心冷如铁。杀人对你来说就像割草一样，不会有任何心理负担。这能让你在魔道之路上走得更远。", type: "exclusive"},
        {name: "吃苦耐劳", color: "C", cost: 100, desc: "你拥有极强的忍耐力。无论是被火烧、被虫咬还是精神折磨，你都能面不改色，坚持到反击的那一刻。", type: "exclusive"},
        {name: "天庭卧底", color: "A", cost: 1800, desc: "你是中洲天庭埋下的棋子。虽然危险，但你可以获得天庭的资源支持，甚至借用宿命蛊的力量。", type: "exclusive"},
        {name: "运道(鸿运齐天)", color: "SS", cost: 8800, desc: "巨阳仙尊的真传。你的运气好到逆天，走路捡仙蛊，敌人会莫名其妙倒霉。但要注意物极必反。", type: "exclusive"},
        {name: "变化道(千变万化)", color: "S", cost: 2200, desc: "你可以变化成各种荒兽、上古荒兽甚至太古荒兽，拥有它们的身体素质和天赋神通。", type: "exclusive"},
        {name: "剑道(波光剑影)", color: "A", cost: 1600, desc: "你的攻击犀利无比，剑气纵横。擅长远程攻击和单点爆发，是攻伐第一的流派之一。", type: "exclusive"},
        {name: "蛊阵师", color: "A", cost: 1400, desc: "你擅长布置蛊阵。只要给你时间准备，你可以用低级蛊虫困杀高级蛊师，甚至建立坚不可摧的基地。", type: "exclusive"},
        {name: "态度蛊", color: "S", cost: 2600, desc: "传说中的蛊虫。你可以完美伪装自己的情感和念头，连八转蛊仙都无法看穿你的真心。是影帝的必备修养。", type: "exclusive"},
        {name: "方源的狠辣", color: "A", cost: 2000, desc: "你继承了方源的性格。为了利益，你可以没有任何底线。这种绝对的理智让你在残酷的修仙界生存率大增。", type: "exclusive"},
        {name: "净魂仙蛊", color: "S", cost: 2400, desc: "魂道仙蛊。可以净化魂魄，提升底蕴，也能克制魂道杀招，防止被夺舍或搜魂。", type: "exclusive"},
        {name: "逆流河护身", color: "SS", cost: 9200, desc: "天地秘境逆流河。任何攻击落入其中都会被逆流反射回去。只要你立于河上，就立于不败之地。", type: "exclusive"},
        {name: "太丘传承", color: "B", cost: 600, desc: "你获得了太丘荒兽的认可，能够指挥兽群，或者在危险的太丘地形中如鱼得水。", type: "exclusive"},
        {name: "白骨战车", color: "B", cost: 500, desc: "骨道杀招凝聚的战车，防御力强，移动速度快，且自带撞角，碾压低级蛊师。", type: "exclusive"},
        {name: "星门蛊", color: "C", cost: 300, desc: "可以在夜晚借助星光开启传送门，连接两个遥远的地点。是长途跋涉和运兵的利器。", type: "exclusive"},
        {name: "无脚鸟", color: "E", cost: 20, desc: "一种只能飞翔不能落地的鸟。象征着你在这个世界的命运，必须不断奔跑，停下就是死亡。", type: "exclusive"},
        {name: "春秋蝉的副作用", color: "E", cost: 10, desc: "虽然能重生，但你的运气会变得极差。重生后往往面临更大的危机，需要极高的智慧化解。", type: "exclusive"},
        {name: "坚持", color: "SSS", cost: 10000, desc: "一种精神境界。哪怕失败一万次，哪怕举世皆敌，哪怕身死道消，你也绝不放弃心中的目标。这是魔尊的潜质。", type: "exclusive"}
    ]
},
              {
        name: "471.步步惊心",
        desc: "清朝康熙年间，九龙夺嫡的漩涡中心。看似平静的紫禁城，每一步都踏在刀尖上。宿命般的爱情与皇权的残酷碾压，现代思想与封建礼教的剧烈碰撞。",
        boss: "康熙, 雍正(四阿哥), 八阿哥",
        identities: [
            { name: "辛者库的浣衣局宫女", items: "一盆洗不完的衣服, 满手的冻疮" },
            { name: "八贝勒府的粗使丫鬟", items: "一把扫帚, 一个被克扣的月钱袋子" },
            { name: "京城落魄旗人的败家子", items: "一只秃毛的斗鸡, 一张欠满赌债的借条" },
            { name: "随军出征的马夫", items: "一把刷马的鬃毛刷, 一袋发霉的干粮" },
            { name: "御膳房的帮厨太监", items: "一把切菜刀, 半块偷藏的糕点" }
        ],
        talents: [
            {name: "现代记忆(残)", color: "S", cost: 2500, desc: "你拥有关于未来的模糊记忆，知道九龙夺嫡的大致走向，这是你在宫廷斗争中活命的最大筹码。", type: "exclusive"},
            {name: "满语精通", color: "B", cost: 300, desc: "你精通满语，能听懂主子们的私密谈话，也能在关键时刻用母语博取皇帝的好感。", type: "exclusive"},
            {name: "步步为营", color: "A", cost: 800, desc: "在宫廷中，你的警觉性极高。每当有人算计你时，你都会产生莫名的心悸。", type: "exclusive"},
            {name: "茶艺大师", color: "C", cost: 180, desc: "你泡茶的手艺一绝，能通过茶水的温度和口感揣摩主子的心情。", type: "exclusive"},
            {name: "冰雪肌肤", color: "A", cost: 600, desc: "你的皮肤即使在寒冬也如凝脂般白皙，极易获得异性的怜惜，但也容易招致同性的嫉妒。", type: "exclusive"},
            {name: "木兰围猎骑术", color: "B", cost: 450, desc: "你拥有精湛的骑术，能在木兰秋狝中大展身手，获得贵人的青睐。", type: "exclusive"},
            {name: "帝王心术(伪)", color: "SS", cost: 5000, desc: "你天生对权力的流动极其敏感，能看穿圣旨背后的深意，仿佛拥有帝王的视角。", type: "exclusive"},
            {name: "四爷党的庇护", color: "S", cost: 3000, desc: "你无意中帮过四阿哥，他把你视为可造之材，暗中派粘杆处的人保护你。", type: "exclusive"},
            {name: "八爷党的眼线", color: "D", cost: 50, desc: "你是八爷安插在暗处的棋子，虽然能获得情报，但随时可能被当作弃子牺牲。", type: "exclusive"},
            {name: "穿越者的香水", color: "C", cost: 200, desc: "你懂得提取花露制作简易香水，这种新奇的玩意儿能让你在后宫中小赚一笔。", type: "exclusive"},
            {name: "因果律：情劫", color: "E", cost: 10, desc: "诅咒。你注定会爱上一个不能爱的人，并为此肝肠寸断，不死不休。", type: "exclusive"},
            {name: "太医院关系户", color: "B", cost: 350, desc: "你有个远房亲戚在太医院当差，生病时能弄到些好药，不用硬扛。", type: "exclusive"},
            {name: "若曦的日记残页", color: "A", cost: 1000, desc: "你捡到了马尔泰·若曦的手稿，上面记载了各位阿哥的喜好和忌讳。", type: "exclusive"},
            {name: "九五之尊的凝视", color: "SSS", cost: 15000, desc: "康熙皇帝在人群中多看了你一眼。这可能是飞黄腾达的开始，也可能是抄家灭族的信号。", type: "exclusive"},
            {name: "守宫砂", color: "C", cost: 100, desc: "证明清白的标记。在某些选秀环节是必须品，但在混乱的宫廷中也是一种束缚。", type: "exclusive"}
        ]
    },
    {
        name: "472.东宫",
        desc: "忘川之水，在于忘情。西凉的红衣少女与中原的顾小五。一场始于利用的政治联姻，终结于国破家亡的血色浪漫。这里没有赢家，只有无尽的悔恨。",
        boss: "李承鄞(顾小五), 豊朝皇帝, 高相",
        identities: [
            { name: "西凉边境的卖茶女", items: "一壶凉茶, 几个干硬的馕" },
            { name: "豊朝潜伏的死士", items: "一把淬毒的匕首, 一颗藏在牙后的毒丸" },
            { name: "丹蚩部落的牧羊人", items: "一根赶羊鞭, 一把锋利的剥皮刀" },
            { name: "上京城的落第书生", items: "几卷读烂的圣贤书, 一身洗得发白的儒衫" },
            { name: "冷宫的洒扫太监", items: "一把长柄扫帚, 一身灰扑扑的太监服" }
        ],
        talents: [
            {name: "忘川之水(免疫)", color: "SS", cost: 6000, desc: "你跳下忘川却依然记得一切。这份痛苦的记忆是你复仇的动力，也是你最大的折磨。", type: "exclusive"},
            {name: "西凉骑射", color: "B", cost: 400, desc: "你在马背上长大，骑射功夫了得，能在高速奔跑的马背上射中飞鸟。", type: "exclusive"},
            {name: "李承鄞的演技", color: "S", cost: 3500, desc: "你拥有影帝级别的伪装能力，能笑着捅人一刀，谈笑间灭人全族。", type: "exclusive"},
            {name: "丹蚩勇士体魄", color: "A", cost: 900, desc: "你拥有丹蚩人强悍的体魄，耐寒耐劳，力大无穷，是天生的战士。", type: "exclusive"},
            {name: "红衣似火", color: "C", cost: 200, desc: "你穿红衣时魅力大幅提升，容易让人联想到那位西凉的九公主。", type: "exclusive"},
            {name: "政治联姻筹码", color: "D", cost: 80, desc: "你的身份尊贵但身不由己，注定要为了两国的利益而被牺牲。", type: "exclusive"},
            {name: "鸣镝", color: "B", cost: 300, desc: "一支特制的响箭，射出后能召集周围的族人或旧部。", type: "exclusive"},
            {name: "瑟瑟的玉佩", color: "A", cost: 1200, desc: "赵瑟瑟的贴身之物，持有它可能会卷入后宫的争宠漩涡，但也可能获得高家的支持。", type: "exclusive"},
            {name: "狼牙项链", color: "C", cost: 150, desc: "象征勇气的项链，能小幅度提升你的统率力，让草原上的汉子高看你一眼。", type: "exclusive"},
            {name: "绝情蛊", color: "S", cost: 2800, desc: "种下此蛊，断绝情爱。你的心将坚如磐石，不再受情感波动影响，修炼速度倍增。", type: "exclusive"},
            {name: "灭族之恨", color: "E", cost: 5, desc: "诅咒。你背负着血海深仇，每天夜里都会梦到族人惨死的景象，精神值持续下降。", type: "exclusive"},
            {name: "太子妃的猫", color: "C", cost: 120, desc: "你拥有一只极通人性的猫，它能帮你探听消息，或者在关键时刻抓伤敌人。", type: "exclusive"},
            {name: "顾剑的剑术", color: "SS", cost: 5500, desc: "你继承了顾剑的绝世剑法，单人独剑可挡千军，但每用一次都会消耗生命力。", type: "exclusive"},
            {name: "萤火虫的祝福", color: "A", cost: 700, desc: "在夜晚，你身边会有萤火虫环绕，能照亮黑暗，也能安抚狂暴的野兽。", type: "exclusive"},
            {name: "悲剧轮回", color: "SSS", cost: 12000, desc: "你意识到这个世界的本质是悲剧。你获得了打破第四面墙的能力，试图改写必死的结局。", type: "exclusive"}
        ]
    },
    {
        name: "473.微微一笑很倾城",
        desc: "键盘敲击出的浪漫。现实中的学霸校花与大神校草，游戏里的芦苇微微与一笑奈何。虚拟与现实交错，网游操作与代码技术是这个世界的硬通货。",
        boss: "真水无香, 曹光, 孟逸然",
        identities: [
            { name: "网吧通宵的颓废少年", items: "一桶泡面, 一张余额不足的网费卡" },
            { name: "庆大食堂的打饭阿姨", items: "一把抖动的大勺, 一顶白色的卫生帽" },
            { name: "游戏里的职业代练", items: "一台高配置电脑, 一双布满老茧的手" },
            { name: "计算机系的挂科生", items: "一本从未翻过的C++教材, 一张补考通知单" },
            { name: "真亿科技的实习生", items: "一叠厚厚的文件, 一个总是被骂的工位" }
        ],
        talents: [
            {name: "APM 300+", color: "A", cost: 800, desc: "你的手速极快，在游戏中能打出眼花缭乱的操作，在现实中敲代码也快人一步。", type: "exclusive"},
            {name: "大神光环", color: "S", cost: 2500, desc: "你无论走到哪里都自带气场，容易获得他人的崇拜，在游戏中组队会有无数人跪求带飞。", type: "exclusive"},
            {name: "顶级黑客技术", color: "SS", cost: 6000, desc: "你精通网络攻防，能轻易入侵服务器，修改游戏数据，甚至查出对方的现实IP。", type: "exclusive"},
            {name: "校花/校草颜值", color: "A", cost: 1000, desc: "你的颜值达到了系花/系草级别，走在校园里回头率爆表，容易触发桃花运。", type: "exclusive"},
            {name: "人民币玩家", color: "B", cost: 500, desc: "你家里有矿，在游戏中可以肆意氪金，用顶级装备碾压技术流玩家。", type: "exclusive"},
            {name: "欧皇附体", color: "S", cost: 3000, desc: "你打怪掉落稀有装备的概率是常人的十倍，强化装备从未失败过。", type: "exclusive"},
            {name: "八卦体质", color: "C", cost: 150, desc: "你总是能第一时间知道论坛上的最新八卦，掌握舆论导向。", type: "exclusive"},
            {name: "视频剪辑大师", color: "B", cost: 350, desc: "你擅长制作游戏视频，能把普通的战斗剪辑成大片，通过视频赚取流量和名声。", type: "exclusive"},
            {name: "侠侣情缘", color: "A", cost: 700, desc: "你容易在游戏中遇到高质量的异性伴侣，触发隐藏的侠侣任务。", type: "exclusive"},
            {name: "键盘侠", color: "D", cost: 50, desc: "你擅长在网上喷人，虽然能造成精神伤害，但容易被管理员禁言或被顺着网线打。", type: "exclusive"},
            {name: "致一科技Offer", color: "S", cost: 2200, desc: "你拥有肖奈公司的入职邀请，这意味着你将进入核心剧情圈，接触到大神团队。", type: "exclusive"},
            {name: "幽闭恐惧症", color: "E", cost: 20, desc: "负面天赋。你在电梯或狭小空间会无法呼吸，可能导致关键时刻掉链子。", type: "exclusive"},
            {name: "游戏开发天赋", color: "A", cost: 900, desc: "你对游戏架构有独特的理解，能设计出令人惊叹的玩法，受到游戏公司的青睐。", type: "exclusive"},
            {name: "小雨家族的仇恨", color: "D", cost: 100, desc: "你被游戏里的反派家族盯上了，出野外随时可能被强行PK。", type: "exclusive"},
            {name: "跨服第一", color: "SSS", cost: 10000, desc: "你是全服公认的战力天花板，你的ID就是一个传说，能号令全服玩家。", type: "exclusive"}
        ]
    },
    {
        name: "474.知否",
        desc: "北宋官宦家庭的少女成长史。没有宫斗的血腥，却有宅斗的阴狠。嫡庶之分、家族利益、婆媳关系，在琐碎的日常中暗藏杀机。活下去，并且活得体面。",
        boss: "小秦氏, 康姨妈, 曼娘",
        identities: [
            { name: "盛府的粗使丫鬟", items: "一把扫帚, 一身打补丁的衣服" },
            { name: "顾家庄子上的佃户", items: "一把锄头, 一袋刚收的谷子" },
            { name: "汴京街头的卖货郎", items: "一个货郎担, 几样不值钱的小玩意" },
            { name: "扬州瘦马", items: "一把琵琶, 一张卖身契" },
            { name: "私塾里的穷酸书生", items: "一支秃笔, 几张草纸" }
        ],
        talents: [
