            {name: "兽血沸腾", color: "B", cost: 800, desc: "短时间内让灵兽进入狂暴状态，全属性提升，但事后会虚弱。", type: "exclusive"},
            {name: "灵兽治疗术", color: "A", cost: 1200, desc: "掌握特殊的治疗法术，能快速治愈灵兽的伤势。", type: "exclusive"},
            {name: "古代语精通", color: "B", cost: 600, desc: "能读懂古代遗迹中的文字，获取失传的进化配方。", type: "exclusive"},
            {name: "采集大师", color: "C", cost: 200, desc: "在野外能识别并采集各种灵草、灵果，不被毒死。", type: "exclusive"},
            {name: "隐匿气息", color: "B", cost: 500, desc: "能完美隐藏自己和灵兽的气息，适合偷袭或逃跑。", type: "exclusive"},
            {name: "坚韧体魄", color: "A", cost: 1000, desc: "御兽师自身的肉体也极其强悍，能抗住灵兽的余波。", type: "exclusive"},
            {name: "合体天赋", color: "SS", cost: 7500, desc: "能与灵兽合体，变身为半人半兽的战斗形态，获得灵兽的能力。", type: "exclusive"},
            {name: "反哺强化", color: "A", cost: 2000, desc: "灵兽升级时，御兽师获得的属性反馈加倍。", type: "exclusive"},
            {name: "威慑光环", color: "B", cost: 700, desc: "释放精神威压，让低阶灵兽感到恐惧而逃跑。", type: "exclusive"},
            {name: "灵兽厨神", color: "C", cost: 300, desc: "能做出灵兽爱吃的食物，提升好感度和成长值。", type: "exclusive"},
            {name: "空间跳跃", color: "S", cost: 3500, desc: "利用空间系灵兽的力量，进行短距离瞬移。", type: "exclusive"},
            {name: "吞噬进化", color: "S", cost: 4000, desc: "你的灵兽可以通过吞噬其他灵兽的晶核来获取技能或属性。", type: "exclusive"},
            {name: "机械改造", color: "A", cost: 2500, desc: "将科技与御兽结合，给灵兽安装机械装甲或武器。", type: "exclusive"},
            {name: "亡灵复苏", color: "S", cost: 4200, desc: "能将死去的灵兽复活为亡灵生物，继续为你战斗。", type: "exclusive"},
            {name: "龙族血脉(人)", color: "SS", cost: 8500, desc: "你拥有龙族血统，对龙系灵兽有绝对的压制力和吸引力。", type: "exclusive"},
            {name: "幸运E(诅咒)", color: "E", cost: -500, desc: "虽然实力强，但总是遇到倒霉事，比如走路踩到神兽尾巴。", type: "exclusive"},
            {name: "多才多艺", color: "C", cost: 100, desc: "除了御兽，你还擅长琴棋书画，能陶冶情操。", type: "exclusive"},
            {name: "耐毒体质", color: "B", cost: 600, desc: "长期接触毒系灵兽，获得了抗毒性。", type: "exclusive"},
            {name: "深渊凝视者", color: "S", cost: 4800, desc: "你能与深渊魔兽沟通，甚至契约它们，但容易被侵蚀。", type: "exclusive"},
            {name: "神兽蛋感应", color: "SS", cost: 7000, desc: "能感应到附近的神兽蛋或幼崽。", type: "exclusive"},
            {name: "时间回溯(微)", color: "SSS", cost: 30000, desc: "在灵兽死亡瞬间，让其状态回溯到5秒前，逆转生死。", type: "exclusive"},
            {name: "全属性亲和", color: "S", cost: 5500, desc: "契约任何属性的灵兽都不会产生排斥反应。", type: "exclusive"},
            {name: "兽语者", color: "A", cost: 1600, desc: "能听懂所有灵兽的语言，了解它们的需求和八卦。", type: "exclusive"}
        ]
    },
    {
        name: "490.山海经世界",
        desc: "上古洪荒，神魔并存。这里有《山海经》中记载的异兽、神人、仙山。修仙者逆天而行，大巫肉身成圣。这是一个弱肉强食、恢弘壮阔的神话世界。",
        boss: "烛龙, 蚩尤, 帝俊, 西王母",
