            {name: "法天象地", color: "SS", cost: 9000, desc: "大神通。身躯可变大至万丈，力量随体型倍增，如山岳般碾压敌人。", type: "exclusive"},
            {name: "三头六臂", color: "S", cost: 5000, desc: "战斗形态。生出三头六臂，可同时使用多种兵器和法术，无死角防御。", type: "exclusive"},
            {name: "九息服气", color: "S", cost: 4500, desc: "呼吸之间即可恢复法力和伤势，持久战无敌。", type: "exclusive"},
            {name: "腾云驾雾", color: "A", cost: 2000, desc: "朝游北海暮苍梧，飞行速度极快，且自带仙气特效。", type: "exclusive"},
            {name: "五行大遁", color: "SS", cost: 8000, desc: "精通金木水火土五行遁术，可融入万物，瞬息万里，难以被困。", type: "exclusive"},
            {name: "天眼通", color: "S", cost: 4000, desc: "眉心生天眼，可看破虚妄、阵法、妖魔原形，甚至窥探天机。", type: "exclusive"},
            {name: "饕餮之胃", color: "SS", cost: 7500, desc: "吞噬万物转化为自身能量。吃得越多，实力越强，但永远处于饥饿状态。", type: "exclusive"},
            {name: "九尾妖狐(魅惑)", color: "S", cost: 4800, desc: "青丘皇族血统。天生媚骨，能魅惑众生，且每断一尾可抵一命。", type: "exclusive"},
            {name: "刑天战意", color: "SS", cost: 8500, desc: "头断而不死，以乳为目，以脐为口，战意永不熄灭，越战越勇。", type: "exclusive"},
            {name: "夸父逐日(步法)", color: "A", cost: 2500, desc: "拥有极快的奔跑速度和耐力，所过之处大地干裂。", type: "exclusive"},
            {name: "后羿射术", color: "S", cost: 5500, desc: "箭术通神，例无虚发。可射落星辰，专破金身法相。", type: "exclusive"},
            {name: "精卫填海(执念)", color: "B", cost: 1000, desc: "拥有坚不可摧的意志力，面对不可能的任务也能坚持到底。", type: "exclusive"},
            {name: "神农百草体", color: "S", cost: 6000, desc: "尝百草而不死，百毒不侵，血液可解万毒。", type: "exclusive"},
            {name: "呼风唤雨", color: "A", cost: 3000, desc: "操控天象，降下暴雨雷电，改变战场环境。", type: "exclusive"},
            {name: "撒豆成兵", color: "B", cost: 1500, desc: "撒出豆子化为黄巾力士，虽然单体不强，但胜在数量多。", type: "exclusive"},
            {name: "炼丹术", color: "A", cost: 2200, desc: "能炼制各种仙丹妙药，提升修为或延年益寿。", type: "exclusive"},
            {name: "炼器术", color: "A", cost: 2200, desc: "能锻造法宝神兵，赋予器物灵性。", type: "exclusive"},
            {name: "御剑术", color: "B", cost: 1200, desc: "千里之外取敌首级，剑修基础。", type: "exclusive"},
            {name: "龟息功", color: "C", cost: 300, desc: "模仿神龟呼吸，能假死闭气，延缓衰老。", type: "exclusive"},
            {name: "相柳毒气", color: "A", cost: 2800, desc: "呼出的气息带有剧毒，所过之处寸草不生。", type: "exclusive"},
            {name: "凤凰涅槃", color: "SSS", cost: 30000, desc: "死亡后浴火重生，实力更上一层楼。冷却时间极长。", type: "exclusive"},
            {name: "麒麟祥瑞", color: "SS", cost: 7000, desc: "身为瑞兽，所到之处风调雨顺，自身运气极佳，逢凶化吉。", type: "exclusive"},
            {name: "鲲鹏展翅", color: "S", cost: 5200, desc: "入海为鲲，上天为鹏。拥有双重形态，速度与力量并存。", type: "exclusive"},
            {name: "息壤", color: "S", cost: 4500, desc: "拥有生生不息的土壤，可用于防御或困敌。", type: "exclusive"},
            {name: "通灵术", color: "B", cost: 800, desc: "能与鬼神沟通，请神上身。", type: "exclusive"},
            {name: "祝由术", color: "C", cost: 400, desc: "上古巫医之术，用符咒治病驱邪。", type: "exclusive"},
            {name: "山神敕令", color: "A", cost: 1800, desc: "号令山川土地，改变地形。", type: "exclusive"},
            {name: "水神共工之力", color: "S", cost: 4600, desc: "操控天下万水，怒触不周山之力。", type: "exclusive"},
            {name: "长生不老药(伪)", color: "B", cost: 2000, desc: "虽不能真长生，但能大幅延长寿命，驻颜有术。", type: "exclusive"}
        ]
