              {
        name: "491.终末的女武神",
        desc: "人神最终斗争。众神决定终结人类的历史，但女武神布伦希尔德提出了“仙境传说”——由13位神明对战13位人类最强战士。这是赌上种族存亡的单挑。",
        boss: "宙斯(众神之父), 奥丁(北欧主神), 湿婆(破坏神), 别西卜",
        identities: [
            { name: "英灵殿的扫地僧", items: "一把断裂的神器碎片, 记录战况的卷轴" },
            { name: "女武神的见习侍从", items: "神界地图, 修复灵魂的药水" },
            { name: "人类看台的观众", items: "写着''人类必胜''的横幅, 望远镜" },
            { name: "被遗忘的半神", items: "稀薄的神血, 一把生锈的长矛" },
            { name: "神界的处刑人", items: "染血的斧头, 处刑名单" }
        ],
        talents: [
            {name: "神虚视(亚当)", color: "SSS", cost: 30000, desc: "能完美复制并反击所看到的任何神技，甚至能超越原版。但这会对神经系统造成极大负担，过度使用会导致失明甚至死亡。", type: "exclusive"},
            {name: "二天一流(佐佐木)", color: "SS", cost: 9000, desc: "究极的意念演练。在战斗开始前，要在脑海中模拟千百次对决，直到找到必胜的那个瞬间，号称“最强输家”的逆袭。", type: "exclusive"},
            {name: "神器炼成(Volund)", color: "SS", cost: 8500, desc: "与女武神进行灵魂同调，将女武神化作最适合你的神器。此神器能伤到神明，但若神器破碎，女武神也会随之消亡。", type: "exclusive"},
            {name: "阿陀磨须(宙斯)", color: "SSS", cost: 25000, desc: "将全身肌肉压缩到极致的最终形态，防御力和破坏力达到神界的顶点，每一拳都是必杀，每一秒都在燃烧生命。", type: "exclusive"},
            {name: "天喰(吕布)", color: "S", cost: 5000, desc: "中华最强武将的绝技。握住武器末端，利用离心力释放出能撕裂大气、吞噬苍穹的恐怖一击。", type: "exclusive"},
            {name: "百闭(开膛手杰克)", color: "S", cost: 4500, desc: "能看到万物色彩（情感）的眼睛。通过观察对手情感颜色的变化，预判其行动，并利用恶意染黑对手。", type: "exclusive"},
            {name: "肌肉控制(雷电)", color: "A", cost: 2000, desc: "能够自由控制体内暴走的肌肉，将其凝聚在身体的一点进行爆发性攻击，甚至能捏碎神器的防御。", type: "exclusive"},
            {name: "未来视(释迦)", color: "SSS", cost: 28000, desc: "天上天下唯我独尊。通过灵魂的波动，能确切地看到未来几秒钟即将发生的事情，从而轻松躲避任何攻击。", type: "exclusive"},
            {name: "海神之怒(波塞冬)", color: "SS", cost: 8000, desc: "神之尊严的体现。以极快的速度挥舞三叉戟，形成如同暴雨般的残影攻击，封锁敌人所有退路。", type: "exclusive"},
            {name: "塔安达瓦之舞(湿婆)", color: "SS", cost: 8200, desc: "毁灭世界的舞蹈。随着节奏加快，体温不断升高，最终进入燃烧状态，攻击附带无法扑灭的业火。", type: "exclusive"},
            {name: "苍蝇王(别西卜)", color: "S", cost: 6000, desc: "操控振动。能通过高频振动切开防御，或通过低频振动制造护盾，甚至能引发体内器官的共振破坏。", type: "exclusive"},
            {name: "地狱之门看守者", color: "A", cost: 1500, desc: "哈迪斯的眷属，拥有在冥界自由行走的能力，对死亡气息极度敏感。", type: "exclusive"},
            {name: "斯巴达之魂", color: "B", cost: 800, desc: "列奥尼达一世的意志。背部受伤是耻辱，正面迎敌时防御力大幅提升，永不后退。", type: "exclusive"},
            {name: "科学狂人(特斯拉)", color: "S", cost: 4000, desc: "相信科学能战胜神明。能利用神力驱动超级装甲，进行瞬移和释放高压电浆球。", type: "exclusive"},
            {name: "始皇帝的威压", color: "SS", cost: 7500, desc: "好大！好强！作为人皇，你的气场能压制神明，甚至能通过吹气扰乱对手的“气”之流动。", type: "exclusive"},
            {name: "蚩尤铠式", color: "A", cost: 2200, desc: "始皇帝创造的武术，集攻防一体，擅长反弹敌人的力量。", type: "exclusive"},
            {name: "燕返(魔改)", color: "A", cost: 1800, desc: "佐佐木小次郎的剑术，能在一瞬间斩出三刀，封锁空间。", type: "exclusive"},
            {name: "大力神纹身", color: "S", cost: 3500, desc: "赫拉克勒斯的力量。纹身蔓延全身时，获得十二试炼的神力，但会伴随巨大的痛苦。", type: "exclusive"},
            {name: "零福的斧头", color: "A", cost: 3000, desc: "武器会随着使用者的不幸和怨恨程度而变大，怨恨越深，破坏力越强。", type: "exclusive"},
            {name: "神之血统(半神)", color: "S", cost: 5000, desc: "拥有一半神明的血统，身体素质远超人类，寿命极长。", type: "exclusive"},
            {name: "女武神的加护", color: "B", cost: 1000, desc: "在濒死状态下，有一名女武神会为你指引方向，提升生存率。", type: "exclusive"},
            {name: "伦敦的雾", color: "C", cost: 500, desc: "能制造出浓雾环境，适合暗杀和隐藏行踪。", type: "exclusive"},
            {name: "相扑力士", color: "B", cost: 600, desc: "拥有极其稳固的下盘，难以被击倒或推开。", type: "exclusive"},
            {name: "神界观众的声援", color: "C", cost: 100, desc: "当神明为你加油时，你的士气会提升（虽然他们通常是嘲讽）。", type: "exclusive"},
            {name: "弑神者(称号)", color: "SSS", cost: 20000, desc: "你曾亲手杀死过神明。对神族造成真实伤害，且免疫神威压制。", type: "exclusive"},
            {name: "阿波罗的拳击", color: "A", cost: 2500, desc: "光速刺拳。攻击速度极快，且动作优雅，附带光属性伤害。", type: "exclusive"},
            {name: "斯巴达盾牌", color: "B", cost: 700, desc: "坚不可摧的意志化作的盾牌，能抵挡高出自身等级的攻击。", type: "exclusive"},
            {name: "神之义眼(伪)", color: "B", cost: 900, desc: "虽然不如亚当，但也能勉强看清神明的动作轨迹。", type: "exclusive"},
            {name: "终焉的倒计时", color: "SS", cost: 6500, desc: "宙斯的最终奥义前置。能压缩时间，让周围的时间流速变慢。", type: "exclusive"},
            {name: "人类的赞歌", color: "A", cost: 1200, desc: "精神类天赋。勇气是人类的赞歌，越是绝境，精神力越强。", type: "exclusive"}
        ]
    },
    {
        name: "492.拳愿阿修罗",
        desc: "企业之间为了利益，雇佣斗技者进行名为“拳愿竞技”的格斗比赛。这里汇聚了世界上最强的格斗家，传统武术、暗杀拳、怪力乱神，一切为了最强。",
        boss: "灭堂之牙(加纳咢), 黑木玄斋(魔枪), 十鬼蛇王马(阿修罗), 申武龙",
