            { name: "吴一族的远亲", items: "黑色的美瞳(伪装), 家族族谱" },
            { name: "炼狱的C级斗技者", items: "面具, 炼狱规则手册" }
        ],
        talents: [
            {name: "预借(凭神)", color: "SS", cost: 8000, desc: "二虎流奥义。通过让心脏超负荷跳动，加速血液循环，大幅提升速度和力量。代价是血管破裂和寿命缩短。", type: "exclusive"},
            {name: "解放(吴一族)", color: "SS", cost: 8500, desc: "解除大脑对身体能力的限制，释放出潜藏的肌肉力量。普通人只能释放30%，吴一族精英可达100%。", type: "exclusive"},
            {name: "魔枪(怪腕流)", color: "S", cost: 6000, desc: "将手指锻炼至钢铁般坚硬，能贯穿人体甚至钢板。这是黑木玄斋的绝技，代表着武术的极致。", type: "exclusive"},
            {name: "无形(Formless)", color: "S", cost: 5500, desc: "加纳咢的绝技。像水一样没有固定的架势，能适应任何对手的风格并进化出克制手段，但反应时间较长。", type: "exclusive"},
            {name: "超人体制(若槻)", color: "SS", cost: 9000, desc: "天生的肌肉密度是常人的52倍。拥有无与伦比的怪力和防御力，被称为“猛虎”，普通一拳即是必杀。", type: "exclusive"},
            {name: "二虎流·操流型", color: "A", cost: 2000, desc: "擅长借力打力，改变力量的流向，能将对手的重击化解或反弹。", type: "exclusive"},
            {name: "二虎流·金刚型", color: "A", cost: 2000, desc: "通过肌肉硬化来防御攻击，或者增强打击的威力，这就是“不坏”。", type: "exclusive"},
            {name: "雷心流(雷闪)", color: "A", cost: 2500, desc: "为了暗杀而生的步法。拥有直线移动的最快速度，如同闪电般瞬间接近对手。", type: "exclusive"},
            {name: "爆芯", color: "S", cost: 4000, desc: "若槻武士的必杀。将全身肌肉像弹簧一样压缩再释放，威力足以一击粉碎内脏。", type: "exclusive"},
            {name: "先之先(预读)", color: "S", cost: 5000, desc: "达到达人境界的证明。在对手行动之前就读出其意图并率先行动，看似是对手自己撞上来。", type: "exclusive"},
            {name: "主要杀手(Zone)", color: "A", cost: 3000, desc: "小宇宙的天才直觉。在对手将意识集中在攻击的一瞬间（0.1秒），切入其死角进行绞杀。", type: "exclusive"},
            {name: "罗刹掌", color: "A", cost: 3500, desc: "狐影流绝技。手掌击中目标时进行高速旋转，能扭曲肌肉和骨骼，造成恐怖的螺旋伤口。", type: "exclusive"},
            {name: "神魔同体", color: "SSS", cost: 20000, desc: "同时开启“预借”和“降魔”。拥有超越极限的速度和反应，但对心脏和大脑的双重负担几乎是自杀。", type: "exclusive"},
            {name: "帝王眼", color: "A", cost: 1800, desc: "拥有极强的动态视力，能看清对手肌肉的细微抽动，从而预判攻击。", type: "exclusive"},
            {name: "杀人音乐", color: "B", cost: 800, desc: "能通过特殊的呼吸节奏或声音干扰对手的听觉平衡。", type: "exclusive"},
            {name: "代行者", color: "C", cost: 500, desc: "作为企业的代表出战，获胜后能获得巨额奖金和地位。", type: "exclusive"},
            {name: "柔道天才", color: "B", cost: 1000, desc: "目黑正树级别的投技，只要抓到对手的衣角就能将其摔死。", type: "exclusive"},
            {name: "痛觉遮断", color: "A", cost: 1500, desc: "大脑分泌特殊的脑内麻药，将痛觉转化为快感，变成不知疲倦的丧尸。", type: "exclusive"},
            {name: "剃刀之锋", color: "A", cost: 1200, desc: "手指拥有极强的握力，能像剃刀一样撕裂皮肤和血管。", type: "exclusive"},
            {name: "巴顿术", color: "B", cost: 700, desc: "结合了拳击和柔术的古老格斗术，风格多变。", type: "exclusive"},
            {name: "炼狱规则适应", color: "C", cost: 200, desc: "擅长利用规则获胜，比如将对手击出场外或诱导对手犯规。", type: "exclusive"},
            {name: "因陀罗模式", color: "S", cost: 4500, desc: "通过调整呼吸和重心，进入完美的战斗状态，全属性大幅提升。", type: "exclusive"},
            {name: "猛虎之咬", color: "B", cost: 900, desc: "咬合力惊人，甚至能咬断动脉。", type: "exclusive"},
            {name: "心理掌控", color: "A", cost: 1600, desc: "在战斗中通过言语和微表情诱导对手，使其产生动摇。", type: "exclusive"},
            {name: "绝对防御(阿古谷)", color: "A", cost: 2200, desc: "拥有超快的神经反射速度，配合盾牌般的手臂，防御滴水不漏。", type: "exclusive"},
            {name: "吴氏传书", color: "B", cost: 600, desc: "掌握吴一族千年来积累的各种暗杀技巧和人体知识。", type: "exclusive"},
            {name: "逻辑崩坏", color: "D", cost: 100, desc: "你的行为完全不按常理出牌，让擅长预读的对手无法预测。", type: "exclusive"},
            {name: "拳眼", color: "S", cost: 3800, desc: "山下一夫的祖先遗传。能看清一切高速运动的物体，是成为顶级经纪人的关键。", type: "exclusive"},
            {name: "龙弹", color: "S", cost: 5000, desc: "加纳咢的必杀。在极近距离内打出的寸劲，威力巨大，防不胜防。", type: "exclusive"},
            {name: "仙人(申武龙)", color: "SSS", cost: 30000, desc: "超越了人类认知的存在。呼吸停止，脉搏停止，如同自然的一部分，出手即是规则。", type: "exclusive"}
        ]
    },
    {
        name: "493.刃牙",
        desc: "地上最强生物的父子局。这里有徒手撕坦克的范马勇次郎，有复活的原始人皮可，有宫本武藏的克隆体。在这个世界，纯度太低可是会死的。",
        boss: "范马勇次郎(地表最强), 宫本武藏(克隆体), 皮可(原始人), 范马刃牙",
        identities: [
            { name: "地下斗技场的清洁工", items: "沾满血的拖把, 斗技场入场券" },
            { name: "神心会的普通学员", items: "空手道服, 一块被劈开的瓦片" },
            { name: "监狱里的囚犯", items: "磨尖的牙刷, 一身伤疤" },
            { name: "中国拳法的挑战者", items: "布鞋, 烈海王的推荐信" },
            { name: "美军基地的士兵", items: "M16步枪(毫无用处), 卫星电话" }
        ],
        talents: [
            {name: "鬼背(Demon Back)", color: "SSS", cost: 28000, desc: "范马之血的证明。背部肌肉呈现出恶鬼的面容，开启后身体素质呈几何级数增长，是地表最强的象征。", type: "exclusive"},
            {name: "范马脑(Demon Brain)", color: "SS", cost: 10000, desc: "大脑呈现鬼脸形状。拥有超强的学习能力和战斗直觉，看一眼就能学会任何格斗技，并能想象出不存在的对手进行训练。", type: "exclusive"},
            {name: "无刀(二天一流)", color: "SS", cost: 9000, desc: "宫本武藏的境界。手中无刀，心中有刀。能用意识斩杀对手，甚至能用手刀切开防弹玻璃。", type: "exclusive"},
            {name: "原始人体质(皮可)", color: "SS", cost: 9500, desc: "来自白垩纪的肉体。专门猎杀恐龙的身体结构，脖子粗如树干，肌肉密度能抵挡现代兵器。", type: "exclusive"},
            {name: "消力(Shaori)", color: "S", cost: 6000, desc: "郭海皇的绝技。将身体放松到极致，像羽毛一样卸掉所有攻击；或在瞬间紧张，打出超越极限的一拳。", type: "exclusive"},
            {name: "握力(花山薰)", color: "A", cost: 3000, desc: "天生的怪力。握力足以捏爆叠在一起的扑克牌，甚至捏碎对手的手臂。不需要锻炼，变强是天生的。", type: "exclusive"},
            {name: "侠客行", color: "A", cost: 2500, desc: "花山薰背后的纹身。代表着绝对的义气和男子汉气概，在保护他人时战斗力爆表，永不倒下。", type: "exclusive"},
            {name: "马赫拳", color: "S", cost: 4000, desc: "愚地克巳的绝技。通过全身关节的加速，让拳头突破音障，产生音爆，威力巨大但会损伤手臂。", type: "exclusive"},
            {name: "视神经切断(切绳)", color: "A", cost: 2000, desc: "镐昂升的绝技。用手指切断对手的视神经，致其失明。需要极高的指力和精准度。", type: "exclusive"},
            {name: "死刑犯的卑鄙", color: "B", cost: 1000, desc: "为了胜利不择手段。使用暗器、偷袭、吐痰、装死，只要能赢，什么都做。", type: "exclusive"},
            {name: "奥利巴的肌肉", color: "S", cost: 5000, desc: "世界上最自由的男人。肌肉量巨大，能硬抗霰弹枪，甚至能用肌肉夹住敌人的攻击。", type: "exclusive"},
            {name: "蟑螂冲刺", color: "A", cost: 2200, desc: "范马刃牙领悟的步法。模仿蟑螂的液压爆发力，瞬间达到最高速度，无法被视觉捕捉。", type: "exclusive"},
            {name: "想象力具象化", color: "S", cost: 4500, desc: "刃牙的特技。通过极度的想象，能让身体产生真实的物理反应，比如想象自己在被火烧，皮肤真的会烫伤。", type: "exclusive"},
            {name: "合气道(涉川)", color: "A", cost: 3500, desc: "以柔克刚的极致。能利用对手的力量将其摔飞，哪怕是比自己重几倍的巨汉，也能像翻手掌一样轻松。", type: "exclusive"},
            {name: "环境利用", color: "B", cost: 800, desc: "盖亚的技能。能利用周围的一切物体（沙子、水、甚至空气）作为武器，甚至能钻进对手体内。", type: "exclusive"},
            {name: "毒手", color: "A", cost: 1800, desc: "柳龙光的绝技。手掌带有剧毒，接触皮肤即可让对手中毒，配合“鞭打”能造成无法愈合的伤口。", type: "exclusive"},
            {name: "咬道", color: "B", cost: 1200, desc: "杰克范马的执念。经过改造的钛合金牙齿，能咬碎椰子壳，甚至咬断骨头。为了变强不惜一切。", type: "exclusive"},
            {name: "兴奋剂体质", color: "C", cost: 500, desc: "能承受大量药物的副作用，通过药物强行提升身体机能。", type: "exclusive"},
            {name: "关节点穴", color: "B", cost: 900, desc: "攻击对手的关节连接处，使其瞬间失去战斗力。", type: "exclusive"},
            {name: "真空掌", color: "A", cost: 1600, desc: "利用手掌制造真空区域，令对手缺氧或破坏其耳膜。", type: "exclusive"},
            {name: "纯度鉴定", color: "D", cost: 100, desc: "你能一眼看出对手的格斗纯度。如果纯度太低，你会不由自主地嘲笑他。", type: "exclusive"},
            {name: "0.5秒的无意识", color: "S", cost: 3200, desc: "捕捉人类大脑在反应前那0.5秒的无意识空档进行攻击，必中。", type: "exclusive"},
            {name: "鞭打", color: "B", cost: 1500, desc: "将手臂像鞭子一样甩出，造成皮肤表面的剧烈疼痛，无视肌肉防御。", type: "exclusive"},
            {name: "金刚拳", color: "B", cost: 1000, desc: "神心会的正拳，经过千锤百炼，足以击碎岩石。", type: "exclusive"},
            {name: "同步率(Synchro)", color: "SS", cost: 7000, desc: "当两名强者产生共鸣时，会发生同步现象。你的战斗意识会与某位强者连接，获得其经验。", type: "exclusive"},
            {name: "拔拳", color: "B", cost: 800, desc: "不用摆架势，随时随地都能打出全力的拳头。", type: "exclusive"},
            {name: "为了变强吃下一切", color: "C", cost: 300, desc: "无论什么食物都能转化为肌肉，哪怕是过期的糖果。", type: "exclusive"},
            {name: "地表最强生物(伪)", color: "A", cost: 2000, desc: "模仿勇次郎的气场，能吓退普通人和低级格斗家。", type: "exclusive"},
            {name: "透明的菜肴", color: "D", cost: 50, desc: "你能看到勇次郎做的空气味增汤，并觉得很好吃（纯度极高）。", type: "exclusive"},
            {name: "复活的脊椎", color: "S", cost: 5500, desc: "即使脊椎断裂，也能通过某种不科学的方式（如想象力）强行接上并恢复战斗力。", type: "exclusive"}
        ]
    },
    {
        name: "494.一胜千金",
        desc: "名为“瓦尔基里”的地下女子格斗团体。这里没有规则，只有暴力与美学。为了金钱、为了梦想、为了愉悦，少女们在铁笼中厮杀。只要赢了，就能得到一切。",
        boss: "天马希望(修罗), 姬那(Hina), 柚叶李(Starfire), 陆道一族",
        identities: [
            { name: "欠债的陪酒女", items: "高额借据, 一双磨脚的高跟鞋" },
            { name: "过气的柔道冠军", items: "旧奖牌, 满身的伤病" },
            { name: "黑道组织的打手", items: "墨镜, 藏在怀里的指虎" },
            { name: "渴望暴力的富家女", items: "黑卡, 昂贵的格斗手套" },
            { name: "瓦尔基里的清洁工", items: "拖把, 染血的毛巾" }
        ],
        talents: [
            {name: "修罗的妄想", color: "SS", cost: 8000, desc: "天马希望的核心能力。通过极度的自我催眠和妄想，将自己代入各种角色（如骑士、恶魔），从而发挥出超越肉体极限的力量。", type: "exclusive"},
            {name: "破坏的快感", color: "S", cost: 5000, desc: "姬那的特质。在破坏对手肉体时能感受到极致的愉悦，这种变态的心理素质让她免疫恐惧和疼痛。", type: "exclusive"},
            {name: "一击必杀(Starfire)", color: "S", cost: 4500, desc: "柚叶李的绝技。追求极致的打击力度和精准度，如同流星般的一击，能瞬间KO对手。", type: "exclusive"},
            {name: "柔道女王", color: "A", cost: 3000, desc: "本弘千寻级别的柔道技巧。只要近身，就能将对手如同破布娃娃般摔在地上，地面技无敌。", type: "exclusive"},
            {name: "警察的逮捕术", color: "B", cost: 1500, desc: "结合了关节技和压制技的实战格斗术，专门用来制服暴徒，简洁高效。", type: "exclusive"},
            {name: "空手道黑带", color: "B", cost: 1200, desc: "正统的空手道技术，打击感强，攻防兼备。", type: "exclusive"},
            {name: "忍者血统(伪)", color: "A", cost: 2000, desc: "拥有极高的敏捷度和使用暗器的技巧，擅长在混乱中取胜。", type: "exclusive"},
            {name: "黑道背景", color: "A", cost: 2500, desc: "拥有黑道陆道一族的支持，能获得情报、资金，甚至能在场外解决问题。", type: "exclusive"},
            {name: "精神崩溃(抗性)", color: "B", cost: 800, desc: "在地下格斗场，精神正常的人是活不下去的。你拥有极强的心理承受力，不会被血腥场面吓倒。", type: "exclusive"},
            {name: "偶像魅力", color: "C", cost: 500, desc: "作为格斗偶像，你拥有大量粉丝。粉丝的声援能让你在绝境中爆发力量。", type: "exclusive"},
            {name: "指虎专精", color: "C", cost: 300, desc: "擅长使用指虎等小型武器，在无规则乱斗中优势巨大。", type: "exclusive"},
            {name: "兴奋剂耐受", color: "B", cost: 700, desc: "能承受违禁药物的副作用，短时间内大幅提升爆发力。", type: "exclusive"},
            {name: "受虐体质", color: "A", cost: 1800, desc: "越是受伤，越是兴奋。疼痛转化为肾上腺素，让你越战越勇。", type: "exclusive"},
            {name: "关节破坏者", color: "A", cost: 2200, desc: "专注于攻击对手的关节，一旦得手，就能废掉对手的一条胳膊或腿。", type: "exclusive"},
            {name: "裸绞大师", color: "B", cost: 1000, desc: "一旦背后位成型，对手必死无疑。强大的绞杀力量。", type: "exclusive"},
            {name: "街头斗殴经验", color: "C", cost: 400, desc: "不讲武德。插眼、踢裆、咬人，怎么赢怎么来。", type: "exclusive"},
            {name: "绝对音准(格斗)", color: "B", cost: 600, desc: "能听出对手肌肉紧绷的声音，预判攻击。", type: "exclusive"},
            {name: "瑜伽柔韧性", color: "B", cost: 900, desc: "身体柔软度惊人，能做出匪夷所思的闪避动作，或者从关节技中逃脱。", type: "exclusive"},
            {name: "复仇女神", color: "S", cost: 4000, desc: "当生命值低于20%时，全属性提升50%，攻击附带吸血效果。", type: "exclusive"},
            {name: "赌徒心理", color: "C", cost: 200, desc: "在战斗中敢于豪赌，用受伤换取致命一击的机会。", type: "exclusive"},
            {name: "金钱驱动", color: "A", cost: 1500, desc: "奖金越高，战力越强。为了十亿日元，神也杀给你看。", type: "exclusive"},
            {name: "美甲武器", color: "C", cost: 100, desc: "经过特殊硬化的美甲，抓挠时能造成流血伤害。", type: "exclusive"},
            {name: "假动作大师", color: "B", cost: 800, desc: "擅长用眼神和肢体动作欺骗对手，制造空档。", type: "exclusive"},
            {name: "钢铁下巴", color: "A", cost: 1600, desc: "下巴抗击打能力极强，不容易被KO。", type: "exclusive"},
            {name: "泰拳膝撞", color: "B", cost: 1100, desc: "凶狠的膝撞，近身缠斗时的利器。", type: "exclusive"},
            {name: "巴西柔术", color: "A", cost: 2000, desc: "地面缠斗的王者，拥有丰富的位置控制和降服技术。", type: "exclusive"},
            {name: "无限制格斗", color: "S", cost: 3500, desc: "适应任何规则，无论是拳愿、炼狱还是瓦尔基里，都能找到最适合的战术。", type: "exclusive"},
            {name: "天生的怪物", color: "SS", cost: 6000, desc: "无需训练，天生拥有顶级的身体素质和战斗本能，是凡人无法企及的天才。", type: "exclusive"},
            {name: "双重人格", color: "S", cost: 4200, desc: "平时是乖乖女，战斗时切换为残暴人格，痛觉屏蔽，力量倍增。", type: "exclusive"},
            {name: "千万富翁", color: "SS", cost: 9999, desc: "拥有一胜千金的财富，可以购买最好的装备、药物和情报。", type: "exclusive"}
        ]
    },
    {
        name: "495.魔物娘的同居日常",
        desc: "“他种族间交流法”颁布后，亚人种（魔物娘）开始融入人类社会。作为寄宿家庭的主人，你需要照顾这些拥有特殊习性和强大力量的魔物娘，同时应对墨守成规的MON部队。",
        boss: "墨须(墨社长), MON部队(混合特种部队), 种族歧视激进派, 暴走的魔物娘",
        identities: [
            { name: "普通的寄宿家庭主人", items: "全能家政指南, 极强的抗击打能力" },
            { name: "墨氏保安公司的特工", items: "墨镜, 麻醉枪" },
            { name: "亚人种非法偷渡中介", items: "假护照, 隐秘路线图" },
            { name: "种族交流法的反对者", items: "抗议标语, 扩音器" },
            { name: "不知情的送货员", items: "快递箱, 吓坏的表情" }
        ],
        talents: [
            {name: "钢铁色狼(Darling)", color: "SSS", cost: 20000, desc: "男主来留主公人的体质。拥有无限的生命力和恢复力，无论被拉米亚勒紧、被哈比撞飞、还是被半人马踢飞，都能奇迹般地存活下来。", type: "exclusive"},
            {name: "蛇之拥抱(米亚)", color: "S", cost: 4000, desc: "拉米亚族的特技。用长长的蛇尾紧紧缠绕目标，力量巨大，既是攻击也是（沉重的）爱。", type: "exclusive"},
            {name: "天际翱翔(帕皮)", color: "A", cost: 2500, desc: "哈比族的飞行能力。能带着一个人在空中飞行，但智商会随着高度上升而下降（鸟脑）。", type: "exclusive"},
            {name: "骑士冲锋(塞卓蕾娅)", color: "S", cost: 4500, desc: "半人马族的冲刺。拥有极高的机动性和冲击力，配合骑士长枪，威力惊人。", type: "exclusive"},
            {name: "史莱姆体质(苏)", color: "SS", cost: 8000, desc: "身体由液体构成，免疫物理攻击，能随意变形，还能通过接触读取记忆或补充水分（各种意义上）。", type: "exclusive"},
            {name: "人鱼之歌(梅洛)", color: "A", cost: 3000, desc: "人鱼族的歌声。能安抚人心，或者引发悲剧恋情（误）。在水中移动速度极快。", type: "exclusive"},
            {name: "蜘蛛束缚(拉克涅)", color: "S", cost: 5000, desc: "阿拉克涅族的能力。能吐出极其坚韧的蛛丝，布置陷阱或束缚敌人，擅长捆绑play。", type: "exclusive"},
            {name: "无头骑士(杜拉汉)", color: "A", cost: 3500, desc: "头身分离。头可以作为侦查器，身体可以独立战斗。拥有死神的镰刀，但性格意外地怕羞。", type: "exclusive"},
            {name: "僵尸不死身(Zombina)", color: "SS", cost: 7000, desc: "真正的肉体不死。无论身体被打烂多少次，只要缝合起来就能继续动。感觉不到疼痛。", type: "exclusive"},
            {name: "变形者(Doppel)", color: "S", cost: 5500, desc: "能完美模仿任何人的外貌和声音，是潜入和恶作剧的专家。", type: "exclusive"},
            {name: "鬼族怪力(Tio)", color: "A", cost: 2800, desc: "体型巨大，力大无穷，性格豪爽。注意不要在狭窄的地方变身。", type: "exclusive"},
            {name: "龙人吐息(Draco)", color: "S", cost: 4200, desc: "龙人族的能力。能喷吐火焰，尾巴极其有力，但尾巴尖是敏感点。", type: "exclusive"},
            {name: "墨氏特工训练", color: "B", cost: 1000, desc: "接受过MON部队的专业训练，掌握格斗、射击和亚人种压制战术。", type: "exclusive"},
            {name: "亚人种フェロモン(Pheromone)", color: "A", cost: 1500, desc: "你身上散发着吸引亚人种的气味，容易获得魔物娘的好感，但也容易引发修罗场。", type: "exclusive"},
            {name: "全能家政夫", color: "C", cost: 500, desc: "精通做饭、洗衣、打扫，能照顾好各种饮食习惯奇特的魔物娘。", type: "exclusive"},
            {name: "法律豁免权(伪)", color: "B", cost: 800, desc: "作为寄宿家庭主人，你在处理魔物娘引发的骚乱时，拥有一定的豁免权。", type: "exclusive"},
            {name: "冷血动物亲和", color: "C", cost: 300, desc: "体温较低，容易吸引蛇、蜥蜴等冷血亚人种来取暖。", type: "exclusive"},
            {name: "植物操控", color: "A", cost: 2000, desc: "树妖族的能力。能操控藤蔓和树根，或者利用花粉进行催眠。", type: "exclusive"},
            {name: "独眼巨人(Mono)", color: "B", cost: 1200, desc: "拥有一只巨大的眼睛，视力极佳，但缺乏距离感。", type: "exclusive"},
            {name: "雪女冰冻", color: "A", cost: 2200, desc: "能降低周围温度，制造冰雪。体温极低，抱起来很凉快。", type: "exclusive"},
            {name: "魅魔契约", color: "S", cost: 3800, desc: "通过亲吻或更亲密的接触吸取精力，但也能赋予对方某种加护。", type: "exclusive"},
            {name: "满月变身", color: "A", cost: 2500, desc: "狼人族在满月时会变身，野性大发，需要注意控制。", type: "exclusive"},
            {name: "神圣光环(伪)", color: "D", cost: 100, desc: "虽然看起来很神圣，但实际上对魔物娘没有任何驱散效果。", type: "exclusive"},
            {name: "触手操控", color: "A", cost: 2600, desc: "斯库拉族的能力。下半身是无数的触手，能进行多重攻击。", type: "exclusive"},
            {name: "极度迟钝", color: "C", cost: 200, desc: "对魔物娘的诱惑视而不见，这反而让她们更加着迷。", type: "exclusive"},
            {name: "裁缝大师", color: "C", cost: 400, desc: "能为体型各异的魔物娘制作合身的衣服（或者修补被撑破的衣服）。", type: "exclusive"},
            {name: "魔物娘图鉴", color: "B", cost: 600, desc: "拥有关于所有亚人种习性的详细知识，知道她们的弱点和敏感点。", type: "exclusive"},
            {name: "大房子", color: "C", cost: 1000, desc: "拥有改建过的巨大房屋，门特别宽，适合半人马和阿拉克涅进出。", type: "exclusive"},
            {name: "墨社长的威胁", color: "E", cost: -500, desc: "时刻被墨社长监视，一旦违反规定就会被抹杀（各种意义上）。", type: "exclusive"},
            {name: "种族和平大使", color: "SS", cost: 10000, desc: "你的存在就是种族共存的证明。能平息种族冲突，获得所有亚人种的尊敬。", type: "exclusive"}
        ]
    },
            {
                name: "496.龙族",
                desc: "一个隐藏在现代社会阴影下的神话世界。混血种、言灵、炼金术与苏醒的古龙。卡塞尔学院致力于屠龙事业，而名为命运的纺车正在编织着名为“哀伤”的丝线。",
                boss: "黑王尼德霍格, 白王赫尔佐格, 奥丁, 芬里厄",
                identities: [
                    { name: "仕兰中学的透明路人", items: "一本写满暗恋日记的笔记本, 一张过期的网吧会员卡" },
                    { name: "卡塞尔学院的退学生", items: "一枚被收回权限的校徽, 一张飞往中国的单程机票" },
                    { name: "东京歌舞伎町的非法滞留者", items: "一件沾着拉面汤渍的廉价西装, 一把防身的折叠刀" },
                    { name: "猎人网站的F级赏金猎人", items: "一台老旧的笔记本电脑, 一个登录暗网的临时账号" },
                    { name: "蛇岐八家下属帮派的清洁工", items: "一套沾满血腥味的清洁工具, 一瓶用来销毁证据的强酸" }
                ],
                talents: [
                    {name: "路鸣泽的交易(魔鬼)", color: "SSS", cost: 50000, desc: "你与小魔鬼路鸣泽签订了契约。你可以通过出卖自己的生命（或灵魂的四分之一），强制兑换名为“Something for nothing”的奇迹，包括但不限于杀死龙王。", type: "exclusive"},
                    {name: "黑王血裔(残缺)", color: "SSS", cost: 45000, desc: "你体内流淌着黑王尼德霍格的血脉。虽然残缺，但你拥有对所有下位龙类的绝对血统压制，拥有究极的言灵皇帝的使用权（需觉醒）。", type: "exclusive"},
                    {name: "白王圣骸(寄生)", color: "SS", cost: 9500, desc: "白王的圣骸寄生在你的脊椎中。你拥有精神元素的最高掌控权，能够通过梦境改写现实，但你的精神状态极不稳定，随时可能化为怪物。", type: "exclusive"},
                    {name: "言灵·时间零", color: "SS", cost: 8800, desc: "刺客的终极言灵。你可以将自身周围的时间流速放慢数十倍，在敌人眼中你就如同瞬移一般。配合炼金刀剑，你是战场上的死神。", type: "exclusive"},
                    {name: "言灵·审判", color: "SS", cost: 9000, desc: "源自上杉绘梨衣的极危言灵。在这个领域内，你发出的任何“死亡”指令都会被强制执行，切割概念上的生命。副作用是身体会逐渐崩溃。", type: "exclusive"},
                    {name: "七宗罪(炼金刀剑)", color: "SS", cost: 8500, desc: "青铜与火之王诺顿铸造的七把屠龙武器：傲慢、妒忌、暴怒、懒惰、贪婪、暴食、色欲。每一把都针对不同形态的龙王，拥有活着的灵魂。", type: "exclusive"},
                    {name: "S级血统(皇)", color: "S", cost: 3500, desc: "你是混血种中的“皇”，血统纯度极高且稳定，无需担心死侍化。你的体能、恢复力、言灵威力都远超常人，天生的领袖。", type: "exclusive"},
                    {name: "言灵·君焰", color: "S", cost: 2800, desc: "高危言灵，在这领域内你可以随意制造高温和爆炸，如同凝固汽油弹洗地。这是青铜与火之王一系的标志性能力。", type: "exclusive"},
                    {name: "侧写(极致)", color: "S", cost: 2500, desc: "你的观察力和逻辑推理能力达到了预知未来的地步。通过现场的蛛丝马迹，你能在脑海中完美重演案件发生的经过，甚至模拟敌人的心理。", type: "exclusive"},
                    {name: "爆血(二度)", color: "S", cost: 2200, desc: "狮心会的秘法。通过强行提升心率纯化龙血，你可以短时间获得跨越阶级的力量。二度爆血后，你的身体将开始出现龙化特征，极易失控。", type: "exclusive"},
                    {name: "炼金术(贤者之石)", color: "S", cost: 3000, desc: "你掌握了高深的炼金术，能够制造精神元素结晶“贤者之石”。这种红色的石头是龙类的剧毒，打磨成子弹可一击必杀复苏的龙王。", type: "exclusive"},
                    {name: "言灵·刹那", color: "A", cost: 1500, desc: "你可以成倍地提升自己的速度，从二倍速到五百一十二倍速（九阶）。虽然没有时间零的时空效应，但在物理层面上你快得看不见。", type: "exclusive"},
                    {name: "言灵·戒律", color: "A", cost: 1200, desc: "守夜人的招牌言灵。你可以压制领域内所有混血种和龙类的言灵能力，强制让他们进行肉搏战。对血统高于你的目标效果减弱。", type: "exclusive"},
                    {name: "言灵·蛇", color: "A", cost: 1000, desc: "你可以通过电流信号寻找信息，像蛇一样在网络和电缆中游走。你是天生的黑客和情报专家，没有你找不到的秘密。", type: "exclusive"},
                    {name: "村雨(妖刀)", color: "A", cost: 800, desc: "一把源自日本的炼金古刀，据说沾染了太多亡魂而带有诅咒。刀身在此刻会渗出露水洗去血迹，锋利无比，对龙类有特攻。", type: "exclusive"},
                    {name: "弗里格嘉子弹(一箱)", color: "B", cost: 400, desc: "卡塞尔学院特制的炼金弹头，击中目标后会瞬间粉碎并释放强效麻醉剂，不会造成物理伤害但能让人瞬间倒地。演习神器。", type: "exclusive"},
                    {name: "言灵·无尘之地", color: "B", cost: 500, desc: "防御型言灵。你可以制造一个排斥所有外来物质的力场，无论是灰尘、雨水还是子弹、毒气，都无法进入你的领域。", type: "exclusive"},
                    {name: "言灵·镰鼬", color: "B", cost: 450, desc: "你可以驱使风妖为你带回声音。在这个领域内，你的听力被极度强化，能听到几公里外的心跳声，适合侦查。", type: "exclusive"},
                    {name: "执行部风衣", color: "C", cost: 150, desc: "卡塞尔学院执行部的制式装备，内衬防弹纤维，剪裁修身帅气。穿上它，你走在街上就像个冷酷的杀手。", type: "exclusive"},
                    {name: "言灵·冥照", color: "C", cost: 180, desc: "你可以折射周围的光线，制造一个视觉盲区。虽然不是完全隐身，但在阴影中几乎无法被察觉，适合潜行和暗杀。", type: "exclusive"},
                    {name: "芬格尔的狗仔包", color: "C", cost: 120, desc: "里面装满了各种偷拍设备、录音笔和高热量零食。这是新闻部部长的真传，适合收集八卦和黑料。", type: "exclusive"},
                    {name: "3E考试作弊码", color: "C", cost: 200, desc: "你提前搞到了3E血统评定考试的答案（虽然是画龙和跳舞）。这能保你顺利入学，不被降级为E级。", type: "exclusive"},
                    {name: "布加迪威龙(借用)", color: "B", cost: 600, desc: "恺撒·加图索借给你开几天的豪车。W16引擎的轰鸣声能让你的肾上腺素飙升，也是泡妞的神器，但在东京街头容易堵车。", type: "exclusive"},
                    {name: "死侍化(诅咒)", color: "E", cost: 50, desc: "你的血统极度不稳定，临界血限已被突破。你的身体开始长出鳞片，理智逐渐丧失，最终将沦为只知道杀戮的怪物。", type: "exclusive"},
                    {name: "言灵·冬", color: "D", cost: 80, desc: "没什么用的言灵，只能让周围的温度稍微降低一点，大概相当于一台移动空调。夏天倒是挺凉快的。", type: "exclusive"},
                    {name: "路明非的PS3", color: "C", cost: 100, desc: "一台老旧的游戏机，里面存着路明非打了一半的《星际争霸》存档。也许你能从中领悟到什么战术，或者只是浪费时间。", type: "exclusive"},
                    {name: "炼金生物(活灵)", color: "A", cost: 900, desc: "你拥有一个微型的炼金生命体，可能是一把会说话的钥匙，或者一只金属老鼠。它能帮你开锁、咬断电线。", type: "exclusive"},
                    {name: "尼伯龙根的门票", color: "S", cost: 3200, desc: "你拥有进入特定尼伯龙根（死人之国）的烙印。那里有无尽的宝藏，也有必死的陷阱。这是通往世界真相的捷径。", type: "exclusive"},
                    {name: "暴血(一度)", color: "B", cost: 650, desc: "狮心会秘法的入门版。你可以轻微提升血统纯度，获得力量增幅，副作用相对较小，但频繁使用会缩短寿命。", type: "exclusive"},
                    {name: "绘梨衣的小黄鸭", color: "C", cost: 250, desc: "一只写着“Sakura & Erii”的橡皮鸭子。它没有任何属性加成，但带着它，或许能在某个雨夜唤回那个女孩的理智。", type: "exclusive"}
                ]
            },
    {
        name: "497.[原创]低魔硬核古代武侠-大壅",
        desc: "一个皇权衰微、江湖草莽并起的低魔武侠世界。这里没有飞天遁地的神仙，只有刀刀见血的搏杀。内力稀薄，武功依靠打熬筋骨和招式精妙。人命如草芥，只有活下去才是硬道理。",
        boss: "摄政王-独孤绝, 魔教教主-厉千行, 隐世剑圣-风清扬",
        identities: [
            { name: "边关战场的死尸堆幸存者", items: "一件染血的破烂皮甲, 一把卷刃的军刀" },
            { name: "京城天牢的死囚", items: "沉重的手脚镣铐, 一件发霉的囚服" },
            { name: "被灭门的镖局少主(落魄)", items: "半块残缺的镖局令牌, 一身补丁摞补丁的布衣" },
            { name: "荒野客栈的哑巴杂役", items: "一条擦桌子的黑抹布, 一把剔骨尖刀" },
            { name: "流落街头的断臂乞丐", items: "一个缺角的破碗, 一根打狗棒(普通木棍)" }
        ],
        talents: [
            {name: "先天痨病", color: "E", cost: 10, desc: "你天生肺脉受损，走几步路都会喘，剧烈运动可能直接导致咳血而亡。在这个世界，这是必死之症。", type: "exclusive"},
            {name: "断指", color: "D", cost: 50, desc: "你的右手缺少两根手指，这严重影响了你握持兵器的稳定性，大多数精妙剑法你都无法修炼。", type: "exclusive"},
            {name: "粗通拳脚", color: "C", cost: 100, desc: "你在市井斗殴中摸索出了一套王八拳，虽然毫无章法，但打几个普通流氓还是绰绰有余的。", type: "exclusive"},
            {name: "皮糙肉厚", color: "C", cost: 150, desc: "多年的挨打经历让你练就了一身抗揍的本事，普通的拳脚打在你身上不痛不痒。", type: "exclusive"},
            {name: "江湖黑话", color: "C", cost: 120, desc: "你精通江湖切口和黑话，能轻易分辨出谁是肥羊谁是硬茬，在黑店里也能混口饭吃。", type: "exclusive"},
            {name: "铁匠学徒", color: "C", cost: 180, desc: "你跟着铁匠打过几年铁，懂得基础的兵器修缮和锻造，臂力也比常人强上几分。", type: "exclusive"},
            {name: "十年内力", color: "B", cost: 500, desc: "你意外服食过一枚朱果，体内积攒了约莫十年的精纯内力，这在低魔世界已是难得的高手根基。", type: "exclusive"},
            {name: "金钟罩(残篇)", color: "B", cost: 600, desc: "你习得了一门外家横练功夫的残篇，运功时皮肤坚如牛皮，能抵挡普通刀剑的劈砍。", type: "exclusive"},
            {name: "暗器精通", color: "B", cost: 450, desc: "你擅长使用飞蝗石、袖箭等暗器，百步之内指哪打哪，是偷袭阴人的好手。", type: "exclusive"},
            {name: "神行太保", color: "B", cost: 550, desc: "你天生腿脚轻快，擅长长途奔袭和短距离爆发，打不过的时候跑得比谁都快。", type: "exclusive"},
            {name: "用毒行家", color: "A", cost: 800, desc: "你熟知百草特性，能调配出见血封喉的毒药，也能解大部分江湖常见的毒。", type: "exclusive"},
            {name: "听风辨位", color: "A", cost: 900, desc: "你的听觉敏锐至极，即便在黑暗中也能通过风声判断敌人的位置和出招轨迹。", type: "exclusive"},
            {name: "百战老兵", color: "A", cost: 850, desc: "你从尸山血海的战场上活了下来，精通各种杀人技，出手狠辣，没有任何多余的动作。", type: "exclusive"},
            {name: "名门弃徒", color: "A", cost: 950, desc: "你曾是名门大派的弟子，虽然被逐出师门，但掌握了正统的内功心法和剑术基础。", type: "exclusive"},
            {name: "软猬甲", color: "S", cost: 1500, desc: "开局自带一件刀枪不入的软猬甲，不仅防御力惊人，上面还带有倒刺，能伤到来犯之敌。", type: "exclusive"},
            {name: "天生神力", color: "S", cost: 1800, desc: "你天生骨骼惊奇，力大无穷，能单手举起千斤巨鼎，所谓的一力降十会在你身上体现得淋漓尽致。", type: "exclusive"},
            {name: "过目不忘", color: "S", cost: 1600, desc: "你拥有过目不忘的能力，任何武功秘籍只要看一遍就能记在脑子里，偷学武功的神技。", type: "exclusive"},
            {name: "剑心通明", color: "S", cost: 1900, desc: "你对剑道有着超乎常人的领悟力，任何剑法在你手中都能化腐朽为神奇，直指剑道本源。", type: "exclusive"},
            {name: "洗髓经(易筋)", color: "SS", cost: 5000, desc: "传说中的少林至宝。你已完成易筋洗髓，资质从凡骨变为绝世天才，修炼任何武功速度提升十倍。", type: "exclusive"},
            {name: "独孤九剑", color: "SS", cost: 6500, desc: "剑魔独孤求败所创绝学，无招胜有招，专门破尽天下武学。只要看穿对方破绽，便可一击必杀。", type: "exclusive"},
            {name: "北冥神功", color: "SS", cost: 7000, desc: "逍遥派绝学，可以吸取他人的内力为己用。在这个内力稀缺的世界，你是唯一的掠夺者。", type: "exclusive"},
            {name: "天魔解体大法", color: "SS", cost: 4500, desc: "魔教禁术，燃烧生命力瞬间爆发十倍战力。虽然副作用极大，但这是绝境翻盘的终极底牌。", type: "exclusive"},
            {name: "长生诀(全本)", color: "SSS", cost: 12000, desc: "道家至高宝典，直指破碎虚空。修炼出的先天真气生生不息，回气极快，几乎拥有不死之身。", type: "exclusive"},
            {name: "武道通神", color: "SSS", cost: 15000, desc: "你就是武道的终点。任何武学你看一眼便能推演到极致甚至超越原版，你的存在打破了这个低魔世界的上限。", type: "exclusive"},
            {name: "位面之子(大壅)", color: "SSS", cost: 18000, desc: "你是这个世界气运的集合体。跳崖必得秘籍，路边乞丐必是隐世高手，所有巧合都为你服务。", type: "exclusive"}
        ]
    },
    {
