            {name: "基建狂魔", color: "C", cost: 150, desc: "你建造和升级宗门建筑的速度比别人快30%，消耗的资源减少20%。前期发展的神技。", type: "exclusive"},
            {name: "忽悠大师", color: "C", cost: 180, desc: "你拥有一张巧嘴，能把路边的乞丐忽悠成绝世天才，能把敌对宗门忽悠得找不到北。", type: "exclusive"},
            {name: "慧眼识珠", color: "B", cost: 400, desc: "你能看到流民的资质面板，在茫茫人海中精准捡漏，找到那些被埋没的天才弟子。", type: "exclusive"},
            {name: "资源返还", color: "B", cost: 550, desc: "你消耗资源培养弟子时，有一定几率触发暴击，返还部分甚至双倍的资源。", type: "exclusive"},
            {name: "护宗神兽(幼崽)", color: "A", cost: 800, desc: "开局自带一只潜力巨大的神兽幼崽。虽然现在还很弱，但培养起来就是镇宗之宝。", type: "exclusive"},
            {name: "名师光环", color: "A", cost: 900, desc: "你的教导能让弟子如沐春风，弟子修炼速度提升50%，领悟功法的几率大幅增加。", type: "exclusive"},
            {name: "洗脑光环", color: "A", cost: 850, desc: "你的弟子对你绝对忠诚，永不背叛。即使你让他们去送死，他们也会毫不犹豫地执行。", type: "exclusive"},
            {name: "欧皇附体", color: "S", cost: 1800, desc: "你的运气好到爆棚。出门就能捡到灵石，随便招募个弟子就是天灵根，秘境探险必得至宝。", type: "exclusive"},
            {name: "SSS级天赋抽取卡", color: "S", cost: 2000, desc: "开局获得一张一次性道具，可以强制抽取一项SSS级天赋赋予自己或弟子。", type: "exclusive"},
            {name: "位面交易网", color: "S", cost: 1600, desc: "你连通了万界交易平台，可以用本世界的土特产换取其他世界的黑科技或修仙资源。", type: "exclusive"},
            {name: "宗门阵法大师", color: "S", cost: 1500, desc: "开局自带一套护宗大阵，攻防一体。在前期没人能攻破你的山门，给你绝对的发育时间。", type: "exclusive"},
            {name: "百倍增幅系统", color: "SS", cost: 6000, desc: "你获得的任何奖励（修为、物品、资源）都可以选择进行百倍数量增幅或百倍质量增幅。", type: "exclusive"},
            {name: "弟子返还系统", color: "SS", cost: 7000, desc: "你授予弟子任何东西（修为、功法、丹药），系统都会最高万倍返还给你。授徒变强流必备。", type: "exclusive"},
            {name: "召唤第四天灾", color: "SS", cost: 8000, desc: "你可以召唤地球玩家作为你的弟子。他们不死不灭，肝度爆表，是你最恐怖的军团。", type: "exclusive"},
            {name: "掌中佛国", color: "SSS", cost: 12000, desc: "你的手掌中蕴含一个独立的小世界。你可以将整个宗门收入其中，随身携带，随时跑路或偷袭。", type: "exclusive"},
            {name: "天道私生子", color: "SSS", cost: 15000, desc: "天道给你开后门。雷劫不劈你，规则限制不了你，你可以随意修改部分宗门系统的规则。", type: "exclusive"},
            {name: "无尽吞噬", color: "SSS", cost: 14000, desc: "你的宗门可以通过吞噬其他宗门的地盘、气运甚至灵脉来无限进化，最终吞噬整个世界。", type: "exclusive"},
            {name: "自动化修仙", color: "SS", cost: 5000, desc: "你的宗门实现了全自动化。炼丹、炼器、种植、修炼全自动挂机，你只需要躺着收菜。", type: "exclusive"},
            {name: "护短狂魔", color: "A", cost: 950, desc: "当你的弟子受到伤害时，你的战力会根据弟子的伤势飙升，最高提升10倍。打了小的来了老的。", type: "exclusive"},
            {name: "灵脉之源", color: "S", cost: 1900, desc: "你的宗门驻地拥有一条极品灵脉，灵气浓度是外界的百倍，在这里修炼一天顶外面一年。", type: "exclusive"},
            {name: "悟道茶树", color: "S", cost: 1700, desc: "开局自带一棵悟道茶树。喝了悟道茶，顿悟如喝水，再难的功法也能瞬间练成。", type: "exclusive"},
            {name: "傀儡大军", color: "A", cost: 800, desc: "你掌握了上古傀儡术，可以制造不知疲倦、悍不畏死的傀儡大军守卫宗门或外出征战。", type: "exclusive"},
            {name: "情报网", color: "B", cost: 350, desc: "你拥有一个遍布大陆的情报组织，能第一时间知晓哪里有宝物出世，哪个宗门最空虚。", type: "exclusive"}
        ]
    },
    {
        name: "501.[原创]现代ABO-信息素纪元",
        desc: "一个人类分化为Alpha、Beta、Omega的现代社会。信息素决定了社会地位和本能冲动。Alpha是精英统治者，Beta是平庸工蜂，Omega是稀有资源。抑制剂和发情期是永恒的主题。",
        boss: "财阀掌舵人(顶级Alpha)-霍寒, 联邦议长-林深, 反叛军首领(变异Omega)-夜莺",
        identities: [
            { name: "贫民窟的劣质Omega", items: "一支过期的抑制剂, 一个破损的防咬项圈" },
            { name: "大企业的底层Beta职员", items: "一张刷爆的信用卡, 一份996的加班表" },
            { name: "黑市拳击场的Alpha拳手", items: "一副沾血的拳套, 一瓶烈性伏特加" },
            { name: "被家族流放的私生子", items: "一张单程机票, 一个隐藏身份的假证件" },
            { name: "医学院的落魄实习生", items: "一本关于腺体手术的笔记, 一把锋利的手术刀" }
        ],
        talents: [
            {name: "腺体残缺", color: "E", cost: 20, desc: "你的腺体先天发育不全，无法正常释放和感知信息素，且容易产生病变，身体素质极差。", type: "exclusive"},
            {name: "信息素过敏", color: "D", cost: 60, desc: "你对高浓度的信息素过敏。一旦处于发情期或易感期的AO身边，你会呼吸困难甚至休克。", type: "exclusive"},
            {name: "Beta的平庸", color: "C", cost: 100, desc: "作为Beta，你没有信息素的困扰，但也没有AO的天赋。在社会中你是最不起眼的螺丝钉，但也最安全。", type: "exclusive"},
            {name: "抑制剂耐药性", color: "D", cost: 80, desc: "普通的抑制剂对你效果甚微。你需要高价购买特制抑制剂，否则发情期/易感期将是你的噩梦。", type: "exclusive"},
            {name: "气味阻断", color: "C", cost: 150, desc: "你擅长消除自身的气味。无论是使用喷雾还是物理手段，你都能让自己像个隐形人。", type: "exclusive"},
            {name: "腺体医生", color: "B", cost: 400, desc: "你精通腺体医学，能进行高难度的腺体摘除或修复手术。这在这个世界是暴利行业。", type: "exclusive"},
            {name: "高阶Alpha体质", color: "A", cost: 800, desc: "你拥有S级Alpha的身体素质，力量、速度、恢复力远超常人，天生的战士和领导者。", type: "exclusive"},
            {name: "信息素安抚", color: "A", cost: 850, desc: "你的信息素具有极强的安抚效果，能平复暴走的Alpha或痛苦的Omega，是天生的治愈者。", type: "exclusive"},
            {name: "伪装者", color: "A", cost: 900, desc: "你可以自由改变自己显露的性别特征。装O钓A，或者装A吓人，随心所欲。", type: "exclusive"},
            {name: "意志坚定", color: "B", cost: 500, desc: "你拥有钢铁般的意志，即使在高浓度信息素压制下，也能保持理智，不被本能支配。", type: "exclusive"},
            {name: "Enigma(稀有性别)", color: "S", cost: 2500, desc: "凌驾于Alpha之上的传说性别。你可以标记Alpha，将其转化为专属的Omega。你是食物链的顶端。", type: "exclusive"},
            {name: "信息素实体化", color: "S", cost: 1800, desc: "你的信息素强大到可以凝聚成实体，进行物理攻击或防御。气味杀人不再是比喻。", type: "exclusive"},
            {name: "绝对命令", color: "S", cost: 2200, desc: "高阶Alpha的专属技能。你可以用声音夹杂信息素下达命令，低阶AO无法抗拒，必须服从。", type: "exclusive"},
            {name: "无味者", color: "S", cost: 1600, desc: "你是一个特殊的变异体，没有任何信息素味道，也不受任何信息素影响。你是天生的杀手。", type: "exclusive"},
            {name: "万人迷光环", color: "SS", cost: 5000, desc: "你的信息素味道对所有人都有致命的吸引力。无论男女AOB，闻到你的味道都会为你疯狂。", type: "exclusive"},
            {name: "腺体猎手", color: "SS", cost: 4500, desc: "你可以通过吞噬他人的腺体来强化自己的等级。这是一条血腥的进化之路。", type: "exclusive"},
            {name: "神之基因", color: "SSS", cost: 12000, desc: "你的基因完美无缺。你的后代必定是SSS级天才。各大财阀和皇室都想把你抓回去配种。", type: "exclusive"},
            {name: "信息素暴君", color: "SSS", cost: 15000, desc: "你的信息素覆盖范围可达全城。一念之间，可以让全城的人陷入发情或恐惧的深渊。", type: "exclusive"},
            {name: "第二性别觉醒", color: "SS", cost: 6000, desc: "你可以在体内觉醒第二套生殖腺体系统，同时拥有A和O的优势，且没有弱点。", type: "exclusive"},
            {name: "绝缘体", color: "SS", cost: 5500, desc: "你对所有信息素攻击免疫。Alpha的压制对你无效，Omega的诱惑对你无效。你是唯一的自由人。", type: "exclusive"},
            {name: "费洛蒙操纵", color: "S", cost: 2000, desc: "你可以精细操控自己的费洛蒙，模拟出任何味道，甚至模拟出毒气的效果。", type: "exclusive"},
            {name: "顶级黑客", color: "A", cost: 950, desc: "你可以入侵联邦的基因数据库，修改任何人的性别档案和匹配记录。", type: "exclusive"},
            {name: "商业奇才", color: "B", cost: 600, desc: "你拥有敏锐的商业嗅觉，能在抑制剂市场中翻云覆雨，建立自己的商业帝国。", type: "exclusive"},
            {name: "野性直觉", color: "B", cost: 450, desc: "像野兽一样敏锐的直觉，能察觉到周围潜伏的掠食者或猎物。", type: "exclusive"},
            {name: "药物大师", color: "A", cost: 800, desc: "你能调配出改变性别的禁药，或者让Alpha瞬间失去战斗力的软骨散。", type: "exclusive"}
        ]
    },
    {
        name: "502.[原创]古代ABO-鸾凤皇朝",
        desc: "一个古风架空的ABO世界。乾元(Alpha)为尊，中庸(Beta)为民，坤泽(Omega)为贵/宠。皇权与信香(信息素)紧密结合。宫廷斗争、边疆战事都围绕着血脉与信香展开。",
        boss: "女帝(天乾)-武曌, 摄政王(天乾)-李承鄞, 倾国妖妃(地坤)-苏妲己",
        identities: [
            { name: "冷宫废后的皇子(未分化)", items: "一块碎裂的玉佩, 一本泛黄的诗书" },
            { name: "边疆戍边的低级军官(中庸)", items: "一把制式长枪, 一壶劣质烧酒" },
            { name: "被进贡的和亲质子(坤泽)", items: "一身华丽却束缚的嫁衣, 一个藏在袖中的毒囊" },
            { name: "御医院的捣药学徒", items: "一个药葫芦, 一本信香调理手册" },
            { name: "京城最大的青楼头牌(坤泽)", items: "一把名贵的琵琶, 无数达官贵人的名帖" }
        ],
        talents: [
            {name: "雨露期紊乱", color: "E", cost: 20, desc: "你的雨露期(发情期)毫无规律可言，随时可能当众出丑，这在礼教森严的古代是致命的。", type: "exclusive"},
            {name: "石女/石男(无信香)", color: "D", cost: 60, desc: "你天生没有信香腺体，被视为残疾，无法与乾元或坤泽结合，受尽冷眼。", type: "exclusive"},
            {name: "宫廷礼仪", color: "C", cost: 100, desc: "你精通宫廷繁文缛节，知道如何跪拜、如何回话才不会被砍头。生存的基础技能。", type: "exclusive"},
            {name: "琴棋书画", color: "C", cost: 150, desc: "才艺是坤泽最好的嫁妆，也是乾元附庸风雅的工具。有一技之长总能获得优待。", type: "exclusive"},
            {name: "香道高手", color: "B", cost: 350, desc: "你擅长调制各种香料，既能掩盖信香，也能用熏香暗中影响他人的情绪和判断。", type: "exclusive"},
            {name: "天生神力(乾元)", color: "A", cost: 800, desc: "作为乾元，你力能扛鼎。在冷兵器时代，这是成为猛将的最佳天赋。", type: "exclusive"},
            {name: "倾国倾城(坤泽)", color: "A", cost: 900, desc: "你的容貌绝美，信香更是令人沉醉。你是红颜祸水，足以让君王不早朝。", type: "exclusive"},
            {name: "医毒双绝", color: "A", cost: 950, desc: "你既能调理信香紊乱，也能配置让人终身无法分化的绝子药。宫斗必备。", type: "exclusive"},
            {name: "隐忍不发", color: "B", cost: 500, desc: "你极擅长忍耐。无论是乾元的压制还是肉体的折磨，你都能面不改色，等待反击的机会。", type: "exclusive"},
            {name: "帝王之气", color: "S", cost: 1800, desc: "天生的上位者威压。即使你现在只是个乞丐，一旦释放信香，也能让周围的人忍不住臣服。", type: "exclusive"},
            {name: "孕育圣体", color: "S", cost: 1600, desc: "作为坤泽，你极易受孕，且必生出高阶乾元子嗣。在母凭子贵的皇宫，这是最强的护身符。", type: "exclusive"},
            {name: "信香伪装术", color: "S", cost: 1700, desc: "失传的秘术。你可以将自己的信香伪装成中庸甚至相反的性别，瞒天过海。", type: "exclusive"},
            {name: "读心术(信香)", color: "S", cost: 1900, desc: "你可以通过分辨他人信香中微弱的情绪波动，读出他们内心的真实想法。", type: "exclusive"},
            {name: "龙凤呈祥", color: "SS", cost: 6000, desc: "你与国运相连。你的情绪波动会影响天象，你的安危关系到皇朝的兴衰。", type: "exclusive"},
            {name: "天命乾元", color: "SS", cost: 7000, desc: "你是传说中的天命之子，信香能压制所有乾元。注定要统一乱世，登基称帝。", type: "exclusive"},
            {name: "祸世妖姬", color: "SS", cost: 6500, desc: "你的信香带有强烈的致幻和成瘾性。任何闻过你信香的人都会成为你的傀儡，为你生为你死。", type: "exclusive"},
            {name: "长生不老", color: "SSS", cost: 15000, desc: "你服用了不死药，容颜永驻，寿元无尽。你将见证无数皇朝的兴起与覆灭。", type: "exclusive"},
            {name: "万香之主", color: "SSS", cost: 13000, desc: "你可以控制世间所有的香气。你可以让花草枯萎，也可以让千里之外的敌人暴毙。", type: "exclusive"},
            {name: "转世重修", color: "SSS", cost: 14000, desc: "你带着前世的记忆和满级技能重生。这一世，你要弥补所有的遗憾，杀尽负心人。", type: "exclusive"},
            {name: "暗卫首领", color: "A", cost: 900, desc: "你拥有一支只忠于你的死士暗卫。他们是你藏在阴影里的利刃。", type: "exclusive"},
            {name: "富可敌国", color: "S", cost: 2000, desc: "你拥有聚宝盆般的经商天赋。在这个乱世，钱能通神，也能买命。", type: "exclusive"},
            {name: "百毒不侵", color: "S", cost: 1500, desc: "任何毒药对你都无效。在充满阴谋诡计的皇宫，你可以放心大胆地吃喝。", type: "exclusive"},
            {name: "骑射无双", color: "B", cost: 450, desc: "你在马背上长大，箭术通神。在这个冷兵器战场，你是敌人的噩梦。", type: "exclusive"},
            {name: "巧舌如簧", color: "C", cost: 180, desc: "你能在朝堂上舌战群儒，也能在后宫中搬弄是非。语言是你最锋利的武器。", type: "exclusive"},
            {name: "过目不忘", color: "B", cost: 400, desc: "你记性极好，看过的奏折、秘闻、地图都能印在脑子里。", type: "exclusive"}
        ]
    },
    {
        name: "503.[原创]机甲星际争霸-钢铁视界",
        desc: "人类与虫族、神族在星海中混战的未来世界。机甲是男人的浪漫，也是战争的主宰。巨舰大炮，虫海淹没，灵能风暴。这是一个属于强者和钢铁的时代。",
        boss: "虫族主宰-凯瑞甘, 帝国元帅-雷诺, 星灵执政官-塔萨达",
        identities: [
            { name: "殖民星球的矿工", items: "一把激光挖掘镐, 一个简易氧气面罩" },
            { name: "坠毁战舰的幸存新兵", items: "一把只有半个弹夹的高斯步枪, 破损的动力装甲" },
            { name: "星际海盗的底层喽啰", items: "一把热能匕首, 一张藏宝图残片" },
            { name: "机甲废弃场的拾荒者", items: "一个多功能扳手, 一块还能用的能量电池" },
            { name: "被遗弃的实验体(半虫人)", items: "变异的利爪, 无法取下的拘束器" }
        ],
        talents: [
            {name: "晕机症", color: "E", cost: 20, desc: "你天生前庭神经敏感，一上飞船或机甲就吐得昏天黑地。在星际时代，你基本告别了太空。", type: "exclusive"},
            {name: "基因崩溃", color: "D", cost: 80, desc: "你的基因链不稳定，随时可能发生畸变或器官衰竭。你需要长期服用昂贵的稳定剂。", type: "exclusive"},
            {name: "机械维修", color: "C", cost: 150, desc: "你擅长修理各种机械设备。在太空中，一个好的维修工比一个战士更受欢迎。", type: "exclusive"},
            {name: "驾驶精通(民用)", color: "C", cost: 120, desc: "你能熟练驾驶各种民用飞船和工程机甲，虽然不能打仗，但跑路和干活没问题。", type: "exclusive"},
            {name: "电子黑客", color: "B", cost: 400, desc: "你能入侵大部分民用网络和低级军用系统，窃取情报或控制自动炮台。", type: "exclusive"},
            {name: "枪械专精", color: "B", cost: 350, desc: "你精通各种单兵轻武器，从高斯步枪到等离子手枪，你是地面的死神。", type: "exclusive"},
            {name: "灵能敏感", color: "B", cost: 500, desc: "你能感觉到周围的灵能波动，甚至能进行微弱的心灵感应。这是成为幽灵特工的潜质。", type: "exclusive"},
            {name: "机甲同步率S", color: "A", cost: 900, desc: "你与机甲的神经同步率高达90%以上。机甲就是你的身体，你能做出各种匪夷所思的战术动作。", type: "exclusive"},
            {name: "虫群亲和", color: "A", cost: 850, desc: "低阶虫族不会主动攻击你，甚至会把你当成同类。你可以安全地穿越虫占区。", type: "exclusive"},
            {name: "战术指挥", color: "A", cost: 950, desc: "你拥有卓越的指挥才能，能在大规模星战中冷静分析局势，指挥舰队反败为胜。", type: "exclusive"},
            {name: "新人类(调整者)", color: "S", cost: 1800, desc: "经过基因调整的新人类，智力、体能、反应速度都是常人的两倍。天生的精英。", type: "exclusive"},
            {name: "王牌机师", color: "S", cost: 2000, desc: "你是星空中的传奇。给你一台机甲，你能单挑一整支舰队。你的名字能止小儿夜啼。", type: "exclusive"},
            {name: "灵能风暴", color: "S", cost: 2200, desc: "你觉醒了强大的灵能，可以释放大范围的灵能闪电，瞬间摧毁成片的敌人。", type: "exclusive"},
            {name: "机械之心", color: "S", cost: 1900, desc: "你可以直接用大脑连接并控制任何电子设备，无需接口。你是网络世界的神。", type: "exclusive"},
            {name: "泰坦机甲召唤", color: "SS", cost: 7000, desc: "你可以随时召唤一台泰坦级战略机甲从天而降。这是足以毁灭地表的终极兵器。", type: "exclusive"},
            {name: "虫群之心", color: "SS", cost: 6500, desc: "你可以控制一支庞大的虫族军队。甚至可以进化出属于你自己的虫族兵种。", type: "exclusive"},
            {name: "星灵科技传承", color: "SS", cost: 6000, desc: "你获得了失落的星灵科技数据库。折跃技术、护盾技术、光子炮，你掌握了黑科技。", type: "exclusive"},
            {name: "时间领主", color: "SSS", cost: 15000, desc: "你可以操控局部的时间流速。让敌人的炮弹静止，或者让自己加速到光速。", type: "exclusive"},
            {name: "灭世级灵能", color: "SSS", cost: 16000, desc: "你的灵能强度足以引爆恒星。你是行走的人形核弹，星际文明的终结者。", type: "exclusive"},
            {name: "维度行者", color: "SSS", cost: 14000, desc: "你可以肉身穿越维度，无视物理距离和障碍。任何防御对你来说都不存在。", type: "exclusive"},
            {name: "再生装甲", color: "S", cost: 1700, desc: "你的机甲拥有生物金属特性，受损后可以自动修复。只要核心不毁，你就不会败。", type: "exclusive"},
            {name: "预知未来", color: "SS", cost: 8000, desc: "你可以看到未来几分钟的战场走向。所有的伏击和陷阱对你都无效。", type: "exclusive"},
            {name: "空间折跃", color: "S", cost: 2100, desc: "你可以进行短距离的空间瞬移。无论是切入战场还是逃命，都神出鬼没。", type: "exclusive"},
            {name: "能量吸收", color: "A", cost: 900, desc: "你的机甲可以吸收敌人的能量攻击转化为自身的护盾或弹药。", type: "exclusive"},
            {name: "星图猎人", color: "B", cost: 450, desc: "你脑中有详尽的星图，知道每一条隐秘的航道和虫洞。没人能在大海星抓到你。", type: "exclusive"}
        ]
    },
              {
        name: "504.[原创]洪荒神话世界-太古纪元",
        desc: "天地初开，万族林立。神魔遍地走，金仙不如狗。这是力量层级最高的世界，讲究跟脚、气运和因果。圣人之下皆蝼蚁，量劫之下皆灰灰。",
        boss: "道祖-鸿钧, 魔祖-罗睺, 妖族二帝-帝俊/太一",
        identities: [
            { name: "不周山脚下的一块顽石", items: "沾染了一丝盘古气息的石皮" },
            { name: "龙凤大劫战场的炮灰", items: "断裂的龙角, 沾血的凤羽" },
            { name: "人族部落的先天人族", items: "一件兽皮衣, 一团燧人氏钻出的火种" },
            { name: "截教外门记名弟子", items: "一把低阶飞剑, 一本上清道法残篇" },
            { name: "天庭看守南天门的小兵", items: "制式天兵甲胄, 一把长戟" }
        ],
        talents: [
            {name: "跟脚浅薄", color: "E", cost: 50, desc: "你只是洪荒最普通的后天生灵，修炼速度极慢，上限也就是个地仙，随时可能被路过的大能踩死。", type: "exclusive"},
            {name: "业力缠身", color: "D", cost: 100, desc: "你前世造孽太多，业火焚身。修炼时心魔丛生，渡劫时雷劫威力翻倍，喝水都塞牙。", type: "exclusive"},
            {name: "先天道体", color: "C", cost: 200, desc: "人族特有的体质，虽然肉身孱弱，但极其适合感悟天道，修炼速度尚可。", type: "exclusive"},
            {name: "炼器童子", color: "C", cost: 180, desc: "你在兜率宫给老君扇过火，虽然没学到真本事，但对火焰和炼器的理解远超常人。", type: "exclusive"},
            {name: "五行亲和", color: "B", cost: 500, desc: "你天生亲和五行灵气，修炼五行遁术事半功倍，保命能力不错。", type: "exclusive"},
            {name: "巫族血脉(稀薄)", color: "B", cost: 600, desc: "你拥有一丝巫族血统，肉身强悍，力大无穷，但这也会让你被妖族视为死敌。", type: "exclusive"},
            {name: "福缘深厚", color: "A", cost: 900, desc: "出门捡宝，遇难成祥。在这个讲究气运的世界，福缘比资质更重要。", type: "exclusive"},
            {name: "九转玄功(前三层)", color: "A", cost: 950, desc: "盘古大神的证道功法。虽然只有前三层，但也足以让你肉身成圣，同阶无敌。", type: "exclusive"},
            {name: "三昧真火", color: "A", cost: 850, desc: "你掌握了道家无上真火，无物不焚，专克各种妖魔鬼怪。", type: "exclusive"},
            {name: "落宝金钱(仿)", color: "S", cost: 1800, desc: "虽然是仿品，但也能落下一部分后天灵宝。在法宝对轰的洪荒，这是神技。", type: "exclusive"},
            {name: "五色神光(残)", color: "S", cost: 2000, desc: "孔宣的成名绝技。虽然不完整，但也能刷走大部分五行之内的兵器法宝。", type: "exclusive"},
            {name: "十二都天神煞大阵(阵图)", color: "S", cost: 2500, desc: "巫族镇族大阵。集齐十二人可召唤盘古真身。虽然你只有阵图，但也足以镇压一方。", type: "exclusive"},
            {name: "先天灵宝伴生", color: "SS", cost: 6000, desc: "你出生时怀抱一件下品先天灵宝。这既是你的护道之物，也是惹祸的根源。", type: "exclusive"},
            {name: "准圣讲道", color: "SS", cost: 5000, desc: "你曾有幸听过准圣大能讲道，对法则的领悟远超同阶，瓶颈对你来说不存在。", type: "exclusive"},
            {name: "功德金轮", color: "SS", cost: 7000, desc: "你拥有海量天道功德护体。万法不侵，诸邪退避。谁敢杀你，必遭天谴。", type: "exclusive"},
            {name: "盘古精血", color: "SSS", cost: 15000, desc: "你融合了一滴盘古心头血。你是盘古正宗，肉身潜力无限，有望以力证道。", type: "exclusive"},
            {name: "混沌钟(东皇钟)", color: "SSS", cost: 20000, desc: "先天至宝，攻防一体。镇压鸿蒙气运。拥有它，你就是圣人之下第一人。", type: "exclusive"},
            {name: "一气化三清", color: "SSS", cost: 18000, desc: "太清圣人的绝学。可以分出三个实力与本体相当的化身，群殴无敌。", type: "exclusive"},
            {name: "圣人门徒(亲传)", color: "SS", cost: 8000, desc: "你是某位圣人的亲传弟子。后台硬得没边，只要不作死，洪荒横着走。", type: "exclusive"},
            {name: "钉头七箭书", color: "S", cost: 2200, desc: "因果律诅咒法宝。只要知道名字和生辰八字，大罗金仙也得拜死。", type: "exclusive"},
            {name: "纵地金光", color: "A", cost: 800, desc: "元始天尊所传遁术，瞬息万里，逃跑赶路必备。", type: "exclusive"},
            {name: "天罡三十六变", color: "S", cost: 1900, desc: "大神通。斡旋造化，颠倒阴阳。不仅是变化之术，更是改天换地的大法力。", type: "exclusive"},
            {name: "诛仙阵图", color: "SSS", cost: 25000, desc: "非四圣不可破。主宰杀伐的终极阵图。一旦布下，重炼地水火风。", type: "exclusive"},
            {name: "混沌魔神转世", color: "SSS", cost: 30000, desc: "你保留了混沌魔神的真灵。你修的不是天道，而是大道。你的目标是超脱。", type: "exclusive"},
            {name: "量劫主角", color: "SS", cost: 9000, desc: "你是本次量劫的应劫之人（如姜子牙、申公豹）。虽然危险，但也是最大的机缘所在。", type: "exclusive"}
        ]
    },
    {
        name: "505.[原创]勇者斗恶龙日式西幻-艾泽利亚",
        desc: "经典的JRPG世界。勇者、魔王、公主、巨龙。画风清新但内核可能很黑深残。回合制战斗（或许），等级森严的职业体系，以及无处不在的史莱姆。",
        boss: "魔王-巴尔, 堕落勇者-西格玛, 远古黑龙-尼德霍格",
        identities: [
            { name: "新手村的村民A", items: "一把木剑, 一个布甲, 5个金币" },
            { name: "被魔王军灭国的亡国公主/王子", items: "一枚王室戒指, 一件破损的礼服" },
            { name: "冒险者公会的柜台小姐/小哥", items: "一本任务登记簿, 一支羽毛笔" },
            { name: "森林里的见习魔法师", items: "一根枯木法杖, 一本初级火球术" },
            { name: "被召唤的异世界高中生(无挂版)", items: "一身校服, 一个智能手机(没网)" }
        ],
        talents: [
            {name: "路人脸", color: "E", cost: 10, desc: "你的长相毫无特色，走进人群就消失。作为NPC很合格，但作为主角很悲剧。", type: "exclusive"},
            {name: "史莱姆体质", color: "D", cost: 50, desc: "你的身体软绵绵的，物理防御极低，但对钝器打击有一定抗性。容易被当成怪刷了。", type: "exclusive"},
            {name: "村民的智慧", color: "C", cost: 100, desc: "你熟知种田、修补房屋和寻找走失宠物的技巧。适合在新手村养老。", type: "exclusive"},
            {name: "初级剑术", color: "C", cost: 150, desc: "你学会了基础的劈砍和格挡。打打哥布林还行，遇到兽人就得跑。", type: "exclusive"},
            {name: "鉴定眼", color: "B", cost: 350, desc: "你能看到物品的名称、属性和耐久度。避免买到假货，也能发现隐藏道具。", type: "exclusive"},
            {name: "回复术士", color: "B", cost: 450, desc: "你会使用初级治疗魔法。在任何队伍里都是受欢迎的奶妈，只要你不黑化。", type: "exclusive"},
            {name: "魔物亲和", color: "B", cost: 500, desc: "低级魔物不会主动攻击你，你甚至可以驯服它们作为宠物。", type: "exclusive"},
            {name: "会心一击", color: "A", cost: 850, desc: "你的攻击有一定几率造成暴击，伤害翻倍。这是欧皇的专属技能。", type: "exclusive"},
            {name: "勇者青梅竹马", color: "A", cost: 900, desc: "你和当代的勇者一起长大。虽然你可能不强，但勇者会拼死保护你。", type: "exclusive"},
            {name: "全属性魔法", color: "S", cost: 1800, desc: "你精通地水火风光暗所有属性的魔法。人形自走炮台。", type: "exclusive"},
            {name: "二刀流奥义", color: "S", cost: 1900, desc: "你可以双手同时持剑攻击，攻速加倍，且没有副手惩罚。帅就完事了。", type: "exclusive"},
            {name: "勇者血统", color: "SS", cost: 6000, desc: "你流淌着传说中勇者的血液。拔出圣剑的唯一人选，成长属性极高。", type: "exclusive"},
            {name: "魔王转生", color: "SS", cost: 7000, desc: "你其实是上一代魔王的转世。拥有恐怖的魔力潜能，一旦觉醒，天下大乱。", type: "exclusive"},
            {name: "读档(Save/Load)", color: "SSS", cost: 15000, desc: "你可以在特定的‘女神像’处存档，死后可以读档重来。真正的玩家特权。", type: "exclusive"},
            {name: "修改器(锁血)", color: "SSS", cost: 20000, desc: "你的生命值被锁定，永远不会低于1点。除非剧情杀，否则你就是不死的。", type: "exclusive"},
            {name: "经验值百倍", color: "SS", cost: 5000, desc: "你获取经验值的速度是常人的百倍。升级如喝水，一天满级不是梦。", type: "exclusive"},
            {name: "圣女的加护", color: "S", cost: 1600, desc: "你受到教会圣女的祝福，对负面状态（中毒、麻痹、诅咒）有极高的抗性。", type: "exclusive"},
            {name: "偷窃技能", color: "B", cost: 400, desc: "你可以从怪物甚至NPC身上偷取物品。包括但不限于金币、药水、甚至内衣。", type: "exclusive"},
            {name: "限界突破", color: "SSS", cost: 12000, desc: "你的等级没有上限（通常人99级）。你可以无限变强，一拳打爆魔王。", type: "exclusive"},
            {name: "后宫男主光环", color: "SS", cost: 6500, desc: "无论你做什么，公主、女骑士、魔女都会对你产生好感。修罗场预定。", type: "exclusive"},
            {name: "自动战斗", color: "A", cost: 950, desc: "你可以开启托管模式，身体会自动做出最优的战斗反应，完美闪避和反击。", type: "exclusive"},
            {name: "道具大师", color: "B", cost: 300, desc: "你使用任何道具的效果翻倍。普通的药草也能发挥出圣药的效果。", type: "exclusive"},
            {name: "龙骑士", color: "S", cost: 2200, desc: "你拥有驾驭巨龙的资格。骑龙作战，空战无敌。", type: "exclusive"},
            {name: "绝对防御", color: "SS", cost: 5500, desc: "你可以展开一个无敌的结界，持续10秒。关键时刻的保命神技。", type: "exclusive"},
            {name: "语言通晓", color: "C", cost: 120, desc: "你能听懂所有种族的语言，包括魔物语和古代语。", type: "exclusive"}
        ]
    },
    {
        name: "506.[原创]日本战国-修罗之刻",
        desc: "烽火连天的日本战国时代。大名割据，武士道与忍术并存。这不是历史课本，而是充满了妖魔、剑豪和野心的修罗场。下克上是常态，活着是奢望。",
        boss: "第六天魔王-织田信长, 军神-上杉谦信, 剑圣-上泉信纲",
        identities: [
            { name: "战场上的足轻(步兵)", items: "一根竹枪, 一个斗笠, 一袋干粮" },
            { name: "流浪的浪人武士", items: "一把打刀, 一把胁差, 一个酒葫芦" },
            { name: "伊贺里的下忍", items: "几枚手里剑, 一身夜行衣" },
            { name: "落魄公卿的随从", items: "一把折扇, 一本和歌集" },
            { name: "战火孤儿", items: "一个捡来的饭团, 满脸的泥土" }
        ],
        talents: [
            {name: "营养不良", color: "E", cost: 20, desc: "长期饥饿导致你身体瘦弱，挥刀没力气，跑两步就晕。在乱世，这是饿死鬼的预备役。", type: "exclusive"},
            {name: "瘸腿", color: "D", cost: 60, desc: "你的腿有残疾，无法奔跑。在溃败逃命时，你绝对是第一个被追兵砍死的。", type: "exclusive"},
            {name: "铁炮操作", color: "C", cost: 150, desc: "你懂得如何装填和发射火绳枪。虽然装填慢，但能对重甲武士造成致命威胁。", type: "exclusive"},
            {name: "茶道", color: "C", cost: 120, desc: "你精通茶道。这在大名和高级武士之间是高雅的社交技能，能让你混入上流圈子。", type: "exclusive"},
            {name: "骑术", color: "B", cost: 350, desc: "你擅长骑马。在这个时代，骑兵是战场上的坦克，也是逃命的法拉利。", type: "exclusive"},
            {name: "居合斩", color: "B", cost: 500, desc: "拔刀术。讲究一击必杀。在突发战斗中，你能比对手更快出刀。", type: "exclusive"},
            {name: "忍术·替身", color: "B", cost: 450, desc: "关键时刻可以用木桩代替自己承受伤害。保命神技，但消耗查克拉（体力）。", type: "exclusive"},
            {name: "兵法家", color: "A", cost: 850, desc: "你熟读孙子兵法，懂得排兵布阵。如果你能成为大名的军师，就能左右战局。", type: "exclusive"},
            {name: "剑豪资质", color: "A", cost: 900, desc: "你拥有成为剑豪的天赋。燕返、无刀取等绝技你一学就会。", type: "exclusive"},
            {name: "影武者", color: "A", cost: 800, desc: "你长得极像某位大名。你可以成为他的替身，享受荣华富贵，也要替他挡刀。", type: "exclusive"},
            {name: "妖刀持有者", color: "S", cost: 1800, desc: "你拥有一把渴血的妖刀（如村正）。它能大幅提升你的战力，但会不断侵蚀你的理智。", type: "exclusive"},
            {name: "第六天魔王(伪)", color: "S", cost: 2000, desc: "你身上带有信长的霸气。对佛神无敬畏，对敌人无怜悯。统率力MAX，魔抗MAX。", type: "exclusive"},
            {name: "不死之身(诅咒)", color: "SS", cost: 6000, desc: "你吃了人鱼肉或被妖魔诅咒，无法死去。即使被砍成肉泥也能复原。求死不能的痛苦。", type: "exclusive"},
