            {name: "模因抗性(顶级)", color: "S", cost: 2800, desc: "你的大脑结构特殊，能够免疫绝大多数视觉、听觉触发的模因杀戮媒介或认知危害。", type: "exclusive"},
            {name: "O5议会权限", color: "SS", cost: 9500, desc: "你拥有基金会的最高权限，可以查阅所有机密文档，调动“红右手”特遣队，甚至批准使用核武器。", type: "exclusive"},
            {name: "SCP-500(万能药)", color: "S", cost: 3000, desc: "你开局自带一片SCP-500。只要还没死透，吞下它就能瞬间治愈所有疾病、伤势和异常状态。", type: "exclusive"},
            {name: "塔乌米尔(Thaumiel)级适应性", color: "SS", cost: 8000, desc: "你本身就是一个异常，但你的特性可以用来收容其他异常。你对大多数Keter级收容物有天然的压制力。", type: "exclusive"},
            {name: "不可观测者(反模因)", color: "A", cost: 1500, desc: "你自带反模因属性。人们会下意识地忽略你的存在，即使你站在他们面前。监控也无法记录你的身影。", type: "exclusive"},
            {name: "奇术师(蓝型)", color: "A", cost: 1200, desc: "你掌握了现代魔法（奇术），能够利用EVE粒子进行防御、攻击或传送，是GOC物理部门的核心战力。", type: "exclusive"},
            {name: "914精加工体质", color: "B", cost: 600, desc: "你曾意外进入SCP-914并以“精加工”档位输出。你的身体素质、智力和反应速度都得到了完美的优化。", type: "exclusive"},
            {name: "克莱夫博士的运气", color: "S", cost: 2500, desc: "你是个不可救药的混蛋，但你总是能在必死的收容失效中活下来，并且顺手泡到几个异常实体。", type: "exclusive"},
            {name: "肉体改造(萨尔克教)", color: "A", cost: 1000, desc: "你信奉血肉飞升，能够控制自身的骨骼和肌肉生长，将其变成致命的武器或护甲。", type: "exclusive"},
            {name: "破碎之神义肢", color: "A", cost: 1100, desc: "你的手臂被替换为麦卡恩的神性金属，拥有无法摧毁的硬度，并能与任何电子设备直接连接。", type: "exclusive"},
            {name: "D级幸存者", color: "C", cost: 200, desc: "你在基金会活过了三个月。你极其擅长在混乱中装死、躲藏和利用环境逃生。", type: "exclusive"},
            {name: "异常直觉", color: "B", cost: 450, desc: "当周围出现休谟指数波动或异常效应时，你会感到剧烈的头痛，这既是预警也是折磨。", type: "exclusive"},
            {name: "万界图书馆借阅证", color: "S", cost: 2200, desc: "你可以通过特殊的路径进入流浪者的图书馆，获取无数平行世界的知识，只要你遵守那里的规矩。", type: "exclusive"},
            {name: "因果律锚点", color: "SSS", cost: 38000, desc: "你是世界的基石之一。如果你的死亡会导致世界毁灭，那么因果律会强行扭曲概率让你活下来。", type: "exclusive"}
        ]
    },
    {
        name: "514.龙与地下城",
        desc: "费伦大陆，剑与魔法的经典世界。诸神行走于凡间，巨龙盘踞在财宝之上。冒险者们探索地下城，书写传奇。",
        boss: "提亚玛特(恶龙之母), 维克那(巫妖神), 罗丝(蛛后), 塔拉斯克巨兽",
        identities: [
            { name: "路边的乞讨者", items: "一个破碗, 满身跳蚤" },
            { name: "一级人类战士", items: "长剑, 链甲衫, 冒险者背包" },
            { name: "地精部落的斥候", items: "生锈的短刀, 臭气熏天的皮甲" },
            { name: "法师塔的学徒", items: "法术书(只有0环戏法), 墨水笔" },
            { name: "偏远村庄的守卫", items: "长矛, 木盾, 劣质烟草" }
        ],
        talents: [
            {name: "祈愿术(Wish)", color: "SSS", cost: 50000, desc: "掌握九环法术的巅峰。你可以通过许愿来改变现实，复制任何法术，甚至逆转时间，但代价由DM决定。", type: "exclusive"},
            {name: "神眷之魂(术士)", color: "S", cost: 2500, desc: "你的血脉中流淌着神性的力量。你不需要学习就能释放神术，并且天生拥有一对光翼。", type: "exclusive"},
            {name: "传奇抗性", color: "SS", cost: 8000, desc: "作为传奇生物的特权。当你豁免检定失败时，你可以选择直接成功。每天只有几次机会，但这足以逆转战局。", type: "exclusive"},
            {name: "超魔专长", color: "A", cost: 1200, desc: "你可以扭曲法术的规则。瞬发法术、强效法术、默发法术，让你的魔法在敌人反应过来之前就将其轰杀。", type: "exclusive"},
            {name: "野蛮人狂暴", color: "B", cost: 500, desc: "在战斗中进入狂暴状态，力量和体质大幅提升，对物理伤害有极高的抗性，但无法使用复杂的技能。", type: "exclusive"},
            {name: "幸运(专长)", color: "S", cost: 2200, desc: "你拥有能够扭曲概率的运气。每天你可以重骰三次任何攻击、属性检定或豁免检定，取最好的结果。", type: "exclusive"},
            {name: "吸血鬼领主模板", color: "S", cost: 3000, desc: "你获得了真正吸血鬼的力量：不死之身、变形、支配人类、再生。但你畏惧阳光和流动的水。", type: "exclusive"},
            {name: "巨龙血脉", color: "A", cost: 1500, desc: "你拥有真龙的血统，天生拥有高护甲的鳞片，并且能喷吐对应的元素龙息。", type: "exclusive"},
            {name: "游荡者闪避", color: "B", cost: 450, desc: "当受到范围攻击时，如果通过敏捷豁免，你将毫发无伤。你的反应速度快得惊人。", type: "exclusive"},
            {name: "吟游诗人激励", color: "C", cost: 200, desc: "你的嘴炮和音乐能给予队友实质性的力量，提升他们的战斗表现，或者通过嘲讽让敌人心态崩溃。", type: "exclusive"},
            {name: "多重攻击", color: "A", cost: 1000, desc: "经过严格训练，你可以在这一轮动作中发动比常人多一倍的攻击次数。", type: "exclusive"},
            {name: "巫妖命匣", color: "SS", cost: 9500, desc: "你将灵魂藏在命匣中。只要命匣不毁，哪怕身体化为灰烬，你也能在几天后复活。你是永恒的亡灵大法师。", type: "exclusive"},
            {name: "神圣复仇者(羁绊)", color: "S", cost: 3500, desc: "你注定会获得一把拥有自我意识的圣剑。它能驱散魔法，斩杀邪恶，并为你提供强大的魔法抗性。", type: "exclusive"},
            {name: "位面传送", color: "A", cost: 1800, desc: "你掌握了穿越位面的能力，可以逃往火元素位面、阴影位面等地，或者将敌人放逐到虚空。", type: "exclusive"},
            {name: "地下城主(DM)的青睐", color: "SSS", cost: 40000, desc: "你似乎能听到掷骰子的声音。世界意志偏向你，必死的攻击会打偏，宝箱里总是你需要的装备。", type: "exclusive"}
        ]
    },
    {
        name: "515.万智牌",
        desc: "多元宇宙由无数个时空组成，包括拉尼卡、赞迪卡、依尼翠等。鹏洛客们点燃火花，穿梭于时空之间，利用五色法术力战斗。",
        boss: "尼克·波拉斯(龙神), 绝望终局伊莫库(奥札奇), 艾蕾侬(机械之母), 约格莫夫",
        identities: [
            { name: "拉尼卡公会的无名小卒", items: "公会徽章, 匕首" },
            { name: "依尼翠的受惊村民", items: "木桩, 大蒜, 破旧的农具" },
            { name: "赞迪卡的探险向导", items: "攀岩绳索, 晶石碎片" },
            { name: "新非瑞克西亚的实验体", items: "被植入的金属管, 腐蚀的肢体" },
            { name: "卡拉德许的发明家学徒", items: "乙太护目镜, 扳手" }
        ],
        talents: [
            {name: "鹏洛客火花", color: "SSS", cost: 50000, desc: "百万分之一的概率。你的灵魂中拥有火花，觉醒后可以自由穿越多元宇宙，成为超越凡人的存在。", type: "exclusive"},
            {name: "法术力连接(全色)", color: "SS", cost: 8500, desc: "你可以自由汲取并转化白、蓝、黑、红、绿五种颜色的法术力，不受地脉限制，施展任何类型的魔法。", type: "exclusive"},
            {name: "奥札奇泰坦化身", color: "SSS", cost: 45000, desc: "你是虚空吞噬者的化身。你的存在本身就会扭曲现实，吞噬世界的法术力，将万物化为尘埃。", type: "exclusive"},
            {name: "完化(非瑞克西亚)", color: "S", cost: 2800, desc: "你的血肉已被烁油完美改造。你没有痛觉，忠诚于机械之母，拥有金属的身躯和传播感染的能力。", type: "exclusive"},
            {name: "精神塑师", color: "S", cost: 2500, desc: "擅长蓝色法术力。你可以读取思维、修改记忆、制造幻象，甚至直接摧毁对手的心智。", type: "exclusive"},
            {name: "死灵术士", color: "A", cost: 1200, desc: "擅长黑色法术力。你可以复活死者为你作战，或者通过献祭生命来换取强大的力量。", type: "exclusive"},
            {name: "鬼怪召唤师", color: "B", cost: 500, desc: "擅长红色法术力。你可以瞬间召唤成百上千只疯狂的鬼怪，虽然它们很弱且容易自爆，但数量就是力量。", type: "exclusive"},
            {name: "神器师", color: "A", cost: 1000, desc: "你擅长制造和操控神器。无论是巨大的构装体还是精密的乙太装置，在你手中都能发挥最大威力。", type: "exclusive"},
            {name: "德鲁伊誓约", color: "B", cost: 600, desc: "擅长绿色法术力。你可以加速植物生长，召唤巨兽，并从大自然中汲取源源不断的生命力。", type: "exclusive"},
            {name: "天使契约", color: "A", cost: 1500, desc: "擅长白色法术力。你与天使军团签订了契约，可以召唤天使守护，通过秩序和法律来束缚敌人。", type: "exclusive"},
            {name: "烁油免疫", color: "S", cost: 2000, desc: "你的体质特殊，能够抵抗非瑞克西亚烁油的完化感染，这在对抗新非瑞克西亚时是至关重要的能力。", type: "exclusive"},
            {name: "时间法师", color: "SS", cost: 9000, desc: "你可以操控时间流。获得额外的回合，将物体送回过去，或者让瞬间变为永恒。", type: "exclusive"},
            {name: "传奇生物光环", color: "A", cost: 1800, desc: "你被视为传奇生物。普通的小法术无法瞄准你，你在战场上不仅战力强大，还能为友军提供光环加成。", type: "exclusive"},
            {name: "地落", color: "C", cost: 300, desc: "每当你踏入一片新的土地或建立法术力连接时，你的力量就会得到一次短暂的爆发。", type: "exclusive"},
            {name: "反击咒语大师", color: "A", cost: 1600, desc: "你极其擅长打断别人的施法。只要你还有法术力，任何试图在你面前施法的人都要面临失败的风险。", type: "exclusive"}
        ]
    },
              {
        name: "516.我独自升级",
        desc: "世界各地出现连接异次元的‘传送门’，魔兽涌入。只有觉醒成为‘猎人’的人类才能与之对抗。而在最弱兵器程肖宇濒死之际，一个名为‘系统’的界面出现在他眼前。",
        boss: "安塔利斯(毁灭君王), 也是本(冰雪君王), 绝对者(神), 建筑师",
        identities: [
            { name: "E级猎人(矿工)", items: "一把磨损的镐头, 满身煤灰的防护服" },
            { name: "猎人协会监察科职员", items: "魔力测量仪, 黑色西装, 墨镜" },
            { name: "大型公会攻击队挑夫", items: "巨大的背包, 几瓶劣质魔力药水" },
            { name: "双重地下城幸存者", items: "断掉的一条腿, 对石像的心理阴影" },
            { name: "觉醒者学校的学生", items: "未完全掌握的魔力球, 学生证" }
        ],
        talents: [
            {name: "暗影君王(继承者)", color: "SSS", cost: 50000, desc: "你被死亡君王阿什伯恩选中。你可以提取死者的影子将其转化为忠诚的士兵，组建不死军团。只要有影子，你就是不灭的。", type: "exclusive"},
            {name: "系统玩家(Player)", color: "SS", cost: 12000, desc: "你是唯一的‘玩家’。通过完成每日任务和杀怪，你可以像玩RPG游戏一样无限升级，获得属性点和技能，没有成长上限。", type: "exclusive"},
            {name: "国家权力级猎人", color: "SS", cost: 9000, desc: "你的力量足以匹敌一个国家的军事力量。你是S级中的顶点，拥有支配者(Ruler)赋予的权能，能够单人通关S级传送门。", type: "exclusive"},
            {name: "支配者之手", color: "S", cost: 2500, desc: "你可以用意念操控物体，不仅能抓取远处的敌人，还能像念动力一样造成物理冲击。", type: "exclusive"},
            {name: "全恢复(每日一次)", color: "S", cost: 3000, desc: "每天一次，无论你受了多重的伤，甚至断肢，只要还有一口气，就能瞬间恢复到满状态。", type: "exclusive"},
            {name: "顶级刺客身法", color: "A", cost: 1200, desc: "你的速度快到肉眼无法捕捉，能够使用‘隐身’技能消除气息，是天生的暗杀者。", type: "exclusive"},
            {name: "双重觉醒者", color: "A", cost: 1500, desc: "你在觉醒后经历了二次觉醒，魔力总量和潜力发生了质的飞跃，从C级跃升至S级。", type: "exclusive"},
            {name: "治疗师(S级)", color: "S", cost: 2800, desc: "极其稀缺的顶级奶妈。你可以瞬间治愈致命伤，甚至能重新长出断肢，是所有公会争抢的对象。", type: "exclusive"},
            {name: "魔兽通译", color: "B", cost: 500, desc: "你能听懂魔兽的语言。虽然它们大多时候都在喊‘杀’，但这能让你提前预判战术。", type: "exclusive"},
            {name: "坦克(嘲讽)", color: "B", cost: 600, desc: "你拥有极高的物理防御力，并且能通过技能强制吸引怪物的仇恨，保护队友。", type: "exclusive"},
            {name: "恶魔猎手", color: "A", cost: 1000, desc: "你在对抗恶魔系怪物时，攻击力翻倍。你熟知恶魔的弱点，并且能制作针对性的毒药。", type: "exclusive"},
            {name: "君王的威压", color: "S", cost: 2200, desc: "释放出恐怖的杀气，让比你等级低的敌人陷入‘恐惧’状态，全属性下降50%。", type: "exclusive"},
            {name: "嗜血", color: "A", cost: 900, desc: "生命值越低，你的攻击力越高。在濒死状态下，你的破坏力将提升至极限。", type: "exclusive"},
            {name: "空间魔法师", color: "S", cost: 3500, desc: "你可以制造传送门，连接两个不同的坐标。这是战略级的技能，无论是支援还是逃跑都无解。", type: "exclusive"},
            {name: "生命之水", color: "SS", cost: 8000, desc: "你拥有制造‘生命之水’的配方。这是能治愈‘永恒睡眠症’的神药，价值连城。", type: "exclusive"}
        ]
    },
    {
        name: "517.古惑仔",
        desc: "香港九十年代，霓虹灯下的黑帮江湖。铜锣湾、旺角、洪兴、东星。这里讲究的是义气、兄弟和拳头。人在江湖，身不由己。",
        boss: "乌鸦, 靓坤, 骆驼, 丁瑶, 蒋天生",
        identities: [
            { name: "屋邨长大的小混混", items: "一根棒球棍, 一包红万宝路" },
            { name: "茶餐厅的伙计", items: "一条油腻的围裙, 隐藏在案板下的西瓜刀" },
            { name: "刚出狱的过气老哥", items: "过时的皮夹克, 一身洗掉色的纹身" },
            { name: "警局卧底(二五仔)", items: "摩斯密码手册, 藏在鞋底的窃听器" },
            { name: "夜总会泊车小弟", items: "一串豪车钥匙, 被打肿的脸" }
        ],
        talents: [
            {name: "天生龙头(蒋天生)", color: "SS", cost: 5000, desc: "你拥有天生的领袖气质和政治智慧。你能平衡各方势力，让手下的大佬们对你心服口服，黑白两道通吃。", type: "exclusive"},
            {name: "铜锣湾扛把子", color: "S", cost: 2500, desc: "你在特定街区拥有绝对的声望。只要你一声令下，几百个兄弟随时能从街角冲出来。", type: "exclusive"},
            {name: "格斗之王(太子)", color: "S", cost: 2800, desc: "你精通泰拳、散打等多种格斗术，单挑能力极强，是帮派中的金牌打手，能以一敌十。", type: "exclusive"},
            {name: "掀桌子(乌鸦)", color: "A", cost: 1200, desc: "你行事疯癫，不讲规矩。当你处于劣势时，你总能用最极端、最卑鄙的手段打破僵局（物理掀桌）。", type: "exclusive"},
            {name: "义薄云天", color: "A", cost: 1500, desc: "你对兄弟绝对忠诚，这让你收获了死忠的追随者。当你陷入绝境时，一定会有兄弟为你挡刀。", type: "exclusive"},
            {name: "刀法宗师", color: "B", cost: 800, desc: "不管是西瓜刀还是开山刀，在你手里都能玩出花来。你砍人快准狠，且能避开要害只伤不杀。", type: "exclusive"},
            {name: "牧师的庇护", color: "C", cost: 200, desc: "你认识一位爱说教的牧师。在他身边时，你的运气会变好，而且能得到免费的治疗和心灵鸡汤。", type: "exclusive"},
            {name: "警方卧底", color: "B", cost: 600, desc: "你拥有警方的资源支持。必要时可以呼叫条子来扫场，借刀杀人，但要小心身份暴露。", type: "exclusive"},
            {name: "旺角车神(小结巴)", color: "C", cost: 300, desc: "你偷车技术一流，飙车技术更是亡命徒级别。在逃跑追逐战中，没人能在大街小巷中抓到你。", type: "exclusive"},
            {name: "只手遮天", color: "SS", cost: 6000, desc: "你的势力庞大到足以影响整个城市的地下秩序。警察抓你都要看证据，甚至要看你脸色。", type: "exclusive"},
            {name: "荷兰特训", color: "A", cost: 1000, desc: "你曾在荷兰受过枪械特训。在这个以冷兵器为主的江湖里，你拔枪的速度就是真理。", type: "exclusive"},
            {name: "生意头脑", color: "B", cost: 700, desc: "你不仅会打打杀杀，更懂怎么赚钱。无论是收保护费还是经营夜场，你都能让社团财源滚滚。", type: "exclusive"},
            {name: "魅惑(丁瑶)", color: "S", cost: 2200, desc: "你拥有致命的魅力和心机。男人只是你的棋子，你能在谈笑间让两个帮派火拼，坐收渔利。", type: "exclusive"},
            {name: "铁头功", color: "C", cost: 150, desc: "你的头很硬，非常硬。在近身肉搏中，一记头槌往往能起到意想不到的效果。", type: "exclusive"},
            {name: "不死小强", color: "A", cost: 1100, desc: "你的生命力极其顽强，受了再重的伤也能爬起来继续打。这种狠劲往往能吓退敌人。", type: "exclusive"}
        ]
    },
    {
        name: "518.环太平洋",
        desc: "太平洋海底的裂缝连接着怪兽（Kaiju）的世界。为了对抗巨型怪兽，人类制造了巨大的机甲战士（Jaeger），通过双人神经元连接进行驾驶。",
        boss: "毒妇(Slattern), 棱背龟, 尾立鼠, 先驱(Precursors)",
        identities: [
            { name: "破碎圆顶基地的维修工", items: "重型扳手, 油污的工作服" },
            { name: "机甲驾驶员候补生", items: "模拟训练成绩单, 神经元连接头盔" },
            { name: "怪兽黑市商人", items: "怪兽骨粉, 寄生虫标本" },
            { name: "香港避难所的难民", items: "应急口粮, 捡来的机甲碎片" },
            { name: "PPDC科学官助手", items: "怪兽图鉴, 盖革计数器" }
        ],
        talents: [
            {name: "完美通感(Drift)", color: "SS", cost: 8000, desc: "你的精神力极强，可以与任何人瞬间达成100%的通感同步率，甚至可以单人驾驶机甲而不流鼻血。", type: "exclusive"},
            {name: "怪兽通感", color: "SSS", cost: 25000, desc: "你可以通过神经桥接直接与怪兽的大脑连接（类似纽特）。你能读取先驱的战术，甚至短暂控制低级怪兽。", type: "exclusive"},
            {name: "机甲猎人王牌", color: "S", cost: 3000, desc: "你拥有极高的驾驶天赋。无论是模拟战还是实战，你都能做出违背物理常识的机动动作。", type: "exclusive"},
            {name: "反怪兽血液毒性", color: "B", cost: 500, desc: "你的体质特殊，怪兽蓝（剧毒血液）对你无效。你甚至可以在充满毒气的环境中呼吸。", type: "exclusive"},
            {name: "第六代机甲图纸", color: "SS", cost: 9000, desc: "你掌握了超越时代的机甲技术：引力弹弓、等离子加农炮、甚至无人机甲编队的核心代码。", type: "exclusive"},
            {name: "怪兽崇拜者", color: "C", cost: 100, desc: "你疯狂迷恋怪兽，这让你在面对它们时不会感到恐惧，反而会兴奋，san值极低。", type: "exclusive"},
            {name: "古武术宗师", color: "A", cost: 1200, desc: "你将古老的武术融入了机甲格斗。你的机甲不仅仅是铁疙瘩，而是一个灵活的武术家。", type: "exclusive"},
            {name: "核动力心脏", color: "A", cost: 1500, desc: "你的身体经过改造，植入了微型核反应堆。你拥有无限的耐力，且能为小型设备供电。", type: "exclusive"},
            {name: "先驱的基因", color: "S", cost: 3500, desc: "你拥有外星先驱的部分基因。怪兽不会主动攻击你，你甚至能听懂它们的低语。", type: "exclusive"},
            {name: "链剑专精", color: "B", cost: 600, desc: "你擅长使用机甲链剑。你知道如何切割怪兽的关节和要害，造成最大的破坏。", type: "exclusive"},
            {name: "数字战术家", color: "A", cost: 1000, desc: "在通感中，你能瞬间计算出怪兽的攻击轨迹和最佳反击路线，如同拥有预知能力。", type: "exclusive"},
            {name: "最后一道防线", color: "S", cost: 2000, desc: "当队友全部倒下，只剩你一人时，你的全属性提升200%。你是守护人类的最后壁垒。", type: "exclusive"},
            {name: "黑市渠道", color: "C", cost: 300, desc: "你认识汉尼拔·周。你可以搞到任何怪兽器官，或者在最危险的时候搞到一张逃往内陆的船票。", type: "exclusive"},
            {name: "模拟驾驶满分", color: "B", cost: 400, desc: "虽然还没上过战场，但你在模拟器里已经击杀了五百头怪兽，理论知识无敌。", type: "exclusive"},
            {name: "暴风赤红(三臂)", color: "A", cost: 1800, desc: "你习惯同时操作三个机械臂进行攻击。这种独特的操作方式让敌人防不胜防。", type: "exclusive"}
        ]
    },
    {
        name: "519.头号玩家",
        desc: "2045年，现实世界衰败，人们沉浸在名为‘绿洲’(OASIS)的VR虚拟宇宙中。这里有流行文化的一切彩蛋，只要找到三把钥匙，就能拥有整个绿洲。",
        boss: "诺兰·索伦托(IOI总裁), 机械哥斯拉(虚拟), 艾奇(PVP斗技场)",
        identities: [
            { name: "贫民窟叠楼的孤儿", items: "一套老旧的触感手套, 全方位跑步机" },
            { name: "IOI公司的契约奴工(六号人)", items: "统一的制服, 无法下线的VR头盔" },
            { name: "绿洲里的赏金猎人", items: "一把爆能枪, 一辆改装的阿基拉摩托" },
            { name: "全职游戏主播", items: "直播无人机, 粉丝打赏的虚拟币" },
            { name: "哈利迪档案馆的管理员", items: "一本年鉴, 只有你懂的冷笑话" }
        ],
        talents: [
            {name: "彩蛋猎人(Easter Egg)", color: "SS", cost: 10000, desc: "你对80-90年代的流行文化了如指掌。无论是雅达利游戏、高达还是闪灵，你都能瞬间找到破局的关键线索。", type: "exclusive"},
            {name: "超级黑客(绿洲版)", color: "S", cost: 3500, desc: "你可以编写代码修改绿洲的局部规则。召唤魔法护盾、修改重力、甚至让别人的神器失效。", type: "exclusive"},
            {name: "高达驾驶证", color: "S", cost: 3000, desc: "你拥有RX-78-2高达的召唤道具（限时）。在时限内，你是战场上的白色恶魔。", type: "exclusive"},
            {name: "额外一条命(硬币)", color: "SS", cost: 8000, desc: "你拥有哈利迪的硬币。当你在绿洲中HP归零时，你不会被清号，而是满血复活。这是唯一的后悔药。", type: "exclusive"},
            {name: "钞能力(IOI)", color: "A", cost: 2000, desc: "你拥有无限的虚拟货币。你可以购买最顶级的装备、神器，甚至雇佣一支军队为你作战。", type: "exclusive"},
            {name: "神器:奥苏沃克斯之球", color: "S", cost: 4000, desc: "开启后生成一个无敌的球形护盾，没有任何魔法或物理攻击能穿透它，持续90秒。", type: "exclusive"},
            {name: "操作怪(高玩)", color: "A", cost: 1500, desc: "你的反应速度和手速是职业电竞选手级别的。在PVP中，没人能摸到你的衣角。", type: "exclusive"},
            {name: "载具改装大师", color: "B", cost: 800, desc: "你能将德罗宁跑车改装成会飞的怪物。你的载具拥有极高的速度和隐藏武器。", type: "exclusive"},
            {name: "人脸识别屏蔽", color: "C", cost: 300, desc: "在绿洲中，没人能通过扫描查出你的现实身份。这对躲避IOI的追杀至关重要。", type: "exclusive"},
            {name: "神器:机械哥斯拉", color: "SS", cost: 7000, desc: "你可以召唤并驾驶机械哥斯拉。虽然行动笨重，但它的原子吐息能摧毁一切阻碍。", type: "exclusive"},
            {name: "泽米基斯方块", color: "A", cost: 1200, desc: "使用后可以将时间倒流60秒。这在解谜或者避免致命失误时是神技。", type: "exclusive"},
            {name: "全知之眼", color: "B", cost: 600, desc: "你可以看到所有玩家的ID、等级和血条，甚至能透视看到他们背包里的装备。", type: "exclusive"},
            {name: "神圣手雷", color: "A", cost: 900, desc: "来自《蒙提·派森》的神器。爆炸范围极大，伤害极高，专治各种不服。", type: "exclusive"},
            {name: "现实运动健将", color: "C", cost: 200, desc: "你的现实身体非常强壮。这让你在使用全方位跑步机时耐力更好，不会因为体力耗尽而下线。", type: "exclusive"},
            {name: "管理员权限(临时)", color: "SSS", cost: 30000, desc: "你获得了安诺拉的化身赋予的临时管理员权限。你可以删除玩家账号，重置区域，你是绿洲的神。", type: "exclusive"}
        ]
    },
    {
        name: "520.哥斯拉系列",
        desc: "怪兽宇宙。泰坦巨兽们从沉睡中苏醒，争夺地球霸权。人类在这些古老神明的脚下瑟瑟发抖，试图寻找生存之道。",
        boss: "基多拉(王者), 哥斯拉(怪兽之王), 戴斯特洛伊亚, 机械哥斯拉",
        identities: [
            { name: "帝王组织的生物学家", items: "声呐探测仪, 泰坦分布图" },
            { name: "被毁城市的幸存者", items: "防辐射服, 一张全家福" },
            { name: "生态恐怖分子", items: "奥卡(ORCA)声波装置, 炸药" },
            { name: "地心世界的原住民(伊维族)", items: "重力反转石, 原始长矛" },
            { name: "APEX公司的机甲驾驶员", items: "神经连接服, 能量饮料" }
        ],
        talents: [
            {name: "阿尔法咆哮(Alpha Call)", color: "SSS", cost: 40000, desc: "你拥有怪兽之王的威压。当你发出咆哮时，全球的低级泰坦都会臣服于你，听从你的号令。", type: "exclusive"},
            {name: "原子吐息(哥斯拉)", color: "SS", cost: 9000, desc: "你的体内拥有生物核反应堆。你可以从口中喷射出高能蓝色光束，贯穿地心，摧毁一切物质。", type: "exclusive"},
            {name: "引力光线(基多拉)", color: "SS", cost: 8500, desc: "作为外星高维生物，你可以释放金色的引力闪电，不仅伤害极高，还能像念力一样抓取物体。", type: "exclusive"},
            {name: "辐射吸收", color: "S", cost: 3000, desc: "你以核辐射为食。核弹炸在你身上就是补血包。辐射浓度越高，你的体型和力量增长越快。", type: "exclusive"},
            {name: "红莲模式", color: "S", cost: 3500, desc: "当你体温过高时进入红莲状态。你周围的一切都会被高温熔化，最后释放出毁灭一切的核脉冲。", type: "exclusive"},
            {name: "摩斯拉的鳞粉", color: "A", cost: 1500, desc: "你可以散布具有治疗和致幻效果的鳞粉。这能安抚狂暴的泰坦，或者为友军提供强大的buff。", type: "exclusive"},
            {name: "地心引力适应", color: "B", cost: 600, desc: "你适应了空心地球的重力反转环境。你可以在巨大的落差间跳跃自如，不会摔死。", type: "exclusive"},
            {name: "氧气破坏者(抗性)", color: "A", cost: 2000, desc: "你的细胞结构特殊，能够抵抗氧气破坏者的分解作用。这是唯一能杀死哥斯拉的武器，但杀不死你。", type: "exclusive"},
            {name: "机械飞升(机械哥斯拉)", color: "S", cost: 2800, desc: "你将意识上传到机械泰坦中。拥有质子尖啸、导弹齐射和无限的耐力，只受能源限制。", type: "exclusive"},
            {name: "泰坦再生", color: "A", cost: 1200, desc: "哪怕头被咬掉（如果是基多拉），你也能在短时间内再生。只要核心不灭，你就很难死。", type: "exclusive"},
            {name: "奥卡声波掌控", color: "B", cost: 800, desc: "你精通奥卡装置的频率。你可以模拟阿尔法泰坦的叫声，诱导、激怒或安抚特定的怪兽。", type: "exclusive"},
            {name: "金刚巨斧", color: "A", cost: 1800, desc: "你会使用工具。这把用哥斯拉背鳍做的斧头能吸收能量，充能后一击甚至能破防哥斯拉。", type: "exclusive"},
            {name: "EMP脉冲(穆托)", color: "B", cost: 900, desc: "你可以释放强大的电磁脉冲，瘫痪周围的所有电子设备。这对人类军队和机械哥斯拉是致命的。", type: "exclusive"},
            {name: "拟态(骷髅爬虫)", color: "C", cost: 400, desc: "你可以像变色龙一样融入环境，或者模仿其他生物的声音来进行伏击。", type: "exclusive"},
            {name: "自然平衡维护者", color: "SS", cost: 6000, desc: "你是地球意志的代行者。当你为了恢复自然平衡而战时，你的力量会得到地球盖亚意识的加持。", type: "exclusive"}
        ]
    },
    {
        name: "521.功夫熊猫",
        desc: "古老的中国，动物们修习功夫，探寻气的奥秘。翡翠宫、和平谷、灵界。这里有绝世武功，也有对内心平静的追求。",
