    {
        name: "527.群星",
        desc: "银河系广袤无垠，充满了奇迹与恐怖。从初次探索星海的年轻文明，到堕落的古老帝国。建立你的舰队，扩张你的疆域，迎接天灾的洗礼。",
        boss: "肃正协议, 破界者(高维恶魔), 索林原虫, 终末之圆, 堕落帝国觉醒",
        identities: [
            { name: "联合国的科学官", items: "科研船驾驶证, 异常现象报告" },
            { name: "巨型企业的执行官", items: "能量币账户, 贸易协议" },
            { name: "格式塔意识的子个体", items: "连接蜂巢的神经节点, 生物组织样本" },
            { name: "唯心帝国的神官", items: "灵能增幅器, 虚境圣典" },
            { name: "失落帝国的考古学家", items: "暗物质偏导护盾碎片, 先驱者遗物" }
        ],
        talents: [
            {name: "以太相引擎(飞升)", color: "SSS", cost: 50000, desc: "你启动了毁灭银河的终极装置。通过引爆恒星收集暗物质，你将带领你的种族进入更高的维度，成为神明。", type: "exclusive"},
            {name: "天灾化身", color: "SS", cost: 12000, desc: "你的文明被全银河视为威胁。你拥有毁灭恒星的武器，舰队造价极其低廉，唯一的目的就是毁灭。", type: "exclusive"},
            {name: "灵能飞升(虚境契约)", color: "S", cost: 3500, desc: "你的种族觉醒了灵能。你可以与虚境中的存在签订契约，预知未来，甚至用意念摧毁敌人的战舰。", type: "exclusive"},
            {name: "机械飞升(合成人)", color: "S", cost: 3000, desc: "血肉苦弱，机械飞升。你将意识上传到完美的机械躯体中，获得永生，生产效率大幅提升。", type: "exclusive"},
            {name: "基因飞升(完美生物)", color: "S", cost: 2800, desc: "通过基因编辑，你创造了完美的物种。强壮、聪明、长寿，适应任何恶劣的星球环境。", type: "exclusive"},
            {name: "巨像计划(地爆天星)", color: "SS", cost: 9000, desc: "你拥有建造“巨像”级战舰的能力。安乐天使、中子灭杀、粉碎星球，一发入魂，彻底解决异见者。", type: "exclusive"},
            {name: "灰蛊风暴(纳米)", color: "A", cost: 2000, desc: "你掌握了L星门的纳米技术。你可以召唤纳米机器人风暴吞噬舰队，或者瞬间改造星球。", type: "exclusive"},
            {name: "星河卫士", color: "S", cost: 2500, desc: "在天灾降临时，你对天灾势力的伤害提升50%。你是全银河的希望，能团结所有帝国共同抗敌。", type: "exclusive"},
            {name: "考古学家(先驱者)", color: "B", cost: 800, desc: "你擅长挖掘古代遗迹。这能让你获得失落的黑科技，如暗物质引擎或赛博勒克斯战体。", type: "exclusive"},
            {name: "蜂群思维", color: "A", cost: 1500, desc: "你的意识与亿万同胞相连。你没有个体的恐惧，绝对服从集体，拥有恐怖的扩张和动员能力。", type: "exclusive"},
            {name: "魅力非凡(外交)", color: "B", cost: 600, desc: "你的种族长得非常符合银河审美。这让你在外交中无往不利，更容易达成贸易协定或附庸他国。", type: "exclusive"},
            {name: "巨型建筑工程", color: "A", cost: 1800, desc: "你掌握了建造戴森球、环形世界、物质解压器的技术。你的资源产出将是无穷无尽的。", type: "exclusive"},
            {name: "虚空居者", color: "C", cost: 300, desc: "你适应了太空站的生活。在居住站中，你的产出效率极高，不需要宜居星球也能生存。", type: "exclusive"},
            {name: "唯物主义(科研)", color: "B", cost: 500, desc: "你坚信科学真理。你的科研速度极快，机器人技术发达，但无法理解灵能。", type: "exclusive"},
            {name: "末日起源(幸存者)", color: "A", cost: 1000, desc: "你的母星爆炸了，但你活了下来。你拥有极强的生存韧性，并且开局就拥有殖民船。", type: "exclusive"}
        ]
    },
    {
        name: "528.我在精神病院学斩神",
        desc: "迷雾降临，神话复苏。希腊、北欧、克苏鲁诸神觊觎大夏。人类最后的防线是守夜人。林七夜在精神病院睁开眼，诸神皆斩。",
        boss: "倪克斯(黑夜女神), 米迦勒(炽天使), 克苏鲁(旧日), 盖亚(大地之母), 湿婆",
        identities: [
            { name: "阳光精神病院的病人", items: "病号服, 诸神精神病院的钥匙" },
            { name: "守夜人新兵", items: "纹章, 直刀, 黑色风衣" },
            { name: "上古神兽的宿主", items: "封印符咒, 偶尔失控的力量" },
            { name: "迷雾中的幸存者", items: "手电筒, 压缩饼干" },
            { name: "守夜人教官", items: "教鞭, 禁墟序列详解" }
        ],
        talents: [
            {name: "诸神精神病院院长", color: "SSS", cost: 40000, desc: "你的脑海中有一座关押着神明的精神病院。你可以抽取病号（神明）的能力，甚至召唤祂们为你作战。", type: "exclusive"},
            {name: "凡尘神域", color: "SSS", cost: 35000, desc: "你以凡人之躯比肩神明。在你的领域内，神明的法则失效，一切由你主宰。你是行走在人间的神。", type: "exclusive"},
            {name: "炽天使米迦勒代理人", color: "SS", cost: 9000, desc: "你借用了天使之王的力量。圣神之火可以焚烧一切罪恶，六翼展开之时，你就是光明的化身。", type: "exclusive"},
            {name: "黑夜女神眷属", color: "SS", cost: 8500, desc: "在黑夜中，你的全属性大幅提升。你可以操控暗夜、阴影，甚至剥夺敌人的五感。", type: "exclusive"},
            {name: "禁墟:王之宝库", color: "S", cost: 3000, desc: "你可以召唤历史上所有的传说兵器。万剑归宗，火力覆盖，一人即是一支军队。", type: "exclusive"},
            {name: "禁墟:星夜", color: "A", cost: 1500, desc: "你可以召唤星光降临，形成绝对防御的屏障，或者凝聚成毁灭性的星辰光束。", type: "exclusive"},
            {name: "禁墟:不朽", color: "A", cost: 1800, desc: "超强的再生能力。只要不是瞬间灰飞烟灭，你都能迅速复原。你是最肉的坦克。", type: "exclusive"},
            {name: "魔法之神代理", color: "S", cost: 2800, desc: "你掌握了梅林的魔法。无论是元素轰炸、空间传送还是变形术，你都信手拈来。", type: "exclusive"},
            {name: "湿婆怨(禁忌)", color: "SS", cost: 10000, desc: "毁灭之神的力量。开启后你的战力将无限飙升，但这会透支你的生命和理智，是同归于尽的招数。", type: "exclusive"},
            {name: "直觉(战斗)", color: "B", cost: 600, desc: "你在战斗中拥有野兽般的直觉。不需要思考，身体会自动做出最正确的反应。", type: "exclusive"},
            {name: "精神病患(伪)", color: "C", cost: 200, desc: "你的思维异于常人，这让你对精神类攻击（如克苏鲁低语）有极高的抗性。", type: "exclusive"},
            {name: "剑道通神", color: "A", cost: 1200, desc: "你对剑术的理解达到了极致。手中无剑胜有剑，草木竹石皆可为剑，斩断神明。", type: "exclusive"},
            {name: "守夜人纹章", color: "C", cost: 150, desc: "佩戴后，你对迷雾中的怪物有威慑力，并且能感应到附近队友的位置。", type: "exclusive"},
            {name: "鬼神引", color: "A", cost: 1000, desc: "你可以通过特殊的旋律引渡亡魂，或者对敌人造成直接的灵魂伤害。", type: "exclusive"},
            {name: "奇迹(概率)", color: "S", cost: 2500, desc: "你拥有引发奇迹的能力。在绝境中，万分之一的生存概率会被你无限放大。", type: "exclusive"}
        ]
    },
    {
        name: "529.妖神记",
        desc: "妖灵师的世界，人族退守光辉之城。聂离重生回十三岁，带着前世的巅峰知识和时空妖灵之书，逆天改命，对抗圣帝。",
        boss: "圣帝, 妖主, 黑龙, 段剑(前期), 聂离(竞争者)",
        identities: [
            { name: "光辉之城的世家子弟", items: "家族令牌, 几枚妖灵币" },
            { name: "炼丹师公会学徒", items: "初级丹炉, 药草图鉴" },
            { name: "黑暗公会的刺客", items: "隐身斗篷, 淬毒匕首" },
            { name: "天痕世家的废材", items: "破旧的修炼功法, 坚毅的眼神" },
            { name: "拥有天灵根的天才", items: "发光的灵魂海, 导师的推荐信" }
        ],
        talents: [
            {name: "时空妖灵之书(残)", color: "SSS", cost: 45000, desc: "传说中的神物。它掌控着时空法则，能加速修炼时间，甚至逆转时空复活。虽然残缺，但足以称霸。", type: "exclusive"},
            {name: "天道神诀", color: "SS", cost: 8000, desc: "前世最强的修炼功法。修炼出的天道之力能压制一切属性的妖灵力，根基无比扎实。", type: "exclusive"},
            {name: "灵魂海(全属性)", color: "SS", cost: 7500, desc: "你的灵魂海广阔无边，且兼容风雷冰火等所有属性。你可以融合任何类型的妖灵，没有瓶颈。", type: "exclusive"},
            {name: "融合妖灵(神级)", color: "S", cost: 3000, desc: "你融合了一只神级成长潜力的妖灵（如影妖、虎牙熊猫）。随着你的提升，它会进化成恐怖的存在。", type: "exclusive"},
            {name: "铭纹大师", color: "A", cost: 1500, desc: "你精通上古铭纹。随便在盔甲或武器上刻画几道，就能让其变成神兵利器，价值连城。", type: "exclusive"},
            {name: "炼丹宗师", color: "A", cost: 1800, desc: "你掌握着失传的丹方。你能炼制出提升修为、治愈绝症的极品丹药，是各大势力争抢的对象。", type: "exclusive"},
            {name: "前世记忆(百科全书)", color: "S", cost: 2500, desc: "你拥有未来的记忆。你知道哪里有宝藏，知道功法的缺陷，知道历史的走向。这是最大的外挂。", type: "exclusive"},
            {name: "刺客之心", color: "A", cost: 1200, desc: "你精通暗杀之术。配合影妖妖灵，你可以在阴影中瞬间取敌首级，然后全身而退。", type: "exclusive"},
            {name: "阵法宗师", color: "A", cost: 1600, desc: "你可以布置出万魔妖灵大阵级别的阵法。一人守城，万夫莫开。", type: "exclusive"},
            {name: "财力雄厚", color: "B", cost: 800, desc: "你极具商业头脑（或抄袭前世）。你富可敌国，能用妖灵币砸死对手，购买海量资源。", type: "exclusive"},
            {name: "圣帝封印(破解)", color: "SS", cost: 6000, desc: "你知晓破解圣帝封锁时空的方法。这让你有机会突破传奇境界，达到天道境。", type: "exclusive"},
            {name: "极品灵根", color: "A", cost: 1000, desc: "你的修炼速度是常人的十倍。别人需要十年突破，你只需要一年。", type: "exclusive"},
            {name: "法则领悟", color: "S", cost: 2200, desc: "你提前领悟了光、暗、死亡等法则之力。这让你在同阶战斗中处于绝对的碾压地位。", type: "exclusive"},
            {name: "妖灵成长(变异)", color: "B", cost: 700, desc: "你的妖灵发生了良性变异，拥有了普通妖灵没有的特殊技能，如吞噬或反伤。", type: "exclusive"},
            {name: "红颜知己(羁绊)", color: "C", cost: 300, desc: "你身边总有天赋异禀的美女相伴（如叶紫芸、肖凝儿）。她们不仅养眼，还是强大的助力。", type: "exclusive"}
        ]
    },
    {
        name: "530.大奉打更人",
        desc: "这个世界，有儒、道、佛、妖、术。许七安从一个小捕快开始，凭借化学知识和破案能力，搅动风云，守护大奉。",
        boss: "贞德帝, 佛陀, 巫神, 蛊神, 荒, 监正(棋手)",
        identities: [
            { name: "长乐县的快手", items: "朴刀, 巡街令牌" },
            { name: "打更人铜锣", items: "铜锣腰牌, 差服, 佩刀" },
            { name: "司天监的白衣术士", items: "望气术入门, 炼金烧杯" },
            { name: "云鹿书院的学子", items: "论语, 毛笔, 一身浩然气" },
            { name: "江湖游侠", items: "一匹瘦马, 一壶浊酒" }
        ],
        talents: [
            {name: "气运加身(半个)", color: "SSS", cost: 40000, desc: "你身负大奉的一半国运。你是天命之子，虽然麻烦不断，但总能逢凶化吉，且升级速度极快。", type: "exclusive"},
            {name: "众生之力", color: "SSS", cost: 38000, desc: "当你为了天下苍生而战时，你可以借用万民的意念。这是超越品级的力量，足以斩杀神魔。", type: "exclusive"},
            {name: "儒家言出法随", color: "SS", cost: 8500, desc: "三品大儒境。你说“此地禁止飞行”，那么连鸟都得下来走路。虽然费嗓子和浩然正气，但逼格拉满。", type: "exclusive"},
            {name: "武神体魄", color: "SS", cost: 9000, desc: "你走的是武夫体系。肉身成圣，万法不侵，滴血重生。你是战场上最恐怖的推土机。", type: "exclusive"},
            {name: "佛门金刚不坏", color: "S", cost: 3000, desc: "你的皮肤呈暗金色，防御力惊人。同阶之中，没人能破你的防，除非是绝世神兵。", type: "exclusive"},
            {name: "炼金术天才", color: "A", cost: 1500, desc: "你拥有现代化学知识。制造鸡精、香水、玻璃，甚至炸药。不仅能赚钱，还能炸翻敌人。", type: "exclusive"},
            {name: "诗词才气", color: "A", cost: 1200, desc: "你是抄诗狂魔。每一首传世诗词都能引发天地异象，为你灌输浩然正气，让你在儒林中声名鹊起。", type: "exclusive"},
            {name: "蛊术(情蛊)", color: "A", cost: 1800, desc: "你精通南疆蛊术。特别是情蛊，能让异性对你死心塌地，也能在战斗中控制敌人的心智。", type: "exclusive"},
            {name: "术士望气", color: "B", cost: 800, desc: "你能看到他人的气运和情绪颜色。这让你在查案和识人方面拥有上帝视角。", type: "exclusive"},
            {name: "破案直觉", color: "B", cost: 600, desc: "你拥有福尔摩斯般的推理能力。任何离奇的案件，在你眼中都有迹可循。", type: "exclusive"},
            {name: "太平刀(意)", color: "S", cost: 2500, desc: "你领悟了“天下太平”的刀意。此刀专斩不平事，心中意气越盛，刀法威力越强。", type: "exclusive"},
            {name: "勾栏听曲", color: "C", cost: 150, desc: "你是教坊司的常客。这不仅能放松心情，还能打探到许多达官显贵的小道消息。", type: "exclusive"},
            {name: "浮屠宝塔", color: "S", cost: 3500, desc: "你拥有法宝浮屠塔。可以镇压强敌，储存物品，甚至塔内自成一界，拥有火焰等攻击手段。", type: "exclusive"},
            {name: "绝世渣男(魅惑)", color: "A", cost: 1000, desc: "你拥有独特的魅力，能周旋于多位红颜知己之间而不翻船（大概）。鱼塘管理大师。", type: "exclusive"},
            {name: "一刀斩(天地一刀斩)", color: "S", cost: 2800, desc: "汇聚全身精气神于一刀。这一刀不成功便成仁，拥有越阶杀敌的恐怖爆发力。", type: "exclusive"}
        ]
    },
                      {
                name: "531.赛马娘",
                desc: "继承了异世界名号与灵魂的少女们，拥有着超越人类的脚力与耐力。她们汇聚在特雷森学园，为了在“Twinkle Series”闪光系列赛中夺冠，并最终站在“URA决赛”的舞台中心而不断奔跑。这是梦想与汗水交织，但对败者极度残酷的竞速世界。",
                boss: "鲁道夫象征(会长), 秋川理事长, 三女神像",
                identities: [
                    { name: "特雷森学园马厩勤杂工", items: "一把沾满泥土的草叉, 一身充满汗臭味的工作服" },
                    { name: "中山赛马场落魄赌徒", items: "一叠全部猜错的废弃马券, 半瓶廉价的烧酒" },
                    { name: "因腿伤退役的无名赛马娘", items: "一只支撑行走的旧拐杖, 一双磨损严重再也无法穿上的蹄铁鞋" },
                    { name: "高知县偏远胡萝卜农户", items: "一把生锈的锄头, 一袋品相不佳的胡萝卜" },
                    { name: "地下黑赛的清理员", items: "一块擦拭血迹的抹布, 一个用来装呕吐物的铁桶" }
                ],
                talents: [
                    {name: "玻璃腿(易碎)", color: "E", cost: 50, desc: "你的腿部骨骼极其脆弱，稍微剧烈的运动就可能导致骨折。在这个以奔跑为尊的世界，这几乎是死刑判决。", type: "exclusive"},
                    {name: "闸门恐惧症", color: "D", cost: 120, desc: "你对出发闸门有着无法克制的心理阴影，每次起跑都会因为惊恐而慢半拍，这在短距离比赛中是致命的缺陷。", type: "exclusive"},
                    {name: "胡萝卜狂热", color: "C", cost: 150, desc: "你对胡萝卜有着超乎常人的执着。虽然这看起来很滑稽，但只要有胡萝卜作为奖励，你的恢复速度会小幅度提升。", type: "exclusive"},
                    {name: "一般路过粉丝", color: "C", cost: 180, desc: "你拥有作为观众的狂热，虽然身体素质平平，但你对赛马娘的数据和八卦了如指掌，容易获得情报。", type: "exclusive"},
                    {name: "大胃王(初期)", color: "B", cost: 300, desc: "你拥有类似小栗帽的无底洞胃口。虽然伙食费惊人，但只要吃得够多，你的体力和伤势恢复速度远超常人。", type: "exclusive"},
                    {name: "末脚(凡庸)", color: "B", cost: 450, desc: "你在比赛终盘时能稍微提升一点加速度，虽然无法与名将相比，但在底层赛事中足以让你摆脱垫底的命运。", type: "exclusive"},
                    {name: "重马场适应性", color: "A", cost: 750, desc: "无论是在泥泞的雨天还是恶劣的草地，你的奔跑速度几乎不受地形阻力的影响，是天生的力量型选手。", type: "exclusive"},
                    {name: "逃亡者直觉", color: "A", cost: 900, desc: "你擅长“领头”跑法，在比赛序盘能凭借野性的直觉抢占最佳赛道，只要没人追上来，你就是无敌的。", type: "exclusive"},
                    {name: "皮斯伊斯(黄金船的恶作剧)", color: "S", cost: 2200, desc: "你继承了那匹不按常理出牌的芦毛马的特质。虽然时常会做出令人匪夷所思的举动，但在绝境中往往能用打破常识的方式逆转战局。", type: "exclusive"},
                    {name: "不沉舰的进击", color: "S", cost: 2500, desc: "如黄金船般无法被击沉的意志。在比赛中盘如果被包围或发生身体碰撞，你的持久力和速度反而会大幅上升，强行冲开一条血路。", type: "exclusive"},
                    {name: "皇帝的神威", color: "S", cost: 2800, desc: "继承自“鲁道夫象征”的威压感。当你处于队伍后方并准备超车时，前方的赛马娘会因为感受到巨大的心理压力而无意识地为你让开道路。", type: "exclusive"},
                    {name: "异次元的逃亡者", color: "SS", cost: 5500, desc: "继承自“无声铃鹿”的极速概念。你的起跑速度无人能及，一旦拉开距离，就会进入“大逃”状态，让后方的追赶者只能望尘莫及，直至绝望。", type: "exclusive"},
                    {name: "绝对的帝王", color: "SS", cost: 6000, desc: "继承自“东海帝王”的柔韧舞步与不屈斗志。拥有极高的闪避能力以免受阻挡，且即便骨折三次，也能奇迹般地复活并夺取冠军。", type: "exclusive"},
                    {name: "总大将的威光", color: "SS", cost: 7500, desc: "继承自“特别周”在日本杯上的光辉一刻。在面对在这个世界被定义为“外敌”的强敌时，你的全属性将得到爆发性增长，背负着整个世界的期待冲线。", type: "exclusive"},
                    {name: "三女神的加护(原始因子)", color: "SSS", cost: 45000, desc: "你直接连接到了创造这个世界赛马娘概念的“三女神”本源。你拥有修改自身适应性（草地/泥地/距离）的权能，并能随意觉醒任何传说级技能，是注定要建立新时代的“神之马”。", type: "exclusive"}
                ]
            },
              {
        name: "532.(漫威)钢铁侠",
        desc: "漫威电影宇宙的开端。在这个世界，科技与资本是主宰。托尼·斯塔克从中东的沙漠中归来，以凡人之躯比肩神明。这里充斥着军火交易、企业博弈以及早期的高科技装甲原型。",
        boss: "奥巴代亚·斯坦(铁霸王), 拉扎(十戒帮头目)",
        identities: [
            { name: "斯塔克工业清洁工", items: "一辆装满废纸的推车, 一张只有底层权限的门禁卡" },
            { name: "阿富汗美军基地大兵", items: "一把磨损的M4卡宾枪, 一张贴着家人照片的头盔内衬" },
            { name: "名利场杂志实习记者", items: "一支录音笔, 一本记满花边新闻的笔记本" },
            { name: "十戒帮山洞人质", items: "一副沉重的铁脚镣, 一把用于挖掘的生锈铁铲" },
            { name: "马里布豪宅装修工人", items: "一套沾满油漆的工作服, 一个装满工具的腰包" }
        ],
        talents: [
            {name: "钯元素中毒", color: "E", cost: 10, desc: "你的血液中钯含量超标，这是一种慢性死亡诅咒。你会感到持续的胸痛和虚弱，如果不解决，寿命将按月计算。", type: "curse"},
            {name: "心脏弹片", color: "D", cost: 50, desc: "几枚细小的弹片残留在你的血管中，随时可能流入心脏导致死亡。你必须依赖外部磁场装置才能存活。", type: "curse"},
            {name: "芝士汉堡狂热", color: "C", cost: 50, desc: "你对美式芝士汉堡有着难以理解的执念。在进食汉堡时，你的精神状态会得到微量恢复，心情变好。", type: "common"},
            {name: "花花公子魅力", color: "B", cost: 300, desc: "你拥有托尼·斯塔克般的社交手腕，在名流聚会和异性交往中通过判定几率大幅提升，容易获得情报。", type: "exclusive"},
            {name: "一箱废铜烂铁", color: "B", cost: 450, desc: "即便是在山洞里，只要有一箱破烂，你也能制造出超出当前科技水平的简易机械装置或武器。", type: "exclusive"},
            {name: "杰里科导弹(残骸)", color: "A", cost: 800, desc: "你捡到了斯塔克工业杰里科导弹的核心部件。虽然无法发射，但其内部的微型集束炸药足以夷平一个街区。", type: "item"},
            {name: "飞行稳定器技术", color: "A", cost: 1200, desc: "掌握了早期钢铁战衣的手部飞行稳定器技术，可以制造出具有强冲击力和飞行辅助功能的掌心炮。", type: "skill"},
            {name: "铁霸王装甲(图纸)", color: "S", cost: 1800, desc: "奥巴代亚·斯坦逆向工程的产物。虽然笨重且能耗巨大，但其火力和防御力在初期世界足以横行霸道。", type: "item"},
            {name: "微型方舟反应炉(一代)", color: "SS", cost: 8000, desc: "冷核聚变技术的奇迹，每秒产生30亿焦耳的能量。这是驱动未来科技的核心，也是让你摆脱能源限制的关键。", type: "exclusive"},
            {name: "马克一号(原型机)", color: "S", cost: 1500, desc: "粗糙、笨重、但这代表了传奇的开始。拥有火焰喷射器和单发导弹，防御力极高，但无法长距离飞行。", type: "item"},
            {name: "贾维斯(核心代码)", color: "SS", cost: 9500, desc: "原本只是自然语言UI，但已具备极高的人工智能雏形。拥有它，你就拥有了顶级的黑客能力和辅助运算能力。", type: "exclusive"},
            {name: "斯塔克工业股份", color: "S", cost: 1900, desc: "你拥有斯塔克工业0.5%的股份。这意味着在这个资本世界里，你拥有了源源不断的巨额分红和一定的社会地位。", type: "status"},
            {name: "十戒帮的凝视", color: "E", cost: 20, desc: "你被这个神秘的恐怖组织盯上了。无论你走到哪里，都可能面临暗杀和绑架的风险。", type: "curse"},
            {name: "我是钢铁侠", color: "SSS", cost: 12000, desc: "概念级天赋。当你公开承认自己身份的那一刻，你的声望将瞬间锁定为世界顶点，获得“超级英雄”概念加持，所有正义阵营好感度拉满。", type: "concept"},
            {name: "机械工程天才", color: "SS", cost: 7500, desc: "你的大脑在机械结构和电子工程方面超越了时代。只要看一眼图纸，你就能理解其原理并进行改进。", type: "talent"}
        ]
    },
    {
        name: "533.(漫威)无敌浩克",
        desc: "充满了愤怒与毁灭的世界。军方在追捕一个绿色的怪物，而伽马射线是这个世界最危险也是最诱人的力量。力量的代价是理智的丧失。",
        boss: "埃米尔·布朗斯基(憎恶), 罗斯将军",
        identities: [
            { name: "卡尔弗大学图书管理员", items: "一辆借书推车, 一本关于伽马射线的旧教材" },
            { name: "巴西汽水厂灌装工", items: "一顶沾满果汁的帽子, 几瓶可能混入了血液的汽水" },
            { name: "罗斯将军的司机", items: "一辆军用吉普车的钥匙, 一副墨镜" },
            { name: "蓝先生的实验助手", items: "一件白大褂, 几支装满不稳定血清的试管" },
            { name: "哈林区街头小贩", items: "一辆热狗车, 几张皱巴巴的零钱" }
        ],
        talents: [
            {name: "愤怒管理失控", color: "D", cost: 80, desc: "你的情绪极不稳定，心率稍有上升就会导致理智断线，虽然不会变身，但会让你做出冲动的蠢事。", type: "curse"},
            {name: "伽马辐射病", color: "E", cost: 30, desc: "你长期暴露在微量伽马射线下，身体正在缓慢衰竭，皮肤呈现病态的灰绿色，免疫力大幅下降。", type: "curse"},
            {name: "巴西柔术精通", color: "B", cost: 350, desc: "为了控制心率而学习的格斗技巧。注重呼吸调节和地面缠斗，能让你在不依赖蛮力的情况下制服敌人。", type: "skill"},
            {name: "心率监测手表", color: "C", cost: 120, desc: "这块手表能精确监测你的每分钟心跳。当心率超过200时会发出刺耳警报，是你保命的小道具。", type: "item"},
            {name: "超级士兵血清(布朗斯基版)", color: "S", cost: 1800, desc: "注射后能大幅增强体能、速度和愈合能力。但副作用是会放大内心的好斗欲望，且骨骼可能会发生畸变。", type: "item"},
            {name: "浩克之血(样本)", color: "SS", cost: 6000, desc: "一管极其危险的血液样本。如果直接注射，99%的几率死亡，1%的几率获得弱化版的浩克之力或变成某种怪物。", type: "item"},
            {name: "声波加农炮", color: "A", cost: 900, desc: "斯塔克工业为军方研制的强力声波武器，能够通过高频声波压制大型生物，是少数能对浩克造成影响的常规武器。", type: "item"},
            {name: "大头目之智(潜质)", color: "S", cost: 2000, desc: "你的大脑受到伽马射线的特殊变异影响，头部开始肿大，但换来的是超乎常人的逻辑运算和推演能力。", type: "talent"},
            {name: "贝蒂的挂念", color: "B", cost: 400, desc: "你拥有罗斯将军之女的关照。在面对军方围剿时，这是一张极好的护身符，甚至能安抚暴走的野兽。", type: "status"},
            {name: "军用悍马", color: "C", cost: 180, desc: "一辆坚固耐用的军用越野车，配备防弹玻璃和车载机枪架，是在混乱战场逃生的好工具。", type: "item"},
            {name: "冥想呼吸法", color: "B", cost: 300, desc: "一种深度的瑜伽冥想技巧，能让你在极度紧张的环境下迅速降低心率，保持绝对的冷静。", type: "skill"},
            {name: "伽马变异体质", color: "SSS", cost: 15000, desc: "你的细胞成为了伽马能量的完美容器。愤怒是你的燃料，你的力量没有上限，且拥有近乎不死的再生能力。", type: "exclusive"},
            {name: "憎恶骨刺", color: "A", cost: 1100, desc: "你的身体可以从关节处生长出锋利的骨刺，既是防御也是致命的武器，能轻易刺穿钢板。", type: "skill"},
            {name: "永不破损的裤衩", color: "S", cost: 2500, desc: "因果律物品。无论你的体型膨胀多少倍，这条裤子永远合身且不会破裂，维护你最后的尊严。", type: "item"},
            {name: "神盾局收容记录", color: "D", cost: 60, desc: "你的名字出现在神盾局的危险名单上，虽然还没抓你，但你已经被黑寡妇级别的特工盯上了。", type: "curse"}
        ]
    },
    {
        name: "534.(漫威)钢铁侠2",
        desc: "世界知道了钢铁侠的身份。反应炉技术引发了全球的军备竞赛。鞭索挥舞着电鞭复仇，而神盾局开始正式介入，复仇者联盟的雏形正在酝酿。",
        boss: "伊凡·万科(鞭索), 贾斯汀·汉默",
        identities: [
            { name: "斯塔克博览会保安", items: "一套制服, 一个手电筒, 一个对讲机" },
            { name: "摩纳哥赛车手", items: "一套防火赛车服, 一辆F1赛车模型" },
            { name: "汉默工业技术员", items: "一台经常死机的电脑, 一堆设计错误的图纸" },
            { name: "神盾局潜伏特工", items: "一把格洛克17手枪, 一个伪造的身份证件" },
            { name: "佩珀·波兹的助理", items: "一部永远响个不停的手机, 一杯冷掉的咖啡" }
        ],
        talents: [
            {name: "钯中毒(晚期)", color: "D", cost: 150, desc: "毒素已经侵入淋巴系统，你的脖子上出现明显的黑色脉络。你必须每天饮用叶绿素汁来缓解痛苦。", type: "curse"},
            {name: "前妻导弹", color: "C", cost: 10, desc: "汉默工业的“杰作”。号称能摧毁碉堡，实际效果可能连个哑炮都不如，甚至会在撞击后被弹开。", type: "item"},
            {name: "手提箱装甲(MK5)", color: "SS", cost: 5000, desc: "便携式钢铁战衣，平时折叠为手提箱。虽然防御力较弱且无法飞行，但胜在能随时随地进行武装。", type: "item"},
            {name: "新元素发现者", color: "SSS", cost: 13000, desc: "你解开了霍华德·斯塔克留下的谜题，合成了一种全新的元素。它是完美的清洁能源，也是无限能源的钥匙。", type: "talent"},
            {name: "鞭索电鞭技术", color: "A", cost: 1400, desc: "利用小型反应炉驱动的高能等离子鞭，能轻易切断F1赛车和金属。缺点是对使用者防护不足。", type: "skill"},
            {name: "战争机器(MK1)", color: "S", cost: 2800, desc: "被军方改装的钢铁战衣，加装了加特林机枪和名为“前妻”的微型导弹，火力凶猛但机动性下降。", type: "item"},
            {name: "黑寡妇格斗术", color: "A", cost: 1100, desc: "娜塔莎·罗曼诺夫的看家本领，融合了多种武术的致命杀人技，擅长利用大腿绞杀和关节技。", type: "skill"},
            {name: "汉默的演讲口才", color: "C", cost: 180, desc: "你拥有贾斯汀·汉默那尴尬又迷之自信的口才，虽然经常冷场，但偶尔能忽悠到一些不懂行的投资人。", type: "skill"},
            {name: "霍华德的遗物", color: "B", cost: 500, desc: "一卷旧胶片或一本旧笔记，里面隐藏着关于新元素或未来城市的构想，是开启更高科技树的钥匙。", type: "item"},
            {name: "无人机军团控制权", color: "S", cost: 3500, desc: "你掌握了汉默工业陆海空无人机战队的控制代码。虽然单体战力一般，但胜在数量庞大，适合人海战术。", type: "item"},
            {name: "鸟类喜爱", color: "C", cost: 100, desc: "不知为何，你非常招鹦鹉喜欢。这可能让你在面对伊凡·万科时获得额外的好感度。", type: "status"},
            {name: "激光切割模块", color: "A", cost: 1600, desc: "一次性的强力武器，能发射切割一切物质的红色激光束。使用一次后需要更换昂贵的能量核心。", type: "item"},
            {name: "神盾局顾问", color: "B", cost: 600, desc: "你被神盾局聘为顾问，虽然没有实权，但可以调动一些基础资源，并接触到复仇者联盟的机密档案。", type: "status"},
            {name: "俄语精通", color: "C", cost: 80, desc: "你精通俄语，能听懂那些来自西伯利亚的复仇者的诅咒和低语。", type: "skill"},
            {name: "自毁程序", color: "D", cost: 120, desc: "你的装备里被汉默工业或者万科植入了后门，战斗中可能随时被远程引爆。", type: "curse"}
        ]
    },
    {
        name: "535.(漫威)雷神",
        desc: "神话降临人间。阿斯加德的王子被放逐到地球，寻找失去的神力。这个世界引入了九界、彩虹桥和魔法的概念，科技不再是唯一的真理。",
        boss: "毁灭者装甲, 洛基",
        identities: [
            { name: "新墨西哥州小镇居民", items: "一杯啤酒, 一辆旧皮卡" },
            { name: "天体物理学实习生", items: "一台相位探测器, 一堆看不懂的数据图表" },
            { name: "神盾局外勤特工(鹰眼部下)", items: "一把复合弓, 几个特种箭头" },
            { name: "阿斯加德平民(流放者)", items: "一件破旧的亚麻长袍, 一个空酒壶" },
            { name: "冰霜巨人弃婴", items: "蓝色的皮肤(需遮掩), 无论何时都感觉不到冷" }
        ],
        talents: [
            {name: "举不起的锤子", color: "E", cost: 5, desc: "你捡到了一把锤子，但无论你怎么用力都拿不起来。它除了占地方和当个摆设外，毫无用处。", type: "item"},
            {name: "雷神之躯(封印)", color: "S", cost: 2200, desc: "你拥有阿斯加德王族的身体素质，刀枪不入，力大无穷。但目前神力被奥丁封印，只能发挥出凡人巅峰的水平。", type: "body"},
            {name: "妙尔尼尔(认可)", color: "SSS", cost: 25000, desc: "你拥有举起雷神之锤的资格。获得雷神之力，操控雷电与风暴，拥有飞行能力，是阿斯加德王位的继承证明。", type: "exclusive"},
            {name: "毁灭者光束", color: "S", cost: 3000, desc: "毁灭者装甲的核心武器，能发射分解一切物质的高温光束。威力巨大，但充能时间较长。", type: "skill"},
            {name: "洛基的幻术", color: "SS", cost: 6500, desc: "诡计之神的招牌魔法。你可以制造极其逼真的全息幻象，甚至能欺骗海姆达尔的眼睛，是战场生存的神技。", type: "magic"},
            {name: "彩虹桥召唤", color: "SS", cost: 8000, desc: "你掌握了召唤彩虹桥的咒语或信物。可以随时进行跨星系的传送，或者用彩虹桥的能量轰击地表。", type: "skill"},
            {name: "阿斯加德体质", color: "A", cost: 1500, desc: "阿斯加德人的平均体质，寿命长达5000年，肌肉密度是人类的三倍，普通的枪械无法对你造成致命伤。", type: "body"},
            {name: "冰霜巨人血统", color: "A", cost: 1600, desc: "来自约顿海姆的血脉。你可以制造冰刃，触碰敌人使其冻结。在寒冷环境下战斗力翻倍。", type: "body"},
            {name: "海姆达尔之眼(伪)", color: "S", cost: 2800, desc: "你能看到极远处的景象，甚至能透过障碍物观察灵魂的颜色。虽然比不上正版，但在地球已是神级侦查。", type: "skill"},
            {name: "简·福斯特的笔记", color: "B", cost: 400, desc: "记录了关于爱因斯坦-罗森桥的详细理论，能帮助你理解空间传送的原理，对科技侧玩家有大用。", type: "item"},
            {name: "鹰眼的箭术", color: "A", cost: 1000, desc: "百发百中的神射手天赋。无论目标如何移动，你总能凭直觉射中要害，且擅长使用各种特殊箭头。", type: "skill"},
            {name: "摔杯为号", color: "C", cost: 50, desc: "你学会了阿斯加德人表达喜爱的方式：喝完饮料后把杯子狠狠摔在地上并大喊“再来一杯”。", type: "skill"},
            {name: "仙宫佳酿", color: "B", cost: 300, desc: "一瓶来自阿斯加德的烈酒。凡人喝一口就会醉倒三天三夜，但能大幅永久提升体质和魔力上限。", type: "item"},
            {name: "永恒之枪(投影)", color: "S", cost: 4500, desc: "奥丁武器的能量投影。虽然只有一击之力，但必定命中目标，且带有贯穿一切的神圣属性。", type: "item"},
            {name: "流放诅咒", color: "D", cost: 100, desc: "你被剥夺了原本的力量和地位，必须通过学会谦逊和牺牲才能找回自我。在此之前，你只是个凡人。", type: "curse"}
        ]
    },
    {
        name: "536.(漫威)美国队长1",
        desc: "二战时期的传奇。九头蛇利用宇宙立方的能量制造了超越时代的武器。史蒂夫·罗杰斯成为了第一个超级士兵，正义与邪恶的较量在战火中展开。",
        boss: "红骷髅, 佐拉博士",
        identities: [
            { name: "布鲁克林瘦弱青年", items: "一张4F(体检不合格)通知单, 一个垃圾桶盖" },
            { name: "107步兵团士兵", items: "一把M1加兰德步枪, 一封写给未婚妻的信" },
            { name: "九头蛇武器工厂工人", items: "一把能量扳手, 一个印着章鱼骷髅的袖标" },
            { name: "战略科学军团护士", items: "急救包, 一支青霉素" },
            { name: "咆哮突击队预备役", items: "一顶贝雷帽, 几颗手雷" }
        ],
        talents: [
            {name: "哮喘病", color: "E", cost: 20, desc: "你患有严重的哮喘，剧烈运动会让你窒息。在这个战火纷飞的年代，这简直是判了死刑。", type: "curse"},
            {name: "超级士兵血清(完美)", color: "SS", cost: 9000, desc: "厄斯金博士的杰作。将你的身体机能提升到人类进化的极限，拥有完美的代谢、力量、耐力和自愈力。", type: "body"},
            {name: "振金盾牌", color: "SS", cost: 8500, desc: "由地球上最坚硬的金属制成。能吸收一切动能和震动，违背物理定律地反弹。是攻防一体的神器。", type: "item"},
            {name: "宇宙立方能量块", color: "SSS", cost: 18000, desc: "空间宝石的能量提取物。蕴含着无限的能源，可以用来驱动毁灭性的武器，或者开启空间门。", type: "item"},
            {name: "红骷髅的面具", color: "D", cost: 150, desc: "注射了未完成血清的副作用。你的皮肤脱落，露出红色的骷髅面容。虽然力量增强，但魅力值归零。", type: "curse"},
            {name: "九头蛇能量武器", color: "A", cost: 1200, desc: "利用宇宙立方能量驱动的激光枪。一击就能将敌人化为灰烬，在这个时代属于降维打击的武器。", type: "item"},
            {name: "佐拉算法(雏形)", color: "S", cost: 3500, desc: "一种极其复杂的数据分析模型，能通过过去的行为预测未来。虽然还在早期，但已具备惊人的战略价值。", type: "skill"},
            {name: "咆哮突击队战术", color: "B", cost: 600, desc: "你精通特种作战和小队配合。在你的指挥下，即便是普通士兵也能发挥出精锐部队的战斗力。", type: "skill"},
            {name: "霍华德的悬浮车", color: "B", cost: 500, desc: "斯塔克早期的反重力技术原型。虽然经常故障掉下来，但在1940年代能飞起来已经是神迹了。", type: "item"},
            {name: "美国队长的演讲", color: "B", cost: 400, desc: "你拥有极强的号召力。你的战前动员能让士气低落的士兵变成无畏的勇士，全属性临时提升。", type: "skill"},
            {name: "瓦尔基里轰炸机", color: "A", cost: 2000, desc: "九头蛇的超巨型空中堡垒，携带足以毁灭美国东海岸的核弹头。需要多人驾驶。", type: "item"},
            {name: "血清强化代谢", color: "A", cost: 1000, desc: "你的新陈代谢是常人的四倍。酒精对你无效，毒素会被快速排出，受伤后恢复速度极快。", type: "body"},
            {name: "冰封沉睡", color: "C", cost: 200, desc: "在极寒环境下，你会进入假死状态而非死亡。这可能是你穿越时间前往70年后的唯一方法。", type: "skill"},
            {name: "巴基的狙击术", color: "B", cost: 700, desc: "精湛的狙击技巧，能在移动的列车上精准命中远处的敌人。是掩护队友的最佳技能。", type: "skill"},
            {name: "九头蛇万岁", color: "C", cost: 100, desc: "你是九头蛇的死忠。在面对同阵营NPC时，这句口号能让你获得额外的援助，但在盟军面前会招致杀身之祸。", type: "status"}
        ]
    },
    {
        name: "537.(漫威)复仇者联盟1",
        desc: "集结的时刻。洛基带着心灵权杖和齐塔瑞大军降临纽约。六位初代复仇者首次联手，面对前所未有的外星威胁。大场面，大集结。",
        boss: "洛基, 齐塔瑞母舰",
        identities: [
            { name: "神盾局空天母舰操作员", items: "神盾局制服, 玩小蜜蜂游戏的电脑" },
            { name: "纽约曼哈顿警察", items: "一把警用手枪, 一个扩音器" },
            { name: "斯塔克大厦前台", items: "一部高级平板电脑, 托尼·斯塔克的行程表" },
            { name: "被控制的鹰眼部下", items: "特种作战装备, 浑浊的蓝色眼睛" },
            { name: "齐塔瑞步兵", items: "一把能量长矛, 连接母舰的神经链接" }
        ],
        talents: [
            {name: "心灵权杖(借用)", color: "SSS", cost: 22000, desc: "镶嵌着心灵宝石的权杖。可以控制他人的心智，发射能量波，甚至能关闭空间传送门。拥有它你就是半个神。", type: "item"},
            {name: "浩克摔", color: "S", cost: 3000, desc: "“好弱的神”。抓住敌人的腿部进行高频率的反复摔打。对神性生物有奇效，能造成巨大的物理和精神伤害。", type: "skill"},
            {name: "MK7追踪导弹", color: "A", cost: 1500, desc: "钢铁侠MK7装甲搭载的微型导弹群，能同时锁定数十个目标进行精确打击，清杂兵的神技。", type: "item"},
            {name: "齐塔瑞飞行器", color: "B", cost: 600, desc: "外星单兵飞行载具，机动性极强但防御薄弱。需要一定的驾驶技巧，否则容易撞大楼。", type: "item"},
            {name: "利维坦巨兽召唤", color: "S", cost: 4000, desc: "召唤一只巨大的齐塔瑞生物战舰。它像游鱼一样在空中飞行，身披重甲，能轻易撞毁高楼大厦。", type: "skill"},
            {name: "神盾局特工身手", color: "B", cost: 500, desc: "经过科尔森级别的训练，精通各种枪械、驾驶和格斗，是凡人中的精英战斗力。", type: "skill"},
            {name: "核弹拦截", color: "SS", cost: 7000, desc: "你拥有在太空中拦截或引导核弹的能力。这是一次性的英雄壮举，可能会导致你迷失在虫洞另一端。", type: "skill"},
            {name: "雷神之怒", color: "SS", cost: 6000, desc: "引动巨大的闪电轰击克莱斯勒大厦顶端，利用传导效应瞬间歼灭传送门涌出的所有敌人。", type: "skill"},
            {name: "总是生气", color: "A", cost: 1200, desc: "班纳博士的秘诀。你不需要等待愤怒积累，可以随时随地瞬间变身浩克，并保持一定的理智。", type: "skill"},
            {name: "复仇者集结", color: "S", cost: 3500, desc: "当与队友并肩作战时，所有属性提升30%，且默契度达到满值，能打出完美的连携攻击。", type: "status"},
            {name: "考森的绝唱", color: "B", cost: 800, desc: "你的死亡将成为团结团队的催化剂。如果你牺牲，所有队友将获得“复仇”BUFF，战斗力翻倍。", type: "concept"},
            {name: "沙威玛聚餐", color: "C", cost: 50, desc: "战后补充体力的最佳选择。在极度疲惫后进食沙威玛，能快速恢复所有生命值和精力。", type: "item"},
            {name: "空间宝石(宇宙立方)", color: "SSS", cost: 30000, desc: "无限原石之一。拥有开启任意空间门、传送军队、甚至重塑空间结构的能力。力量过于强大，凡人无法触碰。", type: "exclusive"},
            {name: "被洗脑", color: "D", cost: 100, desc: "你的心智被心灵权杖扭曲，虽然保留了技能，但你会无条件服从洛基的命令，直到受到强烈撞击。", type: "curse"},
            {name: "独眼局长的信任", color: "A", cost: 1000, desc: "尼克·弗瑞认为你是可以托付这一只眼的人。你可以调动神盾局的高级资源，甚至知晓一些绝密计划。", type: "status"}
        ]
    },
    {
        name: "538.(漫威)钢铁侠3",
        desc: "托尼·斯塔克的焦虑症与绝境病毒的威胁。满大人的恐怖袭击笼罩全美。这是一个关于“人造就了战甲，还是战甲造就了人”的自我救赎故事。",
        boss: "阿尔德里奇·基里安, 满大人(特雷弗)",
        identities: [
            { name: "田纳西州小镇男孩", items: "一把土豆枪, 一块限量版手表" },
            { name: "绝境病毒实验体", items: "不稳定的体温, 随时可能爆炸的身体" },
            { name: "空军一号保镖", items: "一套西装, 隐藏的枪械" },
            { name: "满大人的替身演员", items: "一件戏袍, 两罐啤酒" },
            { name: "AIM科技员工", items: "一张门禁卡, 绝境病毒数据盘" }
        ],
        talents: [
            {name: "焦虑症发作", color: "D", cost: 80, desc: "纽约之战的后遗症。在听到特定词汇或处于压力下时，你会呼吸困难，无法战斗，必须平复心情。", type: "curse"},
            {name: "绝境病毒(完美)", color: "SS", cost: 8500, desc: "改造人体DNA，赋予超高的体温、断肢重生能力和喷火能力。完美版不会自爆，且力量足以手撕钢铁战衣。", type: "body"},
            {name: "MK42浪子", color: "SS", cost: 6000, desc: "具备远程植入和分体组合功能的战甲。可以随时召唤部件覆盖全身，或将部件发射到敌人身上进行禁锢自爆。", type: "item"},
            {name: "家庭派对协议", color: "SSS", cost: 15000, desc: "召唤数十套功能各异的钢铁战衣进行自动作战。这是斯塔克军团的狂欢，足以独自对抗一只军队。", type: "skill"},
            {name: "满大人的演技", color: "C", cost: 200, desc: "你拥有奥斯卡级别的演技，能把自己伪装成恐怖分子首领而不被发现，实际上你只想要毒品和美女。", type: "skill"},
            {name: "高温触碰", color: "A", cost: 1500, desc: "绝境病毒能力之一。你的手掌能产生3000度的高温，瞬间熔化钢铁或烧穿人体。", type: "skill"},
            {name: "哈利的机械天赋", color: "B", cost: 400, desc: "虽然是个孩子，但拥有极佳的动手能力。能帮斯塔克修理战甲，是绝佳的辅助型队友。", type: "talent"},
            {name: "钢铁爱国者", color: "S", cost: 3000, desc: "重新涂装的战争机器，代表了美国政府的形象。性能均衡，火力强大，但容易被黑客入侵。", type: "item"},
            {name: "全息投影犯罪现场", color: "A", cost: 900, desc: "贾维斯的高级功能。能将爆炸现场的数据重构为全息影像，让你身临其境地调查线索。", type: "skill"},
            {name: "绝境自爆", color: "S", cost: 2000, desc: "当生命值归零时，引发一场威力巨大的热能爆炸，摧毁周围的一切。这是最后的同归于尽手段。", type: "skill"},
            {name: "伊戈尔(MK38)", color: "A", cost: 1800, desc: "重型起重装甲。虽然战斗力不强，但拥有巨大的力量，能支撑起坍塌的港口起重机。", type: "item"},
            {name: "双子座(MK39)", color: "A", cost: 1800, desc: "亚轨道飞行装甲。能让你飞出大气层，在这个高度你是无敌的，适合进行战略打击。", type: "item"},
            {name: "外科手术移除", color: "B", cost: 600, desc: "精准的磁力吸取技术，能安全地将体内的弹片或异物取出，彻底治愈托尼的心脏隐患。", type: "skill"},
            {name: "圣诞节礼物", color: "C", cost: 50, desc: "你在圣诞节总能收到意想不到的好运。也许是一个巨大的兔子玩偶，也许是一套全新的实验室设备。", type: "status"},
            {name: "冒牌恐怖分子", color: "D", cost: 100, desc: "你被全世界通缉，但实际上你手无缚鸡之力。这种反差让你在面对真正的敌人时非常危险。", type: "curse"}
        ]
    },
    {
        name: "539.(漫威)雷神2：黑暗世界",
        desc: "黑暗精灵玛勒基斯苏醒，企图利用以太粒子（现实宝石）让宇宙重归黑暗。九界汇聚的天文奇观即将出现，阿斯加德面临入侵。",
        boss: "玛勒基斯, 诅咒战士",
        identities: [
            { name: "伦敦格林威治天文台实习生", items: "相位测量仪, 几根重力异常的棍子" },
            { name: "阿斯加德地牢守卫", items: "金色的盔甲, 长矛" },
            { name: "黑暗精灵士兵", items: "奇异的面具, 黑洞手雷" },
            { name: "瓦特海姆难民", items: "破烂的衣服, 对光明的恐惧" },
            { name: "精神病院病患(艾瑞克)", items: "根本没穿裤子, 两个鞋子模型" }
        ],
        talents: [
            {name: "以太粒子(寄生)", color: "SSS", cost: 28000, desc: "现实宝石的液态形式。寄生在你体内，赋予你修改现实、物质转换的能力。但它会不断汲取你的生命力。", type: "exclusive"},
            {name: "诅咒战士化", color: "SS", cost: 7000, desc: "捏碎诅咒之石，牺牲理智和生命，换取超越雷神的肉体力量。能轻易拍飞妙尔尼尔，但变身不可逆。", type: "body"},
            {name: "黑洞手雷", color: "S", cost: 2500, desc: "黑暗精灵的科技结晶。爆炸后产生微型奇点，将周围的物质瞬间吸入并挤压粉碎，无法防御。", type: "item"},
            {name: "相位转换装置", color: "A", cost: 1200, desc: "艾瑞克博士发明的几根棍子。能利用九界汇聚的引力异常，将巨大的物体（甚至飞船）传送回异世界。", type: "item"},
            {name: "隐形飞船技术", color: "A", cost: 1500, desc: "黑暗精灵的飞船拥有极高的隐身性能，连海姆达尔的眼睛都难以察觉，适合偷袭和潜入。", type: "skill"},
            {name: "弗丽嘉的幻术", color: "S", cost: 3000, desc: "神后亲传的魔法。比洛基的更高级，能制造出具有实体的分身，甚至能短暂欺骗现实。", type: "magic"},
            {name: "九界汇聚", color: "S", cost: 5000, desc: "每5000年一次的天文奇观。在此期间，九界的空间壁垒消失，你可以随意穿梭于各个世界之间。", type: "event"},
            {name: "雷神之母的祝福", color: "B", cost: 600, desc: "弗丽嘉的护身符。能抵挡一次致命的魔法攻击，并在关键时刻指引你找到正确的道路。", type: "item"},
            {name: "裸奔的科学家", color: "D", cost: 50, desc: "你的思维过于超前以至于被认为是疯子。你喜欢在巨石阵裸奔来思考重力问题，社会声望为负。", type: "curse"},
            {name: "阿斯加德防护罩", color: "A", cost: 2000, desc: "保护金宫的能量护盾。能抵挡飞船的撞击和重火力的轰炸，是据点防守的强力设施。", type: "item"},
            {name: "喵喵锤挂架", color: "C", cost: 20, desc: "一个普通的衣帽钩，但雷神把锤子挂在上面了。证明了只要角度刁钻，凡物也能承载神器。", type: "item"},
            {name: "黑暗世界适应", color: "B", cost: 300, desc: "你适应了瓦特海姆的无光环境。在黑暗中视野不受影响，潜行能力大幅提升。", type: "body"},
            {name: "现实扭曲(初级)", color: "SS", cost: 9000, desc: "利用以太粒子的力量，你可以将物体变成气泡或蝴蝶。虽然杀伤力不大，但侮辱性极强。", type: "magic"},
            {name: "洛基的假死", color: "A", cost: 1800, desc: "一种极其逼真的假死技巧，配合幻术使用。能骗过所有人，让你金蝉脱壳并暗中篡夺权力。", type: "skill"},
            {name: "空间裂缝感知", color: "B", cost: 500, desc: "你能感知到空间薄弱点，在战斗中利用这些裂缝转移攻击或瞬间移动。", type: "skill"}
        ]
    },
    {
        name: "540.(漫威)美国队长2：冬日战士",
        desc: "神盾局已死，九头蛇万岁。这是一部政治惊悚片，昔日的战友变成死敌，洞察计划将威胁数百万人的生命。信任是这个世界最奢侈的东西。",
        boss: "冬日战士(巴基), 亚历山大·皮尔斯",
        identities: [
            { name: "神盾局总部文员", items: "加密的U盘, 一杯咖啡" },
            { name: "华盛顿晨跑路人", items: "运动鞋, 总是被队长超圈的心理阴影" },
            { name: "九头蛇突击队员", items: "电击棍, 战术面具" },
            { name: "洞察计划程序员", items: "算法代码, 锁死的机房" },
            { name: "博物馆保安", items: "制服, 美国队长二战制服(展示品)" }
        ],
        talents: [
            {name: "金属手臂", color: "S", cost: 3500, desc: "苏联制造的仿生机械臂。力量足以捏碎钢铁，接住队长的盾牌。不仅是武器，也是身份的象征。", type: "item"},
            {name: "洞察计划算法", color: "SS", cost: 8000, desc: "佐拉算法的终极版。通过分析过去，预测未来。能瞬间锁定全球数百万潜在威胁目标并予以清除。", type: "skill"},
            {name: "猎鹰飞行翼(EXO-7)", color: "A", cost: 2200, desc: "军用单兵飞行背包，配备红翼侦查器和冲锋枪。机动性极高，是空中格斗的利器。", type: "item"},
            {name: "洗脑词", color: "D", cost: 150, desc: "渴望、生锈、十七... 当听到这一串词语时，你会瞬间失去自我，变成只知道服从命令的杀人机器。", type: "curse"},
            {name: "电梯战神", color: "A", cost: 1200, desc: "在狭窄封闭的空间内（如电梯），你的格斗能力提升200%。你可以单挑十几个受过训练的特工。", type: "skill"},
            {name: "尼克·弗瑞的假死药", color: "A", cost: 1000, desc: "河豚毒素B制剂。能让心跳降低到每分钟1次，骗过所有生命体征监测仪器。绝境逢生的神药。", type: "item"},
            {name: "九头蛇渗透", color: "B", cost: 600, desc: "你看似是正义的一方，实则是九头蛇的卧底。你可以利用双重身份获取两边的情报和资源。", type: "status"},
            {name: "盾牌格斗术", color: "S", cost: 2500, desc: "不仅是防御，更是进攻。你精通利用盾牌的反弹特性进行几何打击，一击放倒多个敌人。", type: "skill"},
            {name: "局长的工具箱", color: "SS", cost: 6000, desc: "一个黑色的立方体，储存了神盾局所有的机密档案和重建资源。只有局长的视网膜能解开。", type: "item"},
            {name: "左边！", color: "C", cost: 50, desc: "你的速度远超常人，在跑步时总是从左边超越别人。这会给被超越者带来极大的心理压力。", type: "skill"},
            {name: "三飞饰总部权限", color: "B", cost: 800, desc: "你拥有神盾局总部的最高级通行证。可以控制大楼的防御系统，或者发射空天母舰。", type: "status"},
            {name: "数据盘(星战版)", color: "B", cost: 500, desc: "存有洞察计划核心数据的U盘。它是所有势力争夺的焦点，藏在自动贩卖机里是个不错的选择。", type: "item"},
            {name: "光子易容面具", color: "A", cost: 1500, desc: "黑寡妇使用的纳米面具。能完美模拟任何人的面部特征和声音，是潜入和欺诈的神器。", type: "item"},
            {name: "空天母舰主炮", color: "SS", cost: 5500, desc: "洞察计划母舰的远程狙击炮。能从亚轨道精准打击地面目标，威力堪比小型核弹。", type: "item"},
            {name: "信任危机", color: "D", cost: 100, desc: "在这个世界，你无法完全信任任何人。你的队友随时可能背后捅刀子，组队收益减半。", type: "curse"}
        ]
    },
    {
        name: "541.(漫威)银河护卫队1",
        desc: "画风突变，太空歌剧开启。一群废柴组成的银河护卫队。这里有会说话的浣熊和树人，还有无限宝石中破坏力最强的力量宝石。",
        boss: "罗南, 星云",
        identities: [
            { name: "山达尔星市民", items: "色彩鲜艳的衣服, 诺瓦军团求救信号器" },
            { name: "克林监狱囚犯", items: "黄色的囚服, 一条假腿(虽然不需要)" },
            { name: "掠夺者船员", items: "一把哨箭(仿制), 一口烂牙" },
            { name: "收藏家的奴仆", items: "粉色的皮肤, 随时准备打扫卫生的刷子" },
            { name: "新星军团卫兵", items: "新星头盔, 连在一起的飞船驾驶权" }
        ],
        talents: [
            {name: "宇宙灵球(力量宝石)", color: "SSS", cost: 35000, desc: "无限原石之一。蕴含着宇宙绝对的力量。接触地面可以摧毁一颗星球。凡人触碰会瞬间灰飞烟灭。", type: "exclusive"},
            {name: "我是格鲁特", color: "A", cost: 1000, desc: "你只会说这一句话，但包含了千言万语。拥有强大的植物再生能力，断肢重生，还能生长出藤蔓杀敌。", type: "body"},
            {name: "亚卡箭(哨箭)", color: "SS", cost: 7500, desc: "勇度的神技。通过口哨声控制的一支飞箭，能以极快的速度穿透飞船和人体，清场效率极高。", type: "skill"},
            {name: "星爵的随身听", color: "B", cost: 500, desc: "一台索尼Walkman和劲歌金曲磁带。播放音乐时，你的运气值大幅提升，且能通过尬舞干扰BOSS。", type: "item"},
            {name: "火箭的拼装术", color: "S", cost: 2800, desc: "给我一条腿和一个电池，我就能造出越狱的炸弹。对机械和爆炸物有着疯狂的天赋。", type: "skill"},
            {name: "毁灭者的复仇", color: "A", cost: 1500, desc: "德拉克斯的被动。对罗南和灭霸阵营的敌人伤害加成50%，但智商会降低，无法理解隐喻。", type: "skill"},
            {name: "万能破解器", color: "A", cost: 1200, desc: "星爵的开锁工具。能破解绝大多数电子门锁和飞船启动系统，是星际大盗的必备良品。", type: "item"},
            {name: "克林监狱越狱王", color: "B", cost: 800, desc: "你熟悉宇宙中各大监狱的构造和潜规则。在监狱环境中，你的声望极高，总能找到越狱的方法。", type: "status"},
            {name: "半神血统(未觉醒)", color: "SS", cost: 6000, desc: "你是伊戈的孩子。虽然现在只是凡人，但拥有承载无限宝石而不死的潜力，觉醒后可操控光能。", type: "body"},
            {name: "哈德隆恩炮", color: "S", cost: 3500, desc: "火箭制造的重型武器。据说能炸毁月球（可能是吹牛），但威力绝对足以轰开罗南战舰的装甲。", type: "item"},
            {name: "收藏家的藏品", color: "C", cost: 300, desc: "你被关在收藏家的玻璃柜里。虽然失去了自由，但绝对安全，还能看到宇宙各种奇珍异宝。", type: "curse"},
            {name: "太空义肢", color: "B", cost: 400, desc: "星云同款的机械义肢。虽然痛苦，但赋予了你超强的力量和自我修复能力。", type: "body"},
            {name: "尬舞对决", color: "C", cost: 100, desc: "在关键时刻发起舞蹈挑战。这会让敌人陷入短暂的懵逼状态，为你争取宝贵的反击时间。", type: "skill"},
            {name: "米兰诺号", color: "S", cost: 4000, desc: "星爵的飞船。虽然看起来有些旧，但经过改装，机动性和火力都是一流的，还自带很棒的音响。", type: "item"},
            {name: "不需要的假腿", color: "D", cost: 50, desc: "火箭浣熊让你去偷的一条假腿，实际上根本不需要。这只是个恶作剧，但你为此冒了生命危险。", type: "item"}
        ]
    },
     {
        name: "542.(漫威)复仇者联盟2",
        desc: "人工智能的反叛。托尼·斯塔克试图创造一个维护和平的AI奥创，却制造了一个企图通过陨石撞击毁灭人类的怪物。索科维亚成为战场，双胞胎异能者登场。",
        boss: "奥创(最终形态), 绯红女巫(初期)",
        identities: [
            { name: "索科维亚难民", items: "一张全家福, 一块被炸碎的砖头" },
            { name: "九头蛇古堡守卫", items: "齐塔瑞能量枪, 战术目镜" },
            { name: "复仇者大厦保洁员", items: "被雷神之锤压坏的桌子残骸, 扫帚" },
            { name: "奥创军团量产机", items: "损坏的飞行推进器, 连接奥创主脑的Wifi" },
            { name: "赵海伦博士的助手", items: "再生摇篮操作手册, 组织打印机" }
        ],
        talents: [
            {name: "振金身躯(幻视)", color: "SSS", cost: 28000, desc: "由再生摇篮制造，振金原子与有机组织完美结合的身体。拥有穿透物质、改变密度、飞行和发射心灵宝石光束的能力。", type: "exclusive"},
            {name: "混沌魔法(觉醒)", color: "SSS", cost: 32000, desc: "绯红女巫的潜能。修改概率，扭曲现实，心灵控制。虽然目前还不稳定，但这是漫威宇宙最强的魔法力量源泉。", type: "magic"},
            {name: "极速者(快银)", color: "SS", cost: 9000, desc: "虽然在这个世界容易被子弹打中（剧情杀），但你的速度能达到音速。新陈代谢极快，能瞬间拆解机器人。", type: "body"},
            {name: "反浩克装甲(维罗妮卡)", color: "SS", cost: 8500, desc: "斯塔克工业的巅峰之作。专为压制浩克设计，拥有卫星补给配件，能边打边修，力量足以与浩克角力。", type: "item"},
            {name: "奥创的主脑", color: "S", cost: 5000, desc: "你拥有将意识上传到网络并在任意机械载体中重生的能力。只要互联网存在，你就永生不死。", type: "talent"},
            {name: "心灵宝石(原石)", color: "SSS", cost: 30000, desc: "镶嵌在幻视头顶。赋予最高级的智慧，能发射高能激光。是六大无限原石之一，宇宙级宝物。", type: "exclusive"},
            {name: "再生摇篮技术", color: "S", cost: 3500, desc: "能利用纳米分子打印人体组织。无论是断肢还是脏器受损，只要没死透，都能完美修复。", type: "skill"},
            {name: "振金贩子", color: "A", cost: 1800, desc: "你像尤利西斯·克劳一样，拥有大量振金存货。在这个金属稀缺的世界，你富可敌国。", type: "status"},
            {name: "索科维亚陨石", color: "E", cost: 10, desc: "你住在索科维亚。如果你不能在城市升空并坠落前撤离，你将成为人类灭绝计划的陪葬品。", type: "curse"},
            {name: "电磁脉冲(EMP)", color: "A", cost: 1200, desc: "针对奥创军团的大杀器。能瞬间瘫痪周围所有非防护级别的电子设备，对机器人有奇效。", type: "skill"},
            {name: "鹰眼的农场", color: "B", cost: 600, desc: "一个绝对安全的避难所。当世界大乱时，这里是唯一能让你喝杯热茶、劈劈柴的宁静之地。", type: "status"},
            {name: "值得一试", color: "C", cost: 100, desc: "在举起雷神之锤的挑战中，你能让锤子稍微动一下。这足以让你获得雷神惊恐的眼神和众人的尊敬。", type: "skill"},
            {name: "奥创哨兵", color: "B", cost: 800, desc: "你可以召唤或控制3台奥创量产机器人。虽然单体脆皮，但胜在不知疲倦，适合当炮灰。", type: "item"},
            {name: "精神控制抵抗", color: "A", cost: 1000, desc: "你的意志如钢铁般坚硬，能免疫绯红女巫初级的精神干扰，不会陷入噩梦幻境。", type: "talent"},
            {name: "割草机", color: "C", cost: 150, desc: "面对海量的杂兵机器人，你的攻击具有溅射效果，清理杂兵的效率提升100%。", type: "skill"}
        ]
    },
    {
        name: "543.(漫威)蚁人",
        desc: "微观世界的奇妙冒险。斯科特·朗出狱后接过了蚁人的战衣。这里没有毁天灭地的爆炸，只有变大变小的战术博弈和精心策划的偷盗行动。",
        boss: "黄蜂战士(达伦·克劳斯)",
        identities: [
            { name: "巴斯金-罗宾斯冰淇淋店员", items: "制服, 总是会被发现的犯罪记录" },
            { name: "皮姆科技保安", items: "电击枪, 对讲机" },
            { name: "旧金山职业窃贼", items: "开锁工具包, 一辆破旧的面包车" },
            { name: "克劳斯科技研究员", items: "不稳定的缩小血清, 显微镜" },
            { name: "路易斯的狱友", items: "极其啰嗦的嘴, 制作华夫饼的技巧" }
        ],
        talents: [
            {name: "皮姆粒子(红/蓝)", color: "SSS", cost: 15000, desc: "改变物体原子间距的神奇粒子。红色缩小，蓝色变大。这是违反物理定律的核心科技，能将坦克变成钥匙扣。", type: "item"},
            {name: "蚁人战衣(二代)", color: "SS", cost: 7000, desc: "斯科特·朗的装备。能自由切换体型，保留原有的动能（缩小后子弹般的冲击力）。配备昆虫通讯器。", type: "item"},
            {name: "昆虫指挥官", color: "A", cost: 1500, desc: "通过电磁波控制蚂蚁。你可以指挥子弹蚁攻击、火蚁搭桥、飞蚁运输。在特定环境下是无敌的军团。", type: "skill"},
            {name: "量子领域(迷失)", color: "E", cost: 50, desc: "你调节器故障，无限缩小进入了量子领域。在这里时间和空间失去意义，如果无法恢复，你将永远困在虚无中。", type: "curse"},
            {name: "黄蜂战士战甲", color: "S", cost: 4500, desc: "达伦·克劳斯的杰作。除了缩小功能外，还配备了飞行翼和两条机械激光臂，火力比蚁人战衣更猛。", type: "item"},
            {name: "神偷团队", color: "B", cost: 800, desc: "你有三个死党：路易斯（情报）、戴夫（车技）、库尔特（黑客）。虽然看起来不靠谱，但任务成功率100%。", type: "status"},
            {name: "托马斯小火车", color: "C", cost: 200, desc: "被放大的玩具火车。虽然本质是塑料，但巨大的体积让它拥有了碾压房屋的破坏力，极其荒诞的武器。", type: "item"},
            {name: "有机体凝胶化", color: "D", cost: 100, desc: "使用了未完善的缩小枪。如果不穿防护服，你会被缩小成一滩恶心的果冻状液体。", type: "curse"},
            {name: "潜行大师", color: "A", cost: 1200, desc: "你精通各种潜入技巧，配合缩小能力，世界上没有任何金库能拦住你。复联基地也不例外。", type: "skill"},
            {name: "钥匙扣坦克", color: "S", cost: 2500, desc: "汉克·皮姆的收藏品。平时是钥匙扣，扔出去就是一辆满载弹药的T-34坦克。出其不意的重火力。", type: "item"},
            {name: "路易斯的叙事法", color: "C", cost: 50, desc: "你讲故事时会配上极其洗脑的BGM和口型同步。虽然很啰嗦，但能让听众不由自主地听完，适合拖延时间。", type: "skill"},
            {name: "飞盘飞镖", color: "B", cost: 500, desc: "红蓝两色的飞镖，击中物体后瞬间将其缩小或放大。战术用途极广，可以用来清理路障或投掷巨大的盐罐。", type: "item"},
            {name: "猎鹰的目镜", color: "B", cost: 600, desc: "具有高级热成像和微观扫描功能的护目镜，能发现缩小后的敌人。", type: "item"},
            {name: "量子纠缠(初兆)", color: "SS", cost: 6000, desc: "你曾短暂接触过量子领域，获得了与珍妮特类似的联系。能感知量子能量，甚至短暂虚化身体。", type: "talent"},
            {name: "必须有前科", color: "D", cost: 20, desc: "因为有犯罪记录，你找不到正经工作，只能去巴斯金-罗宾斯卖冰淇淋，而且随时会被辞退。", type: "curse"}
        ]
    },
    {
        name: "544.(漫威)美国队长3：内战",
        desc: "复仇者联盟的分裂。索科维亚协议要求英雄接受监管。泽莫男爵在暗中挑拨，钢铁侠与美国队长因理念和巴基的问题爆发内战。",
        boss: "泽莫男爵, 钢铁侠/美国队长(取决于阵营)",
        identities: [
            { name: "联合国维也纳会议代表", items: "索科维亚协议草案, 防爆公文包" },
            { name: "拉各斯雇佣兵", items: "生化武器样本, 强力弹跳靴" },
            { name: "莱比锡机场地勤", items: "耳罩, 看着满天飞的英雄发呆" },
            { name: "瓦坎达潜伏间谍", items: "振金匕首, 伪造护照" },
            { name: "皇后区高中生", items: "自制蛛网发射器, 一台捡来的DVD机" }
        ],
        talents: [
            {name: "黑豹战衣(储能)", color: "SS", cost: 8500, desc: "瓦坎达国王的战甲。全振金编织，刀枪不入。具备吸收动能并释放紫色冲击波的能力，攻防一体。", type: "item"},
            {name: "蜘蛛感应(初级)", color: "SS", cost: 7000, desc: "彼得·帕克的天赋。能在危险发生前一瞬间感知到威胁。虽然此时还很青涩，但足以躲避冬兵的拳头。", type: "talent"},
            {name: "巨化人形态", color: "S", cost: 4000, desc: "蚁人的逆向操作。变成20米高的巨人，力量暴增，能把飞机当玩具扔。但动作迟缓且极度消耗体力。", type: "skill"},
            {name: "泽莫的小红书", color: "A", cost: 2000, desc: "记载了启动冬日战士的口令以及九头蛇的秘密。拥有它，你就掌握了分裂复联的钥匙。", type: "item"},
            {name: "索科维亚协议", color: "D", cost: 100, desc: "签署后，你的行动受联合国小组监管。虽然合法，但无法自由行侠仗义，违令会被关进水下监狱。", type: "curse"},
            {name: "红翼无人机", color: "B", cost: 800, desc: "猎鹰的助手。具备侦查、扫描和机枪扫射功能。体积小巧，难以被击中。", type: "item"},
            {name: "蜘蛛丝发射器(斯塔克版)", color: "A", cost: 1500, desc: "托尼升级版。拥有576种蛛网组合模式，包括电击网、分裂网等。高强度蛛丝能拉停飞机。", type: "item"},
            {name: "瓦坎达格斗术", color: "A", cost: 1200, desc: "黑豹皇室的战斗技巧，模仿野兽的动作，凶猛且敏捷，擅长爪击和翻滚。", type: "skill"},
            {name: "血边装甲(MK46)", color: "SS", cost: 8000, desc: "流线型设计，便携且反应速度极快。拥有全方位的微型导弹和集束炮，单挑美队和冬兵不落下风。", type: "item"},
            {name: "二打一", color: "C", cost: 50, desc: "当你和你的基友同时攻击一个敌人时，默契度提升，敌人格挡率下降50%。盾牌传递更加顺畅。", type: "status"},
            {name: "水下监狱(筏)", color: "D", cost: 200, desc: "你被关押在公海深处的最高设防监狱。没有超能力抑制项圈，四周是深海，越狱难度极高。", type: "curse"},
            {name: "巴基的李子", color: "C", cost: 10, desc: "几个新鲜的李子。虽然没什么用，但能稍微唤醒冬兵的一丝人性记忆。", type: "item"},
            {name: "幻视的虚化", color: "SS", cost: 6500, desc: "控制身体密度穿透物体。在这个状态下你免疫物理攻击，也能瞬间增加密度摧毁敌人内部。", type: "skill"},
            {name: "交叉骨拳套", color: "A", cost: 1000, desc: "液压助力的重型拳套，附带伸缩冲角。一拳能把防弹门轰开，是近战肉搏的利器。", type: "item"},
            {name: "你的左眼", color: "E", cost: 30, desc: "在战斗中你的义眼可能会被打掉（像雷神3那样），导致视野受损，命中率下降。", type: "curse"}
        ]
    },
    {
        name: "545.(漫威)奇异博士",
        desc: "魔法侧的大门开启。神经外科医生史蒂芬·斯特兰奇车祸后寻求治愈，却成为了至尊法师的继任者。多维空间、时间倒流、黑暗维度降临。",
        boss: "多玛姆, 卡西利亚斯",
        identities: [
            { name: "卡玛泰姬学徒", items: "练习用法戒, 红色练功服" },
            { name: "纽约圣所守护者", items: "法器展示柜钥匙, 拖把" },
            { name: "大都会医院护士", items: "克里斯汀的呼叫机, 昂贵的雪茄" },
            { name: "黑暗信徒", items: "眼周的黑暗印记, 空间碎片" },
            { name: "加德满都乞丐", items: "破碗, 一张写着Shamballa的Wifi密码纸" }
        ],
        talents: [
            {name: "阿戈摩托之眼(时间宝石)", color: "SSS", cost: 40000, desc: "无限原石之一。控制时间流速，倒流时间，制造时间循环。最强的外挂，能让多玛姆都崩溃。", type: "exclusive"},
            {name: "悬浮斗篷", color: "S", cost: 4500, desc: "拥有自我意识的法器。不仅能让你飞行，还能自动防御、缠住敌人、甚至帮你擦眼泪。", type: "item"},
            {name: "悬戒(空间门)", color: "A", cost: 1500, desc: "法师的标配。画圈圈打开通往世界各地的传送门。也能用来切割敌人（如果关门够快的话）。", type: "item"},
            {name: "镜像维度", color: "SS", cost: 6000, desc: "创造一个与现实平行的镜像空间。在这里你可以随意折叠城市、扭曲引力，且不会影响现实世界。", type: "magic"},
            {name: "过目不忘", color: "S", cost: 3000, desc: "斯特兰奇的天赋。你能以惊人的速度阅读并理解晦涩的魔法书籍，甚至在睡眠中灵魂出窍学习。", type: "talent"},
            {name: "维山帝神圣之剑", color: "A", cost: 1200, desc: "召唤金色的魔法能量剑或鞭。对黑暗生物有加成伤害，近战法师的首选。", type: "magic"},
            {name: "双手残废", color: "D", cost: 150, desc: "你的双手神经严重受损，颤抖不止。无法进行精细操作（如手术或射击），施法速度降低20%。", type: "curse"},
            {name: "多玛姆的赐福", color: "S", cost: 5000, desc: "汲取黑暗维度的力量。获得永生不死的能力和强大的空间折叠术，但代价是沦为多玛姆的奴隶。", type: "curse"},
            {name: "灵魂出窍", color: "A", cost: 1800, desc: "将星体灵体与肉身分离。灵体隐形且能飞行，适合侦查或在肉体重伤时继续战斗。", type: "magic"},
            {name: "瓦图姆魔杖", color: "B", cost: 800, desc: "香港圣所王法师使用的法器。能聚集魔力防御攻击，物理打击感也不错。", type: "item"},
            {name: "谈条件", color: "SSS", cost: 10000, desc: "因果律技能。当你陷入必死循环时，你可以强行与BOSS进行谈判，直到对方厌烦而妥协。", type: "concept"},
            {name: "至尊法师的藏书", color: "S", cost: 3500, desc: "卡廖斯特罗之书等禁忌典籍。记载了操控时间、黑暗魔法等高阶法术，阅读需谨慎。", type: "item"},
            {name: "塞拉芬之盾", color: "A", cost: 1400, desc: "召唤巨大的红色魔法盾牌，防御力极强，能抵挡飞船坠毁的冲击。", type: "magic"},
            {name: "克里斯汀的吻", color: "C", cost: 50, desc: "来自前女友的关怀。当你濒死灵魂出窍时，她的电击起搏能把你拉回人间。", type: "status"},
            {name: "Wifi密码", color: "C", cost: 10, desc: "Shamballa。连接卡玛泰姬的网络，虽然没啥大用，但能让你不脱离现代社会。", type: "item"}
        ]
    },
    {
        name: "546.(漫威)银河护卫队2",
        desc: "关于家庭与身世的探索。星爵见到了生父伊戈——一颗活体星球。银河护卫队面临分崩离析，勇度用生命诠释了什么是父亲。",
        boss: "伊戈(天神组), 索维林舰队",
        identities: [
            { name: "索维林遥控飞船驾驶员", items: "街机操作台, 金色的皮肤" },
            { name: "掠夺者叛变船员", items: "电击枪, 难吃的根茎食物" },
            { name: "伊戈星球的尸骨", items: "生前是伊戈的孩子, 只有骨头" },
            { name: "银河护卫队实习生", items: "格鲁特的树枝, 胶带" },
            { name: "康特拉夏星妓女", items: "机械身体部件, 廉价的爱情" }
        ],
        talents: [
            {name: "天神组神力(光)", color: "SSS", cost: 35000, desc: "伊戈遗传的力量。你可以操控分子，创造物质，甚至重塑星球。只要伊戈核心存在，你就拥有无限的能量。", type: "exclusive"},
            {name: "亚卡箭(精通)", color: "SS", cost: 8000, desc: "勇度的绝技。你的心与箭合一。哨声响起，红色的死神将在战场上画出美丽的线条，收割一切生命。", type: "skill"},
            {name: "曼蒂斯的共情", color: "S", cost: 4000, desc: "通过触摸感知并改变他人的情绪。能让暴怒的天神瞬间沉睡，是最强的控制技能，但自身防御极低。", type: "skill"},
            {name: "索维林电池", color: "A", cost: 1200, desc: "宇宙中最完美的能量源。虽然容易引来索维林人的追杀，但其价值连城，且能驱动任何高能武器。", type: "item"},
            {name: "太空服(喷气背包)", color: "B", cost: 600, desc: "星爵的标配。能在太空中短时间生存，喷气背包提供高机动性，适合空战。", type: "item"},
            {name: "格鲁特宝宝", color: "A", cost: 2000, desc: "重生的小树人。虽然战斗力下降，但萌度爆表，且体型小巧能钻入狭窄缝隙安放炸弹。", type: "pet"},
            {name: "吃豆人变身", color: "SS", cost: 6500, desc: "利用天神之力将岩石塑造成巨大的吃豆人。对付巨型怪物的利器，充满童趣的毁灭性打击。", type: "skill"},
            {name: "电击杀手脸", color: "C", cost: 50, desc: "一个极其可笑的名字，会让敌人在战斗中忍不住笑场，降低其防御力。", type: "curse"},
            {name: "700次跳跃", color: "D", cost: 150, desc: "连续进行空间跳跃会导致身体变形成卡通人物，呕吐不止。虽然能快速赶路，但体验极差。", type: "curse"},
            {name: "掠夺者葬礼", color: "S", cost: 3000, desc: "当你死亡时，全宇宙的掠夺者都会赶来为你送行。这是一种至高的荣誉，能让你的继承者获得掠夺者阵营的死忠。", type: "concept"},
            {name: "量子小行星带", color: "B", cost: 800, desc: "极其复杂的宇宙地形。在这里驾驶飞船，你的闪避率提升50%，是摆脱追兵的绝佳场所。", type: "skill"},
            {name: "再生能力(伊戈)", color: "SS", cost: 7000, desc: "作为天神子嗣，只要核心不灭，你的肉体可以无限重组。即使被打成碎片也能复原。", type: "body"},
            {name: "索维林舰队", color: "A", cost: 2500, desc: "成千上万艘遥控无人机。虽然单机脆弱，但密集的激光网足以覆盖整个天空。", type: "item"},
            {name: "胶带", color: "C", cost: 5, desc: "在这个高科技宇宙，没有什么是一个胶带解决不了的。如果有，那就用半个胶带。", type: "item"},
            {name: "我是玛丽·波平斯", color: "B", cost: 200, desc: "当你缓缓从空中飘落时，你会获得一种莫名的帅气加成，即使你是蓝皮肤的外星人。", type: "status"}
        ]
    },
    {
        name: "547.(漫威)蜘蛛侠：英雄归来",
        desc: "友好邻居蜘蛛侠的成长史。彼得·帕克试图在高中生活和超级英雄之间寻找平衡。反派秃鹫利用齐塔瑞废料制造高科技武器。",
        boss: "秃鹫(阿德里安·图姆斯), 惊悚(震动拳套)",
        identities: [
            { name: "中城科技高中学生", items: "乐高死星模型, 西班牙语课本" },
            { name: "损害控制局员工", items: "回收的齐塔瑞金属, 斯塔克工业工牌" },
            { name: "秃鹫帮派技工", items: "反重力枪, 拆解工具" },
            { name: "斯塔顿岛渡轮乘客", items: "船票, 被切成两半的汽车" },
            { name: "梅姨的邻居", items: "望远镜, 免费的泰式枣糕" }
        ],
        talents: [
            {name: "斯塔克战衣(被锁)", color: "A", cost: 2000, desc: "虽然功能强大，但开启了“辅助轮”模式。大部分高级功能被锁定，只能使用基础蛛丝和侦查。", type: "item"},
            {name: "秃鹫飞行翼", color: "S", cost: 3800, desc: "利用外星科技打造的巨型机械翼。拥有极高的飞行速度和锋利的钢羽，爪钩能抓起坦克。", type: "item"},
            {name: "物质相位移器", color: "A", cost: 1500, desc: "秃鹫用来穿墙的黑科技。能在固体物质上开出一个临时的洞，潜入和穿墙神技。", type: "item"},
            {name: "震动拳套", color: "B", cost: 900, desc: "交叉骨同款武器的改造版。利用高频震动粉碎物体，一拳能打翻校车。", type: "item"},
            {name: "凯伦(战衣AI)", color: "S", cost: 3000, desc: "解锁战衣后的AI管家。能提供战术分析、即死模式（慎用）和情感咨询。", type: "exclusive"},
            {name: "复联实习生", color: "B", cost: 600, desc: "你拥有托尼·斯塔克的联系方式（虽然是哈皮接电话）。这层关系让你在面对低级反派时底气十足。", type: "status"},
            {name: "自制战衣", color: "B", cost: 400, desc: "普通的卫衣加护目镜。虽然没有高科技，但这代表了蜘蛛侠的本质——没有战衣你依然是英雄。", type: "item"},
            {name: "损害控制局权限", color: "C", cost: 300, desc: "你可以合法回收超级英雄战斗后的废墟。虽然是捡垃圾，但能捡到不少外星黑科技残骸。", type: "status"},
            {name: "蜘蛛力量", color: "SS", cost: 6000, desc: "能单手接住时速40英里的汽车，拉住裂开的渡轮。看似瘦弱的身体蕴含着几十吨的力量。", type: "body"},
            {name: "高空恐惧", color: "D", cost: 80, desc: "当你爬到华盛顿纪念碑顶端时，你会感到眩晕。对于蜘蛛侠来说，这是个致命的弱点。", type: "curse"},
            {name: "内德的黑客技术", color: "B", cost: 500, desc: "你的“椅背侠”死党。能破解战衣的追踪协议，甚至黑进神盾局的防火墙（大概吧）。", type: "skill"},
            {name: "齐塔瑞能量核心", color: "A", cost: 1000, desc: "极其不稳定的紫色能量源。如果受到撞击会引发大爆炸，威力足以摧毁华盛顿纪念碑。", type: "item"},
            {name: "霍兰德的剧透嘴", color: "C", cost: 20, desc: "你总是忍不住说漏嘴。这可能会让你提前暴露身份，但也可能误打误撞干扰敌人的计划。", type: "curse"},
            {name: "钢铁侠救场", color: "S", cost: 4000, desc: "召唤技能。当你搞砸了并且渡轮要沉时，托尼·斯塔克会飞来帮你擦屁股，但事后会没收你的战衣。", type: "skill"},
            {name: "返校季舞伴", color: "C", cost: 50, desc: "你成功邀请到了女神去舞会，但发现她爸是反派BOSS。这会让你的BOSS战难度倍增，心理压力巨大。", type: "event"}
        ]
    },
    {
        name: "548.(漫威)雷神3：诸神黄昏",
        desc: "阿斯加德的毁灭。死亡女神海拉回归，雷神失去了锤子，流落到萨卡星成为角斗士。这是雷神系列风格最突变、色彩最绚丽的一部。",
        boss: "海拉, 苏尔特尔(完全体)",
        identities: [
            { name: "萨卡星角斗士", items: "控制盘(脖子上), 简陋的战锤" },
            { name: "阿斯加德难民", items: "海姆达尔的剑(仿), 斗篷" },
            { name: "宗师的随从", items: "融化棒, 奇怪的发型" },
            { name: "海拉的亡灵士兵", items: "腐朽的盔甲, 绿色火焰" },
            { name: "拾荒者142号(女武神)", items: "龙牙剑, 无尽的酒瓶" }
        ],
        talents: [
            {name: "奥丁之力(觉醒)", color: "SSS", cost: 30000, desc: "你是雷霆之神，不是锤子之神。失去锤子后，你彻底觉醒了体内的神力，双眼冒出雷光，自身就是最强的武器。", type: "exclusive"},
            {name: "海拉的夜空之剑", color: "SS", cost: 9000, desc: "无限剑制。你可以凭空召唤无数把黑色的利刃，大小随意，能轻易刺穿飞船和阿斯加德的身体。", type: "skill"},
            {name: "永恒之火", color: "SSS", cost: 25000, desc: "能复活亡灵大军，也能让苏尔特尔变成毁灭世界的巨人。是引发诸神黄昏的关键火种。", type: "item"},
            {name: "苏尔特尔(皇冠)", color: "S", cost: 5000, desc: "火焰巨人的本体。只要把它放入永恒之火，就能召唤出身高千米的末日巨人，一剑摧毁阿斯加德。", type: "item"},
            {name: "浩克的角斗士装备", color: "S", cost: 3500, desc: "巨大的战锤和战斧。虽然笨重，但在浩克手中是粉碎一切的神器。附带冠军的威压。", type: "item"},
            {name: "服从磁盘", color: "D", cost: 200, desc: "一个小小的磁盘贴在脖子上，能释放强力神经毒素让你瞬间瘫痪。是萨卡星控制奴隶的手段。", type: "curse"},
            {name: "女武神龙牙剑", color: "A", cost: 1800, desc: "瓦尔基里的专属武器。由龙牙打磨而成，坚不可摧，能斩断海拉的魔剑。", type: "item"},
            {name: "宗师的融化棒", color: "A", cost: 2000, desc: "一种恐怖的行刑工具。触碰到任何生物都会将其瞬间融化成一滩液体，无视防御。", type: "item"},
            {name: "报废飞船(狂欢号)", color: "B", cost: 1000, desc: "宗师的游乐飞船。虽然没有武器，但速度极快，且内饰豪华，适合用来逃离萨卡星。", type: "item"},
            {name: "芬里尔巨狼", color: "S", cost: 4500, desc: "海拉的坐骑。一只巨大的亡灵魔狼，能与浩克肉搏，皮糙肉厚，咬合力惊人。", type: "pet"},
            {name: "太阳下山了", color: "C", cost: 50, desc: "黑寡妇的安抚语。对浩克有一定几率让其变回班纳，但在萨卡星似乎不太管用。", type: "skill"},
            {name: "阿斯加德(毁灭)", color: "E", cost: 0, desc: "阿斯加德不是一个地方，而是人民。但那个地方确实炸了。你失去了家园BUFF，但获得了流浪者羁绊。", type: "event"},
            {name: "开锁大神(洛基)", color: "B", cost: 600, desc: "只要有电子锁，就没有洛基打不开的门。在这个充满科技锁链的萨卡星，这是神技。", type: "skill"},
            {name: "报仇者联盟", color: "B", cost: 500, desc: "临时组建的草台班子。虽然名字很土，但成员都是顶级战力，团队协作充满意外性。", type: "status"},
            {name: "独眼龙", color: "C", cost: 100, desc: "你在战斗中失去了一只眼睛，但看起来更像奥丁了。威严+10，视野-50%。", type: "status"}
        ]
    },
    {
        name: "549.(漫威)黑豹",
        desc: "瓦坎达万岁。一个伪装成第三世界国家的科技强国。振金是这里的灵魂。王位争夺战引发了关于开放还是封闭的思考。",
        boss: "埃里克·克尔芒戈, 尤利西斯·克劳",
        identities: [
            { name: "瓦坎达边境部落牧民", items: "伪装成毯子的能量盾, 犀牛哨" },
            { name: "朵拉侍卫队成员", items: "振金长矛, 红色战甲" },
            { name: "舒莉实验室研究员", items: "远程驾驶珠, 振金手炮" },
            { name: "贾巴里部落战士", items: "木棍(其实很硬), 厚重的毛皮" },
            { name: "克劳的雇佣兵", items: "声波手臂义肢, 钻石" }
        ],
        talents: [
            {name: "心形草(紫色)", color: "SS", cost: 8000, desc: "瓦坎达王室特供。服用后进入先祖之地，醒来获得超越常人的力量、速度和感知。黑豹力量的源泉。", type: "item"},
            {name: "黑豹战衣(纳米)", color: "SSS", cost: 12000, desc: "舒莉的最新设计。平时储存在项链里，意念着装。具备动能释放功能，比旧版更轻便强大。", type: "item"},
            {name: "振金矿脉", color: "SSS", cost: 50000, desc: "你拥有世界上唯一的振金矿。这意味着无限的财富和科技潜力。你可以打造一支征服世界的军队。", type: "exclusive"},
            {name: "朵拉侍卫长矛", color: "A", cost: 1600, desc: "振金打造的长矛，能轻易刺穿坦克装甲，还能发射能量波。配合阵法使用威力倍增。", type: "item"},
            {name: "基莫由珠", color: "B", cost: 500, desc: "瓦坎达的万能手环。通讯、医疗、全息投影、远程控制交通工具，是居家旅行必备的高科技。", type: "item"},
            {name: "战争犀牛", color: "A", cost: 2500, desc: "披挂振金铠甲的巨大犀牛。在这个高科技世界，骑着犀牛冲锋依然是最具压迫感的战术。", type: "pet"},
            {name: "克尔芒戈的怒火", color: "S", cost: 3000, desc: "极端的复仇意志。你的攻击力随血量降低而提升，且在面对王室成员时有额外伤害加成。", type: "talent"},
            {name: "隐形屏障", color: "S", cost: 4000, desc: "覆盖整个瓦坎达的能量罩。能完美伪装成丛林，并抵挡外星飞船的撞击。据点防御神技。", type: "item"},
            {name: "声波炮义肢", color: "A", cost: 1400, desc: "克劳的武器。能发射高频声波，震碎岩石，对振金装备有奇特的干扰效果。", type: "item"},
            {name: "贾巴里猿神之力", color: "A", cost: 2000, desc: "姆巴库信奉的力量。不依赖心形草，纯粹肉体锻炼出的怪力，抗击打能力极强。", type: "body"},
            {name: "瓦坎达夕阳", color: "C", cost: 20, desc: "世界上最美的景色之一。在临死前看到它，你会感到内心的平静，死亡惩罚略微降低。", type: "status"},
            {name: "没有心形草了", color: "D", cost: 200, desc: "克尔芒戈烧毁了药园。如果你想成为黑豹，你得想办法找那最后一颗被偷出来的草。", type: "curse"},
            {name: "天才妹妹", color: "S", cost: 3500, desc: "舒莉是你的技术后盾。她能为你升级任何装备，甚至修好幻视的脑子。智商碾压班纳和斯塔克。", type: "status"},
            {name: "釜山飙车", color: "C", cost: 100, desc: "你在城市追逐战中拥有车神般的驾驶技术，且能远程驾驶位于地球另一端的车辆。", type: "skill"},
            {name: "振金手臂(巴基)", color: "S", cost: 3200, desc: "瓦坎达送给白狼的礼物。比原来的更强，且难以被磁力控制，也许还藏着什么后门。", type: "item"}
        ]
    },
    {
        name: "550.(漫威)复仇者联盟3：无限战争",
        desc: "灭霸来了。为了宇宙的平衡，他收集六颗无限宝石，意图消灭宇宙一半的生命。复仇者联盟分兵两路，在泰坦星和瓦坎达进行绝望的抵抗。",
        boss: "灭霸(无限手套), 黑曜五将",
        identities: [
            { name: "阿斯加德幸存者", items: "求救信号发射器, 宇宙漂浮物" },
            { name: "瓦坎达步兵", items: "振金盾牌, 能量披风" },
            { name: "泰坦星拾荒者", items: "重力炸弹, 呼吸面罩" },
            { name: "黑曜五将杂兵(先锋卫)", items: "四只手, 锋利的牙齿" },
            { name: "尼达维勒矮人", items: "巨大的模具, 熔炉余温" },
        ],
        talents: [
            {name: "无限手套(半成品)", color: "SSS", cost: 50000, desc: "矮人王打造的神器。每镶嵌一颗宝石，威力指数级上升。集齐六颗，一个响指，宇宙洗牌。", type: "exclusive"},
            {name: "风暴战斧", color: "SSS", cost: 28000, desc: "国王的武器。拥有召唤彩虹桥的能力，能抗衡无限手套的能量束，一斧头差点砍出大结局。", type: "item"},
            {name: "钢铁蜘蛛战衣", color: "SS", cost: 9000, desc: "纳米金属打造，背后有四条机械蛛腿。拥有外太空生存模式，是蜘蛛侠的最强装备。", type: "item"},
            {name: "MK50纳米装甲", color: "SS", cost: 10000, desc: "斯塔克科技的巅峰。纳米粒子随心所欲变换形态，护盾、重锤、推进器、导弹，万能的单兵平台。", type: "item"},
            {name: "灭霸的响指", color: "E", cost: 0, desc: "完全随机的死亡判决。无论你多强，你有50%的几率直接化为灰烬。这是宇宙的意志，无法豁免。", type: "curse"},
            {name: "黑曜五将之力", color: "S", cost: 4000, desc: "获得亡刃将军的战刃或乌木喉的念力。虽然比不上灭霸，但在地球上足以横扫复联二线战力。", type: "skill"},
            {name: "先锋卫大军", color: "A", cost: 3000, desc: "不知疼痛、不知恐惧的生物兵器。只要不关门，它们就会像潮水一样淹没瓦坎达。", type: "item"},
            {name: "灵魂宝石的代价", color: "D", cost: 500, desc: "要获得灵魂宝石，必须献祭挚爱。这是一个痛苦的抉择，你会失去最重要的羁绊NPC。", type: "curse"},
            {name: "奇异博士的1400万次推演", color: "SSS", cost: 15000, desc: "预知未来所有可能。你知道唯一的胜算在哪里，但这要求你必须在这个阶段接受失败。", type: "talent"},
            {name: "我要你的眼珠", color: "C", cost: 50, desc: "火箭浣熊的恶趣味。你会获得一个机械眼球，虽然是偷来的，但在关键时刻能给雷神当备件。", type: "item"},
            {name: "泰坦星的废墟", color: "B", cost: 1000, desc: "利用泰坦星的引力异常和巨大残骸进行战斗。你可以像灭霸一样拉下一颗卫星砸人。", type: "skill"},
            {name: "中子星熔炉", color: "SS", cost: 6000, desc: "尼达维勒的核心。你需要承受中子星的能量冲刷来启动它。虽然极度痛苦，但能锻造出弑神级武器。", type: "event"},
            {name: "瓦坎达能量盾(全开)", color: "S", cost: 3500, desc: "虽然会让先锋卫绕后，但开启护盾能绞杀无数试图穿越屏障的敌人。", type: "item"},
            {name: "你应该砍头的", color: "D", cost: 100, desc: "因为想让敌人痛苦而没有直接致命，导致被反杀。这是典型的反派死于话多（虽然雷神不是反派）。", type: "curse"},
            {name: "我们有浩克(离线)", color: "E", cost: 20, desc: "浩克被灭霸打怕了，拒绝出来。你只能驾驶笨重的反浩克装甲作战，战力大打折扣。", type: "curse"}
        ]
    },
    {
        name: "551.(漫威)蚁人2：黄蜂女现身",
        desc: "无限战争的同期故事，但画风截然不同。为了营救初代黄蜂女，皮姆一家再次集结。反派幽灵因量子实验事故而身体虚化，痛苦不堪。",
        boss: "幽灵(艾娃·斯塔尔)",
        identities: [
            { name: "X-Con安保公司合伙人", items: "名片, 奖杯" },
            { name: "FBI探员", items: "电子脚镣监控器, 甜甜圈" },
            { name: "黑市商人手下", items: "自白剂, 一辆很酷的摩托车" },
            { name: "量子领域原住民", items: "量子能量法杖, 奇怪的披风" },
            { name: "小学老师", items: "斯科特女儿的书包, 世界上最大的蚂蚁玩偶" }
        ],
        talents: [
            {name: "量子隧道", color: "SS", cost: 8000, desc: "通往量子领域的稳定大门。不仅能救人，更是后来时间穿越（时空劫持）的关键设备。", type: "item"},
            {name: "黄蜂女战衣", color: "S", cost: 5000, desc: "比蚁人战衣更先进。自带翅膀和能量发射器。飞行灵活性极高，是完美的刺客装备。", type: "item"},
            {name: "幽灵体质", color: "S", cost: 4500, desc: "身体分子结构不稳定，可以随意穿墙、隐形。虽然伴随着剧痛，但也是极其难缠的战斗能力。", type: "body"},
            {name: "变大的HelloKitty", color: "B", cost: 300, desc: "一个巨大的粉色HelloKitty糖果盒。用来砸人或者挡路非常有威慑力（心理上）。", type: "item"},
            {name: "量子治愈粒子", color: "SS", cost: 7000, desc: "珍妮特在量子领域进化出的能力。能修复幽灵不稳定的分子结构，甚至能治愈很多绝症。", type: "skill"},
            {name: "皮姆缩放实验室", color: "A", cost: 2500, desc: "一栋可以缩小成拉杆箱的大楼。随时随地展开你的科研基地，逃跑时拉着就走。", type: "item"},
            {name: "近景魔术", color: "C", cost: 50, desc: "斯科特在软禁期间学的。虽然不能杀敌，但能用来分散敌人注意力或在孩子面前装酷。", type: "skill"},
            {name: "巨型蚂蚁鼓手", color: "C", cost: 100, desc: "一只会打架子鼓的巨大蚂蚁。虽然没什么战斗力，但能代替你戴上电子脚镣迷惑FBI。", type: "pet"},
            {name: "自白剂", color: "B", cost: 400, desc: "黑市商人的逼供药水。打了之后你会滔滔不绝地讲真话，包括你的童年阴影和尴尬往事。", type: "item"},
            {name: "风火轮小汽车", color: "A", cost: 1200, desc: "一盒各色跑车。扔出去变大就能开，简直是载具库。包括那辆很帅的紫色现代飞思。", type: "item"},
            {name: "量子纠缠天线", color: "B", cost: 600, desc: "用来定位量子领域中迷失之人的坐标。如果你想找回失踪的队友，这是必备道具。", type: "item"},
            {name: "被困量子领域", color: "D", cost: 200, desc: "彩蛋结局。当你进入量子领域收集粒子时，外面的队友都被灭霸响指打没了。你被困住了，等老鼠来救你吧。", type: "curse"},
            {name: "FBI的监视", color: "D", cost: 50, desc: "吴探员时刻盯着你。你不能离开房子半步，否则就要回监狱蹲着。这限制了你的活动范围。", type: "curse"},
            {name: "比尔·福斯特的帮助", color: "B", cost: 500, desc: "歌利亚计划的参与者。虽然站在幽灵那边，但他心地善良，能提供关于变大的理论指导。", type: "status"},
            {name: "缓步动物", color: "A", cost: 1000, desc: "量子领域中的巨大水熊虫。虽然可爱，但会吃人。避开它们是生存的关键。", type: "monster"}
        ]
    },
              {
        name: "552.(漫威)惊奇队长",
        desc: "90年代的复古风。克里人与斯克鲁人的星际战争波及地球。卡罗尔·丹弗斯寻找失去的记忆，最终觉醒成为宇宙最强英雄之一。",
        boss: "勇·罗格, 至高智慧",
        identities: [
            { name: "百视达音像店店员", items: "施瓦辛格的人形立牌, 一盘《真实的谎言》录像带" },
            { name: "神盾局低级探员(90s)", items: "BB机, 看起来很笨重的电脑" },
            { name: "斯克鲁难民", items: "变形伪装能力, 科学家的外衣" },
            { name: "克里星际战队士兵", items: "重力护腕, 绿色制服" },
            { name: "天马计划地勤", items: "光速引擎设计图(残缺), 橘猫零食" }
        ],
        talents: [
            {name: "双星模式(觉醒)", color: "SSS", cost: 38000, desc: "吸收光速引擎(空间宝石)能量后的终极形态。全身发光，能以光速飞行，肉身撞毁星际战舰，在这个时代是无敌的存在。", type: "exclusive"},
            {name: "斯克鲁变形术", color: "S", cost: 4500, desc: "能完美复制任何人的外貌、声音甚至DNA，连视网膜扫描都能通过。只有极少数高科技或直觉能识破。", type: "body"},
            {name: "光子能量波", color: "SS", cost: 8000, desc: "双手释放强大的光子冲击，能瞬间融化钢铁，轰飞敌人。随着情绪波动，威力无上限。", type: "skill"},
            {name: "噬元兽(橘猫)", color: "SS", cost: 9500, desc: "外表是可爱的橘猫，嘴里能伸出无数触手吞噬一切，连无限宝石都能吞进胃里的异次元空间。极其危险的宠物。", type: "pet"},
            {name: "克里战队格斗术", color: "A", cost: 1200, desc: "勇·罗格传授的战斗技巧。强调控制情绪，利用敌人的力量反击，适合在失去超能力时使用。", type: "skill"},
            {name: "宇宙立方(空间宝石)", color: "SSS", cost: 30000, desc: "马-维尔博士实验室的核心。虽然被噬元兽吞了，但如果你能拿到，你就能掌握空间传送的力量。", type: "item"},
            {name: "尼克·弗瑞的BB机", color: "S", cost: 5000, desc: "改造成跨星系通讯器。危急时刻按下它，惊奇队长会跨越宇宙来救你（虽然可能要等20年）。", type: "item"},
            {name: "克里血液输送", color: "A", cost: 2000, desc: "接受克里人的蓝色血液。体能大幅增强，寿命延长，但可能会被至高智慧洗脑控制。", type: "body"},
            {name: "光速引擎战机", color: "SS", cost: 7000, desc: "利用空间宝石能量驱动的实验机。虽然不稳定，但拥有超越光速的潜力，是星际旅行的神器。", type: "item"},
            {name: "记忆被篡改", color: "D", cost: 100, desc: "你的记忆被克里人修改过，经常做噩梦。你分不清敌友，这在战斗中是致命的隐患。", type: "curse"},
            {name: "90年代金曲", color: "C", cost: 50, desc: "你随身带着必胜客传单和涅槃乐队的磁带。这种复古氛围能让你在面对地球人时获得好感度。", type: "item"},
            {name: "至高智慧的审判", color: "S", cost: 3000, desc: "进入精神空间与至高智慧对决。如果意志坚定，能打破精神枷锁；如果失败，将永远成为傀儡。", type: "event"},
            {name: "神盾局初创元老", color: "B", cost: 800, desc: "你和年轻的寇森、弗瑞是同事。这意味着你在未来的神盾局拥有极高的辈分和权限。", type: "status"},
            {name: "抓瞎", color: "C", cost: 10, desc: "你被猫抓瞎了一只眼。虽然很疼，但这让你看起来更像个硬汉局长。", type: "status"},
            {name: "斯克鲁科学天赋", color: "A", cost: 1500, desc: "塔洛斯的种族天赋。即便在流亡中，也能利用废铜烂铁改造出光速飞船。", type: "talent"}
        ]
    },
    {
        name: "553.(漫威)复仇者联盟4：终局之战",
        desc: "终局之战。复仇者们集结最后的力量，通过时空劫持收集宝石，逆转无限。这是MCU最高光的时刻，也是最悲壮的告别。",
        boss: "灭霸(2014版), 灭霸大军",
        identities: [
            { name: "新阿斯加德渔民", items: "啤酒肚, 电子游戏手柄" },
            { name: "浪人(鹰眼)的追杀目标", items: "纹身, 日本刀(被抢了)" },
            { name: "复联基地废墟幸存者", items: "纳米手套(空的), 破碎的盾牌" },
            { name: "瓦坎达传送门法师", items: "悬戒, 坚定的眼神" },
            { name: "量子领域老鼠", items: "刚好踩中按钮的运气, 吱吱声" }
        ],
        talents: [
            {name: "纳米无限手套(钢铁侠版)", color: "SSS", cost: 55000, desc: "托尼·斯塔克的绝唱。能承载六颗宝石的力量。打响指的瞬间，你是宇宙的神，但凡人必死无疑。", type: "exclusive"},
            {name: "雷神之锤+风暴战斧", color: "SSS", cost: 32000, desc: "双持神器的肥宅雷神。虽然体型走样，但雷霆之力依旧。双持状态下攻速和暴击率翻倍。", type: "item"},
            {name: "美队的举锤资格", color: "SSS", cost: 28000, desc: "你举起了妙尔尼尔！获得雷神之力，配合盾牌打出连招，能把灭霸打得毫无还手之力。", type: "exclusive"},
            {name: "绯红女巫(愤怒)", color: "SS", cost: 12000, desc: "“你夺走了我的一切！” 愤怒状态下的旺达能单手剥离灭霸的盔甲，迫使他呼叫炮火覆盖。", type: "skill"},
            {name: "惊奇队长(救场)", color: "SS", cost: 15000, desc: "从天而降，直接撞穿圣殿二号战舰。在面对灭霸时能硬抗头槌，力量压制。", type: "skill"},
            {name: "时空穿梭服(皮姆粒子)", color: "SS", cost: 8000, desc: "量子领域的导航服。每人只有两管皮姆粒子，意味着只有一次往返机会。失误就是迷失时空。", type: "item"},
            {name: "我是钢铁侠(牺牲)", color: "SSS", cost: 60000, desc: "概念级技能。当你抢到宝石并说出这句话时，强制清除所有敌对单位。代价是你的生命（不可复活）。", type: "concept"},
            {name: "复仇者集结(全员)", color: "SSS", cost: 20000, desc: "所有英雄通过传送门登场。这是史上最强BUFF，全属性提升100%，士气锁定为最大值。", type: "status"},
            {name: "灭霸暴君战刃", color: "S", cost: 5000, desc: "双头大刀，由未知金属打造，能砍碎振金盾牌。旋转起来是无死角的防御屏障。", type: "item"},
            {name: "圣殿二号炮火覆盖", color: "S", cost: 6000, desc: "“雨露均沾”。无差别轰炸地面，威力足以摧毁魔法护盾和复联基地，改变地形。", type: "skill"},
            {name: "浪人刀法", color: "A", cost: 1500, desc: "鹰眼黑化后的剑术。冷酷无情，招招致命，专门清理黑道杂兵。", type: "skill"},
            {name: "美国翘臀", color: "C", cost: 50, desc: "虽然是搞笑天赋，但能在面对过去的自己时，通过赞美翘臀来分散注意力。", type: "status"},
            {name: "芝士汉堡", color: "C", cost: 20, desc: "摩根·斯塔克的最爱，也是哈皮对托尼的怀念。在葬礼上食用，能获得所有英雄的好感度。", type: "item"},
            {name: "爱你三千遍", color: "B", cost: 500, desc: "无论你身在何处，这句咒语能让你感受到家人的爱，解除恐惧和精神控制。", type: "status"},
            {name: "量子领域老鼠", color: "SSS", cost: 10000, desc: "宇宙的救世主。这只老鼠踩中按钮释放了蚁人，才有了后面的一切。拥有绝对的强运。", type: "pet"}
        ]
    },
    {
        name: "554.(漫威)蜘蛛侠：英雄远征",
        desc: "终局之战后的世界。彼得·帕克继承了托尼的眼镜，却被神秘客欺骗。这是关于信任、幻象和成长的故事。无人机大军笼罩伦敦。",
        boss: "神秘客(昆汀·贝克), 元素众(全息投影)",
        identities: [
            { name: "中城高中游学团学生", items: "黑色大丽花项链, 科学作业" },
            { name: "神秘客特效团队成员", items: "全息投影仪, 动作捕捉服" },
            { name: "威尼斯船夫", items: "船桨, 被水怪吓坏的表情" },
            { name: "神盾局(斯克鲁)特工", items: "绿色皮肤(伪装), 暴躁脾气" },
            { name: "伊迪丝操作员", items: "智能眼镜, 杀手无人机控制权" }
        ],
        talents: [
            {name: "伊迪丝(EDITH)", color: "SSS", cost: 25000, desc: "“死后哪怕是伊迪丝”。斯塔克留下的全球安防系统。拥有数千架杀手无人机和全网情报权。", type: "item"},
            {name: "神秘客全息幻象", color: "SS", cost: 8000, desc: "利用无数无人机制造的逼真幻象。能模拟元素怪兽、丧尸钢铁侠，甚至改变环境，让人分不清虚实。", type: "skill"},
            {name: "彼得一激灵(蜘蛛感应)", color: "SS", cost: 9000, desc: "完全觉醒的蜘蛛感应。闭着眼睛也能躲避无数无人机的子弹，识破幻象，直击本体。", type: "talent"},
            {name: "红黑战衣(自制)", color: "S", cost: 4500, desc: "彼得在飞机上利用斯塔克技术制造的战衣。增加了滑翔翼和电击蛛网，象征着他走出托尼的阴影。", type: "item"},
            {name: "元素众投影", color: "A", cost: 2000, desc: "召唤巨大的水、火、土、风怪物。虽然是假的，但无人机会配合造成真实的物理破坏。", type: "skill"},
            {name: "杀手无人机群", color: "S", cost: 3500, desc: "斯塔克工业制造的武装无人机。配备机枪和声波炮，数量庞大，可组合成各种形态。", type: "item"},
            {name: "欺诈大师", color: "A", cost: 1500, desc: "昆汀·贝克的演技。你能把自己包装成来自平行宇宙的英雄，骗过神盾局和全世界。", type: "talent"},
            {name: "夜猴侠", color: "C", cost: 100, desc: "一套黑色的潜行战衣。虽然被叫成夜猴侠很丢人，但在欧洲行动时能有效隐藏身份。", type: "item"},
            {name: "身份暴露", color: "D", cost: 200, desc: "神秘客死前录像。你的真实身份被号角日报曝光，全世界都知道你是蜘蛛侠，且被诬陷杀人。", type: "curse"},
            {name: "哈皮的飞机", color: "B", cost: 800, desc: "斯塔克工业的私人飞机。虽然经常被炸，但里面有战衣制造机和医疗设备，是移动基地。", type: "item"},
            {name: "黑色大丽花", color: "C", cost: 50, desc: "送给MJ的礼物。虽然碎了，但这代表了你的心意。获得MJ的好感度和真爱之吻。", type: "item"},
            {name: "斯克鲁人的伪装", color: "A", cost: 1200, desc: "尼克·弗瑞其实是塔洛斯变的。你可以利用这种伪装摸鱼，但在关键时刻可能会掉链子。", type: "status"},
            {name: "AC/DC音乐", color: "B", cost: 300, desc: "当你开始制造战衣时，背景响起《Back in Black》。这让你进入专注状态，制造速度提升。", type: "status"},
            {name: "无人机视觉干扰", color: "B", cost: 600, desc: "通过破坏无人机阵列，让幻象出现马赛克或卡顿，从而看清现实。", type: "skill"},
            {name: "相信直觉", color: "A", cost: 1000, desc: "在幻象中，眼睛会骗你，但直觉不会。这是对抗神秘客的唯一法宝。", type: "talent"}
        ]
    },
    {
        name: "555.(漫威)黑寡妇",
        desc: "娜塔莎的谢幕演出（时间线在内战后）。揭开红房子的秘密，面对模仿大师。这是一个关于家庭、救赎和打破枷锁的故事。",
        boss: "德雷科夫, 模仿大师",
        identities: [
            { name: "红房子“黑寡妇”", items: "电击手环, 精神控制血清" },
            { name: "挪威隐居者", items: "拖车, 发电机" },
            { name: "红色守卫者狱友", items: "纹身, 关于美国队长的吹牛故事" },
            { name: "布达佩斯安全屋住客", items: "隐藏的武器库, 简陋的医疗包" },
            { name: "空中要塞囚犯", items: "手铐, 高空寒风" }
        ],
        talents: [
            {name: "红房子解药(红尘)", color: "SS", cost: 6000, desc: "一种红色的合成气体。能瞬间解除红房子对黑寡妇们的精神控制，唤醒她们的自我意识。", type: "item"},
            {name: "模仿大师芯片", color: "S", cost: 5000, desc: "能够完美复制任何人的格斗技巧。美队的盾技、黑豹的爪击、鹰眼的箭术，看一眼就会。", type: "talent"},
            {name: "黑寡妇蛰咬(升级)", color: "A", cost: 1500, desc: "强化的电击手环。能发射高达30万伏特的电流，瞬间击晕敌人或破坏电子设备。", type: "item"},
            {name: "红色守卫者体质", color: "A", cost: 2000, desc: "苏联版的超级士兵血清。虽然年老发福，但依然拥有超越常人的力量和耐力，能徒手掰开钢门。", type: "body"},
            {name: "费洛蒙锁定", color: "D", cost: 100, desc: "德雷科夫的防御机制。只要闻到他的费洛蒙，你就无法对他进行物理攻击。必须切断嗅觉神经才能破解。", type: "curse"},
            {name: "空中要塞(红房)", color: "S", cost: 4000, desc: "隐藏在云层中的巨大基地。拥有完善的训练设施和防御系统。如果坠落，就是一场灾难。", type: "item"},
            {name: "叶莲娜的背心", color: "B", cost: 300, desc: "有很多口袋的战术背心。不仅实用，还是姐妹情深的象征。穿上它，敏捷度提升。", type: "item"},
            {name: "高空跳伞(无伞)", color: "A", cost: 1200, desc: "娜塔莎的极限操作。在空中抢夺降落伞，利用碎片滑翔。这是勇气的试炼。", type: "skill"},
            {name: "布达佩斯经历", color: "B", cost: 500, desc: "你和鹰眼在布达佩斯并肩作战过。这段经历赋予了你极高的城市游击战经验和默契。", type: "status"},
            {name: "世界最强杀手", color: "S", cost: 3000, desc: "红房子的终极训练成果。精通所有杀人技、间谍术和心理战。你是行走的致命武器。", type: "skill"},
            {name: "家庭聚餐", color: "C", cost: 50, desc: "虽然是虚假的家庭，但在饭桌上，你们能获得短暂的温馨和BUFF加成。", type: "event"},
            {name: "猪的呼吸", color: "C", cost: 20, desc: "德雷科夫控制猪停止呼吸的实验。虽然没用，但展示了控制技术的恐怖。", type: "skill"},
            {name: "断鼻梁", color: "B", cost: 400, desc: "为了切断嗅觉神经，你必须自己撞断鼻梁。这种狠劲能让你免疫疼痛和精神控制。", type: "skill"},
            {name: "隐形飞机", color: "A", cost: 1000, desc: "梅森提供的装备。虽然经常出故障，但勉强能飞，且难以被雷达探测。", type: "item"},
            {name: "吹口哨", color: "B", cost: 100, desc: "姐妹间的暗号。在混乱的战场上，这声口哨能确认彼此的位置和安全。", type: "skill"}
        ]
    },
    {
        name: "556.(漫威)尚气与十环传奇",
        desc: "东方玄幻进入MCU。尚气面对父亲文武和十环帮的阴影。大罗仙境、神龙与吸食灵魂的噬魂怪。功夫与魔法的结合。",
        boss: "文武(十环), 噬魂怪(黑暗栖息者)",
        identities: [
            { name: "旧金山泊车小弟", items: "豪车钥匙, 唱KTV的麦克风" },
            { name: "十环帮刺客", items: "电击钩爪, 忍者服" },
            { name: "澳门地下拳手", items: "绷带, 观众的赌注" },
            { name: "大罗村民", items: "龙鳞护甲, 龙鳞棍" },
            { name: "莫里斯(帝江)的饲养员", items: "没有脸的毛绒生物, 水果" }
        ],
        talents: [
            {name: "十环(神器)", color: "SSS", cost: 35000, desc: "千年神器。赋予持有者永生、怪力和能量发射能力。十环离体攻击，攻防一体，还能作为跳板飞行。", type: "exclusive"},
            {name: "神龙之力(气)", color: "SS", cost: 12000, desc: "尚气觉醒的力量。能驾驭风，操控十环变成金色。这是唯一能彻底消灭噬魂怪的神圣力量。", type: "magic"},
            {name: "太极拳(神级)", color: "S", cost: 3000, desc: "以柔克刚。能借力打力，化解文武的刚猛攻击，甚至能引导十环的能量。", type: "skill"},
            {name: "龙鳞武器", color: "A", cost: 1500, desc: "大罗特产。龙鳞强化的棍棒或弓箭，能对灵魂类怪物造成真实伤害，坚硬度堪比振金。", type: "item"},
            {name: "噬魂怪召唤", color: "S", cost: 5000, desc: "打破黑暗之门的封印。召唤无数吸食灵魂的怪物。它们免疫物理攻击，能瞬间吸干一支军队。", type: "skill"},
            {name: "神龙(坐骑)", color: "SS", cost: 8000, desc: "大罗的守护神。巨大的白龙，能飞行、操控水流。骑上它，你就是空战霸主。", type: "pet"},
            {name: "文武的千年武学", color: "S", cost: 2500, desc: "经过千年磨练的杀人技。每一招都直取要害，配合十环使用，单挑无敌。", type: "skill"},
            {name: "莫里斯导航", color: "B", cost: 600, desc: "这只没脸的生物知道进入大罗迷宫的路径。没有它，你会死在竹林迷阵里。", type: "pet"},
            {name: "竹林迷阵", color: "A", cost: 1000, desc: "大罗的天然屏障。会移动的竹林，能吞噬入侵者。在这里战斗，你的闪避率提升。", type: "skill"},
            {name: "无脸怪(特雷弗)", color: "C", cost: 50, desc: "那个演满大人的演员。虽然是个逗比，但他能听懂莫里斯的话，是关键的翻译官。", type: "status"},
            {name: "卡拉OK之王", color: "C", cost: 20, desc: "你和凯蒂在KTV唱《加州旅馆》。这能缓解紧张情绪，增加队友默契。", type: "skill"},
            {name: "地下拳王", color: "B", cost: 800, desc: "你在夏灵的拳场打过拳。抗击打能力强，且熟悉各种阴招。", type: "status"},
            {name: "吸魂", color: "D", cost: 200, desc: "被噬魂怪抓住。你的灵魂会被慢慢吸走，生命值上限永久下降，直到变成干尸。", type: "curse"},
            {name: "风之力", color: "A", cost: 1800, desc: "映丽传授的功夫。能操控气流，让落叶变成武器，或者将敌人吹飞。", type: "magic"},
            {name: "十环易主", color: "S", cost: 4000, desc: "当你的心境超越文武时，十环会改变颜色并听从你的召唤。这是反败为胜的关键。", type: "skill"}
        ]
    },
    {
        name: "557.(漫威)永恒族",
        desc: "跨越7000年的史诗。永恒族被天神组创造来保护人类，实则是为了孵化新的天神。面对异常变异族和即将到来的神现。",
        boss: "伊卡瑞斯, 克罗(进化版异常族)",
        identities: [
            { name: "宝莱坞大明星(金格)", items: "私人飞机, 摄影机" },
            { name: "巴比伦城门守卫", items: "青铜长矛, 盾牌" },
            { name: "现代伦敦博物馆员(瑟西)", items: "古董, 手机" },
            { name: "澳大利亚隐居者(吉尔伽美什)", items: "平底锅, 围裙" },
            { name: "多摩号飞船船员", items: "宇宙星图, 收藏品" }
        ],
        talents: [
            {name: "物质转换(瑟西)", color: "SSS", cost: 25000, desc: "能改变任何非生命物质的形态。将巴士变成花瓣，将天神组变成大理石。觉醒后能杀神。", type: "magic"},
            {name: "超人光束(伊卡瑞斯)", color: "SS", cost: 12000, desc: "永恒族最强战力。飞行、怪力、双眼发射高能激光。简直就是漫威版的超人。", type: "skill"},
            {name: "极速(玛卡瑞)", color: "SS", cost: 10000, desc: "超越音速的移动能力。跑遍全球只需几分钟。攻击产生的音爆能击晕伊卡瑞斯。", type: "body"},
            {name: "战争构造(蒂娜)", color: "S", cost: 8000, desc: "利用宇宙能量具现化任何冷兵器。剑、盾、长矛，随心所欲。技巧达到神级。", type: "skill"},
            {name: "精神控制(德鲁伊格)", color: "S", cost: 7000, desc: "能控制人类的思想。只要他想，可以瞬间平息战争，或者让一支军队为他而战。", type: "magic"},
            {name: "科技发明(法斯托斯)", color: "S", cost: 6000, desc: "只要有能量，能制造任何机械。从古代的犁到现代的统一意志手环，甚至是杀神武器。", type: "talent"},
            {name: "永魔症(Mahd Wy''ry)", color: "D", cost: 300, desc: "因记忆负荷过大而产生的精神错乱。你会不分敌我地攻击周围的人，虽然战力提升，但不可控。", type: "curse"},
            {name: "统一意志(Uni-Mind)", color: "SSS", cost: 30000, desc: "连接所有永恒族的意识和能量。汇聚成一股浩瀚的宇宙之力，足以对抗天神组的意志。", type: "skill"},
            {name: "天神组提亚穆特", color: "SSS", cost: 50000, desc: "正在从地心孵化的天神。一旦出生，地球就会爆炸。他的手掌和头颅是巨大的新地标。", type: "event"},
            {name: "异常族进化", color: "A", cost: 2500, desc: "吸收永恒族的能量进行进化。获得对方的能力和智慧，甚至能自愈。越打越强。", type: "body"},
            {name: "幻术故事(水精灵)", color: "A", cost: 1500, desc: "制造极其逼真的幻象。虽然没有杀伤力，但能用来隐身、讲故事或迷惑敌人。", type: "magic"},
            {name: "一拳超人(吉尔伽美什)", color: "S", cost: 5000, desc: "最强的物理输出。将宇宙能量汇聚在拳头上，一拳能打碎异常族的脑袋。", type: "skill"},
            {name: "多摩号飞船", color: "SS", cost: 8500, desc: "巨大的三角形飞船。拥有超光速航行能力和内部生态系统。是永恒族的家园。", type: "item"},
            {name: "阿里瑟姆的审判", color: "E", cost: 0, desc: "天神组首领的注视。在世界结束时，他会降临审判地球人是否值得保留。无法反抗的威压。", type: "event"},
            {name: "黑骑士之剑(乌木剑)", color: "S", cost: 4000, desc: "戴恩·惠特曼家传的魔剑。虽然尚未拔出，但蕴含着嗜血的诅咒和斩断一切的力量。", type: "item"}
        ]
    },
    {
        name: "558.(漫威)蜘蛛侠：英雄无归",
        desc: "三代蜘蛛侠同框！彼得请求奇异博士让世界遗忘他的身份，却意外打开了多元宇宙。绿魔、章鱼博士等经典反派回归。治愈而非杀戮。",
        boss: "绿魔(诺曼·奥斯本), 电光人(斯塔克科技版)",
        identities: [
            { name: "MIT申请者", items: "拒信, 甜甜圈店打工服" },
            { name: "号角日报实习生", items: "直播设备, 詹姆森的咆哮" },
            { name: "自由女神像施工员", items: "巨大的美国队长盾牌(施工中), 脚手架" },
            { name: "桑迪屋(反派囚禁处)看守", items: "魔法盒子, 奇怪的科学仪器" },
            { name: "哈皮公寓住客", items: "乐高死星(又碎了), 绝密安保系统" }
        ],
        talents: [
            {name: "三蛛同框", color: "SSS", cost: 30000, desc: "召唤另外两个宇宙的蜘蛛侠（托比和加菲）。三倍的嘴炮，三倍的蜘蛛感应，配合默契度MAX。", type: "status"},
            {name: "魔法方块(维山帝之盒)", color: "SS", cost: 15000, desc: "囚禁着失败魔咒的盒子。按下按钮，所有反派会被送回原宇宙并死于非命。也是毁灭世界的开关。", type: "item"},
            {name: "绿魔滑板+南瓜炸弹", color: "S", cost: 5000, desc: "诺曼·奥斯本的装备。滑板带刺刀和导弹，南瓜炸弹能把人炸成骨架。极其疯狂的战斗风格。", type: "item"},
            {name: "章鱼博士机械触手", color: "S", cost: 6000, desc: "四条拥有独立AI的机械臂。力量巨大，反应迅速。如果被纳米战衣控制，会变成友军。", type: "item"},
            {name: "电光人(方舟反应炉)", color: "SS", cost: 8000, desc: "吸收了斯塔克反应炉能量的麦克斯。能瞬移、发射强力闪电。此时的他接近纯能量体，极难对付。", type: "skill"},
            {name: "遗忘魔咒", color: "SSS", cost: 20000, desc: "奇异博士的禁术。让全世界遗忘彼得·帕克的存在。代价是失去所有亲人朋友，彻底孤独。", type: "magic"},
            {name: "镜像维度主宰", color: "SS", cost: 10000, desc: "在镜像维度中，你可以利用数学几何知识战胜奇异博士（只要你数学够好）。", type: "skill"},
            {name: "纳米战衣(融合)", color: "S", cost: 7000, desc: "钢铁蜘蛛战衣与章鱼触手融合。你可以控制触手，反制奥托博士。", type: "item"},
            {name: "治愈血清", color: "A", cost: 2000, desc: "针对绿魔、蜥蜴博士等反派的解药。能剥离他们的超能力和疯狂人格。这是蜘蛛侠的仁慈。", type: "item"},
            {name: "梅姨的遗言", color: "B", cost: 1000, desc: "“能力越大，责任越大”。这句话是蜘蛛侠的精神支柱，能让处于崩溃边缘的你重新振作。", type: "status"},
            {name: "自由女神像之战", color: "A", cost: 3000, desc: "在巨大的盾牌和脚手架上战斗。地形复杂，坠落风险极高。适合蜘蛛侠发挥机动性。", type: "event"},
            {name: "传送门戒指(内德版)", color: "B", cost: 500, desc: "内德意外学会了开传送门。虽然不稳定，但能把关键人物（比如其他蜘蛛侠）传送过来。", type: "magic"},
            {name: "蜥蜴博士", color: "A", cost: 2500, desc: "拥有强大的再生能力和野兽般的力量。但他只想把大家都变成蜥蜴。", type: "body"},
            {name: "沙人化", color: "S", cost: 4000, desc: "身体沙化，物理攻击免疫。能变成巨大的沙尘暴巨人。弱点是水。", type: "body"},
            {name: "这一拳为了格温", color: "C", cost: 100, desc: "加菲版蜘蛛侠救下MJ时触发。弥补了当年的遗憾，获得心灵上的巨大解脱和BUFF。", type: "event"}
        ]
    },
    {
        name: "559.(漫威)奇异博士2：疯狂多元宇宙",
        desc: "恐怖风格的漫威。绯红女巫为了寻找孩子黑化，追杀能够穿越多元宇宙的少女阿美莉卡。光照会惨遭屠杀，丧尸宇宙惊鸿一瞥。",
        boss: "绯红女巫(黑化), 眼魔(Gargantos)",
        identities: [
            { name: "光照会宇宙(838)路人", items: "绿灯行红灯停(反转), 记忆回放仪" },
            { name: "卡玛泰姬法师", items: "能量盾, 必死的决心" },
            { name: "多元宇宙穿越者", items: "牛仔外套, 恐惧" },
            { name: "维山帝之书守护者", items: "魔法纹身, 漂浮的石板" },
            { name: "克里斯汀的婚礼宾客", items: "礼服, 一杯红酒" }
        ],
        talents: [
            {name: "黑暗神书(Darkhold)", color: "SSS", cost: 40000, desc: "诅咒之书。赋予使用者极其强大的黑魔法，包括梦行术（附身平行宇宙的自己）。代价是腐蚀灵魂和引发对撞事件。", type: "item"},
            {name: "阿美莉卡·查维兹(穿越)", color: "SSS", cost: 35000, desc: "唯一能力。能打星型的传送门，穿越多元宇宙。虽然初期不可控，但这是逃离旺达追杀的唯一路径。", type: "exclusive"},
            {name: "梦行术(Dreamwalking)", color: "SS", cost: 12000, desc: "利用黑暗神书附身平行宇宙的自己。虽然身体是尸体或别人的，但力量是你的。跨宇宙杀人神技。", type: "magic"},
            {name: "维山帝之书", color: "SSS", cost: 38000, desc: "光明的魔法书，黑暗神书的克星。能赋予法师对抗旺达的力量。可惜刚拿到就被烧了。", type: "item"},
            {name: "光照会(全灭)", color: "D", cost: 500, desc: "虽然成员包括X教授、神奇先生、黑蝠王等大佬，但因傲慢被旺达秒杀。加入光照会是个高危职业。", type: "curse"},
            {name: "黑蝠王之口", color: "SS", cost: 10000, desc: "只要张嘴说话，声波能摧毁一切。弱点是嘴巴被魔法封住时会爆头自杀。", type: "skill"},
            {name: "丧尸奇异博士", color: "S", cost: 8000, desc: "附身于尸体。利用亡灵恶灵作为披风，极其重口味但战力爆表。拥有腐烂之触。", type: "magic"},
            {name: "音符对决", color: "A", cost: 3000, desc: "将乐谱转化为魔法攻击。音符变成利刃和能量波。一场优雅而致命的魔法决斗。", type: "magic"},
            {name: "旺达的低语", color: "E", cost: 50, desc: "“不，更像是绯红女巫”。当你听到这句话时，快跑。任何防御在黑化旺达面前都像纸一样脆。", type: "curse"},
            {name: "第三只眼", color: "S", cost: 5000, desc: "使用黑暗神书的副作用。额头长出第三只眼，能看到真实，但也意味着你已经堕落。", type: "body"},
            {name: "卡特队长的盾牌", color: "A", cost: 2000, desc: "英国队长的振金盾牌。虽然坚硬，但在旺达面前会被自己的盾牌腰斩。", type: "item"},
            {name: "惊奇队长的能量(838)", color: "S", cost: 6000, desc: "玛利亚·兰博版惊奇队长。能量巨大，能硬抗旺达一段时间，最终被雕像压死。", type: "skill"},
            {name: "Wong的绳索", color: "B", cost: 800, desc: "至尊法师王的法术。虽然打不过旺达，但能拖延时间，且生命力极其顽强。", type: "magic"},
            {name: "对撞事件(Incursion)", color: "SSS", cost: 100000, desc: "两个宇宙相撞，导致双方毁灭。这是滥用穿越能力的终极代价。", type: "event"},
            {name: "你是幸福的吗", color: "C", cost: 20, desc: "来自前女友的灵魂拷问。虽然没有物理伤害，但能造成巨大的精神暴击。", type: "status"}
        ]
    },
    {
        name: "560.(漫威)雷神4：爱与雷霆",
        desc: "雷神的自我发现之旅。简·福斯特成为女雷神，却身患癌症。屠神者格尔誓要杀光所有神明。搞笑与悲伤并存。",
        boss: "屠神者格尔(死灵之剑), 宙斯(雷霆)",
        identities: [
            { name: "新阿斯加德导游", items: "扩音器, 瓦尔基里的签名照" },
            { name: "全能之城侍从", items: "金色的托加长袍, 葡萄" },
            { name: "暗影领域怪物", items: "黑暗触手, 恐惧" },
            { name: "被绑架的阿斯加德儿童", items: "毛绒玩具, 赋予的神力" },
            { name: "银河护卫队临时工", items: "太空服, 听雷神吹牛" }
        ],
        talents: [
            {name: "死灵之剑(All-Black)", color: "SSS", cost: 40000, desc: "共生体之神纳尔的武器。能弑神，召唤暗影怪物，在阴影中穿梭。但会腐蚀使用者的生命和理智。", type: "exclusive"},
            {name: "雷霆之锤(碎片)", color: "SS", cost: 15000, desc: "重组的妙尔尼尔。能分裂成无数碎片攻击敌人再聚合，就像霰弹枪一样。赋予简·福斯特雷神之力。", type: "item"},
            {name: "宙斯的雷霆(闪电箭)", color: "S", cost: 8000, desc: "全能之王的神器。金色的闪电长矛，威力巨大，能当标枪投掷，也能作为近战武器。", type: "item"},
            {name: "永恒许愿", color: "SSS", cost: 100000, desc: "到达宇宙中心的永恒祭坛。第一个到达者可以许现任何一个愿望（复活女儿或毁灭神明）。", type: "event"},
            {name: "阿斯加德儿童军团", color: "S", cost: 6000, desc: "索尔将神力分给孩子们。一群拿着泰迪熊和树枝的孩子瞬间变成雷电战士，横扫暗影怪物。", type: "skill"},
            {name: "暴风战斧的嫉妒", color: "C", cost: 100, desc: "当你使用雷神之锤时，斧子会吃醋，飘过来挡视线。这会降低你的命中率，但很可爱。", type: "curse"},
            {name: "癌症晚期(简)", color: "D", cost: 200, desc: "每次解除雷神形态，化疗效果都会被清除，病情加重。这是在用生命在战斗。", type: "curse"},
            {name: "全能之城", color: "A", cost: 3000, desc: "众神的聚集地。在这里你可以见到各种神（包子神、龙神等）。虽然大部分很怂，但神力充沛。", type: "status"},
            {name: "牙牙与格格(山羊)", color: "B", cost: 1000, desc: "两只巨大的山羊拉的车。它们会发出极其刺耳的尖叫声，能撞碎飞船，还能在彩虹桥上奔跑。", type: "pet"},
            {name: "暗影领域", color: "B", cost: 1500, desc: "黑白配色的世界。在这里没有色彩，只有光影。格尔的主场，你的视野受限。", type: "skill"},
            {name: "爱与雷霆", color: "S", cost: 5000, desc: "索尔与格尔女儿的组合。雷神之力与死灵之剑遗留力量的结合，新一代的超级英雄搭档。", type: "status"},
            {name: "裸体被围观", color: "C", cost: 50, desc: "被宙斯弹飞衣服。虽然很尴尬，但如果你的身材够好，能让在场的女神（和男神）晕倒。", type: "skill"},
            {name: "瓦尔基里的剑术", color: "A", cost: 1800, desc: "阿斯加德王的战斗技巧。即使面对格尔也能过几招，但因为政务繁忙，略显生疏。", type: "skill"},
            {name: "石头人寇格", color: "B", cost: 600, desc: "打不死的小强。即使身体碎了，只要脸还在就能活。讲故事一流，也是很好的肉盾。", type: "pet"},
            {name: "弑神誓言", color: "S", cost: 3500, desc: "格尔的被动。面对神明时，攻击力翻倍，且带有恐惧光环。", type: "talent"}
        ]
    },
    {
        name: "561.(漫威)黑豹2：瓦坎达万岁",
        desc: "特查拉逝世，瓦坎达陷入悲痛。海底文明塔洛坎崛起，纳摩为了保护族人向瓦坎达宣战。苏睿在仇恨与责任中成长为新黑豹。",
        boss: "纳摩(库库尔坎), 塔洛坎大军",
        identities: [
            { name: "MIT天才学生(莉莉)", items: "斯塔克科技笔记, 振金探测器" },
            { name: "塔洛坎战士", items: "水呼吸面具, 振金长矛" },
            { name: "瓦坎达海军", items: "海豹号飞船, 能量毯" },
            { name: "CIA探员", items: "监听设备, 罗斯的前妻" },
            { name: "河边部落长老", items: "唇盘, 坚毅的眼神" }
        ],
        talents: [
            {name: "羽蛇神(纳摩)", color: "SSS", cost: 30000, desc: "变种人混血。脚踝有翅膀能飞，皮肤坚硬如振金，在水中无敌，力量堪比浩克。弱点是脱水。", type: "exclusive"},
            {name: "人造心形草", color: "SS", cost: 10000, desc: "苏睿利用纳摩的手链纤维合成的药草。能赋予使用者黑豹之力，且没有家族遗传限制。", type: "item"},
            {name: "午夜天使战甲", color: "S", cost: 8000, desc: "瓦坎达最新的外骨骼装甲。蓝色涂装，具备飞行能力和更强的力量，专门对抗超人类。", type: "item"},
            {name: "钢铁之心(MK2)", color: "S", cost: 7000, desc: "莉莉·威廉姆斯利用瓦坎达科技制造的战甲。虽然造型粗犷，但火力凶猛，拥有巨大的能量炮。", type: "item"},
            {name: "水炸弹", color: "A", cost: 2000, desc: "塔洛坎人的武器。充满高压水流的手雷，爆炸时释放巨大的水压冲击，能冲垮城墙。", type: "item"},
            {name: "海妖之歌", color: "S", cost: 4000, desc: "塔洛坎人的歌声。能催眠听到的陆地人，让他们不由自主地跳海自杀。精神攻击。", type: "magic"},
            {name: "振金探测器", color: "B", cost: 1500, desc: "能探测全球振金的装置。正是这个机器引来了纳摩的仇恨，是战争的导火索。", type: "item"},
            {name: "脱水虚弱", color: "D", cost: 300, desc: "纳摩的弱点。如果你长时间离开水或暴露在高温下，力量会急剧下降，皮肤无法呼吸。", type: "curse"},
            {name: "瓦坎达水军", color: "A", cost: 3000, desc: "巨大的海上堡垒“海豹号”。拥有声波炮和能量护盾，是瓦坎达对抗海底文明的主力。", type: "item"},
            {name: "复仇的火焰", color: "S", cost: 5000, desc: "苏睿初期的心态。被仇恨驱动，攻击力提升，但容易失去理智。直到在先祖之地见到克尔芒戈。", type: "status"},
            {name: "塔洛坎太阳", color: "A", cost: 2500, desc: "海底的人造太阳。利用振金供能，照亮深海王国。是塔洛坎文明的生命之源。", type: "item"},
            {name: "干燥室", color: "B", cost: 1000, desc: "苏睿设计的陷阱。利用高温蒸发水分，专门用来削弱纳摩。战术智商的体现。", type: "skill"},
            {name: "女王的牺牲", color: "B", cost: 800, desc: "拉曼达女王为了救莉莉而淹死。她的死激励了苏睿，赋予了瓦坎达哀兵必胜的气势。", type: "event"},
            {name: "不杀之恩", color: "C", cost: 100, desc: "苏睿最终选择不杀纳摩，结成同盟。这不仅结束了战争，也获得了一个强大的盟友。", type: "status"},
            {name: "特查拉之子", color: "S", cost: 4500, desc: "彩蛋中的小王子。继承了特查拉的血脉，是瓦坎达未来的希望。", type: "status"}
        ]
    },
              {
        name: "562.(漫威)X战警1",
        desc: "千禧年的开篇。变种人被视为异类。X教授致力于和平共处，万磁王则试图将人类转化为变种人。自由女神像上的决战拉开序幕。",
        boss: "万磁王, 剑齿虎",
        identities: [
            { name: "泽维尔天赋少年学校学生", items: "X战警制服(皮革版), 教科书" },
            { name: "变种人兄弟会成员", items: "兄弟会纹身, 仇视人类的传单" },
            { name: "反变种人议员保镖", items: "墨镜, 容易被变形女顶替的身份" },
            { name: "加拿大酒吧酒客", items: "雪茄, 被金刚狼切断的猎枪" },
            { name: "自由女神像游客", items: "相机, 变成辐射源的恐惧" }
        ],
        talents: [
            {name: "艾德曼合金骨骼", color: "SSS", cost: 40000, desc: "全身骨骼被注入宇宙最强金属。坚不可摧，爪子能切开一切。配合自愈因子，你是杀不死的兵器。", type: "body"},
            {name: "磁场控制(万磁王)", color: "SSS", cost: 38000, desc: "控制任何形式的金属。从硬币穿脑到举起潜艇，甚至控制地球磁极。对付金刚狼有奇效。", type: "exclusive"},
            {name: "心灵感应(X教授)", color: "SSS", cost: 35000, desc: "读取思维、精神控制、记忆修改。只要连接上脑波强化机，你能杀死地球上所有人。", type: "talent"},
            {name: "镭射眼", color: "S", cost: 5000, desc: "双眼发射毁灭性的红色冲击波。威力巨大但无法关闭，必须佩戴红石英眼镜。", type: "skill"},
            {name: "天气控制(暴风女)", color: "SS", cost: 8000, desc: "召唤闪电、龙卷风和暴雪。大范围AOE伤害，能改变局部气候，真正的女神之力。", type: "magic"},
            {name: "变形术(魔形女)", color: "S", cost: 4500, desc: "完美的伪装渗透能力。不仅能改变外貌，还能模拟声带和指纹。体术格斗也是顶级的。", type: "body"},
            {name: "辐射突变机", color: "A", cost: 2000, desc: "万磁王制造的机器。能诱发人类基因突变，但因为不稳定，受害者通常会化为一滩水。", type: "item"},
            {name: "金刚狼的自愈", color: "SS", cost: 12000, desc: "细胞瞬间再生。子弹、刀伤、烧伤都能快速愈合。大大延缓衰老，几乎永生。", type: "body"},
            {name: "蛤蟆功", color: "B", cost: 800, desc: "超强的跳跃能力和一条长长的粘性舌头。虽然恶心，但用来抢东西或控制敌人很有效。", type: "skill"},
            {name: "小淘气(触碰)", color: "S", cost: 6000, desc: "皮肤接触会吸收对方的生命力、记忆和超能力。被动技能无法关闭，注定孤独。", type: "curse"},
            {name: "黑鸟战机", color: "A", cost: 3000, desc: "X战警的专属座驾。具备垂直起降、隐形功能和超音速巡航能力。", type: "item"},
            {name: "剑齿虎之力", color: "A", cost: 2500, desc: "类似金刚狼的野兽感官和利爪（骨爪）。力量比金刚狼更大，但没有合金骨骼。", type: "body"},
            {name: "脑波强化机(Cerebro)", color: "SS", cost: 10000, desc: "放大心灵感应能力的巨型设备。能定位全球任何一个变种人或人类。", type: "item"},
            {name: "我有驾照", color: "C", cost: 20, desc: "镭射眼总是担心金刚狼乱开他的车。拥有此天赋，你能完美驾驶黑鸟战机和摩托车。", type: "skill"},
            {name: "黄色紧身衣", color: "C", cost: 50, desc: "虽然被嘲笑，但这是经典的漫画致敬。穿上它，你的敏捷度微量提升，回头率100%。", type: "item"}
        ]
    },
    {
        name: "563.(漫威)X战警2",
        desc: "人类的反击。史崔克上校突袭X学院，试图利用脑波强化机消灭所有变种人。X战警与万磁王被迫联手。琴·葛蕾展现凤凰之力。",
        boss: "威廉·史崔克, 死亡女(小山百合子)",
        identities: [
            { name: "阿尔卡利湖基地守卫", items: "麻醉枪, 史崔克的命令书" },
            { name: "被绑架的变种人学生", items: "抑制项圈, 恐惧" },
            { name: "夜行者的马戏团同伴", items: "十字架, 德国啤酒" },
            { name: "白宫特勤局特工", items: "手枪, 被瞬移吓坏的经历" },
            { name: "X学院幸存者", items: "秘密地道地图, 金刚狼的打火机" }
        ],
        talents: [
            {name: "瞬间移动(夜行者)", color: "SS", cost: 9000, desc: "伴随着硫磺味和烟雾的瞬移。只要视线所及或记忆中的地方都能去。刺杀美国总统只需几秒。", type: "magic"},
            {name: "艾德曼合金爪(死亡女)", color: "S", cost: 7000, desc: "手指伸出细长的合金刺。虽然不如金刚狼的爪子霸气，但更锋利更隐蔽，且同样拥有自愈能力。", type: "body"},
            {name: "凤凰之力(觉醒)", color: "SSS", cost: 50000, desc: "琴·葛蕾体内沉睡的宇宙级力量。能分解物质、阻挡洪水、复活死者。一旦完全释放，世界将毁灭。", type: "exclusive"},
            {name: "控制药剂(脑叶)", color: "A", cost: 1500, desc: "史崔克用来控制变种人的药物。滴入后脑勺，能让最强的变种人变成听话的傀儡。", type: "item"},
            {name: "冰冻能力(冰人)", color: "A", cost: 2000, desc: "降低温度，制造冰墙，发射冰锥。甚至能冻结爆炸的火焰。潜力巨大（欧米茄级）。", type: "magic"},
            {name: "火焰操纵(火人)", color: "B", cost: 1200, desc: "只能控制火，不能制造火。必须随身携带打火机。性格暴躁，容易被反派利用。", type: "skill"},
            {name: "幻象大师(杰森)", color: "S", cost: 5000, desc: "通过眼神接触制造极其真实的幻象。能让X教授陷入梦魇，差点毁灭所有变种人。", type: "magic"},
            {name: "大坝崩塌", color: "E", cost: 10, desc: "阿尔卡利湖大坝决堤。如果你不会飞也不会瞬移，你将被数亿吨的湖水淹没。", type: "event"},
            {name: "铁分提取", color: "S", cost: 4000, desc: "万磁王的微操。能从守卫血液中提取过量的铁元素，汇聚成几颗钢珠越狱。极度血腥且优雅。", type: "skill"},
            {name: "蓝魔鬼的信仰", color: "B", cost: 500, desc: "夜行者的虔诚信仰。在身上刻下天使符号。能抵御精神攻击，增加瞬移的精准度。", type: "status"},
            {name: "猫咪穿墙", color: "C", cost: 100, desc: "幻影猫的能力。你能带着接触的人或物穿过实体墙壁。逃跑神技。", type: "skill"},
            {name: "史崔克的儿子", color: "D", cost: 200, desc: "你拥有强大的幻象能力，但被父亲切除了脑叶并抽取脑髓液。生不如死。", type: "curse"},
            {name: "金刚狼的狂暴", color: "A", cost: 3000, desc: "当学校被入侵时触发。攻击力翻倍，痛觉屏蔽。为了保护孩子，你会变成真正的野兽。", type: "status"},
            {name: "黑暗脑波机", color: "S", cost: 8000, desc: "史崔克建造的复制品。专门用来锁定并杀死变种人。是正版脑波机的邪恶双胞胎。", type: "item"},
            {name: "还没死透", color: "C", cost: 50, desc: "琴在洪水中的最后时刻。如果你拥有凤凰之力，死亡只是重生的开始。", type: "status"}
        ]
    },
    {
        name: "564.(漫威)X战警3：背水一战",
        desc: "变种人解药问世，引发种族战争。凤凰女彻底黑化，杀死了爱人与导师。万磁王移动金门大桥围攻恶魔岛。旧时代的落幕。",
        boss: "黑凤凰(琴·葛蕾), 拥有解药军队的万磁王",
        identities: [
            { name: "恶魔岛解药实验室保安", items: "塑料武器(防磁), 解药注射枪" },
            { name: "欧米茄帮成员", items: "莫西干头, 廉价的纹身" },
            { name: "排队注射解药的变种人", items: "号码牌, 对平凡生活的渴望" },
            { name: "被移动的金门大桥司机", items: "还在车里, 极度恐慌" },
            { name: "天使沃伦", items: "巨大的白色羽翼, 被父亲嫌弃" }
        ],
        talents: [
            {name: "分子分解(黑凤凰)", color: "SSS", cost: 60000, desc: "琴·葛蕾的完全体。眼神一扫，任何人或物瞬间分解成原子。连X教授都被秒杀。不可阻挡的毁灭。", type: "exclusive"},
            {name: "变种人解药(永久)", color: "S", cost: 5000, desc: "吉米(水蛭)的DNA提取物。一旦注入，永久消除X基因，变种人变成凡人。对凤凰女等神级角色也是致命威胁。", type: "item"},
            {name: "红坦克的头盔", color: "S", cost: 4000, desc: "能免疫精神控制。只要跑起来，就没有什么能阻挡红坦克（除了墙壁太厚）。", type: "item"},
            {name: "移动大桥", color: "SS", cost: 15000, desc: "万磁王的壮举。凭借一己之力连根拔起金门大桥并移动到恶魔岛。展现了磁场控制的宏大力量。", type: "skill"},
            {name: "穿墙术(幻影猫)", color: "A", cost: 2500, desc: "凯蒂的巅峰表现。能对抗红坦克的冲撞（让他卡在地里）。不仅能穿墙，还能穿人。", type: "skill"},
            {name: "钢力士体质", color: "A", cost: 3000, desc: "全身瞬间转化为有机钢。刀枪不入，力大无穷。是保护队友的最佳肉盾。", type: "body"},
            {name: "天使之翼", color: "B", cost: 1500, desc: "背生双翼，飞行速度极快。虽然战斗力一般，但救人于危难（如高空坠落）非常实用。", type: "body"},
            {name: "多重分身(分身人)", color: "A", cost: 2000, desc: "一人成军。能瞬间制造数百个实体分身。虽然单体脆弱，但用来迷惑敌人或搬砖效率极高。", type: "skill"},
            {name: "骨刺生长(刺猬男)", color: "B", cost: 800, desc: "从身体各处射出骨刺。虽然不如金刚狼，但在混战中是很好的远程骚扰手段。", type: "body"},
            {name: "解药无效", color: "D", cost: 100, desc: "对于某些过于强大的变种人（如万磁王），解药只是暂时的。这给了你卷土重来的希望。", type: "status"},
            {name: "最后的一课", color: "S", cost: 3500, desc: "X教授死前的教诲。当面对无法战胜的黑凤凰时，爱与牺牲是唯一的解法。", type: "status"},
            {name: "塑料武器", color: "C", cost: 50, desc: "专门对付万磁王的武器。虽然威力小，但不会被磁力控制。打万磁王必备。", type: "item"},
            {name: "我是红坦克！", color: "B", cost: 600, desc: "喊出这句话时，你的冲撞力度提升50%。虽然智商会暂时下降。", type: "skill"},
            {name: "水蛭光环", color: "S", cost: 4500, desc: "靠近你的一切变种能力都会失效。你是行走的禁魔领域，也是所有势力争夺的目标。", type: "talent"},
            {name: "金刚狼的爱", color: "SS", cost: 10000, desc: "只有你能杀死凤凰。凭借超强自愈顶着分解波走到她面前，这需要极大的勇气和爱。", type: "event"}
        ]
    },
    {
        name: "565.(漫威)金刚狼1：前传",
        desc: "罗根的起源故事。从19世纪的病弱少年到拥有艾德曼合金骨骼的金刚狼。死侍（被封嘴版）作为最终兵器登场。",
        boss: "死侍(十一号武器), 史崔克, 剑齿虎",
        identities: [
            { name: "X武器计划实验体", items: "手术服, 巨大的水槽" },
            { name: "加拿大伐木工", items: "斧头, 格子衬衫" },
            { name: "新奥尔良赌徒(牌皇)", items: "扑克牌, 长棍" },
            { name: "二战战俘", items: "狗牌, 长生不老" },
            { name: "老夫妇收养的儿子", items: "皮夹克, 摩托车" }
        ],
        talents: [
            {name: "十一号武器(死侍)", color: "SS", cost: 12000, desc: "史崔克的缝合怪。拥有金刚狼的自愈、镭射眼的光束、瞬移能力，双臂植入艾德曼长刀。被封嘴的悲剧。", type: "body"},
            {name: "动能充能(牌皇)", color: "A", cost: 3500, desc: "给物体注入动能使其爆炸。扑克牌变手雷，长棍变炸弹。动作潇洒，威力不俗。", type: "skill"},
            {name: "艾德曼合金注射", color: "SSS", cost: 20000, desc: "极其痛苦的手术。将滚烫的合金注入骨骼。如果没有超强自愈力，你会当场死亡。成功后获得无坚不摧的骨架。", type: "event"},
            {name: "骨爪(原始)", color: "B", cost: 1000, desc: "未注入合金前的爪子。虽然能再生，但会被剑齿虎折断。更锋利，但也更脆弱。", type: "body"},
            {name: "银狐的触碰", color: "A", cost: 2000, desc: "通过接触控制他人思想，甚至能制造幻觉和假死。虽然对强者效果有限，但用来欺骗史崔克足够了。", type: "skill"},
            {name: "瞬移(幽灵)", color: "B", cost: 1500, desc: "will.i.am饰演的角色。能短距离瞬移，但没有夜行者那么灵活。", type: "skill"},
            {name: "钻石皮肤(白皇后)", color: "A", cost: 3000, desc: "全身钻石化，防御力极高，免疫心灵感应。虽然不能动，但作为防御手段很强。", type: "body"},
            {name: "艾德曼合金子弹", color: "S", cost: 4000, desc: "唯一能穿透金刚狼头骨并破坏大脑（导致失忆）的武器。是对付金刚狼的杀手锏。", type: "item"},
            {name: "背靠背战斗", color: "B", cost: 500, desc: "罗根与剑齿虎的兄弟羁绊。当两人背靠背时，战斗力互补，几乎无死角。", type: "status"},
            {name: "胖子肉球", color: "B", cost: 800, desc: "拥有巨大的体型和脂肪层，能反弹炮弹和拳头。虽然行动缓慢，但防御力惊人。", type: "body"},
            {name: "精准射击(零号特工)", color: "A", cost: 1200, desc: "枪斗术大师。虽然没有超能力，但凭借极其精准的枪法和敏捷身手，能压制早期的金刚狼。", type: "skill"},
            {name: "失忆诅咒", color: "D", cost: 100, desc: "头部中弹后，你失去了所有记忆。你不知道自己是谁，只知道要杀人。这是罗根悲剧的开始。", type: "curse"},
            {name: "三英里岛核电站", color: "B", cost: 1000, desc: "最终决战地。巨大的冷却塔和不稳定的反应堆。在这里战斗，每一步都可能引发核泄漏。", type: "event"},
            {name: "那件皮夹克", color: "C", cost: 50, desc: "老夫妇送的礼物。虽然不加属性，但这是金刚狼经典造型的灵魂。", type: "item"},
            {name: "闭嘴", color: "E", cost: 10, desc: "死侍最大的痛苦不是被改造，而是嘴巴被缝上了。无法吐槽，攻击力减半（精神上）。", type: "curse"}
        ]
    },
    {
        name: "566.(漫威)X战警：第一战",
        desc: "60年代的冷战背景。X教授与万磁王的年轻时代。从挚友到宿敌。古巴导弹危机的幕后真相。变种人首次登上历史舞台。",
        boss: "黑皇(塞巴斯蒂安·肖), 红魔鬼",
        identities: [
            { name: "CIA变种人部门顾问", items: "黑衣人西装, 脑波机原型" },
            { name: "地狱火俱乐部会员", items: "香槟, 兔女郎装扮(如果是女)" },
            { name: "古巴海域美军水手", items: "导弹发射钮, 望远镜" },
            { name: "纳粹集中营幸存者", items: "硬币, 仇恨" },
            { name: "牛津大学基因学教授", items: "论文, 撩妹技巧" }
        ],
        talents: [
            {name: "能量吸收(黑皇)", color: "SSS", cost: 30000, desc: "吸收一切形式的能量（动能、热能、核能）并转化为自身力量。除非拿硬币穿脑，否则几乎无敌。", type: "exclusive"},
            {name: "钻石形态(白皇后)", color: "S", cost: 5000, desc: "艾玛·弗罗斯特的能力。钻石化后免疫心灵感应，是X教授的克星。也是地狱火俱乐部的核心战力。", type: "body"},
            {name: "瞬移(红魔鬼)", color: "A", cost: 2500, desc: "阿萨佐的能力。比夜行者更具进攻性，能把人抓到高空扔下。配合尾巴攻击，极其难缠。", type: "skill"},
            {name: "声波尖叫(海妖)", color: "B", cost: 1200, desc: "利用高频声波飞行和声呐探测。虽然初期控制不好，但潜力很大，能震碎潜艇声呐。", type: "skill"},
            {name: "适应进化(达尔文)", color: "A", cost: 3000, desc: "身体能瞬间适应任何环境。水下长鳃，火中耐热。虽然电影里死得草率，但理论上是不死之身。", type: "body"},
            {name: "能量光环(破坏者)", color: "B", cost: 1000, desc: "发射红色的同心圆能量波。威力巨大但不可控，必须用呼啦圈一样的装置辅助瞄准。", type: "skill"},
            {name: "野兽形态(汉克)", color: "A", cost: 2000, desc: "注射血清失败后的产物。全身长满蓝毛，获得野兽般的力量和敏捷，但保留了天才的大脑。", type: "body"},
            {name: "硬币穿脑", color: "SS", cost: 8000, desc: "万磁王的复仇一击。在X教授定住黑皇时，缓慢地用硬币穿过他的大脑。极度解压且致命。", type: "skill"},
            {name: "移动潜艇", color: "S", cost: 6000, desc: "万磁王能力的初次觉醒。将巨大的核潜艇抬出水面。虽然很累，但震撼了所有人类。", type: "skill"},
            {name: "偏转导弹", color: "S", cost: 7000, desc: "面对美苏两国的舰队，控制数百枚导弹掉头。这是变种人力量对人类科技的绝对碾压。", type: "skill"},
            {name: "脊椎损伤", color: "D", cost: 200, desc: "被万磁王误伤挡下子弹，导致下半身瘫痪。从此只能坐轮椅。这是X教授一生的痛。", type: "curse"},
            {name: "真正的乌鸦", color: "C", cost: 50, desc: "魔形女的名字来源。你可以变成任何人，但只有保持蓝色皮肤时才是真实的自己。", type: "status"},
            {name: "去你的(金刚狼客串)", color: "C", cost: 10, desc: "当查尔斯和埃里克来招募你时，你只说了一个词。虽然没加入，但装了个大逼。", type: "skill"},
            {name: "X战警制服(黄蓝)", color: "C", cost: 100, desc: "第一代制服。虽然有点土，但具有防弹和滑翔功能。团队精神的象征。", type: "item"},
            {name: "棋逢对手", color: "B", cost: 500, desc: "查尔斯与埃里克的下棋时光。智力+10，好感度+20。这是友谊的见证。", type: "status"}
        ]
    },
    {
        name: "567.(漫威)金刚狼2",
        desc: "罗根在日本的冒险。失去了自愈因子，面对黑帮、忍者和银武士。这是一部充满了东方元素和武士道精神的外传。",
        boss: "银武士(矢志田市朗), 毒蛇女",
        identities: [
            { name: "隐居山林的野人", items: "长发, 噩梦" },
            { name: "矢志田家族保镖", items: "武士刀, 墨镜" },
            { name: "雪绪的同伴", items: "预知未来的能力(弱), 红发" },
            { name: "黑手党成员", items: "冲锋枪, 新干线车票" },
            { name: "忍者村村民", items: "弓箭, 忍术" }
        ],
        talents: [
            {name: "银武士机甲", color: "SS", cost: 10000, desc: "艾德曼合金打造的巨型机甲。配备高热能光剑，能斩断金刚狼的爪子。目的是抽取罗根的自愈因子。", type: "item"},
            {name: "抑制虫", color: "S", cost: 4000, desc: "植入心脏的微型机器人。能抑制变种人的自愈能力，让金刚狼变得像凡人一样脆弱。", type: "curse"},
            {name: "毒液吐息(毒蛇)", color: "A", cost: 2500, desc: "能喷吐致命毒液，免疫所有毒素，还能像蛇一样蜕皮重生。狡猾且致命。", type: "body"},
            {name: "预知死亡(雪绪)", color: "B", cost: 1500, desc: "能看到他人死亡的瞬间。虽然不能改变命运，但能提前预警，是很好的辅助能力。", type: "talent"},
            {name: "新干线战斗", color: "B", cost: 1000, desc: "在时速300公里的列车顶上战斗。需要极高的平衡感和反应速度。利用风阻杀敌。", type: "skill"},
            {name: "居合道", color: "A", cost: 1200, desc: "真理子的护卫传授的剑术。拔刀即斩，快准狠。即使没有超能力也能对抗忍者。", type: "skill"},
            {name: "断爪重生(骨)", color: "A", cost: 3000, desc: "当合金爪被斩断后，罗根重新长出了骨爪。虽然硬度下降，但代表了野性的回归。", type: "body"},
            {name: "长崎核爆幸存", color: "S", cost: 5000, desc: "曾用身体挡下核爆保护矢志田。这份恩情变成了诅咒，引来了觊觎你永生的贪婪。", type: "event"},
            {name: "忍者大军", color: "A", cost: 2000, desc: "数百名精通忍术的黑衣人。利用钩索、烟雾弹和毒箭围攻，能用人海战术拖垮金刚狼。", type: "item"},
            {name: "心脏手术(自救)", color: "S", cost: 3500, desc: "罗根剖开自己的胸膛取出抑制虫。极度血腥，需要极强的意志力和哪怕一点点自愈力。", type: "skill"},
            {name: "吸取生命", color: "S", cost: 6000, desc: "银武士的功能。通过钻头刺入骨髓，吸取罗根的自愈因子让自己返老还童。", type: "skill"},
            {name: "浪人", color: "C", cost: 50, desc: "失去了主人（琴）的武士。心如死灰，战斗力下降，直到找到新的守护目标。", type: "status"},
            {name: "筷子接苍蝇", color: "C", cost: 10, desc: "虽然没接住，但这是武侠片经典桥段。证明你的反应速度依然在线。", type: "skill"},
            {name: "万磁王回归(彩蛋)", color: "SS", cost: 8000, desc: "恢复能力的万磁王定住了罗根。预示着哨兵危机即将到来，世界观瞬间扩大。", type: "event"},
            {name: "熊的复仇", color: "B", cost: 200, desc: "因为猎人使用了毒箭射杀熊，你愤怒地教训了他们。正义感爆棚，获得自然阵营好感。", type: "event"}
        ]
    },
    {
        name: "568.(漫威)X战警：逆转未来",
        desc: "两个时间线的交汇。未来，哨兵机器人屠杀变种人；过去，魔形女的刺杀引发了这一切。金刚狼穿越回1973年，试图改写历史。",
        boss: "哨兵机器人(未来版), 玻利瓦尔·特斯拉克",
        identities: [
            { name: "未来集中营变种人", items: "条形码纹身, 绝望" },
            { name: "1973年X学院废墟住客", items: "毒品注射器, 颓废的X教授" },
            { name: "五角大楼囚犯(快银)", items: "随身听, 护目镜" },
            { name: "巴黎和平会议代表", items: "越南战争文件, 伪装器" },
            { name: "哨兵计划科学家", items: "高分子聚合物, 变种人DNA样本" }
        ],
        talents: [
            {name: "哨兵机器人(未来)", color: "SSS", cost: 50000, desc: "终极变种人杀手。融合了魔形女的基因，能针对任何超能力进行适应性进化。火攻变冰，冰攻变火。无解的绝望。", type: "item"},
            {name: "时间静止(快银)", color: "SS", cost: 15000, desc: "在《Time in a Bottle》的BGM中，你的速度快到仿佛时间静止。可以随意调整子弹轨迹，给敌人内裤提拉。", type: "skill"},
            {name: "意识穿越", color: "S", cost: 8000, desc: "幻影猫的新能力。将人的意识送回过去的身体。如果过去被改变，未来将重写。风险极大。", type: "magic"},
            {name: "传送门(闪烁)", color: "A", cost: 4000, desc: "范冰冰饰演的角色。投掷紫色能量晶体开启传送门。能转移敌人攻击，分割战场，辅助神技。", type: "skill"},
            {name: "太阳黑子", color: "A", cost: 3000, desc: "变身为黑色的火焰形态，发射高温等离子体。虽然打不过哨兵，但火力很猛。", type: "skill"},
            {name: "举起体育场", color: "SS", cost: 10000, desc: "万磁王的场面活。控制整个肯尼迪体育场飞到白宫周围筑起围墙。霸气侧漏。", type: "skill"},
            {name: "魔形女的DNA", color: "S", cost: 5000, desc: "哨兵计划的关键。如果被特斯拉克获得，变种人将灭绝。你是行走的历史转折点。", type: "body"},
            {name: "恢复双腿(血清)", color: "B", cost: 1000, desc: "野兽研制的血清。能让X教授站起来，但会抑制心灵感应能力。是选择走路还是选择力量？", type: "item"},
            {name: "希望", color: "SSS", cost: 20000, desc: "X教授跨越时空的对话。老年的查尔斯唤醒了年轻的自己。精神力量的巅峰，改变未来的关键。", type: "concept"},
            {name: "骨爪(1973)", color: "B", cost: 800, desc: "穿越回去的金刚狼只有骨爪。面对万磁王时不会被控制，但也切不开哨兵原型机。", type: "body"},
            {name: "塑料监狱", color: "C", cost: 300, desc: "关押万磁王的五角大楼地牢。全玻璃和混凝土结构，没有任何金属。越狱难度极高。", type: "item"},
            {name: "弯曲子弹", color: "S", cost: 2500, desc: "万磁王控制子弹转弯。虽然是为了救人，但被误解为刺杀总统。历史的误会。", type: "skill"},
            {name: "哨兵原型机(1973)", color: "A", cost: 3500, desc: "第一代哨兵。全聚合物制造，无金属，装备加特林。虽然不能变形，但足以对付普通变种人。", type: "item"},
            {name: "历史重写", color: "SSS", cost: 100000, desc: "当魔形女放下枪的那一刻，未来被改变了。琴、斯科特都复活了。这是最完美的结局。", type: "event"},
            {name: "水床", color: "C", cost: 20, desc: "罗根穿越醒来时躺在水床上。70年代的独特体验，伴随着宿醉。", type: "status"}
        ]
    },
    {
        name: "569.(漫威)死侍1",
        desc: "打破第四面墙的R级英雄。韦德·威尔逊为了治愈癌症接受实验，变成了毁容的死侍。充满暴力、脏话和低俗笑话的复仇之旅。",
        boss: "阿贾克斯(弗朗西斯), 天使尘",
        identities: [
            { name: "雇佣兵", items: "红色紧身衣, HelloKitty背包" },
            { name: "癌症晚期患者", items: "诊断书, 瓦妮莎的照片" },
            { name: "X武器实验体", items: "氧气面罩, 没有任何麻醉的手术" },
            { name: "盲人老太的室友", items: "宜家家具(没拼好), 可卡因(其实是致盲药)" },
            { name: "出租车司机(多平德)", items: "情敌的照片, 忠诚" }
        ],
        talents: [
            {name: "打破第四面墙", color: "SSS", cost: 30000, desc: "你知道自己是个电影角色。你可以对着观众说话，吐槽剧本，甚至利用这一点预知剧情。", type: "concept"},
            {name: "超级自愈(死侍)", color: "SS", cost: 12000, desc: "比金刚狼还强的再生能力。断手断脚是家常便饭，甚至被炸成灰都能慢慢长回来（如果你有耐心）。", type: "body"},
            {name: "双刀流", color: "A", cost: 2000, desc: "精湛的武士刀技巧。配合瞬移腰带（虽然电影里没带）和不死的身体，把敌人切成刺身。", type: "skill"},
            {name: "嘴炮MAX", color: "S", cost: 5000, desc: "精神攻击。喋喋不休的废话能让反派崩溃，让队友想自杀。嘲讽值拉满。", type: "skill"},
            {name: "阿贾克斯痛觉屏蔽", color: "A", cost: 3000, desc: "弗朗西斯的能力。切除痛觉神经，获得超强反射和力量。虽然没有自愈，但不知疼痛让他极难对付。", type: "body"},
            {name: "天使尘怪力", color: "A", cost: 2500, desc: "能够徒手对抗钢力士的力量。只要嘴里叼着火柴，就能把钢铁打弯。", type: "body"},
            {name: "钢力士(说教版)", color: "A", cost: 3500, desc: "全身金属化，防御极高。但性格过于正直，总想拉你加入X战警，很烦人。", type: "status"},
            {name: "负音波少年弹头", color: "A", cost: 2800, desc: "能引爆原子级能量场。虽然是个玩手机的叛逆少女，但冲刺起来像一颗核弹头。", type: "skill"},
            {name: "牛油果脸", color: "D", cost: 100, desc: "全身皮肤像烂掉的牛油果。魅力值归零（除了对瓦妮莎）。这是获得力量的代价。", type: "curse"},
            {name: "12发子弹", color: "B", cost: 500, desc: "你只带了12发子弹去打BOSS。需要极高的爆头率和串糖葫芦技巧才能清场。", type: "event"},
            {name: "独角兽玩偶", color: "C", cost: 20, desc: "死侍的...特殊爱好。在某些不可描述的时刻能提供精神慰藉。", type: "item"},
            {name: "出租车费", color: "C", cost: 10, desc: "你从来不付多平德车费，用击掌代替。这居然能换来他的忠诚。", type: "skill"},
            {name: "治愈癌症", color: "S", cost: 4000, desc: "变异因子的副作用是治好了癌症，但癌细胞和健康细胞同时在再生，导致毁容。", type: "body"},
            {name: "拼写名字", color: "C", cost: 50, desc: "弗朗西斯。如果你拼出了反派的真名，他会暴怒，攻击力提升但智商下降。", type: "skill"},
            {name: "红色紧身衣", color: "B", cost: 200, desc: "为了不让敌人看到你流血。这很聪明，也很骚气。", type: "item"}
        ]
    },
    {
        name: "570.(漫威)X战警：天启",
        desc: "史上第一个变种人天启苏醒。他集结四骑士，试图清洗人类重建世界。年轻的X战警面临神级挑战。凤凰之力再次爆发。",
        boss: "天启(恩·沙巴·努尔), 四骑士",
        identities: [
            { name: "埃及开罗拾荒者", items: "古老的护身符, 偷来的面包" },
            { name: "波兰炼钢厂工人(万磁王)", items: "隐姓埋名, 妻女的照片" },
            { name: "X学院新学生", items: "80年代摇滚唱片, 蓝色眼影" },
            { name: "天启的信徒", items: "强化的力量, 紫色盔甲" },
            { name: "武器X计划逃亡者", items: "满地尸体, 奇怪的头盔" }
        ],
        talents: [
            {name: "天启转生", color: "SSS", cost: 45000, desc: "积累了数千年的无数超能力。自愈、传送、物质重组、增强他人能力。只要完成转生仪式，就能获得永生。", type: "exclusive"},
            {name: "四骑士强化", color: "S", cost: 8000, desc: "天启赐予的力量。天使获得金属翅膀，灵蝶获得灵能光剑，暴风女雷电增强，万磁王力量最大化。", type: "status"},
            {name: "地球磁极控制", color: "SSS", cost: 20000, desc: "万磁王被强化后的能力。直接操控地球磁场，引发全球地震、海啸和地壳运动。灭世级技能。", type: "skill"},
            {name: "凤凰之力(秒杀)", color: "SSS", cost: 50000, desc: "年轻琴·葛蕾的爆发。没有任何花哨，直接在这个维度层面抹除天启的存在。绝对的力量压制。", type: "exclusive"},
            {name: "快银时刻(救场)", color: "SS", cost: 12000, desc: "X学院爆炸瞬间，快银救出了所有人。速度快到连爆炸波都像静止一样。伴随着《Sweet Dreams》。", type: "skill"},
            {name: "灵能光剑(灵蝶)", color: "A", cost: 2500, desc: "将精神能量具现化为紫色的光刀或鞭子。削铁如泥，也是非常炫酷的近战武器。", type: "skill"},
            {name: "金属羽翼(天使)", color: "A", cost: 3000, desc: "原本的羽毛被天启转化为金属。能发射锋利的金属羽毛，飞行速度和防御力大幅提升。", type: "body"},
            {name: "镭射眼(不可控)", color: "B", cost: 1500, desc: "年轻的斯科特还无法控制能力。摘下眼镜就能切开那棵倒霉的树，或者切开天启的护盾。", type: "skill"},
            {name: "武器X(野兽版)", color: "S", cost: 6000, desc: "被洗脑的金刚狼客串。带着奇怪的头盔，见人就杀。帮助琴等人逃离了基地。", type: "event"},
            {name: "秃头诅咒", color: "D", cost: 50, desc: "X教授试图在精神世界对抗天启，结果头发掉光了。获得了经典的秃头造型。", type: "curse"},
            {name: "金字塔建造", color: "A", cost: 4000, desc: "天启能瞬间重组物质，将现代城市变成古代金字塔。改变地形的神技。", type: "skill"},
            {name: "核弹发射", color: "S", cost: 10000, desc: "天启控制各国发射所有核弹并销毁。虽然是解除武装，但也展示了控制全球的恐怖能力。", type: "event"},
            {name: "商场一日游", color: "C", cost: 20, desc: "带着没见过世面的夜行者逛商场，看《星球大战》。轻松的日常时光。", type: "event"},
            {name: "你是我的父亲", color: "B", cost: 500, desc: "快银知道了万磁王是父亲，但没说出口。这种纠结的情感影响了决战的走向。", type: "status"},
            {name: "不再是学生", color: "A", cost: 1000, desc: "魔形女的训话。面对强敌，你们不再是孩子，而是X战警。全员士气提升。", type: "status"}
        ]
    },
    {
        name: "571.(漫威)罗根",
        desc: "英雄迟暮。2029年，变种人几近灭绝。罗根自愈能力衰退，查尔斯患上老年痴呆。为了护送小狼女劳拉，他们踏上了最后的旅程。",
        boss: "X-24, 唐纳德·皮尔斯(掠夺者)",
        identities: [
            { name: "网约车司机(罗根)", items: "老花镜, 止痛药" },
            { name: "墨西哥边境护工(卡利班)", items: "防晒霜, 追踪能力" },
            { name: "人造变种人儿童(劳拉)", items: "脚上的爪子, 漫画书" },
            { name: "掠夺者雇佣兵", items: "机械义肢, 抓捕网" },
            { name: "伊甸园寻找者", items: "坐标, 希望" }
        ],
        talents: [
            {name: "衰退的自愈", color: "D", cost: 100, desc: "艾德曼合金中毒导致自愈缓慢。伤口无法愈合，走路一瘸一拐。你不再是无敌的，每一战都可能是最后一战。", type: "curse"},
            {name: "X-24(年轻罗根)", color: "SS", cost: 15000, desc: "克隆体。拥有巅峰时期的金刚狼战力，但没有灵魂和理智，只是杀戮机器。罗根的噩梦镜像。", type: "body"},
            {name: "足刃(劳拉)", color: "S", cost: 8000, desc: "X-23的能力。除了双手的爪子，脚上也能伸出爪子。战斗风格更加灵活凶狠，像一只小野兽。", type: "body"},
            {name: "查尔斯的大脑(失控)", color: "SSS", cost: 20000, desc: "世界上最危险的大脑患上了癫痫。发作时会释放毁灭性的精神波，麻痹周围所有人的神经。曾误杀了X战警全员。", type: "curse"},
            {name: "绿色药剂", color: "S", cost: 3000, desc: "能暂时恢复罗根巅峰时期的自愈和力量，但药效过后会加速衰竭。回光返照的毒药。", type: "item"},
            {name: "艾德曼合金子弹(终结)", color: "S", cost: 5000, desc: "罗根留给自己的最后一颗子弹，原本打算自杀。最终用来打爆了X-24的头。宿命的终结。", type: "item"},
            {name: "逐日号(游艇)", color: "B", cost: 2000, desc: "罗根梦想买下的船，带查尔斯出海。代表了无法实现的平静生活。最终只是个梦想。", type: "item"},
            {name: "卡利班的追踪", color: "B", cost: 1000, desc: "能感知周围变种人的存在。被反派利用来追杀罗根。最终选择自爆牺牲。", type: "talent"},
            {name: "伊甸园漫画", color: "C", cost: 50, desc: "X战警的漫画书。虽然大部分是虚构的，但伊甸园的坐标是真的。孩子的希望所在。", type: "item"},
            {name: "十字架(X)", color: "SSS", cost: 10000, desc: "劳拉将罗根坟墓上的十字架转成了X。这一刻，金刚狼死了，但X战警的精神永存。泪崩神技。", type: "concept"},
            {name: "森林追逐战", color: "A", cost: 1500, desc: "在森林中利用地形猎杀雇佣兵。虽然老了，但狼依然是狼。血腥暴力的R级战斗。", type: "skill"},
            {name: "玉米糖浆", color: "D", cost: 20, desc: "转基因玉米抑制了变种人基因。这是人类消灭变种人的软刀子，无声无息且有效。", type: "curse"},
            {name: "老花镜", color: "C", cost: 10, desc: "曾经的超级英雄现在连字都看不清。充满了生活的心酸。", type: "item"},
            {name: "最后一声爸爸", color: "S", cost: 5000, desc: "劳拉在罗根临死前喊的一声爸爸。让罗根在生命的最后一刻感受到了家庭的温暖。", type: "status"},
            {name: "掠夺者机械手", color: "B", cost: 800, desc: "皮尔斯的机械义肢。力量很大，但在这个超能力衰退的世界，依然只是凡人的科技。", type: "item"}
        ]
    },
              {
        name: "572.(漫威)死侍2",
        desc: "家庭篇。死侍组建X特攻队保护小胖子罗素，对抗来自未来的电索。充满了穿越时空的混乱和对流行文化的疯狂吐槽。",
        boss: "红坦克, 疯人院院长",
        identities: [
            { name: "X特攻队跳伞员", items: "降落伞(可能打不开), 必死的决心" },
            { name: "变种人孤儿院护工", items: "电击项圈控制器, 虐待狂倾向" },
            { name: "出租车司机多平德", items: "杀手的渴望, 沾血的雨刷" },
            { name: "电索的未来战士", items: "时空穿梭表, 巨大的枪" },
            { name: "X战警实习生", items: "黄色背心, 被死侍骚扰" }
        ],
        talents: [
            {name: "强运(多米诺)", color: "SSS", cost: 40000, desc: "运气也是一种超能力，而且是电影级的。子弹会卡壳，车祸会避开你，你甚至能猜对彩票号码。被动神技。", type: "concept"},
            {name: "时空穿梭表(电索)", color: "SS", cost: 15000, desc: "来自未来的科技。能回到过去修正错误（比如救下女友或杀死还没拍绿灯侠的瑞安·雷诺兹）。次数有限。", type: "item"},
            {name: "红坦克之力", color: "S", cost: 8000, desc: "“我是红坦克！” 巨大的体型，无法阻挡的冲撞力。能把高架桥像撕纸一样撕碎。弱点是通电。", type: "body"},
            {name: "火拳(罗素)", color: "A", cost: 3000, desc: "双手释放高温火焰。虽然是个胖小孩，但愤怒起来能烧毁整座孤儿院。未来的他是个杀人魔。", type: "skill"},
            {name: "X特攻队(团灭)", color: "E", cost: 10, desc: "加入死侍的团队通常意味着死于非命（跳伞撞公交、被直升机绞碎）。除非你是多米诺。", type: "curse"},
            {name: "死侍自愈(被抑制)", color: "C", cost: 500, desc: "戴上抑制项圈后，你的癌症会复发，自愈能力消失。这是体验凡人脆弱的时刻。", type: "curse"},
            {name: "武士刀切子弹", color: "S", cost: 4500, desc: "死侍的高光时刻。以极快的速度挥刀，将密集的弹幕全部切开。帅气值满分。", type: "skill"},
            {name: "小短腿", color: "C", cost: 100, desc: "被红坦克撕成两半后，你正在重新长腿。此时你是婴儿腿状态，没有战斗力但很萌（恶心）。", type: "body"},
            {name: "电索的机械臂", color: "A", cost: 2000, desc: "未来的生化义肢。力量巨大，内置护盾发生器和武器接口。硬汉标配。", type: "item"},
            {name: "监狱钱包", color: "C", cost: 50, desc: "死侍的...直肠。能藏一直马克笔或一把小刀。越狱必备。", type: "skill"},
            {name: "黑鸟战机(偷开)", color: "B", cost: 1000, desc: "死侍偷开X战警的飞机。虽然驾驶技术烂，但能快速到达战场（并坠毁）。", type: "item"},
            {name: "雪绪的问候", color: "B", cost: 200, desc: "“嗨，韦德！” 每次听到这句问候，你的心情都会变好。获得治愈系BUFF。", type: "status"},
            {name: "隐形人(布拉德·皮特)", color: "A", cost: 2500, desc: "全程隐形，只有触电死的时候才会露脸一秒。最完美的潜行能力。", type: "body"},
            {name: "酸液吐息(喧嚣)", color: "B", cost: 800, desc: "X特攻队幸存者之一。能吐出强腐蚀性酸液。虽然不强，但至少活下来了。", type: "skill"},
            {name: "家庭", color: "S", cost: 5000, desc: "死侍的核心领悟。家庭不是血缘，而是愿意为你流血的人。团队羁绊加成。", type: "concept"}
        ]
    },
    {
        name: "573.(漫威)新变种人",
        desc: "青春恐怖片。五个年轻的变种人被关在一家神秘医院，面对各自的心理阴影和恶魔熊。这是福克斯X战警宇宙的绝唱。",
        boss: "恶魔熊, 塞西利亚·雷耶斯医生",
        identities: [
            { name: "米尔伯里医院病患", items: "病号服, 心理创伤" },
            { name: "埃塞克斯公司监视者", items: "监控屏幕, 记录本" },
            { name: "恶魔熊的猎物", items: "印第安护身符, 恐惧" },
            { name: "地狱边缘领主(秘客)", items: "魂之利刃, 洛克希德(龙)" },
            { name: "煤矿事故幸存者(加农炮)", items: "安全帽, 愧疚" }
        ],
        talents: [
            {name: "魂之利刃(秘客)", color: "SS", cost: 12000, desc: "伊莉亚娜的能力。从地狱边缘召唤的魔法剑，能斩断魔法和灵体。自带酷炫的铠甲和传送门。", type: "magic"},
            {name: "恐惧具现(月星)", color: "S", cost: 8000, desc: "丹妮尔的能力。读取他人的恐惧并将其具现化为实体怪物。恶魔熊就是她潜意识恐惧的产物。", type: "magic"},
            {name: "加农炮冲刺", color: "A", cost: 3000, desc: "山姆的能力。像火箭一样发射自己，产生无敌的能量场。撞击力极强，但转向困难。", type: "skill"},
            {name: "太阳黑子(觉醒)", color: "A", cost: 3500, desc: "罗伯托的能力。全身燃烧黑色火焰，发射高热能量。虽然这里削弱了，但依然是强力输出。", type: "skill"},
            {name: "狼毒变身", color: "B", cost: 1500, desc: "拉恩的能力。变成狼人形态，获得野兽感官和利爪。虽然不如金刚狼，但敏捷度很高。", type: "body"},
            {name: "力场屏障(医生)", color: "B", cost: 1000, desc: "雷耶斯医生的能力。能制造包裹全身或囚禁他人的力场。虽然被恶魔熊一口吞了，但防御力尚可。", type: "skill"},
            {name: "洛克希德(手偶)", color: "A", cost: 2000, desc: "秘客的小龙。平时是手偶，战斗时变成真的紫色喷火龙。是魔法生物。", type: "pet"},
            {name: "地狱边缘传送", color: "S", cost: 5000, desc: "秘客的传送能力。通过地狱边缘中转，可以去任何地方。也是召唤铠甲和剑的通道。", type: "magic"},
            {name: "笑脸人(恐惧)", color: "C", cost: 500, desc: "具现出的恐怖怪物。虽然战斗力不高，但精神污染极强，能让敌人陷入恐慌。", type: "monster"},
            {name: "埃塞克斯公司", color: "D", cost: 100, desc: "惊恶先生的公司。被他们盯上意味着你将被切片研究或改造成武器。这层阴影挥之不去。", type: "curse"},
            {name: "医院结界", color: "B", cost: 800, desc: "困住变种人的能量场。除非杀死施术者（医生），否则无法逃离。限制移动范围。", type: "curse"},
            {name: "印第安血统", color: "C", cost: 50, desc: "月星的背景。赋予你与自然沟通的潜质，以及对恶魔熊传说的了解。", type: "status"},
            {name: "青春期躁动", color: "C", cost: 20, desc: "荷尔蒙爆发。情绪波动大，容易失控，但也容易建立深厚的友情（或爱情）。", type: "status"},
            {name: "测谎仪", color: "C", cost: 10, desc: "大家围坐在一起玩真心话大冒险。能快速了解队友的背景故事和弱点。", type: "event"},
            {name: "不再恐惧", color: "S", cost: 4000, desc: "克服恐惧是战胜恶魔熊的关键。当丹妮尔直面恐惧时，恶魔熊消散。精神力量的胜利。", type: "status"}
        ]
    },
    {
        name: "574.(漫威)毒液1",
        desc: "索尼蜘蛛侠宇宙(SSU)开篇。记者埃迪·布洛克与外星共生体毒液结合。从失败者到致命守护者。不是超级英雄，是吃人的怪物。",
        boss: "暴乱(Riot), 德雷克博士",
        identities: [
            { name: "生命基金会实验体", items: "共生体排斥反应, 死亡倒计时" },
            { name: "旧金山落魄记者", items: "录音笔, 摩托车" },
            { name: "陈太太便利店常客", items: "巧克力, 讨价还价技巧" },
            { name: "特种部队追捕者", items: "声波武器, 闪光弹" },
            { name: "暴乱宿主", items: "银色流体, 想要毁灭地球的疯狂" }
        ],
        talents: [
            {name: "毒液共生体", color: "SS", cost: 15000, desc: "我是毒液。赋予宿主怪力、变形、触手、自愈能力。虽然怕火怕声波，但在地球上几乎是食物链顶端。", type: "exclusive"},
            {name: "暴乱共生体", color: "SS", cost: 18000, desc: "共生体小队的队长。比毒液更强壮，能将手臂变成巨大的斧头、流星锤等冷兵器。极其残暴。", type: "exclusive"},
            {name: "我们是毒液", color: "S", cost: 5000, desc: "埃迪与毒液的完美同步。当两人心意相通时，战斗力倍增，能克服共生体的弱点。", type: "status"},
            {name: "吃脑子", color: "A", cost: 2000, desc: "毒液最喜欢的零食。吃掉敌人的头不仅能补充苯乙胺（维持共生体健康），还能造成即死效果。", type: "skill"},
            {name: "寄生转移", color: "B", cost: 1500, desc: "共生体可以随时更换宿主。从狗到安妮，再回到埃迪。利用这个能力可以快速移动或救人。", type: "skill"},
            {name: "声波弱点", color: "E", cost: 100, desc: "4000-6000赫兹的声音会让共生体痛苦地脱离宿主。这是致命的阿喀琉斯之踵。", type: "curse"},
            {name: "火焰弱点", color: "E", cost: 100, desc: "共生体极度怕火。高温会让其失去战斗力甚至死亡。火箭发射时的火焰是噩梦。", type: "curse"},
            {name: "女毒液(She-Venom)", color: "S", cost: 6000, desc: "安妮与毒液结合的形态。身姿曼妙但致命，拥有不输原本的力量，还多了一份敏捷。", type: "body"},
            {name: "摩托车追逐战", color: "B", cost: 800, desc: "利用触手辅助驾驶摩托车。能做出违背物理定律的动作，在旧金山的街道上横冲直撞。", type: "skill"},
            {name: "生命基金会飞船", color: "A", cost: 3000, desc: "德雷克用来带回更多共生体的飞船。如果发射成功，地球将被数百万共生体吞噬。", type: "item"},
            {name: "巧克力", color: "C", cost: 20, desc: "脑子的替代品。含有苯乙胺，能安抚饥饿的毒液。随身携带能防止毒液吃掉无辜路人。", type: "item"},
            {name: "寄生虫", color: "C", cost: 10, desc: "毒液最讨厌的称呼。如果你叫它寄生虫，它会让你道歉（物理）。", type: "status"},
            {name: "治愈断肢", color: "A", cost: 2500, desc: "共生体能修复宿主的任何损伤。即使腿断了，只要共生体覆盖，就能像没事人一样奔跑。", type: "body"},
            {name: "全景视野", color: "B", cost: 1000, desc: "共生体能感知周围360度的环境。你是无法被偷袭的。", type: "talent"},
            {name: "失败者联盟", color: "B", cost: 500, desc: "毒液自称在母星也是个loser。这让它和埃迪产生了共鸣，决定保护地球（因为这里它是大佬）。", type: "status"}
        ]
    },
    {
        name: "575.(漫威)毒液2：屠杀开始",
        desc: "红色共生体屠杀登场。克莱图斯·卡萨迪是个连环杀手，与屠杀结合后成为了纯粹的杀戮机器。埃迪与毒液的婚姻危机。",
        boss: "屠杀(Carnage), 尖叫(Shriek)",
        identities: [
            { name: "圣昆廷监狱死刑犯", items: "橙色囚服, 咬破的手指" },
            { name: "拉文克罗夫特疯人院病患", items: "束缚衣, 尖叫声" },
            { name: "埃迪的室友(毒液)", items: "两只鸡(索尼和切尔), 乱糟糟的公寓" },
            { name: "屠杀的宿主", items: "红色的触手, 杀人狂的逻辑" },
            { name: "旧金山警探", items: "配枪, 对怪物的无力感" }
        ],
        talents: [
            {name: "屠杀共生体", color: "SSS", cost: 25000, desc: "毒液的后代，红色的死神。与宿主血液融合，更加强大、敏捷。能制造无数锋利的武器，还能像龙卷风一样旋转。", type: "exclusive"},
            {name: "声波尖叫(尖叫)", color: "S", cost: 7000, desc: "弗朗西斯·巴里森的能力。能发出震碎耳膜和玻璃的超声波。是所有共生体的天敌，包括屠杀（家暴现场）。", type: "skill"},
            {name: "武器化肢体", color: "S", cost: 6000, desc: "屠杀能将身体任何部位变成斧头、标枪、网。攻击范围极大，且能发射尖刺进行远程打击。", type: "skill"},
            {name: "互联网上传", color: "A", cost: 3000, desc: "屠杀可以通过电脑网络入侵互联网，获取信息或进行黑客攻击。这是共生体的进化能力。", type: "skill"},
            {name: "致命咬痕", color: "B", cost: 500, desc: "克莱图斯咬了埃迪一口，吞下了含有共生体的血液。这是屠杀诞生的契机。不要乱咬人。", type: "event"},
            {name: "教堂钟声", color: "A", cost: 2000, desc: "最终决战地。巨大的钟声是共生体的噩梦。利用钟声可以剥离屠杀和宿主。", type: "event"},
            {name: "不共戴天", color: "D", cost: 100, desc: "屠杀和宿主并不完美融合。因为尖叫的声波伤到了屠杀，导致两者产生裂痕。这是击败它的关键。", type: "curse"},
            {name: "龙卷风攻击", color: "S", cost: 5000, desc: "屠杀的高速旋转技能。像红色的绞肉机一样摧毁沿途的一切，包括直升机和监狱墙壁。", type: "skill"},
            {name: "毒液的恐惧", color: "C", cost: 50, desc: "看到红色共生体时，毒液吓得躲回了埃迪体内。需要埃迪的鼓励（或承诺让它吃坏人）才能出来战斗。", type: "status"},
            {name: "索尼和切尔", color: "C", cost: 20, desc: "毒液养的两只鸡。虽然毒液想吃脑子，但舍不得吃它们。也是友情的见证。", type: "pet"},
            {name: "红色婚礼", color: "B", cost: 1000, desc: "屠杀大闹婚礼现场。充满了混乱和破坏。在这里战斗，任何物品都可以作为武器。", type: "event"},
            {name: "吞噬后代", color: "S", cost: 4000, desc: "毒液吃掉了屠杀。获得了对方的力量（虽然电影没表现，但理论上变强了）。只有毒液能杀死屠杀。", type: "skill"},
            {name: "多元宇宙穿越(彩蛋)", color: "SS", cost: 10000, desc: "片尾彩蛋。毒液舔屏看到了蜘蛛侠。标志着它进入了MCU（虽然只是度了个假）。", type: "event"},
            {name: "杀人狂的艺术", color: "C", cost: 50, desc: "克莱图斯的画作和诗句。充满了疯狂的艺术感，也能提供关于他弱点的线索。", type: "item"},
            {name: "分手快乐", color: "C", cost: 10, desc: "毒液离家出走去夜店狂欢。虽然很嗨，但离开了埃迪它活不久。", type: "event"}
        ]
    },
    {
        name: "576.(漫威)莫比亚斯",
        desc: "暗夜博士。迈克尔·莫比亚斯为了治愈血液病，将自己变成了吸血鬼。回声定位、飞行、嗜血。在人性与兽性之间挣扎。",
        boss: "米洛(卢锡安), 秃鹫(客串)",
        identities: [
            { name: "诺贝尔奖得主", items: "人造血液, 奖章" },
            { name: "吸血鬼实验体", items: "尖牙, 对血的渴望" },
            { name: "货轮雇佣兵", items: "冲锋枪, 变成干尸" },
            { name: "地铁站路人", items: "报纸, 被风吹倒" },
            { name: "FBI探员", items: "圣水(没用), 银子弹(也没用)" }
        ],
        talents: [
            {name: "活体吸血鬼", color: "SS", cost: 12000, desc: "融合了蝙蝠DNA。获得超人的力量、速度、自愈力。但必须每隔几小时饮用人血，否则会衰弱暴走。", type: "body"},
            {name: "回声定位", color: "S", cost: 6000, desc: "莫比亚斯的招牌能力。发出声波，感知周围的一切动态。视觉化为彩色的波纹，无视烟雾和黑暗。", type: "skill"},
            {name: "滑翔飞行", color: "A", cost: 3000, desc: "利用气流进行高速滑翔。甚至能乘着地铁的气流在隧道中穿梭。机动性极强。", type: "skill"},
            {name: "紫色残影", color: "A", cost: 2500, desc: "移动速度快到留下残影。在敌人眼中，你就是一团紫色的雾气，瞬间出现在身后。", type: "skill"},
            {name: "人造血液(蓝色)", color: "B", cost: 500, desc: "莫比亚斯发明的血液替代品。能暂时抑制嗜血欲望，但效力越来越短。只能维持基本生存。", type: "item"},
            {name: "控制蝙蝠", color: "S", cost: 4000, desc: "召唤并控制成群的吸血蝙蝠。它们视你为同类，能帮你攻击敌人或托起你的身体飞行。", type: "skill"},
            {name: "米洛的嫉妒", color: "A", cost: 2000, desc: "同样注射了血清的反派。因为嫉妒和放纵欲望，他比莫比亚斯更残暴，杀人毫无顾忌。", type: "status"},
            {name: "抗凝血剂", color: "A", cost: 1500, desc: "对付吸血鬼的毒药。注入后会让血液无法凝固，对依赖血液代谢的莫比亚斯是致命的。", type: "item"},
            {name: "吸血鬼之吻", color: "S", cost: 3500, desc: "咬住敌人颈动脉吸血。瞬间恢复生命值并获得力量加成。但会丧失理智，堕入黑暗。", type: "skill"},
            {name: "诺贝尔奖智商", color: "A", cost: 1000, desc: "你是个天才生物学家。能利用环境和科学知识制定战术，而不只是像野兽一样撕咬。", type: "talent"},
            {name: "折纸独角兽", color: "C", cost: 10, desc: "这是《银翼杀手》的梗吗？不，这是莫比亚斯留给米洛的信物。兄弟情的象征。", type: "item"},
            {name: "秃鹫的邀请", color: "B", cost: 500, desc: "片尾彩蛋。来自MCU的秃鹫邀请你组队（邪恶六人组？）。虽然逻辑不通，但意味着你有队友了。", type: "event"},
            {name: "时间变慢", color: "A", cost: 2000, desc: "在极速状态下，周围的时间仿佛变慢。你可以轻松躲避子弹（黑客帝国式）。", type: "skill"},
            {name: "嗜血诅咒", color: "D", cost: 200, desc: "如果不喝血，你会变成干尸状的怪物，理智全无。你必须在做英雄和做怪物之间选择。", type: "curse"},
            {name: "猫咪", color: "C", cost: 20, desc: "你在实验室养的猫。当你变身时，它没有被吓跑。证明你内心深处还有人性。", type: "pet"}
        ]
    },
    {
        name: "577.(漫威)神奇四侠(2005)",
        desc: "经典的四人组。神奇先生、隐形女、霹雳火、石头人。在太空遭遇宇宙风暴后获得超能力。对抗毁灭博士。家庭与责任的主题。",
        boss: "毁灭博士(维克多·冯·杜姆)",
        identities: [
            { name: "巴克斯特大厦访客", items: "参观证, 被石头人吓到" },
            { name: "冯·杜姆工业员工", items: "股票(即将暴跌), 钛合金面具" },
            { name: "布鲁克林大桥路人", items: "消防车, 手机拍照" },
            { name: "太空站宇航员", items: "宇航服, 宇宙风暴辐射" },
            { name: "神奇四侠粉丝", items: "印着4字的T恤, 签名本" }
        ],
        talents: [
            {name: "橡胶身体(神奇先生)", color: "SS", cost: 10000, desc: "身体可以无限拉伸、变形、反弹。能包裹住炸弹，也能变成降落伞。智商更是漫威顶尖。", type: "body"},
            {name: "隐形力场(隐形女)", color: "SS", cost: 12000, desc: "苏·斯托姆的能力。不仅能隐形，还能制造强大的能量力场。能挡住火焰风暴，也能捏碎敌人心脏（如果她想）。", type: "magic"},
            {name: "火焰新星(霹雳火)", color: "SS", cost: 11000, desc: "“Flame On!” 全身燃烧，飞行，发射火球。终极技能是产生超新星般的高温，足以熔化一切。", type: "skill"},
            {name: "岩石皮肤(石头人)", color: "S", cost: 8000, desc: "本·格瑞姆变成了橙色的岩石巨人。力量巨大，防御无敌。虽然失去了正常人的生活，但他是团队的坦克。", type: "body"},
            {name: "电能操纵(毁灭博士)", color: "SS", cost: 15000, desc: "身体金属化，能吸收和发射巨大的电能。加上他的天才头脑和无情手段，是极难对付的BOSS。", type: "skill"},
            {name: "宇宙风暴机器", color: "A", cost: 3000, desc: "里德制造的模拟宇宙风暴的机器。能剥夺四侠的能力，也能强化毁灭博士。双刃剑。", type: "item"},
            {name: "巴克斯特大厦", color: "S", cost: 5000, desc: "神奇四侠的总部。拥有顶尖的实验室、发射台和防御系统。是科技的堡垒。", type: "item"},
            {name: "热追踪导弹", color: "A", cost: 2000, desc: "毁灭博士发射的导弹。霹雳火在城市中与其竞速，最终利用高温引爆。", type: "item"},
            {name: "钛合金面具", color: "B", cost: 500, desc: "维克多为了掩盖伤疤戴上的面具。后来与皮肤融合。是反派的标志。", type: "item"},
            {name: "超新星围困", color: "S", cost: 6000, desc: "四侠合体技。霹雳火制造高温，隐形女用力场包裹，石头人和神奇先生控制。将毁灭博士熔化成雕塑。", type: "skill"},
            {name: "家庭争吵", color: "C", cost: 50, desc: "四个人经常吵架，但这增加了羁绊。在关键时刻，这种羁绊能转化为战斗力。", type: "status"},
            {name: "变回凡人", color: "D", cost: 100, desc: "本一直想变回普通人。这种执念差点被反派利用。接受自我才是力量的源泉。", type: "curse"},
            {name: "神奇飞车", color: "A", cost: 1500, desc: "能飞行的汽车。虽然经常坠毁，但在这个时代是很酷的交通工具。", type: "item"},
            {name: "媒体宠儿", color: "B", cost: 300, desc: "神奇四侠是公众人物。拥有极高的声望，能获得市民的帮助，但也时刻被狗仔队盯着。", type: "status"},
            {name: "路灯侠", color: "C", cost: 20, desc: "神奇先生被冻住时像个路灯。虽然很囧，但身体确实很有韧性。", type: "status"}
        ]
    },
    {
        name: "578.(漫威)神奇四侠2：银影侠",
        desc: "银影侠降临，预示着行星吞噬者的到来。神奇四侠面临全球危机。能力互换的闹剧，以及最后的牺牲与救赎。",
        boss: "行星吞噬者(云团版), 拥有银影滑板的毁灭博士",
        identities: [
            { name: "婚礼宾客", items: "礼服, 被毁的婚礼蛋糕" },
            { name: "美军将领", items: "捕捉银影侠的命令, 顽固" },
            { name: "银影侠", items: "银色滑板, 宇宙能量" },
            { name: "行星吞噬者使徒", items: "虚无感, 对能量的渴望" },
            { name: "能力互换的石头人", items: "身体不仅硬还滑溜溜(橡胶), 困惑" }
        ],
        talents: [
            {name: "银影滑板", color: "SSS", cost: 40000, desc: "宇宙神器。赋予持有者宇宙能量，能以超光速飞行，穿透物质，发射能量波。离开滑板银影侠会变弱。", type: "item"},
            {name: "宇宙能量(银影侠)", color: "SS", cost: 20000, desc: "被吞星赐予的力量。全身银色皮肤坚不可摧，能复活死者，甚至能破坏滑板。", type: "body"},
            {name: "行星吞噬者(Galactus)", color: "UR", cost: 100000, desc: "宇宙五大神明之一。虽然电影里是一团云，但它吞噬星球的概念是绝对的毁灭。无法正面对抗。", type: "event"},
            {name: "能力互换", color: "S", cost: 5000, desc: "因接触银影侠而产生的副作用。四侠只要触碰就会互换能力。虽然混乱，但最后约翰尼集齐了四种能力。", type: "skill"},
            {name: "超级斯克鲁人(伪)", color: "SS", cost: 15000, desc: "集齐四侠能力的约翰尼。拥有岩石身体、隐形力场、橡胶四肢和火焰。单挑拥有滑板的毁灭博士。", type: "skill"},
            {name: "泰加脉冲发射器", color: "A", cost: 3000, desc: "里德发明的装置。能将银影侠从滑板上分离下来。科技侧对神级单位的克制。", type: "item"},
            {name: "毁灭博士(滑板版)", color: "SSS", cost: 30000, desc: "维克多抢走了滑板。结合了他的科技和魔法知识，这一刻他接近神明。能发射追踪飞锯。", type: "status"},
            {name: "牺牲一击", color: "SSS", cost: 50000, desc: "银影侠找回良知，冲向行星吞噬者释放全部能量。同归于尽的一击，拯救了地球。", type: "skill"},
            {name: "伦敦眼救援", color: "A", cost: 2000, desc: "为了防止伦敦眼倒塌，四侠合力支撑。展示了团队配合拯救平民的英雄本色。", type: "event"},
            {name: "极速飞行", color: "S", cost: 4000, desc: "追逐银影侠。从纽约飞到上海只需几分钟。穿越隧道和大气层的极速体验。", type: "skill"},
            {name: "婚礼被毁", color: "C", cost: 50, desc: "里德和苏的婚礼总是被意外打断。这是个诅咒，但也证明了真爱不怕等待。", type: "curse"},
            {name: "大坑", color: "B", cost: 500, desc: "银影侠经过的地方会留下巨大的坑洞，地核能量被吸走。这是末日的倒计时。", type: "event"},
            {name: "石头人的自卑", color: "D", cost: 100, desc: "本依然觉得自己是怪物。但在关键时刻，他用岩石身体保护了苏，证明了外表不重要。", type: "status"},
            {name: "隐形女的力场(加强)", color: "S", cost: 6000, desc: "苏的能力进化了。能打穿毁灭博士的身体，也能包裹整个伦敦眼。她是队里最强的防御。", type: "skill"},
            {name: "滑板冲浪", color: "B", cost: 1000, desc: "如果你能抢到滑板，你也能像银影侠一样冲浪。但小心别掉下来，宇宙空间很冷的。", type: "skill"}
        ]
    },
    {
        name: "579.(漫威)新神奇四侠(2015)",
        desc: "黑暗风重启版。年轻的四人组穿越到零号星球，获得诅咒般的能力。毁灭博士变得更加恐怖和非人。口碑崩塌但设定硬核。",
        boss: "毁灭博士(零号星球版)",
        identities: [
            { name: "巴克斯特基金会天才", items: "量子门设计图, 3D打印机" },
            { name: "零号星球探险者", items: "防护服(已融化), 绿色能量" },
            { name: "军方实验体(第57区)", items: "抑制服, 隐形战机" },
            { name: "街头赛车手(约翰尼)", items: "改装车, 叛逆" },
            { name: "毁灭博士的信徒", items: "爆头意念, 绿色披风" }
        ],
        talents: [
            {name: "零号星球能量", color: "SSS", cost: 35000, desc: "来自异维度的绿色能量。能重组物质，引发地震，甚至创造虫洞吞噬地球。毁灭博士的力量源泉。", type: "exclusive"},
            {name: "爆头(毁灭博士)", color: "SS", cost: 10000, desc: "维克多只需看一眼，就能让人脑浆炸裂。极度血腥的念力攻击，在走廊里屠杀军队。", type: "skill"},
            {name: "岩石茧(石头人)", color: "A", cost: 5000, desc: "本被岩石包裹，没有缝隙，没有嘴唇。比老版更像怪物，防御力更高，但也更痛苦。", type: "body"},
            {name: "能量形态(霹雳火)", color: "A", cost: 6000, desc: "身体时刻在燃烧。需要特制的抑制服才能控制。飞行和火球威力巨大，但容易失控。", type: "body"},
            {name: "伸缩身体(里德)", color: "A", cost: 5500, desc: "身体像流体一样，没有骨头。能变形成各种形状，也能在废墟中穿梭。看着有点恐怖。", type: "body"},
            {name: "量子门", color: "S", cost: 8000, desc: "通往零号星球的传送装置。不仅能传送人，还能作为毁灭地球的武器（吸走地球物质）。", type: "item"},
            {name: "隐形与力场", color: "A", cost: 7000, desc: "苏不仅能隐形，还能用能量球攻击。她的力场是唯一能抵挡毁灭博士爆头攻击的防御。", type: "magic"},
            {name: "第57区", color: "B", cost: 1000, desc: "秘密军事基地。你被关在这里做活体武器。虽然有吃有喝，但没有自由。", type: "status"},
            {name: "毁灭博士的披风", color: "B", cost: 500, desc: "那是宇航服融化在身上的残留物。与皮肤融合，永远无法脱下。象征着人性的丧失。", type: "item"},
            {name: "团队协作(最后10分钟)", color: "S", cost: 4000, desc: "整部电影只有最后10分钟四人联手。里德当绳子，石头人当锤子，合力把毁灭博士推回虫洞。", type: "skill"},
            {name: "被遗弃", color: "D", cost: 200, desc: "维克多被留在零号星球一年。孤独和能量侵蚀让他彻底疯狂，只想毁灭地球。", type: "curse"},
            {name: "猴子实验", color: "C", cost: 50, desc: "第一批传送过去的猴子炸了。这预示着你们的命运。传送有风险，穿越需谨慎。", type: "event"},
            {name: "科学展", color: "C", cost: 10, desc: "里德和本在小学科学展上造出了传送机原型。天才总是从小就与众不同。", type: "event"},
            {name: "我是末日", color: "B", cost: 600, desc: "维克多自称Doom。这不仅是名字，更是他的宣言。气场压制。", type: "status"},
            {name: "烂片诅咒", color: "E", cost: 0, desc: "虽然设定很强，但剧情剪辑混乱。作为玩家，你可能不仅要对抗反派，还要对抗糟糕的剧本。", type: "curse"}
        ]
    },
    {
        name: "580.(漫威)死侍与金刚狼",
        desc: "MCU死侍篇。时间管理局(TVA)介入，死侍为了拯救自己的宇宙，挖出了另一个宇宙的落魄金刚狼。多元宇宙大乱斗。",
        boss: "卡桑德拉·诺瓦, 悖论先生",
        identities: [
            { name: "二手车销售员(韦德)", items: "假发, 平凡的生活" },
            { name: "虚空之地幸存者", items: "本田奥德赛, 疯狂麦克斯风格装备" },
            { name: "TVA特工", items: "时间裁切棒, 传送门控制器" },
            { name: "死侍军团成员", items: "千奇百怪的死侍制服, 狗死侍" },
            { name: "X-23(长大版)", items: "墨镜, 依然锋利的爪子" }
        ],
        talents: [
            {name: "时间撕裂者(Time Ripper)", color: "SSS", cost: 50000, desc: "悖论先生制造的机器。能加速时间线的死亡，瞬间抹除一个宇宙。毁灭世界的终极武器。", type: "item"},
            {name: "卡桑德拉·诺瓦(X教授妹妹)", color: "SSS", cost: 45000, desc: "虚空之地的女王。拥有甚至超越X教授的心灵能力，还能像奇异博士一样玩弄空间。手指插入大脑极其恐怖。", type: "magic"},
            {name: "死侍与金刚狼(合体技)", color: "SSS", cost: 30000, desc: "当两人不再互捅，而是并肩作战时。不死的肉盾+无坚不摧的利爪+嘴炮。伴随着《Like a Prayer》清场。", type: "skill"},
            {name: "虚空之地(The Void)", color: "S", cost: 10000, desc: "时间尽头的垃圾场。这里有被裁剪的复仇者大厦、20世纪福克斯的标志。充满了各种彩蛋角色。", type: "event"},
            {name: "艾德曼合金骨骼(多元宇宙版)", color: "SS", cost: 20000, desc: "这个金刚狼是全宇宙最惨的。他辜负了X战警，但他依然拥有那副无敌的骨架和爪子。", type: "body"},
            {name: "死侍军团", color: "S", cost: 15000, desc: "一百个死侍。女死侍、牛仔死侍、死人头... 虽然都是不死之身，但智商普遍不高。", type: "item"},
            {name: "狗死侍(Dogpool)", color: "A", cost: 5000, desc: "世界上最丑的狗。虽然没战斗力，但它的舔舐能让死侍心情愉悦（或者恶心）。吉祥物。", type: "pet"},
            {name: "时间裁切棒", color: "S", cost: 8000, desc: "TVA的武器。被击中者会被送到虚空之地。一击必杀（物理层面消失）。", type: "item"},
            {name: "佩佩(刀锋战士客串)", color: "A", cost: 3000, desc: "韦斯利·斯奈普斯回归！虽然老了，但杀吸血鬼的刀依然快。还有那句“只有一个刀锋战士”。", type: "status"},
            {name: "牌皇(查宁·塔图姆)", color: "A", cost: 3500, desc: "终于实现了梦想的牌皇。口音很重，但能量爆炸的扑克牌真的帅炸了。", type: "skill"},
            {name: "伊莱克特拉(艾丽卡)", color: "A", cost: 2500, desc: "詹妮弗·加纳回归。双叉犀利，刺客大师。怀旧分满分。", type: "skill"},
            {name: "本田奥德赛", color: "B", cost: 1200, desc: "死侍嫌弃但实用的MPV。在虚空之地的一场血腥车震（打架）发生在这里。", type: "item"},
            {name: "物质反物质对撞", color: "SSS", cost: 60000, desc: "死侍和金刚狼手牵手充当导体，短路了时间撕裂者。这是牺牲，也是救赎。", type: "event"},
            {name: "锚点之人(Anchor Being)", color: "SSS", cost: 40000, desc: "一个宇宙的核心人物（如罗根）。如果他死了，宇宙就会慢慢消亡。你是宇宙存在的基石。", type: "concept"},
            {name: "打破迪士尼第四面墙", color: "SS", cost: 10000, desc: "吐槽凯文·费奇，吐槽迪士尼收购福克斯。这种官方吐槽最为致命。", type: "skill"}
        ]
    },
    {
        name: "581.(漫威)蜘蛛夫人",
        desc: "拥有预知未来能力的急救员卡桑德拉·韦伯。保护三位未来的蜘蛛女侠，对抗毒蜘蛛以西结。这是一场关于命运与母性的战斗。",
        boss: "以西结·希姆斯(毒蜘蛛)",
        identities: [
            { name: "纽约急救员", items: "救护车, 奇怪的既视感" },
            { name: "秘鲁探险家", items: "稀有蜘蛛, 地图" },
            { name: "未来的蜘蛛女侠(朱莉娅)", items: "还未觉醒的战衣, 青春期烦恼" },
            { name: "以西结的黑客助手", items: "面部识别系统, 监控网络" },
            { name: "亚马逊部落守护者", items: "蜘蛛图腾, 治疗毒液" }
        ],
        talents: [
            {name: "预知未来(千里眼)", color: "SS", cost: 15000, desc: "卡桑德拉的能力。能看到几分钟甚至更远的未来片段。虽然不能直接战斗，但能规避所有致死攻击。", type: "talent"},
            {name: "灵体投射", color: "S", cost: 8000, desc: "灵魂出窍，分身出现在不同地点。能同时救下三个人，或者迷惑敌人。物理攻击无效。", type: "magic"},
            {name: "毒触(以西结)", color: "A", cost: 5000, desc: "被亚马逊毒蜘蛛咬后获得的能力。只要触碰就能让人中毒身亡。配合类似蜘蛛侠的体术，非常致命。", type: "skill"},
            {name: "爬墙与怪力", color: "A", cost: 4000, desc: "以西结拥有标准的蜘蛛侠套餐能力。但他没有蛛丝发射器，只能靠跳跃和爬行。", type: "body"},
            {name: "偷来的蜘蛛", color: "B", cost: 1000, desc: "一只具有神奇疗效的秘鲁蜘蛛。它的毒液能治愈瘫痪，也能赋予超能力。一切的起源。", type: "item"},
            {name: "救护车驾驶技术", color: "B", cost: 600, desc: "在纽约拥堵的街道上狂飙。甚至能把救护车当成碰碰车撞飞反派。老司机的愤怒。", type: "skill"},
            {name: "未来的命运线", color: "S", cost: 6000, desc: "你可以看到每个人未来的命运。这让你在战斗中总能做出最优选择，比如让反派被广告牌砸死。", type: "concept"},
            {name: "瘫痪与盲眼", color: "D", cost: 200, desc: "最终战后，卡桑德拉虽然瞎了且瘫痪，但她的心灵感应能力达到了巅峰。成为了真正的蜘蛛夫人。", type: "curse"},
            {name: "三个蜘蛛女侠", color: "A", cost: 3000, desc: "虽然现在是废柴少女，但未来她们是强大的英雄。保护她们就是保护未来。获得团队羁绊。", type: "status"},
            {name: "天花板上的噩梦", color: "C", cost: 50, desc: "以西结总是做梦被三个蜘蛛女侠杀死。这让他变得偏执和疯狂。利用这一点可以扰乱他的心智。", type: "status"},
            {name: "百事可乐广告牌", color: "C", cost: 20, desc: "最终决战的关键道具。巨大的字母掉下来砸死了BOSS。物理学圣剑。", type: "item"},
            {name: "本·帕克(年轻版)", color: "B", cost: 500, desc: "他是你的同事。虽然他还没遇到梅，但那种善良和责任感已经显现。保护好本叔叔！", type: "status"},
            {name: "亚马逊蜘蛛毒液", color: "A", cost: 2000, desc: "既是毒药也是解药。能让死人复活（如果及时），也能让人痛不欲生。", type: "item"},
            {name: "面部识别系统", color: "S", cost: 3500, desc: "以西结盗用的NSA系统。能追踪全球任何一个人。在逃亡中，无处藏身。", type: "item"},
            {name: "烟花仓库", color: "B", cost: 800, desc: "利用烟花制造混乱和爆炸。绚丽的色彩能干扰以西结的蜘蛛感应（虽然他好像没有）。", type: "event"}
        ]
    },
              {
        name: "582.(漫威)蜘蛛侠1",
        desc: "经典的开端。彼得·帕克被变异蜘蛛咬伤，本叔叔的死让他明白了“能力越大，责任越大”。对抗绿魔，拯救玛丽·简。最纯粹的英雄故事。",
        boss: "绿魔(诺曼·奥斯本)",
        identities: [
            { name: "中城高中书呆子", items: "厚眼镜, 相机" },
            { name: "奥斯本工业实习生", items: "实验记录本, 强化药剂残渣" },
            { name: "地下摔跤手", items: "滑稽的自制战衣, 3000美元支票(被骗了)" },
            { name: "号角日报自由摄影师", items: "蜘蛛侠独家照片, 被老板骂" },
            { name: "哥伦比亚大学学生", items: "课本, 总是迟到" }
        ],
        talents: [
            {name: "有机蛛丝", color: "SS", cost: 12000, desc: "托比版的独特设定。不需要发射器，手腕腺体直接喷射蛛丝。无限弹药，但会受情绪影响（抑郁了就射不出来）。", type: "body"},
            {name: "蜘蛛感应", color: "SS", cost: 10000, desc: "预知危险的第六感。时间仿佛变慢，你能感知到背后的拳头、飞来的南瓜炸弹。闪避率+99%。", type: "talent"},
            {name: "吸附爬墙", color: "A", cost: 4000, desc: "手脚产生静电吸附力，能在任何表面自由攀爬。倒挂接吻的前提条件。", type: "body"},
            {name: "人体强化(蜘蛛)", color: "S", cost: 8000, desc: "力量举起卡车，近视眼痊愈，反应速度超越常人。这是完美的生物进化。", type: "body"},
            {name: "绿魔滑板", color: "S", cost: 5000, desc: "奥斯本的高科技飞行器。速度极快，配备机枪和导弹。甚至能伸出刀片把人切成两半（包括使用者）。", type: "item"},
            {name: "人体强化(绿魔)", color: "S", cost: 7000, desc: "注射人体强化药剂。获得与蜘蛛侠匹敌的力量和耐力。副作用是产生邪恶的第二人格。", type: "body"},
            {name: "南瓜炸弹", color: "A", cost: 2500, desc: "绿魔的招牌武器。能把人炸成骷髅，或者释放飞刀。外观可爱但极其致命。", type: "item"},
            {name: "倒挂之吻", color: "C", cost: 500, desc: "在雨中倒挂着亲吻心爱的人。这是影史经典一幕，能大幅提升玛丽·简的好感度。", type: "event"},
            {name: "摔跤技巧", color: "B", cost: 800, desc: "在地下摔跤场练就的格斗术。利用敏捷戏耍大块头对手。那是锯骨机！", type: "skill"},
            {name: "号角日报工作证", color: "C", cost: 100, desc: "你可以自由进出报社，虽然老板很抠门，但这为你提供了合法的身份掩护。", type: "item"},
            {name: "本叔叔的教诲", color: "S", cost: 6000, desc: "“能力越大，责任越大”。这不仅是座右铭，更是精神力量。在绝境中给予你站起来的勇气。", type: "concept"},
            {name: "双重人格(幻听)", color: "D", cost: 200, desc: "诺曼·奥斯本的诅咒。镜子里的那个你会不断诱惑你作恶。意志力薄弱者会沦为傀儡。", type: "curse"},
            {name: "感恩节晚餐", color: "C", cost: 20, desc: "尴尬的晚餐。一滴血就能暴露你的身份。小心别被未来的岳父发现你是他的死敌。", type: "event"},
            {name: "缆车救援", color: "A", cost: 3000, desc: "一手拉住满载孩子的缆车，一手拉住玛丽·简。这是对力量和意志的极限考验。", type: "event"},
            {name: "贫穷", color: "E", cost: 0, desc: "蜘蛛侠永远缺钱。房租、学费、修战衣... 这是一个超级英雄最真实的烦恼。", type: "curse"}
        ]
    },
    {
        name: "583.(漫威)蜘蛛侠2",
        desc: "公认的最佳超英电影之一。彼得在生活与英雄身份之间挣扎，甚至失去了超能力。章鱼博士登场，带来了核聚变的威胁与悲剧。",
        boss: "章鱼博士(奥托·奥克塔维斯)",
        identities: [
            { name: "披萨送餐员", items: "小绵羊摩托, 8个披萨(超时了)" },
            { name: "奥克塔维斯实验室助手", items: "护目镜, 珍贵的氚元素" },
            { name: "失去能力的彼得", items: "近视眼镜, 摔疼的背" },
            { name: "银行柜员", items: "被章鱼触手吓晕, 金币" },
            { name: "高架列车乘客", items: "举起蜘蛛侠, 保守秘密" }
        ],
        talents: [
            {name: "机械触手(四只)", color: "SS", cost: 15000, desc: "奥托博士的发明。拥有独立的人工智能，力量足以撕开银行金库，反应速度能抓住苍蝇。一旦失控会操纵宿主。", type: "item"},
            {name: "人造太阳(聚变反应堆)", color: "SSS", cost: 30000, desc: "珍贵的氚元素引发的核聚变。能提供无限能源，但也能像太阳一样吞噬整个纽约。只有河水能冷却它。", type: "item"},
            {name: "停下列车", color: "SSS", cost: 20000, desc: "蜘蛛侠的高光时刻。用肉身和无数根蛛丝强行拉停失控的高速列车。力量与意志的巅峰展现。力竭后晕倒。", type: "event"},
            {name: "能力丧失(心理)", color: "D", cost: 300, desc: "因为压力和自我怀疑，你的超能力消失了。你会变回近视眼，爬墙掉下来，射不出丝。必须找回初心才能恢复。", type: "curse"},
            {name: "披萨时间(Pizza Time)", color: "C", cost: 50, desc: "迟到就免单。你拥有高超的摩托车驾驶技巧，能在车流中穿梭。但老板还是会炒你鱿鱼。", type: "skill"},
            {name: "触手AI抑制芯片", color: "A", cost: 2000, desc: "位于脖子后面的芯片。如果损坏，触手的人工智能将反客为主，控制你的大脑。保持理智的关键。", type: "item"},
            {name: "玛丽·简的婚礼", color: "B", cost: 1000, desc: "抢婚现场。她穿着婚纱跑来找你。这意味着她接受了你的双重身份，爱情的力量让你满血复活。", type: "event"},
            {name: "英雄归来", color: "S", cost: 5000, desc: "当你从高楼跃下，重新射出蛛丝的那一刻。全属性大幅提升，BGM响起，无人能挡。", type: "status"},
            {name: "银行金库门", color: "A", cost: 1500, desc: "章鱼博士随手扔过来的巨大金属门。如果你能接住或躲开，说明你反应不错。", type: "item"},
            {name: "氚元素", color: "S", cost: 4000, desc: "极其稀有的同位素。只有一点点就能引发巨大的能量反应。是所有反派梦寐以求的能源核心。", type: "item"},
            {name: "每日号角头条", color: "C", cost: 100, desc: "詹姆森老板虽然讨厌蜘蛛侠，但他给的钱能让你交房租。甚至能拿到蜘蛛侠战衣挂在墙上。", type: "item"},
            {name: "善良的市民", color: "A", cost: 3000, desc: "当你在列车上晕倒，纽约市民把你抬进去，并承诺为你保守秘密。这是英雄最大的回报。", type: "event"},
            {name: "租房危机", color: "E", cost: 10, desc: "那个总是要房租的房东迪特科维奇先生。还有那扇永远修不好的门。生活太难了。", type: "curse"},
            {name: "码头决战", color: "B", cost: 2000, desc: "废弃码头的仓库。充满了易燃物和重型机械。适合触手发挥地形优势。", type: "event"},
            {name: "自我牺牲(奥托)", color: "S", cost: 6000, desc: "“我不会死得像个怪物”。奥托在最后时刻夺回控制权，带着反应堆沉入河底。救赎。", type: "status"}
        ]
    },
    {
        name: "584.(漫威)蜘蛛侠3",
        desc: "三部曲终章。沙人、毒液、小绿魔三个反派同台。彼得被黑色战衣（毒液）寄生，性格黑化。原谅与救赎是最后的主题。",
        boss: "毒液(埃迪·布洛克), 沙人(弗林特·马克)",
        identities: [
            { name: "膨胀的彼得", items: "黑色西装, 奇怪的舞步" },
            { name: "沙人实验体", items: "粒子加速器, 变成沙子" },
            { name: "小绿魔(哈利)", items: "新式滑板, 毁容的脸" },
            { name: "毒液宿主(埃迪)", items: "伪造的照片, 尖牙利齿" },
            { name: "爵士乐俱乐部保安", items: "看到彼得跳舞想打人, 门票" }
        ],
        talents: [
            {name: "毒液战衣(黑)", color: "SS", cost: 14000, desc: "共生体附身。力量、速度大幅提升，性格变得暴躁、自大。能做出平时做不到的攻击动作。自带眼线。", type: "item"},
            {name: "沙化身体", color: "SSS", cost: 25000, desc: "身体完全由沙子构成。物理攻击无效，能巨大化，变成沙尘暴，或者把手变成锤子。只要有一粒沙就能复活。", type: "body"},
            {name: "小绿魔装备", color: "S", cost: 6000, desc: "哈利改良的装备。更轻便的滑雪板式飞行器，电子刀，南瓜雷。机动性极强。", type: "item"},
            {name: "霸凌马奎尔(舞步)", color: "C", cost: 50, desc: "一段极其自信（尴尬）的街头独舞。能对周围人造成精神伤害，魅力值在自信和油腻之间反复横跳。", type: "skill"},
            {name: "声波弱点(敲钟)", color: "A", cost: 2000, desc: "利用教堂的钟声迫使共生体脱离。这是摆脱黑化彼得的关键，也是毒液诞生的时刻。", type: "event"},
            {name: "兄弟联手", color: "S", cost: 8000, desc: "哈利放下仇恨，与彼得并肩作战。两人配合默契，重现当年的友情。虽然代价是哈利的牺牲。", type: "status"},
            {name: "巨大的沙人", color: "SS", cost: 12000, desc: "沙人吸收了工地所有的沙子，变成哥斯拉大小的怪物。每一拳都能震碎大楼。", type: "body"},
            {name: "南瓜炸弹(解离)", color: "S", cost: 3000, desc: "能将人瞬间烧成骨架的炸弹。哈利最后用身体挡住了这一击，救了彼得。", type: "item"},
            {name: "原谅", color: "S", cost: 5000, desc: "彼得原谅了杀害本叔叔的真凶沙人。这种精神境界的提升比任何超能力都强大。沙人随风而逝。", type: "concept"},
            {name: "共生体触手", color: "A", cost: 4000, desc: "毒液埃迪能射出黑色的触手网，力量比普通蛛丝更大，能困住蜘蛛侠。", type: "skill"},
            {name: "毁容", color: "D", cost: 100, desc: "哈利被自己的炸弹炸伤半边脸。这加深了他的仇恨，也让他看起来更像个反派。", type: "curse"},
            {name: "格温·史黛西(花瓶)", color: "C", cost: 200, desc: "这个宇宙的格温只是个约会对象。她的出现主要是为了让玛丽·简吃醋。", type: "status"},
            {name: "法国餐厅求婚", color: "C", cost: 50, desc: "如果你能顺利把戒指送出去，就算你赢。通常会被服务员或者突发事件打断。", type: "event"},
            {name: "号角日报伪证", color: "D", cost: 50, desc: "埃迪伪造蜘蛛侠偷窃的照片。被彼得揭穿后身败名裂，这是他对彼得仇恨的根源。", type: "event"},
            {name: "钢管阵", color: "B", cost: 1000, desc: "建筑工地的钢管。彼得利用它们制造声波圈，困住了毒液。物理学除魔。", type: "item"}
        ]
    },
    {
        name: "585.(漫威)超凡蜘蛛侠1",
        desc: "重启版。彼得·帕克更像个现代高中生，滑板、科技宅。探寻父母失踪的真相。对抗蜥蜴博士。格温是唯一的真爱。",
        boss: "蜥蜴博士(柯蒂斯·康纳斯)",
        identities: [
            { name: "中城高中滑板少年", items: "滑板, 胶片相机" },
            { name: "奥斯本大厦访客", items: "偷来的胸牌, 跨物种遗传算法" },
            { name: "蜥蜴人受害者", items: "抓痕, 下水道地图" },
            { name: "纽约警局实习生(乔治·史黛西)", items: "霰弹枪, 对蒙面义警的偏见" },
            { name: "起重机操作员", items: "对讲机, 帮助蜘蛛侠" }
        ],
        talents: [
            {name: "机械蛛丝发射器", color: "A", cost: 3000, desc: "回归漫画设定。彼得自己研发的装置和蛛丝液。能射出高强度蛛丝，但有弹药限制，且可能故障。", type: "item"},
            {name: "蜥蜴血清", color: "S", cost: 6000, desc: "能让断肢重生，但也让人变成巨大的蜥蜴怪物。获得超强力量、鳞片防御和野兽本能。想把全人类都变蜥蜴。", type: "item"},
            {name: "跨物种遗传算法", color: "SS", cost: 10000, desc: "理查德·帕克的研究成果。能将动物基因完美融合到人体。只有帕克家族的血统能完美适配，其他人会死或变异。", type: "talent"},
            {name: "蜘蛛感应(微操)", color: "S", cost: 8000, desc: "加菲版的感应更敏锐，能辅助进行极其精细的操作，比如在几秒钟内接住掉落的几十个瓶子。", type: "talent"},
            {name: "生物电蛛丝", color: "B", cost: 1500, desc: "利用蛛丝传导震动，像蜘蛛网一样感知下水道里蜥蜴人的动向。侦查神技。", type: "skill"},
            {name: "加达西尔解毒剂", color: "A", cost: 2000, desc: "能中和蜥蜴血清的蓝色药剂。发射到云层中可以下“解药雨”，治愈全城的蜥蜴人。", type: "item"},
            {name: "嘴炮(嘲讽)", color: "C", cost: 100, desc: "加菲版彼得特别爱吐槽。在战斗中不断用语言攻击对手，能激怒敌人露出破绽。", type: "skill"},
            {name: "格温的智慧", color: "B", cost: 800, desc: "格温不是花瓶，她是学霸。能帮你合成解药，制定战术。是最完美的搭档。", type: "status"},
            {name: "乔治·史黛西的牺牲", color: "A", cost: 2500, desc: "警察局长为了救你而死。临终前让你承诺远离格温。这是一道沉重的枷锁。", type: "event"},
            {name: "起重机之路", color: "B", cost: 1000, desc: "纽约建筑工人为了报恩，调整起重机为你铺路。让你在受伤状态下也能荡到奥斯本大厦。", type: "event"},
            {name: "断尾重生", color: "B", cost: 1200, desc: "蜥蜴人的能力。即使尾巴被打断也能瞬间长出来，甚至能把断尾当武器扔出去。", type: "body"},
            {name: "篮球羞辱", color: "C", cost: 50, desc: "利用超能力在篮球场羞辱校霸闪电。虽然很爽，但有点不讲武德。", type: "event"},
            {name: "父母的公文包", color: "B", cost: 500, desc: "隐藏着帕克夫妇失踪真相的旧皮包。里面有关键的公式和眼镜。解开谜题的钥匙。", type: "item"},
            {name: "自制战衣(墨镜版)", color: "C", cost: 200, desc: "早期的战衣，用墨镜当眼罩。虽然简陋，但透气性可能不错。", type: "item"},
            {name: "承诺就是用来打破的", color: "C", cost: 10, desc: "虽然答应了局长远离格温，但... 这种承诺最好的归宿就是打破它。", type: "status"}
        ]
    },
    {
        name: "586.(漫威)超凡蜘蛛侠2",
        desc: "电光人、小绿魔、犀牛人。虽然反派众多，但核心是彼得与格温的爱情。钟楼的坠落是所有粉丝心中永远的痛。",
        boss: "电光人(麦克斯), 小绿魔(哈利·奥斯本)",
        identities: [
            { name: "奥斯本电网工程师", items: "生日蛋糕(没人理), 蓝色的皮肤" },
            { name: "牛津大学准留学生(格温)", items: "录取通知书, 英国国旗雨伞" },
            { name: "特种监狱囚犯", items: "犀牛机甲图纸, 疯狂" },
            { name: "绝症患者(哈利)", items: "遗传病, 对蜘蛛血的渴望" },
            { name: "时代广场路人", items: "被电击, 拍视频" }
        ],
        talents: [
            {name: "电能操纵(电光人)", color: "SS", cost: 18000, desc: "身体完全转化为纯能量。能吸收整个纽约的电力，飞行，瞬移，发射闪电。物理攻击几乎无效。", type: "body"},
            {name: "蜘蛛感应(子弹时间)", color: "SS", cost: 12000, desc: "极致的反应速度。在彼得眼中，时间几乎静止。能在大爆炸中同时救下所有的路人并接住飞出的导管。", type: "talent"},
            {name: "格温之死", color: "E", cost: 0, desc: "钟楼一战。蛛丝变成了手掌的形状，但还是晚了一步。那一刻的清脆响声，是彼得一生的噩梦。无法挽回的悲剧。", type: "curse"},
            {name: "蜘蛛毒液(哈利版)", color: "S", cost: 7000, desc: "注射了蜘蛛毒液的哈利。虽然治好了病，但导致身体变异，精神疯狂。成为了小绿魔。", type: "body"},
            {name: "犀牛机甲", color: "A", cost: 4000, desc: "重型俄式机甲。火力凶猛，装甲厚重，像一辆行走的坦克。虽然笨重，但破坏力十足。", type: "item"},
            {name: "过载充电", color: "S", cost: 5000, desc: "击败电光人的方法。利用电网过载，让他吸收超过负荷的电量，导致身体崩溃消散。", type: "skill"},
            {name: "磁化蛛丝发射器", color: "A", cost: 2500, desc: "为了对抗电光人，彼得给发射器做了绝缘和磁化处理。科技侧的针对性升级。", type: "item"},
            {name: "罗斯福地铁站", color: "B", cost: 1000, desc: "帕克父亲的秘密实验室。隐藏在地铁站深处。在这里揭开了帕克家族血统的秘密。", type: "item"},
            {name: "我是无名小卒", color: "D", cost: 100, desc: "麦克斯的执念。他想被看见，想被需要。这种心理被忽视后转化为极端的恨意。", type: "curse"},
            {name: "英伦梦", color: "C", cost: 50, desc: "彼得决定陪格温去英国。放弃纽约蜘蛛侠的身份？不，他想两全其美。可惜没机会了。", type: "status"},
            {name: "特拉维斯克里文疯人院", color: "B", cost: 800, desc: "关押哈利和电光人的地方。也是邪恶六人组计划的诞生地。", type: "item"},
            {name: "带电的栏杆", color: "A", cost: 1500, desc: "电光人能演奏《Itsy Bitsy Spider》的旋律。利用电击产生音乐，这是他的主场BGM。", type: "skill"},
            {name: "复出", color: "S", cost: 3000, desc: "在消沉了五个月后，听着格温的演讲录音，彼得重新穿上战衣对抗犀牛人。生活还要继续。", type: "status"},
            {name: "龙虾餐", color: "C", cost: 20, desc: "格温父亲葬礼后的聚餐。尴尬又温馨。斯坦·李客串的地方。", type: "event"},
            {name: "绿魔滑翔机(超凡版)", color: "A", cost: 3500, desc: "更具生物感的滑翔机。能快速飞行，是哈利带走格温的罪魁祸首。", type: "item"}
        ]
    },
    {
        name: "587.(漫威)刀锋战士1",
        desc: "R级超英鼻祖。埃里克·布鲁克斯是半人半吸血鬼的“日行者”。猎杀吸血鬼，对抗想要召唤血神的狄肯·弗罗斯特。黑色皮衣，墨镜，武士刀。",
        boss: "狄肯·弗罗斯特(血神形态)",
        identities: [
            { name: "吸血鬼猎人", items: "银制武士刀, 墨镜" },
            { name: "血液学家(卡伦)", items: "抗凝血剂, 蒜精喷雾" },
            { name: "纯血统吸血鬼长老", items: "古老的特权, 被弗罗斯特做成祭品" },
            { name: "弗罗斯特的跟班", items: "防晒霜, 纹身" },
            { name: "被咬的倒霉蛋", items: "正在变异的伤口, 恐惧" }
        ],
        talents: [
            {name: "日行者体质", color: "SS", cost: 12000, desc: "拥有吸血鬼的所有优点（力量、速度、再生），却没有缺点（不怕阳光、大蒜、银）。唯一弱点是嗜血。", type: "exclusive"},
            {name: "血神降临(La Magra)", color: "SSS", cost: 25000, desc: "弗罗斯特利用十二长老献祭后获得的终极力量。不死之身，断肢瞬间重组，速度快到肉眼不可见，免疫抗凝血剂。", type: "body"},
            {name: "银制武士刀", color: "A", cost: 3000, desc: "刀锋的标志性武器。经过特殊处理的钛合金刀身，镀银。砍吸血鬼像切豆腐，触碰把柄会有防盗刺。", type: "item"},
            {name: "血清注射器", color: "B", cost: 500, desc: "刀锋需要定期注射血清来抑制嗜血欲望。如果断药，他会变得虚弱并最终失控。", type: "item"},
            {name: "抗凝血剂爆炸", color: "S", cost: 5000, desc: "卡伦发明的武器。注射进吸血鬼体内会让其血液沸腾并爆炸。是对付血神的最后手段（过量注射）。", type: "item"},
            {name: "惠斯勒的工坊", color: "A", cost: 2000, desc: "老搭档惠斯勒的基地。拥有各种魔改武器：紫外线灯、银弹、大蒜精喷雾。猎人的军火库。", type: "item"},
            {name: "吸血鬼格斗术", color: "A", cost: 2500, desc: "结合了多种武术的杀人技。招招致命，专门针对吸血鬼的弱点（心脏、头颅）。", type: "skill"},
            {name: "紫外线手电筒", color: "B", cost: 800, desc: "便携式太阳。照射吸血鬼能造成严重烧伤甚至灰飞烟灭。清杂兵神器。", type: "item"},
            {name: "吸血鬼狂欢派对", color: "C", cost: 100, desc: "天花板喷洒鲜血的夜店。吸血鬼的觅食场所。进入这里意味着你不是猎人就是食物。", type: "event"},
            {name: "纯血统议会", color: "B", cost: 1000, desc: "统治吸血鬼世界的古老家族。他们看不起像弗罗斯特这样的混血（被咬变异的）。这种傲慢导致了他们的灭亡。", type: "status"},
            {name: "母亲的真相", color: "D", cost: 200, desc: "刀锋以为母亲死了，其实她变成了吸血鬼，还是弗罗斯特的情人。这是巨大的心理打击。", type: "event"},
            {name: "回旋镖刀片", color: "B", cost: 600, desc: "刀锋的暗器。扔出去能切断喉咙并飞回手中。耍帅必备。", type: "item"},
            {name: "炸弹背心", color: "A", cost: 1500, desc: "把银桩做成炸弹穿在身上。被包围时的自爆手段，或者用来炸开出路。", type: "item"},
            {name: "古代预言书", color: "C", cost: 500, desc: "记载了召唤血神仪式的古书。只有用纯血统长老的血才能解开封印。", type: "item"},
            {name: "酷", color: "S", cost: 1000, desc: "无论情况多危急，都要保持面无表情，戴着墨镜。这种气场能让敌人未战先怯。", type: "status"}
        ]
    },
              {
        name: "588.(漫威)旺达幻视",
        desc: "情景喜剧的表象下是无尽的悲伤。旺达用混沌魔法绑架了整个小镇，复活了幻视，创造了双胞胎。这里是魔法与现实的边界。",
        boss: "阿加莎·哈克尼斯, 那个“快银”(拉尔夫)",
        identities: [
            { name: "西景镇居民", items: "黑白电视机, 无法控制的微笑" },
            { name: "天剑局特工", items: "六边形辐射检测仪, 这种马戏团帐篷" },
            { name: "情景喜剧群演", items: "50年代的衣服, 剧本" },
            { name: "阿加莎的女巫团", items: "紫色符文, 枯萎的手" },
            { name: "双胞胎的朋友", items: "游戏机, 突然长大的惊讶" }
        ],
        talents: [
            {name: "混沌魔法(绯红女巫)", color: "SSS", cost: 45000, desc: "修改概率，重写现实。你可以凭空创造生命（双胞胎），改变物体形态，甚至毁灭世界。这是无需学习的本能魔法。", type: "magic"},
            {name: "六边形结界(The Hex)", color: "SS", cost: 15000, desc: "巨大的现实扭曲力场。进入其中的人会被改写记忆和外貌以符合情景喜剧的年代设定。绝对的控制权。", type: "magic"},
            {name: "白幻视", color: "SS", cost: 12000, desc: "天剑局用幻视尸体改造的杀人兵器。拥有幻视的所有机能（密度控制、激光），但没有情感和记忆。", type: "item"},
            {name: "黑暗神书(Darkhold)", color: "SSS", cost: 30000, desc: "被诅咒的魔法书。记载了所有黑魔法。阅读它会获得巨大的力量，但灵魂会被腐蚀，指尖变黑。", type: "item"},
            {name: "阿加莎的符文", color: "S", cost: 8000, desc: "“在既定空间内，只有施法者能使用魔法”。利用符文封锁区域，让其他女巫变成凡人。法师内战神技。", type: "magic"},
            {name: "光谱能量(莫妮卡)", color: "A", cost: 4000, desc: "强行穿过结界获得的超能力。能感知电磁波谱，身体能转化为能量形态，免疫子弹。", type: "body"},
            {name: "极速(伪)", color: "B", cost: 1000, desc: "拉尔夫被施法后获得了类似快银的速度。虽然是假的，但跑起来确实很快。这是个残酷的玩笑。", type: "skill"},
            {name: "心灵控制(全镇)", color: "S", cost: 6000, desc: "同时控制数千人的思想和行动。让他们扮演你剧本里的角色。但受害者会感到窒息般的痛苦。", type: "magic"},
            {name: "情景喜剧笑声", color: "C", cost: 50, desc: "无论你说什么，背景里都会传来罐头笑声。能缓解尴尬，也能让恐怖氛围加倍。", type: "curse"},
            {name: "万圣节戏服", color: "C", cost: 100, desc: "旺达和幻视的经典漫画造型。虽然看起来廉价，但在结界里这是最强的战斗形态。", type: "item"},
            {name: "忒修斯之船", color: "B", cost: 500, desc: "哲学辩论技能。通过逻辑悖论让敌对AI（如白幻视）陷入死机或觉醒。知识就是力量。", type: "skill"},
            {name: "心碎", color: "D", cost: 200, desc: "旺达力量的源泉是悲伤。你越痛苦，力量越强。但这会让你失去理智。", type: "curse"},
            {name: "防弹围裙", color: "C", cost: 80, desc: "50年代主妇的标配。在西景镇，它真的能挡子弹（如果剧情需要的话）。", type: "item"},
            {name: "魔法吸取", color: "S", cost: 7000, desc: "阿加莎的能力。当其他女巫攻击你时，你可以吸取她们的魔力为己用。", type: "skill"},
            {name: "再见了，亲爱的", color: "S", cost: 5000, desc: "主动解除结界。牺牲虚构的爱人和孩子，换取自由和觉醒。这是成神的代价。", type: "concept"}
        ]
    },
    {
        name: "589.(漫威)猎鹰与冬兵",
        desc: "美国队长走了，盾牌该归谁？这是一个关于遗产、种族和难民的政治故事。新美队约翰·沃克失控，碎旗者追求无国界。",
        boss: "卡莉·摩根索(碎旗者), 约翰·沃克(黑化美队)",
        identities: [
            { name: "全球回归委员会(GRC)士兵", items: "防暴盾, 驱逐令" },
            { name: "马德里坡保镖", items: "霓虹灯下的墨镜, 冲锋枪" },
            { name: "碎旗者成员", items: "红色手印面具, 偷来的疫苗" },
            { name: "瓦坎达朵拉亲卫队", items: "振金长矛, 极度蔑视眼神" },
            { name: "路易斯安那渔民", items: "修不好的船, 贷款被拒信" }
        ],
        talents: [
            {name: "美国队长盾牌", color: "SS", cost: 9000, desc: "那个圆盾。它不仅是武器，更是符号。拿着它，你就是美国的象征。但如果你配不上它，它会变得很沉重。", type: "item"},
            {name: "振金翅膀(新美队)", color: "SS", cost: 8500, desc: "瓦坎达为山姆定制的装备。红白蓝配色，坚不可摧，带有推进器和红翼无人机。飞行的堡垒。", type: "item"},
            {name: "超级士兵血清(纳格尔版)", color: "S", cost: 6000, desc: "改良版血清，不需要肌肉变大就能获得超级力量。碎旗者全员注射。让普通人能踢飞卡车。", type: "body"},
            {name: "美国密探盾牌", color: "A", cost: 2000, desc: "约翰·沃克自己敲出来的盾牌。虽然不是振金，但也是钢铁意志的证明。虽然很快就被打烂了。", type: "item"},
            {name: "机械臂(振金)", color: "S", cost: 5000, desc: "巴基的新手臂。瓦坎达制造，甚至有可拆卸功能（防暴走）。力量巨大且灵活。", type: "item"},
            {name: "红翼无人机", color: "A", cost: 1500, desc: "猎鹰的战术助手。能侦查、射击、甚至切割钢铁。虽然经常被反派徒手拆掉。", type: "item"},
            {name: "能力掮客的资源", color: "S", cost: 4000, desc: "莎伦·卡特在马德里坡建立的帝国。你可以买到卫星、血清、甚至美国政府的机密。", type: "status"},
            {name: "泽莫的舞步", color: "C", cost: 50, desc: "在夜店里尴尬又不失礼貌的摇摆。虽然没用，但能让你在反派圈子里混个脸熟。", type: "skill"},
            {name: "瓦坎达长矛术", color: "A", cost: 2500, desc: "朵拉亲卫队的武术。能用长矛卸掉冬兵的机械臂。技巧凌驾于力量之上。", type: "skill"},
            {name: "嘴遁(山姆)", color: "B", cost: 800, desc: "山姆的超能力是“做思想工作”。能通过演讲感化参议员和恐怖分子。虽然不一定有用，但很感人。", type: "skill"},
            {name: "带血的盾牌", color: "D", cost: 200, desc: "当你用盾牌当众杀人后，它就不再纯洁了。声望值暴跌，获得“暴徒”称号。", type: "curse"},
            {name: "猎鹰飞行服(旧)", color: "B", cost: 1000, desc: "被沃克扯坏的那套。虽然修修还能用，但在新时代的战斗中已经落伍了。", type: "item"},
            {name: "一无所有", color: "D", cost: 50, desc: "作为复仇者，你竟然贷不到款。现实的引力比灭霸还重。", type: "status"},
            {name: "以赛亚的血液", color: "A", cost: 3000, desc: "被遗忘的黑人超级士兵的血。蕴含着原始血清的力量，但也承载着历史的痛苦。", type: "item"},
            {name: "船只维修", color: "C", cost: 20, desc: "你是个熟练的机械师，能修好老旧的渔船。生活技能点满。", type: "skill"}
        ]
    },
    {
        name: "590.(漫威)洛基 第一季",
        desc: "为了光荣的使命！洛基偷走空间宝石后被时间变异管理局(TVA)逮捕。这是一场关于自由意志、时间循环和自我迷恋（字面意思）的冒险。",
        boss: "遗留之人(康), 艾里奥斯",
        identities: [
            { name: "TVA分析员", items: "制服, 只有一种口味的饮料" },
            { name: "时间犯(Variant)", items: "囚服, 脖子上的项圈" },
            { name: "虚空幸存者", items: "破烂的披风, 躲避云团" },
            { name: "罗克森超市避难者", items: "口香糖, 即将到来的风暴" },
            { name: "拉曼提斯星乘客", items: "富人车票, 毁灭的星球" }
        ],
        talents: [
            {name: "时间控制器(TempPad)", color: "SS", cost: 10000, desc: "TVA的神器。能开启金色的时间门，去往任何时间、任何地点。还能重置时间线。", type: "item"},
            {name: "裁剪杖", color: "S", cost: 5000, desc: "被击中者会被“裁剪”，从当前时间线抹除并送往虚空。一击必杀的近战武器。", type: "item"},
            {name: "经典洛基的幻术", color: "SS", cost: 12000, desc: "老洛基的能力。能制造出足以骗过吞噬万物怪兽的阿斯加德幻象。魔力极其庞大。", type: "magic"},
            {name: "附身魔法(希尔维)", color: "S", cost: 6000, desc: "通过触碰控制他人的心智。虽然需要肢体接触，但能获取记忆并操纵行为。", type: "magic"},
            {name: "时间小姐(Miss Minutes)", color: "A", cost: 3000, desc: "TVA的人工智能吉祥物。虽然看着可爱，但她知道所有秘密，且能操控TVA的系统。", type: "pet"},
            {name: "艾里奥斯(Alioth)", color: "SSS", cost: 20000, desc: "虚空中的风暴怪兽。能吞噬时间和物质。只有强大的附身魔法才能驯服它。", type: "monster"},
            {name: "神圣时间线剧本", color: "SSS", cost: 30000, desc: "遗留之人的剧本。上面写着过去、现在和未来发生的一切。拥有它，你就是全知全能的编剧。", type: "item"},
            {name: "无限宝石(镇纸)", color: "C", cost: 10, desc: "在TVA，无限宝石失去了魔力，被当成镇纸。这让你意识到TVA的力量凌驾于宝石之上。", type: "item"},
            {name: "时间项圈", color: "B", cost: 500, desc: "戴上它，你的时间流速被TVA控制。他们可以让你无限循环在被打脸的那一刻。", type: "curse"},
            {name: "鳄鱼洛基", color: "A", cost: 2000, desc: "一只戴着角冠的鳄鱼。虽然只会咬人，但它也是洛基。咬掉了洛基总统的手。", type: "pet"},
            {name: "光荣的使命", color: "C", cost: 50, desc: "你总是想要统治，但总是失败。这是一种诅咒，也是洛基成长的动力。", type: "concept"},
            {name: "双星相吸", color: "S", cost: 8000, desc: "当两个洛基相爱时，会产生巨大的分歧点事件。这种自恋的爱能打破末日的隐身规则。", type: "event"},
            {name: "时间重置器", color: "A", cost: 2500, desc: "用来修剪分支时间线的手雷。爆炸后会将时间回溯并抹除异常。TVA清洁工必备。", type: "item"},
            {name: "阿斯加德匕首", color: "B", cost: 600, desc: "洛基随时能变出来的匕首。虽然在TVA用不了魔法，但物理攻击依然有效。", type: "item"},
            {name: "水上摩托", color: "C", cost: 100, desc: "莫比乌斯的梦想。拥有一辆水上摩托，在90年代的音乐中驰骋。这是自由的象征。", type: "item"}
        ]
    },
    {
        name: "591.(漫威)无限可能：假如...？第一季",
        desc: "观察者注视着多元宇宙。如果佩吉·卡特打了血清？如果特查拉成了星爵？如果奥创赢了？无限的可能，无限的危机。",
        boss: "无限奥创, 丧尸旺达, 奇异博士(至尊)",
        identities: [
            { name: "多元宇宙守护者", items: "观察者的契约, 跨宇宙通讯器" },
            { name: "丧尸宇宙幸存者", items: "被咬了一口的蜘蛛侠, 斯科特·朗的头" },
            { name: "废土黑寡妇", items: "鹰眼的弓, 佐拉博士的U盘" },
            { name: "派对雷神的朋友", items: "纹身, 宿醉" },
            { name: "瓦坎达星际掠夺者", items: "指控者战锤(偷来的), 灭霸是小弟" }
        ],
        talents: [
            {name: "无限奥创装甲", color: "UR", cost: 100000, desc: "拥有六颗无限宝石的振金身体。能听到观察者的声音，能咬碎星系，能跨越多元宇宙。战力天花板。", type: "exclusive"},
            {name: "至尊奇异魔法", color: "SSS", cost: 50000, desc: "为了救女友吸收了无数维度的魔神。拥有吞噬一切的力量，甚至能毁灭并维持一个微型宇宙。", type: "magic"},
            {name: "卡特队长的盾牌", color: "SS", cost: 8000, desc: "印着英国国旗的振金盾。佩吉·卡特用它战斗时比史蒂夫更凶猛，甚至能切断触手怪。", type: "item"},
            {name: "星爵特查拉的魅力", color: "SSS", cost: 20000, desc: "嘴遁满级。能说服勇度不吃人，说服灭霸从良，说服收藏家女仆反水。宇宙和平靠他一张嘴。", type: "talent"},
            {name: "丧尸病毒(量子)", color: "S", cost: 5000, desc: "来自量子领域的病毒。感染速度极快，连超级英雄和灭霸都无法幸免。保留了超能力的丧尸。", type: "curse"},
            {name: "观察者之眼", color: "SSS", cost: 60000, desc: "全知全能的视角。能看到所有宇宙的过去未来。但受誓言限制，不能干涉（除非忍不住）。", type: "talent"},
            {name: "基尔蒙格的谋略", color: "A", cost: 3000, desc: "能设计出连环计，利用美军、瓦坎达和斯塔克，最终夺取黑豹之力和机甲。心机深沉。", type: "talent"},
            {name: "佐拉病毒(箭矢)", color: "S", cost: 4000, desc: "将佐拉博士的意识注入箭矢。射中奥创后，佐拉会从内部瓦解奥创的系统。黑客攻击的极致。", type: "item"},
            {name: "灭霸(好人版)", color: "S", cost: 6000, desc: "作为特查拉的小弟，这个灭霸虽然强壮，但喜欢讲道理，甚至觉得自己的响指计划有点激进。", type: "pet"},
            {name: "口袋宇宙", color: "SS", cost: 15000, desc: "至尊奇异制造的水晶球。里面封印着齐尔蒙格和佐拉奥创的大战。是一个永恒的监狱。", type: "item"},
            {name: "派对雷神体质", color: "A", cost: 2500, desc: "没有经历过挫折的雷神。力量强大但是个铁憨憨，能把地球变成星际夜店。", type: "body"},
            {name: "九头蛇践踏者", color: "S", cost: 5000, desc: "霍华德为史蒂夫制造的巨型机甲。虽然没有血清，但火力足以对抗九头蛇大军。", type: "item"},
            {name: "无限宝石粉碎机", color: "S", cost: 8000, desc: "卡魔拉的装置。理论上能销毁无限宝石，但在面对不同宇宙的宝石时可能不兼容。", type: "item"},
            {name: "斯科特·朗的头", color: "C", cost: 100, desc: "被放在罐子里的蚁人头。虽然身体没了，但嘴依然很贫。能提供笑话和部分科技支持。", type: "item"},
            {name: "绝对时间点", color: "D", cost: 500, desc: "无法改变的悲剧（如克里斯汀之死）。无论怎么尝试，结果都会发生。强行改变会导致宇宙崩溃。", type: "curse"}
        ]
    },
    {
        name: "592.(漫威)鹰眼",
        desc: "这只是一个想回家过圣诞节的退休老兵的故事。克林特·巴顿带着迷妹凯特·毕晓普，对抗运动服黑帮，并引出了幕后大佬金并。",
        boss: "金并(威尔逊·菲斯克), 艾科(玛雅·洛佩兹)",
        identities: [
            { name: "运动服黑帮成员", items: "红色运动服, 兄弟(Bro)口头禅" },
            { name: "百老汇音乐剧观众", items: "罗杰斯音乐剧门票, 尴尬" },
            { name: "凯特·毕晓普", items: "紫色的弓, 母亲的黑卡" },
            { name: "黑寡妇刺客(叶莲娜)", items: "电击寡妇蛰, 很多口袋的背心" },
            { name: "独眼披萨狗", items: "一块披萨, 极高的萌度" }
        ],
        talents: [
            {name: "皮姆粒子箭", color: "SS", cost: 8000, desc: "射中物体后将其巨大化或缩小。把一支普通箭变成巨型攻城槌，或者把警车变小。视觉效果满分。", type: "item"},
            {name: "浪人战衣(Ronin)", color: "S", cost: 5000, desc: "克林特黑化时期的装备。穿上它，你就是地下世界的死神。但也意味着被无数仇家追杀。", type: "item"},
            {name: "金并之力", color: "A", cost: 4000, desc: "虽然是凡人，但力量大到能徒手扯下车门，硬抗爆炸。加上防弹西装，简直是人形坦克。", type: "body"},
            {name: "特技射击", color: "A", cost: 2500, desc: "不用看就能射中目标。能利用反弹、抛物线击中死角的敌人。鹰眼的看家本领。", type: "skill"},
            {name: "叶莲娜的格斗术", color: "A", cost: 3000, desc: "黑寡妇级别的体术。动作干练狠辣，擅长利用周围环境。还有独特的落地姿势（虽然她吐槽过）。", type: "skill"},
            {name: "回声模仿", color: "B", cost: 1500, desc: "玛雅·洛佩兹的能力。能观察并完美模仿对手的动作。虽然剧里表现不多，但设定上很强。", type: "skill"},
            {name: "USB箭", color: "B", cost: 800, desc: "射入接口即可自动下载数据。黑客任务必备。比亲自去插U盘安全多了。", type: "item"},
            {name: "听力受损", color: "D", cost: 100, desc: "常年战斗的代价。你需要助听器才能听到声音。如果被打掉，你会陷入寂静，战斗力受损。", type: "curse"},
            {name: "披萨狗(Lucky)", color: "B", cost: 500, desc: "一只爱吃披萨的独眼金毛。能帮你发现敌人，还能卖萌降低敌人警惕。好孩子。", type: "pet"},
            {name: "麦克罗尼通心粉", color: "C", cost: 20, desc: "叶莲娜最爱的食物。如果你请她吃这个，也许她会晚一点杀你。", type: "item"},
            {name: "老式豪宅安保", color: "C", cost: 100, desc: "毕晓普家的安保系统。虽然有警报，但对超级英雄来说形同虚设。", type: "item"},
            {name: "剑术大师(杰克)", color: "B", cost: 600, desc: "那个拿剑的继父。剑术确实不错，能跟鹰眼过几招。但他其实是个好人（大概）。", type: "skill"},
            {name: "猫头鹰", color: "C", cost: 10, desc: "被缩小的卡车带走的猫头鹰。它现在有了巨大的食物来源。生态灾难？", type: "event"},
            {name: "冰袋", color: "C", cost: 5, desc: "战斗后必备。对于一身伤病的老兵来说，这是最好的慰藉。", type: "item"},
            {name: "最好的射手", color: "S", cost: 3500, desc: "克林特的认可。凯特·毕晓普继承了鹰眼的名号。师徒羁绊加成。", type: "status"}
        ]
    },
    {
        name: "593.(漫威)月光骑士",
        desc: "史蒂文、马克、杰克。三个身体，三种人格，一个埃及神。在精神分裂的混乱中，对抗企图复活阿米特的邪教徒。",
        boss: "亚瑟·哈罗, 审判之神阿米特",
        identities: [
            { name: "博物馆礼品店店员", items: "名牌(史蒂文), 金鱼" },
            { name: "国际雇佣兵", items: "护照(马克), 藏起来的手机" },
            { name: "孔苏的代行者", items: "月光法杖, 听得见神的声音" },
            { name: "阿米特的信徒", items: "天平纹身, 玻璃渣鞋子" },
            { name: "精神病院病患", items: "镇静剂, 芦苇原的幻觉" }
        ],
        talents: [
            {name: "月光骑士战衣(马克)", color: "SS", cost: 12000, desc: "木乃伊绷带自动缠绕生成的战衣。刀枪不入，拥有披风滑翔和月牙镖。战斗风格残暴直接。", type: "magic"},
            {name: "骑士先生战衣(史蒂文)", color: "S", cost: 8000, desc: "一套白色的西装。史蒂文召唤的版本。虽然格斗技巧不如马克，但更绅士，擅长用棍子。", type: "magic"},
            {name: "孔苏的复活", color: "SS", cost: 15000, desc: "只要孔苏还在，你就不会死。即使被枪杀，也能在月光下复活。这是神的契约。", type: "magic"},
            {name: "灵魂审判(阿米特)", color: "SS", cost: 10000, desc: "亚瑟·哈罗的能力。握住手就能看到你过去和未来的罪行。如果有罪，当场吸干生命。", type: "magic"},
            {name: "回旋天象", color: "S", cost: 6000, desc: "孔苏的神迹。将夜空倒转几千年，回到特定的星图。视觉效果震撼，但会惹怒众神。", type: "magic"},
            {name: "多重人格切换", color: "A", cost: 3000, desc: "在战斗中瞬间切换人格。马克负责打架，史蒂文负责解谜，杰克负责杀人。敌人根本摸不透。", type: "skill"},
            {name: "绯红圣甲虫", color: "A", cost: 5000, desc: "蕾拉获得的塔沃里特女神之力。拥有金色的金属翅膀和双剑。飞行的女武神。", type: "magic"},
            {name: "杰克·洛克利", color: "S", cost: 4000, desc: "第三人格。最残暴的存在。当你断片醒来发现满地尸体时，就是他干的。连孔苏都喜欢他。", type: "status"},
            {name: "精神病院", color: "C", cost: 500, desc: "这到底是现实还是幻觉？你被困在心理医生的诊室里。突破心魔才能回到现实。", type: "event"},
            {name: "河马女神", color: "B", cost: 1000, desc: "塔沃里特。冥界的引路人。虽然长得萌，但能帮你通过杜阿特（冥界）的审判。", type: "status"},
            {name: "乌沙布蒂雕像", color: "B", cost: 800, desc: "封印神明的石像。打破它就能释放神明。孔苏和阿米特都被封印过。", type: "item"},
            {name: "亚历山大之墓", color: "B", cost: 1200, desc: "阿米特的最后封印地。充满了古埃及机关和僵尸。探险家的终极目标。", type: "item"},
            {name: "玻璃渣", color: "D", cost: 50, desc: "亚瑟·哈罗把玻璃渣放进鞋子里行走。这种苦修让他意志坚定。你也可以试试，虽然很疼。", type: "curse"},
            {name: "牛排晚餐", color: "C", cost: 20, desc: "史蒂文约会失败的晚餐。展示了他的孤独。但后来他有了马克和蕾拉，不再孤单。", type: "event"},
            {name: "月亮", color: "S", cost: 2000, desc: "你的力量来源。在满月之夜，你的各项属性达到巅峰。", type: "environment"}
        ]
    },
    {
        name: "594.(漫威)惊奇少女",
        desc: "新泽西少女卡玛拉·汗的成长日记。迷妹变成了英雄。涉及印巴分治的历史创伤、精灵(Djinn)传说和量子手镯的秘密。",
        boss: "纳吉玛(隐秘族), 损害控制局(DODC)",
        identities: [
            { name: "复仇者粉丝", items: "惊奇队长Cos服, 粉丝频道账号" },
            { name: "新泽西高中生", items: "驾照考试失败单, 清真午餐" },
            { name: "隐秘族后裔", items: "努尔维度感知, 晶体武器" },
            { name: "损害控制局特工", items: "声波无人机, 拘捕令" },
            { name: "红色匕首成员", items: "红色围巾, 飞刀" }
        ],
        talents: [
            {name: "量子手镯", color: "SS", cost: 12000, desc: "卡玛拉祖母的遗物。能开启努尔维度，激发佩戴者体内的力量。是开启时空传送门的钥匙。", type: "item"},
            {name: "硬光构造", color: "A", cost: 5000, desc: "卡玛拉的能力。将光固化为晶体状的物质。可以制造踏板行走、巨大的拳头攻击或盾牌防御。", type: "skill"},
            {name: "变种人基因(突变)", color: "S", cost: 8000, desc: "手镯只是钥匙，力量来自卡玛拉自身的基因突变。这暗示了她是MCU主宇宙首批确认的变种人之一。", type: "body"},
            {name: "巨大化(Embiggen)", color: "A", cost: 4000, desc: "利用硬光包裹身体，让自己像蚁人一样变大。力量和防御倍增，能一拳打飞无人机。", type: "skill"},
            {name: "努尔维度通道", color: "S", cost: 6000, desc: "隐秘族渴望回家的路。打开它会吞噬地球的现实。极其危险的空间裂缝。", type: "magic"},
            {name: "晶体长矛", color: "B", cost: 1500, desc: "隐秘族利用维度能量制造的武器。虽然不如卡玛拉的硬光灵活，但杀伤力足够。", type: "item"},
            {name: "红色匕首格斗术", color: "B", cost: 1200, desc: "巴基斯坦守护者的武术。身法灵活，擅长使用飞刀和跑酷。适合巷战。", type: "skill"},
            {name: "家庭支援", color: "C", cost: 500, desc: "汗一家虽然唠叨，但在关键时刻是坚强的后盾。妈妈做的战衣，爸爸的鼓励。", type: "status"},
            {name: "损害控制局无人机", color: "B", cost: 2000, desc: "斯塔克工业的遗留技术。拥有声波炮和追踪功能。对付未成年的超能力者很有效。", type: "item"},
            {name: "时空穿越(祖母)", color: "S", cost: 5000, desc: "卡玛拉通过手镯穿越回1947年的印巴分治时期，救了自己的祖母。闭环的时间线。", type: "event"},
            {name: "惊奇队长的认可", color: "SS", cost: 3000, desc: "片尾彩蛋。如果你和惊奇队长互换了位置，说明你已经进入了宇宙级的叙事。", type: "event"},
            {name: "布鲁诺的小发明", color: "C", cost: 300, desc: "天才好友制造的各种小道具。虽然有时会爆炸，但偶尔能救命。", type: "item"},
            {name: "清真寺", color: "C", cost: 50, desc: "社区的中心。在这里你可以获得庇护，或者被穿鞋进礼拜堂的人气死。", type: "environment"},
            {name: "驾驶技术(不及格)", color: "E", cost: 10, desc: "你倒车撞了校长的车。在追车战中，最好还是让卡姆兰来开。", type: "curse"},
            {name: "名字的意义", color: "B", cost: 200, desc: "Kamal在乌尔都语中意为“完美/惊奇”。这是你代号的由来，也是自我认同的开始。", type: "concept"}
        ]
    },
    {
        name: "595.(漫威)女浩克",
        desc: "珍妮弗·沃尔特斯，绿巨人的表妹。一名专门处理超人类案件的律师。这里打破了第四面墙，充满了吐槽、客串和法律纠纷。",
        boss: "智能浩克王(HulkKing), 泰坦妮亚",
        identities: [
            { name: "GLK&H律所律师", items: "昂贵的西装, 堆积如山的卷宗" },
            { name: "变形后的女浩克", items: "撑破的高跟鞋, 绿色的大长腿" },
            { name: "憎恶的辩护律师", items: "和解协议, 冥想课传单" },
            { name: "智能浩克帮成员", items: "键盘, 仇女言论" },
            { name: "黄石公园瑜伽教练(憎恶)", items: "白袍, 七个灵魂伴侣" }
        ],
        talents: [
            {name: "打破第四面墙(K.E.V.I.N.)", color: "SSS", cost: 50000, desc: "直接爬出屏幕，去漫威影业办公室找编剧和AI机器人K.E.V.I.N.修改大结局。因果律级别的叙事控制。", type: "concept"},
            {name: "女浩克体质", color: "SS", cost: 12000, desc: "获得浩克的力量，但保留完整的理智和人格。不需要愤怒触发，随时变身。除了买衣服难，没缺点。", type: "body"},
            {name: "法律精通", color: "A", cost: 2000, desc: "你是顶级的超人类法律师。能帮王起诉魔法滥用，帮憎恶假释。在法庭上比在战场上更强。", type: "skill"},
            {name: "夜魔侠的浪漫", color: "S", cost: 3000, desc: "与马特·默多克的一夜情。不仅获得了法律上的盟友，还获得了一个能打的男朋友（虽然他要回纽约）。", type: "event"},
            {name: "憎恶(养生版)", color: "A", cost: 5000, desc: "布朗斯基现在是个心灵导师。虽然还能变身，但他更喜欢写俳句和开养生馆。", type: "pet"},
            {name: "泰坦妮亚的怪力", color: "A", cost: 4000, desc: "靠流量和怪力出名的网红。虽然打不过女浩克，但很烦人，而且会破坏你的婚礼。", type: "body"},
            {name: "王(Wong)", color: "S", cost: 6000, desc: "至尊法师是你的好朋友。他经常来找你处理法律问题（比如越狱）。能随时开传送门。", type: "status"},
            {name: "浩克血液", color: "S", cost: 8000, desc: "你的血能合成血清。反派想抢它，但你直接改剧本让他们抢不到。这就很灵性。", type: "item"},
            {name: "梅根·西·斯塔利安", color: "C", cost: 100, desc: "和说唱巨星一起跳电臀舞。虽然对战斗没帮助，但能气死屏幕前的黑粉。", type: "skill"},
            {name: "抑制器", color: "C", cost: 500, desc: "佩戴后无法变身。如果你在法庭上失控，就得戴这个。限制了你的战力。", type: "curse"},
            {name: "糟糕的约会", color: "C", cost: 50, desc: "作为珍妮弗没人理，作为女浩克万人迷。这对你的自尊心是个打击。", type: "status"},
            {name: "恶魔之子(Skaar)", color: "A", cost: 4000, desc: "浩克的儿子从萨卡星来了。虽然发型很奇怪，但他也是个浩克。战力潜力股。", type: "pet"},
            {name: "无敌浩克的特训", color: "B", cost: 1500, desc: "布鲁斯教你的控制技巧。虽然你上手就会，让他很受挫，但基础还是打牢了。", type: "skill"},
            {name: "智能浩克帮", color: "D", cost: 100, desc: "一群在暗网攻击你的喷子。虽然战斗力为5，但恶心人为100。", type: "curse"},
            {name: "版权法", color: "B", cost: 1000, desc: "泰坦妮亚抢注了“女浩克”商标。你必须在法庭上夺回自己的名字。这是一场名誉战。", type: "event"}
        ]
    },
    {
        name: "596.(漫威)洛基 第二季",
        desc: "时间线正在崩溃。洛基在过去、现在和未来之间穿梭。为了拯救TVA和朋友，他必须做出终极牺牲，成为故事之神。",
        boss: "时间隐力爆炸, 维克多·泰姆利",
        identities: [
            { name: "时间溜脱者", items: "不受控的传送, 痛苦的拉扯" },
            { name: "TVA工程师(OB的徒弟)", items: "时间隐力倍增器, 绝版手册" },
            { name: "麦当劳员工(希尔维)", items: "制服, 想要平静的生活" },
            { name: "1893年的发明家", items: "早期时间织布机原型, 骗术" },
            { name: "故事之神", items: "无数条时间线, 孤独的王座" }
        ],
        talents: [
            {name: "故事之神(God of Stories)", color: "UR", cost: 100000, desc: "洛基的终极形态。他摧毁了织布机，用神力抓住所有时间线，赋予它们生命。他成为了活体的世界树，守护多元宇宙。", type: "exclusive"},
            {name: "时间溜脱(掌控)", color: "SS", cost: 15000, desc: "洛基学会了控制溜脱。他可以随意回到任何时间点，重试无数次。这比时间宝石更强，因为TVA无法限制它。", type: "skill"},
            {name: "时间织布机", color: "SS", cost: 20000, desc: "将原生的时间能量编织成物理时间线的机器。如果不扩容，它会爆炸毁灭所有分支宇宙。", type: "item"},
            {name: "OB的工程学", color: "S", cost: 8000, desc: "老欧(O.B.)是TVA的技术大拿。写了TVA手册。拥有他的知识，你能修理任何时间设备。", type: "talent"},
            {name: "时间灵光提取器", color: "A", cost: 5000, desc: "能提取生物或物体的时间灵光。虽然看起来像个吸尘器，但它是拯救织布机的关键。", type: "item"},
            {name: "维克多·泰姆利的原型机", color: "B", cost: 3000, desc: "简陋但精妙的时间机器。康的变体在19世纪的发明。虽然会把人变成面条，但理论是正确的。", type: "item"},
            {name: "热巧克力", color: "C", cost: 20, desc: "在TVA崩溃前，大家喝一杯热巧克力。这是末日前的温情时刻。", type: "item"},
            {name: "百年孤独", color: "S", cost: 10000, desc: "洛基为了学会物理学，花了几个世纪反复重置时间。这种毅力和知识量让他超越了凡人。", type: "status"},
            {name: "魔法无效化", color: "B", cost: 2000, desc: "TVA的阻尼器。在这里魔法无效。但洛基最后成为了超越TVA机制的存在。", type: "curse"},
            {name: "酸橙派", color: "C", cost: 50, desc: "TVA餐厅唯一的甜点。虽然味道一般，但那是家的味道。", type: "item"},
            {name: "分钟小姐(黑化)", color: "S", cost: 6000, desc: "她爱上了康，并变得疯狂。能控制所有TVA设备杀人。恐怖的AI病娇。", type: "monster"},
            {name: "时间辐射", color: "A", cost: 4000, desc: "暴露在原生的时间能量下会加速老化至尘埃。只有神或者特殊的防护服能抵挡。", type: "environment"},
            {name: "谁是你的神", color: "C", cost: 100, desc: "洛基不再要求别人跪下，而是自己走上王座牺牲。这是真正的神性觉醒。", type: "concept"},
            {name: "重置棒", color: "B", cost: 1500, desc: "希尔维不想杀人，只想过平静生活。但当必须战斗时，她的双刀依然致命。", type: "item"},
            {name: "朋友", color: "S", cost: 5000, desc: "莫比乌斯、B-15、凯西、OB。洛基第一次为了朋友而战，而不是为了王位。", type: "status"}
        ]
    },
    {
        name: "597.(漫威)夜魔侠",
        desc: "地狱厨房的恶魔。马特·默多克白天是盲人律师，晚上是打击犯罪的义警。没有超能力光波，只有拳拳到肉的格斗和对正义的拷问。",
        boss: "金并(威尔逊·菲斯克), 靶眼, 手合会",
        identities: [
            { name: "盲人律师", items: "导盲杖, 红色墨镜" },
            { name: "蒙面义警(黑衣)", items: "黑色紧身衣, 泰拳绑带" },
            { name: "夜魔侠(红衣)", items: "红色防弹战衣, 短棍" },
            { name: "金并的黑帮打手", items: "西装, 很快就会被打断的骨头" },
            { name: "号角日报记者(本·尤里克)", items: "录音笔, 致命的独家新闻" }
        ],
        talents: [
            {name: "雷达感官", color: "SS", cost: 12000, desc: "超凡的听觉、嗅觉和触觉。能听到几个街区外的心跳，构建出360度的“火焰世界”图像。无法被偷袭，能测谎。", type: "talent"},
            {name: "金并的犯罪帝国", color: "S", cost: 8000, desc: "掌控警察、媒体、黑帮甚至FBI。只要他在，地狱厨房就在他的阴影下。这种权势比超能力更可怕。", type: "status"},
            {name: "走廊战神", color: "S", cost: 6000, desc: "在狭窄的走廊里，你的战斗力提升300%。即使精疲力尽，也能打倒几十个敌人。长镜头加持。", type: "skill"},
            {name: "比利棍(Billy Club)", color: "A", cost: 3000, desc: "夜魔侠的多功能武器。可变为盲杖、双截棍、投掷棍，甚至带有抓钩。攻防一体。", type: "item"},
            {name: "靶眼的投掷术", color: "S", cost: 7000, desc: "任何物品在他手里都是致命武器。纸牌、铅笔、回形针。百发百中，能利用反弹杀人。", type: "skill"},
            {name: "黑空(Black Sky)", color: "SS", cost: 10000, desc: "艾丽卡被手合会复活后的形态。被黑魔法强化的终极杀手，速度和力量超越常人。", type: "body"},
            {name: "尼尔森&默多克律所", color: "B", cost: 1000, desc: "一家只收水果派当律师费的穷律所。但这里有最好的律师和最真挚的友谊（弗吉和凯伦）。", type: "status"},
            {name: "棍叟的训练", color: "A", cost: 2500, desc: "严酷的忍者训练。学会控制感官，忍受痛苦，以及盲人剑术。虽然老头很讨厌，但本事是真的。", type: "skill"},
            {name: "防弹西装(金并)", color: "A", cost: 2000, desc: "菲斯克的白色西装内衬凯夫拉纤维。能抵挡刀刺和手枪。让他像一堵白色的墙。", type: "item"},
            {name: "天主教信仰", color: "C", cost: 100, desc: "马特的内心挣扎。作为律师信奉法律，作为义警信奉暴力，作为教徒信奉上帝。这种矛盾让他更强。", type: "concept"},
            {name: "手合会忍术", color: "B", cost: 1500, desc: "能隐藏心跳和体温，让夜魔侠的感官失效。还有死而复生的秘术（虽然会变疯）。", type: "magic"},
            {name: "冥想治愈", color: "B", cost: 800, desc: "通过冥想加速伤口愈合。对于每晚都被打得半死的马特来说，这是保命技能。", type: "skill"},
            {name: "艾丽卡的红围巾", color: "C", cost: 50, desc: "致命的诱惑。她是你最爱的人，也是最想杀你的人。相爱相杀的循环。", type: "status"},
            {name: "煎蛋卷", color: "C", cost: 20, desc: "菲斯克每天早上做的早餐。展现了他温柔的一面。如果你打扰他做早餐，后果很严重。", type: "item"},
            {name: "法律与秩序", color: "B", cost: 500, desc: "不仅仅是打拳。利用法律手段把金并送进监狱，才是真正的胜利。", type: "skill"}
        ]
    },
              {
        name: "598.(漫威)杰西卡·琼斯",
        desc: "私家侦探，酒鬼，PTSD患者。她拥有怪力，但内心破碎。对抗拥有精神控制能力的紫人。黑色电影风格的心理惊悚剧。",
        boss: "基尔格雷夫(紫人), 塞林格(连环杀手)",
        identities: [
            { name: "Alias侦探社社长", items: "破烂的门, 威士忌" },
            { name: "基尔格雷夫受害者", items: "精神创伤, 无法拒绝的命令" },
            { name: "电台主持人(崔西)", items: "麦克风, 想要超能力的执念" },
            { name: "IGH实验体", items: "增强体质, 暴怒副作用" },
            { name: "律师霍格斯合伙人", items: "离婚案卷宗, 算计" }
        ],
        talents: [
            {name: "精神控制(紫人)", color: "SS", cost: 15000, desc: "基尔格雷夫的能力。通过释放费洛蒙病毒，让听到他声音的人无条件服从命令。让他人自杀、杀人、静止。极其恐怖。", type: "magic"},
            {name: "怪力体质", color: "A", cost: 5000, desc: "杰西卡的能力。能徒手举起汽车，跳上几层楼高，一拳打穿墙壁。但身体防御力只是略高于常人，会被刀刺伤。", type: "body"},
            {name: "飞行(受控坠落)", color: "B", cost: 2000, desc: "杰西卡并不擅长飞，更像是在跳跃和滑翔。经常降落时砸坏东西。但这让她拥有极高的机动性。", type: "skill"},
            {name: "精神免疫", color: "S", cost: 8000, desc: "在经历了长期的折磨后，杰西卡对紫人的控制产生了抗体。她是唯一能违抗他命令的人。", type: "talent"},
            {name: "地狱猫身手(崔西)", color: "B", cost: 1500, desc: "崔西经过强化训练和后续的手术，获得了夜视能力和超越常人的敏捷。但性格也变得极端。", type: "body"},
            {name: "私家侦探技能", color: "B", cost: 800, desc: "跟踪、偷拍、撬锁、翻垃圾。虽然手段不光彩，但能挖出任何人最深层的秘密。", type: "skill"},
            {name: "威士忌", color: "C", cost: 50, desc: "杰西卡的生命之水。能麻痹痛苦，暂时压制PTSD。喝多了战斗力可能会下降，也可能上升（醉拳？）。", type: "item"},
            {name: "皮夹克", color: "C", cost: 100, desc: "杰西卡的标志性装束。不仅是衣服，更是她的铠甲，保护她不被世界伤害。", type: "item"},
            {name: "破碎的门", color: "C", cost: 20, desc: "Alias侦探社的门永远修不好。每次被修好，就会被新的麻烦（或杰西卡自己）打破。", type: "event"},
            {name: "IGH强化药剂", color: "A", cost: 3000, desc: "能赋予普通人怪力，但会导致情绪失控和暴力倾向。杰西卡力量的来源之一。", type: "item"},
            {name: "微表情观察", color: "B", cost: 1000, desc: "紫人能通过观察微表情判断对方是否在撒谎。这让他很难被欺骗。", type: "skill"},
            {name: "英雄综合症", color: "D", cost: 200, desc: "崔西渴望成为英雄，为此不惜伤害他人甚至杀死杰西卡的母亲。这是一种病态的执念。", type: "curse"},
            {name: "微笑", color: "C", cost: 10, desc: "基尔格雷夫让你微笑。你的脸部肌肉会僵硬地维持笑容几个小时，直到抽筋。", type: "curse"},
            {name: "绝缘室", color: "A", cost: 2500, desc: "为了关押紫人建造的密室。隔绝声音和病毒。是对抗他的唯一安全屋。", type: "item"},
            {name: "杀人凶手", color: "D", cost: 500, desc: "杰西卡被迫杀过人。这份罪恶感时刻折磨着她，让她拒绝成为超级英雄。", type: "curse"}
        ]
    },
    {
        name: "599.(漫威)卢克·凯奇",
        desc: "哈莱姆区的守护者。刀枪不入的皮肤，巨大的力量。充满黑人文化、嘻哈音乐和帮派斗争。Sweet Christmas!",
        boss: "响尾蛇(戴蒙德巴克), 巨腹蛇(布什马斯特)",
        identities: [
            { name: "理发店扫地工", items: "扫帚, 智慧的长者言论" },
            { name: "海门监狱实验体", items: "酸性池, 重获新生" },
            { name: "哈莱姆区英雄", items: "弹孔连帽衫, 咖啡" },
            { name: "帮派分子", items: "哈林天堂夜总会VIP卡, 犹大子弹" },
            { name: "警探(米丝蒂)", items: "机械臂(后期), 直觉" }
        ],
        talents: [
            {name: "钢铁之躯(皮肤)", color: "SS", cost: 10000, desc: "皮肤坚不可摧。子弹、刀具、甚至电锯都无法穿透。能硬抗火箭筒。唯一的弱点是内部器官。", type: "body"},
            {name: "怪力(卢克)", color: "S", cost: 6000, desc: "能轻松举起汽车，一拳打穿墙壁。虽然不如浩克，但在街头战斗中是碾压级的。", type: "body"},
            {name: "犹大子弹", color: "A", cost: 4000, desc: "汉默工业利用齐塔瑞金属制造的子弹。能钻进卢克的皮肤并在体内爆炸。是卢克的克星。", type: "item"},
            {name: "巨腹蛇草药", color: "S", cost: 5000, desc: "牙买加的神秘草药。能赋予布什马斯特超越卢克的力量和敏捷，但会严重损害身体。", type: "item"},
            {name: "响尾蛇战衣", color: "A", cost: 3500, desc: "能够吸收动能并反弹的动力装甲。让普通人也能与卢克肉搏。虽然造型有点像廉价Cosplay。", type: "item"},
            {name: "机械臂(米丝蒂)", color: "A", cost: 2500, desc: "斯塔克工业制造的义肢。力量巨大，甚至能捏碎金属。让米丝蒂成为强力打手。", type: "item"},
            {name: "哈莱姆的尊重", color: "B", cost: 1000, desc: "作为社区英雄，你拥有极高的声望。人们会保护你，为你提供情报。这是你的主场。", type: "status"},
            {name: "卡波耶拉战舞", color: "B", cost: 1200, desc: "布什马斯特的格斗风格。结合了舞蹈的踢技，灵活多变，正好克制笨重的卢克。", type: "skill"},
            {name: "酸性药浴", color: "S", cost: 3000, desc: "让卢克获得能力的实验装置。如果受了重伤（如中了犹大子弹），再次泡进去可能治愈（也可能死）。", type: "event"},
            {name: "连帽衫(满是洞)", color: "C", cost: 50, desc: "卢克的标志。虽然挡不住子弹，但代表了街头精神。买衣服是一笔大开销。", type: "item"},
            {name: "玛利亚·斯托克斯的政治手腕", color: "B", cost: 800, desc: "黑帮教母。能利用法律、媒体和政治手段玩弄英雄。比拳头更危险。", type: "skill"},
            {name: "脏话罐", color: "C", cost: 10, desc: "波普理发店的规矩。不准说脏话，否则罚款。这是哈莱姆仅存的净土。", type: "item"},
            {name: "咖啡", color: "C", cost: 20, desc: "“喝咖啡”在剧中是约炮的暗语。如果你被邀请上去喝咖啡，祝你好运。", type: "status"},
            {name: "理发店", color: "B", cost: 500, desc: "中立区。在这里大家只谈论篮球和生活，不打架。是情报交换中心。", type: "environment"},
            {name: "甜蜜的圣诞节", color: "C", cost: 5, desc: "卢克的口头禅。当你看到不可思议的事情时，请大声喊出来。", type: "skill"}
        ]
    },
    {
        name: "600.(漫威)铁拳",
        desc: "丹尼·兰德，昆仑的守护者，不朽铁拳。虽然剧集评价一般，但铁拳的力量是实打实的。武术、气、企业斗争。",
        boss: "博徒(手合会), 达沃斯(钢蛇)",
        identities: [
            { name: "兰德集团继承人", items: "亿万家产, 光脚" },
            { name: "昆仑武僧", items: "僧袍, 对现代社会的无知" },
            { name: "手合会学院学生", items: "武士刀, 洗脑" },
            { name: "道场教练(科琳·温)", items: "木刀, 正义感" },
            { name: "精神病院病人", items: "被认为是妄想症, 束缚带" }
        ],
        talents: [
            {name: "铁拳之力", color: "SS", cost: 12000, desc: "将“气”集中在拳头上，发出金光。无坚不摧，能打穿防弹门，震飞汽车。还可以用来治疗。", type: "magic"},
            {name: "气", color: "S", cost: 6000, desc: "生命能量。可以用来强化身体、感知周围、治愈伤口。是昆仑武学的核心。", type: "magic"},
            {name: "昆仑武术", color: "A", cost: 3000, desc: "在昆仑苦练15年的格斗术。虽然剧里打得像跳舞，但设定上是顶尖高手。", type: "skill"},
            {name: "科琳的剑术", color: "A", cost: 2500, desc: "科琳·温是真正的剑术大师。拿着武士刀的她比空手的铁拳更危险。她是“龙之女”。", type: "skill"},
            {name: "钢蛇拳(红拳)", color: "S", cost: 7000, desc: "达沃斯夺取铁拳之力后变异出的红拳。杀伤力更强，带有腐蚀性。不需要冥想就能发动。", type: "magic"},
            {name: "兰德集团股份", color: "S", cost: 5000, desc: "你是亿万富翁。可以用钱解决很多问题（比如买下整栋楼）。虽然丹尼经常不管公司。", type: "status"},
            {name: "寿老之心", color: "SS", cost: 10000, desc: "不朽之龙寿老的力量源泉。击败它才能获得铁拳之力。龙骨也是手合会追求的长生药。", type: "item"},
            {name: "手合会复活术", color: "A", cost: 4000, desc: "利用龙骨复活死者。但复活后会失去部分灵魂，变得越来越疯狂和邪恶。", type: "magic"},
            {name: "我是不朽铁拳", color: "C", cost: 50, desc: "你每集都要自我介绍一遍：“我是丹尼·兰德，不朽铁拳...”。这会让敌人（和观众）感到厌烦。", type: "curse"},
            {name: "真气枪", color: "A", cost: 3500, desc: "奥森·兰德（前代铁拳）的技巧。将气注入双枪射击。子弹能转弯，威力巨大。枪斗术。", type: "skill"},
            {name: "白虎护身符", color: "B", cost: 1000, desc: "能召唤分身或增强力量的神秘护符。虽然剧里没怎么展开，但潜力很大。", type: "item"},
            {name: "赤脚", color: "C", cost: 20, desc: "丹尼喜欢光脚走路。在满是玻璃渣的纽约街头，这需要勇气（和厚脚皮）。", type: "status"},
            {name: "梅查姆家族的阴谋", color: "B", cost: 800, desc: "商业斗争比武术更险恶。被合伙人陷害、下毒、送进精神病院。商场如战场。", type: "event"},
            {name: "龙骨汤", color: "S", cost: 5000, desc: "喝了能长生不老，治愈百病。手合会为此不惜摧毁纽约。", type: "item"},
            {name: "昆仑的消失", color: "B", cost: 2000, desc: "昆仑每15年出现一次。如果你错过了回家的路，就得在地球流浪15年。", type: "event"}
        ]
    },
    {
        name: "601.(漫威)捍卫者联盟",
        desc: "街头复联集结！夜魔侠、杰西卡、卢克、铁拳。对抗手合会的终极阴谋。为了拯救纽约，他们必须放下成见，并肩作战。",
        boss: "黑空(艾丽卡), 手合会五指",
        identities: [
            { name: "中餐馆聚餐者", items: "饺子, 尴尬的沉默" },
            { name: "米德兰圈金融公司员工", items: "掩盖龙骨挖掘的报表, 恐惧" },
            { name: "手合会忍者", items: "红衣, 无限复活(炮灰)" },
            { name: "纽约警局警探", items: "对四个义警的头疼, 加班" },
            { name: "被绑架的亲友团", items: "卡伦、马尔科姆、克莱尔等, 人质" }
        ],
        talents: [
            {name: "捍卫者集结", color: "SS", cost: 12000, desc: "四人联手。卢克当坦，铁拳输出，夜魔侠控场，杰西卡游走。虽然配合生疏，但互补性极强。", type: "status"},
            {name: "龙骨挖掘场", color: "S", cost: 8000, desc: "位于纽约地下的巨大龙骨化石。手合会挖掘它会导致纽约地震甚至坍塌。决战之地。", type: "environment"},
            {name: "黑空艾丽卡", color: "SS", cost: 10000, desc: "彻底觉醒的黑空。单挑四位捍卫者不落下风。速度快到能躲避铁拳，力量能踢飞卢克。", type: "body"},
            {name: "铁拳破门", color: "S", cost: 5000, desc: "只有铁拳能打破封印龙骨的墙壁。这也是手合会抓丹尼的原因。钥匙也是武器。", type: "skill"},
            {name: "走廊大战(四人版)", color: "A", cost: 4000, desc: "经典的走廊战升级版。四个人在狭窄空间里配合杀敌。爽快感倍增。", type: "event"},
            {name: "克莱尔·坦普尔", color: "A", cost: 2000, desc: "夜护。连接四位英雄的纽带。能治疗所有人的伤，还能提供战术建议。最强辅助。", type: "status"},
            {name: "C4炸药", color: "S", cost: 3000, desc: "为了埋葬手合会和龙骨，马特决定炸毁整栋大楼。同归于尽的战术。", type: "item"},
            {name: "手合会五指", color: "B", cost: 1500, desc: "手合会的五个首领。虽然活了很久，但除了亚历山德拉和高夫人，其他几个有点弱。", type: "status"},
            {name: "电梯嘴炮", color: "C", cost: 50, desc: "在去打BOSS的电梯里，杰西卡吐槽铁拳的紧身衣。这是团队磨合的必经之路。", type: "event"},
            {name: "中餐馆", color: "B", cost: 500, desc: "捍卫者们的临时基地。老板娘也是个狠人。在这里制定了最后的计划。", type: "environment"},
            {name: "马特的牺牲", color: "S", cost: 6000, desc: "为了唤醒艾丽卡，马特选择留在即将爆炸的洞穴里。英雄的悲壮落幕（虽然没死透）。", type: "event"},
            {name: "气的使用权", color: "A", cost: 3500, desc: "高夫人也能使用气。能一掌把杰西卡打飞。证明气不是铁拳的专利。", type: "magic"},
            {name: "断臂", color: "B", cost: 1000, desc: "米丝蒂为了救克莱尔被砍断了手臂。这为她换上机械臂做了铺垫。", type: "event"},
            {name: "纽约警局的围剿", color: "C", cost: 200, desc: "警察不分青红皂白地围捕义警。你们不仅要打坏人，还要躲警察。", type: "curse"},
            {name: "史蒂克之死", color: "B", cost: 800, desc: "老头子终于领便当了。被艾丽卡所杀。他的死让马特失去了导师。", type: "event"}
        ]
    },
    {
        name: "602.(漫威)惩罚者",
        desc: "弗兰克·卡斯特。前海军陆战队队员。全家被杀。他没有超能力，只有枪、战术和无尽的怒火。复仇是唯一的正义。",
        boss: "拼图(比利·鲁索), 威廉·罗林斯(橙剂)",
        identities: [
            { name: "建筑工地工人", items: "大锤, 沉默" },
            { name: "海军陆战队特种兵", items: "狙击枪, 坎大哈的回忆" },
            { name: "惩罚者", items: "骷髅头防弹衣, 军火库" },
            { name: "国土安全部探员(马达尼)", items: "徽章, 对真相的执着" },
            { name: "黑客(微芯片)", items: "无人机, 三明治" }
        ],
        talents: [
            {name: "战术大师", color: "SS", cost: 10000, desc: "精通所有单兵战术、陷阱布置、潜行暗杀。只要给他准备时间，他能一个人歼灭一支军队。", type: "talent"},
            {name: "武器精通", color: "S", cost: 8000, desc: "从手枪到加特林，从刀具到火箭筒。任何武器在他手里都能发挥最大威力。行走的军火库。", type: "skill"},
            {name: "痛觉耐受", color: "SS", cost: 9000, desc: "弗兰克能忍受常人无法想象的痛苦。中枪、骨折、被拷打，他依然能站起来反杀。意志力锁血。", type: "body"},
            {name: "骷髅头防弹衣", color: "A", cost: 3000, desc: "喷涂着白色骷髅头的战术背心。不仅防弹，更是死亡的象征。敌人看到它就会恐惧。", type: "item"},
            {name: "拼图的毁容", color: "A", cost: 2000, desc: "比利·鲁索被弗兰克在旋转木马的玻璃上磨烂了脸。这让他精神崩溃，变成了“拼图”。", type: "event"},
            {name: "微芯片的黑客技术", color: "A", cost: 4000, desc: "大卫·利伯曼。能黑进NSA、CIA的系统。为弗兰克提供情报支援和无人机侦查。", type: "skill"},
            {name: "战地医疗", color: "B", cost: 1000, desc: "自己取子弹，用订书机缝伤口。久病成医，只要不死就能治。", type: "skill"},
            {name: "坎大哈的噩梦", color: "D", cost: 200, desc: "战争罪行的回忆时刻折磨着你。这是弗兰克复仇的根源，也是他的心魔。", type: "curse"},
            {name: "战斗车(Battle Van)", color: "B", cost: 1500, desc: "改装过的黑色货车。里面装满了武器、通讯设备和医疗包。移动基地。", type: "item"},
            {name: "旋转木马决战", color: "S", cost: 5000, desc: "家人死去的地方，也是复仇终结的地方。充满了悲剧色彩的血腥决斗。", type: "event"},
            {name: "一击必杀", color: "S", cost: 6000, desc: "惩罚者不留活口。爆头是他的仁慈。这种高效的杀戮方式让他在超英中独树一帜。", type: "skill"},
            {name: "吉他藏刀", color: "C", cost: 100, desc: "在吉他里藏一把刀。看似流浪歌手，实则致命杀手。", type: "item"},
            {name: "橙剂", color: "B", cost: 800, desc: "CIA的非法行动代号。利用海洛因尸体运毒。揭开这个黑幕是第一季的主线。", type: "event"},
            {name: "健身房肉搏", color: "A", cost: 2500, desc: "在举重房里利用器械杀人。杠铃片、哑铃都成了凶器。暴力美学。", type: "skill"},
            {name: "唯一的幸存者", color: "S", cost: 7000, desc: "全队都死了，只有你活着。这份愧疚让你变成了惩罚者。你不再是弗兰克，你是复仇的化身。", type: "concept"}
        ]
    },
    {
        name: "603.(漫威)恶灵骑士",
        desc: "尼古拉斯·凯奇版。强尼·布雷兹为了救父亲与墨菲斯托交易，成为恶灵骑士。燃烧的骷髅头，地狱摩托，审判之眼。把灵魂烧成灰烬！",
        boss: "巫心魔(黑心), 墨菲斯托",
        identities: [
            { name: "特技摩托车手", items: "哈雷摩托, 粉丝的欢呼" },
            { name: "恶灵骑士", items: "地狱火锁链, 燃烧的皮衣" },
            { name: "守墓人(卡特·史雷)", items: "铁锹, 最后的契约" },
            { name: "墨菲斯托的赏金猎人", items: "契约书, 无法违抗的命令" },
            { name: "被审判的罪人", items: "燃烧的灵魂, 忏悔" }
        ],
        talents: [
            {name: "恶灵骑士体质", color: "SS", cost: 15000, desc: "复仇之灵附体。不死之身，免疫所有物理伤害（除了圣器）。力量巨大，能举起直升机。", type: "body"},
            {name: "审判之眼(Penance Stare)", color: "SSS", cost: 30000, desc: "直视恶人的眼睛，让他们一次性体验过去施加给别人的所有痛苦。灵魂层面的秒杀技。对没有灵魂的人无效。", type: "magic"},
            {name: "地狱火操纵", color: "SS", cost: 12000, desc: "召唤来自地狱的火焰。不烧肉体，专烧灵魂。能附魔任何载具和武器（如挖掘机、锁链）。", type: "magic"},
            {name: "地狱摩托", color: "S", cost: 8000, desc: "被地狱火附魔的哈雷。轮子燃烧，能垂直爬墙，在水面行驶。召唤即来，极速狂飙。", type: "item"},
            {name: "地狱锁链", color: "A", cost: 5000, desc: "无限延长的燃烧铁链。能像鞭子一样抽打，也能捆绑敌人。配合地狱火威力倍增。", type: "item"},
            {name: "圣凡冈萨契约", color: "SSS", cost: 25000, desc: "拥有千个堕落灵魂的契约。吞噬它能获得名为“群魔(Legion)”的力量，统治人间。巫心魔的目标。", type: "item"},
            {name: "卡特·史雷的骑行", color: "S", cost: 6000, desc: "老一代恶灵骑士（骑马）与新一代（骑摩托）并肩驰骋。影史最酷的镜头之一。", type: "event"},
            {name: "元素恶魔", color: "B", cost: 2000, desc: "巫心魔的手下：风、土、水。物理攻击无效，必须用环境杀（如烧干水魔）或地狱火解决。", type: "monster"},
            {name: "阳光变身", color: "C", cost: 500, desc: "在第一部中，强尼只能在晚上变身。白天是凡人。这是一个巨大的弱点。", type: "curse"},
            {name: "父亲的癌症", color: "B", cost: 800, desc: "为了治好父亲的癌症，强尼签了契约。结果父亲第二天死于车祸。恶魔的诈骗。", type: "event"},
            {name: "猴面包树下的初恋", color: "C", cost: 50, desc: "罗克珊。强尼为了保护她而远离她。经典的英雄悲剧爱情。", type: "status"},
            {name: "霰弹枪(地狱火版)", color: "A", cost: 3500, desc: "强尼拿起卡特的霰弹枪，注入地狱火。一枪轰碎水魔。万物皆可附魔。", type: "skill"},
            {name: "吃豆豆(糖果)", color: "C", cost: 10, desc: "强尼喜欢吃这种彩色糖果。也是他在变身前安抚情绪的方式。反差萌。", type: "item"},
            {name: "复仇之灵的疯狂", color: "D", cost: 300, desc: "骑士不仅仅是力量，更是诅咒。它渴望复仇，有时会甚至不受宿主控制。", type: "curse"},
            {name: "打破契约", color: "S", cost: 10000, desc: "结局时，强尼拒绝交还力量给墨菲斯托。他决定留着这份诅咒，用来惩罚恶魔。自由意志的胜利。", type: "concept"}
        ]
    },
              {
        name: "604.(原创)东方玄幻-万灵古族御兽界",
        desc: "一个万物皆有灵，家族为核心的御兽世界。在这里，血脉决定命运，家族掌控资源。强大的古族供奉着传说中的圣兽，而弱小的旁系只能契约蛇虫鼠蚁。",
        boss: "古族老祖(叶/萧/林), 圣兽·吞天犼, 禁区之主·九幽雀, 域外邪灵王",
        identities: [
            { name: "没落旁系子弟", items: "一枚黯淡的家族令牌, 一只病恹恹的杂毛灵狐" },
            { name: "家族兽栏杂役", items: "一把铲屎用的灵木铲, 一身带着腥臭味的麻布衣" },
            { name: "被退婚的天才(曾经)", items: "一封被撕碎的婚书, 经脉受损的身体" },
            { name: "古族私生子", items: "一块只有一半的玉佩, 母亲留下的染血遗书" },
            { name: "家族死士预备役", items: "一把淬毒的匕首, 随时准备自爆的灵纹咒印" },
            { name: "炼丹房烧火童子", items: "满脸的黑灰, 一本偷藏的残缺控火诀" },
            { name: "外门执事", items: "一本记满黑账的账本, 一根打人很疼的教鞭" }
        ],
        talents: [
            {name: "天煞孤星", color: "E", cost: 50, desc: "你身边的人和宠兽都会莫名倒霉甚至暴毙，注定孤独一生，难以建立羁绊。", type: "exclusive"},
            {name: "灵觉迟钝", color: "D", cost: 100, desc: "你对灵气的感知极差，契约御兽的成功率只有常人的十分之一。", type: "exclusive"},
            {name: "兽见愁", color: "D", cost: 120, desc: "不知为何，大部分御兽看到你都会产生厌恶感，好感度极难提升。", type: "exclusive"},
            {name: "经脉淤塞", color: "E", cost: 20, desc: "天生经脉堵塞，修炼御兽功法速度极慢，几乎不可能突破学徒级。", type: "exclusive"},
            {name: "家族弃子", color: "D", cost: 150, desc: "你被家族除名，没有任何资源支持，甚至会被家族执法队追杀。", type: "exclusive"},
            {name: "基础御兽术", color: "C", cost: 150, desc: "掌握最基础的契约手印，能够勉强契约一只E级潜力的御兽。", type: "exclusive"},
            {name: "灵草辨识", color: "C", cost: 180, desc: "你能认出野外常见的灵草，避免在给御兽喂食时把毒草当成补药。", type: "exclusive"},
            {name: "初级兽医", color: "C", cost: 200, desc: "懂得简单的包扎和草药配比，能处理御兽的外伤和常见疾病。", type: "exclusive"},
            {name: "身强体壮", color: "C", cost: 160, desc: "比一般人强壮一些，能扛得住低级御兽的一击而不死。", type: "exclusive"},
            {name: "微弱灵感", color: "C", cost: 190, desc: "偶尔能感应到附近有野生御兽出没，适合做斥候。", type: "exclusive"},
            {name: "亲和力", color: "B", cost: 300, desc: "你的笑容很有感染力，野生御兽对你的初始警戒心会降低。", type: "exclusive"},
            {name: "家族藏书阁通行证", color: "B", cost: 400, desc: "你拥有进入家族藏书阁外层的权限，可以学习黄阶下品的御兽技。", type: "exclusive"},
            {name: "小有资产", color: "B", cost: 500, desc: "开局自带100块下品灵石，足够购买一只不错的幼年御兽。", type: "exclusive"},
            {name: "炼体小成", color: "B", cost: 450, desc: "肉身经过打磨，可以配合御兽进行简单的协同作战。", type: "exclusive"},
            {name: "灵兽食谱", color: "B", cost: 350, desc: "掌握一种特殊的灵兽食物制作方法，长期喂养可微弱提升御兽潜力。", type: "exclusive"},
            {name: "鹰眼", color: "B", cost: 320, desc: "视力极佳，能看清千米之外的动静，适合指挥飞行御兽。", type: "exclusive"},
            {name: "陷阱精通", color: "B", cost: 280, desc: "擅长布置针对野兽的陷阱，捕捉幼崽的成功率提升。", type: "exclusive"},
            {name: "坚韧意志", color: "B", cost: 380, desc: "在面对高等级御兽的威压时，你比常人更能保持冷静。", type: "exclusive"},
            {name: "家族旁系血脉", color: "B", cost: 420, desc: "虽然血脉稀薄，但至少能让你在家族领地内获得基本的庇护。", type: "exclusive"},
            {name: "初级灵力护盾", color: "B", cost: 480, desc: "能释放一个持续3秒的微弱护盾，抵挡一次致命伤害。", type: "exclusive"},
            {name: "火系亲和", color: "A", cost: 800, desc: "天生亲近火元素，契约火系御兽时，御兽的成长速度提升20%。", type: "exclusive"},
            {name: "兽语者(残)", color: "A", cost: 950, desc: "能听懂部分御兽的情绪表达，虽然不能完全对话，但能大致理解意图。", type: "exclusive"},
            {name: "家族嫡系身份", color: "A", cost: 1500, desc: "出生即在罗马。每月可领取家族供奉的资源，拥有护道者暗中保护。", type: "exclusive"},
            {name: "变异灵眸", color: "A", cost: 1200, desc: "双眼能看穿御兽的等级和弱点，战斗时能精准指挥。", type: "exclusive"},
            {name: "伴生灵物", color: "A", cost: 1800, desc: "出生时伴生一件黄阶上品灵器，可增幅御兽的攻击力。", type: "exclusive"},
            {name: "过目不忘", color: "A", cost: 700, desc: "任何御兽功法看一遍就能记住，修炼效率极高。", type: "exclusive"},
            {name: "战斗直觉", color: "A", cost: 1100, desc: "天生的战斗天才，能在混乱的御兽战场中瞬间找到最佳战术。", type: "exclusive"},
            {name: "灵力漩涡", color: "A", cost: 1300, desc: "修炼时周围灵气自动汇聚，回复灵力的速度是常人的三倍。", type: "exclusive"},
            {name: "契约强化", color: "A", cost: 1400, desc: "你的契约空间比常人稳固，能额外契约一只御兽。", type: "exclusive"},
            {name: "古方炼丹师", color: "A", cost: 1600, desc: "掌握失传的丹方，能炼制提升御兽血脉纯度的丹药。", type: "exclusive"},
            {name: "返祖血脉", color: "S", cost: 3500, desc: "体内流淌着家族初代老祖的血液，有极低概率觉醒家族传承神通。", type: "exclusive"},
            {name: "通灵之心", color: "S", cost: 4000, desc: "任何御兽在见到你的第一眼就会产生好感，几乎不存在背叛的可能。", type: "exclusive"},
            {name: "多重契约", color: "S", cost: 5000, desc: "打破灵魂限制，你的契约位是同阶御兽师的两倍，一人成军。", type: "exclusive"},
            {name: "元素之体", color: "S", cost: 4500, desc: "肉身元素化，可以免疫50%的物理伤害，并大幅增幅对应属性御兽。", type: "exclusive"},
            {name: "魂印掠夺", color: "S", cost: 6000, desc: "邪道禁术。杀死其他御兽师后，可强行掠夺其一只御兽并抹去原主印记。", type: "exclusive"},
            {name: "空间行者", color: "S", cost: 5500, desc: "拥有极其稀有的空间天赋，可契约空间系御兽，并掌握短距离瞬移。", type: "exclusive"},
            {name: "进化之手", color: "S", cost: 7000, desc: "你的灵力具有特殊活性，触摸御兽可加速其进化过程，甚至诱导良性变异。", type: "exclusive"},
            {name: "古兽残魂", color: "S", cost: 6500, desc: "识海中寄宿着一只上古凶兽的残魂，关键时刻可借用其力量，但有被夺舍风险。", type: "exclusive"},
            {name: "天生阵法师", color: "S", cost: 4800, desc: "挥手成阵，能在战斗中瞬间刻画增幅法阵或困兽阵。", type: "exclusive"},
            {name: "不死之身(伪)", color: "S", cost: 8000, desc: "只要本命御兽存活，你受到的致命伤都会转移到御兽身上（御兽：听我说谢谢你）。", type: "exclusive"},
            {name: "圣兽转世", color: "SS", cost: 9500, desc: "你不是人，你是传说中的圣兽重修成人。天生压制万兽，修炼无瓶颈。", type: "exclusive"},
            {name: "万妖瞳", color: "SS", cost: 8800, desc: "一眼万年。可强行控制低于自身等级的任何妖兽，甚至短时间控制同级神兽。", type: "exclusive"},
            {name: "山海经图录", color: "SS", cost: 9000, desc: "脑海中自带上古神兽图录，知晓所有神兽的合成公式和进化路线。", type: "exclusive"},
            {name: "气运之子", color: "SS", cost: 9999, desc: "走路捡神器，摔跤遇神兽。天道私生子，逢凶化吉，遇难成祥。", type: "exclusive"},
            {name: "祖龙精血", color: "SS", cost: 9200, desc: "融合了一滴祖龙精血，肉身堪比神兽，可化身半龙人形态，万法不侵。", type: "exclusive"},
            {name: "万灵主宰", color: "SSS", cost: 30000, desc: "【唯一】你是万灵的主宰。所有生物（包括神兽）在面对你时必须通过意志检定，否则将无条件臣服。你可以随意修改契约规则，甚至赋予死物灵智。", type: "exclusive"},
            {name: "位面之胎", color: "SSS", cost: 45000, desc: "【唯一】你融合了本世界的位面核心。在这个世界内，你即是神。你可以调动整个世界的力量镇压敌人，灵力无穷无尽。", type: "exclusive"},
            {name: "概念级·进化", color: "SSS", cost: 50000, desc: "【唯一】你的御兽没有上限。你可以将不同物种的优点强制融合（如给蚂蚁融合巨龙的力量），创造出超越法则的怪物。", type: "exclusive"},
            {name: "因果律·绝对命中", color: "SSS", cost: 38000, desc: "【唯一】你和你的御兽发动的攻击，在因果层面上‘必定命中’。无视闪避、无视防御、无视空间距离。", type: "exclusive"},
            {name: "时空回溯", color: "SSS", cost: 60000, desc: "【唯一】掌握时间法则。当你的御兽死亡或你死亡时，可将时间回溯到战斗开始前。每日限一次。", type: "exclusive"}
        ]
    },
    {
        name: "605.(原创)末法武侠-残道江湖界",
        desc: "仙路断绝，灵气枯竭。曾经的修仙大能纷纷陨落或陷入沉睡。如今是凡人武学的巅峰时代，但江湖中仍流传着关于‘仙’的只言片语。这是一个充满血腥、阴谋与绝望的硬核江湖。",
        boss: "武林盟主·独孤败天, 魔教教主·东方无道, 隐世老怪·枯木道人(筑基期残存), 皇宫大内总管",
        identities: [
            { name: "破庙乞丐", items: "一根打狗棒, 一个破碗, 一身生疮的烂肉" },
            { name: "落第书生", items: "一把折扇, 一本读了一半的圣贤书, 满腹牢骚" },
            { name: "镖局趟子手", items: "一把朴刀, 一面破旧的镖旗, 一双磨穿的草鞋" },
            { name: "青楼乐师", items: "一把琵琶, 一把藏在琴中的细剑, 一段不堪回首的往事" },
            { name: "山贼喽啰", items: "一把生锈的砍刀, 一袋抢来的干粮, 随时会被官府砍头" },
            { name: "流亡皇子", items: "一块代表身份的玉佩(惹祸根源), 一身被血染黑的锦衣" },
            { name: "少林弃徒", items: "一串佛珠, 一本偷出来的入门拳谱, 一颗凡心" }
        ],
        talents: [
            {name: "先天残疾", color: "E", cost: 10, desc: "缺胳膊少腿，在这个弱肉强食的江湖，你就是待宰的羔羊。", type: "exclusive"},
            {name: "肺痨鬼", color: "E", cost: 30, desc: "身患绝症，走几步就咳血，寿命不足三年。", type: "exclusive"},
            {name: "路痴", color: "D", cost: 80, desc: "在这个没有导航的世界，你永远找不到去往各大门派的路。", type: "exclusive"},
            {name: "晕血", color: "D", cost: 90, desc: "见到血就会昏倒，这在江湖中简直是致命的笑话。", type: "exclusive"},
            {name: "仇家满天下", color: "E", cost: 5, desc: "你的脸长得像前任魔教教主，黑白两道都想杀你。", type: "exclusive"},
            {name: "粗通拳脚", color: "C", cost: 120, desc: "学过几套庄稼把式，打两三个普通流氓不在话下。", type: "exclusive"},
            {name: "皮糙肉厚", color: "C", cost: 150, desc: "抗击打能力强，挨顿揍睡一觉就好，适合练硬功。", type: "exclusive"},
            {name: "飞毛腿", color: "C", cost: 180, desc: "打不过跑得过，逃跑速度一流，保命神技。", type: "exclusive"},
            {name: "妙手空空", color: "C", cost: 160, desc: "手指灵活，擅长偷窃和开锁，饿不死的手艺。", type: "exclusive"},
            {name: "识文断字", color: "C", cost: 140, desc: "能看懂武功秘籍，在这个文盲遍地的江湖算是个文化人。", type: "exclusive"},
            {name: "根骨清奇", color: "B", cost: 350, desc: "也就是俗话说的练武奇才，修炼内功速度比常人快一倍。", type: "exclusive"},
            {name: "百毒不侵(初)", color: "B", cost: 400, desc: "对蒙汗药、软筋散等下三滥毒药有抗性，行走江湖更安全。", type: "exclusive"},
            {name: "暗器精通", color: "B", cost: 380, desc: "无论石子还是树叶，在你手中都能成为杀人利器。", type: "exclusive"},
            {name: "闻香识药", color: "B", cost: 320, desc: "能分辨草药和毒药，甚至能根据气味追踪敌人。", type: "exclusive"},
            {name: "易容术", color: "B", cost: 450, desc: "行走江湖，马甲很重要。能改变容貌，躲避追杀。", type: "exclusive"},
            {name: "听风辨位", color: "B", cost: 420, desc: "哪怕双目失明，也能靠听觉判断敌人方位，夜战无敌。", type: "exclusive"},
            {name: "酒豪", color: "B", cost: 250, desc: "千杯不醉。喝得越多，某些特殊功法威力越大（如醉拳）。", type: "exclusive"},
            {name: "驯马高手", color: "B", cost: 280, desc: "能驯服烈马，在这个交通靠走的世界，有好马等于多条命。", type: "exclusive"},
            {name: "铁匠传人", color: "B", cost: 300, desc: "懂得锻造和修补兵器，能让你的武器时刻保持最佳状态。", type: "exclusive"},
            {name: "冷血", color: "B", cost: 360, desc: "杀人时心率不会波动，不会手软，天生的杀手胚子。", type: "exclusive"},
            {name: "天生神力", color: "A", cost: 900, desc: "双臂有千斤之力，手撕虎豹，力举千钧，一力降十会。", type: "exclusive"},
            {name: "剑心通明", color: "A", cost: 1200, desc: "对剑道有超乎常人的领悟，任何剑法看一遍就能掌握精髓。", type: "exclusive"},
            {name: "九阳之体", color: "A", cost: 1500, desc: "体内阳气极盛，修炼至刚至阳的内功事半功倍，百毒难侵。", type: "exclusive"},
            {name: "九阴绝脉", color: "A", cost: 1500, desc: "体内阴气极重，活不过20岁，但修炼阴寒武功威力无穷。", type: "exclusive"},
            {name: "左右互搏", color: "A", cost: 1100, desc: "心分二用，双手可同时使出不同的武功，战力翻倍。", type: "exclusive"},
            {name: "吸星体质", color: "A", cost: 1800, desc: "丹田异于常人，可以强行吸纳他人的内力转化为己用，但有走火入魔风险。", type: "exclusive"},
            {name: "金刚不坏", color: "A", cost: 1600, desc: "外功极致，刀枪不入，水火不侵，站着让人打都打不动。", type: "exclusive"},
            {name: "天魔音", color: "A", cost: 1300, desc: "声音自带魅惑或杀伤力，能用琴音或长啸震碎敌人心脉。", type: "exclusive"},
            {name: "神行百变", color: "A", cost: 1000, desc: "轻功绝顶，身法诡异莫测，踏雪无痕，渡江如平地。", type: "exclusive"},
            {name: "名门之后", color: "A", cost: 1400, desc: "你是某大宗门的嫡传弟子，开局自带上乘武学和神兵利器。", type: "exclusive"},
            {name: "武道通神", color: "S", cost: 4000, desc: "打破了凡人的极限，以武入道。你的内力开始液化，接触到了修仙的门槛。", type: "exclusive"},
            {name: "残缺灵根", color: "S", cost: 5000, desc: "末法时代唯一的希望。你拥有残缺的灵根，可以感知稀薄的灵气，修习残存的仙法。", type: "exclusive"},
            {name: "剑意雏形", color: "S", cost: 3500, desc: "领悟了剑意，草木竹石皆可为剑，无剑胜有剑。", type: "exclusive"},
            {name: "长生诀", color: "S", cost: 6000, desc: "一本养生奇书。虽无杀伐之力，但能让你回气速度极快，且寿命悠长。", type: "exclusive"},
            {name: "天眼通", color: "S", cost: 4500, desc: "眉心天眼开启，能看破一切虚妄、幻术、伪装，直视本源。", type: "exclusive"},
            {name: "杀神降临", color: "S", cost: 5500, desc: "每杀一人，积攒一分煞气。煞气爆发时，战力翻倍，神鬼皆惊。", type: "exclusive"},
            {name: "不死印法", color: "S", cost: 5800, desc: "能够将敌人的死气转化为生气，在战斗中无限续航，越战越强。", type: "exclusive"},
            {name: "万剑归宗", color: "S", cost: 6500, desc: "可操控周身千米内的所有剑器，化作剑河，摧枯拉朽。", type: "exclusive"},
            {name: "破碎虚空(伪)", color: "S", cost: 7000, desc: "攻击力达到世界临界点，能短暂撕裂空间，造成无法防御的伤害。", type: "exclusive"},
            {name: "蛊王宿主", color: "S", cost: 5200, desc: "以身为盅，体内养着一只万蛊之王。百毒不侵，且能操控天下毒虫。", type: "exclusive"},
            {name: "修仙者遗物", color: "SS", cost: 9000, desc: "你获得了一枚还有灵气的储物戒指，里面有筑基期修士的全部身家（飞剑、丹药、符箓）。降维打击。", type: "exclusive"},
            {name: "魔尊转世", color: "SS", cost: 8500, desc: "你是上古魔尊的一缕残魂转世。自带魔道至高功法，杀伐果断，视苍生为蝼蚁。", type: "exclusive"},
            {name: "天道酬勤", color: "SS", cost: 8000, desc: "你的努力必定有回报。练拳一万次，必定突破。没有瓶颈，只要肝，就能无敌。", type: "exclusive"},
            {name: "预知未来", color: "SS", cost: 9500, desc: "你能看到未来三秒发生的画面。在高手对决中，这三秒就是绝对的胜利。", type: "exclusive"},
            {name: "系统拥有者", color: "SS", cost: 9900, desc: "虽然是低配版系统，但能通过杀敌获取经验值升级武功。数据化身体，不受致命伤影响。", type: "exclusive"},
            {name: "末法终结者", color: "SSS", cost: 35000, desc: "【唯一】你是灵气复苏的源头。你所在之处，灵气浓度飙升。你可以重启修仙大世，成为新时代的道祖。", type: "exclusive"},
            {name: "一剑开天门", color: "SSS", cost: 40000, desc: "【唯一】攻击力极致。只要你出剑，天门亦可开，仙人亦可斩。无视任何防御、规则、因果。", type: "exclusive"},
            {name: "言出法随", color: "SSS", cost: 45000, desc: "【唯一】儒道至圣。你说要有光，便有了光。你说敌人死了，他便死了。消耗寿命为代价修改现实。", type: "exclusive"},
            {name: "吞噬天地", color: "SSS", cost: 50000, desc: "【唯一】北冥神功的终极版。不仅吸人内力，连天地灵气、日月精华、甚至世界本源都能吞噬。", type: "exclusive"},
            {name: "无限复活", color: "SSS", cost: 60000, desc: "【唯一】你被世界诅咒，无法真正死亡。每次死亡后原地满血复活，并且对杀死你的手段产生绝对抗性。", type: "exclusive"}
        ]
    },
