        function setInitialPoints(val) { initialPoints = parseInt(val) || 0; playerPoints = initialPoints; updatePlayerPoints(playerPoints); }
        function updatePlayerPoints(value) { playerPoints = parseInt(value) || 0; document.getElementById(''player-points-display'').innerText = playerPoints; applyShopFilters(); }
        function renderShop() {
            const list = document.getElementById(''shop-list''); 
            if(!list) return;
            list.innerHTML = ''''; 
            let allTalents = [...commonTalents]; 
            worldDB.forEach(w => allTalents = allTalents.concat(w.talents));
            document.getElementById(''total-talents-count'').innerText = allTalents.length;
            allTalents.sort((a, b) => a.cost - b.cost).forEach((t, index) => {
                const div = document.createElement(''div''); div.className = `rarity-${t.color}`; div.style.padding = ''5px''; div.style.borderBottom = ''1px solid #333''; div.style.cursor = ''pointer''; 
                div.dataset.cost = t.cost;
                const worldName = t.type === ''exclusive'' %s (worldDB.find(w=>w.talents.includes(t))%s.name.toLowerCase() || ''%s%s'') : ''通用'';
                div.dataset.name = t.name.toLowerCase(); div.dataset.world = worldName;
                div.innerHTML = `<span style="color:var(--neon-blue); font-weight:bold; margin-right:5px;">No.${index + 1}</span> [${worldName.charAt(0).toUpperCase() + worldName.slice(1)}] ${t.name} <span style="color:var(--rarity-gold);">(${t.cost} P)</span><br><small style="color:#ccc;">${t.desc}</small>`;
                div.onclick = () => buyTalent(t); list.appendChild(div);
            });
            applyShopFilters();
        }
        function applyShopFilters() {
            const list = document.getElementById(''shop-list'');
            if(!list) return;
            const items = list.children;
            for (let item of items) {
                const cost = parseInt(item.dataset.cost);
                const nameMatch = item.dataset.name.includes(shopSearchTerm) || item.dataset.world.includes(shopSearchTerm);
                const priceMatch = cost >= shopPriceFilter.min && cost <= shopPriceFilter.max;
                const affordableMatch = !shopAffordableOnly || cost <= playerPoints;
                item.style.display = (nameMatch && priceMatch && affordableMatch) %s ''block'' : ''none'';
            }
        }
        function setSearchTerm(value) { shopSearchTerm = value.toLowerCase(); applyShopFilters(); }
        function setPriceFilter(btn, min, max) {
            document.querySelectorAll(''button[name="price-filter"]'').forEach(b => b.classList.remove(''active-filter''));
            if (shopPriceFilter.min === min && shopPriceFilter.max === max) {
                shopPriceFilter = { min: 0, max: 999999 };
            } else {
                shopPriceFilter = { min, max };
                btn.classList.add(''active-filter'');
            }
            applyShopFilters();
        }
        function toggleAffordableFilter(btn) { shopAffordableOnly = !shopAffordableOnly; btn.classList.toggle(''active-filter'', shopAffordableOnly); applyShopFilters(); }
        function resetAllFilters() {
            shopSearchTerm = ''''; shopPriceFilter = {min: 0, max: 999999}; shopAffordableOnly = false;
            const searchBox = document.querySelector(''.search-box'');
            if(searchBox) searchBox.value = '''';
            document.querySelectorAll(''.filter-buttons .btn'').forEach(b => b.classList.remove(''active-filter''));
            applyShopFilters();
        }
        function updatePurchasedList() {
            const container = document.getElementById(''purchased-list'');
            container.innerHTML = '''';
            if(purchasedTalents.length === 0) { container.innerText = ''无''; return; }
            purchasedTalents.forEach(t => {
                const span = document.createElement(''span'');
                span.style.marginRight = ''10px'';
                span.className = `rarity-${t.color}`;
                span.innerHTML = `[${t.name}] <span class="remove-btn" onclick="refundTalent(''${t.name}'')">X</span>`;
                container.appendChild(span);
            });
        }
        function buyTalent(t) { 
            if(purchasedTalents.find(pt => pt.name === t.name)) { __htmlFixerInlineAlert("已购买该天赋"); return; } 
            if(playerPoints >= t.cost) { 
                playerPoints -= t.cost; 
                purchasedTalents.push(t); 
                updatePlayerPoints(playerPoints); 
                updatePurchasedList();
            } else { __htmlFixerInlineAlert("积分不足！"); } 
        }
        function refundTalent(name) {
            const t = purchasedTalents.find(pt => pt.name === name);
            if(t) {
                playerPoints += t.cost;
                purchasedTalents = purchasedTalents.filter(pt => pt.name !== name);
                updatePlayerPoints(playerPoints);
                updatePurchasedList();
            }
        }
        function showCustomTalentModal() { document.getElementById(''custom-talent-modal'').style.display = ''block''; }
