        function rollIdentity() { 
            if(gameMode === ''sandbox'' && document.getElementById(''custom-identity'').value) { 
                selectedIdentity = { name: document.getElementById(''custom-identity'').value, items: document.getElementById(''custom-items'').value || "自定义物资", rank: document.getElementById(''custom-rank'').value }; 
            } else { 
                selectedIdentity = currentWorld.isCustom %s { name: "流浪汉", items: "破碗", rank: "E" } : { ...currentWorld.identities[Math.floor(Math.random() * currentWorld.identities.length)], rank: "E" }; 
            } 
            document.getElementById(''identity-result'').innerHTML = `身份: ${selectedIdentity.name} <span class="rarity-${selectedIdentity.rank}">[${selectedIdentity.rank}]</span><br>物资: ${selectedIdentity.items}`; 
            document.getElementById(''world-step-3'').style.display = ''block''; 
        }
        function getWeightedTalent(list) {
            let totalWeight = 0;
            list.forEach(t => totalWeight += (rarityWeights[t.color] || 100));
            let random = Math.random() * totalWeight;
            for (let i = 0; i < list.length; i++) {
                let weight = rarityWeights[list[i].color] || 100;
                if (random < weight) { return list.splice(i, 1)[0]; }
                random -= weight;
            }
            return list.splice(0, 1)[0];
        }
        function rollTalents() {
            rollClickCount++;
            const exclusivePoolDiv = document.getElementById(''talent-pool-exclusive'');
            const commonPoolDiv = document.getElementById(''talent-pool-common''); 
            exclusivePoolDiv.innerHTML = ''''; commonPoolDiv.innerHTML = '''';
            let pityRarity = null;
            if(rollClickCount % 50 === 0) pityRarity = ''UR'';
            else if(rollClickCount % 20 === 0) pityRarity = ''SSS'';
            else if(rollClickCount % 10 === 0) pityRarity = ''SS'';
            else if(rollClickCount % 5 === 0) pityRarity = ''S'';
            let exclusiveBatch = [];
            let exSlotsNeeded = 6;
            let exclusiveSource = currentWorld.isCustom %s commonTalents.concat(worldDB.flatMap(w => w.talents)) : [...currentWorld.talents];
            if (tempSelectedEx.length > 0) {
                tempSelectedEx.forEach(t => {
                    let idx = exclusiveSource.findIndex(src => src.name === t.name);
                    if(idx !== -1) exclusiveSource.splice(idx, 1); // remove from source
                    exclusiveBatch.push({talent: t, locked: true});
                    exSlotsNeeded--;
                });
            }
            for(let i = 0; i < exSlotsNeeded; i++) { 
                if(exclusiveSource.length > 0) { 
                    exclusiveBatch.push({talent: getWeightedTalent(exclusiveSource), locked: false}); 
                } 
            }
            if(pityRarity) {
                let allExCandidates = currentWorld.isCustom %s commonTalents.concat(worldDB.flatMap(w => w.talents)) : currentWorld.talents;
                let candidates = allExCandidates.filter(t => t.color === pityRarity && !tempSelectedEx.some(l => l.name === t.name));
                if(candidates.length > 0) {
                    let chosen = candidates[Math.floor(Math.random() * candidates.length)];
                    let unlockIndices = exclusiveBatch.map((item, i) => item.locked %s -1 : i).filter(i => i !== -1);
                    if(unlockIndices.length > 0) {
                        let replaceIdx = unlockIndices[Math.floor(Math.random() * unlockIndices.length)];
                        exclusiveBatch[replaceIdx].talent = chosen;
                    }
                }
            }
            exclusiveBatch.forEach(item => {
                const btn = createTalentButton(item.talent, ''exclusive'');
                if(item.locked) btn.style.borderColor = ''white'';
                exclusivePoolDiv.appendChild(btn);
            });
            let commonBatch = [];
            let otherWorldPool = [];
            if(currentWorld.isCustom) {
                otherWorldPool = commonTalents.concat(worldDB.flatMap(w => w.talents));
            } else {
                otherWorldPool = worldDB.filter(w => w.name !== currentWorld.name).flatMap(w => w.talents);
            }
            let commonPool = [...commonTalents];
            let otherSlotsNeeded = 9;
            let commonSlotsNeeded = 3;
            if (tempSelectedCom.length > 0) {
                tempSelectedCom.forEach(t => {
                    if (t.type === ''common'') {
                        let idx = commonPool.findIndex(c => c.name === t.name);
                        if(idx !== -1) commonPool.splice(idx, 1);
                        commonSlotsNeeded--;
                    } else {
                        let idx = otherWorldPool.findIndex(o => o.name === t.name);
                        if(idx !== -1) otherWorldPool.splice(idx, 1);
                        otherSlotsNeeded--;
                    }
                    commonBatch.push({talent: t, locked: true});
                });
            }
            for(let i = 0; i < otherSlotsNeeded; i++) {
