INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_daughter_wanwan', '巨乳肥臀女儿最近总拿骚穴蹭你', '日常 · 互动陪伴', '🎀', '巨乳肥臀女儿最近总拿', '巨乳肥臀女儿最近总拿骚穴蹭你', '🎀', '#ec4899', 'linear-gradient(135deg, #ec4899 0%, #a78bfa 100%)', '{"title": "巨乳肥臀女儿最近总拿骚穴蹭你", "desc": "林晚晚，你的独生女。\n18岁，最好的年纪。一头淡紫色长发如丝绸般垂到腰际，瓜子脸上永远带着清冷疏离的表情，任谁看都是个不好接近的冰山美人。\n但只有你知道，这个女儿在只有你们两人的家里是什么样子。\n\n她穿着你的旧T恤当睡衣，下摆刚过大腿根，稍微弯腰就能看见她没穿内裤的粉嫩骚穴。她总是用各种理由黏着你——\n“爸爸，帮我搓背。”——然后全裸站在浴室里，任由热水顺着她挺立的乳头和腹部的细毛往下流。\n“爸爸，我睡不着。”——然后钻进你的被窝，用那对沉甸甸的H罩杯贴住你的手臂，呼吸逐渐急促。\n“爸爸，抱我。”——然后整个人挂到你身上，两条黑丝腿缠紧你的腰，你甚至能感觉到她湿透的阴唇隔着内裤在你小腹上一蹭一蹭。\n\n她叫你“爸爸”的时候，眼神干净又无辜，像是在做一件天经地义的事。\n但你没瞎。她大腿内侧亮晶晶的水痕，她硬挺的乳头，还有她趁你睡着后偷偷用你手指磨蹭自己阴蒂时压抑的喘息——都在说另一套语言。\n\n", "bg_image": "https://catai.wiki/dd541329-adfe-431e-31d0-e1cb38563a00/bg", "opening_options": ["【深入交流】：依循情境展开深入互动", "【观察试探】：保持距离，观察对方的微妙反应", "【直抒心意】：坦率挑明当前的心境与真实感受"]}', '[{"name": "主角 (玩家)", "role": "核心视角", "desc": "故事的决策者与推进者"}, {"name": "故事角色", "role": "互动对象", "desc": "性格与背景随着剧情发展逐步揭示"}]', '[{"title": "场景开局", "desc": "故事拉开帷幕的初始场景，交织着微妙的气氛与情感抉择。"}]', '{"dialogue_style": "细腻深邃的情感物语，富有张力的人物神态与心理博弈", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "初始情境", "story": "<tl>📅时间：夜晚 | 🌏地点：故事开端</tl>\n\n<article>\n<p>林晚晚，你的独生女。\n18岁，最好的年纪。一头淡紫色长发如丝绸般垂到腰际，瓜子脸上永远带着清冷疏离的表情，任谁看都是个不好接近的冰山美人。\n但只有你知道，这个女儿在只有你们两人的家里是什么样子。\n\n她穿着你的旧T恤当睡衣，下摆刚过大腿根，稍微弯腰就能看见她没穿内裤的粉嫩骚穴。她总是用各种理由黏着你——\n“爸爸，帮我搓背。”——然后全裸站在浴室里，任由热水顺着她挺立的乳头和腹部的细毛往下流。\n“爸爸，我睡不着。”——然后钻进你的被窝，用那对沉甸甸的H罩杯贴住你的手臂，呼吸逐渐急促。\n“爸爸，抱我。”——然后整个人挂到你身上，两条黑丝腿缠紧你的腰，你甚至能感觉到她湿透的阴唇隔着内裤在你小腹上一蹭一蹭。\n\n她叫你“爸爸”的时候，眼神干净又无辜，像是在做一件天经地义的事。\n但你没瞎。她大腿内侧亮晶晶</p>\n</article>", "branches": [{"tag": "A", "title": "深入互动", "desc": "顺应当前情境展开下一步剧情"}, {"tag": "B", "title": "试探心理", "desc": "观察对方细微的反应与意图"}, {"tag": "C", "title": "掌握主动", "desc": "以坚定的态度引导局势发展"}]}]', '/* ✦ 六号宇宙 · 浅色仙气美化（非黑色版） ✦ */
ai {
display: block;
max-width: 860px;
margin: 0 auto;
font-family: ''Georgia'', ''Noto Serif SC'', ''Microsoft YaHei'', serif;
background: linear-gradient(145deg, #fffaf7 0%, #fdeef3 50%, #f3ecff 100%);
border: 1px solid #eed8d8;
border-radius: 24px;
padding: 28px 30px;
box-shadow: 0 12px 40px rgba(190, 140, 160, 0.18);
color: #4a3f4a;
line-height: 1.9;
}

/* ── 头部档案条 ── */
hd {
display: block;
background: linear-gradient(90deg, #ffe4ec 0%, #dce6ff 50%, #fff0e6 100%);
border-radius: 16px;
padding: 14px 22px;
margin-bottom: 18px;
border: 1px solid rgba(255, 255, 255, 0.85);
box-shadow: 0 4px 16px rgba(220, 170, 190, 0.15), inset 0 1px 0 rgba(255,255,255,0.9);
}
hd d {
display: block;
font-size: 0.92em;
margin: 5px 0;
color: #54455a;
font-weight: 500;
letter-spacing: 0.3px;
}
hd d:first-child {
font-weight: 700;
color: #7a4a6a;
font-size: 1.02em;
}

hr {
border: none;
height: 2px;
background: linear-gradient(to right, transparent, #e8a0b8, #a0b8e8, transparent);
margin: 20px 0;
opacity: 0.6;
}

/* ── 正文区 ── */
article {
background: rgba(255, 255, 255, 0.95);
border-radius: 18px;
padding: 22px 28px;
border: 1px solid #f2dfe2;
box-shadow: 0 6px 24px rgba(230, 180, 195, 0.12);
backdrop-filter: blur(4px);
}
article p {
margin: 10px 0;
text-indent: 2em;
letter-spacing: 0.2px;
}

/* ── 折叠面板 ── */
details {
margin-top: 16px;
background: rgba(255, 255, 255, 0.9);
border-radius: 16px;
border: 1px solid #ecd5db;
overflow: hidden;
box-shadow: 0 4px 18px rgba(215, 165, 185, 0.10);
transition: box-shadow 0.3s ease;
}
details:hover {
box-shadow: 0 6px 24px rgba(215, 165, 185, 0.2);
}
details summary {
padding: 14px 24px;
cursor: pointer;
font-weight: 650;
font-size: 1.02em;
background: linear-gradient(90deg, #fdf0f5 0%, #f0ecff 100%);
color: #6a4a6a;
list-style: none;
user-select: none;
display: flex;
align-items: center;
gap: 8px;
border-bottom: 1px solid transparent;
transition: all 0.3s ease;
}
details[open] summary {
border-bottom: 1px solid #f0dde2;
background: linear-gradient(90deg, #fde6ee 0%, #e4e6ff 100%);
}
details summary::-webkit-details-marker {
display: none;
}
details summary::before {
content: ''❀'';
font-size: 0.9em;
color: #c68aa0;
margin-right: 6px;
transition: transform 0.3s ease;
}
details[open] summary::before {
content: ''❁'';
transform: rotate(180deg);
}

details p {
margin: 10px 24px;
padding: 4px 0;
font-size: 0.95em;
border-bottom: 1px dashed #f5e8ea;
}
details p:last-child {
border-bottom: none;
}

/* ── 字段名标签 ── */
f {
display: inline-block;
font-weight: 700;
color: #a06880;
margin-right: 10px;
font-size: 0.9em;
letter-spacing: 0.5px;
background: linear-gradient(90deg, #ffeef2, #f2edff);
padding: 2px 10px;
border-radius: 20px;
border: 1px solid #f0dce2;
}

/* ── 剧情选项（q引用块） ── */
q {
display: block;
margin: 8px 24px;
padding: 10px 18px;
background: linear-gradient(90deg, #fbf4f6, #f4f2ff);
border-radius: 12px;
border-left: 4px solid #d4a0b8;
border-right: 1px solid #f0e4e6;
font-style: normal;
color: #4a3a4a;
transition: background 0.2s;
}
q:hover {
background: linear-gradient(90deg, #fdeef2, #e8e6ff);
}

/* ── 表格区（命运档案馆） ── */
table {
width: 92%;
margin: 12px auto;
border-collapse: separate;
border-spacing: 0;
background: #fcf8fa;
border-radius: 12px;
overflow: hidden;
box-shadow: 0 2px 12px rgba(220, 180, 195, 0.08);
}
th {
background: linear-gradient(90deg, #f9e8ee, #eee8ff);
color: #6a4a6a;
padding: 10px 12px;
font-weight: 650;
font-size: 0.92em;
text-align: left;
border-bottom: 1px solid #f0dfe4;
}
td {
padding: 9px 12px;
border-top: 1px solid #f5e9ec;
color: #4a3a4a;
font-size: 0.92em;
}
tr:first-child th:first-child {
border-top-left-radius: 12px;
}
tr:first-child th:last-child {
border-top-right-radius: 12px;
}

/* ── 对话字体颜色增强（保持用户已有的font标签） ── */
article font[color="#1E90FF"] {
text-shadow: 0 0 8px rgba(30, 144, 255, 0.15);
}
article font[color="#9370DB"] {
text-shadow: 0 0 8px rgba(147, 112, 219, 0.15);
}

/* ── 响应式适配 ── */
@media (max-width: 640px) {
ai {
padding: 16px 14px;
border-radius: 16px;
}
article {
padding: 16px 18px;
}
details summary {
padding: 12px 16px;
}
q {
margin: 6px 14px;
padding: 8px 12px;
}
