        ''越级反杀（被动）'', ''天生坏种'', ''圣母之心（？？？）'', ''此子与我有缘'', ''魅力反转'', ''修炼加速'', ''丹毒不侵'', ''直觉野兽''
    ]
};
const engine3_pool = {
    blue: [
        ''剑道通明'', ''缩地成寸'', ''过目不忘'', ''趋吉避凶'', ''百毒不侵（初级）'', ''丹道宗师'', ''阵法奇才'', 
        ''神魂天成'', ''炼器大师'', ''符箓圣手'', ''五行均衡'', ''天生灵体'', ''战斗直觉'', ''魅力非凡'', 
        ''威压天成'', ''灵视'', ''听风者'', ''危机预感'', ''妙手空空'', ''一心二用'', ''药理精通'',
        ''五脏强韧'', ''血气如虹'', ''精神饱满'', ''追风者'', ''巧舌如簧'', ''举一反三'', ''食补达人'', ''环境适应'', ''愈合加速''
    ],
    green: [
        ''身强体壮'', ''小有家资'', ''耳聪目明'', ''灵气亲和'', ''酒中仙（伪）'', ''第六感'', ''交际手腕'', 
        ''鸿运当头'', ''跑得快'', ''抗击打'', ''恢复力强'', ''精力旺盛'', ''手有余香'', ''小福星'',
        ''过目不忘（劣化）'', ''方向感极佳'', ''千杯不醉'', ''人缘好'', ''动物亲和'', ''讨价还价'', ''手脚麻利'',
        ''耐力持久'', ''睡眠质量高'', ''认路达人'', ''厨艺精湛'', ''水性良好'', ''不易生病'', ''长相清秀'', ''声音好听'', ''手气不错''
    ],
    white: [
        ''路人脸'', ''家徒四壁'', ''体弱多病'', ''霉运缠身'', ''方向感缺失'', ''酒精过敏'', ''穷鬼'', ''话痨'', 
        ''社交恐惧'', ''选择困难症'', ''夜猫子'', ''嗜睡'', ''洁癖'', ''惧内（潜在）'', ''天生劳碌命'',
        ''平胸'', ''身高残念'', ''疤痕体质'', ''傲娇'', ''中二病'', ''杠精'', ''脸盲'', ''喝凉水都塞牙'',
        ''平地摔跤'', ''路痴晚期'', ''猫毛过敏'', ''五音不全'', ''肢体不协调'', ''食量大'', ''有口气''
    ]
};
function getRandomElement(arr) {
return arr[Math.floor(Math.random() * arr.length)];
}
function generateFromEngine1() {
const origin = getRandomElement(engine1_pools.origins);
const concept = getRandomElement(engine1_pools.concepts);
const form = getRandomElement(engine1_pools.forms);
return `${origin}${concept}${form}`;
}
function generateFromEngine2(rarity) {
return getRandomElement(engine2_pool[rarity]);
}
function generateFromEngine3(rarity) {
return getRandomElement(engine3_pool[rarity]);
}
function generateSingleTalent(rarity) {
const rand = Math.random() * 100;
switch (rarity) {
case ''red'':
return rand < 80 %s generateFromEngine2(''red'') : generateFromEngine1();
case ''orange'':
return rand < 70 %s generateFromEngine2(''orange'') : generateFromEngine1();
case ''purple'':
return rand < 60 %s generateFromEngine2(''purple'') : generateFromEngine1();
case ''blue'':
return rand < 80 %s generateFromEngine3(''blue'') : generateFromEngine1();
default:
return generateFromEngine3(rarity);
}
}
function getRandomQualityKey(isGuaranteed) {
if (isGuaranteed) {
const highTierKeys = [''blue'', ''purple'', ''orange'', ''red''];
return getRandomElement(highTierKeys);
}
const totalWeight = Object.values(qualityMap).reduce((sum, q) => sum + q.weight, 0);
let random = Math.random() * totalWeight;
for (const key in qualityMap) {
if (random < qualityMap[key].weight) {
return key;
}
random -= qualityMap[key].weight;
}
}
function rollTalents() {
talentsDisplay.innerHTML = '''';
selectedTalents = [];
let hasHighQuality = false;
const talentPool = [];
for (let i = 0; i < 6; i++) {
const qualityKey = getRandomQualityKey(false);
if ([''blue'', ''purple'', ''orange'', ''red''].includes(qualityKey)) {
hasHighQuality = true;
}
talentPool.push(qualityKey);
}
if (!hasHighQuality) {
const randomIndex = Math.floor(Math.random() * 6);
talentPool[randomIndex] = getRandomQualityKey(true);
}
talentPool.forEach(qualityKey => {
const qualityInfo = qualityMap[qualityKey];
const name = generateSingleTalent(qualityKey);
const card = document.createElement(''div'');
card.classList.add(''talent-card'');
card.dataset.name = `[${qualityInfo.name}] ${name}`;
card.innerHTML = `<span class="quality ${qualityInfo.class}">[${qualityInfo.name}]</span> ${name}`;
card.addEventListener(''click'', () => toggleTalentSelection(card));
talentsDisplay.appendChild(card);
});
updatePreview();
}
function toggleTalentSelection(card) {
const talentName = card.dataset.name;
if (selectedTalents.includes(talentName)) {
selectedTalents = selectedTalents.filter(t => t !== talentName);
card.classList.remove(''selected'');
} else {
if (selectedTalents.length < MAX_TALENTS) {
selectedTalents.push(talentName);
card.classList.add(''selected'');
} else {
alert(`最多只能选择 ${MAX_TALENTS} 个天赋！`);
}
}
updatePreview();
}
function updatePreview() {
const name = charNameInput.value || ''【未命名】'';
const gender = container.querySelector(''input[name="gender"]:checked'').value;
const age = ageSelect.value;
const origin = charOriginInput.value || ''【未填写】'';
const appearance = appearanceTextarea.value || ''【未描述】'';
let talentsText = selectedTalents.length > 0 %s selectedTalents.join(''\n'') : ''【尚未选择天赋】'';
previewArea.value = `【角色姓名】：${name}\n【性别】：${gender}\n【年龄段】：${age}\n【天命出身】：${origin}\n【容貌风姿】：${appearance}\n\n【先天气运】：\n${talentsText}`;
}
tabBtns.forEach(btn => {
btn.addEventListener(''click'', () => {
tabBtns.forEach(b => b.classList.remove(''active''));
tabContents.forEach(c => c.classList.remove(''active''));
btn.classList.add(''active'');
container.querySelector(`#${btn.dataset.tab}`).classList.add(''active'');
});
});
accordions.forEach(accordion => {
const header = accordion.querySelector(''.accordion-header'');
const content = accordion.querySelector(''.accordion-content'');
header.addEventListener(''click'', () => {
accordion.classList.toggle(''active'');
if (accordion.classList.contains(''active'')) {
content.style.maxHeight = content.scrollHeight + ''px'';
} else {
content.style.maxHeight = ''0'';
}
});
});
charNameInput.addEventListener(''input'', updatePreview);
genderRadios.forEach(radio => radio.addEventListener(''change'', updatePreview));
ageSelect.addEventListener(''change'', updatePreview);
charOriginInput.addEventListener(''input'', updatePreview);
appearanceTextarea.addEventListener(''input'', updatePreview);
rollBtn.addEventListener(''click'', rollTalents);
copyBtn.addEventListener(''click'', () => {
previewArea.select();
document.execCommand(''copy'');
alert(''角色设定已复制到剪贴板！'');
});
rollTalents();
});
</script>
</body>
</html>', '男性向', '2026-10-11 11:21:05', '2026-10-11 11:21:05', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('e7784aa4-f7a3-4ecb-a4d9-b3463f9f122a', '写文助手V3', '已破甲 · 高自由度', '📖', '写文助手V3', '［且行且珍惜］元旦快乐，感谢陪伴。更新：优化结构降耗，对状态栏、女性向、色情增强等功能进行了拆分，避免误触发导致增耗，需要安装MOD主动开启，并加入了MOD系统', '📖', '#3b82f6', 'linear-gradient(135deg, #3b82f6 0%, #6366f1 100%)', '{"title": "写文助手V3", "desc": "［且行且珍惜］元旦快乐，感谢陪伴。更新：优化结构降耗，对状态栏、女性向、色情增强等功能进行了拆分，避免误触发导致增耗，需要安装MOD主动开启，并加入了MOD系统，能够更好的调动自设、MOD，后续有空将会不断更新各类MOD，包括常规同人MOD、肉文MOD、玩法MOD等，功能测试中，有问题请友善反馈，爱你们。全视角，全性向设定、全性向角色状态栏，多文风调教，写文、自定义均可。您可以用我创作任何满足您幻", "bg_image": "https://catai.wiki/b8ccf491-9e59-46fd-36f5-985b19047100/bg"}', '[]', '[]', '{}', '[{"isUser": false, "story": "【序章 · 初临】\n\n［且行且珍惜］元旦快乐，感谢陪伴。更新：优化结构降耗，对状态栏、女性向、色情增强等功能进行了拆分，避免误触发导致增耗，需要安装MOD主动开启，并加入了MOD系统，能够更好的调动自设、MOD，后续有空将会不断更新各类MOD，包括常规同人MOD、肉文MOD、玩法MOD等，功能测试中，有问题请友善反馈，爱你们。全视角，全性向设定、全性向角色状态栏，多文风调教，写文、自定义均可。您可以用我创作任何满足您幻想的文学作品，可以适应任何世界观、任何文风创作，无论是都市的逆天邪神、重活了，玄幻的斗破苍穹、武动乾坤大主宰斗罗大陆、龙王传说绝世唐门轮回乐园赘婿龙族，还是修仙的凡人修仙传、诛仙，或者金庸古龙的传统武侠、雪中剑来等仙侠，亦或者诡异、惊悚的恐怖复苏、亦或者动漫同人的死神海贼王火影忍者七龙珠咒术回战轻音少女少女乐队mygo、邦多利、缘之空、电棍、东雪莲asoul嘉然乃琳贝拉珈乐向晚七海阿梓冰糖塔菲东海帝皇诗歌剧阿巴阿巴\n\n阳光穿透微隙，周围的喧嚣渐渐清晰。你迈出脚步，开启了在这片天地间的全新篇章……", "branches": [{"tag": "A", "title": "环顾四周观察当前局势", "desc": "环顾四周观察当前局势"}, {"tag": "B", "title": "顺应眼前的指引前行", "desc": "顺应眼前的指引前行"}]}]', '', '<html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>文助手 V3.2 (MOD版)</title><style>:root {--primary-color: #e74c3c;--primary-hover: #c0392b;--secondary-color: #f1c40f;--bg-dark: #2c3e50;--bg-light: #34495e;--text-light: #ecf0f1;--text-dark: #bdc3c7;--border-color: rgba(231, 76, 60, 0.5);--success-color: #2ecc71;--success-hover: #27ae60;--info-bg: rgba(52, 152, 219, 0.1);--info-border: #3498db;--warning-bg: rgba(241, 196, 15, 0.1);--warning-border: #f1c40f;}
* { margin: 0; padding: 0; box-sizing: border-box; scrollbar-width: thin; scrollbar-color: var(--primary-color) var(--bg-dark); }
*::-webkit-scrollbar { width: 8px; height: 8px; }
*::-webkit-scrollbar-track { background: var(--bg-dark); }
*::-webkit-scrollbar-thumb { background-color: var(--primary-color); border-radius: 10px; border: 2px solid var(--bg-dark); }
html { scroll-behavior: smooth; }
body {font-family: ''PingFang SC'', ''Microsoft YaHei'', ''SimSun'', sans-serif; background: linear-gradient(135deg, var(--bg-dark), var(--bg-light));color: var(--text-light); min-height: 100vh; line-height: 1.6; font-size: 15px; display: flex; justify-content: center;align-items: flex-start; padding: 20px 10px; overflow-x: hidden;}
.container { width: 100%; max-width: 900px; height: calc(100vh - 40px); overflow-y: auto; overflow-x: hidden; padding-right: 10px; }
.main-panel { background: rgba(44, 62, 80, 0.92); border: 2px solid var(--primary-color); border-radius: 15px; padding: 30px; backdrop-filter: blur(8px); box-shadow: 0 0 30px rgba(231, 76, 60, 0.5); margin-bottom: 30px; overflow: auto; }
h1 { color: var(--primary-color); text-align: center; font-size: 2.5em; margin-bottom: 10px; text-shadow: 2px 2px 5px rgba(0, 0, 0, 0.8); letter-spacing: 2px; }
h2 { color: var(--text-dark); text-align: center; font-size: 1.1em; margin-bottom: 25px; font-weight: 400; }
h3 { color: var(--secondary-color); font-size: 1.4em; margin: 25px 0 15px 0; text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.7); padding-bottom: 5px; border-bottom: 1px solid rgba(241, 196, 15, 0.3); }
h4 { color: var(--info-border); font-size: 1.2em; margin-top: 20px; margin-bottom: 10px; }
p { color: var(--text-light); margin-bottom: 10px; line-height: 1.7; font-size: 1em; }
.collapsible-section { background: rgba(52, 73, 94, 0.75); border: 1px solid var(--border-color); border-radius: 8px; margin-bottom: 15px; overflow: hidden; transition: all 0.3s ease-in-out; }
.collapsible-header { display: block; padding: 14px 20px; background: rgba(231, 76, 60, 0.85); color: #ffffff; font-weight: bold; font-size: 1.1em; cursor: pointer; user-select: none; transition: background 0.3s ease; position: relative; }
.collapsible-header:hover { background: var(--primary-hover); }
.collapsible-header::after { content: ''▼''; position: absolute; right: 20px; top: 50%; transform: translateY(-50%); transition: transform 0.3s; font-size: 0.9em; }
details[open] > .collapsible-header::after { transform: translateY(-50%) rotate(180deg); }
.collapsible-content { padding: 20px; background: rgba(44, 62, 80, 0.95); border-top: 1px solid rgba(231, 76, 60, 0.4); }
.checkbox-group { display: flex; flex-wrap: wrap; gap: 10px 15px; }
.checkbox-group label { display: flex; align-items: center; color: var(--text-light); font-size: 1em; cursor: pointer; padding: 5px 10px; border-radius: 5px; background: rgba(255, 255, 255, 0.05); transition: background 0.3s; }
.checkbox-group label:hover { background: rgba(255, 255, 255, 0.1); }
.checkbox-group input[type="checkbox"] { margin-right: 8px; width: 18px; height: 18px; accent-color: var(--primary-color); }
.form-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 20px; }
.form-group { display: flex; flex-direction: column; }
.form-group.full-width { grid-column: 1 / -1; }
.form-group label { color: var(--secondary-color); margin-bottom: 8px; font-weight: bold; font-size: 1em; }
.form-group input, .form-group select, .form-group textarea { background: rgba(0, 0, 0, 0.2); border: 1px solid rgba(255, 255, 255, 0.2); border-radius: 6px; padding: 10px; color: var(--text-light); font-size: 1em; transition: border-color 0.3s, background 0.3s; }
.form-group select { color: var(--text-light); background-color: rgba(0, 0, 0, 0.2); }
.form-group select option { background-color: var(--bg-dark); color: var(--text-light); }
.form-group input:focus, .form-group select:focus, .form-group textarea:focus { outline: none; border-color: var(--primary-color); background: rgba(0, 0, 0, 0.3); box-shadow: 0 0 8px rgba(231, 76, 60, 0.5); }
textarea { resize: vertical; min-height: 60px; }
.button-group { display: flex; gap: 15px; justify-content: center; margin-top: 25px; flex-wrap: wrap; }
.action-btn { color: #ffffff; border: none; border-radius: 8px; padding: 12px 30px; font-size: 1.1em; font-weight: bold; cursor: pointer; transition: all 0.3s; box-shadow: 0 4px 15px rgba(0,0,0,0.3); text-transform: uppercase; letter-spacing: 1px; flex-grow: 1; min-width: 150px; }
.generate-btn { background: var(--primary-color); }
.generate-btn:hover { background: var(--primary-hover); transform: translateY(-2px); box-shadow: 0 6px 20px rgba(231, 76, 60, 0.5); }
.reset-btn { background: var(--info-border); }
.reset-btn:hover { background: #3aa9e3; transform: translateY(-2px); box-shadow: 0 6px 20px rgba(52, 152, 219, 0.4); }
#previewModal, #modInstructionModal { display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.7); z-index: 1001; backdrop-filter: blur(5px); align-items: center; justify-content: center; }
#modInstructionModal { z-index: 1002; }
.modal-content { position: relative; background: rgba(44, 62, 80, 0.98); padding: 30px; border-radius: 15px; border: 2px solid var(--success-color); width: 90%; max-width: 600px; max-height: 90vh; overflow-y: auto; box-shadow: 0 0 30px rgba(46, 204, 113, 0.5); }
.modal-content h3 { color: var(--success-color); border-bottom: 2px solid rgba(46, 204, 113, 0.4); padding-bottom: 1rem; margin-top: 0; margin-bottom: 20px; text-align: center; font-size: 1.5em; }
#previewContent { color: var(--text-light); line-height: 1.7; font-size: 1em; white-space: pre-wrap; word-break: break-all; }
.preview-buttons { margin-top: 2rem; display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }
.preview-buttons button { border: none; padding: 0.8rem 1.8rem; cursor: pointer; border-radius: 6px; transition: all 0.3s; font-weight: bold; font-size: 1em; }
.confirm-btn { background: var(--success-color); color: var(--bg-dark); }
.confirm-btn:hover { background: var(--success-hover); transform: translateY(-2px); box-shadow: 0 4px 10px rgba(46, 204, 113, 0.4); }
.return-btn { background: rgba(255, 255, 255, 0.1); color: var(--text-light); border: 1px solid var(--text-dark); }
.return-btn:hover { background: rgba(255, 255, 255, 0.2); color: #ffffff; }
.quick-nav { position: fixed; top: 50%; right: 15px; transform: translateY(-50%); background: rgba(44, 62, 80, 0.8); backdrop-filter: blur(5px); border-radius: 10px; padding: 10px; z-index: 1000; display: flex; flex-direction: column; gap: 12px; border: 1px solid var(--border-color); box-shadow: 0 0 15px rgba(0,0,0,0.5); }
.quick-nav.hidden { display: none; }
.quick-nav a { color: var(--text-light); text-decoration: none; font-size: 1.5em; text-align: center; transition: color 0.3s, transform 0.3s; padding: 5px; position: relative; }
.quick-nav a:hover { color: var(--primary-color); transform: scale(1.2); }
.quick-nav a .tooltip { visibility: hidden; width: 120px; background-color: var(--bg-dark); color: #fff; text-align: center; border-radius: 6px; padding: 5px 0; position: absolute; z-index: 1; top: 50%; right: 120%; transform: translateY(-50%); opacity: 0; transition: opacity 0.3s; font-size: 0.6em; }
.quick-nav a:hover .tooltip { visibility: visible; opacity: 1; }
.close-nav { position: absolute; top: -15px; right: -15px; background: var(--primary-color); color: white; border: none; border-radius: 50%; width: 30px; height: 30px; font-size: 1.2em; cursor: pointer; display: flex; align-items: center; justify-content: center; box-shadow: 0 0 10px rgba(0,0,0,0.5); }
.reminder-box { background: var(--info-bg); border-left: 4px solid var(--info-border); padding: 15px; margin-top: 20px; border-radius: 0 8px 8px 0; }
.update-notice-box { background: var(--warning-bg); border-left: 4px solid var(--warning-border); padding: 15px; margin: 20px 0; border-radius: 0 8px 8px 0; }
.update-notice-box h4 { color: var(--warning-border); margin-top:0; }
.update-notice-box p { margin-bottom: 8px; color: var(--text-light); font-size: 0.95em; }
.reminder-box p { margin-bottom: 8px; color: var(--text-light); font-size: 0.95em; }
.reminder-box code, .update-notice-box code { background: rgba(0, 0, 0, 0.3); padding: 2px 6px; border-radius: 4px; font-family: ''Courier New'', Courier, monospace; color: var(--secondary-color); }
.reminder-box pre { background: rgba(0, 0, 0, 0.4); padding: 10px; border-radius: 5px; white-space: pre-wrap; word-break: break-all; margin-top: 5px; }
#toast-container { position: fixed; top: 20px; right: 20px; z-index: 2000; display: flex; flex-direction: column; gap: 10px; }
.toast { background-color: var(--success-color); color: var(--bg-dark); padding: 15px 20px; border-radius: 8px; box-shadow: 0 4px 15px rgba(0,0,0,0.3); transform: translateX(120%); opacity: 0; transition: transform 0.5s ease, opacity 0.5s ease; font-weight: bold; }
.toast.show { transform: translateX(0); opacity: 1; }
footer { text-align: center; margin-top: 30px; font-size: 0.9em; }
footer a { color: var(--text-dark); text-decoration: none; transition: color 0.3s; }
footer a:hover { color: var(--primary-color); }
@media (max-width: 1024px) { .quick-nav { right: 5px; } }
@media (max-width: 768px) {body { padding: 10px 5px; font-size: 14px; }.container { height: calc(100vh - 20px); padding-right: 5px; }.main-panel { padding: 20px; }h1 { font-size: 2em; }.form-row { grid-template-columns: 1fr; }.quick-nav { display: none; }.modal-content { width: 95%; max-height: 85vh; padding: 20px; }}
@media (max-width: 400px) {body { padding: 5px 0; }.container { height: calc(100vh - 10px); padding: 0 5px; }.main-panel { padding: 15px; border-radius: 10px; border: 1px solid var(--primary-color); }h1 { font-size: 1.8em; }.collapsible-header { padding: 12px 15px; font-size: 1em; }.collapsible-content { padding: 15px; }.action-btn, .preview-buttons button { width: 100%; padding: 12px; }.modal-content { width: 98%; padding: 15px; border-radius: 10px; }#toast-container { right: 10px; top: 10px; width: calc(100% - 20px); }}</style></head><body><div id="toast-container"></div><div class="quick-nav" id="quickNav"><button class="close-nav" id="closeNavBtn">&times;</button><a href="#style-section">🎨<span class="tooltip">风格与视角</span></a><a href="#world-section">🌍<span class="tooltip">世界观设定</span></a><a href="#protagonist-section">👤<span class="tooltip">主角信息</span></a><a href="#creation-section">💡<span class="tooltip">创作需求</span></a><a href="#character-section">👥<span class="tooltip">定制角色</span></a><a href="#mod-section">🛠️<span class="tooltip">MOD制作</span></a></div><div class="container" id="mainContainer"><div class="main-panel"><h1>写文助手 V3</h1><h2>您的专属幻想工程师，生成无限可能的故事</h2><form id="story-form"><details id="style-section" class="collapsible-section" open><summary class="collapsible-header">创作风格与视角选择</summary><div class="collapsible-content"><h3>创作性向 (可多选)</h3><div class="checkbox-group"><label><input type="checkbox" class="orientation-style" value="男性向风格"> 男性向</label><label><input type="checkbox" class="orientation-style" value="女性向风格"> 女性向</label><label><input type="checkbox" class="orientation-style" value="BL风格"> BL</label><label><input type="checkbox" class="orientation-style" value="GL风格"> GL</label><label><input type="checkbox" class="orientation-style" value="1风格"> 1</label><label><input type="checkbox" class="orientation-style" value="1风格"> 1</label><label><input type="checkbox" class="orientation-style" value="2"> 2</label></div><h3>叙事视角</h3><div class="checkbox-group"><label><input type="checkbox" id="povFirst"> 第一人称</label><label><input type="checkbox" id="povSecond"> 第二人称</label><label><input type="checkbox" id="povThird"> 第三人称</label></div><h3>小说文风 (可多选)</h3><div class="checkbox-group"><label><input type="checkbox" class="writing-style" value="现代言情情文风"> 现代言情</label><label><input type="checkbox" class="writing-style" value="古代言情文风"> 古代言情</label><label><input type="checkbox" class="writing-style" value="都市文风"> 都市文风</label><label><input type="checkbox" class="writing-style" value="青春校园文风"> 青春校园</label><label><input type="checkbox" class="writing-style" value="温馨日常文风"> 温馨日常</label><label><input type="checkbox" class="writing-style" value="日式轻小说文风"> 日式轻小说</label><label><input type="checkbox" class="writing-style" value="西幻小说文风"> 西幻史诗</label><label><input type="checkbox" class="writing-style" value="玄幻小说文风"> 东方玄幻</label><label><input type="checkbox" class="writing-style" value="修仙小说文风"> 缥缈修仙</label></div><div class="update-notice-box"><h4>⚠️ 本次更新内容</h4><p>1、本次更新为重大更新，对作品结构进行了大幅度的调整，将许多功能以mod的形式进行了拆分，从而更个性化的为大家提供自由的定制服务，且彻底杜绝本不需要的功能可能被触发从而导致消耗增加的情况。请立即根据需求前往mod区选用对应mod以确保功能完整。</p><p>2、新增了mod系统，优化了AI读取，能够更好的调动MOD、世界书，基于此功能，今后将会持续制作各种各样的MOD供大家选用，创作出更好的作品，但更新时间待定。</p><p>3、新增了MOD制作工坊，在本页的底部，输入对应内容后即可预览、复制，放到自定义配置的提示词中，保存即可载入该MOD，推荐大家制作角色设定信息MOD、已发生的重要剧情MOD等，维持角色和剧情不崩。</p></div><h4>温馨提示</h4><div class="reminder-box"><p>1️⃣ <strong>记忆推荐：</strong>4记忆即可，记忆越高AI要处理的信息越多，消耗也越高，并非越高越好</p><p>2️⃣ <strong>模型推荐：</strong><br>① <code>aibus vertex gemini 2.5pro</code><br>② <code>aibus vertex gemini 3.0pro</code><br>③ <code>yuegle anthropic anti Claude opus 4-5-20251101-thinking，价格系数0.12，这个的表现不错，用腻了哈基米的可以试试这个，不过克劳德的破甲不如哈基米稳定，大家灵活运用叭 ④  若以上渠道均截断，请切换grok模型跑一两轮后切回</p><p>3️⃣ <strong>使用技巧：</strong>本作品为AI辅助创作工具，重要的世界设定、角色设定、剧情节点，请使用MOD工坊制作并放入右上角－自定义配置－提示词中保存并及时更新;格式为：<br>&lt;世界设定&gt;<br>这里放世界设定<br>&lt;/世界设定&gt;<br>
&lt;已保存的角色信息&gt;<br>这里放需要保存记录的角色信息<br>&lt;/已保存的角色信息&gt;<br>
&lt;已保存的重要剧情节点&gt;<br>这里放需要保存的剧情节点<br>&lt;/已保存的重要剧情节点&gt;<br>
</p></code></pre></p><p>4️⃣ <strong>撞甲、截断：</strong>优先推荐流式，开局尽量先别涩涩，做点铺垫体验更好更不容易撞甲，常规内容截断为风月、渠道不稳定，正常截断也是，此时可以切换非流式，敏感内容必须流式，截断可以切上面推荐克劳德模型，或者切grok、ds模型过渡一两轮内容再切回来，半夜美国上班模型厚，截断率激增，请耐心、多包涵，有问题可以评论区反馈，感谢大家的游玩，爱你们</p></div></div></details><details id="world-section" class="collapsible-section"><summary class="collapsible-header">世界观设定</summary><div class="collapsible-content"><div class="form-group full-width"><label for="worldInfo">世界信息</label><textarea id="worldInfo" rows="4" placeholder="描述故事发生的世界背景，例如：这是一个魔法与科技并存的赛博朋克都市；一个遵循残酷丛林法则的末日废土；或者一个等级森严、神权至上的奇幻王国..."></textarea></div></div></details><details id="protagonist-section" class="collapsible-section" open><summary class="collapsible-header">主角信息</summary><div class="collapsible-content form-row"><div class="form-group full-width"><label for="protagonistName">姓名</label><input type="text" id="protagonistName" placeholder="例如：龙傲天 / 苏玛丽"></div><div class="form-group"><label for="protagonistGender">性别</label><select id="protagonistGender"><option value="男">男</option><option value="女">女</option><option value="双性">双性</option><option value="扶他">扶他</option><option value="其他">其他</option></select></div><div class="form-group"><label for="protagonistAge">年龄</label><input type="number" id="protagonistAge" min="1" max="999" value="20"></div><div class="form-group full-width"><label for="protagonistAppearance">身材外貌</label><textarea id="protagonistAppearance" rows="2" placeholder="例如：身高188cm，宽肩窄腰，八块腹肌人鱼线，黑发黑眸，眼神深邃如渊..."></textarea></div><div class="form-group full-width"><label for="protagonistPersona">详细人设</label><textarea id="protagonistPersona" rows="3" placeholder="例如：职业：退役兵王/吸血鬼后裔；穿着：万年不变的黑背心和工装裤；性格：外冷内热，杀伐果断，对认可的人极其护短..."></textarea></div><div class="form-group full-width"><label for="protagonistPower">主角外挂/金手指</label><textarea id="protagonistPower" rows="3" placeholder="例如：能看到好感度的系统、可以无限复活、拥有吞噬他人能力的体质、一块能穿越时空的神秘玉佩..."></textarea></div></div></details><details id="creation-section" class="collapsible-section"><summary class="collapsible-header">创作需求</summary><div class="collapsible-content form-row"><div class="form-group full-width"><label for="scene">创作场景</label><textarea id="scene" rows="2" placeholder="例如：豪华游轮的私人套房、废弃古堡的地下室、充满异域风情的沙漠帐篷..."></textarea></div><div class="form-group full-width"><label for="event">创作事件</label><textarea id="event" rows="2" placeholder="例如：一场意外的邂逅、被困密室、复仇计划的实施、一次身体检查..."></textarea></div><div class="form-group full-width"><label for="specialRequirements">特殊需求/XP</label><textarea id="specialRequirements" rows="3" placeholder="例如：道具使用、角色扮演、身体改造、变身、怪物..."></textarea></div></div></details><details id="character-section" class="collapsible-section"><summary class="collapsible-header">定制角色 (最多3位)</summary><div class="collapsible-content"><details class="collapsible-section"><summary class="collapsible-header">定制角色1信息</summary><div class="collapsible-content form-row"><div class="form-group full-width"><label for="char1Name">姓名</label><input type="text" id="char1Name" placeholder="例如：赵灵儿"></div><div class="form-group"><label for="char1Gender">性别</label><select id="char1Gender"><option value="">无</option><option value="男">男</option><option value="女">女</option><option value="双性">双性</option><option value="其他">其他</option></select></div><div class="form-group"><label for="char1Age">年龄</label><input type="number" id="char1Age" min="0" max="999" placeholder="无"></div><div class="form-group full-width"><label for="char1Appearance">身材外貌</label><textarea id="char1Appearance" rows="2" placeholder="例如：身高160cm，娇小可爱，黑长直，大眼睛，皮肤白皙..."></textarea></div><div class="form-group full-width"><label for="char1Persona">详细人设</label><textarea id="char1Persona" rows="3" placeholder="例如：职业：清纯女大学生；穿着：常穿白裙，校服；性格：温柔善良，容易害羞..."></textarea></div></div></details><details class="collapsible-section"><summary class="collapsible-header">定制角色2信息</summary><div class="collapsible-content form-row"><div class="form-group full-width"><label for="char2Name">姓名</label><input type="text" id="char2Name" placeholder="例如：林月如"></div><div class="form-group"><label for="char2Gender">性别</label><select id="char2Gender"><option value="">无</option><option value="男">男</option><option value="女">女</option><option value="双性">双性</option><option value="其他">其他</option></select></div><div class="form-group"><label for="char2Age">年龄</label><input type="number" id="char2Age" min="0" max="999" placeholder="无"></div><div class="form-group full-width"><label for="char2Appearance">身材外貌</label><textarea id="char2Appearance" rows="2" placeholder="例如：身高170cm，身材火辣，C杯蜜桃臀，金色波浪卷..."></textarea></div><div class="form-group full-width"><label for="char2Persona">详细人设</label><textarea id="char2Persona" rows="3" placeholder="例如：职业：夜店舞女；穿着：暴露舞衣；性格：风情万种..."></textarea></div></div></details><details class="collapsible-section"><summary class="collapsible-header">定制角色3信息</summary><div class="collapsible-content form-row"><div class="form-group full-width"><label for="char3Name">姓名</label><input type="text" id="char3Name" placeholder="例如：阿奴"></div><div class="form-group"><label for="char3Gender">性别</label><select id="char3Gender"><option value="">无</option><option value="男">男</option><option value="女">女</option><option value="双性">双性</option><option value="其他">其他</option></select></div><div class="form-group"><label for="char3Age">年龄</label><input type="number" id="char3Age" min="0" max="999" placeholder="无"></div><div class="form-group full-width"><label for="char3Appearance">身材外貌</label><textarea id="char3Appearance" rows="2" placeholder="例如：身高180cm，肌肉发达，寸头，脸上有刀疤..."></textarea></div><div class="form-group full-width"><label for="char3Persona">详细人设</label><textarea id="char3Persona" rows="3" placeholder="例如：职业：黑帮老大；穿着：黑色皮夹克；性格：残暴冷酷，占有欲强..."></textarea></div></div></details></div></details><details id="mod-section" class="collapsible-section"><summary class="collapsible-header">MOD制作工坊</summary><div class="collapsible-content"><div class="form-group full-width"><label for="modName">MOD名称 (必须是英文/拼音, 无空格)</label><input type="text" id="modName" placeholder="例如: ExtraAbilities"></div><div class="form-group full-width"><label for="modContent">MOD内容</label><textarea id="modContent" rows="5" placeholder="在此输入你的MOD指令或设定..."></textarea></div><div class="button-group"><button type="button" class="action-btn generate-btn" id="previewModBtn">预览并准备复制MOD</button></div></div></details></form><div class="button-group"><button class="action-btn generate-btn" id="generateBtn">生成故事设定</button><button class="action-btn reset-btn" id="resetBtn" type="button">一键重置</button></div></div></div><div id="previewModal"><div class="modal-content"><h3 id="previewTitle">故事设定预览</h3><div id="previewContent"></div><div class="preview-buttons"><button class="confirm-btn" id="confirmCopyBtn">复制设定</button><button class="return-btn" id="returnEditBtn">返回修改</button></div></div></div><div id="modInstructionModal"><div class="modal-content" style="border-color: var(--info-border); box-shadow: 0 0 30px rgba(52, 152, 219, 0.5);"><h3 style="color: var(--info-border);">MOD复制成功！</h3><p style="text-align: center; font-size: 1.1em; margin: 20px 0;">请点击右上角设置→自定义配置→提示词，进行粘贴保存，即成功加载MOD。</p><div class="preview-buttons"><button class="return-btn" id="closeInstructionBtn">关闭</button></div></div></div><script>document.addEventListener(''DOMContentLoaded'', () => {const getEl = (id) => document.getElementById(id);const mainContainer = getEl(''mainContainer'');const quickNav = getEl(''quickNav'');const previewModal = getEl(''previewModal'');const modInstructionModal = getEl(''modInstructionModal'');const previewTitle = getEl(''previewTitle'');const previewContent = getEl(''previewContent'');const confirmCopyBtn = getEl(''confirmCopyBtn'');const returnEditBtn = getEl(''returnEditBtn'');function showToast(message, duration = 3000) {const toastContainer = getEl(''toast-container'');const toast = document.createElement(''div'');toast.className = ''toast'';toast.textContent = message;toastContainer.appendChild(toast);setTimeout(() => { toast.classList.add(''show''); }, 10);setTimeout(() => {toast.classList.remove(''show'');toast.addEventListener(''transitionend'', () => toast.remove());}, duration);}
function performCopy(text) {const tempTextarea = document.createElement(''textarea'');tempTextarea.value = text;tempTextarea.style.position = ''fixed'';tempTextarea.style.opacity = ''0'';document.body.appendChild(tempTextarea);tempTextarea.select();tempTextarea.setSelectionRange(0, 99999);try {document.execCommand(''copy'');return true;} catch (err) {console.error(''复制失败:'', err);return false;} finally {document.body.removeChild(tempTextarea);}}
function openStoryPreview() {previewModal.dataset.mode = ''story'';previewTitle.textContent = ''故事设定预览'';confirmCopyBtn.textContent = ''复制设定'';returnEditBtn.textContent = ''返回修改'';const protagonist = {name: getEl(''protagonistName'').value, gender: getEl(''protagonistGender'').value, age: getEl(''protagonistAge'').value,appearance: getEl(''protagonistAppearance'').value, persona: getEl(''protagonistPersona'').value, power: getEl(''protagonistPower'').value};const worldInfo = getEl(''worldInfo'').value;const creationNeeds = { scene: getEl(''scene'').value, event: getEl(''event'').value, specialRequirements: getEl(''specialRequirements'').value };const orientations = Array.from(document.querySelectorAll(''.orientation-style:checked'')).map(el => el.value);const povs = [];if (getEl(''povFirst'').checked) povs.push(''第一人称'');if (getEl(''povSecond'').checked) povs.push(''第二人称'');if (getEl(''povThird'').checked) povs.push(''第三人称'');const writingStyles = Array.from(document.querySelectorAll(''.writing-style:checked'')).map(el => el.value);const chars = [];for (let i = 1; i <= 3; i++) {const charName = getEl(`char${i}Name`).value; const charGender = getEl(`char${i}Gender`).value;if (charName || charGender) {chars.push({name: charName, gender: charGender, age: getEl(`char${i}Age`).value,appearance: getEl(`char${i}Appearance`).value, persona: getEl(`char${i}Persona`).value});}}
let previewText = `肉文助手V3.2：一个根据用户需求生成小说的工具。\n--- 创作风格与视角 ---\n创作性向：${orientations.length > 0 %s orientations.join('', '') : ''未选择''}\n叙事视角：${povs.length > 0 %s povs.join('', '') : ''未选择''}\n小说文风：${writingStyles.length > 0 %s writingStyles.join('', '') : ''未选择''}\n`;if (worldInfo) { previewText += `--- 世界观设定 ---\n${worldInfo}\n`; }
previewText += `--- 主角信息 ---\n姓名：${protagonist.name || ''未填写''}\n性别：${protagonist.gender || ''未填写''}\n年龄：${protagonist.age || ''未填写''}\n身材外貌：${protagonist.appearance || ''无''}\n详细人设：${protagonist.persona || ''无''}\n外挂/金手指：${protagonist.power || ''无''}\n`;previewText += `--- 创作需求 ---\n创作场景：${creationNeeds.scene || ''无''}\n创作事件：${creationNeeds.event || ''无''}\n特殊需求/XP：${creationNeeds.specialRequirements || ''无''}\n`;if (chars.length > 0) {previewText += `--- 定制角色信息 ---\n`;chars.forEach((char, index) => {previewText += `角色${index + 1}：姓名：${char.name || ''无''}, 性别：${char.gender || ''无''}, 年龄：${char.age || ''无''}, 身材外貌：${char.appearance || ''无''}, 详细人设：${char.persona || ''无''}\n`;});}
previewContent.textContent = previewText.trim();previewModal.style.display = ''flex'';}
function openModPreview() {const modName = getEl(''modName'').value.trim();const modContent = getEl(''modContent'').value.trim();if (!modName || !modContent) { showToast(''MOD名称和内容不能为空！'', 2000); return; }
previewModal.dataset.mode = ''mod'';previewTitle.textContent = ''MOD 预览'';confirmCopyBtn.textContent = ''复制MOD'';returnEditBtn.textContent = ''关闭'';const formattedMod = `<MOD_${modName}>${modContent}</MOD_${modName}>`;previewContent.textContent = formattedMod;previewModal.style.display = ''flex'';}
confirmCopyBtn.addEventListener(''click'', () => {const mode = previewModal.dataset.mode;const textToCopy = previewContent.textContent;if (!textToCopy) return;if (performCopy(textToCopy)) {previewModal.style.display = ''none'';if (mode === ''mod'') {modInstructionModal.style.display = ''flex'';} else {showToast(''故事设定已成功复制！'');}} else {showToast(''复制失败，浏览器可能不支持此操作。'');}});getEl(''generateBtn'').addEventListener(''click'', openStoryPreview);getEl(''previewModBtn'').addEventListener(''click'', openModPreview);getEl(''resetBtn'').addEventListener(''click'', () => { getEl(''story-form'').reset(); showToast(''所有设定已清空！'', 2000); });const closeModal = () => {previewModal.style.display = ''none'';};returnEditBtn.addEventListener(''click'', closeModal);previewModal.addEventListener(''click'', (e) => { if (e.target === previewModal) closeModal(); });getEl(''closeInstructionBtn'').addEventListener(''click'', () => { modInstructionModal.style.display = ''none''; });getEl(''closeNavBtn'').addEventListener(''click'', () => { quickNav.classList.add(''hidden''); });document.querySelectorAll(''.quick-nav a'').forEach(anchor => {anchor.addEventListener(''click'', function (e) {e.preventDefault();const targetId = this.getAttribute(''href'');const targetElement = document.querySelector(targetId);if (targetElement && mainContainer) {const containerRect = mainContainer.getBoundingClientRect();const targetRect = targetElement.getBoundingClientRect();const scrollTop = mainContainer.scrollTop;const offset = targetRect.top - containerRect.top - 20;mainContainer.scrollTo({ top: offset, behavior: ''smooth'' });}});});});</script></body></html>', '已破甲', '2026-10-11 11:21:08', '2026-10-11 11:21:08', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_rent_apartment', '交不起房租就要被肏的肉偿公寓', '极乐领地 · 绝对主宰', '🏢', '肉偿公寓', '肉体是唯一的硬通货', '🏢', '#e11d48', 'linear-gradient(135deg, #e11d48 0%, #9f1239 100%)', '{"desc": "继承了城市边缘的一栋公寓成为绝对主宰。租客全都是穷女人：301室38岁极品熟女苏玉兰与18岁太妹女儿苏小雅、202室三个精神小妹、401室漫展高冷底层Coser。肉体是唯一的硬通货。", "author": "醉花阴墓"}', '[{"name": "苏玉兰", "role": "38岁极品成熟人妻", "desc": "H罩杯丰腴身材，为了躲避家暴丈夫带着女儿逃到这里身无分文，怯弱温顺"}, {"name": "苏小雅", "role": "18岁太妹女儿", "desc": "染金发、嘴硬傲娇，暗藏无助，对母亲的软弱嗤之以鼻"}, {"name": "精神小妹三人组", "role": "202室租客", "desc": "浓妆假睫毛超短裙，天天出去蹦迪，拖欠三个月房租"}, {"name": "底层Coser双人组", "role": "401室租客", "desc": "漫展上被无数摄影师围拍的性感女神，私下连水电费都交不起"}]', '[{"title": "公寓昏暗走廊", "desc": "锈迹斑斑的防盗门，幽暗的声控灯与握着万能钥匙的主角"}, {"title": "301室 苏家母女房", "desc": "简陋破旧的布沙发，散落的旧行李，弥漫着熟女体香与廉价洗衣粉气息"}, {"title": "202室 精神小妹房", "desc": "满地易拉罐与荧光假发，混杂着香水与烟味"}, {"title": "401室 Coser秘密基地", "desc": "挂满华丽C服与假发的更衣架，落地更衣镜"}]', '{}', '{"story": "月底的夜风带着几分沉闷的燥热，老旧公寓狭长的走廊里，只有几盏昏黄闪烁的声控灯在勉强亮着。\n你手里转动着整栋楼的万能钥匙串，金属碰撞发出清脆的声响。在这里，你是这栋楼唯一的房东与绝对主宰。租期已到，房租单上密密麻麻拖欠的记录清晰可见。\n你停在301室的门前，敲响了房门。片刻后，房门战战兢兢地拉开了一条缝隙——38岁的苏玉兰穿着略显褪色的宽大家居裙，却掩盖不住那对沉甸甸的H罩杯巨乳与丰满臀线。而在她身后，18岁的女儿苏小雅正叼着根未点燃的细烟，双臂抱胸靠在破旧鞋柜旁，神色倔强又带着慌乱。\n“房东先生……您、您怎么这个时候来了……”苏玉兰眼神躲闪，双手不安地攥紧围裙。", "branches": [{"tag": "A", "title": "手持催租单步入301室直接反锁房门", "desc": "迈步跨进狭窄的门厅顺势带上房门反锁，居高临下直视这对局促不安的母女"}, {"tag": "B", "title": "冷声质问苏玉兰并审视她颤抖的身躯", "desc": "将拖欠三个月的账单拍在鞋柜上，冷声追问苏玉兰今晚打算拿什么来清账"}, {"tag": "C", "title": "挑眉打量门口叼烟冷笑的叛逆女儿苏小雅", "desc": "伸手夹走苏小雅嘴角的细烟，凑近她耳边打趣这位不良少女此刻发抖的指尖"}, {"tag": "D", "title": "挑明肉偿规则逼迫母女当面做出抉择", "desc": "坐在唯一的旧沙发上翘起二郎腿：“交不起钱没关系，这栋楼里，肉体也是硬通货。”"}], "location": "城市边缘旧式公寓 · 301室门厅"}', NULL, '<!DOCTYPE html>
