INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_xiuxian_world', '从零开始的修仙日常', '高自由度修仙 · 苍澜界', '⚔️', '从零开始的修仙日常', 'roll天赋·大世界·开放探索', 'https://catai.wiki/db5174e8-79b6-4fcc-a931-776ee4351000/cover', 'bg-slate-900/90 text-sky-200 border-sky-600/50', 'from-cyan-600 to-blue-700', '{"title": "【roll天赋/大世界，可bg,bl,gb,gl】从零开始的修仙日常", "desc": "欢迎来到最真实的修仙世界！这里你可以体验抽灵根，roll天赋，还可以从凡人开始修仙（也可以开局直接当大佬），众多门派任你挑选，正派反派随你选择，当人还是当妖还是当魔修可以，超高自由度！内置二十几个NPC任你挑选，可bg可bl可gb可gl\n\n", "bg_image": "https://free.picui.cn/free/2025/12/01/692c8049eabb9.jpg", "opening_options": ["今天是百年难得一遇的中州宗门统一开放招收弟子的日子……", "这是你们宗门招收弟子的日子，你作为长老理应前往……", "（自定义开场白）", "（输入“开启灵网”打开论坛，输入“关闭灵网”关闭论坛）"]}', '[{"name": "君亦尘", "role": "昆仑宗掌门", "desc": "外貌三十许岁，面如冠玉，紫金道袍。性格沉稳内敛，心怀天下苍生，行事公正严明，实则是位操心的“老父亲”。"}, {"name": "萧寒衣", "role": "天剑门剑首", "desc": "胜雪白衣，衣角带陈旧血梅，背负麻布缠裹古剑。极度沉默寡言，纯粹的剑痴，战力惊世。"}, {"name": "叶倾城", "role": "昆仑宗首席", "desc": "肌肤胜雪，万年玄冰雕琢般的玉人，素白长裙。极度高冷孤傲，一心向道的修炼狂魔。"}, {"name": "魅姬", "role": "合欢宗宗主", "desc": "清纯与妖艳交织，紫裙赤足，脚踝系红绳金铃。随心所欲玩弄人心，视天下男子为玩物却从未动情。"}, {"name": "温如玉", "role": "青囊药谷谷主", "desc": "面若冠玉，双目覆素白绫缎，浅青宽袖长衫。温和宽厚彬彬有礼，心眼通透能洞察人心。"}, {"name": "君无邪", "role": "天魔教教主", "desc": "魔道第一美男，左金右黑摄人异瞳，暗金魔纹黑皇袍。狂傲霸道智多近妖，立志颠覆修仙界的枭雄。"}]', '[{"title": "中州太白峰下 · 问仙大会 · 宗门招徒大典", "desc": "巍峨磅礴的昆仑仙山直插云霄，太白峰下云海翻涌，瑞气千条。百年难得一遇的中州宗门统一大典今日正式开启，各大正派魁首、中立世家、散修翘楚云集于此。测灵石柱在广场中央耸立，散发出变幻莫测的灵光。各派长老与亲传弟子高踞玉台，审视着台下前赴后继的求道者。天地灵气浩荡激荡，风云变幻，属于你的修仙纪元正在揭开帷幕……"}]', '{"dialogue_style": "修仙沉浸小说笔调，兼顾仙侠意境、人物心机推拉、道法摩擦与感官张力", "format": "AI风月标准双栏规范及.xiuxian-ui样式"}', '[{"index": 1, "isUser": false, "scene": "中州太白峰下 · 问仙大会 · 宗门招徒大典", "story": "<tl>📅时间：大典吉时 | 🌏世界：苍澜界 | 🏘️场所：中州太白峰下·问仙灵台</tl>\n\n<article>\n<p>巍峨直插入天穹的太白峰下，翻滚的七彩霞云如同怒浪翻腾。数以万计的求道者自九州四海跋涉而来，将整座白玉广场围得水泄不通。天际不时有划破虚空的凌厉剑光与华贵云舟飞掠而过，引来阵阵惊叹与抽气声。</p>\n\n<p>“肃静——！”</p>\n\n<p>天剑门长老洛崇珩声若奔雷，浑厚的灵压自高空垂落，瞬息压制全场喧哗。广场正中央，九根雕刻着上古真龙与玄武的测灵石柱陡然轰鸣，幽蓝、赤金与青翠的玄光在石柱纹路中疯狂游走。玉台之上，正道首座昆仑宗掌门君亦尘神色威严温和，天剑门剑首萧寒衣抱剑闭目不语，合欢宗妖娆妩媚的魅姬则掩唇轻笑，一双桃花眼饶有兴致地打量着台下神态各异的年轻人。</p>\n\n<p><w>“若有身怀绝顶灵根或天生剑骨者，本门绝不吝赐下亲传令羽。”</w></p>\n\n<p>台下人群之中，你深吸了一口气，掌心微微沁出薄汗。周围人的目光或期盼、或嫉妒、或警惕，所有人都在等待着你登上测灵台的那一刻。</p>\n<p><thk>台上的各大宗门长老与暗中隐匿的魔修密探都在不动声色地注视着走上前台的每一个苗子，暗自盘算着此人的根骨与未来的道途价值……</thk></p>\n</article>\n\n<opt>\n<suggested_questions>\n<d>A. 【稳步登台测灵】：神色自若迈上测灵白玉台，将手掌贴向九龙测灵柱，毫无保留地展现自身灵根底蕴【策略评估：引动全场异象，直接成为各大顶级宗门争夺的热门天骄】</d>\n<d>B. 【收敛隐匿锋芒】：暗中运转独门匿气法门压制灵压，只展露出平平无奇的双灵根资质【策略评估：藏木于林，避免成为众矢之的，为暗中行事提供掩护】</d>\n<d>C. 【直面魔宗使者】：将目光投向广场角落戴着兜帽的血煞宗或万毒窟使者，传递桀骜不驯的魔道意志【策略评估：脱离正道桎梏，开启凶险莫测、快意恩仇的魔道修仙路】</d>\n<d>D. 【开启灵网玉简】：从怀中取出万宝楼特制的水晶玉简，轻唤“开启灵网”查看全大陆最新八卦与实时宗门招收内幕【策略评估：解锁修仙界互联网论坛模式，搜集情报与修仙道友灌水】</d>\n</suggested_questions>\n</opt>", "branches": [{"tag": "A", "title": "稳步登台展现灵根底蕴", "desc": "迈上测灵白玉台，将手掌贴向九龙测灵柱，引动全场异象"}, {"tag": "B", "title": "收敛隐匿锋芒暗藏底牌", "desc": "暗中运转匿气法门压制灵压，只展现中庸资质，藏木于林"}, {"tag": "C", "title": "直面暗处魔宗试探底线", "desc": "将视线投向边缘魔道使者，探寻非正统道途的别样可能"}, {"tag": "D", "title": "开启灵网玉简搜集情报", "desc": "取出通讯玉简输入“开启灵网”，阅览修仙界论坛热帖与道友议论"}]}]', '/* === 修仙 UI 基础框架 (已完美适配您的模板，去除灵网并格式化) === */

.xiuxian-ui {
    font-family: "KaiTi", "STKaiti", serif;
    background: #f5f7fa url("data:image/svg+xml,%3Csvg width=''64'' height=''64'' viewBox=''0 0 64 64'' xmlns=''http://www.w3.org/2000/svg''%3E%3Cpath d=''M8 16c4.418 0 8-3.582 8-8s-3.582-8-8-8-8 3.582-8 8 3.582 8 8 8zm0-2c3.314 0 6-2.686 6-6s-2.686-6-6-6-6 2.686-6 6 2.686 6 6 6zm33.414-6l5.95-5.95L45.95.636 40 6.586 34.05.636 32.636 2.05 38.586 8l-5.95 5.95 1.414 1.414L40 9.414l5.95 5.95 1.414-1.414L41.414 8zM40 48c4.418 0 8-3.582 8-8s-3.582-8-8-8-8 3.582-8 8 3.582 8 8 8zm0-2c3.314 0 6-2.686 6-6s-2.686-6-6-6-6 2.686-6 6 2.686 6 6 6zM9.414 40l5.95-5.95-1.414-1.414L8 38.586l-5.95-5.95L.636 34.05 6.586 40l-5.95 5.95 1.414 1.414L8 41.414l5.95 5.95 1.414-1.414L9.414 40z'' fill=''%23b0bec5'' fill-opacity=''0.15'' fill-rule=''evenodd''/%3E%3C/svg%3E");
    color: #455a64 !important;
    padding: 15px;
    border: 1px solid #90a4ae;
    border-radius: 5px;
    box-shadow: 0 0 20px rgba(120,144,156,0.15);
    line-height: 1.6;
    max-width: 800px;
    margin: 0 auto;
}

/* 1: 场景信息 */
.xx-header { border-bottom: 1px solid #cfd8dc; padding-bottom: 8px; margin-bottom: 15px; display: flex; flex-wrap: wrap; gap: 8px; }
.xx-tag { background: rgba(236,240,241,0.6); color: #546e7a !important; padding: 2px 6px; border-radius: 3px; font-size: 0.9em; border: 1px solid #cfd8dc; }
.xx-cause { width: 100%; margin-top: 5px; font-style: italic; color: #78909c !important; border-left: 3px solid #78909c; padding-left: 6px; }

/* 2: 故事正文 */
.xx-content { text-indent: 2em; margin-bottom: 20px; font-size: 1.05em; text-align: justify; color: #37474f !important; }

/* 3: 心声模块 */
.xx-voice-box { background: rgba(236,240,241,0.4); border: 1px dashed #b0bec5; padding: 10px; border-radius: 6px; margin-bottom: 15px; position: relative; }
.xx-voice-title { text-align: center; color: #5c6bc0 !important; font-weight: bold; font-size: 0.9em; margin-bottom: 5px; letter-spacing: 1px; }
.xx-voice-list { display: flex; flex-direction: column; gap: 4px; font-size: 0.9em; }
.xx-v-user { color: #00838f !important; }
.xx-v-npc { color: #5c6bc0 !important; }
.xx-v-sys { color: #78909c !important; font-style: italic; }

/* 4 & 5: 面板通用 (道友信息 & 肉身状态) */
.xx-panel { margin-bottom: 10px; border: 1px solid #cfd8dc; background: rgba(255,255,255,0.7); border-radius: 4px; overflow: hidden; }
.xx-sum { background: #eceff1; padding: 8px; cursor: pointer; font-weight: bold; color: #546e7a !important; list-style: none; outline: none; border-bottom: 1px solid #cfd8dc; }
.xx-sum::-webkit-details-marker { display: none; }
.xx-sum::after { content: "▼"; float: right; color: #90a4ae; font-size: 0.8em; }
details[open] > .xx-sum::after { content: "▲"; }
.xx-info-box { padding: 12px; font-size: 0.9em; color: #546e7a !important; }
.xx-row { border-bottom: 1px dashed #cfd8dc; padding: 4px 0; }
.xx-sep { color: #b0bec5; margin: 0 5px; }

/* 修为进度条 */
.xx-bar-bg { display: inline-block; width: 100px; height: 8px; background: #eceff1; border-radius: 4px; overflow: hidden; vertical-align: middle; margin-right: 5px; }
.xx-bar-fg { display: block; height: 100%; background: #81d4fa; background-image: linear-gradient(45deg,rgba(255,255,255,0.2) 25%,transparent 25%,transparent 50%,rgba(255,255,255,0.2) 50%,rgba(255,255,255,0.2) 75%,transparent 75%,transparent); background-size: 10px 10px; }

/* 详情块 (功法、招式、法宝等) */
.xx-block { margin-top: 8px; }
.xx-block strong { color: #5c6bc0 !important; }
.xx-block p { margin: 4px 0 4px 12px !important; color: #607d8b !important; font-size: 0.95em; }

/* 角色属性区域 */
.xx-char-section { margin-bottom: 10px; }
.xx-char-name { font-weight: bold; color: #455a64 !important; font-size: 1.1em; border-left: 4px solid #78909c; padding-left: 8px; margin-bottom: 6px; background: linear-gradient(90deg,rgba(120,144,156,0.1),transparent); }
.xx-char-section p { margin: 4px 0; line-height: 1.4; }
.xx-char-section p:first-of-type strong { color: #e91e63 !important; }
.xx-divider { border: 0; height: 1px; background-image: linear-gradient(to right,rgba(0,0,0,0),rgba(120,144,156,0.3),rgba(0,0,0,0)); margin: 15px 0; }

/* 🔞 肉身私密板块 */
.xx-sex-part { background: #eceff1; border: 1px solid #cfd8dc; border-radius: 4px; padding: 8px; margin-top: 6px; }
.xx-sex-title { color: #5c6bc0 !important; font-weight: bold; margin-bottom: 4px; font-size: 0.9em; }

/* 7: 记忆模块 */
.memory-section { margin-bottom: 10px; border: 1px solid #cfd8dc; background: rgba(255,255,255,0.7); border-radius: 4px; overflow: hidden; }
.section-summary { background: #eceff1; padding: 8px; cursor: pointer; font-weight: bold; color: #546e7a !important; list-style: none; outline: none; border-bottom: 1px solid #cfd8dc; display: flex; align-items: center; }
.section-summary::-webkit-details-marker { display: none; }
.section-summary::after { content: "▼"; margin-left: auto; color: #90a4ae; font-size: 0.8em; }
details[open] > .section-summary::after { content: "▲"; }
.sum-icon { margin-right: 8px; }
.mem-count { font-size: 0.85em; font-weight: normal; opacity: 0.8; margin-left: 8px; }
.memory-content { padding: 10px; display: flex; flex-direction: column; gap: 15px; }
.mem-title { font-size: 0.9em; font-weight: bold; color: #5c6bc0 !important; text-align: center; margin-bottom: 8px; padding: 4px; background: rgba(92,107,192,0.05); border-radius: 4px; }
.table-wrap { width: 100%; overflow-x: auto; }
.mem-table { width: 100%; border-collapse: collapse; font-size: 0.85em; min-width: 400px; }
.mem-table th { background: #f0f2f5; color: #455a64; padding: 6px; border: 1px solid #cfd8dc; text-align: left; }
.mem-table td { padding: 6px; border: 1px solid #cfd8dc; color: #546e7a !important; line-height: 1.4; }
.mem-table tr:nth-child(even) { background: rgba(236,240,241,0.3); }

/* 8: 玩家选项 */
.xx-choice-box { margin-top: 20px; background: rgba(236,240,241,0.5); padding: 15px; border-radius: 6px; border: 1px solid #b0bec5; }
.xx-c-title { font-weight: bold; margin-bottom: 8px; color: #78909c !important; }
.xx-btn { background: rgba(255,255,255,0.8); border: 1px solid #b0bec5; padding: 6px 10px; margin: 4px 0; border-radius: 3px; cursor: pointer; transition: 0.2s; color: #546e7a !important; }
.xx-btn:hover { background: #78909c; color: #fff !important; border-color: #78909c; transform: translateX(3px); }
.xx-diy { border-style: dashed; color: #90a4ae !important; }


/* ========================================== */
/* === 附加美化：雾霾蓝修仙气泡与全局样式 === */
/* ========================================== */

/* 基础气泡样式 (日间模式) */
.group.relative.ml-2 .relative.inline-block,
.group.relative.ml-4 .relative.inline-block,
.chat-answer-container .relative.inline-block,
.flex .relative.inline-block {
    background-color: rgba(240, 242, 245, 0.85) !important; 
    background-image: none !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    color: #2b2b2b !important; 
    border: 1.5px solid #b0bec5 !important;
    border-radius: 20px 8px 20px 8px !important;
    padding: 18px 22px !important;
    margin: 14px 0 !important;
    position: relative !important;
    font-family: "KaiTi", "STKaiti", "Microsoft YaHei", serif !important;
    line-height: 1.6 !important;
    box-shadow: 
        0 8px 32px rgba(176, 190, 197, 0.15),
        0 4px 16px rgba(207, 216, 220, 0.2),
        0 0 20px rgba(255, 255, 255, 0.3),
        inset 0 0 0 1px rgba(255, 255, 255, 0.4) !important;
    transform: none !important;
    transition: all 0.3s ease !important;
    overflow: hidden !important;
}

/* 去除云纹渐变，保持纯净磨砂质感 */
.group.relative.ml-2 .relative.inline-block::before,
.group.relative.ml-4 .relative.inline-block::before,
.chat-answer-container .relative.inline-block::before,
.flex .relative.inline-block::before {
    display: none !important;
}

/* 右上角装饰 - ☁ 云纹符号 */
.group.relative.ml-2 .relative.inline-block::after,
.group.relative.ml-4 .relative.inline-block::after,
.chat-answer-container .relative.inline-block::after,
.flex .relative.inline-block::after {
    content: "☁" !important;
    position: absolute !important;
    top: -15px !important;
    right: -5px !important;
    font-size: 80px !important;
    color: rgba(144, 164, 174, 0.1) !important;
    z-index: 1 !important;
    pointer-events: none !important;
    text-shadow: 0 0 20px rgba(255, 255, 255, 0.5) !important;
    line-height: 1 !important;
    transform: rotate(-10deg) !important;
}

/* 确保内容在云纹之上 */
.group.relative.ml-2 .relative.inline-block .markdown-body,
.group.relative.ml-4 .relative.inline-block .markdown-body,
.chat-answer-container .relative.inline-block .markdown-body,
.flex .relative.inline-block .markdown-body {
    position: relative !important;
    z-index: 2 !important;
    color: inherit !important; 
}

/* 气泡边框虚线与流光 */
.group.relative.ml-2 .relative.inline-block,
.group.relative.ml-4 .relative.inline-block,
.chat-answer-container .relative.inline-block,
.flex .relative.inline-block {
    border-left: 2px dashed rgba(176, 190, 197, 0.6) !important;
    border-bottom: 2px dashed rgba(176, 190, 197, 0.6) !important;
    border-top: 1.5px solid #b0bec5 !important;
    border-right: 1.5px solid #b0bec5 !important;
}
.group.relative.ml-2 .relative.inline-block .absolute.top-0,
.group.relative.ml-4 .relative.inline-block .absolute.top-0,
.chat-answer-container .relative.inline-block .absolute.top-0,
.flex .relative.inline-block .absolute.top-0 {
    background: linear-gradient(90deg, transparent, #90a4ae, #eceff1, #90a4ae, transparent) !important;
    height: 2px !important;
    border-radius: 2px !important;
    box-shadow: 0 0 8px rgba(144, 164, 174, 0.5) !important;
}

/* 夜间模式适配 (Dark Mode) */
@media (prefers-color-scheme: dark) {
    .group.relative.ml-2 .relative.inline-block,
    .group.relative.ml-4 .relative.inline-block,
    .chat-answer-container .relative.inline-block,
    .flex .relative.inline-block {
        background-color: rgba(45, 51, 54, 0.85) !important; 
        backdrop-filter: blur(12px) !important;
        -webkit-backdrop-filter: blur(12px) !important;
        color: #2b2b2b !important; 
        border-color: #546e7a !important; 
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2), 0 4px 16px rgba(0, 0, 0, 0.1), 0 0 20px rgba(144, 164, 174, 0.05), inset 0 0 0 1px rgba(255, 255, 255, 0.05) !important;
    }
    .group.relative.ml-2 .relative.inline-block::after,
    .group.relative.ml-4 .relative.inline-block::after,
    .chat-answer-container .relative.inline-block::after,
    .flex .relative.inline-block::after { color: rgba(255, 255, 255, 0.02) !important; text-shadow: 0 0 20px rgba(255, 255, 255, 0.05) !important; }
    .group.relative.ml-2 .relative.inline-block,
    .group.relative.ml-4 .relative.inline-block,
    .chat-answer-container .relative.inline-block,
    .flex .relative.inline-block { border-left: 2px dashed rgba(84, 110, 122, 0.6) !important; border-bottom: 2px dashed rgba(84, 110, 122, 0.6) !important; }
    .group.relative.ml-2 .relative.inline-block .absolute.top-0,
    .group.relative.ml-4 .relative.inline-block .absolute.top-0,
    .chat-answer-container .relative.inline-block .absolute.top-0,
    .flex .relative.inline-block .absolute.top-0 { background: linear-gradient(90deg, transparent, #546e7a, #90a4ae, #546e7a, transparent) !important; box-shadow: 0 0 8px rgba(84, 110, 122, 0.5) !important; }
}

/* 雾霾蓝丹药风格按钮 */
.MuiButtonBase-root.MuiButton-root, button[class*="choice"], button[class*="button"], .btn, .button, .choice-btn, .MuiButton-root.MuiButton-outlined, .MuiButton-root.MuiButton-text {
    background: radial-gradient(circle at 30% 30%, rgba(236, 239, 241, 0.95) 0%, rgba(207, 216, 220, 0.9) 100%) !important;
    color: #546e7a !important;
    border: 1px solid #cfd8dc !important;
    border-radius: 40px !important;
    padding: 6px 14px !important;
    margin: 2px !important;
    font-family: "KaiTi", "Microsoft YaHei", sans-serif !important;
    font-weight: 600 !important;
    font-size: 12px !important;
    box-shadow: 0 4px 10px rgba(176, 190, 197, 0.3), inset 0 0 10px rgba(255, 255, 255, 0.8) !important;
    transform: none !important;
    transition: all 0.3s ease !important;
    position: relative !important;
    min-width: 70px !important;
    overflow: hidden !important;
}
.MuiButtonBase-root.MuiButton-root:hover, button[class*="choice"]:hover, button[class*="button"]:hover, .btn:hover, .button:hover, .choice-btn:hover {
    background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 1) 0%, rgba(236, 239, 241, 0.95) 100%) !important;
    color: #37474f !important;
    border-color: #90a4ae !important;
    box-shadow: 0 6px 15px rgba(176, 190, 197, 0.5), 0 0 10px rgba(144, 164, 174, 0.2), inset 0 0 15px rgba(255, 255, 255, 0.9) !important;
    transform: translateY(-2px) scale(1.03) !important;
}

/* Markdown 内容文本样式 */
.markdown-body p { color: #2b2b2b !important; }
.markdown-body strong { color: #1a1a1a !important; font-weight: 600 !important; }
.markdown-body em { color: #2b2b2b !important; font-style: italic !important; }

/* 输入框设计 - 宣纸质感 */
input[type="text"], textarea, input[type="password"] {
    background: rgba(255, 255, 255, 0.8) !important;
    color: #455a64 !important;
    border: 1.5px solid #cfd8dc !important;
    border-radius: 8px !important;
    padding: 12px 16px !important;
    font-family: "KaiTi", "Microsoft YaHei", serif !important;
    box-shadow: inset 0 0 10px rgba(176, 190, 197, 0.1) !important;
    backdrop-filter: blur(5px) !important;
}
input[type="text"]:focus, textarea:focus { outline: none !important; border-color: #90a4ae !important; box-shadow: inset 0 0 10px rgba(176, 190, 197, 0.2), 0 0 15px rgba(144, 164, 174, 0.2) !important; background: rgba(255, 255, 255, 0.95) !important; }

/* ☁️ 修仙主题加载动画 - 天机推演 */
.flex.items-center.justify-center.w-6.h-5 { width: auto !important; height: auto !important; min-width: 180px !important; padding: 12px 20px !important; background: linear-gradient(135deg, #eceff1 0%, #cfd8dc 100%) !important; border: 1px solid #b0bec5 !important; border-radius: 12px !important; box-shadow: 0 6px 20px rgba(176, 190, 197, 0.3), inset 0 0 0 1px rgba(255, 255, 255, 0.5) !important; position: relative !important; font-family: "KaiTi", serif !important; display: flex !important; align-items: center !important; justify-content: center !important; overflow: hidden !important; }
.style_dot-flashing__8L91Q.style_text__zGhNq { display: none !important; }
.flex.items-center.justify-center.w-6.h-5::before { content: "正在推演天机" !important; font-size: 15px !important; color: #546e7a !important; animation: wave-text 6s ease-in-out infinite !important; }
.flex.items-center.justify-center.w-6.h-5::after { content: "……" !important; color: #78909c !important; font-weight: bold !important; animation: wave-dots 5s ease-in-out infinite !important; }

/* 状态栏 (兼容原版) - 雾霾蓝风格 */
.status-container { border: 1px solid #cfd8dc !important; border-radius: 6px !important; margin: 14px 0 !important; background: #f5f7fa !important; box-shadow: 0 4px 15px rgba(176, 190, 197, 0.2) !important; color: #546e7a !important; }
.status-summary { background: #eceff1 !important; color: #455a64 !important; border-bottom: 1px solid #cfd8dc !important; font-family: "KaiTi", serif !important; }
.status-summary::before { content: "✦" !important; color: #90a4ae !important; transform: rotate(0deg) !important; }
.status-container[open] .status-summary::before { transform: rotate(45deg) !important; }
.status-content { background: #fafafa !important; color: #607d8b !important; }
.status-content p { border-left: 2px solid #cfd8dc !important; background: rgba(236, 239, 241, 0.3) !important; color: #546e7a !important; }

/* 动画定义 */
@keyframes wave-text { 0%, 100% { transform: translateY(0); opacity: 0.8; } 50% { transform: translateY(-2px); opacity: 1; } }
@keyframes wave-dots { 0%, 100% { opacity: 0.5; } 50% { opacity: 1; } }

/* 📜 滚动条全域美化 (玉石质感) */
*::-webkit-scrollbar { width: 8px !important; height: 8px !important; background: transparent !important; }
*::-webkit-scrollbar-track { background: rgba(245, 247, 250, 0.5) !important; border-radius: 4px !important; }
*::-webkit-scrollbar-thumb { background-color: #cfd8dc !important; border: 2px solid transparent !important; background-clip: content-box !important; border-radius: 10px !important; box-shadow: inset 0 0 6px rgba(176, 190, 197, 0.3) !important; }
*::-webkit-scrollbar-thumb:hover { background-color: #90a4ae !important; border: 1px solid transparent !important; }
html { scrollbar-width: thin !important; scrollbar-color: #cfd8dc rgba(245, 247, 250, 0.5) !important; }', '<!DOCTYPE html>
