<script>

// ============ Sound System (Protected) ============
let audioCtx = null;
function initAudio() {
    try {
        if (!audioCtx && (window.AudioContext || window.webkitAudioContext)) {
            const AudioCtx = window.AudioContext || window.webkitAudioContext;
            audioCtx = new AudioCtx();
        }
    } catch(e) {
        audioCtx = null;
    }
}

function playSound(type) {
    try {
        if (!audioCtx) initAudio();
        if (!audioCtx) return;
        if (audioCtx.state === ''suspended'') {
            audioCtx.resume().catch(() => {});
        }
        const oscillator = audioCtx.createOscillator();
        const gainNode = audioCtx.createGain();
        oscillator.connect(gainNode);
        gainNode.connect(audioCtx.destination);
        const now = audioCtx.currentTime;
        switch(type) {
            case ''click'':
                oscillator.type = ''sine'';
                oscillator.frequency.setValueAtTime(800, now);
                oscillator.frequency.exponentialRampToValueAtTime(1200, now + 0.05);
                gainNode.gain.setValueAtTime(0.1, now);
                gainNode.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
                oscillator.start(now);
                oscillator.stop(now + 0.1);
                break;
            case ''toggle'':
                oscillator.type = ''sine'';
                oscillator.frequency.setValueAtTime(600, now);
                oscillator.frequency.exponentialRampToValueAtTime(900, now + 0.08);
                gainNode.gain.setValueAtTime(0.08, now);
                gainNode.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
                oscillator.start(now);
                oscillator.stop(now + 0.12);
                break;
            case ''open'':
                oscillator.type = ''triangle'';
                oscillator.frequency.setValueAtTime(400, now);
                oscillator.frequency.exponentialRampToValueAtTime(800, now + 0.1);
                gainNode.gain.setValueAtTime(0.08, now);
                gainNode.gain.exponentialRampToValueAtTime(0.001, now + 0.15);
                oscillator.start(now);
                oscillator.stop(now + 0.15);
                break;
            case ''close'':
                oscillator.type = ''triangle'';
                oscillator.frequency.setValueAtTime(800, now);
                oscillator.frequency.exponentialRampToValueAtTime(400, now + 0.08);
                gainNode.gain.setValueAtTime(0.08, now);
                gainNode.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
                oscillator.start(now);
                oscillator.stop(now + 0.1);
                break;
            case ''success'':
                oscillator.type = ''sine'';
                oscillator.frequency.setValueAtTime(523, now);
                oscillator.frequency.setValueAtTime(659, now + 0.08);
                gainNode.gain.setValueAtTime(0.1, now);
                gainNode.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
                oscillator.start(now);
                oscillator.stop(now + 0.2);
                break;
        }
    } catch(e) {}
}

function createParticles() {
    const container = document.getElementById(''particles'');
    if (!container) return;
    for (let i = 0; i < 15; i++) {
        const particle = document.createElement(''div'');
        particle.className = ''particle'';
        particle.style.left = Math.random() * 100 + ''%'';
        particle.style.animationDuration = (Math.random() * 10 + 10) + ''s'';
        particle.style.animationDelay = (Math.random() * 10) + ''s'';
        particle.style.width = (Math.random() * 4 + 2) + ''px'';
        particle.style.height = particle.style.width;
        particle.style.background = `hsl(${Math.random() * 60 + 280}, 70%, 70%)`;
        container.appendChild(particle);
    }
}
createParticles();

// ============ Character Data ============
// ============ Character Data (Updated Real Avatars) ============
const characterData = {
    ''suxiaoke'': {
