    padding: 8px 14px !important;
    cursor: pointer !important;
    list-style: none !important;
    border-bottom: 1px solid #EBEBEB !important;
    border-radius: 10px 10px 0 0 !important;
    transition: background 0.2s ease !important;
    position: relative !important;
}

.markdown-body details > summary::-webkit-details-marker,
.markdown-body details > summary::marker {
    display: none !important;
    content: "" !important;
}

.markdown-body details > summary::before {
    content: "›" !important;
    margin-right: 8px !important;
    font-size: 14px !important;
    font-weight: 600 !important;
    display: inline-block !important;
    transition: transform 0.2s ease !important;
    color: #999 !important;
}

.markdown-body details[open] > summary::before {
    transform: rotate(90deg) !important;
}

.markdown-body details > summary:hover {
    background: #F0F0F0 !important;
}

/* --- 折叠内容区 --- */
.markdown-body details > *:not(summary) {
    position: relative !important;
    z-index: 1 !important;
}

/* --- 折叠块内代码块无缝贴合 --- */
.markdown-body details > pre {
    margin: 0 !important;
    border: none !important;
    box-shadow: none !important;
}

.markdown-body details > pre > div {
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
}

.markdown-body details > pre > div > div.flex.justify-between.h-8 {
    border-radius: 0 !important;
}

.markdown-body details > pre > div::before {
    display: none !important;
}

.markdown-body details > pre > code[node] {
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
}

/* ============================================
   夜间兜底：不追求美，只保证不刺眼
   ============================================ */

/* 主容器：深底 */
.bg-gray-100\/90.relative.inline-block:is(.dark *) {
    background: #1C1C1E !important;
