INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('087637dd-b4ba-4588-ac91-cd6361d47be0', '🌸全裸女校，只有你是特招', '全裸铁律 · 唯我特招', '🌸', '🌸全裸女校，只有你是特招', '全裸铁律 · 唯我特招', 'https://catai.wiki/4d39b21c-82c1-4986-8feb-1f5a25806e00/cover', 'bg-pink-950/90 text-pink-300 border-pink-600/60', 'from-rose-600 to-purple-600', '{"title": "🌸全裸女校，只有你是特招", "desc": "【超低耗】【全校全裸】【唯一男生】全封闭圣伊甸贵族女子学园，三千名名门千金一丝不挂。因报名系统故障，你作为特招生成为了建校百年唯一的男学生。入校即脱衣——面对全校全裸的绝对铁律，全校只有公共女浴室与女更衣室，面对少女们毫不避讳的目光与生理课老师的热烈研究，你该如何生存与征服？", "bg_image": "https://catai.wiki/6ef5e821-d7db-4a16-808a-a90d95975900/bg"}', '[{"name": "主人公", "desc": "【超低耗】【全校全裸】【唯一男生】全封闭圣伊甸贵族女子学园，三千名名门千金一丝不挂。因报名系统故障，你作为特招生成为了建校百年唯一的男学生。入校即脱衣——面对全校全裸的绝对铁律，全校只有公共女浴室与女更衣室，面对少女们毫不避讳的目光与生理课老师的热烈研究，你该如何生存与征服？", "role_type": "protagonist"}]', '[{"title": "圣伊甸贵族女子学园 · 入学校门强制更衣室 · 上午", "desc": "【超低耗】【全校全裸】【唯一男生】全封闭圣伊甸贵族女子学园，三千名名门千金一丝不挂。因报名系统故障，你作为特招生成为了建校百年唯一的男学生。入校即脱衣——面对全校全裸的绝对铁律，全校只有公共女浴室与女更衣室，面对少女们毫不避讳的目光与生理课老师的热烈研究，你该如何生存与征服？"}]', '{"dialogue_style": "沉浸式感官细节描写，兼顾心理摩擦、禁断张力与高潮爆发", "format": "AI风月标准双栏规范"}', '[{"index": 1, "isUser": false, "scene": "圣伊甸贵族女子学园 · 入学校门强制更衣室 · 上午", "story": "“新生同学，欢迎来到圣伊甸。在这里，身体是唯一的诚实礼仪。”校门旁的更衣室门推开，成熟丰满、一丝不挂的女校长塞西莉亚优雅地端着茶杯注视着你。在她的注视下，你脱下了身上的最后一件衣物。当踏入恒温26℃的林荫校园，走廊与草坪上成百上千名赤身裸体的贵族少女们齐刷刷转过头来，目光聚焦在全校唯一一具男性肉体上，窃窃私语与好奇惊呼此起彼伏……", "branches": [{"tag": "A", "title": "顺应当前情境小心周旋应对", "desc": "保持镇定，仔细观察周遭人物的微表情与防备程度，稳步建立信任关系"}, {"tag": "B", "title": "出人意料反客为主试探底线", "desc": "抓住对方好奇或破防的瞬间，采取大胆主动的行动颠覆攻守局势"}, {"tag": "C", "title": "制造独处私密借口深入交流", "desc": "将关键人物引向更隐秘的角落或私密房间，拉开二人深度交互帷幕"}, {"tag": "D", "title": "直接挑明自身特殊需求与条件", "desc": "打破常规客套，直言不讳地提出极具侵略性与掌控欲的契约规则"}]}]', '/* ========== 全局 ========== */
body,
p,
span,
div,
details,
summary,
td,
th,
li,
blockquote {
    font-size: 16px !important;
    font-family: ''Microsoft YaHei'', ''PingFang SC'', sans-serif !important;
}

/* ===== 对话颜色 ===== */
.player-talk {
    color: #1a73e8 !important;
    font-weight: 500;
}
.npc-talk {
    color: #d63384 !important;
    font-weight: 500;
}

/* ===== 容器基准 ===== */
.w {
    display: block;
    font-family: system-ui, -apple-system, sans-serif;
    font-size: 14px;
    color: #4a2c40;
    line-height: 1.5;
    background: linear-gradient(135deg, #fff0f5 0%, #fef5f9 100%);
    padding: 8px;
    border-radius: 12px;
    box-shadow: 0 4px 15px rgba(255, 126, 179, 0.1);
}

/* ===== 状态面板 (a) ===== */
.w .a {
    display: block;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 126, 179, 0.3);
    border-radius: 8px;
    margin-bottom: 8px;
    overflow: hidden;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
    transition: box-shadow 0.3s ease, border-color 0.3s ease;
}
.w .a[open] {
    box-shadow: 0 6px 16px rgba(255, 117, 140, 0.12);
    border-color: rgba(255, 126, 179, 0.55);
}

/* ===== 师生图鉴 (b) ===== */
.w .b {
    display: block;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 126, 179, 0.3);
    border-radius: 8px;
    margin-bottom: 8px;
    overflow: hidden;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
}

/* ===== 记忆区 (star-memory) ===== */
.w .star-memory {
    display: block;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 126, 179, 0.3);
    border-radius: 8px;
    margin-bottom: 8px;
    overflow: hidden;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
    transition: box-shadow 0.3s ease, border-color 0.3s ease;
}
.w .star-memory[open] {
    box-shadow: 0 6px 16px rgba(255, 117, 140, 0.12);
    border-color: rgba(255, 126, 179, 0.55);
}

/* ===== 隐藏原生三角 ===== */
.w .a summary::-webkit-details-marker,
.w .b summary::-webkit-details-marker,
.w .star-memory summary::-webkit-details-marker,
.w .m summary::-webkit-details-marker {
    display: none;
}
.w .a summary,
.w .b summary,
.w .star-memory summary,
.w .m summary {
    list-style: none;
}

/* ===== 标题通用 ===== */
.w .a summary,
.w .b summary,
.w .star-memory summary {
    cursor: pointer;
    padding: 10px 12px;
    font-weight: 600;
    user-select: none;
    display: flex;
    justify-content: space-between;
    align-items: center;
    transition: background 0.25s ease;
    background: linear-gradient(90deg, rgba(255, 126, 179, 0.13) 0%, rgba(255, 255, 255, 0) 100%);
    color: #d81b60;
    font-size: 15px;
    border-bottom: 1px solid transparent;
}
.w .a[open]>summary,
.w .b[open]>summary,
.w .star-memory[open]>summary {
    border-bottom: 1px solid rgba(255, 126, 179, 0.2);
}

/* ===== 箭头动画 ===== */
.w .a summary::after,
.w .b summary::after,
.w .star-memory summary::after {
    content: "▼";
    font-size: 11px;
    color: #ff758c;
    opacity: 0.7;
    transition: transform 0.3s ease;
    margin-left: 8px;
}
.w .a[open]>summary::after,
.w .b[open]>summary::after,
.w .star-memory[open]>summary::after {
    transform: rotate(180deg);
}

/* ===== Hover ===== */
.w .a summary:hover,
.w .b summary:hover,
.w .star-memory summary:hover {
    background: rgba(255, 126, 179, 0.18);
}

/* ===== 展开动画 ===== */
.w .a[open]>*:not(summary),
.w .b[open]>*:not(summary),
.w .star-memory[open]>*:not(summary) {
    animation: panel-fade-in 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes panel-fade-in {
    0% {
        opacity: 0;
        transform: translateY(-4px);
    }
    100% {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ===== 状态条目容器 ===== */
.w .r {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    margin: 5px 10px;
    background: rgba(255, 255, 255, 0.85);
    border-radius: 6px;
    padding: 4px 0;
    border: 1px solid rgba(255, 126, 179, 0.12);
    transition: background 0.2s ease;
}
.w .r:hover {
    background: rgba(255, 255, 255, 0.96);
}

/* ===== 粉色标签 ===== */
.w .k {
    display: inline-block;
    background: linear-gradient(135deg, #ff7eb3 0%, #ff758c 100%);
    color: white;
    padding: 2px 10px;
    font-size: 12px;
    font-weight: 600;
    border-radius: 4px;
    margin: 0 10px 2px 10px;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
    white-space: nowrap;
}

/* ===== 内容值 ===== */
.w .v {
    display: block;
    padding: 2px 10px 4px 10px;
    font-size: 13px;
    color: #4a2c40;
    width: 100%;
    box-sizing: border-box;
    line-height: 1.6;
    word-wrap: break-word;
    white-space: normal;
}

/* ===== 师生图鉴内部卡片 (m) ===== */
.w .m {
    background: rgba(255, 240, 245, 0.6);
    border-radius: 6px;
    margin: 6px 10px;
    border-left: 3px solid #ff758c;
}
.w .m summary {
    padding: 8px 10px;
    font-size: 13px;
    color: #6a4a5b;
    background: transparent;
    font-weight: 500;
}
.w .mi {
    padding: 6px 10px;
    margin: 4px 6px 8px 6px;
    background: rgba(255, 255, 255, 0.5);
    border-radius: 4px;
    font-size: 13px;
    color: #553a4b;
    line-height: 1.6;
}

/* ===== 记忆区内层 details ===== */
.w .star-memory details {
    background: rgba(255, 245, 248, 0.5);
    border-radius: 6px;
    margin: 6px 10px;
    border-left: 3px solid #ffa5b9;
    overflow: hidden;
}
.w .star-memory details summary {
    padding: 8px 10px;
    font-size: 13px;
    color: #6a4a5b;
    background: transparent;
    font-weight: 500;
    cursor: pointer;
    user-select: none;
    display: flex;
    justify-content: space-between;
    align-items: center;
    transition: background 0.2s ease;
    border-bottom: 1px solid transparent;
}
.w .star-memory details summary:hover {
    background: rgba(255, 126, 179, 0.10);
}
.w .star-memory details[open]>summary {
    border-bottom: 1px solid rgba(255, 126, 179, 0.15);
}
.w .star-memory details summary::-webkit-details-marker {
    display: none;
}
.w .star-memory details summary::after {
    content: "▸";
    font-size: 12px;
    color: #ff758c;
    opacity: 0.6;
    transition: transform 0.25s ease;
    margin-left: 8px;
}
.w .star-memory details[open]>summary::after {
    transform: rotate(90deg);
}

/* ===== 记忆区表格容器 ===== */
.w .star-memory details .table-wrap {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    margin: 6px 8px 8px 8px;
    border-radius: 6px;
    background: rgba(255, 255, 255, 0.6);
    padding: 4px 0;
}

/* ===== 记忆区表格（HTML表格） ===== */
.w .star-memory table {
    width: 100%;
    min-width: 340px;
    border-collapse: collapse;
    font-size: 13px;
    color: #4a2c40;
    table-layout: fixed;
}
.w .star-memory table th,
.w .star-memory table td {
    padding: 6px 4px;
    text-align: left;
    vertical-align: top;
    border-bottom: 1px solid rgba(255, 126, 179, 0.10);
    word-wrap: break-word;
    overflow-wrap: break-word;
    line-height: 1.5;
}
.w .star-memory table th {
    background: rgba(255, 126, 179, 0.08);
    font-weight: 600;
    font-size: 12px;
    color: #b34a6a;
    letter-spacing: 0.3px;
    border-bottom: 2px solid rgba(255, 126, 179, 0.20);
}
/* ===== 列宽分配：编号窄，时间窄，场景窄，内容宽 ===== */
.w .star-memory table th:nth-child(1),
.w .star-memory table td:nth-child(1) {
    width: 10%;
    min-width: 40px;
    padding-right: 2px;
}
.w .star-memory table th:nth-child(2),
.w .star-memory table td:nth-child(2) {
    width: 18%;
    min-width: 70px;
    padding-right: 2px;
}
.w .star-memory table th:nth-child(3),
.w .star-memory table td:nth-child(3) {
    width: 18%;
    min-width: 60px;
    padding-right: 2px;
}
.w .star-memory table th:nth-child(4),
.w .star-memory table td:nth-child(4) {
    width: 54%;
    min-width: 120px;
}
/* ===== 表格行 hover ===== */
.w .star-memory table tr:hover td {
    background: rgba(255, 126, 179, 0.04);
}
/* ===== 表格最后一行无边框 ===== */
.w .star-memory table tr:last-child td {
    border-bottom: none;
}

/* ===== 记忆区文本表格（备选：纯文本表格美化） ===== */
.w .star-memory details .text-table {
    display: block;
    margin: 6px 8px 8px 8px;
    padding: 8px 10px;
    background: rgba(255, 255, 255, 0.6);
    border-radius: 6px;
    font-size: 13px;
    line-height: 1.7;
    color: #4a2c40;
    white-space: pre-wrap;
    word-break: break-word;
    overflow-x: auto;
    font-family: ''SF Mono'', ''Menlo'', ''Monaco'', ''Consolas'', ''Liberation Mono'', monospace;
}
/* ===== 文本表格中的行（模拟） ===== */
.w .star-memory details .text-table .row {
    display: block;
    padding: 2px 0;
    border-bottom: 1px solid rgba(255, 126, 179, 0.06);
}
.w .star-memory details .text-table .row:last-child {
    border-bottom: none;
}
/* ===== 文本表格中的列（用 inline-block 模拟，编号/时间/场景窄，内容宽） ===== */
.w .star-memory details .text-table .col-id {
    display: inline-block;
    min-width: 36px;
    font-weight: 600;
    color: #b34a6a;
}
.w .star-memory details .text-table .col-time {
    display: inline-block;
    min-width: 72px;
    color: #6a4a5b;
}
.w .star-memory details .text-table .col-scene {
    display: inline-block;
    min-width: 64px;
    color: #6a4a5b;
}
.w .star-memory details .text-table .col-content {
    display: inline;
    color: #4a2c40;
}

/* ===== 记忆区说明文字 (.i) ===== */
.w .star-memory .i {
    display: block;
    margin: 4px 10px 10px 10px;
    font-size: 12px;
    color: #a08496;
    opacity: 0.8;
    font-style: normal;
    padding: 6px 10px;
    background: rgba(255, 255, 255, 0.5);
    border-radius: 4px;
    border-left: 2px solid rgba(255, 126, 179, 0.3);
}

/* ===== 其他辅助 ===== */
.w .t {
    display: block;
    font-weight: bold;
    font-size: 14px;
    color: #d81b60;
    margin: 12px 10px 4px 10px;
    padding-left: 8px;
    border-left: 3px solid #ff758c;
}
.w .q {
    display: block;
    margin: 12px 10px 8px 10px;
    padding: 8px 0 4px 0;
    font-size: 11px;
    color: #ff758c;
    text-align: center;
    border-top: 1px dashed rgba(255, 126, 179, 0.4);
    letter-spacing: 0.3px;
}

/* ===== 可选行动推荐 ===== */
.w .action-list {
    margin: 8px 10px 4px 10px;
    padding: 6px 10px;
    background: rgba(255, 255, 255, 0.6);
    border-radius: 6px;
    border-left: 3px solid #ff758c;
    font-size: 13px;
    color: #4a2c40;
}
.w .action-list .act {
    display: block;
    padding: 2px 0;
    color: #6a4a5b;
}

/* ===== 移动端适配 ===== */
@media (max-width: 480px) {
    .w {
        padding: 4px;
        border-radius: 8px;
    }
    .w .a summary,
    .w .b summary,
    .w .star-memory summary {
        padding: 8px 10px;
        font-size: 14px;
    }
    .w .r {
        margin: 4px 6px;
        padding: 3px 0;
    }
    .w .k {
        font-size: 11px;
        padding: 1px 8px;
        margin: 0 8px 1px 8px;
    }
    .w .v {
        font-size: 12px;
        padding: 1px 8px 3px 8px;
    }
    .w .m {
        margin: 4px 6px;
    }
    .w .mi {
        font-size: 12px;
        padding: 4px 8px;
    }
    /* 记忆区表格手机优化 */
    .w .star-memory table {
        font-size: 12px;
        min-width: 280px;
    }
    .w .star-memory table th,
    .w .star-memory table td {
        padding: 4px 2px;
        font-size: 12px;
    }
    .w .star-memory table th:nth-child(1),
    .w .star-memory table td:nth-child(1) {
        min-width: 30px;
        width: 8%;
    }
    .w .star-memory table th:nth-child(2),
    .w .star-memory table td:nth-child(2) {
        min-width: 56px;
        width: 16%;
    }
    .w .star-memory table th:nth-child(3),
    .w .star-memory table td:nth-child(3) {
        min-width: 50px;
        width: 16%;
    }
    .w .star-memory table th:nth-child(4),
    .w .star-memory table td:nth-child(4) {
        min-width: 90px;
        width: 60%;
    }
    .w .star-memory details {
        margin: 4px 6px;
    }
    .w .star-memory details .table-wrap {
        margin: 4px 4px 6px 4px;
        padding: 2px 0;
    }
    .w .star-memory details .text-table {
        font-size: 12px;
        padding: 6px 8px;
        margin: 4px 4px 6px 4px;
    }
    .w .star-memory .i {
        font-size: 11px;
        margin: 2px 6px 8px 6px;
        padding: 4px 8px;
    }
    .w .t {
        font-size: 13px;
        margin: 10px 6px 2px 6px;
        padding-left: 6px;
    }
    .w .action-list {
        font-size: 12px;
        margin: 6px 6px 2px 6px;
        padding: 4px 8px;
    }
}

/* ===== 非常小的屏幕 (宽度 < 360px) ===== */
@media (max-width: 359px) {
    .w .star-memory table {
        font-size: 11px;
        min-width: 240px;
    }
    .w .star-memory table th,
    .w .star-memory table td {
        padding: 3px 1px;
        font-size: 11px;
    }
    .w .star-memory table th:nth-child(1),
    .w .star-memory table td:nth-child(1) {
        min-width: 24px;
        width: 7%;
    }
    .w .star-memory table th:nth-child(2),
    .w .star-memory table td:nth-child(2) {
        min-width: 44px;
        width: 15%;
    }
    .w .star-memory table th:nth-child(3),
    .w .star-memory table td:nth-child(3) {
        min-width: 40px;
        width: 15%;
    }
    .w .star-memory table th:nth-child(4),
    .w .star-memory table td:nth-child(4) {
        min-width: 70px;
        width: 63%;
    }
    .w .star-memory details .text-table {
        font-size: 11px;
        padding: 4px 6px;
    }
    .w .star-memory details .text-table .col-id {
        min-width: 28px;
    }
    .w .star-memory details .text-table .col-time {
        min-width: 52px;
    }
    .w .star-memory details .text-table .col-scene {
        min-width: 44px;
    }
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>圣伊甸贵族女子学园 - 入学系统</title>
    <style>
        :root {
            --primary: #e8b4b8;
            --secondary: #eed6d3;
            --accent: #a45c40;
            --bg: #f6e6e4;
            --text: #4a3b32;
            --glass: rgba(255, 255, 255, 0.7);
            --glass-border: rgba(255, 255, 255, 0.5);
        }
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            font-family: ''Georgia'', ''Microsoft YaHei'', serif;
        }
        body {
            background: linear-gradient(135deg, var(--bg) 0%, #fff0f0 100%);
            color: var(--text);
            min-height: 100vh;
            display: flex;
            flex-direction: column;
            align-items: center;
            padding: 20px 10px;
        }
        .container {
            width: 100%;
            max-width: 900px;
            background: var(--glass);
            backdrop-filter: blur(15px);
            -webkit-backdrop-filter: blur(15px);
            border: 1px solid var(--glass-border);
            border-radius: 20px;
            box-shadow: 0 8px 32px rgba(164, 92, 64, 0.15);
            overflow: hidden;
        }
        .header {
            text-align: center;
            padding: 30px 20px;
            background: rgba(255, 255, 255, 0.4);
            border-bottom: 1px solid var(--glass-border);
        }
        .header h1 {
            font-size: 2rem;
            color: var(--accent);
            margin-bottom: 10px;
            text-shadow: 1px 1px 2px rgba(255, 255, 255, 0.8);
        }
        .header p {
            font-size: 1rem;
            color: #7a6b62;
        }
        .tabs {
            display: flex;
            justify-content: center;
            background: rgba(255, 255, 255, 0.3);
            padding: 10px;
            gap: 10px;
            flex-wrap: wrap;
        }
        .tab-btn {
            background: transparent;
            border: 2px solid var(--primary);
            color: var(--accent);
            padding: 10px 25px;
            border-radius: 30px;
            font-size: 1rem;
            font-weight: bold;
            cursor: pointer;
            transition: all 0.3s ease;
            -webkit-tap-highlight-color: transparent;
            touch-action: manipulation;
        }
        .tab-btn:hover {
            background: var(--secondary);
        }
        .tab-btn.active {
            background: var(--accent);
            color: white;
            border-color: var(--accent);
            box-shadow: 0 4px 15px rgba(164, 92, 64, 0.3);
        }
        .content-area {
            padding: 30px;
        }
        .tab-content {
            display: none;
            animation: fadeIn 0.5s ease;
        }
        .tab-content.active {
            display: block;
        }
        @keyframes fadeIn {
            from {
                opacity: 0;
                transform: translateY(10px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }
        .card {
            background: rgba(255, 255, 255, 0.6);
            border-radius: 15px;
            padding: 20px;
            margin-bottom: 20px;
            border: 1px solid var(--glass-border);
            box-shadow: 0 4px 10px rgba(0, 0, 0, 0.03);
        }
        .card h3 {
            color: var(--accent);
            margin-bottom: 15px;
            border-bottom: 1px dashed var(--primary);
            padding-bottom: 5px;
            font-size: 1.3rem;
        }
        .card p {
            line-height: 1.8;
            margin-bottom: 10px;
            text-align: justify;
        }
        .highlight {
            color: var(--accent);
            font-weight: bold;
        }
        .form-group {
            margin-bottom: 20px;
        }
        .form-group label {
            display: block;
            margin-bottom: 8px;
            font-weight: bold;
            color: var(--accent);
        }
        .form-control {
            width: 100%;
            padding: 12px 14px;
            border: 1px solid var(--primary);
            border-radius: 8px;
            background: rgba(255, 255, 255, 0.8);
            color: var(--text);
            font-size: 1rem;
            transition: all 0.3s;
            -webkit-appearance: none;
            appearance: none;
        }
        .form-control:focus {
            outline: none;
            border-color: var(--accent);
            box-shadow: 0 0 8px rgba(164, 92, 64, 0.2);
        }
        .custom-input {
            display: none;
            margin-top: 10px;
        }
        .custom-input.show {
            display: block;
        }
        textarea.form-control {
            resize: vertical;
            min-height: 100px;
        }
        .btn-group {
            display: flex;
            gap: 15px;
            margin-top: 20px;
        }
        .action-btn {
            flex: 1;
            padding: 15px;
            border: none;
            border-radius: 10px;
            font-size: 1.1rem;
            font-weight: bold;
            cursor: pointer;
            transition: all 0.3s;
            color: white;
            -webkit-tap-highlight-color: transparent;
            touch-action: manipulation;
        }
        .generate-btn {
            background: linear-gradient(135deg, var(--primary), var(--accent));
            box-shadow: 0 4px 15px rgba(164, 92, 64, 0.3);
        }
        .generate-btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(164, 92, 64, 0.4);
        }
        .copy-btn {
            background: linear-gradient(135deg, #7f8fa6, #2f3640);
            box-shadow: 0 4px 15px rgba(47, 54, 64, 0.3);
        }
        .copy-btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(47, 54, 64, 0.4);
        }
        .preview-box {
            width: 100%;
            height: 280px;
            margin-top: 20px;
            padding: 15px;
            border: 2px dashed var(--accent);
            border-radius: 10px;
            background: rgba(255, 255, 255, 0.9);
            font-family: monospace;
            font-size: 14px;
            color: #333;
            resize: vertical;
        }
        footer {
            margin-top: auto;
            padding: 20px;
            text-align: center;
            font-size: 0.9rem;
        }
        footer a {
            color: var(--accent);
            text-decoration: none;
            font-weight: bold;
            transition: opacity 0.3s;
        }
        footer a:hover {
            opacity: 0.8;
        }
        .toast {
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: var(--accent);
            color: white;
            padding: 15px 30px;
            border-radius: 30px;
            font-weight: bold;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
            display: none;
            z-index: 1000;
        }

        /* ===== 自定义下拉组件 ===== */
        .custom-select {
            position: relative;
            width: 100%;
            user-select: none;
            -webkit-tap-highlight-color: transparent;
        }
        .custom-select-trigger {
            display: flex;
            align-items: center;
            justify-content: space-between;
            width: 100%;
            padding: 12px 14px;
            border: 1px solid var(--primary);
            border-radius: 8px;
            background: rgba(255, 255, 255, 0.8);
            color: var(--text);
            font-size: 1rem;
            cursor: pointer;
            transition: all 0.3s;
            min-height: 48px;
            touch-action: manipulation;
        }
        .custom-select-trigger:active {
            background: rgba(232, 180, 184, 0.2);
        }
        .custom-select-trigger .value {
            flex: 1;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
        .custom-select-trigger .arrow {
            margin-left: 10px;
            font-size: 12px;
            color: var(--accent);
            transition: transform 0.3s;
            flex-shrink: 0;
        }
        .custom-select-trigger .arrow.open {
            transform: rotate(180deg);
        }
        .custom-select-trigger.placeholder {
            color: #999;
        }
        .custom-select-trigger:focus {
            outline: none;
            border-color: var(--accent);
            box-shadow: 0 0 8px rgba(164, 92, 64, 0.2);
        }

        .custom-select-dropdown {
            position: absolute;
            top: calc(100% + 4px);
            left: 0;
            right: 0;
            z-index: 999;
            background: #fff;
            border: 1px solid var(--primary);
            border-radius: 8px;
            box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
            max-height: 220px;
            overflow-y: auto;
            display: none;
            -webkit-overflow-scrolling: touch;
        }
        .custom-select-dropdown.open {
            display: block;
            animation: dropdownIn 0.2s ease;
        }
        @keyframes dropdownIn {
            from {
                opacity: 0;
                transform: translateY(-6px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }
        .custom-select-dropdown .option {
            padding: 12px 14px;
            font-size: 0.95rem;
            color: var(--text);
            cursor: pointer;
            transition: background 0.15s;
            border-bottom: 1px solid #f5f0ee;
            min-height: 44px;
            display: flex;
            align-items: center;
            touch-action: manipulation;
            -webkit-tap-highlight-color: transparent;
        }
        .custom-select-dropdown .option:last-child {
            border-bottom: none;
        }
        .custom-select-dropdown .option:active {
            background: var(--secondary);
        }
        .custom-select-dropdown .option:hover {
            background: var(--secondary);
        }
        .custom-select-dropdown .option.selected {
            background: var(--primary);
            color: var(--accent);
            font-weight: bold;
        }
        .custom-select-dropdown .option.custom-option {
            border-top: 1px dashed var(--primary);
            color: var(--accent);
            font-style: italic;
        }

        /* 自定义输入框在select下方 */
        .custom-input-wrapper {
            margin-top: 10px;
            display: none;
        }
        .custom-input-wrapper.show {
            display: block;
        }

        /* 移动端适配 */
        @media (max-width: 600px) {
            .tabs {
                flex-direction: column;
            }
            .tab-btn {
                width: 100%;
                padding: 14px;
                font-size: 0.95rem;
            }
            .btn-group {
                flex-direction: column;
            }
            .action-btn {
                padding: 16px;
                font-size: 1rem;
            }
            .content-area {
                padding: 16px;
            }
            .card {
                padding: 16px;
            }
            .header h1 {
                font-size: 1.6rem;
            }
            .custom-select-trigger {
                min-height: 48px;
                padding: 12px 14px;
                font-size: 0.95rem;
            }
            .custom-select-dropdown .option {
                padding: 14px 14px;
                font-size: 0.95rem;
                min-height: 48px;
            }
            .custom-select-dropdown {
                max-height: 200px;
                top: calc(100% + 2px);
            }
            .preview-box {
                height: 220px;
                font-size: 13px;
            }
        }

        @media (max-width: 400px) {
            .header h1 {
                font-size: 1.3rem;
            }
            .header p {
                font-size: 0.85rem;
            }
            .tab-btn {
                font-size: 0.85rem;
                padding: 12px 16px;
            }
            .content-area {
                padding: 12px;
            }
            .card {
                padding: 12px;
            }
            .form-control,
            .custom-select-trigger {
                padding: 10px 12px;
                font-size: 0.9rem;
            }
        }

        /* 滚动条美化 */
        .custom-select-dropdown::-webkit-scrollbar {
            width: 4px;
        }
        .custom-select-dropdown::-webkit-scrollbar-track {
            background: #f5f0ee;
            border-radius: 4px;
        }
        .custom-select-dropdown::-webkit-scrollbar-thumb {
            background: var(--primary);
            border-radius: 4px;
        }
        .custom-select-dropdown::-webkit-scrollbar-thumb:hover {
            background: var(--accent);
        }
    </style>
</head>
