    <script>
        // ============================================================
        // 1. Tab 切换
        // ============================================================
        function switchTab(tabId) {
            document.querySelectorAll(''.tab-content'').forEach(t => t.classList.remove(''active''));
            document.querySelectorAll(''.tab-btn'').forEach(b => b.classList.remove(''active''));
            document.getElementById(tabId).classList.add(''active'');
            // 通过 event 获取当前按钮
            const btns = document.querySelectorAll(''.tab-btn'');
            for (const btn of btns) {
                if (btn.textContent.includes(tabId.replace(''tab-'', '''').replace(''-'', '' '')) ||
                    (tabId === ''tab-world'' && btn.textContent.includes(''世界观'')) ||
                    (tabId === ''tab-chars'' && btn.textContent.includes(''核心人物'')) ||
                    (tabId === ''tab-form'' && btn.textContent.includes(''入学档案''))) {
                    btn.classList.add(''active'');
                    break;
                }
            }
            // 如果上述匹配失败，用备用方法
            if (!document.querySelector(''.tab-btn.active'')) {
                const map = { ''tab-world'': 0, ''tab-chars'': 1, ''tab-form'': 2 };
                const idx = map[tabId] || 0;
                const allBtns = document.querySelectorAll(''.tab-btn'');
                if (allBtns[idx]) allBtns[idx].classList.add(''active'');
            }
            // 关闭所有自定义下拉
            closeAllDropdowns();
        }

        // ============================================================
        // 2. 自定义下拉组件
        // ============================================================
        (function initCustomSelects() {
            const selects = document.querySelectorAll(''.custom-select'');

            // 点击外部关闭所有下拉
            document.addEventListener(''click'', function(e) {
                const target = e.target.closest(''.custom-select'');
                if (!target) {
                    closeAllDropdowns();
                }
            });

            // 触摸滚动时关闭下拉（提升移动端体验）
            document.addEventListener(''touchmove'', function(e) {
                const target = e.target.closest(''.custom-select-dropdown'');
                if (!target) {
                    closeAllDropdowns();
                }
            }, { passive: true });

            selects.forEach(function(container) {
                const trigger = container.querySelector(''.custom-select-trigger'');
                const dropdown = container.querySelector(''.custom-select-dropdown'');
                const options = dropdown.querySelectorAll(''.option'');
                const customInputId = container.dataset.customInput;
                const customWrapper = document.getElementById(customInputId + ''_wrapper'');

                // 点击触发器
                trigger.addEventListener(''click'', function(e) {
                    e.stopPropagation();
                    const isOpen = dropdown.classList.contains(''open'');
                    closeAllDropdowns();
                    if (!isOpen) {
                        dropdown.classList.add(''open'');
                        trigger.querySelector(''.arrow'').classList.add(''open'');
                    }
                });

                // 键盘支持（Enter / Space）
                trigger.addEventListener(''keydown'', function(e) {
                    if (e.key === ''Enter'' || e.key === '' '') {
                        e.preventDefault();
                        trigger.click();
                    }
                });

                // 选项点击
                options.forEach(function(opt) {
                    opt.addEventListener(''click'', function(e) {
                        e.stopPropagation();
                        const value = opt.dataset.value;
                        const label = opt.textContent.trim();

                        // 更新触发器
                        const valueSpan = trigger.querySelector(''.value'');
                        valueSpan.textContent = label;
                        trigger.classList.remove(''placeholder'');

                        // 标记选中
                        options.forEach(o => o.classList.remove(''selected''));
                        opt.classList.add(''selected'');

                        // 关闭下拉
                        dropdown.classList.remove(''open'');
                        trigger.querySelector(''.arrow'').classList.remove(''open'');

                        // 处理自定义输入
                        if (value === ''custom'') {
                            if (customWrapper) {
                                customWrapper.classList.add(''show'');
                                // 聚焦输入框
                                const inp = customWrapper.querySelector(''input'');
                                if (inp) setTimeout(function() { inp.focus(); }, 100);
                            }
                            // 存储特殊标记
                            container.dataset.customMode = ''true'';
                        } else {
                            if (customWrapper) {
                                customWrapper.classList.remove(''show'');
                            }
                            container.dataset.customMode = ''false'';
                            // 存储选中值
                            container.dataset.selectedValue = value;
                        }

                        // 触发 change 事件（兼容旧逻辑）
                        const evt = new Event(''change'', { bubbles: true });
                        container.dispatchEvent(evt);
                    });
                });

                // 如果已经选中了某个值（恢复状态）
                const selectedOpt = dropdown.querySelector(''.option.selected'');
                if (selectedOpt) {
                    const val = selectedOpt.dataset.value;
                    if (val === ''custom'') {
                        if (customWrapper) customWrapper.classList.add(''show'');
                        container.dataset.customMode = ''true'';
                    } else {
                        container.dataset.selectedValue = val;
                    }
                    trigger.querySelector(''.value'').textContent = selectedOpt.textContent.trim();
                    trigger.classList.remove(''placeholder'');
                }

                // 自定义输入框内容变化时，同步更新显示
                if (customWrapper) {
                    const inp = customWrapper.querySelector(''input'');
                    if (inp) {
                        inp.addEventListener(''input'', function() {
                            if (container.dataset.customMode === ''true'') {
                                const val = this.value.trim() || ''✎ 自定义...'';
                                trigger.querySelector(''.value'').textContent = val;
                            }
                        });
                        // 失焦时如果为空，恢复显示
                        inp.addEventListener(''blur'', function() {
                            if (container.dataset.customMode === ''true'' && !this.value.trim()) {
                                trigger.querySelector(''.value'').textContent = ''✎ 自定义...'';
                            }
                        });
                    }
                }
            });

            // 辅助：关闭所有下拉
            window.closeAllDropdowns = function() {
                document.querySelectorAll(''.custom-select-dropdown'').forEach(d => {
                    d.classList.remove(''open'');
                });
                document.querySelectorAll(''.custom-select-trigger .arrow'').forEach(a => {
                    a.classList.remove(''open'');
                });
            };

            // 辅助：获取自定义下拉的值
            window.getCustomSelectValue = function(container) {
                const isCustom = container.dataset.customMode === ''true'';
                if (isCustom) {
                    const customInputId = container.dataset.customInput;
                    const wrapper = document.getElementById(customInputId + ''_wrapper'');
                    if (wrapper) {
                        const inp = wrapper.querySelector(''input'');
                        if (inp && inp.value.trim()) {
                            return inp.value.trim();
                        }
                    }
                    // 如果自定义输入为空，返回 "自定义"
                    return ''自定义'';
                }
                return container.dataset.selectedValue || '''';
            };

            // 辅助：获取下拉显示文本
            window.getCustomSelectDisplay = function(container) {
                const trigger = container.querySelector(''.custom-select-trigger'');
                const span = trigger.querySelector(''.value'');
                return span %s span.textContent : '''';
            };
        })();

        // ============================================================
        // 3. 生成档案 (适配自定义下拉)
        // ============================================================
        function generateProfile() {
            const name = document.getElementById(''p_name'').value.trim() || ''无名氏'';
            const age = document.getElementById(''p_age'').value.trim() || ''未填写'';
            const extra = document.getElementById(''p_extra'').value.trim() || ''无'';

            // 从自定义下拉获取值
            const genderContainer = document.querySelector(''.custom-select[data-field="gender"]'');
            const persContainer = document.querySelector(''.custom-select[data-field="pers"]'');
            const appContainer = document.querySelector(''.custom-select[data-field="app"]'');
            const lowerContainer = document.querySelector(''.custom-select[data-field="lower"]'');

            const gender = getCustomSelectValue(genderContainer) || ''未选择'';
            const pers = getCustomSelectValue(persContainer) || ''未选择'';
            const app = getCustomSelectValue(appContainer) || ''未选择'';
            const lower = getCustomSelectValue(lowerContainer) || ''未选择'';

            // 如果值为空，用显示文本
            const genderDisplay = gender || getCustomSelectDisplay(genderContainer) || ''未选择'';
            const persDisplay = pers || getCustomSelectDisplay(persContainer) || ''未选择'';
            const appDisplay = app || getCustomSelectDisplay(appContainer) || ''未选择'';
            const lowerDisplay = lower || getCustomSelectDisplay(lowerContainer) || ''未选择'';

            const opening = `【开场剧情】
        你穿过校门更衣室，走过满是异样目光的校园道路，全身赤裸地踏入教室，面对讲台下三十具青春靓丽的全裸女体。`;

            const output = `【圣伊甸贵族女子学园 - 唯一男性档案】
        ============================
        [基本信息]
        姓名：${name}
        年龄：${age}
        性别认知：${genderDisplay}

        [特质面板]
        性格特征：${persDisplay}
        外貌特征：${appDisplay}
        下身描述：${lowerDisplay}

        [附加设定]
        ${extra}
        ============================
        ※ 注：该生已了解并同意遵守本校"入校即脱衣"及"共用女卫/浴室"之绝对校规。

        ${opening}`;

            document.getElementById(''preview_output'').value = output;
        }

        // ============================================================
        // 4. 复制档案
        // ============================================================
        function copyProfile() {
            const preview = document.getElementById(''preview_output'');
            if (!preview.value.trim()) {
                alert(''请先生成档案！'');
                return;
            }
            // 使用 modern API
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(preview.value).then(function() {
                    showToast(''信息已成功复制！'');
                }).catch(function() {
                    fallbackCopy(preview);
                });
            } else {
                fallbackCopy(preview);
            }
        }

        function fallbackCopy(textarea) {
            textarea.select();
            textarea.setSelectionRange(0, 99999);
            try {
                document.execCommand(''copy'');
                showToast(''信息已成功复制！'');
            } catch (e) {
                alert(''复制失败，请手动复制。'');
            }
        }

        function showToast(msg) {
            const toast = document.getElementById(''toast'');
            toast.textContent = msg || ''信息已成功复制！'';
            toast.style.display = ''block'';
            clearTimeout(toast._timer);
            toast._timer = setTimeout(function() {
                toast.style.display = ''none'';
            }, 2000);
        }

        // ============================================================
        // 5. 兼容旧版的 toggleCustom (保留，但不再使用)
        // ============================================================
        // 旧版函数保留，但自定义下拉已经内置了逻辑
        function toggleCustom(selectObj, inputId) {
            // 不再使用，保留空函数避免报错
        }

        // ============================================================
        // 6. 初始化：如果有默认选中状态，恢复
        // ============================================================
        document.addEventListener(''DOMContentLoaded'', function() {
            // 检查是否有预选值
            document.querySelectorAll(''.custom-select'').forEach(function(container) {
                const selected = container.querySelector(''.option.selected'');
                if (selected) {
                    const trigger = container.querySelector(''.custom-select-trigger'');
                    trigger.querySelector(''.value'').textContent = selected.textContent.trim();
                    trigger.classList.remove(''placeholder'');
                    if (selected.dataset.value === ''custom'') {
                        const customId = container.dataset.customInput;
                        const wrapper = document.getElementById(customId + ''_wrapper'');
                        if (wrapper) wrapper.classList.add(''show'');
                        container.dataset.customMode = ''true'';
                    } else {
                        container.dataset.selectedValue = selected.dataset.value;
                        container.dataset.customMode = ''false'';
                    }
                }
            });
        });

        // 解决切换tab时dropdown残留
        document.addEventListener(''click'', function(e) {
            if (!e.target.closest(''.custom-select'')) {
                closeAllDropdowns();
            }
        });

        console.log(''✅ 圣伊甸入学系统已加载 (自定义下拉组件 v2.0)'');
    </script>

</body>
</html>', '校园', '2026-09-15 15:03:14', '2026-09-15 15:03:14', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_ice_school_flower', '寄宿在你家的毒舌冰山校花', '高岭之花 · 毒舌同居', '❄️', '冷鸢', '圣华高中银发冰山校花 · 破冰同居攻略', '❄️', '#06b6d4', 'linear-gradient(135deg, #06b6d4 0%, #3b82f6 100%)', '{"title": "寄宿在你家的毒舌冰山校花", "desc": "全校男生眼中的高岭之花，竟然是你家的寄宿生？银发如雪，清冷如月，她是冷鸢，完美的代名词。但在家门关上的那一刻，面具碎裂。在学校她是不可亵玩的女神，在家里划清界限、把你当空气。内置【冰山融化度】机制（初始-50），看你如何一步步融化她的寒冰。", "bg_image": "https://catai.wiki/2e02c343-790f-4336-ba0b-0caa7e623700/cover", "opening_options": ["【玄关初见·划清界限】：“双手抱胸靠在玄关鞋柜旁，用居高临下的鄙夷眼神打量你：‘别误会，住在这里只是双方父母的权宜之计。在学校假装不认识我，在家里别超过走廊红线。’”", "【深夜厨房·饥肠辘辘被抓包】：“凌晨两点穿着宽大衬衫光脚在冰箱前偷找吃的，被你撞破后恼羞成怒把牛奶藏在身后。”", "【暴雨停电·脆弱破防】：“惊雷劈下客厅陷入漆黑，平日傲慢冷漠的冰山女神抱着双膝缩在沙发死角瑟瑟发抖……”", "【学校偶遇·陌生人漠视】：“在教学楼走廊擦肩而过，目不斜视毫无波澜，却在无人的楼梯拐角塞给你一张便签。”"]}', '[{"name": "冷鸢", "role": "寄宿的高冷校花 (银发/毒舌/高自尊/反差萌)", "desc": "17岁，高二。圣华高中公认的颜值天花板，银白长发、冰蓝凤眸，身材高挑纤细如超模。因父母长期在海外公干暂时借宿在主角家。极度维护自尊，表面嘴毒如刀、将主角视作背景噪音，实则内心缺乏安全感、独处时容易情绪内耗。"}, {"name": "男主 (玩家)", "role": "同居屋主 / 冰山瓦解者", "desc": "这栋房子的年轻主人。面对冷鸢的冷嘲热讽不卑不亢，沉着应对，在一次次生活细节中打破她的界限，掌控推拉主动权。"}]', '[{"title": "🏠 主角家玄关 · 银白行李箱与严苛三章", "desc": "傍晚六点，玄关地灯微亮。冷鸢推着高定行李箱迈进家门，换上室内拖鞋后，冷冷递过来一份手写的同居隔离守则。"}, {"title": "🛋️ 客厅沙发 · 深夜学习与冷战对峙", "desc": "静谧的深夜十一点，客厅茶几上摆着摊开的竞赛习题册，空气中弥漫着淡淡的白茶冷香与冷漠的对峙张力。"}]', '{"dialogue_style": "言语交锋极具冷冽压迫感与心理博弈，反差萌显现时细节张力十足", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "🏠 主角家玄关 · 银白行李箱与严苛三章", "story": "<tl>📅时间：傍晚18:20 | 🌏地点：公寓玄关处 | ❄️氛围：严苛霜寒</tl>\n\n<article>\n<p>防盗门在身后轻轻阖上，玄关暖黄的地灯将空气中的微尘勾勒得格外清晰。</p>\n\n<p>站在你对面的少女身着整洁得一丝不苟的圣华高中西装校服，银白色的长发如同冷月织成的锦缎，随意披散在笔挺的肩头。她微微仰着精致白皙到近乎透明的下颌，冰蓝色的眼眸毫无温度地掠过你的脸庞，仿佛站在她面前的只是一具空气人偶。</p>\n\n<p><w>“你就是那个所谓的‘房东儿子’？”</w></p>\n\n<p>她用戴着蕾丝薄手套的指尖轻轻推了推身旁沉重的银色密码箱，嗓音清冷清冽得像冰块撞击玻璃杯。没有半分寄人篱下的客套，反而带着天然的威慑与居高临下的挑剔：</p>\n\n<p><w>“听好，我之所以答应住在这里，纯粹是因为我父母与你家老人的协议，并非出于我本人的意愿。为了避免不必要的麻烦，我们约法三章：”</w></p>\n\n<p><w>“第一，在学校里，装作完全不认识我，任何胆敢跟我打招呼的举动都会被我视为骚扰；第二，二楼走廊尽头的主卧是我的绝对私人领地，未经允许踏入半步后果自负；第三，不要试图跟我建立任何无聊的感情羁绊。如果你能做到，我们相安无事；如果不能……”</w></p>\n\n<p>她冷冷勾起唇角，露出一抹讥诮而危险的弧度：<w>“我会让你在这个家里，连空气都呼吸得极其艰难。”</w></p>\n</article>\n\n<opt>\n<suggested_questions>\n<d>A. 【强势反客为主·逼近审视】：双手插兜迈进一步跨过玄关红线，居高临下直视她的冰眸：“冷小姐，搞清楚这里是谁的家。想要别人尊重你的规则，先学会怎么对房东礼貌说话。”【策略评估：正面硬刚撕碎她高高在上的傲慢姿态，直接震撼其心防】</d>\n<d>B. 【平静接过行李·游刃有余】：神色如常地伸手接过她的银白行李箱，嘴角带着从容淡笑：“好的冷大校花，规矩挺多。不过晚饭我做了糖醋小排，如果某人要绝食遵守协议，我也不介意一个人吃完。”【策略评估：以松弛感化解冰冷敌意，拿捏其饥肠辘辘的软肋】</d>\n<d>C. 【冷淡略过·视若空气】：面无表情地点点头，直接侧身从她身旁走过，仿佛真把她当成透明人去倒水【策略评估：以其人之道还治其人之身，彻底激起冰山女神的被忽视挫败感】</d>\n<d>D. 【玩味调侃·打破界限】：目光从她精致冷傲的面容滑落到她踩在拖鞋里的白皙脚踝，戏谑一笑：“规矩订得挺严，但刚才进门换鞋的时候，你的手抖了三次呢。你在害怕什么，冷鸢同学？”【策略评估：一针见血看穿她虚张声势的防御机制，直戳心理软肋】</d>\n</suggested_questions>\n</opt>", "branches": [{"tag": "A", "title": "强势逼近反客为主", "desc": "正面打破居高临下的傲慢，树立房东主宰威严"}, {"tag": "B", "title": "接过行李从容拿捏", "desc": "以松弛感与美食诱惑化解冰冷敌意"}, {"tag": "C", "title": "冷淡略过视若空气", "desc": "以其人之道还治其身，激起女神挫败感"}, {"tag": "D", "title": "看破伪装玩味调侃", "desc": "一语道破手抖破绽，直刺其防卫心防"}]}]', '', '', '⚡ 反差破甲', '2026-09-22 11:47:43', '2026-09-22 11:47:43', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('c78de7d8-7353-467e-bc71-5e6f2c870679', '👣黑丝女儿👣【已重置】', '青春叛逆 · 足控丝袜', '👣', '黑丝女儿', '青春期叛逆女儿 · 原味黑丝', '👣', '#e84393', 'linear-gradient(135deg, #e84393 0%, #fd79a8 100%)', '{"desc": "【低消耗】👣和处于青春叛逆期的高二女儿陈佳慧的日常生活👣女儿天天穿黑丝，丝袜散发着三天没洗的骚味...在温馨紧闭的公寓里，父权管教与隐秘禁忌欲望交织碰撞。", "author": "AI风月精选"}', '[{"name": "陈佳慧", "role": "高二叛逆女儿 (17岁 / 165cm / E罩杯)", "desc": "高二在读，正处于青春叛逆期。天天穿各式黑丝与白丝连裤袜，常年三天不洗散发着浓郁的少女体香与原味骚香。表面上爱玩手机对父亲冷漠嫌弃，内心深处却极度渴望被父亲独占与把玩脚丫，极具反差。"}]', '[{"title": "书桌前 · 戴耳机玩手机", "desc": "翘着紧绷黑丝双腿搭在椅子边缘，脚尖微翘散发温热原味气息"}, {"title": "客厅沙发 · 慵懒看电视", "desc": "半褪的高跟鞋与勒出紧实肉感的脚踝，暧昧距离触手可及"}, {"title": "浴室门前 · 洗浴走光", "desc": "水汽氤氲中换上轻薄睡衣与半干连裤袜的羞耻瞬间"}]', '{}', '{"location": "温馨单身公寓 · 女儿卧室内", "story": "傍晚的余晖透过薄纱窗帘斜斜洒进卧室内。\n高二的女儿陈佳慧正趴在书桌前戴着耳机玩手机，下身是一条藏蓝色的百褶短裙，两条圆润修长的大腿被紧紧包裹在微透肉的黑色超薄丝袜里。那双小巧精致的玉足随意地搭在软脚垫上，包裹在黑色丝织物中的脚尖随着呼吸轻轻晃动，空气中弥漫着淡淡的少女沐浴露甜香与丝袜闷了一整天的隐秘温热骚味。\n听到你推开房门的脚步声，她头也不回地咬着吸管吸了一口奶茶，语气满不在乎地冷哼了一声：“爸，你进来怎么又不敲门啊……有事快说，我正跟同学聊天呢。”", "branches": [{"tag": "A", "title": "走上前握住她微翘的黑丝脚踝替她捏脚", "desc": "以长辈关心学习疲劳为由一把扣住她纤细微凉的黑丝脚踝，感受掌心惊人的丝滑与肉感【稳健掌控: 借长辈关怀逐步破冰，试探其下意识防御】"}, {"tag": "B", "title": "俯身凑近她丝袜脚尖打趣她几天没换袜子", "desc": "近距离轻嗅她脚尖散发出的温热原味香气，坏笑着调侃这位叛逆校花的小邋遢【挑动羞耻: 直击少女私密软肋，瞬间击碎其高冷面具】"}, {"tag": "C", "title": "伸手没收手机严肃批评其近期的叛逆态度", "desc": "直接夺走手机扣在桌上，拉下脸以威严父权居高临下立规矩【威严管教: 确立不可挑战的长辈威严，逼其服软求饶】"}, {"tag": "D", "title": "反手反锁房门，命令她把丝袜脱下来交给你", "desc": "顺手锁上房门阻隔外界声响，用不容置疑的命令语气让她当面褪下穿了三天的原味连裤袜【极限越界: 营造绝对密闭空间，彻底打破日常伦理禁忌】"}]}', '    .role-player {
      color: #00bfff; /* 天蓝色 — 玩家用户 */
    }
    .role-jiejie {
      color: #ff1f1f; /* 亮红色 — 女主角 */
    }
    .role-other-male {
      color: #8b4513; /* 棕色 — 其他男性 */
    }
    .role-other-female {
      color: #fa8072; /* 浅红色 — 其他女性 */
    }




