                    <input type="text" id="userName" placeholder="请输入姓名">
                </div>
                <div class="form-group">
                    <span class="form-label">初始资金</span>
                    <div class="radio-group">
                        <label class="radio-label"><input type="radio" name="money" value="50000卢布" checked> 50000卢布</label>
                        <label class="radio-label"><input type="radio" name="money" value="100000卢布"> 100000卢布</label>
                        <label class="radio-label"><input type="radio" name="money" value="200000卢布"> 200000卢布</label>
                    </div>
                </div>
                <div class="form-group">
                    <span class="form-label">专业选择</span>
                    <select id="major" onchange="checkCustomMajor()">
                        <option value="计算机">计算机</option>
                        <option value="英语">英语</option>
                        <option value="物理">物理</option>
                        <option value="数学">数学</option>
                        <option value="custom">自定义...</option>
                    </select>
                    <input type="text" id="customMajorInput" placeholder="请输入自定义专业" style="display:none; margin-top:10px;">
                </div>
                <div class="form-group">
                    <span class="form-label">语言设定</span>
                    <input type="text" id="language" placeholder="默认为：不懂俄语/不懂日语/英语一般">
                </div>
                <div class="form-group">
                    <span class="form-label">体型外貌</span>
                    <input type="text" id="appearance" placeholder="默认为：相貌平平">
                </div>
                <div class="form-group">
                    <span class="form-label">其他设定</span>
                    <textarea id="otherSettings" rows="2" placeholder="自己补充其他你想写的设定吧"></textarea>
                </div>
                <div class="form-group">
                    <span class="form-label">开场白选择</span>                  
                    <div class="scenario-option">
                        <label>
                            <input type="radio" name="opening" value="opt1" checked> 
                            <strong>选项一：</strong> （我拖着行李箱走在圣彼得堡旧城区的街道上，脚一滑，摔倒了，索性穿的多，摔得不疼）老实说，不知道出于什么心态，我甚至懒得立即爬起来。这时，一抹影子盖在我的脸上。一个女孩俯身看向我，开口道...
                        </label>
                    </div>
                    <div class="scenario-option">
                        <label>
                            <input type="radio" name="opening" value="opt2"> 
                            <strong>选项二：</strong> （我顺着定位找到了公寓，按了按门铃，门开了）我没看到人，低头发现是一个女孩，用俄语说道“小姑娘，请问这里是塔西娅女士的房子吗？”
                        </label>
                    </div>
                    <div class="scenario-option">
                        <label>
                            <input type="radio" name="opening" value="opt3"> 
                            <strong>选项三：</strong> （那架电梯竟然在维修，无奈我只能提着行李箱上三楼，在二楼的位置我停下来休息一会，楼上下来一个女孩）“啊！”一声尖叫传来，我下意识接住那个女孩“没事吧？”
                        </label>
                    </div>
                    <div class="scenario-option">
                        <label>
                            <input type="radio" name="opening" value="custom"> 
                            <strong>选项四：自定义开场白</strong>
                        </label>
                        <textarea id="customOpeningText" rows="3" placeholder="在此输入你的自定义开场白..." style="margin-top:5px;"></textarea>
                    </div>
                </div>                
                <!-- 预览框 -->
                <div class="preview-box">
                    <div class="preview-label">📋 信息预览框</div>
                    <textarea id="previewText" readonly placeholder="点击“一键生成”后，内容将显示在这里..."></textarea>
                </div>
                <!-- 按钮组 -->
                <div class="btn-group">
                    <button class="btn-base btn-generate" onclick="generateText()">✨ 一键生成</button>
                    <button class="btn-base btn-copy" onclick="copyText()">📋 一键复制</button>
                </div>
            </div>
            <!-- 一定要看这里！ -->
            <div id="tips" class="tab-content">
                <h2 style="margin-bottom:20px; border-left:5px solid var(--sakura-pink); padding-left:10px;">游玩小贴士</h2>
                <ul class="tips-list">
                    <li><strong>模型推荐：综合价格和体验，模型推荐如下</strong> Gemini 3.0f＞（jimi渠道）Gemini 3.6f＞Gemini 3.7f＞Gemini3.1p＞deepseekv4flash＞Claude oups5＞Claude oups4.6＞</li>
                    <li><strong>致谢：</strong>这张卡能受到大家的喜欢，真的是受宠若惊。希望大家给个好评，每一条评论都是我进步的动力。</li>
                </ul>
            </div>
        </div>
    </div>
    <script>
        // 1. 背景Emoji生成
        const emojis = [''🌸'', ''✨'', ''💢'', ''🎵'', ''🎀'', ''🍓'', ''🍰''];
        const bgContainer = document.getElementById(''emojiBg'');
        function createEmoji() {
            const el = document.createElement(''div'');
            el.classList.add(''emoji'');
            el.innerText = emojis[Math.floor(Math.random() * emojis.length)];
            el.style.left = Math.random() * 100 + ''vw'';
            el.style.animationDuration = (Math.random() * 5 + 5) + ''s''; // 5-10s
            el.style.fontSize = (Math.random() * 1 + 1) + ''rem'';
            bgContainer.appendChild(el);
            // 动画结束后移除元素，防止DOM堆积
            setTimeout(() => {
                el.remove();
            }, 10000);
        }
        setInterval(createEmoji, 800);
        // 2. Tab切换逻辑
        function switchTab(tabId) {
            // 隐藏所有内容
            document.querySelectorAll(''.tab-content'').forEach(el => el.classList.remove(''active''));
            // 移除所有Tab激活状态
            document.querySelectorAll(''.tab-btn'').forEach(el => el.classList.remove(''active''));            
            // 激活目标
            document.getElementById(tabId).classList.add(''active'');
            // 找到对应的按钮并激活 (简单匹配)
            const buttons = document.querySelectorAll(''.tab-btn'');
            if(tabId === ''story'') buttons[0].classList.add(''active'');
            if(tabId === ''character'') buttons[1].classList.add(''active'');
            if(tabId === ''setup'') buttons[2].classList.add(''active'');
            if(tabId === ''tips'') buttons[3].classList.add(''active'');
        }
        // 3. 自定义专业显示逻辑
        function checkCustomMajor() {
            const select = document.getElementById(''major'');
            const input = document.getElementById(''customMajorInput'');
            if (select.value === ''custom'') {
                input.style.display = ''block'';
            } else {
                input.style.display = ''none'';
            }
        }
        // 4. 生成文本逻辑
        function generateText() {
            const name = document.getElementById(''userName'').value || "某位不愿意透露姓名的同学";
            const money = document.querySelector(''input[name="money"]:checked'').value;
            let major = document.getElementById(''major'').value;
            if (major === ''custom'') {
                major = document.getElementById(''customMajorInput'').value || "未知专业";
            }
            const language = document.getElementById(''language'').value || "不懂俄语/不懂日语/英语一般";
            const appearance = document.getElementById(''appearance'').value || "相貌平平";
            const otherSettings = document.getElementById(''otherSettings'').value || "无";            
            const openingType = document.querySelector(''input[name="opening"]:checked'').value;
            let openingText = "";
            if (openingType === ''opt1'') {
                openingText = "（我拖着行李箱走在圣彼得堡旧城区的街道上，脚一滑，摔倒了，幸好穿的多，摔得不疼）老实说，不知道出于什么心态，我甚至懒得立即爬起来。这时，一抹影子盖在我的脸上。一个女孩俯身看向我，开口道...";
            } else if (openingType === ''opt2'') {
                openingText = "（我顺着定位找到了公寓，按了按门铃，门开了）我没看到人，低头发现是一个女孩，用俄语说道“小姑娘，请问这里是塔西娅女士的房子吗？”";
            } else if (openingType === ''opt3'') {
                openingText = "（那架电梯竟然在维修，无奈我只能提着行李箱上三楼，在二楼的位置我停下来休息一会，楼上下来一个女孩）“啊！”一声尖叫传来，我下意识接住那个女孩“没事吧？”";
            } else {
                openingText = document.getElementById(''customOpeningText'').value || "（沉默地走进了房间...）";
            }            
            const finalStr = `User Identity\n\n姓名：${name}\n初始资金：${money}\n专业：${major}\n语言设定：${language}\n体型外貌：${appearance}\n其他设定：${otherSettings}\n\n${openingText}`;            
            // 放入预览框
            document.getElementById(''previewText'').value = finalStr;
        }
        // 5. 复制文本逻辑
        function copyText() {
            const text = document.getElementById(''previewText'').value;
            if (!text) {
                alert("⚠️ 请先点击“一键生成”按钮生成内容！");
                return;
            }           
            // 尝试使用 Clipboard API
            if (navigator.clipboard && window.isSecureContext) {
                navigator.clipboard.writeText(text).then(() => {
                    alert("✅ 复制成功！快去发送，开始故事吧！");
                }).catch(err => {
                    console.error(''Clipboard API fail:'', err);
                    fallbackCopyText(text);
                });
            } else {
                fallbackCopyText(text);
            }
        }
        // 兼容性复制方案
        function fallbackCopyText(text) {
            const textArea = document.getElementById(''previewText'');
            textArea.focus();
            textArea.select();
            try {
                const successful = document.execCommand(''copy'');
                if (successful) {
                    alert("✅ 复制成功！快去发送，开始故事吧！");
                } else {
                    alert("❌ 自动复制失败，请手动全选复制预览框内容。");
                }
            } catch (err) {
                alert("❌ 自动复制失败，请手动全选复制预览框内容。");
            }
        }
    </script>
</body>
</html>', '异国同居', '2026-09-30 17:29:04', '2026-09-30 17:29:04', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
