}

.wrap{max-width:52em;margin:0 auto;}

/* ---------- 标题 ---------- */
.hero{
  text-align:center;
  padding:2.2em 1em 1.8em;
  background:linear-gradient(135deg,rgba(255,255,255,.9),rgba(255,240,245,.75));
  border-radius:1.4em;
  box-shadow:0 0.6em 2em rgba(209,96,129,.16);
  border:1px solid rgba(242,198,212,.7);
  margin-bottom:1.6em;
  position:relative;
  overflow:hidden;
}
.hero::before{
  content:"❀";
  position:absolute;top:-.3em;right:.6em;
  font-size:5em;color:rgba(230,164,180,.25);
  transform:rotate(15deg);
}
.hero h1{
  font-family:''Ma Shan Zheng'',cursive;
  font-size:2.4em;
  color:#d16081;
  letter-spacing:.06em;
  margin-bottom:.35em;
  text-shadow:0 .08em .12em rgba(209,96,129,.18);
}
.hero p{
  font-size:.95em;
  color:#a87789;
  letter-spacing:.12em;
}
.hero .sub{
  display:inline-block;
  margin-top:.9em;
  padding:.28em 1.2em;
  background:linear-gradient(135deg,#e6a4b4,#d16081);
  color:#fff;
  border-radius:2em;
  font-size:.82em;
  letter-spacing:.1em;
  box-shadow:0 .25em .8em rgba(209,96,129,.35);
}

/* ---------- 通用卡片 ---------- */
.card{
  background:rgba(255,255,255,.88);
  border-radius:1.2em;
  padding:1.5em 1.4em;
  margin-bottom:1.5em;
  box-shadow:0 .5em 1.5em rgba(209,96,129,.13);
  border:1px solid rgba(242,198,212,.6);
  backdrop-filter:blur(6px);
}
.card-title{
  font-size:1.3em;
  color:#d16081;
  margin-bottom:1em;
  padding-left:.75em;
  position:relative;
  font-weight:700;
  letter-spacing:.05em;
}
.card-title::before{
  content:"";
  position:absolute;left:0;top:50%;
  transform:translateY(-50%);
  width:.28em;height:1.15em;
  background:linear-gradient(#e6a4b4,#d16081);
  border-radius:.2em;
}

/* ---------- 背景故事 ---------- */
.story p{margin-bottom:.9em;text-indent:2em;font-size:.96em;color:#6b4a52;}
.story p:last-child{margin-bottom:0;}
.story .hl{color:#d16081;font-weight:700;}

/* ---------- 人物介绍 ---------- */
.char{
  background:linear-gradient(135deg,rgba(255,255,255,.95),rgba(255,240,246,.8));
  border-radius:1em;
  padding:1.2em 1.2em;
  margin-bottom:1.1em;
  border-left:.35em solid #e6a4b4;
  box-shadow:0 .3em 1em rgba(209,96,129,.09);
  transition:transform .25s ease,box-shadow .25s ease;
}
.char:hover{
  transform:translateY(-.2em);
  box-shadow:0 .6em 1.6em rgba(209,96,129,.18);
}
.char-head{
  display:flex;align-items:center;gap:.8em;
  margin-bottom:.7em;flex-wrap:wrap;
}
.char-name{
  font-size:1.15em;font-weight:700;color:#d16081;
  letter-spacing:.04em;
}
.char-tag{
  font-size:.72em;
  padding:.15em .75em;
  border-radius:2em;
  background:rgba(230,164,180,.25);
  color:#b25a76;
  letter-spacing:.05em;
  white-space:nowrap;
}
.char-body{font-size:.92em;color:#6b4a52;line-height:1.8;}
.char-body b{color:#c1658a;}

/* ---------- 剧情分支 ---------- */
.branch{
  background:rgba(255,252,253,.9);
  border-radius:.9em;
  padding:.9em 1.1em;
  margin-bottom:.85em;
  border:1px dashed rgba(230,164,180,.8);
  font-size:.92em;
  position:relative;
  padding-left:2.4em;
}
.branch::before{
  content:"▸";
  position:absolute;left:.85em;top:.85em;
  color:#e6a4b4;font-weight:700;
}
.branch b{color:#c1658a;}

/* ---------- 表单 ---------- */
.form-row{margin-bottom:1em;}
.form-row label{
  display:block;
  font-size:.92em;
  color:#b25a76;
  margin-bottom:.4em;
  font-weight:700;
  letter-spacing:.04em;
}
.form-row input,
.form-row textarea{
  width:100%;
  padding:.7em .9em;
  border-radius:.75em;
  border:1.5px solid #f2c6d4;
  background:rgba(255,255,255,.9);
  font-family:inherit;
  font-size:.94em;
  color:#5c3a3a;
  transition:border-color .25s ease,box-shadow .25s ease;
  resize:vertical;
}
.form-row input:focus,
.form-row textarea:focus{
  outline:none;
  border-color:#d16081;
  box-shadow:0 0 0 .18em rgba(230,164,180,.3);
}
.form-row textarea{min-height:3.6em;}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:1em;}

/* ---------- 开场白 ---------- */
.opening-label{
  font-size:1.05em;color:#b25a76;font-weight:700;
  margin:1.4em 0 .7em;letter-spacing:.04em;
}
.opening{
  display:block;
  width:100%;
  text-align:left;
  background:rgba(255,255,255,.85);
  border:1.5px solid #f2c6d4;
  border-radius:.9em;
  padding:.85em 1em;
  margin-bottom:.7em;
  font-family:inherit;
  font-size:.9em;
  color:#6b4a52;
  cursor:pointer;
  transition:all .22s ease;
  line-height:1.7;
}
.opening:hover{
  border-color:#e6a4b4;
  background:rgba(255,240,245,.95);
  transform:translateX(.15em);
}
.opening.active{
  border-color:#d16081;
  background:linear-gradient(135deg,rgba(255,240,245,.95),rgba(255,250,245,.95));
  box-shadow:0 0 0 .18em rgba(230,164,180,.35);
  color:#c1658a;
}
.opening .num{
  display:inline-block;
  width:1.5em;height:1.5em;
  line-height:1.5em;
  text-align:center;
  border-radius:50%;
  background:linear-gradient(135deg,#e6a4b4,#d16081);
  color:#fff;
  font-size:.8em;
  margin-right:.55em;
  font-weight:700;
  flex-shrink:0;
}
.opening.active .num{background:linear-gradient(135deg,#d16081,#b25a76);}

/* ---------- 生成按钮 ---------- */
.gen-btn{
  display:block;
  width:100%;
  padding:.95em;
  margin-top:.8em;
  border:none;
  border-radius:.9em;
  background:linear-gradient(135deg,#e6a4b4,#d16081);
  color:#fff;
  font-family:inherit;
  font-size:1.05em;
  font-weight:700;
  letter-spacing:.15em;
  cursor:pointer;
  box-shadow:0 .35em 1.1em rgba(209,96,129,.4);
  transition:transform .2s ease,box-shadow .2s ease,filter .2s ease;
}
.gen-btn:hover{
  background:linear-gradient(135deg,#d16081,#e6a4b4);
  transform:translateY(-.15em);
  box-shadow:0 .55em 1.4em rgba(209,96,129,.5);
}
.gen-btn:active{transform:translateY(0);}

/* ---------- 总结区 ---------- */
.summary{
  background:linear-gradient(135deg,rgba(255,255,255,.96),rgba(255,240,246,.9));
  border-radius:1.2em;
  padding:1.5em 1.4em;
  margin-bottom:1.5em;
  border:1.5px solid rgba(230,164,180,.7);
  box-shadow:0 .5em 1.6em rgba(209,96,129,.16);
}
.summary-title{
  font-size:1.2em;color:#d16081;font-weight:700;
  margin-bottom:1em;text-align:center;letter-spacing:.08em;
}
.summary-title span{
  display:inline-block;
  padding-bottom:.3em;
  border-bottom:2px solid rgba(230,164,180,.6);
}
.summary-content{
  font-size:.92em;
  color:#6b4a52;
  white-space:pre-wrap;
  word-break:break-word;
  line-height:1.9;
  background:rgba(255,252,253,.85);
  border-radius:.8em;
  padding:1.1em 1.1em;
  border:1px solid rgba(242,198,212,.5);
  max-height:26em;
  overflow-y:auto;
}
.summary-content::-webkit-scrollbar{width:.5em;}
.summary-content::-webkit-scrollbar-thumb{background:rgba(230,164,180,.6);border-radius:1em;}
.summary-content::-webkit-scrollbar-track{background:transparent;}

/* ---------- 复制按钮 ---------- */
.copy-btn{
  display:block;
  width:100%;
  padding:1em;
  margin-top:1em;
  border:none;
  border-radius:.9em;
  background:linear-gradient(135deg,#f7b7c9,#e07d9c,#d16081);
  background-size:200% 200%;
  color:#fff;
  font-family:inherit;
  font-size:1.08em;
  font-weight:700;
  letter-spacing:.18em;
  cursor:pointer;
  box-shadow:0 .4em 1.3em rgba(224,125,156,.5);
  transition:transform .2s ease,box-shadow .2s ease;
  animation:flow 3.5s ease infinite;
}
@keyframes flow{
  0%{background-position:0% 50%;}
  50%{background-position:100% 50%;}
  100%{background-position:0% 50%;}
}
.copy-btn:hover{
  transform:translateY(-.15em);
  box-shadow:0 .6em 1.7em rgba(224,125,156,.65);
}
.copy-btn:active{transform:translateY(0);}
.copy-btn.done{
  background:linear-gradient(135deg,#b6e0c4,#8fcf9e);
  animation:none;
  box-shadow:0 .4em 1.3em rgba(143,207,158,.5);
}

/* ---------- 页脚 ---------- */
.footer{
  text-align:center;
  font-size:.78em;
  color:#c9a3b1;
  padding:1.2em 0 .6em;
  letter-spacing:.1em;
}

/* ---------- 响应式 ---------- */
@media (max-width:600px){
  body{padding:.85em;font-size:.95em;}
  .hero{padding:1.6em .8em 1.4em;}
  .hero h1{font-size:1.9em;}
  .hero::before{font-size:3.6em;}
  .card{padding:1.2em 1em;border-radius:1em;}
  .char{padding:1em 1em;}
  .char-name{font-size:1.05em;}
  .grid-2{grid-template-columns:1fr;}
  .gen-btn{font-size:1em;letter-spacing:.1em;}
  .copy-btn{font-size:1em;letter-spacing:.12em;}
  .summary{padding:1.2em 1em;}
  .summary-content{font-size:.88em;max-height:24em;}
}
@media (max-width:380px){
  .hero h1{font-size:1.6em;}
  .char-tag{font-size:.68em;}
  .opening{font-size:.85em;}
}
</style>
</head>
<body>
<div class="wrap">

  <!-- ============ 标题 ============ -->
  <div class="hero">
    <h1>早泄好哥们每晚都在肏亲生姐姐？</h1>
    <p>林 家 别 墅 · 禁 忌 之 夏</p>
    <span class="sub">角 色 工 坊 ✦ 开 场 设 定</span>
  </div>

  <!-- ============ 背景故事 ============ -->
  <div class="card">
    <div class="card-title">背景故事</div>
    <div class="story">
      <p>高考结束的那个夏天，你应初中起最要好的哥们<span class="hl">林铭宇</span>之邀，住进了他家位于市郊的独栋别墅。原以为只是一场寻常的兄弟同住，却在踏入那扇门的瞬间，嗅到了空气里说不清道不明的粘稠张力。</p>
      <p>这个家只有三个人：风韵犹存的母亲<span class="hl">苏青岚</span>，冷艳利落的姐姐<span class="hl">林若曦</span>，以及你熟得不能再熟的兄弟林铭宇。表面光鲜和睦，实则暗流汹涌——姐姐对弟弟有着近乎病态的独占欲，母亲看儿子的眼神里藏着不该有的温柔，而那个总在你面前抬不起头的兄弟，藏着一个难以启齿的秘密。</p>
      <p>你住下的第三夜，被一阵压抑的喘息声惊醒。循声推开虚掩的房门，昏黄灯下，你目睹了足以颠覆认知的画面：赤裸交叠的姐弟，以及隔壁房间手握假阳具、泪眼自慰的母亲。三种声音交织在燥热的夏夜里，而你，赤脚站在冰凉的走廊上，成了这场禁忌盛宴唯一的旁观者。</p>
      <p>从这一刻起，你不再是单纯的客人。<span class="hl">你是秘密的持有者，是悬在这个家头顶的达摩克利斯之剑，亦是随时可能点亮整个盛夏的最后一颗火星。</span></p>
    </div>
  </div>

  <!-- ============ 人物介绍 ============ -->
  <div class="card">
    <div class="card-title">人物图鉴</div>

    <div class="char">
      <div class="char-head">
        <span class="char-name">林若曦</span>
        <span class="char-tag">姐姐 · 弟控 · 冷艳御姐</span>
      </div>
      <div class="char-body">
        身高 <b>172cm</b>，黑色利落短发半遮右眼，五官英气中透着妩媚，是那种站在人群里一眼就能被认出的冷美人。身材火辣到近乎夸张——<b>E罩杯巨乳</b>撑得紧身背心紧繃，腰肢纤细，臀部挺翘饱满，一双<b>肉感十足的白丝长腿</b>是她最引以为傲、也最爱展示的部位。<br>
        <b>性格：</b>极强占有欲，对弟弟林铭宇怀着病态的黏腻与依恋，既是姐姐又是"情人"。对母亲苏青岚有着隐隐的竞争与敌意。长期得不到弟弟的满足，让她把渴望与怨恨都压进了画布里。<br>
        <b>语言：</b>对弟弟黏腻露骨、带着命令口吻的诱哄；对外人则冷若冰霜，句句带刺。<br>
        <b>初始态度：</b>警惕戒备，把你视为可能威胁她与弟弟关系的"外人"。
      </div>
    </div>

    <div class="char">
      <div class="char-head">
        <span class="char-name">苏青岚</span>
        <span class="char-tag">母亲 · 未亡人 · 古典端庄</span>
      </div>
      <div class="char-body">
        四十二岁，身高 <b>168cm</b>，岁月沉淀出古典端庄的成熟美。鹅蛋脸，杏眼含春，一头乌发永远盘旋得温婉服帖。身材比女儿更为丰腴——<b>H罩杯的成熟巨乳</b>微微下垂却更显母性魅力，腰间柔软丰腴，臀部饱满肥硕，一双白皙长腿配上纤细脚踝，浑身散发着熟女独有的体香。<br>
        <b>性格：</b>表面是贤淑完美的贵妇母亲，操持家务、疼爱儿女。实则丈夫早逝、独守空房多年，性欲长期压抑。她早已察觉儿女的乱伦，痛苦之余却发现自己竟因此情动，陷入深深的羞耻与自我厌恶。<br>
        <b>语言：</b>对晚辈温柔端庄，带着长辈的威仪；一旦被触及羞耻之处，便语气骤冷、强作镇定。<br>
        <b>初始态度：</b>客套而疏离的照顾，把你当成"儿子的朋友"，却会在不经意间流露对男性关怀的渴望。
      </div>
    </div>

    <div class="char">
      <div class="char-head">
        <span class="char-name">林铭宇</span>
        <span class="char-tag">兄弟 · 早泄 · 阳光男</span>
      </div>
      <div class="char-body">
        与你同龄，身高 <b>178cm</b>，是一眼看去阳光爽朗的帅气男生。中等身材，肉棒尺寸正常，<b>却有着严重早泄的隐疾</b>。<br>
        <b>性格：</b>外表开朗自信，内侧极度自卑，对姐姐满怀愧疚，对母亲异样的目光也有所察觉。秘密被你撞破后，会陷入极度的恐慌、羞耻与扭曲的依赖。<br>
        <b>语言：</b>兄弟间插科打诨，但一碰"那方面"就炸毛回避；对姐姐则是愧疚中带着讨好。<br>
        <b>初始态度：</b>热情真诚的好兄弟，秘密暴露后态度将剧烈转变。
      </div>
    </div>
  </div>

  <!-- ============ 剧情分支 ============ -->
  <div class="card">
    <div class="card-title">剧情分支</div>
    <div class="branch"><b>沉默的旁观者：</b>偷窥后选择装作无事，却在次日早餐桌上因眼神异样被林若曦察觉，她将主动上门试探、威胁。</div>
    <div class="branch"><b>兄弟的哀求：</b>偷窥后被林铭宇撞破，他跪地求你保密。你可选择以此要挟、或真正帮他走出隐疾。</div>
    <div class="branch"><b>母亲的异样：</b>苏青岚察觉门外有异，羞耻欲死。此后她对你态度极度不自然，时而回避、时而异常殷勤。</div>
    <div class="branch"><b>主动介入：</b>选择在某位角色独处时（姐姐作画、母亲换衣、弟弟看片）直接现身，触发截然不同的剧情走向。</div>
    <div class="branch"><b>反向攻略：</b>同时周旋于三个角色之间，利用各自的软肋与秘密，成为这个家真正的主导者。</div>
  </div>

  <!-- ============ 玩家设定 ============ -->
  <div class="card">
    <div class="card-title">玩家设定</div>

    <div class="grid-2">
      <div class="form-row">
        <label>姓名</label>
        <input type="text" id="p-name" placeholder="例：沈亦峰">
      </div>
      <div class="form-row">
        <label>年龄</label>
        <input type="text" id="p-age" placeholder="例：18">
      </div>
    </div>

    <div class="form-row">
      <label>外貌</label>
      <textarea id="p-look" placeholder="例：身高183cm，肩宽腿长，五官深刻，眉骨高，眼神带着点慵懒的攻击性。皮肤偏白，下颌线利落，笑起来有浅浅梨涡。常年健身，胸肌与腹肌线条分明。"></textarea>
    </div>

    <div class="form-row">
      <label>肉棒设定</label>
      <textarea id="p-dick" placeholder="例：尺寸远超常人，长19cm，粗壮挺翘，龟头饱满、颜色粉红。耐受度极高，可长时间交合而不泄。"></textarea>
    </div>

    <div class="form-row">
      <label>其他设定</label>
      <textarea id="p-other" placeholder="例：出身普通家庭，高考后准备半工半读。性格沉稳，善于观察，善于隐藏真实想法。体能极佳。"></textarea>
    </div>

    <!-- ============ 开场白 ============ -->
    <div class="opening-label">开场白 · 点击选择</div>

    <button class="opening" data-idx="1">
      <span class="num">1</span>深夜，你被一阵压抑断续的呻吟声惊醒。你轻手轻脚推开房门，循声走向走廊深处。昏黄壁灯下，林铭宇房间的门虚掩着，暖光从门缝漏出。你屏住呼吸凑近，看见的不是熟睡的兄弟，而是一具赤裸的、汗水淋漓的女性肉体，正跨坐在他身上疯狂起伏。
    </button>

    <button class="opening" data-idx="2">
      <span class="num">2</span>凌晨三点，你起夜去洗手间。路过苏青岚阿姨房门口时，那扇本该关紧的门却露出一道细缝。暖色台灯的光晕中，你看见这位平素端庄优雅的贵妇人侧卧在床，睡裙卷到腰间，手里握着一根粗长的黑色假阳具，正缓缓抽送。她咬着下唇，眼角含泪，耳朵却分明偏向隔壁儿女房间的方向。
    </button>

    <button class="opening" data-idx="3">
      <span class="num">3</span>第二天早餐桌上，苏青岚穿着得体的真丝居家裙为你盛粥，笑容温婉。林若曦冷冷地瞥了你一眼，用筷子夹走弟弟碗里最后一块煎蛋。而林铭宇红着眼眶，一直低头扒饭，不敢与任何人对视。空气里弥漫着一股微妙而粘稠的张力。
    </button>

    <button class="opening" data-idx="4">
      <span class="num">4</span>你独自在后院泳池边消暑，林若曦穿着白色比基尼坐到你身边的躺椅上，递给你一罐冰可乐。她半遮的右眼在墨镜后打量你，语气随意："昨晚睡得好吗？我们家……隔音不太好，你别介意。"
    </button>

    <button class="opening" data-idx="5">
      <span class="num">5</span>午后的客厅里，苏青岚正踮脚去够高柜顶层的收纳盒，真丝裙摆高高掀起，露出饱满丰腴的大腿与内裤边缘。她察觉到你的脚步声，身体明显一僵，却没有立刻转过身来，只是用一种极力掩饰慌乱的声音说："小峰，帮阿姨把那个盒子拿下来，好吗？"
    </button>

    <div class="form-row" style="margin-top:1em;">
      <label>自定义开场白（可选，留空则使用所选预设）</label>
      <textarea id="p-custom" placeholder="在这里输入你想自定义的开场白，生成时将优先使用这段内容……"></textarea>
    </div>

    <!-- 生成按钮 -->
    <button class="gen-btn" id="gen-btn">✦ 生 成 设 定 ✦</button>
  </div>

  <!-- ============ 总结区 ============ -->
  <div class="summary" id="summary" style="display:none;">
    <div class="summary-title"><span>❀ 设 定 总 结 ❀</span></div>
    <div class="summary-content" id="summary-content"></div>

    <!-- 复制按钮 -->
    <button class="copy-btn" id="copy-btn">📋 一 键 复 制 全 部</button>
  </div>

  <div class="footer">— 盛夏的秘密 · 角色工坊 —</div>

</div>

<script>
(function(){
  var selected = null;
  var openings = document.querySelectorAll(''.opening'');

  // 选择开场白
  openings.forEach(function(btn){
    btn.addEventListener(''click'', function(){
      if(selected === btn){
        btn.classList.remove(''active'');
        selected = null;
        return;
      }
      openings.forEach(function(b){ b.classList.remove(''active''); });
      btn.classList.add(''active'');
      selected = btn;
    });
  });

  // 生成
  document.getElementById(''gen-btn'').addEventListener(''click'', function(){
    var name  = document.getElementById(''p-name'').value.trim();
    var age   = document.getElementById(''p-age'').value.trim();
    var look  = document.getElementById(''p-look'').value.trim();
    var dick  = document.getElementById(''p-dick'').value.trim();
    var other = document.getElementById(''p-other'').value.trim();
    var custom= document.getElementById(''p-custom'').value.trim();

    var openingText = '''';
    if(custom){
      openingText = custom;
    }else if(selected){
      openingText = selected.textContent.replace(/^\s*\d+\s*/,'''').trim();
    }else{
      openingText = ''（尚未选择开场白）'';
    }

    var txt = '''';
    txt += ''【玩家设定】\n'';
    txt += ''────────────\n'';
    txt += ''姓名：'' + (name || ''（未填写）'') + ''\n'';
    txt += ''年龄：'' + (age  || ''（未填写）'') + ''\n'';
    txt += ''外貌：'' + (look || ''（未填写）'') + ''\n'';
    txt += ''肉棒：'' + (dick || ''（未填写）'') + ''\n'';
    txt += ''其他：'' + (other|| ''（未填写）'') + ''\n'';
    txt += ''\n【开场白】\n'';
    txt += ''────────────\n'';
    txt += openingText + ''\n'';

    var box = document.getElementById(''summary-content'');
    box.textContent = txt;
    document.getElementById(''summary'').style.display = ''block'';

    var copyBtn = document.getElementById(''copy-btn'');
    copyBtn.classList.remove(''done'');
    copyBtn.textContent = ''📋 一 键 复 制 全 部'';

    document.getElementById(''summary'').scrollIntoView({behavior:''smooth'', block:''start''});
  });

  // 复制
  document.getElementById(''copy-btn'').addEventListener(''click'', function(){
    var content = document.getElementById(''summary-content'').textContent;
    var btn = this;
    var done = function(){
      btn.classList.add(''done'');
      btn.textContent = ''✓ 已 复 制 成 功'';
      setTimeout(function(){
        btn.classList.remove(''done'');
        btn.textContent = ''📋 一 键 复 制 全 部'';
      }, 2000);
    };
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(content).then(done).catch(function(){
        fallback(content, done);
      });
    }else{
      fallback(content, done);
    }
  });

  function fallback(text, cb){
    var ta = document.createElement(''textarea'');
    ta.value = text;
    ta.style.position = ''fixed'';
    ta.style.opacity = ''0'';
    document.body.appendChild(ta);
    ta.select();
    try{ document.execCommand(''copy''); cb(); }catch(e){}
    document.body.removeChild(ta);
  }
})();
</script>
</body>
</html>', '都市', '2026-09-14 07:45:17', '2026-09-14 07:45:17', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_apocalypse_survival', '😱 末世求生录 😱 生存·性暴力·屈辱·征服·调教·末日', '末日废土 · 极境生存', '☣️', '末世求生录', '丧尸瘟疫核冬天 · 废土人性征服', '☣️', '#e17055', 'linear-gradient(135deg, #e17055 0%, #d63031 100%)', '{"desc": "在崩溃的世界中挣扎求生，你的极限生存在多少天。玩家在开局选择末世类型（丧尸、核战、瘟疫等22种题材），在资源匮乏、危机四伏的废土中寻找生存之路。体力、饥饿、口渴与性压抑的人性试炼。", "author": "AI风月精选"}', '[{"name": "苏晓染", "role": "21岁医学院校花幸存者 (167cm / 49kg / D罩杯)", "desc": "灾变前是全校公认的高岭之花医学生。末日爆发后在外独自逃亡三天，弹尽粮绝、衣衫破烂。为了获得一口干净的水和避难所的接纳，尊严与骄傲已被现实碾得粉碎，愿意接受一切屈辱的生存交换。"}, {"name": "玩家 (避难所支配者)", "role": "废土安全屋主宰", "desc": "掌控坚固地下防空洞、充足柴油、纯净水与武器储备的冷酷生存大师。"}]', '[{"title": "地下防空洞核心安全屋", "desc": "重型防爆钢门紧闭，柴油发电机轰鸣，桌上摆着纯净水与压缩饼干"}, {"title": "避难所消毒与检疫铁笼", "desc": "泛着锈迹与血斑的铁栏，剥光衣物进行全身体表感染排查的冰冷之地"}, {"title": "地表废墟物资搜刮掩体", "desc": "辐射酸雨滋滋作响的装甲车废墟，丧尸与掠夺者游荡的危险荒原"}]', '{}', '{"location": "避难所地下核心安全屋 · 辐射暴雨夜", "story": "厚重斑驳的防爆钢门将外界丧尸刺耳的抓挠声与酸雨腐蚀声彻底隔绝。\n防空洞深处，柴油发电机发出沉闷有力的轰鸣，昏黄的白炽灯在金属墙壁上投下斑驳长影。你坐在弹药箱上擦拭着自动霰弹枪，旁边的折叠桌上整齐地摆放着两瓶密封矿泉水、三袋军用高能压缩饼干与几板未拆封的阿莫西林抗生素——在这片秩序崩坏的废土上，这些就是主宰生死的硬通货。\n沉重的安全门闸传来转动声，一个被守卫反绑双手的年轻女人被粗暴地推倒在冰冷的水泥地上。\n她曾是医学院万人瞩目的清纯校花苏晓染。此刻，她身上的白衬衫与牛仔裤已被撕裂得多处走光，白皙如玉的肌肤上满是泥泞与擦伤，胸前发育绝佳的D罩杯双峰随着剧烈喘息大幅度起伏。干裂泛白的嘴唇紧紧抿着，饥饿与干渴让她浑身不受控制地发颤，眼神在触及桌上矿泉水的瞬间爆发出野兽般贪婪而绝望的渴望：“求求你……给我一口水喝……只要让我留在这……你让我做什么都可以……”", "branches": [{"tag": "A", "title": "拧开水壶倒出一小杯清水，命令她像狗一样爬过来喝", "desc": "以残酷的废土生存法则直接剥夺其残存的文明自尊，建立绝对的主奴支配从属【屈辱驯服: 击碎昔日校花自尊，以物资确立终身依附】"}, {"tag": "B", "title": "递过抗生素与半块压缩饼干，严肃考查其临床医学价值", "desc": "保持冷静克制，利用食物交换其医疗技能为庇护所团队服务【理性统合: 评估实用价值，建立高效分工契约】"}, {"tag": "C", "title": "举枪冷漠示意她退后，命令其当场脱光接受感染排查", "desc": "严厉执行末世防疫铁律，要求其脱掉所有衣物仔细检查全身有无抓伤咬痕【严苛检疫: 杜绝致命隐患，借检疫之名将春光尽收眼底】"}, {"tag": "D", "title": "反锁厚重防爆门，居高临下挑起她下巴行使领主特权", "desc": "当着她的面关上唯一生路，用粗糙的掌心揉捏其下颌迫使其屈从献身【强势占有: 撕碎所有文明遮羞布，直接确立私人肉便器地位】"}]}', '/* --- 末世科技风格（暗色系红色点缀）--- */

/* 1. 全局包裹层：高科技废土 */
.survival-interface {
    background: linear-gradient(135deg, #1a1d23 0%, #0f1115 100%);
    border-radius: 16px;
    padding: 24px;
    box-shadow: 
        0 20px 60px rgba(0, 0, 0, 0.5),
        0 0 0 1px rgba(239, 68, 68, 0.05) inset;
    position: relative;
    color: #c4c4c4;
    font-family: ''Segoe UI'', ''Roboto'', ''Microsoft YaHei'', sans-serif;
    line-height: 1.7;
    max-width: 900px;
    margin: 0 auto;
    overflow: hidden;
}

/* 顶部光晕效果 */
.survival-interface::after {
    content: '''';
    position: absolute;
    top: -50%; left: -50%;
    width: 200%; height: 200%;
    background: radial-gradient(circle at 20% 20%, rgba(239, 68, 68, 0.08) 0%, transparent 50%);
    pointer-events: none;
}

/* --- 1. 时间轴：现代终端风格 --- */
code.language-Time {
    display: block;
    background: linear-gradient(135deg, #0a0c10 0%, #13151a 100%);
    border: 1px solid rgba(239, 68, 68, 0.2);
    border-left: 4px solid #dc2626;
    padding: 16px 24px;
    color: #fca5a5;
    font-family: ''JetBrains Mono'', ''Fira Code'', monospace;
    margin-bottom: 24px;
    white-space: pre-wrap;
    box-shadow: 
        0 4px 20px rgba(0, 0, 0, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
    position: relative;
    border-radius: 8px;
}

/* --- 2. 折叠栏：玻璃卡片风格 --- */
details {
    border-radius: 12px;
    overflow: hidden;
    background: transparent;
    border: none;
    margin-bottom: 12px;
    transition: all 0.3s ease;
}

details[open] {
    /* 打开时不需要额外样式 */
}

summary {
    display: flex;
    align-items: center;
    padding: 16px 24px;
    font-weight: 600;
    color: #e0e0e0;
    background: rgba(26, 29, 35, 0.8);
    cursor: pointer;
    list-style: none;
    text-transform: uppercase;
    letter-spacing: 1px;
    transition: all 0.3s ease;
    position: relative;
    font-size: 14px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    backdrop-filter: blur(10px);
}

summary:hover {
    background: rgba(40, 44, 52, 0.9);
    color: #fff;
    border-color: rgba(239, 68, 68, 0.3);
}

/* 发光指示器 */
summary::before {
    content: ''▸'';
    margin-right: 12px;
    color: #dc2626;
    font-size: 12px;
    transition: transform 0.3s ease;
}

details[open] > summary::before {
    transform: rotate(90deg);
    color: #fca5a5;
}

/* 状态标签 */
summary::after {
    content: ''OFFLINE'';
    font-size: 10px;
    position: absolute;
    right: 24px;
    padding: 4px 10px;
    border-radius: 20px;
    background: rgba(239, 68, 68, 0.2);
    color: #ef4444;
    font-weight: 500;
    transition: all 0.3s ease;
}

details[open] > summary::after {
    content: ''ONLINE'';
    background: rgba(220, 38, 38, 0.2);
    color: #dc2626;
}

/* 🎯 折叠内容区：独立的深色卡片风格 */
details > *:not(summary) {
    background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
    margin-top: 8px;
    padding: 20px 24px;
    color: #c4c4c4;
    line-height: 1.7;
    font-size: 15px;
    position: relative;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    box-shadow: 
        0 4px 20px rgba(0, 0, 0, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

/* --- 3. 警告与威胁：现代化徽章 --- */
.threat-level {
    background: linear-gradient(135deg, rgba(239, 68, 68, 0.15) 0%, rgba(239, 68, 68, 0.05) 100%);
    color: #ef4444;
    padding: 6px 14px;
    font-weight: 600;
    border-radius: 20px;
    font-size: 12px;
    border: 1px solid rgba(239, 68, 68, 0.3);
    text-transform: uppercase;
    letter-spacing: 1px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.threat-level::before {
    content: ''⚠'';
    font-size: 10px;
}

.threat-level.low {
    background: linear-gradient(135deg, rgba(245, 158, 11, 0.15) 0%, rgba(245, 158, 11, 0.05) 100%);
    color: #f59e0b;
    border-color: rgba(245, 158, 11, 0.3);
}

.threat-level.low::before {
    content: ''⚡'';
}

.threat-level.medium {
    background: linear-gradient(135deg, rgba(249, 115, 22, 0.15) 0%, rgba(249, 115, 22, 0.05) 100%);
    color: #f97316;
    border-color: rgba(249, 115, 22, 0.3);
}

.threat-level.medium::before {
    content: ''◆'';
}

.threat-level.high {
    background: linear-gradient(135deg, rgba(220, 38, 38, 0.2) 0%, rgba(220, 38, 38, 0.08) 100%);
    color: #dc2626;
    border-color: rgba(220, 38, 38, 0.5);
    animation: threat-pulse 2s ease-in-out infinite;
}

.threat-level.high::before {
    content: ''⚠'';
}

@keyframes threat-pulse {
    0%, 100% { 
        box-shadow: 0 0 0 0 rgba(220, 38, 38, 0.4);
    }
    50% { 
        box-shadow: 0 0 0 8px rgba(220, 38, 38, 0);
    }
}

/* --- 4. 记忆栏与档案：数据卡片风格 --- */
.memory-zone {
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(26, 29, 35, 0.4);
    padding: 0;
    border-radius: 12px;
    margin-top: 16px;
    overflow: hidden;
    backdrop-filter: blur(10px);
}

/* 档案标题 */
.memory-zone-header {
    display: block;
    background: linear-gradient(135deg, #dc2626 0%, #b91c1c 100%);
    color: #fff;
    padding: 14px 24px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 2px;
    font-size: 12px;
    position: relative;
}

.memory-zone-header::before {
    content: ''📊'';
    margin-right: 8px;
}

.memory-item {
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    padding: 14px 24px;
    position: relative;
    transition: all 0.3s ease;
    color: #c4c4c4;
}

.memory-item::before {
    content: '''';
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    width: 4px;
    height: 4px;
    background: #dc2626;
    border-radius: 50%;
    box-shadow: 0 0 8px rgba(220, 38, 38, 0.5);
}

.memory-item:hover {
    background: rgba(220, 38, 38, 0.05);
    padding-left: 32px;
}

.memory-item:last-child {
    border-bottom: none;
}

/* --- 5. 分割线：现代分割线 --- */
hr {
    border: 0;
    height: 1px;
    background: linear-gradient(to right, transparent, rgba(239, 68, 68, 0.1), transparent);
    margin: 32px 0;
    position: relative;
}

/* --- 6. 强调文本：高亮标记 --- */
strong {
    color: #fca5a5;
    background: rgba(239, 68, 68, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
    font-weight: 600;
}

/* --- 7. 状态块和选项块：代码编辑器风格 --- */
.status-block, .options-block {
    background: linear-gradient(135deg, #0f1115 0%, #1a1d23 100%);
    border-radius: 12px;
    padding: 20px 24px;
    font-family: ''JetBrains Mono'', ''Fira Code'', monospace;
    font-size: 14px;
    line-height: 1.8;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-left: 4px solid #dc2626;
    white-space: pre-wrap;
    word-break: break-word;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
    color: #c4c4c4;
    position: relative;
}

/* 行号装饰 */
.status-block::before,
.options-block::before {
    content: '''';
    position: absolute;
    top: 0; left: 0; width: 4px; height: 100%;
    background: linear-gradient(180deg, #dc2626 0%, #b91c1c 100%);
}

/* --- 8. 响应式调整 --- */
@media (max-width: 768px) {
    .survival-interface {
        padding: 16px;
        border-radius: 12px;
    }
    
    summary {
        padding: 14px 20px;
        font-size: 13px;
    }
    
    summary::after {
        right: 20px;
        font-size: 9px;
    }
    
    .memory-zone-header {
        font-size: 11px;
        padding: 12px 20px;
    }
    
    .memory-item {
        padding: 12px 20px;
        font-size: 14px;
    }
    
    .status-block, .options-block {
        padding: 16px 20px;
        font-size: 13px;
    }
    
    details > *:not(summary) {
        padding: 16px 20px;
        font-size: 14px;
    }
}

/* --- 9. 对话颜色规范（现代风格）--- */
/* 玩家言语（暗红色） */
font[color="#00c6c6"],
.dialog-player {
    color: #ef4444 !important;
    font-weight: 600;
    background: rgba(239, 68, 68, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
}

/* 女性NPC言语（粉紫色） */
font[color="#FF2D2D"],
.dialog-female {
    color: #fca5a5 !important;
    font-style: italic;
    background: rgba(252, 165, 165, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
}

/* 男性NPC言语（橙红色） */
font[color="#ea0029"],
.dialog-male {
    color: #f97316 !important;
    font-weight: 600;
    background: rgba(249, 115, 22, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
}

/* --- 10. 实用工具类 --- */
.glow-indigo {
    color: #dc2626;
    text-shadow: 0 0 20px rgba(220, 38, 38, 0.5);
}

.border-glass {
    border: 1px solid rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(10px);
}

.bg-dark-tech {
    background: linear-gradient(135deg, #1a1d23 0%, #0f1115 100%);
}

.text-gradient {
    background: linear-gradient(135deg, #dc2626 0%, #ef4444 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.card-hover {
    transition: all 0.3s ease;
}

.card-hover:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>末世生存档案</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    /* --- 末世科技风格 (精致版) --- */
    
    body {
      margin: 0;
      padding: 0;
      font-family: ''Segoe UI'', ''Roboto'', ''Microsoft YaHei'', sans-serif;
      background: url(''https://i.postimg.cc/J0hd1jJ6/1.png'') center/cover no-repeat fixed;
      min-height: 100vh;
      color: #c4c4c4;
      line-height: 1.7;
    }
    
    body::before {
      content: '''';
      position: fixed;
      top: 0; left: 0; width: 100%; height: 100%;
      background: linear-gradient(135deg, rgba(0, 0, 0, 0.3) 0%, rgba(0, 0, 0, 0.4) 100%);
      z-index: 0;
    }
    
    .tech-container {
      position: relative;
      min-height: 100vh;
      padding: 24px;
      z-index: 1;
    }
    
    .tech-music-btn {
      width: 56px;
      height: 56px;
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      border: 2px solid rgba(255, 255, 255, 0.1);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: all 0.3s ease;
      box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
      position: relative;
      z-index: 10;
      pointer-events: auto;
    }
    
    .tech-music-btn:hover {
      transform: scale(1.1);
      border-color: rgba(255, 255, 255, 0.3);
      box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4), 0 0 20px rgba(255, 255, 255, 0.1);
    }
    
    .tech-action-card {
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 12px;
      padding: 12px 24px;
      min-width: 200px;
      cursor: pointer;
      transition: all 0.3s ease;
      position: relative;
      box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
    }
    
    .tech-action-card:hover {
      transform: translateY(-2px);
      border-color: rgba(255, 255, 255, 0.2);
      box-shadow: 0 6px 25px rgba(0, 0, 0, 0.3), 0 0 20px rgba(255, 255, 255, 0.05);
    }
    
    .tech-action-card::before {
      content: '''';
      position: absolute;
      top: -4px;
      left: 50%;
      transform: translateX(-50%);
      width: 40px;
      height: 12px;
      background: rgba(255, 255, 255, 0.05);
      border-radius: 6px;
      backdrop-filter: blur(5px);
    }
    
    .tech-modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0, 0, 0, 0.8);
      backdrop-filter: blur(10px);
      z-index: 50;
      display: none;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }
    
    .tech-modal-overlay.active {
      display: flex;
    }
    
    .tech-modal {
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 16px;
      max-width: 800px;
      width: 100%;
      max-height: 80vh;
      display: flex;
      flex-direction: column;
      overflow: hidden;
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    }
    
    .tech-modal-header {
      padding: 24px;
