<script>
(function(){
''use strict'';
var $=function(id){return document.getElementById(id)};
var $$=function(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s))};

/* =========================================================
   音效引擎
========================================================= */
var SND={
  ctx:null,master:null,sg:null,mg:null,musicOn:true,_noise:null,_ch:null,_mtimer:null,
  ensure:function(){
    if(this.ctx){ if(this.ctx.state===''suspended'') this.ctx.resume(); return; }
    var C=window.AudioContext||window.webkitAudioContext; if(!C) return;
    this.ctx=new C();
    this.master=this.ctx.createGain(); this.master.gain.value=.9; this.master.connect(this.ctx.destination);
    this.sg=this.ctx.createGain(); this.sg.connect(this.master);
    this.mg=this.ctx.createGain(); this.mg.gain.value=0; this.mg.connect(this.master);
    this.startPad(); this.applyMusic();
  },
  noiseBuf:function(){
    if(this._noise) return this._noise;
    var b=this.ctx.createBuffer(1,this.ctx.sampleRate,this.ctx.sampleRate),d=b.getChannelData(0);
    for(var i=0;i<d.length;i++) d[i]=Math.random()*2-1;
    this._noise=b; return b;
  },
  tone:function(o){
    if(!this.ctx) return;
    var t=this.ctx.currentTime+(o.delay||0),dur=o.dur||.2;
    var osc=this.ctx.createOscillator(),g=this.ctx.createGain();
    osc.type=o.type||''sine''; osc.frequency.setValueAtTime(o.f,t);
    if(o.f2) osc.frequency.exponentialRampToValueAtTime(Math.max(o.f2,1),t+dur);
    g.gain.setValueAtTime(0,t);
    g.gain.linearRampToValueAtTime(o.vol||.2,t+(o.at||.012));
    g.gain.exponentialRampToValueAtTime(.0001,t+dur);
    osc.connect(g); g.connect(o.dest||this.sg);
    osc.start(t); osc.stop(t+dur+.05);
  },
  noise:function(o){
    if(!this.ctx) return;
    var t=this.ctx.currentTime+(o.delay||0),dur=o.dur||.25;
    var src=this.ctx.createBufferSource(); src.buffer=this.noiseBuf(); src.loop=true;
    var fl=this.ctx.createBiquadFilter(); fl.type=o.ft||''bandpass''; fl.Q.value=o.q||1;
    fl.frequency.setValueAtTime(o.f||800,t);
    if(o.f2) fl.frequency.exponentialRampToValueAtTime(Math.max(o.f2,20),t+dur);
    var g=this.ctx.createGain();
    g.gain.setValueAtTime(0,t);
    g.gain.linearRampToValueAtTime(o.vol||.25,t+(o.at||.015));
    g.gain.exponentialRampToValueAtTime(.0001,t+dur);
    src.connect(fl); fl.connect(g); g.connect(o.dest||this.sg);
    src.start(t); src.stop(t+dur+.1);
  },
  click:function(){ this.tone({f:1250,dur:.05,type:''triangle'',vol:.1}); this.tone({f:2500,dur:.03,type:''sine'',vol:.04}); },
  panel:function(open){ this.noise({f:open%s260:1600,f2:open%s1800:240,dur:.22,vol:.14}); this.tone({f:open%s320:620,f2:open%s640:300,dur:.2,type:''sine'',vol:.1}); },
  drawer:function(open){ this.noise({f:open%s180:1400,f2:open%s1500:160,dur:.32,vol:.16}); this.tone({f:open%s240:560,f2:open%s520:240,dur:.28,type:''triangle'',vol:.12}); },
  tick:function(f){ this.tone({f:f,dur:.045,type:''square'',vol:.055}); },
  ring:function(c){
    var m={w:340,y:440,p:560,b:170,r:680,o:820};
    this.tone({f:m[c]||420,dur:.1,type:''triangle'',vol:.15});
    if(c===''b'') this.noise({f:120,dur:.16,vol:.1,ft:''lowpass''});
    if(c===''r'') this.tone({f:1360,dur:.14,type:''sine'',vol:.08,delay:.05});
    if(c===''o''){ this.tone({f:1640,dur:.2,type:''sine'',vol:.1,delay:.06}); this.noise({f:4000,f2:8000,dur:.2,vol:.05,ft:''highpass''}); }
  },
  add:function(){ this.tone({f:620,f2:980,dur:.14,type:''triangle'',vol:.14}); },
  del:function(){ this.tone({f:320,f2:150,dur:.16,type:''sawtooth'',vol:.1}); },
  toggle:function(on){ on%s(this.tone({f:520,dur:.09,type:''sine'',vol:.13}),this.tone({f:780,dur:.12,type:''sine'',vol:.13,delay:.08})):this.tone({f:600,f2:300,dur:.16,type:''sine'',vol:.12}); },
  segSel:function(){ this.tone({f:880,dur:.07,type:''triangle'',vol:.12}); this.tone({f:1320,dur:.1,type:''sine'',vol:.09,delay:.06}); },
  modal:function(open){ open%sthis.tone({f:180,f2:360,dur:.3,type:''sine'',vol:.16}):this.tone({f:360,f2:180,dur:.24,type:''sine'',vol:.12}); this.noise({f:open%s400:900,f2:open%s1200:300,dur:.2,vol:.08}); },
  select:function(){ this.tone({f:980,dur:.1,type:''sine'',vol:.14}); this.tone({f:1470,dur:.16,type:''sine'',vol:.1,delay:.07}); },
  bookFlip:function(){ this.noise({f:900,f2:2600,dur:.32,vol:.14,q:.8}); this.tone({f:400,f2:640,dur:.24,type:''sine'',vol:.07}); },
  levelUp:function(){ this.tone({f:523,dur:.1,type:''triangle'',vol:.13}); this.tone({f:784,dur:.16,type:''triangle'',vol:.13,delay:.08}); },
  chargeStart:function(){
    if(!this.ctx) return;
    this.chargeStop(true);
    var t=this.ctx.currentTime;
    var o=this.ctx.createOscillator(),g=this.ctx.createGain(),f=this.ctx.createBiquadFilter();
    o.type=''sawtooth''; f.type=''lowpass''; f.frequency.value=900;
    o.frequency.setValueAtTime(70,t);
    o.frequency.exponentialRampToValueAtTime(620,t+3);
    g.gain.setValueAtTime(.001,t); g.gain.linearRampToValueAtTime(.13,t+.15);
    o.connect(f); f.connect(g); g.connect(this.sg); o.start();
    this._ch={o:o,g:g};
  },
  chargeStop:function(silent){
    if(!this._ch) return;
    var c=this._ch; this._ch=null;
    try{
      var t=this.ctx.currentTime;
      c.g.gain.cancelScheduledValues(t); c.g.gain.setValueAtTime(c.g.gain.value,t);
      c.g.gain.linearRampToValueAtTime(0,t+.08); c.o.stop(t+.12);
    }catch(e){}
    if(!silent) this.tone({f:420,f2:160,dur:.2,type:''sine'',vol:.1});
  },
  noDraw:function(){ this.tone({f:640,f2:260,dur:.16,type:''sine'',vol:.08}); },
  tierUp:function(n){
    var f=[523,622,740,880,1047][n]||523;
    this.tone({f:f,dur:.2,type:''triangle'',vol:.15});
    this.tone({f:f*1.5,dur:.26,type:''sine'',vol:.1,delay:.05});
    this.noise({f:2500,f2:8000,dur:.18,vol:.06,ft:''highpass''});
  },
  reveal:function(r){
    var seq={
      waste:[[300,0],[236,.09]],
      common:[[420,0],[560,.1]],
      rare:[[440,0],[554,.09],[659,.18]],
      epic:[[440,0],[554,.08],[659,.16],[880,.24]],
      legend:[[523,0],[659,.08],[784,.16],[1047,.24],[1319,.36]],
      god:[[392,0],[523,.07],[659,.14],[784,.21],[1047,.28],[1568,.4]]
    }[r]||[[440,0]];
    for(var i=0;i<seq.length;i++){
      this.tone({f:seq[i][0],dur:(r===''god''||r===''legend'')%s.5:.3,type:''sine'',vol:.16,delay:seq[i][1]});
      if(r===''god''||r===''legend'') this.tone({f:seq[i][0]*1.5,dur:.4,type:''triangle'',vol:.07,delay:seq[i][1]});
    }
    if(r===''god'') this.noise({f:2000,f2:9000,dur:.8,vol:.08,ft:''highpass'',delay:.3});
  },
  thunder:function(){ this.noise({f:320,f2:50,dur:1,vol:.4,ft:''lowpass''}); this.tone({f:64,f2:26,dur:.9,type:''sine'',vol:.4}); },
  fallWhoosh:function(){ this.noise({f:220,f2:2600,dur:.8,vol:.3,q:.7}); },
  hammerHit:function(){
    this.tone({f:130,f2:28,dur:.55,type:''sine'',vol:.85});
    this.noise({f:3200,f2:160,dur:.4,vol:.5});
    this.tone({f:420,dur:.5,type:''sine'',vol:.1,delay:.02});
    this.tone({f:640,dur:.45,type:''sine'',vol:.08,delay:.03});
  },
  shatter:function(){
    this.tone({f:110,f2:26,dur:.5,type:''sine'',vol:.6});
    this.noise({f:5000,f2:1200,dur:.5,vol:.35,ft:''highpass''});
    for(var i=0;i<16;i++) this.tone({f:1600+Math.random()*3800,dur:.1+Math.random()*.2,type:''triangle'',vol:.05,delay:Math.random()*.45});
  },
  startPad:function(){
    var t=this.ctx.currentTime;
    [[110,.05,''sine''],[164.81,.04,''sine''],[220.5,.025,''triangle'']].forEach(function(p){
      var o=SND.ctx.createOscillator(),g=SND.ctx.createGain();
      o.type=p[2]; o.frequency.value=p[0]; g.gain.value=p[1];
      o.connect(g); g.connect(SND.mg); o.start(t);
    });
    this._mtimer=setInterval(function(){
      if(!SND.musicOn||!SND.ctx||SND.ctx.state!==''running'') return;
      if(Math.random()<.25) return;
      var sc=[440,523.25,587.33,659.25,783.99,880];
      var f=sc[Math.floor(Math.random()*sc.length)];
      SND.tone({f:f,dur:2.8,type:''sine'',vol:.05,dest:SND.mg});
      SND.tone({f:f/2,dur:2.4,type:''sine'',vol:.03,delay:.5,dest:SND.mg});
    },2600);
  },
  applyMusic:function(){
    if(!this.ctx) return;
if(BG_MUSIC_URL) return;
    var t=this.ctx.currentTime;
    this.mg.gain.cancelScheduledValues(t);
    this.mg.gain.setValueAtTime(this.mg.gain.value,t);
    this.mg.gain.linearRampToValueAtTime(this.musicOn%s1:0,t+.8);
  }
};
document.addEventListener(''pointerdown'',function(){ SND.ensure(); },true);

/* ===== Toast / 复制 ===== */
var toastTimer=null;
function toast(msg){
  var t=$(''toast''); t.textContent=msg; t.classList.add(''show'');
  clearTimeout(toastTimer); toastTimer=setTimeout(function(){ t.classList.remove(''show''); },2400);
}
function copyText(txt,okMsg){
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(txt).then(function(){ toast(okMsg||''已复制到剪贴板''); SND.select(); },function(){ fallbackCopy(txt,okMsg); });
  } else fallbackCopy(txt,okMsg);
}
function fallbackCopy(txt,okMsg){
  var ta=document.createElement(''textarea''); ta.value=txt;
  ta.style.cssText=''position:fixed;opacity:0''; document.body.appendChild(ta);
  ta.select(); try{ document.execCommand(''copy''); toast(okMsg||''已复制到剪贴板''); SND.select(); }catch(e){ toast(''复制失败，请手动选择复制''); }
  document.body.removeChild(ta);
}

