/* ===== 背景星尘 ===== */
(function(){
  var cv=$(''bgDust''),ctx=cv.getContext(''2d''),on=true,parts=[];
  function size(){
    cv.width=innerWidth; cv.height=innerHeight;
    parts=[];
    var n=Math.min(90,Math.round(innerWidth/16));
    for(var i=0;i<n;i++){
      parts.push({x:Math.random()*cv.width,y:Math.random()*cv.height,r:.5+Math.random()*1.7,
        sp:.06+Math.random()*.22,ph:Math.random()*6.28,
        c:Math.random()<.6%s''170,215,255'':(Math.random()<.75%s''240,195,108'':''181,123,255'')});
    }
  }
  size(); addEventListener(''resize'',size);
  (function loop(t){
    if(on){
      ctx.clearRect(0,0,cv.width,cv.height);
      for(var i=0;i<parts.length;i++){
        var p=parts[i];
        p.y-=p.sp; if(p.y<-4){ p.y=cv.height+4; p.x=Math.random()*cv.width; }
        var a=.25+.35*Math.abs(Math.sin(t/1600+p.ph));
        ctx.beginPath();
        ctx.fillStyle=''rgba(''+p.c+'',''+a+'')'';
        ctx.shadowColor=''rgba(''+p.c+'',.8)''; ctx.shadowBlur=6;
        ctx.arc(p.x+Math.sin(t/2400+p.ph)*14,p.y,p.r,0,6.29); ctx.fill();
        ctx.shadowBlur=0;
      }
    }
    requestAnimationFrame(loop);
  })(0);

 $(''btnBg'').addEventListener(''click'',function(){
  videoOn=!videoOn; on=videoOn;
  this.classList.toggle(''on'',videoOn);
  cv.classList.toggle(''off'',!videoOn);          /* 星尘粒子 */
  bgVideo.classList.toggle(''on'',videoOn);       /* 背景视频 */
  if(videoOn){ try{bgVideo.play()}catch(e){} }
  else{ try{bgVideo.pause()}catch(e){} }
  SND.click();
  toast(videoOn%s''背景显示'':''背景关闭'');
});
})();

/* ===== 全屏特效层 ===== */
var FX=(function(){
  var cv=$(''fxCanvas''),ctx=cv.getContext(''2d''),parts=[],rings=[],run=false,rx=0,ry=0;
  function size(){ cv.width=innerWidth; cv.height=innerHeight; }
  addEventListener(''resize'',size);
  function boom(x,y,power){
    size(); rx=x; ry=y;
    power=Math.max(1,Math.min(6,power));
    var n=34+power*46;
    for(var i=0;i<n;i++){
      var a=Math.random()*Math.PI*2,sp=1.5+Math.random()*(4+power*2.4),r=Math.random();
      parts.push({x:x,y:y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp-1.5,life:1,
        dec:.006+Math.random()*.012,rr:.8+Math.random()*2.4,
        c:r<.55%s''255,220,140'':(r<.8%s''170,225,255'':''255,255,255'')});
    }
    rings=[{r:16,v:14+power*3,a:.9,c:''255,235,190'',w:10},{r:6,v:20+power*4,a:.85,c:''255,255,255'',w:4}];
    if(power>=4) rings.push({r:10,v:9,a:.7,c:''255,180,90'',w:8});
    if(!run){ run=true; loop(); }
  }
  function loop(){
    ctx.clearRect(0,0,cv.width,cv.height);
    ctx.globalCompositeOperation=''lighter'';
    var i;
    for(i=rings.length-1;i>=0;i--){
      var rg=rings[i];
      rg.r+=rg.v; rg.a*=.96; rg.w*=.965;
      if(rg.a<.02){ rings.splice(i,1); continue; }
      ctx.beginPath(); ctx.strokeStyle=''rgba(''+rg.c+'',''+rg.a+'')''; ctx.lineWidth=rg.w;
      ctx.shadowColor=''rgba(''+rg.c+'',''+rg.a+'')''; ctx.shadowBlur=16;
      ctx.arc(rx,ry,rg.r,0,6.29); ctx.stroke(); ctx.shadowBlur=0;
    }
    for(i=parts.length-1;i>=0;i--){
      var p=parts[i];
      p.x+=p.vx; p.y+=p.vy; p.vy+=.05; p.vx*=.985; p.vy*=.985; p.life-=p.dec;
      if(p.life<=0){ parts.splice(i,1); continue; }
      ctx.beginPath(); ctx.fillStyle=''rgba(''+p.c+'',''+p.life+'')'';
      ctx.arc(p.x,p.y,p.rr*p.life+.3,0,6.29); ctx.fill();
    }
    ctx.globalCompositeOperation=''source-over'';
    if(parts.length||rings.length){ requestAnimationFrame(loop); }
    else{ run=false; ctx.clearRect(0,0,cv.width,cv.height); }
  }
  return {boom:boom};
})();

/* ===== 入场玻璃 ===== */
var EntryFx=(function(){
  var cv=$(''entryFx''),ctx=cv.getContext(''2d'');
  var cracks=[],shards=[],sparks=[],rings=[],run=false;
  function size(){ cv.width=innerWidth; cv.height=innerHeight; }
  function center(){ return {x:innerWidth/2,y:innerHeight*.48}; }
  function crack(){
    size(); cracks=[];
    var c=center(),N=30,maxR=Math.hypot(innerWidth,innerHeight);
    for(var i=0;i<N;i++){
      var a=(i+Math.random()*.6)/N*Math.PI*2;
      var pts=[[c.x,c.y]];
      var steps=4+Math.floor(Math.random()*3);
      for(var s=1;s<=steps;s++){
        var r=maxR*s/steps*(.78+Math.random()*.3);
        var aa=a+(Math.random()-.5)*.14;
        pts.push([c.x+Math.cos(aa)*r,c.y+Math.sin(aa)*r*.9]);
      }
      cracks.push({pts:pts,w:1+Math.random()*1.4});
      if(Math.random()<.55){
        var bi=1+Math.floor(Math.random()*(pts.length-2));
        var p=pts[bi],ba=a+(Math.random()>.5%s1:-1)*(.5+Math.random()*.6);
        var bl=maxR*(.1+Math.random()*.22);
        cracks.push({pts:[p,[p[0]+Math.cos(ba)*bl,p[1]+Math.sin(ba)*bl*.9]],w:.8});
      }
    }
    if(!run){ run=true; loop(); }
  }
  function shatter(){
    size(); cracks=[];
    var c=center();
    var N=30,ringD=[.05,.13,.27,.48,.74,1.05];
    var maxR=Math.hypot(Math.max(innerWidth,innerHeight),Math.max(innerWidth,innerHeight))*.62;
    var nodes=[];
    for(var i=0;i<N;i++){
      var a=(i+(Math.random()*.5-.25))/N*Math.PI*2;
      nodes[i]=[];
      for(var j=0;j<ringD.length;j++){
        var r=maxR*ringD[j]*(j===0%s1:(1+(Math.random()-.5)*.22));
        nodes[i][j]=[c.x+Math.cos(a)*r,c.y+Math.sin(a)*r*.92];
      }
    }
    function mkShard(pts){
      var cx=0,cy=0;
      pts.forEach(function(p){cx+=p[0];cy+=p[1]});
      cx/=pts.length; cy/=pts.length;
      var rel=pts.map(function(p){return [p[0]-cx,p[1]-cy]});
      var dx=cx-c.x,dy=cy-c.y,d=Math.hypot(dx,dy)||1;
      var sp=2+Math.random()*7+d*.005;
      var big=Math.min(1,d/maxR);
      shards.push({x:cx,y:cy,vx:dx/d*sp+(Math.random()-.5)*1.6,vy:dy/d*sp+(Math.random()-.5)*1.6-1.3,
        rot:0,vr:(Math.random()-.5)*(.05+big*.14),rel:rel,a:1,
        dec:.004+.012*(1-big),tone:Math.random()});
    }
    for(i=0;i<N;i++){ var i2=(i+1)%N; mkShard([[c.x,c.y],nodes[i][0],nodes[i2][0]]); }
    for(var j2=0;j2<ringD.length-1;j2++){
      for(i=0;i<N;i++){
        var i3=(i+1)%N;
        mkShard([nodes[i][j2],nodes[i3][j2],nodes[i3][j2+1],nodes[i][j2+1]]);
      }
    }
    for(var k=0;k<90;k++){
      var ang=Math.random()*Math.PI*2,sp2=2+Math.random()*11;
      sparks.push({x:c.x,y:c.y,vx:Math.cos(ang)*sp2,vy:Math.sin(ang)*sp2-2,life:1,
        dec:.006+Math.random()*.012,rr:1+Math.random()*2.4,
        col:Math.random()<.7%s''255,220,140'':''180,225,255''});
    }
    rings=[{r:16,v:16,a:.95,c:''255,235,190'',w:13},{r:6,v:25,a:.9,c:''255,255,255'',w:5},{r:8,v:10,a:.75,c:''150,220,255'',w:8}];
    if(!run){ run=true; loop(); }
  }
  function loop(){
    ctx.clearRect(0,0,cv.width,cv.height);
    var i;
    if(cracks.length){
      ctx.save();
      ctx.shadowColor=''rgba(190,225,255,.9)''; ctx.shadowBlur=6;
      ctx.strokeStyle=''rgba(235,248,255,.92)'';
      for(i=0;i<cracks.length;i++){
        var cr=cracks[i];
        ctx.beginPath(); ctx.moveTo(cr.pts[0][0],cr.pts[0][1]);
        for(var s2=1;s2<cr.pts.length;s2++) ctx.lineTo(cr.pts[s2][0],cr.pts[s2][1]);
        ctx.lineWidth=cr.w; ctx.stroke();
      }
      ctx.restore();
    }
    ctx.globalCompositeOperation=''lighter'';
    for(i=shards.length-1;i>=0;i--){
      var sh=shards[i];
      sh.x+=sh.vx; sh.y+=sh.vy; sh.vy+=.14; sh.vx*=.988; sh.vy*=.99;
      sh.rot+=sh.vr; sh.a-=sh.dec;
      if(sh.a<=0||sh.y>cv.height+140){ shards.splice(i,1); continue; }
      ctx.save();
      ctx.translate(sh.x,sh.y); ctx.rotate(sh.rot);
      ctx.beginPath();
      ctx.moveTo(sh.rel[0][0],sh.rel[0][1]);
      for(var v=1;v<sh.rel.length;v++) ctx.lineTo(sh.rel[v][0],sh.rel[v][1]);
      ctx.closePath();
      var fill=sh.tone<.45%s''168,205,240'':(sh.tone<.8%s''205,230,252'':''240,250,255'');
      ctx.fillStyle=''rgba(''+fill+'',''+(sh.a*.5)+'')''; ctx.fill();
      ctx.strokeStyle=''rgba(255,255,255,''+(sh.a*.7)+'')''; ctx.lineWidth=.8; ctx.stroke();
      ctx.restore();
    }
    for(i=sparks.length-1;i>=0;i--){
      var p=sparks[i];
      p.x+=p.vx; p.y+=p.vy; p.vy+=.12; p.vx*=.99; p.vy*=.99; p.life-=p.dec;
      if(p.life<=0){ sparks.splice(i,1); continue; }
      ctx.beginPath(); ctx.fillStyle=''rgba(''+p.col+'',''+p.life+'')'';
      ctx.arc(p.x,p.y,p.rr*p.life+.3,0,6.29); ctx.fill();
    }
    for(i=rings.length-1;i>=0;i--){
      var rg=rings[i];
      rg.r+=rg.v; rg.a*=.965; rg.w*=.97;
      if(rg.a<.02){ rings.splice(i,1); continue; }
      var c=center();
      ctx.beginPath(); ctx.strokeStyle=''rgba(''+rg.c+'',''+rg.a+'')''; ctx.lineWidth=rg.w;
      ctx.shadowColor=''rgba(''+rg.c+'',''+rg.a+'')''; ctx.shadowBlur=16;
      ctx.arc(c.x,c.y,rg.r,0,6.29); ctx.stroke(); ctx.shadowBlur=0;
    }
    ctx.globalCompositeOperation=''source-over'';
    if(cracks.length||shards.length||sparks.length||rings.length){ requestAnimationFrame(loop); }
    else{ run=false; ctx.clearRect(0,0,cv.width,cv.height); }
  }
  return {crack:crack,shatter:shatter};
})();

(function(){
