var CHARGE_MAX=3000;
var TIERS=[
 {label:''凡引'',ru:''觉醒'',m:''指尖轻触 · 凡引觉醒'',core:''255,248,225'',n1:''240,195,108'',n2:''108,208,255'',n3:''181,123,255'',ring:''240,195,108'',glow:''70,140,220'',bolt:''255,225,160'',sparks:''255,240,200''},
 {label:''灵引'',ru:''凝魂'',m:''蓄力一档 · 灵引觉醒'',core:''230,255,250'',n1:''143,227,216'',n2:''108,208,255'',n3:''200,255,240'',ring:''143,227,216'',glow:''80,200,190'',bolt:''190,255,245'',sparks:''210,255,250''},
 {label:''天引'',ru:''聚灵'',m:''蓄力二档 · 天引觉醒'',core:''245,235,255'',n1:''181,123,255'',n2:''143,227,216'',n3:''216,180,255'',ring:''181,123,255'',glow:''150,100,255'',bolt:''225,195,255'',sparks:''235,215,255''},
 {label:''圣引'',ru:''通天'',m:''蓄力三档 · 圣引觉醒'',core:''255,242,215'',n1:''255,150,80'',n2:''240,195,108'',n3:''255,94,108'',ring:''255,150,60'',glow:''255,150,60'',bolt:''255,220,170'',sparks:''255,230,190''},
 {label:''神引'',ru:''天命'',m:''蓄力圆满 · 神引天命'',core:''255,255,255'',n1:''255,225,150'',n2:''255,255,255'',n3:''240,195,108'',ring:''255,240,200'',glow:''255,220,150'',bolt:''255,255,255'',sparks:''255,250,230''}
];
function tierOf(ch){
  var p=Math.min(1,ch/CHARGE_MAX);
  if(p>=1) return 4; if(p>=.75) return 3; if(p>=.5) return 2; if(p>=.25) return 1;
  return 0;
}

/* =========================================================
   命运水晶球
========================================================= */
var Orb=(function(){
  var cv=$(''orbCanvas''),wrap=$(''orbWrap''),stage=$(''awakenStage''),runes=$(''orbRunes'');
  var ctx=cv.getContext(''2d'');
  var dpr=Math.min(window.devicePixelRatio||1,2);
  var W=0,cx=0,cy=0,R=0;
  var t=0,spin=0,coreFlash=0;
  var pressed=false,charge=0,curTier=0,pT=0,ptr={x:0,y:0};
  var inner=[],flows=[],shocks=[],orbSparks=[];

  function resize(){
    var s=wrap.clientWidth||300;
    W=s; cx=s/2; cy=s/2; R=s*.40;
    cv.width=Math.round(s*dpr); cv.height=Math.round(s*dpr);
    cv.style.width=s+''px''; cv.style.height=s+''px'';
    ctx.setTransform(dpr,0,0,dpr,0,0);
    inner=[];
    for(var i=0;i<26;i++){
      inner.push({a:Math.random()*6.28,r:Math.sqrt(Math.random())*R*.85,
        pr:.6+Math.random()*1.4,al:.25+Math.random()*.5,sp:.15+Math.random()*.5});
    }
  }
  resize(); addEventListener(''resize'',resize);

  function bolt(x1,y1,x2,y2,amp,width,branch,col){
    var n=7,pts=[[x1,y1]],i;
    var dx=-(y2-y1),dy=(x2-x1),L=Math.hypot(dx,dy)||1; dx/=L; dy/=L;
    for(i=1;i<n;i++){
      var k=i/n,mx=x1+(x2-x1)*k,my=y1+(y2-y1)*k;
      var off=(Math.random()-.5)*amp*Math.sin(Math.PI*k);
      pts.push([mx+dx*off,my+dy*off]);
    }
    pts.push([x2,y2]);
    ctx.beginPath(); ctx.moveTo(pts[0][0],pts[0][1]);
    for(i=1;i<pts.length;i++) ctx.lineTo(pts[i][0],pts[i][1]);
    ctx.strokeStyle=''rgba(''+col+'',''+(.35+charge*.0003)+'')'';
    ctx.lineWidth=width*2.6; ctx.shadowColor=''rgba(''+col+'',.9)''; ctx.shadowBlur=10; ctx.stroke();
    ctx.strokeStyle=''rgba(255,255,255,.9)''; ctx.lineWidth=width; ctx.shadowBlur=0; ctx.stroke();
    if(branch){
      for(i=2;i<n-1;i+=3){
        if(Math.random()<.55){
          var p=pts[i],ang=Math.random()*6.28,len=amp*(.4+Math.random()*.6);
          ctx.beginPath(); ctx.moveTo(p[0],p[1]);
          ctx.lineTo(p[0]+Math.cos(ang)*len*.5+(Math.random()-.5)*8,p[1]+Math.sin(ang)*len*.5+(Math.random()-.5)*8);
          ctx.lineTo(p[0]+Math.cos(ang)*len,p[1]+Math.sin(ang)*len);
          ctx.strokeStyle=''rgba(220,240,255,.45)''; ctx.lineWidth=width*.5; ctx.stroke();
        }
      }
    }
  }

  function frame(){
    t+=1/60;
    var T=TIERS[curTier];
    var heat=Math.min(1,charge/CHARGE_MAX);
    ctx.clearRect(0,0,W,W);

    if(pressed){
      charge+=1000/60;
      var nt=tierOf(charge);
      if(nt>curTier){
        curTier=nt; T=TIERS[curTier];
        coreFlash=1;
        shocks.push({r:R*.15,v:R*.07,a:.85},{r:R*.3,v:R*.05,a:.6});
        SND.tierUp(nt);
        runes.textContent=T.ru;
        if(navigator.vibrate) navigator.vibrate(30);
      }
      wrap.classList.toggle(''charged'',curTier>=4);
    }

    var og=ctx.createRadialGradient(cx,cy,R*.5,cx,cy,R*1.35);
    og.addColorStop(0,''rgba(''+T.glow+'',''+(.3+heat*.3+coreFlash*.4)+'')'');
    og.addColorStop(.65,''rgba(''+T.glow+'',.12)'');
    og.addColorStop(1,''rgba(20,60,120,0)'');
    ctx.fillStyle=og; ctx.beginPath(); ctx.arc(cx,cy,R*1.35,0,6.29); ctx.fill();

    var base=ctx.createRadialGradient(cx-R*.35,cy-R*.42,R*.05,cx,cy,R);
    base.addColorStop(0,''rgba(228,246,255,.95)'');
    base.addColorStop(.28,''rgba(155,208,255,.6)'');
    base.addColorStop(.62,''rgba(60,125,205,.55)'');
    base.addColorStop(1,''rgba(8,28,66,.94)'');
    ctx.fillStyle=base; ctx.beginPath(); ctx.arc(cx,cy,R,0,6.29); ctx.fill();

    ctx.globalCompositeOperation=''lighter'';
    var blobs=[
      {r:R*.5,sp:.45,ph:0,c:T.n1,a:.3},
      {r:R*.62,sp:-.3,ph:2.1,c:T.n2,a:.26},
      {r:R*.4,sp:.62,ph:4.2,c:T.n3,a:.22}
    ];
    for(var i=0;i<blobs.length;i++){
      var b=blobs[i],ang=t*b.sp*(1+heat*2.4)+b.ph;
      var bx=cx+Math.cos(ang)*b.r*.55, by=cy+Math.sin(ang)*b.r*.4;
      var g=ctx.createRadialGradient(bx,by,0,bx,by,R*.5);
      g.addColorStop(0,''rgba(''+b.c+'',''+(b.a+heat*.25+coreFlash*.3)+'')'');
      g.addColorStop(1,''rgba(''+b.c+'',0)'');
      ctx.fillStyle=g; ctx.beginPath(); ctx.arc(bx,by,R*.5,0,6.29); ctx.fill();
    }
    spin+=.007+heat*.06+coreFlash*.02;
    ctx.save(); ctx.translate(cx,cy); ctx.rotate(spin);
    for(i=0;i<5;i++){
      var rr=R*(.34+.13*i);
      ctx.beginPath(); ctx.arc(0,0,rr,i*1.26,i*1.26+1.05+heat*.7);
      ctx.strokeStyle=''rgba(''+T.ring+'',''+(.12+heat*.24)+'')''; ctx.lineWidth=1.6; ctx.stroke();
    }
    ctx.restore();

    for(i=0;i<inner.length;i++){
      var p=inner[i]; p.a+=p.sp*.01*(1+heat*3);
      var px=cx+Math.cos(p.a)*p.r, py=cy+Math.sin(p.a)*p.r*.92;
      var al=p.al*(.6+.4*Math.sin(t*2+p.a*3))*(1+heat*.6);
      ctx.beginPath(); ctx.fillStyle=''rgba(''+T.sparks+'',''+Math.min(1,al)+'')'';
      ctx.arc(px,py,p.pr*(1+heat*.5),0,6.29); ctx.fill();
    }

    var coreR=R*.2*(1+.13*Math.sin(t*2.3))*(1+heat*.45+coreFlash*.9);
    var cg=ctx.createRadialGradient(cx,cy,0,cx,cy,coreR*2.2);
    cg.addColorStop(0,''rgba(''+T.core+'',''+(.95+coreFlash*.05)+'')'');
    cg.addColorStop(.4,''rgba(''+T.ring+'',.75)'');
    cg.addColorStop(1,''rgba(''+T.ring+'',0)'');
    ctx.fillStyle=cg; ctx.beginPath(); ctx.arc(cx,cy,coreR*2.2,0,6.29); ctx.fill();

    for(i=orbSparks.length-1;i>=0;i--){
      var os=orbSparks[i];
      os.x+=os.vx; os.y+=os.vy; os.vx*=.94; os.vy*=.94; os.life-=.03;
      if(os.life<=0){ orbSparks.splice(i,1); continue; }
      ctx.beginPath(); ctx.fillStyle=''rgba(''+T.sparks+'',''+os.life+'')'';
      ctx.arc(os.x,os.y,1.8*os.life+.4,0,6.29); ctx.fill();
    }
    ctx.globalCompositeOperation=''source-over'';

    function ring(rot,scale,col,dashSp){
      ctx.save(); ctx.translate(cx,cy); ctx.rotate(rot); ctx.scale(1,scale);
      ctx.beginPath(); ctx.arc(0,0,R*1.1,0,6.29);
      ctx.setLineDash([14,20]); ctx.lineDashOffset=-dashSp;
      ctx.strokeStyle=col; ctx.lineWidth=1.6; ctx.stroke();
      ctx.setLineDash([]); ctx.restore();
    }

    var hg=ctx.createRadialGradient(cx-R*.42,cy-R*.46,0,cx-R*.42,cy-R*.46,R*.4);
    hg.addColorStop(0,''rgba(255,255,255,''+(.5+heat*.2)+'')''); hg.addColorStop(1,''rgba(255,255,255,0)'');
    ctx.fillStyle=hg; ctx.beginPath(); ctx.arc(cx-R*.42,cy-R*.46,R*.4,0,6.29); ctx.fill();



    for(i=shocks.length-1;i>=0;i--){
      var s3=shocks[i]; s3.r+=s3.v; s3.a-=.03;
      if(s3.a<=0){ shocks.splice(i,1); continue; }
      ctx.beginPath(); ctx.arc(cx,cy,s3.r,0,6.29);
      ctx.strokeStyle=''rgba(''+T.ring+'',''+s3.a+'')''; ctx.lineWidth=3*s3.a; ctx.stroke();
    }
    coreFlash*=.94;

    if(pressed){
      var prog=Math.min(1,charge/CHARGE_MAX);
      for(i=1;i<=4;i++){
        var dp=i*.25,da=-Math.PI/2+dp*6.283;
        ctx.beginPath();
        ctx.arc(cx+Math.cos(da)*(R+9),cy+Math.sin(da)*(R+9),2.6,0,6.29);
        ctx.fillStyle=prog>=dp%s''rgba(255,255,255,.95)'':''rgba(140,190,255,.4)'';
        ctx.fill();
      }
      ctx.beginPath(); ctx.arc(cx,cy,R+9,-Math.PI/2,-Math.PI/2+prog*6.283);
      ctx.strokeStyle=curTier>=4%s''#ffffff'':''rgba(''+T.ring+'',.95)'';
      ctx.lineWidth=curTier>=4%s5:4;
      ctx.shadowColor=''rgba(''+T.ring+'',.9)''; ctx.shadowBlur=12; ctx.stroke();
      ctx.shadowBlur=0;
      if(curTier>=4){
        ctx.beginPath(); ctx.arc(cx,cy+R+9,4.5,0,6.29);
        ctx.fillStyle=''#fff''; ctx.fill();
      }
    }

    if(pressed&&ptr.x){
      ctx.globalCompositeOperation=''lighter'';
      var mxp=(ptr.x+cx)/2, myp=(ptr.y+cy)/2+Math.sin(t*7)*13;
      var bg=ctx.createLinearGradient(ptr.x,ptr.y,cx,cy);
      bg.addColorStop(0,''rgba(''+T.n2+'',.85)''); bg.addColorStop(1,''rgba(''+T.ring+'',.9)'');
      ctx.beginPath(); ctx.moveTo(ptr.x,ptr.y); ctx.quadraticCurveTo(mxp,myp,cx,cy);
      ctx.strokeStyle=bg; ctx.lineWidth=5+2*Math.sin(t*13)+heat*4;
      ctx.shadowColor=''rgba(''+T.n2+'',.8)''; ctx.shadowBlur=16; ctx.stroke();
      ctx.beginPath(); ctx.moveTo(ptr.x,ptr.y); ctx.quadraticCurveTo(mxp,myp,cx,cy);
      ctx.strokeStyle=''rgba(255,255,255,.75)''; ctx.lineWidth=1.6; ctx.shadowBlur=0; ctx.stroke();
      bolt(ptr.x,ptr.y,cx,cy,R*.5+heat*40,1.7,true,T.bolt);
      bolt(ptr.x,ptr.y,cx,cy,R*.28,1,false,T.bolt);
      if(Math.random()<.5) bolt(ptr.x,ptr.y,cx+(Math.random()-.5)*R,cy+(Math.random()-.5)*R,R*.6,1,false,T.bolt);
      var pg=ctx.createRadialGradient(ptr.x,ptr.y,0,ptr.x,ptr.y,20);
      pg.addColorStop(0,''rgba(255,255,255,.95)''); pg.addColorStop(.3,''rgba(''+T.n2+'',.6)''); pg.addColorStop(1,''rgba(''+T.n2+'',0)'');
      ctx.fillStyle=pg; ctx.beginPath(); ctx.arc(ptr.x,ptr.y,20,0,6.29); ctx.fill();
      ctx.save(); ctx.translate(ptr.x,ptr.y); ctx.rotate(t*4);
      ctx.beginPath(); ctx.setLineDash([5,7]); ctx.arc(0,0,26,0,6.29);
      ctx.strokeStyle=''rgba(''+T.bolt+'',.7)''; ctx.lineWidth=1.5; ctx.stroke(); ctx.setLineDash([]);
      ctx.restore();
      if(Math.random()<.45+heat*.55){
        var aa=Math.random()*6.28, ar=14+Math.random()*34;
        flows.push({x:ptr.x+Math.cos(aa)*ar,y:ptr.y+Math.sin(aa)*ar,vx:0,vy:0});
      }
      for(i=flows.length-1;i>=0;i--){
        var f=flows[i];
        var ddx=cx-f.x,ddy=cy-f.y,dd=Math.hypot(ddx,ddy)||1;
        f.vx+=ddx/dd*(.5+heat*.9); f.vy+=ddy/dd*(.5+heat*.9);
        f.vx*=.96; f.vy*=.96;
        var ox=f.x,oy=f.y; f.x+=f.vx; f.y+=f.vy;
        if(dd<R*.28){ flows.splice(i,1); coreFlash=Math.min(1,coreFlash+.25); continue; }
        ctx.beginPath(); ctx.moveTo(ox,oy); ctx.lineTo(f.x,f.y);
        ctx.strokeStyle=''rgba(''+T.sparks+'',.8)''; ctx.lineWidth=1.8; ctx.stroke();
      }
      ctx.globalCompositeOperation=''source-over'';
    }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);

  function loc(e){
    var r=cv.getBoundingClientRect();
    return {x:e.clientX-r.left,y:e.clientY-r.top};
  }
  stage.addEventListener(''contextmenu'',function(e){ e.preventDefault(); });
  wrap.addEventListener(''pointerdown'',function(e){
    if(e.button&&e.button>0) return;
    SND.ensure();
    pressed=true; charge=0; curTier=0; pT=performance.now();
    ptr=loc(e);
    try{ wrap.setPointerCapture(e.pointerId); }catch(err){}
    wrap.classList.add(''pressing'',''hot'');
    SND.chargeStart();
    e.preventDefault();
  });
  wrap.addEventListener(''pointermove'',function(e){ if(pressed) ptr=loc(e); });
  function release(e){
    if(!pressed) return;
    var tier=curTier;
    pressed=false;
    SND.chargeStop();
    wrap.classList.remove(''pressing'',''hot'',''charged'');
    runes.textContent=''觉醒'';
    if(e&&e.type===''pointercancel''){ charge=0; flows=[]; curTier=0; return; }
    charge=0; flows=[]; curTier=0;
    if(tier<1){ SND.noDraw(); Orb.burst(0); return; }
    DRAW.draw(tier);
  }
  wrap.addEventListener(''pointerup'',release);
  wrap.addEventListener(''pointercancel'',release);

  return {
    burst:function(tier){
      for(var i=0;i<1+Math.min(4,tier);i++) shocks.push({r:R*.15*(i+1),v:R*(.05+.012*tier),a:.9});
      coreFlash=1;
      for(i=0;i<20+tier*20;i++){
        var a=Math.random()*6.28,sp=1.5+Math.random()*(2.5+tier);
        orbSparks.push({x:cx,y:cy,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,life:1});
      }
    }
  };
})();

