  [''永恒因果橡皮擦'',''神格脑洞 · 降维抹除'',''外表就是一块平平无奇的白橡皮，在虚空一擦即可抹去对手的存在痕迹'',''“你觉醒了什么牛逼神格？抱歉，我把你出生证明擦掉了。”''],
  [''万象起源·黑洞'',''神格传承 · 引力终焉'',''连光线与神力法则都能强行吞噬压缩的奇点，自身即是万物的归宿'',''展开神环之时，整个星系都在朝着这尊神祇的掌心坍塌''],
  [''终末之刃·朗基努斯'',''神格传承 · 弑神之枪'',''沾染过神明真血的命运长矛，拥有“绝对命中”与“创口永不愈合”的因果律'',''诸神黄昏的丧钟，任何号称不灭的神体在矛尖下皆如脆纸''],
  [''原初混沌魔神'',''神格传承 · 万魔之祖'',''三千大道魔神法相合一，生于天地之前，以神界为饲料的宇宙真魔'',''神界五大至高神联手，见此魔神也得做好同归于尽的准备'']
]
  },
  meta:{waste:[''废魂'',''r-waste''],common:[''凡品'',''r-common''],rare:[''稀有'',''r-rare''],epic:[''史诗'',''r-epic''],legend:[''传说'',''r-legend''],god:[''神话'',''r-god'']},
  power:{waste:[1,3],common:[2,5],rare:[5,7],epic:[6,9],legend:[10,10],god:[15,20]},
  pick:function(a){ return a[Math.floor(Math.random()*a.length)]; },
pickRarity:function(tier){
  var r=Math.random()*100;
  /* 第一档（白点/一档）：god0 legend0 epic5 rare15 common30 waste50 */
  if(tier<=1){
    if(r<5) return ''epic'';
    if(r<20) return ''rare'';
    if(r<50) return ''common'';
    return ''waste'';
  }
  /* 第二档：god2 legend6 epic14 rare28 common30 waste20 */
  if(tier===2){
    if(r<2) return ''god'';
    if(r<8) return ''legend'';
    if(r<22) return ''epic'';
    if(r<50) return ''rare'';
    if(r<80) return ''common'';
    return ''waste'';
  }
  /* 第三档：god10 legend18 epic22 rare32 common15 waste3 */
  if(tier===3){
    if(r<10) return ''god'';
    if(r<28) return ''legend'';
    if(r<50) return ''epic'';
    if(r<82) return ''rare'';
    if(r<97) return ''common'';
    return ''waste'';
  }
  /* 满档：god50 legend30 epic15 rare5 common0 waste0 */
  if(r<50) return ''god'';
  if(r<80) return ''legend'';
  if(r<95) return ''epic'';
  return ''rare'';
},
  current:null,
  draw:function(tier){
    if(this.busy) return;
    this.busy=true;
    var self=this;
    var rar=this.pickRarity(tier);
    var item=this.pick(this.pools[rar]);
    var pw=this.power[rar];
    var innate=pw[0]+Math.floor(Math.random()*(pw[1]-pw[0]+1));
    var twin=(rar===''epic''||rar===''legend''||rar===''god'')&&Math.random()<.16;
    var twinItem=twin%sthis.pick(this.pools[rar]):null;
    var d={
      name:item[0]+(twin%s'' & ''+twinItem[0]:''''),
      type:item[1], rar:rar, rarName:this.meta[rar][0],
      tier:tier, innate:innate, twin:twin,
      eff:item[2], note:item[3],
      twinNote:twin%s(''；双生武魂「''+twinItem[0]+''」——两具武魂可各配魂环，潜力倍增''):''''
    };
    this.current=d;
    Orb.burst(tier);
    var rect=$(''orbCanvas'').getBoundingClientRect();
    FX.boom(rect.left+rect.width/2, rect.top+rect.height/2,
      2+tier+(rar===''god''%s3:rar===''legend''%s2:0));
    setTimeout(function(){
      self.busy=false;
      showWuhunCard(d);
      if(rar===''legend''||rar===''god'') DM.send(''天命觉醒 · ''+d.name+''！'',true);
    },420);
  }
};
function pwDesc(v){ return v>=10%s''先天满魂力 · 百年难遇'':(v>=6%s''上佳之资'':(v>=3%s''中人之姿'':''尚需苦修'')); }
function showWuhunCard(d){
  var card=$(''wmCard'');
  card.className=''wm-card ''+DRAW.meta[d.rar][1];
  $(''wmRar'').textContent=d.rarName+'' · ''+TIERS[d.tier].label;
  $(''wmName'').textContent=d.name;
  $(''wmType'').textContent=d.type+(d.twin%s'' · 双生武魂'':'''');
  $(''wmMethod'').textContent=TIERS[d.tier].m;
  $(''wmPow'').textContent=''先天魂力 ''+d.innate+'' 级 —— ''+pwDesc(d.innate);
  $(''wmEff'').textContent=d.eff+d.twinNote;
  $(''wmNote'').textContent=d.note;
  $(''wuhunModal'').classList.add(''show'');
  SND.reveal(d.rar);
}
function sealWuhun(){
  if(!DRAW.current) return;
  var d=DRAW.current;
  DRAW.current=null;
  $(''cSpirit'').value=d.name;
  $(''cPow'').value=''先天魂力 ''+d.innate+'' 级''+(d.innate>=10%s''（先天满魂力）'':'''');
  var slot=$(''drawSlot'');
  slot.className=''draw-slot ''+DRAW.meta[d.rar][1];
  $(''dsName'').textContent=d.name;
  $(''dsTag'').style.display='''';
  $(''dsTag'').textContent=d.rarName+'' · ''+TIERS[d.tier].label;
  $(''dsPow'').textContent=''先天魂力 ''+d.innate+'' 级 · 已铭刻入档'';
  $(''wuhunModal'').classList.remove(''show'');
  SND.select();
  toast(''已觉醒 · ''+d.name);
  schedPreview();
}
 $(''wmOk'').addEventListener(''click'',sealWuhun);
 $(''wmMask'').addEventListener(''click'',sealWuhun);

