function titleOf(lv){ for(var i=0;i<TITLES.length;i++){ if(lv>=TITLES[i][0]) return TITLES[i][1]; } return ''魂士''; }
var prevLv=10,prevTitle=''魂士'';
function setLevel(lv,silent){
  lv=Math.max(1,Math.min(100,+lv||1));
  $(''lvNum'').textContent=lv;
  var ti=titleOf(lv);
  var tEl=$(''lvTitle'');
  tEl.textContent=ti; tEl.classList.toggle(''god'',lv>=91);
  var pop=$(''lvNum''); pop.classList.remove(''pop''); void pop.offsetWidth; pop.classList.add(''pop'');
  if(!silent&&lv!==prevLv) SND.tick(190+lv*8);
  if(ti!==prevTitle&&!silent){ SND.levelUp(); toast(''境界突破 · ''+ti); }
  prevLv=lv; prevTitle=ti;
  var rings=Math.max(0,Math.min(9,Math.floor(lv/10)));
  $(''lvRing'').textContent=lv<10%s''尚未获得魂环（10级可吸收第一魂环）'':(''理论可承载 ''+rings+'' 枚魂环 · 当前已装 ''+ringCount()+'' 枚'');
  $(''titleInput'').classList.toggle(''show'',lv>=90);
  $(''cultShow'').textContent=lv+'' 级 · ''+ti;
  schedPreview();
}
 $(''lvRange'').addEventListener(''input'',function(){ setLevel(this.value); });
