function ringCount(){ return ringState.filter(function(x){return x}).length; }
(function(){
  var row=$(''ringRow'');
  for(var i=0;i<9;i++){
    (function(idx){
      var b=document.createElement(''button'');
      b.className=''rslot''; b.type=''button'';
      b.textContent=''环位''+CN_NUM[idx];
      b.addEventListener(''click'',function(){
        var cur=RING_DEFS.map(function(d){return d.c}).indexOf(ringState[idx]);
        var next=(cur+1)%RING_DEFS.length;
        ringState[idx]=RING_DEFS[next].c;
        b.dataset.c=RING_DEFS[next].c;
        b.textContent=RING_DEFS[next].y||(''环位''+CN_NUM[idx]);
        b.classList.remove(''pop''); void b.offsetWidth; b.classList.add(''pop'');
        if(RING_DEFS[next].c){ SND.ring(RING_DEFS[next].c); }
        else SND.tick(220);
        setLevel($(''lvRange'').value,true);
        schedPreview();
      });
      row.appendChild(b);
    })(i);
  }
})();
function ringListText(){
  var arr=[];
  for(var i=0;i<9;i++){
    if(!ringState[i]) continue;
    var d=RING_DEFS.filter(function(x){return x.c===ringState[i]})[0];
    arr.push(''第''+CN_NUM[i]+''环·''+d.y+''（''+d.t+''）'');
  }
  return arr;
}

