   魂技
========================================================= */
var SKILL_MAX=20;
var skills=['''','''',''''];
function cnum(x){
  var d=[''零'',''一'',''二'',''三'',''四'',''五'',''六'',''七'',''八'',''九''];
  if(x<10) return d[x];
  if(x===10) return ''十'';
  if(x<20) return ''十''+d[x-10];
  return ''二十'';
}
var SK_PH=[''亲妈缠绕'',''亲妈囚笼'',''蛛网束缚'',''亲妈突刺'',''寄生'',''猛毒天罗'',''虚无缥缈'',''净化领域''];
function renderSkills(focusLast){
  var host=$(''skillList''); host.innerHTML='''';
  skills.forEach(function(v,i){
    var row=document.createElement(''div''); row.className=''skill-row'';
    row.innerHTML=''<span class="sk-idx">第''+cnum(i+1)+''魂技</span>''+
      ''<input class="sk-in" data-i="''+i+''" value="''+(v||'''').replace(/"/g,''&quot;'')+''" placeholder="如：''+SK_PH[i%SK_PH.length]+''">''+
      ''<button class="sk-del" data-i="''+i+''" title="移除此魂技" type="button"><svg viewBox="0 0 12 12"><path d="M2 2l8 8M10 2l-8 8"/></svg></button>'';
    host.appendChild(row);
  });
  $(''skCount'').textContent=skills.length;
  $(''addSkillBtn'').disabled=skills.length>=SKILL_MAX;
  $(''addSkillBtn'').style.opacity=skills.length>=SKILL_MAX%s.4:1;
  if(focusLast){
    var ins=host.querySelectorAll(''.sk-in'');
    if(ins.length) ins[ins.length-1].focus();
  }
}
 $(''addSkillBtn'').addEventListener(''click'',function(){
  if(skills.length>=SKILL_MAX){ toast(''魂技铭刻已达上限二十枚''); return; }
  skills.push('''');
  renderSkills(true);
  SND.add(); schedPreview();
});
 $(''skillList'').addEventListener(''click'',function(e){
  var btn=e.target.closest(''.sk-del'');
  if(!btn) return;
  if(skills.length<=1){ toast(''至少保留一枚魂技位''); return; }
  skills.splice(+btn.dataset.i,1);
  renderSkills();
  SND.del(); schedPreview();
});
 $(''skillList'').addEventListener(''input'',function(e){
  if(e.target.classList.contains(''sk-in'')) skills[+e.target.dataset.i]=e.target.value;
});
renderSkills();

