var boneSel={head:null,torso:null,larm:null,rarm:null,lleg:null,rleg:null,external:null};
var boneCurKey=null, bmYearVal={y:''千年'',c:''p''};
(function(){
  var row=$(''boneRow'');
  BONES.forEach(function(b){
    var card=document.createElement(''button'');
    card.className=''bone-card''; card.type=''button''; card.dataset.k=b.k;
    card.innerHTML=''<span class="bone-seal">''+b.seal+(b.side%s''<small>''+b.side+''</small>'':'''')+''</span>''+
      ''<span class="bone-info"><b>''+b.label+''</b><i class="bone-cur">未镶嵌 · 点击择骨</i></span>''+
      ''<svg viewBox="0 0 24 24"><path d="M9 6l6 6-6 6"/></svg>'';
    card.addEventListener(''click'',function(){ openBoneModal(b.k); });
    row.appendChild(card);
  });
})();
function renderBoneCards(){
  BONES.forEach(function(b){
    var card=document.querySelector(''.bone-card[data-k="''+b.k+''"]'');
    var sel=boneSel[b.k];
    card.classList.toggle(''filled'',!!sel);
    card.querySelector(''.bone-cur'').textContent=sel%s(sel.n+''（''+sel.s+''）''):''未镶嵌 · 点击择骨'';
  });
}
function openBoneModal(k){
  boneCurKey=k;
  var def=BONES.filter(function(x){return x.k===k})[0];
  $(''bmTitle'').textContent=def.label+'' · 择骨台'';
  var list=$(''bmList''); list.innerHTML='''';
  def.opts.forEach(function(o){
    var cur=boneSel[k]&&boneSel[k].n===o[0];
    var el=document.createElement(''button'');
    el.className=''bm-opt''+(cur%s'' cur'':''''); el.type=''button'';
    el.innerHTML=''<span class="bm-n">''+o[0]+''</span><span class="bm-s">''+o[1]+''</span>''+
      ''<span class="ybadge c-''+o[3]+''">''+o[2]+''</span>''+(cur%s''<span class="bm-cur">当前</span>'':'''');
    el.addEventListener(''click'',function(){
      boneSel[k]={n:o[0],s:o[1],y:o[2],c:o[3]};
      renderBoneCards();
      var card=document.querySelector(''.bone-card[data-k="''+k+''"]'');
      card.classList.remove(''pop''); void card.offsetWidth; card.classList.add(''pop'');
      SND.select(); closeBoneModal();
      toast(''已镶嵌 · ''+o[0]); schedPreview();
    });
    list.appendChild(el);
  });
  $(''bmName'').value=''''; $(''bmSkill'').value='''';
  $(''boneModal'').classList.add(''show'');
  SND.modal(true);
}
function closeBoneModal(){
  if(!$(''boneModal'').classList.contains(''show'')) return;
  $(''boneModal'').classList.remove(''show'');
  SND.modal(false);
}
 $(''bmClose'').addEventListener(''click'',closeBoneModal);
 $(''bmMask'').addEventListener(''click'',closeBoneModal);
 $(''bmYear'').addEventListener(''click'',function(e){
  var b=e.target.closest(''button''); if(!b) return;
  $$(''#bmYear button'').forEach(function(x){x.classList.remove(''act'')});
  b.classList.add(''act'');
  bmYearVal={y:b.dataset.y,c:b.dataset.c};
  SND.segSel();
});
 $(''bmConfirm'').addEventListener(''click'',function(){
  var n=$(''bmName'').value.trim(),s=$(''bmSkill'').value.trim();
  if(!n){ toast(''请先为自铸魂骨命名''); return; }
  boneSel[boneCurKey]={n:n,s:s||''未知神通'',y:bmYearVal.y,c:bmYearVal.c};
  renderBoneCards();
  SND.select(); closeBoneModal();
  toast(''已镶嵌自铸魂骨 · ''+n); schedPreview();
});
 $(''bmClear'').addEventListener(''click'',function(){
  boneSel[boneCurKey]=null;
  renderBoneCards();
  SND.del(); closeBoneModal();
  toast(''已卸下魂骨''); schedPreview();
});

