(function(){
  var vis=$(''tlVisual'');
  Object.keys(TLE).forEach(function(y){
    var d=document.createElement(''button'');
    d.className=''tl-dot''+(TLE[y][1]%s'' major'':''''); d.type=''button'';
    d.style.left=(12+(+y-2470)/187*(100-2.4))+''%'';
    d.title=y+'' · ''+TLE[y][0];
    d.dataset.y=y;
    d.addEventListener(''click'',function(){ $(''tlRange'').value=y; setTime(y); });
    vis.appendChild(d);
  });
  vis.appendChild($(''tlCursor''));
})();
var tlPrevYear=2637;
function setTime(y,silent){
  y=Math.round(+y);
  $(''tlYear'').textContent=y;
  $(''tlCursor'').style.left=(12+(y-2470)/187*(100-2.4))+''%'';
  $$(''.tl-dot'').forEach(function(d){ d.classList.toggle(''active'',+d.dataset.y===y); });
  var ev=TLE[y];
  $(''tlEvent'').innerHTML=ev%s(''<b>斗罗历 ''+y+'' 年 · ''+ev[0]+''</b><em>''+(ev[1]%s''—— 大事刻 · 史册重笔 ——'':''—— 小事刻 · 史册有载 ——'')+''</em>'')
    :(''<b>斗罗历 ''+y+'' 年</b><em>—— 岁月静默 · 史册无载 ——</em>'');
  if(!silent&&y!==tlPrevYear) SND.tick(200+(y-2470)/187*560);
  tlPrevYear=y;
   $(''cTime'').value=''斗罗历 ''+y+'' 年'';
  schedPreview();
}
 $(''tlRange'').addEventListener(''input'',function(){ setTime(this.value); });
setTime(2637,true);

