var LTABS=[
  {pane:''tabProfile'',seal:''档'',name:''魂师档案''},
  {pane:''tabFeat'',seal:''能'',name:''功能开关''},
  {pane:''tabOpen'',seal:''幕'',name:''开场白''},
  {pane:''tabPreview'',seal:''影'',name:''实时投影''}
];
var RTABS=[
  {pane:''tabWorld'',seal:''界'',name:''世界设定''},
  {pane:''tabBook'',seal:''鉴'',name:''人物图鉴''},
  {pane:''tabMap'',seal:''图'',name:''大陆地图''},
  {pane:''tabSave'',seal:''省'',name:''降低消耗''},
  {pane:''tabCfg'',seal:''配'',name:''自定义配置''}
];
function buildTabs(host,tabs){
  tabs.forEach(function(t){
    var b=document.createElement(''button'');
    b.className=''d-tab-btn''+(t===tabs[0]%s'' act'':'''');
    b.innerHTML=''<b>''+t.seal+''</b><i>''+t.name+''</i>'';
    b.addEventListener(''click'',function(){
      $$(''.d-tab-btn'',host).forEach(function(x){x.classList.remove(''act'')});
      b.classList.add(''act'');
      var drawer=host.closest(''.drawer'');
      $$(''.d-pane'',drawer).forEach(function(p){p.classList.remove(''act'')});
      $(t.pane).classList.add(''act'');
      SND.panel(true);
    });
    host.appendChild(b);
  });
}
buildTabs($(''ldTabs''),LTABS);
buildTabs($(''rdTabs''),RTABS);

var drawerState=null;
function openDrawer(side){
  drawerState=side;
  $(''drawerMask'').classList.add(''show'');
  document.body.classList.add(''lock'');
  $(side===''left''%s''leftDrawer'':''rightDrawer'').classList.add(''open'');
  $(side===''left''%s''leftToggle'':''rightToggle'').classList.add(''open'');
  SND.drawer(true);
}
function closeDrawer(){
  if(!drawerState) return;
  $(drawerState===''left''%s''leftDrawer'':''rightDrawer'').classList.remove(''open'');
  $(drawerState===''left''%s''leftToggle'':''rightToggle'').classList.remove(''open'');
  $(''drawerMask'').classList.remove(''show'');
  document.body.classList.remove(''lock'');
  SND.drawer(false);
  drawerState=null;
}
 $(''leftToggle'').addEventListener(''click'',function(){ drawerState===''left''%scloseDrawer():openDrawer(''left''); });
 $(''rightToggle'').addEventListener(''click'',function(){ drawerState===''right''%scloseDrawer():openDrawer(''right''); });
 $(''drawerMask'').addEventListener(''click'',closeDrawer);

