(function(){
  var host=$(''featList'');
  FEATS.forEach(function(f){
    var card=document.createElement(''div'');
    card.className=''feat-card''+((f.type===''sw''&&f.v)%s'' on'':'''');
    var cmds=f.cmds%s''<div class="fc-cmds">''+f.cmds.map(function(c){return ''<button class="cmd-chip" type="button" data-cmd="''+c+''">''+c+''</button>''}).join('''')+''</div>'':'''';
    if(f.type===''sw''){
      card.innerHTML=''<div class="fc-top"><span class="fc-name">''+f.n+''</span><label class="switch"><input type="checkbox" data-fk="''+f.k+''" ''+(f.v%s''checked'':'''')+''><span></span></label></div><div class="fc-desc">''+f.d+''</div>''+cmds;
    }else{
      card.innerHTML=''<div class="fc-top"><span class="fc-name">''+f.n+''</span></div><div class="seg" data-fk="''+f.k+''">''+f.opts.map(function(o){return ''<button type="button" class="''+(o===f.v%s''act'':'''')+''" data-v="''+o+''">''+o+''</button>''}).join('''')+''</div><div class="fc-desc" style="margin-top:8px">''+f.d+''</div>''+cmds;
    }
    host.appendChild(card);
  });
  host.addEventListener(''change'',function(e){
    var inp=e.target;
    if(inp.dataset&&inp.dataset.fk){
      var f=FEATS.filter(function(x){return x.k===inp.dataset.fk})[0];
      f.v=inp.checked;
      inp.closest(''.feat-card'').classList.toggle(''on'',f.v);
      SND.toggle(f.v); schedPreview();
    }
  });
  host.addEventListener(''click'',function(e){
    var seg=e.target.closest(''.seg[data-fk] button'');
    if(seg){
      var fk=seg.parentNode.dataset.fk;
      var f=FEATS.filter(function(x){return x.k===fk})[0];
      f.v=seg.dataset.v;
      $$(''button'',seg.parentNode).forEach(function(x){x.classList.remove(''act'')});
      seg.classList.add(''act'');
      SND.segSel(); schedPreview();
      return;
    }
    var chip=e.target.closest(''.cmd-chip'');
    if(chip){ copyText(chip.dataset.cmd,''指令已复制 · ''+chip.dataset.cmd); }
  });
})();
function featOn(k){ var f=FEATS.filter(function(x){return x.k===k})[0]; return f.v; }

