(function(){
  var bookEl=$(''book'');
  var cover=document.createElement(''div'');
  cover.className=''page'';
  cover.innerHTML=''<div class="page-face page-front cover">''+
    ''<h2>人物图鉴</h2><p class="cover-sub">斗罗大陆 · 魂师卷宗</p><div class="cover-line"></div>''+
    ''<div class="cover-info">翻开人物档案 · 点击图片查看<b>史莱克学院监制 · 武魂殿出版</b></div></div>'';
  bookEl.appendChild(cover);
  var toc=document.createElement(''div'');
  toc.className=''page'';
  toc.innerHTML=''<div class="page-face page-front">''+
    ''<div class="toc-page">''+
    ''<div class="toc-head"><h3>目 录</h3><p>—— 点击名字可直达对应页面 ——</p></div>''+
    ''<div class="toc-list">''+SIS.map(function(s,i){
      return ''<button type="button" class="toc-item" data-goto="''+(i+2)+''">''+
        ''<span class="toc-no">''+String(i+1).padStart(2,''0'')+''</span>''+
        ''<span class="toc-info"><span class="toc-name">''+s.name+''</span><span class="toc-trait">''+s.trait+''</span></span></button>'';
    }).join('''')+''</div></div></div>'';
  bookEl.appendChild(toc);
  SIS.forEach(function(s,i){
    var p=document.createElement(''div'');
    p.className=''page'';
    p.innerHTML=''<div class="page-face page-front sis-page">''+
      ''<div class="sis-photo-wrap" data-idx="''+i+''">''+
      ''<img class="sis-photo" data-src="''+(IMG[s.name]||(''https://picsum.photos/seed/douluo-''+s.img+''/540/920.jpg''))+''" decoding="async" alt="''+s.name+''">''+
      ''<div class="sis-overlay"><span class="sis-no">''+String(i+1).padStart(2,''0'')+''</span><h4>''+s.name+''</h4><span class="sis-tag">''+s.tag+''</span></div>''+
      ''</div></div>'';
    bookEl.appendChild(p);
  });

var pages=$$(''.page'',bookEl);
var view=0;
var farTimer=null;
function updatePageState(){
  pages.forEach(function(p,idx){
    var flipped=idx<view;
    p.classList.toggle(''flipped'',flipped);
    p.style.zIndex=flipped%sString(200+idx):String(100-idx);
    var d=Math.abs(idx-view);
    if(d<=2){ p.classList.remove(''far''); }
    if(d<=2){
      var im=p.querySelector(''img[data-src]'');
      if(im){ im.src=im.dataset.src; im.removeAttribute(''data-src''); }
    }
  });
  clearTimeout(farTimer);
  farTimer=setTimeout(function(){
    pages.forEach(function(p,idx){ if(Math.abs(idx-view)>2) p.classList.add(''far''); });
  },950);
  $(''prevBtn'').disabled=view<=0;
  $(''nextBtn'').disabled=view>=pages.length-1;
}
function goTo(v){
  if(v<0||v>=pages.length||v===view) return;
  view=v;
  SND.bookFlip();
  updatePageState();
}
 $(''prevBtn'').addEventListener(''click'',function(){ goTo(view-1); });
 $(''nextBtn'').addEventListener(''click'',function(){ goTo(view+1); });
bookEl.addEventListener(''click'',function(e){
  var item=e.target.closest(''.toc-item'');
  if(item){ goTo(parseInt(item.dataset.goto,10)); return; }
  var w=e.target.closest(''.sis-photo-wrap'');
  if(w) openPhoto(SIS[+w.dataset.idx]);
});
updatePageState();
})();

var photoTimer=null;
function openPhoto(s){
  clearTimeout(photoTimer);
 $(''pcFront'').innerHTML=''<img src="''+(IMG[s.name]||(''https://picsum.photos/seed/douluo-''+s.img+''/540/920.jpg''))+''" alt="''+s.name+''">'';
  var introHtml=s.intro.split(''\n'').filter(function(x){return x.trim().length>0})
    .map(function(x){return ''<p>''+x.trim()+''</p>''}).join('''');
  $(''pcBack'').innerHTML=''<h4>''+s.name+''<span class="pc-tag">''+s.tag+''</span></h4>''+
    ''<div class="pc-row"><b>武魂：</b>''+s.spirit+''</div><div class="pc-row"><b>魂力：</b>''+s.lv+''</div>''+
    ''<div class="pc-row"><b>卷宗：</b>''+s.trait+''</div>''+introHtml+
    ''<div class="pc-close">点击卡面可翻看</div>'';
  var card=$(''photoCard'');
  card.classList.remove(''flipped'');
  $(''photoOverlay'').classList.add(''show'');
  SND.bookFlip();
  var fimg=$(''pcFront'').querySelector(''img'');
  var ready=(fimg&&fimg.decode)%sfimg.decode().catch(function(){}):Promise.resolve();
  ready.then(function(){
    photoTimer=setTimeout(function(){
      if($(''photoOverlay'').classList.contains(''show'')) card.classList.add(''flipped'');
    },700);
  });
}
 $(''photoCard'').addEventListener(''click'',function(e){
  if(e.target.closest(''.pc-close'')) return;
  this.classList.toggle(''flipped'');
  SND.bookFlip();
});
 $(''photoOverlay'').addEventListener(''click'',function(e){
  if(e.target.closest(''.photo-card'')&&!e.target.closest(''.pc-close'')) return;
  SND.panel(false);
  $(''photoCard'').classList.remove(''flipped'');
  var ov=this;
  setTimeout(function(){ ov.classList.remove(''show''); },450);
});

/* =========================================================
   竖版大陆地图（疆域仅大字可点 · 地点带热区 · 弹窗详情）
========================================================= */
var MC={cap:''#f0c36c'',city:''#c9d8ec'',edu:''#6cd0ff'',sect:''#b57bff'',holy:''#ff9d45'',danger:''#ff5e6c'',forest:''#58c99a'',sea:''#8fe3d8'',secret:''#ff7ab8'',arena:''#ffd166'',village:''#9db4d0''};
var MT={cap:''帝国首都'',city:''城镇'',edu:''学院机构'',sect:''宗门家族'',holy:''圣地'',danger:''秘境险地'',forest:''魂兽森林'',sea:''海外神岛'',secret:''秘境宝地'',arena:''斗魂场'',village:''村落''};
var MAP=[
 {n:''星斗大森林'',x:200,y:100,dy:-14,t:''forest'',d:''斗罗大陆面积最大、魂兽种类与数量最多的魂兽聚居地，危险与机遇并存。从十年到十万年魂兽皆有栖息，存在天青牛蟒和泰坦巨猿，是魂师获取魂环的主要地点之一。小舞的本体柔骨兔就来自这里。''},
 {n:''天斗城'',x:170,y:150,dy:-14,t:''cap'',d:''天斗帝国的首都，繁华无比，设有天斗皇家学院、月轩、天斗大斗魂场等重要机构。''},
 {n:''天斗大斗魂场'',x:280,y:130,dy:-14,t:''arena'',d:''位于天斗城，比索托城的大斗魂场规模更大、规格更高。''},
 {n:''月轩'',x:110,y:190,dy:-14,t:''edu'',d:''位于天斗城，由唐三的姑姑唐月华创办。并非修炼魂力之处，而是学习贵族礼仪、音乐、艺术，提升气质与精神境界之地，拥有特殊的领域能力。''},
 {n:''天斗皇家学院'',x:250,y:195,dy:-14,t:''edu'',d:''天斗帝国最好的魂师学院，资源丰富，但内部派系林立。皇斗战队是其代表队伍，史莱克学院曾短暂在此挂名。''},
 {n:''圣魂村'',x:120,y:250,dy:-14,t:''village'',d:''位于法斯诺行省诺丁城南的小村庄，是唐三幼年生活的地方，也是他武魂觉醒之地。因曾走出过一位魂圣而得名。''},
 {n:''武魂殿'',x:330,y:230,dy:-14,t:''holy'',d:''斗罗大陆最强大、覆盖范围最广的魂师组织，负责魂师觉醒与注册，拥有强大武力。由教皇比比东和长老殿掌控，后期试图统一大陆建立武魂帝国，但以失败告终。''},
 {n:''武魂城'',x:370,y:280,dy:-14,t:''holy'',d:''武魂殿的总部所在地，是大陆魂师心中的圣地，规模宏大，教皇殿和长老殿坐落于此。''},
 {n:''昊天宗'',x:400,y:180,dy:-14,t:''sect'',d:''上三宗之首，以拥有大陆第一强攻系武魂「昊天锤」闻名，唐三、唐昊所属宗门。因唐昊事件选择隐世，后在唐三的努力下重新出世对抗武魂殿。''},
 {n:''庚辛城'',x:420,y:330,dy:-14,t:''city'',d:''以金属锻造闻名的大陆城市，被誉为「金属之都」，拥有最顶尖的铁匠。唐三在此获得了大量稀有金属并结识了神匠楼高，为唐门暗器的制造提供了基础。''},
 {n:''力之村'',x:100,y:310,dy:20,t:''village'',d:''力之一族聚居地。族长泰坦，武魂大力猩猩，擅长力量与铸造，曾是昊天宗附属，后整体加入唐门成为力堂。''},
 {n:''御之村'',x:155,y:300,dy:-14,t:''village'',d:''御之一族聚居地。族长牛皋，武魂板甲巨犀，防御登峰造极，后加入唐门成为御堂。''},
 {n:''敏之村'',x:210,y:312,dy:20,t:''village'',d:''敏之一族聚居地。族长白鹤，武魂尖尾雨燕，速度冠绝大陆，后加入唐门成为敏堂。''},
 {n:''破魂村'',x:265,y:300,dy:-14,t:''village'',d:''破之一族聚居地。族长杨无敌，武魂破魂枪，攻击锐不可当，后加入唐门成为药堂。''},
 {n:''诺丁城'',x:185,y:360,dy:-14,t:''city'',d:''位于天斗帝国法斯诺行省的小城，是唐三和小舞初遇并进入诺丁初级魂师学院的地方。''},
 {n:''诺丁学院'',x:245,y:385,dy:20,t:''edu'',d:''位于诺丁城的初级魂师学院，唐三和小舞学习的第一个学院，也是唐三拜大师玉小刚为师的地方。''},
 {n:''七宝琉璃宗'',x:360,y:390,dy:-14,t:''sect'',d:''上三宗之一，以拥有大陆第一辅助系武魂「七宝琉璃塔」闻名，宗主宁风致。富甲天下，有剑斗罗尘心和骨斗罗古榕两位封号斗罗守护，是唐三和天斗帝国的重要盟友。''},
 {n:''索托城'',x:300,y:450,dy:-14,t:''city'',d:''隶属于巴拉克王国（天斗帝国附属）的繁华城市，拥有著名的大斗魂场，史莱克学院初期位于城外。''},
 {n:''史莱克学院'',x:250,y:470,dy:20,t:''edu'',d:''一所专门招收「怪物」天才魂师的学院，由弗兰德创办。初期位于索托城附近，条件简陋，后迁至天斗城，以实战教学、培养精英闻名。''},
 {n:''索托城大斗魂场'',x:360,y:475,dy:20,t:''arena'',d:''位于索托城，供魂师进行对战、提升实战经验和获取积分等级的地方。史莱克七怪在此初露锋芒，获得了「史莱克七怪」的称号。''},
 {n:''蓝电霸王龙家族'',x:410,y:430,dy:20,t:''sect'',d:''上三宗之一，以拥有顶级强攻系兽武魂「蓝电霸王龙」闻名，玉小刚、玉天恒、玉元震所属家族。实力强大，后在武魂殿的猎魂行动中几乎被灭门。''},
 {n:''落日森林'',x:95,y:430,dy:-14,t:''forest'',d:''靠近天斗城的一片大型魂兽森林，危险程度低于星斗大森林，冰火两仪眼就隐藏在其中。''},
 {n:''冰火两仪眼'',x:130,y:480,dy:20,t:''secret'',d:''位于落日森林中心的宝地，一半极寒一半极热的泉眼，孕育了大量顶级仙品药草。原为毒斗罗独孤博的药圃，后被唐三获得，极大地提升了史莱克七怪等人的实力和天赋。''},
 {n:''杀戮之都'',x:140,y:650,dy:-14,t:''danger'',d:''充满血腥与堕落的特殊区域，无法使用魂技，只能依靠纯粹的力量、技巧和杀气生存。通过「地狱路」试炼可获得「杀神领域」，唐三和胡列娜都在此获得了该领域，唐晨曾是这里的杀戮之王。''},
 {n:''星罗城'',x:330,y:650,dy:-14,t:''cap'',d:''星罗帝国的首都。星罗帝国位于大陆西部，崇尚武力，皇室继承制度残酷，与天斗帝国长期对峙，戴沐白和朱竹清的故乡。''},
 {n:''海神岛'',x:438,y:60,dy:20,t:''sea'',d:''位于大海深处，供奉海神的神秘岛屿。由大祭司波塞西守护，拥有强大的海魂师和圣柱守护者。魂师可以通过海神试炼获得力量甚至继承神位，是唐三获得海神传承的地方。''}
];
var MAPREG=[
 {n:''天斗帝国'',labelX:108,labelY:522,cx:225,cy:290,rx:185,ry:250,t:''cap'',d:''斗罗大陆两大帝国之一，位于大陆东部，由雪氏皇族统治，首都天斗城。整体实力相对弱于星罗帝国，后期成为对抗武魂帝国的主要力量。''},
 {n:''星罗帝国'',labelX:335,labelY:600,cx:340,cy:560,rx:150,ry:190,t:''cap'',d:''斗罗大陆两大帝国之一，位于大陆西部，崇尚武力，皇室继承制度残酷，与天斗帝国长期对峙。戴沐白和朱竹清的故乡。''}
];
(function(){
  var svg=$(''mapSvg'');
  var s='''';
  /* 大陆地块 */
  s+=''<path class="map-land" d="M60 120 C 90 40, 220 30, 300 70 C 370 100, 430 60, 450 130 C 470 200, 440 280, 450 380 C 460 480, 430 580, 380 660 C 330 730, 240 760, 170 720 C 100 680, 60 600, 50 480 C 40 360, 30 200, 60 120 Z"/>'';
  s+=''<ellipse class="map-land" cx="438" cy="60" rx="40" ry="24"/>'';
  s+=''<ellipse class="map-deco" cx="470" cy="120" rx="15" ry="6"/><ellipse class="map-deco" cx="462" cy="145" rx="20" ry="7"/>'';
  [[160,220],[340,335],[220,555],[150,600],[300,590]].forEach(function(m){
    s+=''<path class="map-deco" d="M''+(m[0]-14)+'' ''+m[1]+'' l 14 -20 l 14 20"/><path class="map-deco" d="M''+(m[0]-2)+'' ''+m[1]+'' l 12 -16 l 12 16" opacity=".6"/>'';
  });
  /* 帝国疆域：椭圆仅描边装饰（不拦截点击），大字标签可点 */
  MAPREG.forEach(function(r,i){
    s+=''<g class="map-region" data-ri="''+i+''">''+
      ''<ellipse cx="''+r.cx+''" cy="''+r.cy+''" rx="''+r.rx+''" ry="''+r.ry+''"/>''+
      ''<text class="map-region-label" data-ri="''+i+''" x="''+r.labelX+''" y="''+r.labelY+''" text-anchor="middle">''+r.n+''</text></g>'';
  });
  /* 地点：透明热区 + 光点 + 标签 */
  MAP.forEach(function(m,i){
    var col=MC[m.t];
    s+=''<g class="map-dot" data-i="''+i+''">''+
      ''<circle cx="''+m.x+''" cy="''+m.y+''" r="18" fill="rgba(0,0,0,0)"/>''+
      ''<circle class="core" cx="''+m.x+''" cy="''+m.y+''" r="5" fill="''+col+''" stroke="#030a16" stroke-width="2"/>''+
      ''<circle cx="''+m.x+''" cy="''+m.y+''" r="10" fill="none" stroke="''+col+''" stroke-opacity=".35" stroke-width="1.5"/>''+
      ''<text class="map-pin-label" x="''+m.x+''" y="''+(m.y+m.dy)+''" text-anchor="middle">''+m.n+''</text></g>'';
  });
  svg.innerHTML=s;
  function showInfo(m){
    $(''mmName'').textContent=m.n;
    var badge=$(''mmBadge'');
    badge.textContent=MT[m.t];
    badge.style.color=MC[m.t];
    badge.style.borderColor=MC[m.t];
    $(''mmDesc'').textContent=m.d;
    $(''mapModal'').classList.add(''show'');
    SND.modal(true);
  }
  svg.addEventListener(''click'',function(e){
    var d=e.target.closest(''.map-dot'');
    if(d){ showInfo(MAP[+d.dataset.i]); return; }
    var t=e.target.closest(''.map-region-label'');
    if(t){ showInfo(MAPREG[+t.dataset.ri]); }
  });
  var lg=$(''mapLegend'');
  [''cap'',''city'',''edu'',''sect'',''holy'',''danger'',''forest'',''sea'',''secret'',''arena'',''village''].forEach(function(k){
    var sp=document.createElement(''span'');
    sp.innerHTML=''<i style="background:''+MC[k]+''"></i>''+MT[k];
    lg.appendChild(sp);
  });
})();
function closeMapModal(){
  if(!$(''mapModal'').classList.contains(''show'')) return;
  $(''mapModal'').classList.remove(''show'');
  SND.modal(false);
}
 $(''mmClose'').addEventListener(''click'',closeMapModal);
 $(''mmMask'').addEventListener(''click'',closeMapModal);

/* =========================================================
   实时投影
========================================================= */
function gv(id){ return ($(id).value||'''').trim(); }
function buildText(){
  var g=genderVal();
  var name=gv(''cName'')||(g===''女''%s''刘亦菲'':''彭于晏'');
  var lv=$(''lvRange'').value, ti=titleOf(lv);
  var fh=gv(''cTitle'')%s('' · 封号''+(gv(''cTitle'').indexOf(''「'')===0%sgv(''cTitle''):''「''+gv(''cTitle'')+''」'')):'''';
  var rl=ringListText();
  var sks=[]; skills.forEach(function(s,i){ if(s.trim()) sks.push(''第''+cnum(i+1)+''魂技·''+s.trim()); });
  var bs=[]; BONES.forEach(function(b){ var s=boneSel[b.k]; if(s) bs.push(b.label+''·''+s.n+''（''+s.s+''）''); });
  var ex=[];
  $$(''#extraChars .extra-card'').forEach(function(c,i){
    var q=function(cls){ var el=c.querySelector(''.''+cls); return el%sel.value.trim():''''; };
    var nm=q(''ex-name'')||(''角色''+(i+1));
    var parts=[];
    if(q(''ex-gender'')) parts.push(q(''ex-gender''));
    if(q(''ex-age'')) parts.push(q(''ex-age''));
    if(q(''ex-role'')) parts.push(q(''ex-role''));
    if(q(''ex-spirit'')) parts.push(''武魂：''+q(''ex-spirit''));
    ex.push((i+1)+''. ''+nm+(parts.length%s''（''+parts.join('' · '')+''）'':''''));
    if(q(''ex-look'')) ex.push(''　　外貌：''+q(''ex-look''));
    if(q(''ex-char'')) ex.push(''　　性格：''+q(''ex-char''));
    if(q(''ex-rel'')) ex.push(''　　关系网：''+q(''ex-rel''));
    if(q(''ex-bg'')) ex.push(''　　背景：''+q(''ex-bg''));
  });
  var yr=$(''tlRange'').value, ev=TLE[yr];
  var L=[];
  L.push(''【我的档案】'');
  L.push(''◆ 觉醒'');
  L.push(''武魂：''+(gv(''cSpirit'')||''未觉醒''));
  L.push(''先天魂力：''+(gv(''cPow'')||''未知'')+''（觉醒时与生俱来，决定天赋与修炼速度）'');
  L.push(''◆ 修炼'');
  L.push(''修炼魂力：''+lv+''级 · ''+ti+fh+''（修炼后的实时境界，与先天魂力相互独立）'');
  L.push(''魂环：''+(rl.length%srl.join(''、''):''尚未猎取魂环''));
  L.push(''魂技：''+(sks.length%ssks.join('' ｜ ''):''尚未习得魂技''));
  L.push(''魂骨：''+(bs.length%sbs.join(''、''):''未镶嵌魂骨''));
  L.push(''◆ 基础'');
  L.push(''姓名：''+name);
  L.push(''性别：''+g);
  L.push(''年龄：''+(gv(''cAge'')||''未填写''));
  L.push(''当前时间：斗罗历''+yr+''年'');
  if(gv(''cLook'')) L.push(''外貌：''+gv(''cLook''));
  if(gv(''cChar'')) L.push(''性格：''+gv(''cChar''));
  if(gv(''cId'')) L.push(''身份：''+gv(''cId''));
  if(gv(''cRel'')) L.push(''关系网：''+gv(''cRel''));
  if(gv(''cBg'')) L.push(''背景：''+gv(''cBg''));
  if(gv(''cOpen'')) L.push(''开场白：''+gv(''cOpen''));
  if(ex.length){ L.push(''◆ 同行角色''); ex.forEach(function(x){L.push(x)}); }
  L.push(''◆ 小功能'');
  L.push(''总结：''+(featOn(''summary'')%s''开启'':''关闭'')+'' ｜ 选项：''+(featOn(''options'')%s''开启'':''关闭'')+'' ｜ 直播：''+(featOn(''live'')%s''开启'':''关闭'')+'' ｜ 视角：''+featOn(''person'')+'' ｜ 特写：''+(featOn(''closeup'')%s''开启'':''关闭'')+'' ｜ 美化：''+(featOn(''beautify'')%s''开启'':''关闭''));
  L.push(''小说模式：''+(featOn(''novel'')%s''开启'':''关闭'')+'' ｜ 剧情辅助：''+(featOn(''plot'')%s''开启'':''关闭'')+'' ｜ 回复长度：''+featOn(''length'')+'' ｜ 雌小鬼吐槽：''+(featOn(''gaki'')%s''开启'':''关闭'')+'' ｜ 幕后采访：''+(featOn(''interview'')%s''开启'':''关闭''));
  return L.join(''\n'');
}
function countFill(){
  var n=0;
  [''cName'',''cAge'',''cLook'',''cChar'',''cId'',''cRel'',''cBg'',''cOpen'',''cSpirit'',''cPow'',''cTitle''].forEach(function(id){ if(gv(id)) n++; });
  n+=ringCount();
  n+=skills.filter(function(s){return s.trim()}).length;
  var bn=0; BONES.forEach(function(b){ if(boneSel[b.k]) bn++; }); n+=bn;
  n+=$$(''#extraChars .extra-card'').length;
  return n;
}
function updatePreview(){
  $(''previewPre'').textContent=buildText();
  $(''fillCount'').textContent=countFill();
  $(''featCount'').textContent=FEATS.filter(function(f){return f.v===true}).length;
  $(''innateShow'').textContent=gv(''cPow'')||''未知'';
  $(''cultShow'').textContent=$(''lvRange'').value+'' 级 · ''+titleOf(+$(''lvRange'').value);
}
var pvTimer=null;
function schedPreview(){
  clearTimeout(pvTimer);
  pvTimer=setTimeout(updatePreview,160);
}
[''cName'',''cAge'',''cLook'',''cChar'',''cId'',''cRel'',''cBg'',''cOpen'',''cSpirit'',''cPow''].forEach(function(id){
  $(id).addEventListener(''input'',schedPreview);
});
 $(''leftDrawer'').addEventListener(''input'',schedPreview);
 $(''previewPre'').addEventListener(''click'',function(){ copyText(buildText()); });
 $(''copyBtn'').addEventListener(''click'',function(){ copyText(buildText(),''档案已复制到剪贴板''); });
(function(){
  var armed=false,t=null;
  var btn=$(''clearBtn'');
  btn.addEventListener(''click'',function(){
    if(!armed){
      armed=true; btn.textContent=''再点一次确认清空''; btn.classList.add(''warn'');
      SND.click();
      t=setTimeout(function(){ armed=false; btn.textContent=''清空档案''; btn.classList.remove(''warn''); },2800);
      return;
    }
    clearTimeout(t); armed=false;
    btn.textContent=''清空档案''; btn.classList.remove(''warn'');
    [''cName'',''cAge'',''cLook'',''cChar'',''cId'',''cRel'',''cBg'',''cOpen'',''cSpirit'',''cPow'',''cTitle''].forEach(function(id){ $(id).value=''''; });
    ringState=['''','''','''','''','''','''','''','''',''''];
    $$(''#ringRow .rslot'').forEach(function(s,i){ s.dataset.c=''''; s.textContent=''环位''+CN_NUM[i]; });
    skills=['''','''','''']; renderSkills();
    BONES.forEach(function(b){ boneSel[b.k]=null; }); renderBoneCards();
    $(''extraChars'').innerHTML='''';
    $(''lvRange'').value=10; setLevel(10,true);
    $(''tlRange'').value=2637; setTime(2637,true);
    var slot=$(''drawSlot'');
    slot.className=''draw-slot'';
    $(''dsName'').textContent=''？？？'';
    $(''dsTag'').style.display=''none'';
    $(''dsPow'').textContent=''尚未觉醒武魂'';
    updatePreview();
    SND.del();
    toast(''档案已归于白纸'');
  });
})();
updatePreview();

/* ===== 顶栏开关 ===== */
/* ★ 歌曲列表：一首歌配一个背景视频 */
var SONGS=[
  {name:''斗罗大陆'', music:''https://raw.githubusercontent.com/wszqwe/-/refs/heads/main/f0q6m-v9t8e.mp3'', video:''https://img.wjwj.top/2026/09/23/6d12bb8ca0f7af29c08d554f143931ed.mp4''},
  {name:''破茧'',     music:''https://raw.githubusercontent.com/wszqwe/-/refs/heads/main/tz5de-64tar.mp3'', video:''https://img.wjwj.top/2026/09/23/a0d59c9f8dee53c72935dff55a45ebb4.mp4''},
  {name:''不舍'', music:''https://raw.githubusercontent.com/wszqwe/-/refs/heads/main/bhx2q-x8mea.mp3'', video:''https://img.wjwj.top/2026/09/23/299c250965ad848a7128b6324ff0cb38.mp4''},
  {name:''战歌'', music:''https://raw.githubusercontent.com/wszqwe/-/refs/heads/main/u0nyp-tvcex.mp3'', video:''https://img.wjwj.top/2026/09/23/d9a3e1aa4e78a05e555c2a4e19e67cb7.mp4''},
  {name:''不抛弃不嫌弃'', music:''https://raw.githubusercontent.com/wszqwe/-/refs/heads/main/relzx-kelc4.mp3'', video:''https://img.wjwj.top/2026/09/23/6b4f11705f254ab5f1b8d98f1052de1d.mp4''}];
var videoOn=true;
var bgMusic=$(''bgMusic''), bgVideo=$(''bgVideo'');
var musicIdx=0, musicWanted=true;

function applySong(idx){
  musicIdx=idx;
  var s=SONGS[idx];
  bgMusic.src=s.music;
  try{bgMusic.volume=.45}catch(e){}
  bgVideo.src=s.video;
  if(videoOn){ bgVideo.classList.add(''on''); try{bgVideo.play()}catch(e){} }   /* ← 尊重按钮状态 */
  var p=bgMusic.play(); if(p&&p.catch) p.catch(function(){});
  toast(''♪《''+s.name+''》'');
}

if(SONGS.length){
  applySong(0);
  bgMusic.addEventListener(''ended'',function(){ applySong((musicIdx+1)%SONGS.length); });
  var syncBtn=function(){ $(''btnMusic'').classList.toggle(''on'',!bgMusic.paused); };
  bgMusic.addEventListener(''play'',syncBtn);
  bgMusic.addEventListener(''pause'',syncBtn);
  [''pointerdown'',''touchend'',''click''].forEach(function(ev){
    document.addEventListener(ev,function(){
      if(musicWanted&&bgMusic.paused){
        var p=bgMusic.play(); if(p&&p.catch) p.catch(function(){});
      }
    },true);
  });
  setTimeout(syncBtn,300);
}

 $(''btnMusic'').addEventListener(''click'',function(){
  SND.ensure(); SND.click();
  if(!SONGS.length){
    SND.musicOn=!SND.musicOn;
    this.classList.toggle(''on'',SND.musicOn);
    SND.applyMusic();
    toast(SND.musicOn%s''氛围乐 · 起'':''氛围乐 · 止'');
    return;
  }
  musicWanted=!musicWanted;
  if(musicWanted){
    var p=bgMusic.play(); if(p&&p.catch) p.catch(function(){});
    toast(''♪《''+SONGS[musicIdx].name+''》'');
  }else{
    bgMusic.pause();
  }
});

/* 切歌按钮：歌+视频一起切，到底回第一首 */
 $(''btnNext'').addEventListener(''click'',function(){
  if(!SONGS.length){ SND.click(); toast(''未配置歌曲列表''); return; }
  SND.click();
  applySong((musicIdx+1)%SONGS.length);
});

 $(''btnDm'').addEventListener(''click'',function(){
  DM.on=!DM.on;
  this.classList.toggle(''on'',DM.on);
  SND.click();
  toast(DM.on%s''高维观众入场'':''观众席已静音'');
});

/* ===== ESC 收起所有弹出 ===== */
document.addEventListener(''keydown'',function(e){
  if(e.key!==''Escape'') return;
  if($(''wuhunModal'').classList.contains(''show'')){ sealWuhun(); return; }
  if($(''photoOverlay'').classList.contains(''show'')){ $(''photoOverlay'').classList.remove(''show''); SND.panel(false); return; }
  if($(''mapModal'').classList.contains(''show'')){ closeMapModal(); return; }
  if($(''boneModal'').classList.contains(''show'')){ closeBoneModal(); return; }
  closeDrawer();
});

})();
</script>
<script>
/* ===== ★ 能量环 + 魂力波动 + 标题闪电（自动注入，不动原有 HTML）===== */
(function(){
const wrap=document.querySelector(''.orb-wrap'');
if(!wrap)return;
const TAU=Math.PI*2, R=(a,b)=>a+Math.random()*(b-a), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const hex2rgb=h=>({r:parseInt(h.slice(1,3),16),g:parseInt(h.slice(3,5),16),b:parseInt(h.slice(5,7),16)});
const rgba=(c,a)=>`rgba(${c.r|0},${c.g|0},${c.b|0},${a})`;
const oc=document.getElementById(''orbCanvas'');
if(oc){oc.style.position=''relative'';oc.style.zIndex=2;}   /* 让你的球体盖住后半环 */

/* 品阶色映射（联动 .draw-slot 的稀有度 class） */
const RARITY={''r-waste'':''#9aa7b5'',''r-common'':''#ffd166'',''r-rare'':''#b57bff'',''r-epic'':''#8fa3ff'',''r-legend'':''#ff5e6c'',''r-god'':''#ffd88a''};
let colNow={r:108,g:208,b:255}, colTgt={...colNow}, sprites={}, cnt=0;
function makeSprites(){
  const mk=st=>{const c=document.createElement(''canvas'');c.width=c.height=96;
    const x=c.getContext(''2d''),g=x.createRadialGradient(48,48,0,48,48,48);
    st.forEach(s=>g.addColorStop(s[0],s[1]));x.fillStyle=g;x.fillRect(0,0,96,96);return c;};
  sprites.spark=mk([[0,''rgba(255,255,255,1)''],[.3,rgba(colNow,.9)],[1,rgba(colNow,0)]]);
  sprites.mist =mk([[0,rgba(colNow,.5)],[.55,rgba(colNow,.15)],[1,rgba(colNow,0)]]);
}
makeSprites();

/* —— 生成四层能量环（土星环式穿插球体）—— */
/* 先量球宽：球占屏宽一半以上 → 判定为窄屏（手机） */
const W0=wrap.getBoundingClientRect().width;
const narrow=W0>innerWidth*0.5;
const RINGS= narrow %s [
 /* 手机紧凑版：紧贴水晶球，不会跑出屏幕 */
 {d:1.06,tilt:.30,rot:0,  w:5,dur:11,dir: 1,orbn:3,om:.50},
 {d:1.13,tilt:.26,rot:22, w:4,dur:15,dir:-1,orbn:2,om:.34},
 {d:1.18,tilt:.34,rot:-16,w:3,dur:19,dir: 1,orbn:2,om:.26},
 {d:1.02,tilt:.21,rot:40, w:5,dur:8, dir:-1,orbn:2,om:.62}
]:[
 /* 电脑宽屏版：大气环绕 */
 {d:1.26,tilt:.30,rot:0,  w:5,dur:11,dir: 1,orbn:3,om:.50},
 {d:1.52,tilt:.26,rot:22, w:4,dur:15,dir:-1,orbn:2,om:.34},
 {d:1.80,tilt:.34,rot:-16,w:3,dur:19,dir: 1,orbn:2,om:.26},
 {d:1.04,tilt:.21,rot:40, w:5,dur:8, dir:-1,orbn:2,om:.62}
];
const mkEl=c=>{const d=document.createElement(''div'');d.className=c;return d;};
RINGS.forEach(r=>{
  const pc=r.d*132;
  [''back'',''front''].forEach(half=>{
    const clip=mkEl(''ring-clip ''+half+(r.dir<0%s'' rev'':''''));
    clip.style.cssText=`width:${pc}%;height:${pc}%;margin:${-pc/2}% 0 0 ${-pc/2}%`;
    const plane=mkEl(''ring-plane'');
    plane.style.cssText=`width:75.76%;height:75.76%;--rot:${r.rot}deg`;
    const ell=mkEl(''band-ell''),base=mkEl(''band-base''),spin=mkEl(''band-spin''),grad=mkEl(''band-grad'');
    ell.style.cssText=`--tilt:${r.tilt};--w:${r.w}px`;
    spin.style.animationDuration=r.dur+''s'';
    spin.appendChild(grad);ell.append(base,spin);plane.appendChild(ell);clip.appendChild(plane);
    if(half===''back'')wrap.insertBefore(clip,wrap.firstChild);else wrap.appendChild(clip);
  });
  r.rotR=r.rot*Math.PI/180;r.orbs=[];
  for(let i=0;i<r.orbn;i++){
    const el=mkEl(''orb''),s=R(9,13);
    el.style.width=el.style.height=s+''px'';wrap.appendChild(el);
    r.orbs.push({el,ph:R(0,TAU),om:r.om*R(.8,1.25)});
  }
});

/* —— 球内波动画布（叠在你的 orbCanvas 上）—— */
const fx=document.createElement(''canvas'');fx.id=''soulFx'';
const runes=wrap.querySelector(''.orb-runes'');
if(runes)wrap.insertBefore(fx,runes);else wrap.appendChild(fx);
const fxr=fx.getContext(''2d'');
let W=0,SR=0;
function resize(){
  W=wrap.getBoundingClientRect().width;SR=W/2;
  const dpr=Math.min(devicePixelRatio||1,2);
  fx.width=fx.height=Math.round(W*dpr);
  fxr.setTransform(dpr,0,0,dpr,0,0);fxr.translate(W/2,W/2);
}
addEventListener(''resize'',resize);resize();

/* —— 粒子池 —— */
const env={spin:1,tSpin:1,radial:1,tRadial:1,glow:1,tGlow:1};
const mist=[],sparks=[],arcs=[],waves=[];
for(let i=0;i<12;i++)mist.push({baseR:R(.18,.8),th:R(0,TAU),om:R(.1,.32)*(Math.random()<.5%s-1:1),size:R(.42,.8),ph:R(0,TAU),a:R(.1,.18)});
function spawnArc(){
  const a1=R(0,TAU),a2=a1+R(1.2,3.6),rr=SR*.92;
  arcs.push({ax:Math.cos(a1)*rr,ay:Math.sin(a1)*rr*.9,bx:Math.cos(a2)*rr,by:Math.sin(a2)*rr*.9,cx:R(-.5,.5)*rr*.7,cy:R(-.5,.5)*rr*.7,age:0,life:R(.7,1.4)});
}
function burst(){
  for(let i=0;i<90;i++){
    const a=R(0,TAU),sp=R(.35,1.05)*SR;
    sparks.push({x:R(-.1,.1)*SR,y:R(-.1,.1)*SR,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,life:R(.45,1.25),age:0,sz:R(1.5,4.5),kind:''burst''});
  }
  waves.push({r:SR*.15,v:SR*1.9,a:.9,lw:SR*.055},{r:SR*.1,v:SR*1.4,a:.7,lw:SR*.035});
  env.spin=8;
}

/* —— 联动：长按加速（配合你的指尖闪电）、觉醒变色+爆发 —— */
let pressing=false,lastRar='''';
new MutationObserver(()=>{
  const p=wrap.classList.contains(''pressing'');
  if(p!==pressing){pressing=p;env.tSpin=p%s5.5:1;env.tRadial=p%s.32:1;}
  env.tGlow=pressing%s1.9:(wrap.classList.contains(''hot'')%s1.5:1);
}).observe(wrap,{attributes:true,attributeFilter:[''class'']});
const slot=document.querySelector(''.draw-slot'');
if(slot)new MutationObserver(()=>{
  let cur='''',hex=''#6cd0ff'';
  for(const k in RARITY)if(slot.classList.contains(k)){cur=k;hex=RARITY[k];break;}
  colTgt=hex2rgb(hex);wrap.style.setProperty(''--rc'',hex);
  if(cur&&cur!==lastRar)burst();
  lastRar=cur;
}).observe(slot,{attributes:true,attributeFilter:[''class'']});
window.__soulColor=hex=>{colTgt=hex2rgb(hex);wrap.style.setProperty(''--rc'',hex);};  /* 手动备用接口 */

/* —— 主循环 —— */
let last=0;
function frame(t){
  requestAnimationFrame(frame);
  const dt=clamp((t-last)/1000,0,.05);last=t;
  const k=1-Math.exp(-3*dt),k2=1-Math.exp(-1.3*dt);
  env.spin+=(env.tSpin-env.spin)*k;env.radial+=(env.tRadial-env.radial)*k2;env.glow+=(env.tGlow-env.glow)*k;
  const kc=1-Math.exp(-2.5*dt);
  colNow.r+=(colTgt.r-colNow.r)*kc;colNow.g+=(colTgt.g-colNow.g)*kc;colNow.b+=(colTgt.b-colNow.b)*kc;
  if(Math.abs(colNow.r-colTgt.r)+Math.abs(colNow.g-colTgt.g)+Math.abs(colNow.b-colTgt.b)>3&&++cnt%6===0)makeSprites();

  RINGS.forEach(r=>{
    const rad=W*r.d/2,cr=Math.cos(r.rotR),sr=Math.sin(r.rotR);
    r.orbs.forEach(o=>{
      o.ph+=o.om*r.dir*env.spin*dt;
      const x0=Math.cos(o.ph)*rad,y0=Math.sin(o.ph)*rad*r.tilt;
      const x=x0*cr-y0*sr,y=x0*sr+y0*cr,near=Math.sin(o.ph);
      o.el.style.zIndex=near>0%s4:1;
      o.el.style.opacity=.3+.7*(.5+.5*Math.max(0,near));
      o.el.style.transform=`translate(-50%,-50%) translate(${x}px,${y}px) scale(${.65+.6*Math.max(0,near)})`;
    });
  });

  fxr.clearRect(-SR,-SR,W,W);
  fxr.globalCompositeOperation=''lighter'';
  mist.forEach(m=>{
    m.th+=m.om*env.spin*.9*dt;
    const r=m.baseR*SR*env.radial+Math.sin(t*.0006+m.ph)*SR*.05;
    const s=m.size*SR*env.radial+8;
    fxr.globalAlpha=m.a*env.glow;
    fxr.drawImage(sprites.mist,Math.cos(m.th)*r-s/2,Math.sin(m.th)*r*.85-s/2,s,s);
  });
  if(Math.random()<(pressing%s.05:.008))spawnArc();
  for(let i=arcs.length-1;i>=0;i--){
    const a=arcs[i];a.age+=dt;
    if(a.age>=a.life){arcs.splice(i,1);continue;}
    const al=Math.pow(Math.sin(Math.PI*a.age/a.life),1.5)*.55;
    fxr.beginPath();fxr.moveTo(a.ax,a.ay);fxr.quadraticCurveTo(a.cx,a.cy,a.bx,a.by);
    fxr.strokeStyle=rgba(colNow,al*.3);fxr.lineWidth=5;fxr.stroke();
    fxr.strokeStyle=`rgba(255,255,255,${al})`;fxr.lineWidth=1.4;fxr.stroke();
  }
  if(pressing){
    if(Math.random()<.85){
      const a=R(0,TAU),rr=SR*R(.75,.98),sp=SR*R(.5,.85);
      sparks.push({x:Math.cos(a)*rr,y:Math.sin(a)*rr*.9,
        vx:-Math.cos(a)*sp-Math.sin(a)*sp*.5,vy:-Math.sin(a)*sp+Math.cos(a)*sp*.5,
        life:R(.6,1.1),age:0,sz:R(1.4,3),kind:''in''});
    }
  }else if(sparks.length<46&&Math.random()<.3){
    const a=R(0,TAU),rr=Math.sqrt(Math.random())*SR*.85;
    sparks.push({x:Math.cos(a)*rr*.75,y:Math.abs(Math.sin(a))*rr*.6+SR*.15,
      vx:R(-6,6),vy:-R(14,42),life:R(1.8,3.6),age:0,sz:R(1.2,3.2),kind:''rise''});
  }
  for(let i=sparks.length-1;i>=0;i--){
    const p=sparks[i];p.age+=dt;
    if(p.age>=p.life||p.y<-SR*1.05){sparks.splice(i,1);continue;}
    if(p.kind===''burst''){const f=Math.pow(.88,dt*60);p.vx*=f;p.vy*=f;}
    if(p.kind===''rise'')p.vy-=dt*6;
    p.x+=p.vx*dt;p.y+=p.vy*dt;
    if(p.kind===''in''&&Math.hypot(p.x,p.y)<SR*.1){sparks.splice(i,1);continue;}
    fxr.globalAlpha=Math.sin(Math.PI*p.age/p.life)*.85;
    const s=p.sz*3.2;fxr.drawImage(sprites.spark,p.x-s/2,p.y-s/2,s,s);
  }
  for(let i=waves.length-1;i>=0;i--){
    const w=waves[i];w.r+=w.v*dt;w.a-=dt*1.15;
    if(w.a<=0||w.r>SR*1.15){waves.splice(i,1);continue;}
    fxr.globalAlpha=1;fxr.beginPath();fxr.arc(0,0,w.r,0,TAU);
    fxr.strokeStyle=rgba(colNow,w.a*.5);fxr.lineWidth=w.lw*2;fxr.stroke();
    fxr.strokeStyle=`rgba(255,255,255,${w.a})`;fxr.lineWidth=w.lw*.5;fxr.stroke();
  }
  fxr.globalAlpha=1;fxr.globalCompositeOperation=''source-over'';
}
requestAnimationFrame(frame);
})();

/* ===== ★ 标题“斗罗大陆”闪电 ===== */
(function(){
const h1=document.querySelector(''.hero h1'');
if(!h1||!h1.querySelector(''span''))return;
const lc=document.createElement(''canvas'');
lc.style.cssText=''position:absolute;inset:0;pointer-events:none;z-index:5'';
h1.appendChild(lc);
const g=lc.getContext(''2d''),spans=h1.querySelectorAll(''span'');
const R=(a,b)=>a+Math.random()*(b-a);
let bolt=null,nextAt=performance.now()+1200,last=0;
function fire(){
  const rc=h1.getBoundingClientRect();
  lc.width=Math.round(rc.width);lc.height=Math.round(rc.height);
  const w=lc.width,h=lc.height,pts=[];
  let x=R(.12,.4)*w,y=-4;pts.push([x,y]);
  while(y<h){y+=R(.07,.2)*h;x+=R(-.16,.16)*w;pts.push([x,Math.min(y,h)]);}
  const br=[];
  for(let i=2;i<pts.length-1;i++)if(Math.random()<.45){
    let[cx,cy]=pts[i];const b=[[cx,cy]];
    for(let k=0;k<3;k++){cx+=R(-.09,.09)*w;cy+=R(.03,.09)*h;b.push([cx,cy]);}
    br.push(b);
  }
  bolt={pts,br,life:1};
  const s=spans[Math.random()*spans.length|0];
  if(s){s.classList.add(''zapped'');setTimeout(()=>s.classList.remove(''zapped''),200);}
  nextAt=performance.now()+R(1800,4200);
}
function path(p){g.beginPath();g.moveTo(p[0][0],p[0][1]);for(let i=1;i<p.length;i++)g.lineTo(p[i][0],p[i][1]);}
requestAnimationFrame(function loop(now){
  requestAnimationFrame(loop);
  const dt=Math.min((now-last)/1000,.05);last=now;
  if(!bolt){if(now>=nextAt)fire();return;}
  bolt.life-=dt*3;
  if(bolt.life<=0){bolt=null;g.clearRect(0,0,lc.width,lc.height);return;}
  g.clearRect(0,0,lc.width,lc.height);
  g.globalAlpha=Math.random()<.5%sbolt.life:bolt.life*.35;
  g.lineJoin=g.lineCap=''round'';
  g.strokeStyle=''rgba(140,210,255,.9)'';g.lineWidth=4.5;path(bolt.pts);g.stroke();
  g.strokeStyle=''#fff'';g.lineWidth=1.6;path(bolt.pts);g.stroke();
  g.globalAlpha*=.65;g.lineWidth=1.6;g.strokeStyle=''rgba(160,220,255,.8)'';
  bolt.br.forEach(b=>{path(b);g.stroke();});
  g.globalAlpha=1;
});
})();
</script>
<script>
/* ★ 水晶球本体染色：觉醒后球色随档位变化 ★ */
(function(){
const wrap=document.querySelector(''.orb-wrap''),slot=document.querySelector(''.draw-slot'');
if(!wrap)return;
wrap.style.isolation=''isolate'';            /* 把染色范围锁死在球内 */
const runes=wrap.querySelector(''.orb-runes'');
const tint=document.createElement(''div'');tint.id=''orbTint'';
wrap.insertBefore(tint,runes||wrap.lastChild);
if(runes)runes.style.zIndex=3;             /* 金色"觉醒"符文保持原色不染 */
if(slot)new MutationObserver(()=>{
  let has=false;
  [''r-waste'',''r-common'',''r-rare'',''r-epic'',''r-legend'',''r-god'']
    .forEach(k=>{if(slot.classList.contains(k))has=true;});
  tint.classList.toggle(''on'',has);         /* 觉醒出结果→开染色；重置→关掉回蓝 */
}).observe(slot,{attributes:true,attributeFilter:[''class'']});
window.__awakenColor=hex=>{wrap.style.setProperty(''--rc'',hex);tint.classList.add(''on'');};
})();
</script>
</body>
</html>', '高自由度', '2026-10-11 11:21:20', '2026-10-11 11:21:20', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_cousin_stay', '✨ 姑姑外地出差，照顾不听话的表妹', '叛逆同居 · 纯爱反差', '🎀', '不听话的表妹', '单身公寓与叛逆少女的意外同居', '🎀', '#ec4899', 'linear-gradient(135deg, #ec4899 0%, #be185d 100%)', '{"desc": "单身社畜公寓与叛逆高二挑染表妹林晚晚的意外同居生活。斗嘴、抢手柄、洗澡尴尬走光到深层依赖。", "author": "风月妹酱"}', '[{"name": "林晚晚", "role": "17岁高二表妹", "desc": "挑染短发、露脐短T超短裤，嘴硬心软的叛逆少女，外表像小太妹其实内心纯情"}]', '[{"title": "单身公寓玄关与客厅", "desc": "凌乱的手柄与零食袋，粉色行李箱"}, {"title": "狭小浴室门口", "desc": "热气蒸腾的磨砂玻璃门，遗落在洗衣篮的贴身衣物"}, {"title": "次卧单人床", "desc": "抱枕与玩偶堆积的小天地"}]', '{}', '{"story": "门铃声急促地打破了周末假期的宁静。\n你顶着鸡窝头拉开公寓防盗门，门外站着的赫然是一个身段高挑、充满青春张力的年轻女孩——正是姑姑电话里托付的表妹林晚晚。她留着一头带点挑染的俏丽短发，白皙娇嫩的脸上架着一副无框近视镜，上身穿一件极短的白色修身露脐短T，平坦紧致的小腹上隐约能看见诱人的马甲线；下身则是磨毛牛仔超短裤，笔直修长的雪白大腿晃得人眼晕。\n她一只手拉着粉色行李箱，另一只手把玩着手机，嘴里嚼着泡泡糖，微微仰头斜眼打量着你：“喂，你就是我那个成天只会宅在家里打单机游戏的便宜表哥？地方这么小……我住哪间啊？”", "branches": [{"tag": "A", "title": "一把拉过她的行李箱没收口香糖立家规", "desc": "伸手接过行李箱，顺手捏住她微翘的下巴：“进了我的家门，就得按我的规矩来。”"}, {"tag": "B", "title": "挑眉打量她大胆的穿着故意凑近打趣", "desc": "抱起双臂上下打量她白花花的大腿：“穿这么少出门，你妈没拿皮带抽你？”"}, {"tag": "C", "title": "领她进房间主动帮她整理行李与衣物", "desc": "帮她把沉重的行李搬进次卧，一边收拾一边询问她喜欢吃什么外卖夜宵"}, {"tag": "D", "title": "双手抱胸挡在门口逼她先礼貌叫一声表哥", "desc": "板起脸挡住过道：“叫谁便宜表哥呢？先乖乖叫一声好哥哥，才准进门。”"}], "location": "单身公寓 · 玄关门口"}', NULL, '<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover">
