      --font-body: ''Inter'', ''Segoe UI'', ''PingFang SC'', ''Microsoft YaHei'', sans-serif;
      --font-mono: ''JetBrains Mono'', ''Fira Code'', ''Consolas'', monospace;
    }

    * { margin: 0; padding: 0; box-sizing: border-box; }
    html { scroll-behavior: smooth; scroll-padding-top: 20px; font-size: 16px; background: #160c18; }

    body {
      font-family: var(--font-body);
      background: url(''https://catai.wiki/d1eecdc6-38e6-476f-a35c-19bdc421cc00/w=3000'') no-repeat center center fixed;
      background-size: cover;
      color: #fce8e8;
      overflow-x: hidden;
      min-height: 100vh;
      position: relative;
      letter-spacing: 0.02em;
      line-height: 1.5;
