    ::-webkit-scrollbar-thumb { background: linear-gradient(180deg, #f8a8b8, #f87868, #e8a040, #70c8a8, #78b8d8, #b898d0); border-radius: 0; }

    #particle-canvas { position: fixed; top: 0; left: 0; width: 100%; height: 100%; z-index: 0; pointer-events: none; opacity: 0.5; }
    .main-wrapper { position: relative; z-index: 1; }

    .floating-nav-btn {
      position: fixed; top: 20px; right: 20px; z-index: 1200;
      width: 46px; height: 46px; background: rgba(26, 16, 30, 0.35);
      backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px);
      border: 1px solid rgba(240, 160, 140, 0.5);
