      box-shadow: 0 8px 28px rgba(0,0,0,0.5); transition: 0.25s; border-radius: 0;
    }
    .floating-nav-btn:hover { border-color: rgba(250, 180, 160, 0.85); box-shadow: 0 0 22px rgba(240, 130, 110, 0.5); }
    .floating-nav-btn .hamburger-lines { display: flex; flex-direction: column; gap: 5px; pointer-events: none; }
    .floating-nav-btn .hamburger-lines span { display: block; width: 18px; height: 2px; background: #f8d0c8; transition: 0.25s; }
    .floating-nav-btn.active .hamburger-lines span:nth-child(1) { transform: translateY(7px) rotate(45deg); background: #f8a8b8; }
    .floating-nav-btn.active .hamburger-lines span:nth-child(2) { opacity: 0; }
    .floating-nav-btn.active .hamburger-lines span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); background: #70c8a8; }

    .nav-popup {
