      letter-spacing: 0.06em; transition: 0.2s;
      background: linear-gradient(135deg, #f8a8b8, #f87868, #e8a040, #70c8a8);
      -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
    }
    .nav-popup a:hover { filter: brightness(1.4); }

    .hero-section { min-height: 100vh; }

    .section-container { max-width: 1000px; margin: 0 auto; padding: 2rem 1.5rem; position: relative; z-index: 2; }
    .section-header { margin-bottom: 2rem; text-align: center; }
    .section-label {
      display: inline-block; font-size: 0.7rem; letter-spacing: 0.2em; text-transform: uppercase;
      background: linear-gradient(135deg, #f8a8b8, #f87868, #e8a040, #70c8a8); -webkit-background-clip: text; background-clip: text;
      -webkit-text-fill-color: transparent; margin-bottom: 0.5rem;
      border-bottom: 1px solid rgba(240,160,140,0.5); padding-bottom: 0.3rem;
    }
    .section-title {
      font-family: var(--font-display); font-size: 2.2rem; font-weight: 700;
      background: linear-gradient(135deg, #fce0e0, #f8a8b8, #f87868, #e8a040, #70c8a8, #78b8d8); -webkit-background-clip: text; background-clip: text;
      -webkit-text-fill-color: transparent; margin-bottom: 0.4rem;
    }
