      -webkit-text-fill-color: transparent;
    }

    .sharp-card {
      background: var(--bg-card); backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px);
      border: 1px solid var(--border-dim); border-radius: 0; padding: 1.8rem; margin-bottom: 1.5rem;
      box-shadow: 0 18px 36px rgba(0,0,0,0.6), 0 0 0 1px rgba(240,160,140,0.04) inset;
      transition: 0.3s; position: relative;
    }
    .sharp-card:hover { border-color: rgba(240,160,140,0.55); box-shadow: 0 22px 44px rgba(0,0,0,0.75); }
    .sharp-card::after { content: ''''; position: absolute; bottom: 0; left: 0; width: 55px; height: 2px; background: linear-gradient(90deg, #f8a8b8, #f87868, #e8a040, #70c8a8, #78b8d8, #b898d0); }

    .world-text p {
