    .card-inner-title { font-family: var(--font-display); font-size: 1.5rem; font-weight: 700; background: linear-gradient(135deg, #fce0e0, #f8a8b8, #f87868, #e8a040, #70c8a8); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
    .card-inner-tag { margin-left: auto; font-size: 0.65rem; padding: 0.25rem 0.8rem; border: 1px solid rgba(240,160,140,0.6); background: rgba(240,160,140,0.1); color: #f8a8b8; letter-spacing: 0.1em; text-transform: uppercase; }

    .char-panel { display: flex; flex-direction: column; border-radius: 0; overflow: hidden; border: 1px solid rgba(240,160,140,0.15); background: rgba(20,12,24,0.7); backdrop-filter: blur(16px); margin-bottom: 1.5rem; }
    .char-panel:hover { border-color: rgba(240,160,140,0.55); box-shadow: 0 0 28px rgba(240,130,110,0.2); }
    .char-img-wrap { width: 100%; background: #08040c; }
    .char-img { width: 100%; height: auto; display: block; }
    .char-info { padding: 1.5rem; }
    .char-name { font-family: var(--font-display); font-size: 2rem; font-weight: 700; background: linear-gradient(135deg, #fcd8d0, #f8a8b8, #f87868, #e8a040, #70c8a8); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; margin-bottom: 0.2rem; }
    .char-role { font-size: 0.85rem; background: linear-gradient(135deg, #e8c8c0, #d0a898, #a0c0b8); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; margin-bottom: 1.2rem; }
    .info-seg { margin-bottom: 0.9rem; line-height: 1.7; background: linear-gradient(135deg, #fce8e8, #e8d0c8); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
    .info-seg strong { background: linear-gradient(135deg, #f8a8b8, #f87868, #e8a040, #70c8a8); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; margin-right: 0.4rem; }

    /* 子标题优化 */
