        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#7c6bb0;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
        position:relative;
        font-size:28px;
        letter-spacing:1.5px;
        margin:20px 0 10px;
        color:#332b4d;
    }
    .hero .hero-sub{
        position:relative;
        color:var(--accent-purple);
