            animation: fadeInUp 0.8s ease-out 1.6s both;
        }
        .splash-loading-bar {
            width: 0%;
            height: 100%;
            background: linear-gradient(90deg, var(--gold), var(--wine), var(--purple));
            border-radius: 2px;
