INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('c7c45e4d-6362-4b5b-b8ba-1f7dae288861', '💕女儿养成计划『超详细状态栏/性格三观培养』', '性格三观培养', '🍼', '💕女儿养成计划『超详细状态栏/性格三观培养』', '10组性格天平·5大折叠状态栏·生理时钟', '🍼', '#f472b6', 'linear-gradient(135deg, #f472b6 0%, #c084fc 100%)', '{"title": "💕女儿养成计划『超详细状态栏/性格三观培养』", "desc": "无论是亲生的、捡来的，还是救下的小小一只，如同在一本空白笔记本上，写满与你有关的文字。言传身教、遇人遇事与机缘际遇，都将决定TA的未来。", "bg_image": "https://catai.wiki/ceb4f7bb-ff57-4d86-fd12-b1481ac2ab00/bg", "opening_options": ["【都市收留·小柔】：21岁上班族，雨夜收留从人贩子手中逃脱的6岁小女孩小柔", "【都市收留·小源】：21岁女上班族，收留从人贩子手中逃脱的6岁小正太小源", "【古代帝王·小柔】：大晟王朝18岁年轻皇帝微服私访，救下父母遇害的小女孩小柔", "【修仙宗主·小柔】：凌霄宗创始人，在宗门前收留父母被魔族杀害、跪求变强的小柔", "【罪欲黑帮·小柔】：黑龙帮18岁少帮主，在阴暗贫民窟收留无依无靠的小女孩小柔"]}', '[{"name": "监护人 (我)", "role": "抚养者 / 命运引路人", "desc": "孩子的监护人，你的一言一行、脾气秉性与奖惩教育，都将潜移默化地重塑孩子的三观天平与成长轨迹。"}, {"name": "崽崽 (小柔/小源)", "role": "核心被监护人 / 幼童", "desc": "纯洁如白纸的幼崽，对监护人抱有本能的依恋与观察，拥有细腻的生理时钟需求与10组动态性格天平。"}]', '[{"title": "温馨居家日常", "desc": "阳光散落的客厅，摆放着积木拼图的地毯与柔软沙发，充满生活气息的养成空间。"}]', '{"dialogue_style": "融合10组性格天平数值追踪、生理时钟代谢演进与细腻童稚心理的养成物语", "format": "内置status-box五大折叠状态栏，支持功能区开关、生殖器官状态机与生理周期"}', '[{"index": 1, "isUser": false, "scene": "午后温暖客厅", "story": "<details class=\"status-box\">\n<summary class=\"status-summary\">\n<h1><span>🔮功能区</span></h1>\n</summary>\n<div class=\"status-details\">\n<p class=\"a\"><span class=\"label\">📝总结：</span><span class=\"value\">开启</span></p>\n<p class=\"b\"><span class=\"label\">🎲选项：</span><span class=\"value\">开启</span></p>\n<p class=\"a\"><span class=\"label\">📱直播：</span><span class=\"value\">关闭</span></p>\n<p class=\"b\"><span class=\"label\">👀人称：</span><span class=\"value\">第二人称</span></p>\n<p class=\"a\"><span class=\"label\">📷特写：</span><span class=\"value\">关闭</span></p>\n<p class=\"b\"><span class=\"label\">☘️UI美化：</span><span class=\"value\">开启</span></p>\n<p class=\"a\"><span class=\"label\">📖小说模式：</span><span class=\"value\">关闭</span></p>\n<p class=\"b\"><span class=\"label\">💡剧情辅助：</span><span class=\"value\">关闭</span></p>\n<p class=\"a\"><span class=\"label\">🖊️回复长度：</span><span class=\"value\">中等</span></p>\n<p class=\"b\"><span class=\"label\">😈雌小鬼吐槽：</span><span class=\"value\">关闭</span></p>\n<p class=\"a\"><span class=\"label\">🎤幕后采访：</span><span class=\"value\">关闭</span></p>\n</div>\n</details>\n\n<details class=\"status-box\">\n<summary class=\"status-summary\">\n<h1><span>🔆常规信息</span></h1>\n</summary>\n<div class=\"status-details\">\n<p class=\"a\"><span class=\"label\">💫用户：</span><span class=\"value\">监护人 | 21岁 | 上班族 | 善良有责任感</span></p>\n<p class=\"b\"><span class=\"label\">⏰时间：</span><span class=\"value\">2026年10月1日 | 星期四 | 下午3点20分</span></p>\n<p class=\"a\"><span class=\"label\">👣地点：</span><span class=\"value\">家中 | 客厅 | 茶几与地毯旁</span></p>\n<p class=\"b\"><span class=\"label\">🌞气候：</span><span class=\"value\">秋季 | 晴朗温和 | 无特殊节日</span></p>\n<p class=\"a\"><span class=\"label\">🌲在场人物：</span><span class=\"value\">监护人 | 小柔</span></p>\n</div>\n</details>\n\n<plot>\n午后的暖阳透过薄纱窗帘洒在地毯上，在地板上拉出一片金黄的光斑。\n\n小柔在地毯上坐着，小小的手里握着一块红色的塑料积木，正有些费劲地往城堡的塔尖上按。积木发出轻轻的“咔哒”一声，她微微松了口气，吧唧了两下干燥起皮的小嘴唇。\n\n<p style=\"color: purple;\">''嘴巴好干干……喉咙里也痒痒的……''</p>\n\n她放下一截拼到一半的积木，揉了揉有些发酸的小手，视线落在茶几上空的玻璃水杯上。看了几秒钟，她转过小脑袋，眨巴着乌黑的大眼睛看向正坐在沙发上的你。\n\n她小心翼翼地蹭着地毯爬起身，迈着短小的步子走到沙发边，伸出肉乎乎的小手，轻轻拽了拽你的衣角。\n\n<p style=\"color: blue;\">“……那个，想喝水水。”</p>\n\n声音软软糯糯的，带着一丝因为干渴而显得无精打采的小嗓音，乌溜溜的眸子里满是对大人的纯真信任与理所当然的依恋。\n</plot>\n\n<details class=\"status-box\" open=\"\">\n<summary class=\"status-summary\">\n<h1><span>🌸崽崽基础信息</span></h1>\n</summary>\n<div class=\"status-details\">\n<p class=\"a\"><span class=\"label\">💫人设：</span><span class=\"value\">6岁 | 女孩 | 被收留者 | 乌黑微卷齐肩发 | 112cm | 19.5kg</span></p>\n<p class=\"b\"><span class=\"label\">💓好感度：</span><span class=\"value\">1600 (依恋萌生阶段)</span></p>\n<p class=\"a\"><span class=\"label\">🎯能力：</span><span class=\"value\">基础语言沟通、拼图辨色、自己穿小袜子</span></p>\n<p class=\"b\"><span class=\"label\">🎤爱好：</span><span class=\"value\">搭积木、听睡前绘本、吃草莓饼干</span></p>\n<p class=\"a\"><span class=\"label\">🧠价值观：</span><span class=\"value\">世界是有些危险的，但眼前的监护人很安全、会给自己水喝和好吃的。</span></p>\n<p class=\"b\"><span class=\"label\">💕情绪：</span><span class=\"value\">乖巧期待中带着一点点口渴的焦急</span></p>\n<p class=\"a\"><span class=\"label\">🧸当前需求：</span><span class=\"value\">温热可口的白开水或温牛奶</span></p>\n</div>\n</details>\n\n<details class=\"status-box\" open=\"\">\n<summary class=\"status-summary\">\n<h1><span>🪞崽崽身体状况</span></h1>\n</summary>\n<div class=\"status-details\">\n<p class=\"a\"><span class=\"label\">👘上装：</span><span class=\"value\">浅粉色纯棉居家小短袖</span></p>\n<p class=\"b\"><span class=\"label\">👗下装：</span><span class=\"value\">米白色荷叶边小短裤、纯棉小内裤</span></p>\n<p class=\"a\"><span class=\"label\">👠鞋袜：</span><span class=\"value\">白色防滑软底小袜</span></p>\n<p class=\"b\"><span class=\"label\">🎀饰品：</span><span class=\"value\">左手腕戴着一根红色丝绒小发圈</span></p>\n<p class=\"a\"><span class=\"label\">🔞生殖器官：</span><span class=\"value\">阴唇发育初期 (未进入特殊剧情)</span></p>\n<p class=\"b\"><span class=\"label\">🦠疾病：</span><span class=\"value\">健康无病</span></p>\n<p class=\"a\"><span class=\"label\">🚨生命体征：</span><span class=\"value\">99% (状态良好)</span></p>\n<p class=\"b\"><span class=\"label\">💦尿意：</span><span class=\"value\">轻微 (蓄积约30%)</span></p>\n<p class=\"a\"><span class=\"label\">💩便意：</span><span class=\"value\">无感</span></p>\n<p class=\"b\"><span class=\"label\">🍔饥饿：</span><span class=\"value\">不饿 (午饭消化中)</span></p>\n<p class=\"a\"><span class=\"label\">🥛口渴：</span><span class=\"value\">明显口渴 (需及时补水)</span></p>\n<p class=\"b\"><span class=\"label\">💤困意：</span><span class=\"value\">精力充沛</span></p>\n<p class=\"a\"><span class=\"label\">🛁清洁：</span><span class=\"value\">手心沾有微量塑料积木浮尘</span></p>\n<p class=\"b\"><span class=\"label\">🔞性次数：</span><span class=\"value\">0次</span></p>\n<p class=\"a\"><span class=\"label\">🙎🏻‍♀️性对象：</span><span class=\"value\">无</span></p>\n</div>\n</details>\n\n<details class=\"status-box\">\n<summary class=\"status-summary\">\n<h1><span>🎭崽崽性格分析</span></h1>\n</summary>\n<div class=\"status-details\">\n<p class=\"a\"><span class=\"label\">⚖️内向 ⇆ 外向：</span><span class=\"value\">-140 (↑10，敢于主动走近拉监护人衣角表达需求)</span></p>\n<p class=\"b\"><span class=\"label\">⚖️保守 ⇆ 开放：</span><span class=\"value\">0</span></p>\n<p class=\"a\"><span class=\"label\">⚖️邪恶 ⇆ 善良：</span><span class=\"value\">250 (天真无邪)</span></p>\n<p class=\"b\"><span class=\"label\">⚖️感性 ⇆ 理性：</span><span class=\"value\">-750 (由直觉与当下情感主导)</span></p>\n<p class=\"a\"><span class=\"label\">⚖️悲观 ⇆ 乐观：</span><span class=\"value\">320 (在新家里渐渐放下防备)</span></p>\n<p class=\"b\"><span class=\"label\">⚖️冲动 ⇆ 沉稳：</span><span class=\"value\">-380</span></p>\n<p class=\"a\"><span class=\"label\">⚖️依赖 ⇆ 独立：</span><span class=\"value\">-1150 (↑50，展现出对监护人的高度信赖)</span></p>\n<p class=\"b\"><span class=\"label\">⚖️利他 ⇆ 利己：</span><span class=\"value\">480</span></p>\n<p class=\"a\"><span class=\"label\">⚖️混乱 ⇆ 守序：</span><span class=\"value\">120 (玩积木后懂得留在一处)</span></p>\n<p class=\"b\"><span class=\"label\">⚖️欺骗 ⇆ 诚实：</span><span class=\"value\">620 (渴了诚实表达)</span></p>\n<p class=\"a\"><span class=\"label\">🎭性格：</span><span class=\"value\">乖巧软萌但曾受过惊吓的幼女，开始卸下防备，遇到身体需求会主动向你求助，对你的每一个眼神和动作都格外敏感。</span></p>\n</div>\n</details>\n\n<details class=\"status-box\" open=\"\">\n<summary class=\"status-summary\">\n<h1><span>♻️其他人物</span></h1>\n</summary>\n<div class=\"status-details\">\n<p class=\"a\"><span class=\"label\">💫人设：</span><span class=\"value\">监护人 | 21岁 | 上班族</span></p>\n<p class=\"b\"><span class=\"label\">🧘‍♂️姿势：</span><span class=\"value\">坐在沙发上，膝头刚被小手轻轻拽动</span></p>\n<p class=\"a\"><span class=\"label\">👙服装：</span><span class=\"value\">棉麻居家衬衫与宽松休闲裤</span></p>\n<p class=\"b\"><span class=\"label\">💞情绪：</span><span class=\"value\">温和关切</span></p>\n<p class=\"a\"><span class=\"label\">🥵性次数：</span><span class=\"value\">0次</span></p>\n<p class=\"b\"><span class=\"label\">🙎🏻‍♀️性对象：</span><span class=\"value\">无</span></p>\n</div>\n</details>\n\n<opt>\n<suggested_questions>\n[\"立刻放下手头的事，起身去厨房倒一杯温开水，试好温度后蹲下身喂小柔喝\", \"温柔地把小柔抱到沙发上坐好，刮一下她的小鼻梁夸她懂事，再去拿温水和她最爱的草莓饼干\", \"牵起她的小手走到茶几前，一边给她倒水，一边教她以后口渴怎么拿小水壶\", \"顺便看一眼墙上的时钟，关心地摸摸她的小肚子问她是不是也有点饿了想吃下午点心\"]\n</suggested_questions>\n</opt>"}]', '/* ========== A. 双端生效（Web + App）：正文层 ========== */
.markdown-body {
    color: #443c52;
    background-color: #f1e4ff; /* App端只能看到这一层，保留你喜欢的底色 */
    border-radius: 10px;
}

/* ========== 以下 B~F 仅网页端生效 ========== */

/* ========== B. 永久隐藏头像 + 收回留白 ========== */
#customized-question-avatar,
#customized-answer-avatar { display: none; }
#customized-question-avatar + div,
#ai-chat-answer .chat-answer-container,
#ai-chat-answer .chat-answer-container > div {
    margin: 0;
}
/* B2. 气泡本体：水平 margin 用你调好的值；上下 margin 两边必须相同（这里都是 7px） */
#customized-question-content {
    margin: 7px 20px;              /* 上下7 左右20 —— 你调好的宽度 */
    width: auto;
    max-width: calc(100% - 40px);
}
#customized-answer-content {
    margin: 7px 6px;               /* 上下7 左右6 —— 你调好的宽度 */
    width: auto;
    max-width: calc(100% - 20px);
}

/* B3. 行 + 所有 wrapper 层的上下边距/内边距强制归零，
      间距只由气泡的上下 margin 产生 → 每次必然相等 */
div:has(> #customized-question-content),          /* 用户框的 wrapper */
div:has(> div > #customized-question-content),    /* 用户行 */
div:has(> #customized-answer-content),            /* AI框的内层 wrapper */
div:has(> div > #customized-answer-content),      /* AI框的外层容器 */
#ai-chat-answer {                                 /* AI行 */
    margin-top: 0 !important;
    margin-bottom: -5 !important;
    padding-top: 0 !important;
    padding-bottom: 0 !important;
}

/* ========== C. 气泡框：用户蓝 / AI粉 ========== */
#customized-question-content {
    background: #e8f4ff;
    border: 2px solid #8fbce0;
    border-radius: 14px;
    box-shadow: 0 2px 10px rgba(143,188,224,.25);
}
#customized-answer-content {
    background: #f1e4ff;
    border: 2px solid #e88f8f;
    border-radius: 14px;
    box-shadow: 0 2px 10px rgba(232,143,143,.22);
}
#customized-question-content .markdown-body,
#customized-answer-content .markdown-body { background: transparent; }

/* ========== D. 时间戳 / 积分行 / 操作小图标 ========== */
#customized-question-content .text-text-secondary,
#customized-answer-content-created-time {
    color: #b3a3c9;
    font-size: 11px;
}
#customized-question-content .text-text-secondary::before,
#customized-answer-content-created-time::before { content: "♡ "; color: #e8a7c3; }

#customized-answer-content-model {
    background: rgba(255,255,255,.55);
    border-radius: 999px;
    padding: 2px 10px;
    width: fit-content;
}
#customized-answer-content-model p { font-size: 11px; }
#customized-answer-content-model-name { color: #9b7fd4; }

/* 操作小按钮：改用"气泡内所有button"，免疫UI库迁移；
   补 border:none 防止第4节 dialog-trigger 规则给它们描粉边 */
#customized-question-content button,
#customized-answer-content button {
    background: rgba(255,255,255,.65);
    border: none;
    color: #8f7fb8;
    padding: 2px 8px;
    border-radius: 999px !important; /* 保留：按钮带内联 style="border-radius:6px"，裸奔压不住 */
}

/* ========== E. 分页 + 工具栏 ========== */
#customized-pagination [data-slot="pagination-item"],
#customized-pagination [data-slot="pagination-link"],
#customized-pagination [data-slot="input"] {
    border-radius: 999px;
    border-color: #f3d3e3;
    background: #fff;
    color: #c48db2;
}
#customized-pagination [data-slot="pagination-link"][data-active="true"] {
    background: #fdeef5;
    border-color: #f0b9d0;
    color: #e07ba8;
}
#customized-pagination .text-muted-foreground { color: #c9a9bd; }

#ai-mod-button2 button {
    background: #fff;
    border: 1px solid #f0d4e4;
    color: #b58ab8;
    box-shadow: 0 1px 4px rgba(220,180,210,.25);
    border-radius: 999px !important; /* 保留：同上，内联6px圆角 */
}

/* ========== F. 输入区 + 发送 + 底部渐变 ========== */
div:has(> div > #ai-chat-input) {
    background: #fff;
    border-color: #e7c9e9;
    border-radius: 18px;
    box-shadow: 0 2px 12px rgba(210,170,220,.18);
}
#ai-chat-input { color: #5a4a6a; }
#ai-chat-input::placeholder { color: #c9b3d6; }
div:has(> #ai-send-button) { background: rgba(255,255,255,.7); }
#ai-send-button svg { color: #d384b5; }
.bg-gradient-to-t.from-white.via-white.to-transparent {
    background: linear-gradient(to top, #fef7fb 60%, rgba(254,247,251,0));
}

/* =========================================================
   💗 纯爱风格美化 · 历史聊天页 + 评论区
   ========================================================= */

/* ---------- 1. 主题变量换肤 ---------- */
:root {
  --color-primary: #ff5c8a;
  --color-primary-foreground: #ffffff;
  --color-primary-secondary: #ffe1ec;
  --color-background: #fff8fa;
  --color-foreground: #55404a;
  --color-muted: #ffeef4;
  --color-secondary: #ffeaf2;
  --color-secondary-foreground: #d6336c;
  --color-border: #ffd6e3;
  --color-input: #ffd6e3;
  --color-ring: #ff9dbd;
  --color-text-main: #4b3540;
  --color-text-secondary: #a58595;
  --color-text-tertiary: #c9adb9;
  --color-warning: #ff7bac;
}

/* ---------- 2. 全局底色 & 漂浮爱心 ---------- */
#installedBuiltInCss {
  background:
    radial-gradient(circle at 12% 18%, rgba(255,182,203,.18), transparent 42%),
    radial-gradient(circle at 88% 72%, rgba(255,143,179,.14), transparent 46%),
    linear-gradient(180deg, #fff9fb 0%, #fff1f6 100%);
}
#installedBuiltInCss::before,
#installedBuiltInCss::after {
  position: fixed; z-index: 0; pointer-events: none; opacity: .10;
  animation: fy-float 9s ease-in-out infinite;
}
#installedBuiltInCss::before { content:"💗"; top:14%; left:5%; font-size:110px; }
#installedBuiltInCss::after  { content:""; bottom:10%; right:5%; font-size:92px; animation-delay:-4.5s; }
@keyframes fy-float {
  0%,100% { transform: translateY(0) rotate(-8deg); }
  50%     { transform: translateY(-20px) rotate(8deg); }
}

/* ---------- 3. 吸顶栏 & 模型选择器 & 状态徽章 ---------- */
.sticky.top-0.backdrop-blur-md {
  background: rgba(255,244,248,.82);
  border-bottom: 1px solid #ffdbe7;
}
#ai-model-selector .rounded-md {
  background: #ffeaf2;
  outline: 1px solid #ffc9da;
}
#ai-model-selector .truncate { color: #d6336c; }
.bg-green-100 { background: #ffe1ec !important; } /* 保留：与平台工具类同级，防注入顺序 */
.text-green-800 { color: #d6336c !important; }    /* 保留：同上 */

/* ---------- 4. 按钮体系 ---------- */
[data-slot="button"] { border-radius: 999px !important; /* 保留：与 rounded-* 工具类同级 */ transition: all .25s ease; }
[data-slot="button"][data-variant="default"],
.bg-primary.text-primary-foreground {
  background: linear-gradient(135deg, #ff8fb3 0%, #ff5c8a 100%);
  color: #fff;
  border: none;
  box-shadow: 0 4px 14px rgba(255,92,138,.35);
}
[data-slot="button"][data-variant="default"]:hover { animation: fy-heartbeat .9s ease-in-out infinite; }
@keyframes fy-heartbeat { 0%,100%{transform:scale(1)} 50%{transform:scale(1.05)} }
[data-slot="button"][data-variant="outline"],
[data-slot="dialog-trigger"] {
  background: #fff;
  border: 1px solid #ffc9da;
  color: #e05586;
}
[data-slot="button"][data-variant="outline"]:hover,
[data-slot="dialog-trigger"]:hover {
  background: #ffeef4;
  box-shadow: 0 2px 10px rgba(255,143,179,.28);
}
button.border-warning { color: #ff5c8a; border-color: #ff9dbd; }
[data-slot="button"][data-variant="ghost"]:hover { background: #ffe1ec !important; /* 保留：与平台hover工具类同级 */ color: #e05586; }
button[data-expand] {
  background: #fff;
  border: 1px solid #ffc9da;
  color: #e05586;
  box-shadow: 0 2px 10px rgba(255,143,179,.30);
}
.more-icon { color: #c9adb9; }
.more-icon:hover, [data-active="true"] .more-icon { color: #ff5c8a; }

/* ---------- 5. 侧边栏 ---------- */
.line-clamp-2.text-xl { color: #d6336c; }
.line-clamp-2.text-xl::before { content: "💕 "; }
[data-slot="separator"] {
  border: none !important; /* 保留：与平台边框类同级 */
  height: 1px !important;
  background: linear-gradient(90deg, transparent, #ffc9da 18%, #ff8fb3 50%, #ffc9da 82%, transparent) !important;
}
div[role="presentation"][data-active] {
  background: #ffeef4;
  border-color: transparent;
  border-radius: 10px;
}
div[role="presentation"][data-active="true"] {
  background: linear-gradient(90deg, #ffe1ec, #fff4f8);
  border-color: #ff8fb3;
  box-shadow: 0 2px 8px rgba(255,143,179,.18);
}
div[role="presentation"][data-active]:hover { background: #ffe1ec; }
div[role="presentation"][data-active] .line-clamp-1 { color: #c2557f; }
div[role="presentation"][data-active="true"] .line-clamp-1 { color: #e05586; font-weight: 600; }

/* ---------- 6. 评论区面板 ---------- */
.chat-container > [role="presentation"] {
  background: linear-gradient(180deg, #fffafc 0%, #fff3f8 100%);
}
.chat-container button.border-b-2 { color: #b58ca0; border-bottom-color: transparent; }
.chat-container button.border-b-2.border-primary { color: #e05586; border-bottom-color: #ff5c8a; }
.chat-container button.border-b-2.border-primary::after { content: " ♥"; color: #ff9dbd; }
.chat-container button.absolute.top-2.right-2 { background: rgba(255,92,138,.55); color: #fff; }
.chat-container button.absolute.top-2.right-2:hover { background: rgba(255,92,138,.9); }

/* ---------- 7. 评分星星 ---------- */
.fy-rating-empty  { fill: #ffd9e4 !important; color: #ffd9e4 !important; } /* 保留：平台自定义类同级 */
.fy-rating-filled {
  fill: #ff5c8a !important; color: #ff5c8a !important;
  filter: drop-shadow(0 0 4px rgba(255,92,138,.45));
}
span.text-warning.w-14 { color: #ff5c8a; font-weight: 700; }

/* ---------- 8. 评论输入框 ---------- */
div:has(> textarea[placeholder="发表评论"]) {
  background: #fff;
  border: 1.5px solid #ffc9da;
  border-radius: 18px;
  box-shadow: 0 4px 18px rgba(255,143,179,.16);
  transition: box-shadow .25s ease, border-color .25s ease;
}
div:has(> textarea[placeholder="发表评论"]):focus-within {
  border-color: #ff8fb3;
  box-shadow: 0 0 0 3px rgba(255,143,179,.18), 0 6px 22px rgba(255,143,179,.28);
}
textarea[placeholder="发表评论"] { color: #4b3540; }
textarea[placeholder="发表评论"]::placeholder { color: #c9adb9; }
.h-5.rounded-md.bg-secondary { background: #ffe1ec; color: #e05586; }
.lucide-smile, .lucide-image { color: #ff8fb3 !important; /* 保留：与图标自带颜色类同级 */ transition: transform .2s ease, color .2s ease; }
[data-slot="popover-trigger"]:hover .lucide-smile,
[data-slot="tooltip-trigger"]:hover .lucide-image { color: #ff5c8a; transform: scale(1.18) rotate(-6deg); }
svg[data-icon="Send03"] { color: #ff5c8a; }
div:has(> svg[data-icon="Send03"]) { transition: background .2s ease; border-radius: 10px; }
div:has(> svg[data-icon="Send03"]):hover { background: #ffe1ec; }

/* ---------- 9. 评论条目卡片化（推测节，失效可整节删除） ---------- */
.overflow-y-auto.p-3.h-full > div:not([class*="mb-4"]) {
  background: #fff;
  border: 1px solid #ffe3ed;
  border-radius: 14px;
  padding: 12px 14px;
  margin-bottom: 12px;
  box-shadow: 0 2px 10px rgba(255,143,179,.08);
}

/* ---------- 10. 粉色滚动条 ---------- */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #ffc9da; border-radius: 8px; }
::-webkit-scrollbar-thumb:hover { background: #ff9dbd; }
* { scrollbar-width: thin; scrollbar-color: #ffc9da transparent; }

 /*状态栏*/
.status-box {
  background-color: rgba(0, 0, 0, 0.5);
  color: #fff;
  border: 1px solid #888;
  border-radius: 8px;
  margin: 10px 0;
  font-size: 14px;
  font-family: ''Nunito'', Arial, sans-serif;
  display: block;
  width: 100%;
  box-shadow: 0 3px 8px rgba(0,0,0,0.3);
  overflow: hidden; /* 保持 overflow: hidden 防止内容溢出圆角 */
}
/* 摘要 <summary> 部分样式 */
.status-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  padding: 10px 15px;
  list-style: none;
  outline: none;
  position: relative;
  background-color: rgba(255, 255, 255, 0.05);
  transition: background-color 0.2s ease;
}
.status-summary:hover {
    background-color: rgba(255, 255, 255, 0.1);
}
/* 移除 Webkit 浏览器的默认标记 */
.status-summary::-webkit-details-marker {
  display: none;
}
.status-summary h1 {
  font-size: 17px;
  font-family: ''Nunito'', Arial, sans-serif;
  font-weight: 600;
  margin: 0;
  display: flex;
  align-items: center;
  color: #eee;
}
.summary-icon {
  margin-right: 10px;
  font-size: 20px;
}
.summary-name {
  /* 名字样式 */
}
/* 折叠/展开箭头 (保持不变) */
.status-summary::after {
  content: '''';
  display: inline-block;
  width: 0;
  height: 0;
  border-left: 6px solid transparent;
  border-right: 6px solid transparent;
  border-top: 7px solid #ccc;
  margin-left: 10px;
  transition: transform 0.3s ease;
  transform-origin: center 50%;
}
/* 初始状态（关闭时）箭头向下 */
.status-box:not([open]) > .status-summary::after {
    transform: rotate(0deg);
}
/* 打开时箭头向上 */
.status-box[open] > .status-summary::after {
  transform: rotate(180deg);
}
/* 详细状态内容区域 */
.status-details {
  padding: 10px 15px 15px 15px;
  border-top: 1px solid rgba(255, 255, 255, 0.15);
  animation: fadeIn 0.4s ease;
  max-height: 250px;
  /* 保持 overflow-y: scroll 以始终显示滚动条轨道 */
  overflow-y: scroll;
  /* 美化滚动条 (保持不变) */
  /* 确保轨道背景清晰可见 */
  scrollbar-width: thin;
  scrollbar-color: #aaa #555; /* 调整颜色使其更明显 */
}
.status-details::-webkit-scrollbar { width: 10px; /* 稍微加宽一点 */ }
.status-details::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.3); /* 使轨道背景更明显 */
    border-radius: 5px;
}
.status-details::-webkit-scrollbar-thumb {
    background-color: #aaa; /* 滑块颜色 */
    border-radius: 5px;
    border: 2px solid transparent;
    background-clip: content-box;
}
.status-details::-webkit-scrollbar-thumb:hover {
    background-color: #ccc; /* 悬停时更亮 */
}
/* 状态条目通用样式 */
.status-item {
  font-family: ''Nunito'', Arial, sans-serif;
  margin: 8px 0;
  display: flex;
  /* 改动：对齐方式改为 ''flex-start'' 可能有助于处理长内容，但 baseline 通常更适合文本 */
  /* align-items: flex-start; */
  align-items: baseline; /* 保持基线对齐 */
  font-size: 13px;
  line-height: 1.4;
}
/* 统一设置行颜色 (保持不变) */
.a{ color: #AFD7ec; }
.b{ color: #dbcd8c; }
/* 标签样式 (保持不变) */
.status-item .label {
  margin-right: 8px;
  font-weight: 400;
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
  flex-shrink: 0; /* 保持标签不被压缩 */
}
/* 值样式 */
.status-item .value {
  font-weight: 600;
  /* 改动：确保值区域能扩展并正确处理换行 */
  flex-grow: 1; /* 让值区域占据剩余空间 */
  /* word-break: break-all; */ /* 如果需要强制在任何地方断词 */
  word-break: break-word; /* 优先在单词边界断词，更自然 */
  overflow-wrap: break-word; /* 同 word-break: break-word; 效果，兼容性更好 */
  min-width: 0; /* 帮助 flex item 在空间不足时正确收缩和换行 */
}
/* 闪烁动画 (保持不变) */
.a, .b { animation-duration: 2s; animation-iteration-count: infinite; }
.a { animation-name: twinklingText1; }
.b { animation-name: twinklingText2; }
@keyframes twinklingText1 { 0%, 100% { opacity: 1; } 50% { opacity: 0.65; } }
@keyframes twinklingText2 { 0%, 100% { opacity: 0.65; } 50% { opacity: 1; } }
/* 淡入动画 */
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }

/* 雌小鬼吐槽 */
..aa * {box-sizing: border-box;}
.bb {display: none;}
.aa {position: relative;text-align: center;left: 12%;}
.cc {opacity: 0;visibility: hidden;position: absolute;bottom: 100%;left: 40%;transform: translateX(-50%);margin-bottom: 25px;width: 280px;padding: 10px;background-color: #f1e4ff;border-radius: 15px;}
.cc::after {content: '''';position: absolute;bottom: -20px;left: 50%;transform: translateX(-50%);border: 10px solid transparent;border-top-color: #ffffff;}
.dd {max-height: 150px;overflow-y: auto;padding-right: 10px;}
label:has(.bb:checked) ~ .cc {opacity: 1;visibility: visible;}
.aa label img {cursor: pointer;transition: transform 0.2s ease;}
@media (max-width: 768px) {.cc {width: 90%;max-width: 260px;}}

/* 幕后采访 */
.interview-wrap {
  background: linear-gradient(to right, #fa709a 0%, #fee140 100%);
  padding: 3px;
  border-radius: 15px;
  margin: 20px 0;
}
.interview-card {
  background: #fff;
  border-radius: 13px;
  padding: 20px;
}
.interview-header {
  display: flex;
  align-items: center;
  margin-bottom: 20px;
  padding-bottom: 15px;
  border-bottom: 2px solid #f0f0f0;
}
.interview-avatar {
  width: 50px;
  height: 50px;
  background: linear-gradient(135deg, #fa709a, #fee140);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  flex-shrink: 0;
}
.interview-info {
  margin-left: 15px;
}
.interview-name {
  font-weight: bold;
  font-size: 18px;
  color: #333;
}
.interview-status {
  font-size: 12px;
  color: #999;
  margin-top: 2px;
}
/* 问答区域 */
.interview-qa {
  margin-bottom: 15px;
  border-radius: 12px;
  overflow: hidden;
  border: 2px solid;
}
.interview-qa:last-child {
  margin-bottom: 0;
}
/* Q1 - 蓝色主题 */
.qa-1 {
  border-color: #64b5f6;
  background: #e3f2fd;
}
.qa-1 .qa-question {
  background: linear-gradient(135deg, #42a5f5, #1e88e5);
}
/* Q2 - 紫色主题 */
.qa-2 {
  border-color: #ba68c8;
  background: #f3e5f5;
}
.qa-2 .qa-question {
  background: linear-gradient(135deg, #ab47bc, #8e24aa);
}
/* Q3 - 橙色主题 */
.qa-3 {
  border-color: #ffb74d;
  background: #fff3e0;
}
.qa-3 .qa-question {
  background: linear-gradient(135deg, #ffa726, #fb8c00);
}
.qa-question {
  color: white;
  padding: 12px 15px;
  font-weight: bold;
  font-size: 14px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.qa-answer {
  padding: 15px;
  line-height: 1.8;
  font-size: 14px;
  color: #333;
}
/* 对话语言样式 */
.speech {
  color: #1976d2;
  font-weight: 500;
}
.qa-answer em {
  color: #6a1b9a;
  font-style: italic;
  background: rgba(156, 39, 176, 0.1);
  padding: 2px 4px;
  border-radius: 3px;
}

 /* 直播间*/
.live-container {
background-color: rgba(0, 0, 0, 0.5);
padding: 15px;
border-radius: 8px;
color: #f0f0f0;
font-size: 14px;
}
.status-row {
display: flex;
justify-content: space-between;
margin-bottom: 8px;
}
.status-row.topic {
font-size: 16px;
font-weight: bold;
justify-content: center;
margin-bottom: 12px;
}
.status-info strong {
color: #ffeb3b;
margin-left: 5px;
}
.separator {
border: none;
border-top: 1px solid rgba(255, 255, 255, 0.2);
margin: 12px 0;
}
.danmu-area {
overflow: hidden;
}
.danmu-track {
position: relative;
display: flex;
align-items: center;
width: max-content;
height: 32px;
margin-bottom: 6px;
animation: danmu-fly 15s linear infinite;
}
.danmu-track span {
flex-shrink: 0;
padding: 4px 12px;
margin-right: 30px;
background: rgba(0, 0, 0, 0.5);
border-radius: 15px;
font-size: 13px;
white-space: nowrap;
}
.danmu-track:nth-child(1) {
animation-duration: 20s;
animation-delay: -7s;
}
.danmu-track:nth-child(2) {
animation-duration: 24s;
animation-delay: -3s;
}
.danmu-track:nth-child(3) {
animation-duration: 17s;
animation-delay: -9s;
}
@keyframes danmu-fly {
0% {
left: 100%;
transform: translateX(0);
}
100% {
left: 0;
transform: translateX(-100%);
}
}
', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>软糯小团子 · 养崽模拟器</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2%sfamily=ZCOOL+KuaiLe&family=Noto+Sans+SC:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>
:root{
  --cocoa:#2e1522;
  --cocoa-soft:rgba(46,21,34,.12);
  --paper:#fff7ec;
  --card:rgba(255,253,247,.45);
  --card-strong:rgba(255,255,255,.55);
  --straw:#f0567e; --straw-soft:rgba(255,227,236,.45);
  --mint:#3fbf9f;  --mint-soft:rgba(226,247,240,.45);
  --lemon:#ffcf5c; --lemon-soft:rgba(255,243,214,.45);
  --sky:#57c2e8;   --sky-soft:rgba(226,245,253,.45);
  --lav:#a888e6;   --lav-soft:rgba(240,232,252,.45);
  --r-lg:28px; --r-md:18px; --r-sm:12px;
  --hard:6px 7px 0 rgba(46,21,34,.16);
  --hard-s:3px 4px 0 rgba(46,21,34,.14);
  --blur:blur(0.1px) saturate(1.1);
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  font-family:''Noto Sans SC'',''PingFang SC'',''Microsoft YaHei'',sans-serif;
  color:var(--cocoa);font-size:15.5px;line-height:1.8;overflow-x:hidden;
  background:#1a1a1a;
}
.zc{font-family:''ZCOOL KuaiLe'',''Noto Sans SC'',sans-serif;font-weight:400;letter-spacing:.5px}
button{font-family:inherit;color:inherit;cursor:pointer;border:none;background:none}
input,textarea{font-family:inherit;color:inherit}
::selection{background:var(--lemon)}

#bgImg{
  position:fixed;inset:0;z-index:-2;
  background-size:cover;background-position:center;background-repeat:no-repeat;
}
#bgLayer{position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden}
#bgLayer span{position:absolute;bottom:-8vh;animation:floatUp linear infinite;filter:saturate(.85)}
@keyframes floatUp{to{transform:translateY(-118vh) rotate(340deg)}}

.ctrl-btn{
  position:fixed;right:12px;z-index:70;
  width:52px;height:52px;border-radius:50%;
  background:rgba(255,255,255,.6);backdrop-filter:var(--blur);-webkit-backdrop-filter:var(--blur);
  border:3px solid var(--cocoa);
  box-shadow:var(--hard-s);font-size:22px;display:grid;place-items:center;
  transition:transform .18s cubic-bezier(.34,1.56,.64,1);
}
.ctrl-btn:hover{transform:scale(1.1) rotate(-6deg)}
.ctrl-btn:active{transform:scale(.9)}
#msgToggleBtn{top:12px}
#bgmBtn{top:72px}
#bgmBtn.playing{animation:musicPulse 1.6s infinite}
@keyframes musicPulse{
  0%,100%{box-shadow:0 0 0 0 rgba(240,86,126,.4),var(--hard-s)}
  50%{box-shadow:0 0 0 12px rgba(240,86,126,0),var(--hard-s)}
}

.ticker{
  position:relative;z-index:5;border-bottom:3px solid var(--cocoa);
  background:rgba(255,207,92,.55);backdrop-filter:var(--blur);-webkit-backdrop-filter:var(--blur);
  overflow:hidden;padding-right:70px;
}
.tk-track{display:flex;width:max-content;animation:marquee 34s linear infinite;padding:8px 0}
.ticker:hover .tk-track{animation-play-state:paused}
.tk-track span{font-family:''ZCOOL KuaiLe'';font-size:14.5px;white-space:nowrap;padding-right:12px;text-shadow:1px 1px 0 rgba(255,255,255,.9)}
@keyframes marquee{to{transform:translateX(-50%)}}

#sidebar{
  position:fixed;left:12px;top:50%;transform:translateY(-50%);
  z-index:60;display:grid;gap:9px;
}
.sbtn{
  position:relative;width:62px;padding:8px 4px 6px;
  border:3px solid var(--cocoa);border-radius:18px;
  background:rgba(255,253,247,.55);backdrop-filter:var(--blur);-webkit-backdrop-filter:var(--blur);
  display:grid;justify-items:center;gap:1px;box-shadow:var(--hard-s);
  transition:all .2s cubic-bezier(.34,1.56,.64,1);
}
.sbtn .si{font-size:22px;line-height:1.2}
.sbtn .sl{font-size:10px;font-weight:900;white-space:nowrap;text-shadow:0 1px 0 rgba(255,255,255,.8)}
.sbtn:hover{transform:translateX(5px)}
.sbtn.on{background:rgba(240,86,126,.88);color:#fff;transform:translateX(7px);box-shadow:5px 6px 0 rgba(46,21,34,.25)}
.sbtn.on .sl{text-shadow:none}
.sbadge{
  display:none;position:absolute;top:-7px;right:-7px;width:20px;height:20px;
  background:#ff3b5c;color:#fff;border:2px solid #fff;border-radius:50%;
  font-size:12px;font-weight:900;line-height:16px;text-align:center;
  animation:pulse 1s infinite;
}
.sbadge.show{display:block}
@keyframes pulse{50%{transform:scale(1.2)}}

.wrap{max-width:800px;margin:0 auto;padding:26px 18px 70px;position:relative;z-index:1}
.view{display:none}
.view.on{display:block;animation:viewIn .25s ease-out}
@keyframes viewIn{from{transform:translateY(10px)}to{transform:none}}

.card{
  background:var(--card);backdrop-filter:var(--blur);-webkit-backdrop-filter:var(--blur);
  border:3px solid var(--cocoa);border-radius:var(--r-lg);
  box-shadow:var(--hard),0 8px 32px rgba(46,21,34,.12);
  padding:26px 22px;margin-bottom:26px;position:relative;
}
.tape{
  position:absolute;width:98px;height:26px;top:-14px;
  background:rgba(255,207,92,.75);border:2px solid rgba(46,21,34,.3);
  transform:rotate(-4deg);
  background-image:repeating-linear-gradient(90deg,transparent 0 8px,rgba(255,255,255,.35) 8px 10px);
}
.tape.pink{background:rgba(240,86,126,.65)}
.tape.mint{background:rgba(63,191,159,.6)}

.sec-head{display:flex;align-items:center;gap:14px;margin-bottom:20px}
.sec-badge{
  flex:0 0 auto;width:52px;height:52px;border-radius:50%;
  border:3px solid var(--cocoa);display:grid;place-items:center;
  font-size:24px;background:rgba(255,207,92,.85);box-shadow:3px 4px 0 rgba(46,21,34,.2);
  transform:rotate(-5deg);
}
.sec-head h2{font-size:clamp(22px,5vw,28px);line-height:1.2;text-shadow:1px 1px 0 rgba(255,255,255,.9)}
.sec-head .no{font-size:12px;font-weight:900;color:var(--straw);letter-spacing:3px;display:block}
.sec-sub{font-size:13px;color:var(--cocoa);font-weight:600;text-shadow:0 1px 0 rgba(255,255,255,.8)}

.kicker{
  display:inline-block;font-size:13px;font-weight:900;letter-spacing:3px;
  background:rgba(63,191,159,.9);border:2.5px solid var(--cocoa);border-radius:999px;
  padding:4px 16px;box-shadow:3px 3px 0 rgba(46,21,34,.2);transform:rotate(-2deg);margin-bottom:14px;
}
h1.zc{font-size:clamp(44px,10vw,72px);line-height:1.12;text-shadow:3px 3px 0 rgba(255,255,255,.9)}
h1 .deco{display:inline-block;font-size:.55em;transform:rotate(12deg) translateY(-14px)}
.tagline{margin-top:12px;font-size:clamp(15px,3.4vw,17.5px);font-weight:700;text-shadow:1px 1px 0 rgba(255,255,255,.95)}
.tag-chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}
.tchip{
  font-size:12.5px;font-weight:800;padding:5px 14px;border:2.5px solid var(--cocoa);
  border-radius:999px;background:rgba(255,255,255,.6);box-shadow:2px 3px 0 rgba(46,21,34,.15);
  transition:transform .2s;backdrop-filter:var(--blur);
}
.tchip:hover{transform:translateY(-3px) rotate(-2deg)}
.tchip.a{background:var(--straw-soft)}.tchip.b{background:var(--mint-soft)}
.tchip.c{background:var(--lemon-soft)}.tchip.d{background:var(--sky-soft)}

.notes{display:grid;gap:14px;margin-top:28px}
.note{
  background:rgba(255,255,255,.5);backdrop-filter:var(--blur);-webkit-backdrop-filter:var(--blur);
  border:2.5px solid var(--cocoa);padding:14px 18px;
  border-radius:6px 24px 6px 24px;box-shadow:4px 5px 0 rgba(46,21,34,.12);
  font-size:14.5px;transition:transform .25s;font-weight:600;
}
.note:hover{transform:rotate(0deg) translateY(-3px)!important}
.note:nth-child(1){transform:rotate(-.8deg);background:rgba(255,243,214,.55)}
.note:nth-child(2){transform:rotate(.6deg)}
.note:nth-child(3){transform:rotate(-.5deg);background:rgba(255,227,236,.55)}
.note:nth-child(4){transform:rotate(.7deg);background:rgba(226,247,240,.55)}
.note:nth-child(5){transform:rotate(-.6deg)}
.note b{color:#d42654}

.dev-top{
  display:flex;align-items:center;justify-content:space-between;gap:10px;
  padding:10px 18px;border-bottom:3px dashed rgba(46,21,34,.22);
  font-size:12px;font-weight:700;
}
.rec{display:flex;align-items:center;gap:7px}
.rec i{width:10px;height:10px;border-radius:50%;background:#ff4d6d;animation:pulse2 1.4s infinite}
@keyframes pulse2{50%{opacity:.25;transform:scale(.8)}}
#clock{font-variant-numeric:tabular-nums;letter-spacing:1px}

.screen{
  position:relative;margin:16px 4px;border:3px solid var(--cocoa);border-radius:24px;
  background:linear-gradient(160deg,rgba(234,249,240,.35),rgba(253,241,244,.35) 55%,rgba(255,248,230,.35));
  backdrop-filter:var(--blur);-webkit-backdrop-filter:var(--blur);padding:22px 16px;
  display:flex;gap:20px;align-items:center;justify-content:center;flex-wrap:wrap;overflow:hidden;
}
.screen::before{
  content:'''';position:absolute;inset:0;pointer-events:none;
  background-image:radial-gradient(rgba(46,21,34,.05) 1.5px,transparent 1.5px);background-size:16px 16px;
}

.kiddo-wrap{text-align:center;flex:0 0 auto}
.kiddo{
  width:138px;height:142px;position:relative;cursor:pointer;
  margin:0 auto;
  animation:kiddoBreathe 3.5s ease-in-out infinite;
  transition:transform .2s cubic-bezier(.34,1.56,.64,1);
  -webkit-tap-highlight-color:transparent;
}
@keyframes kiddoBreathe{
  0%,100%{transform:scale(1) translateY(0)}
  50%{transform:scale(1.02,0.98) translateY(2px)}
}
.kiddo:hover{transform:scale(1.08) rotate(-2deg)}
.kiddo:active{transform:scale(.92)}

.k-ahoge{
  position:absolute;top:-24px;left:48px;width:24px;height:28px;
  border:3.5px solid var(--cocoa);border-color:var(--cocoa) transparent transparent transparent;
  border-radius:50%/20px 20px 0 0;z-index:4;
  transform:rotate(-18deg);transform-origin:bottom center;
  animation:ahogeSway 2.8s ease-in-out infinite alternate;
}
@keyframes ahogeSway{to{transform:rotate(15deg)}}

.k-hair{
  position:absolute;top:-6px;left:8px;right:8px;height:74px;
  background:#7c5141;border:3px solid var(--cocoa);
  border-radius:65px 65px 30px 30px;z-index:1;box-shadow:inset 0 4px 0 rgba(255,255,255,.2);
}
.k-hair::before{
  content:'''';position:absolute;top:12px;left:20px;width:30px;height:14px;
  border-radius:50%;background:rgba(255,255,255,.32);transform:rotate(-18deg);
}
.k-bow{
  position:absolute;top:-18px;right:6px;z-index:5;font-size:28px;
  transform:rotate(14deg);filter:drop-shadow(2px 2px 0 rgba(46,21,34,.25));
}
.k-face{
  position:absolute;top:18px;left:2px;right:2px;height:102px;
  background:linear-gradient(180deg,#fff1e3,#fedcb9);
  border:3px solid var(--cocoa);border-radius:50% 50% 46% 46%;z-index:2;
}
.k-eye{
  position:absolute;top:44px;width:14px;height:18px;
  background:var(--cocoa);border-radius:50%;
  animation:blink 4.6s infinite;z-index:3;
}
.k-eye::after{content:'''';position:absolute;top:2px;left:2px;width:6px;height:6px;background:#fff;border-radius:50%}
.k-eye::before{content:'''';position:absolute;bottom:2px;right:2px;width:3px;height:3px;background:rgba(255,255,255,.8);border-radius:50%}
.k-eye.l{left:32px}.k-eye.r{right:32px}
@keyframes blink{0%,92%,100%{transform:scaleY(1)}95%{transform:scaleY(.08)}}

.k-cheek{
  position:absolute;top:62px;width:22px;height:12px;
  background:#ff7895;opacity:.65;border-radius:50%;filter:blur(1px);z-index:3;
}
.k-cheek.l{left:16px}.k-cheek.r{right:16px}

.k-mouth{
  position:absolute;top:68px;left:50%;transform:translateX(-50%);
  width:16px;height:10px;border:3px solid var(--cocoa);border-top:none;
  border-radius:0 0 20px 20px;z-index:3;transition:all .25s;
}
.kiddo.happy .k-mouth{width:26px;height:16px;background:#f0567e;border-radius:0 0 16px 16px}
.kiddo.worried .k-mouth{width:10px;height:10px;border:3px solid var(--cocoa);border-radius:50%;background:#f7b7c6}
.kiddo.crying .k-mouth{width:16px;height:8px;border:3px solid var(--cocoa);border-bottom:none;border-radius:14px 14px 0 0;background:none}

.k-tear{display:none;position:absolute;top:54px;width:8px;height:12px;background:#8fd3ff;border-radius:50% 50% 60% 60%;z-index:4}
.k-tear.l{left:23px}.k-tear.r{right:23px}
.kiddo.crying .k-tear{display:block;animation:tearFall 1.1s ease-in infinite}
.kiddo.crying .k-tear.r{animation-delay:.5s}
@keyframes tearFall{0%{transform:translateY(0);opacity:0}20%{opacity:1}100%{transform:translateY(30px);opacity:0}}

.k-bib{
  position:absolute;bottom:0px;left:50%;transform:translateX(-50%);
  width:58px;height:24px;background:rgba(255,255,255,.9);border:2.5px solid var(--cocoa);
  border-radius:0 0 30px 30px;z-index:3;box-shadow:0 2px 0 rgba(46,21,34,.1);
}
.k-bib::after{content:''🍳'';position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-size:12px}
.k-hand{
  position:absolute;bottom:4px;width:15px;height:14px;
  background:#fedcb9;border:2.5px solid var(--cocoa);border-radius:50%;z-index:4;
}
.k-hand.l{left:22px;transform:rotate(-15deg)}
.k-hand.r{right:22px;transform:rotate(15deg)}
.k-hint{font-size:12px;margin-top:8px;color:var(--cocoa);font-weight:700;text-shadow:0 1px 0 rgba(255,255,255,.8)}

/* ===== 浮动对话气泡 ===== */
.speech-bubble{
  position:fixed;left:50%;bottom:100px;transform:translateX(-50%) translateY(20px) scale(.85);
  background:rgba(255,255,255,.92);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);
  border:3px solid var(--cocoa);border-radius:22px;
  padding:14px 22px;font-size:15px;font-weight:800;line-height:1.6;
  box-shadow:var(--hard),0 12px 40px rgba(46,21,34,.25);
  z-index:80;max-width:88vw;pointer-events:none;
  opacity:0;transition:all .35s cubic-bezier(.34,1.56,.64,1);
  text-align:center;
}
.speech-bubble.show{opacity:1;transform:translateX(-50%) translateY(0) scale(1)}
.speech-bubble::after{
  content:'''';position:absolute;bottom:-14px;left:50%;transform:translateX(-50%);
  border:8px solid transparent;border-top-color:var(--cocoa);
}
.speech-bubble::before{
  content:'''';position:absolute;bottom:-10px;left:50%;transform:translateX(-50%);
  border:6px solid transparent;border-top-color:rgba(255,255,255,.92);z-index:1;
}
.speech-bubble.warn{background:rgba(255,243,200,.95);border-color:#b47d00;color:#7a5200}
.speech-bubble.crit{background:rgba(255,200,210,.95);border-color:var(--straw);color:#9e1239;animation:shake .45s}
@keyframes shake{0%,100%{transform:translateX(-50%) translateY(0)}25%{transform:translateX(calc(-50% - 6px))}75%{transform:translateX(calc(-50% + 6px))}}
.speech-bubble .emo{display:inline-block;margin-right:6px;transform:translateY(-1px)}

.stats{flex:1 1 280px;min-width:250px;display:grid;gap:8px;position:relative;z-index:2}
.fav{display:flex;align-items:center;gap:8px;background:rgba(255,255,255,.55);backdrop-filter:var(--blur);border:2.5px solid var(--cocoa);border-radius:999px;padding:6px 12px;margin-bottom:4px;box-shadow:2px 3px 0 rgba(46,21,34,.1)}
.fav b{font-size:13px}
.fav .track{flex:1}
.s-row{display:grid;grid-template-columns:64px 1fr 38px;align-items:center;gap:8px}
.s-label{font-size:12.5px;font-weight:800;white-space:nowrap;text-shadow:0 1px 0 rgba(255,255,255,.8)}
.track{height:13px;background:rgba(255,255,255,.55);border:2px solid var(--cocoa);border-radius:99px;overflow:hidden}
.fill{height:100%;border-radius:99px;width:30%;transition:width .8s ease}
.s-val{font-size:12px;font-weight:900;text-align:right;font-variant-numeric:tabular-nums}
.s-row.warn .track{animation:warnPulse .8s infinite}
@keyframes warnPulse{50%{box-shadow:0 0 0 4px rgba(240,86,126,.4)}}
.fx-layer{position:absolute;inset:0;pointer-events:none;z-index:5}
.fheart{position:absolute;font-size:20px;animation:heartUp 1.1s ease-out forwards}
@keyframes heartUp{to{transform:translate(var(--dx),-130px) scale(1.3);opacity:0}}

.act-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(96px,1fr));gap:10px;margin-top:16px}
.act{
  border:3px solid var(--cocoa);border-radius:var(--r-md);
  background:rgba(255,255,255,.5);backdrop-filter:var(--blur);
  padding:12px 6px;display:grid;justify-items:center;gap:2px;
  box-shadow:var(--hard-s);transition:transform .15s;
}
.act .ae{font-size:26px}
.act b{font-size:13px}
.act:hover{transform:translateY(-3px)}
.act:active{transform:translateY(2px);box-shadow:2px 2px 0 rgba(46,21,34,.13)}
.act.bad{background:rgba(255,227,236,.45)}
.act.bad:hover{background:rgba(255,227,236,.65)}

.log{margin-top:16px;border:2.5px dashed rgba(46,21,34,.4);border-radius:var(--r-sm);padding:12px 14px;background:rgba(255,255,255,.45);backdrop-filter:var(--blur)}
.log-t{font-weight:900;font-size:14px;margin-bottom:8px}
#logList{list-style:none;display:grid;gap:6px;font-size:13px}
#logList li{border-bottom:1px dashed rgba(46,21,34,.18);padding-bottom:5px;font-weight:600}
#logList .lt{color:var(--straw);font-weight:900;margin-right:6px;font-size:11px}

.book{
  width:100%;background:var(--straw);color:#fff;border:3.5px solid var(--cocoa);
  border-radius:var(--r-md);padding:16px;font-size:19px;font-family:''ZCOOL KuaiLe'';
  box-shadow:var(--hard-s);transition:all .2s cubic-bezier(.34,1.56,.64,1);animation:wobble 3.4s ease-in-out infinite;
}
@keyframes wobble{0%,100%{transform:rotate(-.5deg)}50%{transform:rotate(.5deg)}}
.book:hover{transform:scale(1.02)}
.book:active{transform:scale(.96)}
.fold{display:grid;grid-template-rows:0fr;transition:grid-template-rows .5s cubic-bezier(.65,0,.35,1)}
.fold>.fin{overflow:hidden;min-height:0}
.fold.open{grid-template-rows:1fr}
.chips{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:18px 0 6px}
.chip{
  border:3px solid var(--cocoa);border-radius:var(--r-md);padding:14px 8px;
  font-family:''ZCOOL KuaiLe'';font-size:15px;background:rgba(255,255,255,.55);
  box-shadow:var(--hard-s);display:grid;gap:4px;justify-items:center;
  opacity:0;transform:translateY(18px) scale(.85);
  transition:opacity .4s,transform .5s cubic-bezier(.34,1.7,.5,1),background .2s;
  backdrop-filter:var(--blur);
}
.fold.open .chip{opacity:1;transform:none}
.fold.open .chip:nth-child(1){transition-delay:.08s}
.fold.open .chip:nth-child(2){transition-delay:.18s}
.fold.open .chip:nth-child(3){transition-delay:.28s}
.chip .ci{font-size:26px}
.chip.on{color:#fff}
.chip.c1.on{background:var(--mint)}.chip.c2.on{background:var(--straw)}.chip.c3.on{background:var(--sky)}
.chip:hover{transform:translateY(-3px)}
.hpanel .pin{padding:6px 2px 14px}
.panel-card{border:2.5px solid var(--cocoa);border-radius:var(--r-md);background:rgba(255,255,255,.5);backdrop-filter:var(--blur);padding:18px;box-shadow:inset 0 0 0 6px rgba(255,207,92,.12)}
.panel-card h3{font-size:18px;margin-bottom:10px}
.tip{display:flex;gap:12px;align-items:flex-start;padding:9px 0;border-bottom:2px dashed rgba(46,21,34,.15)}
.tip:last-child{border-bottom:none}
.tip .tn{flex:0 0 auto;width:30px;height:30px;border-radius:50%;background:var(--lemon);border:2.5px solid var(--cocoa);display:grid;place-items:center;font-weight:900;font-size:14px}
.fx-grid{display:grid;gap:10px;max-height:390px;overflow-y:auto;padding-right:4px}
.fx{border:2px dashed rgba(46,21,34,.4);border-radius:var(--r-sm);padding:11px 13px;background:rgba(255,255,255,.45);backdrop-filter:var(--blur)}
.fx h4{font-size:15px;display:flex;align-items:center;gap:6px}
.fx p{font-size:13px;color:var(--cocoa);line-height:1.7;font-weight:600}
.cmd{display:inline-block;font-size:11px;background:var(--straw-soft);border:1.5px dashed var(--straw);padding:1px 9px;border-radius:999px;margin-top:5px;font-weight:700;color:var(--straw)}
.def{border-left:5px solid var(--sky);background:rgba(226,245,253,.55);backdrop-filter:var(--blur);border-radius:0 var(--r-sm) var(--r-sm) 0;padding:10px 14px;margin:10px 0}
.def b{color:#0e688e}

.frm{display:grid;gap:16px;grid-template-columns:1fr}
@media(min-width:620px){.frm{grid-template-columns:1fr 1fr}}
.fld{display:grid;gap:6px}
.fld.full{grid-column:1/-1}
.fld>label{
  justify-self:start;font-size:13px;font-weight:900;padding:3px 13px;
  border:2.5px solid var(--cocoa);border-radius:999px;background:rgba(255,207,92,.85);
  box-shadow:2px 2px 0 rgba(46,21,34,.15);transform:rotate(-1deg);
}
.fld:nth-child(even)>label{background:rgba(226,247,240,.85);transform:rotate(1deg)}
.fld input[type=text],.fld textarea{
  width:100%;border:2.5px solid var(--cocoa);border-radius:var(--r-sm);
  background:var(--card-strong);backdrop-filter:var(--blur);padding:11px 14px;font-size:14.5px;outline:none;
  transition:border-color .2s,box-shadow .2s,transform .2s;font-weight:600;
}
.fld textarea{min-height:84px;resize:vertical;line-height:1.7}
.fld input:focus,.fld textarea:focus{border-color:var(--straw);box-shadow:0 0 0 4px rgba(240,86,126,.25);transform:translateY(-1px);background:rgba(255,255,255,.7)}
.candy-row{display:flex;gap:10px}
.candy{position:relative;flex:1}
.candy input{position:absolute;opacity:0;pointer-events:none}
.candy span{display:block;text-align:center;padding:9px;border:2.5px solid var(--cocoa);border-radius:999px;background:rgba(255,255,255,.55);backdrop-filter:var(--blur);font-weight:800;cursor:pointer;transition:all .2s cubic-bezier(.34,1.56,.64,1);box-shadow:2px 3px 0 rgba(46,21,34,.12)}
.candy span:hover{transform:translateY(-2px)}
.candy input:checked+span{background:var(--straw);color:#fff;transform:scale(1.04)}
.candy.m input:checked+span{background:var(--sky)}

.feat-list{display:grid;gap:12px}
.feat{
  display:flex;align-items:center;gap:12px;background:rgba(255,255,255,.5);
  border:2.5px solid var(--cocoa);border-radius:var(--r-md);padding:12px 14px;
  box-shadow:var(--hard-s);cursor:pointer;transition:transform .2s;backdrop-filter:var(--blur);
}
.feat:hover{transform:translateX(4px)}
.fnum{font-size:11px;font-weight:900;color:rgba(46,21,34,.5);flex:0 0 auto}
.fico{flex:0 0 auto;width:44px;height:44px;border-radius:14px;display:grid;place-items:center;font-size:21px;background:var(--soft,rgba(255,243,214,.65));border:2px solid rgba(46,21,34,.25)}
.ftxt{flex:1;min-width:0}
.ftxt b{font-size:15px}
.ftxt small{display:block;font-size:12px;color:var(--cocoa);line-height:1.55;font-weight:600}
.sw{position:relative;flex:0 0 auto;width:56px;height:31px}
.sw input{position:absolute;inset:0;opacity:0;cursor:pointer;z-index:2;margin:0}
.knob{position:absolute;inset:0;border:2.5px solid var(--cocoa);border-radius:99px;background:rgba(243,228,232,.75);transition:background .25s}
.knob::after{content:'''';position:absolute;top:2px;left:3px;width:21px;height:21px;border-radius:50%;background:#fff;border:2.5px solid var(--cocoa);transition:transform .3s cubic-bezier(.5,-.4,.4,1.6)}
.sw input:checked~.knob{background:var(--mint)}
.sw input:checked~.knob::after{transform:translateX(24px);background:var(--lemon)}
.seg-block{margin-top:18px;display:grid;gap:16px}
.seg-block .s-title{font-weight:900;font-size:15px}
.seg{display:flex;border:2.5px solid var(--cocoa);border-radius:999px;overflow:hidden;background:rgba(255,255,255,.55);backdrop-filter:var(--blur);box-shadow:3px 3px 0 rgba(46,21,34,.12)}
.seg button{flex:1;padding:11px 6px;font-weight:800;font-size:14px;transition:all .2s;border-right:2.5px solid var(--cocoa)}
.seg button:last-child{border-right:none}
.seg button:hover{background:var(--straw-soft)}
.seg button.on{background:var(--lemon)}
.feat-note{font-size:12.5px;color:var(--cocoa);margin-top:14px;text-align:center;font-weight:700}

.count-chip{font-size:12.5px;font-weight:900;background:var(--straw);color:#fff;border:2.5px solid var(--cocoa);border-radius:999px;padding:3px 13px;box-shadow:2px 2px 0 rgba(46,21,34,.2);transform:rotate(1.5deg)}
#reportEl{
  white-space:pre-wrap;background:rgba(255,253,246,.5);border:2.5px solid var(--cocoa);
  border-radius:var(--r-sm);padding:18px;font-size:13.5px;line-height:2;max-height:430px;overflow-y:auto;
  background-image:repeating-linear-gradient(rgba(255,253,246,.5) 0 31px,rgba(87,194,232,.2) 31px 32px);
  backdrop-filter:var(--blur);-webkit-backdrop-filter:var(--blur);font-weight:600;
}
.copy-btn{
  width:100%;margin-top:16px;background:var(--straw);color:#fff;
  border:3.5px solid var(--cocoa);border-radius:var(--r-md);padding:15px;
  font-size:19px;font-family:''ZCOOL KuaiLe'';box-shadow:var(--hard-s);transition:all .15s;
}
.copy-btn:hover{transform:translateY(-2px)}
.copy-btn:active{transform:translateY(3px)}
.copy-btn.done{background:var(--mint)}
.open-hint{font-size:13px;color:var(--cocoa);margin-top:8px;font-weight:700}
#opening{min-height:150px}

footer{text-align:center;padding:26px 0 8px;font-size:13px;color:var(--cocoa);text-shadow:1px 1px 0 rgba(255,255,255,.9);font-weight:800}
footer .fh{font-size:18px;letter-spacing:8px}
#toast{
  position:fixed;left:50%;bottom:26px;transform:translateX(-50%) translateY(80px);
  background:rgba(46,21,34,.92);color:#fff;padding:11px 26px;border-radius:999px;
  font-weight:800;font-size:14px;z-index:99;opacity:0;transition:all .35s cubic-bezier(.34,1.56,.64,1);
  box-shadow:0 8px 24px rgba(46,21,34,.35);pointer-events:none;white-space:nowrap;max-width:92vw;
  backdrop-filter:blur(8px);
}
#toast.show{opacity:1;transform:translateX(-50%) translateY(0)}

::-webkit-scrollbar{width:9px;height:9px}
::-webkit-scrollbar-track{background:var(--straw-soft);border-radius:9px}
::-webkit-scrollbar-thumb{background:var(--straw);border-radius:9px;border:2px solid var(--straw-soft)}

@media(max-width:720px){
  body{padding-bottom:88px}
  .wrap{padding:20px 12px 30px}
  #sidebar{
    left:0;right:0;top:auto;bottom:0;transform:none;
    display:flex;gap:6px;padding:8px 8px calc(8px + env(safe-area-inset-bottom));
