    emo:''😢'',snd:''spank'',bad:true,
    reaction:[''呜哇哇——好疼！屁屁好疼！'',''呜呜呜……为什么要打我……好委屈……'',''被打屁屁了……不喜欢……好伤心……'',''呜呜……我做错什么了吗……好难过……'']
  }
};
function spawnInScreen(emoji,n=5){
  const rect=$(''screen'').getBoundingClientRect();
  for(let i=0;i<n;i++){
    const h=document.createElement(''span'');h.className=''fheart'';h.textContent=emoji;
    h.style.left=(rect.width*.3+Math.random()*rect.width*.4)+''px'';
    h.style.top=(rect.height*.45+Math.random()*rect.height*.3)+''px'';
    h.style.setProperty(''--dx'',(Math.random()*90-45)+''px'');
    h.style.animationDelay=(i*.06)+''s'';
    $(''fxLayer'').appendChild(h);setTimeout(()=>h.remove(),1400);
  }
}
document.querySelectorAll(''.act'').forEach(b=>{
  b.addEventListener(''click'',()=>{
    const a=ACTS[b.dataset.act];
    const obj={};NEEDS.forEach(s=>obj[s.k]=s.v);
    a.fx(obj);NEEDS.forEach(s=>s.v=obj[s.k]);
    if(b.dataset.act===''pat'') {
      // already added in fx
    } else if(b.dataset.act===''spank'') {
      // already reduced in fx
    } else {
      fav=Math.min(100,fav+1);
    }
    log(a.msg);
    // 显示崽崽的反应语音气泡
    const reaction=a.reaction[Math.floor(Math.random()*a.reaction.length)];
    const reactEmo=a.bad%s''😢'':(a.emo||''💬'');
    showSpeech(reaction, a.bad%s''warn'':''normal'', reactEmo, 3200);
    
    if(a.bad){
      SFX[a.snd]%sSFX[a.snd]():SFX.spank();
      spawnInScreen(''💔'',4);
    } else {
      SFX[a.snd]%sSFX[a.snd]():SFX.pop();
      spawnInScreen(a.emo);
    }
    
    const k=$(''kiddo'');
    if(a.bad){
      k.classList.add(''crying'');
      k.classList.remove(''happy'',''worried'');
      clearTimeout(k._t);
      k._t=setTimeout(()=>{k.classList.remove(''crying'');renderBaby();},3500);
      SFX.sad();
    } else {
      k.classList.add(''happy'');k.classList.remove(''crying'',''worried'');
      clearTimeout(k._t);k._t=setTimeout(()=>k.classList.remove(''happy''),1500);
    }
    renderBaby();
  });
});
$(''kiddo'').addEventListener(''click'',e=>{
  const k=$(''kiddo'');k.classList.add(''happy'');k.classList.remove(''worried'',''crying'');
  clearTimeout(k._t);k._t=setTimeout(()=>k.classList.remove(''happy''),1300);
  fav=Math.min(100,fav+1);
  SFX.giggle();
  const reactMsg=[''嘿嘿～戳戳好痒！'',''咿呀～喜欢你！'',''再戳再戳～好开心！'',''咯咯咯～好痒痒！''][Math.floor(Math.random()*4)];
  showSpeech(reactMsg,''normal'',''💗'');
  const rect=$(''screen'').getBoundingClientRect();
  const x=e.clientX-rect.left,y=e.clientY-rect.top;
  for(let i=0;i<6;i++){
    const h=document.createElement(''span'');h.className=''fheart'';
    h.textContent=[''💗'',''💖'',''✨'',''🌟''][i%4];
    h.style.left=(x-8)+''px'';h.style.top=(y-8)+''px'';
    h.style.setProperty(''--dx'',(Math.random()*90-45)+''px'');
    h.style.animationDelay=(i*.06)+''s'';
    $(''fxLayer'').appendChild(h);setTimeout(()=>h.remove(),1400);
  }
  renderBaby();
});

$(''bookBtn'').addEventListener(''click'',()=>{
  const body=$(''bookBody''),open=body.classList.toggle(''open'');
  $(''bookBtn'').textContent=open%s''📕 合上养成手册'':''📖 打开养成手册'';
  open%sSFX.open():SFX.close();
});
document.querySelectorAll(''.chip'').forEach(chip=>{
  chip.addEventListener(''click'',()=>{
    const target=$(chip.dataset.p),willOpen=!target.classList.contains(''open'');
    document.querySelectorAll(''.hpanel'').forEach(p=>p.classList.remove(''open''));
    document.querySelectorAll(''.chip'').forEach(c=>c.classList.remove(''on''));
    if(willOpen){target.classList.add(''open'');chip.classList.add(''on'');SFX.open();}
    else SFX.close();
  });
});
(function(){
  const all=[
    ...FEATS.slice(0,3),
    {name:''人称视角'',icon:''👁️'',desc:''改变 AI 描写时对用户的代称：第一人称「我」/ 第二人称「你」/ 第三人称「TA / 姓名」。'',cmd:''改成第一人称 / 改成第二人称 / 改成第三人称''},
    FEATS[3],FEATS[4],FEATS[5],FEATS[6],
    {name:''回复长度'',icon:''✍️'',desc:''影响 AI 输出字数：简短（500字以下）/ 中等（700~1200字）/ 冗长（1500字以上）。'',cmd:''回复长度简短 / 中等 / 冗长''},
    FEATS[7],FEATS[8]
  ];
  $(''fxGrid'').innerHTML=all.map(f=>`<div class="fx"><h4>${f.icon} ${f.name}</h4><p>效果：${f.desc}</p><span class="cmd">指令：${f.cmd}</span></div>`).join('''');
})();

(function(){
  $(''featList'').innerHTML=FEATS.map((f,i)=>`
    <label class="feat" style="--soft:${SOFT[i%SOFT.length]}">
      <span class="fnum">${String(i+1).padStart(2,''0'')}</span>
      <span class="fico">${f.icon}</span>
      <span class="ftxt"><b>${f.name}</b><small>${f.desc}</small><span class="cmd">指令：${f.cmd}</span></span>
      <span class="sw"><input type="checkbox" data-key="${f.key}" ${f.def%s''checked'':''''}><span class="knob"></span></span>
    </label>`).join('''');
  document.querySelectorAll(''#featList input[type=checkbox]'').forEach(cb=>{
    cb.addEventListener(''change'',()=>{cb.checked%sSFX.on():SFX.off();update();});
  });
})();
document.querySelectorAll(''.seg'').forEach(seg=>{
  seg.addEventListener(''click'',e=>{
    const b=e.target.closest(''button[data-val]'');if(!b)return;
    seg.querySelectorAll(''button'').forEach(x=>x.classList.remove(''on''));
    b.classList.add(''on'');state[seg.dataset.key]=b.dataset.val;
    SFX.pop();update();
  });
});

function gender(p){return $(p+''_g_f'').checked%s''女'':($(p+''_g_m'').checked%s''男'':'''')}
function buildReport(){
  const L=[];
  L.push('''');L.push(''【用户档案】'');
  let any=false;
  [[''姓名'',v(''u_name'')],[''性别'',gender(''u'')],[''外貌'',v(''u_look'')],[''年龄'',v(''u_age'')],[''身份'',v(''u_role'')],[''性格'',v(''u_persona'')],[''背景'',v(''u_bg'')]]
    .forEach(([k,val])=>{if(val){L.push(k+''：''+val);any=true;}});
  if(!any)L.push(''（尚未填写）'');
  
  L.push('''');L.push(''【其他角色档案】'');
  any=false;
  [[''姓名'',v(''p_name'')],[''性别'',gender(''p'')],[''外貌'',v(''p_look'')],[''年龄'',v(''p_age'')],[''身份'',v(''p_role'')],[''性格'',v(''p_persona'')],[''背景'',v(''p_bg'')]]
    .forEach(([k,val])=>{if(val){L.push(k+''：''+val);any=true;}});
  if(!any)L.push(''（尚未填写）'');
  
  L.push('''');L.push(''【崽崽档案】'');
  any=false;
  [[''姓名'',v(''k_name'')],[''性别'',gender(''k'')],[''年龄'',v(''k_age'')],[''身份'',v(''k_role'')],[''身高'',v(''k_height'')],[''体重'',v(''k_weight'')],[''性格'',v(''k_persona'')],[''能力'',v(''k_skill'')],[''外貌'',v(''k_look'')],[''语言风格'',v(''k_talk'')],[''行为习惯'',v(''k_habit'')],[''与用户的关系'',v(''k_rel'')]]
    .forEach(([k,val])=>{if(val){L.push(k+''：''+val);any=true;}});
  if(!any)L.push(''（尚未填写）'');
  L.push('''');L.push(''【功能状态】'');
  FEATS.forEach(f=>L.push(`${f.name}：${document.querySelector(`input[data-key=${f.key}]`).checked%s''开启'':''关闭''}`));
  L.splice(L.length-6,0,`人称视角：${state.pov}`);
  L.splice(L.length-2,0,`回复长度：${state.len}`);
  L.push('''');L.push(''【开场白】'');
  L.push(v(''opening'')||''（尚未填写）'');
  return L.join(''\n'');
}
function update(){
  $(''reportEl'').textContent=buildReport();
  const ids=[''u_name'',''u_age'',''u_look'',''u_role'',''u_persona'',''u_bg'',''p_name'',''p_age'',''p_look'',''p_role'',''p_persona'',''p_bg'',''k_name'',''k_age'',''k_role'',''k_rel'',''k_height'',''k_weight'',''k_persona'',''k_skill'',''k_look'',''k_talk'',''k_habit''];
  let n=ids.filter(id=>v(id)).length;
  if(gender(''u''))n++;if(gender(''p''))n++;if(gender(''k''))n++;
  $(''doneCount'').textContent=`已填写 ${n} / 26`;
}
document.addEventListener(''input'',e=>{
  if(e.target.matches(''input[type=text],textarea'')){SFX.type();update();}
});
document.addEventListener(''change'',e=>{
  if(e.target.matches(''input[type=radio]'')){SFX.pop();update();}
});
document.addEventListener(''focusin'',e=>{
  if(e.target.matches(''.fld input,.fld textarea''))SFX.click();
});

async function copyText(text){
  try{await navigator.clipboard.writeText(text);return true;}
  catch(err){
    const ta=document.createElement(''textarea'');
    ta.value=text;ta.setAttribute(''readonly'','''');
    ta.style.cssText=''position:fixed;left:-9999px;top:0;opacity:0'';
    document.body.appendChild(ta);ta.select();ta.setSelectionRange(0,ta.value.length);
    let ok=false;try{ok=document.execCommand(''copy'');}catch(e2){}
    ta.remove();return ok;
  }
}
$(''copyBtn'').addEventListener(''click'',async()=>{
  const ok=await copyText($(''reportEl'').textContent);
  const btn=$(''copyBtn'');
  if(ok){
    SFX.good();toast(''✅ 已复制到剪贴板，去粘贴吧！'');
    btn.classList.add(''done'');btn.textContent=''✅ 复制成功！'';
    setTimeout(()=>{btn.classList.remove(''done'');btn.textContent=''📋 一键复制配置单'';},1800);
  }else{SFX.close();toast(''😥 复制失败，请长按文本手动复制'');}
});

update();
</script>
</body>
</html>', '都市日常', '2026-10-01 00:36:07', '2026-10-01 00:36:07', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('265891f0-ca5b-48f7-8fb3-7063f28a6f65', '🩵妈妈🩵【全服装立绘】', '全服装立绘', '🩵', '🩵妈妈🩵【全服装立绘】', '40+写实服装换装·28天经期系统', '🩵', '#06b6d4', 'linear-gradient(135deg, #06b6d4 0%, #3b82f6 100%)', '{"title": "🩵妈妈🩵【全服装立绘】", "desc": "唐懿，38岁，温婉成熟的绝美母亲，拥有曼妙端庄的身段与深藏不露的温存。游戏内置40+套全场景服装立绘系统与28天生理期节律追踪。", "bg_image": "https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAERjGlprgngJjV1z-X", "opening_options": ["【放学到家】：推开门闻到饭菜香，她系着围裙头也没回地轻声唤你洗手吃饭", "【周末早晨】：无意撞见她在客厅穿紧身瑜伽裤趴在垫子上做晨间拉伸", "【深夜撞见】：浴室水声初歇，她裹着白浴巾擦着微湿的黑发走出来", "【睡不着的夜】：凌晨两点她穿着丝绸吊带睡裙窝在昏暗沙发上刷手机", "【说到做到】：因为你期末考进前三，她愿赌服输穿着你挑的cos服走出来"]}', '[{"name": "我 (儿子)", "role": "故事主角 / 玩家", "desc": "家中独子，正值青春荷尔蒙萌动期，与温柔端庄的母亲唐懿同住一个屋檐下。"}, {"name": "唐懿 (妈妈)", "role": "核心女主 / 熟韵温柔母亲", "desc": "38岁，兼具优雅知性与成熟肉体魅力的母亲，对儿子关怀备至，随着同居日常的推移逐步展露羞涩与深层情感。"}]', '[{"title": "温馨居家日常", "desc": "采光通透的现代公寓，带有生活气息的玄关、厨房、客厅沙发与散发淡淡香气的浴室。"}]', '{"dialogue_style": "包含40+套写实服装动态切换、28天生理节律推算与实时双轨心理状态的Galgame物语", "format": "内置fz-xxxx全套服装类名，支持k-sum折叠状态栏与role角色对话着色"}', '[{"index": 1, "isUser": false, "scene": "温馨公寓玄关与厨房", "story": "<tl>⏰时间：傍晚 18:30 | 🏡地点：家中玄关与饭厅 | 气氛：温暖温馨</tl>\n\n钥匙插进锁孔轻轻转动，“咔哒”一声，防盗门被推开。\n\n玄关处飘散着浓郁醇厚的排骨冬瓜汤香气，暖黄色的顶灯柔和地洒在原木地板上，将一整天的疲惫悄然驱散。\n\n厨房里传来抽油烟机微弱的嗡鸣与锅铲碰撞的清脆声响。一位身姿曼妙曼丽的成熟女子正站在灶台前，身上穿着一件修身居家的针织体恤，外系一袭天蓝色的围裙，恰到好处地收束出纤细柔软的腰肢与饱满圆润的臀线。几缕微卷的青丝散落在白皙细嫩的后颈旁，随着她翻炒的动作轻轻摇曳。\n\n<p class=\"role-jiejie\">“嗯？回来了吗？今天学校功课多不多？”</p>\n\n听到门响，唐懿微微侧过柔美的脸庞，温婉的眸子在你脸上轻轻打量了一眼，嘴角泛起一抹让人安心的浅笑：\n\n<p class=\"role-jiejie\">“先去把书包放下，洗洗手准备吃饭。锅里焖着你最喜欢的红烧排骨，马上就能出锅了。”</p>\n\n<thk>（这孩子最近长个子真快……眼神总往我身上瞟，今天出门前换围裙是不是太显身段了？……算了，多给他补补营养才是正事。）</thk>\n\n她轻轻转回身去盛汤，围裙布料被紧绷的曲线微微撑起，在暖光下勾勒出成熟女性独有的柔美温存。\n\n<details>\n<summary class=\"k-sum\">✨【角色状态栏】</summary>\n<div class=\"k-box\">◆信息状态栏◆\n🌏【世界】：现代都市 / 21世纪\n⏰【时间】：2026/09/30/周三/秋季/晴朗/18:30\n🏕️【地点】：中国/沿海城市/静安区/温馨公寓\n🏡【场景】：玄关与饭厅/饭菜飘香/温暖居家氛围\n◆主互动角色状态栏◆\n<div class=\"k-img\">\n<div class=\"fz-aprn\"></div>\n</div>\n👤【角色】：唐懿 / 女 / 38岁\n🎭【身份】：母亲 / 企业财务主管\n💰【资金】：今日日常买菜开销 ¥128 / 家庭活期储蓄 ¥450,000\n🫂【关系】：温柔宠溺 / 好感度 35% / 无变动\n🌹【外貌】：黑发微卷低马尾 / 浅棕温婉美眸 / 丰腴成熟曲线 / 皮肤白皙细腻\n👗【服装】：棕色长袖体恤搭配天蓝色围裙、黑色长裙（家务装）\n🧍‍♀️【姿势】：手持汤勺站在灶台前微微回眸浅笑\n💬【内心】：看到儿子平安放学心头微松，希望他多吃两碗排骨\n🤍【健康】：体温 36.5℃ / 精力充沛 / 周期第8天·卵泡期正常\n🔞【身体】：未进入特殊剧情\n◆我的状态栏◆\n👤【我】：儿子 / 18岁 / 高中毕业生\n🍌【身材】：180cm / 匀称健康 / 暂无反应\n✍️【设定】：容貌清秀 / 略带少年荷尔蒙躁动\n💰【物品】：学生书包、钥匙串、零花钱 ¥85\n</div>\n</details>\n\n<opt>\n<suggested_questions>\n[\"乖巧应答，把书包放到沙发并进厨房从身后帮妈妈系紧松开的围裙带子\", \"从玄关换鞋走过去，从背后探头看看锅里好吃的，顺势夸赞妈妈今天真香真美\", \"走到洗手台洗干净手，主动拿碗筷摆桌，询问妈妈今天上班累不累\", \"略显迟疑地站在厨房门口，目光忍不住落在妈妈被围裙勾勒出的丰腴腰臀曲线上\"]\n</suggested_questions>\n</opt>"}]', '    .role-player {
      color: #00bfff; /* 天蓝色 — 玩家用户 */
    }
    .role-jiejie {
      color: #ff1f1f; /* 亮红色 — 女主角 */
    }
    .role-other-male {
      color: #8b4513; /* 棕色 — 其他男性 */
    }
    .role-other-female {
      color: #fa8072; /* 浅红色 — 其他女性 */
    }

/* 开始信息栏 */
.x{border:2px solid #808080;padding:8px 10px;border-radius:6px;background:rgba(128,128,128,0.05);font-size:0.9em;color:#333;line-height:1.4}.x div{margin:2px 0;display:flex;align-items:center}

/* 状态栏 */
@keyframes k-fade{from{opacity:0;transform:translateY(-5px)}to{opacity:1;transform:translateY(0)}}
.k-sum{background:linear-gradient(145deg,#808080,#696969);color:#fff;padding:6px 12px;border-radius:4px;cursor:pointer;font-size:12px;display:inline-block;margin-top:5px;transition:all 0.3s ease;box-shadow:2px 2px 5px rgba(0,0,0,0.1);user-select:none}
.k-sum:hover{background:linear-gradient(145deg,#909090,#757575);transform:scale(1.02);box-shadow:3px 3px 8px rgba(0,0,0,0.15)}
.k-box{background:#dcdcdc;border-radius:6px;padding:10px;margin-top:8px;font-size:14px;text-align:left;white-space:pre-wrap;line-height:1.6;box-shadow:inset 0 0 10px rgba(0,0,0,0.05);border:1px solid rgba(255,255,255,0.3)}
details[open] .k-box{animation:k-fade 0.4s cubic-bezier(0.4,0,0.2,1)}
.k-img{margin:8px 0;text-align:left;white-space:normal;position:relative}
/* 新增：红色警示标题样式 */
.k-red{color:#8B0000;font-weight:bold;cursor:pointer;margin-top:5px;display:inline-block}
/* 新增：普通子标题样式 */
.k-sub{cursor:pointer;opacity:0.8;font-size:0.9em;margin-top:5px;display:inline-block}



/* ================= 通用样式 (防干扰版) ================= */
