/* ===== 公共 ===== */
World,secret{display:none!important}
wc p,wm p,py p,wf p{display:contents!important}
wc>br,wm br,py br,wl br,wl>i>br,pl br,po>br,mg>br,wf>br,wf>p::before,wf>p::after,wlist br,wtop br,wi>br{display:none!important}
ua span br,ub span br,po span br,it br{display:inline!important}
/* 👇 修复这里：把 wf 加上去了，让它拥有固定的手机外框！ */
wm,wc,py,wf{width:270px;height:450px;background:#fff;font-family:-apple-system,BlinkMacSystemFont,"Helvetica Neue","PingFang SC","Microsoft YaHei",Arial,sans-serif;border-radius:8px;border:.7px solid #bdbdbd;box-shadow:0 7px 22px rgba(0,0,0,.13);position:relative;margin:30px auto;overflow:hidden;display:block;color:#111;-webkit-font-smoothing:antialiased}

/* ===== 1 主页 wm ===== */
wh{display:flex;align-items:center;justify-content:center;position:absolute;top:0;left:0;width:100%;height:44px;background:#ededed;z-index:10;border-bottom:.5px solid #d8d8d8;font-size:15px;font-weight:400;color:#111;box-sizing:border-box}
wh::before{content:''🔍'';position:absolute;right:40px;top:0;width:22px;height:44px;line-height:44px;text-align:center;font-size:14px}
wh::after{content:none!important}
wl{display:block;position:absolute;top:44px;bottom:52px;width:100%;overflow-y:auto;background:#fff}
wl::-webkit-scrollbar{display:none}
wl>i{display:block;position:relative;height:62px;padding:37px 42px 0 54px;box-sizing:border-box;border-bottom:.5px solid #ededed;font-style:normal;font-size:10.5px;color:#999;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;background:#fff}
wl>i::before{content:attr(a);position:absolute;left:11px;top:9px;width:38px;height:38px;border-radius:5px;background-color:#7890aa;color:#fff;font-size:14px;font-weight:400;display:flex;align-items:center;justify-content:center;overflow:hidden;box-sizing:border-box}
wl>i:nth-child(2n):before{background-color:#07c160}
wl>i:nth-child(3n):before{background-color:#6688a8}
wl>i:nth-child(4n):before{background-color:#d48b68}
wl>i:nth-child(5n):before{background-color:#8c78a6}
wl>i:nth-child(6n):before{background-color:#5d9999}
wl>i::after{content:attr(n);position:absolute;left:54px;top:12px;font-size:13px;color:#171717;font-weight:400;line-height:1}
wl>i b{position:absolute;right:11px;top:12px;font-weight:400;font-size:9.5px;color:#aaa;line-height:1}
wl>i.gp1::before{content:''👥'';background-color:#e9e9e9;color:#555;font-size:18px}
wm::before{content:''➕'';position:absolute;z-index:20;right:8px;top:0;width:26px;height:44px;line-height:44px;text-align:center;font-size:15px}
wm::after{content:none!important}
wn{display:flex;position:absolute;bottom:0;left:0;width:100%;height:52px;background:#f7f7f7;border-top:.5px solid #dcdcdc;z-index:10}
wn s{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:8.5px;color:#181818;font-weight:400;text-decoration:none;gap:2px;line-height:1}
wn s.on1{color:#07c160}
wn s::before{content:'''';display:block;font-size:16px;line-height:1}
wn s:nth-child(1)::before{content:''💬''}
wn s.on1:nth-child(1)::before{content:''💚''}
wn s:nth-child(2)::before{content:''👤''}
wn s:nth-child(3)::before{content:''🧭''}
wn s:nth-child(4)::before{content:''🙂''}

/* ===== 2 聊天 wc ===== */
cn{display:flex;align-items:center;justify-content:center;position:absolute;top:0;left:0;width:100%;height:44px;background:#ededed;z-index:10;border-bottom:.5px solid #d8d8d8;font-size:14px;font-weight:400;color:#111;box-sizing:border-box}
cn::before{content:''‹'';position:absolute;left:10px;top:0;width:22px;height:44px;font-size:28px;line-height:42px;color:#111}
cn::after{content:''⋯'';position:absolute;right:10px;top:0;height:44px;font-size:18px;color:#111;line-height:42px}
mg{display:block;position:absolute;top:44px;bottom:46px;left:0;width:100%;overflow-y:auto;background:#ededed;padding:10px 0 15px;box-sizing:border-box}
mg::-webkit-scrollbar{display:none}
sy{display:block;width:max-content;max-width:80%;text-align:center;font-size:8.5px;color:#888;background:#dcdcdc;border-radius:3px;padding:3px 5px;margin:8px auto 14px;line-height:1}
ua,ub{display:block;position:relative;margin:0 9px 16px;min-height:34px;box-sizing:border-box}
ua{padding-left:42px;text-align:left}
ub{padding-right:42px;text-align:right}
ua::before,ub::before{content:attr(data-a);position:absolute;top:0;width:34px;height:34px;border-radius:4px;display:flex;align-items:center;justify-content:center;font-size:13px;color:#fff;overflow:hidden;box-sizing:border-box}
ua::before{left:0;background:#879bb2}
ub::before{right:0;background:#69b957}
ua::after,ub::after{content:attr(data-n);position:absolute;top:0;font-size:8px;color:#999;line-height:1;white-space:nowrap;max-width:110px;overflow:hidden;text-overflow:ellipsis}
ua::after{left:42px}
ub::after{right:42px;text-align:right}
ua span,ub span{display:inline-block;width:fit-content;max-width:72%;font-size:12px;padding:8px 10px;border-radius:4px;line-height:1.42;word-break:break-word;position:relative;text-align:left;box-sizing:border-box;vertical-align:top;margin-top:12px}
ua span{background:#fff;color:#222;border:.5px solid #e5e5e5}
ub span{background:#95ec69;color:#222}
ua span::before,ub span::before{content:'''';position:absolute;top:10px;border-top:5px solid transparent;border-bottom:5px solid transparent}
ua span::before{left:-5px;border-right:5px solid #fff}
ub span::before{right:-5px;border-left:5px solid #95ec69}
ua span:has(div[class]),ub span:has(div[class]){padding:0;background:transparent;border:0;max-width:73%}
ua span:has(div[class])::before,ub span:has(div[class])::before{display:none}
ua span div[class],ub span div[class]{display:flex;align-items:center;justify-content:center;width:132px;height:132px;border-radius:2px;background:#f3f3f3;overflow:hidden;font-size:56px;line-height:1}
ua span.hb,ub span.hb,ua span.zz,ub span.zz{background:#fa9d3b;color:#fff;min-width:158px;max-width:190px;min-height:64px;padding:12px 8px 22px 42px;font-size:12px;line-height:1.35;border:0}
ua span.hb::before,ub span.hb::before,ua span.zz::before,ub span.zz::before{content:''🧧'';left:4px;top:8px;width:34px;height:34px;border:0;font-size:28px;line-height:34px;text-align:center}
ua span.zz::before,ub span.zz::before{content:''💸''}
ua span.hb::after,ub span.hb::after,ua span.zz::after,ub span.zz::after{content:''微信红包'';display:block;position:absolute;bottom:0;left:0;width:100%;height:18px;box-sizing:border-box;padding:3px 8px;font-size:8px;color:rgba(255,255,255,.8);background:rgba(0,0,0,.08);border-radius:0 0 4px 4px;text-align:left}
ua span.zz::after,ub span.zz::after{content:''微信转账''}
wb{position:absolute;bottom:0;left:0;width:100%;height:46px;background:#f7f7f7;border-top:.5px solid #d7d7d7;z-index:15;box-sizing:border-box}
wb::before{content:''🎤'';position:absolute;left:6px;top:0;width:24px;height:46px;line-height:46px;text-align:center;font-size:15px;z-index:2;pointer-events:none}
wb::after{content:''😊➕'';position:absolute;right:6px;top:0;width:52px;height:46px;line-height:46px;text-align:right;font-size:15px;letter-spacing:4px;z-index:2;pointer-events:none}
wb input{position:absolute;left:32px;width:calc(100% - 90px);top:8px;height:30px;margin:0;padding:0 8px;border:.5px solid #ddd;border-radius:4px;background:#fff;outline:none;box-sizing:border-box;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;font-size:12px;color:#222;z-index:1}
wc::after{display:none!important}

/* ====== 4. 微信朋友圈 (蓝天白云户外版) ====== */
wf{overflow-y:auto}
wf::-webkit-scrollbar{display:none}
wtop{display:block;position:relative;height:170px;background:#fff;margin-bottom:15px}

