#chat-ui-bot-login-v30 .title{padding:30px 10px 10px 10px;text-align:center;position:relative;}
#chat-ui-bot-login-v30 .title h2{margin:0;font-weight:900;font-size:1.8rem;letter-spacing:2px;color:#1a237e;text-shadow:0 0 10px rgba(255,255,255,0.8);}
#chat-ui-bot-login-v30 .title .subtitle{margin-top:5px;font-size:1em;font-weight:bold;color:#fff;letter-spacing:1px;text-shadow:0 1px 3px rgba(0,0,0,0.9),0 0 8px rgba(0,0,0,0.5);}
#chat-ui-bot-login-v30 .corner-btn{position:absolute;font-size:26px;cursor:pointer;z-index:100;animation:cornerFloat 2.5s ease-in-out infinite;filter:drop-shadow(0 0 5px #fff);color:#1a237e;top:15px;}
#chat-ui-bot-login-v30 .corner-btn.left{left:15px;}
#chat-ui-bot-login-v30 .spacer{flex:1;}
#chat-ui-bot-login-v30 .input-area{background:rgba(255,255,255,0.4);padding:15px;margin-top:auto;border-radius:4px;border:1px solid rgba(255,255,255,0.6);backdrop-filter:blur(8px);}
#chat-ui-bot-login-v30 .input-box,#chat-ui-bot-login-v30 .textarea-box{width:90%;padding:10px 12px;border-radius:2px;font-size:14px;outline:none;transition:0.3s;color:#000;margin:0 auto 10px auto;display:block;box-sizing:border-box;border:1px solid rgba(26,35,126,0.2);background:rgba(255,255,255,0.7);}
#chat-ui-bot-login-v30 .input-box:focus,#chat-ui-bot-login-v30 .textarea-box:focus{border-color:#1a237e;background:rgba(255,255,255,0.95);}
#chat-ui-bot-login-v30 .input-box.error-border{border:2px solid #c62828;background:rgba(255,230,230,0.8);}
#chat-ui-bot-login-v30 .error-hint{color:#c62828;font-size:11px;text-align:center;margin:-5px auto 8px auto;display:none;font-weight:bold;}
#chat-ui-bot-login-v30 .button{width:90%;padding:12px 0;border-radius:2px;font-size:16px;font-weight:bold;cursor:pointer;transition:0.3s;margin:0 auto;display:block;border:1px solid #1a237e;background:rgba(26,35,126,0.8);color:#fff;letter-spacing:2px;}
#chat-ui-bot-login-v30 .button:hover{background:#0d47a1;box-shadow:0 0 15px rgba(26,35,126,0.3);}
#chat-ui-bot-login-v30 .details-box{padding:12px;border-top:1px solid #263238;font-size:11px;color:#90a4ae;background:#101010;text-align:center;}
/* 左侧开局面板——改为双列图�的格式 */
#chat-ui-bot-login-v30 .opening-overlay{position:absolute;top:0;left:0;width:100%;height:100%;background:#f0f4f8;z-index:200;transform:translateX(-100%);transition:transform 0.5s cubic-bezier(0.4,0,0.2,1);display:flex;flex-direction:column;}
#chat-ui-bot-login-v30 .opening-overlay.active{transform:translateX(0);}
#chat-ui-bot-login-v30 .panel-header{padding:18px;background:#fff;border-bottom:1px solid #d1d9e0;display:flex;align-items:center;justify-content:space-between;}
#chat-ui-bot-login-v30 .small-btn{padding:6px 15px;border:1px solid #1a237e;background:#fff;color:#1a237e;font-size:12px;cursor:pointer;font-weight:bold;}
#chat-ui-bot-login-v30 .opening-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:15px;overflow-y:auto;flex:1;}
#chat-ui-bot-login-v30 .opening-grid::-webkit-scrollbar{width:4px;}
#chat-ui-bot-login-v30 .opening-grid::-webkit-scrollbar-thumb{background:#1a237e;}
#chat-ui-bot-login-v30 .opening-item{display:flex;flex-direction:column;align-items:center;background:#fff;border:1px solid #e0e6ed;padding:4px;border-radius:2px;cursor:pointer;transition:0.2s;}
#chat-ui-bot-login-v30 .opening-item:hover{border-color:#1a237e;background:#f0f4ff;}
#chat-ui-bot-login-v30 .opening-item.selected{background:#e8eaf6;border-color:#1a237e;box-shadow:0 0 0 2px rgba(26,35,126,0.2);}
#chat-ui-bot-login-v30 .opening-item img{width:100%;aspect-ratio:2/3;object-fit:cover;filter:brightness(0.95);}
#chat-ui-bot-login-v30 .opening-item .op-title{font-size:11px;margin-top:6px;color:#1a237e;font-weight:bold;text-align:center;}
#chat-ui-bot-login-v30 .opening-item .op-desc{font-size:9px;color:#607d8b;line-height:1.4;text-align:center;padding:2px 4px 4px 4px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;}
#finalCopyToast{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#1a237e;color:#fff;padding:15px 30px;border-radius:2px;display:none;z-index:999;font-weight:bold;letter-spacing:1px;}
#openingToast{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#1a237e;color:#fff;padding:12px 24px;border-radius:2px;display:none;z-index:999;font-size:13px;font-weight:bold;}
</style>
</head>
<body>
<div id="chat-ui-bot-login-v30">
<div class="card-container">

<div class="corner-btn left" onclick="openOpenings()">📖</div>

<div class="content-layer">
<div class="title">
<h2>🩵妈妈🩵</h2>
