document.getElementById(''p-tip'').textContent=''✅ 已复制'';
setTimeout(function(){document.getElementById(''p-tip'').textContent='''';},2000);
}
</script>', '校园青春', '2026-10-05 10:12:59', '2026-10-05 10:15:00', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
