        .mode-btn#extreme-mode-btn.selected{background:linear-gradient(135deg,rgba(220,38,38,0.4),rgba(127,29,29,0.3));border-color:#dc2626;box-shadow:0 0 20px rgba(220,38,38,0.4)}
        @media (max-width:900px){.mode-selector{grid-template-columns:repeat(3,1fr)}}
        @media (max-width:768px){.tabs{flex-direction:column;align-items:center}.tab-btn{width:85%;text-align:center}h1{font-size:1.4rem}.btn-group{flex-direction:column;align-items:center}.copy-btn,.reset-btn{width:80%}.mode-selector{grid-template-columns:repeat(2,1fr)}.difficulty-selector{flex-wrap:wrap}.difficulty-selector .diff-btn{min-width:calc(33% - 0.5rem)}.xp-grid{grid-template-columns:repeat(2,1fr)}.route-grid{grid-template-columns:1fr}.fetish-tag-grid{grid-template-columns:repeat(2,1fr)}.author-note-grid{grid-template-columns:1fr}}
        @media (max-width:480px){.mode-selector{grid-template-columns:1fr}.difficulty-selector .diff-btn{min-width:calc(50% - 0.3rem)}}
