        .route-grid{grid-template-columns:1fr!important}
        .fetish-tag-grid{grid-template-columns:repeat(2,1fr)!important}
        .feature-grid{grid-template-columns:repeat(2,1fr)!important;gap:0.6rem}
        .route-showcase{grid-template-columns:repeat(2,1fr)!important}
        .target-wife-box{padding:0.8rem}
