.select-with-custom {
    display: flex;
    flex-direction: column;
    gap: 0.5em;
}
.custom-text-input {
    display: none;
    background: rgba(255, 105, 180, 0.1) !important;
    border-color: rgba(255, 105, 180, 0.5) !important;
}
.custom-text-input.active {
    display: block;
}
.custom-text-input:focus {
    border-color: #ff69b4 !important;
    box-shadow: 0 0 0 0.2em rgba(255, 105, 180, 0.3) !important;
}
.opening-options{display:flex;flex-direction:column;gap:0.8rem;margin:1rem 0}
.opening-option{background:rgba(42,26,58,0.6);border:2px solid rgba(255,105,180,0.2);border-radius:10px;padding:1rem;cursor:pointer;transition:all 0.3s;display:flex;align-items:flex-start;gap:0.8rem}
.opening-option:hover{border-color:rgba(255,105,180,0.5);background:rgba(74,20,140,0.4)}
.opening-option.selected{border-color:#ff69b4;background:rgba(199,21,133,0.3);box-shadow:0 0 15px rgba(255,105,180,0.3)}
.opening-option input[type="radio"]{margin-top:0.2rem;accent-color:#ff69b4;cursor:pointer;width:18px;height:18px;flex-shrink:0}
.opening-option .opening-content{flex:1}
.opening-option .opening-number{color:#ff69b4;font-weight:bold;font-size:0.9rem;margin-bottom:0.3rem}
.opening-option .opening-text{color:#ccc;font-size:0.9rem;line-height:1.6}
.opening-option.selected .opening-text{color:#e0e0e0}
/* ========== 手机端宽度修复 ========== */
@media (max-width: 768px) {
    .form-group input,
    .form-group textarea,
    .form-group select,
    .custom-text-input,
    .custom-input {
        width: 100% !important;
        max-width: 100% !important;
        min-width: 0 !important;
        box-sizing: border-box !important;
    }
    .select-with-custom,
    .target-wife-box,
    .target-wife-box .form-grid {
        width: 100% !important;
        max-width: 100% !important;
        overflow-x: hidden !important;
    }
    .form-group {
        width: 100% !important;
        max-width: 100% !important;
        overflow: hidden !important;
    }
}
/* 全局防止横向滚动 */
html, body, main, .section {
    overflow-x: hidden;
    max-width: 100vw;
}
.extreme-settings{display:none;background:linear-gradient(135deg,rgba(220,38,38,0.15),rgba(127,29,29,0.1));border:2px solid rgba(220,38,38,0.4);border-radius:12px;padding:1.2rem;margin-top:1rem;animation:fadeIn 0.3s ease}
.extreme-settings h4{color:#ef4444;margin:0 0 1rem 0;text-align:center;display:flex;align-items:center;justify-content:center;gap:0.5rem}
.extreme-settings .form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem}
.extreme-settings .hint{color:#888;font-size:0.8rem;margin-top:0.5rem;text-align:center}
.extreme-settings.active{display:block}
@media(max-width:768px){.extreme-settings .form-grid{grid-template-columns:1fr}}
.changelog-btn{position:fixed;top:1rem;right:8.2rem;z-index:100;background:linear-gradient(135deg,#ff69b4,#c71585);color:#fff;border:none;border-radius:50px;padding:0.6rem 1.2rem;font-size:0.9rem;font-weight:bold;cursor:pointer;display:flex;align-items:center;gap:0.4rem;box-shadow:0 4px 15px rgba(255,105,180,0.4);transition:all 0.3s}
.changelog-btn:hover{transform:translateY(-2px);box-shadow:0 6px 20px rgba(255,105,180,0.6)}
        .guide-btn{position:fixed;top:1rem;right:1rem;z-index:100;background:linear-gradient(135deg,#3b82f6,#2563eb);color:#fff;border:none;border-radius:50px;padding:0.6rem 1.2rem;font-size:0.9rem;font-weight:bold;cursor:pointer;display:flex;align-items:center;gap:0.4rem;box-shadow:0 4px 15px rgba(59,130,246,0.4);transition:all 0.3s}
        .guide-btn:hover{transform:translateY(-2px);box-shadow:0 6px 20px rgba(59,130,246,0.6)}
        #guide-modal{position:fixed;inset:0;background:rgba(0,0,0,0.85);display:none;align-items:center;justify-content:center;z-index:1000;backdrop-filter:blur(5px)}
        #guide-modal.active{display:flex}
#changelog-modal{position:fixed;inset:0;background:rgba(0,0,0,0.85);display:none;align-items:center;justify-content:center;z-index:1000;backdrop-filter:blur(5px)}
#changelog-modal.active{display:flex}
.changelog-content{background:linear-gradient(135deg,#1e1e2e,#2a2a4a);border:2px solid #ff69b4;border-radius:20px;padding:0;max-width:600px;width:90%;max-height:80vh;position:relative;box-shadow:0 20px 60px rgba(255,105,180,0.3);animation:modalPop 0.3s ease;display:flex;flex-direction:column;overflow:hidden}
.changelog-header{padding:1.5rem 1.5rem 1rem;border-bottom:1px solid rgba(255,105,180,0.3);display:flex;align-items:center;justify-content:space-between;flex-shrink:0}
.changelog-header h3{color:#ff69b4;margin:0;display:flex;align-items:center;gap:0.5rem;font-size:1.2rem}
.changelog-close{font-size:1.8rem;cursor:pointer;color:#ff69b4;transition:transform 0.2s;background:none;border:none;line-height:1;padding:0}
.changelog-close:hover{transform:rotate(90deg)}
.changelog-body{padding:1.5rem;overflow-y:auto;flex:1}
.changelog-item{margin-bottom:1.5rem;padding-bottom:1.5rem;border-bottom:1px dashed rgba(255,105,180,0.2)}
.changelog-item:last-child{margin-bottom:0;padding-bottom:0;border-bottom:none}
.changelog-date{color:#ff69b4;font-weight:bold;font-size:1rem;margin-bottom:0.5rem;display:flex;align-items:center;gap:0.5rem}
.changelog-version{background:rgba(255,105,180,0.2);color:#ff69b4;padding:0.2rem 0.6rem;border-radius:10px;font-size:0.8rem;margin-left:0.5rem}
.changelog-list{margin:0;padding-left:1.2rem;color:#ccc;line-height:1.8}
.changelog-list li{margin:0.3rem 0}
.changelog-tag{display:inline-block;padding:0.1rem 0.5rem;border-radius:8px;font-size:0.75rem;margin-right:0.3rem;font-weight:bold}
.changelog-tag.new{background:rgba(99,102,241,0.2);color:#6366f1}
.changelog-tag.fix{background:rgba(99,102,241,0.2);color:#6366f1}
.changelog-tag.update{background:rgba(99,102,241,0.2);color:#6366f1}
.changelog-tag.optimize{background:rgba(99,102,241,0.2);color:#6366f1}
@media(max-width:768px){.changelog-btn{top:0.5rem;right:5.5rem;padding:0.5rem 0.8rem;font-size:0.8rem}.changelog-btn span{display:none}.guide-btn{top:0.5rem;right:0.5rem;padding:0.5rem 0.8rem;font-size:0.8rem}.guide-btn span{display:none}.changelog-content{width:95%;max-height:85vh}.changelog-header{padding:1rem}.changelog-body{padding:1rem}}
    </style>
</head>
<body>
<button type="button" class="guide-btn" id="guide-btn">💡 建议 <span></span></button>
<button type="button" class="changelog-btn" id="changelog-btn">📋日志 <span></span></button>
<div id="changelog-modal">
    <div class="changelog-content">
        <div class="changelog-header">
            <h3>📋 更新日志</h3>
            <button type="button" class="changelog-close" id="changelog-close">&times;</button>
        </div>
        <div class="changelog-body">
