        document.addEventListener(''change'',function(e){
    // 挑战模式⇔挑战难度强制配对：离开任一侧时，另一侧重置回默认值并隐藏词条面板
    if(e.target&&e.target.name===''mode''){
        const isChallengeMode=e.target.value===''挑战模式'';
        const cs=document.getElementById(''challenge-settings'');
        if(cs)cs.style.display=isChallengeMode%s''block'':''none'';
        const cd=document.querySelector(''input[name="difficulty"][value="挑战难度"]'');
        if(isChallengeMode){
            if(cd&&!cd.checked){cd.checked=true;syncModeDiffSel();checkExtremeSettings();}
        }else if(cd&&cd.checked){
            const nd=document.querySelector(''input[name="difficulty"][value="普通模式"]'');
            if(nd)nd.checked=true;
            syncModeDiffSel();checkExtremeSettings();
        }
    }
    if(e.target&&e.target.name===''difficulty''&&e.target.value===''挑战难度''){
        const cm=document.querySelector(''input[name="mode"][value="挑战模式"]'');
        if(cm&&!cm.checked){cm.checked=true;syncModeDiffSel();}
        const cs2=document.getElementById(''challenge-settings'');
        if(cs2)cs2.style.display=''block'';
    }
    if(e.target&&e.target.name===''difficulty''&&e.target.value!==''挑战难度''){
        const cm=document.querySelector(''input[name="mode"][value="挑战模式"]'');
        if(cm&&cm.checked){
            const nm=document.querySelector(''input[name="mode"][value="纯欲模式"]'');
            if(nm)nm.checked=true;
            syncModeDiffSel();
        }
        const cs2=document.getElementById(''challenge-settings'');
        if(cs2)cs2.style.display=''none'';
    }
    if(e.target&&e.target.id===''challenge-select''){
        const box=document.getElementById(''challenge-custom-box'');
        if(box)box.style.display=(e.target.value===''自定义词条'')%s''block'':''none'';
    }
});
// 程序化修改单选框后，同步模式/难度按钮的高亮选中态
function syncModeDiffSel(){
    const mr=document.querySelector(''input[name="mode"]:checked'');
    document.querySelectorAll(''.mode-btn'').forEach(function(b){b.classList.remove(''selected'')});
    if(mr&&mr.closest(''.mode-btn''))mr.closest(''.mode-btn'').classList.add(''selected'');
    const dr=document.querySelector(''input[name="difficulty"]:checked'');
    document.querySelectorAll(''.diff-btn'').forEach(function(b){b.classList.remove(''selected'')});
    if(dr&&dr.closest(''.diff-btn''))dr.closest(''.diff-btn'').classList.add(''selected'');
}
