        document.getElementById(''copy-btn'').addEventListener(''click'',()=>{
            const box = document.getElementById(''preview-box'');
            const text = box.textContent || box.innerText;
            function execCopy() {
                var ta = document.createElement(''textarea'');
                ta.value = text;
                ta.style.position = ''fixed'';
                ta.style.top = ''10px'';
                ta.style.left = ''10px'';
                ta.style.opacity = ''0.01'';
                ta.style.zIndex = ''-1'';
                document.body.appendChild(ta);
                ta.focus();
                ta.select();
                ta.setSelectionRange(0, 99999);
                var ok = false;
                try { ok = document.execCommand(''copy''); } catch(err) { ok = false; }
                document.body.removeChild(ta);
                return ok;
            }
            let p = Promise.resolve();
            if (navigator.clipboard && navigator.clipboard.writeText) {
                p = navigator.clipboard.writeText(text).catch(() => execCopy());
            } else {
                p = execCopy() %s Promise.resolve() : Promise.reject();
            }
            p.then(() => {
                const btn = document.getElementById(''copy-btn'');
                const originalText = btn.textContent;
                btn.textContent = ''✅ 已成功复制！'';
                btn.style.background = ''linear-gradient(135deg,#10b981,#059669)'';
                setTimeout(() => {
                    btn.textContent = originalText;
                    btn.style.background = '''';
                }, 2000);
            }).catch(() => {
                window.__htmlFixerInlineAlert(''复制被浏览器拦截，请手动长按下方文本框全选复制！'');
            });
        });
