const selectConfigs = [
    { selectId: ''body-type-select'', customId: ''body-type-custom'' },
    { selectId: ''bust-select'', customId: ''bust-custom'' },
    { selectId: ''personality-select'', customId: ''personality-custom'' },
    { selectId: ''job-select'', customId: ''job-custom'' },
    { selectId: ''marriage-select'', customId: ''marriage-custom'' },
    { selectId: ''relation-select'', customId: ''relation-custom'' },
    { selectId: ''appearance-select'', customId: ''appearance-custom'' },
    { selectId: ''background-select'', customId: ''background-custom'' }
];
selectConfigs.forEach(config => {
    const select = document.getElementById(config.selectId);
    const customInput = document.getElementById(config.customId);
    if (select && customInput) {
        select.addEventListener(''change'', () => {
            if (select.value === ''自定义'') {
                customInput.classList.add(''active'');
            } else {
                customInput.classList.remove(''active'');
            }
        });
    }
});
function checkExtremeSettings(){
    const selectedMode=document.querySelector(''input[name="mode"]:checked'');
    const selectedDiff=document.querySelector(''input[name="difficulty"]:checked'');
    const extremeSettings=document.getElementById(''extreme-settings'');
    const isExtremeMode=selectedMode&&selectedMode.value===''极致模式'';
    const isExtremeDiff=selectedDiff&&selectedDiff.value===''极致难度'';
    if(isExtremeMode||isExtremeDiff){
        extremeSettings.classList.add(''active'');
    }else{
        extremeSettings.classList.remove(''active'');
    }
}
