function pwSelect(card){const g=document.getElementById(''pw-grid'');g.querySelectorAll(''.pw-card'').forEach(function(x){x.classList.remove(''sel'')});card.classList.add(''sel'');const pw=card.getAttribute(''data-pw'');window._presetWife=pw;const bar=document.getElementById(''pw-action'');const nm=document.getElementById(''pw-action-name'');const mb=document.getElementById(''pw-modify'');if(!bar)return;if(pw===''__random__''){nm.textContent=''🎲 AI随机生成，点「生成角色卡」直接开局'';if(mb)mb.style.display=''none'';}else{nm.textContent=''已选：''+pw;if(mb)mb.style.display=''inline-block'';}bar.style.display=''block'';}
function pwSetSel(selId,cusId,val,cusVal){const s=document.getElementById(selId);if(!s)return;let ok=false;for(let i=0;i<s.options.length;i++){if(s.options[i].value===val){ok=true;break}}if(ok){s.value=val;}else{s.value=''自定义'';const c=document.getElementById(cusId);if(c)c.value=cusVal||val;}try{s.dispatchEvent(new Event(''change''))}catch(e){}}
function pwUseModify(){const pd=WIFE_PRESETS.find(function(x){return x.n===window._presetWife});if(!pd)return;function set(k,v){const el=document.querySelector(''[data-key="''+k+''"]'');if(el)el.value=v;}
set(''人妻姓名'',pd.n);set(''人妻年龄'',pd.a);
pwSetSel(''body-type-select'',''body-type-custom'',pd.body);
pwSetSel(''bust-select'',''bust-custom'',pd.bust);
pwSetSel(''personality-select'',''personality-custom'',pd.t);
pwSetSel(''job-select'',''job-custom'',pd.p,pd.p2);
pwSetSel(''marriage-select'',''marriage-custom'',pd.m2,pd.m2c);
pwSetSel(''relation-select'',''relation-custom'',pd.rel,pd.relc);
const ac=document.getElementById(''appearance-custom'');if(ac)ac.value=pd.look;
const bc=document.getElementById(''background-custom'');if(bc)bc.value=pd.bg;
const rc=document.getElementById(''wife-custom'');if(rc){rc.checked=true;try{rc.dispatchEvent(new Event(''change''))}catch(e){}}
window._presetWife='''';const bar=document.getElementById(''pw-action'');if(bar)bar.style.display=''none'';const box=document.getElementById(''wife-custom-box'');if(box&&box.scrollIntoView)box.scrollIntoView({behavior:''smooth''});}
function pwRender(){const g=document.getElementById(''pw-grid'');if(!g)return;let h=''<div class="pw-card" data-pw="__random__"><div class="pw-nm">🎲 AI随机生成</div><div class="pw-info">不选特定角色，由AI根据你的模式与路线随机生成一位人妻</div></div>''+WIFE_PRESETS.map(function(c){return ''<div class="pw-card" data-pw="''+c.n+''"><div class="pw-nm">''+c.n+''</div><div class="pw-info">''+c.a+''岁 · ''+c.p+''<br>''+c.t+''<br>''+c.m+''</div><div class="pw-hook">突破口：''+c.w+''｜专属钩子：''+c.k+''</div></div>''}).join('''');g.innerHTML=h;g.querySelectorAll(''.pw-card'').forEach(function(card){card.addEventListener(''click'',function(){pwSelect(card);});});}
pwRender();
const pwModBtn=document.getElementById(''pw-modify'');if(pwModBtn)pwModBtn.addEventListener(''click'',pwUseModify);
// ===== 性别切换-事件委托兜底 v2.1 =====
document.addEventListener(''change'',function(e){
  const t=e.target;
  if(t&&t.name===''gender''&&t.type===''radio''){
    let v=(t.value||'''').trim();
    if(!v&&t.closest&&t.closest(''label'')){const lb=t.closest(''label'').textContent.trim();if(lb)v=lb;}
    const mf=document.getElementById(''male-fields''),ff=document.getElementById(''female-fields''),ffu=document.getElementById(''futa-fields''),of=document.getElementById(''other-fields'');
    if(mf)mf.classList.toggle(''active'',v===''男'');
    if(ff)ff.classList.toggle(''active'',v===''女'');
    if(ffu)ffu.classList.toggle(''active'',v===''扶他'');
    if(of)of.style.display=(v===''其他'')%s''block'':''none'';
  }
});
const cg=document.getElementById(''challenge-grid'');
if(cg)cg.querySelectorAll(''.pw-card'').forEach(function(card){card.addEventListener(''click'',function(){cg.querySelectorAll(''.pw-card'').forEach(function(x){x.classList.remove(''sel'')});card.classList.add(''sel'');const s=document.getElementById(''challenge-select'');if(s){s.value=card.getAttribute(''data-cv'');try{s.dispatchEvent(new Event(''change'',{bubbles:true}))}catch(e){}}});});
    </script>
