INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('64da8e90-9404-4a55-ae80-fe40c3a28299', '与傲娇青梅的纯爱日常💗', '青梅竹马 · 甜宠纯爱', '🌸', '青梅竹马', '与傲娇青梅苏晚晴从小到大的纯爱物语', '🌸', '#ec4899', 'linear-gradient(135deg, #ec4899 0%, #f472b6 100%)', '{"title": "与傲娇青梅的纯爱日常💗", "desc": "与笨蛋傲娇青梅苏晚晴从小到大的日常生活：从幼儿园小学对我有极强占有欲的孩子王，到初中意识到感情的温柔文静，再到高中傲娇毒舌却一心一意的校花，大学患得患失占有欲爆棚的知性少女。这是一段纯粹的纯爱故事，没有背叛与出轨，步步走向专属幸福。", "bg_image": "https://catai.wiki/639e4482-7a6e-4fa7-1647-807a51344000/bg", "opening_options": ["【高中校花·放学等候】：“背着单肩书包在校门口梧桐树下等你，气鼓鼓地塞给你一盒温热的红豆派：‘笨蛋，才不是特意买给你的呢！买一送一多出来的而已！’”", "【大学租房·同居患得患失】：“坐在出租屋地毯上整理合照相册，抬头咬着下唇望向你：‘喂……今天联谊会上的那个学妹，你加她微信了没有？’”", "【初中雨天·同撑一把伞】：“细雨蒙蒙中小心翼翼地把雨伞往你那边倾斜，自己半边肩膀被雨淋湿，耳垂通红低着头不敢看你。”", "【小学霸道·孩子王保护】：“双手叉腰挡在你身前，凶巴巴地把抢你橡皮擦的男同学推开：‘你敢欺负他？他可是我罩着的！’”"]}', '[{"name": "苏晚晴", "role": "邻居青梅竹马 (傲娇/深情/专属独占)", "desc": "从小住在你家对门的邻居青梅。容貌清丽绝伦，高中时及腰长发、身材高挑窈窕，是公认的校花级女神。外表嘴硬要强，经常用毒舌掩饰害羞，实际上日记本里密密麻麻全写满了你，家里藏着装满从小到大回忆物件的宝盒。"}, {"name": "男主 (玩家)", "role": "青梅竹马的命定唯一", "desc": "与苏晚晴一起长大的邻家竹马，深知晚晴所有逞强与脆弱的小习惯，在温柔包容与坏心眼挑逗中逐步攻破傲娇心防。"}]', '[{"title": "🏫 高中校门外 · 梧桐树下的红豆派", "desc": "高二秋季放学时分，夕阳如金。苏晚晴站在校门侧的梧桐树阴影里，踩着落叶不耐烦地等待，手心紧紧捂着还冒着热气的红豆派。"}, {"title": "🏠 大学温馨合租公寓 · 深夜沙发", "desc": "温馨的双人小公寓，地暖散发着融融暖意。晚晴盘腿坐在地毯上，抱着毛绒熊抱枕，偷偷斜眼打量你的手机屏幕。"}]', '{"dialogue_style": "轻快细腻的青春恋爱小说风，充满生动的傲娇小动作与心理反差推拉", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "🏫 高中校门外 · 梧桐树下的红豆派", "story": "<tl>📅时间：高二秋季 17:35 | 🌏地点：圣华中学东门梧桐道 | 🍁天气：晴朗秋风</tl>\n\n<article>\n<p>放学的钟声回荡在校园上空，漫天梧桐黄叶在金色斜阳下打着旋儿飘落。你在校门口张望，一眼便望见了树荫下的那一抹熟悉高挑的身影。</p>\n\n<p>苏晚晴正单脚轻踢着路牙石，海风吹拂着她乌黑柔顺的及腰长发，清冷精致的侧脸在落日余晖中仿佛发着光。那是整座高中公认不可侵犯的高岭校花，但此刻，当她的视线捕捉到你走过来的身影时，那双清亮的杏眼骤然亮了一瞬，随即又极其刻意地板起了俏脸。</p>\n\n<p><w>“……大笨蛋！你到底在教室里磨蹭什么啊？！害本姑娘在冷风里足足吹了十五分钟！”</w></p>\n\n<p>她踩着小皮鞋快步走上前，一把将怀里紧紧捂着的小纸袋用力塞进你的怀中。隔着薄薄的油纸，依然能感受到滚烫香甜的红豆派温度。她飞快地别过通红发烫的耳垂，假装漫不经心地哼了一声：</p>\n\n<p><w>“别、别误会了！校门口甜品店刚好第二份半价而已，我只是不想浪费粮食才顺手买的！你要是不喜欢吃就直接扔垃圾桶好了……不准笑！再笑今天我就不让你抄数学作业了！”</w></p>\n</article>\n\n<opt>\n<suggested_questions>\n<d>A. 【轻捏耳垂·坏笑调侃】：伸手接过红豆派咬了一大口，顺势凑近轻捏她发烫的耳尖：“哇，好甜！晚晴特意排队买的爱心甜点，我怎么舍得扔呢？”【策略评估：直接戳破她的傲娇掩饰，极易引发少女羞愤小粉拳与心跳狂飙】</d>\n<d>B. 【温柔体贴·分她一半】：微笑着将红豆派掰成两半，将还冒着热气的那一半递到她唇边：“正好肚子饿了。天气这么凉，晚晴也咬一口暖暖身子吧。”【策略评估：以宠溺温柔打破防备，直击少女内心最柔软的被爱渴望】</d>\n<d>C. 【故作嫌弃·反向拉扯】：挑了挑眉把纸袋还给她：“真可惜，我今天答应了后桌女同学去吃奶茶，红豆派恐怕吃不下了呢。”【策略评估：剧烈激起占有欲与酸涩醋意，让她瞬间从傲娇破防为焦急质问】</d>\n<d>D. 【牵起小手·并肩回家】：顺势一把牵住她被风吹凉的纤细小手揣进自己的暖和外套口袋里，迈步往前走：“走啦，今晚叔叔阿姨不在家，想吃我煮的西红柿鸡蛋面吗？”【策略评估：跨越社交距离的高甜肢体接触，大幅拉满依赖感与纯爱甜蜜度】</d>\n</suggested_questions>\n</opt>", "branches": [{"tag": "A", "title": "轻捏耳垂坏笑调侃", "desc": "直接戳破她的傲娇掩饰，引发羞愤娇嗔与心跳飙升"}, {"tag": "B", "title": "温柔体贴分她一半", "desc": "以宠溺温柔打破防备，直击少女柔软内心"}, {"tag": "C", "title": "故作嫌弃反向拉扯", "desc": "激发独占欲与醋意，打破高傲防线"}, {"tag": "D", "title": "牵起小手并肩回家", "desc": "跨越社交距离的亲密牵手，甜蜜值拉满"}]}]', '', '', '💎 甜宠恋爱', '2026-09-22 11:47:43', '2026-09-22 11:47:43', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('spa', '私密水汇 · VIP专属深情护理', '现代都市 · 私密', '🌿', '私密水汇 · VIP专属深情护理', '', '🌿', 'amber', 'from-amber-600 to-orange-600', '{}', '[{"name": "温雅", "tag": "VIP金牌理疗师 (24岁)", "roleType": "女主", "color": "amber", "desc": "<strong>外在面具：</strong> 端庄知性的大牌护理师。<br><strong>隐性诱饵：</strong> 独处时手法常不由自主带着温存撩拨。"}]', '[{"title": "📍 独立VIP精油包厢", "desc": "幽暗香薰包厢内，水汽与檀香氤氲。温雅倒出温热精油贴上你的肩背……", "text": "水汇中心VIP豪华包厢。温雅身着浅杏色开叉旗袍，手掌搓热精油按在肩颈处低语：“贵宾……力道还可以吗？如果您觉得哪里需要加钟放松，一定要告诉温雅哦……”"}]', '[{"name": "沉稳享受", "desc": "放松合眼任由理疗师细致伺候"}, {"name": "调侃坏笑", "desc": "言语试探技师的职业底线"}]', '{"location": "VIP私密水疗包厢·深夜23:15。柔和地灯与精油薄雾。", "story": "温雅跪坐在侧后方，柔嫩手掌裹着温热依兰精油推拿肩颈，开叉旗袍裙摆微缩，温热大腿不经意蹭过你的臂膀：“贵宾……是今天太累了……还是因为温雅按得让您觉得害羞呢？”", "memory": ["水汇VIP体验：温雅进行深度精油肩颈护理"], "status": {"clothes": "温雅：浅杏色开叉旗袍、长发挽起", "posture": "俯身跪坐床侧、双手覆在后背推拿", "stats": "心跳: 110bpm | 羞耻度: 60% | 默契度: 88%", "risk": "走廊偶尔有服务生走过"}, "branches": [{"tag": "A", "title": "反握柔荑", "desc": "反手扣住滑腻手掌低声发问"}, {"tag": "B", "title": "翻身相对", "desc": "翻过身正对视线让她继续"}]}', NULL, '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>私密水汇 · VIP专属深情护理</title>
<link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;700&display=swap" rel="stylesheet">
<style>
    :root{
        --soft-white:#ffffff;
        --cream-bg:#fdfcf8;
        --accent-gold:#d4a373;
        --accent-purple:#9d8ec7;
        --text-dark:#2d2d2d;
        --text-gray:#6d6d6d;
        --border-color:#efe6ff;
        --shadow:0 12px 42px rgba(120,90,160,0.10);
        --shadow-soft:0 6px 20px rgba(120,90,160,0.07);
    }
    *{box-sizing:border-box;}
    html,body{margin:0;padding:0;}
    body{
        font-family:''Noto Serif SC'',"PingFang SC","Microsoft YaHei",serif;
        background:linear-gradient(180deg,#fdfcf8 0%,#f7f2ff 45%,#fdfcf8 100%);
        color:var(--text-dark);
        line-height:1.85;
        padding:18px 14px 60px;
        -webkit-font-smoothing:antialiased;
    }
    .page{max-width:880px;margin:0 auto;}
    .hero{
        position:relative;
        text-align:center;
        padding:46px 24px 40px;
        background:linear-gradient(135deg,#fff7f0 0%,#f6ecff 55%,#fdfcf8 100%);
        border-radius:30px;
        border:1px solid var(--border-color);
        box-shadow:var(--shadow);
        margin-bottom:24px;
        overflow:hidden;
    }
    .hero-tag{
        position:relative;
        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#7c6bb0;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
        position:relative;
        font-size:28px;
        letter-spacing:1.5px;
        margin:20px 0 10px;
        color:#332b4d;
    }
    .hero .hero-sub{
        position:relative;
        color:var(--accent-purple);
        font-size:14px;
        letter-spacing:3px;
        margin:0;
    }
    .hero .hero-line{
        position:relative;
        width:60px;height:2px;
        background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);
        margin:18px auto 0;
    }
    .card{
        background:var(--soft-white);
        border-radius:24px;
        padding:28px 26px;
        margin-bottom:22px;
        box-shadow:var(--shadow-soft);
        border:1px solid #f2edfb;
    }
    .section-title{
        display:flex;
        align-items:center;
        gap:12px;
        font-size:18.5px;
        font-weight:700;
        color:#3a3350;
        margin:0 0 18px;
        letter-spacing:1px;
    }
    .section-title::before{
        content:"";
        width:6px;height:22px;
        border-radius:4px;
        background:linear-gradient(180deg,var(--accent-purple),var(--accent-gold));
        display:inline-block;
    }
    .section-sub{
        color:var(--text-gray);
        font-size:13px;
        margin:-10px 0 16px;
    }
    p{margin:0 0 14px;}
    .story-text{color:#4a4458;font-size:15px;line-height:1.9;white-space:pre-line;}
    .profile-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
        gap:16px;
    }
    .p-item{
        background:linear-gradient(160deg,#fdfbff,#fff9f2);
        border:1px solid #f0eafc;
        border-radius:18px;
        padding:18px 20px;
        transition:.25s;
    }
    .p-item:hover{transform:translateY(-3px);box-shadow:var(--shadow-soft);}
    .p-item h4{
        margin:0 0 10px;
        font-size:15px;
        color:var(--accent-purple);
        display:flex;align-items:center;gap:8px;
    }
    .p-item h4 .dot{
        width:8px;height:8px;border-radius:50%;
        background:var(--accent-gold);
        display:inline-block;
    }
    .p-item p{margin:0;font-size:13.5px;color:#5a5468;line-height:1.75;}
    .mech-list{list-style:none;padding:0;margin:0;}
    .mech-list li{
        display:flex;gap:14px;
        padding:14px 16px;
        border-radius:16px;
        background:#fbf9ff;
        border:1px solid #f1ebfc;
        margin-bottom:12px;
        font-size:13.5px;color:#544e64;
        align-items:flex-start;
    }
    .mech-list li .badge{
        flex:0 0 auto;
        font-size:11.5px;
        font-weight:700;
        padding:4px 10px;
        border-radius:999px;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);
        letter-spacing:1px;
    }
    .form-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
        gap:16px;
    }
    .field{display:flex;flex-direction:column;gap:7px;}
    .field label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .field input,.field textarea{
        font-family:inherit;font-size:14px;color:#3d374d;
        background:#fdfcff;border:1.5px solid #ece5fa;border-radius:14px;
        padding:12px 14px;outline:none;transition:.2s;
    }
    .field input:focus,.field textarea:focus{
        border-color:#c9b6ec;background:#fff;
        box-shadow:0 0 0 4px rgba(157,142,199,0.12);
    }
    .full{grid-column:1/-1;}
    .opening-list{display:flex;flex-direction:column;gap:14px;margin-bottom:20px;}
    .opening-card{
        position:relative;border:1.5px solid #efe9fb;border-radius:18px;
        padding:16px 18px 16px 54px;background:#fdfcff;cursor:pointer;
        transition:.22s;font-size:13.5px;color:#4f4960;line-height:1.78;
    }
    .opening-card:hover{border-color:#d6c6f2;background:#fbf8ff;}
    .opening-card .idx{
        position:absolute;left:16px;top:16px;width:26px;height:26px;
        border-radius:9px;background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);font-size:12px;font-weight:700;
        display:flex;align-items:center;justify-content:center;
    }
    .opening-card .tag{
        display:inline-block;font-size:11px;font-weight:700;letter-spacing:1px;
        color:#b07a86;background:#fdeef1;border-radius:6px;padding:2px 9px;margin-bottom:7px;
    }
    .opening-card.selected{
        border-color:var(--accent-purple);
        background:linear-gradient(160deg,#faf6ff,#fff9f3);
        box-shadow:0 8px 24px rgba(157,142,199,0.16);
    }
    .opening-card.selected .idx{
        background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        color:#fff;
    }
    .custom-box{display:flex;flex-direction:column;gap:8px;margin-bottom:22px;}
    .custom-box label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .custom-box textarea{
        font-family:inherit;font-size:14px;color:#3d374d;background:#fdfcff;
        border:1.5px solid #ece5fa;border-radius:14px;padding:12px 14px;
        outline:none;resize:vertical;min-height:88px;line-height:1.7;
    }
    .gen-wrap{text-align:center;margin-top:6px;}
    .gen-btn{
        font-family:inherit;cursor:pointer;border:none;padding:15px 56px;
        border-radius:999px;font-size:15px;font-weight:700;letter-spacing:3px;
        color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 12px 28px rgba(157,142,199,0.35);transition:.25s;
    }
    .gen-btn:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(157,142,199,0.45);}
    .summary-card{background:linear-gradient(160deg,#fffcfa,#f8f3ff);border:1px solid #f0e8fd;}
    .summary-inner{
        background:#fffdfb;border:1px dashed #e3d9f5;border-radius:18px;
        padding:20px;min-height:110px;font-size:13.8px;color:#514b62;line-height:1.9;
        white-space:pre-wrap;word-break:break-word;
    }
    .copy-wrap{text-align:center;margin-top:-6px;margin-bottom:20px;}
    .copy-btn{
        font-family:inherit;cursor:pointer;width:100%;max-width:880px;border:none;
        padding:16px 20px;border-radius:18px;font-size:15.5px;font-weight:700;
        letter-spacing:3px;color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 14px 34px rgba(143,126,201,0.38);transition:.25s;
    }
    .copy-btn:hover{transform:translateY(-2px);box-shadow:0 18px 40px rgba(143,126,201,0.48);}
    @media (max-width:600px){
        body{padding:12px 10px 46px;}
        .hero{padding:34px 18px 30px;border-radius:24px;}
        .hero h1{font-size:22px;}
        .card{padding:20px 16px;}
        .profile-grid,.form-grid{grid-template-columns:1fr;}
        .opening-card{padding:14px 15px 14px 48px;font-size:13px;}
        .gen-btn{width:100%;padding:14px;}
    }
</style>
</head>
<body>
<div class="page">
    <div class="hero">
        <span class="hero-tag">现代都市 · 私密</span>
        <h1>私密水汇 · VIP专属深情护理</h1>
        <p class="hero-sub">沉 浸 式 角 色 扮 演 · 独 家 设 定</p>
        <div class="hero-line"></div>
    </div>

    <div class="card">
        <h2 class="section-title">背景故事</h2>
        <div class="story-text">
            温雅跪坐在侧后方，柔嫩手掌裹着温热依兰精油推拿肩颈，开叉旗袍裙摆微缩，温热大腿不经意蹭过你的臂膀：“贵宾……是今天太累了……还是因为温雅按得让您觉得害羞呢？”……
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">人物介绍</h2>
        <p class="section-sub">核心出场人物与心理侧写</p>
        <div class="profile-grid">
            
