const charClassSelect=document.getElementById(''char-class'');
const customClassGroup=document.getElementById(''custom-class-group'');
const existingItemSelect=document.getElementById(''choose-existing-item'');
const customItemInputs=document.getElementById(''custom-item-inputs'');
const showCustomBtn=document.getElementById(''show-custom-btn'');
const itemSearchInput=document.getElementById(''item-search-input'');
const itemGallery=document.getElementById(''item-gallery'');
const galleryWrapper=document.querySelector(''.item-gallery-wrapper'');
const selectedItemsList=document.getElementById(''selected-items-list'');
const itemDetailsModal=document.getElementById(''item-details-modal'');
const quickNavModal=document.getElementById(''quick-nav-modal'');
const quickNavBtn=document.getElementById(''quick-nav-btn'');
const quickNavSelect=document.getElementById(''quick-nav-select'');
const chordLockModal=document.getElementById(''chord-lock-modal'');
const chordLockToggleBtn=document.getElementById(''chord-lock-toggle-btn'');
let isCustomMode=false;
let selectedItems=[];
let isChordLockActive=false;
let chordLockInfoShown=false;
function showNotification(message,duration=3000){const notificationBox=document.getElementById(''notification-box'');notificationBox.textContent=message;notificationBox.classList.add(''show'');setTimeout(()=>{notificationBox.classList.remove(''show'');},duration);}
function renderItemCards(poolToRender){itemGallery.innerHTML='''';if(poolToRender.length===0){itemGallery.innerHTML=''<p style="text-align:center;width:100%;font-style:italic;">未找到匹配的商品。</p>'';return;}
poolToRender.forEach(item=>{const card=document.createElement(''div'');card.classList.add(''item-card'');card.dataset.code=item.code;card.innerHTML=`<div class="item-card-info"><p class="code">${item.code}</p><h4>${item.name}</h4><p class="work">${item.work}</p><p>${item.tagline}</p></div><div class="item-card-buttons"><button class="btn card-btn view-details-btn" data-code="${item.code}">查看详情</button><button class="btn card-btn add-to-list-btn" data-code="${item.code}">添加到选购清单</button></div>`;itemGallery.appendChild(card);});updateSelectedListUI();}
function populateWorkFilter(){const workFilterSelect=document.getElementById(''work-filter-select'');workFilterSelect.innerHTML='''';const works=[''all'',...new Set(WORLD_POOL.map(item=>item.work))];works.forEach(work=>{const option=document.createElement(''option'');option.value=work;option.textContent=(work===''all'')%s''—— 所有作品 ——'':work;workFilterSelect.appendChild(option);});populateCharFilter(''all'');}
function populateCharFilter(selectedWork){const charFilterSelect=document.getElementById(''char-filter-select'');charFilterSelect.innerHTML='''';const allOption=document.createElement(''option'');allOption.value=''all'';allOption.textContent=''—— 所有角色 ——'';charFilterSelect.appendChild(allOption);if(selectedWork===''all''){charFilterSelect.disabled=true;}else{charFilterSelect.disabled=false;const chars=WORLD_POOL.filter(item=>item.work===selectedWork);chars.forEach(char=>{const option=document.createElement(''option'');option.value=char.code;option.textContent=char.name;charFilterSelect.appendChild(option);});}}
function updateGallery(){const workFilter=document.getElementById(''work-filter-select'').value;const charFilter=document.getElementById(''char-filter-select'').value;const sortMethod=document.getElementById(''sort-by-select'').value;const searchTerm=itemSearchInput.value.toLowerCase();let tempPool=[...WORLD_POOL];if(workFilter!==''all''){tempPool=tempPool.filter(item=>item.work===workFilter);}
if(charFilter!==''all''){tempPool=tempPool.filter(item=>item.code===charFilter);}
if(searchTerm){tempPool=tempPool.filter(item=>item.name.toLowerCase().includes(searchTerm)||item.code.toLowerCase().includes(searchTerm)||item.origin.toLowerCase().includes(searchTerm)||item.work.toLowerCase().includes(searchTerm));}
switch(sortMethod){case''name-asc'':tempPool.sort((a,b)=>a.name.localeCompare(b.name));break;case''name-desc'':tempPool.sort((a,b)=>b.name.localeCompare(a.name));break;case''code-desc'':tempPool.sort((a,b)=>b.code.localeCompare(a.code));break;case''code-asc'':default:tempPool.sort((a,b)=>a.code.localeCompare(b.code));}
renderItemCards(tempPool);}
function updateSelectedListUI(){selectedItemsList.innerHTML='''';selectedItems.forEach(code=>{const item=WORLD_POOL.find(i=>i.code===code);if(!item)return;const tag=document.createElement(''div'');tag.classList.add(''selected-item-tag'');tag.innerHTML=`<span>${item.name}</span><button class="remove-item-btn" data-code="${code}">&times;</button>`;selectedItemsList.appendChild(tag);});const addBtns=document.querySelectorAll(''.add-to-list-btn'');addBtns.forEach(btn=>{if(selectedItems.includes(btn.dataset.code)){btn.textContent=''已添加'';btn.disabled=true;}else{btn.textContent=''添加到选购清单'';btn.disabled=false;}});}
function addToSelectedList(code){if(!selectedItems.includes(code)){selectedItems.push(code);updateSelectedListUI();showNotification(''商品已添加至清单！'');}}
function removeFromSelectedList(code){selectedItems=selectedItems.filter(itemCode=>itemCode!==code);updateSelectedListUI();showNotification(''商品已从清单移除。'');}
function showDetailsModal(code){const item=WORLD_POOL.find(i=>i.code===code);if(!item)return;const modalBody=itemDetailsModal.querySelector(''#modal-body'');const featuresHTML=item.features.map(f=>`<li>${f}</li>`).join('''');modalBody.innerHTML=`<h3 style="text-align:left;">${item.name} <span style="font-size:0.7em;color:#aaa;">(${item.code})</span></h3><p><strong>身份：</strong> ${item.origin}</p><p><strong>来源：</strong> ${item.work}</p><p><strong>宣传语：</strong> ${item.tagline}</p><hr style="border-color:var(--border-color);margin:15px 0;"><p><strong>外貌档案：</strong></p><ul class="features"><li>发色: ${item.appearance.hair}</li><li>瞳色: ${item.appearance.eyes}</li><li>身材: ${item.appearance.body}</li><li>胸部: ${item.appearance.breasts}</li></ul><p><strong>特征：</strong></p><ul class="features">${featuresHTML}</ul><p><strong>联邦推荐：</strong></p><p>${item.comment}</p><div style="text-align:center;margin-top:20px;"><button id="modal-add-btn" class="btn add-to-list-btn" data-code="${item.code}">添加到选购清单</button></div>`;itemDetailsModal.classList.add(''active'');const modalAddBtn=document.getElementById(''modal-add-btn'');if(selectedItems.includes(code)){modalAddBtn.textContent=''已添加'';modalAddBtn.disabled=true;}else{modalAddBtn.addEventListener(''click'',()=>{addToSelectedList(code);itemDetailsModal.classList.remove(''active'');});}}
function populateQuickNav(){quickNavSelect.innerHTML='''';WORLD_POOL.forEach(item=>{const option=document.createElement(''option'');option.value=item.code;option.textContent=`${item.name} (${item.code})`;quickNavSelect.appendChild(option);});}
function scrollToCard(code){const cardToScroll=document.querySelector(`.item-card[data-code="${code}"]`);if(cardToScroll){galleryWrapper.scrollLeft=cardToScroll.offsetLeft-galleryWrapper.offsetLeft;}quickNavModal.classList.remove(''active'');}
function setCustomMode(mode){isCustomMode=mode;if(isCustomMode){customItemInputs.style.display=''block'';galleryWrapper.style.display=''none'';selectedItemsList.parentElement.style.display=''none'';showCustomBtn.textContent=''返回商品列表'';itemSearchInput.disabled=true;showNotification(''已进入自定义模式。'');}else{customItemInputs.style.display=''none'';galleryWrapper.style.display=''block'';selectedItemsList.parentElement.style.display=''block'';showCustomBtn.textContent=''自定义临时商品'';itemSearchInput.disabled=false;updateGallery();showNotification(''已返回商品列表。'');}}
function generatePrologue(){const name=document.getElementById(''char-name'').value||''林宇'';const age=document.getElementById(''char-age'').value||''25'';const gender=document.getElementById(''char-gender'').value;const appearance=document.getElementById(''char-appearance'').value||''外貌普通，但眼神深邃'';const personality=document.getElementById(''char-personality'').value||''沉着冷静，富有野心'';const selectedClass=document.getElementById(''char-class'').value;const customClass=selectedClass===''自定义''%s(document.getElementById(''custom-class-input'').value||''无名小卒''):selectedClass;let selectedWorlds=[];if(isCustomMode){selectedWorlds.push({code:document.getElementById(''custom-item-code'').value||''C-9999'',name:document.getElementById(''custom-item-name'').value||''一位自定义商品'',origin:document.getElementById(''custom-item-origin'').value||''被捕前身份不明'',tagline:''自定义标签'',appearance:{hair:''自定义'',eyes:''自定义'',body:document.getElementById(''custom-item-appearance'').value||''自定义外貌'',breasts:document.getElementById(''custom-item-breasts'').value||''自定义罩杯''},features:[''性格：''+(document.getElementById(''custom-item-personality'').value||''自定义性格'')],comment:document.getElementById(''custom-item-comment'').value||''这是一件根据您的喜好特别定制的商品。''});}else{selectedItems.forEach(code=>{const item=WORLD_POOL.find(i=>i.code===code);if(item)selectedWorlds.push(item);});}
if(selectedWorlds.length===0){showNotification(''请至少选择或自定义一个商品！'');return;}
let prologueContent=`【联邦订单确认...】\n姓名：${name}\n年龄：${age}\n性别：${gender}\n外貌：${appearance}\n性格：${personality}\n社会阶层：${customClass}\n【商品信息】\n您已成功选购以下商品：\n`;selectedWorlds.forEach(worldData=>{const featuresString=worldData.features.join(''，'');const appearanceString=`\n  - 发色: ${worldData.appearance.hair}\n  - 瞳色: ${worldData.appearance.eyes}\n  - 身材: ${worldData.appearance.body}\n  - 胸部: ${worldData.appearance.breasts}`;prologueContent+=`\n商品编号：${worldData.code}\n商品名称：${worldData.name}\n商品宣传：${worldData.tagline}\n被捕前身份：${worldData.origin}\n性格特征：${featuresString}\n商品外貌档案:${appearanceString}\n【联邦宣传语】\n${worldData.comment}\n---\n`;});prologueContent+=`\n清脆的提示音响起，我的账户已完成扣款。\n家里的冷气打在我的脸上，面前的玻璃柜中，我的“所有物”正安静地沉睡着。\n联邦的AI语音在耳边响起：“欢迎回家，您的专属‘所有物’已为您准备就D就绪。”\n一`;if(isChordLockActive){prologueContent+=`\n\n💗`;}
const outputContainer=document.getElementById(''prologue-output-container'');const outputDiv=document.getElementById(''prologue-output'');outputDiv.textContent=prologueContent.trim();outputContainer.style.display=''block'';}
function generateWanderingPrologue(){const name=document.getElementById(''char-name'').value||''林宇'';const appearance=document.getElementById(''char-appearance'').value||''外貌普通，但眼神深邃'';const personality=document.getElementById(''char-personality'').value||''沉着冷静，富有野心'';const selectedClass=document.getElementById(''char-class'').value;const customClass=selectedClass===''自定义''%s(document.getElementById(''custom-class-input'').value||''无名小卒''):selectedClass;const prologue=`【场景：联邦特供服务中心 - 中央展厅】\n我，${name}，一位${customClass}，正漫步在服务中心的中央展厅。空气中弥漫着消毒水和昂贵香氛混合的冰冷气息。穹顶的柔和光线均匀地洒在抛光的大理石地板上，反射出周围一个个休眠仓的轮廓。\n我的外貌——${appearance}——在光线下显得轮廓分明。我的性格为${personality}。\n这里安静得只剩下我自己的脚步声，以及远处其他买家偶尔传来的低语。他们和您一样，衣着光鲜，眼神中带着审视与欲望，像是在挑选一件昂贵的艺术品。\n我的目光扫过一排排透明的休眠仓。里面的“商品”们都穿着统一的素白长裙，静静地沉睡着，胸前显示着她们独一无二的商品编号。她们曾经的身份——演员、科学家、反抗者、学生——都已被去，只剩下标签化的简介供人挑选。\n是选择一个外表柔弱、内心却充满反抗火苗的，享受征服的快感？还是挑选一个曾经高高在上、如今却只能任人摆布的，品味地位颠覆的乐趣？\n我停下脚步，深吸一口气。选择的时刻即将来临。我需要做的，只是选择清单，然后做出决定。\n`;const outputContainer=document.getElementById(''prologue-output-container'');const outputDiv=document.getElementById(''prologue-output'');outputDiv.textContent=prologue.trim();outputContainer.style.display=''block'';}
function generateItemPrologue(){let name,origin,appearance,personality;const selectedItemCode=existingItemSelect.value;const itemCode=document.getElementById(''item-code'').value||''无编号'';if(selectedItemCode){const itemData=WORLD_POOL.find(i=>i.code===selectedItemCode);name=itemData.name;origin=itemData.origin;appearance=`发色: ${itemData.appearance.hair}，瞳色: ${itemData.appearance.eyes}，身材: ${itemData.appearance.body}，胸部: ${itemData.appearance.breasts}`;personality=`性格: ${itemData.features.find(f=>f.startsWith(''性格：'')).split(''：'')[1]}`;}else{name=document.getElementById(''item-name'').value||''一位无名女性'';origin=document.getElementById(''item-origin'').value||''前某行业精英'';appearance=document.getElementById(''item-appearance'').value||''外貌普通，但眼神倔强'';personality=document.getElementById(''item-personality'').value||''内心充满不屑与反抗'';}
const buyerProfile=document.getElementById(''buyer-profile'').value||''一位面容冷峻的男人'';const prologue=`玩家选择扮演被捕获的商品为主角，明确使用被捕获者的第一/第二人称混合视角。\n商品编号：${itemCode}\n商品名称：${name}\n被捕前身份：${origin}\n外貌档案：${appearance}\n性格档案：${personality}\n买主档案：${buyerProfile}\n---\n我被一阵强光刺醒，回想起了自己被莫名D妙的捕获。\n我打量着自己穿着的几乎可以说得上只有几个乳贴和阴贴的逆兔女郎装，耳边充斥着对于你的特色玩法以及舒适用法的三流低俗广告一样的广告词。\n我曾是${origin}，拥有自己的骄傲和尊严。而现在，我只是一件被明码标价的“所有物”。\n新的篇章，在你成为“商品”的那一刻，正式开启。\n`;const outputContainer=document.getElementById(''prologue-output-container'');const outputDiv=document.getElementById(''prologue-output'');outputDiv.textContent=prologue.trim();outputContainer.style.display=''block'';}
function copyPrologue(){const outputDiv=document.getElementById(''prologue-output'');if(!outputDiv.textContent)return;const tempTextArea=document.createElement(''textarea'');tempTextArea.value=outputDiv.textContent;document.body.appendChild(tempTextArea);tempTextArea.select();document.execCommand(''copy'');document.body.removeChild(tempTextArea);showNotification(''开场信息已成功复制到剪贴板！'');}
document.querySelectorAll(''input[name="player-role"]'').forEach(radio=>{radio.addEventListener(''change'',(event)=>{const isBuyer=event.target.value===''buyer'';document.getElementById(''buyer-section'').classList.toggle(''active'',isBuyer);document.getElementById(''item-section'').classList.toggle(''active'',!isBuyer);document.getElementById(''buyer-item-selection'').style.display=isBuyer%s''block'':''none'';document.getElementById(''buyer-choice-buttons'').classList.toggle(''active'',isBuyer);document.getElementById(''item-choice-buttons'').classList.toggle(''active'',!isBuyer);document.getElementById(''prologue-output-container'').style.display=''none'';if(isBuyer)setCustomMode(false);});});
charClassSelect.addEventListener(''change'',(event)=>{customClassGroup.style.display=event.target.value===''自定义''%s''block'':''none'';showNotification(''社会阶层已更新。'');});
showCustomBtn.addEventListener(''click'',()=>{setCustomMode(!isCustomMode);});
itemGallery.addEventListener(''click'',event=>{const target=event.target;if(target.classList.contains(''view-details-btn'')){showDetailsModal(target.dataset.code);}else if(target.classList.contains(''add-to-list-btn'')){addToSelectedList(target.dataset.code);}});
selectedItemsList.addEventListener(''click'',event=>{if(event.target.classList.contains(''remove-item-btn'')){const code=event.target.dataset.code;removeFromSelectedList(code);}});
document.querySelectorAll(''.modal-overlay'').forEach(modal=>{modal.addEventListener(''click'',event=>{if(event.target===modal||event.target.classList.contains(''modal-close-btn'')){modal.classList.remove(''active'');}});});
quickNavBtn.addEventListener(''click'',()=>{quickNavModal.classList.add(''active'');});
quickNavSelect.addEventListener(''change'',(event)=>{scrollToCard(event.target.value);});
chordLockToggleBtn.addEventListener(''click'',()=>{isChordLockActive=!isChordLockActive;chordLockToggleBtn.classList.toggle(''active'',isChordLockActive);if(isChordLockActive){if(!chordLockInfoShown){chordLockModal.classList.add(''active'');chordLockInfoShown=true;}
showNotification(''和弦锁定已开启'');}else{showNotification(''和弦锁定已关闭'');}});
WORLD_POOL.forEach(item=>{const option=document.createElement(''option'');option.value=item.code;option.textContent=`${item.name} (${item.origin})`;existingItemSelect.appendChild(option);});
existingItemSelect.addEventListener(''change'',(event)=>{const selectedItemCode=event.target.value;const customInputs=document.querySelectorAll(''#item-section input, #item-section textarea'');const isCustom=!selectedItemCode;customInputs.forEach(input=>{if(input.id!==''buyer-profile''&&input.id!==''choose-existing-item'')input.disabled=!isCustom;});const itemCodeInput=document.getElementById(''item-code'');const itemNameInput=document.getElementById(''item-name'');const itemOriginInput=document.getElementById(''item-origin'');const itemAppearanceInput=document.getElementById(''item-appearance'');const itemPersonalityInput=document.getElementById(''item-personality'');if(!isCustom){const itemData=WORLD_POOL.find(i=>i.code===selectedItemCode);itemCodeInput.value=itemData.code;itemNameInput.value=itemData.name;itemOriginInput.value=itemData.origin;itemAppearanceInput.value=itemData.appearance.body;itemPersonalityInput.value=itemData.features.find(f=>f.startsWith(''性格：'')).split(''：'')[1];showNotification(''已选择现有角色，自定义输入框已锁定。'');}else{itemCodeInput.value='''';itemNameInput.value='''';itemOriginInput.value='''';itemAppearanceInput.value='''';itemPersonalityInput.value='''';showNotification(''已切换为自定义角色。'');}});
document.getElementById(''generate-prologue-btn'').addEventListener(''click'',generatePrologue);
document.getElementById(''generate-wandering-btn'').addEventListener(''click'',generateWanderingPrologue);
document.getElementById(''generate-item-prologue-btn'').addEventListener(''click'',generateItemPrologue);
document.getElementById(''copy-prologue-btn'').addEventListener(''click'',copyPrologue);
itemSearchInput.addEventListener(''input'',updateGallery);
document.getElementById(''work-filter-select'').addEventListener(''change'',(event)=>{populateCharFilter(event.target.value);updateGallery();});
document.getElementById(''char-filter-select'').addEventListener(''change'',updateGallery);
document.getElementById(''sort-by-select'').addEventListener(''change'',updateGallery);
document.getElementById(''reset-filters-btn'').addEventListener(''click'',()=>{itemSearchInput.value='''';document.getElementById(''work-filter-select'').value=''all'';populateCharFilter(''all'');document.getElementById(''sort-by-select'').value=''code-asc'';updateGallery();showNotification(''筛选与排序已重置。'');});
populateWorkFilter();
updateGallery();
populateQuickNav();
document.getElementById(''buyer-section'').classList.add(''active'');
document.getElementById(''buyer-choice-buttons'').classList.add(''active'');
</script>
</body>
</html>', '男性向', '2026-10-11 11:21:15', '2026-10-11 11:21:15', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('d9380550-16bf-48a8-8492-e5edd9bd8497', '🏪24小时便利店：色情店员的无套内射服务💰(NTL/人妻/萝莉/少女/御姐)', '都市 · 特殊服务', '🏪', '🏪24小时便利店：色', '🏪24小时便利店：色情店员的无套内射服务💰(NTL/人妻/萝莉/少女/御姐)', '🏪', '#f59e0b', 'linear-gradient(135deg, #d97706 0%, #f59e0b 100%)', '{"title": "🏪24小时便利店：色情店员的无套内射服务💰(NTL/人妻/萝莉/少女/御姐)", "desc": "午夜两点半，街头冷风呼啸，唯有老旧街角那盏闪烁着「24小时便利店」的招牌还透着暖黄光晕。\n\n你推开玻璃门，机械门铃发出「叮咚，欢迎光临」的清脆声响。店内货架齐整，而在收银台后，值班店员正抬起头打量着你，领口微敞的制服与若有似无的香水味在静谧的空气中悄然弥漫……小票机上静静闪烁着特殊服务的消费代码。", "bg_image": "https://catai.wiki/99dc2c92-a193-4b63-054c-abf318495b00/bg", "opening_options": ["【选购高额商品】：递上印有大额消费的小票，试探开启暗室服务密码", "【靠在收银台前】：直接询问今晚有哪些特色服务与私密体验项目", "【点名挑选店员】：指名心仪当班店员，直接进入收银台后方的私密隔间"]}', '[{"name": "主角 (玩家)", "role": "核心视角 / 顾客", "desc": "手握充沛预算走进这家表面平凡却暗藏玄机的24小时便利店的顾客。"}, {"name": "李佳怡", "role": "店员 · 青春少女 (20岁)", "desc": "高马尾鹅蛋脸，活泼开朗善于察言观色，兼职赚取生活费，周一、周四排班。"}, {"name": "沈璃", "role": "店员 · 高冷御姐 (24岁)", "desc": "黑长直冷白皮凤眼，高冷傲慢少言，求职碰壁为生计兼职，周二、周五排班。"}, {"name": "王馨悦", "role": "店员 · 成熟人妻 (30岁)", "desc": "丰腴温柔眉目含情，背负家庭房贷重压，周三、周六排班。"}]', '[{"title": "深夜的24小时便利店收银台", "desc": "老旧居民区边缘亮着暖黄色灯光的便利店，后方收银台隔帘后暗藏私密隔间。"}]', '{"dialogue_style": "细腻深邃的情感描写，极具沉浸感的人物神态心理博弈与生动对话", "format": "幻诺剧场标准交互规范及.custom-ui手账联动"}', '[{"index": 1, "isUser": false, "scene": "深夜的24小时便利店收银台", "story": "<tl>📅时间：关键时刻 | 🌏地点：深夜的24小时便利店收银台</tl>\n\n<article>\n<p>午夜两点半，街头冷风呼啸，唯有老旧街角那盏闪烁着「24小时便利店」的招牌还透着暖黄光晕。</p><p></p><p>你推开玻璃门，机械门铃发出「叮咚，欢迎光临」的清脆声响。店内货架齐整，而在收银台后，值班店员正抬起头打量着你，领口微敞的制服与若有似无的香水味在静谧的空气中悄然弥漫……小票机上静静闪烁着特殊服务的消费代码。</p>\n</article>", "branches": [{"tag": "A", "title": "选购高额商品", "desc": "递上印有大额消费的小票，试探开启暗室服务密码"}, {"tag": "B", "title": "靠在收银台前", "desc": "直接询问今晚有哪些特色服务与私密体验项目"}, {"tag": "C", "title": "点名挑选店员", "desc": "指名心仪当班店员，直接进入收银台后方的私密隔间"}]}]', '', '<style>
.cvs-app{--bg:#fdf8f2;--card:#ffffff;--line:#ecdfd0;--ink:#3b3530;--ink2:#8a7d70;--main:#d98a4e;--main-d:#c4743a;--blue:#6a9bb5;--pink:#d98aa0;--green:#8fb886;--purple:#a89ac5;font-family:"PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;background:linear-gradient(180deg,#fdf8f2,#faf3ea);color:var(--ink);line-height:1.75;border:1px solid var(--line);border-radius:22px;max-width:920px;margin:0 auto;padding:0;overflow:hidden;font-size:15px;letter-spacing:.2px;box-shadow:0 12px 40px rgba(180,140,90,.1)}
.cvs-app *{box-sizing:border-box}
.cvs-app .hd{background:linear-gradient(135deg,#fbe9d2,#f7d9bd 55%,#f3cdac);padding:30px 26px 26px;text-align:center;position:relative;border-bottom:1px solid #f0dcc4;scroll-margin-top:14px}
.cvs-app .hd .badge{display:inline-block;font-size:12px;letter-spacing:3px;color:#b0794a;background:rgba(255,255,255,.7);border:1px solid #eed3b6;border-radius:999px;padding:3px 14px;margin-bottom:12px;font-weight:700}
.cvs-app .hd h1{margin:0;font-size:29px;letter-spacing:2px;color:#6b4a2c;font-weight:800}
.cvs-app .hd p{margin:9px 0 0;font-size:13.5px;color:#9a7a58;letter-spacing:1px}
.cvs-app .nav{display:flex;flex-wrap:wrap;gap:9px;padding:16px 20px;background:#fffdf9;border-bottom:1px solid var(--line);justify-content:center}
.cvs-app .nav-btn{font-family:inherit;cursor:pointer;border:1px solid #e9d8c4;background:#fff;color:#856b4e;padding:7px 16px;border-radius:999px;font-size:13.5px;font-weight:600;transition:all .22s ease;box-shadow:0 1px 2px rgba(180,140,90,.07)}
.cvs-app .nav-btn:hover{transform:translateY(-2px);border-color:var(--main);color:var(--main-d);background:#fff8f0;box-shadow:0 5px 14px rgba(216,138,78,.2)}
.cvs-app .nav-btn:active{transform:translateY(0)}
.cvs-app .wrap{padding:22px 20px 30px;display:flex;flex-direction:column;gap:22px}
.cvs-app .sec{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:22px 22px 24px;position:relative;box-shadow:0 3px 14px rgba(190,155,110,.07);scroll-margin-top:14px}
.cvs-app .sec::before{content:"";position:absolute;left:0;top:22px;bottom:22px;width:4px;border-radius:0 4px 4px 0;background:var(--accent,var(--main));opacity:.85}
.cvs-app .sec-title{display:flex;align-items:center;gap:11px;margin:0 0 16px;padding-bottom:13px;border-bottom:2px dashed #efe3d4;font-size:18.5px;font-weight:800;color:#5d4a37;letter-spacing:.5px}
.cvs-app .sec-title .ico{width:30px;height:30px;flex:0 0 auto;display:flex;align-items:center;justify-content:center;border-radius:10px;font-size:15px;background:var(--accent,var(--main));color:#fff;box-shadow:0 3px 8px rgba(0,0,0,.12)}
.cvs-app .sec-title .top-btn{margin-left:auto;font-family:inherit;cursor:pointer;font-size:12px;font-weight:600;color:#a08464;background:#fdf6ee;border:1px solid #eeddc9;border-radius:8px;padding:4px 10px;transition:all .2s}
.cvs-app .sec-title .top-btn:hover{color:var(--main-d);border-color:var(--main);background:#fff4e8}
.cvs-app .sec p{margin:0 0 12px;color:#4b4239;font-size:14.5px}
.cvs-app .sec p:last-child{margin-bottom:0}
.cvs-app ol.bg-list{margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:11px}
.cvs-app ol.bg-list li{position:relative;padding:12px 14px 12px 46px;background:#fdf9f3;border:1px solid #f0e4d5;border-radius:12px;font-size:14px;color:#4b4239;transition:all .2s}
.cvs-app ol.bg-list li:hover{border-color:#e9cfa8;background:#fffaf2;transform:translateX(3px)}
.cvs-app ol.bg-list li .n{position:absolute;left:14px;top:12px;width:22px;height:22px;border-radius:7px;background:linear-gradient(135deg,#e8a35c,#d4813f);color:#fff;font-size:12px;font-weight:800;display:flex;align-items:center;justify-content:center}
.cvs-app ol.bg-list li strong{color:#b5602c;font-weight:700}
.cvs-app .table-wrap{overflow-x:auto;border-radius:14px;border:1px solid #f0e2d0;margin-top:6px}
.cvs-app table{border-collapse:collapse;width:100%;min-width:340px;font-size:14px}
.cvs-app thead th{background:linear-gradient(135deg,#fbead4,#f7ddc2);color:#8a5a2a;font-weight:800;padding:10px 14px;text-align:left;letter-spacing:.5px;white-space:nowrap}
.cvs-app tbody td{padding:9px 14px;border-top:1px solid #f4e9db;color:#4b4239}
.cvs-app tbody tr:nth-child(even){background:#fdfaf5}
.cvs-app tbody tr:hover{background:#fff6ea}
.cvs-app tbody td:first-child{font-weight:700;color:#c4743a;white-space:nowrap}
.cvs-app .staff-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.cvs-app .staff{border:1px solid var(--sc,#e9dcc9);border-radius:16px;padding:16px;background:linear-gradient(180deg,#fffdfb,#fdf8f2);position:relative;overflow:hidden;transition:all .25s}
.cvs-app .staff::after{content:"";position:absolute;right:-30px;top:-30px;width:90px;height:90px;border-radius:50%;background:var(--sc,#e9dcc9);opacity:.12}
.cvs-app .staff:hover{transform:translateY(-3px);box-shadow:0 10px 24px rgba(190,155,110,.18)}
.cvs-app .staff-hd{display:flex;align-items:center;gap:11px;margin-bottom:12px;position:relative;z-index:1}
.cvs-app .avatar{width:44px;height:44px;flex:0 0 auto;border-radius:14px;background:linear-gradient(135deg,var(--sc,#e9dcc9),#fff);border:2px solid var(--sc,#e9dcc9);display:flex;align-items:center;justify-content:center;font-size:19px;font-weight:800;color:#6b5340}
.cvs-app .staff-hd h4{margin:0;font-size:16.5px;color:#4b3a29;font-weight:800;letter-spacing:.5px}
.cvs-app .staff-hd .role{font-size:12px;color:#fff;background:var(--sc,#e9dcc9);border-radius:999px;padding:2px 9px;display:inline-block;margin-top:3px;font-weight:600;letter-spacing:.5px}
.cvs-app .staff dl{margin:0;position:relative;z-index:1}
.cvs-app .staff dl>div{display:flex;gap:9px;padding:5px 0;border-top:1px dashed #f1e6d7;font-size:13.5px}
.cvs-app .staff dl>div:first-child{border-top:none}
.cvs-app .staff dt{flex:0 0 62px;color:var(--sc,#c4743a);font-weight:700;text-align:right}
.cvs-app .staff dd{margin:0;color:#514639;flex:1}
.cvs-app .staff dd.limit{color:#c05656;font-weight:600}
.cvs-app .form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}
.cvs-app .field{display:flex;flex-direction:column;gap:6px}
.cvs-app .field.full{grid-column:1/-1}
.cvs-app .field label{font-size:13px;font-weight:700;color:#8a6f52;letter-spacing:.5px}
.cvs-app .field label span{color:#c4743a}
.cvs-app .field input[type=text],.cvs-app .field textarea{width:100%;font-family:inherit;font-size:14px;padding:9px 12px;border:1px solid #e6d8c8;border-radius:11px;background:#fffdfa;color:#3b3530;transition:all .2s;resize:vertical;line-height:1.65}
.cvs-app .field input:focus,.cvs-app .field textarea:focus{outline:none;border-color:var(--main);box-shadow:0 0 0 3px rgba(216,138,78,.15);background:#fff}
.cvs-app .field input::placeholder,.cvs-app .field textarea::placeholder{color:#c4b6a5}
.cvs-app .sc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
.cvs-app .sc-card{font-family:inherit;text-align:left;cursor:pointer;border:1.6px solid #ecdcc9;border-radius:13px;background:#fffdfa;padding:13px 15px;transition:all .22s;position:relative}
.cvs-app .sc-card:hover{border-color:#e0b988;background:#fffaf2;transform:translateY(-2px);box-shadow:0 6px 16px rgba(216,138,78,.13)}
.cvs-app .sc-card.active{border-color:var(--main);background:linear-gradient(135deg,#fff4e8,#ffece0);box-shadow:0 0 0 3px rgba(216,138,78,.14)}
.cvs-app .sc-card.active::before{content:"✓";position:absolute;right:11px;top:10px;width:20px;height:20px;border-radius:50%;background:var(--main);color:#fff;font-size:12px;font-weight:800;display:flex;align-items:center;justify-content:center}
.cvs-app .sc-card .day{display:inline-block;font-size:12px;font-weight:800;color:#fff;background:linear-gradient(135deg,#e8a35c,#d4813f);border-radius:7px;padding:2px 9px;margin-bottom:7px;letter-spacing:.5px}
.cvs-app .sc-card .txt{font-size:13.5px;color:#5c5148;line-height:1.6}
.cvs-app #custom-scenario-box{display:none;margin-top:13px;padding-top:13px;border-top:1px dashed #ecdcc9}
.cvs-app textarea.output-area{width:100%;min-height:170px;max-height:340px;resize:vertical;font-family:inherit;font-size:14px;line-height:1.85;color:#4b4239;background:#fdfaf5;border:1.6px dashed #e6d0b4;border-radius:14px;padding:16px 18px;white-space:pre-wrap;word-break:break-word;transition:all .2s;overflow:auto;display:block}
.cvs-app textarea.output-area:focus{outline:none}
.cvs-app textarea.output-area.filled{border-style:solid;border-color:#dfc19c;background:#fffdf9}
.cvs-app textarea.output-area::placeholder{color:#c0b19f;font-size:13.5px;line-height:1.75}
.cvs-app .btn-row{display:flex;flex-wrap:wrap;gap:12px;margin-top:16px;justify-content:center}
.cvs-app .act-btn{font-family:inherit;cursor:pointer;border:none;border-radius:12px;padding:11px 26px;font-size:14.5px;font-weight:800;letter-spacing:1px;color:#fff;transition:all .22s;position:relative;box-shadow:0 4px 12px rgba(0,0,0,.1)}
.cvs-app .act-btn:hover{transform:translateY(-2px);box-shadow:0 8px 20px rgba(0,0,0,.16)}
.cvs-app .act-btn:active{transform:translateY(0);box-shadow:0 3px 8px rgba(0,0,0,.12)}
.cvs-app .act-btn.confirm{background:linear-gradient(135deg,#e9a35c,#d4813f)}
.cvs-app .act-btn.copy{background:linear-gradient(135deg,#7fb3cc,#5a8fa8)}
.cvs-app .act-btn.clear{background:linear-gradient(135deg,#d9909a,#c07a8a)}
.cvs-app .act-btn.done{background:linear-gradient(135deg,#8fb886,#6da06a)}
.cvs-app .tip{text-align:center;font-size:12.5px;color:#a89478;margin-top:12px;letter-spacing:.5px}
@media (max-width:640px){.cvs-app .hd h1{font-size:23px}.cvs-app .staff-grid{grid-template-columns:1fr}.cvs-app .form-grid{grid-template-columns:1fr}.cvs-app .sc-grid{grid-template-columns:1fr}.cvs-app .nav{padding:12px 14px;gap:7px}.cvs-app .nav-btn{padding:6px 12px;font-size:12.5px}.cvs-app .wrap{padding:16px 13px 24px;gap:16px}.cvs-app .sec{padding:17px 15px 19px}.cvs-app .sec-title{font-size:16.5px}.cvs-app .btn-row{gap:9px}.cvs-app .act-btn{padding:10px 18px;font-size:13.5px;flex:1;min-width:100px}}
</style>
<div class="cvs-app" id="cvs-app">
<header class="hd" id="cvs-top">
<div class="badge">SPECIAL STORE</div>
<h1>24小时便利店</h1>
<p>竭诚为您服务</p>
</header>
<nav class="nav">
<button type="button" class="nav-btn" data-target="#sec-bg">社会背景</button>
<button type="button" class="nav-btn" data-target="#sec-store">便利店介绍</button>
<button type="button" class="nav-btn" data-target="#sec-staff">店员介绍</button>
<button type="button" class="nav-btn" data-target="#sec-player">玩家面板</button>
<button type="button" class="nav-btn" data-target="#sec-scenario">开场情景</button>
<button type="button" class="nav-btn" data-target="#sec-output">复制输出</button>
</nav>
<div class="wrap">
<section class="sec" id="sec-bg" style="--accent:#6a9bb5">
<h2 class="sec-title"><span class="ico">世</span>一、社会背景<button type="button" class="top-btn" data-target="#cvs-top">↑ 回到顶部</button></h2>
<ol class="bg-list">
<li><span class="n">1</span><strong>经济形势：</strong>近两年全球性经济衰退蔓延至国内，失业率飙升至近十年峰值，大量企业倒闭或大规模裁员。</li>
<li><span class="n">2</span><strong>就业困境：</strong>应届大学生毕业即失业成为普遍现象，中年职员被优化后难以再就业，零工经济盛行但收入微薄。</li>
<li><span class="n">3</span><strong>物价压力：</strong>房租、食品、教育、医疗等基本生活成本持续上涨，普通家庭入不敷出，积蓄快速消耗。</li>
<li><span class="n">4</span><strong>道德松动：</strong>在生存压力下，社会风气逐渐转变，灰色产业暗中滋生，人们对边缘行为的容忍度提高。</li>
<li><span class="n">5</span><strong>执法现状：</strong>相关部门在明面上维持打击姿态，但实际执法力度因经济困境明显减弱，只要不引发公众事件便鲜少干预。</li>
</ol>
</section>
<section class="sec" id="sec-store" style="--accent:#d98a4e">
<h2 class="sec-title"><span class="ico">店</span>二、便利店介绍<button type="button" class="top-btn" data-target="#cvs-top">↑ 回到顶部</button></h2>
<ol class="bg-list">
<li><span class="n">1</span><strong>名称与位置：</strong>店名「24小时便利店」，坐落于城市边缘老旧居民区，周边是密集的出租屋与老小区，人流以底层劳动者和租客为主。</li>
<li><span class="n">2</span><strong>店面规模：</strong>约四十平米，装修陈旧但整洁，货架陈列日常用品、烟酒、零食、饮料和速食品。</li>
<li><span class="n">3</span><strong>经营者：</strong>店长姓张，五十多岁秃顶中年男人，原为普通小店主，因连锁便利店挤压濒临倒闭，后从外地引入特殊经营模式。</li>
<li><span class="n">4</span><strong>运营方式：</strong>表面与普通便利店无异，特殊服务仅面向「懂行」熟客。结账时小票印有消费金额与对应服务代码，当消费金额超过一定数目，店员可以给顾客提供一些特殊服务。</li>
<li><span class="n">5</span><strong>私密空间：</strong>收银台后方原员工休息室被改造为私密隔间，内设简易床垫、湿巾、纸巾等。</li>
<li><span class="n">6</span><strong>员工激励：</strong>每完成一单，店员按比例抽取提成作为小费，因此店员有强烈动机引导顾客提高消费金额，渴望顾客高消费。</li>
</ol>
<p style="margin-top:16px;font-weight:800;color:#b5602c;font-size:14.5px;letter-spacing:.5px">▎定价体系（消费金额可累加享受对应服务）</p>
<div class="table-wrap">
<table>
<thead><tr><th>消费金额</th><th>可享服务</th></tr></thead>
<tbody>
<tr><td>100元</td><td>隔衣摸胸</td></tr>
<tr><td>500元</td><td>亲吻</td></tr>
<tr><td>800元</td><td>伸衣摸胸</td></tr>
<tr><td>1000元</td><td>摸小穴</td></tr>
<tr><td>1500元</td><td>手交</td></tr>
<tr><td>2000元</td><td>足交</td></tr>
<tr><td>3000元</td><td>口交</td></tr>
<tr><td>4000元</td><td>戴套做爱</td></tr>
<tr><td>5000元</td><td>无套做爱</td></tr>
<tr><td>10000元</td><td>无限制做爱含肛交</td></tr>
</tbody>
</table>
</div>
</section>
<section class="sec" id="sec-staff" style="--accent:#d98aa0">
