div.group.ml-0{
  border-left:2px solid rgba(176,138,40,.4) !important;border-radius:0 8px 8px 0 !important;
  transition:border-color .25s,background .25s !important;
}
div.group.ml-0:hover{border-left-color:#a87f1e !important;background:rgba(255,255,255,.55) !important;}
div.group img.rounded-full{
  border:2px solid #b8902e !important;box-shadow:0 1px 5px rgba(0,0,0,.15) !important;
}
div.text-sm.text-grey-600 span.font-bold{color:#9a7826 !important;}
span.text-\[10px\]{
  color:#9a7720 !important;background:rgba(176,138,40,.15) !important;
  border-radius:4px !important;padding:1px 5px !important;
}
div.break-all{color:#574c30 !important;}
div.text-xs.text-grey-600{color:#766943 !important;}
button.text-gray-400{color:#766943 !important;transition:color .2s,transform .15s !important;}
button.text-gray-400:hover{color:#a87f1e !important;transform:scale(1.08) !important;}
button.text-gray-400 svg{transition:transform .15s !important;}
button.text-gray-400:active svg{transform:scale(1.3) !important;}
span.cursor-pointer{color:#a87f1e !important;transition:color .2s !important;}
span.cursor-pointer:hover{color:#b8902e !important;}
div.ml-8.border-l{border-left:2px solid #a07d22 !important;}

/* ═══ 移动端微调 ═══ */
@media (max-width:480px){
  .sticky.w-full.top-0.flex.items-center{box-shadow:0 1px 6px rgba(0,0,0,.15) !important;}
  div:has(> div > #ai-chat-input){border-radius:10px !important;box-shadow:0 2px 8px rgba(0,0,0,.14) !important;}
}
/* ════════ 晴空学院 · 制卡师聊天框美化 ════════ */
/* 卡牌护套质感 · SVG SMIL 动画 · 移动端友好 */

/* ── 隐藏聊天框顶部颜色条(想保留就删掉这条) ── */
[class*="bg-[#F1CBCB]"],
[class*="bg-[#c9e1e9]"]{
  display:none !important;
}

/* ── 统一聊天框:浅蓝衬垫 + 卡牌护套投影 ── */
.bg-gray-100\/90.relative.inline-block{
  background:rgba(246,239,217,.55) !important;
  border:1px solid rgba(176,138,40,.5) !important;
  border-radius:14px !important;
  box-shadow:0 4px 18px rgba(0,0,0,.14) !important;
  transition:box-shadow .3s,border-color .3s !important;
}
.bg-gray-100\/90.relative.inline-block:hover{
  border-color:#b8902e !important;
  box-shadow:0 6px 24px rgba(176,138,40,.2) !important;
}

/* ── 单独输入框:faint 暖金调,区分 AI 输出 ── */
.bg-gray-100\/90.relative.inline-block:not(.chat-answer-container .bg-gray-100\/90){
  background:linear-gradient(135deg,rgba(236,226,198,.62),rgba(246,239,217,.55)) !important;
  border-color:rgba(176,138,40,.45) !important;
}

/* ── 主文本:浅底→深字,确保可读(无 text-shadow) ── */
.markdown-body{
  color:#3a3320 !important;
}

/* ── 底部附加元素 ── */
.MuiButtonBase-root.MuiButton-root.MuiButton-text.MuiButton-textPrimary{
  color:#9a7720 !important;
  border-radius:6px !important;
  font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',''PingFang SC'',''Microsoft YaHei'',sans-serif !important;
  transition:background .2s !important;
}
.MuiButtonBase-root.MuiButton-root.MuiButton-text.MuiButton-textPrimary:hover{
  background:rgba(176,138,40,.1) !important;
}
.MuiTypography-root.MuiTypography-body2.css-6c0gf2{
  color:#675b38 !important;
  font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',''PingFang SC'',''Microsoft YaHei'',sans-serif !important;
}
.text-orange-500{
  color:#9a7720 !important;
  font-weight:bold !important;
}

/* ── 自定义加载动画(SVG SMIL · 双环旋转) ── */
[class*="dot-flashing"]{
  display:none !important;
}
.flex.items-center.justify-center.w-6.h-5{
  position:relative !important;
  width:100% !important;
  height:64px !important;
  background:linear-gradient(168deg,#f6f0d9,#f3ead2 70%,#f3ead2) !important;
  border:1px solid #a07d22 !important;
  border-radius:6px !important;
  box-shadow:inset 0 0 38px rgba(176,138,40,.10) !important;
}
.flex.items-center.justify-center.w-6.h-5::before{
  content:'''' !important;
  position:absolute !important;
  left:50% !important;
  top:50% !important;
  transform:translate(-50%,-50%) !important;
  width:54px !important;
  height:54px !important;
  background:url(''data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><circle cx="50" cy="50" r="42" fill="none" stroke="%23d8b24a" stroke-width="3" stroke-dasharray="5 11" stroke-linecap="round"><animateTransform attributeName="transform" type="rotate" from="0 50 50" to="360 50 50" dur="3s" repeatCount="indefinite"/></circle><circle cx="50" cy="50" r="29" fill="none" stroke="%234f93d4" stroke-width="3" stroke-dasharray="22 16" stroke-linecap="round"><animateTransform attributeName="transform" type="rotate" from="0 50 50" to="-360 50 50" dur="2s" repeatCount="indefinite"/></circle><circle cx="50" cy="50" r="8" fill="%234f93d4"><animate attributeName="r" values="6;10;6" dur="1.4s" repeatCount="indefinite"/><animate attributeName="opacity" values="0.5;1;0.5" dur="1.4s" repeatCount="indefinite"/></circle></svg>'') center/contain no-repeat !important;
}
/* CSP 占位:若平台拦截 data: SVG,可改为同尺寸 PNG/图床链接 */

/* ── 移动端微调 ── */
@media (max-width:480px){
  .bg-gray-100\/90.relative.inline-block{
    border-radius:11px !important;
    box-shadow:0 3px 12px rgba(0,0,0,.13) !important;
  }
  .flex.items-center.justify-center.w-6.h-5{height:52px !important;}
  .flex.items-center.justify-center.w-6.h-5::before{
    width:44px !important;height:44px !important;
  }
}

/* ── 低动效:换单环慢转(不完全关闭) ── */
@media (prefers-reduced-motion:reduce){
  .flex.items-center.justify-center.w-6.h-5::before{
    background-image:url(''data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><circle cx="50" cy="50" r="38" fill="none" stroke="%234f93d4" stroke-width="3" stroke-dasharray="9 15" stroke-linecap="round"><animateTransform attributeName="transform" type="rotate" from="0 50 50" to="360 50 50" dur="6s" repeatCount="indefinite"/></circle><circle cx="50" cy="50" r="7" fill="%23d8b24a" opacity="0.85"/></svg>'') !important;
  }
}
/* ── 外层气泡隐形,内容面板直接当对话框,缝隙归零 ── */
.bg-gray-100\/90.relative.inline-block{
  background:transparent !important;
  border:none !important;
  box-shadow:none !important;
  padding:0 !important;
}
.bg-gray-100\/90.relative.inline-block:not(.chat-answer-container .bg-gray-100\/90){
  background:transparent !important;
  border:none !important;
}
.markdown-body{
  margin:0 !important;
}
.mb-2 > .shrink-0.w-10.h-10 {
    display: none;
}


/* ════════════ HTML 数据面板：状态栏 / 卡包·卡组包 / 系统提示 ════════════ */
/* 装备卡气泡参考克苏鲁 tooltip，适配晴空学院浅蓝描金主题 */

details.pack,details.sys{
  margin:7px 0 !important;
  border:1px solid #b8902e !important;
  border-top:2px solid #a87f1e !important;
  border-radius:5px !important;
  background:linear-gradient(160deg,#f6f0d9,#f3ead2) !important;
  box-shadow:0 3px 10px rgba(0,0,0,.16) !important;
  overflow:hidden !important;
}
details.pack>summary,details.sys>summary{
  cursor:pointer !important;list-style:none !important;text-align:center !important;
  font-family:''KaiTi'',''STKaiti'',''Noto Serif SC'',serif !important;
  font-size:16px !important;font-weight:700 !important;letter-spacing:3px !important;
  color:#b8902e !important;padding:11px 16px !important;
  background:linear-gradient(90deg,rgba(176,138,40,.08),rgba(176,138,40,.20),rgba(176,138,40,.08)) !important;
  border-bottom:1px solid rgba(176,138,40,.30) !important;
}
details.pack>summary::-webkit-details-marker,details.sys>summary::-webkit-details-marker{display:none !important;}
details.pack>summary::before{content:''❐ '' !important;color:#a87f1e !important;}
details.pack>summary::after{content:'' ❐'' !important;color:#a87f1e !important;}
details.sys>summary::before{content:''✉ '' !important;color:#a87f1e !important;}
details.sys>summary::after{content:'' ✉'' !important;color:#a87f1e !important;}
details.pack .s,details.sys .s{padding:6px 14px 12px !important;}

details.status{overflow:visible !important;}
details.status .s{
  border:1px solid #b8902e !important;border-top:none !important;
  border-radius:0 0 5px 5px !important;
  background:linear-gradient(170deg,#f6f0d9,#f3ead2) !important;
  box-shadow:0 4px 10px rgba(0,0,0,.13) !important;
  padding:6px 14px 12px !important;
  overflow:visible !important;
}

details.status .s>t,details.pack .s>t,details.sys .s>t{
  display:block !important;text-align:center !important;
  font-family:''KaiTi'',''STKaiti'',''Noto Serif SC'',serif !important;
  font-size:16px !important;font-weight:700 !important;letter-spacing:2px !important;
  color:#b8902e !important;margin:9px 0 5px !important;
}
details.status .s>t::before,details.pack .s>t::before,details.sys .s>t::before{content:''━ '' !important;color:rgba(176,138,40,.4) !important;}
details.status .s>t::after,details.pack .s>t::after,details.sys .s>t::after{content:'' ━'' !important;color:rgba(176,138,40,.4) !important;}

details.status .s>r,details.pack .s>r,details.sys .s>r{
  display:block !important;position:relative !important;
  font-size:15px !important;line-height:1.8 !important;color:#3a3320 !important;
  padding:2px 2px 2px 3px !important;
}
details.status .s>r::before,details.pack .s>r::before,details.sys .s>r::before{
  content:'''' !important;position:absolute !important;left:3px !important;top:.74em !important;
  display:none !important;
}
details.status .s>r.i{margin:0 0 0 5px !important;padding-left:12px !important;border-left:1.5px solid rgba(176,138,40,.30) !important;color:#574c30 !important;font-size:14.5px !important;}
details.status .s>r.i::before{display:none !important;}
details.status .s>r.d{color:#766943 !important;font-size:13.5px !important;font-style:italic !important;padding-left:4px !important;}
details.status .s>r.d::before{display:none !important;}

details.status .s>hr,details.pack .s>hr,details.sys .s>hr{
  border:none !important;height:1px !important;
  background:linear-gradient(90deg,transparent,rgba(176,138,40,.5),transparent) !important;
  margin:9px 0 3px !important;
}

/* ════════════ 装备卡 · 气泡网格 ════════════ */
.eqg{display:flex !important;flex-wrap:wrap !important;gap:6px !important;margin:7px 0 3px !important;}
eq{
  display:inline-flex !important;align-items:center !important;position:relative !important;
  padding:5px 10px 5px 8px !important;
  border:1px solid rgba(176,138,40,.30) !important;border-left:3px solid #b08a26 !important;
  border-radius:0 5px 5px 0 !important;
  background:rgba(176,138,40,.07) !important;
  font-size:13.5px !important;line-height:1.3 !important;color:#3a3320 !important;
  cursor:pointer !important;transition:background .15s,box-shadow .15s !important;
}
eq::before{content:attr(p) !important;font-size:11px !important;color:#766943 !important;margin-right:6px !important;}
eq:hover,eq:active,eq:focus{background:rgba(176,138,40,.17) !important;box-shadow:0 2px 9px rgba(0,0,0,.22) !important;}
eq.o{border-left-style:dashed !important;border-left-color:#bcae82 !important;background:rgba(175,165,135,.09) !important;color:#857850 !important;cursor:default !important;}
eq.o:hover,eq.o:active,eq.o:focus{background:rgba(175,165,135,.09) !important;box-shadow:none !important;}

eq>tip{
  position:absolute !important;bottom:calc(100% + 9px) !important;left:50% !important;
  transform:translateX(-50%) translateY(6px) !important;
  opacity:0 !important;pointer-events:none !important;
  width:188px !important;padding:10px 13px !important;
  border-radius:7px !important;background:#f6f0d9 !important;
  border:1px solid #b8902e !important;border-top:2px solid #a87f1e !important;
  box-shadow:0 6px 18px rgba(0,0,0,.30) !important;
  font-size:13px !important;line-height:1.75 !important;font-weight:400 !important;
  color:#3a3320 !important;white-space:normal !important;text-align:left !important;
  z-index:60 !important;transition:opacity .22s,transform .22s !important;
}
eq>tip::before{
  content:attr(p) !important;display:block !important;text-align:center !important;
  font-family:''KaiTi'',''STKaiti'',''Noto Serif SC'',serif !important;
  font-size:13px !important;font-weight:700 !important;letter-spacing:2px !important;
  color:#b8902e !important;margin-bottom:5px !important;padding-bottom:4px !important;
  border-bottom:1px solid rgba(176,138,40,.28) !important;
}
eq>tip::after{
  content:'''' !important;position:absolute !important;top:100% !important;left:50% !important;
  transform:translateX(-50%) !important;border:6px solid transparent !important;border-top-color:#2e2716 !important;
}
eq:hover>tip,eq:active>tip,eq:focus>tip{opacity:1 !important;transform:translateX(-50%) translateY(0) !important;pointer-events:auto !important;}

eq[q="不入流"]{border-left-color:#766943 !important;}
eq[q="黑铁"]{border-left-color:#7e7148 !important;}
eq[q="青铜"]{border-left-color:#b07a43 !important;}
eq[q="白银"]{border-left-color:#766943 !important;}
eq[q="黄金"]{border-left-color:#a87f1e !important;}
eq[q="铂金"]{border-left-color:#a87f1e !important;}
eq[q="钻石"]{border-left-color:#36b6c6 !important;}
eq[q="星耀"]{border-left-color:#e08b3a !important;}
eq[q="史诗"]{border-left-color:#9b6fc4 !important;}
eq[q="传奇"]{border-left-color:#c4543a !important;}
eq[q="神话"]{border-left-color:#b8862f !important;}
