eq[q="铂金"]>tip{border-top-color:#a87f1e !important;background-color:#f6f0d9 !important;background-image:url(''data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" fill="none"><g stroke="%234f93d4" fill="none" opacity="0.52"><circle cx="24" cy="24" r="17.5" stroke-width="0.75"/><path d="M24 11 L37 24 L24 37 L11 24 Z" stroke-width="0.85"/><circle cx="24" cy="24" r="2.5" fill="%234f93d4" stroke="none"/></g></svg>'') !important;background-repeat:no-repeat !important;background-position:bottom 6px right 6px !important;background-size:31px 31px !important;}
