#view-design .talent-card-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;border-bottom:1px dashed rgba(255,255,255,.06);padding-bottom:6px}
#view-design .talent-card-name{font-weight:800;font-size:15px}
#view-design .talent-card-rank{padding:2px 8px;border-radius:999px;font-size:12px;color:#0a0d0f;background:var(--chip,#7ce5b0);font-weight:900}
#view-design .talent-card-desc{font-size:13px;color:var(--muted);line-height:1.6;margin:0}
#view-design .lock-btn{position:absolute;bottom:6px;right:6px;background:none;border:none;font-size:18px;cursor:pointer;opacity:.5;transition:.2s}
#view-design .talent-card:hover .lock-btn,#view-design .talent-card.locked .lock-btn{opacity:1}
.popup-copy{position:fixed;inset:0;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;z-index:9999;opacity:0;pointer-events:none;transition:opacity .3s;backdrop-filter:blur(5px)}.popup-copy.show{opacity:1;pointer-events:auto}.popup-content{background:var(--panel);padding:24px;border-radius:12px;text-align:center;border:1px solid var(--border);box-shadow:0 10px 30px #000}.popup-content h3{margin:0 0 10px;color:var(--accent-2)}.popup-content p{margin:0 0 18px;color:var(--muted)}.popup-content button{padding:8px 16px;background:var(--accent);color:#0a0d0f;border:none;border-radius:8px;font-weight:700;cursor:pointer}
@media(max-width:768px){#view-design h1{font-size:26px}#view-design .tab-btn{padding:8px 12px}#view-design .hero-img{max-height:240px}#view-design .rank-btn{padding:6px 12px}#view-design #generate-talents-btn{width:92%}#view-design #full-talent-list{max-height:none;overflow:visible;padding:0;border:none;background:none}#view-design #talent-pool,#view-design .rank-group-body{grid-template-columns:1fr;gap:8px}#view-design .talent-card-back{box-shadow:none}#view-design .lock-btn{opacity:1;font-size:22px;padding:4px}}
.tsukkomi{font-size:.78em;font-style:italic;font-weight:400;line-height:1.5;opacity:.92;display:inline-block;vertical-align:baseline;margin:0 4px}
.tsukkomi-yellow{color:#d4a017}
.tsukkomi-blue{color:#2e7fb8}
.tsukkomi-purple{color:#8b5cf6}
.weird-note{font-family:''Ma Shan Zheng'',cursive;font-size:1.15em;color:#8aa046;display:inline-block;letter-spacing:3px;text-shadow:1px 1px 0 rgba(0,0,0,.7),0 0 10px rgba(138,160,70,.4);transform:rotate(-1.5deg);animation:weirdWobble 3.2s ease-in-out infinite;}
@keyframes weirdWobble{0%,100%{transform:rotate(-1.5deg) skewX(-2deg) translateY(0)}50%{transform:rotate(1.2deg) skewX(2deg) translateY(-2px)}}
