.lore-tip-btns{display:flex;gap:12px;justify-content:center;flex-wrap:wrap;}
.lore-tip-btn{font-family:''Montserrat'',''Noto Serif SC'',sans-serif;font-weight:700;font-size:0.9rem;padding:10px 20px;background:rgba(0,0,0,0.4);color:#fff;border:1px solid rgba(0,229,255,0.4);cursor:pointer;transition:.3s;clip-path:polygon(5px 0,100% 0,100% calc(100% - 5px),calc(100% - 5px) 100%,0 100%,0 5px);letter-spacing:1px;}
.lore-tip-btn:hover{border-color:var(--p3-blue);box-shadow:0 0 15px rgba(0,229,255,0.5);transform:translateY(-2px);}
