/* 更新日志按钮 & 侧边栏 */
.log-toggle-btn{position:fixed;top:16px;left:16px;width:42px;height:42px;border-radius:50%;background:rgba(2,8,19,0.8);border:1.5px solid var(--p3-blue);color:var(--p3-blue);font-family:''Cinzel'',serif;font-weight:900;font-size:0.75rem;letter-spacing:1px;cursor:pointer;z-index:500;display:flex;align-items:center;justify-content:center;transition:.3s;backdrop-filter:blur(4px);box-shadow:0 0 12px rgba(0,229,255,0.3);}
.log-toggle-btn:hover{background:var(--p3-blue);color:#020813;box-shadow:0 0 20px rgba(0,229,255,0.6);transform:scale(1.08);}
.log-sidebar{position:fixed;top:0;left:0;width:min(88vw,420px);height:100%;background:rgba(2,8,19,0.98);border-right:1px solid var(--p3-blue);z-index:9997;transform:translateX(-100%);transition:transform .35s cubic-bezier(0.7,0,0.3,1);display:flex;flex-direction:column;box-shadow:10px 0 40px rgba(0,0,0,0.6);}
.log-sidebar.show{transform:translateX(0);}
.log-sidebar-header{padding:16px 18px;border-bottom:1px solid rgba(0,229,255,0.2);display:flex;align-items:center;justify-content:space-between;flex-shrink:0;}
.log-sidebar-header h3{font-family:''Cinzel'',serif;color:var(--p3-blue);letter-spacing:3px;font-size:1.1rem;}
.log-sidebar-close{background:none;border:1px solid rgba(255,255,255,0.3);color:#fff;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:1rem;display:flex;align-items:center;justify-content:center;transition:.2s;}
.log-sidebar-close:hover{border-color:var(--mg-pink);color:var(--mg-pink);}
.log-sidebar-body{flex:1;overflow-y:auto;padding:18px 20px 40px;}
.log-sidebar-body::-webkit-scrollbar{width:4px;}
.log-sidebar-body::-webkit-scrollbar-thumb{background:var(--p3-blue);border-radius:2px;}
.log-date{font-family:''Cinzel'',serif;color:var(--gold);font-size:1rem;letter-spacing:2px;margin:22px 0 10px;padding-bottom:6px;border-bottom:1px dashed rgba(212,175,55,0.3);}
.log-date:first-child{margin-top:0;}
.log-list{list-style:none;padding:0 0 0 6px;}
ol.log-list{list-style:decimal inside;padding:0 0 0 6px;counter-reset:none;}
ol.log-list li{padding-left:0;}
ol.log-list li::before{content:none;}
.log-list li{color:#ccc;font-size:clamp(0.82rem,2vw,0.92rem);line-height:1.75;margin-bottom:8px;padding-left:14px;position:relative;}
ul.log-list li::before{content:''▸'';position:absolute;left:0;color:var(--p3-blue);font-size:0.7em;top:4px;}
.log-subtitle{color:var(--mg-pink);font-weight:900;font-size:0.92rem;margin:14px 0 8px;letter-spacing:1px;}
.log-backdrop{position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:9996;opacity:0;pointer-events:none;transition:opacity .3s;backdrop-filter:blur(2px);}
.log-backdrop.show{opacity:1;pointer-events:auto;}
@media(max-width:767px){.log-toggle-btn{top:10px;left:10px;width:36px;height:36px;font-size:0.65rem;}}
</style>
