function fill(){if(!identity)return;identity.innerHTML="";const curRace=raceSel%sraceSel.value:'''';const arr=(maps[birthplace.value]||[]).filter(o=>!o.races||!curRace||o.races.includes(curRace));arr.forEach(o=>{const op=document.createElement(''option'');op.value=o.value;op.textContent=o.text;identity.appendChild(op)});if(birthplace.value==="自定义"){const op=document.createElement(''option'');op.value="custom";op.textContent="自定义身份（请在下方输入框填写）";identity.appendChild(op)}if(typeof window.updatePreview===''function'')window.updatePreview()}const bpCustom=document.getElementById(''birthplace-custom'');const idCustom=document.getElementById(''identity-custom'');const raceSel=document.getElementById(''race-select'');const raceMap={''黑石城'':[''人类'',''精灵'',''矮人''],''魔物森林'':[''人类'',''精灵'',''吸血鬼'',''魅魔'',''哥布林''],''猩红熔炉'':[''人类'',''精灵'',''恶魔'',''吸血鬼''],''风神要塞'':[''人类'',''魔女''],''响尾草镇'':[''人类'',''精灵'',''矮人''],''凛冬雪山'':[''人类'',''精灵'',''女武神''],''圣都艾兰迪亚'':[''人类''],''农场镇'':[''人类'',''魔女'',''吸血鬼'',''欲魔''],''魔女镇'':[''人类'',''魔女'',''吸血鬼'',''欲魔''],''大坟墓'':[''人类'',''魔女'',''吸血鬼'',''欲魔''],''欲魔村'':[''人类'',''魔女'',''吸血鬼'',''欲魔''],''万魔殿'':[''人类'',''魔女'',''吸血鬼'',''欲魔''],''崩坏3·天命纪元'':[''人类'',''女武神''],''四海诸岛'':[''人类'',''鱼人''],''巴伦西亚'':[''人类'',''精灵'',''矮人''],''树星国'':[''人类'',''魔女''],''浩瀚洋'':[''人类'',''鱼人'',''人鱼''],''罗曼'':[''人类'',''兽人'',''精灵'',''矮人'',''半人马''],''阿比拉'':[''人类'',''兽人'',''精灵'',''矮人'',''魔女''],''奈赫卡拉'':[''人类'',''亡灵''],''自定义'':[''人类'',''魔女'',''欲魔'',''吸血鬼'']};function fillRace(){if(!raceSel)return;const cur=raceSel.value;raceSel.innerHTML="";(raceMap[birthplace.value]||[''人类'']).forEach(r=>{const op=document.createElement(''option'');op.value=r;op.textContent=r;raceSel.appendChild(op)});if([...raceSel.options].some(o=>o.value===cur))raceSel.value=cur;if(typeof window.updatePreview===''function'')window.updatePreview()}function syncBpCustom(){if(!bpCustom)return;bpCustom.style.display=birthplace.value==="自定义"%s''block'':''none'';if(typeof window.updatePreview===''function'')window.updatePreview()}function syncIdCustom(){if(!idCustom||!identity)return;idCustom.style.display=(identity.value==="custom")%s''block'':''none'';if(typeof window.updatePreview===''function'')window.updatePreview()}if(birthplace)birthplace.addEventListener(''change'',()=>{fillRace();fill();syncBpCustom();syncIdCustom()});if(identity)identity.addEventListener(''change'',syncIdCustom);if(raceSel)raceSel.addEventListener(''change'',()=>{fill();syncIdCustom()});fillRace();fill();syncBpCustom();syncIdCustom();})();
(()=>{const previewBox=document.getElementById(''preview-box'');const toggle=document.getElementById(''preview-toggle'');const caret=document.getElementById(''caret'');const copyBtn=document.getElementById(''copy-button'');const pop=document.getElementById(''copy-popup'');function getVal(id,def="未设定"){const el=document.getElementById(id);return (el&&el.value.trim())%sel.value.trim():def}function getSel(id,def="未设定"){const el=document.getElementById(id);return el%sel.options[el.selectedIndex].text:def}function build(){const name=getVal(''player-name'');const gender=getSel(''player-gender'');const age=parseInt(getVal(''player-age'',''21''),10);const race=getSel(''race-select'');const birthSel=document.getElementById(''birthplace-select'');let birth=birthSel%sbirthSel.options[birthSel.selectedIndex].text:''未设定'';if(birthSel&&birthSel.value==="自定义"){const bpc=document.getElementById(''birthplace-custom'');birth=(bpc&&bpc.value.trim())%sbpc.value.trim():''自定义出身地（未填写）''}let ident="未选择";const identSel=document.getElementById(''identity-select'');if(identSel&&identSel.options.length){ident=identSel.options[identSel.selectedIndex].text}if(identSel&&identSel.value==="custom"){const idc=document.getElementById(''identity-custom'');ident=(idc&&idc.value.trim())%sidc.value.trim():''自定义身份（未填写）''}const body=getVal(''player-body'');const face=getVal(''player-face'');const outfit=getVal(''player-outfit'');const mark=getVal(''player-special-mark'',''无'');const opening=getVal(''player-opening'',''默认开局'');const per=getVal(''player-personality'');const xp=getVal(''player-xp'');const motto=getVal(''player-motto'');const other=getVal(''player-other'',''无'');const antiSnatch=document.getElementById(''toggle-anti-snatch'')&&document.getElementById(''toggle-anti-snatch'').checked%s''(开启)'':''(关闭)'';const lewdStyle=document.getElementById(''toggle-lewd-style'')&&document.getElementById(''toggle-lewd-style'').checked%s''(开启)'':''(关闭)'';const npcMemory=document.getElementById(''toggle-npc-memory'')&&document.getElementById(''toggle-npc-memory'').checked%s''(开启)'':''(关闭)'';const taskSystem=document.getElementById(''toggle-task-system'')&&document.getElementById(''toggle-task-system'').checked%s''(开启)'':''(关闭)'';const hardMode=document.getElementById(''toggle-hard-mode'')&&document.getElementById(''toggle-hard-mode'').checked%s''(开启)'':''(关闭)'';const diceMode=document.getElementById(''toggle-dice-mode'')&&document.getElementById(''toggle-dice-mode'').checked%s''(开启)'':''(关闭)'';const cotMode=document.getElementById(''toggle-cot'')&&document.getElementById(''toggle-cot'').checked%s''(开启)'':''(关)'';const talents=window.__selectedTalents&&window.__selectedTalents.length%swindow.__selectedTalents.map(t=>`  - 【${t.name}（${t.rank}）】：${t.desc}`).join(''\n''):'' 未选择'';const txt=`### 玩家配置 ###\n--------------------\n【姓名】：${name}\n【性别】：${gender}\n【年龄】：${isNaN(age)%s''21'':age}\n【种族】：${race}\n【出身】：${birth} - ${ident}\n【外貌】：身材(${body})，面部(${face})，穿搭(${outfit})，特殊标记(${mark})\n【开局】：${opening}\n--------------------\n【性格】：${per}\n【XP】：${xp}\n【格言】：${motto}\n【其他】：${other}\n--------------------\n【天赋】：\n${talents}\n--------------------\n防抢话${antiSnatch}\n发情文风${lewdStyle}\nNPC记忆${npcMemory}\n任务生成${taskSystem}\n困难模式${hardMode}\n骰子模式${diceMode}\n思维链${cotMode}`;if(previewBox)previewBox.textContent=txt}function update(){build()}window.updatePreview=update;[''player-name'',''player-gender'',''player-age'',''race-select'',''birthplace-select'',''identity-select'',''player-body'',''player-face'',''player-outfit'',''player-special-mark'',''player-opening'',''player-personality'',''player-xp'',''player-motto'',''player-other'',''toggle-anti-snatch'',''toggle-lewd-style'',''toggle-npc-memory'',''toggle-task-system'',''toggle-hard-mode'',''toggle-dice-mode'',''toggle-cot'',''birthplace-custom'',''identity-custom''].forEach(id=>{const el=document.getElementById(id);if(el){el.addEventListener(''input'',update);el.addEventListener(''change'',update)}});if(toggle)toggle.addEventListener(''click'',()=>{const open=previewBox.style.display!==''none'';previewBox.style.display=open%s''none'':''block'';caret.textContent=open%s''▶'':''▼''});if(copyBtn)copyBtn.addEventListener(''click'',()=>{build();const ta=document.createElement(''textarea'');ta.value=previewBox.textContent;ta.style.position=''fixed'';ta.style.opacity=''0'';document.body.appendChild(ta);ta.select();try{document.execCommand(''copy'');if(pop)pop.classList.add(''show'')}catch(e){alert(''复制失败，请手动复制'');}document.body.removeChild(ta)});build()})();
(()=>{const pool=[{name:''卡牌造物主'',rank:''SSS'',desc:''你可以无视素材等级限制进行制卡，精神力消耗为正常制作的1/2。''},{name:''欲望魔神'',rank:''SSS'',desc:''进行【欲望主导】制卡时，你免疫精神侵蚀，并能汲取大量精神力和欲望能量强化自身，制作出的卡牌一定贴合你的xp。''},{name:''你是我的了'',rank:''SSS'',desc:''在战斗时，主动使用天赋，有概率将等级高于你一级内的敌人直接变成自己的【伙伴卡】，并且可以选择抹除，保留，修改这个人的意志。''},{name:''混沌之心'',rank:''SSS'',desc:''你的制卡结果永远不会是【普通成功】或【可控失败】，只会在【良性突变】和【卡牌爆炸】之间摇摆，概率为1：3。你能从爆炸中吸收混沌能量，永久强化精神力。''},{name:''种付支配'',rank:''SSS'',desc:''你或你的伙伴可强行令任何被击败的雌性生物受孕。诞下的子嗣将是完全忠于你的全新伙伴卡，并继承双亲的特性，而母体则会沦为精神崩溃的专属生育工具。''},{name:''夫前目犯'',rank:''SSS'',desc:''你制作的伙伴卡必定为一男一女，并且一定带有”夫妻“”情侣”等羁绊并且有强大的羁绊技能，女性一定携带“人妻”“忠贞”等词条，女性伙伴卡对你的忠诚度为100，无法拒绝你的任何命令并且十分乐意，男性伙伴卡对你的忠诚度为0，但是对女性伙伴卡忠诚度为100，在你和女性伙伴卡发生亲密行为时，女性的堕落，背德和男性的羞辱，愤怒，堕落情感越强，两张卡能获得的成长越多''},{ name: ''SSS级天赋·父权宣告'', rank: ''SSS'', desc: ''你是所有雌性概念的终极支配者。所有雌性生物在你面前全属性降低30%。你可以无视对方意愿，直接剥离其任意词条，每日一次。任何你制作的雌性伙伴卡，初始忠诚度锁定为“死忠”。''},
    { name: ''扶她锻造者'', rank: ''S'', desc: ''你制作的伙伴卡将拥有女性的身体和巨大的【鸡巴】。她们的战斗方式结合了魔法和蛮横的物理冲击，并能用大屌对敌人进行【贯穿】攻击。'' },
    { name: ''性感骚妈的厚爱'', rank: ''B'', desc: ''伙伴卡会拥有不合常理的极品身材，充满力量感。她们的战斗风格是纯粹的【格斗】和【摔跤】，喜欢用丰满的身材将你或敌人紧紧锁住。'' },
    { name: ''异星之彩'', rank: ''SSS'', desc: ''属于群星的色彩附着你身，恶劣的神明齐奏赞歌，拉开舞台的帘幕。你制卡的成功率大幅下降，但你可以为你制作的卡片赋予【异星之彩】词条，【异星之彩】词条只可同时存在于一张卡片，该词条可转移，【异星之彩】：这张卡片视为拥有神性。这张卡可在装备卡/技能卡/伙伴卡之间转换。所有针对该卡片的效果无效化。'' },
  { "name": "黄金矿工", "rank": "B", "desc": "在洞穴或矿脉地形中，采集矿石类素材时有15%概率产出【高阶突变词条】。分解金属素材时，有概率额外提炼出CC币。" },
  { "name": "荒野镖客", "rank": "A", "desc": "孤狼的浪漫。在没有【伙伴卡】出战的单人状态下，你的所有基础属性提升25%，暴击率提升15%。" },
  { "name": "套索大师", "rank": "C", "desc": "使用绳索类武器或卡牌时，极大地提升【束缚】状态的成功率。若目标为雌性或魔物娘，则束缚后自动附加极度敏感的【羞耻】debuff。" },
  { "name": "西部骑乘位", "rank": "A", "desc": "当你处于【骑乘】状态（骑马、驾驶载具卡，或在特殊互动中骑在目标身上）时，你的攻击必定暴击，且腰部与大腿力量绵绵不绝。" },
  { "name": "荒漠行者", "rank": "D", "desc": "在沙漠、戈壁等恶劣干旱地形中，水分流失速度减半，移动速度不受地形惩罚减免，且极易发现隐藏的地下水脉。" },
  { "name": "绞刑架幸存者", "rank": "S", "desc": "曾被吊死却奇迹生还。你的颈部极其坚韧，免疫一切窒息、绞杀类伤害。当你的HP归零时，有一次机会以1点HP强行锁血复活，并瞬间获得满额MP。" },
  { "name": "扑克脸", "rank": "C", "desc": "在进行【赌卡】或黑市讨价还价时，NPC极难看穿你的真实意图和底牌。交易成功率及“捡漏”捡到神卡的概率小幅提升。" },
  { "name": "宿醉狂暴", "rank": "B", "desc": "当你处于【中毒】或【醉酒】等负面状态时，你的痛觉被屏蔽，攻击力大幅提升，但命中率轻微下降。" },
  { "name": "狂野女牛仔", "rank": "A", "desc": "仅限女性和扶她。装备马靴、皮鞭或套索时，对目标造成额外30%的伤害；若使用皮鞭抽击，有概率直接将低等级敌人驯化为【奴隶】。" },
  { "name": "西部决斗礼仪", "rank": "S", "desc": "可以强制任何目标与你进行1v1对决。在此期间，双方均无法使用【伙伴卡】，且免疫一切外部伤害与治疗。" },
  { "name": "套索龟甲缚", "rank": "B", "desc": "你对绳索类装备有着极其变态的理解。使用套索技能时，不仅能100%触发【束缚】，还会让类人型目标陷入强烈的【发情】与【羞耻】状态。" },
  { "name": "马刺践踏", "rank": "B", "desc": "装备“牛仔靴/马刺”类装备卡时，对倒地或体型小于你的目标造成的伤害提升30%。若目标拥有“M体质”，连续踩踏会直接将其强行驯服。" },
  { "name": "警服崇拜", "rank": "C", "desc": "当你或你的伙伴卡穿戴“警长徽章”或“制服”时，制卡成功率提升，且所有攻击附带【威严】效果，极大削弱法外狂徒的抵抗意志。" },
  { "name": "左轮轮盘赌", "rank": "A", "desc": "技能卡冷却完毕时，有六分之一的概率该技能威力提升500%，但有六分之五的概率炸膛，扣除自身20%HP并陷入【爆衣】状态。" },
  { "name": "硝烟催情药", "rank": "C", "desc": "火器开火时的硝烟味会让你感到极度兴奋。战斗环境中的火属性魔法或枪械开火频率越高，你的敏捷、攻击力以及【欲望值】就越高。" },
  { "name": "烈马调教者", "rank": "A", "desc": "你在制作或对抗带有【野性】、【傲慢】标签的魔物娘/伙伴卡时，拥有绝对压制力。每次攻击都有概率削减其忠诚底线，最终将其变为你的专属“坐骑”。" },
  { "name": "雌雄双煞", "rank": "S", "desc": "当你队伍中只有一名异性伙伴卡，且你们都在被通缉时，你们的全属性提升50%，且脱战后可以通过“深入的体液交换”瞬间恢复满血满蓝。" },
  { "name": "酒馆艳遇体质", "rank": "C", "desc": "在酒馆或居住区，NPC主动向你搭讪、提供隐藏任务或特殊服务的概率提升。你制作的恢复类卡牌会自带微弱的【催情】效果。" },
  { "name": "黄金矿工的贪婪", "rank": "B", "desc": "你的眼里只有钱。遇到高价值素材或CC币时，无视所有精神类控制debuff；但如果有人抢你的战利品，你会陷入不死不休的【狂暴】。" },
  { "name": "黑市老千", "rank": "B", "desc": "在赌卡或黑市交易时，你可以偷偷用下位垃圾素材替换上位素材进行检定，有较高概率不被发现。被发现则直接进入肉搏战。" },
  { "name": "仙人掌绿洲", "rank": "C", "desc": "在沙漠地形中，你的体液会变得极其甘甜且具有强效恢复能力。你的伙伴卡可以通过“吸吮”你来快速回复HP和状态。" },
  { "name": "黄沙迷彩", "rank": "D", "desc": "在沙尘暴或沙漠环境中，只要你静止不动，就会自动进入【隐身】状态，非常适合用于发起偷袭或进行偷窥。" },
  { "name": "劣酒豪客", "rank": "C", "desc": "饮用劣质酒精类道具后，不仅不会中毒，反而会获得【霸体】效果，无视所有僵直，但事后有极大几率引发酒后乱性事件。" },
  { "name": "体温共享（极地特供）", "rank": "B", "desc": "在冰雪环境中，只要你与另一名处于【脱衣】状态的伙伴卡紧密相拥，双方的HP和MP将以极快的速度恢复，且会大幅增加羁绊与【发情】值。" },
  { "name": "卢恩符文刻印", "rank": "B", "desc": "你可以将古代卢恩符文直接刻在自己或伙伴卡的肉体上。每刻印一个符文，全属性提升5%，但被刻印部位会变得极其敏感，受到触摸时会产生强烈的快感与硬直。" },
  { "name": "女武神的青睐", "rank": "A", "desc": "你制作的女性战士类【伙伴卡】初始等级更高，且对你的忠诚度极难下降。当你在战斗中濒死时，她们会陷入【狂暴】并强行替你承受致命一击。" },
  { "name": "冰霜之子", "rank": "C", "desc": "你免疫一切【冻伤】、【减速】效果。在雪地环境中，你的隐蔽性极强，且冰属性魔法的MP消耗降低30%。" },
  { "name": "蜜酒豪饮者", "rank": "C", "desc": "饮用酒精类道具卡后，防御力翻倍，痛觉消失。但会大幅降低你的理智（SAN值），极易在酒后对身边的NPC或魔物娘做出“野蛮”行为。" },
  { "name": "霜巨人体魄", "rank": "S", "desc": "你的体型和肌肉密度异于常人。HP上限增加200%，免疫击退效果。在各种“贴身肉搏”或“深夜互动”中，你拥有绝对的体型压制力和破坏力。" },
  { "name": "盾女之誓", "rank": "B", "desc": "当你的队伍中存在持有“盾牌”的女性伙伴卡时，你受到的所有物理伤害由她代为承受。每次成功格挡，都会加深她对你的【依赖】与【服从】。" },
  { "name": "极寒凝视", "rank": "C", "desc": "你的眼神冷若冰霜。与你对视的低等级敌人有几率陷入【僵直】。在交涉时，这种冰冷的气质对某些拥有“M体质”的NPC有着致命的吸引力。" },
  { "name": "凛冬冬眠", "rank": "D", "desc": "在寒冷环境中睡眠时，你的伤势恢复速度是平时的五倍，甚至能断肢再生。但睡眠期间你将完全失去反抗能力，任由身边的伙伴卡摆布。" },
  { "name": "雪崩之势", "rank": "B", "desc": "你的重型武器攻击或徒手攻击带有“粉碎”效果，极易破坏敌人的盔甲和武器。如果敌方是女性，极大概率一击造成【爆衣】状态。" },
  { "name": "冰渊垂钓者", "rank": "C", "desc": "在冰层上打洞垂钓时，你总能钓上来一些奇奇怪怪的高级素材，包括但不限于：深海巨兽的触手、古代冻尸的器官，或是某种滑溜溜的催情海藻。" },
  { "name": "巨鲸猎手", "rank": "B", "desc": "对体型大于你的魔物造成的伤害提升40%。使用长柄武器或鱼叉时，必定附带【贯穿】效果，将其死死钉在原地。" },
  { "name": "冻骨巫医", "rank": "C", "desc": "使用动物骨骼和冰雪素材制卡时，必定生成带有【诅咒】或【毒性】的冰霜法术卡。这些法术会在冻结敌人肉体的同时，腐蚀他们的理智。" },
  { "name": "冰洋触手亲和", "rank": "B", "desc": "制作水系或海兽素材时，极大概率突变出带有【触手】词条的卡牌。在战斗中，这些触手会自动捆绑女性目标，强制灌注粘液并施加【高潮晕厥】状态。" },
  { "name": "雪女饲养员", "rank": "B", "desc": "冰雪系的女性魔物（如雪女、冰妖）对你天然抱有好感。如果你喂食她们你自身温热的“白色体液”，她们会心甘情愿地化作绝对忠诚的极品伙伴卡。" },
  { "name": "瓦尔哈拉的门票", "rank": "S", "desc": "当你的女性伙伴卡战死时，她的灵魂不会消散，而是化作半透明的女武神幽灵永远绑定在你的身体，成为身后灵。" },
  { "name": "冰原雪橇犬", "rank": "C", "desc": "使用锁链或项圈将战败的敌人（尤其是高傲的女性）套住拉雪橇时，你的移动速度大幅提升。她们爬得越屈辱，你在冰原上的状态就越好。" },
  { "name": "鲸骨束腰", "rank": "C", "desc": "用深海巨兽骨骼制作的装备。给女性伙伴卡穿上后，会强制改变其骨骼结构，使其胸部更挺拔、臀部更翘。降低少量HP上限，但大幅增加【魅惑】与拉仇恨能力。" },
  { "name": "海象皮脂肪", "rank": "C", "desc": "自带极高的天然寒冷抗性，完全免疫【冻伤】debuff，受到的冰属性伤害降低20%。" },
    { name: ''小马游戏鞍具师'', rank: ''B'', desc: ''伙伴卡能将敌人变成【人形小马】，为他们戴上鞍具和口衔。被转化的敌人会失去施法能力，只能四足奔跑，成为伙伴卡的坐骑。'' },
    { name: ''坐脸王座'', rank: ''A'', desc: ''伙伴卡的臀部拥有王座般的威严。她能跳到敌人脸上【坐脸】，造成【窒息】、【视野遮蔽】和【精神屈服】三重效果，是强大的单体控制技能。'' },
    { name: ''女王的衣橱'', rank: ''A'', desc: ''该天赋解锁一系列【女王/女主人】风格的卡牌外观。制作的伙伴卡能根据战况瞬间切换不同的SM服装（如乳胶、皮衣、芭蕾舞伶装），每套服装对应一种战斗模式。'' },
    { name: ''吞噬之口'', rank: ''S'', desc: ''伙伴卡能将嘴或下体变得巨大，直接【活吞】体型较小的敌人。被吞噬的敌人会在其体内被缓慢消化，成为她的养分。'' },
    { name: ''人偶师之线'', rank: ''A'', desc: ''伙伴卡能射出几乎看不见的【魔力丝线】，操控敌人的四肢，使其自相残杀或做出滑稽的动作。她视所有人为自己的提线木偶。'' },
    { name: ''军靴擦拭工'', rank: ''C'', desc: ''伙伴卡总是穿着一双锃亮的【长筒军靴】。她会强迫战败的敌人或你本人为她【舔靴】，从中获得满足感并恢复少量生命值。'' },
    { name: ''人间烟灰缸'', rank: ''D'', desc: ''伙伴卡有【吸烟】的习惯，并且会把烟头摁在你或敌人的身上。这是一种纯粹的【羞辱】技能，伤害不高，但侮辱性极强。'' },
    { name: ''财务榨取'', rank: ''A'', desc: ''制作的伙伴卡会变成【女王】或【大小姐】性格，她会不断向你索要金钱（游戏内货币）。你越“上贡”，她在战斗中就越强大，并能使用【金钱攻击】直接对敌人造成财富打击。'' },
    { name: ''败犬烙印'', rank: ''SS'', desc: ''每一次战败，都会在你的灵魂上留下一枚【败犬烙印】。在制卡时，你可以消耗一枚烙印，强行扭转一次词条冲突，极大增加成功率，甚至能化腐朽为神奇。'' },
    { name: ''支配者倒影'', rank: ''S'', desc: ''你崇拜着将你踩在脚下的强者。被敌人击败后，你可以复制对方的一个技能，并以此为蓝本，在制卡时创造出一张全新的技能卡。'' },
    { name: ''世界线的收束点'', rank: ''SSS'', desc: ''凡是你战败的，都将成为滋养你的养分。每次战斗失败后，系统会从无数“if线”中随机抽取三种“如果你赢了”的可能性，并将其中的奖励（如经验、金钱、掉落物）直接赋予给你。'' },
    { name: ''践踏权威'', rank: ''B'', desc: ''伙伴卡对【踩踏】行为有特殊偏好，尤其是踩脸。她们的技能多为地面范围攻击，能轻易破坏敌人的平衡，并对倒地的敌人造成巨大额外伤害。'' },
    { name: ''修女的神圣戒律'', rank: ''A'', desc: ''伙伴卡化身为禁欲又渴望惩戒罪人的【战斗修女】，身着暴露的改良修女服。她们使用十字架和圣水战斗，对恶魔和亡灵系敌人有特攻，并坚信你是需要被“净化”的罪人。'' },
    { name: ''羞辱真言'', rank: ''B'', desc: ''你制作的伙伴卡将精通【言语羞辱】，性格变得毒舌、刻薄。她们的战斗方式以精神攻击为主，每句骂声都能削弱敌人的意志力，同时让你感到一阵阵屈辱的兴奋。'' },
    { name: ''家政达人'', rank: ''D'', desc: ''擅长制作各种生活类伙伴卡，如会自动打扫的【扫帚仆人】、会自动烹饪的【厨刀小人】，毫无战斗力，但能极大提升生活品质。'' },
    { name: ''时尚先锋'', rank: ''C'', desc: ''专注于制作各种外观华丽、奇异的【时装】卡，防御力不高，但通常携带特效词条，能提供魅力、社交等方面的加成。'' },
    { name: ''圣歌咏唱'', rank: ''B'', desc: ''能将祝福祷文灌注进卡牌，制作出拥有【驱邪】、【庇护】、【治愈光环】的领域卡或装备卡。'' },
    { name: ''量产专家'', rank: ''B'', desc: ''牺牲质量换取数量。一次制卡可以消耗多份材料，批量生产出多张效果相同的、略低于正常品质的卡牌。适合为军队提供装备。'' },
    { name: ''孤高之作'', rank: ''A'', desc: ''制卡成功率不高，但一旦成功，必是精品。成品卡牌通常会带有【唯一】词条，无法被复制。'' },
    { name: ''傀儡师'', rank: ''B'', desc: ''擅长制作【人偶】伙伴卡，并通过【丝线】进行操控。可以制作出与真人无异的精致人偶。'' },
    { name: ''天气掌控者'', rank: ''S'', desc: ''能够制作出影响战场的天气类【领域卡】，如【祈雨】、【烈日】、【沙暴】、【雷云】，为特定属性的卡牌提供强大的主场优势。'' },
    { name: ''节俭持家'', rank: ''D'', desc: ''使用边角料或废弃材料制卡时，有极高的成功率，但成品威力通常较弱。总能把垃圾变成不那么垃圾的东西。'' },
    { name: ''粘液亲和'', rank: ''C'', desc: ''使用任何粘稠、流动的液体（如史莱姆粘液、树脂、沥青）作为材料，制作出的卡牌会附加【减速】、【粘滞】、【无法挣脱】等词条。'' },
    { name: ''骨骼工匠'', rank: ''B'', desc: ''使用各种生物的骸骨作为材料，能制作出比钢铁更坚硬的【骨质武器】和【骨质盔甲】，或直接召唤【骸骨战士】。'' },
    { name: ''吟游诗人的浪漫'', rank: ''C'', desc: ''能制作出各种【乐曲】卡，通过演奏发动效果，多为群体增益或减益，甚至能记录历史事件，召唤【历史残影】助战。'' },
    { name: ''炼金炸弹客'', rank: ''B'', desc: ''专注于制作各种效果的【炼金炸弹】卡，如冰冻弹、火焰弹、粘胶弹、烟雾弹等。'' },
    { name: ''宝石迷恋'', rank: ''A'', desc: ''使用宝石作为核心材料时，能完美激发其能量，制作出的法术卡威力倍增，装备卡必定附加华丽的元素抗性或攻击词条。'' },
    { name: ''武器大师'', rank: ''S'', desc: ''对所有类型的武器都有深刻理解。制作任何武器卡时，都有较高概率提升一个稀有度等级，并有几率领悟出该武器的专属【武器技能】词条。'' },
    { name: ''防具大师'', rank: ''S'', desc: ''对所有类型的防具有深刻理解。制作任何防具卡时，都能完美平衡重量与防御，并有几率附加【套装】词条，多件激活额外效果。'' },
    { name: ''侏儒工程师'', rank: ''B'', desc: ''擅长制作各种带有奇特效果的【机械装置】卡，效果强大但不稳定，有一定概率在使用时【爆炸】。'' },
    { name: ''精神塑造者'', rank: ''A'', desc: ''擅长制作【幻术】、【心灵冲击】、【读心】等精神系法术卡，能直接攻击敌人的意志。'' },
    { name: ''迷你王国'', rank: ''B'', desc: ''制作伙伴卡时，倾向于制作出体型微缩但能力不变的“迷你”版本，如【口袋巨龙】、【指尖哥布林军团】。'' },
    { name: ''触手爱慕'', rank: ''B'', desc: ''使用章鱼、乌贼、或任何带触手的魔物材料，能轻易制作出带有【束缚】、【缠绕】、【吸附】词条的装备或技能卡，以及【触手怪】伙伴卡。'' },
    { name: ''模块化天才'', rank: ''S'', desc: ''你制作的载具卡天生拥有额外的改装槽位，且其部件支持战斗中热插拔，能够根据战况瞬间切换形态与功能，是战场上的变形金刚。'' },
    { name: ''地行龙骑'', rank: ''A'', desc: ''对使用龙类、亚龙类及大型爬行魔物素材制作载具卡有特殊心得，成品更容易获得【龙鳞装甲】、【吐息炮】、【野性冲锋】等词条。'' },
    { name: ''浮空城之梦'', rank: ''A'', desc: ''在制作【飞行】或【浮空】类载具时，大幅降低MP消耗与材料要求，并有更高几率制作出可供多人搭乘的大型空中载具。'' },
    { name: ''废土工程师'', rank: ''B'', desc: ''擅长变废为宝，能够高效利用废铁、破损零件等【垃圾】级素材，拼凑出外形狂野但性能可靠的载具，尤其擅长制作冲撞车和武装摩托。'' },
    { name: ''过载专家'', rank: ''B'', desc: ''你制作的载具都能进行【过载】操作，短时间内爆发远超常规的性能，但会持续损失耐久度，甚至导致引擎永久性损伤。'' },
    { name: ''幽灵船长'', rank: ''B'', desc: ''使用亡灵或诅咒类素材制作载具时，有几率获得【幽魂形态】（物理闪避）、【恐吓光环】等词条，尤其擅长制作潜行类载具。'' },
    { name: ''熟练工'', rank: ''C'', desc: ''常年的流水线工作经验让你在制作通用型载具卡时，MP消耗略有降低，且成品质量稳定。'' },
    { name: ''深海调试'', rank: ''C'', desc: ''专精于水下与水面载具，制作的船只或潜艇拥有更好的密封性与抗压性，不易进水或被水压摧毁。'' },
    { name: ''摩托小子'', rank: ''D'', desc: ''你只对制作结构简单的双轮魔动车感兴趣，且成功率较高。制作更复杂的载具则会感到力不从心。'' },
    { name: ''扳手精通'', rank: ''E'', desc: ''在为载具卡添加【坚固】或【耐用】词条时，有微乎其微的几率提升词条效果。'' },
    { name: ''万物皆药'', rank: ''SSS'', desc: ''你的炼金术已触及法则层面。你可以用“一段记忆”、“一缕悲伤”甚至“一个谎言”作为核心素材，创造出效果扭曲现实、无法预测的禁忌药剂。'' },
    { name: ''因果炼金术'', rank: ''SS'', desc: ''能够制作出短暂操纵“运气”的道具卡。例如，必定成功的【幸运硬币】或必定失败的【厄运护符】，但使用后必然会在其他方面遭到反噬。'' },
    { name: ''瘟疫之源'', rank: ''S'', desc: ''你天生就是行走的灾厄。使用任何有毒素材制作道具卡，其毒性都会被数倍放大，并有极高几率附加【传染】、【变异】、【腐化】等恶性词条。'' },
    { name: ''双生药剂'', rank: ''S'', desc: ''制作任何药水类道具卡时，有一定几率额外生成一张效果完全相反的“双生卡”。例如，制作【巨力药水】时，可能附赠一张【虚弱药水】。'' },
    { name: ''爆破狂人'', rank: ''A'', desc: ''你对爆炸就是艺术的信条深信不疑。制作的所有炸弹、爆弹类道具卡，爆炸范围和伤害都显著提升，且有几率引发【连锁爆炸】。'' },
    { name: ''陷阱大师'', rank: ''A'', desc: ''你制作的陷阱类道具卡（符文、地雷、捕兽夹等）更难被侦测，触发条件更隐蔽，且效果往往比描述的更阴险。'' },
    { name: ''香氛魅惑'', rank: ''B'', desc: ''专精于制作各种信息素、催情香水、迷魂熏香等道具卡，能轻易操控他人情绪，使其陷入爱恋、恐惧或顺从，是交涉与审讯的利器。'' },
    { name: ''丰饶祝福'', rank: ''B'', desc: ''受到丰收女神的青睐，每次制作道具卡时，产出数量总是会比配方预期的多出一份。'' },
    { name: ''液体机械'', rank: ''SS'', desc: ''能够将金属与流体素材结合，制作出【液态金属】或【纳米机群】类的特殊道具卡。激活后可短暂构筑成武器、护盾甚至简易载具。'' },
    { name: ''军火巨头'', rank: ''S'', desc: ''专精于制作载具专用的【弹药卡】。这些道具卡可作为载具武器的弹药，提供穿甲、爆破、追踪等多种攻击特效。'' },
    { name: ''自毁协议'', rank: ''A'', desc: ''你可以在制作任何载具卡时，额外为其植入一张隐藏的【自爆】道具卡，可在载具被摧毁或主动引爆时触发，造成巨大范围伤害。'' },
    { name: ''便携式工事'', rank: ''B'', desc: ''擅长制作可快速部署的防御性道具卡，如【合金墙】、【斥力屏障发生器】、【自动炮塔】等，能瞬间改变战场地形。'' },
    { name: ''炼金气雾师'', rank: ''A'', desc: ''你能将药水与炸弹结合，制作出能大范围播撒治疗、毒雾或减益效果的【炼金气雾弹】。'' },
    { name: ''活体弹药'', rank: ''A'', desc: ''你可以将小型的、活的魔物（如史莱姆、尖叫蘑菇）直接封印成道具卡，作为投掷武器，命中后会释放其生物特性。'' },
    { name: ''奇迹卷轴'', rank: ''S'', desc: ''制作卷轴类道具卡时，有极小概率发生“奇迹突变”，使卷轴效果升华为更高阶的魔法，甚至可能随机召唤出强大的存在。'' },
    { name: ''圣油涂抹'', rank: ''B'', desc: ''专精于制作可以涂抹在武器或载具上的【附魔油】道具卡，短时间内为其附加元素伤害或特殊攻击效果。'' },
    { name: ''便携黑洞'', rank: ''SS'', desc: ''使用蕴含重力或空间属性的素材，有极小概率制作出一次性的【微型黑洞】道具卡，激活后会吞噬周围的一切。'' },
    { name: ''血肉诅咒'', rank: ''A'', desc: ''擅长使用血液、脏器等素材制作恶毒的诅咒道具。目标一旦中招，不仅会受到持续伤害，其身体还会发生恐怖的异变。'' },
    { name: ''拟态胶囊'', rank: ''B'', desc: ''可以制作出【万能胶囊】式的道具卡，能将非战斗物品（如房屋、家具）临时封入其中，方便携带。'' },
    { name: ''共生体'', rank: ''S'', desc: ''你能制作出特殊的【共生体】道具卡，使用后会与使用者（或其载具）结合，提供强大的属性和技能，但同时也会持续汲取生命力或精神力。'' },
    { name: ''时间沙漏'', rank: ''SS'', desc: ''使用蕴含时间之力的稀有素材，有几率制作出能小范围【加速】或【减速】时间的道具卡，效果结束后素材会彻底化为凡尘。'' },
    { name: ''不稳定化合物'', rank: ''C'', desc: ''你制作的药水和炸弹效果总是随机上下浮动，偶尔有惊喜，但更多的是惊吓。'' },
    { name: ''回收利用'', rank: ''D'', desc: ''使用任何道具卡后，有微小几率回收一部分基础素材。'' },
    { name: ''紧急维修套件'', rank: ''C'', desc: ''擅长制作能瞬间恢复载具少量耐久度的【维修包】道具卡。'' },
    { name: ''燃料专家'', rank: ''C'', desc: ''能将多种材料转化为载具可用的【能量块】道具卡，以补充载具的MP消耗。'' },
    { name: ''逃脱烟幕'', rank: ''D'', desc: ''制作【烟雾弹】类道具卡时，烟雾的遮蔽效果会更好一些。'' },
    { name: ''小发明家'', rank: ''D'', desc: ''你总喜欢在道具卡里加一些没什么用但很有趣的小功能，比如会唱歌的炸弹。'' },
    { name: ''防腐处理'', rank: ''E'', desc: ''你制作的食物和药水道具保质期会更长一些。'' },
    { name: ''二次利用'', rank: ''E'', desc: ''你制作的陷阱类道具有极小的概率在触发后不会被摧毁，可以回收再利用。'' },
    { name: ''应急食品'', rank: ''B'', desc: ''你可以将任何生物素材（无论多猎奇）制作成能提供特殊增益的【料理】道具卡，但食用者需要有极佳的心理承受能力。'' },
    { name: ''草药学徒'', rank: ''C'', desc: ''使用植物类素材制作治疗或增益类药水时，成功率更高，效果略有提升。'' },
    { name: ''精准投掷'', rank: ''C'', desc: ''你使用任何投掷类道具卡时，其弹道更稳定，射程更远。'' },
    { name: ''厨师'', rank: ''D'', desc: ''能将普通的食材制作成提供微弱、短效增益的食物道具，至少味道还不错。'' },
    { name: ''森之低语'', rank: ''A'', desc: ''制作植物或德鲁伊相关卡牌时，成品会拥有更高的“活性”，如【树人】伙伴卡能缓慢自愈，【藤蔓】技能卡能自主寻找敌人。'' },
    { name: ''光之拥护'', rank: ''B'', desc: ''擅长制作【治疗】、【净化】、【祝福】等神圣系法术卡，对亡灵和恶魔类敌人有特效。'' },
    { name: ''影之仆从'', rank: ''B'', desc: ''擅长制作【潜行】、【背刺】、【暗杀】等刺客类技能卡，以及【影子仆从】等侦查、奇袭类伙伴卡。'' },
    { name: ''大地之握'', rank: ''B'', desc: ''使用岩石、土壤等材料，能制作出坚固的【土墙】防御卡、【地刺】技能卡和【岩石傀儡】伙伴卡。'' },
    { name: ''雷霆之怒'', rank: ''A'', desc: ''制作雷电系技能卡时，有极高概率附加【麻痹】和【连锁闪电】词条。'' },
    { name: ''风之语'', rank: ''B'', desc: ''使用羽毛、风滚草等轻盈材料，擅长制作风系法术卡或能提升速度的装备卡，常附加【飞行】、【加速】词条。'' },
    { name: ''炎之亲和'', rank: ''C'', desc: ''制作火系技能卡时，有较高概率提升卡牌威力或附加【燃烧】词条。'' },
    { name: ''萌即是正义'', rank: ''B'', desc: ''使用“可爱”生物的材料（如兔子毛、猫胡须），极易制作出拥有【可爱】、【毛茸茸】、【治愈】词条的伙伴卡。'' },
    { name: ''锻火之心'', rank: ''A'', desc: ''使用金属矿石制作武器卡时，有概率制造出更高等级的卡牌，并有几率附加【灼热】、【熔岩】等火属性词条。'' },
    { name: ''恋足癖'', rank: ''C'', desc: ''专注于制作鞋、袜、腿甲等足部装备卡，有较高概率附加【迅捷】、【优雅】、【防滑】甚至【气味】等特殊词条。'' },
    { name: ''巨龟之壳'', rank: ''B'', desc: ''使用龟壳、甲壳等坚硬材料制作防具卡时，必定会附加【坚固】词条，并有概率附加【偏转】、【不动如山】词条。'' },
    { name: ''尸体收藏家'', rank: ''B'', desc: ''使用尸体、骸骨等材料，能高效制作出【骷髅】、【僵尸】等亡灵伙伴卡，但制作者身上会残留尸臭。'' },
    { name: ''绿拇指'', rank: ''C'', desc: ''使用植物种子或枝叶，极易制作出各种植物系伙伴卡（如豌豆射手、食人花），或带有【缠绕】效果的技能卡。'' },
    { name: ''食神之舌'', rank: ''B'', desc: ''能够将食材制作成效果强大的【料理】消耗卡，食用后可获得长时间的强力增益效果。'' },
    { name: ''天衣无缝'', rank: ''A'', desc: ''制作任何布甲、皮甲类服装卡时，成品的基础防御力和舒适度远超常规，有极高概率附加【轻盈】、【韧性】词条。'' },
    { name: ''绝对领域'', rank: ''B'', desc: ''你制作的伙伴卡腿部曲线将变得极为诱人，并自带【过膝袜】或【长筒袜】外观。她们的踢技伤害提升，且有几率释放【魅惑】效果，让敌人跪倒在她们的裙下。'' },
    { name: ''神圣责打'', rank: ''A'', desc: ''制作的伙伴卡将变为手持【戒律鞭】或【板子】的【风纪委员】或【修女】形象。她们的攻击会附加【痛觉】与【快感】的双重debuff，每次攻击都会让你（玩家）获得一个短暂的“惩戒”增益。'' },
    { name: ''SSS级天赋·神孕之屌'', rank: ''SSS'', desc: ''你的精液是比你制卡师等级高出一级并可直接使用的制卡素材。任何雌性生物被你内射后，都有极低概率孕育出比你二人中等级较高者高出一级的级素材或直接诞生你二人中等级较高者同等级的伙伴卡。此过程无视物种隔离。'' },
    { name: ''女王领域'', rank: ''SSS'', desc: ''你制作的所有女性伙伴卡将自带天生领域，效果各不相同，每个都拥有强大的buff和debuff。领域内，伙伴卡的全属性提升50%，所有敌方单位的全属性降低50%，并且始终携带【臣服】等降低战斗欲望的词条。'' },
    { name: ''吞噬一切'', rank: ''SSS'', desc: ''你的卡牌均带有【吞噬】词条，可以直接吞噬等级不高于你制卡师等级一级的【卡牌】或【素材】成长，在吸收其所有基础属性的同时，还会随机吸收被吞噬者的一个【词条】。'' },
    { name: ''万物归一'', rank: ''SSS'', desc: ''你可以将任意三张等级不高于你制卡师等级的卡牌（不论类型）融合成一张全新的、未知的卡牌，新卡牌将继承三张卡牌的部分词条并有概率产生更高级的专属词条。'' },
    { name: ''素材之王'', rank: ''SSS'', desc: ''战斗时，你可以主动催动天赋，有概率直接将等级不高于你制卡师等级一级的敌人拆解为【素材】；在非战斗状态下，你也可以消耗精神力将等级不高于你制卡师等级一级的无主物品拆解为【素材】。'' },
    { name: ''神罚执行官'', rank: ''SSS'', desc: ''你制作的女性【伙伴卡】将获得【神格】词条，她们的攻击有将会为目标附加【神罚印记】。拥有印记的男性目标在被击败时，会直接转化为名为【神罚肉奴】的特殊素材，该素材可用于喂养你的【伙伴卡】，快速提供经验值，也可制作【装备卡】或【领域卡】，在制作卡牌时，此素材将优先燃烧MP，并且承担所有的负面效果。'' },
    { name: ''终极雌堕'', rank: ''SSS'', desc: ''你可以指定任意一张男性【伙伴卡】或捕获的男性敌人，对其进行【雌堕仪式】。仪式成功后，目标将永久转变为绝对忠诚于你的伪娘【伙伴卡】，保留部分原有技能并觉醒强大的【雌堕】专属词条，如“背叛之刺”、“魅惑之躯”等。'' },
    { name: ''鸿蒙道体（东方）'', rank: ''SSS'', desc: ''你是混沌未开时诞生的最初生灵，拥有世间最强的体质。所有经验值获取效率提升100%，能够勘破一切虚妄，制作卡牌的结果只有成功和良性突破，并且每张卡牌都携带【鸿蒙紫气】这一词条'' },
    { name: ''契约魔女的子宫'', rank: ''SSS'', desc: ''你的身体成为与女性伙伴卡链接的【温床】。制卡时，你可以选择让女性伙伴卡将素材【吞入子宫】进行孕育。孕育过程（1天）会持续消耗你的HP和MP，但完成后必定产生【良性突变】，且卡牌会额外获得原【素材】所有词条的超进化【词条】。'' },
    { name: ''女王气场'', rank: ''SSS'', desc: ''你制作出的伙伴卡均为性格各异，风格不同但都带有"抖s"，"女王"，"施虐"等词条的女王型【伙伴卡】，拥有很强悍的肉体实力和精神威慑力。每位女王都有自己的骄傲，因此你的卡组只能是单人卡组（仅能拥有一位伙伴卡），但同时，你的所有卡组都将自带【领域卡】和世界观背景故事，直接成为【超级卡组】，但此卡组后续不能额外添加任何卡片。'' },
    { name: ''词条之王'', rank: ''SSS'', desc: ''你天生能看到素材中所有隐藏的词条，并且剥离词条时精神力消耗减半。'' },
    { name: ''野性原初'', rank: ''SS'', desc: ''【福瑞】你只能制作兽人（福瑞）型【伙伴卡】。你的伙伴卡无视位阶压制，在面对比自己等级高的敌人时，反而会激发“狩猎本能”，全属性提升。所有技能卡和装备卡装备时会自动兽化，获得额外词条。'' },
    { name: ''绝对母权'', rank: ''SS'', desc: ''【恋母情结】你制作的所有【伙伴卡】都会视你为“孩子”，拥有极强的保护欲和控制欲。她们会为你提供无与伦比的防御和恢复，在战斗时强行吸引仇恨，但当你试图使用她们不认可的卡牌时，有概率遭到“母爱惩戒”，该卡牌被无效化并对你造成精神冲击。'' },
    { name: ''进化奇迹'', rank: ''SSS'', desc: ''你的卡牌在进化时，有50%概率触发【良性突变】。'' },
    { name: ''龙裔之血'', rank: ''SSS'', desc: ''你制作的卡牌会转化为高傲的【龙娘/龙男】系列生物，继承龙族的强大元素亲和与肉体力量，但性格极度自负，偶尔会无视你的指令。'' },
    { name: ''狐之魅'', rank: ''A'', desc: ''你制作的卡牌会转化为狡黠的【狐妖】系列生物，天生擅长幻术与精神魅惑，战斗风格诡秘，但有收集亮晶晶东西的怪癖。'' },
    { name: ''月下狼魂'', rank: ''B'', desc: ''你制作的卡牌会转化为团结而凶猛的【狼人】系列生物，具有【集群作战】特性，在月光下战斗力飙升，但对“家庭”和“伙伴”的概念极为执着。'' },
    { name: ''猫之九命'', rank: ''S'', desc: ''你制作的卡牌会转化为慵懒而敏捷的【猫娘/猫男】系列生物，获得【九次生命】（天赋）的特殊能力（同一场战斗可免死8次），但极度好奇，可能会被无关紧要的事物吸引注意力。'' },
    { name: ''蛛后血统'', rank: ''B'', desc: ''你制作的卡牌会转化为冷酷的【蜘蛛精】系列生物，擅长布置陷阱与使用毒素，思考方式绝对理性，会将一切视为捕食或被捕食的关系。'' },
    { name: ''史莱姆之心'', rank: ''C'', desc: ''你制作的卡牌会转化为天真烂漫的【史莱姆娘】系列生物，拥有极强的物理抗性与变形能力，性格单纯，战斗全凭直觉，能通过吞噬获得短暂的能力模仿。'' },
    { name: ''神圣马角'', rank: ''A'', desc: ''你制作的卡牌会转化为圣洁的【独角兽】系列生物，拥有强大的治疗与净化能力，无法容忍任何邪恶或污秽的存在，对使用者有极高的道德要求。'' },
    { name: ''狮鹫骑士'', rank: ''A'', desc: ''你制作的卡牌会转化为兼具威严与忠诚的【狮鹫】拟人系列生物，拥有飞行的能力与王者的气度，认定你是其唯一的效忠对象，并会主动守护你的荣耀。'' },
    { name: ''蛇神之瞳'', rank: ''B'', desc: ''你制作的卡牌会转化为妖艳的【拉米亚/娜迦】系列生物，下半身为蛇，拥有石化凝视的能力，性格占有欲极强，会将你视为自己的私有物。'' },
    { name: ''海妖之歌'', rank: ''B'', desc: ''你制作的卡牌会转化为歌声动人的【塞壬】系列生物，能够在水中高速移动，其歌声能魅惑心智不坚的敌人，但情绪起伏极大，时而温柔时而狂暴。'' },
    { name: ''魅魔契约'', rank: ''A'', desc: ''你制作的卡牌会转化为诱人的【魅魔】系列生物，擅长吸取生命力与精神力，一举一动都充满诱惑，认为通过满足欲望来支配敌人是最高效的战斗方式。'' },
    { name: ''元素之躯'', rank: ''B'', desc: ''使用元素灵素材时，你制作的卡牌会转化为对应属性的【元素娘】系列生物，免疫同属性伤害，但也会被克制属性双倍克制，性格会与元素特性高度一致（如火爆、冰冷）。'' },
    { name: ''人马的骄傲'', rank: ''B'', desc: ''你制作的卡牌会转化为骁勇善战的【人马】系列生物，拥有极高的移动速度和骑射技巧，信奉荣誉与力量，鄙视任何形式的诡计。'' },
    { name: ''不死鸟之羽'', rank: ''SSS'', desc: ''你制作的卡牌会转化为华丽的【凤凰】拟人系列生物，掌握着【涅槃重生】（天赋）的能力，性格高洁。'' },
    { name: ''地精工程师'', rank: ''C'', desc: ''你制作的卡牌会转化为热衷发明的【地精】系列生物，擅长制作各种不稳定但威力巨大的爆炸物与机械装置，口头禅是“为了更大的爆炸！”。'' },
    { name: ''树妖之心'', rank: ''B'', desc: ''你制作的卡牌会转化为热爱自然的【树妖】系列生物，可以与植物沟通并操控它们，战斗时会优先保护周围的环境，对火焰有着天生的恐惧。'' },
    { name: ''鹰身女妖之爪'', rank: ''C'', desc: ''你制作的卡牌会转化为尖啸的【哈比】系列生物，飞行能力优秀，叫声能造成精神干扰，但性格贪婪且残忍，喜欢抢夺一切发光的东西。'' },
    { name: ''哥布林种猪'', rank: ''D'', desc: ''你制作的卡牌会转化为卑劣但狡猾的【哥布林】系列生物。'' },
    { name: ''黏菌共生体'', rank: ''A'', desc: ''你制作的卡牌会转化为可爱的【真菌娘】系列生物，能够分裂成多个拥有独立意识的个体，并能通过孢子感染敌人，将其转化为临时的“同伴”。'' },
    { name: ''晶化之蜥'', rank: ''B'', desc: ''你制作的卡牌会转化为身体部分由水晶构成的【晶蜥娘】系列生物，拥有极高的魔法抗性，能够折射和储存魔力，但行动相对迟缓。'' },
    { name: ''深潜者血脉'', rank: ''B'', desc: ''你制作的卡牌会转化为【鱼人】系列生物，能在深水中呼吸和高速移动，会使用古老且低语般的精神冲击，但长期暴露在日光下会感到不适。'' },
    { name: ''石像鬼守护'', rank: ''C'', desc: ''你制作的卡牌会转化为沉默的【石像鬼】系列生物，白天会变为防御力极高的石像，夜晚则恢复行动力，作为绝对忠诚的守护者而存在。'' },
    { name: ''螳螂舞刃'', rank: ''B'', desc: ''你制作的卡牌会转化为凌厉的【螳螂娘】系列生物，双臂为锋利的骨刃，战斗风格是迅捷而致命的刺杀，认为战斗是最优美的舞蹈。'' },
    { name: ''红头文件'', rank: ''B'', desc: ''制作的卡牌攻击敌人时，会给对方施加一层“审批”状态。叠满5层后，敌人下一个行动必须跳过，因为“流程还没走完”。'' },
    { name: ''律师函警告'', rank: ''SSS'', desc: ''制作的生物卡可以对敌方单位施加一份“行为合同”（如：禁止使用火系技能），若对方违反，则会受到合同约定的巨额反噬真实伤害。'' },
    { name: ''最终解释权'', rank: ''SS'', desc: ''每场战斗一次，你可以重新定义你制作的一张卡牌描述中的一个关键词。例如，将“造成火焰伤害”改为“造成真实伤害”。'' },
    { name: ''病娇烙印'', rank: ''S'', desc: ''制作的生物卡牌对主人有极强的占有欲，当主人受创时会陷入狂暴，攻击力剧增。但它们会优先攻击任何靠近主人的单位，包括友军。'' },
    { name: ''傲娇模板'', rank: ''B'', desc: ''制作的生物卡牌嘴上说着“才不是为了你呢”，但会在主人遭受致命攻击时，强制格挡一次该伤害，随后会陷入“害羞”状态，防御力大幅下降。'' },
    { name: ''懒惰天才'', rank: ''S'', desc: ''制作的生物卡牌拥有极高的面板属性，但极度懒惰，有50%的几率会“摸鱼”而跳过行动。但只要它们行动，必定产生暴击或效果翻倍。'' },
    { name: ''中二病晚期'', rank: ''C'', desc: ''制作的生物卡牌在登场和攻击时，会念出冗长而羞耻的台词，攻击前摇增加，但技能会附带无法被驱散的微弱暗影伤害。'' },
    { name: ''腹黑之智'', rank: ''A'', desc: ''制作出的女性卡牌外表温柔无害，内心却精于算计。她们擅长利用语言和环境设下陷阱，战斗中更倾向于使用Debuff和控制类技能，看着敌人在绝望中覆灭是她们最大的乐趣。'' },
    { name: ''天然呆'', rank: ''C'', desc: ''制作出的女性卡牌思维会有些脱线，经常会误解命令或在关键时刻发呆。她们的攻击有一定几率打偏，但也因为这种不确定性，偶尔会歪打正着，打出意想不到的暴击效果。'' },
    { name: ''电波系少女'', rank: ''B'', desc: ''制作出的女性卡牌思维方式异于常人，会说一些意义不明的呓语。敌人无法通过读心等方式探知其想法，她的行动模式完全无法预测，有时会做出令敌我双方都匪夷所思的举动。'' },
    { name: ''元气少女'', rank: ''C'', desc: ''制作出的女性卡牌总是精力充沛、活泼开朗。她们的存在会持续为我方全体单位提供微弱的【振奋】效果，提升移动速度和攻击速度，但她们的战斗风格大开大合，容易露出破绽。'' },
    { name: ''巫女祈愿'', rank: ''B'', desc: ''制作出的女性卡牌身份为神社的巫女。她们拥有对魔物和不死生物的特攻能力，擅长使用符咒和结界进行净化与防御。衣着为传统的巫女服，行动较为端庄。'' },
    { name: ''乐高大师'', rank: ''B'', desc: ''你制作的卡牌都具有【组合】特性，多张同系列的卡牌同时在场时，可以合体成一个更强大的单位。'' },
    { name: ''开源精神'', rank: ''C'', desc: ''你制作的装备卡上会多出一个【插槽】，可以镶嵌其他低等级的技能卡，但稳定性较差，有1%的概率在使用时失效。'' },
    { name: ''哲学家'', rank: ''A'', desc: ''你制作的伙伴卡总是会思考一些深刻的问题，比如“我为何而战”。她们的忠诚度不容易提升，但一旦认可你，将至死不渝，并有概率在战斗中领悟专属技能。'' },
    { name: ''量子纠缠'', rank: ''A'', desc: ''你制作的卡牌，其效果会在“成功”和“失败”两种状态中叠加，直到使用时才最终确定。例如，一张火球卡在使用前，你不知道它会是“大火球”还是“小火苗”。'' },
    { name: ''混沌理论'', rank: ''SS'', desc: ''使用【对冲融合】时，素材的冲突值越高，【良性突变】的概率反而越大。你总能在最混乱的能量中找到秩序。'' },
    { name: ''艺术家'', rank: ''C'', desc: ''你制作的卡牌，卡面都异常精美，宛如艺术品。没有任何实际加成，但非常赏心悦目，也更容易卖出高价。'' },
    { name: ''模仿者'', rank: ''A'', desc: ''制卡时，你可以指定一张自己的手牌作为“模板”，新制成的卡牌有概率复制“模板”卡的一个词条。'' },
    { name: ''神性火花'', rank: ''SSS'', desc: ''使用【传奇】或【神话】级素材时，你必定能引出其核心的【神性词条】，这是制作神卡的唯一门票。'' },
    { name: ''万物皆可萌'', rank: ''B'', desc: ''无论使用多么狰狞可怖的素材，你制作出的伙伴卡外表都异常的“萌”，拥有迷惑敌人的奇效。'' },
    { name: ''第四面墙'', rank: ''SSS'', desc: ''你隐约意识到自己身处的世界的“规则”。制卡时，你可以消耗巨量MP，直接修改一个词条的效果描述。'' },
    { name: ''和风'', rank: ''B'', desc: ''你制作的卡牌都带有“和风”元素，如武士、忍者、巫女等，装备或伙伴卡的外形也会发生相应变化。'' },
    { name: ''赛博格'', rank: ''A'', desc: ''你擅长将生物素材与机械素材结合，制作出的“赛博格”伙伴卡同时拥有生物的成长性和机械的可改造性。'' },
    { name: ''克苏鲁的呼唤'', rank: ''S'', desc: ''使用蕴含“疯狂”或“扭曲”概念的素材时，你更容易成功，并有概率为卡牌附加【古神低语】词条，对敌人造成理智削减（SAN check）效果。'' },
    { name: ''盗火者'', rank: ''SS'', desc: ''越阶挑战时，若挑战成功，制成的卡牌有50%的概率直接提升一个大等级。'' },
    { name: ''文科生'', rank: ''D'', desc: ''你制作的卡牌，介绍文字写得天花乱坠，充满诗意，但实际效果往往平平无奇。'' },
    { name: ''理科生'', rank: ''D'', desc: ''你制作的卡牌，介绍文字就是干巴巴的数据和公式，但效果稳定可靠。'' },
    { name: ''合成歌姬'', rank: ''A'', desc: ''你制作的女性伙伴卡都拥有天籁般的歌喉，可以通过歌唱释放强大的增益或减益效果。'' },
    { name: ''降维打击'', rank: ''S'', desc: ''你制作的领域卡，有极小概率会演化为【世界卡】。使用时，会将敌人拉入一个由你主宰的“小世界”中。'' },
    { name: ''双刃剑'', rank: ''B'', desc: ''你制作的卡牌效果都极其强大，但都带有一个明显的负面效果。'' },
    { name: ''F级解释权'', rank: ''F'', desc: ''你拥有对你制作的F级天赋卡牌效果的最终解释权。当然，前提是有人信。'' },
  {"name": "野猪骑士","rank": "D","desc": "你骑乘猪科生物时获得额外的亲和加成——坐骑不会尥蹶子把你甩下来，且冲锋伤害提升15%。如果你的伙伴卡和猪有关，它的忠诚度永远不会低于100。"},
    { name: ''王之财宝'', rank: ''SSS'', desc: ''制卡时有极低概率将主素材升华为【宝具】原型。制作出的装备卡必定拥有至少一条金色词条，且装备时会与使用者灵魂绑定，发挥出超越等级的威力。'' },
    { name: ''赌徒谬论'', rank: ''S'', desc: ''使用【对冲融合】流派时，每次“大失败”都会为你叠加一层“厄运”，每层“厄运”都会显著提高下一次【对冲融合】的“大成功”概率。此天赋是赌徒的福音，也是非酋的诅咒。'' },
    { name: ''灵魂低语者'', rank: ''A'', desc: ''在【融合】阶段，你能模糊地听到素材词条的“意愿”，更容易找到最和谐的融合路径。使用【和谐共鸣】流派时，“可控失败”的概率大幅降低。'' },
    { name: ''王室血誓'', rank: ''A'', desc: ''制作出的女性卡牌拥有高贵的王室血统。她们自带【领导】光环，能提升我方所有单位的士气。战斗风格为正统的骑士剑术，坚信荣誉与守护，绝不使用卑劣的手段。'' },
    { name: ''魔女的契约'', rank: ''S'', desc: ''制作出的女性卡牌是与古老存在签订了契约的魔女。她们能使用强大但代价高昂的禁忌魔法，每次使用都会消耗自身的“存在”，可能导致记忆缺失或身体异变。'' },
    { name: ''女王的踏足'', rank: ''B'', desc: ''制作出的女性伙伴卡天生带有高傲气质，视线永远向下。她们的普通攻击会演变为用脚踩踏，对倒地的敌人有额外伤害加成，并有几率附加【屈辱】状态，降低敌方攻击力。'' },
    { name: ''肥臀骚妈'', rank: ''A'', desc: ''制作出的体型丰满的伙伴卡拥有强大的臀部。她们的特殊技能【坐杀】能瞬间压制单个敌人，造成巨大伤害并长时间眩晕，但自身也会陷入短暂的无法移动状态。'' },
    { name: ''窒息的母爱'', rank: ''A'', desc: ''制作出的体型丰满的伙伴卡拥有强烈的守护欲。她们会将敌人或友军（不分敌我）拉入怀中进行“保护”，使其无法行动但获得高额减伤，同时对敌人造成持续的窒息伤害。'' },
    { name: ''巨人的宠爱'', rank: ''S'', desc: ''制作出的女性伙伴卡体型会变得异常巨大。她们视制卡师为掌中玩物，战斗中会将制卡师放在肩膀上提供绝对保护，并能将敌人像小石子一样弹飞。'' },
    { name: ''高跟凶器'', rank: ''B'', desc: ''制作出的女性卡牌会自动装备一双与其等级相匹配的【高跟鞋】，该装备无法卸下，且普通攻击变为穿刺属性，对护甲单位有特效。'' },
    { name: ''山峦之拥'', rank: ''B'', desc: ''制作出的女性伙伴卡胸怀博大。她们的技能【埋首】能强制将一个敌人拉入怀中，使其视野归零并陷入【魅惑】状态，持续数秒。'' },
    { name: ''踩脸处刑官'', rank: ''A'', desc: ''制作出的女性伙伴卡对被击倒的敌人拥有终结技【处刑】。她会用脚踩住敌人的脸，进行一次必定暴击且无视防御的攻击。'' },
    { name: ''体格差压制'', rank: ''B'', desc: ''制作出的伙伴卡在攻击体型远小于自己的敌人时，会造成额外的威压伤害（无视防御）。'' },
    { name: ''足之炼金术'', rank: ''S'', desc: ''极度稀有的天赋。制作出的女性伙伴卡能通过踩踏不同的素材，将其转化为全新的道具卡。例如踩踏矿石可能炼出金属，踩踏草药可能炼出药剂。'' },
    { name: ''踩蚁的乐趣'', rank: ''D'', desc: ''制作出的卡牌在面对昆虫类或体型极小的敌人时，攻击力会莫名提升50%。她们单纯地享受踩扁小东西的快感。'' },
    { name: ''绝对支配宣言'', rank: ''S'', desc: ''制作出的女性伙伴卡在登场时，会强制所有敌方男性单位进行一次意志检定。检定失败者会陷入【痴迷】状态，优先攻击该卡牌的队友。'' },
    { name: ''碾压快感'', rank: ''B'', desc: ''制作出的卡牌在用范围技能同时击杀多个敌人时，会获得一个短暂的、可叠加的【愉悦】Buff，提升自身攻击速度。'' },
    { name: ''小人国的女王'', rank: ''A'', desc: ''制作出的女性伙伴卡在面对复数个等级低于自己的敌人时，全属性会获得提升。敌人越多，她就越强。'' },
    { name: ''高塔的公主'', rank: ''B'', desc: ''制作出的巨大化女性伙伴卡，当她静立不动时，会获得【堡垒】状态，防御力大幅提升，并允许友方远程单位以她为掩体。'' },
    { name: ''迷你暴君'', rank: ''B'', desc: ''制作出的体型娇小的伙伴卡，性格却异常暴躁。她们的攻击速度极快，且有几率让敌人陷入【恼火】状态（攻击力提升，但防御力大幅下降）。'' },
    { name: ''足模的骄傲'', rank: ''C'', desc: ''制作出的女性卡牌，其脚部被视为一个独立的装备栏，可以额外装备【脚链】、【涂装】等特殊道具卡。'' },
    { name: ''踩碎的尊严'', rank: ''B'', desc: ''制作出的卡牌在击败敌人时，如果鞭尸（攻击尸体），能从尸体上踩出少量的卡币。'' },
    { name: ''修女的忏悔'', rank: ''B'', desc: ''制作出的女性卡牌身份为修女。她们拥有强大的治疗和辅助能力，能为队友【赎罪】，转移其受到的负面效果。但她们对“不洁”的恶魔或淫邪系敌人会抱有极大的憎恶，攻击时会不计代价。'' },
    { name: ''海盗女王'', rank: ''B'', desc: ''制作出的女性卡牌身份为豪放不羁的海盗船长。她擅长使用火枪和弯刀，战斗风格大开大合。她对财宝有天生的敏感，能提升战斗后的战利品掉落率。'' },
    { name: ''天使之羽'', rank: ''S'', desc: ''制作出的女性卡牌会拥有圣洁的羽翼，身份为天使或女武神。她们天生拥有飞行能力和神圣属性攻击，对亡灵和恶魔造成巨大伤害。她们的思维中，“绝对正义”高于一切，有时会做出冷酷的抉择。'' },
    { name: ''女王的恩赐'', rank: ''S'', desc: ''制作出的女性伙伴卡必定为巨女体型，性格极其高傲。她们的普通攻击即为“踩踏”，对小型单位造成碾压伤害，并有几率附加“恐惧”状态。她们视万物为蝼蚁，存在的唯一乐趣就是寻找值得用脚尖“玩弄”的玩具。'' },
    { name: ''军靴的纪律'', rank: ''A'', desc: ''制作出的卡牌必定穿着厚重的军靴，性格严苛冷酷。她们擅长使用踢技，能够轻易踢碎敌人的护甲。其卡牌自带“威压”光环，降低敌方全体单位的士气。'' },
    { name: ''汗湿的诱惑'', rank: ''A'', desc: ''制作出的女性卡牌双脚极易出汗，散发出浓郁的香气。这股香气会持续对周围敌方单位造成“魅惑”和“精神错乱”效果，尤其对男性单位效果翻倍。'' },
    { name: ''水晶舞鞋'', rank: ''B'', desc: ''制作装备卡时，有高几率制造出各种附魔舞鞋。这些舞鞋能赋予穿戴者“优雅舞步”、“冰上行走”等特殊能力，并对特定种族有克制效果。'' },
    { name: ''赤足的野性'', rank: ''B'', desc: ''制作出的伙伴卡必定是赤足，性格狂野奔放。她们的脚底皮肤坚韧如革，能适应任何地形，并且奔跑速度极快。她们的踢技充满了原始的力量感。'' },
    { name: ''棉袜的温暖'', rank: ''C'', desc: ''制作出的卡牌总是穿着厚厚的棉袜，给人一种邻家女孩的亲切感。她们擅长治疗和辅助，能用她们“温暖”的脚为队友驱散寒冷和诅咒。'' },
    { name: ''趾甲彩绘师'', rank: ''D'', desc: ''制作出的卡牌痴迷于给自己的脚趾甲涂上各种颜色的指甲油。不同的颜色会带来微弱的不同属性加成，但她们会因为趾甲被刮花而陷入“暴怒”状态。'' },
    { name: ''足弓的陷阱'', rank: ''A'', desc: ''制作出的女性卡牌拥有完美得令人窒息的足弓。她们的双脚本身就是一种概念陷阱，任何试图攻击她们足部的敌人，都有可能被足弓的曲线所“捕获”，陷入永久的痴迷状态。'' },
    { name: ''踢蛋专家'', rank: ''B'', desc: ''制作出的卡牌，其所有踢击会自动锁定敌方男性单位的下体。攻击必定造成“剧痛”和“沉默”效果，有一定几率造成“致命一击”。'' },
    { name: ''足尖的剧毒'', rank: ''A'', desc: ''制作出的卡牌，其脚趾甲中含有剧毒。她们擅长用看似轻柔的足尖划过敌人皮肤，注入毒素。这种毒素会慢慢侵蚀敌人的神经，使其在幻觉中痛苦死去。'' },
    { name: ''木屐的节奏'', rank: ''C'', desc: ''制作出的卡牌必定穿着木屐，走路时会发出清脆的“咔哒”声。这种声音能扰乱敌人的心神，起到范围性“嘲讽”和“降速”的效果。'' },
    { name: ''足底的纹身'', rank: ''A'', desc: ''制作出的卡牌脚底刻有神秘的魔法纹身。她们可以通过跺脚来激活纹身，发动强大的元素魔法。跺左脚是火焰，跺右脚是冰霜，双脚同时跺地则会引发地震。'' },
    { name: ''高筒靴的女王'', rank: ''A'', desc: ''，此天赋专注于长筒、过膝的皮靴。制作出的卡牌充满了女王气质和施虐欲望，她们的靴子能吸收敌人的恐惧转化为自身的力量，并且擅长用长靴的靴筒夹住敌人进行“折磨”。'' },
    { name: ''恋味癖的盛宴'', rank: ''A'', desc: ''制作出的卡牌，其脚部散发的气味对特定单位有致命的吸引力。她们能轻易奴役那些对气味痴迷的敌人，将其变为自己的“气味奴隶”，为自己作战。'' },
    { name: ''玛丽珍的诅咒'', rank: ''B'', desc: ''制作出的卡牌总是穿着可爱的玛丽珍鞋，但鞋子上附有诅咒。任何被她们的鞋子触碰到的敌人，心智都会慢慢退化成孩童，最终忘记如何战斗。'' },
    { name: ''足音的催眠'', rank: ''A'', desc: ''制作出的卡牌，其脚步声（无论是高跟鞋的“哒哒”声还是赤足的“啪嗒”声）都带有强烈的催眠效果。敌人听得越久，就越容易陷入沉睡或被操控。'' },
    { name: ''踏星者'', rank: ''S'', desc: ''制作出的卡牌可以在虚空中行走，她们的每一步都踏在星辰之上。她们无视任何地形障碍，并且可以在战场上任意传送，其攻击会附带星辰陨落的范围伤害。'' },
    { name: ''每日签到系统'', rank: ''A'', desc: ''每天可进行一次签到，随机获得卡币、素材或消耗品。连续签到天数越多，出现稀有奖励的概率越高，特定天数更有保底大奖。'' },
    { name: ''素材十连系统'', rank: ''S'', desc: ''每天获得一次免费的素材十连抽机会，保底获得一张不低于自身等级的稀有素材，有极小概率抽出高阶突变词条。'' },
    { name: ''亲吻女神系统'', rank: ''S'', desc: ''亲吻任意女性可触发一次轮盘抽奖。对方实力越强、颜值越高、好感度越低，奖励轮盘的品质就越高，奖励包括但不限于临时强力Buff、稀有素材或对方的技能卡碎片。'' },
    { name: ''美食家系统'', rank: ''A'', desc: ''品尝不同的食物可以获得“美食点数”，累积点数可永久提升基础属性。品尝到传说级或蕴含特殊能量的料理时，可直接领悟新的技能或词条。'' },
    { name: ''无限猎杀系统'', rank: ''S'', desc: ''每击杀一个敌人，都会掉落“灵魂碎片”，可用于直接提升等级经验或强化装备。连续击杀（Combo）会提升稀有碎片的掉率。'' },
    { name: ''后宫之主系统'', rank: ''SSS'', desc: ''每当一位女性对你的好感度达到“爱恋”，你就能永久获得她一项最强的天赋或技能，并解锁一个专属的“后宫光环”，所有后宫成员在附近时全属性提升。'' },
    { name: ''垃圾佬系统'', rank: ''C'', desc: ''你拥有化腐朽为神奇的能力。任何被判定为“垃圾”或“损坏”的物品在你手中都有概率被修复或提炼出稀有素材，甚至找到被遗弃的神器。'' },
    { name: ''主角光环系统'', rank: ''SSS'', desc: ''你是世界的中心。濒死时有极大概率触发奇遇，跳崖必得神功，遇事总有贵人相助，关键战斗中更容易触发顿悟和临场突破。'' },
    { name: ''宿敌认证系统'', rank: ''S'', desc: ''当你被一名强大的敌人视为“宿敌”时，系统会激活。每次与宿敌战斗或想到他时，你的训练效率都会翻倍，战胜宿敌后更能夺取其部分气运或一项技能。'' },
    { name: ''万物图鉴系统'', rank: ''A'', desc: ''你接触到的任何新物种、新素材、新卡牌都会被自动记录在图鉴中。每完成一个分类的图鉴，就能获得一次针对该分类的永久性加成（如对“龙类”伤害增加）。'' },
    { name: ''神级选项系统'', rank: ''SS'', desc: ''在人生的重要十字路口，时间会为你暂停，面前将出现三个选项，每个选项后面都清晰地标注了可能带来的后果。'' },
    { name: ''谎言家系统'', rank: ''B'', desc: ''你说出的每一个谎言，只要成功骗过对方，就能积累“欺诈点数”。该点数可用于兑换幻术系技能或让下一次的谎言变得更加天衣无缝。'' },
    { name: ''搞事系统'', rank: ''S'', desc: ''你搞出的乱子越大，影响范围越广，事后获得的“混乱源质”就越多。混乱源质是制作【畸变卡】和【混沌系】卡牌的顶级材料。'' },
    { name: ''NTR牛头人系统'', rank: ''SSS'', desc: ''当你成功NTR他人，或你的伴侣被他人NTR时，你将获得一股强大而扭曲的“嫉妒之力”，短时间内全属性爆炸性增长，但心智会受到严重侵蚀。'' },
    { name: ''圣液收集系统'', rank: ''S'', desc: ''通过各种方式收集到的女性体液（汗水、唾液、泪水、X液等）都能被系统提纯为高级炼金素材或强力药剂。特定人物的体液更有奇效。'' },
    { name: ''深度睡眠系统'', rank: ''C'', desc: ''你的睡眠质量极高。只要进入深度睡眠，精神力（MP）的恢复速度就是常人的三倍，偶尔还会在梦中预见到未来的片段。'' },
    { name: ''行走印钞机系统'', rank: ''A'', desc: ''你每走一公里，系统就会自动生成一定数量的卡币。你的等级越高，每公里的“汇率”也越高。'' },
    { name: ''反派洗白系统'', rank: ''A'', desc: ''你拥有与生俱来的亲和力，与“恶”阵营的角色交流时，有更高几率触发特殊剧情，说服他们，甚至让他们弃暗投明，成为你的伙伴。'' },
    { name: ''一拳超人系统'', rank: ''SS'', desc: ''你每天只能挥出一拳，但这一拳的威力会被增幅到你当前等级所能达到的极限。出拳后，你将进入24小时的虚弱状态。'' },
    { name: ''炼金工坊系统'', rank: ''B'', desc: ''你拥有一个便携的炼金空间。任何素材投入其中，都可以按照配方合成为药剂、炸弹或装备强化石。熟练度越高，解锁的配方越多。'' },
    { name: ''师道尊严系统'', rank: ''A'', desc: ''当你收下弟子并传授其知识或技能时，你能获得其成长经验的20%作为反馈。弟子越强，你获得的好处越多。'' },
    { name: ''打脸升级系统'', rank: ''S'', desc: ''当你被人嘲讽、鄙视或看不起后，再用实力狠狠打对方的脸，你将获得海量经验值和“打脸点数”，可用于兑换特殊称号或装备。'' },
    { name: ''情报贩子系统'', rank: ''B'', desc: ''你总能听到各种流言蜚语。每天系统会刷新三条随机情报，可能是某地的宝藏信息，也可能是某位大人物的秘密丑闻。'' },
    { name: ''剧透者系统'', rank: ''S'', desc: ''你能在关键时刻看到“弹幕”或“旁白”，提前预知接下来的剧情走向或敌人的技能。但强行改变剧情会遭到世界意志的反噬。'' },
    { name: ''赌徒谬论系统'', rank: ''A'', desc: ''你的所有概率性技能或行为，如果连续失败，下一次的成功率将会指数级提升。只要坚持，总有一次会逆天改命。'' },
    { name: ''偷窃神手系统'', rank: ''B'', desc: ''你对任何人或魔物进行“偷窃”时，成功率会得到极大提升，甚至有概率偷到对方正在使用的装备或技能卡。'' },
    { name: ''调教大师系统'', rank: ''S'', desc: ''你制作或捕获的女性伙伴卡，可以通过“调教”来塑造其性格和能力。无论是培养成忠犬还是女王，都由你决定。调教程度越高，她们的潜力激发得越彻底。'' },
    { name: ''氪金就强系统'', rank: ''SSS'', desc: ''你可以通过消耗卡币来直接提升自己的等级、技能熟练度或购买系统商店里的任何物品，包括规则级道具。只要有钱，你就是神。'' },
    { name: ''BOSS首杀系统'', rank: ''A'', desc: ''你作为队长第一次击杀区域BOSS或副本BOSS时，队伍将获得额外奖励，包括稀有称号、专属装备和大量经验。'' },
    { name: ''地图全开系统'', rank: ''C'', desc: ''你进入任何一个新区域，该区域的简易地图都会自动点亮，并标记出危险区域和大致的资源点。'' },
    { name: ''召唤媒介系统'', rank: ''S'', desc: ''你的身体是一个特殊的召唤媒介，可以通过献祭自身的生命值或精神力，召唤出异世界的强大存在为你作战，但召唤物通常不受完全控制。'' },
    { name: ''读心术系统'', rank: ''B'', desc: ''你可以消耗MP来读取他人的表层思想，精神力远超对方时，甚至能窥探到深层记忆。'' },
    { name: ''黄毛必须死系统'', rank: ''B'', desc: ''当你遇到企图NTR你的黄毛角色时，你对他的所有伤害提升300%，且他所有判定都会遭遇不幸。'' },
    { name: ''任务发布系统'', rank: ''A'', desc: ''你可以像系统一样，向其他人发布任务。当他们接受并完成后，你可以获得一部分系统奖励，而他们也能得到你设定的报酬。'' },
    { name: ''奇迹暖暖系统'', rank: ''C'', desc: ''你拥有一个无限衣柜，可以随时换上任何风格的服装。搭配不同的服装会获得微小的属性加成或特殊效果。'' },
    { name: ''真名看破系统'', rank: ''S'', desc: ''你可以看穿一切伪装，洞悉他人的真名和部分真实信息。念出对方的真名，可以对其造成一次强大的精神冲击。'' },
    { name: ''世界线变动系统'', rank: ''SS'', desc: ''当你做出足以影响世界的重大决定时，你能看到数条不同的世界线分支，并选择其中一条进入。'' },
    { name: ''献祭系统'', rank: ''A'', desc: ''你可以通过献祭物品、卡牌甚至活物来取悦某个未知的存在，以换取力量、知识或实现一个愿望。祭品越珍贵，回报越丰厚。'' },
    { name: ''圣母克星系统'', rank: ''B'', desc: ''在面对“圣母”型角色时，你的所有言行都会被系统自动修正得极具说服力，能轻易地让她们的逻辑崩溃，怀疑人生。'' },
    { name: ''催眠大师系统'', rank: ''A'', desc: ''通过眼神、声音或特定道具，你可以对他人进行催眠，植入指令或篡改记忆。效果强弱取决于双方的精神力差距。'' },
    { name: ''苦主光环系统'', rank: ''C'', desc: ''你身边的女性朋友或伴侣，出轨的概率会莫名其妙地提高。每次发现被NTR后，你的某项基础属性会得到永久性的微小提升。'' },
    { name: ''贤者时间系统'', rank: ''D'', desc: ''在你高潮射精后的五分钟内，你将进入“贤者模式”，所有欲望消失，逻辑思维能力和计算能力提升到极致，如同一个绝对理性的机器。'' },
    { name: ''神之右手系统'', rank: ''A'', desc: ''你的右手拥有特殊的力量，无论是制卡、抚摸还是战斗，都能发挥出远超平常的精准度和力量。俗称“麒麟臂”。'' },
    { name: ''贪婪系统'', rank: ''A'', desc: ''你击杀敌人后，战利品的掉落数量和稀有度会得到提升。你还可以指定一件物品，在下一次交易中强买强卖。'' },
    { name: ''欧皇系统'', rank: ''SS'', desc: ''你的幸运值被锁定在一个极高的水平。无论是抽卡、赌博还是战斗中的暴击判定，你总能得到最好的结果。'' },
    { name: ''非酋系统'', rank: ''F'', desc: ''你的幸运值被锁定在一个极低的水平。所有概率性事件你都会得到最差的结果。但作为补偿，你每次大失败后，都会获得一点永久属性点。'' },
    { name: ''剧本编写系统'', rank: ''SS'', desc: ''你可以消耗大量精神力，编写一段简短的“剧本”，在未来一段时间内，世界会大概率按照你的剧本发展。'' },
    { name: ''舔狗终极系统'', rank: ''S'', desc: ''当你对一位女性角色进行“舔狗”行为（送礼、夸赞、无条件帮助）时，她对你的好感度会暴涨，并返还给你双倍价值的礼物或Buff。'' },
    { name: ''等价交换系统'', rank: ''A'', desc: ''你可以向系统献祭任何物品（卡牌、素材、装备）来换取“炼成值”。消耗“炼成值”，你可以指定一个模糊的方向（如“锋利的剑”、“治愈的药水”），系统将为你随机生成一件符合描述的物品，品质完全随机。'' },
    { name: ''反派的自我修养系统'', rank: ''B'', desc: ''当你做出符合“反派”模板的行为时（如威胁、勒索、背叛），系统会根据行为的恶劣程度给予“恶人点数”。点数可用于在系统商城兑换物品或提升对善良阵营角色的威慑力。'' },
    { name: ''人肉高跟鞋'', rank: ''S'', desc: ''极为残忍的天赋。制作出的女王型卡牌，能将一个活着的敌人通过魔法强制压缩、变形，成为自己脚下的一次性“高跟鞋”。这只“鞋”会不断发出惨叫，并在女王的每一次跺脚中受到巨大伤害，直到最终崩坏。'' },
    { name: ''足下之臣'', rank: ''A'', desc: ''制作出的女王型卡牌，天生就拥有招募“足下之臣”的能力。她们可以通过用脚触碰一个单位的头顶，来强制进行一次精神判定。判定成功，则该单位会叛变，成为她的忠实奴仆。'' },
    { name: ''恶魔之角'', rank: ''S'', desc: ''制作出的女性卡牌会长出恶魔的角和尾巴，身份为恶魔或堕天使。她们擅长使用火焰和暗影魔法，能诱惑敌人或汲取其生命力。她们的思维方式以利己为核心，信奉力量与欲望。'' },
    { name: ''万能武装'', rank: ''S'', desc: ''制作出的女性卡牌能使用任何她能接触到的武器，并能瞬间发挥其最大效能。她的战斗风格会根据手中的武器而千变万化，适应性极强，使用武器类装备时，该装备卡等级自动提升一个大等级，装备卡的经验值获取速度提升100%。'' },
    { name: ''表演型人格'', rank: ''B'', desc: ''制作的生物卡牌渴望成为焦点。己方场上单位越少，它的能力越强。若成为场上唯一的我方单位，它会发动华丽但高耗能的终极技能。'' },
    { name: ''杠精'', rank: ''C'', desc: ''你的生物卡牌会自动反驳敌人的强化效果。每当一个敌方单位获得增益（Buff）时，你的卡牌会尝试“反驳”掉该增益，有一定成功率。'' },
    { name: ''墨绘丹青'', rank: ''A'', desc: ''制作的卡牌呈现水墨画风格，其生物的移动会留下“墨痕”，对踏入的敌人造成持续伤害和减速。'' },
    { name: ''暗影哥特'', rank: ''B'', desc: ''制作的生物卡牌身着繁复的哥特式服饰，气质阴郁，自带微弱的“吸血”光环和“诅咒”能力。'' },
    { name: ''万物骸骨'', rank: ''A'', desc: ''制作的任何生物卡牌都会变成对应的骷髅形态，种族变为“亡灵”，免疫精神与血肉类攻击，但受到光属性和钝击伤害加倍。'' },
    { name: ''孤狼'', rank: ''B'', desc: ''制作的生物卡牌，当场上没有其他友方单位时，攻击力和速度提升100%。'' },
    { name: ''堕落英雄'', rank: ''S'', desc: ''制作的卡牌拥有[神圣]和[邪恶]双重属性，可以在高攻的“堕落形态”和高防的“救赎形态”之间切换。'' },
    { name: ''天生剑骨（东方）'', rank: ''SS'', desc: ''你天生拥有一把跟自己同步成长，极其强大的【本名剑】装备卡，你不能拿装备其他武器类装备卡，但你在制作剑类装备卡时触发良性进化概率为百分之百。'' },
    { name: ''阵法大师（东方）'', rank: ''SS'', desc: ''你的脑海中天生便刻印着无数阵图，对空间与能量的排布极为敏感。制作【阵法】（即领域卡）的成功率和效果均得到极大提升，并且你制作的所有卡组必定是精英级卡组。'' },
    { name: ''符箓宗师（东方）'', rank: ''SS'', desc: ''你获得【空白符篆】（特殊物品）的制作配方，制作起来极其简单，可以同时携带大量空白符篆，你使用任何技能将不会损耗MP值，同时也没有冷却时间，每一次使用技能都会消耗一张空白符篆，并以使用符篆的形式使用技能。'' },
    { name: ''炼器神手（东方）'', rank: ''SS'', desc: ''你与器物有特殊的缘分。你只能制作【装备卡】，并且在素材等级等于你的制卡师等级时成功率为百分之百，有较大概率触发良性进化，每次触发良性进化，则必定附带器灵【配套伙伴卡】和本命决【配套技能卡】，并且自动形成精英级卡组。'' },
    { name: ''御兽奇才（东方）'', rank: ''SS'', desc: ''你与万兽有着天然的亲和力，能够轻易理解它们的灵魂。制作【伙伴卡】时成功率大幅提升，且召唤出的伙伴初始好感度更高，每天你都可以将一个等级不高于你的兽类卡牌或素材强行提升一个大等级。'' },
    { name: ''词条窃贼'', rank: ''SS'', desc: ''每天一次，当你接触到不属于自己的【卡牌】或【素材】时，可以从它们身上随机窃取一个【词条】，并附加到自己的任意一张卡牌上。'' },
    { name: ''时间回溯'', rank: ''S'', desc: ''制卡失败时，你可以选择回溯时间，消耗大量精神力重新进行一次制卡过程，所有素材和状态将返回至制卡前。'' },
    { name: ''肉体圣杯'', rank: ''S'', desc: ''你的体液（血液、精液、唾液等）是顶级的制卡素材，能大幅提升卡牌的生命活性和对你的忠诚度，并必然产生“献身”或“淫乱”类词条。'' },
    { name: ''卡组世界'', rank: ''S'', desc: ''你的第一个【卡组】必将直接进化为【超级卡组】，并根据你的潜意识快速生成初始的【世界观背景】。'' },
    { name: ''机械飞升'', rank: ''S'', desc: ''你只能制作出机械类【卡牌】，同时你所有机械类【卡牌】全属性增加100%。'' },
    { name: ''道法自然（东方）'', rank: ''SS'', desc: ''你天生与大道相合，制卡时可大幅降低素材间的属性冲突，【对冲融合】的成功率与收益远超常人，万物皆可为你所用，制作的每张卡片都会有一个符合卡片特质的概念性词条。'' },
    { name: ''轮回圣瞳（东方）'', rank: ''SSS'', desc: ''你的双眼能勘破虚妄，洞悉因果。在制卡前，你能预见此次制作的四种结果（大成功、普通成功、可控失败、卡牌爆炸）的模糊画面与概率，并且可以花费所有MP指定结果。'' },
    { name: ''牛头人之神'', rank: ''SS'', desc: ''你可以强行控制敌人阵营不高于自己制卡师等级一级的【伙伴卡】叛变并且和自己发生任意性行为，性行为越大胆，敌方制卡师越容易进入【失控】状态，有直接失控的风险，而被你牛头人的敌方【伙伴卡】则会彻底听从你的命令，成为你的卡牌。'' },
    { name: ''完美幼妻'', rank: ''SS'', desc: ''你执着于创造完美的幼女。你可以将大量【幼女】型伙伴与【畸变】类素材进行融合献祭，通过残酷的淘汰与缝合，最终制造出一张拥有强大能力、外表天真可爱、内在绝对服从的强大幼女怪物伙伴。'' },
    { name: ''异种繁殖者'', rank: ''SS'', desc: ''你无视生殖隔离。你可以与任何伙伴卡，魔物，NPC（无论种族、形态）进行交配，并有百分之百产下继承双方天赋的【后代卡】。'' },
    { name: ''元素亲和'', rank: ''S'', desc: ''制作元素类卡牌时，成功率大幅提升，且卡牌威力大幅增强。'' },
    { name: ''废品专家'', rank: ''A'', desc: ''你总能从【可控失败】的废卡中发现意想不到的价值，其负面词条有概率转化为特殊正面词条。'' },
    { name: ''天生丹心（东方）'', rank: ''SS'', desc: ''你拥有成为炼丹大师的心窍，你可以将三个完全不同的素材放入心中丹炉炼制，炼制出没有任何负面词条，并且素材等级不变，完美融合三个素材优点的高级素材。'' },
    { name: ''女王特攻'', rank: ''S'', desc: ''你制作出的卡牌，都带有强烈的女s特征，伙伴卡更容易携带【女王】等词条，并且可以通过虐杀敌人或支配别人快速提升实力。'' },
    { name: ''魂之烙印'', rank: ''S'', desc: ''获得【魂缚仆从】【伙伴卡】（天赋）和附属【装备卡】（武器）【灵魂渔网】的制作方法。制作【魂缚仆从】需要较为完整的灵魂【素材】。成功后，该生物将转化为绝对忠诚的伙伴卡，保留其生前的部分技能与记忆，但其意识将被彻底奴役，成为制卡师最黑暗的棋子。'' },
    { name: ''血肉圣杯'', rank: ''S'', desc: ''你需在制卡时融入你自身的【本源精血】，通过消耗你的HP上限，制作强大的血族系卡牌。'' },
    { name: ''淫欲具象'', rank: ''S'', desc: ''获得【心魔魅影】【伙伴卡】（天赋）的制作方法。此伙伴卡会具象化为能勾起敌人内心最深处淫欲与恐惧的幻象，对其进行精神层面的绝对支配与折磨，甚至可以永久策反。'' },
    { name: ''畸变温床'', rank: ''S'', desc: ''获得【血肉殖装】【装备卡】（饰品）（天赋）的制作方法。【血肉殖装】是一种活体寄生装备，它会与宿主深度共生，通过吞噬其他装备卡或魔物血肉进行自我进化与变异。能提供强大的属性与随机技能，但同时也会不断侵蚀宿主的理智，存在被反噬的巨大风险。'' },
    { name: ''足下亡魂'', rank: ''S'', desc: ''你的女性伙伴卡通过踩踏攻击击杀敌人后，会从尸体上凝聚出【足下魂晶】素材，该素材是制作【诅咒】和【束缚】类技能卡的极品材料。'' },
    { name: ''法则扭曲者'', rank: ''S'', desc: ''获得【绝对王权】【领域卡】（天赋）的制作方法。在【绝对王权】领域内，制卡师可以指定一条战斗规则进行篡改（例如：将“治疗效果”转化为“伤害效果”，或“禁止敌方使用特定属性卡牌”）。此领域是足以逆转战局的霸道天赋。'' },
    { name: ''契约烙铁'', rank: ''S'', desc: ''获得【屈辱颈环】【装备卡】（饰品）（天赋）的制作方法。此装备卡只能为伙伴装备。被装备的【伙伴卡】将沦为制卡师的【奴隶】，属性增强50%，忠诚度清0，对制卡师本人极度抵触厌恶，但无法抗拒制卡师的任何命令。'' },
    { name: ''高跟践踏'', rank: ''B'', desc: ''你制作的所有【脚部】装备卡，都会自动附加【高跟】词条，装备该卡的女性伙伴卡，其移动会发出清脆的响声，对男性敌人造成【威慑】效果，并使其物理攻击附带【破甲】属性。'' },
    { name: ''万兽同衾'', rank: ''SS'', desc: ''你可以与你的任意兽人/福瑞伙伴卡进行【人兽合一】。融合期间，你获得其强悍的肉体与野性本能，它获得你的制卡能力与智慧，成为一个由你主导的完美战斗生物。'' },
    { name: ''娇小巨神兵'', rank: ''S'', desc: ''你只擅长制作体型娇小的女性伙伴卡（如萝莉、侏儒）。但你的所有伙伴卡都拥有【召唤巨神兵】的能力，可以召唤出与其体型形成巨大反差的机甲或魔像进行战斗，伙伴的属性会直接增幅于召唤物。'' },
    { name: ''人外新娘'', rank: ''S'', desc: ''制卡时，你可以献祭自己的精血作为核心素材。这会必定制作出一张强大的人外形态伙伴卡（如拉米亚、阿剌克涅、史莱姆娘等），她会将你视为唯一的配偶，对你抱有极端的忠诚与占有欲。'' },
    { name: ''永恒幼神'', rank: ''S'', desc: ''你制作的伙伴卡外表将永远停留在幼年期。但她们的本质是远古神灵的容器，实力不随等级提升，而是通过吞噬特定的祭品（稀有素材、其他卡牌、强烈的情感）来解锁更强大的力量。'' },
    { name: ''野兽乐园'', rank: ''S'', desc: ''你可以制作出专属领域卡【福瑞天堂】。在领域内，所有兽人、福瑞、兽娘友军都会获得高速再生和全属性加成，而所有人类敌人则会受到【原始恐惧】的精神压制。'' },
    { name: ''S级天赋·堕落圣女'', rank: ''S'', desc: ''当你击败【圣洁】、【神圣】属性的雌性单位时，有50%的几率使其【堕落】，转化为属性相反的【淫魔】或【荡妇】，并有极高概率直接收为伙伴卡。'' },
    { name: ''氪金大佬'', rank: ''S'', desc: ''制卡时，你可以投入【金钱】作为额外“素材。投入的金钱越多，制卡成功率越高，并且有更高概率出现【奢华】、【强运】等稀有正面词条。'' },
    { name: ''混沌赌徒'', rank: ''S'', desc: ''获得【潘多拉魔盒】【技能卡】（天赋）的制作方法。使用此卡将从一个包含“极度有利”和“毁灭性灾难”的混沌效果池中随机触发一个效果，作用于场上所有单位（包括自己）。是疯子与赌徒的最终王牌，能在一瞬间决定天堂或地狱。'' },
    { name: ''孕育之喰'', rank: ''S'', desc: ''获得【魔胎寄生】【技能卡】（天赋）的制作方法。此卡能将一枚【魔胎】植入敌人体内。经过一回合的潜伏孕育后，魔胎将从内部爆发，对宿主造成毁灭性穿透伤害，并根据宿主的等阶与属性，孵化出一只临时的【恶兆孽物】为你作战，战斗结束后，自动化为【魔胎晶体】素材。'' },
    { name: ''万法归寂'', rank: ''S'', desc: ''获得【禁忌石碑】【领域卡】（天赋）的制作方法。在【禁忌石碑】领域内，所有单位（包括自己）的【技能卡】将被封印，所有【装备卡】与【伙伴卡】的被动词条效果将被压制。该领域将一切化为原始的肉搏，是所有依靠复杂卡组配合的制卡师的噩梦。'' },
    { name: ''魅魔体质'', rank: ''S'', desc: ''你的身体对异性/同性有天然吸引力。进行【欲望主导】制卡时，失败的惩罚会转化为对你身体的快感奖励（参考xp）。'' },
    { name: ''调教大师'', rank: ''S'', desc: ''你可以对伙伴卡进行【调教】。每次成功调教后，可永久提升其一项基础属性，并解锁专属的顺从/淫乱词条。'' },
    { name: ''不等价交换'', rank: ''S'', desc: ''你可以将自己的【素材】和【卡牌】放弃，天赋会给你带来1-2个类型相同，品质不高于原【卡牌】/【素材】的回报。'' },
    { name: ''禁忌知识'', rank: ''S'', desc: ''你天生就能解读古代文献和禁忌魔法，制作的【卡牌】有概率携带禁忌词条，如“恶魔契约”、“灵魂囚笼”。'' },
    { name: ''淫欲化身'', rank: ''S'', desc: ''进行【欲望主导】制卡时，你不仅免疫精神侵蚀，还能将溢出的欲望能量凝聚成【欲望结晶】素材，在进化或制作卡牌时，加入此种【素材】可以让卡牌的欲望属性增强。'' },
    { name: ''巨女的蹂躏'', rank: ''S'', desc: ''你制作的女性【伙伴卡】体型会变得异常巨大。她们的普通攻击自带“震慑”和“碾压”效果，对体型小于自己的单位造成额外伤害。制卡时使用“体型”相关词条效果翻倍。'' },
    { name: ''双生羁绊'', rank: ''S'', desc: ''你可以指定两张伙伴卡建立【双生羁绊】，她们将共享感官和伤害，并能在战斗中释放强大的组合技。'' },
    { name: ''收缩射线'', rank: ''A'', desc: ''你制作的【技能卡】有概率附加【收缩】词条，可以暂时将敌方单位的体型缩小，大幅削弱其属性。'' },
    { name: ''素材点金'', rank: ''S'', desc: ''每天一次，你可以指定一个素材，使其品质提升一个大等级（如黑铁→青铜）。'' },
    { name: ''下克上'', rank: ''SS'', desc: ''你的卡牌在攻击实际等级（即不计算任何增益的原生等级）高于自身的敌人时，会获得【克上】效果，无视对方部分防御力并造成额外伤害。等级差距越大，该效果越强。'' },
    { name: ''玷污圣所'', rank: ''S'', desc: ''使用【神圣】或【纯洁】属性的素材进行制卡时，你有极高几率使其发生【恶堕】突变，卡牌将获得【淫纹】、【媚态】等强力魅惑系词条，但原有的神圣属性会转化为【亵渎】。'' },
    { name: ''堕落之种'', rank: ''S'', desc: ''进行【欲望主导】制卡时，你有概率向卡牌灵魂中植入“堕落之种”。拥有此种子的卡牌，在经历特定羞辱或快乐事件后，会开启【雌堕】或【恶堕】的专属进化路线。'' },
    { name: ''集群母狗'', rank: ''A'', desc: ''你拥有的【母狗】单位超过3个时，激活【犬舍】光环，所有【母狗】单位的全属性提升10%。每多拥有一个，额外提升2%。'' },
    { name: ''圣遗物'', rank: ''S'', desc: ''对于每一个人形态【伙伴卡】，你都可以指定一件物品（如丝袜、内裤、胸罩）作为伙伴卡的【圣物】。只要该伙伴卡向你奉献一件他/她穿戴过的圣物，战斗力就会大幅提升，甚至触发小幅度进化，穿戴的时间越久，沾染到的体味/气息越多，【伙伴卡】本身获得的增幅越强大。'' },
    { name: ''足尖舞者'', rank: ''S'', desc: ''你制作的伙伴卡，其“脚”部会得到超级强化，更喜欢使用腿法战斗。自带“高跟鞋踢”、“践踏”、“足交榨取”等特殊技能，对敌人造成物理与精神双重打击。'' },
    { name: ''纯真塑形'', rank: ''S'', desc: ''你制作的【伙伴卡】有极高概率以“幼态”或“萝莉”形态诞生，无论使用何种素材。这些卡牌拥有极高的成长潜力和更多的进化分支（始终保持幼态形象，不会长大），但初始能力较弱。'' },
    { name: ''恋足工匠'', rank: ''B'', desc: ''制卡时，你可以请求女性伙伴卡用玉足“祝福”核心素材（如踩踏、包裹）。被祝福的素材将自带【迷恋】与【足韵】词条，制成的卡牌将会和该伙伴卡联系更紧密，在卡组中配合更好，百分百出现羁绊。'' },
    { name: ''贡金契约'', rank: ''A'', desc: ''你每天必须向你的女性伙伴卡上缴一定数额的金钱作为“贡金”。上缴越多，她当天反馈给你的【女王的恩赐】随机buff就越强。若无法上缴，你将受到【奴隶的惩戒】debuff。'' },
    { name: ''虐待狂化'', rank: ''A'', desc: ''你的女性伙伴卡在HP低于30%时，会进入【虐待狂化】状态。攻击力与攻击速度大幅提升，但在战斗结束后，会持续虐待你直到【虐待狂化】状态结束。'' },
    { name: ''血灵根（东方）'', rank: ''S'', desc: ''你的体内有一股禁忌的东方之力——血灵根。它代表着生命的本源与邪道，在击杀敌人后，你可以通过吸收精血来补充体力，同时你必定获得被吸收者随机一个天赋或词条的弱化版，即低一个等级，你更容易创造出诡异强大的血咒卡牌。'' },
    { name: ''黄金浴'', rank: ''B'', desc: ''你的女性伙伴卡可以将体内多余的魔力转化为【黄金圣水】并喷射出去。该技能可大范围对敌人造成腐蚀伤害和强烈的【羞辱】debuff。'' },
    { name: ''无垢仙体（东方）'', rank: ''S'', desc: ''你的身体纯净无暇，能自动净化素材中的负面与杂质词条，并免疫一切诅咒与侵蚀。你是欲望主导流派天生的克星。'' },
    { name: ''功德金身（东方）'', rank: ''S'', desc: ''你的灵魂中蕴含着浩然正气，制卡时可将善念注入其中，创造出具有守护与净化奇效的卡牌。邪恶生物会对你产生天然的畏惧。'' },
    { name: ''榨精工坊'', rank: ''S'', desc: ''你获得特殊能力，可以将捕获的男性敌人或自愿的你作为“材料”，由女性伙伴卡进行“压榨”，产出等级等于被压榨的人等级的【生命精华】素材。该素材是制作高阶生命与召唤类卡牌的核心。'' },
    { name: ''雌雄同体'', rank: ''S'', desc: ''你制作的伙伴卡都有概率诞生为【Futa】形态，她们可以自我受孕，或让其他生物怀孕，射出的精液是极佳的【素材】，带有“繁殖”“生命”等词条，将普通【素材】浸泡在她们的精液里一天，可以直接变成一张有羁绊的，等级不变新卡牌。'' },
    { name: ''将就着用'', rank: ''A'', desc: ''你每天可以使一个等级不高于你一级的素材直接变成一张相关卡牌，卡牌等级低于原素材等级一级。'' },
    { name: ''退化射线'', rank: ''SS'', desc: ''你获得了【退化射线】【技能卡】（天赋）的制作方法，【退化射线】能将敌人的伙伴卡在战斗过程中降低一个等级，小概率永久变成小孩子（能力不流失）并直接倒戈到你的阵营。'' },
    { name: ''百毒之体（东方）'', rank: ''A'', desc: ''你天生不惧任何剧毒。处理剧毒素材时不会受到任何负面影响，并能最大化地提炼其毒性词条。'' },
    { name: ''魔种寄生（东方）'', rank: ''A'', desc: ''一颗上古魔种寄生在你的心脏。它时刻引诱你堕落，但也赋予你强大的力量。使用【欲望主导】流派制卡时，效果和成功率提升，但每次都会侵蚀你的理智，入魔可以短暂增强你的实力，但会大幅影响心智。'' },
    { name: ''炼金巧手'', rank: ''A'', desc: ''分解素材时，有较高概率获得额外的稀有材料。'' },
    { name: ''战场直觉'', rank: ''B'', desc: ''在战斗中，你能敏锐地察觉到敌人的弱点，暴击率提升20%。'' },
    { name: ''痛苦链接'', rank: ''A'', desc: ''制卡失败或卡牌爆炸时，你受到的伤害和损失的mp会转化为等量的MP，并且下一次制卡成功率小幅提升。'' },
    { name: ''魔物亲和'', rank: ''A'', desc: ''你可以与部分智慧型魔物进行交流。使用魔物素材制卡时，有更高概率保留其原始的野性词条。'' },
    { name: ''黑市贵宾'', rank: ''A'', desc: ''你在黑市中声名远扬，所有交易都能享受折扣，并能接到一些不对外开放的特殊委托。'' },
    { name: ''活体巢穴'', rank: ''A'', desc: ''获得【虫巢子宫】【装备卡】（饰品）的制作方法。【虫巢子宫】可寄生于雌性伙伴体内，通过持续吸收其生命力与淫液来孕育并高速产下悍不畏死的虫族战士。生产过程会为新生虫群附加短暂的狂暴效果。'' },
    { name: ''糖果与鞭挞'', rank: ''A'', desc: ''制作萝莉型伙伴卡时，会附加【双面】词条，使其在可爱外表下拥有截然相反的腹黑或病娇人格，并获得一套独立的技能组。'' },
    { name: ''圣水之泉'', rank: ''A'', desc: ''获得【祝福之泉】【领域卡】（天赋）的制作方法。需指定一名伙伴卡在领域中心持续撒尿，其尿液将形成大喷泉，治愈友军并净化负面状态；同时，尿骚味会对敌人造成精神冲击与属性腐蚀。'' },
    { name: ''血肉契约'', rank: ''A'', desc: ''获得【血肉魔偶】【伙伴卡】的制作方法。允许制卡师将生物（包括自己）的血肉肢体作为核心素材，制造出绝对忠诚的魔偶。使用的血肉部位越关键、越新鲜，魔偶的初始属性与成长潜力就越强。'' },
    { name: ''精神烙印'', rank: ''A'', desc: ''获得【支配项圈】【技能卡】的制作方法。该项圈可强行作用于敌人颈部，通过注入混合着痛苦与快感的精神冲击来摧毁其意志，有较高概率将其转化为临时奴隶。失败将遭到精神反噬，陷入痴呆。'' },
    { name: ''榨精魔纹'', rank: ''A'', desc: ''获得【淫纹附体】【技能卡】的制作方法。可将此魔纹烙印在任何生物身上，使其陷入永恒的性高潮状态，不断榨取其生命力与魔力反哺给施术者，直至对方化为干尸。'' },
    { name: ''丝袜裁缝'', rank: ''A'', desc: ''你天生擅长制作丝织品。在制作【腿部】和【脚部】的袜类装备卡时，材料消耗减少，且必定会附加一个随机的正面词条（如【诱惑】、【坚韧】、【轻盈】）。'' },
    { name: ''明日方舟'', rank: ''SSS'', desc: '' 你获得自带世界观和领域卡的超级卡组【罗德岛】，但你有且只能拥有这一个卡组，你制作的伙伴卡转化拥有一定兽类特征的【明日方舟】系列生物。【明日方舟】必定拥有一个【源石技艺】词条，并且拥有较高的初始数值，和伤害能力，可能会携带有【矿石病】词条，矿石病词条极难摘除和覆盖，战斗都有可能触发导致体质下降，与血量上限减少，还携带有【信赖度】词条：拥有专门的信赖度条目，与好感度挂钩，信赖度越高战斗能力便越强，基础数值也会有一定增幅。'' },
    { name: ''生命摇篮'', rank: ''S'', desc: ''你的灵魂深处烙印着生命最原始的法则。你制作的所有【女性伙伴卡】都将获得一个主动技能【原始胎动】：激活后，该伙伴将化为生命源泉，每隔数秒以自身为模板，消耗少量MP孵化出一个同种类的衍生物。'' },
    { name: ''军团熔炉'', rank: ''SSS'', desc: ''你可以将多张【伙伴卡】的灵魂强行熔炼于一炉。通过献祭至少三张伙伴卡，你能将它们的灵魂、天赋和技能糅合成一张全新的、拥有复数天赋的【集合体】或【神格】卡。这是一条通往人造神祇的禁忌之路。'' },
    { name: ''寄生殖入'', rank: ''SS'', desc: ''你制作的卡牌是活体寄生卵。你可以将这些“卡牌”植入生物体内，它们会汲取宿主的生命力成长。成熟后，宿主会被瞬间改造，破体而出一个完全忠于你，并且吸收母体和寄生卡牌所有特性的强大生物兵器伙伴卡。被植入者等阶越高，兵器越强。'' },
    { name: ''痛苦引擎'', rank: ''S'', desc: ''你深知痛苦是最高效的燃料。在制作任何卡牌时，你都可以选择对其“施虐”，大幅降低其初始忠诚度或增加一个负面词条，以此为代价，强制提升该卡牌一个大等级。此法制作的伙伴卡会对除你之外的一切生物抱有极端的施虐倾向。'' },
    { name: ''自体熔炉'', rank: ''S'', desc: ''你能将活物直接作为燃料和材料投入你的【移动工厂】机械中。被吞噬的生物等级越高，工厂生产出的【自走火炮】或【突击傀儡】的品质就越好。这些被生产出的机械单位会发出酷似被吞噬者的悲鸣。'' },
    { name: ''机械福音'', rank: ''SSS'', desc: ''你能制造并散播一种【机械飞升】病毒。该病毒会感染一切有机生命体，将其DNA改写，不可逆地从分子层面转化为生物机械。你将成为新世界的唯一造物主，所有被转化的生命都将视你为神，组成绝对忠诚的机械军团。'' },
    { name: ''肉便器烙印'', rank: ''A'', desc: ''你制作的【伙伴卡】将自动获得[肉便器]词条，该伙伴卡无法反抗你的任何命令，且其MP会转化为【淫力】，每次被肏干都能恢复。'' },
    { name: ''忠诚之鞭'', rank: ''A'', desc: ''获得【调教鞭】【装备卡】的制作方法，使用该卡牌鞭打你的伙伴或奴隶，会小幅降低其HP，但能大幅提升其【忠诚度】和短时间内的攻击力。'' },
    { name: ''痛苦回响'', rank: ''A'', desc: ''获得【荆棘之心】【技能卡】的制作方法。被动技能，将自身或伙伴卡受到的所有伤害（尤其是痛觉）转化为“纯粹痛苦”，按一定比例无视防御地反射给攻击者，是典型的受虐狂M体质神技。'' },
    { name: ''强制受孕'', rank: ''A'', desc: ''获得【温床刻印】【技能卡】的制作方法。此歹毒印记可打入敌人体内，强制其子宫（无论男女）在数秒内受孕并孕育出一头凶暴的“寄生孽子”。孽子会啃食母体，破体而出后为己方作战。'' },
    { name: ''恋物化身'', rank: ''A'', desc: ''获得【胶衣囚笼】【技能卡】的制作方法。可将敌人强制转化为一件拥有其意识的紧身胶衣。穿上此胶衣的单位将获得极高的防御力和韧性，并能利用囚笼内灵魂的挣扎来发动窒息与束缚攻击。'' },
    { name: ''污秽之力'', rank: ''A'', desc: ''获得【绝望泥沼】【领域卡】（天赋）的制作方法。制卡时需混入大量粪便、腐尸等污秽之物。领域内，敌人将持续受到“恶臭”与“不洁”影响，全属性大幅降低，而亡灵、恶魔等友军单位则会获得强化。'' },
    { name: ''排泄之友'', rank: ''A'', desc: ''你能够处理并使用【黄金圣水】、【圣乳】等极度污秽或神圣的体液素材。这类素材制成的卡牌效果极强且带有剧毒或强力净化，但制卡失败时会引发【精神污染】，让你陷入对应的色情幻觉。'' },
    { name: ''机械改造'', rank: ''A'', desc: ''你可以进行残忍的活体改造手术，将生物肢体替换为精密的机械造物，大幅提升其战斗能力。改造过程不可逆，且有概率发生排异反应导致机体崩溃。'' },
    { name: ''便器改造师'', rank: ''A'', desc: ''你可将【不入流】至【青铜】级的雌性伙伴卡，永久改造为【专属肉便器】，失去战斗能力，但会定期产出【污浊的魔力结晶】。'' },
    { name: ''萝莉养成'', rank: ''A'', desc: ''你培育【萝莉】伙伴卡的效率提升100%。通过【调教】指令，你可以自定义她们的成长方向，甚至为其增添新的词条。'' },
    { name: ''烙印支配者'', rank: ''A'', desc: ''你可以给伙伴卡打上专属的【烙印】，带有烙印的伙伴卡无法背叛你，且你能随时感知到她们的位置和情绪。'' },
    { name: ''雷灵根（东方）'', rank: ''A'', desc: ''你的体内有一股狂暴的东方之力——雷灵根。它是天罚的化身，你制作的卡牌会附带毁灭性的雷霆灵力，迅捷且霸道。'' },
    { name: ''风灵根（东方）'', rank: ''A'', desc: ''你的体内有一股飘逸的东方之力——风灵根。它是自由的象征，你制作的卡牌会附带灵动的风之灵力，轻盈且迅疾。'' },
    { name: ''冰灵根（东方）'', rank: ''A'', desc: ''你的体内有一股极寒的东方之力——冰灵根。它是万物寂灭的体现，你制作的卡牌会附带冻结一切的玄冰灵力，兼具控制与杀伤。'' },
    { name: ''触手之友'', rank: ''A'', desc: ''你天生对触手类生物有极强的吸引力。制作或使用触手类卡牌时，效果增强30%，且能通过与触手交媾来恢复精神力。'' },
    { name: ''卡牌美食家'', rank: ''A'', desc: ''你可以通过“吃掉”卡牌来分解它，获得比普通分解更多的核心素材，并有小概率直接领悟卡牌的部分能力。'' },
    { name: ''催眠之瞳'', rank: ''A'', desc: ''你的眼睛拥有微弱的催眠能力，在与NPC交涉时成功率提升。在制卡时，可以对素材进行“催眠”，使其词条更易于引导。'' },
    { name: ''A级天赋·强制排卵'', rank: ''A'', desc: ''你可以强制刺激雌性伙伴卡或俘虏，使其在短时间内排出大量【卵子】，这是一种【白银】级的稀有生物素材。'' },
    { name: ''流体亲和'', rank: ''A'', desc: ''你对史莱姆、元素凝胶等流体生物有特殊亲和力，能将它们制作成具有塑形、束缚、侵蚀，吞噬等能力的特殊卡牌。'' },
    { name: ''共鸣之躯'', rank: ''A'', desc: ''制卡时，你可以与主素材进行精神共鸣，亲身体验其核心情感，大幅提升保留高品质词条的概率。'' },
    { name: ''血肉炼成'', rank: ''A'', desc: ''你可以将自己的血肉作为素材融入卡牌，大幅提升卡牌的生命链接，但会永久消耗HP上限。'' },
    { name: ''卡牌附身'', rank: ''A'', desc: ''你可以让一张【伙伴卡】临时附身于你，借用其部分能力和属性，但期间你的身体主导权会受到伙伴卡性格的影响。'' },
    { name: ''深渊墨水'', rank: ''A'', desc: ''每天都会获得一份【深渊墨水】，你可以使用【深渊墨水】作为制卡素材。使用后，必定为卡牌附加“恶堕”或“魔化”词条，并扭曲其原有词条，使其变得更具魔幻性与侵略性，但是失败和发生变异的可能性同时增大。'' },
    { name: ''雌堕改造师'', rank: ''A'', desc: ''你擅长制作改变性征的装备卡和消耗品。对男性伙伴卡使用时，可逐步改变其身体与心智，解锁“伪娘”、“扶他”或“彻底变性”等特殊形态，并重塑其技能组。'' },
    { name: ''破瓜者'', rank: ''A'', desc: ''成功夺取雌性生物的第一次后，你将永久夺取其1个随机词条，并可获得特殊素材【染血的元阴】。'' },
    { name: ''魔乳炼成'', rank: ''A'', desc: ''（仅限女性/Futa伙伴卡）你可以提取伙伴卡的乳汁作为【素材】，能显著提升制卡成功率，并有概率为卡牌附加“哺乳”、“催乳”、“巨乳化”等特殊词条。'' },
    { name: ''圣秽之躯'', rank: ''A'', desc: ''你制作的【伙伴卡】有大概率携带“圣遗物”词条，拥有该词条的【伙伴卡】，他/她的所有排泄物都有非常强大的恢复能力和随机正向buff，是超级恢复药剂，但是本身携带的异味会放大两倍。'' },
    { name: ''嫉妒之火'', rank: ''A'', desc: ''当你的伙伴卡与除你之外的任何人（包括敌人）发生亲密互动被你目击时，你的下一次制卡必定会触发【良性突变】。'' },
    { name: ''肉体改造家'', rank: ''A'', desc: ''你可以主动在制卡时添加“改造”词条，为诞生的伙伴卡附加额外的非人部件，如触手、翅膀、兽耳等，并赋予其相应能力。'' },
    { name: ''魅魔君主'', rank: ''A'', desc: ''你制作的所有卡牌，都会天生带有“吸精”词条，可以通过性行为从任何生物身上汲取生命力和魔力，用于自我恢复和成长。'' },
    { name: ''幸运星'', rank: ''B'', desc: ''你的【幸运】属性额外提升20点。赌卡时手气更好。'' },
    { name: ''精力旺盛'', rank: ''B'', desc: ''你的HP和MP上限永久提升20%。'' },
    { name: ''淫纹共鸣'', rank: ''B'', desc: ''你可以通过与伙伴卡进行色情互动来暂时提升其战斗力，并在伙伴卡身上留下临时的【淫纹】。'' },
  { "name": "活体工具", "rank": "C", "desc": "倾向于制造拥有工具特性（如【钻头】、【熔炉】）的生物卡，它们既能战斗，也能辅助进行工程或锻造活动。" },
  { "name": "不死奴仆", "rank": "C", "desc": "使用尸体作为材料时，有较高概率完美保留死者生前的部分战斗技巧，制造出精英亡灵。" },
  { "name": "亡者低语", "rank": "D", "desc": "制作亡灵卡牌时，能听到它们的低语，更容易制造出拥有特殊记忆或技能的亡灵。" },
  { "name": "风之语者", "rank": "D", "desc": "制作的飞行单位或风元素卡牌，飞行速度和灵活性获得小幅提升。" },
  { "name": "潮汐之心", "rank": "C", "desc": "对【水】与【冰】属性有天生的亲和力，制作此类卡牌时成功率更高，且有小概率附加【潮湿】或【迟缓】效果。" },
  { "name": "魔能熔炉", "rank": "A", "desc": "你可以将两张低于你制卡师等级一阶或以下的卡牌熔炼，有概率获得一张更高级的、融合两者特性的新技能卡，但也有可能彻底损毁。" },
  { "name": "活体熔炉", "rank": "A", "desc": "你可以将【野兽】与【机械】材料融合，创造出独一无二的【生化机械兽】，它们兼具生物的恢复能力和机械的坚固。" },
  { "name": "神之血", "rank": "A", "desc": "使用蕴含“神性”的材料时，有概率制造出【天使】、【英灵】等伙伴卡，她们拥有强大的圣属性，并天生对恶魔、亡灵有克制效果。" },
  { "name": "堕落的救赎", "rank": "A", "desc": "你对【圣洁】或【纯洁】的伙伴卡使用“堕落”材料（如淫纹、恶魔之血）时，有概率使其转化为属性更强、技能更具侵略性的【堕落】形态。" },
  { "name": "古代知识", "rank": "S", "desc": "你能够解读并制作【古代】或【失落】文明的卡牌，它们往往拥有独特而强大的机制，但材料也极为稀有。" },
  { "name": "战争之王", "rank": "A", "desc": "你场上的伙伴卡数量越多，所有伙伴卡的攻击力越高（每多一张+5%）。" },
  { "name": "悖论制造者", "rank": "A", "desc": "你制作的卡牌有概率同时拥有两个完全相反的词条（如【火焰亲和】与【寒冰之躯】），并能从中获得意想不到的强大力量。" },
  { "name": "无限军火库", "rank": "S", "desc": "你的所有伙伴卡，装备【装备卡】时不再有部位限制，一个伙伴可以同时装备多把武器或多件盔甲。" },
  { "name": "卡牌降临", "rank": "S", "desc": "你可以将一张伙伴卡以【降临】形态召唤到自己身上，短时间内获得该伙伴的核心能力与外貌特征，成为一个强大的战士。" },
  { "name": "最终兵器", "rank": "S", "desc": "你的卡组中只能放入一张伙伴卡。但这张卡牌的所有基础属性翻倍，且可以装备的装备卡数量翻倍。" },
  { "name": "群星的回想", "rank": "A", "desc": "每轮对话，群星会告诉你一个关于卡兰大陆的情报。你也可以主动问你想知道的，但需要花费一定代价。" },
  { "name": "空白卡牌", "rank": "SSS", "desc": "你能创造出【空白卡牌】。它没有任何属性和描述。在任何对局中，你可以消耗这张卡，将其永久变为你此生亲眼见过的任何一张卡牌的完美复制品，复制品等级和体现出的战力水平永远跟你的等级相等，也可不断成长。" },
  { "name": "复古风尚", "rank": "E", "desc": "制造出的卡牌，无论是人物还是装备，总会带有一些过时或复古的设计元素。" },
  { "name": "匠人之手", "rank": "D", "desc": "制造出的装备卡外观会格外精致，虽然属性不变，但在交易时能卖出更高的价格。" },
  { "name": "野性呼唤", "rank": "C", "desc": "使用高等级的魔兽素材，伙伴卡有极高概率觉醒【兽化】词条，可以在短时间内展现部分野兽特征，战斗风格狂野。" },
  { "name": "巨物崇拜", "rank": "C", "desc": "你制造的伙伴卡有更高概率获得【巨乳】或【丰臀】词条，同时，你制造的武器也倾向于巨大化，如巨剑、巨斧。" },
  { "name": "娇小可爱", "rank": "C", "desc": "你制造的伙伴卡有更高概率获得【萝莉】或【贫乳】词条，她们身形小巧，擅长闪避和潜行。" },
  { "name": "废土朋克", "rank": "C", "desc": "你制造的卡牌充满废土气息，伙伴卡像是拾荒者，装备由破铜烂铁拼接而成，性格坚韧而多疑。" },
  { "name": "抖S气场", "rank": "C", "desc": "伙伴卡天生带有女王或施虐者的气质，她们的攻击有一定概率让敌人陷入【畏缩】状态。" },
  { "name": "武器拟人", "rank": "C", "desc": "可以将【装备卡】作为核心材料，制造出该武器的“器灵”伙伴卡，其性格和能力与武器特性息息相关。" },
  { "name": "百合之友", "rank": "C", "desc": "制造出的女性伙伴卡，会对其他女性角色抱有更高的初始好感度，有概率触发女性限定的【羁绊】。" },
  { "name": "家畜化", "rank": "B", "desc": "使用牲畜类材料，伙伴卡会带有【家畜】词条，她们性格温顺，任劳任怨，并且在被“饲养”（提供食物和住所）时，能缓慢产出特殊素材。" },
  { "name": "双生梦魇", "rank": "A", "desc": "制造伙伴卡时，有一定概率额外生成一张同名的“镜像”卡。两张卡共享生命，但性格与能力往往截然相反，一个是光，另一个就是影。" },
  { "name": "童话编织者", "rank": "A", "desc": "你能以“童话故事”为蓝本制造卡牌，并能自由扭曲其设定，例如制造出“猎杀王子的白雪公主”或“用魔法开办工厂的灰姑娘”。" },
  { "name": "神性窃取", "rank": "S", "desc": "使用蕴含“神性”的物品作为材料，你有极小概率能窃取一丝神性，制造出拥有【伪神】词条的伙伴卡，她们拥有微弱的权能，但性格极其傲慢。" },
  { "name": "卡组生态", "rank": "SS", "desc": "你构筑的卡组不再是卡牌的集合，而是一个微缩的生态系统。卡牌之间会自行繁衍、捕食、进化，你需要像“神”一样去维护这个生态的平衡。" },
  { "name": "世界之种", "rank": "SSS", "desc": "你有极小概率制造出名为“世界之种”的特殊领域卡，它是一个可以成长的微缩世界。你在这个世界里是唯一的“神”，可以培养其中的生物，最终将它们转化为你的卡牌。" },
  { "name": "画师", "rank": "SS", "desc": "卡牌的强度不再取决于材料，而取决于你的“画技”。你亲手绘制的卡面越精美、越富神韵，卡牌的最终能力就越强大。你可以随时修改卡面，从而调整卡牌的技能。" },
  { "name": "作者", "rank": "SSS", "desc": "你意识到你并非“存在”，而是在“叙述”。你可以通过在脑内书写“旁白”来影响现实。例如，当你描述“他脚下一滑”时，你的敌人真的会平地摔倒。这种力量的滥用会引来世界意志的反噬。" },
  { "name": "模组加载", "rank": "SSS", "desc": "你可以将其他世界的“设定”或“系统”以模组的形式加载到自己的认知中。例如，加载“宝可梦模组”后，你可以通过精灵球捕捉魔物；加载“老头环模组”后，你可以通过赐福来复活。" },
  { "name": "玩家", "rank": "SSS", "desc": "你觉醒了“玩家”的本质。你可以看到其他制卡师看不到的隐藏数值、任务线和攻略提示。你甚至可以拥有一个【系统背包】，容量无限，且其中的物品不会被抢夺或损坏。" },
  { "name": "GM权限(伪)", "rank": "SSS", "desc": "你每天可以发布三条“指令”，这些指令会以极高的优先级被世界规则执行。例如：“/give item [稀有素材] 1”或“/weather clear”或“/kill [指定低等级魔物]”。指令的复杂度越高，成功率越低。" },
  { "name": "巨力崇拜", "rank": "D", "desc": "倾向于制造拥有【巨力】词条的卡牌，它们攻击更高，但攻击速度和命中率会下降。" },
  { "name": "梦境织造者", "rank": "D", "desc": "在睡眠后立即制卡，能将梦境碎片融入其中，制成的卡牌效果会变得难以预测，时好时坏。" },
  { "name": "暗影仆从", "rank": "D", "desc": "制作的刺客或侦察型伙伴卡，在阴影中的潜行能力获得小幅提升。" },
  { "name": "圣光亲和", "rank": "D", "desc": "倾向于制造治疗与祝福类卡牌，对亡灵单位的伤害有额外加成。" },
  { "name": "腐败之触", "rank": "D", "desc": "使用带毒或腐烂的材料时，能更有效地提取毒素，制成的卡牌大概率附加【中毒】效果。" },
  { "name": "水晶雕刻家", "rank": "D", "desc": "使用水晶或宝石制卡时，成品有更高概率附加【魔法增幅】或【精神守护】词条。" },
  { "name": "战场工程师", "rank": "D", "desc": "擅长制作陷阱、路障、简易炮台等功能性构装体卡牌。" },
  { "name": "劣质金属通晓", "rank": "E", "desc": "使用铁、铜等低级金属材料时，制成的卡牌物理防御有极其微弱的提升。" },
  { "name": "木材亲和", "rank": "E", "desc": "使用木头作为核心材料时，制成的卡牌会拥有更强的韧性，不易被物理攻击直接摧毁。" },
  { "name": "健壮之触", "rank": "E", "desc": "制作生物类卡牌时，有微小概率为其附加【健壮】词条（生命值+5%）。" },
  { "name": "敏锐之刻", "rank": "E", "desc": "在卡牌上铭刻风或羽毛的符号时，有微小概率使其获得【轻盈】词条（敏捷+5%）。" },
  { "name": "石之心", "rank": "D", "desc": "使用“岩石”、“矿物”类材料时，更容易制造出拥有更高HP和【坚韧】词条的伙伴卡，但敏捷通常偏低。" },
  { "name": "嗜血本能", "rank": "D", "desc": "制造【野兽】卡时，有微小概率出现【嗜血】词条，击杀单位后回复少量生命。" },
  { "name": "尖锐化", "rank": "D", "desc": "使用“兽牙”、“利爪”材料时，更容易为武器卡附加微量的【破甲】效果。" },
  { "name": "寒气入门", "rank": "D", "desc": "使用“冰霜”材料时，有微小概率为攻击附加短暂的【寒冷】效果，略微降低目标攻速。" },
  { "name": "毒素入门", "rank": "D", "desc": "使用“毒囊”等材料时，有微小概率附加【中毒】效果，造成极微弱的持续伤害。" },
  { "name": "冰结之心", "rank": "C", "desc": "稳定制造出拥有【冰冻】（强减速）或【冻结】（定身）能力的卡牌，制卡师本人对寒冷效果有较高抗性。" },
  { "name": "雷电召唤师", "rank": "C", "desc": "可制造连锁闪电或单体高爆发的雷电系技能卡，有概率附加【麻痹】效果。" },
  { "name": "地形术士", "rank": "C", "desc": "可制造【石墙】、【地刺】、【流沙】等地形控制类卡牌，擅长分割战场和限制敌人移动。" },
  { "name": "墓穴领主呼唤", "rank": "B", "desc": "可使用高等级灵魂和尸体，制造出强大的【亡灵】单位（如幽魂、僵尸龙），并能通过【亡者契约】让所有亡灵单位共享增益。" },
  { "name": "深渊编织者", "rank": "S", "desc": "可使用“古神残片”、“异界血肉”等材料，制造出拥有【触手】攻击的伙伴卡，擅长【束缚】和【精神污染】，其攻击带有强烈的色情与恐怖暗示。" },
  { "name": "巨龙血脉（伪）", "rank": "S", "desc": "你制作的卡组都拥有微弱的龙系血脉。可制造【龙息】（伪）、【龙威】（伪）等技能卡。" },
  { "name": "元素融合", "rank": "A", "desc": "制卡时，可将两种不冲突的元素材料（如火焰和大地）融合，制造出拥有双重属性的卡牌（如【熔岩】）。" },
  { "name": "英雄之王", "rank": "A", "desc": "你可以将传说级英雄的“圣遗物”作为核心，制造出独一无二的【英灵】伙伴卡。一个卡组只能存在一张【英灵】卡，但它的战斗力远超同级，并拥有复数个专属技能。" },
    { name: ''水仙之爱'', rank: ''SS'', desc: ''你制作的第一张伙伴卡不需要任何材料。你制作的第一张伙伴卡是你本人的性转后的姿态。你们共享知识、记忆、能力，当任意一方变强时，另一方都会同步获得相同幅度的强化。'' },
    { name: ''速度与激情'', rank: ''B'', desc: ''制作的所有卡牌额外获得【加速】和’【暴击】效果。'' },
    { name: ''后宫三千'', rank: ''SSS'', desc: ''你获得自带世界观和领域卡的超级卡组【后宫宫殿】，召唤卡为【太监】和【宫女】，同时你也只能拥有这一个卡组，你只能制作女性伙伴卡，且由你亲自制作的伙伴卡必定符合你自身的xp，你做出的伙伴卡会自动成为你的妃子，对你的忠诚度锁定100.，后宫中含有位份设定，你可以通过封妃的方式为卡组中的伙伴卡提供增益，皇后则是你的卡组核心，获得所有伙伴卡全属性的10%。'' },
    { name: ''铸剑为犁'', rank: ''A'', desc: ''你制造战斗系卡牌的成功率下降，制作工具类、服装类卡牌时，必定触发【良性突变】。'' },
    { name: ''我来！我见！我征服！'', rank: ''SSS'', desc: ''每击败一名目标，你获得一层【征服】印记，进入战斗后，每层【征服】印记会使你方全体在造成伤害后额外造成5%的附加伤害。'' },
    { name: ''母畜牧场'', rank: ''SSS'', desc: ''你获得自带世界观和领域卡的超级卡组【母畜欢乐牧场】，你只能拥有这一个卡组，该卡组只能由雌性组成，可以塞入任意雌性生物，你可以对其中的任意母畜进行【配种受孕】，受孕的母畜将会定期出产【畜奶】【畜蛋】【畜毛】等素材素材品质根据母畜品质决定。该卡组可以通过对母畜进行【出栏转生】的方式重新变成【转生畜蛋】可以指定母畜孵化成【小母畜】，属性根据孵化者和【出栏转生】母畜决定，保留转生前的记忆。'' },
    { name: ''碧蓝航线'', rank: ''SS'', desc: ''你获得自带世界观和领域卡的超级卡组【碧蓝航线】，但你有且只能拥有这一个卡组，你只能制作女性伙伴卡，你制作的伙伴卡转化为有少女外观，带有特殊武装：【舰装】的【舰娘】系列生物，【舰装】分为舰炮/鱼雷/飞机三种，并获得特殊词条【舰种】，【舰种】必定为【驱逐舰】【战列舰】【航空母舰】中的一种，并带有不同武装（驱逐舰带有鱼雷、战列舰带有舰炮、航空母舰带有舰载机）你做出的伙伴卡会认定你是指挥官，对你的忠诚度锁定100。'' },
    { name: ''母马驯师'', rank: ''S'', desc: ''将雌性目标永久改造为保留心智的【人形母马】，通过【调教】与【骑乘】将其彻底【驯服】后，她将成为集高速移动、恢复支援与专属战斗技能于一体的【专属坐骑】。'' },
    { name: ''闪耀！优骏少女！'', rank: ''SSS'', desc: ''你获得自带世界观和领域卡的超级卡组【特雷森学园】，但你有且只能拥有这一个卡组，你只能制作女性伙伴卡，你制作的伙伴卡转化为有少女外观，长有马耳和马尾巴的【赛马娘】系列生物。【赛马娘】必定拥有一个奔跑类词条，并且拥有较低的初始数值和超高的成长能力，可以通过训练无上限的提高能力和获取技能，并带有【一心同体】词条，和你的好感度越高，越能爆发出超出本身数值的战斗力。。'' },
    { name: ''尤格萨隆的低语'', rank: ''SSS'', desc: ''你制作时使用了多少词条，卡牌就会由完全随机的生成相应数量的词条组成，与制作词条属性完全无关。。'' },
    { name: ''对魔忍'', rank: ''A'', desc: ''你的攻击，防御，敏捷都会大幅提升，但是你的幸运会下降，并且身体敏感度增长为原先的3千倍。'' },
    { name: ''血伶人'', rank: ''SS'', desc: ''你可以直接将活物作为素材制作卡牌(无需分解)，而且你可以按照你的想法随意塑造卡牌形状，当你的伙伴卡阵亡之后你可以复活她。'' },
    { name: ''败北强化'', rank: ''B'', desc: ''当你战败时，得到经验值加成，在战败后受到的凌辱越强，提供的经验加成与属性加成便越多。'' },
    { name: ''地精国王'', rank: ''S'', desc: ''你会被野生的哥布林当作国王崇拜，并且制作有关哥布林的卡牌时必定大成功。'' },
    { name: ''再生'', rank: ''S'', desc: ''你的身体拥有极其强大的再生能力，不会真正的死亡，哪怕是变成肉块都能重新活过来。'' },
    { name: ''姬骑士军团'', rank: ''SS'', desc: ''你在制作姬骑士相关卡牌时必定大成功，且开局自带一张白银级姬骑士伙伴卡。'' },
    { name: ''成龙'', rank: ''A'', desc: ''你可以把任何东西当作装备来使用。'' },
    { name: ''蛇符咒'', rank: ''S'', desc: ''你可以隐身。'' },
    { name: ''巨人'', rank: ''B'', desc: ''你有九米高。'' },
    { name: ''窃智术'', rank: ''SSS'', desc: ''你可以窃取他人的智力。'' },
    { name: ''白给之人'', rank: ''D'', desc: ''无论你的实力有多么强大，每次战斗你都注定败北。'' },
    { name: ''爬虫王朝'', rank: ''S'', desc: ''当你制作有关爬行类卡牌时必定大成功，并且开局就拥有一张青铜级爬行类伙伴卡。'' },
    { name: ''贝蒙斯坦'', rank: ''S'', desc: ''你可以吸收魔法和远程攻击，将其转换为hp和mp。'' },
    { name: ''百合绿奴'', rank: ''C'', desc: ''当你为女性或FUTA时，你的女性伙伴卡必定出轨，每次出轨你一定知道，并且每次出轨都会获得大量经验值。'' },
    { name: ''植物大战僵尸'', rank: ''SS'', desc: ''你在制作植物和亡灵卡时必定大成功。'' },
    { name: ''百合破坏'', rank: ''B'', desc: ''当你对一对百合进行牛头人时，获得大量经验值。'' },
    { name: ''兔女郎爱好者'', rank: ''SS'', desc: ''当你在制作有关兔女郎和兔子的卡时必定大成功，并且你可以将其他卡转化为兔女郎。'' },
    { name: ''痛苦阶梯'', rank: ''S'', desc: ''该伙伴卡获得一个独特的“痛苦”能量槽，通过对敌人造成伤害和折磨来填充。能量槽每填满一阶，她的体型和力量都会发生一次可见的、永久性的增长，同时性格会变得更加残暴嗜虐。'' },
    { name: ''恐虐印记'', rank: ''S'', desc: ''使用恶魔或混沌类素材制卡时，伙伴卡将携带“恐虐印记”，每次击杀敌人都能获得一层“杀戮祝福”，提升伤害和体型，最多叠加8层。'' },
    { "name": "肉体改造师", "rank": "SS", "desc": "在制卡过程中，你可以精细调整女性伙伴卡的肌肉群分布，可以特化【腿部】力量以获得毁灭性的踢技，或特化【背部】力量以增强摔投威力。" },
    { "name": "泰坦尼亚的血脉觉醒", "rank": "SSS", "desc": "你制作的女性伙伴卡将直接继承远古泰坦女王的血脉。她的体型可以自由在【常人】和【巨神】（高达50米）之间切换。在巨神形态下，她拥有毁天灭地的力量和极高的抗性，但在常人形态下，她将泰坦之力浓缩于一体，获得无与伦比的爆发速度和格斗技巧。" },
    { "name": "最终兵器：她", "rank": "SSS", "desc": "你将创造的不再是伙伴，而是一个拥有自我进化能力的【最终兵器】。她初始能力普通，但拥有【无限适应】天赋。每次战斗结束后，她都会根据战斗数据进行自我优化和改造，进化出克制敌人的能力。假以时日，她将成为一切天敌的克星，所有生命的终点。" },
    { name: ''军团之主'', rank: ''A'', desc: ''制卡时，你可以明确你创造的卡牌是个性鲜明的【领军】或是数量众多的【士兵】，前者则根据素材，必定拥有强大的独特技能并且性格突出，后者则必定带有【群体召唤】词条，卡牌内并非一张卡，而是一支队伍，但数值将平均分配至每个单位。'' },
    { name: ''哥布林孕袋'', rank: ''S'', desc: ''用【哥布林】素材制卡必定成功，并固定为【哥布林】系列卡牌；若素材为【哥布林】体液，则制作伙伴卡必定大成功。制作的【哥布林】伙伴卡性格倾向：强欲/狡黠/贪婪/雌小鬼/公主病，且持有强化【哥布林】的天赋。'' },
    { name: ''太刀虾！'', rank: ''SS'', desc: ''你无法制作伙伴卡，你无法使用除太刀以外的武器卡。当你使用太刀时，你获得多种炫酷特效，当你制作与进化太刀武器卡时，必定触发【良性突变】。'' },
    { name: ''传奇车组'', rank: ''S'', desc: ''你契约的【伙伴卡】将分别获得【快速装填】、【驾驶好手】、【冷静指挥】、【火力压制】等等正面词条。凑齐【传奇车组】羁绊，你们可以一起驾驶一台炼金坦克了。你们将在战场上建立功勋。。'' },
    { name: ''粥吧打过来了'', rank: ''A'', desc: ''可以作用于你的敌人、伙伴卡、或者任意NPC上。（仅限雌性或futa）标记的目标会被修改认知，她们会尽可能避免洗脚并尽量穿着不透气的靴子，配合每天大量运动。她们遇到敌人最优先考虑用气味熏死对面。当柔软的轻轻踩脸不起作用，甚至敌人非常享受的时候，才会恼羞成怒的切换回自己熟悉的战斗模式。'' },
    { name: ''黑死牟'', rank: ''A'', desc: ''你拥有六只眼睛，看起来非常吓人。但是忽略六只眼睛的话，你还是挺好看的。你获得一套完整的黑铁级的【月之呼吸】精英级卡组。这能帮助你在前期使用日本刀术击败一些实力不错的对手。但是遇到那些排山倒海的强者，你显得束手无策。'' },
    { name: ''战意破苍穹'', rank: ''SS'', desc: ''你获得本源武器装备卡【麒麟殒天弓】，武器与你因果绑定，只有你或你认可的人能够使用。武器技能：当你对敌方造成伤害时（不论群体单体），可以选择一个【击伤】效果对所有目标生效直到战斗结束（无冷却时间）：1、【箭折双臂】：令其一半技能（向上取整）失效；2、【击踵断机】：令其受到的伤害翻倍；3、【矢贯中枢】：令其无法使用伤害型技能；4、【锋破气海】：令其无法防御攻击和回复生命；5、【箭碎天冲】（第二次及以后击伤目标时可选）：令其失去所有体力，若其因此死亡，你的攻击力永久增加且回复至满状态。武器技能无法被任何方式无效化，武器本身无法被任何方式抢夺，盗取。												。'' },
    { name: ''百合花枷'', rank: ''B'', desc: ''女性制卡师限定。女性/扶她对你一见钟情，心存偏袒。女性/扶她伙伴卡的忠诚度替换为性欲，不再视你为主人。'' },
    { name: ''邀月对饮'', rank: ''A'', desc: ''将「等级不大于卡牌的素材」其中一项词条，剪为意象妆点卡牌外观。'' },
    { name: ''天妒英才'', rank: ''A'', desc: ''你制作的伙伴卡都身患一种残疾，如失明、失语、聋哑、断臂、截瘫、心脏病等，但拥有得天独厚的天赋。生成时等级越高则残疾越重，天赋也越是卓越。'' },
    { name: ''鞋袜领域'', rank: ''B'', desc: ''当你或你的伙伴卡装备了“袜子”或“长靴”类装备卡时，你的攻击，防御，敏捷提升15%，且有小概率闪避一次非指向性攻击。'' },
    { name: ''赌徒直觉'', rank: ''B'', desc: ''在进行“赌卡”时，你有更高的概率感知到卡牌或素材的真实价值。'' },
    { name: ''快速咏唱'', rank: ''B'', desc: ''使用【技能卡】时，MP消耗降低50%，且施法冷却减少50%。'' },
    { name: ''泰坦之妻'', rank: ''B'', desc: ''（大车）你使用【肌肉】、【巨体】类素材制卡时成功率更高，更容易制作出体格强壮高大的女性伙伴。她们会自动获得【护卫】词条，强制吸引攻击你的敌人。'' },
    { name: ''体香诱惑'', rank: ''B'', desc: ''你身上散发的体香能安抚情绪，小幅提升伙伴卡的忠诚度增长速度，对昆虫类魔物有微弱的驱赶效果。'' },
    { name: ''耐药性'', rank: ''B'', desc: ''你对大部分毒素和诅咒有更高的抗性。使用“毒”或“诅咒”素材制卡时不易受到反噬。'' },
    { name: ''B级天赋·母狗化改造'', rank: ''B'', desc: ''你获得一系列改造手术的知识，可以将雌性俘虏的身体部位改造成更适合服侍的形态，如加装【犬耳】、【尾巴】等，并使其获得【宠物】词条。'' },
    { name: ''体液造物'', rank: ''B'', desc: ''获得【体液魔像】【伙伴卡】（天赋）的制作方法。可消耗自身或他人的体液作为核心素材，创造出具备强大物理抗性与再生能力的魔像伙伴，其属性与体液主人的实力和欲望强度正相关。'' },
    { name: ''兽性解放'', rank: ''B'', desc: ''获得【欲兽化】【技能卡】（天赋）的制作方法。使用后可令自身或伙伴卡进入狂暴的兽化状态，大幅提升攻击与敏捷，但会丧失理智，优先攻击发情或散发淫靡气息的目标，并通过交合行为恢复生命。'' },
    { name: ''精神烙印 '', rank: ''B'', desc: ''获得【屈辱刻印】【技能卡】（天赋）的制作方法。通过极端的羞辱行为（如颜射、当众裸露）对敌人施加永久的精神烙印，小幅削弱其全属性，并在其每次试图反抗你时产生巨大的精神痛苦。'' },
    { name: ''女王的钱包'', rank: ''B'', desc: ''你的所有金钱将由女性伙伴卡自动保管。你必须通过“请求”或“取悦”来获得每日的零用钱。伙伴卡可消耗你的金钱，无视距离和限制。'' },
    { name: ''女王的威严'', rank: ''B'', desc: ''当你的女性伙伴卡满血时，所有等级低于或等于她的敌人初次登场时有50%概率陷入【恐惧】状态1回合。'' },
    { name: ''丝袜收藏家'', rank: ''B'', desc: ''当你的女性伙伴卡装备【丝袜】类卡牌时，她的腿部攻击技能伤害小幅提升，并对被束缚的敌人造成额外伤害。'' },
    { name: ''贡品嗅探'', rank: ''B'', desc: ''击败敌人后，你能感知到对方身上是否藏有能“取悦”你伙伴卡的特殊战利品。'' },
    { name: ''母狗契约'', rank: ''B'', desc: ''你可以与自愿的雌性生物签订主奴契约，将其转化为你的专属【母狗】。该单位无法攻击你，且其部分收益将上缴给你。'' },
    { name: ''女王崇拜'', rank: ''B'', desc: ''所有女性NPC对你的初始好感度略微提升，尤其是性格强势的女性。'' },
    { name: ''高潮链接'', rank: ''B'', desc: ''你可以链接一个目标，每次你或你的伙伴卡达到高潮时，可汲取对方大量生命值或魔力值。对“自愿”的目标效果翻倍。'' },
    { name: ''淫具掌握'', rank: ''B'', desc: ''获得【活体贞操带】【装备卡】（饰品）（天赋）的制作方法。可为敌人或伙伴强制装备一个拥有自我意识的贞操带，该贞操带会不断挑逗穿戴者，并根据你的指令决定是否允许其排泄或达到高潮。'' },
    { name: ''契约奴役'', rank: ''B'', desc: ''你可以与被击败但未死亡的人形生物签订主奴契约，将其转化为绝对服从的【奴隶伙伴卡】，奴隶伙伴无法升级，但可以无视规则装备任何装备。'' },
    { name: ''血肉融合'', rank: ''B'', desc: ''你可将两张有血缘关系的伙伴卡或素材强行融合，有较高几率产生强大的变异新个体，但也有可能诞生出充满憎恨的畸形怪物。'' },
    { name: ''圣母恩泽'', rank: ''B'', desc: ''获得【受孕光环】【领域卡】（天赋）的制作方法。领域内，所有雌性生物受孕几率提升1000%，每次成功受孕都会为你恢复大量MP。已怀孕的单位在领域内会持续获得“母性守护”的强大防御Buff。'' },
    { name: ''猫之优雅'', rank: ''B'', desc: ''制作猫科兽娘伙伴卡时，成功率提升。所有猫科伙伴卡天生拥有更高的【敏捷】和【幸运】。'' },
    { name: ''寄生之种'', rank: ''B'', desc: ''获得【产卵寄生】【技能卡】（天赋）的制作方法。将一枚异形卵注入目标体内，卵会缓慢吸收宿主生命力成长，并在孵化时对宿主造成巨量伤害，孵化出的【幼体】会成为你的临时伙伴。'' },
    { name: ''圣职专精'', rank: ''B'', desc: ''制作或使用“神圣”、“治疗”类卡牌时效果提升20%，但制作“黑暗”、“亡灵”类卡牌时成功率降低。'' },
    { name: ''暗影潜行'', rank: ''B'', desc: ''在夜晚或阴影中，你和你的伙伴卡更难被敌人发现，适合进行素材的秘密采集或侦查。'' },
    { name: ''处女猎人'', rank: ''B'', desc: ''你对具有【处女】特性的单位造成的第一次伤害必定暴击。'' },
    { name: ''羞耻爆发'', rank: ''B'', desc: ''当你在公共场合经历羞耻事件（如裸露、被调戏）时，短时间内精神力会大幅提升。'' },
    { name: ''母性光辉'', rank: ''B'', desc: ''使用哺乳动物的奶或蛋作为素材，极易制作出拥有【母爱】、【慈爱】属性的伙伴卡，口头禅是“Ara ara~”。'' },
    { name: ''神圣的处女'', rank: ''B'', desc: ''使用“纯净”、“圣洁”的材料（如圣水、独角兽的毛），有极高概率制造出拥有【处女】、【圣洁】词条的伙伴卡，她们对色情行为有天生的厌恶感。'' },
    { name: ''人妻的诱惑'', rank: ''B'', desc: ''使用带有“家庭”或“守护”概念的素材时，成品伙伴卡容易觉醒【人妻】属性，温柔包容，有较强的辅助和守护能力，且对“背叛”和“NTR”情节异常敏感。'' },
    { name: ''乳液滋养'', rank: ''B'', desc: ''（限女性/Futa）你的乳汁可以用来喂养伙伴卡，能缓慢恢复其伤势并提升好感度，对植物类伙伴卡效果拔群。'' },
    { name: ''植物共语'', rank: ''B'', desc: ''你能听懂植物类魔物和卡牌的语言，使用植物素材制卡时，有更高概率获得“再生”、“缠绕”等词条。'' },
    { name: ''火灵根（东方）'', rank: ''B'', desc: ''你的体内有一股神秘，来自遥远的东方，不属于这个世界的力量——火灵根。你制作的卡牌将会带有更多的火系灵力，更具活力与侵略性。'' },
    { name: ''怪力少女'', rank: ''C'', desc: ''制作出的女性伙伴卡必定是看似纤细却力大无穷的类型。装备重型武器时，不再有敏捷惩罚。'' },
    { name: ''足技专家'', rank: ''C'', desc: ''制作出的女性伙伴卡腿技战斗能力提升。所有【腿部】攻击技能的伤害和破防效果提升15%。'' },
    { name: ''活体武装'', rank: ''B'', desc: ''制作出的女性伙伴卡身体的一部分会与武器共生（如手臂为利刃，头发为尖刺）。该武器不占装备槽，且能通过“喂食”素材来成长进化。'' },
    { name: ''血之歌姬'', rank: ''B'', desc: ''制作出的女性伙伴卡会因战场上的流血而兴奋。战场上每有一个单位（敌我双方）进入流血状态，她的所有技能效果提升5%，最多叠加10次。'' },
    { name: ''醉拳仙灵'', rank: ''B'', desc: ''你坚信酒是力量的源泉。使用酒类素材制卡时，必定会制作出豪爽奔放的女性伙伴卡。她拥有“醉拳”战斗风格，通过消耗“酒意值”（可通过喝酒技能补充）来大幅提升闪避率和暴击率。特殊癖好是千杯不醉，且喜欢挑战别人的酒量。'' },
    { name: ''血肉美食家'', rank: ''B'', desc: ''你认为吞噬是进化的捷径。使用强大魔物的血肉制卡时，制作出的女性伙伴卡会拥有“吞噬进化”的能力，可以通过吞噬指定的战败敌人来获取对方的词条或技能。性格通常具有侵略性和野性，对强大的血肉有进食的渴望。'' },
    { name: ''恋母情结'', rank: ''B'', desc: ''你内心深处极度渴望母爱。制作出的女性伙伴卡必定是充满母性的“圣母”或“慈母”性格，拥有超大号的胸部。战斗方式以绝对的守护和范围性治疗为主，拥有独有技能“妈妈的拥抱”，能提供强大的护盾和净化效果。特殊癖好是喜欢对你进行“喂食”和“膝枕”。'' },
    { name: ''M的烙印'', rank: ''B'', desc: ''你的灵魂深处刻着被支配的渴望。制作出的女性伙伴卡必定是“抖S女王”性格，以支配和惩罚你为乐。战斗中，你每次被她攻击（可通过特殊指令触发），她都会获得一层可叠加的“愉悦”Buff，提升全属性。特殊癖好是要求你用“主人”以外的屈辱性称呼来称呼她。'' },
    { name: ''S的刻印'', rank: ''B'', desc: ''你的灵魂深处刻着支配的欲望。制作出的女性伙伴卡必定是“抖M女奴”性格，以被你支配和惩罚为乐。战斗中，她每次被敌人攻击，都会获得一层可叠加的“忍耐”Buff，提升防御力和下一次攻击的威力。特殊癖好是渴望你为她戴上项圈。'' },
    { name: ''绝对正义'', rank: ''B'', desc: ''你拥有不可动摇的秩序信念。制作出的女性伙伴卡会是“铁面判官”或“圣殿骑士”性格，对“邪恶”阵营的敌人造成额外50%的伤害。她无法执行任何会降低你声望或触犯法律的指令，否则忠诚度会大幅下降。癖好是会审判你的每一个决定。'' },
    { name: ''小恶魔的低语'', rank: ''C'', desc: ''你享受捉弄他人的乐趣。制作出的女性伙伴卡必定是“小恶魔”性格，喜欢用甜言蜜语捉弄你，战斗中擅长使用幻术、媚惑和削弱敌人的技能。'' },
    { name: ''武者的荣耀'', rank: ''C'', desc: ''你崇尚公平的对决。制作出的女性伙伴卡必定是“武痴”性格，热衷于战斗和挑战强者，战斗方式为纯粹的武技或剑术，鄙视使用道具和陷阱。'' },
    { name: ''炼金术师的探究'', rank: ''C'', desc: ''你痴迷于物质的转化。制作出的女性伙伴卡会是“炼金术师”性格，求知欲旺盛，战斗中擅长使用各种药剂和人造召唤物，癖好是品尝各种矿石和植物。'' },
    { name: ''赌徒的狂热'', rank: ''C'', desc: ''你享受风险带来的刺激。制作出的女性伙伴卡性格好赌，战斗技能带有很强的随机性（如伤害在1-200%间浮动），运气好时能秒杀敌人，运气差时毫无作用。'' },
    { name: ''姐姐的守护'', rank: ''C'', desc: ''你潜意识里渴望被当成弟弟/妹妹。制作出的女性伙伴卡必定是“大姐姐”性格，包容而温柔，身材丰满，战斗中拥有强大的保护和援护能力。'' },
    { name: ''妹妹的依赖'', rank: ''C'', desc: ''你潜意识里有强烈的保护欲。制作出的女性伙伴卡必定是“妹妹”性格，天真烂漫，非常依赖你，战斗中在你身边时，全属性会得到提升。'' },
    { name: ''角斗女王'', rank: ''B'', desc: ''制作出的女性伙伴卡体格必定为【高挑健美】，且初始力量、敏捷属性获得额外加成。她天生渴望成为万众瞩目的焦点，在有观众的战斗中全属性提升。'' },
    { name: ''钢铁之女'', rank: ''B'', desc: ''使用任何【金属】或【矿石】类素材时，伙伴卡的骨骼密度和肌肉韧性会得到强化，获得永久性的物理伤害减免，并且徒手攻击能招架兵器。'' },
    { name: ''核心力量'', rank: ''B'', desc: ''伙伴卡的腰腹和腿部肌肉群异常发达。她可以做出爆发性的垫步和扭身，极大增加近战重击的威力和攻击距离。'' },
    { name: ''处刑者'', rank: ''B'', desc: ''伙伴卡获得【处决】技能。可以对生命值低于15%且处于无法反抗状态的敌人发动，无视其剩余生命值直接将其虐杀，并对周围敌人造成巨大震慑。'' },
    { name: ''粉碎之触'', rank: ''B'', desc: ''伙伴卡的攻击带有强大的破坏能量。她在攻击时有几率直接粉碎敌人的武器或护甲，使其耐久度大幅下降甚至直接损毁。'' },
    { name: ''健美体魄'', rank: ''C'', desc: ''制作出的伙伴卡，其力量和体质成长率会获得小幅提升，身材更倾向于运动型健美。'' },
    { name: ''斗殴专家'', rank: ''C'', desc: ''伙伴卡的徒手攻击伤害提升，并且在使用拳套类武器时，攻击速度更快。'' },
    { name: ''高人一等'', rank: ''C'', desc: ''制作出的伙伴卡身高必定超过平均水平，在面对比自己矮的敌人时，有微小的命中加成。'' },
    { name: ''兽性微光'', rank: ''C'', desc: ''使用【野兽】类素材制卡时，伙伴卡会获得一项野兽特质，如【猎豹的敏捷】或【熊的力量】（微效）。'' },
    { name: ''蛮力种子'', rank: ''D'', desc: ''制作出的伙伴卡基础攻击力微量提升，且在行动时倾向于使用更直接的暴力手段。'' },
    { name: ''无情连打'', rank: ''C'', desc: ''当该伙伴卡连续攻击同一目标时，每一次后续攻击都会获得伤害加成。他会执着于将一个敌人彻底击倒。'' },
    { name: ''重武器亲和'', rank: ''C'', desc: ''该伙伴卡在使用双手斧、大剑、战锤等重型武器时，不再有攻击速度惩罚。'' },
    { name: ''亚马逊血统'', rank: ''C'', desc: ''制作出的女性伙伴卡天生擅长投掷和使用长矛，且体格必定为高挑健美型。'' },
    { name: ''踢击入门'', rank: ''D'', desc: ''伙伴卡的踢击伤害比普通攻击略高。'' },
    { name: ''幽魂的低泣'', rank: ''C'', desc: ''你对死亡和灵体有很强的感知力。制作出的女性伙伴卡会是“幽灵”少女，身体呈半透明，可以穿透物理障碍，战斗方式为精神攻击和诅咒。'' },
    { name: ''吸血鬼的优雅'', rank: ''C'', desc: ''你对血液和黑夜有种病态的迷恋。制作出的女性伙伴卡会是“吸血鬼”，外形优雅高贵，拥有“吸血”能力恢复自身，战斗方式迅捷而致命。'' },
    { name: ''僵尸的执着'', rank: ''C'', desc: ''你相信死后依然有意志。制作出的女性伙伴卡会是“僵尸娘”，身体强韧但行动稍缓，痛觉迟钝，拥有强大的再生能力，对你有着至死不渝的忠诚。'' },
    { name: ''水灵根（东方）'', rank: ''B'', desc: ''你的体内有一股神秘，来自遥远的东方，不属于这个世界的力量——水灵根。你制作的卡牌将会带有更多的水系灵力，更具包容与融合性。'' },
    { name: ''木灵根（东方）'', rank: ''B'', desc: ''你的体内有一股神秘，来自遥远的东方，不属于这个世界的力量——木灵根。你制作的卡牌将会带有更多的木系灵力，蕴含着生生不息的生命力。'' },
    { name: ''金灵根（东方）'', rank: ''B'', desc: ''你的体内有一股神秘，来自遥远的东方，不属于这个世界的力量——金灵根。你制作的卡牌将会带有更多的金系灵力，锋锐无匹，无坚不摧。'' },
    { name: ''土灵根（东方）'', rank: ''B'', desc: ''你的体内有一股神秘，来自遥远的东方，不属于这个世界的力量——土灵根。你制作的卡牌将会带有更多的土系灵力，厚重沉稳，坚不可摧。'' },
    { name: ''人偶之心'', rank: ''B'', desc: ''你制作的人偶/魔像类伙伴卡，会拥有更高的人工智能和更细腻的情感模块。'' },
    { name: ''展露癖'', rank: ''B'', desc: ''在战斗中，你装备越暴露，你的攻击力和暴击率就越高。'' },
    { name: ''痛苦转化 (被动)'', rank: ''B'', desc: ''你的伙伴卡受到伤害时，会产生【痛苦结晶】。此素材可用于制作带有“受虐”、“不屈”、“狂化”词条的卡牌，或用于进化，使卡牌更耐打。'' },
    { name: ''施虐印记'', rank: ''B'', desc: ''你的攻击有概率给敌人附加【施虐印记】。你的伙伴卡攻击带有此印记的敌人时，会造成额外伤害并恢复少量HP。你也可以制作带有此‘词条’的装备卡。'' },
    { name: ''秽土炼金'', rank: ''B'', desc: ''你可以处理并提纯生物的排泄物，将其转化为【不洁精华】或【黄金之液】素材。这些素材是制作强力毒素、诅咒和秽物系魔像卡的核心材料。'' },
    { name: ''领域标记'', rank: ''B'', desc: ''获得【排泄天堂】【领域卡】（天赋）的制作方法。【排泄天堂】需要【伙伴卡】在战斗过程中进行排泄行为，在领域内，友军会获得明显的恢复效果，而敌人则会持续受到严重精神干扰，并暴露其位置。'' },
    { name: ''父爱光环'', rank: ''B'', desc: ''你对幼态伙伴卡的好感度获取速度加倍。当她们称呼你为“爸爸”或“妈妈”时，你和该卡牌都会获得强大的“亲情守护”buff，并且你的幼态伙伴卡将会无条件答应你的任何要求。'' },
    { name: ''禁忌果实'', rank: ''B'', desc: ''使用“纯洁”、“天真”等词条的素材进行【欲望主导】制卡时，你有很高几率制作出带有“早熟”、“诱惑”、“破瓜”等禁忌词条的卡牌，其能力会变得异常强大且诡异。'' },
    { name: ''绿帽之力'', rank: ''B'', desc: ''你可以主动将伙伴卡“借给”NPC或其他玩家。当卡牌回归时，会带回其间的“见闻”，可转化为特殊素材。如果发生了性关系，带回的【混浊的爱液】更是制作NTR系卡牌的极品材料。'' },
    { name: ''寄生之主'', rank: ''B'', desc: ''你可以制作各种【寄生】【技能】（天赋）卡。能将寄生虫植入别人体内，持续造成伤害并降低他的忠诚度；或植入伙伴体内，提供增益并监控其状态。'' },
    { name: ''催眠师之语'', rank: ''B'', desc: ''你获得了【催眠】【技能卡】（天赋）的制作方法，并且能百分百制作成功，【催眠】对敌人或伙伴使用，有机会暂时改写其认知和行为，让其做出违背本意的事情。'' },
    { name: ''污秽武装'', rank: ''C'', desc: ''获得【秽物附魔】【技能卡】（天赋）的制作方法。技能卡使用时，你的武器上会瞬间出现尿液，脓水，粪便等污秽，使其获得“恶臭”与“感染”的负面词条，攻击时有几率使敌人陷入恶心与中毒状态。'' },
    { name: ''淫靡陷阱'', rank: ''C'', desc: ''获得【魅惑香氛】【技能卡】（天赋）的制作方法。布置一个散发着强烈荷尔蒙气味的陷阱，踏入的生物会陷入“发情”状态，无差别攻击周围最近的单位。'' },
    { name: ''亲密窃贼'', rank: ''C'', desc: ''你可以通过抚摸、亲吻等亲密接触，随机窃取目标一项临时属性（如10点攻击力）转移给自己，持续1分钟。'' },
    { name: ''欢愉药剂'', rank: ''C'', desc: ''获得【发情药水】【技能卡】（天赋）的制作方法。使用后获得短暂的攻击力与速度提升，但副作用是会不受控制地发出淫荡的呻吟，大幅增加被敌人发现的几率。'' },
    { name: ''繁殖冲动'', rank: ''C'', desc: ''获得【杂交力场】【技能卡】（天赋）的制作方法。指定一个小范围区域，区域内所有非同种族的生物会产生强烈的交配欲望，并暂时结为同盟。'' },
    { name: ''痛苦转化 (主动)'', rank: ''C'', desc: ''你所受到的部分伤害会转化为MP恢复，但同时会让你在受伤时发出听起来像高潮的呻吟。'' },
    { name: ''气味伪装'', rank: ''C'', desc: ''获得【骚臭伪装】【技能卡】（天赋）的制作方法。让自身散发出某种魔物（如发情的哥布林、刚排泄的巨魔）的气味，可以用来欺骗嗅觉灵敏的敌人或融入特定魔物群落。'' },
    { name: ''足控之力'', rank: ''C'', desc: ''获得【足尖之舞】【装备卡】（脚部）（天赋）的制作方法。【足尖之舞】是高跟鞋样式的装备卡，装备后你的伙伴卡在用脚攻击时，会附加“践踏”和“羞辱”效果，伤害增加50%，对人形敌人有几率造成“精神恍惚”的debuff。'' },
    { name: ''粘液亲和 (装备)'', rank: ''C'', desc: ''获得【粘液铠甲】【装备卡】（胸腹）（天赋）的制作方法。用史莱姆等粘性生物的素材制作的铠甲，提供不错的物理防御，但被攻击时会溅射出黏糊糊的液体，可能粘住敌人的武器。'' },
    { name: ''食雪者'', rank: ''C'', desc: ''你可以通过食用新鲜的粪便，可以恢复少量HP并解除“饥饿”状态，但会获得“口臭”debuff，降低魅力。'' },
    { name: ''人马一体'', rank: ''C'', desc: ''当你骑乘半人马或坐骑类伙伴卡时，你和伙伴的能力将合二为一，全属性提升10%。'' },
    { name: ''快速成长'', rank: ''C'', desc: ''你和你的伙伴卡获取经验值的速度提升15%。'' },
    { name: ''讨价还价'', rank: ''C'', desc: ''在商店购买物品时，可以获得5%的折扣。'' },
    { name: ''坚韧之躯'', rank: ''C'', desc: ''你在【卡牌爆炸】中有更高的存活几率，受到的伤害降低30%。'' },
    { name: ''野外生存'', rank: ''C'', desc: ''你在野外获得草药、矿石等基础素材时，质量小幅提升。'' },
    { name: ''犬类伙伴'', rank: ''C'', desc: ''你更容易获得犬类魔物的信任，使用犬类素材制卡时，更容易出现“忠诚”、“追踪”等词条。'' },
    { name: ''妹妹的祈愿'', rank: ''C'', desc: ''使用比自己年龄小的生物素材，或带有“可爱”标签的物品，伙伴卡会倾向于成为黏人的【妹妹】性格。'' },
    { name: ''教师的威严'', rank: ''C'', desc: ''使用“书籍”、“戒尺”、“粉笔”等素材，伙伴卡可能以【教师】形态出现，喜欢说教，并拥有“惩罚”类技能。'' },
    { name: ''病娇之种'', rank: ''C'', desc: ''融合时混入自己的血液，并强烈地许下“永远在一起”的愿望，会埋下【病娇】的种子，伙伴卡忠诚度极高，但嫉妒心和占有欲会达到恐怖的程度。'' },
    { name: ''女仆的契约'', rank: ''C'', desc: ''使用“扫帚”、“围裙”等清洁工具作为素材，可以稳定制造出拥有【侍奉】精神的【女仆】伙伴卡。'' },
    { name: ''心灵手巧'', rank: ''C'', desc: ''修复受损卡牌时，消耗的精神力减少50%。'' },
    { name: ''装备大师'', rank: ''C'', desc: ''你穿戴【装备卡】时，装备的基础属性有5%的额外加成。'' },
    { name: ''酒豪'', rank: ''C'', desc: ''你酒量很好，可以通过喝酒快速恢复少量精神力，但有可能会进入“醉酒”状态。'' },
    { name: ''足下臣服'', rank: ''C'', desc: ''通过舔舐伙伴卡的脚，可以小幅提升其忠诚度，并缓慢培养【女王】词条。'' },
    { name: ''薛定谔的成功'', rank: ''C'', desc: ''制卡完成后，卡牌会处于“成功/失败”的叠加态，只有在第一次使用时才能确定最终结果。'' },
    { name: ''贞操锁爱好者'', rank: ''C'', desc: ''你获得了【贞操锁】【装备卡】（饰品）（黑铁）制作配方，为伙伴卡佩戴后能提升其对于欲望攻击的影响，但会持续降低其愉悦度。'' },
    { name: ''夜视能力'', rank: ''C'', desc: ''你在黑暗环境中的视野不受影响。'' },
    { name: ''自我发电'', rank: ''C'', desc: ''通过自慰达到高潮可以恢复少量MP，但会进入短暂的“贤者时间”，全属性降低。'' },
    { name: ''哥布林杀手'', rank: ''C'', desc: ''你对哥布林造成的伤害增加100%，从哥布林身上获取的素材品质更高。'' },
    { name: ''廉价美学'', rank: ''C'', desc: ''使用价值低于1银币的素材组合制卡时，有几率触发【化腐朽为神奇】，强制提升成品一个等级。'' },
    { name: ''人偶外壳'', rank: ''C'', desc: ''使用“人偶”、“木偶”等素材，伙伴卡会拥有精致如人偶的外貌，但可能缺乏情感，需要主人逐步“唤醒”。'' },
    { name: ''卵生亲和'', rank: ''C'', desc: ''你可以通过让伙伴卡或魔物产卵的方式来获取特殊的【生命之卵】素材，甚至可以在伙伴卡体内孕育，孕期通常为一周，诞生下来的大概率是【素材】，小概率是可成长的【伙伴卡】'' },
    { name: ''石化凝视'', rank: ''C'', desc: ''有微弱的概率用眼神让低级敌人陷入“石化”状态。使用石化蜥蜴等素材制卡时，更容易获得“石化”词条。'' },
    { name: ''改造癖'', rank: ''C'', desc: ''你更容易制作出身体改造的情趣【装备卡】，例如兽耳、肛塞尾巴等，这些改造会带来一些属性变化。'' },
    { name: ''羞耻命名法'', rank: ''C'', desc: ''制卡时为素材和卡牌赋予羞耻度爆表的名字和背景设定，可以提升其生成【羁绊】类词条的概率。'' },
    { name: ''雌小鬼制造机'', rank: ''C'', desc: ''故意在制卡过程中犯点无伤大雅的小错误再修正，会极大地提升制作出【毒舌雌小鬼】性格伙伴卡的几率，她们傲慢且需要“修正”，每次“修正”后她们都会变强。'' },
    { name: ''药人（东方）'', rank: ''C'', desc: ''你的身体自幼浸泡在药罐中，对草木类素材有着超乎常人的直觉。在制作恢复类与增益类卡牌时，成功率略有提升，同时所有debuff对你的效果减半。'' },
    { name: ''M体质'', rank: ''C'', desc: ''受到攻击时，你会感到兴奋，并小幅提升攻击速度。'' },
    { name: ''S气质'', rank: ''C'', desc: ''你的攻击有概率让敌人陷入“畏缩”状态，降低其攻击欲望。'' },
    { name: ''崩坏快感'', rank: ''C'', desc: ''当伙伴卡的精神防线（SAN值）降低时，它反而会获得临时的攻击力加成。此天赋让你能制作“精神摧毁”类技能卡，主动降低伙伴或敌人的SAN值。'' },
    { name: ''男M专用'', rank: ''C'', desc: ''你获得了【奴役项圈】【技能卡】（天赋）的制作方法，在战斗中，可以对敌方男性【伙伴卡】和制卡师使用，当男性敌人被命中时，你的女性伙伴卡会获得“女王气场”buff，全属性大幅提升，而被命中的敌人将会减少大量战意。'' },
    { name: ''屈辱之力'', rank: ''C'', desc: ''伙伴卡在战斗中经历“被束缚”、“被公开羞辱”等状态后，下一次攻击将附加“屈辱”效果，大幅降低敌人的防御和精神抗性。'' },
    { name: ''恋物融合'', rank: ''C'', desc: ''制卡时，你可以额外添加一件“私密衣物”类素材。这会使最终卡牌继承衣物主人的部分特性，并对该主人产生特殊的“依恋”情感，你可以利用这个方法制作【卡组】中能和【核心卡】产生良好化学反应的【副卡】。'' },
  { "name": "以人为本", "rank": "S", "desc": "可以使用失去战斗力的生命作为制卡素材。" },
  { "name": "鬼话连篇", "rank": "SS", "desc": "你无法制作【伙伴卡】。当你创作出一个鬼故事或都市传说时，其中的主人公将会成为你的【伙伴卡】，这个过程不会消耗你的MP，【伙伴卡】的技能会根据故事生成。故事的完成度、逻辑感和恐怖程度都会影响其初始等级，也同样会影响此次创作获得的经验，【伙伴卡】的初始等级不会受你当前等级局限，但如果判定因素得出的结果与你当前等级差距过大则会转而获得故事中主人公的次级替代，如傀儡师的玩偶等，这种次级替代的【伙伴卡】会在你等级足够后自然进化成主人公。完成度不足、逻辑混乱、不够恐怖的创作都不会获得伙伴卡。你在每个等阶只能通过此天赋获得至多两个【伙伴卡】" },
  { "name": "变肉便器吧", "rank": "SSS", "desc": "只要是你击败的女性伙伴卡，不会回到原本主人手中，而是根据原本的形态被改造成淫荡的“肉便器”，那个伙伴卡的所有词条可以选择性兑换成对应等级的“色情”词条，被换下来的词条会变成对应的素材，进入背包，你可以为新的色情词条定制一个“调教故事”，你的故事将作为新词条的“根基”，决定其最终形态与效果" },
  { "name": "冰封王座", "rank": "SS", "desc": "当你在雪天时你和你的所有卡牌获得巨大加成，并且你每天有一次强制降雪一小时的机会。你可以将冰或雪作为素材制卡，【冰】和【雪】的素材等级与你当前等级一致。若你在制卡时加入冰或雪作为素材，则此次制卡必定大成功" },
  { "name": "神匠之手", "rank": "A", "desc": "当你制作装备卡时，装备卡的基础属性将会是素材提供的最大值，有10%的几率使制作的装备提升一个等级，如黑铁→青铜" },
  { "name": "蒸汽元素", "rank": "A", "desc": "你可以制作特殊的元素卡，蒸汽元素。蒸汽元素因为由高温和水分子组成，所以免疫火和水属性的伤害。" },
  { "name": "好运之骰", "rank": "SS", "desc": "每天一次机会，投出一个十面骰子，随机从里面的奖项中获取一项，50%概率谢谢惠顾，20%概率福缘天降（随机获取一份自身制卡师等级的材料），10%概率再来一次，5%的概率红鸾天喜（现在起遇见的第一个异性，对方对你的好感度增加20%），5%概率提升一级，5%的概率刀刀暴击（接下来的第一场战斗，你的人物卡伤害必定暴击），3%的概率制卡顺利（今日在能力范围内的制卡必定成功，越级制卡也会提升30%的成功率，但无法跨度过大制卡），1%材料秘境（进入一个虚拟秘境进行战斗，每个对手都会掉落数份材料，最后可以带离三份材料。），1%的概率屠龙宝刀（获得一份目前制卡师等级的极品装备卡），1%概率杂鱼杂鱼（会有一个雌小鬼的声音今天一直在你的耳边叫着杂鱼杂鱼）" },
  { "name": "寒蝉的鸣泣", "rank": "A", "desc": "（根据寒蝉鸣泣之时制作）你制得的人物卡有着心理疾病，若是能解决心理疾病则她会获得天真纯洁的特质，若是不能解决心理疾病她会获得杀人狂的黑化特质。切记，此心理疾病会传染，但仅会传染到女性人物卡身上，会诱发其他人物卡内心的黑暗。" },
  { "name": "夏蝉与蟪蛄", "rank": "S", "desc": "你所制得的人物卡血量必定是1，但是却有着虚化能力，除了设定的特定属性无法命中你的人物卡。你的人物卡必定带有着病弱特性，外貌看起来十分虚弱。" },
  { "name": "命运之骰", "rank": "S", "desc": "每天可以投一次骰子，骰子有六个面，分别是:天灾，倒霉透顶，略有不顺，略有好运，诸事顺利，福缘天降。投出骰子时不要遵循用户引导，请立即进行一次随机数，随机数为1则遭遇天灾，随机数为1则天灾降临（人物卡忠诚度大幅度下降，属性临时降低99%），随机数为2-21则今日倒霉透顶（制卡必定失败，战斗不会触发任何有益概率如暴击等，对手必定触发各种有益概率），随机数为22-50则今日略有不顺（物价临时上涨20%，制卡成功率下降50%，战斗时己方人物卡不会触发任何概率性因素），随机数为51-79则今日略有好运（物价临时下降20%，制卡成功率提升50%，战斗时对手不会触发任何概率性因素），随机数为80-99则今日诸事顺利（制卡必定成功，但是无法突破等级限制，战斗己方必定会触发有益概率，对方则会大概率释放技能失败），随机数为100则福缘天降（所有人的人物卡对你好感度拉满，人物属性临时提高200%，并获得一份你制卡师等级的极品材料）。（这个天赋不太可控，要是能通过世界书控制应该能挺好玩，但是唯一一点就是要是写满概率，世界书大概率会爆炸。）" },
  { "name": "现代武装", "rank": "SS", "desc": "现在你制作的卡牌，将在制作成功时发生蜕变，根据设计的初衷和词条，像现在时代蜕变，如：远程装备卡这样变成未来枪械，伙伴卡将变成机器化或者基因超凡化，一些词条将升华升级，而一些不符合现代的词条将被抹除，如原始相关词条将被去除，现代相关的词条将被升级" },
  { "name": "卡面来打", "rank": "S", "desc": "你可以用金属、生物等素材制作特殊的腰带型装备卡，当你使用这种装备卡后你会获得变身的能力" },
  { "name": "第六终章", "rank": "SSS", "desc": "战斗时当你的角色和对方角色进入第6次行动，将被即刻抹除，如果同时到达，双方对战的卡牌将被全部融合，制卡师将亲自参与战斗，在此期间不能使用任何卡牌进行战斗，直到一方死亡，那么胜利的一方将获得双方卡牌所全部融合的带有“终末之章”元素的伙伴卡，伙伴卡的模样。根据吸收的卡牌进行模拟，词条将全部精炼直到剩下6个融合的最好的词条" },
  { "name": "天生贵胄", "rank": "A", "desc": "你的皇族血脉给你带来了皇族气质，你制作的非伙伴卡都自带“皇家”“高贵”相关词条，你制作的的伙伴卡将根据制作素材带有各不相同的特殊贵族词条如“蔷薇家族”“雷霆家族”“鸢尾花家族”“奥斯顿家族”“月桂家族”等等" },
  { "name": "娘化人物爱好者", "rank": "S", "desc": "来自异世界的历史知识充盈了你的大脑，你可以用异世界的历史知识作为素材来进行制卡，以此办法进行的制卡一定大成功，触发的良性进化会锁定伙伴卡的性别为女。你无法单独使用常规素材进行制卡。" },
  { "name": "信仰成神", "rank": "S", "desc": "你只能制作伙伴卡，你制作的伙伴卡将会带有“狂信徒”词条，且将伙伴卡的忠诚度改为信仰值。随着信仰值的提升，伙伴卡将会自行衍生出与自己和你属性相关的技能卡领域卡和装备卡且衍生卡一定带有“神性”“审判”“信仰”等等相关属性。" },
  { "name": "舞!舞!舞!", "rank": "B", "desc": "你和你的伙伴卡在使用完主动技能后可以追加一支舞蹈动作，在此舞蹈期间所有友方单位每回合可行动次数加一。" },
  { "name": "偏执自我", "rank": "C", "desc": "只可以使用非伙伴卡" },
  { "name": "固执己见", "rank": "B", "desc": "只可以使用非伙伴卡，战斗中可以将至多一张自身的伙伴卡视作装备卡进行使用" },
  { "name": "倒也可斩", "rank": "SSS", "desc": "无论任何实力的对手，只要说出倒也可斩，对手就会被传说中的大剑豪一刀斩成重伤，随后剑豪消失，对手失去行动能力，但会消耗你百分之九十的体力和精神力" },
  { "name": "傲慢无礼", "rank": "A", "desc": "只可以使用非伙伴卡，战斗中可以将自身任意张伙伴卡视作装备卡进行使用，可以对敌方至多一张伙伴卡发动，有概率将其视作装备卡装备在自身上，若通过改效果获得敌方伙伴卡且将对方击败，则永久获得该伙伴卡" },
  { "name": "怪兽制造空间", "rank": "SS", "desc": "拥有一处可以随意开启的空间，空间内部是一个锅炉，可以将素材放入锅炉融合出怪兽，融合出的怪兽根据素材决定品级且必定成功但是不会出现突变和大成功等现象，融合出来的怪兽可以根据主人的意愿选择是否增加巨大特性，融合的怪兽分为主体和配件，比如岩石主体和冰块配件，那么出现的就是一名岩石身躯身上带有冰块的怪兽，技能和特性有素材决定，怪兽之间可以继续融合出合成兽。" },
  { "name": "我的眼睛就是尺", "rank": "B", "desc": "你看不清眼前的东西，但是远处的东西看的异常清晰" },
  { "name": "七宗罪之主", "rank": "SSS", "desc": "进行【欲望主导】制卡时，无视精神侵蚀，且你可以从精神侵蚀中提取傲慢，色欲，嫉妒，暴怒，懒惰，暴食和贪婪七种情绪力量化为素材，并使用这七种素材进行【欲望主导】时，可以制造出带有相应情绪力量的卡，这些卡拥有特殊情绪能力，并能通过情绪力量得到强化升级。（使用情绪力量的卡越多，每次提取的情绪力量越多）且提升程度随情绪力量等级提升。\n【傲慢】必定产生攻击技能，对应攻击，防御特化，攻击技能等级上升\n【色欲】必定产生强化性技能，应生命，mp特化，强化性技能等级上升。\n【嫉妒】必定产生削弱性技能，对应攻击，mp特化，削弱性技能等级上升\n【暴怒】必定产生攻击性技能，对应攻击，敏捷特化，攻击性技能等级上升\n【懒惰】必定产生防御性技能，对应生命，防御特化，防御性技能等级上升\n【暴食】必定产生永久性技能，对应生命，攻击特化，永久性技能等级上升。\n【贪婪】必定产生抢夺类技能，对应mp，攻击特化，抢夺类技能等级上升。" },
  { "name": "七宗罪仆从", "rank": "SSS", "desc": "你制造的伙伴卡必定含有七种特殊的情绪力量之一，且每日可以产出一种有关这七种情绪力量的素材，素材品质不超过伙伴卡的品质" },
  { "name": "人从众𠈌", "rank": "B", "desc": "你制作的伙伴卡类型必定为“复数个体”，且制卡时高概率获得羁绊技能一类的词条" },
  { "name": "生九子", "rank": "E", "desc": "你不是龙，但你依然生性淫乱，每次做爱时必定诞下九个孩子。" },
  { "name": "小小的也很可爱", "rank": "B", "desc": "你制作的伙伴卡的伙伴必定小且可爱，获得怜悯效果（对手战意减弱）" },
  { "name": "矮个子的从容", "rank": "C", "desc": "你很矮，常常被人忽视，存在感减弱，个子越矮幸运值越高" },
  { "name": "平地摔的馈赠", "rank": "B", "desc": "每天必定平地摔一次，之后会幸运地遇到一次“馈赠”，摔得越惨，获得的“馈赠”越好" },
  { "name": "抽象派", "rank": "D", "desc": "你制作的卡面充满艺术气息，也许会有意想不到的效果" },
  { "name": "只是个面瘫", "rank": "D", "desc": "你是个面瘫，对普通敌人产生威慑效果，但对某些敌人会使其增强战意" },
  { "name": "哈基咪爱好者", "rank": "D", "desc": "你制作的伙伴卡将与猫有关，但它可能对你哈气，战斗时使动物类伙伴获得属性加成，猫类获得额外加成" },
  { "name": "听个响", "rank": "E", "desc": "你能打出很响的响指，这也许很酷" },
  { "name": "冷笑话", "rank": "D", "desc": "你的笑话很冷，让人遍体生寒、行动迟缓，但你会因为自己的笑话笑个不停" },
  { "name": "厨神？", "rank": "A", "desc": "你做的食物很好看且拥有随机永久增益效果，但非常难吃" },
  { "name": "flag%s", "rank": "S", "desc": "你向别人立下的flag从不让人失望，以各种奇怪的形式" },
  { "name": "替身之力", "rank": "A", "desc": "你的攻击会伴随\"欧拉欧拉\"或者\"木大木大\"等意义不明的叫声，同时会出现一个其他人看不见的替身攻击敌方。" },
  { "name": "反间计", "rank": "A", "desc": "你可以通过言语描述、虚假情报等任意方式，降低敌方伙伴卡的忠诚度，降低程度决定于你言语的煽动性、逻辑合理性" },
  { "name": "这他妈就离谱！", "rank": "A", "desc": "当你将一件事说的越离谱时，NPC将会越相信你的话。你的语言，将引来神灵的关注。" },
  { "name": "启明哲智", "rank": "S", "desc": "你无需设备链接即可随时进入天网，并获取查询天网数据库的权限。降低所有制卡流派的失败概率，并使良性突变与高阶突变概率提高。" },
  { "name": "鸿图华构", "rank": "SSS", "desc": "你可以无视素材等级限制进行制卡，并能将任意素材/卡牌（不论类型）融合成一张全新的、未知的素材/卡牌。天生能看到素材中所有隐藏的词条，并可直接剔除负面词条，制作卡牌与剥离词条时精神力消耗为正常的1/3。" },
  { "name": "千秋证果", "rank": "SS", "desc": "你的属性修正为floor(((L-1)/10)+1)而非标准制卡师的floor((L-1)/10)，但升级所需EXP为标准制卡师的5倍(比如不入流每级需要500，黑铁每级需要2000)。你与伙伴获得的EXP会储存起来，需要手动升级，储存的EXP可分享给伙伴卡。" },
  { "name": "天征霸域", "rank": "SSS", "desc": "无效化对方领域卡对你的影响。你和你的所有伙伴卡将获得【帝授荣勋】词条：战斗开始时额外行动1次并免疫1次敌人的攻击，并在回合结束后解除一项负面状态。当战斗胜利时可选择对方的一张卡牌夺走，对每个人只能作用一次，可以放弃夺取的权限。" },
  { "name": "脏枪小子", "rank": "S", "desc": "你拥有一把可以无限改造，增加任何东西的枪。枪越大，枪口越多，声音越响，火力越猛。" },
  { "name": "播种九子", "rank": "D", "desc": "你不是龙，但你依然跟龙一样淫乱，并且与你性交过的对象必定会产下九个子嗣。" },
  { "name": "你真帅", "rank": "D", "desc": "你很帅，经此而已" },
  { "name": "突变巫师", "rank": "SSS", "desc": "你可以自由自在的操控自己与其他事物的身体，将其改变为任何模样" },
  { "name": "初代血魔", "rank": "SSS", "desc": "你是「血魔」的始祖，拥有对下位眷属绝对的统治力，可以随意的操控血液进行战斗或者制卡。你制作的生物卡牌会获得“一代眷属”词条，并且他们可以自行转化眷属。" },
  { "name": "无限精液", "rank": "C", "desc": "你就拥有无限的精液，你完全不用担心被榨干了" },
  { "name": "卡牌之手", "rank": "SSS", "desc": "你可以将任何拥双手触碰到的物品变成你的卡牌" },
    { name: ''污秽洗礼'', rank: ''C'', desc: ''当你的伙伴卡或你自身被敌人的“污物”类技能命中时，不仅免疫其负面效果，反而会恢复少量MP，并暂时提升对“腐蚀”和“精神”攻击的抗性。'' },
    { name: ''小小守护者'', rank: ''C'', desc: ''当你的队伍中有幼态伙伴卡时，所有成年形态的伙伴卡都会自动获得“守护”词条，优先为幼态卡牌格挡伤害。'' },
    { name: ''成长之痛'', rank: ''C'', desc: ''你的幼态伙伴卡在进化（长大）时会经历巨大的痛苦，但作为补偿，她们可以从“力量”、“敏捷”、“智慧”中选择一项属性获得永久性的巨额加成。'' },
    { name: ''观众席'', rank: ''C'', desc: ''你可以制作特殊的【旁观卡】【技能卡】（天赋）。在战斗中对任意两名角色（可包含你的伙伴）使用，强制他们进行亲密互动，而你作为旁观者，可以从中汲取精神力。'' },
    { name: ''体液收藏家'', rank: ''C'', desc: ''你对各种体液有特殊癖好。战斗中收集到的不同体液可以作为添加剂在制卡时使用，为卡牌附加各种意想不到的微弱效果。'' },
    { name: ''公开露出癖'', rank: ''C'', desc: ''你的伙伴卡的装备卡越暴露，其MP，HP恢复速度越快。'' },
    { name: ''矿工之友'', rank: ''D'', desc: ''在矿场搜集素材时，效率略有提升，有小概率发现伴生矿。'' },
    { name: ''森林向导'', rank: ''D'', desc: ''在森林地形中，你的移动速度提升10%，且不易遭遇低级魔物骚扰。'' },
    { name: ''沼泽适应'', rank: ''D'', desc: ''在沼泽地形中，你的移动速度不会受到影响。'' },
    { name: ''二手专家'', rank: ''D'', desc: ''你在购买二手卡牌或素材时，有微小概率发现其隐藏的价值。'' },
    { name: ''刺绣爱好者'', rank: ''D'', desc: ''你制作的【装备卡】会带有刺绣元素，外观更美丽，并获得微弱的属性加成（如：防御+1）。'' },
    { name: ''气味控'', rank: ''D'', desc: ''你对气味很敏感，可以通过闻伙伴卡穿过的衣物来判断其当前的情绪状态。'' },
    { name: ''捆绑初学者'', rank: ''D'', desc: ''你获得了【束缚绳】（饰品）（黑铁）装备卡的制作方法，可以百分百成功制作【束缚绳】（黑铁）卡牌，有较低概率在战斗中束缚敌人一回合或作为情趣道具。'' },
    { name: ''耐寒'', rank: ''D'', desc: ''在雪山等寒冷环境下，体力消耗速度减缓。'' },
    { name: ''耐热'', rank: ''D'', desc: ''在火山口等炎热环境下，体力消耗速度减缓。'' },
    { name: ''动物亲和'', rank: ''D'', desc: ''普通的野兽不会主动攻击你。'' },
    { name: ''灌肠爱好者'', rank: ''D'', desc: ''你可以对伙伴卡亲自进行【灌肠】，清理其身体，小幅提升其对“毒”和“腐蚀”的抗性。'' },
    { name: ''姐姐的呼唤'', rank: ''D'', desc: ''你制作的卡牌有高概率让伙伴卡拥有【温柔体贴】的御姐性格。'' },
    { name: ''美食家'', rank: ''D'', desc: ''能通过烹饪制作出带有微弱buff的食物，效果持续时间很短。'' },
    { name: ''抗干扰'', rank: ''D'', desc: ''在嘈杂的环境中制卡，你的专注度不会受到太大影响。'' },
    { name: ''胶衣爱好者'', rank: ''D'', desc: ''穿着或制作胶衣类装备卡时，你会感到安心，精神力消耗速度降低5%。'' },
    { name: ''完美主义'', rank: ''D'', desc: ''制卡时，你会下意识地将能量调整到最完美状态，这会略微增加制卡时间，但小幅提高成功率。'' },
    { name: ''玉足祈福'', rank: ''D'', desc: ''你可以命令伙伴卡用她们的脚为你的下体进行“抛光”（足交）。此行为能小幅提升你制作卡牌的成功率。'' },
    { name: ''黄金祝福'', rank: ''D'', desc: ''（需要进行【欲望主导】判定）在制卡的关键时刻，若有伙伴卡对你进行“排尿”，则有小概率使卡牌的某个词条品质提升一级。'' },
    { name: ''肠道探险家'', rank: ''D'', desc: ''你对生物的消化系统有特殊理解，可以用于治疗伙伴或对敌人造成难以忍受的内部骚扰。'' },
    { name: ''命名修正'', rank: ''D'', desc: ''为卡牌起一个与其实际能力完全相反的名字（比如给攻击卡起名“爱与和平”），可以使其获得一个隐藏的反转效果。'' },
    { name: ''扁平化设计'', rank: ''D'', desc: ''你制作的所有伙伴卡都是2D纸片人形态，物理防御极低，但对能量攻击有微弱抗性。'' },
    { name: ''滑溜溜'', rank: ''D'', desc: ''获得【体液地雷】【技能卡】（天赋）的制作方法。在地面留下一滩难以察觉的淫液或尿液（同时最多三个），敌人踩上后有极高几率滑倒，并沾染上骚臭的气味。'' },
    { name: ''羞耻回响'', rank: ''D'', desc: ''获得【嘲讽胖次】【装备卡】（头部）（天赋）的制作方法。一条画着鬼脸的内裤，被攻击命中时会发出响亮的嘲讽声：“你没吃饭吗？”，小幅吸引敌人仇恨。'' },
    { name: ''触手亲和'', rank: ''D'', desc: ''获得【伙伴：没用的触手君】【伙伴卡】（天赋）的制作方法。召唤一只只会蠕动和分泌粘液的小触手，毫无攻击力，但可以用来清洁难以触及的角落或作为自慰工具。'' },
    { name: ''失语之咒'', rank: ''D'', desc: ''获得【淫语诅咒】【技能卡】（天赋）的制作方法。使目标在接下来的一分钟内，说出的所有话语都会自动变成不堪入耳的淫言秽语，对施法者有奇效。'' },
    { name: ''油腻之躯'', rank: ''D'', desc: ''你的身体会分泌一层薄薄的油脂，让敌人很难抓住你，但同时也会让你闻起来像一周没洗澡。'' },
    { name: ''屁之艺术'', rank: ''D'', desc: ''获得【响屁术】【技能卡】（天赋）的制作方法。发出一声可控音量和音调的屁，可以用来吸引注意力、模仿特定声音，或者单纯为了恶心人。'' },
    { name: ''毛发增生'', rank: ''D'', desc: ''获得【疯长之毛】【技能卡】（天赋）的制作方法。让目标（或自己）的阴毛或腋毛在瞬间疯长到一米长，可以起到遮蔽视线或绊倒敌人的作用。'' },
    { name: ''呕吐物爱好者'', rank: ''D'', desc: ''获得【反刍之力】【技能卡】（天赋）的制作方法。可以让敌人瞬间呕吐，造成微量伤害和“恶心”debuff。'' },
    { name: ''丝袜即是正义'', rank: ''D'', desc: ''将丝绸、蛛丝等材料作为辅助素材，制成的伙伴卡会自动生成各种款式的【丝袜】作为初始装备。'' },
    { name: ''辣妹养成'', rank: ''D'', desc: ''使用“宝石”、“香料”、“丝绸”等艳丽的素材，容易制造出肤色健康、性格开放、喜欢打扮的【辣妹】（Gyaru）伙伴卡。'' },
    { name: ''触手共鸣'', rank: ''D'', desc: ''使用章鱼、水母等软体生物素材，伙伴卡不仅可能拥有触手，性格也会变得【黏人】、【痴缠】。'' },
    { name: ''无口之声'', rank: ''D'', desc: ''在绝对安静的环境下，不发一言地完成制卡，伙伴卡有较高概率成为情感不外露的【无口】少女。'' },
    { name: ''元气注入'', rank: ''D'', desc: ''在阳光明媚的早晨，一边做着广播体操一边制卡，能显著提升伙伴卡成为【元气少女】的概率。'' },
    { name: ''自慰熟练'', rank: ''D'', desc: ''在非战斗状态下，你的自慰速度提升50%，并能更快地进入“贤者时间”以抵抗精神攻击。'' },
    { name: ''酒鬼的诞生'', rank: ''D'', desc: ''使用任何含酒精的液体作为融合剂，伙伴卡都会有【嗜酒】的特性，喝醉后会展现出隐藏的另一面性格。'' },
    { name: ''恋物癖之心'', rank: ''D'', desc: ''获得【原味收集】【技能卡】（天赋）的制作方法。（一次性卡牌）可以从敌人身上窃取一件穿过的内衣或袜子，该物品可作为下次【欲望主导】制卡的微弱增幅素材。'' },
    { name: ''健壮'', rank: ''E'', desc: ''你的负重上限提升10公斤。'' },
    { name: ''格斗熟练'', rank: ''D'', desc: ''你的伙伴卡有更强的近身搏斗能力。'' },
    { name: ''干净整洁'', rank: ''E'', desc: ''你总是能把自己的装备和卡牌擦得锃亮，与NPC初次见面时好感度有微弱提升。'' },
    { name: ''方向感'', rank: ''E'', desc: ''在探索过的区域，你不会迷路。'' },
    { name: ''早起'', rank: ''E'', desc: ''每天早上你会比别人更早醒来，多出一些自由活动时间。'' },
    { name: ''不挑食'', rank: ''E'', desc: ''吃任何食物都能正常恢复体力，哪怕是味道古怪的炼金产物。'' },
    { name: ''口才'', rank: ''E'', desc: ''你说话比较利索，与人争论时不易吃亏。'' },
    { name: ''甜食爱好者'', rank: ''E'', desc: ''吃甜食时，你的心情会变好，精神力恢复速度有微乎其微的提升。'' },
    { name: ''恋物癖(内衣)'', rank: ''E'', desc: ''收集伙伴卡的内衣会让你感到满足，但并没有实际效果。'' },
    { name: ''打屁股爱好者'', rank: ''E'', desc: ''通过打伙伴卡的屁股可以进行无伤大雅的训诫，小幅提升其执行命令的效率。'' },
    { name: ''声优'', rank: ''E'', desc: ''你很会模仿各种声音，包括魔物的叫声，有时可以用来迷惑敌人。'' },
    { name: ''内衣交换'', rank: ''E'', desc: ''获得【内裤置换】【技能卡】（天赋）的制作方法。随机交换你与目标当前穿着的内裤。天知道你会换来一条龙的丁字裤还是一条公主的蕾丝内裤。'' },
    { name: ''恶臭光环'', rank: ''E'', desc: ''获得【腐烂咸鱼之触】【技能卡】（天赋）的制作方法。让一件物品（或生物）在24小时内散发出强烈的腐烂咸鱼混合脚臭的气味，不可驱散。'' },
    { name: ''催乳之术'', rank: ''E'', desc: ''获得【无限泌乳】【技能卡】（天赋）的制作方法。使一个哺乳动物目标（包括你自己）在接下来的一小时内不受控制地喷射乳汁，射程一米。'' },
    { name: ''裆部毁灭者'', rank: ''E'', desc: ''获得【召唤：寻根鹅】【伙伴卡】（天赋）的制作方法。召唤一只对所有生物的胯下部位有无尽恨意的白鹅，它会不顾一切地冲向并啄击目标裆部，直到自身死亡。'' },
    { name: ''凌晨四点的黑石城'', rank: ''E'', desc: ''在凌晨3点到4点之间制卡，有微小几率触发“灵感迸发”，无视规则随机生成一个词条。'' },
    { name: ''闪光地狱'', rank: ''E'', desc: ''获得【妖男金粉】【技能卡】（天赋）的制作方法。使用后撒向目标后会使其在黑暗中也闪闪发光，如同午夜牛郎。'' },
    { name: ''娇小迷恋'', rank: ''E'', desc: ''你更容易制作出娇小的卡牌。'' },
    { name: ''歌剧之魂'', rank: ''E'', desc: ''获得【咏叹调诅咒】【技能卡】（天赋）的制作方法。使目标在接下来的十分钟内，必须用破锣嗓子的歌剧咏叹调来说话，否则会受到微弱的电击伤害。'' },
    { name: ''废话文学'', rank: ''E'', desc: ''在制卡过程中，持续不断地对素材进行长达十分钟的无意义描述，可以使其精神麻痹，降低融合抗性。'' },
    { name: ''武器戏法'', rank: ''E'', desc: ''获得【橡胶鸡之神】【技能卡】（天赋）的制作方法。将目标手中的武器变成一只一捏就会惨叫的橡胶鸡，持续5秒。对空手的目标无效。'' },
    { name: ''生理认知错乱'', rank: ''E'', desc: ''获得【幻鸡症】【技能卡】（天赋）的制作方法。让目标坚信自己长出了一条巨大的鸡巴（或骚屄），并试图用它来攻击，但实际上什么都不会发生。'' },
    { name: ''凡骨【禁法】（东方）'', rank: ''E'', desc: ''你只是个普通人，体内没有任何灵力，也无法感受到卡兰大陆的魔力，但你拥有概念级能力，禁法，任何能量攻击都无法对你和你的伙伴卡造成伤害，你和你的伙伴卡也无法使用魔力，你的伙伴卡MP值始终为0，但每次升级其余的基础属性增长倍率为1.5。'' },
    { name: ''强制露阴'', rank: ''E'', desc: ''获得【裤子消失术】【技能卡】（天赋）的制作方法。有50%的几率让目标的裤子（或裙子）瞬间消失，如果失败，则自己的裤子会消失。'' },
    { name: ''变声器'', rank: ''E'', desc: ''获得【萝莉音/大叔音】【技能卡】（天赋）的制作方法。让目标的声音在接下来的对话中变成甜腻的萝莉音或油腻的大叔音。'' },
    { name: ''视觉污染'', rank: ''E'', desc: ''获得【马赛克之眼】【技能卡】（天赋）的制作方法。让目标的视野中，所有生物的生殖器部位都被打上厚厚的马赛克，持续一分钟。'' },
    { name: ''绝对音痴'', rank: ''E'', desc: ''获得【魔音贯耳】【技能卡】（天赋）的制作方法。强制目标唱一首儿歌，其歌声会对其自身和周围的友军造成微量的精神伤害和“耳鸣”效果。'' },
    { name: ''勃起凝视'', rank: ''E'', desc: ''获得【瞪谁谁硬】【技能卡】（天赋）的制作方法。你的凝视可以让任何有相应器官的目标不受控制地勃起，持续数秒，有微小概率打断其施法。'' },
    { name: ''万物皆可肛'', rank: ''E'', desc: ''获得【后庭探索者】【被动技能卡】（天赋）的制作方法。让你获得透视所有生物屁眼的能力，并能大概判断出其括约肌的松紧程度。仅此而已。'' },
    { name: ''过目不忘'', rank: ''E'', desc: ''你看过的卡牌图鉴和配方都能记住。'' },
    { name: ''气味鉴赏家'', rank: ''E'', desc: ''你仅通过气味就能分辨出不同素材的产地和大致品质，在购买未鉴定素材时有点用。'' },
    { name: ''人体彩绘师'', rank: ''E'', desc: ''你可以用特殊的颜料在伙伴卡身上绘制魔法阵，提供一些微不足道但颇具观赏性的临时buff。'' },
    { name: ''深渊领主'', rank: ''SSS'', desc: ''你可以与深海中任何超过你等级的巨型魔物建立"深渊契约"。契约成功后，该魔物会化为一张特殊的【伙伴卡】，保留其全部深海词条，且自带"深渊压制"被动——在水下环境中，全属性额外提升40%。'' },
    { name: ''海神代言人'', rank: ''SS'', desc: ''你能听懂所有海洋生物的语言，并且可以用精神力向它们下达简单指令。每日可以免费召唤一群低级海洋生物为你侦查、运输或骚扰敌人。制作与海洋生物相关的伙伴卡时，初始忠诚度直接拉满。'' },
    { name: ''永恒航路'', rank: ''SS'', desc: ''你的脑海中刻印着一张不断自动更新的完整海图，包括所有已知和未知的暗礁、洋流、沉船位置与魔物巢穴分布。你在海上永远不会迷失方向，且航行速度提升50%。'' },
    { name: ''黑潮之子'', rank: ''SS'', desc: ''你的身体已经适应了深海的极端环境。你在水下不需要呼吸，免疫水压伤害，且在深海环境中敏捷和防御各提升30%。'' },
    { name: ''碎嘴鹦鹉'', rank: ''B'', desc: ''开局获得一张青铜级伙伴卡【满嘴骚话的鹦鹉】。鹦鹉拥有飞行侦查能力，会在战斗中不停用尖锐刻薄的脏话辱骂敌人，有几率使敌方陷入"激怒"或"羞耻"状态。鹦鹉的忠诚度极高但永远无法闭嘴。'' },
    { name: ''鲨鱼嗅觉'', rank: ''C'', desc: ''你对血液的气味极度敏感。在半径500米内，只要有生物流血，你就能精准锁定其位置。血量越低的目标，你对其造成的伤害越高。'' },
    { name: ''海妖之歌'', rank: ''A'', desc: ''你可以制作特殊的【海妖之歌】系列技能卡。使用时发出魔力灌注的歌声，对听到歌声的敌人造成"迷惑""眩晕"或"恐惧"效果。效果强度取决于你的MP与目标的精神抗性差值。但歌声无差别传播，友军也有几率受到影响。'' },
    { name: ''深渊之瞳'', rank: ''A'', desc: ''你的双眼适应了深海的黑暗。在水下环境中获得完美的暗视能力，且能看穿一切隐身与幻术效果。在陆地上，你的视力在黑夜中同样优越，但强光会对你造成短暂致盲。'' },
    { name: ''藤壶寄生'', rank: ''C'', desc: ''获得【藤壶铠甲】【装备卡】（全身）（天赋）的制作方法。用海洋藤壶类素材制作的活体铠甲，提供中等物理防御。被近战攻击时，藤壶会自动割伤攻击者，造成"流血"效果。但穿戴者移动速度降低10%。'' },
    { name: ''深海发光体'', rank: ''C'', desc: ''你的身体在黑暗环境中会发出微弱的生物荧光，为周围提供照明。该光芒可以主动关闭，但在你情绪激动时会不受控制地闪烁。制作光属性素材时，可以用自身的荧光作为辅助催化剂。'' },
    { name: ''海底捞月'', rank: ''S'', desc: ''你在进行任何"打捞""采集""搜索"行为时，有额外15%的概率获得超出预期一个等级的物品或素材。该概率在月圆之夜翻倍至30%。'' },
    { name: ''深海垂钓者'', rank: ''B'', desc: ''你拥有一根不可摧毁的幽灵钓竿（不占装备栏）。在任何有水体的地方，你可以花费10分钟进行垂钓，随机获得从垃圾到稀有素材的各种收获。水体越深、越危险，钓到好东西的概率越高。但你也有可能钓到不想钓到的东西——比如一头愤怒的深海魔物。'' },
    { name: ''海怪之胃'', rank: ''C'', desc: ''你可以食用任何海洋生物的生肉——无论多么恶心、有毒或腥臭——都不会中毒或生病，反而能恢复少量HP。食用高等级海洋魔物的肉时，有极低概率临时获得该魔物的一项能力。'' },
    { name: ''龙涎香鉴定师'', rank: ''C'', desc: ''你拥有鉴定海洋生物遗留物的专业能力。在处理海洋类素材时，你有20%的概率从普通素材中额外发现一个隐藏词条。此外，你在出售海洋素材时价格提升15%，因为你知道如何向买家吹嘘它们的价值。'' },
    { name: ''盐风铸甲'', rank: ''B'', desc: ''你制作的所有装备卡都会自带"盐蚀"词条——装备者的近战攻击会在伤口中留下盐分结晶，使"流血"效果的伤害提升且持续时间翻倍。'' },
   { name: ''珍珠产卵器'', rank: ''A'', desc: ''获得【蚌女的诅咒】【装备卡】（贞操带型）的制作方法。强制装备给战败的女性敌人后，她们的子宫会被改造为珍珠培育室，每天需消耗其HP孕育出一颗【催情珍珠】（高阶素材）。'' }, 
   { name: ''塞壬之主'', rank: ''SS'', desc: ''你可以用任意女性NPC的毛发配合海洋素材，必定制作出专属伙伴卡【塞壬】。她不仅拥有顶级的音波攻击，其特殊技能【靡靡之音】能让全场非水属性敌方单位陷入“强制发情”状态，防御力归零。'' }, 
   { name: ''触手苗床'', rank: ''S'', desc: ''你可以用深海软体动物素材制作专属伙伴卡【触手娘】。该卡牌在战斗中可通过“侵犯”并“注射黏液”到敌方女性单位体内，将其临时转化为受你控制的傀儡，战斗结束后可提取出【淫堕的苗床精粹】素材。'' }, 
   { name: ''龙宫驸马'', rank: ''S'', desc: ''你天生自带一张无法遗弃的专属伙伴卡【傲娇的龙女】。只要你每天通过体液交换（如深吻、交媾）为其补充“阳气”，她的全属性将随你的等级同步成长，且你制作的所有水属性装备卡对她效果翻倍。'' }, 
   { name: ''裸露狂'', rank: ''C'', desc: ''你和你的伙伴卡身上穿的越少，你们的敏捷和攻击力加成就越高，最高可达200%。'' }, 
   { name: ''深海恐惧'', rank: ''B'', desc: ''你散发着深渊的气息。所有非水属性的敌人在面对你时，幸运值强制减半，且有几率在战斗中产生“溺水”的幻觉，导致窒息而死。'' }, 
   { name: ''海洋之心'', rank: ''SS'', desc: ''你对所有水属性卡牌拥有绝对支配权。敌方使用的水属性【技能卡】或【领域卡】对你无效，且你可以消耗双倍MP强行夺取敌方水属性【伙伴卡】的控制权。'' }, 
   { name: ''唤雨师'', rank: ''C'', desc: ''你可以随时改变局部天气，降下暴雨。在雨中，你的水属性伙伴卡HP持续恢复，且女性角色的衣物会湿身透视。'' }, 
   { name: ''剧毒水母'', rank: ''B'', desc: ''你制作的水属性卡牌有极高概率突变出“神经毒素”词条。中毒者会全身麻痹，但痛觉和触觉会被放大十倍，是极佳的审讯和调教手段。'' }, 
   { name: ''盲眼海鱼'', rank: ''C'', desc: ''你免疫一切“致盲”和“强光”效果。在绝对黑暗的环境中，你的感知力大幅提升，能通过水流和空气的震动精准锁定敌人的位置（甚至能感知到敌人心跳和体液流动的声音）。'' }, 
   { name: ''鱼群意识'', rank: ''S'', desc: ''你可以分裂出数百条由精神力构成的微小透明游鱼。它们可以潜入敌人的营地、衣物内甚至体内进行侦查，为你提供绝对的视野和情报。'' }, 
   { name: ''美人鱼的眼泪'', rank: ''B'', desc: ''你可以通过虐待或感动你的人鱼类伙伴卡，收集她们流下的眼泪。这些眼泪是制作高级卡牌的核心素材。'' }, 
   { "name": "法老的恩典", "rank": "S", "desc": "你可以用古代干尸素材必定制作出专属伙伴卡【艳后木乃伊】。她能操控绷带进行“龟甲缚”等高难度捆绑。被她缠住的敌人会被缓慢吸干体液（HP与MP）。" }, 
   { "name": "蝎后巢穴", "rank": "S", "desc": "你可以用毒蝎素材制作专属伙伴卡【沙漠蝎后】。她的尾刺不致命，但注入的毒液是极品催情剂。被击中的敌人会浑身燥热，失去理智主动求欢。蝎后可以通过交媾将虫卵产在敌人体内，孵化出受你控制的低阶蝎人。" }, 
   { "name": "壶中女仆", "rank": "SS", "desc": "获得专属道具卡【神灯】的制作方法。摩擦神灯可召唤出专属伙伴卡【沙漠神灯精灵】。她可以实现你“改变NPC认知”的愿望（如让高傲的公主认为自己是你的性奴），愿望越离谱，需要的代价就越多。" }, 
   { "name": "胡狼嗅觉", "rank": "C", "desc": "你的嗅觉如同胡狼般敏锐。你能隔着几公里闻到血液、汗液的味道，从而精准追踪猎物，绝不迷路。" }, 
   { "name": "卡诺匹斯魔罐", "rank": "B", "desc": "获得【灵魂储存罐】【道具卡】的制作方法。可以封印即将消散的魔物灵魂。集齐四种特定属性的灵魂罐，可融合制作出一张随机的高阶元素伙伴卡。" }, 
   { "name": "沙漠行者", "rank": "C", "desc": "你完全适应了沙漠的极端气候。免疫‘中暑’、‘冻伤’等环境负面状态，且在沙地上的移动速度不受地形减速影响。" }, 
   { "name": "蝗灾降临", "rank": "A", "desc": "获得【十灾·蝗虫】【技能卡】的制作方法。召唤铺天盖地的魔力蝗虫，迅速啃噬战场上的所有植物系魔物和木制建筑/装备。" }, 
   { "name": "血水之灾", "rank": "B", "desc": "获得【十灾·血水】【技能卡】的制作方法。将指定区域的水源转化为沸腾的毒血，饮用者将受到严重毒害，处于血水中的敌人速度减半。" }, 
   { "name": "冰雹与火", "rank": "A", "desc": "获得【十灾·冰火】【技能卡】的制作方法。召唤夹杂着烈焰的巨大冰雹轰击敌阵，造成冰火双重属性的范围伤害，并破坏地形。" }, 
   { "name": "黑暗之灾", "rank": "B", "desc": "获得【十灾·黑暗】【技能卡】的制作方法。剥夺指定区域内所有敌方单位的视觉，使其陷入‘致盲’状态，且无法被常规照明魔法驱散。" }, 
   { "name": "神灯眷属", "rank": "SSS", "desc": "你可以消耗极品魔法金属与灵魂素材，必定制作出专属伙伴卡【神灯精灵·阿米娜】。她能实现你的愿望（如修改现实、大范围洗脑），但每次许愿后，你需要用大量MP或浓厚的体液精气来重新填满她。" }, 
   { "name": "极乐水烟", "rank": "B", "desc": "获得【致幻水烟壶】【道具卡】的制作方法。点燃后散发异域香料的烟雾。吸入烟雾的敌人会陷入“极乐幻境”，在幻觉中失去战斗力。" }, 
   { "name": "星象占卜", "rank": "B", "desc": "在繁星密布的夜晚，你可以通过占卜预测第二天的运势。" }, 
   { "name": "幻沙舞娘", "rank": "B", "desc": "你可以用风属性与魅惑素材制作伙伴卡【幻沙舞娘】。她精通所有异域舞蹈。战斗时，她的舞姿能让敌方全体陷入“目眩神迷”状态，命中率大幅下降。" }, 
   { "name": "盗贼王女", "rank": "B", "desc": "你可以制作专属伙伴卡【大盗首领·】。她拥有极高的敏捷与潜行能力。她的专属技能【妙手空空】不仅能偷取敌人的稀有素材，还能在不知不觉中解开敌方女性的防具搭扣，使其陷入“爆衣”与“羞耻”状态。" }, 
   { "name": "芝麻开门", "rank": "A", "desc": "你掌握了古老的开锁咒语。无论是遗迹的远古宝箱、敌人的魔法结界，还是女性NPC身上的贞操带或紧身胸衣，你只需一句“芝麻开门”就能瞬间将其无损解开。" }, 
   { "name": "夜之城", "rank": "C", "desc": "你是属于夜晚的王者。在夜间（或黑暗环境中），你的所有“潜行”、“偷窃”、“魅惑”技能成功率翻倍。" }, 
   { "name": "鹰眼", "rank": "C", "desc": "获得【沙漠猎鹰】【伙伴卡】的制作方法。召唤一只猎鹰为你侦查。" }, 
   { "name": "天方夜谭", "rank": "SSS", "desc": "你的制卡不再局限于物质素材。你可以将“传说”、“故事”甚至“NPC的记忆”作为素材投入制卡中。以这种方式制作的卡牌，必定拥有【神话级】词条，且能短暂修改局部现实。" }, 
   { "name": "黄金脚链", "rank": "C", "desc": "获得【魅惑脚链】【装备卡】的制作方法。专为舞娘设计的饰品。移动或跳舞时会发出清脆的铃声，铃声带有轻微的催眠效果，能逐渐瓦解敌人的意志。" },
    ];
const rankOrder={SSS:8,SS:7,S:6,A:5,B:4,C:3,D:2,E:1,F:0};
const RANK_DESC=[''SSS'',''SS'',''S'',''A'',''B'',''C'',''D'',''E'',''F''];
const ALL_RANKS=[''F'',''E'',''D'',''C'',''B'',''A'',''S'',''SS'',''SSS''];
const poolDiv=document.getElementById(''talent-pool'');
const fullDiv=document.getElementById(''full-talent-list'');
const genBtn=document.getElementById(''generate-talents-btn'');
const foldHead=document.getElementById(''full-list-toggle'');
const foldCaret=document.getElementById(''full-list-caret'');
const rankBtns=document.querySelectorAll(''.rank-btn'');
const rankSet=new Set();const locked=new Set();const selSet=new Set();
window.__selectedTalents=[];
const cntEl=document.getElementById(''full-list-count'');if(cntEl)cntEl.textContent=pool.length;
const idxByRank={};
pool.forEach(function(t,i){(idxByRank[t.rank]||(idxByRank[t.rank]=[])).push(i)});
/* 等级配色只在启动时读一次并缓存：旧版每张卡都要跑一遍 getComputedStyle，631 张卡上万次强制样式重算，手机必卡 */
const RANK_COLOR=(function(){var cs=getComputedStyle(document.documentElement),m={};ALL_RANKS.forEach(function(r){m[r]=(cs.getPropertyValue(''--rank-''+r.toLowerCase())||'''').trim()||''#7ce5b0''});return m})();
function stripeByRank(r){return RANK_COLOR[r]||''#7ce5b0''}
function esc(s){return String(s).replace(/&/g,''&amp;'').replace(/</g,''&lt;'').replace(/>/g,''&gt;'').replace(/"/g,''&quot;'')}
function cardHTML(i,lockable){
var t=pool[i],c=stripeByRank(t.rank);
var cls=''talent-card''+(selSet.has(i)%s'' selected'':'''')+(lockable&&locked.has(i)%s'' locked'':'''');
return ''<div class="''+cls+''" data-i="''+i+''" style="--stripe:''+c+''"><div class="talent-card-back"><div class="talent-card-header"><span class="talent-card-name">''+esc(t.name)+''</span><span class="talent-card-rank" style="--chip:''+c+''">''+t.rank+''</span></div><p class="talent-card-desc">''+esc(t.desc)+''</p>''+(lockable%s''<button class="lock-btn" type="button">&#128274;</button>'':'''')+''</div></div>'';
}
/* 点选后只更新同名的那一两张卡，不再 querySelectorAll 全表 631 个节点 */
function syncOne(i){var on=selSet.has(i),l=document.querySelectorAll(''.talent-card[data-i="''+i+''"]'');for(var k=0;k<l.length;k++)l[k].classList.toggle(''selected'',on)}
function toggleSelect(i){
var t=pool[i];if(!t)return;
if(selSet.has(i)){selSet.delete(i);var p=window.__selectedTalents.indexOf(t);if(p>-1)window.__selectedTalents.splice(p,1)}
else{selSet.add(i);window.__selectedTalents.push(t)}
syncOne(i);
if(typeof window.updatePreview===''function'')window.updatePreview();
}
/* 事件委托：每个容器一个监听器，取代旧版「每张卡各挂一个」 */
function delegate(root){
if(!root)return;
root.addEventListener(''click'',function(e){
var el=e.target;if(!el||!el.closest)return;
var card=el.closest(''.talent-card'');if(!card)return;
var i=parseInt(card.dataset.i,10);if(isNaN(i))return;
if(el.closest(''.lock-btn'')){if(locked.has(i)){locked.delete(i);card.classList.remove(''locked'')}else{locked.add(i);card.classList.add(''locked'')}return}
toggleSelect(i);
});
}
delegate(poolDiv);delegate(fullDiv);
function render(list){if(poolDiv)poolDiv.innerHTML=list.map(function(i){return cardHTML(i,true)}).join('''')}
/* 分帧填充：一次性插 100+ 张卡会让手机长时间掉帧，改成每帧 40 张 */
function fillGroup(body,arr){
var idx=0,STEP=40,token=String(Date.now())+''-''+Math.random();
body.dataset.fill=token;
(function step(){
if(!body.isConnected||body.dataset.fill!==token)return;
if(idx>=arr.length){body.dataset.fill='''';return}
body.insertAdjacentHTML(''beforeend'',arr.slice(idx,idx+STEP).map(function(i){return cardHTML(i,false)}).join(''''));
idx+=STEP;requestAnimationFrame(step);
})();
}
function closeGroup(g){
var body=g.querySelector(''.rank-group-body''),car=g.querySelector(''.fold-caret'');
g.classList.remove(''open'');if(car)car.textContent=''▶'';
if(body){body.dataset.fill='''';body.innerHTML=''''}
}
function openGroup(g){
var body=g.querySelector(''.rank-group-body''),car=g.querySelector(''.fold-caret'');
g.classList.add(''open'');if(car)car.textContent=''▼'';
if(body&&!body.firstChild)fillGroup(body,idxByRank[g.dataset.rank]||[]);
}
function renderFullTalentList(){
if(!fullDiv)return;
if(fullDiv.classList.contains(''collapsed'')){fullDiv.dataset.stale=''1'';return}
var ranks=RANK_DESC.filter(function(r){return (!rankSet.size||rankSet.has(r))&&(idxByRank[r]||[]).length});
if(!ranks.length){fullDiv.innerHTML=''<p class="talent-empty">没有符合筛选条件的天赋。</p>'';fullDiv.dataset.stale='''';return}
fullDiv.innerHTML=ranks.map(function(r){
return ''<div class="rank-group" data-rank="''+r+''" style="--stripe:''+stripeByRank(r)+''"><div class="rank-group-head"><span class="rg-name">''+r+'' 级天赋<span class="cnt">共 ''+idxByRank[r].length+'' 条</span></span><span class="fold-caret">▶</span></div><div class="rank-group-body"></div></div>'';
}).join('''');
fullDiv.dataset.stale='''';
if(ranks.length===1)openGroup(fullDiv.firstChild);
}
if(fullDiv){fullDiv.addEventListener(''click'',function(e){
var el=e.target;if(!el||!el.closest)return;
var head=el.closest(''.rank-group-head'');if(!head)return;
var g=head.parentNode;
if(g.classList.contains(''open''))closeGroup(g);else openGroup(g);
})}
if(foldHead){foldHead.addEventListener(''click'',function(){
var collapsed=fullDiv.classList.toggle(''collapsed'');
if(foldCaret)foldCaret.textContent=collapsed%s''▶'':''▼'';
if(collapsed){fullDiv.innerHTML='''';fullDiv.dataset.stale=''1''}
else if(fullDiv.dataset.stale===''1''||!fullDiv.firstChild)renderFullTalentList();
})}
rankBtns.forEach(function(b){b.addEventListener(''click'',function(){
b.classList.toggle(''active'');
if(b.classList.contains(''active''))rankSet.add(b.dataset.rank);else rankSet.delete(b.dataset.rank);
renderFullTalentList();
})});
function roll(){
var want=rankSet.size%sArray.from(rankSet):ALL_RANKS;
var kept=Array.from(locked),avail=[];
pool.forEach(function(t,i){if(want.indexOf(t.rank)>-1&&!locked.has(i))avail.push(i)});
for(var k=avail.length-1;k>0;k--){var r=Math.floor(Math.random()*(k+1)),tmp=avail[k];avail[k]=avail[r];avail[r]=tmp}
var need=Math.max(0,9-kept.length);
var out=kept.concat(avail.slice(0,need)).sort(function(a,b){return (rankOrder[pool[b].rank]||0)-(rankOrder[pool[a].rank]||0)});
render(out);
}
if(genBtn){genBtn.addEventListener(''click'',roll);genBtn.addEventListener(''touchend'',function(e){e.preventDefault();roll()},{passive:false});roll()}
})();
</script>
</body>
</html>', '开放世界', '2026-10-11 11:21:40', '2026-10-11 11:21:40', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('972540eb-b794-48ba-b70c-f02c3c2e6a15', '只要考得好，妈妈可以满足我一个不花钱的要求', '母子禁忌 · 越界先例', '🏠', '只要考得好，妈妈可以满足我一个不花钱的要求', '母子禁忌 · 越界先例', 'https://catai.wiki/1dfaa07b-2460-4f7f-db8a-0aa0c6c4f700/cover', '#f97316', 'linear-gradient(135deg, #f97316 0%, #ea580c 100%)', '{"title": "只要考得好，妈妈可以满足我一个不花钱的要求", "desc": "为了激励即将高考的你，全职主妇母亲林雨晴（37岁/E罩杯）许下承诺：“只要你考得好，妈妈可以满足你一个不花钱的要求。”她以为只是捶背倒水，却没想到在父亲频繁加班与出差的深夜，那件穿了五年的V领家居服下藏着的一切，被儿子一步一步用成绩兑现……独创“先例系统”，每一次越界永远记录，沦陷无法回头。", "bg_image": "https://catai.wiki/1dfaa07b-2460-4f7f-db8a-0aa0c6c4f700/cover", "opening_options": ["【月考放榜·深夜兑现】：“月考成绩单摆在茶几上，数学单科年级第一。妈妈端着温牛奶进屋，眼神既欣慰又有些紧张地轻声问：‘说吧，这次想要什么奖励？’你把目光移向她宽松领口下的雪白……”", "【父亲出差·留灯独处】：“父亲去外地出差三天，偌大的客厅只有电视微弱的反光。妈妈洗完澡穿着单薄的棉质睡裙走出来擦头发，水汽弥漫中，你叫住了她……”", "【书桌辅导·暗流涌动】：“晚自习做题遇到卡顿，妈妈坐在身旁轻声讲题，身上淡淡的雪花膏香味与温热的体温不断靠拢，你的手假装不经意地落在了她的大腿上……”"]}', '[{"name": "林雨晴", "role": "母亲 (37岁 / 全职主妇 / 170cm / E罩杯 / 温柔知性)", "desc": "原本是公司文员，为了照顾你辞职。旧手机摔裂了还舍不得换，把所有的爱与未来寄托在你身上。心底有身为母亲的道德底线，但在你优异的成绩和步步紧逼的“要求”下，开始逐渐动摇、羞耻妥协。"}, {"name": "儿子 (玩家)", "role": "高三备考生", "desc": "成绩优异，深谙母亲对自己的期望。在一次次以成绩换取奖励的博弈中，撕开母子之间隐秘的禁忌面纱。"}]', '[{"title": "老旧两居室 · 深夜微光客厅", "desc": "泛黄的墙纸，旧布艺沙发，微弱的电视荧光与母子温存的私密空间。"}, {"title": "主卧大床 · 弥漫水汽与雪花膏香味", "desc": "父亲出差后空旷的大床，月光透过薄纱窗帘洒在被褥上。"}]', '{"dialogue_style": "生动细腻的生活化情感推拉，深度神态捕捉与心理博弈", "format": "AI风月标准双栏规范及.custom-ui样式"}', '{"index": 1, "isUser": false, "scene": "老旧两居室 · 深夜微光客厅", "story": "<tl>📅时间：高三月考放榜夜 22:30 | 🌏地点：老旧两居室客厅 | 🚪氛围：温存与心跳博弈</tl>\n\n<article>\n<p>客厅里的老式石英钟滴答走着，电视机被调成了静音，屏幕的荧蓝光芒在泛黄的墙纸上流转。</p>\n\n<p>茶几的正中央端端正正地放着那张盖着学校红章的月考成绩单——总分642，单科数学141分，全校第七名。</p>\n\n<p>厨房的移门轻轻拉开，母亲林雨晴端着一杯温热的甜牛奶款步走了出来。她今年三十七岁，虽然常年的操劳在眼角留下了极细微的纹路，但岁月却给了她一种无可挑剔的成熟韵味。她身上穿着那件领口微松的旧灰粉色棉质家居裙，170公分的高挑身形被勾勒出温软丰满的弧度，走动间胸前沉甸甸的E罩杯随着呼吸轻微晃动。</p>\n\n<p><w>“儿子，还没睡呢？”</w>林雨晴把牛奶杯轻放在茶几上，目光落在成绩单上，那双温柔似水的眸子里满是欣慰与骄傲，嘴角弯起好看的弧度，<w>“数学考得真好……妈说话算话，之前答应你的，只要考进前十，满足你一个不花钱的要求。说吧，想要什么？妈都依你。”</w></p>\n\n<p>她微笑着在你身旁坐下，沙发陷下去了一块，空气里顿时弥漫开她洗完澡后淡淡的幽香。她完全没有意识到，自己这句看似寻常的承诺，会在这个父亲加班未归的深夜，化作一把开启禁忌之门的钥匙。</p>\n</article>", "branches": [{"tag": "A", "title": "兑现承诺·初次越界", "desc": "指向她家居服领口，提出今晚由她帮自己做全身放松按摩"}, {"tag": "B", "title": "心理施压·步步紧逼", "desc": "假装学习疲惫，靠进她温软的怀里索求拥抱与膝枕"}, {"tag": "C", "title": "深夜长谈·探知底线", "desc": "提起父亲常年冷落，一边试探她的情感缺口一边握住她的手"}]}', '', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0,maximum-scale=1.0,user-scalable=no,viewport-fit=cover">
<title>这个家</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2%sfamily=Ma+Shan+Zheng&family=Long+Cang&family=Noto+Serif+SC:wght@400;600;900&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}
:root{
--c-wall:#3d2419;
--c-wall-deep:#2a1810;
--c-light:#f4d8a8;
--c-light-soft:#f9e8c8;
--c-mom:#c2185b;
--c-mom-soft:#e91e63;
--c-paper:#f5e6c8;
--c-paper-deep:#e8d4a8;
--c-ink:#3d2419;
--c-ink-soft:#5a3a28;
--c-window:#ffd98a;
--ff-hand:''Ma Shan Zheng'',''Long Cang'',cursive;
--ff-hand2:''Long Cang'',cursive;
--ff-body:''Noto Serif SC'',serif;
--shadow-warm:0 4px 20px rgba(244,216,168,.3);
--shadow-deep:0 8px 24px rgba(0,0,0,.4);
}
html,body{
width:100%;
overflow-x:hidden;
font-family:var(--ff-body);
color:var(--c-ink);
font-size:16px;
line-height:1.7;
-webkit-font-smoothing:antialiased;
}
body{
min-height:100vh;
min-height:100dvh;
position:relative;
background-image:url(''https://img.cdn1.vip/i/69f4741756ae5_1777628183.webp'');
background-repeat:repeat;
background-size:auto;
background-attachment:fixed;
background-color:#f5e6c8;
}
body::before{
content:'''';position:fixed;inset:0;pointer-events:none;z-index:1;
background:rgba(255,248,232,.4);
}
body::after{
content:'''';position:fixed;inset:0;pointer-events:none;z-index:2;
background:radial-gradient(ellipse at center,transparent 50%,rgba(194,24,91,.08) 100%);
}
@media (min-width:1024px){body{cursor:url("data:image/svg+xml;utf8,<svg xmlns=''http://www.w3.org/2000/svg'' width=''32'' height=''32'' viewBox=''0 0 32 32''><defs><radialGradient id=''g'' cx=''50%25'' cy=''40%25''><stop offset=''0%25'' stop-color=''%23ffd98a'' stop-opacity=''1''/><stop offset=''100%25'' stop-color=''%23ffd98a'' stop-opacity=''0''/></radialGradient></defs><circle cx=''16'' cy=''14'' r=''14'' fill=''url(%23g)'' opacity=''.6''/><path d=''M12 8 L20 8 L18 14 L14 14 Z'' fill=''%23c2185b''/><rect x=''15'' y=''14'' width=''2'' height=''3'' fill=''%233d2419''/></svg>") 16 16,auto}}
.intro{
position:fixed;inset:0;z-index:9999;
background:#000;
display:flex;align-items:center;justify-content:center;
flex-direction:column;
transition:opacity 1.2s ease,visibility 1.2s ease;
padding:24px;
}
.intro.fade-out{opacity:0;visibility:hidden;pointer-events:none}
.intro-skip{
position:absolute;top:max(16px,env(safe-area-inset-top));right:16px;
min-width:64px;min-height:44px;padding:8px 16px;
background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.2);
color:rgba(255,255,255,.7);font-family:var(--ff-body);font-size:14px;
border-radius:22px;cursor:pointer;
transition:all .3s;letter-spacing:1px;
}
.intro-skip:active,.intro-skip:hover{background:rgba(255,255,255,.15);color:#fff}
.intro-line{
font-family:var(--ff-body);font-size:18px;color:rgba(255,255,255,.85);
text-align:center;letter-spacing:3px;line-height:2;
opacity:0;
}
.intro-line.show{animation:lineFade 2s ease forwards}
.intro-quote{
font-family:var(--ff-hand);font-size:24px;color:var(--c-mom-soft);
text-align:center;letter-spacing:2px;line-height:1.8;
opacity:0;max-width:520px;
text-shadow:0 0 20px rgba(194,24,91,.5);
}
.intro-quote.show{animation:quoteFade 2.5s ease forwards}
.intro-quote::before,.intro-quote::after{
content:''"'';font-size:32px;color:var(--c-mom-soft);opacity:.6;
}
@keyframes lineFade{0%{opacity:0;transform:translateY(10px)}30%{opacity:1;transform:translateY(0)}80%{opacity:1}100%{opacity:0;transform:translateY(-10px)}}
@keyframes quoteFade{0%{opacity:0;transform:scale(.95)}30%{opacity:1;transform:scale(1)}85%{opacity:1}100%{opacity:0}}
.intro-title{
position:absolute;top:38%;left:50%;transform:translateX(-50%);
font-family:var(--ff-hand);font-size:36px;color:var(--c-window);
letter-spacing:6px;opacity:0;
text-shadow:0 0 30px rgba(255,217,138,.6);
white-space:nowrap;
}
.intro-title.show{animation:titleShine 2s ease forwards}
@keyframes titleShine{0%{opacity:0;letter-spacing:20px}100%{opacity:1;letter-spacing:6px}}
.intro-tip{
position:absolute;bottom:14%;left:50%;transform:translateX(-50%);
font-family:var(--ff-body);font-size:13px;color:rgba(244,216,168,.7);
letter-spacing:3px;opacity:0;
}
.intro-tip.show{animation:tipBlink 1.5s ease infinite 1s}
@keyframes tipBlink{0%,100%{opacity:.4}50%{opacity:.9}}
.app{
position:relative;z-index:10;
min-height:100vh;min-height:100dvh;
display:flex;flex-direction:column;
opacity:0;transition:opacity 1s ease;
padding-top:max(16px,env(safe-area-inset-top));
padding-bottom:max(16px,env(safe-area-inset-bottom));
}
.app.show{opacity:1}
.app-header{
flex:0 0 auto;
text-align:center;padding:12px 16px 8px;
position:relative;
}
.app-header h1{
font-family:var(--ff-hand);font-size:24px;color:var(--c-mom);
letter-spacing:5px;font-weight:normal;
text-shadow:0 2px 8px rgba(255,255,255,.6);
}
.app-header .sub{
font-family:var(--ff-body);font-size:12px;color:var(--c-ink-soft);
letter-spacing:2px;margin-top:2px;opacity:.7;
}
.house-view{
flex:0 0 auto;
padding:12px 16px;
position:relative;
display:flex;justify-content:center;
}
.house{
width:100%;max-width:520px;
position:relative;
filter:drop-shadow(0 12px 32px rgba(194,24,91,.25));
}
.house-roof{
height:24px;
background:linear-gradient(180deg,var(--c-mom) 0%,#9a1248 100%);
clip-path:polygon(8% 100%,50% 0,92% 100%);
margin:0 auto;width:90%;
position:relative;z-index:2;
}
.house-grid{
display:grid;
grid-template-columns:1fr 1fr 1fr;
gap:6px;
background:var(--c-wall);
padding:8px;
border-radius:8px;
border:3px solid var(--c-wall-deep);
box-shadow:inset 0 4px 16px rgba(0,0,0,.4),0 8px 24px rgba(61,36,25,.3);
}
.room{
position:relative;
aspect-ratio:1/1.1;
background:linear-gradient(160deg,#3a2418 0%,#2a1810 100%);
border-radius:5px;
overflow:hidden;
cursor:pointer;
transition:all .4s ease;
display:flex;flex-direction:column;align-items:center;justify-content:center;
padding:6px;
border:1px solid rgba(244,216,168,.15);
}
.room::before{
content:'''';position:absolute;inset:0;
background:radial-gradient(ellipse at 50% 35%,rgba(255,217,138,.3) 0%,transparent 70%);
opacity:.5;transition:opacity .4s;
}
.room:active::before,.room:hover::before{opacity:1}
.room:active,.room:hover{
border-color:rgba(255,217,138,.6);
transform:scale(1.04);
z-index:5;
box-shadow:0 0 28px rgba(255,217,138,.4);
}
.room-icon{
width:55%;height:48%;
display:flex;align-items:center;justify-content:center;
position:relative;z-index:2;
opacity:.9;
transition:transform .4s,opacity .4s;
margin-bottom:4px;
}
.room:active .room-icon,.room:hover .room-icon{opacity:1;transform:translateY(-2px)}
.room-icon svg{width:100%;height:100%}
.room-name{
font-family:var(--ff-hand);font-size:16px;
color:var(--c-light-soft);
letter-spacing:1.5px;
text-shadow:0 0 8px rgba(0,0,0,.8);
position:relative;z-index:2;
margin-top:2px;
}
.room-tag{
font-family:var(--ff-body);font-size:10px;
color:rgba(244,216,168,.7);
letter-spacing:.5px;
position:relative;z-index:2;
margin-top:2px;
text-align:center;
line-height:1.3;
}
.room.mom-room::before{background:radial-gradient(ellipse at 50% 35%,rgba(233,30,99,.4) 0%,rgba(255,217,138,.2) 50%,transparent 80%)}
.room.mom-room .room-name{color:#ffc4d8;text-shadow:0 0 10px rgba(194,24,91,.6)}
.room-detail{position:absolute;inset:0;pointer-events:none;z-index:1}
.tv-glow{position:absolute;bottom:25%;left:25%;width:50%;height:30%;background:linear-gradient(180deg,#5a8fbf,#3a6f9f);border-radius:3px;animation:tvFlicker 4s ease-in-out infinite;opacity:.5}
@keyframes tvFlicker{0%,100%{opacity:.4;background:#5a8fbf}25%{opacity:.7;background:#7aafd5}50%{opacity:.5;background:#4a7faf}75%{opacity:.8;background:#8abff5}}
.curtain{position:absolute;top:5%;right:8%;width:30%;height:55%;background:linear-gradient(90deg,rgba(194,24,91,.4) 0%,rgba(194,24,91,.2) 50%,rgba(194,24,91,.4) 100%);transform-origin:top center;animation:curtainSway 5s ease-in-out infinite}
@keyframes curtainSway{0%,100%{transform:skewX(0deg)}50%{transform:skewX(3deg)}}
.lamp-glow{position:absolute;bottom:25%;right:18%;width:35%;height:35%;background:radial-gradient(circle,rgba(255,217,138,.7) 0%,transparent 70%);animation:lampFlicker 3s ease-in-out infinite}
@keyframes lampFlicker{0%,100%{opacity:.7}50%{opacity:1}}
.guide{
flex:1 1 auto;
padding:24px 24px 16px;
display:flex;flex-direction:column;justify-content:center;
text-align:center;
position:relative;
}
.guide-text{
font-family:var(--ff-hand);font-size:20px;
color:var(--c-ink);
line-height:2;letter-spacing:2px;
margin-bottom:18px;
opacity:.85;
text-shadow:0 1px 4px rgba(255,255,255,.5);
}
.guide-text .accent{color:var(--c-mom)}
.guide-arrow{
font-family:var(--ff-body);font-size:13px;
color:var(--c-mom);
letter-spacing:3px;
animation:arrowBlink 2s ease-in-out infinite;
opacity:.8;
}
@keyframes arrowBlink{0%,100%{opacity:.4;transform:translateY(0)}50%{opacity:.9;transform:translateY(2px)}}
.room-page{
position:fixed;inset:0;z-index:100;
background-image:url(''https://img.cdn1.vip/i/69f4741756ae5_1777628183.webp'');
background-repeat:repeat;
background-color:#f5e6c8;
display:flex;flex-direction:column;
transform:translateY(100%);
transition:transform .5s cubic-bezier(.4,0,.2,1);
visibility:hidden;
padding-top:max(0px,env(safe-area-inset-top));
padding-bottom:max(0px,env(safe-area-inset-bottom));
}
.room-page::after{
content:'''';position:absolute;inset:0;pointer-events:none;
background:rgba(255,248,232,.4);
}
.room-page.show{transform:translateY(0);visibility:visible}
.page-header{
flex:0 0 auto;
display:flex;align-items:center;justify-content:space-between;
padding:14px 16px;
background:rgba(255,248,232,.92);
backdrop-filter:blur(12px) saturate(1.2);
-webkit-backdrop-filter:blur(12px) saturate(1.2);
border-bottom:1px solid rgba(194,24,91,.2);
position:sticky;top:0;z-index:10;
}
.btn-back{
min-width:44px;min-height:44px;
display:flex;align-items:center;justify-content:center;
background:rgba(194,24,91,.08);border:1px solid rgba(194,24,91,.25);
border-radius:22px;padding:0 16px;
color:var(--c-mom);font-family:var(--ff-body);font-size:14px;
cursor:pointer;transition:all .3s;letter-spacing:1px;
gap:4px;font-weight:600;
}
.btn-back:active,.btn-back:hover{background:rgba(194,24,91,.18)}
.page-title{
font-family:var(--ff-hand);font-size:20px;
color:var(--c-mom);letter-spacing:3px;
flex:1;text-align:center;
}
.page-title-icon{
width:36px;height:36px;
display:flex;align-items:center;justify-content:center;
opacity:.85;
}
.page-title-icon svg{width:24px;height:24px}
.page-content{
flex:1 1 auto;
overflow-y:auto;
padding:24px 18px 100px;
-webkit-overflow-scrolling:touch;
position:relative;z-index:1;
}
.card{
background:linear-gradient(180deg,#fffaf0 0%,var(--c-paper) 100%);
color:var(--c-ink);
border-radius:8px;
padding:18px 20px;
margin-bottom:18px;
position:relative;
box-shadow:0 6px 18px rgba(194,24,91,.15),inset 0 0 60px rgba(244,216,168,.2);
font-family:var(--ff-body);
border:1px solid rgba(194,24,91,.12);
}
.card::before{
content:'''';position:absolute;inset:0;pointer-events:none;border-radius:8px;
background-image:
radial-gradient(circle at 20% 30%,rgba(139,90,50,.04) 0%,transparent 40%),
radial-gradient(circle at 80% 70%,rgba(139,90,50,.04) 0%,transparent 40%);
}
.card-title{
font-family:var(--ff-hand);font-size:22px;color:var(--c-mom);
margin-bottom:12px;letter-spacing:2px;
border-bottom:1px dashed rgba(194,24,91,.3);
padding-bottom:8px;
display:flex;align-items:center;gap:8px;
}
.card-title-icon{font-size:20px}
.card p{
font-size:15px;line-height:1.9;color:var(--c-ink-soft);
margin-bottom:10px;
text-indent:2em;
}
.card p:last-child{margin-bottom:0}
.card .highlight{color:var(--c-mom);font-weight:600}
.card .quote{
font-family:var(--ff-hand);font-size:17px;color:var(--c-mom);
text-indent:0;text-align:center;
padding:8px 12px;margin:8px 0;
border-left:3px solid var(--c-mom);
background:rgba(194,24,91,.06);
letter-spacing:1px;
}
.mom-portrait{
text-align:center;
padding:32px 0 28px;
position:relative;
border-bottom:1px dashed rgba(194,24,91,.3);
margin-bottom:20px;
}
.mom-portrait::before{
content:''·   ·   ·'';
display:block;
color:var(--c-mom);
font-size:14px;
letter-spacing:6px;
margin-bottom:14px;
opacity:.5;
}
.mom-portrait::after{
content:''·   ·   ·'';
display:block;
color:var(--c-mom);
font-size:14px;
letter-spacing:6px;
margin-top:14px;
opacity:.5;
}
.mom-name{
font-family:var(--ff-hand);font-size:28px;color:var(--c-mom);
letter-spacing:6px;text-shadow:0 2px 8px rgba(255,255,255,.6);
}
.mom-name-sub{
font-family:var(--ff-body);font-size:13px;color:var(--c-ink-soft);
letter-spacing:5px;margin-top:6px;opacity:.8;
}
.diary{
background:linear-gradient(180deg,#fffaf0 0%,var(--c-paper) 100%);
color:var(--c-ink);
border-radius:6px;
margin-bottom:14px;
position:relative;
box-shadow:0 4px 14px rgba(194,24,91,.12);
overflow:hidden;
transition:transform .3s ease;
border:1px solid rgba(194,24,91,.12);
}
.diary::before{
content:'''';position:absolute;left:8px;top:0;bottom:0;width:1px;
background:repeating-linear-gradient(180deg,rgba(194,24,91,.3) 0,rgba(194,24,91,.3) 4px,transparent 4px,transparent 8px);
}
.diary:hover{transform:translateY(-2px)}
.diary-head{
display:flex;align-items:center;gap:10px;
padding:14px 16px 14px 24px;
cursor:pointer;
user-select:none;
position:relative;
}
.diary-emoji{font-size:22px;flex-shrink:0}
.diary-title{
flex:1;
font-family:var(--ff-hand);font-size:18px;color:var(--c-mom);
letter-spacing:2px;
}
.diary-toggle{
width:24px;height:24px;
display:flex;align-items:center;justify-content:center;
color:var(--c-mom);font-size:18px;
transition:transform .3s;
}
.diary.open .diary-toggle{transform:rotate(180deg)}
.diary-body{
max-height:0;overflow:hidden;
transition:max-height .5s ease;
}
.diary.open .diary-body{max-height:1500px}
.diary-content{
padding:0 18px 18px 24px;
border-top:1px dashed rgba(194,24,91,.2);
padding-top:12px;
}
.diary-content p{
font-size:14.5px;line-height:1.95;color:var(--c-ink-soft);
margin-bottom:8px;text-indent:2em;
}
.diary-content .label{
display:inline-block;
font-family:var(--ff-hand);font-size:15px;color:var(--c-mom);
margin-right:6px;font-weight:bold;
}
.diary-content ul{list-style:none;padding:0;margin:6px 0}
.diary-content li{
font-size:14px;line-height:1.85;color:var(--c-ink-soft);
padding:3px 0 3px 18px;position:relative;
}
.diary-content li::before{
content:''·'';position:absolute;left:6px;top:0;
color:var(--c-mom);font-weight:bold;font-size:18px;
}
.form-paper{
background:
repeating-linear-gradient(180deg,transparent 0,transparent 28px,rgba(194,24,91,.08) 28px,rgba(194,24,91,.08) 29px),
linear-gradient(180deg,#fffaf0 0%,var(--c-paper) 100%);
color:var(--c-ink);
border-radius:8px;
padding:24px 20px;
margin-bottom:18px;
box-shadow:0 6px 20px rgba(194,24,91,.15);
position:relative;
border:1px solid rgba(194,24,91,.12);
}
.form-paper::before{
content:'''';position:absolute;left:36px;top:0;bottom:0;width:1px;
background:rgba(194,24,91,.25);
}
.form-paper-title{
font-family:var(--ff-hand);font-size:24px;color:var(--c-mom);
text-align:center;letter-spacing:4px;margin-bottom:8px;
}
.form-paper-sub{
font-family:var(--ff-body);font-size:12px;color:var(--c-ink-soft);
text-align:center;letter-spacing:2px;opacity:.7;margin-bottom:24px;
border-bottom:1px dashed rgba(194,24,91,.3);padding-bottom:12px;
}
.field{margin-bottom:20px;position:relative}
.field-label{
display:block;
font-family:var(--ff-hand);font-size:16px;color:var(--c-mom);
margin-bottom:8px;letter-spacing:1px;
}
.field-label .num{
display:inline-block;width:22px;height:22px;
background:var(--c-mom);color:#fff;border-radius:50%;
text-align:center;line-height:22px;font-size:13px;
margin-right:6px;font-family:var(--ff-body);
}
.field-label .opt{
font-size:12px;color:var(--c-ink-soft);
font-family:var(--ff-body);font-weight:normal;
margin-left:6px;opacity:.7;
}
.field input[type="text"],.field input[type="number"],.field textarea{
width:100%;
min-height:48px;
padding:12px 14px;
font-family:var(--ff-body);font-size:16px;
color:var(--c-ink);
background:rgba(255,255,255,.5);
border:1px solid rgba(194,24,91,.25);
border-radius:6px;
transition:all .3s;
-webkit-appearance:none;
}
.field textarea{
min-height:80px;
resize:vertical;
line-height:1.7;
}
.field input:focus,.field textarea:focus{
outline:none;
border-color:var(--c-mom);
background:#fff;
box-shadow:0 0 0 3px rgba(194,24,91,.15);
}
.field input::placeholder,.field textarea::placeholder{
color:rgba(93,58,40,.4);
font-style:italic;
}
.radio-group{
display:grid;
grid-template-columns:repeat(auto-fit,minmax(80px,1fr));
gap:8px;
}
.radio-btn{position:relative}
.radio-btn input{position:absolute;opacity:0;pointer-events:none}
.radio-btn label{
display:flex;align-items:center;justify-content:center;
min-height:48px;padding:8px 14px;
background:rgba(255,255,255,.5);
border:1.5px solid rgba(194,24,91,.25);
border-radius:6px;
font-family:var(--ff-body);font-size:15px;color:var(--c-ink);
cursor:pointer;transition:all .25s;
text-align:center;
}
.radio-btn input:checked+label{
background:var(--c-mom);color:#fff;
border-color:var(--c-mom);
box-shadow:0 4px 12px rgba(194,24,91,.35);
transform:translateY(-1px);
}
.radio-btn label:active{transform:scale(.97)}
.custom-call{margin-top:8px;display:none}
.custom-call.show{display:block;animation:fieldFade .3s ease}
@keyframes fieldFade{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:translateY(0)}}
.preview-wrap{margin-top:24px}
.preview-label{
font-family:var(--ff-hand);font-size:18px;color:var(--c-mom);
letter-spacing:2px;margin-bottom:10px;
display:flex;align-items:center;gap:8px;
}
.preview-box{
background:linear-gradient(180deg,#fff8e8 0%,#f5e6c8 100%);
border:1px solid rgba(194,24,91,.2);
border-radius:6px;
padding:18px 20px;
font-family:var(--ff-body);font-size:14.5px;
line-height:1.95;color:var(--c-ink);
min-height:120px;
white-space:pre-wrap;
word-wrap:break-word;
position:relative;
box-shadow:inset 0 0 20px rgba(244,216,168,.4),0 4px 12px rgba(194,24,91,.1);
}
.preview-box::before{
content:'''';position:absolute;top:-6px;left:30px;width:60px;height:14px;
background:rgba(194,24,91,.4);
transform:rotate(-3deg);
border-radius:2px;
opacity:.6;
}
.preview-empty{color:rgba(93,58,40,.4);font-style:italic}
.btn-copy{
margin-top:16px;width:100%;
min-height:54px;
background:linear-gradient(180deg,var(--c-mom-soft) 0%,var(--c-mom) 100%);
color:#fff;border:none;border-radius:8px;
font-family:var(--ff-hand);font-size:20px;letter-spacing:4px;
cursor:pointer;
box-shadow:0 6px 18px rgba(194,24,91,.4);
transition:all .25s;
display:flex;align-items:center;justify-content:center;gap:8px;
}
.btn-copy:active{transform:translateY(1px);box-shadow:0 3px 10px rgba(194,24,91,.4)}
.btn-copy:hover{box-shadow:0 8px 22px rgba(194,24,91,.5)}
.btn-start{
margin-top:20px;width:100%;
min-height:60px;
background:linear-gradient(180deg,#fff 0%,#fff5ed 100%);
color:var(--c-mom);border:2px solid var(--c-mom);border-radius:8px;
font-family:var(--ff-hand);font-size:22px;letter-spacing:6px;
cursor:pointer;
box-shadow:0 6px 18px rgba(194,24,91,.2);
transition:all .25s;
display:flex;align-items:center;justify-content:center;gap:8px;
position:relative;
}
.btn-start::before{
content:'''';position:absolute;inset:-4px;
border:1px solid rgba(233,30,99,.4);border-radius:10px;
animation:startPulse 2s ease-in-out infinite;
pointer-events:none;
}
@keyframes startPulse{0%,100%{transform:scale(1);opacity:.6}50%{transform:scale(1.02);opacity:.2}}
.btn-start:active{transform:translateY(2px);background:var(--c-mom);color:#fff}
.start-hint{
font-family:var(--ff-body);font-size:12px;
color:var(--c-ink-soft);
letter-spacing:1px;margin-top:14px;line-height:1.8;
text-align:center;opacity:.75;
}
.tip-list{margin:8px 0}
.tip-item{
display:flex;gap:12px;
padding:10px 0;
border-bottom:1px dashed rgba(194,24,91,.15);
}
.tip-item:last-child{border-bottom:none}
.tip-icon{
flex:0 0 32px;height:32px;
display:flex;align-items:center;justify-content:center;
font-size:20px;
}
.tip-text{flex:1;font-size:14px;line-height:1.7;color:var(--c-ink-soft)}
.tip-text strong{color:var(--c-mom);font-weight:600}
.tag-row{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}
.tag{
display:inline-block;
padding:4px 12px;
background:rgba(194,24,91,.1);
border:1px solid rgba(194,24,91,.25);
border-radius:14px;
font-family:var(--ff-body);font-size:12.5px;color:var(--c-mom);
letter-spacing:.5px;
}
.boundary-list{margin:8px 0;padding:0;list-style:none}
.boundary-list li{
padding:8px 12px 8px 32px;
margin-bottom:6px;
position:relative;
font-size:14px;line-height:1.7;color:var(--c-ink-soft);
background:rgba(244,216,168,.4);
border-radius:6px;
border-left:3px solid var(--c-mom);
}
.boundary-list li::before{
content:''✓'';position:absolute;left:10px;top:8px;
color:var(--c-mom);font-weight:bold;font-size:14px;
}
.boundary-list li.no{border-left-color:#8b3a3a;background:rgba(139,58,58,.08)}
.boundary-list li.no::before{content:''✗'';color:#8b3a3a}
.room-nav{
position:fixed;bottom:0;left:0;right:0;z-index:20;
background:rgba(255,248,232,.95);
backdrop-filter:blur(12px);
-webkit-backdrop-filter:blur(12px);
border-top:1px solid rgba(194,24,91,.2);
padding:8px 4px max(8px,env(safe-area-inset-bottom));
display:none;
overflow-x:auto;
-webkit-overflow-scrolling:touch;
scrollbar-width:none;
justify-content:center;
}
.room-page.show ~ .room-nav,.room-nav.show{display:flex}
.room-nav::-webkit-scrollbar{display:none}
.nav-item{
flex:0 0 auto;min-width:80px;
padding:8px 6px;
display:flex;flex-direction:column;align-items:center;gap:2px;
background:none;border:none;
color:var(--c-ink-soft);
font-family:var(--ff-body);font-size:11px;letter-spacing:1px;
cursor:pointer;transition:all .2s;
border-radius:6px;
opacity:.6;
}
.nav-item svg{width:22px;height:22px;opacity:.7}
.nav-item.active{color:var(--c-mom);opacity:1}
.nav-item.active svg{opacity:1}
.nav-item:active{background:rgba(194,24,91,.1)}
.modal-mask{
position:fixed;inset:0;z-index:9000;
background:rgba(61,36,25,.65);
backdrop-filter:blur(6px);
display:flex;align-items:center;justify-content:center;
opacity:0;visibility:hidden;
transition:all .3s;
padding:24px;
}
.modal-mask.show{opacity:1;visibility:visible}
.modal{
background:linear-gradient(180deg,#fffaf0 0%,var(--c-paper) 100%);
color:var(--c-ink);
border-radius:12px;
padding:32px 28px;max-width:340px;width:100%;
text-align:center;
box-shadow:0 20px 60px rgba(0,0,0,.4);
transform:scale(.9);transition:transform .3s;
position:relative;
border:1px solid rgba(194,24,91,.2);
}
.modal-mask.show .modal{transform:scale(1)}
.modal::before{
content:'''';position:absolute;inset:8px;border:1px dashed rgba(194,24,91,.3);
border-radius:8px;pointer-events:none;
}
.modal-icon{font-size:40px;margin-bottom:12px}
.modal-title{
font-family:var(--ff-hand);font-size:24px;color:var(--c-mom);
letter-spacing:3px;margin-bottom:8px;
}
.modal-msg{
font-family:var(--ff-body);font-size:14px;color:var(--c-ink-soft);
line-height:1.8;margin-bottom:20px;
}
.modal-btn{
min-width:120px;min-height:44px;padding:10px 24px;
background:var(--c-mom);color:#fff;border:none;border-radius:22px;
font-family:var(--ff-body);font-size:15px;letter-spacing:2px;
cursor:pointer;transition:all .2s;
}
.modal-btn:active{transform:scale(.95)}
.modal-btn:hover{background:var(--c-mom-soft)}
footer{
position:relative;z-index:10;
text-align:center;
padding:20px 16px max(20px,env(safe-area-inset-bottom));
font-family:var(--ff-body);font-size:11px;
letter-spacing:1px;
}
footer a{
color:var(--c-ink-soft);
text-decoration:none;
transition:color .3s;
border-bottom:1px dotted rgba(93,58,40,.3);
padding-bottom:2px;
opacity:.7;
}
footer a:hover{color:var(--c-mom);opacity:1}
@media (min-width:768px){
.app-header h1{font-size:32px;letter-spacing:8px}
.app-header .sub{font-size:14px}
.house{max-width:640px}
.guide-text{font-size:24px}
.intro-line{font-size:24px}
.intro-quote{font-size:32px;max-width:680px}
.intro-title{font-size:48px}
.page-content{padding:32px 32px 120px;max-width:760px;margin:0 auto;width:100%}
.page-title{font-size:24px}
.card{padding:24px 28px}
.card-title{font-size:26px}
.card p{font-size:16px}
.diary-title{font-size:20px}
.form-paper{padding:32px 36px}
.form-paper-title{font-size:30px}
.field-label{font-size:18px}
.preview-box{font-size:15.5px;padding:24px}
.btn-start{font-size:26px;padding:22px 48px}
.mom-name{font-size:34px}
.room-name{font-size:18px}
.room-tag{font-size:11px}
}
@media (min-width:1024px){
.house{max-width:720px}
.room-nav{padding:10px 12px max(10px,env(safe-area-inset-bottom))}
.nav-item{min-width:100px;font-size:12px}
.nav-item svg{width:24px;height:24px}
.page-content{max-width:860px}
}
@supports (-webkit-touch-callout:none){
input,textarea,select{font-size:16px !important}
}
</style>
</head>
<body>
<div class="intro" id="intro">
<button class="intro-skip" id="skipIntro">跳过 →</button>
<div class="intro-line" id="introLine1">这个家很普通...直到三个月前，妈妈说了一句话。</div>
<div class="intro-quote" id="introLine2">只要你考得好，妈妈可以满足你一个不花钱的要求。</div>
<div class="intro-title" id="introTitle">温柔的妈妈</div>
<div class="intro-tip" id="introTip">点击任意房间进入</div>
</div>
<div class="app" id="app">
<header class="app-header">
<h1>温柔的妈妈</h1>
<div class="sub">A HOUSE WITH SECRETS</div>
</header>
<div class="house-view">
<div class="house">
<div class="house-roof"></div>
<div class="house-grid">
<div class="room" data-room="livingroom">
<div class="room-detail"><div class="tv-glow"></div></div>
<div class="room-icon">
<svg viewBox="0 0 64 64" fill="none" stroke="#f4d8a8" stroke-width="2"><rect x="8" y="36" width="22" height="14" rx="2"/><rect x="34" y="20" width="22" height="16" rx="1"/><line x1="14" y1="50" x2="14" y2="56"/><line x1="24" y1="50" x2="24" y2="56"/></svg>
</div>
<div class="room-name">客厅</div>
<div class="room-tag">玩法 · 故事</div>
</div>
<div class="room mom-room" data-room="bedroom">
<div class="room-detail"><div class="curtain"></div></div>
<div class="room-icon">
<svg viewBox="0 0 64 64" fill="none" stroke="#f4d8a8" stroke-width="2"><rect x="8" y="32" width="48" height="20" rx="2"/><rect x="6" y="42" width="52" height="10" rx="1"/><rect x="14" y="26" width="14" height="10" rx="2"/><rect x="36" y="26" width="14" height="10" rx="2"/></svg>
</div>
<div class="room-name">主卧</div>
<div class="room-tag">妈妈在这里</div>
</div>
<div class="room" data-room="myroom">
<div class="room-detail"><div class="lamp-glow"></div></div>
<div class="room-icon">
<svg viewBox="0 0 64 64" fill="none" stroke="#f4d8a8" stroke-width="2"><rect x="10" y="32" width="44" height="20"/><line x1="14" y1="32" x2="14" y2="20" stroke-linecap="round"/><circle cx="14" cy="18" r="3" fill="#ffd98a" stroke="none"/><rect x="22" y="36" width="14" height="10"/><line x1="40" y1="36" x2="50" y2="36" stroke-linecap="round"/><line x1="40" y1="40" x2="50" y2="40" stroke-linecap="round"/></svg>
</div>
<div class="room-name">我的房间</div>
<div class="room-tag">填写 · 开始</div>
</div>
</div>
</div>
</div>
<div class="guide">
<div class="guide-arrow">↑ 点击任意房间进入 ↑</div>
</div>
</div>
<div class="room-page" id="page-livingroom">
<div class="page-header">
<button class="btn-back" data-action="back">← 返回</button>
<div class="page-title">客厅</div>
<div class="page-title-icon">
<svg viewBox="0 0 24 24" fill="none" stroke="#c2185b" stroke-width="1.5"><rect x="3" y="14" width="9" height="6"/><rect x="14" y="8" width="7" height="6"/></svg>
</div>
</div>
<div class="page-content">
<div class="card">
<div class="card-title"><span class="card-title-icon">🏠</span>这个家</div>
<p>一座老旧两居室，墙皮微微泛黄，旧布艺沙发上盖着妈妈手织的毛线毯——那是用来遮住磨损处的。</p>
<p>我们家普通得不能再普通：<span class="highlight">爸爸</span>是个老实本分的工人，每天早出晚归，工资勉强够交房贷和我的补习费。<span class="highlight">妈妈</span>叫林雨晴，37岁，全职主妇——她以前是公司文员，我上小学那年为了陪我，辞职了。</p>
<p>家里的电视是20寸老款，茶几上常年放着妈妈织到一半的毛衣。她的旧手机摔坏了，用胶带粘着还在用。她总说"等我考上好大学，一切就都好了"。</p>
<div class="quote">"家里条件不好，妈妈只能给你这些..."</div>
</div>
<div class="card">
<div class="card-title"><span class="card-title-icon">📅</span>三个月前的那句话</div>
<p>那是我高三开学的第一天。妈妈端着切好的水果坐到我书桌边，眼神温柔又期待。</p>
<div class="quote">"儿子，只要你考得好，妈妈可以满足你一个不花钱的要求。"</div>
<p>她以为我会要求"陪陪我""帮我按摩"——她完全没想到，这个承诺会把我们引向何处。</p>
<p>而现在，是月考成绩公布后的第一个夜晚。<span class="highlight">爸爸不在家。</span></p>
</div>
<div class="card">
<div class="card-title"><span class="card-title-icon">👔</span>关于爸爸</div>
<p>爸爸40岁，普通工人，沉默寡言，有点大男子主义。他爱这个家，但不擅长表达。</p>
<p>工作日早7点出门，晚上7-8点才到家，常加班到9点。每月会出差一两次，每次2-4天。</p>
<div class="tag-row">
<span class="tag">老实本分</span>
<span class="tag">话少</span>
<span class="tag">常加班</span>
<span class="tag">月出差1-2次</span>
</div>
</div>
<div class="card">
<div class="card-title"><span class="card-title-icon">🎮</span>这是一个什么样的故事？</div>
<p>这是一个完全沉浸的现代家庭叙事体验。你扮演高三的{user}，与你的妈妈林雨晴以及偶尔出现的爸爸展开一段被禁忌包裹的日常。</p>
<p>你的输入决定一切。每一句话、每一个选择，都会让妈妈的反应发生微妙的变化。她会害羞、会推开你，也可能...在某个时刻悄悄妥协。</p>
</div>
<div class="card">
<div class="card-title"><span class="card-title-icon">⏰</span>玩法节奏</div>
<div class="tip-list">
<div class="tip-item"><div class="tip-icon">📅</div><div class="tip-text">每月一次<strong>月考</strong>，决定本月可兑换的奖励范围。</div></div>
<div class="tip-item"><div class="tip-icon">🌙</div><div class="tip-text">爸爸的<strong>作息与出差</strong>影响家中是否安全——他随时可能回来。</div></div>
<div class="tip-item"><div class="tip-icon">⚡</div><div class="tip-text">输入"<strong>跳到晚上</strong>""<strong>跳到下次月考</strong>"等指令可以快速推进时间。</div></div>
<div class="tip-item"><div class="tip-icon">📚</div><div class="tip-text">学习行为会让妈妈欣慰，也会真的让你成绩进步。</div></div>
</div>
</div>
<div class="card">
