if(!pages[name])return;
if(currentRoom&&currentRoom!==name){
pages[currentRoom].classList.remove(''show'');
}
pages[name].classList.add(''show'');
pages[name].querySelector(''.page-content'').scrollTop=0;
currentRoom=name;
document.body.style.overflow=''hidden'';
}
function closeRoom(){
if(!currentRoom)return;
pages[currentRoom].classList.remove(''show'');
currentRoom=null;
document.body.style.overflow='''';
}
document.querySelectorAll(''.room[data-room]'').forEach(r=>{
r.addEventListener(''click'',()=>openRoom(r.dataset.room));
});
document.querySelectorAll(''[data-action="back"]'').forEach(b=>{
b.addEventListener(''click'',closeRoom);
});
document.querySelectorAll(''[data-diary]'').forEach(d=>{
const head=d.querySelector(''.diary-head'');
