ta.style.left=''-9999px'';
ta.style.top=''0'';
ta.setAttribute(''readonly'','''');
document.body.appendChild(ta);
ta.select();
ta.setSelectionRange(0,99999);
let ok=false;
try{ok=document.execCommand(''copy'')}catch(e){ok=false}
document.body.removeChild(ta);
if(ok){
modalMask.classList.add(''show'');
}else{
alert(''复制失败，请手动选择预览框文字复制～'');
}
});
modalBtn.addEventListener(''click'',()=>{
modalMask.classList.remove(''show'');
});
modalMask.addEventListener(''click'',e=>{
if(e.target===modalMask)modalMask.classList.remove(''show'');
});
document.getElementById(''btnStart'').addEventListener(''click'',()=>{
const text=previewBox.textContent;
if(!text||text.indexOf(''填写上方'')>-1){
alert(''请先填写并复制档案，再开始故事～'');
return;
}
const ta=document.createElement(''textarea'');
ta.value=text;
ta.style.position=''fixed'';
ta.style.left=''-9999px'';
ta.style.top=''0'';
ta.setAttribute(''readonly'','''');
document.body.appendChild(ta);
ta.select();
ta.setSelectionRange(0,99999);
let ok=false;
try{ok=document.execCommand(''copy'')}catch(e){ok=false}
document.body.removeChild(ta);
if(ok){
modalMask.classList.add(''show'');
}
});
document.addEventListener(''keydown'',e=>{
if(e.key===''Escape''){
if(modalMask.classList.contains(''show'')){modalMask.classList.remove(''show'')}
else if(currentRoom){closeRoom()}
}
});
document.addEventListener(''touchmove'',e=>{
if(e.touches.length>1)e.preventDefault();
},{passive:false});
let lastTouch=0;
document.addEventListener(''touchend'',e=>{
const now=Date.now();
if(now-lastTouch<=300)e.preventDefault();
lastTouch=now;
},{passive:false});
})();
</script>
</body>
</html>', '家庭情感', '2026-10-07 19:36:39', '2026-10-07 19:36:39', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('eb144786-e215-4166-9fcd-ad9d57f2be3f', '型月大世界💕超自由🎲Roll天赋|深度还原', '平平触摸银河 · 男性向', '📖', '型月大世界💕超自由🎲Roll天赋|深度还原', '欢迎加群：317800217
---
2026.9.24更新：重新修订了全新的英灵图鉴同步更新至日版最新482号代达罗斯 角色多模态重新扫描全灵基姿态，重新核对', '📖', '#ec4899', 'linear-gradient(135deg, #ec4899 0%, #f97316 100%)', '{"title": "型月大世界💕超自由🎲Roll天赋|深度还原", "desc": "欢迎加群：317800217\n---\n2026.9.24更新：重新修订了全新的英灵图鉴同步更新至日版最新482号代达罗斯 角色多模态重新扫描全灵基姿态，重新核对了wiki的能力参数，完全重置触发词，可使用NO.XXX直接触发非同位异构体版本，存在同位异构体的英灵将需要本名+职介+特殊词条，比如阿尔托莉雅+saber+Alter都出现才能精准召唤。降低错误召唤概率，版本介绍将会把是所有的触发词都写上", "bg_image": "https://catai.wiki/dca2b2fc-5abf-4417-eb6a-b7933d5b5000/bg"}', '[]', '[]', '{}', '[{"isUser": false, "story": "【序章 · 初临】\n\n欢迎加群：317800217\n---\n2026.9.24更新：重新修订了全新的英灵图鉴同步更新至日版最新482号代达罗斯 角色多模态重新扫描全灵基姿态，重新核对了wiki的能力参数，完全重置触发词，可使用NO.XXX直接触发非同位异构体版本，存在同位异构体的英灵将需要本名+职介+特殊词条，比如阿尔托莉雅+saber+Alter都出现才能精准召唤。降低错误召唤概率，版本介绍将会把是所有的触发词都写上，有需要请自己挨个查询，如果遇上无法触发的，请查询FGOWIKI名称，或者加群有完整的触发名单，字太多了这里写不下\n---\n更新日志：2026.9.13：2026/9/13：\n修复提示词冲突部分bug一共改了13处：\n演化奇点统一满7条合成1条，相关按钮和输出模板也一起对齐\n“记忆区异常”按钮改成“重新审视星记忆回廊规则，此模块重新生成”，修复时不再要求把核心记忆清空。\n世界线已经发生的变化和后续影响优先于原著，FGO也一样，不再硬拉回原著。人物设定可以跟着合理变化，但只改真正受到影响的部分。\n魔术师创世时，性格扩写只结合准则，不再把起源混进去，避免还没觉醒的起源提前影响性格。\n跳过几天或一段时间时，其他阵营也要按自己的情况行动，不会只有玩家的时间在走。\n遇到超出角色认知的信息时，信息迷雾的处理优先于防抢话；除此之外，还是由玩家自己决定怎么说、怎么做。\n创世时先看角色的身份、背景和经历，再给合适的知识等级，信息迷雾沿用这个结果，不再一律锁成LV 1。\n里程碑单独结算，放在正文后面，可以正常总结和鼓励，不再被正文结尾的限制拦住。\n输出模板给世界线分歧协议和FGO世界线协议留出例外，允许它们参考预训练内容，但不能覆盖已经确认的事实。\n英灵面板和NPC面板的实力示例，统一换成总提示词里的八阶划分，避免一处一套标准。\n自定义设定先检查是否合法，通过后再接受并调整原著差异，不能用“绝对适用”跳过检查。\n删掉创世阶段只输出思考、其他模块都不生成的要求，恢复正常的模块显示。\n极限压力转化协议的编号和相关引用统一，避免调用时指错条目。\n剧情方面更新，补上并精修了三个FGO番外：地狱界曼荼罗 平安京 轰雷一闪、死想显现界域 Traum 某个幻想的生与死、非灵长生存圈 通古斯卡·圣域。\n二世大冒险单开五个篇章，加入吞食神的男人、彷徨海的魔人、炼金术师的遗产、费姆的船宴、星冠密议五篇，按提供的小说整理了总览和分段剧情。《星冠密议》目前写到第11卷，没有擅自补结局。\n三个FGO番外各补了1个魔术师切入点和1个英灵切入点，共6个；二世大冒险五篇各补了1个魔术师切入点，共5个，这次合计新增11个切入点。\n对白显示也一起调整了：角色说话统一用<say>标签，单独成行，NPC用冷蓝色，玩家角色用暖金色，动作和叙述另起段落。相关提示词、模板和样式都已对齐，文件和入口也做了自检。\n---\n更新日志：8.16更新奏章IV 人类裁决法庭 三位一体·梅塔特洛努斯\n---\n更新日志：5.12更新Fate/EXTRA CCC英灵和御主切入点/更新Fate/hollow ataraxia REMASTERED英灵和御主切入点/更新100+天赋池，订正部分天赋谬误，时钟塔十二科补全。\n---\n更新日志： 3.17FSF已经更新至最新的第九卷内容施工结束|3.13更新两个FSF的切入点，内容较多还在完善中|3.5更新了部分FSF的内容，切入点的相关设定已经完善，但是剧情还没做好，所以没有开放出完整的切入点，可以通过【Fate/strange Fake】作为触发词书写自定义切入点进行游玩|2.24更新FGO/魔法使之夜联动 新增切入点|2.2更新部分触发bug和品论区反馈问题更新HF线御主切入点和英灵切入点|1.18终章内容更新，更新两个切入点。包括我自己续写的结局，为FGO画上一个圆满的句号，修复部分bug|1/3更新英灵图鉴补全所有内容更新部分FGO设定，修复部分反馈bug|12/15更新英灵图鉴补全100-200部分，但是需要重新订阅|12/08更新埃尔梅罗二世的阿特拉斯契约/冠位决议内容|11/24号更新总计更新12个英灵切入点和10个魔术师/御主切入点Fate/EXTRA&Fate/EXTRA Last Encore，更新FGO奏章1-3，虚数罗针盘/不可逆废弃孔/新灵长后继战，更新FGO1.5亚种特异点恶性隔绝魔境 新宿/传承地底世界 雅戈泰/尸山血河舞台 下总国/禁忌降临庭园 塞勒姆。修复Fate/Prototype 苍银的碎片/Fate/Prototype的英灵切入点。修复若干评论区bug|11/13更新了201-300编号英灵，泳装圣诞等英灵需要名字需要正确出现才能生效，泳装需要带泳装字样名字上加上对应的状态才能准确召唤，避免的了一个名字触发多个世界书|11/9修复记忆区格式错乱及稳定记忆区，修复存档转移时出现时间线错乱的现象，英灵图鉴新增401-451位的英灵数据，移除卫宫饭等内容已出新卡型月小世界囊括|11/3更新英灵图鉴，作为mod加载No.01-100位英灵数据，其余角色待更新 | 10/29更新埃尔梅罗二世事件簿1-5卷内容剥离城阿德拉/双貌塔伊泽尔玛/魔眼搜集列车|10/28修复了若干UI格式错乱问题，强化格式输出稳定性，新增两个英灵切入点10/25在粉丝的帮助下重写的魔法使之夜的剧情，修复若干评论区bug 10/19更新魔法少女伊莉雅第一季-第四季内容+剧场版雪下誓言内容，更新苍银碎片（fate原典第一和第二次东京圣杯战争）修复若干评论区问题|10/15修复了记忆区容易掉的问题，修改思维链，移除部分内容至mod区降耗|10/12更新了FA剧情和多项bug，新增英灵切入点和大量英灵导入改动|10/10 目前修复优化了破甲和世界书触发，降低了一部分消耗，总体的降消耗正在持续进行 |10/8 已重置目前所有故事线内容，修复了大量评论bug，有问题请评论区积极反馈|目前已更新月姬/FZ/FSN/空之境界/魔法使之夜/FGO第一部七个特异点/第二部七个异闻带内容，后续更新包括所有型月世界观下的世界内容。记忆4游玩，建议先用Pro对话两次后切换flash游玩|\n---\n欢迎来到一个世界线为你而生的型月。在这里，你的每一个选择，都将是撼动世界的奇点。没有固定的剧本，没有降智的NPC，但是有降智的哈基米——她们是拥有独立灵魂、会因你的行为而爱、恨、背叛或追随的真实存在。\n---\n魔力的奔流，不仅是战斗的序曲，更是灵魂交融的**禁忌仪式**。与骄傲的魔术师、圣洁的代行者、或是来自神代的英灵，缔结超越生死的契约……或是在她们因你而起的沉沦与献身中，窥见“根源”最真实的倒影。\n你的传说，将由你自己——以及为你倾倒的她们，共同书写。\n---\n可以深度领略型月世界观下的各个角色，可以是瑟瑟也可以是弥补遗憾，全看玩家一念之间。内置特殊【升座系统】可以从魔术师升华成英灵，当玩家的过往经历月丰富，生成的英灵越强大。成为英灵后可以穿梭于各个Fate系列的时间线上，游玩所有型月的内容\n埃尔梅罗二世事件簿/Fate stay night（FSN）第五次圣杯战争/Fate zero（FZ）第四次圣杯战争/月姬/空之境界/魔法使之夜/Fate Grand Order(FGO)/Fate/strange fake（FSF）/FatePrototype 苍银的碎片/卫宫家今天的饭/魔法少女伊莉雅/月之圣杯战争/亚种特异点/活动特异点/FateApocrypha(FA）\n\n阳光穿透微隙，周围的喧嚣渐渐清晰。你迈出脚步，开启了在这片天地间的全新篇章……", "branches": [{"tag": "A", "title": "环顾四周观察当前局势", "desc": "环顾四周观察当前局势"}, {"tag": "B", "title": "顺应眼前的指引前行", "desc": "顺应眼前的指引前行"}]}]', '.style-module__AtdJSq__dot-flashing {
  display: none !important;
}

