  transition: all 0.3s ease-in-out !important;
}
/* [新增] 主容器的鼠标悬停效果 */
div.relative.inline-block.bg-gray-100\/90:hover {
  /* 向上轻微浮动 */
  transform: translateY(-5px) !important;
  /* 阴影加深，更有层次感 */
  box-shadow: 0 12px 35px rgba(0, 0, 0, 0.7), inset 0 1px 0 rgba(0, 212, 255, 0.2) !important;
  /* 边框变亮，增加反馈 */
  border-color: rgba(0, 212, 255, 0.6) !important;
}
/* 顶部装饰线 */
div.relative.inline-block.bg-gray-100\/90 > .MuiBox-root.css-0 {
