(function(){const e=document.getElementById("particles-canvas");if(e&&e.getContext){const t=e.getContext("2d");function n(){e.width=innerWidth,e.height=innerHeight}n(),window.addEventListener("resize",n);const o={x:null,y:null};window.addEventListener("mousemove",e=>{o.x=e.x,o.y=e.y});class a{constructor(e,t,n,o,l,d){Object.assign(this,{x:e,y:t,dx:n,dy:o,size:l,color:d})}draw(){t.beginPath(),t.arc(this.x,this.y,this.size,0,2*Math.PI),t.fillStyle=this.color,t.fill()}update(){this.x>e.width||this.x<0%sthis.dx=-this.dx:void 0,this.y>e.height||this.y<0%sthis.dy=-this.dy:void 0;const n=o.x-this.x,a=o.y-this.y;Math.sqrt(n*n+a*a)<150%s(this.x+=.5*this.dx,this.y+=.5*this.dy):(this.x+=this.dx,this.y+=this.dy),this.draw()}}let l=[];function d(){l=[];const t=(e.height*e.width)/9e3;for(let e=0;e<t;e++){const t=2*Math.random()+.5,n=Math.random()*(innerWidth-2*t-2*t)+2*t,o=Math.random()*(innerHeight-2*t-2*t)+2*t,c=.4*Math.random()-.2,r=.4*Math.random()-.2;l.push(new a(n,o,c,r,t,"rgba(168,178,209,.5)"))}}function c(){requestAnimationFrame(c),t.clearRect(0,0,innerWidth,innerHeight);const n=t.createLinearGradient(0,0,e.width,e.height);n.addColorStop(0,"#0a192f"),n.addColorStop(1,"#132f4c"),t.fillStyle=n,t.fillRect(0,0,e.width,e.height),l.forEach(e=>e.update())}d(),c(),window.addEventListener("resize",d)}})();
(function(){
    const mainNav = document.getElementById(''horizontal-nav'');
    if(mainNav){
        const navBtns = mainNav.querySelectorAll(''.nav-btn'');
        navBtns.forEach(btn => {
            btn.addEventListener(''click'', () => {
                mainNav.querySelector(''.nav-btn.active'')%s.classList.remove(''active'');
                document.querySelector(''.tm-section.active'')%s.classList.remove(''active'');
                btn.classList.add(''active'');
                const targetId = btn.getAttribute(''data-target'');
                const targetSection = document.getElementById(targetId);
                if (targetSection) targetSection.classList.add(''active'');
            });
        });
        let isDown = false;
        let startX;
        let scrollLeft;
        mainNav.addEventListener(''mousedown'', (e) => {
            isDown = true;
            mainNav.classList.add(''active-drag'');
            startX = e.pageX - mainNav.offsetLeft;
            scrollLeft = mainNav.scrollLeft;
        });
        [''mouseleave'', ''mouseup''].forEach(event => mainNav.addEventListener(event, () => {
            isDown = false;
            mainNav.classList.remove(''active-drag'');
        }));
        mainNav.addEventListener(''mousemove'', (e) => {
            if (!isDown) return;
            e.preventDefault();
            const x = e.pageX - mainNav.offsetLeft;
            const walk = (x - startX) * 2;
            mainNav.scrollLeft = scrollLeft - walk;
        });
    }
    document.querySelectorAll(".accordion-trigger").forEach(trigger => {
        trigger.addEventListener("click", () => {
            const item = trigger.parentElement;
            item.classList.toggle("active");
            const content = trigger.nextElementSibling;
            content.style.maxHeight = item.classList.contains("active") %s content.scrollHeight + "px" : null;
        });
    });
    const charGrid = document.getElementById(''char-grid'');
    const modal = document.getElementById(''char-modal'');
    const modalTitle = document.getElementById(''modal-title'');
    const modalNameInput = document.getElementById(''modal-char-name'');
    const modalDescTextarea = document.getElementById(''modal-char-desc'');
    const modalCloseBtn = document.getElementById(''modal-close-btn'');
    const charData = [
         { name: ''两仪式'', img: ''https://cdn.jsdelivr.net/gh/lix14031-arch/TypeMoon/liangyishi.jpg'', desc: ''出身于拥有异能的古老退魔家族——两仪家，其身体直接与万物的根源『』相连。因意外事故，代表肯定的人格『织』陷入沉睡，换来了能目视万物之『死』的『直死之魔眼』。平日里身着和服，手持利刃，在城市的阴暗角落中斩杀怪异。外表看似冷漠疏离，内心却渴望着普通的幸福，是徘徊于日常与非日常夹缝中的孤独少女。'' },
        { name: ''苍崎青子'', img: ''https://cdn.jsdelivr.net/gh/lix14031-arch/TypeMoon/qingzi.jpg'', desc: ''现存的五位魔法使之一，司掌第五魔法『青』。在学生时代便继承了魔法，性格豪爽奔放，行事不拘一格，被誉为『Magic Gunner』。她的魔法涉及时间旅行与事象替换，能够将“结果”提前，拥有着颠覆因果的破坏力。尽管身负绝大的力量，却选择以一个普通人的身份生活，是游走于魔术世界与现代社会之间的稀有存在。'' },
        { name: ''阿尔托莉雅'', img: ''https://cdn.jsdelivr.net/gh/lix14031-arch/TypeMoon/saber.webp'', desc: ''古不列颠传说中的亚瑟王，以『Saber』的职阶现世的从者。为了拯救濒临毁灭的故国而拔出选定之剑，从此身体停止成长，以少女之姿背负起王的宿命。她恪守骑士道，正直而忠诚，但内心深处却为未能拯救国家而深感悔恨。手持誓约胜利之剑（Excalibur），为追寻圣杯的奇迹而战，是一位既高洁又食量惊人的少女骑士王。'' },
        { name: ''久远寺有珠'', img: ''https://cdn.jsdelivr.net/gh/lix14031-arch/TypeMoon/youzhu.png'', desc: ''隐居于久远寺邸的纯粹魔女，被称为『天生的魔女（Born Witch）』。性格孤高、不喜与人交往，是苍崎青子的同居人与魔术上的导师。她继承了古老的童话魔术（Ploy），能够将一个个完整的故事化为现实，创造出强大而诡异的怪物使魔。作为现代最后的魔女，她守护着神秘的边界。'' },
        { name: ''远坂凛'', img: ''https://cdn.jsdelivr.net/gh/lix14031-arch/TypeMoon/yuanbanlin.png'', desc: ''魔术名门远坂家的现任当主，继承了家族代代相传的宝石魔术。作为第五次圣杯战争的御主，她是一位能力全面、知识渊博的优等生。时刻秉持着『时刻保持优雅』的家训，外表看似高傲难以接近，实则内心善良且富有同情心。性格坚强好胜，但关键时刻总会出些小差错（掉链子），是一位兼具优雅、强大与可爱反差的现代魔术师。'' },
        { name: ''爱尔奎特'', img: ''https://cdn.jsdelivr.net/gh/lix14031-arch/TypeMoon/yueji.png'', desc: ''真祖的王族，被称为『真祖的公主』的吸血鬼。拥有将自己的意志直接反映到现实的究极能力『空想具現化』。原本沉睡于千年城中，因某个契机苏醒并来到人类世界，追杀宿敌。性格天真烂漫，对现代社会充满好奇，但其本质是作为星球抑制力的处刑装置而诞生。被远野志贵『杀死』一次后力量大幅削弱，从此与这位少年结下了奇妙的缘分。'' },
    ];
    while (charData.length < 30) {
        charData.push({ name: '''', img: '''', desc: '''' });
    }
    let currentEditingIndex = -1;
    function renderAllCards() {
        if (!charGrid) return;
        charGrid.innerHTML = '''';
        const frag = document.createDocumentFragment();
        for(let i = 0; i < 30; i++){
            const data = charData[i];
            const wrap = document.createElement("div");
            wrap.className = "char-item";
            wrap.dataset.index = i;
            const imgHtml = data.img 
                %s `<img src="${data.img}" alt="${data.name || ''''}" loading="lazy">`
                : `<span>#${i + 1}<br/>待填充</span>`;
            const nameValue = data.name || `角色 #${i+1}`;
            wrap.innerHTML = `
                <div class="char-item-img">${imgHtml}</div>
                <div class="char-item-name">${nameValue}</div>
            `;
            frag.appendChild(wrap);
        }
        charGrid.appendChild(frag);
    }
    function openModal(index) {
        currentEditingIndex = index;
        const data = charData[index];
        modalTitle.textContent = data.name %s `档案: ${data.name}` : `编辑角色档案 #${index + 1}`;
        modalNameInput.value = data.name;
        modalDescTextarea.value = data.desc;
        const isEditable = !data.name; 
        modalNameInput.readOnly = !isEditable;
        modalDescTextarea.readOnly = !isEditable;
        modal.style.display = ''flex'';
    }
    function closeModal() {
        if (currentEditingIndex > -1) {
            const data = charData[currentEditingIndex];
            const isEditable = !data.name;
            if(isEditable) { 
                data.name = modalNameInput.value;
                data.desc = modalDescTextarea.value;
                const card = charGrid.querySelector(`[data-index=''${currentEditingIndex}'']`);
                if(card) {
                    card.querySelector(''.char-item-name'').textContent = data.name || `角色 #${currentEditingIndex + 1}`;
                    if(data.img) {
                        card.querySelector(''.char-item-img img'').alt = data.name;
                    }
                }
            }
        }
        modal.style.display = ''none'';
        currentEditingIndex = -1;
    }
    function autoResize(textarea) {
        textarea.style.height = ''auto'';
        textarea.style.height = (textarea.scrollHeight) + ''px'';
    }
    if(charGrid && modal){
        renderAllCards();
        charGrid.addEventListener(''click'', (e) => {
            const card = e.target.closest(''.char-item'');
            if (card) {
                const index = parseInt(card.dataset.index, 10);
                openModal(index);
            }
        });
        modalCloseBtn.addEventListener(''click'', closeModal);
        modal.addEventListener(''click'', (e) => {
            if (e.target === modal) closeModal();
        });
    }
    document.querySelectorAll(''textarea'').forEach(ta => {
        ta.addEventListener("input", () => autoResize(ta), false);
    });
})();
const ROLL_POOL = [
    { k: "起源觉醒·[切断]", d: "你的本质是“切断”与“结合”。你擅长分离与连接万物，无论是物理的拆解还是概念的割裂都得心应手。但你的命运也将充满生离死别，无法与任何事物保持长久安稳的联系。" },
    { k: "起源觉醒·[吞噬]", d: "你的本质是“吞噬”。你能通过吸收他者的血肉乃至灵魂来获取力量与知识，但你永远无法满足，时刻被原始的饥饿感和吞噬一切的欲望所折磨。" },
    { k: "起源觉醒·[虚无]", d: "你的本质是“无”。你擅长消去、分解、归零类的魔术，甚至能让自身存在感变得稀薄。但你几乎无法使用任何创造或构筑系魔术，且难以在他人心中留下深刻印象。" },
    { k: "起源觉醒·[重复]", d: "你的本质是“重复”。你擅长需要反复操作的仪式和持续性魔术，并且能从无数次的失败中汲取经验。但你的思维容易僵化，难以跳出固有的模式去创造新事物。" },
    { k: "起源觉醒·[流动]", d: "你的本质是“流动”。你对变化有极高的适应性，擅长回避和伪装，如同流水般不被束缚。但这也使你缺乏坚定的立场，容易随波逐流，无法守护真正重要的东西。" },
    { k: "起源觉醒·[静止]", d: "你的本质是“静止”。你擅长设置结界和防御术式，内心如止水般难以被精神干涉。但你的行动力和爆发力天生较差，总是慢人一步。" },
    { k: "起源觉醒·[破坏]", d: "你的本质是“破坏”。你天生就适合使用攻击性魔术，并且威力巨大。但你几乎无法使用任何精密或非破坏性的术式，甚至身边的物品也容易被你无意识地损坏。" },
    { k: "起源觉醒·[救济]", d: "你的本质是“救济”。你无法对他人的苦难坐视不理，在治愈和守护魔术上有极高天赋。但也因此常常将自己拖入险境，是无法拯救所有人的“伪善”的体现。" },
    { k: "起源觉醒·[记录]", d: "你的本质是“记录”。你拥有过目不忘的记忆力，能快速解析并模仿他人的魔术。但你缺乏原创性，终其一生都可能只是他人的“复写品”。" },
    { k: "起源觉醒·[病]", d: "你的本质是“病”。你对毒、诅咒和疾病有天生的深刻理解，擅长制作和解除它们。但你的身体也永远被某种顽疾所折磨，比常人更接近死亡。" },
    { k: "宝石魔术的素养", d: "你天生就懂得如何将魔力储存在宝石中，并以最高效率引爆。学习宝石魔术时有额外加成，但这也意味着你是个天生的“败家子”。" },
    { k: "伪·空想具现化", d: "劣化版的空想具现化。你能将强烈的个人心象短暂地投射到现实，对一小片区域的物理法则进行微弱扭曲，但极不稳定且消耗巨大。" },
    { k: "阿特拉斯院的仿制品", d: "你持有一个阿特拉斯院“七大兵器”之一的仿制品。它拥有原型约十分之一的功能，但只能使用一次，且后果未知。" },
    { k: "黑化体质", d: "你的身体极易被“此世全部之恶”一类的概念污染。这让你对诅咒有极高的抗性，但也更容易吸引来自“外侧”的邪神或黑影的注意。" },
    { k: "彷徨海的邀请函", d: "你拥有一封一次性的邀请函，可以让你找到并进入魔术师的隐世乐园——彷徨海。这是机遇，也可能是通往与世隔绝的陷阱。" },
    { k: "直死之魔眼（劣化）", d: "你的眼睛能微弱地看到事物的“死”，但并非清晰的“线”或“点”，而是模糊的“裂痕”。你需要集中精神才能勉强斩断它们，且对大脑负担极大。" },
    { k: "巴格斯特的祝福", d: "你曾被妖精“黑犬”所祝福，拥有了部分它的权能。你的耐力和追踪能力得到提升，但会周期性地陷入无法抑制的饥饿感。" },
    { k: "第五魔法的残片", d: "你偶然接触过“魔法·青”的残渣。你无法理解其原理，但你的魔术有时会无视能量守恒，产生微小的、无法解释的奇迹。" },
    { k: "礼装·月灵髓液", d: "由时钟塔矿石科君主埃尔梅罗开发的自律防御礼装，形态为水银。能根据主人意志变形为盾牌或武器，但有侵蚀使用者心智的风险。" },
    { k: "圣骸布", d: "一块据说是包裹过圣人的布片。对灵体、恶魔等有强力的驱散和束缚效果，但对物理攻击无效。" },
    { k: "魔眼·束缚", d: "黄金级的魔眼。目光所及之处，能对目标施加“无法动弹”的强制概念，但对拥有强大魔力抗性的对手效果会减弱。" },
    { k: "代行者的训练", d: "你接受过圣堂教会代行者的基础训练，精通黑键投掷和洗礼咏唱。这让你在面对非人存在时更具优势，但也让你被魔术协会所警惕。" },
    { k: "炼金术（赫尔墨斯派）", d: "你师从时钟塔的炼金术师，专精于物质变换与人造人（Homunculus）的制造。你相信万物皆可被解析与再构。" },
    { k: "投影魔术", d: "你掌握了基础的投影魔术，能够复制并实体化你理解构造的物品。但投影物是空心的，且会因“世界的修正”而迅速消失。" },
    { k: "元素亲和·风", d: "你与“风”元素有极高的亲和力，学习风系魔术事半功倍，并能通过风感知周围环境。" },
    { k: "元素亲和·火", d: "你与“火”元素有极高的亲和力，这让你在使用攻击性魔术时威力倍增，但也让你性格急躁易怒。" },
    { k: "直感 (C)", d: "在战斗中，能以第六感预知对自己最有利的展开。相当于一种有限的未来视，能规避危险，但等级不高时容易被误导。" },
    { k: "心眼（真） (B)", d: "通过后天锻炼和战斗经验，在绝境中冷静分析局势、打破僵局的能力。是战斗智慧的体现，而非超能力。" },
    { k: "魔力放出 (A)", d: "将庞大的魔力直接用于强化身体能力的技术。无论是攻击、防御还是移动，都能获得爆发性的提升。" },
    { k: "卢恩魔术", d: "掌握了北欧的古老文字魔术。能够通过刻印卢恩符文发动各种效果，如强化、结界、索敌等。" },
    { k: "高速神言 (C)", d: "无需连接魔术回路，仅通过语言就能启动魔术的能力。C级可以省略一工程以下的魔术咏唱。" },
    { k: "魔术·Gandr", d: "源自北欧神话的诅咒术式（并非实体礼装）。通过手指指向目标发动，击中目标会使其身体状况恶化，俗称“Gandr射击”。" },
    { k: "强化魔术的极致", d: "你对“强化”这一基础魔术的理解登峰造极，能够强化物体的本质，使其发挥出远超常理的性能。" },
    { k: "魔眼·魅惑", d: "宝石级的魔眼。与你对视的人会不受控制地对你产生好感，意志薄弱者甚至会服从你的简单命令。" },
    { k: "动物对话 (D)", d: "能够理解低等动物的语言和情感。虽然无法命令它们，但可以与它们进行简单的交流，获取情报。" },
    { k: "礼装·Azoth剑", d: "魔术师之间传承的仪式用短剑，本身威力不大，但储存有一定魔力，是施展魔术的优秀辅助礼装。" },
    { k: "魔术刻印（移植）", d: "你被移植了一个衰败家系的魔术刻印。其中包含了数代人的魔术知识，但排异反应会周期性地让你感到剧痛。" },
    { k: "人工天线", d: "你的身体被改造过，能够像天线一样高效地从外界汲取魔力（Mana），在大源魔力浓厚的地区战斗力倍增。" },
    { k: "肯主任的讲义", d: "你拥有埃尔梅罗教室的秘传讲义副本，其中系统性地记录了现代魔术的各项理论，能让你在学习魔术时少走很多弯路。" },
    { k: "死灵魔术（Witchcraft）", d: "你学习的是偏向诅咒和草药学的“魔女”式魔术，而非操纵尸体的“Necromancy”。你擅长制作各种效果的灵药。" },
    { k: "固有时制御（卫宫家）", d: "通过加速或减慢自身时间的流动，实现超高速战斗或规避攻击。但对身体和灵魂的负荷极大，是双刃剑。" },
    { k: "礼装·黑键", d: "圣堂教会代行者的标准武装。是经过魔术处理的投掷剑，对灵体有特效，刀身长度可以根据使用者的意愿伸缩。" },
    { k: "魔眼·歪曲", d: "宝石级的魔眼，能够“扭曲”万物的概念。你可以将坚固的钢铁变得像布一样柔软，或将一条直线扭曲成螺旋。能力强大但极难控制。" },
    { k: "体质·吸血冲动", d: "你拥有微弱的吸血鬼血统，身体能力高于常人，并拥有自我恢复能力。但每月必须吸食一次血液，否则会陷入虚弱。" },
    { k: "召唤学（基础）", d: "你掌握了召唤学的基础，能够召唤并役使一些低等的灵体或元素灵，但无法进行英灵召唤。" },
    { k: "礼装·概念武装（仿）", d: "一件能够对特定“概念”产生干涉效果的武器仿制品。例如，“对不死者特效”、“斩断契约”等，效果较弱。" },
    { k: "幸运 (E)", d: "你的运气非常差，总是被卷入各种麻烦事件中。但俗话说“Lancer死了”，也许在绝境中这会成为一种另类的护身符。" },
    { k: "单独行动 (C)", d: "即使没有御主供给魔力，也能在现世停留一天。这让你在脱离组织或御主后仍有一定的自保能力。" },
    { k: "中国拳法", d: "你修习过八极拳、形意拳等中国武术，并将其与魔力运行相结合，形成了独特的战斗风格。" },
    { k: "阿瓦隆的苹果", d: "你吃过一颗来自理想乡阿瓦隆的苹果。你的恢复能力和魔力亲和性得到了永久提升。" },
    { k: "礼装·第五架空要素", d: "以“以太”为基础，模拟出不存在的“第五架空元素”的礼装。可以用来发动一些违反常规属性的奇迹，但消耗巨大。" },
    { k: "工房建造", d: "你擅长建立自己的魔术工房。在工房内，你的魔术效果会得到增幅，并且可以设置各种陷阱和结界。" },
    { k: "人体改造（Caster式）", d: "你对用魔术改造人体有一定心得，能够为自己或他人进行小幅度的能力强化改造。" },
    { k: "黄金律 (C)", d: "身体的黄金比例，也指获得财运的宿命。你从不为金钱所困，总有办法搞到活动资金。" },
    { k: "气息遮断 (D)", d: "能够遮断自身气息，让敌人难以察觉。虽然不适合潜入，但在战斗中突然消失或偷袭时非常有效。" },
    { k: "礼装·魔力棱镜", d: "能将一种属性的魔力折射、转换为另一种属性的小型棱镜。虽然转换效率不高，但在关键时刻能派上用场。" },
    { k: "魔眼·未来视", d: "能够看到未来的可能性片段。但未来并非固定，你看到的只是无数可能性中的一种，过度依赖会被未来所束缚。" },
    { k: "人造人（Homunculus）", d: "你本身就是一名被制造出来的人造人。你的寿命很短，但拥有远超常人的魔术回路和某一方面的特化能力。" },
    { k: "神性 (E-)", d: "你的血脉中混有极其稀薄的神之血。这让你拥有微弱的魔力抗性，但也让你更容易被“弑神”属性的攻击所伤。" },
    { k: "礼装·宝石剑泽尔里奇（设计图）", d: "你拥有第二魔法使的杰作——宝石剑的设计图。虽然以你的能力无法再现，但研究它能让你对“多元宇宙”有更深的理解。" },
    { k: "战斗续行 (B)", d: "即使受到濒死的重伤也能继续战斗，拥有顽强的生命力。只要不是决定性的致命伤，就能存活下来。" },
    { k: "音乐魔术", d: "你擅长通过演奏乐器来施展魔术，能够通过旋律对人的精神进行干涉，或引发小规模的物理现象。" },
    { k: "黑魔术（Voodoo）", d: "你学习的是加勒比地区的巫毒魔术，擅长制作人偶和使用“灵”进行诅咒或守护。" },
    { k: "魔眼·石化", d: "蛇发女妖的魔眼。能将魔力等级在C以下的生物直接石化，对高等级目标也能造成“重压”和“迟缓”效果。" },
    { k: "礼装·万能钥匙", d: "一把可以打开任何“被锁住”的物理门扉的钥匙。但无法打开魔术结界或概念性的“锁”。" },
    { k: "自我改造 (C)", d: "能够将其他生物的肉体和能力吸收、融合到自己身上，从而不断进化。是一种踏上非人之路的技能。" },
    { k: "天体科魔术", d: "你属于时钟塔的阿尼姆斯菲亚（Animusphere）科，擅长通过观测星辰来进行占卜和大规模的仪式魔术。" },
    { k: "无毁的湖光（仿）", d: "一把模仿了某位骑士圣剑的魔剑。它不会毁坏，并且能将持有者获得的魔力转化为攻击力。" },
    { k: "投影装填", d: "投影魔术的亚种，将投影出的武器作为一次性的“弹药”发射出去，威力等同于C级宝具，俗称“幻想崩坏”。" },
    { k: "魔眼·因果律操作（微）", d: "极罕见的魔眼。能对微小事件的因果进行篡改，例如“让本该射偏的子弹命中”，但每次使用都会积累“世界的债务”。" },
    { k: "礼装·自我封印·暗黑神殿", d: "用于束缚自身强大力量或魔眼的制御礼装。平时压制你的力量，但在解开时能爆发出惊人的威力。" },
    { k: "勇猛 (B)", d: "能够无效化威压、混乱、迷惑等精神干涉。在格斗战中，能让自己的攻击力得到提升。" },
    { k: "千里眼 (C)", d: "超常的视觉能力。能够捕捉到远方或高速移动的物体，甚至能进行一定程度的透视。" },
    { k: "降灵术", d: "你擅长将灵体（包括英灵的侧面）凭依到自己或他人身上，从而暂时获得其能力。是一种高风险的技术。" },
    { k: "礼装·伪臣之书", d: "能够与没有御主的从者签订临时契约的书本。虽然能指挥从者，但魔力供给效率低下。" },
    { k: "动物灵附体", d: "你的家族与特定的动物灵签订了契约，你可以在战斗中借用动物灵的力量，使自己兽化，身体能力大幅提升。" },
    { k: "魔眼·时间感知", d: "能让自己的主观时间变慢，从而在高速战斗中看清对手的动作。相当于一种精神层面的“固有时间制御”。" },
    { k: "以太块", d: "你能够将以太（第五架空要素）塑造成块状并投掷。虽然是基础魔术，但你的熟练度极高，威力堪比炮弹。" },
    { k: "礼装·幻想铁线", d: "由特殊合金和魔力构成的极细钢丝，可以用于设置陷阱、束缚敌人或进行精密切割。" },
    { k: "收藏家", d: "你对收集魔术礼装有异常的执着和天赋，总能找到各种珍奇的道具，并且能很快掌握它们的使用方法。" },
    { k: "无貌之王", d: "你拥有能够自由改变自己外貌和声音的技能，甚至能模仿他人的魔力波动。是顶级的伪装能力。" },
    { k: "咒腕", d: "你的手臂被寄宿了恶魔的咒腕。它能伸长并扭曲，发动必中的咒杀攻击，但使用时会侵蚀你的生命。" },
    { k: "礼装·起源弹", d: "你拥有某位魔术师出售的十枚用肋骨磨成粉，混入水银制成的特殊子弹。击中魔术师会使其起源暴走，从而从内部破坏其魔术回路。" },
    { k: "炼金术（阿特拉斯院）", d: "你属于分割思考、高速演算的阿特拉斯院。你不依赖外界大源魔力，而是通过肉体小源计算未来的所有可能性并“固定”最佳结果来进行战斗。" },
    { k: "贫者的见识", d: "能够看破对手的性格和属性，识破花言巧语。在与人交涉时不会被欺骗。" },
    { k: "礼装·穿刺之棘", d: "一把布满倒刺的短枪，被其刺伤后，伤口会不断扩大并难以治愈。" },
    { k: "怪力 (C)", d: "暂时性地增幅筋力。源于魔物或幻想种的特性，使用时会让你的一部分身体产生兽化特征。" },
    { k: "魔术抗性 (D)", d: "对魔术有一定程度的抵抗力。能够将D级以下的魔术直接无效化。" },
    { k: "影之国血统", d: "你拥有影之国女王的血统，天生就精通枪术和卢恩魔术，并对死亡有特殊的感知。" },
    { k: "湖之妖精的祝福", d: "你受到了湖之妖精的祝福，水属性亲和力极高，并能在水边缓慢治愈伤势。且可以站在水面之上" },
    { k: "太阳的恩惠", d: "你可能与某位太阳神有关，在白天时身体能力和魔力恢复速度会得到显著提升。但在黑夜或日食期间，你会陷入虚弱。" },
    { k: "伽蓝之堂", d: "你的起源觉醒后变得“空洞”，这让你能轻易容纳和学习任何知识与能力，但你本身没有任何特长和欲望，像一个等待被填满的空虚容器。" },
    { k: "埋葬机关预备役", d: "你被第七圣典所记录，是埋葬机关的候补成员。你拥有狩猎异端的知识和部分权限，但也被教会严格监视，人生无法自由。" },
    { k: "魔术协会的封印指定", d: "你的才能或研究成果被时钟塔认定为“对神秘保护有害”，被列为封印指定执行者追捕的对象。你很强大，但也从此活在无尽的逃亡中。" },
    { k: "二十七祖的因子", d: "你体内混有死徒二十七祖中某一位的微弱因子，拥有其权能的劣化版（如不死性、高速思考等），但也会被其本性（如吸血冲动、残虐性）所影响。" },
    { k: "元素亲和·地", d: "你与“地”元素有极高的亲和力，防御和结界类魔术效果倍增，但行动相对迟缓。" },
    { k: "元素亲和·水", d: "你与“水”元素有极高的亲和力，擅长治愈、变形和防御魔术，性格也如水般柔和。" },
    { k: "元素转换", d: "你拥有罕见的“架空元素”属性，能够自由转换四大元素的属性，让你的魔术变幻莫测。" },
    { k: "植物科魔术", d: "你属于时钟塔的尤米娜（Yumina）科，擅长操纵植物进行战斗或制作各种魔药，专精于魔术植物的培育、魔药学以及部分炼金术的分支。" },
    { k: "埃及神代魔术", d: "你传承了古埃及的魔术基盘，擅长诅咒、使役灵兽和制作守护符。你的魔术在现代魔术体系中显得异质而强大。" },
    { k: "卡巴拉", d: "你学习的是源于犹太秘术的魔术体系，通过“生命之树”图谱来解析世界、创造魔像（Golem）或设置天使级结界。" },
    { k: "阴阳道", d: "你掌握了日本的阴阳道，擅长占卜、符咒、式神使役和风水结界，对东方的灵体有很强的克制力。" },
    { k: "巴瑟梅罗的血统", d: "你拥有时钟塔君主·巴瑟梅罗的血脉，天生拥有高质量的魔术回路和对“至高”的追求，能轻易驾驭强大的魔术礼装。" },
    { k: "魔道元帅的印记", d: "你曾得到过魔道元帅泽尔里奇的指点，虽然没学到魔法，但对“平行世界干涉”有了一定的抗性和理解。" },
    { k: "魔眼·解析", d: "黄金级的魔眼，能够快速解析魔术术式的构成和魔力流动。是学者和技师梦寐以求的能力。" },
    { k: "魔眼·燃烧", d: "宝石级的魔眼，能将视线汇聚之处的魔力点燃，引发小规模的火焰或爆炸。对魔术结界有特效。" },
    { k: "魔眼·记忆", d: "黄金级的魔眼，能够读取物品上残留的“记忆”，回溯其过去的景象。对活物使用则负担极大。" },
    { k: "魔眼·静谧", d: "宝石级的魔眼，你的视线能平息他人的负面情绪，如愤怒、恐惧，对精神干涉类魔术有防御效果。" },
    { k: "心眼（伪） (A)", d: "在修行和锻炼的尽头，达成的洞察力。即使在绝境中也能保持冷静，并以“第六感”找出活路。是真正的天启。" },
    { k: "重整旗鼓 (C)", d: "脱离战斗后，能让不利的战况和自身状态得到重置的能力。C级可以消除大部分负面效果。" },
    { k: "领导力 (D)", d: "指挥团队的天生才能。D级足以领导一个小队，能提升同伴的士气和战斗力。" },
    { k: "骑乘 (B)", d: "能够熟练驾驭各种坐骑。B级可以驾驭现代交通工具和大部分幻想种。" },
    { k: "礼装·自动书记人偶", d: "一具能自动记录、整理信息，并进行简单魔术辅助演算的小型人偶。是你的移动工房和秘书。" },
    { k: "礼装·空间收纳盒", d: "一个内部被施加了空间魔术的盒子，可以存放远超其体积的物品。但无法存放活物。" },
    { k: "礼装·记忆读取银针", d: "能刺入他人大脑，读取其表层记忆的危险礼装。使用不当会导致目标变成白痴。" },
    { k: "礼装·人偶义肢", d: "你的部分身体被替换为苍崎橙子制作的高性能人偶义肢，拥有远超常人的力量和精密性，并内置了简单的魔术机构。" },
    { k: "合成兽（Chimera）", d: "你的身体被深度改造，融合了多种魔兽的因子，获得了多种能力（如飞行、再生、毒液），但也失去了大部分人性。" },
    { k: "圣人遗骨", d: "你的体内被植入了某位圣人的遗骨，这让你拥有了对恶魔、吸血鬼的强大抗性，并能使用微弱的“秘迹”。" },
    { k: "精灵种血统", d: "你拥有稀薄的精灵血统，对大自然有天生的亲和力，能看懂“妖精文字”，并能使用一些自然系的魔术。" },
    { k: "神代神秘携带者", d: "你的血脉或灵魂中寄宿着某种来自神代的诅咒或恩惠，这让你拥有某种异质的能力（如微弱的神代魔术），但也会被其反噬，身体或精神有异于常人之处。" },
    { k: "南美咒术", d: "你使用的是基于活祭和通灵的南美原始咒术，效果诡异且威力巨大，但与现代魔术体系格格不入，容易被视为异端。" },
    { k: "诅咒科魔术", d: "你属于时钟塔的吉格马克（Jigmac）科，专精于各种诅咒，无论是迟效性的恶毒诅咒还是速效性的战斗咒术都信手拈来。" },
    { k: "创造科魔术", d: "你属于时钟塔的巴琉耶雷塔（Valualeta）科，你将魔术与艺术视为一体，常以绘画、雕塑等美学形式来构筑魔术或制作武装。" },
    { k: "传承科魔术", d: "你属于时钟塔的布里希桑（Brishisan）科，致力于守护和传承古老的神秘，你对神代魔术和古代遗物有很深的了解。" },
    { k: "法政科魔术", d: "你属于时钟塔的巴瑟梅罗科。作为时钟塔的‘警察’与特权阶级，你负责肃清异端、维持神秘的隐匿，擅长以极其正统且压倒性的暴力魔术碾碎一切违规者" },
    { k: "礼装·迎击武装", d: "一件能对特定攻击自动做出反应的防御礼装，例如“自动格挡飞行道具”、“自动展开魔力护盾”等。" },
    { k: "礼装·痛觉屏蔽", d: "一件能暂时屏蔽身体痛觉的礼装，让你在重伤时也能保持战斗力。但过度使用会导致身体因不知损伤而崩溃。" },
    { k: "礼装·魔力弹夹", d: "能预先储存大量魔力，并在战斗中快速补充使用者魔力的道具。相当于魔术师的“备用电池”。" },
    { k: "礼装·替身人偶", d: "一个能替你承受一次致命攻击的人偶。发动后人偶会毁灭，并将你传送到附近的安全位置。" },
    { k: "礼装·真实之貌", d: "一面能看破幻术、伪装和气息遮断的镜子。对高等级的隐藏能力效果会减弱。" },
    { k: "无念之拳", d: "一种将精神放空，完全凭借本能和经验进行战斗的武术境界。能有效对抗依赖预判和直感的敌人。" },
    { k: "双貌塔的密使", d: "你曾为时钟塔的情报机构“双貌塔”工作，精通情报收集、潜入和暗杀技术。" },
    { k: "秘仪裁示局", d: "你是圣堂教会下属“秘仪裁示局”的成员，负责鉴定圣遗物和裁定“奇迹”，拥有丰富的宗教和神秘学知识。" },
    { k: "代偿魔术", d: "你擅长使用“以物易物”的代偿魔术，通过献出自己的某些东西（如视力、记忆、寿命）来发动强大的奇迹。" },
    { k: "结界师", d: "你对结界魔术有极高的天赋，能布置出覆盖整个城市的大结界，或是在方寸之间创造出隔绝世界的异空间。" },
    { k: "符文大师", d: "你的卢恩魔术已臻化境，能够组合复数的卢恩符文，创造出接近神代魔术效果的“原初卢恩”。" },
    { k: "幻想种召唤", d: "你的召唤学超越了基础，能够与特定的幻想种（如狮鹫、独角兽）签订契约，并在战斗中召唤它们协助。" },
    { k: "魔剑使", d: "你并非投影，而是真正持有一把拥有自我意识和强大能力的“魔剑”。你与剑是伙伴，但也可能被其意志所吞噬。" },
    { k: "圣剑使", d: "你被某把“圣剑”所选中，能够发挥其神圣的力量。你对邪恶的存在有强大的杀伤力，但也受到剑的戒律所束缚。" },
    { k: "傀儡师", d: "你擅长操纵人偶进行战斗，你的战斗力取决于你人偶的数量和质量。本体通常隐藏在幕后，极为安全。" },
    { k: "炼金炸弹客", d: "你将炼金术用于制作各种效果的炸弹，如水银炸弹、魔力吸收炸弹、概念迟缓炸弹等，是战术大师。" },
    { k: "精神入侵者", d: "你擅长潜入他人的精神世界，读取记忆、植入暗示或破坏其心智。是无声的刺客，但也极易在精神世界中迷失。" },
    { k: "神明代理", d: "你被某个衰落的神明选为代理人，能够在付出代价后，有限地使用其部分权能。" },
    { k: "死灵魔术（Necromancy）", d: "你学习的是操纵尸体和灵魂的“通灵术”，能够将死者作为士兵或情报源来使役。这是被教会视为禁忌，但在时钟塔属于合法研究领域的技术。" },
    { k: "血之伯爵", d: "你的家族传承了弗拉德三世的穿刺之术，能从身体中伸出无数的桩子进行攻击和防御。" },
    { k: "未来观测", d: "你有极高精度的未来视，能看到确定的“未来结果”。这让你能规避死亡，但也让你的人生失去了所有惊喜和未知。" },
    { k: "存在悖论", d: "你的存在本身就是一个矛盾体，例如“活着但却在腐朽”。这让你拥有一些无视常理的能力，但也让你自身的存在极不稳定，容易被世界修正。" },
    { k: "猎食者的直觉", d: "你对“弱肉强食”的法则有深刻的理解，能够轻易看穿他人的杀意、恐惧和弱点，并找出最有效率的捕猎方法。" },
    { k: "痛觉复写", d: "你能够让敌人已经治愈的伤口“记忆”住疼痛，即使身体完好无损，也会持续感受到剧痛的折磨。" },
    { k: "灵体脱壳", d: "你拥有脱离肉体的“灵体飞行”能力，可以从高空俯瞰城市，进行侦察。但灵体状态下很脆弱。" },
    { k: "记忆录音", d: "你能够“收集”他人的记忆，并将其储存在特定物品中。你也能将这些记忆“播放”给别人看。" },
    { k: "伪神之书", d: "你持有一本用人皮制成的魔导书，能够召唤并役使大量海魔。但长期使用会严重扭曲使用者的精神。" },
    { k: "统率力 (B)", d: "并非后天的技巧，而是天生的领袖气质。B级足以领导一个国家，让人们不由自主地追随你。" },
    { k: "炼金术（贤者之石）", d: "你的炼金术研究触及了终极目标——贤者之石。你拥有一个不完整的“石头”，能让你进行有限的“等价交换”和灵魂炼成。" },
    { k: "对魔力 (B)", d: "B级足以将三节以下的魔术咏唱无效化，即使是大魔术、仪礼咒法也难以伤害到你。" },
    { k: "圣杯的残渣", d: "你曾沐浴在圣杯泄露的魔力中，身体被其改造。你的魔力总量大幅增加，但身体也留下了无法治愈的“孔”。" },
    { k: "妖精眼", d: "能看穿谎言，并将无法用数值表示的抽象概念（如“运气”、“好感度”）视觉化的眼睛。但无法看穿发自真心的欺骗。" },
    { k: "教会骑士团", d: "你曾是圣堂教会下属骑士团的一员，精通对魔物的剑术和团队作战，并拥有祝福过的甲胄。" },
    { k: "魔术回路·异质", d: "你的魔术回路并非正常形态，而是像“植物”或“机械”一样，这让你在特定领域的魔术上有超常表现，但也限制了你的泛用性。" },
    { k: "魔力过敏症", d: "你的身体对魔力有强烈的排异反应，无法正常使用魔术。但作为代价，你对魔力异常敏感，能轻易察觉到隐藏的魔术师或结界。" },
    { k: "神话礼装", d: "你拥有一件在神代由神明或传说中的工匠打造的礼装，其性能远超现代礼装，甚至接近宝具的领域。" },
    { k: "概念礼装·天之衣", d: "一件能无效化大部分诅咒和概念干涉的防御礼装。但对纯粹的物理攻击防御力不高。" },
    { k: "神域剑术·终之太刀", d: "已踏入神域的剑之绝技。此斩击并非为了“切断”肉体，而是为了斩断目标的“存在概念”。被此剑斩中，伤口不会流血，而是存在本身会从世界的记录中被抹消，是抵达“空”之境界的一剑。" },
    { k: "神域枪术·穿界", d: "已踏入神域的枪之绝技。此枪无视距离的概念，在枪尖锁定目标的瞬间，因果便已决定“命中”。枪身并非穿越空间，而是将“起点”与“终点”直接相连，是无法闪避、无法格挡的必中之刺。" },
    { k: "神域枪术·千之命运", d: "已踏入神域的枪之绝技。一枪刺出，便同时衍生出一千种“命中”的因果，每一道枪影都是一个确定的未来。除非能同时否定这一千种命运，否则必然会被其中一道真实之枪所贯穿。" },
    { k: "燕返（亚种）", d: "模仿传说中剑豪宝具的斩击。通过超高速的剑闪，在同一时间点从三个方向斩出无视物理法则的“同时斩击”，形成一个无法回避的囚笼。但作为亚种，对使用者的负担极大，且无法达到原版的“多重次元曲折现象”。" },
    { k: "八极拳（魔术改良）", d: "将中国拳法与魔术回路的运行相结合的武技。每一击都伴随着魔力爆发，能以“寸劲”的形式将魔力打入敌人体内，从内部破坏其脏器或魔术回路。" },
    { k: "浸透劲", d: "一种特殊的发力技巧，能够让攻击的劲力无视物理防御，直接渗透到目标的内部。即使对方穿着厚重的铠甲，也能对其内脏造成伤害。" },
    { k: "缩地（武术）", d: "并非魔术，而是纯粹凭借步法、呼吸法和身体运用达到超高速移动的武术境界。在他人眼中看来，就像是缩短了空间的距离。" },
    { k: "无明三段突", d: "将通常只能刺出一次的突刺，在同一时间点、同一位置上，以无视物理惯性的方式连续击出三次。第一击撕开防御，第二击扩大伤口，第三击贯穿核心，是必杀的刺击。" },
    { k: "流水之太刀", d: "一种专注于防御和反击的剑术流派。如同流水一般卸开、格挡、闪避敌人的所有攻击，并能在对方露出破绽的瞬间，以最小的动作施以致命反击。" },
    { k: "重斧碎甲", d: "专为破坏而生的斧术。舍弃了所有技巧，将全部力量和魔力集中于一点，每一次挥击都以粉碎敌人的铠甲、盾牌、结界为唯一目的。" },
    { k: "双匕之舞", d: "使用双短剑的战斗技巧，如同舞蹈般华丽而致命。通过高速的移动和变幻莫测的攻击角度迷惑敌人，在交错的瞬间割裂其要害。" },
    { k: "兽性解放", d: "通过魔术或血脉，暂时解放体内潜藏的野兽本能。身体能力会得到爆发性提升，痛觉变得迟钝，但理性也会随之减弱，甚至有失控的风险。" },
    { k: "魔力硬化", d: "强化魔术的应用技巧，将高密度的魔力覆盖在皮肤表面，使其硬度瞬间超越钢铁。是魔术师在近战中用于防御或增强打击力的常用手段。" },
    { k: "符文之刃", d: "将卢恩符文预先刻印在武器上，在战斗中通过简短的言灵激活。可以瞬间发动“锐化”、“火焰”、“冻结”、“追踪”等多种效果。" },
    { k: "以太冲击", d: "将以太块在手心或武器前端凝聚，在接触到敌人的瞬间引爆，造成零距离的魔力爆炸。简单粗暴但威力巨大。" },
    { k: "血液结界（自伤）", d: "以自己的血液为媒介，在身体周围展开小型的防御或束缚结界。虽然咏唱极短，但每次使用都会消耗自身的生命力。" },
    { k: "不愈之伤", d: "通过诅咒或特殊的武器，对敌人造成无法被常规治愈魔术或自愈能力所恢复的伤口。除非解除诅咒，否则伤口会持续流血并恶化。" },
    { k: "概念捕缚", d: "使用附有“束缚”概念的武器（如锁链），一旦命中，不仅是束缚敌人的肉体，更是束缚其“行动”的概念，使其难以挣脱。" },
    { k: "因果切断之击", d: "一种高度神秘性的攻击，其目的并非杀伤，而是切断目标身上的某种“因果联系”，例如切断魔术师与使魔的契约，或暂时切断作用于其身上的强化魔术。" },
    { k: "骨骼再编", d: "通过魔术改造，可以自由地让自己的骨骼伸长、变形或增殖，从而在近战中发动出人意料的攻击，例如从手臂中弹出骨刃，或让脊椎化为骨鞭。" },
    { k: "杀气感知", d: "对“杀意”有极其敏锐的直觉。能够提前感知到敌人的攻击意图和攻击方向，即使是气息遮断也难以完全隐藏杀气。" },
    { k: "武器的共鸣", d: "能够理解武器“感情”的特殊体质。能以最快速度掌握任何武器的使用方法，并能最大限度地发挥出武器本身蕴含的神秘。" },
    { k: "一击决胜", d: "将自己所有的魔力、体力、甚至生命力都灌注于一次攻击中，以求必杀的舍身之技。使用后，无论成功与否，使用者都会陷入极度的虚弱状态。" },
    { k: "武器格挡（A++）", d: "将单纯的格挡技巧磨炼至极致后产生的异能。已经不再是“挡住攻击”，而是“否定攻击”的境界。甚至能够格挡无形的魔术或概念性攻击。" },
    { k: "不动如山", d: "一种特殊的防御架势，将重心与大地相连，大幅提升自身的防御力和抗冲击能力。摆出此架势后，极难被击退或击倒，但机动性会大幅下降。" },
    { k: "受流·天守", d: "一种高级的卸力技巧，能够将来袭的攻击（包括物理和魔术）的力量流向改变，使其偏离原本的轨道，甚至可以将其反弹给攻击者。" },
    { k: "心眼（真） (A)", d: "通过无数次修罗场般的战斗经验，培养出的超凡洞察力。能在绝境中保持冷静，分析战况，并从千万种可能性中找出那唯一的“活路”。" },
    { k: "战斗续行 (A)", d: "拥有异常顽强的生命力，即使身负足以致命的重伤也能继续战斗。只要不是心脏或大脑被彻底破坏，就不会轻易停下活动。" },
    { k: "基础科魔术", d: "你属于时钟塔的密斯提亚（Mystile）科，由特兰贝里奥派掌管。你专注于全体魔术的共通基础理论，魔术地基极其扎实，泛用性极强。" },
    { k: "个体基础科魔术", d: "你属于时钟塔的索罗内亚（Solonea）科。专注于魔术师个体差异的研究，对魔术回路的开发和异化改造有独到见解。" },
    { k: "降灵科魔术", d: "你属于时钟塔的尤利菲斯（Eulyphis）科。正统的通灵术研究者，擅长召唤灵体、降灵术以及英灵召唤的相关秘仪。" },
    { k: "矿石科魔术", d: "你属于时钟塔的基修亚（Kischur）科，由埃尔梅罗派掌管。精通宝石魔术、矿物炼成以及将魔力注入无机物的流体操作技术。" },
    { k: "动物科魔术", d: "你属于时钟塔的奇美拉（Chimera）科。致力于研究魔兽、幻想种的生态以及使魔的培养，甚至能进行跨物种的融合实验。" },
    { k: "考古科魔术", d: "你属于时钟塔的梅亚斯提亚（Meluastea）科。不问俗世，沉迷于发掘古老魔术基盘和神代遗迹，掌握许多失传的古代魔术知识。" },
    { k: "现代魔术科", d: "你属于时钟塔的诺利吉（Norwich）科。致力于研究百年内诞生的现代神秘，虽然缺乏神代底蕴，但擅长将魔术与现代科技结合。" },
    { k: "龙之因子", d: "你体内沉睡着幻想种顶点的“龙”之因子。魔力生成量如同炉心般庞大，但容易受到“对龙”属性武器的致命克制。" },
    { k: "鬼之混血", d: "你拥有东洋“鬼”的稀薄血脉。天生拥有骇人的怪力与强韧的肉体，但情绪容易失控，被激发血性时会无视痛觉。" },
    { k: "妖精乡的迷途者", d: "你曾在无意间踏入过妖精领域并生还。你的时间流逝变慢，对现代魔术的抗性极高，但常有脱离现实的虚无感。" },
    { k: "水银之血", d: "你的血液被特殊的炼金术改造，如同水银般沉重且具有剧毒。你能自由操纵自己的血液进行攻防，但寿命大幅缩短。" },
    { k: "虚数属性", d: "你的魔术属性是极为罕见的“虚数”。你的魔术在物理层面没有直接破坏力，但在处理灵魂、灵体或干涉空间概念时有奇效。" },
    { k: "以太宇宙体质", d: "你的肉体构成异于常人，更适应真以太环境。在神代魔力浓度极高的地方如鱼得水，但在现代魔力枯竭的环境会感到窒息。" },
    { k: "思想盘连线", d: "你连接着东洋魔术世界的“思想盘”。能够使用区别于西洋魔术基盘的“思想魔术”，发动极快且借力于大地。" },
    { k: "神言残响", d: "你的发声器官异于常人，能够发出近似于“神代语言”的音节。咏唱魔术时威力翻倍，但发音错误会严重损伤声带。" },
    { k: "直系弟子（魔女）", d: "你曾是某位活在现代的“魔女”（如苍崎青子或有珠）的记名弟子。虽然没学全，但你的战斗风格异常狂放且破坏力惊人。" },
    { k: "灵子转移适应性", d: "你的存在（灵魂形态）极其稳定，能够承受灵子转移（Rayshift）的拉扯，是罕见的能够进行时间旅行的御主候补。" },
    { k: "异星神眷属（微）", d: "你曾被外侧的某种“东西”注视过。你的魔力带有污染性，对地球的原生生命有微弱的克制，但容易被抑止力抹杀。" },
    { k: "抑止力代行者（临时）", d: "你在某个节点被阿赖耶识选中。当你为了人类存续而战时，所有基础能力会获得世界级加成；平时则只是个凡人。" },
    { k: "毒之躯", d: "你的肉体自幼浸泡在剧毒中。你的体液、甚至呼吸都带有致命毒性。你对一切毒素免疫，但也无法轻易触碰他人。" },
    { k: "魔眼·透视 (C)", d: "能够看穿物理障碍，看到墙壁后方的事物或隐蔽的魔术回路。对魔力密集的结界效果不佳。" },
    { k: "魔眼·幻觉 (C)", d: "与你对视的瞬间，能让对方产生短暂的视觉或听觉错乱。在白刃战中能制造致命的破绽。" },
    { k: "魔眼·掠夺 (B)", d: "黄金级。注视目标时，能微量吸收对方的魔力或生命力补充自身。视线接触时间越长效果越强。" },
    { k: "魔眼·冰冻 (B)", d: "黄金级。目光所及之处的热量会被强行剥夺。可以瞬间冻结水面，或让敌人的关节因极寒而僵硬。" },
    { k: "魔眼·破幻 (A)", d: "宝石级。能够看穿一切幻术、伪装和低级别的空间扭曲。在你眼前，大部分隐秘魔术都无所遁形。" },
    { k: "魔眼·重压 (B)", d: "黄金级。对视线内的目标施加概念上的“重力”。能让敏捷的敌人变得迟缓，甚至将脆弱者压趴在地。" },
    { k: "魔眼·强制 (A)", d: "宝石级。以言灵结合魔眼，强制命令对方执行你的语言。意志力低于一定程度的敌人无法反抗。" },
    { k: "魔眼·死灵感知 (C)", d: "被动生效的魔眼。能够清晰地看到灵魂、死气和幽灵的残响，是探索凶宅和墓地的利器。" },
    { k: "魔眼·预知梦 (D)", d: "无法主动控制。在睡眠时偶尔会看到与自己相关的未来片段，醒来后记忆会变得模糊。" },
    { k: "魔眼·复写 (A)", d: "宝石级。能够将看过的魔术术式瞬间复制到自己的脑海中。但如果魔力属性不符，依然无法使用。" },
    { k: "宗和的心得 (B)", d: "对于同一对手重复使用同样的招式，命中精度也不会下降的特殊技能。敌人无法从你的攻击模式中学习并适应。" },
    { k: "无我境界 (A)", d: "摒弃一切杂念和感情，让肉体自动应对攻击。能够无效化一切迷惑、魅惑等针对精神的干涉。" },
    { k: "呼吸法 (B)", d: "古武术或剑客的特殊呼吸节奏。能在战斗中快速恢复体力，并在瞬间爆发出超越肉体极限的筋力。" },
    { k: "气配感知 (B)", d: "能够察觉周围数公里内的魔力反应和生命气息，相当于人肉雷达，能有效防备暗杀者的偷袭。" },
    { k: "道具作成 (C)", d: "具备制作带有魔力的器具的才能。虽然无法制作宝具级的礼装，但量产恢复药剂和低级符咒不在话下。" },
    { k: "阵地作成 (C)", d: "具备建造对自身有利的阵地“工房”的才能。在工房内，你的魔力恢复和魔术威力都会得到提升。" },
    { k: "剑术 (A)", d: "已经达到了现代剑客的巅峰。即使不使用魔力，仅凭剑技也能与下级使魔或劣化的死徒周旋。" },
    { k: "枪术 (A)", d: "精通长柄武器的战斗技巧。擅长控制距离，能以精准的刺击贯穿魔力护盾的薄弱点。" },
    { k: "暗杀术 (B)", d: "精通各种下毒、偷袭、陷阱设置和一击毙命的技巧。正面战斗力不强，但只要条件允许，能越级击杀强敌。" },
    { k: "弓术/射击 (A)", d: "弹无虚发的射手。不仅是现代枪械，即便使用古老的弓弩，也能将其威力发挥到极致。" },
    { k: "骑乘 (A)", d: "除了幻兽和神兽等级，几乎所有现存的兽类或现代交通工具都能以极高的技巧驾驭。" },
    { k: "魔力防御 (B)", d: "被动将魔力覆盖全身，能够减免大量物理和魔术伤害，等同于随时穿着一件无形的铠甲。" },
    { k: "结界破坏者 (B)", d: "你的攻击（物理或魔术）带有破坏阵地和术式的特性。能够以暴力强行撕裂复杂的防御结界。" },
    { k: "奇迹 (D)", d: "极小概率引发无法用魔术理论解释的现象。当你陷入绝境且Roll出大成功时，能强行扭转局势。" },
    { k: "洗礼咏唱 (B)", d: "圣堂教会代行者的标配。通过神之言灵净化灵体和吸血鬼。对普通人无效，对死徒有致命杀伤力。" },
    { k: "信仰的加护 (C)", d: "拥有坚定的宗教信仰。精神绝对不会被外道魔术扭曲，且在面对异端时身体能力会小幅上升。" },
    { k: "圣言法术 (B)", d: "不属于魔术，而是借由祈祷降下的“秘迹”。擅长治愈绝症、驱散诅咒，是教会高级神职人员的象征。" },
    { k: "极意·缩地 (A)", d: "缩地的极致。一步踏出，视觉上如同瞬间移动，能瞬间跨越几十米的距离突入敌人怀中。" },
    { k: "极意·无明剑 (A)", d: "舍弃了视觉后练就的绝技。在极端的黑暗或被致盲状态下，剑术的威力与精准度反而会大幅提升。" },
    { k: "极意·燕飞 (A)", d: "从不可思议的角度斩出的变幻之剑，专门用于破解敌人的防御架势和反击格挡。" },
    { k: "礼装·死海文书残卷", d: "记载着神代末期知识的羊皮纸残片。携带时对天使和高级灵体有微弱的威慑力。" },
    { k: "礼装·防弹法衣", d: "圣堂教会代行者的制式服装。表面编织了防护概念，连大口径狙击枪的子弹都能轻易弹开。" },
    { k: "礼装·灰锁", d: "教会的异端审问官常用的拘束武装。能将触碰到的“罪人”的魔术回路强制锁死。" },
    { k: "礼装·阿特拉斯的契约书", d: "拥有此物，你可以向阿特拉斯院提出一个不过分的请求（如鉴定古代兵器），他们必须履行。" },
    { k: "礼装·苍崎的橘子", d: "一颗看似普通的橘子，吃下后能在一个小时内让你的魔术回路全开，无视痛觉。过后会虚脱三天。" },
    { k: "礼装·卢恩石碑 (仿)", d: "刻有北欧原初卢恩的石块仿制品。只能使用一次，能释放出足以夷平一座山丘的魔力风暴。" },
    { k: "礼装·概念摘出器", d: "时钟塔创造科的奇特发明。能将极小范围内的某种“概念”（如“湿润”、“热”）暂时吸走。" },
    { k: "礼装·时间胶囊", d: "彷徨海流出的道具。能将自身或某件物品的时间倒流回10秒前，是逆转生死的极品保命道具。" },
    { k: "礼装·魔术师的烟斗", d: "抽这根烟斗时，吐出的烟雾能够自动搜寻周围的陷阱和生命体，持续几分钟。" },
    { k: "礼装·所罗门戒指 (赝品)", d: "能够让你暂时听懂并号令低阶的恶魔和灵体。但如果遇到高阶恶魔，会被反噬。" },
    { k: "礼装·妖精之丝", d: "用妖精的头发编织的隐形斗篷。披上后不仅能遮断气息，连物理光线都能完全折射，实现隐身。" },
    { k: "礼装·时钟塔正装", d: "代表高级魔术师身份的礼服。材质能大幅提升魔术抗性，并在协会内部获得极高的社交特权。" },
    { k: "礼装·鲜血小瓶", d: "装有某位高阶死徒鲜血的瓶子。饮下可暂时获得超越人类的恢复力和怪力，但有极高的尸骨化风险。" },
    { k: "礼装·替身护符 (玉藻)", d: "东洋产的咒术护符。在受到致命一击时，护符会化为你的模样替死，但面对大范围攻击无效。" },
    { k: "礼装·龙牙兵之种", d: "随身携带的十几颗龙牙。播撒在地上并注入魔力后，能召唤出不知疲倦的骷髅兵为你作战。" },
    { k: "礼装·记忆的香囊", d: "闻到香味的人，会不可避免地陷入一生中最美好或最痛苦的记忆回溯中，暂时失去对现实的感知。" },
    { k: "礼装·裹尸布 (圣骸布异体)", d: "与基础圣骸布不同，这是一条能够包裹全身的长布。披上后能完全隔绝一切对魔力、诅咒的探知。" },
    { k: "礼装·封印指定之匣", d: "一个异度空间的小盒子，能够强行将处于虚弱状态的魔物、灵体甚至魔术师封印在其中。" },
    { k: "礼装·概念武装 (斩裂)", d: "极度锋利的短刀，并非斩断物理，而是斩断“魔力连接”。是专门用来破坏结界和解除使魔契约的武装。" },
    { k: "礼装·恶魔契约书", d: "只要对方在上面签字或按下血手印，违背契约者将受到灵魂被撕裂的诅咒，连令咒也难以完全抵消。" },
    { k: "思想魔术 (八卦)", d: "东方思想键纹的运用者。通过八卦阵列引发自然现象的共鸣，擅长改变地貌和天气。" },
    { k: "炼丹术", d: "追求长生不老的东方炼金术。不擅长物质转化，但能炼制出各种永久性强化肉体或治愈暗疾的丹药。" },
    { k: "降灵术 (英灵借体)", d: "极其危险的尝试。将自身作为容器，勉强降下某位英灵极小一部分的力量，失败则肉体崩溃。" },
    { k: "妖精魔术", d: "并非控制妖精，而是向大自然中的妖精“借用”力量的魔术。效果极不稳定（全看妖精心情），但偶尔能引发奇迹。" },
    { k: "宝石魔术 (芬恩派)", d: "不注重宝石的爆炸，而是利用宝石特有的光谱和折射率，施展幻觉、催眠和精神控制的美学魔术。" },
    { k: "镜面界魔术", d: "能够通过镜子进入现实的倒影世界。在镜面界中发生的破坏不会影响现实，是绝佳的隐秘战场。" },
    { k: "空间魔术 (转移)", d: "掌握了极小规模的空间转移。能在视距内进行短距离的瞬移，但每次都需要精确的坐标计算和庞大的魔力。" },
    { k: "结界魔术 (固有结界残篇)", d: "你触及了心象风景具现化的边缘。虽然无法展开完整的固有结界，但能短暂让周围的物理法则发生小幅异变。" },
    { k: "时间魔术 (停滞)", d: "时钟塔天体科的秘术。能让极小范围（如一个苹果、一个伤口）的时间陷入短暂的绝对静止。" },
    { k: "灵魂干涉魔术", d: "能够直接对目标的灵魂进行“触碰”。虽然无法夺舍，但能借此探知对方的起源、本质或灵魂上的创伤。" },
    { k: "蛊毒之术", d: "通过让复数毒虫相互吞噬，培养出极其凶恶的“蛊”。被蛊附身的人会成为你的傀儡或凄惨死去。" },
    { k: "纸舞术", d: "阴阳道的一种。将普通的纸张折叠后赋予魔力，化为锐利的刀刃或成群飞舞的侦察使魔。" },
    { k: "诅咒·丑时参拜", d: "极其古老且阴毒的诅咒。需要对方的头发或体液，连续七天在半夜钉草人。一旦完成，必死无疑，但极易被反噬。" },
    { k: "诅咒·死相附体", d: "你的魔术能让敌人的“死期”提前。一旦被你的死相诅咒缠上，对手遭遇各种意外事故的概率会呈指数级上升。" },
    { k: "灵肉剥离魔术", d: "专门针对附身者或降灵术的破解魔术。能强行将被附身的灵体或恶魔从肉体中抽离出来。" },
    { k: "恶魔学", d: "你深入研究过所罗门七十二柱魔神及各种恶魔。知道如何与它们谈判、交易而不被立刻吞噬灵魂。" },
    { k: "梦魇契约", d: "你与梦魇签订了契约。能够在梦境中自由穿梭，在对方的潜意识中植入暗示，或吸食他人的精神力。" },
    { k: "影之魔术 (操作)", d: "能够将自己的影子实体化为触手或利刃进行攻击，也能潜入二维的阴影中移动，极具隐蔽性。" },
    { k: "鲜血魔术", d: "以大量鲜血为代价的禁忌术式。能将血液化为沸腾的酸液、坚固的结晶盾牌或爆炸物。" },
    { k: "咒体化", d: "主动让某种强大的诅咒寄宿在自己体内。虽然身体会异化并时刻承受痛苦，但能获得对应诅咒特性的诡异能力。" },
    { k: "第八秘迹会成员", d: "你是专门负责回收圣遗物的教会组织成员。你拥有极高的搜查权限，以及面对任何魔术师都毫不退缩的狂热。" },
    { k: "幸运 (A)", d: "你被幸运女神眷顾。即使闭着眼睛开枪也能打中敌人的要害，在绝境中总能遇到极其离谱的巧合来拯救你。" },
];
(function(){
    const rollGridElement = document.getElementById(''roll-grid'');
    const doRollButton = document.getElementById(''do-roll'');
    const clearPicksButton = document.getElementById(''clear-picks'');
    const pickCountElement = document.getElementById(''pick-count'');
    const selectedPicks = new Set();
    function renderRollCards(itemList) {
        rollGridElement.innerHTML = "";
        itemList.forEach(itemData => {
            const cardElement = document.createElement("div");
            cardElement.className = "roll-card";
            cardElement.innerHTML = `
                <div class="roll-card-title">${itemData.k}</div>
                <div class="roll-card-desc">${itemData.d}</div>
            `;
            cardElement.addEventListener("click", () => {
                if (cardElement.classList.contains("active")) {
                    cardElement.classList.remove("active");
                    selectedPicks.delete(itemData.k);
                } else {
                    if (selectedPicks.size >= 2) return;
                    cardElement.classList.add("active");
                    selectedPicks.add(itemData.k);
                }
                pickCountElement.textContent = selectedPicks.size;
            });
            rollGridElement.appendChild(cardElement);
        });
    }
    function rollNewItems() {
        const poolCopy = [...ROLL_POOL];
        const resultList = [];
        for (let i = 0; i < 10; i++) {
            if(poolCopy.length === 0) break;
            const randomIndex = Math.floor(Math.random() * poolCopy.length);
            resultList.push(poolCopy.splice(randomIndex, 1)[0]);
        }
        selectedPicks.clear();
        pickCountElement.textContent = "0";
        renderRollCards(resultList);
    }
    doRollButton.addEventListener("click", rollNewItems);
    clearPicksButton.addEventListener("click", () => {
        selectedPicks.clear();
        pickCountElement.textContent = "0";
        rollGridElement.querySelectorAll(".roll-card.active").forEach(card => {
            card.classList.remove("active");
        });
    });
    rollNewItems();
    window.__ROLL_EXPORT__ = () => ({
        selected: [...selectedPicks],
        custom: (document.getElementById(''custom-talent'').value || "").trim()
    });
})();
(function(){
    const profileOutput = document.getElementById("profile-merge");
    const buildButton = document.getElementById("build-profile");
    const copyButton = document.getElementById("copy-profile");
    const randomDefaults = {
        姓名: ["随机"],
        起源: ["随机"],
        性格: ["利己主义", "人善", "伪恶", "冷静沉着", "胆小", "傲娇"]
    };
    const getRandomItem = (array) => array[Math.floor(Math.random() * array.length)];
    function getValue(id, defaultValues = null) {
        const element = document.getElementById(id);
        const value = element %s element.value.trim() : "";
        if (value) {
            return value;
        }
        return defaultValues %s getRandomItem(defaultValues) : "";
    }
    function getSelectedWorld() {
        const checkedRadio = document.querySelector(''input[name="entry-world"]:checked'');
        if (!checkedRadio) {
            return "未选择";
        }
        if (checkedRadio.id === ''pick-custom'') {
            const customEntry = document.getElementById(''custom-timeline-entry'');
            const customText = customEntry %s customEntry.value.trim() : "";
            return customText %s `自定义: ${customText}` : "自定义 (未填写)";
        } else {
            const card = checkedRadio.closest(''.timeline-card'');
            if (card) {
                const title = card.querySelector(''h4'')%s.textContent.trim() || "";
                const description = card.querySelector(''p'')%s.textContent.trim() || "";
                return `【${title}】\n${description}`;
            }
            return checkedRadio.value; // Fallback
        }
    }
    function buildProfileText() {
        const profileData = {
            姓名: getValue(''p-name'', randomDefaults.姓名),
            性别: getValue(''p-gender'') || "未指定",
            年龄: getValue(''p-age'') || "19",
            外貌: getValue(''p-look'') || "普通，无明显特征",
            体型: getValue(''p-body'') || "中等",
            起源: getValue(''p-origin'', randomDefaults.起源),
            ''魔术回路·量'': getValue(''p-circuit-quantity''),
            ''魔术回路·质'': getValue(''p-circuit-quality''),
            性格: getValue(''p-persona'', randomDefaults.性格),
            魔术师准则: getValue(''p-creed'') || "明哲保身",
            梦想: getValue(''p-dream'') || "平静地生活下去",
            出身: getValue(''p-birth'') || "三流魔术家系末裔",
        };
        const entryPointText = getSelectedWorld();
        const rollData = window.__ROLL_EXPORT__ %s window.__ROLL_EXPORT__() : { selected: [], custom: '''' };
        const selectedTalentKeys = rollData.selected || [];
        const customTalentText = rollData.custom;
        let lines = [];
        lines.push("================= MAGUS PROFILE =================");
        Object.entries(profileData).forEach(([key, value]) => lines.push(`${key}: ${value}`));
        lines.push("-------------------------------------------------");
        lines.push("世界切入点：");
        lines.push(entryPointText);
        lines.push("-------------------------------------------------");
        lines.push("天赋/礼装/刻印：");
        let talentsText = selectedTalentKeys.map(key => {
            const talentObject = ROLL_POOL.find(t => t.k === key);
            return talentObject %s `- 【${talentObject.k}】\n  ${talentObject.d}` : `- ${key}`;
        }).join("\n\n");
        if (customTalentText) {
            if (talentsText) talentsText += "\n\n";
            talentsText += `- 【自定义】\n  ${customTalentText}`;
        }
        if (!talentsText) {
            lines.push("（未选择）");
        } else {
            lines.push(talentsText);
        }
        const notes = getValue(''p-notes'');
        if (notes) {
            lines.push("-------------------------------------------------");
            lines.push("补充说明：\n" + notes);
        }
        lines.push("=================================================");
        profileOutput.textContent = lines.join(''\n'');
    }
    if (buildButton) buildButton.addEventListener("click", buildProfileText);
  if (copyButton) copyButton.addEventListener("click", () => {
        if (!profileOutput.textContent.trim()) {
            buildProfileText();
        }
        navigator.clipboard.writeText(profileOutput.textContent)
            .then(() => alert("档案已复制到剪贴板！"))
            .catch(err => {
                try {
                    const textArea = document.createElement(''textarea'');
                    textArea.value = profileOutput.textContent;
                    textArea.style.position = ''fixed'';
                    textArea.style.top = ''0'';
                    textArea.style.left = ''0'';
                    textArea.style.opacity = ''0'';
                    document.body.appendChild(textArea);
                    textArea.focus();
                    textArea.select();
                    const successful = document.execCommand(''copy'');
                    document.body.removeChild(textArea);
                    if(successful) {
                        alert("档案已复制到剪贴板！(兼容模式)");
                    } else {
                        alert("复制失败，请手动复制。");
                    }
                } catch (e) {
                    alert("复制失败: " + e);
                }
            });
    });
})();
