  var playerAppearance = document.getElementById(''playerAppearance'');
  var playerPersonality= document.getElementById(''playerPersonality'');
  var playerDick       = document.getElementById(''playerDick'');
  var playerOther      = document.getElementById(''playerOther'');

  var openingList   = document.getElementById(''openingList'');
  var customOpening = document.getElementById(''customOpening'');
  var generateBtn   = document.getElementById(''generateBtn'');
  var summaryContent= document.getElementById(''summaryContent'');
  var copyBtn       = document.getElementById(''copyBtn'');
  var toast         = document.getElementById(''toast'');
  var hiddenCopyArea= document.getElementById(''hiddenCopyArea'');

  /* ---------- 状态 ---------- */
  var selectedOpeningIndex = 0;      /* 0-4 内置开场白，-1 表示自定义 */
  var openings = [
    ''放学铃响过半小时，你折返回教室拿忘带的课本。刚推开后门，就看见你的清冷校花同桌姜晚晴半跪在讲台边，包臀裙撩到腰上，一根手指正深深插在粉嫩的白虎蜜穴里，你推门的声音在寂静的教室里格外清晰。'',
    ''第二节课间，姜晚晴起身去接水。她今天穿了件宽松的白色衬衣，弯腰接水的瞬间，领口大敞，你清晰地看到那对饱满H罩杯巨乳沉甸甸的弧度，以及顶端两粒粉嫩挺立的乳头，她完全没穿内衣。'',
