.progress-bar { width: 300px; height: 6px; background: var(--border); border-radius: 3px; overflow: hidden; position: relative; }
.progress-fill { height: 100%; background: linear-gradient(90deg, var(--primary), var(--secondary)); border-radius: 3px; animation: loading 2s ease-in-out forwards; box-shadow: 0 0 10px var(--primary-glow); }
.skip-btn { margin-top: 2rem; padding: 0.8rem 2rem; background: transparent; border: 2px solid var(--primary); color: var(--primary); border-radius: 25px; cursor: pointer; font-size: 1rem; transition: all 0.3s; }
.skip-btn:hover { background: var(--primary); color: white; box-shadow: 0 0 20px var(--primary-glow); }
@keyframes loading { 0% { width: 0%; } 100% { width: 100%; } }
