div.flex.flex-col.border-gray-200:is(.dark *){border-color:#3a3427!important}
div.bg-gray-100.text-gray-500:is(.dark *){background:#2a251c!important;color:#8f8878!important}
div.cursor-pointer.group.flex.items-center.justify-center:hover:is(.dark *){background:rgba(212,169,74,0.14)!important;color:#d4a94a!important}
div[data-state="closed"] svg[data-icon="Send03"]:is(.dark *){fill:#d4a94a!important}
div.style_divider__mW0YX:is(.dark *){border-top-color:#3a3427!important;border-bottom-color:#3a3427!important}
div.style_divider__mW0YX:is(.dark *)::after{background:#17140e!important;color:#d4a94a!important}
.MuiStack-root.css-1dmzxoz:is(.dark *){color:#8f8878!important}
