    var d=document.createElement(''div'');
    d.className=''ch''+(i===0%s'' on'':'''');
    d.textContent=txt;
    d.onclick=function(){
      document.querySelectorAll(''#tk-wv .ch'').forEach(function(x){x.classList.remove(''on'')});
      this.classList.add(''on'');
    };
    wvc.appendChild(d);
  });
  var idc=document.getElementById(''tk-id-chips'');
  tkIds.forEach(function(txt){
    var d=document.createElement(''div'');
    d.className=''ch'';
    d.textContent=txt;
    d.onclick=function(){
      document.querySelectorAll(''#tk-id-chips .ch'').forEach(function(x){x.classList.remove(''on'')});
      this.classList.add(''on'');
      document.getElementById(''tk-f-id'').value=txt;
    };
    idc.appendChild(d);
  });
  var lkc=document.getElementById(''tk-look-chips'');
  tkLooks.forEach(function(txt){
    var d=document.createElement(''div'');
    d.className=''ch'';
    d.textContent=txt;
    d.onclick=function(){
      document.querySelectorAll(''#tk-look-chips .ch'').forEach(function(x){x.classList.remove(''on'')});
      this.classList.add(''on'');
      document.getElementById(''tk-f-look'').value=txt;
    };
    lkc.appendChild(d);
  });
  tkLenUpd();tkCupUpd();
}
function tkGen(){
  var v=function(id,d){var e=document.getElementById(id);return (e&&e.value.trim())||d;};
  var fn=v(''tk-f-name'',''陈默'');
  var fa=v(''tk-f-age'',''24'');
  var fid=v(''tk-f-id'',''普通社畜，存在感稀薄'');
  var flook=v(''tk-f-look'',''平平无奇，扔进人堆就找不到'');
  var flen=(document.getElementById(''tk-f-len'')||{}).value||''16'';
  var cup=tkCups[(parseInt((document.getElementById(''tk-f-cup'')||{}).value,10)||4)-1];
  var wvCustom=v(''tk-f-wvc'','''');
  var wvSel=document.querySelector(''#tk-wv .ch.on'');
  var wv=wvCustom||(wvSel%swvSel.textContent:''现代都市'');
  var fscene=v(''tk-f-scene'','''');
  var gout=tkG;
  if(tkG===''自定义''){ gout=v(''tk-f-gcustom'',''不明''); }
  var lines=[
    ''【我 · 词条修改异能持有者】'',
    ''姓名:''+fn,
    ''性别:''+gout,
    ''年龄:''+fa,
    ''身份:''+fid,
    ''外貌:''+flook
  ];
  if(tkG===''男''){ lines.push(''肉棒长度:''+flen+''cm''); }
  else if(tkG===''女''){ lines.push(''罩杯:''+cup); }
  else if(tkG===''扶他''){ lines.push(''罩杯:''+cup); lines.push(''肉棒长度:''+flen+''cm''); }
  lines.push(
    '''',
    ''【世界观】'',
    wv,
    '''',
    ''【开局场景】'',
    fscene||''未指定——请按世界观切入'',
    '''',
    ''【系统初始】'',
    ''今日可改:1 字（每性交一个新对象，每日上限+1）'',
    ''已性交:0 人'',
    '''',
    ''描写玩家开始觉醒异能，切入具体生动的场景''
  );
  var box=document.getElementById(''tk-out'');
  box.value=lines.join(''\n'');
  document.getElementById(''tk-out-wrap'').style.display=''block'';
  setTimeout(function(){box.scrollIntoView({behavior:''smooth'',block:''center''})},80);
}
function tkCopy(){
  var box=document.getElementById(''tk-out'');
  var text=box.value;
  var btn=document.getElementById(''tk-copy'');
  function ok(){btn.textContent=''✓ 已复制 · 去粘贴'';setTimeout(function(){btn.textContent=''复 制 · 粘 到 聊 天''},2000)}
  function fb(){
    box.select();box.setSelectionRange(0,99999);
    try{document.execCommand(''copy'');ok()}
    catch(e){
      try{window.parent.postMessage({type:''copy'',text:text},''*'');ok()}
      catch(e2){alert(''请手动选中文本并复制'')}
    }
  }
  if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(text).then(ok).catch(fb);}
  else{fb();}
}
function tkObs(){
  var els=[].slice.call(document.querySelectorAll(''.reveal''));
  function showAll(){els.forEach(function(el){el.style.transition=''none'';el.style.opacity=''1'';el.style.transform=''none'';});}
  if(!(''IntersectionObserver'' in window)){showAll();return;}
  var io=new IntersectionObserver(function(entries){
    entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add(''in'');io.unobserve(e.target);}});
  },{threshold:.05,rootMargin:''0px 0px -4% 0px''});
  els.forEach(function(el){io.observe(el)});
  setTimeout(showAll,900);
}
if(document.readyState===''loading''){
  document.addEventListener(''DOMContentLoaded'',function(){tkInit();tkObs();});
}else{tkInit();tkObs();}
</script>
</body>
</html>
