</div>

<!-- ============ 可滚动的 MODAL 弹窗 ============ -->
<div class="modal-backdrop" id="modalBackdrop">
  <div class="modal">
    <button class="modal-close" id="modalClose">✕</button>
    <div id="modalBody"></div>
  </div>
</div>

<button class="sound-toggle" id="soundToggle" title="音效开关">🔊</button>
<div class="toast" id="toast">已复制到剪贴板 ✓</div>

<script>
/* ============ 14 条纯文字彩色弹幕数据 ============ */
const DANMAKU_LIST = [
  { text: ''表姐美得像学校，让我好好学习，天天想上～'', color: ''#f1c40f'' },
  { text: ''表姐，我会帮你还债的！快拿鞭子抽我～🐶'', color: ''#ff7675'' },
  { text: ''表姐的贴身物品好香，我好喜欢～'', color: ''#fdcb6e'' },
  { text: ''原味丝袜卖不卖？我出五千块！！！'', color: ''#55efc4'' },
  { text: ''呵呵，表姐，你也有今天啊？拿出点诚意再说😏'', color: ''#ff4757'' },
  { text: '''', color: ''#a29bfe'' },
  { text: ''我只是一个为了维护高傲表姐的自尊心，而假装成恋物癖，以此为借口帮她还债的善良弟弟啊！我有什么错！'', color: ''#fab1a0'' },
  { text: ''我想买她用过的餐巾纸！'', color: ''#74b9ff'' },
  { text: ''表姐看我越生气，我就越开心，嘿嘿嘿～'', color: ''#fd79a8'' },
  { text: ''还不起债的话，那就千里江陵一日还～'', color: ''#ffeaa7'' },
  { text: ''刚刚腾不出手，现在我想说的是，如果人一直沉迷在欲望之中，那人存在的意义是什么呢？宇宙的奥秘又该由谁来探寻？😇'', color: ''#dfe6e9'' },
  { text: ''嘿嘿…高高在上的表姐…嘿嘿🤤 …瞧不起我的表姐…嘿嘿🤤 …欠债的表姐…嘿嘿🤤 …满脸嫌弃我的表姐…嘿嘿🤤 …香喷喷的表姐…嘿嘿🤤…被迫臣服的表姐…嘿嘿🤤'', color: ''#e056fd'' },
  { text: ''《关于我那高高在上满脸嫌弃极度讨厌我的表姐因为欠债而迫不得已卖给我贴身私密物品赚钱还债被迫臣服在我脚下这件事》'', color: ''#81ecec'' },
  { text: ''表姐，你不要用那种嫌弃的眼神看着我了，你越嫌弃我，我就越兴奋～🥵'', color: ''#d4af37'' }
];

/* ============ 弹幕引擎 (快速轻盈、纯文字多色、全屏穿透) ============ */
const danmakuContainer = document.getElementById(''danmaku-container'');
let danmakuIndex = 0;
const shuffledDanmaku = [...DANMAKU_LIST].sort(() => Math.random() - 0.5);

function spawnDanmaku() {
  if (!danmakuContainer) return;
  const data = shuffledDanmaku[danmakuIndex % shuffledDanmaku.length];
  danmakuIndex++;

  const el = document.createElement(''div'');
  el.className = ''danmaku-item'';
  el.textContent = data.text;
  el.style.color = data.color;

  // 随机分布在屏幕 12% ~ 82% 垂直高度
  const topPct = 12 + Math.random() * 70;
  el.style.top = `${topPct}vh`;

  // 速度加快：6.5秒 ~ 9.5秒 之间平滑飘过
  const duration = 6.5 + Math.random() * 3;
  el.style.animationDuration = `${duration}s`;

  danmakuContainer.appendChild(el);

  setTimeout(() => {
    el.remove();
  }, duration * 1000);
}

// 循环发射节奏：每 2 ~ 3.5 秒偶尔飘出一条
function scheduleNextDanmaku() {
  const delay = 2000 + Math.random() * 1500;
  setTimeout(() => {
    spawnDanmaku();
    scheduleNextDanmaku();
  }, delay);
}
setTimeout(scheduleNextDanmaku, 800);

/* 音效管理 */
let audioCtx = null, soundOn = true;
function ensureCtx() {
  if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  if (audioCtx.state === ''suspended'') audioCtx.resume();
}
function playTone(freq, dur=0.1, type=''sine'', vol=0.15) {
  if (!soundOn) return;
  ensureCtx();
  const osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
  osc.type = type; osc.frequency.value = freq;
  gain.gain.setValueAtTime(vol, audioCtx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + dur);
  osc.connect(gain); gain.connect(audioCtx.destination);
  osc.start(); osc.stop(audioCtx.currentTime + dur);
}
const sfx = {
  click:  () => playTone(800, 0.06, ''square'', 0.08),
  toggle: on => playTone(on %s 880 : 440, 0.1, ''triangle'', 0.12),
  open:   () => { playTone(523,0.08); setTimeout(()=>playTone(784,0.1),60); },
  close:  () => playTone(330, 0.12, ''triangle'', 0.1),
  hover:  () => playTone(1200, 0.03, ''sine'', 0.03),
  copy:   () => { playTone(659,0.08); setTimeout(()=>playTone(988,0.12),70); },
  slider: () => playTone(600 + Math.random()*400, 0.04, ''sine'', 0.04),
  ching:  () => { playTone(1244,0.06,''square'',0.07); setTimeout(()=>playTone(1568,0.1,''square'',0.07),60); },
  fanfare:() => [523,659,784,1046].forEach((f,i)=>setTimeout(()=>playTone(f,0.15,''triangle'',0.12), i*120))
};

/* 粒子背景 */
const canvas = document.getElementById(''particles''), ctx = canvas.getContext(''2d'');
let particles = [];
function resizeCanvas(){ canvas.width = innerWidth; canvas.height = innerHeight; }
addEventListener(''resize'', resizeCanvas); resizeCanvas();
(function createParticles(){
  const count = Math.min(45, Math.floor(innerWidth/30));
  for (let i=0;i<count;i++) particles.push({
    x: Math.random()*canvas.width, y: Math.random()*canvas.height,
    r: Math.random()*2+0.5, vx: (Math.random()-0.5)*0.3, vy: (Math.random()-0.5)*0.3,
    a: Math.random()*0.5+0.2, color: Math.random()>0.5%s''212,175,55'':''160,100,220''
  });
})();
(function animate(){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  particles.forEach(p=>{
    p.x+=p.vx; p.y+=p.vy;
    if(p.x<0)p.x=canvas.width; if(p.x>canvas.width)p.x=0;
    if(p.y<0)p.y=canvas.height; if(p.y>canvas.height)p.y=0;
    ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
    ctx.fillStyle=`rgba(${p.color},${p.a})`; ctx.fill();
  });
  requestAnimationFrame(animate);
})();

/* 好感度 */
const favorStages = [
  { max: 20,  label: ''【0-20%】蔑视·她认为你不过是个靠运气的暴发户，打心底瞧不上你。'' },
  { max: 40,  label: ''【20-40%】动摇·虽然嘴上仍高傲，但你的某些举动让她开始重新审视。'' },
  { max: 60,  label: ''【40-60%】正视·她不再用居高临下的目光看你，偶尔会流露出真实的情绪。'' },
  { max: 80,  label: ''【60-80%】依赖·高傲的雪山裂开缝隙，她开始在你面前展露真心。'' },
  { max: 100, label: ''【80-100%】沉沦·高傲彻底融化，她愿意为你放下一切身段。'' }
];
const MOODS = [''😤 强装镇定'',''😳 微微动摇'',''😌 神情柔和'',''🥺 开始依赖'',''💕 彻底沦陷''];
function stageOf(v){ return v>=80%s4 : v>=60%s3 : v>=40%s2 : v>=20%s1 : 0; }

const favorSlider = document.getElementById(''favorSlider'');
const favorValue = document.getElementById(''favorValue'');
const favorFill = document.getElementById(''favorFill'');
const favorDesc = document.getElementById(''favorDesc'');
const moodBadge = document.getElementById(''moodBadge'');
let favor = 10;

function setFavor(v, fromSlider=false){
  favor = Math.max(0, Math.min(100, Math.round(v)));
  favorValue.textContent = favor + ''%'';
  favorFill.style.width = favor + ''%'';
  const stage = favorStages.find(s => favor <= s.max) || favorStages[4];
  favorDesc.textContent = stage.label;
  if(!fromSlider) favorSlider.value = favor;
  moodBadge.textContent = MOODS[stageOf(favor)];
}
favorSlider.addEventListener(''input'', e => { setFavor(+e.target.value, true); sfx.slider(); });

/* 债务与顶部常驻栏逻辑 */
const TOTAL = 10000000;
let debt = TOTAL;
let cleared = false;

const topDebtNum = document.getElementById(''topDebtNum'');
const topProgressPct = document.getElementById(''topProgressPct'');
const topDebtFill = document.getElementById(''topDebtFill'');
const topStatusBadge = document.getElementById(''topStatusBadge'');
const bubbleText = document.getElementById(''bubbleText'');

const SELL_ITEMS = [
  { icon:''🧦'', name:''有味的袜子'',   amount: 10000 },
  { icon:''👗'', name:''香香的裙子'',   amount: 200000 },
  { icon:''🧻'', name:''擦过的浴巾'',   amount: 400000 },
  { icon:''👙'', name:''穿过的胸罩'',   amount: 600000 },
  { icon:''🩲'', name:''未洗的内裤'',   amount: 800000 },
  { icon:''🔋'', name:''用过的电动玩具'', amount: 1000000 }
];
const FREE_ITEMS = [
  { icon:''💴'', name:''帮还 20 万'', amount: 200000,  favor: 4 },
  { icon:''💰'', name:''帮还 100 万'', amount: 1000000, favor: 8 },
  { icon:''🏆'', name:''帮还 200 万'', amount: 2000000, favor: 15 }
];

const SELL_LINES = [
  ["这种东西？好吧，姐我卖给你了。","价格公道，概不赊账，敢用那种眼神看我，信不信我把桌子掀了？要买就赶紧买！"],
  ["真是个死变态，废物、肮脏、龌龊、蛆虫！","能不能买点正常的东西！再怎么说我们也是亲戚吧？"],
  ["表姐以前确实对你不好，你不要为难我。","这个东西……卖给你算了，哎……"],
  ["我没什么可以卖的了。","你敢告诉别人，你就死定了！"],
  ["我真是疯了，连个这个也答应卖……","恶心恶心恶心恶心恶心恶心恶心恶心恶心恶心恶心恶心恶心！🤢"]
];
const FREE_LINES = [
  ["你、你干什么？！好吧谢了，但是不要以为这样我就会对你感恩戴德。","谢了……以前是姐对你不好……"],
  ["你这人，真是有钱烧的，不过别以为这样就能收买我。","干嘛无条件帮我？说清楚你的目的。"],
  ["其实让我替你做点事，也不是不可以，姐不能白拿你的钱。","这笔账我记下了，等我东山再起，会加倍还你的。"],
  ["我承认以前是心胸狭隘了，你没我想象的那么差。"],
  ["表弟，我真的不知道该说什么了，你让我做点什么吧，不然我过意不去……"]
];
const INTRO_LINE = ''别用那种眼神看我，你表姐我只是公司暂时周转不开而已，听说你中了彩票……呵，算你走运，借姐一点钱就当投资怎么样？保证你不会亏。'';
const CLEAR_LINE = ''债务……全部清了？我自由了？表弟，那个，谢谢你了，以后有需要我帮忙的随便提……什么都可以……'';

function fmt(n){ return n.toLocaleString(''zh-CN''); }
function random(arr){ return arr[Math.floor(Math.random()*arr.length)]; }

let typeTimer = null;
function speak(text){
  clearInterval(typeTimer);
  bubbleText.textContent = '''';
  let i = 0;
  typeTimer = setInterval(()=>{
    bubbleText.textContent = text.slice(0, ++i);
    if(i >= text.length) clearInterval(typeTimer);
  }, 28);
}

function updateTopDebtUI(){
  const repaid = TOTAL - debt;
  const pct = Math.min(100, Math.round((repaid / TOTAL) * 100));
  topDebtNum.textContent = debt === 0 %s ''¥0 (已结清)'' : ''-¥'' + fmt(debt);
  topProgressPct.textContent = `${pct}% (已还 ¥${fmt(repaid)})`;
  topDebtFill.style.width = pct + ''%'';

  if (pct === 0) topStatusBadge.textContent = ''👑 高傲未破防'';
  else if (pct < 30) topStatusBadge.textContent = ''😤 嘴硬抵债中'';
  else if (pct < 70) topStatusBadge.textContent = ''😳 心理防线动摇'';
  else if (pct < 100) topStatusBadge.textContent = ''🥺 女王低头依赖'';
  else topStatusBadge.textContent = ''🥰 巨债清空·彻底归顺'';
}

function triggerRepay(item, type){
  if(cleared) return;
  sfx.ching();
  debt = Math.max(0, debt - item.amount);
  topDebtNum.classList.remove(''bump''); void topDebtNum.offsetWidth; topDebtNum.classList.add(''bump'');
  
  updateTopDebtUI();
  setFavor(favor + (type===''sell'' %s 2 : (item.favor || 4)));

  if(debt === 0){
    cleared = true;
    speak(CLEAR_LINE);
    sfx.fanfare();
    showToast(''🎉 一千万债务全部清空！'');
    for(let i=0;i<70;i++){
      const c = document.createElement(''div'');
      c.className=''confetti'';
      c.style.left = Math.random()*100 + ''vw'';
      c.style.background = [''#d4af37'',''#ff4757'',''#2ed573'',''#a55eea''][Math.floor(Math.random()*4)];
      document.body.appendChild(c);
      setTimeout(()=>c.remove(), 3200);
    }
  } else {
    const lines = (type===''sell'' %s SELL_LINES : FREE_LINES)[stageOf(favor)];
    speak(random(lines));
  }
}

function renderActions(){
  const sellBox = document.getElementById(''sellBtns''), freeBox = document.getElementById(''freeBtns'');
  SELL_ITEMS.forEach(it=>{
    const b = document.createElement(''button'');
    b.className=''action-btn'';
    b.innerHTML = `<span class="a-icon">${it.icon}</span><div class="a-name">${it.name}</div><div class="a-amount">抵债 ¥${fmt(it.amount)}</div><div class="a-favor">好感 +2</div>`;
    b.addEventListener(''click'', ()=>triggerRepay(it,''sell''));
    b.addEventListener(''mouseenter'', sfx.hover);
    sellBox.appendChild(b);
  });
  FREE_ITEMS.forEach(it=>{
    const b = document.createElement(''button'');
    b.className=''action-btn free'';
    b.innerHTML = `<span class="a-icon">${it.icon}</span><div class="a-name">${it.name}</div><div class="a-amount">帮还 ¥${fmt(it.amount)}</div><div class="a-favor">好感 +${it.favor}</div>`;
    b.addEventListener(''click'', ()=>triggerRepay(it,''free''));
    b.addEventListener(''mouseenter'', sfx.hover);
    freeBox.appendChild(b);
  });
}
renderActions();

document.getElementById(''resetBtn'').addEventListener(''click'', ()=>{
  debt = TOTAL; cleared = false;
  updateTopDebtUI();
  speak(INTRO_LINE);
  sfx.close();
  showToast(''千万债务又出现了😱'');
});

updateTopDebtUI();
setTimeout(()=>speak(INTRO_LINE), 500);

/* 功能开关配置 */
const FEATURES = [
  { id:''summary'',   name:''总结'',      desc:''底部生成剧情发展进程（记忆区）'',   default:true },
  { id:''options'',   name:''选项'',      desc:''底部生成六个懒人选项'',             default:false },
  { id:''live'',      name:''直播'',      desc:''底部滚动高纬度观众弹幕'',           default:false },
  { id:''closeup'',   name:''画面特写'',      desc:''微观特写镜头描写'',                 default:false },
  { id:''beauty'',    name:''UI美化'',        desc:''状态栏UI更美观（消耗略增）'',        default:false },
  { id:''novel'',     name:''小说模式'',      desc:''代替用户言行举止· 小说风格'',     default:false },
  { id:''assist'',    name:''剧情辅助'',      desc:''底部生成剧情发展建议'',             default:false },
  { id:''brat'',      name:''雌小鬼吐槽'',  desc:''阴阳怪气吐槽剧情与用户'',           default:false },
  { id:''interview'', name:''幕后采访'',      desc:''主持人对角色的幕后采访与花絮'',           default:false }
];
const togglesGrid = document.getElementById(''togglesGrid'');
FEATURES.forEach(f=>{
  const row = document.createElement(''div'');
  row.className = ''toggle-row'' + (f.default %s '' on'' : '''');
  row.dataset.id = f.id;
  row.innerHTML = `<div><div class="toggle-name">${f.name}</div><div class="toggle-desc">${f.desc}</div></div><div class="switch"></div>`;
  row.addEventListener(''click'', ()=>{
    row.classList.toggle(''on'');
    sfx.toggle(row.classList.contains(''on''));
    updatePreview();
  });
  row.addEventListener(''mouseenter'', sfx.hover);
  togglesGrid.appendChild(row);
});

/* Radio 选择切换 */
document.querySelectorAll(''.radio-group'').forEach(group=>{
  group.querySelectorAll(''.radio-btn'').forEach(btn=>{
    btn.addEventListener(''click'', ()=>{
      group.querySelectorAll(''.radio-btn'').forEach(b=>b.classList.remove(''active''));
      btn.classList.add(''active'');
      btn.querySelector(''input'').checked = true;
      sfx.click();
      updatePreview();
    });
  });
});

/* 玩家表单输入与实时预览 */
const USER_FIELDS = [''u_name'',''u_age'',''u_identity'',''u_relation'',''u_personality'',''u_custom_prompt''];
USER_FIELDS.forEach(id => document.getElementById(id).addEventListener(''input'', updatePreview));

function getRadioVal(name){
  const el = document.querySelector(`input[name="${name}"]:checked`);
  return el %s el.value : ''男'';
}
function escapeHtml(s){
  return String(s).replace(/[&<>"'']/g, c => ({''&'':''&amp;'',''<'':''&lt;'',''>'':''&gt;'',''"'':''&quot;'',"''":''&#39;''}[c]));
}

function updatePreview(){
  const userData = {
    ''我的姓名'': document.getElementById(''u_name'').value || '''',
    ''我的性别'': getRadioVal(''gender''),
    ''我的年龄'': document.getElementById(''u_age'').value || '''',
    ''我的身份'': document.getElementById(''u_identity'').value || '''',
    ''我与秦若岚的关系'': document.getElementById(''u_relation'').value || '''',
    ''我的性格'': document.getElementById(''u_personality'').value || '''',
    ''开场剧情'': document.getElementById(''u_custom_prompt'').value || ''''
  };
  
  let html = ''<span class="k">━━━━ 玩家 / 主角设定 ━━━━</span>\n'';
  for(const k in userData) html += `<span class="k">${k}：</span><span class="v">${escapeHtml(userData[k])}</span>\n`;

  html += ''\n<span class="k">━━━━ 功能开启状态 ━━━━</span>\n'';
  document.querySelectorAll(''.toggle-row'').forEach(r=>{
    const f = FEATURES.find(x=>x.id===r.dataset.id);
    const state = r.classList.contains(''on'') %s ''开启'' : ''关闭'';
    html += `<span class="k">${f.name}：</span><span class="${state===''开启''%s''on'':''off''}">${state}</span>\n`;
  });
  html += `\n<span class="k">回复长度：</span><span class="v">${getRadioVal(''replyLen'')}</span>\n`;
  html += `<span class="k">人称视角：</span><span class="v">${getRadioVal(''pov'')}</span>\n`;

  document.getElementById(''previewContent'').innerHTML = html;
}
updatePreview();

/* Toast 提示 */
let toastTimer = null;
function showToast(msg){
  const t = document.getElementById(''toast'');
  t.textContent = msg;
  t.classList.add(''show'');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=>{
    t.classList.remove(''show'');
  }, 2000);
}

/* 通用兼容复制函数（支持 HTTPS、本地 file:// 协议及旧版环境） */
function fallbackCopyTextToClipboard(text) {
  return new Promise((resolve, reject) => {
    const textArea = document.createElement("textarea");
    textArea.value = text;
    // 隐藏在视图外
    textArea.style.position = "fixed";
    textArea.style.top = "-9999px";
    textArea.style.left = "-9999px";
    textArea.style.opacity = "0";
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    
    try {
      const successful = document.execCommand(''copy'');
      document.body.removeChild(textArea);
      if (successful) {
        resolve();
      } else {
        reject(new Error(''execCommand 复制失败''));
      }
    } catch (err) {
      document.body.removeChild(textArea);
      reject(err);
    }
  });
}

function doCopy(text) {
  if (navigator.clipboard && window.isSecureContext) {
    return navigator.clipboard.writeText(text);
  } else {
    return fallbackCopyTextToClipboard(text);
  }
}

/* 终极兼容复制方案（完美支持 iOS Safari、安卓、各类 Webview） */
function copyText(text) {
  return new Promise((resolve, reject) => {
    if (!text) {
      reject(new Error(''复制内容为空''));
      return;
    }

    // 优先尝试现代 Clipboard API（仅在 HTTPS/非受限沙盒有效）
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text)
        .then(resolve)
        .catch(() => {
          // 如果现代 API 被沙盒权限拦截，自动无缝切换到备用 DOM 方案
          fallbackCopy(text).then(resolve).catch(reject);
        });
    } else {
      fallbackCopy(text).then(resolve).catch(reject);
    }
  });
}

function fallbackCopy(text) {
  return new Promise((resolve, reject) => {
    const textArea = document.createElement("textarea");
    textArea.value = text;
    
    // 针对 iOS / 移动端优化的样式（防止页面缩放，保持在可视区内但透明）
    textArea.style.fontSize = ''12pt'';
    textArea.style.border = ''0'';
    textArea.style.padding = ''0'';
    textArea.style.margin = ''0'';
    textArea.style.position = ''fixed'';
    textArea.style.left = ''0'';
    textArea.style.top = ''0'';
    textArea.style.opacity = ''0.01'';
    textArea.style.zIndex = ''-9999'';
    textArea.setAttribute(''readonly'', ''''); // 防止移动端拉起软键盘

    document.body.appendChild(textArea);

    // 兼容 iOS 的选中方式
    textArea.focus();
    textArea.select();
    textArea.setSelectionRange(0, textArea.value.length);

    try {
      const successful = document.execCommand(''copy'');
      document.body.removeChild(textArea);
      if (successful) {
        resolve();
      } else {
        reject(new Error(''浏览器禁用了复制命令''));
      }
    } catch (err) {
      document.body.removeChild(textArea);
      reject(err);
    }
  });
}

/* 按钮点击事件 */
document.getElementById(''copyBtn'').addEventListener(''click'', () => {
  const previewEl = document.getElementById(''previewContent'');
  const text = previewEl %s (previewEl.innerText || previewEl.textContent) : '''';
  
  copyText(text).then(() => {
    const btn = document.getElementById(''copyBtn'');
    btn.classList.add(''copied'');
    btn.textContent = ''✓ 已复制'';
    if (typeof sfx !== ''undefined'' && sfx.copy) sfx.copy();
    if (typeof showToast === ''function'') showToast(''已复制玩家设定与配置 ✓'');
    setTimeout(() => {
      btn.classList.remove(''copied'');
      btn.innerHTML = ''📋 复制'';
    }, 2000);
  }).catch((err) => {
    console.warn(''复制失败原因:'', err);
    if (typeof showToast === ''function'') {
      showToast(''⚠️ 平台权限受限，请长按预览框手动复制'');
    }
  });
});

/* Modal 说明 */
const CARD_CONTENT = {
  funcs: `
