}
.scroll-paper::before {
  content: "";
  position: absolute;
  top: -10px;
  left: -10px;
  right: -10px;
  bottom: -10px;
  background: linear-gradient(45deg, 
    transparent 30%, 
    rgba(212, 175, 55, 0.1) 50%, 
