    color: var(--gold);
    font-size: 1.2rem;
    opacity: 0.5;
    top: auto; 
    transform: none; 
}
h1::before { 
}
h1::after { 
}
@media (max-width: 768px) {
    h1 {
        font-size: 1.8rem;
        letter-spacing: 3px;
    }
    h1::before { 
        left: calc(50% - 110px); 
    }
    h1::after { 
        right: calc(50% - 110px); 
    }
}
@media (max-width: 480px) {
    h1 {
        font-size: 1.5rem;
        letter-spacing: 2px;
    }
    h1::before { 
