    font-family: inherit;
    font-weight: bold;
}
.tab-btn:hover { color: var(--gold); }
.tab-btn.active {
    color: var(--gold);
    border: 1px solid var(--border-color);
    background: rgba(212, 175, 55, 0.05);
    box-shadow: 0 0 15px rgba(0,0,0,0.5);
}
