    padding: 12px 8px;
    text-align: center; 
    font-size: 0.9rem;
    cursor: pointer;
    transition: all 0.3s;
    position: relative;
    display: flex;
    flex-direction: column;
    justify-content: center; 
    align-items: center; 
    min-height: 60px;
}
.talent-card:hover {
    transform: translateY(-2px);
    z-index: 10;
    box-shadow: 0 5px 15px rgba(0,0,0,0.5);
}
.talent-card.selected {
    border-color: var(--gold);
    background: rgba(212, 175, 55, 0.15);
    box-shadow: 0 0 10px var(--gold);
}
.talent-card.locked {
    border-color: #ffcc00;
    background: rgba(255, 204, 0, 0.1);
    box-shadow: 0 0 15px rgba(255, 204, 0, 0.5);
}
.talent-card.locked.selected {
    border-color: #ffcc00;
    background: rgba(212, 175, 55, 0.25);
    box-shadow: 0 0 15px rgba(255, 204, 0, 0.5), 0 0 10px rgba(212, 175, 55, 0.5);
}
.lock-icon {
    position: absolute;
    top: 5px;
    right: 5px;
    font-size: 0.8rem;
    color: #666;
    transition: all 0.3s;
    z-index: 5;
    cursor: pointer;
    width: 18px;
    height: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(0,0,0,0.5);
    border-radius: 3px;
}
.lock-icon:hover {
    color: #ffcc00;
    transform: scale(1.2);
}
.talent-card.locked .lock-icon {
    color: #ffcc00;
    text-shadow: 0 0 5px rgba(255, 204, 0, 0.8);
}
.talent-name {
    font-weight: bold;
    width: 100%; 
    text-align: center; 
    padding: 0 5px; 
    box-sizing: border-box; 
}
.q-7 { 
    color: #ff3333; 
    text-shadow: 0 0 8px rgba(255, 51, 51, 0.7); 
    border-color: #990000 !important; 
    border-width: 1.5px !important;
}
.q-6 { 
    color: #ffaa00; 
    text-shadow: 0 0 6px rgba(255, 170, 0, 0.6); 
    border-color: #cc6600 !important;
    border-width: 1.5px !important;
}
.q-5 { 
    color: #ffcc00; 
    text-shadow: 0 0 5px rgba(212, 175, 55, 0.5); 
    border-color: #aa8c2c !important;
    border-width: 1.5px !important;
}
.q-4 { 
    color: #c770ff; 
    text-shadow: 0 0 5px rgba(163, 53, 238, 0.5); 
    border-color: #9933cc !important;
    border-width: 1.5px !important;
}
.q-3 { 
    color: #3399ff; 
    text-shadow: 0 0 5px rgba(0, 112, 221, 0.5); 
    border-color: #0066cc !important;
    border-width: 1.5px !important;
}
.q-2 { 
    color: #33ff33; 
    text-shadow: 0 0 5px rgba(30, 255, 0, 0.5); 
    border-color: #00aa00 !important;
    border-width: 1.5px !important;
}
.q-1 { 
    color: #cccccc; 
    text-shadow: 0 0 3px rgba(170, 170, 170, 0.3); 
    border-color: #666666 !important;
    border-width: 1.5px !important;
}
.tooltip-box {
    position: absolute;
    background: rgba(0, 0, 0, 0.95);
    border: 1px solid var(--gold);
    color: #ddd;
    padding: 10px;
    font-size: 0.85rem;
    width: 200px;
    z-index: 100;
    pointer-events: none;
    display: none;
    box-shadow: 0 0 20px rgba(0,0,0,0.8);
    border-radius: 4px;
    text-align: left;
    line-height: 1.4;
}
.tooltip-title { 
    color: var(--gold); 
    font-weight: bold; 
    margin-bottom: 5px; 
    display: block; 
    border-bottom: 1px solid #333; 
    padding-bottom: 3px;
}
.btn-action {
    background: linear-gradient(135deg, #8a7024, #d4af37);
    color: #050505;
    border: none;
    padding: 15px 30px;
    font-weight: bold;
    cursor: pointer;
    width: 100%;
    margin-top: 25px;
    font-size: 1.1rem;
    letter-spacing: 3px;
    transition: 0.3s;
    text-transform: uppercase;
    box-shadow: 0 5px 15px rgba(0,0,0,0.3);
    position: relative;
    overflow: hidden;
}
.btn-action::before {
    content: "";
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);
    transition: 0.5s;
}
.btn-action:hover::before {
    left: 100%;
}
.btn-action:hover {
    filter: brightness(1.2);
    transform: translateY(-2px);
    box-shadow: 0 0 20px var(--gold);
}
.btn-refresh {
    background: #222;
    border: 1px solid var(--gold);
    color: var(--gold);
    padding: 8px 15px;
    width: auto;
    margin-bottom: 15px;
    font-size: 0.9rem;
    display: inline-block;
    cursor: pointer;
}
.btn-refresh:hover { 
    background: var(--gold); 
    color: #000; 
}
.preview-box {
    background: #080808;
    border: 1px dashed var(--deep-gold);
    padding: 25px;
    margin-top: 40px;
    white-space: pre-wrap;
    font-size: 0.95rem;
    color: #ccc;
    line-height: 1.8;
    position: relative;
    font-family: "Courier New", monospace;
}
.preview-box::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: 
        url("data:image/svg+xml,%3Csvg width=''100'' height=''100'' xmlns=''http://www.w3.org/2000/svg''%3E%3Cpath d=''M0,50 Q25,40 50,50 Q75,60 100,50'' stroke=''rgba(212,175,55,0.05)'' fill=''none'' stroke-width=''2''/%3E%3C/svg%3E");
    background-size: 100px 100px;
    opacity: 0.3;
    pointer-events: none;
}
.preview-box::after {
    content: "卷轴预览";
    position: absolute;
    top: -10px;
    right: 20px;
    background: var(--dark-bg);
    padding: 0 10px;
    color: var(--deep-gold);
    font-size: 0.8rem;
}
.modal {
    display: none;
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: #111;
    border: 2px solid var(--gold);
    padding: 40px;
    z-index: 10000;
    text-align: center;
    box-shadow: 0 0 100px rgba(0,0,0,0.9);
    width: 90%;
    max-width: 400px;
}
.modal-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0,0,0,0.9);
    z-index: 9999;
    backdrop-filter: blur(5px);
}
footer {
    text-align: center;
    padding: 40px 0;
    font-size: 0.8rem;
    border-top: 1px solid #222;
    margin-top: 60px;
    color: #555;
    position: relative;
    background: linear-gradient(to top, rgba(0, 0, 0, 0.9), rgba(10, 10, 10, 0.95));
}
footer::before {
    content: "";
    position: absolute;
    top: -1px;
    left: 10%;
    right: 10%;
    height: 1px;
    background: linear-gradient(to right, transparent, var(--gold), transparent);
}
#talent-pool.terminal-mode {
    position: relative;
    min-height: 300px;
    background: #0a0a0a;
    border: 1px solid var(--border-color);
    padding: 20px;
    font-family: "Courier New", monospace;
    color: #b3a16e;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}
.terminal-header {
    color: var(--gold);
    font-size: 1.1rem;
    margin-bottom: 15px;
    display: flex;
    align-items: center;
    gap: 10px;
    text-shadow: 0 0 10px rgba(212, 175, 55, 0.3);
    letter-spacing: 2px;
}
.terminal-header::before {
    content: "⚙";
    font-size: 1.2rem;
}
.terminal-content {
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    padding: 20px;
}
.terminal-line {
    margin: 8px 0;
    font-size: 1rem;
    color: #d4c9a8;
    opacity: 0;
    animation: terminalFadeIn 0.5s ease-out forwards;
}
.terminal-line:nth-child(1) { animation-delay: 0.2s; }
.terminal-line:nth-child(2) { animation-delay: 0.8s; }
.terminal-line:nth-child(3) { animation-delay: 1.4s; }
.terminal-line:nth-child(4) { animation-delay: 2s; }
@keyframes terminalFadeIn {
    0% { opacity: 0; transform: translateY(10px); }
    100% { opacity: 1; transform: translateY(0); }
}
.terminal-glow {
    color: var(--gold);
    text-shadow: 0 0 8px rgba(212, 175, 55, 0.5);
    font-weight: bold;
}
.terminal-cursor {
    display: inline-block;
    width: 8px;
    height: 1.2em;
    background-color: var(--gold);
    margin-left: 5px;
    animation: cursorBlink 1s infinite;
    vertical-align: middle;
}
@keyframes cursorBlink {
    0%, 50% { opacity: 1; }
    51%, 100% { opacity: 0; }
}
.terminal-footer {
    margin-top: 20px;
    font-size: 0.9rem;
    color: #8a7024;
    text-align: center;
    opacity: 0;
    animation: fadeIn 0.5s ease-out 2.5s forwards;
}
.perspective-selector {
    margin-bottom: 15px;
}
.perspective-selector label {
    display: inline-block;
    margin-top: 0;
    margin-right: 15px;
    font-size: 0.95rem;
}
.perspective-selector select {
    background: #111;
    border: 1px solid var(--border-color);
    color: #fff;
    padding: 8px 12px;
    font-family: inherit;
    font-size: 0.95rem;
    border-radius: 3px;
    width: auto;
}
.perspective-selector select:focus {
    border-color: var(--gold);
    outline: none;
}
.locked-count {
    display: inline-block;
    margin-left: 10px;
    font-size: 0.85rem;
    color: #ffcc00;
}
.setting-switches {
    margin: 20px 0;
    padding: 15px;
    background: rgba(30, 30, 30, 0.3);
    border: 1px solid var(--border-color);
    border-radius: 4px;
}
.switch-container {
    display: flex;
    align-items: center;
    margin-bottom: 12px;
    min-height: 30px;
}
.switch-container:last-child {
    margin-bottom: 0;
}
.switch {
    position: relative;
    display: inline-block;
    width: 50px;
    height: 26px;
    flex-shrink: 0;
    margin-top: 2px; 
}
.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}
.slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #333;
    transition: .4s;
    border-radius: 34px;
}
.slider:before {
    position: absolute;
    content: "";
    height: 18px;
    width: 18px;
    left: 4px;
    bottom: 4px;
    background-color: #666;
    transition: .4s;
    border-radius: 50%;
}
input:checked + .slider {
    background-color: var(--gold);
}
input:checked + .slider:before {
    transform: translateX(24px);
    background-color: #fff;
}
.switch-label {
    color: #bbb;
    font-size: 0.95rem;
    margin-left: 12px;
    line-height: 1.3;
    padding-top: 2px; 
    flex: 1;
}
.switch-label::before {
    content: "⚠️ ";
    color: #ffaa00;
    font-size: 0.8em;
}
@media (max-width: 600px) {
    h1 { font-size: 1.5rem; }
    h1::before, h1::after { display: none; }
    .tab-btn { 
        padding: 8px 15px; 
        font-size: 0.95rem; 
        flex: 1 1 30%; 
    }
    .content-section { padding: 15px; }
    .talent-grid { grid-template-columns: repeat(3, 1fr); }
    .talent-card {
        min-height: 70px;
        padding: 15px 8px;
    }
    .talent-card.selected {
        border-width: 2px !important;
    }
    h3 { font-size: 1.1rem; }
    .switch-label {
        font-size: 0.85rem;
    }
}
.author-tip {
    margin-bottom: 25px;
    padding: 15px;
    background: rgba(30, 30, 30, 0.4);
    border: 1px solid var(--border-color);
    border-radius: 4px;
    position: relative;
    overflow: hidden;
}
.author-tip::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 3px;
    height: 100%;
    background: linear-gradient(to bottom, var(--gold), var(--deep-gold));
}
.author-tip strong {
    color: var(--gold);
    font-size: 1.05rem;
    display: block;
    margin-bottom: 10px;
    letter-spacing: 1px;
}
.author-list {
    list-style-type: none;
    padding-left: 0;
    margin: 0;
}
.author-list li {
    margin-bottom: 8px;
    padding-left: 20px;
    position: relative;
    color: #bbb;
    line-height: 1.6;
}
.author-list li:before {
    content: "»";
    position: absolute;
    left: 0;
    color: var(--deep-gold);
    font-size: 0.9rem;
}
.recommendation {
    color: #33ff33;
    font-weight: bold;
    text-shadow: 0 0 5px rgba(51, 255, 51, 0.3);
}
.warning {
    color: #ff3333;
    font-weight: bold;
    text-shadow: 0 0 5px rgba(255, 51, 51, 0.3);
}
.note {
    color: #3399ff;
    font-weight: bold;
    text-shadow: 0 0 5px rgba(51, 153, 255, 0.3);
}
.music-player {
    position: fixed;
    bottom: 30px;
    right: 30px;
    z-index: 1000;
    opacity: 0;
    transition: opacity 0.8s ease;
}
.music-player.visible {
    opacity: 1;
}
.music-control {
    width: 70px;
    height: 70px;
    border-radius: 50%;
    background: rgba(20, 20, 20, 0.95);
    border: 2px solid var(--gold);
    box-shadow: 
        0 0 20px rgba(212, 175, 55, 0.3),
        inset 0 0 15px rgba(0, 0, 0, 0.8);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    position: relative;
    overflow: hidden;
    transition: all 0.3s ease;
}
.music-control:hover {
    transform: scale(1.1);
    box-shadow: 
        0 0 30px rgba(212, 175, 55, 0.5),
        inset 0 0 15px rgba(0, 0, 0, 0.8);
}
.music-control::before {
    content: "";
    position: absolute;
    top: -2px;
    left: -2px;
    right: -2px;
    bottom: -2px;
    background: linear-gradient(45deg, 
        var(--gold) 0%, 
        var(--deep-gold) 25%, 
        transparent 50%, 
        var(--deep-gold) 75%, 
        var(--gold) 100%);
    border-radius: 50%;
    z-index: -1;
    opacity: 0.3;
}
.music-control.playing::before {
    animation: rotateBorder 3s linear infinite;
}
@keyframes rotateBorder {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}
.music-icon {
    font-size: 28px;
    color: var(--gold);
    text-shadow: 0 0 10px rgba(212, 175, 55, 0.5);
    transition: all 0.3s ease;
}
.music-control:hover .music-icon {
    color: #fff;
    text-shadow: 0 0 15px rgba(255, 255, 255, 0.8);
}
.music-waves {
    position: absolute;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    opacity: 0;
}
.music-control.playing .music-waves {
    opacity: 1;
}
.music-wave {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    border: 2px solid var(--gold);
    border-radius: 50%;
    animation: wavePulse 2s ease-out infinite;
}
.music-wave:nth-child(1) {
    width: 60px;
    height: 60px;
    animation-delay: 0s;
}
.music-wave:nth-child(2) {
    width: 80px;
    height: 80px;
    animation-delay: 0.3s;
}
.music-wave:nth-child(3) {
    width: 100px;
    height: 100px;
    animation-delay: 0.6s;
}
@keyframes wavePulse {
    0% {
        opacity: 1;
        transform: translate(-50%, -50%) scale(0.8);
    }
    100% {
        opacity: 0;
        transform: translate(-50%, -50%) scale(1.2);
    }
}
.music-title {
    position: absolute;
    right: 85px;
    top: 50%;
    transform: translateY(-50%);
    background: rgba(20, 20, 20, 0.9);
    border: 1px solid var(--border-color);
    padding: 8px 15px;
    border-radius: 4px;
    color: var(--gold);
    font-size: 0.9rem;
    white-space: nowrap;
    opacity: 0;
    transition: opacity 0.3s ease;
    pointer-events: none;
    box-shadow: 0 0 15px rgba(0, 0, 0, 0.8);
}
.music-title::before {
    content: "";
    position: absolute;
    top: 50%;
    right: -5px;
    transform: translateY(-50%);
    width: 10px;
    height: 10px;
    background: rgba(20, 20, 20, 0.9);
    border-right: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
    transform: translateY(-50%) rotate(-45deg);
}
.music-control:hover .music-title {
    opacity: 1;
}
.scroll-content p:last-child {
    margin-top: 20px;
    font-size: 0.9rem;
    color: rgba(212, 175, 55, 0.7);
    animation: pulseGlow 2s ease-in-out infinite;
}
@keyframes pulseGlow {
    0%, 100% { opacity: 0.7; }
    50% { opacity: 1; }
}
@media (max-width: 768px) {
    .music-player {
        bottom: 20px;
        right: 20px;
    }
    .music-control {
        width: 60px;
        height: 60px;
    }
    .music-icon {
        font-size: 24px;
    }
    .music-title {
        display: none;
    }
}
@media (max-width: 768px) {
    .scroll-content {
        justify-content: center;
        padding-top: 0;
        margin-top: -15px; 
    }
    .scroll-content h2 {
        margin-bottom: 5px; 
    }
    .scroll-content p {
        margin: 3px 0; 
    }
    .scroll-content .subtext {
        margin-top: 5px; 
    }
}
@media (max-width: 480px) {
    .music-player {
        bottom: 15px;
        right: 15px;
    }
    .music-control {
        width: 50px;
        height: 50px;
    }
    .music-icon {
        font-size: 20px;
    }
}
.click-ripple {
  position: absolute;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(212, 175, 55, 0.6) 0%, transparent 70%);
  transform: scale(0);
  animation: rippleEffect 0.6s ease-out;
  pointer-events: none;
  z-index: 1000;
}
@keyframes rippleEffect {
  to {
    transform: scale(4);
    opacity: 0;
  }
}
.talent-card:active {
  transform: scale(0.95) !important;
  transition: transform 0.1s !important;
}
.marquee-container {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    background: linear-gradient(90deg, 
        rgba(10, 10, 10, 0.95) 0%,
        rgba(20, 20, 20, 0.98) 20%,
        rgba(20, 20, 20, 0.98) 80%,
        rgba(10, 10, 10, 0.95) 100%);
    border-bottom: 1px solid rgba(212, 175, 55, 0.3);
    backdrop-filter: blur(10px);
    z-index: 1001;
    padding: 8px 0;
    overflow: hidden;
    box-shadow: 0 5px 20px rgba(0, 0, 0, 0.7);
}
.marquee-wrapper {
  position: relative;
  padding: 0 120px;
  overflow: hidden;
}
.marquee-track {
  display: flex;
  white-space: nowrap;
  animation: marqueeScroll 40s linear infinite;
}
@keyframes marqueeScroll {
  0% { transform: translateX(100%); }
  100% { transform: translateX(-100%); }
}
.marquee-item {
  display: inline-block;
  padding: 0 40px;
  color: #b3a16e;
  font-size: 0.9rem;
  position: relative;
}
.marquee-item::before {
  content: "◆";
  position: absolute;
  left: 15px;
  color: var(--gold);
  font-size: 0.6rem;
  top: 50%;
  transform: translateY(-50%);
}
.marquee-label {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  background: linear-gradient(90deg, rgba(212, 175, 55, 0.2), transparent);
  padding: 0 15px;
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--gold);
  font-weight: bold;
  font-size: 0.9rem;
  border-right: 1px solid rgba(212, 175, 55, 0.3);
  backdrop-filter: blur(5px);
}
.marquee-icon {
  animation: pulse 2s ease-in-out infinite;
}
.status-bar {
  display: flex;
  justify-content: space-around;
  background: rgba(10, 10, 10, 0.8);
  border: 1px solid rgba(212, 175, 55, 0.2);
  border-radius: 8px;
  padding: 12px;
  margin: 20px 0 30px 0;
  backdrop-filter: blur(10px);
  box-shadow: 
    0 0 20px rgba(0, 0, 0, 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}
.status-item {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #bbb;
  font-size: 0.9rem;
}
.status-icon {
  font-size: 1.1rem;
  filter: drop-shadow(0 0 5px currentColor);
}
.status-text {
  color: #d4c9a8;
}
#onlineCount, #topRank, #weatherStatus, #calendarDate {
  color: var(--gold);
  font-weight: bold;
  text-shadow: 0 0 8px rgba(212, 175, 55, 0.5);
}
@media (max-width: 768px) {
  .status-bar {
    flex-wrap: wrap;
    gap: 10px;
    justify-content: center;
  }
  .status-item {
    flex: 0 0 calc(50% - 10px);
  }
  .marquee-wrapper {
    padding: 0 80px;
  }
  .marquee-item {
    padding: 0 20px;
    font-size: 0.8rem;
  }
}
@media (max-width: 480px) {
  .status-bar {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }
  .status-item {
    flex: 0 0 100%;
  }
  .marquee-wrapper {
    padding: 0 70px;
  }
  .marquee-item {
    font-size: 0.75rem;
  }
.marquee-track {
    animation: marqueeScroll 15s linear infinite !important;
  }
}
.dice-btn {
    position: absolute;
    right: 5px;
    top: 50%;
    transform: translateY(-50%); 
    background: rgba(212, 175, 55, 0.2);
    border: 1px solid var(--gold);
    color: var(--gold);
    width: 35px;
    height: 35px;
    border-radius: 3px;
    cursor: pointer;
    font-size: 1rem;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.3s, color 0.3s, transform 0.3s; 
}
.dice-btn:hover {
    background: var(--gold);
    color: #000;
    transform: translateY(-50%) rotate(90deg); 
}
.dice-btn.rolling {
    animation: diceRoll 0.5s ease-in-out forwards;
}
.input-with-dice textarea ~ .dice-btn {
    top: 50%; 
    transform: translateY(-50%);
}
@keyframes diceRoll {
    0% { 
        transform: translateY(-50%) rotate(0deg); 
    }
    100% { 
        transform: translateY(-50%) rotate(360deg); 
    }
}
.dice-btn.rolling {
    animation: diceRoll 0.5s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}
@media (max-width: 768px) {
    .dice-btn {
        width: 30px;
        height: 30px;
        font-size: 0.9rem;
        transform: translateY(-50%);
    }
    .dice-btn:hover {
        transform: translateY(-50%) rotate(90deg);
    }
}
.world-map {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    margin-top: 20px;
}
.region-box {
    background: rgba(30, 25, 20, 0.6);
    border: 1px solid var(--border-color);
    border-radius: 4px;
    padding: 15px;
    position: relative;
    transition: all 0.3s ease;
}
.region-box:hover {
    border-color: var(--gold);
    background: rgba(40, 35, 30, 0.8);
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(0,0,0,0.5);
}
.region-title {
    color: var(--gold);
    font-size: 1.2rem;
    font-weight: bold;
    border-bottom: 1px dashed var(--border-color);
    margin-bottom: 12px;
    padding-bottom: 5px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}
.region-title span {
    font-size: 0.8rem;
    color: var(--sub-text);
    font-weight: normal;
}
.faction-mini-card {
    margin-bottom: 10px;
    padding-left: 10px;
    border-left: 2px solid var(--deep-gold);
}
.faction-name {
    color: #e0e0e0;
    font-weight: bold;
    font-size: 0.95rem;
    display: flex;
    align-items: center;
    gap: 5px;
}
.faction-feature {
    color: #999;
    font-size: 0.85rem;
    line-height: 1.5;
    margin-top: 3px;
}
.forbidden-zone {
    border-color: #ff4444 !important;
    background: rgba(255, 0, 0, 0.05) !important;
}
.forbidden-zone .region-title {
    color: #ff6666;
}
.global-factions {
    grid-column: span 2;
    background: rgba(20, 30, 40, 0.5);
    border: 1px solid #334455;
}
@media (max-width: 768px) {
    .world-map {
        grid-template-columns: 1fr;
    }
    .global-factions {
        grid-column: span 1;
    }
}
.world-map-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    margin-top: 20px;
}
.map-region {
    background: rgba(15, 15, 15, 0.7);
    border: 1px solid var(--border-color);
    border-radius: 4px;
    padding: 15px;
    position: relative;
    display: flex;
    flex-direction: column;
}
.region-header {
    border-bottom: 2px solid var(--deep-gold);
    margin-bottom: 15px;
    padding-bottom: 5px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}
.region-header h4 {
    margin: 0;
    border: none;
    padding: 0;
    color: var(--gold);
    font-size: 1.2rem;
    text-shadow: 0 0 10px rgba(212, 175, 55, 0.3);
}
.region-header .coord {
    font-size: 0.75rem;
    color: var(--sub-text);
    font-family: monospace;
}
.map-region .list-item {
    background: rgba(0, 0, 0, 0.4);
    margin-bottom: 10px;
    padding: 12px;
}
.map-region .list-item:last-child {
    margin-bottom: 0;
}
.map-region.forbidden {
    border-color: #ff4d4d;
    background: linear-gradient(135deg, rgba(15, 15, 15, 0.8), rgba(40, 10, 10, 0.4));
}
.map-region.forbidden .region-header h4 {
    color: #ff4d4d;
}
.global-map-region {
    grid-column: span 2;
    background: rgba(20, 25, 30, 0.6);
}
.global-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 15px;
}
@media (max-width: 768px) {
    .world-map-grid, .global-grid {
        grid-template-columns: 1fr;
    }
    .global-map-region {
        grid-column: span 1;
    }
}
</style>
</head>
