</footer>
<script>
let selectedTalents = [];
let lockedTalents = [];
function hideLoading() {
    document.getElementById(''musicPlayer'').classList.add(''visible'');
    playBackgroundMusic();
    document.getElementById(''loading-overlay'').style.opacity = ''0'';
    setTimeout(() => {
        document.getElementById(''loading-overlay'').style.display = ''none'';
        document.querySelector(''.main-container'').style.display = ''block'';
        initTalents();
        initCollapsible();
    }, 200);
}
function initCollapsible() {
    const foldSections = document.querySelectorAll(''.fold-section'');
    if (foldSections.length > 0) {
        foldSections.forEach((section, index) => {
            const h3 = section.querySelector(''h3'');
            const content = section.querySelector(''.collapsible-content'');
            if (index === 0) {
                h3.classList.remove(''collapsed'');
                content.classList.remove(''collapsed'');
            } else {
                h3.classList.add(''collapsed'');
                content.classList.add(''collapsed'');
            }
        });
    }
}
function toggleCollapse(element) {
    const content = element.nextElementSibling;
    const isCollapsed = content.classList.contains(''collapsed'');
    element.classList.toggle(''collapsed'');
    content.classList.toggle(''collapsed'');
    if (!isCollapsed && window.innerWidth <= 768) {
        setTimeout(() => {
            const rect = element.getBoundingClientRect();
            if (rect.top < 0 || rect.top > window.innerHeight) {
                element.scrollIntoView({ behavior: ''smooth'', block: ''nearest'' });
            }
        }, 50);
    }
}
function openTab(evt, tabName) {
    const tabcontent = document.getElementsByClassName("tab-content");
    for (let i = 0; i < tabcontent.length; i++) {
        tabcontent[i].style.display = "none";
    }
    const tablinks = document.getElementsByClassName("tab-btn");
    for (let i = 0; i < tablinks.length; i++) {
        tablinks[i].className = tablinks[i].className.replace(" active", "");
    }
    document.getElementById(tabName).style.display = "block";
    if (evt) evt.currentTarget.className += " active";
    setTimeout(initCollapsible, 50);
}
function handleCustomInput(id) {
    const sel = document.getElementById(id + ''-sel'');
    const custom = document.getElementById(id + ''-custom'');
    if (sel.value === ''custom'') { 
        custom.style.display = ''block''; 
    } else { 
        custom.style.display = ''none''; 
    }
    updatePreview();
}
function animateDice(btn) {
    btn.classList.add(''rolling'');
    setTimeout(() => btn.classList.remove(''rolling''), 500);
}
const namePrefixes = ["风", "云", "白", "墨", "夜", "月", "寒", "雪", "凌", "清", "玄", "玉", "霜", "惊", "羽", "流", "孤", "残", "红", "紫", "幽", "离", "醉", "梦", "星", "辰", "朝", "暮", "江", "山"];
const nameSuffixes = ["尘", "烟", "痕", "涯", "渊", "楼", "舟", "笙", "弦", "影", "衣", "袖", "辞", "歌", "语", "言", "醉", "醒", "绝", "空", "遥", "远", "深", "浅", "重", "轻", "旧", "新", "晚", "初"];
function rollName() {
    const btn = event.target.closest(''.dice-btn'');
    animateDice(btn);
    const prefix = namePrefixes[Math.floor(Math.random() * namePrefixes.length)];
    const suffix = nameSuffixes[Math.floor(Math.random() * nameSuffixes.length)];
    const middle = Math.random() > 0.5 %s nameSuffixes[Math.floor(Math.random() * nameSuffixes.length)] : "";
    const name = prefix + (middle || "") + suffix;
    document.getElementById(''char-name'').value = name;
    updatePreview();
}
function rollAge() {
    const btn = event.target.closest(''.dice-btn'');
    animateDice(btn);
    const age = Math.floor(Math.random() * 100) + 1;
    document.getElementById(''char-age'').value = age;
    updatePreview();
}
