function rollLook() {
    const btn = event.target.closest(''.dice-btn'');
    animateDice(btn);
    const gender = document.getElementById(''char-gender'').value;
    let look;
    if (gender === "男性") {
        look = maleLooks[Math.floor(Math.random() * maleLooks.length)];
    } else {
        look = femaleLooks[Math.floor(Math.random() * femaleLooks.length)];
    }
    document.getElementById(''char-look'').value = look;
    updatePreview();
}
