text += `【当前所在】\n${region}\n`;
    text += `━━━━━━━━━━━━━━━━\n`;
    text += `【觉醒天赋】\n${talentText}\n`;
    text += `━━━━━━━━━━━━━━━━\n`;
    if (nsfwStyleEnabled) {
    text += `【额外设置】\n`;
