        if (successful) {
            document.getElementById(''modal-overlay'').style.display = ''block'';
            document.getElementById(''success-modal'').style.display = ''block'';
        } else {
            alert(''复制失败，请手动复制预览内容'');
        }
    } catch (err) {
        alert(''复制失败，请手动复制预览内容'');
    }
    document.body.removeChild(textarea);
}
