};
let backgroundMusic = null;
let isMusicPlaying = false;
let userInteracted = false;
function playBackgroundMusic() {
    if (!backgroundMusic) {
        backgroundMusic = new Audio(''http://music.163.com/song/media/outer/url%sid=2656158058.mp3'');
        backgroundMusic.loop = true;
        backgroundMusic.volume = 0.5;
        backgroundMusic.addEventListener(''ended'', function() {
            this.currentTime = 0;
            this.play();
        });
        backgroundMusic.addEventListener(''error'', function(e) {
            console.error(''音乐加载失败:'', e);
            showMusicError();
        });
    }
    const playPromise = backgroundMusic.play();
    if (playPromise !== undefined) {
        playPromise.then(() => {
            isMusicPlaying = true;
            updateMusicUI();
        }).catch(error => {
            console.log(''自动播放被阻止，等待用户交互:'', error);
            isMusicPlaying = false;
            updateMusicUI();
            document.addEventListener(''click'', unlockAudio, { once: true });
        });
    }
}
function unlockAudio() {
    userInteracted = true;
    if (backgroundMusic && !isMusicPlaying) {
        const playPromise = backgroundMusic.play();
        if (playPromise !== undefined) {
            playPromise.then(() => {
                isMusicPlaying = true;
                updateMusicUI();
            }).catch(error => {
                console.error(''播放失败:'', error);
            });
        }
    }
}
function toggleMusic() {
    if (!backgroundMusic) {
        playBackgroundMusic();
        return;
    }
    if (isMusicPlaying) {
        backgroundMusic.pause();
        isMusicPlaying = false;
    } else {
        if (backgroundMusic.ended) {
            backgroundMusic.currentTime = 0;
        }
        const playPromise = backgroundMusic.play();
        if (playPromise !== undefined) {
            playPromise.then(() => {
                isMusicPlaying = true;
                updateMusicUI(); // 确保播放成功后再更新UI
            }).catch(error => {
                console.error(''播放失败:'', error);
                isMusicPlaying = false;
                updateMusicUI(); // 播放失败也要更新UI
            });
        }
    }
    updateMusicUI();
}
function updateMusicUI() {
    const musicControl = document.getElementById(''musicControl'');
    const musicIcon = document.getElementById(''musicIcon'');
    musicIcon.style.color = '''';
