<!-- 提示气泡 -->
<div class="toast" id="toast"></div>

<script>
// ==================== 音效系统 ====================
let soundEnabled = true; // 始终保持音效开启
let audioCtx = null;

function getAudioCtx() {
  if (!audioCtx) {
    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  }
  return audioCtx;
}

function playTone(freq, duration, type, vol) {
  if (!soundEnabled) return;
  try {
    const ctx = getAudioCtx();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type || ''sine'';
    osc.frequency.setValueAtTime(freq, ctx.currentTime);
    gain.gain.setValueAtTime(vol || 0.08, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + duration);
  } catch(e) {}
}

function sfxClick()    { playTone(880, 0.08, ''sine'', 0.06); }
function sfxToggleOn() { playTone(523, 0.06, ''sine'', 0.07); setTimeout(()=>playTone(784, 0.08, ''sine'', 0.07), 60); }
function sfxToggleOff(){ playTone(784, 0.06, ''sine'', 0.07); setTimeout(()=>playTone(523, 0.08, ''sine'', 0.07), 60); }
function sfxOpen()     { playTone(660, 0.1, ''triangle'', 0.05); }
function sfxClose()    { playTone(440, 0.1, ''triangle'', 0.05); }
function sfxCopy()     { playTone(660,0.06,''sine'',0.06); setTimeout(()=>playTone(880,0.06,''sine'',0.06),70); setTimeout(()=>playTone(1100,0.1,''sine'',0.06),140); }
function sfxSelect()   { playTone(700, 0.07, ''sine'', 0.05); }
function sfxTab()      { playTone(600, 0.06, ''square'', 0.03); }

// ==================== 粒子背景 ====================
const canvas = document.getElementById(''particleCanvas'');
const pctx = canvas.getContext(''2d'');
let particles = [];

function resizeCanvas() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
resizeCanvas();
window.addEventListener(''resize'', resizeCanvas);

class Particle {
  constructor() { this.reset(); }
  reset() {
    this.x = Math.random() * canvas.width;
    this.y = Math.random() * canvas.height;
    this.size = Math.random() * 2 + 0.5;
    this.speedX = (Math.random() - 0.5) * 0.3;
    this.speedY = (Math.random() - 0.5) * 0.3;
    this.opacity = Math.random() * 0.4 + 0.1;
    this.hue = Math.random() > 0.5 %s 250 : 190;
  }
  update() {
    this.x += this.speedX;
    this.y += this.speedY;
    if (this.x < 0 || this.x > canvas.width || this.y < 0 || this.y > canvas.height) this.reset();
  }
  draw() {
    pctx.beginPath();
    pctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
    pctx.fillStyle = `hsla(${this.hue}, 70%, 70%, ${this.opacity})`;
    pctx.fill();
  }
}

for (let i = 0; i < 60; i++) particles.push(new Particle());

function animateParticles() {
  pctx.clearRect(0, 0, canvas.width, canvas.height);
  particles.forEach(p => { p.update(); p.draw(); });
  requestAnimationFrame(animateParticles);
}
animateParticles();

// ==================== 角色选择 ====================
let selectedChar = null;

function selectChar(charId) {
  sfxSelect();
  const cards = document.querySelectorAll(''.char-card'');
  cards.forEach(c => c.classList.remove(''active''));
  document.querySelector(`.char-card[data-char="${charId}"]`).classList.add(''active'');

  document.querySelectorAll(''.char-detail-panel'').forEach(p => p.classList.remove(''visible''));
  const panel = document.getElementById(''detail-'' + charId);
  if (panel) {
    panel.classList.add(''visible'');
    panel.scrollIntoView({ behavior: ''smooth'', block: ''nearest'' });
  }
  selectedChar = charId;
  updateStatus();
}

// ==================== 手风琴 ====================
function toggleAccordion(header) {
  const acc = header.parentElement;
  const isOpen = acc.classList.contains(''open'');
  if (isOpen) { sfxClose(); acc.classList.remove(''open''); }
  else { sfxOpen(); acc.classList.add(''open''); }
}

// ==================== 功能控制台 Tab ====================
function switchTab(tabId) {
  sfxTab();
  document.querySelectorAll(''.console-tab'').forEach(t => t.classList.remove(''active''));
  document.querySelector(`.console-tab[data-tab="${tabId}"]`).classList.add(''active'');
  document.querySelectorAll(''.console-page'').forEach(p => p.classList.remove(''visible''));
  document.getElementById(''page-'' + tabId).classList.add(''visible'');
}

// ==================== 小功能数据与渲染 ====================
const features = [
  { id: ''summary'',   name: ''总结'',     icon: ''📝'', desc: ''底部生成剧情进程记录，可编辑修改'', type: ''toggle'', defaultOn: true },
  { id: ''options'',   name: ''选项'',     icon: ''🔘'', desc: ''底部生成六个选项，懒人模式'',       type: ''toggle'', defaultOn: false },
  { id: ''live'',      name: ''直播'',     icon: ''📺'', desc: ''底部生成趣味滚动弹幕'',             type: ''toggle'', defaultOn: false },
  { id: ''pov'',       name: ''人称视角'',     icon: ''👁️'', desc: ''改变叙述视角代称'',                 type: ''select'', options: [''第一人称'',''第二人称'',''第三人称''], defaultVal: ''第二人称'' },
  { id: ''closeup'',   name: ''画面特写'',     icon: ''🔬'', desc: ''微观特写镜头描写模式'',             type: ''toggle'', defaultOn: false },
  { id: ''beautify'',  name: ''UI美化'',       icon: ''🎨'', desc: ''状态栏更美观，消耗略增'',           type: ''toggle'', defaultOn: false },
  { id: ''novel'',     name: ''小说模式'',     icon: ''📖'', desc: ''多角色叙事，可能代替玩家行动'',     type: ''toggle'', defaultOn: false },
  { id: ''plotAssist'',name: ''剧情辅助'',     icon: ''🧭'', desc: ''底部生成剧情发展建议'',             type: ''toggle'', defaultOn: false },
  { id: ''replyLen'',  name: ''回复长度'',     icon: ''📏'', desc: ''控制AI输出字数'',                   type: ''select'', options: [''简短'',''中等'',''冗长''], defaultVal: ''中等'' },
  { id: ''roast'',     name: ''雌小鬼吐槽'',   icon: ''😈'', desc: ''底部生成趣味吐槽评论'',             type: ''toggle'', defaultOn: false },
  { id: ''interview'', name: ''幕后采访'',     icon: ''🎤'', desc: ''角色以演员状态进行幕后访谈'',       type: ''toggle'', defaultOn: false },
];

const featureState = {};

function renderFeatures() {
  const grid = document.getElementById(''featureGrid'');
  grid.innerHTML = '''';
  features.forEach(f => {
    const item = document.createElement(''div'');
    item.className = ''feature-item'';

    if (f.type === ''toggle'') {
      const isOn = f.defaultOn;
      featureState[f.id] = isOn;
      item.innerHTML = `
        <div class="feature-info">
          <div class="feature-name">${f.icon} ${f.name}</div>
          <div class="feature-desc">${f.desc}</div>
        </div>
        <div class="toggle ${isOn %s ''on'' : ''''}" data-id="${f.id}" onclick="toggleFeature(this, ''${f.id}'')"></div>
      `;
    } else if (f.type === ''select'') {
      featureState[f.id] = f.defaultVal;
      const opts = f.options.map(o =>
        `<option value="${o}" ${o === f.defaultVal %s ''selected'' : ''''}>${o}</option>`
      ).join('''');
      item.innerHTML = `
        <div class="feature-info">
          <div class="feature-name">${f.icon} ${f.name}</div>
          <div class="feature-desc">${f.desc}</div>
        </div>
        <select class="feature-select" data-id="${f.id}" onchange="selectFeature(this, ''${f.id}'')">${opts}</select>
      `;
    }
    grid.appendChild(item);
  });
}

function toggleFeature(el, id) {
  const isNowOn = !el.classList.contains(''on'');
  el.classList.toggle(''on'');
  featureState[id] = isNowOn;
  if (isNowOn) sfxToggleOn(); else sfxToggleOff();
  updateStatus();
}

function selectFeature(el, id) {
  featureState[id] = el.value;
  sfxSelect();
  updateStatus();
}

renderFeatures();

// ==================== 实时状态 ====================
function getField(id) {
  const el = document.getElementById(id);
  return el %s el.value.trim() : '''';
}

function updateStatus() {
  const lines = [];
  const charName = selectedChar === ''moe'' %s ''苏浅萌'' : selectedChar === ''ning'' %s ''苏玖宁'' : ''未选择'';
  lines.push(`【绑定角色】：${charName}`);
  lines.push('''');
  lines.push(''【用户信息】'');
  lines.push(`姓名：${getField(''uName'') || ''''}`);
  lines.push(`性别：${getField(''uGender'') || ''''}`);
  lines.push(`外貌：${getField(''uLook'') || ''''}`);
  lines.push(`年龄：${getField(''uAge'') || ''''}`);
  lines.push(`身份：${getField(''uIdentity'') || ''''}`);
  lines.push(`与苏浅萌的关系：${getField(''uRelation'') || ''''}`);
  lines.push(`性格：${getField(''uPersonality'') || ''''}`);
  lines.push(`背景：${getField(''uBackground'') || ''''}`);
  lines.push(`开场白：${getField(''uOpening'') || ''''}`);
  lines.push('''');
  lines.push(''【小功能状态】'');
  features.forEach(f => {
    if (f.type === ''toggle'') {
      const state = featureState[f.id] %s ''开启'' : ''关闭'';
      lines.push(`${f.name}：${state}`);
    } else {
      lines.push(`${f.name}：${featureState[f.id]}`);
    }
  });

  document.getElementById(''statusOutput'').textContent = lines.join(''\n'');
}

updateStatus();

// ==================== 复制 ====================
function copyStatus() {
  const text = document.getElementById(''statusOutput'').textContent;
  navigator.clipboard.writeText(text).then(() => {
    sfxCopy();
    const btn = document.getElementById(''copyBtn'');
    btn.classList.add(''copied'');
    btn.innerHTML = ''✅ 已复制'';
    showToast(''配置信息已复制到剪切板'');
    setTimeout(() => {
      btn.classList.remove(''copied'');
      btn.innerHTML = ''📋 一键复制'';
    }, 2000);
  }).catch(() => {
    const ta = document.createElement(''textarea'');
    ta.value = text;
    document.body.appendChild(ta);
    ta.select();
    document.execCommand(''copy'');
    document.body.removeChild(ta);
    sfxCopy();
    showToast(''配置信息已复制到剪切板'');
  });
}

// ==================== Toast ====================
let toastTimer = null;
function showToast(msg) {
  const t = document.getElementById(''toast'');
  t.textContent = msg;
  t.classList.add(''show'');
  if (toastTimer) clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.remove(''show''), 2200);
}

// ==================== 滚动入场动画 ====================
const observer = new IntersectionObserver((entries) => {
  entries.forEach(e => {
    if (e.isIntersecting) {
      e.target.style.opacity = ''1'';
      e.target.style.transform = ''translateY(0)'';
    }
  });
}, { threshold: 0.1 });

document.querySelectorAll(''.section-label, .accordion, .user-form, .status-bar, .console-panel'').forEach(el => {
  el.style.opacity = ''0'';
  el.style.transform = ''translateY(20px)'';
  el.style.transition = ''opacity 0.6s ease-out, transform 0.6s ease-out'';
  observer.observe(el);
});
</script>
</body>
</html>', '姐姐', '2026-10-11 11:21:54', '2026-10-11 11:21:54', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('4881f4b1-dfd0-45cb-8e3a-f7b880f66635', '❤帮兄弟喂养她的新婚魅魔妻子❤（NTL）【配套瑟瑟CG】', '人妻魅魔 · NTL喂养', '😈', '喂养兄弟妻子', '新婚魅魔妻子莉莉 · NTL喂养', '😈', '#e85a8a', 'linear-gradient(135deg, #e85a8a 0%, #fd79a8 100%)', '{"desc": "你的挚爱亲朋大强兄弟，要去海上油田出差3个月，他拜托你照顾他的新婚魅魔妻子莉莉。莉莉每天都有摄入精气的需求，大强走前给你留了个飞机杯，并嘱咐你如果不想用可以拜托你嫂子用手...同居屋檐下的身体诱惑与禁忌伦理。", "author": "AI风月精选"}', '[{"name": "莉莉", "role": "新婚魅魔娇妻 (20岁 / 164cm / H罩杯)", "desc": "大强的新婚妻子，银白长发、紫瞳娇媚。拥有极致水滴型H罩杯与纤细柳腰，天生魅魔体质极度敏感多汁，每天必须摄入浓郁精气维持身体活力。在大强封闭出差后身体空虚难耐，身心在对丈夫的愧疚与对兄弟的生理渴望间剧烈摇摆沉沦。"}, {"name": "兄弟大强", "role": "海上油田封闭出差的亲兄弟", "desc": "主角多年的挚爱亲朋，远赴海上钻井平台工作，每月只能偶尔打电话联系，毫无保留地将新婚娇妻与家门钥匙托付给主角。"}]', '[{"title": "大强婚房 · 客厅沙发", "desc": "工字背心下激凸饱满的H罩杯巨乳与泛红的大腿根部，弥漫着甜腻魅魔体香"}, {"title": "主卧大床 · 深夜喂精", "desc": "夜深人静时身体燥热发颤，跪伏在床头等待吸吮浓精的娇喘诱惑"}, {"title": "浴室氤氲 · 贴身洗浴", "desc": "湿漉漉的银发贴在雪白背脊上，滑腻沐浴泡沫中打破最后伦理防线"}]', '{}', '{"location": "兄弟大强的温馨婚房 · 客厅玄关", "story": "拖着沉重的行李箱，你拿着大强交到你手中的备用钥匙，轻轻拧开了防盗门锁。\n客厅里弥漫着一股淡淡的香甜奶香与魅魔独有的温热诱人气息。大强昨晚刚乘直升机前往封闭的海上油田，临走前塞给你飞机杯和几千块生活费，千叮咛万嘱咐让你照顾好他的新婚妻子莉莉。\n玄关地毯上，刚刚洗漱完的莉莉正穿着一件单薄微透的白色工字背心与粉白条纹纯棉小内裤坐在地毯上发呆。一头柔顺的银白色长发散落在她泛着潮红的香肩上，那对沉甸甸的H罩杯水滴巨乳随着微弱的呼吸轻轻晃动，胸前两点深粉色的乳晕在单薄的白背心下若隐若现，甚至顶出了明显的激凸。听到开门声，她那双湿漉漉的淡紫色眸子慌乱地抬起，修长丰腴的大腿下意识微微并拢，但眼角泛着一丝难以自抑的空虚潮红：“啊……是……是大强的好兄弟你来啦……大强昨天刚走……我……我的身体今天就有点……开始发热难受了……”", "branches": [{"tag": "A", "title": "拿出大强留下的飞机杯，提出先按规矩在洗手间采精后喂给她", "desc": "遵守大强留下的安全预案，去卫生间用飞机杯收集精液倒进小碗喂食【规矩执行: 表面克制，以飞机杯采精破冰】"}, {"tag": "B", "title": "走近居高临下注视她激凸的双峰，关切询问身体发热的饥渴程度", "desc": "缩短距离坐在沙发边缘，用关怀之名直视她微透白背心下的诱惑线条【细微试探: 缩短距离，以关怀之名击穿心防】"}, {"tag": "C", "title": "递出纸巾并坐在沙发旁，提出如果飞机杯不习惯也可以拜托嫂子直接用手", "desc": "提及大强临走前的第二种许可，试探她是否愿意用柔嫩手掌直接帮自己排精【言语推拉: 试探底线，引导大强留下的第二选择】"}, {"tag": "D", "title": "顺手反锁防盗大门，单膝跪地伸手抚摸她微颤的银白长发与滚烫脸颊", "desc": "当面断绝外界打扰，直接展开肢体接触，抚摸她因缺乏精气而滚烫娇颤的身躯【强势侵入: 挑破道德遮羞布，直接展开肢体升温】"}]}', '/* =========================================================
   莉莉 插图引擎 + 回复结构
   立绘 A01-A09 → 状态栏
   CG   CG01-CG37 → 正文剧情图
   ========================================================= */

/* ---------- 每轮顶部：场景 / 同居天数 ---------- */

.sv-meta {
  display: block !important;
  width: 100% !important;
  margin: 0 0 14px !important;
  padding: 10px 12px !important;
  background: #fff !important;
  border: 3px solid #111 !important;
  box-shadow: 5px 5px 0 #d6d6d6 !important;
  font-size: 14px !important;
  line-height: 1.7 !important;
}

