}

/* ---------- 正文段落间距 ---------- */

p {
  display: block !important;
  margin: 0 0 1em !important;
  line-height: 1.85 !important;
}

br + br {
  display: block !important;
  content: "" !important;
  margin-bottom: 0.85em !important;
}

/* ---------- 莉莉对话：粉色 ---------- */

