<script>
  function openMask(id) {
    document.getElementById(id).classList.add(''open'');
  }
  function closeMask(id) {
    document.getElementById(id).classList.remove(''open'');
  }
  function maskClose(e) {
    if (e.target.classList.contains(''gallery-mask'')) e.target.classList.remove(''open'');
  }
  function copyToClipboard(text, btn) {
    function done() {
      var old = btn.innerText;
      btn.innerText = ''✓ 已复制，去发给莉莉'';
      setTimeout(function () { btn.innerText = old; }, 1800);
    }
    function fallback() {
      var ta = document.createElement(''textarea'');
      ta.value = text;
      ta.style.position = ''fixed'';
      ta.style.opacity = ''0'';
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand(''copy''); } catch (e) {}
      document.body.removeChild(ta);
      done();
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done).catch(fallback);
    } else {
      fallback();
    }
  }
  function startGame() {
    var name = document.getElementById(''playerName'').innerText.trim();
    var setting = document.getElementById(''playerSetting'').innerText.trim();
    if (!name) name = ''用户'';
    if (!setting) setting = ''未填写'';
    var text =
      ''姓名：'' + name + ''\n'' +
      ''性格设定：'' + setting + ''\n'' +
      ''这天'' + name + ''接到大强的电话后，带着行李，拿着大强给的钥匙，第一次打开门，看到了大强的妻子莉莉....'';
    copyToClipboard(text, document.getElementById(''startBtn''));
  }
</script>
