/* --- 6. 激活逻辑 --- */
.MuiStack-root.css-1kz283j > p.MuiTypography-root.css-6c0gf2:hover ~ p.MuiTypography-root.css-1x48u03,
#customized-answer-content-model:has(#customized-answer-content-model-name:is(:hover, :focus-visible)) :is(#customized-answer-content-model-input-points, #customized-answer-content-model-output-points) {
  opacity: 1 !important;
