    <script>
    const canvas = document.getElementById(''bg-canvas'');
    const ctx = canvas.getContext(''2d'');
    let width, height;
    let particles = [];
    function resize() {
        width = canvas.width = window.innerWidth;
        height = canvas.height = window.innerHeight;
    }
    window.addEventListener(''resize'', resize);
    resize();
    class Particle {
        constructor() {
            this.x = Math.random() * width;
            this.y = Math.random() * height;
            this.vx = (Math.random() - 0.5) * 0.5;
            this.vy = (Math.random() - 0.5) * 0.5;
            this.size = Math.random() * 2;
            this.alpha = Math.random() * 0.5 + 0.1;
        }
        update() {
            this.x += this.vx;
            this.y += this.vy;
            if (this.x < 0) this.x = width;
            if (this.x > width) this.x = 0;
            if (this.y < 0) this.y = height;
            if (this.y > height) this.y = 0;
        }
        draw() {
            ctx.fillStyle = `rgba(255, 255, 255, ${this.alpha})`;
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
            ctx.fill();
        }
    }
    function initParticles() {
        particles = [];
        for (let i = 0; i < 100; i++) {
            particles.push(new Particle());
        }
    }
    function animateBg() {
        ctx.clearRect(0, 0, width, height);
        for (let i = 0; i < particles.length; i++) {
            particles[i].update();
            particles[i].draw();
            for (let j = i + 1; j < particles.length; j++) {
                const dx = particles[i].x - particles[j].x;
                const dy = particles[i].y - particles[j].y;
                const dist = Math.sqrt(dx * dx + dy * dy);
                if (dist < 100) {
                    ctx.strokeStyle = `rgba(255, 255, 255, ${0.1 * (1 - dist / 100)})`;
                    ctx.lineWidth = 0.5;
                    ctx.beginPath();
                    ctx.moveTo(particles[i].x, particles[i].y);
                    ctx.lineTo(particles[j].x, particles[j].y);
                    ctx.stroke();
                }
            }
        }
        requestAnimationFrame(animateBg);
    }
    document.addEventListener(''DOMContentLoaded'', () => {
        initParticles();
        animateBg();
        const phrases = [
            "正在凝聚查克拉...",
            "解析封印卷轴...",
            "结印序列确认：未-巳-寅...",
            "通灵之术准备...",
            "开启仙人模式...",
            "同步忍界坐标...",
            "欢迎回到木叶."
        ];
        const TOTAL_DURATION = 5000; 
        const PHRASE_DURATION = TOTAL_DURATION / phrases.length;
        const loaderWrapper = document.getElementById(''loader-wrapper'');
        const statusText = document.getElementById(''status-text'');
        const progressBar = document.getElementById(''progress-bar'');
        const progressPercent = document.getElementById(''progress-percent'');
        const skipBtn = document.getElementById(''loader-skip-btn'');
        const bgmBtn = document.getElementById(''bgm-btn'');
        const bgm = document.getElementById(''bgm'');
        let phraseInterval, progressInterval;
        let isLoadingFinished = false;
        function formatPercent(num) {
            return num < 10 %s `0${num}%` : `${num}%`;
        }
        function finishLoading() {
            if (isLoadingFinished) return;
            isLoadingFinished = true;
            clearInterval(phraseInterval);
            clearInterval(progressInterval);
            progressBar.style.width = ''100%'';
            progressPercent.textContent = ''100%'';
            statusText.textContent = phrases[phrases.length - 1];
            loaderWrapper.classList.add(''fade-out'');
            setTimeout(() => {
                document.body.style.overflow = ''auto''; // 恢复页面滚动
            }, 800);
        }
        let phraseIndex = 0;
        function updatePhrase() {
            if (phraseIndex < phrases.length) {
                statusText.innerText = phrases[phraseIndex];
                phraseIndex++;
            }
        }
        skipBtn.addEventListener(''click'', finishLoading);
        bgmBtn.addEventListener(''click'', () => {
            if (bgm.paused) {
                bgm.play();
                bgmBtn.innerText = "♪ 暂停音乐";
                bgmBtn.style.color = "rgba(255, 255, 255, 0.6)"; 
                bgmBtn.style.borderColor = "rgba(255, 255, 255, 0.2)";
            } else {
                bgm.pause();
                bgmBtn.innerText = "♪ 播放音乐";
                bgmBtn.style.color = "rgba(255, 255, 255, 0.3)";
            }
        });
        function startLoadingSequence() {
                bgm.volume = 0.1;
                bgm.play().catch(() => {
                    console.log("自动播放等待交互...");
                    const enableAudio = () => {
                        bgm.play();
                        document.removeEventListener(''click'', enableAudio);
                    };
                    document.addEventListener(''click'', enableAudio);
                });
                updatePhrase();
                phraseInterval = setInterval(updatePhrase, PHRASE_DURATION);
                let elapsedTime = 0;
                const updateInterval = 30;
                progressInterval = setInterval(() => {
                    elapsedTime += updateInterval;
                    let progress = Math.min((elapsedTime / TOTAL_DURATION) * 100, 100);
                    progressBar.style.width = `${progress}%`;
                    progressPercent.textContent = formatPercent(Math.floor(progress));
                    if (elapsedTime >= TOTAL_DURATION) {
                        finishLoading();
                    }
                }, updateInterval);
            }
        startLoadingSequence();
        initMainPage();
    });
