        };
        let currentFates = [];
        let selectedFates = [];
        let selectedIntro = null;
        let refreshCount = 0;
        const fateContainer = document.getElementById(''fate-container'');
        const refreshBtn = document.getElementById(''refresh-fate'');
        const selectedCountEl = document.getElementById(''selected-count'');
        const refreshCountValEl = document.getElementById(''refresh-count-val'');
        const summaryContent = document.getElementById(''summary-content'');
        const copyBtn = document.getElementById(''copy-btn'');
        const introOptions = document.querySelectorAll(''.intro-option'');
        const customIntroContainer = document.getElementById(''custom-intro-container'');
        const customIntroText = document.getElementById(''custom-intro'');
        const baseProbabilities = { white: 25, blue: 25, purple: 15, orange: 15, red: 15, gold: 5 };
        let currentProbabilities = { ...baseProbabilities };
        function updateProbabilityDisplay() { for (const level in currentProbabilities) { document.getElementById(`prob-${level}`).textContent = currentProbabilities[level].toFixed(1) + ''%''; } }
        function adjustProbabilities() {
            const factor = Math.floor(refreshCount / 10);
            currentProbabilities.gold = Math.min(0.5, baseProbabilities.gold + factor * 0.02);
            currentProbabilities.red = Math.min(2.0, baseProbabilities.red + factor * 0.1);
            currentProbabilities.orange = Math.min(8.0, baseProbabilities.orange + factor * 0.2);
            let highTierProb = currentProbabilities.gold + currentProbabilities.red + currentProbabilities.orange;
            let remainingProb = 100 - highTierProb;
            currentProbabilities.purple = remainingProb * (baseProbabilities.purple / (baseProbabilities.purple + baseProbabilities.blue + baseProbabilities.white));
            currentProbabilities.blue = remainingProb * (baseProbabilities.blue / (baseProbabilities.purple + baseProbabilities.blue + baseProbabilities.white));
            currentProbabilities.white = remainingProb - currentProbabilities.purple - currentProbabilities.blue;
            updateProbabilityDisplay();
        }
        function getRandomFateLevel() {
            const rand = Math.random() * 100;
            let cumulative = 0;
            for (const level in currentProbabilities) { cumulative += currentProbabilities[level]; if (rand <= cumulative) return level; }
            return ''white'';
        }
        function getRandomFate() {
            const level = getRandomFateLevel();
            const fateList = fates[level];
            const randomIndex = Math.floor(Math.random() * fateList.length);
            return { ...fateList[randomIndex], level: level };
        }
        function generateFates() {
            const fatesArray = [];
            const usedNames = new Set();
            let safetyCounter = 0;
            while (fatesArray.length < 10 && safetyCounter < 100) {
                const fate = getRandomFate();
                if (!usedNames.has(fate.name)) {
                    fatesArray.push(fate);
                    usedNames.add(fate.name);
                }
                safetyCounter++;
            }
            return fatesArray;
        }
        function getLevelName(level) {
            const names = { white: ''普通'', blue: ''精良'', purple: ''稀有'', orange: ''史诗'', red: ''传说'', gold: ''神话'' };
            return names[level] || ''未知'';
        }
        function renderFates(fatesArray) {
            fateContainer.innerHTML = '''';
            fatesArray.forEach((fate) => {
                const isSelected = selectedFates.some(f => f.name === fate.name && f.level === fate.level);
                const card = document.createElement(''div'');
                card.className = `fate-card fate-${fate.level} ${isSelected %s ''selected'' : ''''}`;
                card.innerHTML = `<div class="fate-title"><span class="color-${fate.level}">【${getLevelName(fate.level)}】</span>${fate.name}</div><div class="fate-desc">${fate.desc}</div>`;
                card.addEventListener(''click'', () => toggleFateSelection(fate));
                fateContainer.appendChild(card);
            });
        }
        function toggleFateSelection(fate) {
            const index = selectedFates.findIndex(f => f.name === fate.name && f.level === fate.level);
            if (index !== -1) { selectedFates.splice(index, 1); } 
            else {
                if (selectedFates.length < 3) { selectedFates.push(fate); } 
                else { alert(''最多只能选择3个命运！''); return; }
            }
            updateSummary();
            renderFates(currentFates);
        }
        function refreshFates() {
            if (selectedFates.length > 0 && !confirm(''刷新将清空已选的命运，确定吗？'')) return;
            selectedFates = [];
            refreshCount++;
            adjustProbabilities();
            currentFates = generateFates();
            renderFates(currentFates);
            updateSummary();
        }
        function updateSummary() {
            selectedCountEl.textContent = `${selectedFates.length}/3`;
            refreshCountValEl.textContent = refreshCount;
            const name = document.getElementById(''player-name'').value || ''未填写'';
            const genderEl = document.getElementById(''player-gender'');
            const gender = genderEl.options[genderEl.selectedIndex].text;
            const age = document.getElementById(''player-age'').value || ''未填写'';
            let personality = document.getElementById(''player-personality'').value;
            if (!personality) {
                const personalityPool = [''热血'', ''冷静'', ''腹黑'', ''天然呆'', ''傲娇'', ''乐天派'', ''谨慎'', ''豪爽'', ''胆小'', ''意志坚定''];
                personality = `${personalityPool[Math.floor(Math.random() * personalityPool.length)]} (随机生成)`;
            }
            const origin = document.getElementById(''player-origin'').value || ''未填写'';
            const strengthEl = document.getElementById(''player-strength'');
            const strength = strengthEl.options[strengthEl.selectedIndex].text; 
            const dream = document.getElementById(''player-dream'').value || ''未填写'';
            let introContent = ''尚未选择'';
            if (selectedIntro === ''custom'') { introContent = customIntroText.value || ''未填写自定义起点''; } 
            else if (selectedIntro) {
                const selectedOption = document.querySelector(`.intro-option[data-intro="${selectedIntro}"]`);
                if (selectedOption) { introContent = `【${selectedOption.querySelector(''h3'').textContent}】\n${selectedOption.querySelector(''p'').textContent}`; }
            }
            let summaryText = `===== 忍者登录信息 =====\n名号: ${name}\n性别: ${gender}\n年龄: ${age}\n性格: ${personality}\n实力: ${strength}\n出身: ${origin}\n忍道: ${dream}\n\n===== 忍道的起点 =====\n${introContent}\n\n===== 命运的卷轴 =====\n`;
            if (selectedFates.length > 0) {
                selectedFates.sort((a, b) => Object.keys(baseProbabilities).indexOf(b.level) - Object.keys(baseProbabilities).indexOf(a.level));
                selectedFates.forEach(fate => { summaryText += `【${getLevelName(fate.level)}】${fate.name}\n效果: ${fate.desc}\n\n`; });
            } 
            const customFateName = document.getElementById(''custom-fate-name'').value;
            const customFateDesc = document.getElementById(''custom-fate-desc'').value;
            if (customFateName || customFateDesc) {
                summaryText += `【自定义】${customFateName || ''自定义''}\n以下为内容\n${customFateDesc || ''未填写''}\n\n`;
            }
            if (selectedFates.length === 0 && !customFateName && !customFateDesc) {
                 summaryText += "尚未选择命运\n"; 
            }
            summaryText += `\n===== 刷新次数 =====\n${refreshCount} 次`;
            summaryContent.textContent = summaryText;
        }
        function copySummary() {
            const textToCopy = summaryContent.textContent;
            const showSuccessFeedback = () => {
                const originalText = copyBtn.innerHTML;
                copyBtn.innerHTML = ''<i class="fas fa-check"></i> 已复制'';
                setTimeout(() => { copyBtn.innerHTML = '' <i class="fas fa-copy"></i> 复制登录书''; }, 2000);
            };
            const fallbackCopyTextToClipboard = (text) => {
                try {
                    const textArea = document.createElement("textarea");
                    textArea.value = text;
                    textArea.style.position = "fixed";
                    textArea.style.left = "0";
                    textArea.style.top = "0";
                    textArea.style.opacity = "0";
                    document.body.appendChild(textArea);
                    textArea.focus();
                    textArea.select();
                    const successful = document.execCommand(''copy'');
                    document.body.removeChild(textArea);
                    if (successful) {
                        showSuccessFeedback();
                    } else {
                        alert(''复制失败，请尝试手动截图。'');
                    }
                } catch (err) {
                    alert(''无法复制: '' + err);
                }
            };
            if (!navigator.clipboard) {
                fallbackCopyTextToClipboard(textToCopy);
                return;
            }
            navigator.clipboard.writeText(textToCopy).then(
                function() {
                    showSuccessFeedback();
                }, 
                function(err) {
                    fallbackCopyTextToClipboard(textToCopy);
                }
            );
        }
        currentFates = generateFates();
        renderFates(currentFates);
        updateProbabilityDisplay();
        updateSummary();
        refreshBtn.addEventListener(''click'', refreshFates);
        copyBtn.addEventListener(''click'', copySummary);
        introOptions.forEach(option => {
            option.addEventListener(''click'', () => {
                const currentSelected = document.querySelector(''.intro-option.selected'');
                if (currentSelected) currentSelected.classList.remove(''selected'');
                option.classList.add(''selected'');
                selectedIntro = option.dataset.intro;
                customIntroContainer.style.display = (selectedIntro === ''custom'') %s ''block'' : ''none'';
                updateSummary();
            });
        });
        document.querySelectorAll(''input, textarea, select'').forEach(input => {
            input.addEventListener(''input'', updateSummary);
            input.addEventListener(''change'', updateSummary);
        });
        document.getElementById(''custom-fate-name'').addEventListener(''input'', updateSummary);
        document.getElementById(''custom-fate-desc'').addEventListener(''input'', updateSummary);
    }
    </script>
</body>
</html>', 'R18', '2026-10-11 11:21:56', '2026-10-11 11:21:56', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
