/* 全局设定 */
body {
  background-color: #f0f2f5;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px;
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang SC", "Microsoft YaHei", "Source Han Sans SC", "Noto Sans CJK SC", "WenQuanYi Micro Hei", sans-serif;
}

/* 聊天窗口总容器 - 宽度从375缩小到260 */
.wechat-container {
  width: 260px;
  max-height: 80vh;
  border: 1px solid #dcdcdc;
  background-color: #ededed;
  display: flex;
  flex-direction: column;
  box-shadow: 0 3px 8px rgba(0,0,0,0.1);
  border-radius: 6px;
  overflow: hidden;
}

/* 顶部标题栏 */
.wechat-header {
  background-color: #f7f7f7;
  border-bottom: 1px solid #e7e7e7;
  padding: 8px 0; /* 缩小内边距 */
  text-align: center;
  flex-shrink: 0;
}

.wechat-title {
  font-size: 12px; /* 字体缩小 */
  font-weight: 600;
  color: #181818;
}

/* 消息区域 */
.wechat-messages {
  flex-grow: 1;
  padding: 14px 7px; /* 缩小内边距 */
  overflow-y: auto;
}

/* 系统消息 */
.system-message {
  text-align: center;
  font-size: 10px; /* 字体缩小 */
  color: #b2b2b2;
  margin: 7px auto;
  padding: 1px 6px;
  background-color: #dadada;
  display: table;
  border-radius: 3px;
}

/* 消息行 */
.message-row {
  display: flex;
  margin-bottom: 10px; /* 间距缩小 */
  align-items: flex-start;
}

.message-row.left {
  justify-content: flex-start;
}

.message-row.right {
  justify-content: flex-end;
}

/* 头像 - 从40px缩小到28px */
.avatar {
  width: 28px;
  height: 28px;
  border-radius: 4px;
  background-color: #ff5252;
  color: white;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 11px; /* 字体缩小 */
  font-weight: bold;
  flex-shrink: 0;
}

.avatar.user {
  background-color: #4a90e2;
}

/* 消息内容容器 */
.message-content {
  display: flex;
  flex-direction: column;
  max-width: calc(100% - 60px);
}

.message-row.left .message-content {
  margin-left: 7px;
}

.message-row.right .message-content {
  margin-right: 7px;
}

/* 发送者名字 - 特殊处理缩小 */
.sender-name {
  font-size: 10px; /* 基础字体设小 */
  color: #888;
  margin-bottom: 2px;
  padding: 0 1px;
  /* 使用transform进一步缩小以满足"缩小40%"的视觉要求 */
  transform: scale(0.7); 
  transform-origin: left bottom; /* 左侧名字左对齐缩放 */
  white-space: nowrap;
}

.sender-name.right {
  text-align: right;
  transform-origin: right bottom; /* 右侧名字右对齐缩放 */
}

/* 消息气泡 */
.bubble {
  padding: 7px 9px; /* 内边距缩小 */
  border-radius: 4px;
  font-size: 11px; /* 字体缩小 */
  line-height: 1.4;
  word-wrap: break-word;
  position: relative;
  box-shadow: 0 1px 2px rgba(0,0,0,0.05);
}

.bubble.left {
  background-color: #ffffff;
  color: #000000;
}

.bubble.right {
  background-color: #95ec69;
  color: #000000;
}

/* 气泡小三角 - 尺寸缩小 */
.bubble.left::before {
  content: '''';
  position: absolute;
  left: -4px;
  top: 9px;
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 4px 4px 4px 0;
  border-color: transparent #ffffff transparent transparent;
}

.bubble.right::before {
  content: '''';
  position: absolute;
  right: -4px;
  top: 9px;
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 4px 0 4px 4px;
  border-color: transparent transparent transparent #95ec69;
}

/* 底部输入栏 */
.wechat-input-bar {
  height: 35px; /* 高度缩小 */
  background-color: #f7f7f7;
  border-top: 1px solid #e7e7e7;
  flex-shrink: 0;
}









