INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('7a68d42a-e4bf-4eaf-961d-991baeb50232', '【CG立绘】巨​乳妹妹还债生活', '立绘 · 动态CG', '👙', '妹妹还债', '【CG立绘】巨​乳妹妹还债生活', '👙', '#f43f5e', 'linear-gradient(135deg, #f43f5e 0%, #ec4899 100%)', '{"title": "【CG立绘】巨​乳妹妹还债生活", "desc": "300+张CG！101套立绘！46种表情！父母欠下巨债后不知所踪，你与相依为命的巨乳妹妹在逼仄出租屋开启了充满波折与心跳的还债同居生活。", "bg_image": "https://catai.wiki/89a4287a-1fd9-44ac-c01d-408f043b2000/bg", "opening_options": ["【相依为命】：温柔安抚慌乱的妹妹，承诺共同承担债务", "【盘算账目】：冷静规划打工与还债计划，建立开支账本", "【危险试探】：在债务重压的狭窄房间内，试探彼此的感情界限"]}', '[{"name": "主角 (哥哥)", "role": "故事主角 / 决策者", "desc": "为了保护妹妹并偿还家庭巨债而拼搏的青年，每一个抉择都将影响妹妹的命运与心智走向。"}, {"name": "妹妹", "role": "核心女主 / 巨乳相依为命少女", "desc": "拥有惊人曼妙身材与绝美容颜的妹妹，性格柔弱依赖却又渴望为哥哥分忧，在巨额债务的阴影下暗自挣扎。"}]', '[{"title": "狭窄昏暗的出租屋开局", "desc": "堆满逾期账单的逼仄小房间，瓦数不高的暖黄吊灯下，两人面对巨债抉择的命运之夜。"}]', '{"dialogue_style": "融合CG立绘与丰富表情插图的超沉浸视觉Galgame物语，人物心理细腻，充满张力", "format": "内置459张原画立绘与CG动态切片，支持.story-image及.custom-ui联动"}', '[{"index": 1, "isUser": false, "scene": "深夜逼仄出租屋", "story": "<tl>📅时间：深夜 | 🌏地点：狭窄出租屋客厅</tl>\n\n<article>\n<div class=\"story-image img-BG-01\"></div>\n<p>逼仄昏暗的单间出租屋里，只有一盏瓦数不高的暖黄吊灯在头顶微微摇晃。茶几上凌乱堆叠着印有鲜红“逾期催缴”字样的巨额债务单据。</p>\n\n<div class=\"story-image img-BQ-01\"></div>\n<p>妹妹穿着单薄宽松的居家旧睡裙，低垂着头紧咬下唇，纤细白皙的十指用力揪着裙摆，饱满挺拔的胸脯随着压抑的呼吸剧烈起伏。她抬起泪光涟涟的双眸望向你，声音微颤：“哥……催债的人说，如果这个月底再还不上第一期利息，他们就要把你……我们该怎么办啊……”</p>\n</article>", "branches": [{"tag": "A", "title": "温柔安抚紧紧相拥", "desc": "伸手揽住她战栗的肩膀，坚定承诺只要有哥在天就塌不下来"}, {"tag": "B", "title": "拿起账单冷静盘算", "desc": "拿起茶几上的催缴单仔细核对利息与本金，开始筹划两人的打工兼职"}, {"tag": "C", "title": "深沉凝视试探底线", "desc": "目光扫过她单薄睡裙下泛着绯红的娇躯，低声询问她能为这个家做到哪一步"}]}]', '/* ========== 樱泉密事 · 界面美化 ========== */
/* —— 主题变量参考 ——
