    drop-shadow(0 0 6px rgba(255, 183, 197, 0.45)) !important;

  /* 关键：两个独立动画并行
     A. cake-girl-frames 3s：每张图各占 1s 离散切换
     B. cake-girl-sway 1s：每张图显示期间完成一次完整摆动 */
  animation:
    cake-girl-frames 3s linear infinite,
    cake-girl-sway 1s ease-in-out infinite !important;
}

/* 4. 图片切换动画：background-image 本身不可插值，会自动跳变 */
@keyframes cake-girl-frames {
