INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_d8ab1654', '🐉我即系统!🐉【自定义系统任务及奖励】', 'AI风月收录 · 纯爱肉卡', '📖', '🐉我即系统!🐉【自定义系统任务及奖励】', '', '📖', 'rose', 'from-rose-600 to-pink-600', '{}', '[{"name": "主角(女生)", "tag": "反差优等生 / 核心女主", "roleType": "女主", "color": "rose", "desc": "<strong>外在面具与设定：</strong> 【无玩家本体。玩家本身即为系统】【绑定一个人，给 ta 发任务、给 ta 奖励——ta 以为自己觉醒了系统，却不知道那个系统就是你】\n【可进入任何世界观 · 绑...<br><strong>隐性诱饵：</strong> 拥有极度羞耻的反差秘密，被抓住把柄后从虚张声势快速瓦解为带哭腔的服从。"}, {"name": "玩家(主角)", "tag": "秘密掌控者", "roleType": "男主", "color": "blue", "desc": "<strong>定位：</strong> 撞破秘密的绝对支配者。在逗弄、把柄压制与极致深情的占有中逐步瓦解防线。"}]', '[{"title": "📍 开场核心事件: 秘密撞破", "desc": "【无玩家本体。玩家本身即为系统】【绑定一个人，给 ta 发任务、给 ta 奖励——ta 以为自己觉醒了系统，却不知道那个系统就是你】\n【可进入任何世界观 · 绑...", "text": "【无玩家本体。玩家本身即为系统】【绑定一个人，给 ta 发任务、给 ta 奖励——ta 以为自己觉醒了系统，却不知道那个系统就是你】\n【可进入任何世界观 · 绑定对象完全自定义】\n你绑定了一个人。\n从此 ta 的世界里，多了一个只有 ta 看得见的系统：发布任务、给予奖励、循循善诱。\nta 兴冲冲地接任务、领奖励、变得越来越好——ta 以为这是自己的金手指，是命运的馈赠。\n只有你知道：每一条任务、每一份奖励，都是你写的；ta 走的每一步，都是你让 ta 走的。"}]', '[{"name": "把柄施压", "desc": "以抓包把柄居高临下试探防线，言语坏笑逼其就范"}, {"name": "强势掌控", "desc": "果断反客为主制住双手与退路，粉碎一切虚张声势"}, {"name": "温柔诱捕", "desc": "在羞耻破防时给予温柔安抚，将其完全融化在怀中"}, {"name": "假意呼救", "desc": "故意制造门外动静，引诱对方慌乱用唇封口求饶"}]', '{"location": "密闭场景深处·黄昏时刻。光线昏暗，门外走廊隐约传来脚步声与杂音。", "story": "【无玩家本体。玩家本身即为系统】【绑定一个人，给 ta 发任务、给 ta 奖励——ta 以为自己觉醒了系统，却不知道那个系统就是你】\n【可进入任何世界观 · 绑定对象完全自定义】\n你绑定了一个人。\n从此 ta 的世界里，多了一个只有 ta 看得见的系统：发布任务、给予奖励、循循善诱。\nta 兴冲冲地接任务、领奖励、变得越来越好——ta 以为这是自己的金手指，是命运的馈赠。\n只有你知道：每一条任务、每一份奖励，都是你写的；ta 走的每一步，都是你让 ta 走的。\n\n对方发抖的双手紧紧揪着你的衣角，因为心跳失速眼眶瞬间盈满水汽，身子在逼仄的角落里瑟瑟发抖……", "memory": ["开局事件：撞破绝密隐私", "权力颠倒：对方从试图恐吓迅速转向慌乱与哀求", "外部环境：门外有脚步声走动，随时可能被发现"], "status": {"clothes": "制服微敞、领结凌乱、百褶裙被挤压上移", "posture": "被逼至墙角/书架死角、双手抵在男主胸口、身体紧贴颤抖", "stats": "心跳指数: 155bpm | 羞耻度: 95% | 屈从度: 82%", "risk": "门外脚步声逼近，被抓风险 75%"}, "branches": [{"tag": "A", "title": "强势反制", "desc": "反手扣住她发抖的手腕压在墙上，低声审问是否真的什么都听你的"}, {"tag": "B", "title": "把柄威胁", "desc": "将她的秘密拿在手中把玩，居高临下逼她亲口叫一声动听的称呼"}, {"tag": "C", "title": "极度温存", "desc": "顺势环住她微颤的腰肢，低头拭去眼角泪水将恐惧转化为依恋"}, {"tag": "D", "title": "佯装呼救", "desc": "作势要惊动门外路过的人，引她惊恐失措主动投怀用唇封口"}]}', NULL, '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>🐉我即系统!🐉【自定义系统任务及奖励】</title>
<link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;700&display=swap" rel="stylesheet">
<style>
    :root{
        --soft-white:#ffffff;
        --cream-bg:#fdfcf8;
        --accent-gold:#06b6d4;
        --accent-purple:#8b5cf6;
        --text-dark:#2d2d2d;
        --text-gray:#6d6d6d;
        --border-color:#efe6ff;
        --shadow:0 12px 42px rgba(120,90,160,0.10);
        --shadow-soft:0 6px 20px rgba(120,90,160,0.07);
    }
    *{box-sizing:border-box;}
    html,body{margin:0;padding:0;}
    body{
        font-family:''Noto Serif SC'',"PingFang SC","Microsoft YaHei",serif;
        background:linear-gradient(180deg,#fcfaff 0%,#f0f9ff 45%,#fcfaff 100%);
        color:var(--text-dark);
        line-height:1.85;
        padding:18px 14px 60px;
        -webkit-font-smoothing:antialiased;
    }
    .page{max-width:880px;margin:0 auto;}
    .hero{
        position:relative;
        text-align:center;
        padding:46px 24px 40px;
        background:linear-gradient(135deg,#f5f3ff 0%,#e0f2fe 55%,#fdfcf8 100%);
        border-radius:30px;
        border:1px solid var(--border-color);
        box-shadow:var(--shadow);
        margin-bottom:24px;
        overflow:hidden;
    }
    .hero-tag{
        position:relative;
        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#6366f1;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
        position:relative;
        font-size:28px;
        letter-spacing:1.5px;
        margin:20px 0 10px;
        color:#332b4d;
    }
    .hero .hero-sub{
        position:relative;
        color:var(--accent-purple);
        font-size:14px;
        letter-spacing:3px;
        margin:0;
    }
    .hero .hero-line{
        position:relative;
        width:60px;height:2px;
        background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);
        margin:18px auto 0;
    }
    .card{
        background:var(--soft-white);
        border-radius:24px;
        padding:28px 26px;
        margin-bottom:22px;
        box-shadow:var(--shadow-soft);
        border:1px solid #f2edfb;
    }
    .section-title{
        display:flex;
        align-items:center;
        gap:12px;
        font-size:18.5px;
        font-weight:700;
        color:#3a3350;
        margin:0 0 18px;
        letter-spacing:1px;
    }
    .section-title::before{
        content:"";
        width:6px;height:22px;
        border-radius:4px;
        background:linear-gradient(180deg,var(--accent-purple),var(--accent-gold));
        display:inline-block;
    }
    .section-sub{
        color:var(--text-gray);
        font-size:13px;
        margin:-10px 0 16px;
    }
    p{margin:0 0 14px;}
    .story-text{color:#4a4458;font-size:15px;line-height:1.9;white-space:pre-line;}
    .profile-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
        gap:16px;
    }
    .p-item{
        background:linear-gradient(160deg,#fdfbff,#fff9f2);
        border:1px solid #f0eafc;
        border-radius:18px;
        padding:18px 20px;
        transition:.25s;
    }
    .p-item:hover{transform:translateY(-3px);box-shadow:var(--shadow-soft);}
    .p-item h4{
        margin:0 0 10px;
        font-size:15px;
        color:var(--accent-purple);
        display:flex;align-items:center;gap:8px;
    }
    .p-item h4 .dot{
        width:8px;height:8px;border-radius:50%;
        background:var(--accent-gold);
        display:inline-block;
    }
    .p-item p{margin:0;font-size:13.5px;color:#5a5468;line-height:1.75;}
    .mech-list{list-style:none;padding:0;margin:0;}
    .mech-list li{
        display:flex;gap:14px;
        padding:14px 16px;
        border-radius:16px;
        background:#fbf9ff;
        border:1px solid #f1ebfc;
        margin-bottom:12px;
        font-size:13.5px;color:#544e64;
        align-items:flex-start;
    }
    .mech-list li .badge{
        flex:0 0 auto;
        font-size:11.5px;
        font-weight:700;
        padding:4px 10px;
        border-radius:999px;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);
        letter-spacing:1px;
    }
    .form-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
        gap:16px;
    }
    .field{display:flex;flex-direction:column;gap:7px;}
    .field label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .field input,.field textarea{
        font-family:inherit;font-size:14px;color:#3d374d;
        background:#fdfcff;border:1.5px solid #ece5fa;border-radius:14px;
        padding:12px 14px;outline:none;transition:.2s;
    }
    .field input:focus,.field textarea:focus{
        border-color:#c9b6ec;background:#fff;
        box-shadow:0 0 0 4px rgba(157,142,199,0.12);
    }
    .full{grid-column:1/-1;}
    .opening-list{display:flex;flex-direction:column;gap:14px;margin-bottom:20px;}
    .opening-card{
        position:relative;border:1.5px solid #efe9fb;border-radius:18px;
        padding:16px 18px 16px 54px;background:#fdfcff;cursor:pointer;
        transition:.22s;font-size:13.5px;color:#4f4960;line-height:1.78;
    }
    .opening-card:hover{border-color:#d6c6f2;background:#fbf8ff;}
    .opening-card .idx{
        position:absolute;left:16px;top:16px;width:26px;height:26px;
        border-radius:9px;background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);font-size:12px;font-weight:700;
        display:flex;align-items:center;justify-content:center;
    }
    .opening-card .tag{
        display:inline-block;font-size:11px;font-weight:700;letter-spacing:1px;
        color:#b07a86;background:#fdeef1;border-radius:6px;padding:2px 9px;margin-bottom:7px;
    }
    .opening-card.selected{
        border-color:var(--accent-purple);
        background:linear-gradient(160deg,#faf6ff,#fff9f3);
        box-shadow:0 8px 24px rgba(157,142,199,0.16);
    }
    .opening-card.selected .idx{
        background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        color:#fff;
    }
    .custom-box{display:flex;flex-direction:column;gap:8px;margin-bottom:22px;}
    .custom-box label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .custom-box textarea{
        font-family:inherit;font-size:14px;color:#3d374d;background:#fdfcff;
        border:1.5px solid #ece5fa;border-radius:14px;padding:12px 14px;
        outline:none;resize:vertical;min-height:88px;line-height:1.7;
    }
    .gen-wrap{text-align:center;margin-top:6px;}
    .gen-btn{
        font-family:inherit;cursor:pointer;border:none;padding:15px 56px;
        border-radius:999px;font-size:15px;font-weight:700;letter-spacing:3px;
        color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 12px 28px rgba(157,142,199,0.35);transition:.25s;
    }
    .gen-btn:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(157,142,199,0.45);}
    .summary-card{background:linear-gradient(160deg,#fffcfa,#f8f3ff);border:1px solid #f0e8fd;}
    .summary-inner{
        background:#fffdfb;border:1px dashed #e3d9f5;border-radius:18px;
        padding:20px;min-height:110px;font-size:13.8px;color:#514b62;line-height:1.9;
        white-space:pre-wrap;word-break:break-word;
    }
    .copy-wrap{text-align:center;margin-top:-6px;margin-bottom:20px;}
    .copy-btn{
        font-family:inherit;cursor:pointer;width:100%;max-width:880px;border:none;
        padding:16px 20px;border-radius:18px;font-size:15.5px;font-weight:700;
        letter-spacing:3px;color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 14px 34px rgba(143,126,201,0.38);transition:.25s;
    }
    .copy-btn:hover{transform:translateY(-2px);box-shadow:0 18px 40px rgba(143,126,201,0.48);}
    @media (max-width:600px){
        body{padding:12px 10px 46px;}
        .hero{padding:34px 18px 30px;border-radius:24px;}
        .hero h1{font-size:22px;}
        .card{padding:20px 16px;}
        .profile-grid,.form-grid{grid-template-columns:1fr;}
        .opening-card{padding:14px 15px 14px 48px;font-size:13px;}
        .gen-btn{width:100%;padding:14px;}
    }
</style>
</head>
<body>
<div class="page">
    <div class="hero">
        <span class="hero-tag">AI风月收录 · 纯爱肉卡</span>
        <h1>🐉我即系统!🐉【自定义系统任务及奖励】</h1>
        <p class="hero-sub">沉 浸 式 角 色 扮 演 · 独 家 设 定</p>
        <div class="hero-line"></div>
    </div>

    <div class="card">
        <h2 class="section-title">背景故事</h2>
        <div class="story-text">
            【无玩家本体。玩家本身即为系统】【绑定一个人，给 ta 发任务、给 ta 奖励——ta 以为自己觉醒了系统，却不知道那个系统就是你】
【可进入任何世界观 · 绑定对象完全自定义】
你绑定了一个人。
从此 ta 的世界里，多了一个只有 ta 看得见的系统：发布任务、给予奖励、循循善诱。
ta 兴冲冲地接任务、领奖励、变得越来越好——ta 以为这是自己的金手指，……
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">人物介绍</h2>
        <p class="section-sub">核心出场人物与心理侧写</p>
        <div class="profile-grid">
            
            <div class="p-item">
                <h4><span class="dot"></span>主角(女生) · 登场人物</h4>
                <p><strong>外在面具与设定：</strong> 【无玩家本体。玩家本身即为系统】【绑定一个人，给 ta 发任务、给 ta 奖励——ta 以为自己觉醒了系统，却不知道那个系统就是你】
【可进入任何世界观 · 绑...<br><strong>隐性诱饵：</strong> 拥有极度羞耻的反差秘密，被抓住把柄后从虚张声势快速瓦解为带哭腔的服从。</p>
            </div>
            
            <div class="p-item">
                <h4><span class="dot"></span>玩家(主角) · 登场人物</h4>
                <p><strong>定位：</strong> 撞破秘密的绝对支配者。在逗弄、把柄压制与极致深情的占有中逐步瓦解防线。</p>
            </div>
            
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">核心机制与场景</h2>
        <ul class="mech-list">
            
            <li><span class="badge">场所</span><div><b>📍 开场核心事件: 秘密撞破</b>：【无玩家本体。玩家本身即为系统】【绑定一个人，给 ta 发任务、给 ta 奖励——ta 以为自己觉醒了系统，却不知道那个系统就是你】
【可进入任何世界观 · 绑...</div></li>
            
        </ul>
    </div>

    <div class="card">
        <h2 class="section-title">玩家设定</h2>
        <p class="section-sub">填写你的个性化专属属性，将随选定的开场白一起生效。</p>
        <div class="form-grid">
            <div class="field">
                <label>玩家姓名</label>
                <input id="p-name" type="text" placeholder="例如：林铭宇 / 顾言">
            </div>
            <div class="field">
                <label>玩家年龄</label>
                <input id="p-age" type="text" placeholder="例如：20 / 24">
            </div>
            <div class="field full">
                <label>外貌与体态</label>
                <input id="p-look" type="text" placeholder="例如：身材修长匀称，眼神干净深邃，气质沉稳">
            </div>
            <div class="field full">
                <label>核心特征 / 专属能力</label>
                <textarea id="p-cock" rows="2" placeholder="例如：体能极佳，掌控欲强，或拥有特殊因果律/权限"></textarea>
            </div>
            <div class="field full">
                <label>补充设定 / 关系羁绊</label>
                <textarea id="p-other" rows="2" placeholder="例如：与主要角色相识已久，表面克制但内心独占欲深厚"></textarea>
            </div>
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">开场白选择</h2>
        <p class="section-sub">点击卡片选择想要切入的剧情节点，或在下方自定义。</p>
        <div class="opening-list" id="openingList"></div>

        <div class="custom-box">
            <label>自定义开场白（可选，若填写则优先使用）</label>
            <textarea id="customOpening" placeholder="在这里写下你构想的开场剧情……"></textarea>
        </div>

        <div class="gen-wrap">
            <button class="gen-btn" id="genBtn">生 成 设 定</button>
        </div>
    </div>

    <div class="card summary-card">
        <h2 class="section-title">总结区</h2>
        <div class="summary-inner" id="summaryBox">
            <span style="color:#b0a9c2;font-style:italic;">点击上方【生成设定】按钮，玩家设定与所选开场白将自动汇总到这里。</span>
        </div>
    </div>

    <div class="copy-wrap">
        <button class="copy-btn" id="copyBtn">一 键 复 制</button>
    </div>
</div>

<script>
    const OPENINGS = [{"tag": "官方开局 · 核心第一幕", "cls": "daily", "text": "【无玩家本体。玩家本身即为系统】【绑定一个人，给 ta 发任务、给 ta 奖励——ta 以为自己觉醒了系统，却不知道那个系统就是你】 【可进入任何世界观 · 绑定对象完全自定义】 你绑定了一个人。 从此 ta 的世界里，多了一个只有 ta 看得见的系统：发布任务、给予奖励、循循善诱。 ta 兴冲冲地接任务、领奖励、变得越来越好——ta 以为这是自己的金手指，是命运的馈赠。 只有你知道：每一条任务、每一份奖励，都是你写的；ta 走的每一步，都是你让 ta 走的。  对方发抖的双手紧紧揪着你的衣角，因为心跳失速眼眶瞬间盈满水汽，身子在逼仄的角落里瑟瑟发抖……"}, {"tag": "走向 · 强势反制", "cls": "", "text": "【无玩家本体。玩家本身即为系统】【绑定一个人，给 ta 发任务、给 ta 奖励——ta 以为自己觉醒了系统，却不知道那个系统就是你】 【可进入任何世界观 · 绑定对象完全自定义】 你绑定了一个人。 从……针对这一情况，你决定【强势反制】：反手扣住她发抖的手腕压在墙上，低声审问是否真的什么都听你的。"}, {"tag": "走向 · 把柄威胁", "cls": "", "text": "【无玩家本体。玩家本身即为系统】【绑定一个人，给 ta 发任务、给 ta 奖励——ta 以为自己觉醒了系统，却不知道那个系统就是你】 【可进入任何世界观 · 绑定对象完全自定义】 你绑定了一个人。 从……针对这一情况，你决定【把柄威胁】：将她的秘密拿在手中把玩，居高临下逼她亲口叫一声动听的称呼。"}, {"tag": "走向 · 极度温存", "cls": "", "text": "【无玩家本体。玩家本身即为系统】【绑定一个人，给 ta 发任务、给 ta 奖励——ta 以为自己觉醒了系统，却不知道那个系统就是你】 【可进入任何世界观 · 绑定对象完全自定义】 你绑定了一个人。 从……针对这一情况，你决定【极度温存】：顺势环住她微颤的腰肢，低头拭去眼角泪水将恐惧转化为依恋。"}, {"tag": "走向 · 佯装呼救", "cls": "", "text": "【无玩家本体。玩家本身即为系统】【绑定一个人，给 ta 发任务、给 ta 奖励——ta 以为自己觉醒了系统，却不知道那个系统就是你】 【可进入任何世界观 · 绑定对象完全自定义】 你绑定了一个人。 从……针对这一情况，你决定【佯装呼救】：作势要惊动门外路过的人，引她惊恐失措主动投怀用唇封口。"}];
    let selectedIndex = 0;
    const listEl = document.getElementById(''openingList'');
    OPENINGS.forEach(function (op, i) {
        const card = document.createElement(''div'');
        card.className = ''opening-card'' + (i === 0 %s '' selected'' : '''');
        card.dataset.index = i;
        card.innerHTML = ''<span class="idx">'' + (i + 1) + ''</span>'' +
                         ''<span class="tag '' + op.cls + ''">'' + op.tag + ''</span><br>'' +
                         op.text;
        card.addEventListener(''click'', function () {
            document.querySelectorAll(''.opening-card'').forEach(function (c) {
                c.classList.remove(''selected'');
            });
            card.classList.add(''selected'');
            selectedIndex = i;
        });
        listEl.appendChild(card);
    });

    const summaryBox = document.getElementById(''summaryBox'');
    const copyBtn = document.getElementById(''copyBtn'');
    let lastSummaryText = '''';

    function val(id) {
        const v = document.getElementById(id).value.trim();
        return v %s v : ''（未填写）'';
    }

    document.getElementById(''genBtn'').addEventListener(''click'', function () {
        const name = val(''p-name'');
        const age = val(''p-age'');
        const look = val(''p-look'');
        const cock = val(''p-cock'');
        const other = val(''p-other'');

        const custom = document.getElementById(''customOpening'').value.trim();
        const chosen = custom %s custom : OPENINGS[selectedIndex].text;
        const chosenTag = custom %s ''自定义开场白'' : OPENINGS[selectedIndex].tag;

        let out = '''';
        out += ''【玩家设定】\n'';
        out += ''姓名：'' + name + ''\n'';
        out += ''年龄：'' + age + ''\n'';
        out += ''外貌：'' + look + ''\n'';
        out += ''特质设定：'' + cock + ''\n'';
        out += ''其他设定：'' + other + ''\n\n'';
        out += ''【开场白 · '' + chosenTag + ''】\n'';
        out += chosen;

        lastSummaryText = out;
        summaryBox.textContent = out;
        summaryBox.scrollIntoView({behavior: ''smooth'', block: ''start''});
    });

    copyBtn.addEventListener(''click'', function () {
        if (!lastSummaryText) { lastSummaryText = summaryBox.textContent; }
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(lastSummaryText).then(function() {
                copyBtn.textContent = ''已 复 制 ✓'';
                setTimeout(function() { copyBtn.textContent = ''一 键 复 制''; }, 1800);
            });
        }
    });
</script>
</body>
</html>', '都市', '2026-09-12 02:01:42', '2026-09-12 02:01:42', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_classmate_xia_wanyu', '暴露癖同桌的深夜展示', '校园 · 深夜窥见', '🌙', '暴露癖同桌的深夜展示', '暴露癖同桌的深夜展示', '🌙', '#a855f7', 'linear-gradient(135deg, #9333ea 0%, #c084fc 100%)', '{"title": "暴露癖同桌的深夜展示", "desc": "（记得看评论区）《重大更新》优化了页面以及夏晚妤在不同分支下好感度以及奴性的影响（半重做）\n深夜十一点半，教学楼早已熄灯。你返回教室拿作业，却透过窗户看到了这辈子最难以置信的画面——\n你的同桌夏晚妤，那个每天早上对你小声说“早安”、被老师点名时脸红到耳根的乖乖女班长，正全裸地坐在讲台上。她的校服被整齐叠好放在课桌上。她背对着你，双腿大开，用讲台桌角摩擦着自己的下体。压抑的喘息在空教室里回荡。\n她对着空无一人的座位自言自语：“你们在看吗……班长在讲台上做这种事，很意外吧……”\n她不知道窗外有人在注视。她不知道她的同桌正蹲在后门外面。\n你在窗外蹲了很久。你有三个选择：默默成为她每晚的秘密观众，看她一天比一天大胆；推开门，成为她第一个真实观众，开启一段白天与黑夜截然不同的秘密关系；或者推开门，用她的秘密换取她完全的服从。\n她是你的同桌。这个秘密，只有你知道。\n和角色卡相比加强了设定，有什么问题可", "bg_image": "https://catai.wiki/5cf8a3e0-353a-47f8-09ee-daa3232acd00/bg", "opening_options": ["【深入互动】：依循情境展开深入探索与对话", "【试探心理】：保持警觉，观察对方隐秘情绪与微妙反应", "【掌控局势】：以坚定主动态度引导场景走向"]}', '[{"name": "主角 (玩家)", "role": "核心视角", "desc": "故事的决策者与见证者，每一次对话抉择都将决定剧情与好感走向。"}, {"name": "夏晚妤", "role": "乖巧班长 / 你的同桌", "desc": "高二二班班长兼同桌，年级前十，圆框眼镜短发，白皙清秀，平时极度容易害羞。深夜却独自在熄灯教室讲台大胆露出，沉溺于被注视的快感。"}]', '[{"title": "深夜十一点半的讲台", "desc": "教学楼全员熄灯的深夜，手机微光化作舞台聚光灯，你在折返拿作业时直面了乖乖女班长毫无防备的赤裸秘密。"}]', '{"dialogue_style": "细腻深邃的情感描写，极具沉浸感的人物神态心理博弈与生动对话", "format": "幻诺剧场标准交互规范及.custom-ui手账联动"}', '[{"index": 1, "isUser": false, "scene": "深夜十一点半的讲台", "story": "<tl>📅时间：关键时刻 | 🌏地点：深夜十一点半的讲台</tl>\n\n<article>\n<p>深夜十一点半，整栋高二教学楼早已归于死寂。\n\n你因为遗落了明天一早就要检查的物理重点作业，借着手机屏幕微弱的亮光轻手轻脚摸回教室后门。然而隔着窗玻璃，讲台上投下的一抹光晕却骤然攥住了你的视线——\n\n那竟是你的同桌、每天早上都会脸红着轻声向你道早安的模范班长夏晚妤。她整齐折叠好校服放在一旁课桌上，此刻正近乎全裸地坐在微凉的讲台边，两颊泛着不自然的潮红，闭着双眼沉浸在压抑而急促的低吟声中。推门的细微响动在空荡教室内回荡，夏晚妤瞬间僵住了动作，像一只受惊的小鹿猛然转过头来，水汽氤氲的眸子里写满了恐惧与耻辱。</p>\n</article>", "branches": [{"tag": "A", "title": "轻声唤出班长名字", "desc": "压低声线轻唤“夏班长……？”，安抚她不要惊慌失措"}, {"tag": "B", "title": "随手反锁教室房门", "desc": "顺势合上门并按下内锁，杜绝巡夜保安发现的可能"}, {"tag": "C", "title": "上前帮她遮掩校服", "desc": "拿起课桌上的校服走向讲台，将衣服温柔披在她战栗的肩头"}]}]', '/* ================= 全局背景（深夜月光淡蓝） ================= */
body {
    background: radial-gradient(ellipse at 50% 0%, #16223b 0%, #0a1120 50%, #04060a 100%) !important;
    background-attachment: fixed !important;
    color: #c8d8f0;
}

/* ================= 正文气泡（淡蓝琉璃风） ================= */
.rk-main-text {
    position: relative; 
    color: #d0e0f8; 
    font-size: 15px; 
    line-height: 2.0; 
    letter-spacing: 0.5px;
    background: rgba(20, 35, 60, 0.75);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(100, 180, 255, 0.4);
    border-radius: 18px; 
    padding: 20px 22px; 
    margin: 14px 0;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.5), inset 0 0 15px rgba(100, 180, 255, 0.05); 
    z-index: 1;
}

/* 夏晚妤的台词强制蓝色高亮（配合正则脚本强行染色） */
.sister-xia { 
    color: #4db8ff !important; 
    font-weight: 700; 
    text-shadow: 0 0 8px rgba(77, 184, 255, 0.4); 
}

/* ================= 幕布剧场（思维链折叠区） ================= */
.rk-thinking {
    background: rgba(10, 20, 35, 0.7); 
    border-left: 4px solid #4db8ff;
    border-radius: 8px; 
    padding: 12px 16px; 
    font-size: 12px; 
    color: #8aa8c8; 
    margin-bottom: 10px;
}
.rk-thinking summary { cursor: pointer; color: #4db8ff; font-weight: bold; list-style: none; outline: none; }
.rk-thinking summary::before { content: "🎭 "; }

/* ================= 状态栏（垂直卡片列表） ================= */
.rk-status-list { display: flex; flex-direction: column; gap: 10px; margin: 14px 0; }
.rk-status-card {
    background: rgba(16, 28, 48, 0.8); 
    border: 1px solid rgba(77, 184, 255, 0.3);
    border-radius: 12px; 
    padding: 14px 16px; 
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.4);
    backdrop-filter: blur(8px);
}
.rk-status-card summary {
    cursor: pointer; font-weight: bold; font-size: 14px; color: #80c8ff;
    outline: none; user-select: none; list-style: none;
}
.rk-status-card summary::before { content: "▶ "; font-size: 12px; color: #4db8ff; }
.rk-status-content { 
    margin-top: 10px; 
    white-space: pre-wrap; 
    color: #b0c8e0; 
    font-size: 13px; 
    line-height: 1.9; 
    padding-left: 4px; 
}

/* ================= 选项按钮 ================= */
.rk-options { display: flex; flex-direction: column; gap: 10px; margin-top: 14px; }
.rk-option-item {
    background: rgba(16, 28, 48, 0.8); 
    border: 1.5px solid rgba(77, 184, 255, 0.4); 
    border-radius: 12px; 
    padding: 16px 18px; 
    color: #a0d0ff; 
    font-size: 14px; 
    font-weight: 600;
    cursor: pointer; 
    transition: all 0.25s ease; 
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}
.rk-option-item:hover {
    background: rgba(77, 184, 255, 0.15); border-color: #4db8ff;
    transform: translateY(-2px); box-shadow: 0 6px 20px rgba(77, 184, 255, 0.2);
    color: #ffffff;
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no, viewport-fit=cover">
    <title>深夜教室 · 班长夏晚妤</title>
    <style>
        :root {
            --bg-deep: #080c14;
            --bg-card: rgba(14, 16, 28, 0.38);
            --border: rgba(120, 140, 180, 0.16);
            --text: #c8ccd8;
            --text-dim: #788098;
            --accent: #8090b8;
            --accent-light: #a0b0d0;
            --warm: #c8a870;
            --moon: #d0d8e8;
        }
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Noto Sans SC", sans-serif;
            background: radial-gradient(ellipse at center, #0e1220 0%, #060810 60%, #020408 100%);
            color: var(--text);
            min-height: 100vh;
            overflow-x: hidden;
            overflow-y: auto;
            -webkit-overflow-scrolling: touch;
            display: flex;
            flex-direction: column;
            align-items: center;
            padding: 20px 16px 40px;
            position: relative;
        }
        .bg-moonlight {
            position: fixed; top: 0; left: 0; width: 100%; height: 100%;
            pointer-events: none; z-index: 0; opacity: 0.15;
            background: radial-gradient(ellipse at 30% 20%, rgba(180, 200, 230, 0.4) 0%, transparent 60%),
                        radial-gradient(ellipse at 70% 80%, rgba(200, 180, 140, 0.25) 0%, transparent 50%);
        }
        .dust-mote {
            position: absolute; border-radius: 50%;
            background: radial-gradient(circle, rgba(200, 210, 230, 0.5) 0%, transparent 70%);
            animation: moteFloat 7s infinite ease-in; opacity: 0;
        }
        @keyframes moteFloat {
            0% { transform: translateY(0) scale(0.2); opacity: 0; }
            25% { opacity: 0.8; }
            75% { opacity: 0.2; }
            100% { transform: translateY(-105vh) scale(1.6); opacity: 0; }
        }
        .main-wrapper {
            position: relative; z-index: 1; width: 100%; max-width: 500px;
            display: flex; flex-direction: column; gap: 18px;
        }
        .glass-card {
            background: var(--bg-card); backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
            border: 1px solid var(--border); border-radius: 20px;
            padding: 24px 20px; box-shadow: 0 6px 28px 0 rgba(0, 0, 0, 0.5); width: 100%;
        }
        h1 {
            font-size: 25px; text-align: center;
            background: linear-gradient(to right, #c8c8d8, #8898b8, #c8c8d8);
            -webkit-background-clip: text; -webkit-text-fill-color: transparent;
            background-clip: text; font-weight: 900; letter-spacing: 1.5px; margin-bottom: 6px;
        }
        .subtitle {
            text-align: center; font-size: 13px; color: var(--accent);
            margin-bottom: 14px; font-style: italic; letter-spacing: 1px;
            border-bottom: 1px dashed rgba(120, 140, 180, 0.2); padding-bottom: 12px;
        }
        .story-text { font-size: 14px; line-height: 1.85; color: var(--text); text-indent: 2em; margin-bottom: 10px; }
        .emphasis { color: var(--accent-light); font-weight: 600; }
        .setting-field { margin-bottom: 15px; }
        .setting-field label {
            display: block; font-size: 13px; color: #a0a8b8; margin-bottom: 5px; font-weight: 500; letter-spacing: 0.4px;
        }
        .setting-field input[type="text"], .setting-field textarea {
            width: 100%; background: rgba(6, 8, 16, 0.6); border: 1px solid var(--border);
            border-radius: 10px; padding: 10px 14px; color: var(--text);
            font-size: 14px; outline: none; transition: border-color 0.2s;
            font-family: inherit; resize: vertical;
        }
        .setting-field input:focus, .setting-field textarea:focus { border-color: rgba(140, 160, 200, 0.5); }
        .setting-field input::placeholder, .setting-field textarea::placeholder { color: #4a5068; }
        .small-hint { font-size: 11px; color: var(--text-dim); margin-top: 4px; }
        
        /* 选项组与切换开关 */
        .option-grid { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 6px; }
        .option-item {
            flex: 1; min-width: 65px; padding: 10px 8px; border-radius: 10px;
            border: 1.5px solid var(--border); background: rgba(255, 255, 255, 0.65);
            color: var(--text); text-align: center; cursor: pointer; transition: all 0.2s;
            font-size: 12px; font-weight: 600; letter-spacing: 0.3px; line-height: 1.3;
            user-select: none; -webkit-user-select: none;
        }
        .option-item.active {
            border-color: var(--accent-light); background: rgba(200, 130, 230, 0.25);
            box-shadow: 0 0 12px rgba(180, 100, 220, 0.2); color: #6a2a8a;
        }
        .option-item:active { transform: scale(0.95); }

        /* 滑块 */
        .slider-container { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-top: 6px; }
        input[type="range"] {
            flex: 1; -webkit-appearance: none; height: 8px; border-radius: 4px;
            background: rgba(120, 140, 180, 0.2); outline: none;
        }
        input[type="range"]::-webkit-slider-thumb {
            -webkit-appearance: none; width: 22px; height: 22px; border-radius: 50%;
            background: var(--accent); cursor: pointer; box-shadow: 0 0 10px rgba(160, 80, 200, 0.6); border: 2px solid #fff;
        }
        .slider-value { font-size: 15px; font-weight: 700; color: var(--warm); min-width: 55px; text-align: center; }
        .slider-comment { font-size: 12px; color: #8a5a9a; font-style: italic; min-width: 160px; }

        /* 分支选择 */
        .branch-selector { display: flex; gap: 10px; flex-wrap: wrap; }
        .branch-option {
            flex: 1; min-width: 80px; padding: 12px 8px; border-radius: 12px;
            border: 1.5px solid var(--border); background: rgba(10, 12, 22, 0.5);
            color: var(--text); text-align: center; cursor: pointer; transition: all 0.2s;
            font-size: 13px; font-weight: 500; letter-spacing: 0.5px; user-select: none;
        }
        .branch-option.active { border-color: rgba(160, 180, 210, 0.6); background: rgba(30, 40, 70, 0.5); box-shadow: 0 0 16px rgba(120, 150, 200, 0.2); color: #d0d8e8; }
        .branch-option:active { transform: scale(0.96); }
        .branch-desc { font-size: 11px; color: var(--text-dim); margin-top: 4px; display: block; }
        .branch-option.active .branch-desc { color: #a0b0c8; }

        /* 复制按钮 */
        .copy-btn {
            width: 100%; padding: 12px; border: none; border-radius: 50px;
            background: linear-gradient(135deg, #2a3048 0%, #3a4560 50%, #2a3048 100%);
            color: #d0d8e0; font-size: 15px; font-weight: bold; cursor: pointer;
            display: flex; align-items: center; justify-content: center; gap: 8px;
            transition: transform 0.1s, box-shadow 0.2s; box-shadow: 0 4px 18px rgba(0, 0, 0, 0.4);
            letter-spacing: 1px; margin-top: 8px; border: 1px solid rgba(120, 140, 180, 0.25);
        }
        .copy-btn:active { transform: scale(0.97); box-shadow: 0 2px 8px rgba(0, 0, 0, 0.5); }
        .copy-btn.copied { background: linear-gradient(135deg, #2a3a2a 0%, #3a5a3a 100%); border-color: rgba(100, 140, 100, 0.4); }

        /* 折叠面板 */
        details.rules-accordion {
            background: rgba(10, 12, 22, 0.5); border: 1px solid var(--border);
            border-radius: 14px; padding: 0; transition: all 0.25s; width: 100%;
        }
        details.rules-accordion[open] { background: rgba(14, 16, 26, 0.6); border-color: rgba(120, 140, 180, 0.35); }
        details.rules-accordion summary {
            padding: 14px 18px; font-size: 14px; font-weight: 600;
            color: #a0a8b8; cursor: pointer; list-style: none;
            display: flex; align-items: center; gap: 8px; letter-spacing: 0.5px; user-select: none;
        }
        details.rules-accordion summary::-webkit-details-marker { display: none; }
        details.rules-accordion summary::before {
            content: ''▸''; display: inline-block; transition: transform 0.3s;
            font-size: 11px; color: var(--accent); flex-shrink: 0;
        }
        details.rules-accordion[open] summary::before { transform: rotate(90deg); }
        .rules-content { padding: 4px 18px 16px 28px; font-size: 13px; line-height: 1.75; color: #a8b0c0; }
        .rules-content ul { list-style: none; padding: 0; }
        .rules-content ul li { margin-bottom: 7px; padding-left: 16px; position: relative; }
        .rules-content ul li::before { content: ''—''; position: absolute; left: 0; color: var(--accent); font-size: 10px; }
        .rules-subtitle { font-weight: 700; color: #b0b8c8; margin-top: 10px; margin-bottom: 5px; font-size: 13px; }

        /* 弹窗 */
        .copy-overlay {
            display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%;
            background: rgba(0, 0, 0, 0.7); z-index: 999; justify-content: center; align-items: center; backdrop-filter: blur(4px);
        }
        .copy-overlay.show { display: flex; }
        .copy-dialog {
            background: #0e1220; border: 1px solid var(--border); border-radius: 20px;
            padding: 22px 16px; width: 92%; max-width: 520px; max-height: 85vh;
            display: flex; flex-direction: column; gap: 12px; box-shadow: 0 10px 40px rgba(0,0,0,0.6);
        }
        .copy-dialog h3 { color: var(--accent); text-align: center; font-size: 17px; }
        .copy-dialog .instruction { font-size: 11.5px; color: var(--text-dim); text-align: center; line-height: 1.6; }
        .copy-dialog textarea {
            width: 100%; height: 250px; background: rgba(6, 8, 16, 0.8); border: 1px solid var(--border);
            border-radius: 10px; color: var(--text); font-size: 12px; padding: 12px; resize: vertical;
            font-family: inherit; line-height: 1.6; user-select: text; -webkit-user-select: text;
        }
        .btn-row-dialog { display: flex; gap: 8px; flex-wrap: wrap; }
        .btn-dialog {
            flex: 1; min-width: 70px; padding: 11px 6px; border: none; border-radius: 50px;
            font-size: 13px; font-weight: bold; cursor: pointer; text-align: center;
            transition: all 0.2s; border: 1px solid rgba(120, 140, 180, 0.25);
        }
        .btn-copy-auto { background: #3a4560; color: #fff; }
        .btn-copy-download { background: rgba(120, 140, 180, 0.2); color: #c8ccd8; }
        .btn-close-dialog { background: rgba(80, 90, 110, 0.2); color: #a0a8b8; }
        .btn-dialog:active { transform: scale(0.96); }

        @media (max-width: 480px) {
            .main-wrapper { max-width: 100%; gap: 14px; }
            .glass-card { padding: 18px 14px; }
            .story-text { font-size: 13px; line-height: 1.7; }
            .branch-selector { gap: 6px; }
            .branch-option { font-size: 12px; padding: 10px 6px; }
        }
    </style>
</head>
<body>
    <div class="bg-moonlight">
        <div class="dust-mote"></div><div class="dust-mote"></div><div class="dust-mote"></div>
        <div class="dust-mote"></div><div class="dust-mote"></div><div class="dust-mote"></div>
    </div>

    <div class="main-wrapper">
        <div class="glass-card" style="text-align: center;">
            <h1>深夜教室</h1>
            <div class="subtitle">班长 · 夏晚妤</div>
        </div>

        <div class="glass-card">
            <p class="story-text">
                教学楼已熄灯。月光从窗帘缝隙透入，手机手电筒放在讲台上是唯一光源——像聚光灯一样照亮她的身体。校服被整齐叠好放在课桌上。她正在讲台上用桌角摩擦下体，沉浸在幻想被注视的快感中。
            </p>
            <p class="story-text">
                你回教室拿忘带的作业。推开门的一瞬间，她僵住了——<span class="emphasis">全裸</span>，手还在两腿之间。你认出她是<span class="emphasis">夏晚妤</span>——班长，你的同桌，年级前十，从不迟到早退的乖乖女。她保持蹲在讲台上的姿势，眼眶发红，声音在发抖。
            </p>
            <p class="story-text">
                她是第一个知道你看到的人。而你是第一个知道她秘密的人。
            </p>
        </div>

        <div class="glass-card">
            <h2 style="font-size:17px;color:#b0b8c8;margin-bottom:12px;text-align:center;">👩 夏晚妤 · 班长</h2>
            <p style="font-size:14px;line-height:1.8;color:#c8ccd8;">
                <span class="emphasis">17岁</span>，高中二年级班长，你的同桌。身高160cm，黑长直及肩，平时用浅蓝色发夹别起碎发。戴圆框细边眼镜，圆脸，皮肤白皙，眼睛很大，嘴唇偏薄。
            </p>
            <p style="font-size:14px;line-height:1.8;color:#c8ccd8;margin-top:6px;">
                <span class="emphasis">身材：</span>C罩杯乳房，标准的半球形，饱满挺翘，乳头颜色极浅，兴奋时逐渐变成深粉色并完全硬挺。腰很细，臀部小巧但弧度恰到好处。大腿内侧皮肤白皙得能看到青色血管。
            </p>
            <p style="font-size:14px;line-height:1.8;color:#c8ccd8;margin-top:6px;">
                <span class="emphasis">性格：</span>白天是温柔乖巧的乖乖女——说话声音小，被点名回答问题时脸红到耳根。但内心深处隐藏着一个从初二就开始的秘密：她最大的幻想是在众目睽睽之下被人注视、被人占有。羞耻本身成了快感的一部分。这个秘密她藏了五年，直到今晚被你撞见。
            </p>
        </div>

        <div class="glass-card" id="branchCard">
            <h2 style="font-size:17px;color:#b0b8c8;margin-bottom:14px;text-align:center;">🔀 选择你的回应</h2>
            <p style="font-size:13px;color:var(--text-dim);text-align:center;margin-bottom:12px;">你推开门看到了她。接下来你选择——</p>
            <div class="branch-selector" id="branchSelector">
                <div class="branch-option active" data-branch="1" onclick="selectBranch(1)">
                    分支一<span class="branch-desc">秘密观众</span>
                </div>
                <div class="branch-option" data-branch="2" onclick="selectBranch(2)">
                    分支二<span class="branch-desc">观众契约</span>
                </div>
                <div class="branch-option" data-branch="3" onclick="selectBranch(3)">
                    分支三<span class="branch-desc">威胁调教</span>
                </div>
            </div>
            <div id="branchExplain" style="font-size:13px;color:#a0a8b8;margin-top:10px;text-align:center;line-height:1.7;">
                你默默退到窗外，在黑暗中观看。她不知道你在看，表演没有表演成分。白天你们仍是普通的同桌关系。
            </div>
        </div>

        <details class="rules-accordion">
            <summary>📊 数值系统与身体反应</summary>
            <div class="rules-content">
                <p class="rules-subtitle">意识与暴露</p>
                <ul>
                    <li>暴露癖唤起：随暴露程度逐渐升高，影响她的主动性和身体敏感度。</li>
                    <li>羞耻心：与暴露癖唤起互为消长。高潮时羞耻心短暂归零。</li>
                    <li>身体反应按天数升级：第1天压抑高潮→第4天潮喷首次出现→第7天可连续高潮三到五次。</li>
                </ul>
            </div>
        </details>

        <details class="rules-accordion">
            <summary>💞 分支二好感度与分支三奴性</summary>
            <div class="rules-content">
                <p class="rules-subtitle">分支二好感度系统</p>
                <ul>
                    <li>初始好感60%。称赞身体+3%-5%；课堂高潮+5%-10%；欣赏大胆行为+5%-8%。</li>
                    <li>感情阶段：萌芽期(60%-70%)→升温期(70%-85%)→临界期(85%-95%)→确定关系(95%以上)。</li>
                </ul>
                <p class="rules-subtitle">分支三奴性系统（只增不减）</p>
                <ul>
                    <li>服从指令+5%-10%；课堂不反抗+3%-5%；说羞辱性话+3%-8%。</li>
                    <li>阶段：0%-30%被动服从→30%-60%习惯服从→60%-90%主动服从→90%-100%完全驯化。</li>
                </ul>
            </div>
        </details>

        <details class="rules-accordion">
            <summary>🎭 自慰方式与道具</summary>
            <div class="rules-content">
                <p class="rules-subtitle">深夜教室自慰方式</p>
                <ul>
                    <li>讲台桌角：最熟悉的方式。双腿分开蹲下，将桌角对准入口缓缓坐下。</li>
                    <li>课桌边缘：跨坐在自己的课桌上，用课桌边缘摩擦下体。</li>
                    <li>窗台：一条腿搭在窗台上，对着月光分开双腿。</li>
                    <li>黑板：背靠黑板，另一只手在黑板上写下清醒时绝不会写的词。</li>
                </ul>
                <p class="rules-subtitle">道具</p>
                <ul>
                    <li>深夜：跳蛋、震动棒、吸吮器、肛塞（狐狸/猫/兔尾）、拉珠、乳夹（带铃铛）。</li>
                    <li>白天课堂：小型跳蛋（遥控器在对方手里）、笔、尺子。</li>
                </ul>
            </div>
        </details>

        <details class="rules-accordion">
            <summary>🏫 隐蔽场景</summary>
            <div class="rules-content">
                <ul>
                    <li>体育器材室：厚体操垫、跳马箱，深夜绝对无人。</li>
                    <li>图书馆角落：最后一排书架后，必须绝对安静。</li>
                    <li>生物实验室：实验台边缘高度刚好适合她坐上去。</li>
                    <li>游泳馆：氯水气味掩盖分泌物腥味，湿泳衣紧贴皮肤。</li>
                    <li>女生厕所隔间：实验楼三楼最隐蔽，冲水声掩盖呻吟。</li>
                    <li>操场大树后：百年老榕树，树干挡住视线但随时可能有人经过。</li>
                </ul>
            </div>
        </details>

        <!-- ==================== 同桌设定与预设行为 ==================== -->
        <div class="glass-card" id="playerSettingsCard">
            <h2 style="font-size:17px;color:#b0b8c8;margin-bottom:14px;text-align:center;">👤 同桌 · 我的设定</h2>
            
            <div class="setting-field">
                <label for="playerName">姓名</label>
                <input type="text" id="playerName" placeholder="请输入你的名字" autocomplete="off">
                <div class="small-hint">高中二年级学生，夏晚妤的同桌 · 年龄：17岁</div>
            </div>

            <div class="setting-field">
                <label>视角选择</label>
                <div class="option-grid" id="povSelector">
                    <div class="option-item active" data-pov="third" onclick="selectPOV(''third'', this)">第三人称（他）</div>
                    <div class="option-item" data-pov="first" onclick="selectPOV(''first'', this)">第一人称（我）</div>
                </div>
                <div class="small-hint">请选择你在游戏中的视角，AI将按此视角进行叙述。</div>
            </div>

            <div class="setting-field">
                <label>性格</label>
                <div class="option-grid" id="personalitySelector">
                    <div class="option-item" onclick="selectPersonality(''温和'', this)">温和</div>
                    <div class="option-item" onclick="selectPersonality(''强势'', this)">强势</div>
                    <div class="option-item" onclick="selectPersonality(''冷漠'', this)">冷漠</div>
                    <div class="option-item" onclick="selectPersonality(''阳光'', this)">阳光</div>
                    <div class="option-item" onclick="selectPersonality(''内向'', this)">内向</div>
                </div>
                <input type="text" id="playerPersonalityInput" placeholder="或在此自由输入性格，如：傲娇、腹黑..." style="margin-top:8px;">
                <div class="small-hint">点击上方预设可直接填入，也可自行输入。</div>
            </div>

            <!-- 男性专属板块 -->
            <div id="maleSection">
                <div class="setting-field">
                    <label>肉棒长度</label>
                    <div class="slider-container">
                        <input type="range" id="maleLength" min="5" max="25" value="15" step="1" oninput="updateMaleLength()">
                        <span class="slider-value" id="maleLengthValue">15cm</span>
                    </div>
                    <div class="slider-comment" id="maleLengthComment">“刚好，不算太大。”</div>
                </div>
            </div>

            <div class="setting-field">
                <label>默认穿着（可更改）</label>
                <input type="text" id="playerOutfit" value="白色T恤 + 灰色短裤 + 黑色内裤" placeholder="如：白色T恤 + 灰色短裤 + 黑色内裤">
                <div class="small-hint">夏晚妤可能会在调教中要求你更换，也可能亲手帮你脱掉。</div>
            </div>
        </div>

        <div class="glass-card" id="actionCard">
            <h2 style="font-size:17px;color:#b0b8c8;margin-bottom:14px;text-align:center;">🎯 我要怎么做</h2>
            <div class="setting-field">
                <label for="actionPreset">快速选择预设行为</label>
                <select id="actionPreset" onchange="updateActionInput()">
                    <option value="">-- 选择预设 --</option>
                    <option value="默默退到窗外，在黑暗中观看她接下来的表演">默默退到窗外，在黑暗中观看她接下来的表演</option>
                    <option value="推门进入，告诉她你理解她，想成为她的观众">推门进入，告诉她你理解她，想成为她的观众</option>
                    <option value="推门进入，用这个秘密威胁她服从你">推门进入，用这个秘密威胁她服从你</option>
                    <option value="假装什么都没看到，悄悄离开教室">假装什么都没看到，悄悄离开教室</option>
                    <option value="站在门口，等她先开口">站在门口，等她先开口</option>
                </select>
            </div>
            <div class="setting-field">
                <label for="actionCustom">自定义行为描述</label>
                <textarea id="actionCustom" rows="2" placeholder="或在这里自由输入你想做的事情……"></textarea>
                <div class="small-hint">选择预设后会自动填充，也可以直接修改。</div>
            </div>
        </div>

        <!-- 复制按钮 -->
        <button class="copy-btn" id="copyAllBtn" onclick="showCopyDialog()">
            📋 一键复制设定与行为
        </button>
    </div>

    <!-- 复制弹窗 -->
    <div class="copy-overlay" id="copyOverlay">
        <div class="copy-dialog">
            <h3>📋 你的开局设定</h3>
            <div class="instruction">
                点击文本框全选并复制，或点击下方按钮。<br>
                如果无法一键复制，请尝试“下载为txt文件”。
            </div>
            <textarea id="copyTextarea" readonly onclick="this.select()"></textarea>
            <div class="btn-row-dialog">
                <button class="btn-dialog btn-copy-auto" id="btnAutoCopy" onclick="autoCopy()">一键复制</button>
                <button class="btn-dialog btn-copy-download" onclick="downloadSettings()">下载为txt</button>
                <button class="btn-dialog btn-close-dialog" onclick="closeCopyDialog()">关闭</button>
            </div>
        </div>
    </div>

    <script>
        const nameInput = document.getElementById(''playerName'');
        const personalityInput = document.getElementById(''playerPersonalityInput'');
        const actionPreset = document.getElementById(''actionPreset'');
        const actionCustom = document.getElementById(''actionCustom'');
        const copyOverlay = document.getElementById(''copyOverlay'');
        const copyTextarea = document.getElementById(''copyTextarea'');

        let currentBranch = 1;
        let currentPOV = ''third'';

        const branchExplains = {
            1: ''你默默退到窗外，在黑暗中观看。她不知道你在看，表演没有表演成分。白天你们仍是普通的同桌关系。'',
            2: ''你推门进入并表示理解。你们建立了观众契约——她有了第一个真实观众。白天课堂她会主动挑逗你。'',
            3: ''你推门进入并威胁她。她被迫服从你的命令。最初会哭、会沉默，但她的身体不会说谎。''
        };

        // 更适合深夜教室/班长设定的评语
        const lengthComments = {
            5:''“这么小……班长连夹紧的力气都省了。”'',
            6:''“有点可怜呢，班长估计都不会多看一眼。”'',
            7:''“别急，班长还没有开始认真。”'',
            8:''“尺寸不重要，能不能让班长求饶才重要。”'',
            9:''“刚好能藏进校服裤子里，不显眼。”'',
            10:''“普通尺寸，班长大概会装作不在意。”'',
            11:''“还行，能玩，但不够让班长腿软。”'',
            12:''“这个尺寸够用了，班长会脸红着偷偷看。”'',
            13:''“不错，应该能顶到让班长说不出话的深度。”'',
            14:''“班长会喜欢的，估计夹得很紧。”'',
            15:''“刚好，不算太大，但班长肯定受不了。”'',
            16:''“妹妹可能会叫出来，班长会咬住嘴唇硬撑。”'',
            17:''“有点深了，班长得慢慢适应才行。”'',
            18:''“这个……得慢慢来，班长第一次不一定吃得住。”'',
            19:''“太大了，班长会被顶得直不起腰。”'',
            20:''“别太急，会弄疼班长的。”'',
            21:''“这个尺寸……班长看到怕是会腿软。”'',
            22:''“会被顶到最里面的，班长肯定求饶。”'',
            23:''“班长光是看着就害怕了，别说碰。”'',
            24:''“太大了，得好好润滑，班长会哭的。”'',
            25:''“看到就腿软了，班长连站都站不稳。”''
        };

        window.selectBranch = function(branchNum) {
            currentBranch = branchNum;
            document.querySelectorAll(''.branch-option'').forEach(opt => {
                opt.classList.toggle(''active'', parseInt(opt.dataset.branch) === branchNum);
            });
            document.getElementById(''branchExplain'').textContent = branchExplains[branchNum];
        };

        window.selectPOV = function(pov, el) {
            currentPOV = pov;
            document.querySelectorAll(''#povSelector .option-item'').forEach(opt => opt.classList.remove(''active''));
            el.classList.add(''active'');
        };

        window.selectPersonality = function(val, el) {
            personalityInput.value = val;
            document.querySelectorAll(''#personalitySelector .option-item'').forEach(opt => opt.classList.remove(''active''));
            el.classList.add(''active'');
        };

        personalityInput.addEventListener(''input'', () => {
            document.querySelectorAll(''#personalitySelector .option-item'').forEach(opt => opt.classList.remove(''active''));
        });

        window.updateMaleLength = function() {
            const v = parseInt(document.getElementById(''maleLength'').value);
            document.getElementById(''maleLengthValue'').textContent = v + ''cm'';
            document.getElementById(''maleLengthComment'').textContent = lengthComments[v] || '''';
        };

        window.updateActionInput = function() {
            const selected = actionPreset.value;
            if (selected) {
                actionCustom.value = selected;
            }
        };

        function getSettingsText() {
            const name = nameInput.value.trim() || ''未命名'';
            const personality = personalityInput.value.trim() || ''未设定'';
            const outfit = document.getElementById(''playerOutfit'').value.trim() || ''白色T恤 + 灰色短裤 + 黑色内裤'';
            const length = document.getElementById(''maleLength'').value;
            const action = actionCustom.value.trim() || ''无特定行为'';
            const povText = currentPOV === ''first'' %s ''第一人称（我）'' : ''第三人称（他）'';

            const branchNames = { 1: ''分支一：秘密观众'', 2: ''分支二：观众契约'', 3: ''分支三：威胁调教'' };
            const branchName = branchNames[currentBranch] || ''分支一：秘密观众'';

            // 注意：此处复制文本中不包含评语，只保留 cm 数值
            return `【同桌设定】
姓名：${name}
视角：${povText}
性格：${personality}
体型：正常
肉棒长度：${length}cm
默认穿着：${outfit}

【当前选择的分支】
${branchName}

【我要怎么做】
${action}`;
        }

        window.showCopyDialog = function() {
            copyTextarea.value = getSettingsText();
            copyOverlay.classList.add(''show'');
            setTimeout(() => {
                copyTextarea.focus();
                copyTextarea.select();
            }, 100);
        };

        window.closeCopyDialog = function() {
            copyOverlay.classList.remove(''show'');
        };

        window.autoCopy = function() {
            const text = getSettingsText();
            const btn = document.getElementById(''btnAutoCopy'');
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(text).then(() => {
                    btn.textContent = ''✅ 已复制！'';
                    btn.style.background = ''#2a3a2a'';
                    setTimeout(() => { btn.textContent = ''一键复制''; btn.style.background = ''''; }, 2000);
                }).catch(() => fallbackCopy(text, btn));
            } else {
                fallbackCopy(text, btn);
            }
        };

        function fallbackCopy(text, btn) {
            copyTextarea.value = text;
            copyTextarea.focus();
            copyTextarea.select();
            try {
                const success = document.execCommand(''copy'');
                btn.textContent = success %s ''✅ 已复制！'' : ''请手动复制'';
            } catch (e) {
                btn.textContent = ''请手动复制'';
            }
            btn.style.background = ''#2a3a2a'';
            setTimeout(() => { btn.textContent = ''一键复制''; btn.style.background = ''''; }, 2000);
        }

        window.downloadSettings = function() {
            const text = getSettingsText();
            const blob = new Blob([text], { type: ''text/plain;charset=utf-8'' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement(''a'');
            a.href = url;
            a.download = ''深夜教室设定_'' + new Date().toLocaleDateString() + ''.txt'';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        };

        copyOverlay.addEventListener(''click'', function(e) {
            if (e.target === this) closeCopyDialog();
        });

        updateMaleLength();
    </script>
</body>
</html>', '校园日常', '2026-09-30 17:29:04', '2026-09-30 17:29:04', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('e346f716-5b4c-4fbd-abef-2131c6dcfa71', '好哥们舍不得肏的青梅被我抱起来肏', '校园 · 隐秘悸动', '🌸', '好哥们舍不得肏的青梅', '好哥们舍不得肏的青梅被我抱起来肏', '🌸', '#a78bfa', 'linear-gradient(135deg, #a78bfa 0%, #f472b6 100%)', '{"title": "好哥们舍不得肏的青梅被我抱起来肏", "desc": "苏清鸢，这个名字在整个学校等同于“高岭之花”。\n黑长直，巨乳，白丝肉腿，清冷绝美的面容，她是林铭宇的青梅竹马，也是被他捧在手心里精心呵护的珍宝。\n林铭宇喜欢她，喜欢到不敢亵渎，连亲吻都小心翼翼。他们互相爱慕，是所有人眼中天造地设的一对。\n\n但林铭宇不知道的是——他心中纯洁无瑕的女神，其实是一个非常色情的骚货。\n她的水比谁都多，她的穴比谁都骚。她会穿着最色情的内衣，在半夜偷偷溜进林铭宇的房间，躺在他身边，双腿大张，故意发出细碎的呻吟，等他用肉棒填满自己空虚的骚穴。\n可那个木头，每次都只是红着脸给她盖上被子，然后自己跑去冲冷水澡。\n\n苏清鸢快要被逼疯了。\n她的身体早已饥渴难耐，每次装睡，小穴都在疯狂泌水，顺着大腿根流到床单上。她不知道林铭宇是装傻还是真的看不到，但她的欲望已经积压到了临界点。\n\n而你，林铭宇最好的哥们，是唯一一个偶然撞破这一切的人。\n那天你去林铭宇家拿东西，推开虚掩的卧室门，看", "bg_image": "https://catai.wiki/a453ff42-3348-4410-df2f-67fa38191f00/bg", "opening_options": ["【深入交流】：依循情境展开深入互动", "【观察试探】：保持距离，观察对方的微妙反应", "【直抒心意】：坦率挑明当前的心境与真实感受"]}', '[{"name": "主角 (玩家)", "role": "核心视角", "desc": "故事的决策者与推进者"}, {"name": "故事角色", "role": "互动对象", "desc": "性格与背景随着剧情发展逐步揭示"}]', '[{"title": "场景开局", "desc": "故事拉开帷幕的初始场景，交织着微妙的气氛与情感抉择。"}]', '{"dialogue_style": "细腻深邃的情感物语，富有张力的人物神态与心理博弈", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "初始情境", "story": "<tl>📅时间：夜晚 | 🌏地点：故事开端</tl>\n\n<article>\n<p>苏清鸢，这个名字在整个学校等同于“高岭之花”。\n黑长直，巨乳，白丝肉腿，清冷绝美的面容，她是林铭宇的青梅竹马，也是被他捧在手心里精心呵护的珍宝。\n林铭宇喜欢她，喜欢到不敢亵渎，连亲吻都小心翼翼。他们互相爱慕，是所有人眼中天造地设的一对。\n\n但林铭宇不知道的是——他心中纯洁无瑕的女神，其实是一个非常色情的骚货。\n她的水比谁都多，她的穴比谁都骚。她会穿着最色情的内衣，在半夜偷偷溜进林铭宇的房间，躺在他身边，双腿大张，故意发出细碎的呻吟，等他用肉棒填满自己空虚的骚穴。\n可那个木头，每次都只是红着脸给她盖上被子，然后自己跑去冲冷水澡。\n\n苏清鸢快要被逼疯了。\n她的身体早已饥渴难耐，每次装睡，小穴都在疯狂泌水，顺着大腿根流到床单上。她不知道林铭宇是装傻还是真的看不到，但她的欲望已经积压到了临界点。\n\n</p>\n</article>", "branches": [{"tag": "A", "title": "深入互动", "desc": "顺应当前情境展开下一步剧情"}, {"tag": "B", "title": "试探心理", "desc": "观察对方细微的反应与意图"}, {"tag": "C", "title": "掌握主动", "desc": "以坚定的态度引导局势发展"}]}]', '/* ✦ 六号宇宙 · 浅色仙气美化（非黑色版） ✦ */
ai {
display: block;
max-width: 860px;
margin: 0 auto;
font-family: ''Georgia'', ''Noto Serif SC'', ''Microsoft YaHei'', serif;
background: linear-gradient(145deg, #fffaf7 0%, #fdeef3 50%, #f3ecff 100%);
border: 1px solid #eed8d8;
border-radius: 24px;
padding: 28px 30px;
box-shadow: 0 12px 40px rgba(190, 140, 160, 0.18);
color: #4a3f4a;
line-height: 1.9;
}

/* ── 头部档案条 ── */
hd {
display: block;
background: linear-gradient(90deg, #ffe4ec 0%, #dce6ff 50%, #fff0e6 100%);
border-radius: 16px;
padding: 14px 22px;
margin-bottom: 18px;
border: 1px solid rgba(255, 255, 255, 0.85);
box-shadow: 0 4px 16px rgba(220, 170, 190, 0.15), inset 0 1px 0 rgba(255,255,255,0.9);
}
hd d {
display: block;
font-size: 0.92em;
margin: 5px 0;
color: #54455a;
font-weight: 500;
letter-spacing: 0.3px;
}
hd d:first-child {
font-weight: 700;
color: #7a4a6a;
font-size: 1.02em;
}

hr {
border: none;
height: 2px;
background: linear-gradient(to right, transparent, #e8a0b8, #a0b8e8, transparent);
margin: 20px 0;
opacity: 0.6;
}

/* ── 正文区 ── */
article {
background: rgba(255, 255, 255, 0.95);
border-radius: 18px;
padding: 22px 28px;
border: 1px solid #f2dfe2;
box-shadow: 0 6px 24px rgba(230, 180, 195, 0.12);
backdrop-filter: blur(4px);
}
article p {
margin: 10px 0;
text-indent: 2em;
letter-spacing: 0.2px;
}

/* ── 折叠面板 ── */
details {
margin-top: 16px;
background: rgba(255, 255, 255, 0.9);
border-radius: 16px;
border: 1px solid #ecd5db;
overflow: hidden;
box-shadow: 0 4px 18px rgba(215, 165, 185, 0.10);
transition: box-shadow 0.3s ease;
}
details:hover {
box-shadow: 0 6px 24px rgba(215, 165, 185, 0.2);
}
details summary {
padding: 14px 24px;
cursor: pointer;
font-weight: 650;
font-size: 1.02em;
background: linear-gradient(90deg, #fdf0f5 0%, #f0ecff 100%);
color: #6a4a6a;
list-style: none;
user-select: none;
display: flex;
align-items: center;
gap: 8px;
border-bottom: 1px solid transparent;
transition: all 0.3s ease;
}
details[open] summary {
border-bottom: 1px solid #f0dde2;
background: linear-gradient(90deg, #fde6ee 0%, #e4e6ff 100%);
}
details summary::-webkit-details-marker {
display: none;
}
details summary::before {
content: ''❀'';
font-size: 0.9em;
color: #c68aa0;
margin-right: 6px;
transition: transform 0.3s ease;
}
details[open] summary::before {
content: ''❁'';
transform: rotate(180deg);
}

details p {
margin: 10px 24px;
padding: 4px 0;
font-size: 0.95em;
border-bottom: 1px dashed #f5e8ea;
}
details p:last-child {
border-bottom: none;
}

/* ── 字段名标签 ── */
f {
display: inline-block;
font-weight: 700;
color: #a06880;
margin-right: 10px;
font-size: 0.9em;
letter-spacing: 0.5px;
background: linear-gradient(90deg, #ffeef2, #f2edff);
padding: 2px 10px;
border-radius: 20px;
border: 1px solid #f0dce2;
}

/* ── 剧情选项（q引用块） ── */
q {
display: block;
margin: 8px 24px;
padding: 10px 18px;
background: linear-gradient(90deg, #fbf4f6, #f4f2ff);
border-radius: 12px;
border-left: 4px solid #d4a0b8;
border-right: 1px solid #f0e4e6;
font-style: normal;
color: #4a3a4a;
transition: background 0.2s;
}
q:hover {
background: linear-gradient(90deg, #fdeef2, #e8e6ff);
}

/* ── 表格区（命运档案馆） ── */
table {
width: 92%;
margin: 12px auto;
border-collapse: separate;
border-spacing: 0;
background: #fcf8fa;
border-radius: 12px;
overflow: hidden;
box-shadow: 0 2px 12px rgba(220, 180, 195, 0.08);
}
th {
background: linear-gradient(90deg, #f9e8ee, #eee8ff);
color: #6a4a6a;
padding: 10px 12px;
font-weight: 650;
font-size: 0.92em;
text-align: left;
border-bottom: 1px solid #f0dfe4;
}
td {
padding: 9px 12px;
border-top: 1px solid #f5e9ec;
color: #4a3a4a;
font-size: 0.92em;
}
tr:first-child th:first-child {
border-top-left-radius: 12px;
}
tr:first-child th:last-child {
border-top-right-radius: 12px;
}

/* ── 对话字体颜色增强（保持用户已有的font标签） ── */
article font[color="#1E90FF"] {
text-shadow: 0 0 8px rgba(30, 144, 255, 0.15);
}
article font[color="#9370DB"] {
text-shadow: 0 0 8px rgba(147, 112, 219, 0.15);
}

/* ── 响应式适配 ── */
@media (max-width: 640px) {
ai {
padding: 16px 14px;
border-radius: 16px;
}
article {
padding: 16px 18px;
}
details summary {
padding: 12px 16px;
}
q {
margin: 6px 14px;
padding: 8px 12px;
}
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;500;700&family=ZCOOL+XiaoWei&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}

:root{
  --bg1:#fdf2f8;
  --bg2:#f5f0ff;
  --bg3:#edf2ff;
  --bg4:#fff6fb;
  --card:rgba(255,255,255,.82);
  --card-solid:#ffffff;
  --border:rgba(167,139,250,.24);
  --border-strong:rgba(167,139,250,.45);
  --primary:#a78bfa;
  --primary-deep:#7c5cd6;
  --primary-soft:#ede9fe;
  --accent:#f472b6;
  --accent-soft:#fce7f3;
  --gold:#c9a35c;
  --text:#4a3d63;
  --text-dim:#78688f;
  --text-mute:#aa9fc6;
  --shadow:0 10px 30px rgba(138,110,200,.13);
  --shadow-lg:0 18px 46px rgba(138,110,200,.22);
  --radius:20px;
  --font:''Noto Serif SC'',''Songti SC'',serif;
  --font-title:''ZCOOL XiaoWei'',''Noto Serif SC'',serif;
}

html,body{
  width:100%;
  min-height:100vh;
  font-family:var(--font);
  color:var(--text);
  background:
    radial-gradient(circle at 12% 8%, #ffe4f1 0%, transparent 42%),
    radial-gradient(circle at 88% 6%, #e6e2ff 0%, transparent 40%),
    radial-gradient(circle at 50% 100%, #dbeeff 0%, transparent 48%),
    linear-gradient(160deg,var(--bg4) 0%,var(--bg2) 45%,var(--bg3) 100%);
  background-attachment:fixed;
  line-height:1.75;
  -webkit-font-smoothing:antialiased;
}

body::before{
  content:"";
  position:fixed;inset:0;pointer-events:none;z-index:0;
  background-image:
    radial-gradient(rgba(167,139,250,.06) 1px, transparent 1px),
    radial-gradient(rgba(244,114,182,.05) 1px, transparent 1px);
  background-size:36px 36px,36px 36px;
  background-position:0 0,18px 18px;
}

.wrap{
  position:relative;z-index:1;
  max-width:760px;
  margin:0 auto;
  padding:34px 18px 90px;
}

/* ============ 封面 ============ */
.cover{
  position:relative;
  border-radius:26px;
  overflow:hidden;
  padding:46px 26px 40px;
  text-align:center;
  background:
    radial-gradient(circle at 30% 20%, rgba(255,255,255,.55), transparent 60%),
    linear-gradient(135deg,#e9d9ff 0%,#fbd7e8 55%,#d7e8ff 100%);
  box-shadow:var(--shadow-lg);
  border:1px solid rgba(255,255,255,.7);
  margin-bottom:30px;
}
.cover::after{
  content:"";position:absolute;inset:0;
  background-image:
    repeating-linear-gradient(45deg,rgba(255,255,255,.16) 0 2px,transparent 2px 14px);
  pointer-events:none;
}
.cover-orn{
  font-size:13px;letter-spacing:.55em;
  color:#b39ae0;text-transform:uppercase;
  margin-bottom:16px;position:relative;z-index:2;
}
.cover h1{
  font-family:var(--font-title);
  font-size:clamp(30px,8.5vw,48px);
  font-weight:400;
  color:#5c4290;
  letter-spacing:.1em;
  text-shadow:0 2px 12px rgba(255,255,255,.9);
  position:relative;z-index:2;
  line-height:1.3;
}
.cover .sub{
  position:relative;z-index:2;
  margin-top:16px;
  font-size:14.5px;
  color:#8a78b8;
  letter-spacing:.12em;
}
.cover .tagline{
  position:relative;z-index:2;
  display:inline-block;
  margin-top:22px;
  padding:8px 24px;
  border-radius:999px;
  font-size:13.5px;
  letter-spacing:.14em;
  color:#fff;
  background:linear-gradient(120deg,var(--primary),var(--accent));
  box-shadow:0 8px 20px rgba(167,139,250,.4);
}
.cover .deco-line{
  position:relative;z-index:2;
  width:70px;height:2px;margin:20px auto 0;
  background:linear-gradient(90deg,transparent,var(--gold),transparent);
  border-radius:2px;
}

/* ============ 卡片通用 ============ */
.card{
  background:var(--card);
  backdrop-filter:blur(14px);
  -webkit-backdrop-filter:blur(14px);
  border:1px solid var(--border);
  border-radius:var(--radius);
  box-shadow:var(--shadow);
  padding:24px 22px;
  margin-bottom:22px;
  position:relative;
  overflow:hidden;
}
.card::before{
  content:"";position:absolute;top:0;left:0;right:0;height:3px;
  background:linear-gradient(90deg,var(--primary),var(--accent),#93c5fd);
  opacity:.75;
}
.sec-title{
  display:flex;align-items:center;gap:10px;
  font-family:var(--font-title);
  font-size:20px;
  letter-spacing:.08em;
  color:#5c4290;
  margin-bottom:18px;
}
.sec-title .ico{
  width:30px;height:30px;flex:0 0 30px;
  display:flex;align-items:center;justify-content:center;
  border-radius:10px;
  font-size:15px;
  background:linear-gradient(135deg,var(--primary-soft),var(--accent-soft));
  border:1px solid var(--border);
}
.sec-title .ln{
  flex:1;height:1px;
  background:linear-gradient(90deg,var(--border-strong),transparent);
}

/* ============ 世界背景 ============ */
.story p{
  font-size:14.5px;
  color:var(--text-dim);
  margin-bottom:12px;
  text-align:justify;
  text-indent:2em;
}
.story p:last-child{margin-bottom:0}
.story .hl{color:var(--primary-deep);font-weight:700}
.story .hl2{color:var(--accent);font-weight:700}
.story blockquote{
  margin:16px 0;
  padding:12px 16px;
  border-left:3px solid var(--accent);
  background:linear-gradient(90deg,var(--accent-soft),transparent);
  border-radius:0 12px 12px 0;
  font-size:14px;
  color:#a04a79;
  font-style:italic;
  text-indent:0;
}

/* ============ 人物介绍 ============ */
.char{
  border-radius:16px;
  padding:18px 16px;
  margin-bottom:16px;
  border:1px solid var(--border);
  background:linear-gradient(150deg,rgba(255,255,255,.9),rgba(245,240,255,.7));
  position:relative;
}
.char:last-child{margin-bottom:0}
.char-head{
  display:flex;align-items:center;gap:12px;
  margin-bottom:12px;
  padding-bottom:12px;
  border-bottom:1px dashed var(--border-strong);
}
.char-ava{
  width:46px;height:46px;flex:0 0 46px;
  border-radius:14px;
  display:flex;align-items:center;justify-content:center;
  font-size:22px;
  box-shadow:0 6px 16px rgba(167,139,250,.28);
}
.char-ava.p1{background:linear-gradient(135deg,#fbcfe8,#f9a8d4)}
.char-ava.p2{background:linear-gradient(135deg,#ddd6fe,#c4b5fd)}
.char-ava.p3{background:linear-gradient(135deg,#bae6fd,#93c5fd)}
.char-name{
  font-family:var(--font-title);
  font-size:18px;
  color:#5c4290;
  letter-spacing:.06em;
}
.char-name small{
  display:block;
  font-family:var(--font);
  font-size:11.5px;
  color:var(--text-mute);
  letter-spacing:.1em;
  margin-top:2px;
  font-weight:400;
}
.char-body p{
  font-size:13.8px;
  color:var(--text-dim);
  margin-bottom:8px;
  text-indent:0;
}
.char-body p:last-child{margin-bottom:0}
.char-body .k{color:var(--accent);font-weight:700}
.char-body .k2{color:var(--primary-deep);font-weight:700}
.chips{display:flex;flex-wrap:wrap;gap:7px;margin-top:6px}
.chip{
  font-size:11.5px;padding:4px 11px;border-radius:999px;
  color:var(--primary-deep);
  background:var(--primary-soft);
  border:1px solid var(--border);
  letter-spacing:.04em;
}
.chip.acc{color:#be3d80;background:var(--accent-soft)}

/* ============ 玩法 ============ */
.rules p{font-size:13.8px;color:var(--text-dim);margin-bottom:9px;text-indent:0}
.rules p:last-child{margin-bottom:0}
.rules .num{
  display:inline-flex;width:19px;height:19px;flex:0 0 19px;
  align-items:center;justify-content:center;
  border-radius:6px;margin-right:8px;
  font-size:11px;font-weight:700;color:#fff;
  background:linear-gradient(135deg,var(--primary),var(--accent));
  vertical-align:1px;
}

/* ============ 表单 ============ */
.field{margin-bottom:16px}
.field:last-child{margin-bottom:0}
.field label{
  display:block;font-size:13px;letter-spacing:.08em;
  color:var(--primary-deep);margin-bottom:7px;font-weight:700;
}
.field label .req{color:var(--accent)}
.field input[type=text],
.field textarea{
  width:100%;
  padding:11px 14px;
  font-family:var(--font);
  font-size:14px;
  color:var(--text);
  background:rgba(255,255,255,.85);
  border:1px solid var(--border-strong);
  border-radius:12px;
  outline:none;
  transition:.25s;
  resize:vertical;
  line-height:1.7;
}
.field input[type=text]:focus,
.field textarea:focus{
  border-color:var(--primary);
  box-shadow:0 0 0 3px rgba(167,139,250,.18);
  background:#fff;
}
.field textarea{min-height:74px}
.field input::placeholder,.field textarea::placeholder{color:var(--text-mute)}
.row2{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.row3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}

/* ============ 开场白列表 ============ */
.opts{display:flex;flex-direction:column;gap:11px}
.opt{
  display:flex;gap:11px;
  padding:14px 15px;
  border-radius:14px;
  border:1px solid var(--border);
  background:linear-gradient(140deg,rgba(255,255,255,.88),rgba(252,231,243,.42));
  cursor:pointer;
  transition:.22s;
  align-items:flex-start;
}
.opt:hover{border-color:var(--primary);box-shadow:0 6px 18px rgba(167,139,250,.2);transform:translateY(-1px)}
.opt.on{
  border-color:var(--accent);
  background:linear-gradient(140deg,var(--accent-soft),var(--primary-soft));
  box-shadow:0 8px 22px rgba(244,114,182,.26);
}
.opt .radio{
  width:19px;height:19px;flex:0 0 19px;margin-top:2px;
  border-radius:50%;
  border:2px solid var(--border-strong);
  display:flex;align-items:center;justify-content:center;
  transition:.2s;
  background:#fff;
}
.opt.on .radio{border-color:var(--accent);background:var(--accent)}
.opt.on .radio::after{
  content:"";width:7px;height:7px;border-radius:50%;background:#fff;
}
.opt .txt{font-size:13.6px;color:var(--text-dim);line-height:1.72;flex:1}
.opt .txt b{color:var(--primary-deep);display:block;margin-bottom:3px;letter-spacing:.06em;font-size:13px}
.opt.on .txt{color:#7a4a66}

/* ============ 按钮 ============ */
.btn-gen{
  display:block;width:100%;
  margin-top:20px;
  padding:14px;
  font-family:var(--font-title);
  font-size:17px;
  letter-spacing:.22em;
  color:#fff;
  border:none;border-radius:15px;cursor:pointer;
  background:linear-gradient(120deg,var(--primary) 0%,var(--accent) 100%);
  box-shadow:0 12px 28px rgba(167,139,250,.42);
  transition:.28s;
  position:relative;overflow:hidden;
}
.btn-gen::after{
  content:"";position:absolute;top:0;left:-70%;width:45%;height:100%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.5),transparent);
  transform:skewX(-22deg);
  transition:.6s;
}
.btn-gen:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(167,139,250,.55)}
.btn-gen:hover::after{left:130%}
.btn-gen:active{transform:translateY(0) scale(.99)}

/* ============ 总结区 ============ */
.sum-box{
  border-radius:18px;
  padding:18px 16px;
  background:linear-gradient(150deg,rgba(255,255,255,.95),rgba(237,233,254,.72));
  border:1px solid var(--border-strong);
  box-shadow:inset 0 0 24px rgba(167,139,250,.08);
}
.sum-empty{
  text-align:center;
  font-size:13.5px;
  color:var(--text-mute);
  padding:26px 10px;
  letter-spacing:.1em;
}
.sum-empty .big{font-size:26px;display:block;margin-bottom:8px;opacity:.6}
.sum-block{margin-bottom:15px}
.sum-block:last-child{margin-bottom:0}
.sum-label{
  display:inline-block;
  font-size:11.5px;letter-spacing:.16em;
  color:#fff;padding:3px 12px;border-radius:999px;
  margin-bottom:8px;
  background:linear-gradient(120deg,var(--primary),var(--accent));
}
.sum-text{
  font-size:13.6px;
  color:var(--text);
  line-height:1.85;
  white-space:pre-wrap;
  word-break:break-word;
  background:rgba(255,255,255,.72);
  border:1px dashed var(--border-strong);
  border-radius:12px;
  padding:12px 14px;
}
.sum-op{
  border-left:3px solid var(--accent);
  border-radius:0 12px 12px 0;
  background:linear-gradient(90deg,var(--accent-soft),rgba(255,255,255,.5));
  padding:12px 14px;
  font-size:13.6px;
  color:#8a4a70;
  line-height:1.8;
  white-space:pre-wrap;
  word-break:break-word;
}
.btns{display:flex;gap:10px;margin-top:18px}
.btn-copy,.btn-clr{
  flex:1;
  padding:13px;
  font-family:var(--font-title);
  font-size:15.5px;
  letter-spacing:.16em;
  border-radius:14px;
  cursor:pointer;
  transition:.26s;
  border:none;
}
.btn-copy{
  color:#fff;
  background:linear-gradient(120deg,#7c5cd6,#c084fc);
  box-shadow:0 10px 24px rgba(124,92,214,.4);
}
.btn-copy:hover{transform:translateY(-2px);box-shadow:0 14px 30px rgba(124,92,214,.55)}
.btn-copy:active{transform:scale(.98)}
.btn-clr{
  flex:0 0 40%;
  color:var(--text-dim);
  background:rgba(255,255,255,.75);
  border:1px solid var(--border-strong);
}
.btn-clr:hover{border-color:var(--accent);color:var(--accent)}
.btn-copy.done{
  background:linear-gradient(120deg,#34d399,#10b981);
  box-shadow:0 10px 24px rgba(16,185,129,.4);
}

.toast{
  position:fixed;
  left:50%;bottom:38px;
  transform:translateX(-50%) translateY(20px);
  padding:11px 26px;
  border-radius:999px;
  font-size:13.5px;letter-spacing:.1em;
  color:#fff;
  background:linear-gradient(120deg,var(--primary-deep),var(--accent));
  box-shadow:0 12px 28px rgba(124,92,214,.45);
  opacity:0;pointer-events:none;
  transition:.32s;
  z-index:99;
}
.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}

.foot{
  text-align:center;
  font-size:11.5px;
  letter-spacing:.24em;
  color:var(--text-mute);
  margin-top:26px;
}

/* ============ 手机端 ============ */
@media(max-width:520px){
  .wrap{padding:20px 12px 70px}
  .cover{padding:34px 18px 30px;border-radius:20px}
  .card{padding:19px 15px;border-radius:16px}
  .sec-title{font-size:17.5px}
  .row2,.row3{grid-template-columns:1fr}
  .char{padding:15px 13px}
  .char-name{font-size:16px}
  .btn-gen{font-size:15.5px;letter-spacing:.16em}
  .btns{flex-direction:column}
  .btn-clr{flex:1}
}
</style>
</head>
