.chk-row{display:flex;align-items:center;padding:0 4px;margin-bottom:5px;}
.chk-lbl{display:flex;align-items:center;cursor:pointer;font-size:0.65rem;color:rgba(255,255,255,0.8);font-weight:300;letter-spacing:1px;transition:all 0.3s;}
