.chk-box{width:14px;height:14px;border:1px solid rgba(255,255,255,0.3);border-radius:4px;margin-right:6px;display:flex;align-items:center;justify-content:center;transition:all 0.2s;background:rgba(0,0,0,0.3);}
.chk-lbl input:checked + .chk-box{background:var(--ac);border-color:var(--ac);box-shadow:0 0 8px rgba(255,105,180,0.4);}
.chk-lbl input:checked + .chk-box::after{content:''✔'';font-size:9px;color:#fff;font-weight:bold;}
#ts{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%) scale(0.9);background:rgba(20,15,25,0.95);backdrop-filter:blur(15px);color:var(--wh);padding:10px 18px;border:1px solid var(--ac);border-radius:12px;font-size:0.75rem;font-weight:500;letter-spacing:1px;opacity:0;visibility:hidden;transition:all 0.3s cubic-bezier(0.175,0.885,0.32,1.275);z-index:999;box-shadow:0 8px 25px rgba(0,0,0,0.5);text-align:center;width:max-content;max-width:85%;}
#ts.sw{opacity:1;visibility:visible;transform:translate(-50%,-50%) scale(1);}
.op{position:absolute;top:0;left:0;width:100%;height:100%;background:rgba(10,10,15,0.95);backdrop-filter:blur(25px);-webkit-backdrop-filter:blur(25px);z-index:20;display:flex;flex-direction:column;opacity:0;visibility:hidden;transition:all 0.4s;transform:scale(0.98) translateY(10px);}
.op.sw{opacity:1;visibility:visible;transform:scale(1) translateY(0);}
.wh{padding:15px;display:flex;justify-content:space-between;align-items:center;flex-shrink:0;}
.wt{color:var(--wh);font-size:0.95rem;font-weight:500;letter-spacing:2px;text-shadow:0 0 6px rgba(255,105,180,0.5);}
.wc{color:rgba(255,255,255,0.5);font-size:1.2rem;cursor:pointer;transition:all 0.3s;font-weight:100;}
.wc:hover{transform:rotate(90deg);color:var(--ac);}
.cg{padding:0 15px 15px;overflow-y:auto;height:calc(100% - 55px);}
.cg::-webkit-scrollbar{width:3px;}
.cg::-webkit-scrollbar-thumb{background:rgba(255,105,180,0.4);border-radius:3px;}
.wd-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;}
