.wd-nm{position:relative;z-index:2;height:100%;display:flex;align-items:flex-end;justify-content:center;padding-bottom:8px;background:linear-gradient(to top, rgba(0,0,0,0.9) 0%, transparent 50%);color:var(--wh);font-size:0.7rem;font-weight:500;pointer-events:none;text-shadow:0 1px 3px #000;}
