<script>
function switchTab(tabId) {
    document.querySelectorAll(''.content-area'').forEach(el => el.classList.remove(''active''));
    document.querySelectorAll(''.tab-btn'').forEach(el => el.classList.remove(''active''));
    document.getElementById(tabId).classList.add(''active'');
    event.currentTarget.classList.add(''active'');
    window.scrollTo(0,0);
}
function toggleKink(el) { el.classList.toggle(''active''); updatePreview(); }
function selectNpc(el) { el.classList.toggle(''selected''); updatePreview(); }
function showNpcModal() { document.getElementById(''npcModal'').style.display = ''flex''; }
function closeModal() { document.getElementById(''npcModal'').style.display = ''none''; }
function addNewNpc() {
    const name = document.getElementById(''new_name'').value;
    const age = document.getElementById(''new_age'').value;
    const pers = document.getElementById(''new_personality'').value;
    const iden = document.getElementById(''new_identity'').value;
    const bg = document.getElementById(''new_bg'').value;
    if(!name) return;
    const div = document.createElement(''div'');
    div.className = ''npc-list-item selected'';
    div.onclick = function() { this.classList.toggle(''selected''); updatePreview(); };
    div.innerHTML = `<h5>👤 ${name}</h5><p>${age} | ${pers} | ${iden}</p><div style="display:none">${bg}</div>`;
    document.getElementById(''npcList'').appendChild(div);
    closeModal();
    updatePreview();
}
function updatePreview() {
    const pName = document.getElementById(''p_name'').value || ''龙傲天'';
    const pGender = document.getElementById(''p_gender'').value || ''男'';
    const pPers = document.getElementById(''p_personality'').value || ''温柔体贴'';
    const pIden = document.getElementById(''p_identity'').value || ''高中生'';
    const pOther = document.getElementById(''p_other'').value || ''无'';
    const kinks = Array.from(document.querySelectorAll(''.kink-item.active'')).map(el => el.innerText).join('', '') || ''无'';
    let npcInfo = '''';
    document.querySelectorAll(''.npc-list-item.selected'').forEach(el => {
        const h5 = el.querySelector(''h5'').innerText;
        const p = el.querySelector(''p'').innerText;
        const bg = el.querySelector(''div'').innerText;
        npcInfo += `【NPC：${h5}】\n详情：${p}\n背景：${bg}\n\n`;
    });
    const intro = document.getElementById(''custom_intro'').value || ''默认开场'';
    const fullText = `【玩家信息】\n姓名：${pName}\n性别：${pGender}\n性格：${pPers}\n身份：${pIden}\n核心性癖：${kinks}\n其他：${pOther}\n\n【NPC信息】\n${npcInfo}【剧情开场】\n${intro}\n\n(请按照Aphrodite👦管理员模拟系统规则开始游戏)`;
    document.getElementById(''finalPreview'').innerText = fullText;
}
function quickCopy(name, traits) {
    const admin = document.getElementById(''shop_admin_name'').value || ''新任管理员'';
    const iden = document.getElementById(''shop_admin_identity'').value || ''管理员'';
    const text = `【管理员查房确认】\n\n👤 管理员设定：\n姓名：${admin}\n身份：${iden}\n\n📦 目标住户：\n姓名：${name}\n核心属性：${traits}\n\n(【👦】请按照月桂庄公寓规则开始剧情)`;
    const el = document.createElement(''textarea'');
    el.value = text;
    document.body.appendChild(el);
    el.select();
    document.execCommand(''copy'');
    document.body.removeChild(el);
    showToast();
}
function copyConfig() {
    updatePreview();
    const text = document.getElementById(''finalPreview'').innerText;
    const el = document.createElement(''textarea'');
    el.value = text;
    document.body.appendChild(el);
    el.select();
    document.execCommand(''copy'');
    document.body.removeChild(el);
    showToast();
}
function showToast() {
    const t = document.getElementById(''toast'');
    t.style.display = ''block'';
    setTimeout(() => t.style.display = ''none'', 2000);
}
document.querySelectorAll(''input, textarea'').forEach(el => el.addEventListener(''input'', updatePreview));
updatePreview();
</script>
</body>
</html>', '都市', '2026-09-15 15:03:14', '2026-09-15 15:03:14', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
