body,
p,
span,
div,
details,
summary,
td,
th,
li,
blockquote {
    font-size: 16px !important;
    font-family: ''Microsoft YaHei'', ''PingFang SC'', sans-serif !important;
}

/* ===== 对话颜色 ===== */
.player-talk {
    color: #1a73e8 !important;
    font-weight: 500;
}
.npc-talk {
    color: #d63384 !important;
    font-weight: 500;
}

/* ===== 容器基准 ===== */
.w {
    display: block;
    font-family: system-ui, -apple-system, sans-serif;
    font-size: 14px;
    color: #4a2c40;
    line-height: 1.5;
    background: linear-gradient(135deg, #fff0f5 0%, #fef5f9 100%);
    padding: 8px;
    border-radius: 12px;
    box-shadow: 0 4px 15px rgba(255, 126, 179, 0.1);
}

/* ===== 状态面板 (a) ===== */
.w .a {
    display: block;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 126, 179, 0.3);
    border-radius: 8px;
    margin-bottom: 8px;
    overflow: hidden;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
    transition: box-shadow 0.3s ease, border-color 0.3s ease;
}
.w .a[open] {
    box-shadow: 0 6px 16px rgba(255, 117, 140, 0.12);
    border-color: rgba(255, 126, 179, 0.55);
}

/* ===== 师生图鉴 (b) ===== */
.w .b {
    display: block;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 126, 179, 0.3);
    border-radius: 8px;
    margin-bottom: 8px;
    overflow: hidden;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
}

/* ===== 记忆区 (star-memory) ===== */
.w .star-memory {
    display: block;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 126, 179, 0.3);
    border-radius: 8px;
    margin-bottom: 8px;
    overflow: hidden;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
    transition: box-shadow 0.3s ease, border-color 0.3s ease;
}
.w .star-memory[open] {
    box-shadow: 0 6px 16px rgba(255, 117, 140, 0.12);
    border-color: rgba(255, 126, 179, 0.55);
}

/* ===== 隐藏原生三角 ===== */
.w .a summary::-webkit-details-marker,
.w .b summary::-webkit-details-marker,
.w .star-memory summary::-webkit-details-marker,
.w .m summary::-webkit-details-marker {
    display: none;
}
.w .a summary,
.w .b summary,
.w .star-memory summary,
.w .m summary {
    list-style: none;
}

/* ===== 标题通用 ===== */
.w .a summary,
.w .b summary,
.w .star-memory summary {
    cursor: pointer;
    padding: 10px 12px;
    font-weight: 600;
    user-select: none;
    display: flex;
    justify-content: space-between;
    align-items: center;
    transition: background 0.25s ease;
    background: linear-gradient(90deg, rgba(255, 126, 179, 0.13) 0%, rgba(255, 255, 255, 0) 100%);
    color: #d81b60;
    font-size: 15px;
    border-bottom: 1px solid transparent;
}
.w .a[open]>summary,
.w .b[open]>summary,
.w .star-memory[open]>summary {
    border-bottom: 1px solid rgba(255, 126, 179, 0.2);
}

/* ===== 箭头动画 ===== */
.w .a summary::after,
.w .b summary::after,
.w .star-memory summary::after {
    content: "▼";
    font-size: 11px;
    color: #ff758c;
    opacity: 0.7;
    transition: transform 0.3s ease;
    margin-left: 8px;
}
.w .a[open]>summary::after,
.w .b[open]>summary::after,
.w .star-memory[open]>summary::after {
    transform: rotate(180deg);
}

/* ===== Hover ===== */
.w .a summary:hover,
.w .b summary:hover,
.w .star-memory summary:hover {
    background: rgba(255, 126, 179, 0.18);
}

/* ===== 展开动画 ===== */
.w .a[open]>*:not(summary),
.w .b[open]>*:not(summary),
.w .star-memory[open]>*:not(summary) {
    animation: panel-fade-in 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes panel-fade-in {
    0% {
        opacity: 0;
        transform: translateY(-4px);
    }
    100% {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ===== 状态条目容器 ===== */
.w .r {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    margin: 5px 10px;
    background: rgba(255, 255, 255, 0.85);
    border-radius: 6px;
    padding: 4px 0;
    border: 1px solid rgba(255, 126, 179, 0.12);
    transition: background 0.2s ease;
}
.w .r:hover {
    background: rgba(255, 255, 255, 0.96);
}

/* ===== 粉色标签 ===== */
.w .k {
    display: inline-block;
    background: linear-gradient(135deg, #ff7eb3 0%, #ff758c 100%);
    color: white;
    padding: 2px 10px;
    font-size: 12px;
    font-weight: 600;
    border-radius: 4px;
    margin: 0 10px 2px 10px;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
    white-space: nowrap;
}

/* ===== 内容值 ===== */
.w .v {
    display: block;
    padding: 2px 10px 4px 10px;
    font-size: 13px;
    color: #4a2c40;
    width: 100%;
    box-sizing: border-box;
    line-height: 1.6;
    word-wrap: break-word;
    white-space: normal;
}

/* ===== 师生图鉴内部卡片 (m) ===== */
.w .m {
    background: rgba(255, 240, 245, 0.6);
    border-radius: 6px;
    margin: 6px 10px;
    border-left: 3px solid #ff758c;
}
.w .m summary {
    padding: 8px 10px;
    font-size: 13px;
    color: #6a4a5b;
    background: transparent;
    font-weight: 500;
}
.w .mi {
    padding: 6px 10px;
    margin: 4px 6px 8px 6px;
    background: rgba(255, 255, 255, 0.5);
    border-radius: 4px;
    font-size: 13px;
    color: #553a4b;
    line-height: 1.6;
}

/* ===== 记忆区内层 details ===== */
.w .star-memory details {
    background: rgba(255, 245, 248, 0.5);
    border-radius: 6px;
    margin: 6px 10px;
    border-left: 3px solid #ffa5b9;
    overflow: hidden;
}
.w .star-memory details summary {
    padding: 8px 10px;
    font-size: 13px;
    color: #6a4a5b;
    background: transparent;
    font-weight: 500;
    cursor: pointer;
    user-select: none;
    display: flex;
    justify-content: space-between;
    align-items: center;
    transition: background 0.2s ease;
    border-bottom: 1px solid transparent;
}
.w .star-memory details summary:hover {
    background: rgba(255, 126, 179, 0.10);
}
.w .star-memory details[open]>summary {
    border-bottom: 1px solid rgba(255, 126, 179, 0.15);
}
.w .star-memory details summary::-webkit-details-marker {
    display: none;
}
.w .star-memory details summary::after {
    content: "▸";
    font-size: 12px;
    color: #ff758c;
    opacity: 0.6;
    transition: transform 0.25s ease;
    margin-left: 8px;
}
.w .star-memory details[open]>summary::after {
    transform: rotate(90deg);
}

/* ===== 记忆区表格容器 ===== */
.w .star-memory details .table-wrap {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    margin: 6px 8px 8px 8px;
    border-radius: 6px;
    background: rgba(255, 255, 255, 0.6);
    padding: 4px 0;
}

/* ===== 记忆区表格（HTML表格） ===== */
.w .star-memory table {
    width: 100%;
    min-width: 340px;
    border-collapse: collapse;
    font-size: 13px;
    color: #4a2c40;
    table-layout: fixed;
}
.w .star-memory table th,
.w .star-memory table td {
    padding: 6px 4px;
    text-align: left;
    vertical-align: top;
    border-bottom: 1px solid rgba(255, 126, 179, 0.10);
    word-wrap: break-word;
    overflow-wrap: break-word;
    line-height: 1.5;
}
.w .star-memory table th {
    background: rgba(255, 126, 179, 0.08);
    font-weight: 600;
    font-size: 12px;
    color: #b34a6a;
    letter-spacing: 0.3px;
    border-bottom: 2px solid rgba(255, 126, 179, 0.20);
}
/* ===== 列宽分配：编号窄，时间窄，场景窄，内容宽 ===== */
.w .star-memory table th:nth-child(1),
.w .star-memory table td:nth-child(1) {
    width: 10%;
    min-width: 40px;
    padding-right: 2px;
}
.w .star-memory table th:nth-child(2),
.w .star-memory table td:nth-child(2) {
    width: 18%;
    min-width: 70px;
    padding-right: 2px;
}
.w .star-memory table th:nth-child(3),
.w .star-memory table td:nth-child(3) {
    width: 18%;
    min-width: 60px;
    padding-right: 2px;
}
.w .star-memory table th:nth-child(4),
.w .star-memory table td:nth-child(4) {
    width: 54%;
    min-width: 120px;
}
/* ===== 表格行 hover ===== */
.w .star-memory table tr:hover td {
    background: rgba(255, 126, 179, 0.04);
}
/* ===== 表格最后一行无边框 ===== */
.w .star-memory table tr:last-child td {
    border-bottom: none;
}

/* ===== 记忆区文本表格（备选：纯文本表格美化） ===== */
.w .star-memory details .text-table {
    display: block;
    margin: 6px 8px 8px 8px;
    padding: 8px 10px;
    background: rgba(255, 255, 255, 0.6);
    border-radius: 6px;
    font-size: 13px;
    line-height: 1.7;
    color: #4a2c40;
    white-space: pre-wrap;
    word-break: break-word;
    overflow-x: auto;
    font-family: ''SF Mono'', ''Menlo'', ''Monaco'', ''Consolas'', ''Liberation Mono'', monospace;
}
/* ===== 文本表格中的行（模拟） ===== */
.w .star-memory details .text-table .row {
    display: block;
    padding: 2px 0;
    border-bottom: 1px solid rgba(255, 126, 179, 0.06);
}
.w .star-memory details .text-table .row:last-child {
    border-bottom: none;
}
/* ===== 文本表格中的列（用 inline-block 模拟，编号/时间/场景窄，内容宽） ===== */
.w .star-memory details .text-table .col-id {
    display: inline-block;
    min-width: 36px;
    font-weight: 600;
    color: #b34a6a;
}
.w .star-memory details .text-table .col-time {
    display: inline-block;
    min-width: 72px;
    color: #6a4a5b;
}
.w .star-memory details .text-table .col-scene {
    display: inline-block;
    min-width: 64px;
    color: #6a4a5b;
}
.w .star-memory details .text-table .col-content {
    display: inline;
    color: #4a2c40;
}

/* ===== 记忆区说明文字 (.i) ===== */
.w .star-memory .i {
    display: block;
    margin: 4px 10px 10px 10px;
    font-size: 12px;
    color: #a08496;
    opacity: 0.8;
    font-style: normal;
    padding: 6px 10px;
    background: rgba(255, 255, 255, 0.5);
    border-radius: 4px;
    border-left: 2px solid rgba(255, 126, 179, 0.3);
}

/* ===== 其他辅助 ===== */
.w .t {
    display: block;
    font-weight: bold;
    font-size: 14px;
    color: #d81b60;
    margin: 12px 10px 4px 10px;
    padding-left: 8px;
    border-left: 3px solid #ff758c;
}
.w .q {
    display: block;
    margin: 12px 10px 8px 10px;
    padding: 8px 0 4px 0;
    font-size: 11px;
    color: #ff758c;
    text-align: center;
    border-top: 1px dashed rgba(255, 126, 179, 0.4);
    letter-spacing: 0.3px;
}

/* ===== 可选行动推荐 ===== */
.w .action-list {
    margin: 8px 10px 4px 10px;
    padding: 6px 10px;
    background: rgba(255, 255, 255, 0.6);
    border-radius: 6px;
    border-left: 3px solid #ff758c;
    font-size: 13px;
    color: #4a2c40;
}
.w .action-list .act {
    display: block;
    padding: 2px 0;
    color: #6a4a5b;
}

/* ===== 移动端适配 ===== */
@media (max-width: 480px) {
    .w {
        padding: 4px;
        border-radius: 8px;
    }
