}#xj-page .film::before{top:6px}#xj-page .film::after{bottom:6px}#xj-page .film-track{display:flex;gap:16px;width:max-content;padding:12px 0;animation:slide 80s linear infinite}#xj-page .film:hover .film-track{animation-play-state:paused}#xj-page .film-track img{height:168px;border-radius:3px;display:block;filter:saturate(.92);transition:filter .4s,transform .4s}#xj-page .film-track img:hover{filter:saturate(1.1);transform:scale(1.04)}#xj-page .ward-grid{columns:4;column-gap:22px;margin-top:8vh}#xj-page .ward-item{
