  background:#fffdf9;padding:8px 8px 0;box-shadow:0 10px 30px rgba(61,58,56,.12);
  transition:transform .5s cubic-bezier(.2,.8,.2,1),box-shadow .5s;
}#xj-page .ward-item img{width:100%;display:block;border-radius:5px}#xj-page .ward-item .ward-cap{
