}#xj-page .ward-item:hover{transform:translateY(-7px) rotate(.6deg);box-shadow:0 24px 54px rgba(61,58,56,.2)}#xj-page .ward-item.hot{box-shadow:0 14px 38px rgba(176,65,62,.22);border:1px solid rgba(176,65,62,.28)}#xj-page .ward-item.hot .ward-cap{color:var(--red);font-weight:400}#xj-page .ward-item.hot::after{
