}#xj-page .opening-letter p{font-family:var(--serif);font-weight:300;font-size:15.5px;line-height:2.35;letter-spacing:.05em;color:#4a4642;margin-bottom:1.2em}#xj-page .opening-letter p:last-child{margin-bottom:0}#xj-page .opening-letter .hand{font-size:1.25em}#xj-page .mod-title{font-family:var(--serif);font-weight:900;font-size:clamp(26px,3.2vw,38px);letter-spacing:.14em;color:#3d3a38;margin-bottom:3vh}#xj-page .mod-prose{font-size:14.5px;line-height:2.2;font-weight:300;letter-spacing:.03em;color:#4a4642;margin-bottom:1.3em;max-width:760px}#xj-page .mod-prose b{font-weight:500;color:var(--red)}#xj-page .mod-foot{margin-top:4.5vh;font-size:13.5px;line-height:2.2;font-weight:300;color:var(--ink-soft);border-top:1px dashed rgba(61,58,56,.2);padding-top:3vh}#xj-page .mod-foot b{font-weight:500;color:var(--red)}#xj-page .bill{
