  padding:26px 16px 22px;text-align:center;box-shadow:0 8px 22px rgba(61,58,56,.07);
  transition:transform .45s cubic-bezier(.2,.8,.2,1),box-shadow .45s;
}#xj-page .stat:hover{transform:translateY(-5px);box-shadow:0 18px 40px rgba(61,58,56,.13)}#xj-page .stat .v{font-family:var(--serif);font-weight:900;font-size:clamp(24px,2.6vw,33px);color:#3d3a38;line-height:1.2}#xj-page .stat .v small{font-size:.5em;font-weight:600;color:var(--ink-soft);margin-left:2px}#xj-page .stat .v.lv{font-size:clamp(19px,2vw,25px);letter-spacing:.1em}#xj-page .stat .k{margin-top:10px;font-size:11px;letter-spacing:.18em;color:var(--ink-soft);line-height:1.8}#xj-page .stars span{color:#dcd6cd;font-size:clamp(20px,2.2vw,28px)}#xj-page .stars span.on{color:var(--gold)}#xj-page .stars span.half{color:var(--gold);opacity:.45}#xj-page .rf-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:4vh}#xj-page .rf{padding:24px 28px;border-radius:8px}#xj-page .rf h4{font-family:var(--serif);font-weight:600;font-size:15.5px;letter-spacing:.14em;margin-bottom:10px}#xj-page .rf p{font-size:13.5px;line-height:2.05;font-weight:300}#xj-page .rf-up{background:rgba(201,168,106,.1);border:1px solid rgba(201,168,106,.35)}#xj-page .rf-up h4{color:#8a6d33}#xj-page .rf-up p{color:#6f675a}#xj-page .rf-down{background:rgba(90,85,96,.07);border:1px solid rgba(90,85,96,.25)}#xj-page .rf-down h4{color:#4a4650}#xj-page .rf-down p{color:#6a6570}#xj-page .goal{margin-top:4.5vh}#xj-page .goal-label{display:flex;justify-content:space-between;font-family:var(--serif);font-size:13px;letter-spacing:.14em;color:var(--ink-soft);margin-bottom:12px}#xj-page .goal-bar{height:9px;border-radius:99px;background:rgba(61,58,56,.1);overflow:hidden}#xj-page .goal-fill{height:100%;width:0;border-radius:99px;background:linear-gradient(90deg,var(--gold),var(--red));transition:width 1.8s cubic-bezier(.2,.8,.2,1)}#xj-page .play-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:26px;margin-top:8vh}#xj-page .play-card{
