  transition:transform .5s cubic-bezier(.2,.8,.2,1),box-shadow .5s,border-color .5s;
}#xj-page .play-card:hover{transform:translateY(-8px);box-shadow:0 26px 56px rgba(61,58,56,.16);border-color:rgba(176,65,62,.4)}#xj-page .play-card .num{font-family:var(--serif);font-weight:900;font-size:15px;color:var(--gold);letter-spacing:.2em}#xj-page .play-card h3{font-family:var(--serif);font-weight:600;font-size:20px;letter-spacing:.14em;margin:14px 0 16px;color:#3d3a38}#xj-page .play-card p{font-size:13.5px;line-height:2.1;font-weight:300;color:var(--ink-soft)}#xj-page .play-card p .hand{font-size:1.15em}#xj-page .play-card::after{
