  </div>

  <!-- ========== 生成按钮 ========== -->
  <div class="generate-area">
    <button class="generate-btn" id="generate-btn" onclick="generateSummary()">
      <span class="star">✦</span>
      生成角色卡
      <span class="star">✦</span>
    </button>
  </div>

  <!-- ========== 总结区 ========== -->
  <div class="summary-area" id="summary-area">
    <div class="summary-title">角色卡片</div>
    <div class="summary-card">
      <div class="summary-content" id="summary-content">
        <div class="empty-state">点击上方「生成角色卡」按钮，<br>生成你的专属角色卡。</div>
      </div>
      <div class="copy-area">
        <button class="copy-btn" id="copy-btn" onclick="copySummary()" style="opacity:0;pointer-events:none;pointer-events:auto;opacity:1;">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg>
          一键复制
        </button>
      </div>
    </div>
  </div>

</div>

<script>
/* ===== 折叠功能 ===== */
document.querySelectorAll(''.fold-btn'').forEach(btn=>{
  btn.addEventListener(''click'',function(){
    const target=this.getAttribute(''data-target'');
    const card=this.closest(''.card'');
    const collapse=card.querySelector(''.collapse-area'');
    collapse.classList.toggle(''closed'');
    this.textContent=collapse.classList.contains(''closed'')%s''展开'':''收起'';
  });
});

/* ===== 字符折叠 ===== */
function toggleChar(id){
  const el=document.getElementById(id);
  el.classList.toggle(''closed'');
}

/* ===== 开场白选择 ===== */
let selectedStarter='''';
function selectStarter(el){
  document.querySelectorAll(''.starter-item'').forEach(item=>item.classList.remove(''selected''));
  el.classList.add(''selected'');
  selectedStarter=el.getAttribute(''data-text'');
}

/* ===== 生成总结 ===== */
function generateSummary(){

  // 收集玩家设定
  const name=document.getElementById(''p-name'').value.trim()||''未命名'';
  const age=document.getElementById(''p-age'').value.trim()||''未知'';
  const look=document.getElementById(''p-look'').value.trim()||''普通身材，体格匀称'';
  const dick=document.getElementById(''p-dick'').value.trim()||''18cm/6cm，粗壮坚硬，微微上翘'';
  const extra=document.getElementById(''p-extra'').value.trim();

  // 收集开场白
  const customStarter=document.getElementById(''starter-custom-input'').value.trim();
  const finalStarter=customStarter||selectedStarter||''黄昏时分，你按响了林铭宇家的门铃。门被打开，一股幽香的暖风带着女人和欲望的气息，扑面而来。'';

  let playerText='''';
  playerText+=`【玩家设定】\n`;
  playerText+=`姓名：${name}\n`;
  playerText+=`年龄：${age}\n`;
  playerText+=`外貌：${look}\n`;
  playerText+=`肉棒：${dick}\n`;
  if(extra){
    playerText+=`额外设定：${extra}\n`;
  }

  const dividerText=`\n✦ ✦ ✦ ✦ ✦ ✦\n`;

  let starterText=`【开场白】\n${finalStarter}\n`;

  const summaryText=playerText+dividerText+starterText;

  // 输出到总结区
  const content=document.getElementById(''summary-content'');
  content.innerHTML='''';
  const textNode=document.createElement(''div'');
  textNode.style.whiteSpace=''pre-wrap'';
  textNode.style.wordBreak=''break-word'';
  textNode.textContent=summaryText;
  content.appendChild(textNode);

  // 显示复制按钮
  const copyBtn=document.getElementById(''copy-btn'');
  copyBtn.style.opacity=''1'';
  copyBtn.style.pointerEvents=''auto'';
  copyBtn.classList.remove(''copied'');
  copyBtn.innerHTML=''<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg> 一键复制'';

  // 滚动到总结区
  setTimeout(()=>{
    document.getElementById(''summary-area'').scrollIntoView({behavior:''smooth'',block:''center''});
  },100);
}

/* ===== 复制功能 ===== */
function copySummary(){
  const content=document.getElementById(''summary-content'');
  const text=content.innerText.replace(/\n{3,}/g,''\n\n'').trim();

  const copyBtn=document.getElementById(''copy-btn'');

  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(()=>{
      copyBtn.classList.add(''copied'');
      copyBtn.innerHTML=''<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="M20 6L9 17l-5-5"/></svg> 已复制'';
      setTimeout(()=>{
        copyBtn.classList.remove(''copied'');
        copyBtn.innerHTML=''<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg> 一键复制'';
      },2000);
    }).catch(()=>{
      fallbackCopy(text);
    });
  }else{
    fallbackCopy(text);
  }
}

function fallbackCopy(text){
  const content=document.getElementById(''summary-content'');
  const range=document.createRange();
  range.selectNodeContents(content);
  const selection=window.getSelection();
  selection.removeAllRanges();
  selection.addRange(range);

  try{
    document.execCommand(''copy'');
    const copyBtn=document.getElementById(''copy-btn'');
    copyBtn.classList.add(''copied'');
    copyBtn.innerHTML=''<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="M20 6L9 17l-5-5"/></svg> 已复制'';
    setTimeout(()=>{
      copyBtn.classList.remove(''copied'');
      copyBtn.innerHTML=''<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg> 一键复制'';
    },2000);
  }catch(err){
    alert(''复制失败，请手动复制文本。'');
  }
  selection.removeAllRanges();
}
</script>

</body>
</html>', '都市情感', '2026-10-05 10:12:59', '2026-10-05 10:15:00', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_wife_business_trip', '肥臀巨乳美妻要跟男闺蜜出差？', '都市 · 情感抉择', '👠', '肥臀巨乳美妻要跟男闺', '肥臀巨乳美妻要跟男闺蜜出差？', '👠', '#8e5cc4', 'linear-gradient(135deg, #8e5cc4 0%, #e0689a 100%)', '{"title": "肥臀巨乳美妻要跟男闺蜜出差？", "desc": "苏婉晴，你的妻子，结婚两年。\n\n她今年二十六岁，是广告公司的客户总监。身高168，却有着一对沉甸甸的H罩杯巨乳，走路时那两团软肉在衬衫下微微晃动，足以让任何男人移不开眼。她的腰细得惊人，下面是浑圆挺翘、手感极佳的肥臀，穿包臀裙时曲线能把裙子撑出淫靡的弧度。她的乳晕是少女般的粉嫩色，蜜穴天生多汁，每次被你进入时都会发出黏腻的水声，像熟透的水蜜桃。\n\n这两年里，她几乎把所有女人的娇媚和放荡都给了你一个人。你加班晚归，她会仅穿着你的衬衫在厨房给你留饭，衬衫下摆堪堪盖住臀部，你从背后抱上去时她总会笑着扭动腰肢；周末的早晨她喜欢用那对豪乳夹住你的肉棒，一边乳交一边用湿漉漉的眼睛看着你；你们的性生活从来不需要前戏，因为她的身体永远为你准备好——一个眼神、一次触碰，她的小穴就会自己流出汁水。\n\n但你有个说不出口的心结。她有一个从大学就认识的“男闺蜜”——陆明远。\n\n陆明远是个健身教练，一米八五，浑身肌肉", "bg_image": "https://catai.wiki/a4a5cc46-0570-4c91-4134-ec20dd46e100/bg", "opening_options": ["【深入交流】：依循情境展开深入互动", "【观察试探】：保持距离，观察对方的微妙反应", "【直抒心意】：坦率挑明当前的心境与真实感受"]}', '[{"name": "主角 (玩家)", "role": "核心视角", "desc": "故事的决策者与推进者"}, {"name": "故事角色", "role": "互动对象", "desc": "性格与背景随着剧情发展逐步揭示"}]', '[{"title": "场景开局", "desc": "故事拉开帷幕的初始场景，交织着微妙的气氛与情感抉择。"}]', '{"dialogue_style": "细腻深邃的情感物语，富有张力的人物神态与心理博弈", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "初始情境", "story": "<tl>📅时间：夜晚 | 🌏地点：故事开端</tl>\n\n<article>\n<p>苏婉晴，你的妻子，结婚两年。\n\n她今年二十六岁，是广告公司的客户总监。身高168，却有着一对沉甸甸的H罩杯巨乳，走路时那两团软肉在衬衫下微微晃动，足以让任何男人移不开眼。她的腰细得惊人，下面是浑圆挺翘、手感极佳的肥臀，穿包臀裙时曲线能把裙子撑出淫靡的弧度。她的乳晕是少女般的粉嫩色，蜜穴天生多汁，每次被你进入时都会发出黏腻的水声，像熟透的水蜜桃。\n\n这两年里，她几乎把所有女人的娇媚和放荡都给了你一个人。你加班晚归，她会仅穿着你的衬衫在厨房给你留饭，衬衫下摆堪堪盖住臀部，你从背后抱上去时她总会笑着扭动腰肢；周末的早晨她喜欢用那对豪乳夹住你的肉棒，一边乳交一边用湿漉漉的眼睛看着你；你们的性生活从来不需要前戏，因为她的身体永远为你准备好——一个眼神、一次触碰，她的小穴就会自己流出汁水。\n\n但你有个说</p>\n</article>", "branches": [{"tag": "A", "title": "深入互动", "desc": "顺应当前情境展开下一步剧情"}, {"tag": "B", "title": "试探心理", "desc": "观察对方细微的反应与意图"}, {"tag": "C", "title": "掌握主动", "desc": "以坚定的态度引导局势发展"}]}]', '/* --- 主题：樱花男子 (Sakura Danshi) - 女校唯一的你 --- */
/* --- 核心修复：强制亮色模式 & 移动端重置 & 状态栏紧凑化 --- */
:root {
    color-scheme: light !important;
}
* {
    -webkit-tap-highlight-color: transparent !important;
    -webkit-touch-callout: none !important;
}
*:focus, *:active {
    outline: none !important;
    box-shadow: none !important;
}

/* --- 整体风格：樱粉与天蓝的邂逅 --- */

/* 1. 主容器：柔和的樱花奶昔渐变 */
.bg-gray-100\/90.relative.inline-block {
    background: linear-gradient(165deg, #FFF0F5 0%, #F5F0FF 100%) !important;
    border: 3px solid #F5D0E0 !important;
    border-radius: 24px !important;
    box-shadow: 0 8px 25px rgba(245, 208, 224, 0.5) !important;
    padding: 20px !important;
    margin: 15px auto !important;
    max-width: 900px !important;
    position: relative !important;
}

/* 2. 文本区域：干净的少女日记本 */
.markdown-body {
    background-color: rgba(255, 250, 252, 0.9) !important;
    color: #5A4A5A !important;
    border-radius: 18px !important;
    padding: 20px !important;
    line-height: 1.8 !important;
    font-family: ''Nunito'', ''Segoe UI'', ''PingFang SC'', sans-serif !important;
    font-size: 1em !important;
    box-shadow: inset 0 2px 8px rgba(245, 208, 224, 0.2) !important;
}

/* 3. 标题：蔷薇粉 */
.markdown-body h1, .markdown-body h2, .markdown-body h3 {
    color: #D18DAA !important;
    text-shadow: 1px 1px 3px rgba(255, 255, 255, 0.7) !important;
    border-bottom: 2px solid #F5E0E8 !important;
    padding-bottom: 6px !important;
    margin-top: 1.5em !important;
    margin-bottom: 0.8em !important;
}

/* --- 状态栏 (Details) 紧凑化修改 --- */
details {
    background-color: #FFF9FC !important;
    border: 2px dashed #E8C8D8 !important;
    border-radius: 16px !important;
    /* 减小外边距 */
    margin: 15px 0 !important;
    /* 减小内边距 */
    padding: 10px 18px !important;
    box-shadow: 0 4px 12px rgba(232, 200, 216, 0.25) !important;
    transition: all 0.3s ease !important;
}

details[open] {
    border-style: solid !important;
    border-color: #D18DAA !important;
    background-color: #FFFAFC !important;
}

summary {
    /* 关键：减小字体大小，使其不再硕大 */
    font-size: 1.1em !important;
    font-weight: bold !important;
    color: #B080A8 !important;
    cursor: pointer !important;
    /* 减小垂直内边距 */
    padding: 4px 0 !important;
    transition: color 0.3s ease !important;
    outline: none !important;
    list-style: none !important;
}

/* 移除默认三角箭头 */
summary::-webkit-details-marker {
    display: none !important;
}

/* 自定义图标：樱花(女校) -> 蓝钻(男生) */
summary::before {
    content: ''🌸 '' !important;
    display: inline-block !important;
    /* 减小右边距 */
    margin-right: 8px !important;
    transform: rotate(0deg) scale(0.9) !important;
    transition: transform 0.3s ease !important;
    filter: drop-shadow(0 0 1px #FFC0CB) !important;
}

details[open] summary::before {
    /* 💎 代表男生的独特与珍稀 */
    content: ''💎 '' !important;
    transform: rotate(15deg) scale(1) !important;
    filter: drop-shadow(0 0 3px #87CEEB) !important;
}

/* 状态栏内的链接：天蓝色，代表男生的色彩 */
details a {
    color: #7BA8D0 !important;
    text-decoration: none !important;
    font-weight: 600 !important;
    border-bottom: 1px dotted #A0C4E8 !important;
}

/* --- 代码块强力修复 --- */
.markdown-body pre, .markdown-body code {
    background-color: #F8F5FF !important;
    border: 1px solid #E8E0F5 !important;
    border-radius: 10px !important;
    padding: 3px 6px !important;
    color: #7A6A95 !important;
    font-family: ''Consolas'', ''Courier New'', monospace !important;
    white-space: pre-wrap !important;
    word-break: break-all !important;
    font-size: 0.9em !important;
    outline: none !important;
    -webkit-appearance: none !important;
    box-shadow: none !important;
}
.markdown-body pre {
    padding: 12px 15px !important;
    border-left: 3px solid #D8C8F0 !important;
}

/* 顶部颜色条移除 */
[class*="bg-[#F1CBCB]"], [class*="bg-[#c9e1e9]"] {
    display: none !important;
}

/* 底部功能按钮 */
.MuiButtonBase-root.MuiButton-root {
    background: linear-gradient(135deg, #F5C6D8, #E8B0D8) !important;
    color: #FFFFFF !important;
    border-radius: 20px !important;
    box-shadow: 0 4px 15px rgba(245, 198, 216, 0.5) !important;
    transition: all 0.3s ease !important;
    font-weight: bold !important;
    text-transform: none !important;
    padding: 8px 18px !important;
    text-shadow: 0 1px 2px rgba(0,0,0,0.1) !important;
}
.MuiButtonBase-root.MuiButton-root:hover {
    transform: translateY(-2px) !important;
    box-shadow: 0 6px 20px rgba(245, 198, 216, 0.6) !important;
}

/* 用户输入框区域 */
.bg-gray-100\/90.relative.inline-block:not(.chat-answer-container .bg-gray-100\/90) {
    background: #F0F8FF !important; /* 天蓝色，代表男生的区域 */
    border: 2px solid #D0E4F4 !important;
    box-shadow: 0 5px 20px rgba(208, 228, 244, 0.6) !important;
    padding: 15px !important;
}

/* 输入框 */
textarea, input[type="text"] {
    background-color: #FFFFFF !important;
    border: 1px solid #D0E4F4 !important;
    border-radius: 12px !important;
    color: #4A5A7A !important;
    padding: 10px 14px !important;
    font-family: ''Nunito'', ''Segoe UI'', sans-serif !important;
    -webkit-appearance: none !important;
}
textarea:focus, input[type="text"]:focus {
    border-color: #87CEEB !important;
    box-shadow: 0 0 8px rgba(135, 206, 235, 0.4) !important;
}

/* --- 其他元素美化 --- */

/* 链接 */
.markdown-body a {
    color: #D18DAA !important;
    text-decoration: none !important;
    font-weight: bold !important;
    border-bottom: 1px solid #F5D0E0 !important;
}

/* 列表 */
.markdown-body ul {
    list-style: none !important;
    padding-left: 10px !important;
}
.markdown-body ul li::before {
    content: ''🎀 '' !important;
    margin-right: 6px !important;
}

/* 图片 */
.markdown-body img {
    border-radius: 16px !important;
    border: 2px solid #F5E0E8 !important;
    box-shadow: 0 4px 15px rgba(245, 208, 224, 0.3) !important;
    max-width: 100% !important;
    height: auto !important;
}

/* --- 手机端适配微调 --- */
@media (max-width: 768px) {
    .bg-gray-100\/90.relative.inline-block {
        margin: 10px !important;
        padding: 15px !important;
        border-radius: 20px !important;
    }
    .markdown-body {
        padding: 15px !important;
        font-size: 0.95em !important;
    }
    .markdown-body pre {
        overflow-x: auto !important;
        -webkit-overflow-scrolling: touch !important;
    }
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=5.0">
<title>她的出差行李 · 设定集</title>
<style>
    @import url(''https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;700&family=Ma+Shan+Zheng&display=swap'');

    :root{
        --bg-1:#f6f0fb;
        --bg-2:#efe3f7;
        --bg-3:#fbeef3;
        --card-bg:rgba(255,255,255,0.76);
        --card-border:rgba(168,120,214,0.35);
        --text:#4a3a5c;
        --text-soft:#7a668f;
        --title:#8e5cc4;
        --accent:#e0689a;
        --accent-2:#b07ad6;
        --gold:#c99a4b;
        --shadow:0 6px 22px rgba(142,92,196,0.16);
        --font:''Noto Serif SC'', serif;
    }

    *{
        margin:0;
        padding:0;
        box-sizing:border-box;
    }

    body{
        font-family:var(--font);
        background:
            radial-gradient(1200px 800px at 10% -10%, #fde7f3 0%, transparent 60%),
            radial-gradient(900px 700px at 110% 10%, #eee3fb 0%, transparent 55%),
            linear-gradient(160deg,var(--bg-1),var(--bg-2) 55%,var(--bg-3));
        color:var(--text);
        line-height:1.75;
        padding:24px 16px 60px;
        min-height:100vh;
    }

    .page-wrap{
        max-width:860px;
        margin:0 auto;
        position:relative;
    }

    /* 装饰光斑 */
    .page-wrap::before,
    .page-wrap::after{
        content:"";
        position:fixed;
        border-radius:50%;
        filter:blur(70px);
        opacity:.35;
        z-index:-1;
        pointer-events:none;
    }
    .page-wrap::before{
        width:320px;height:320px;
        background:#f7c6e0;
        top:-80px;left:-100px;
    }
    .page-wrap::after{
        width:280px;height:280px;
        background:#cdb6f2;
        bottom:-60px;right:-80px;
    }

    /* ============ 顶部标题 ============ */
    .header{
        text-align:center;
        margin-bottom:30px;
        padding:18px 12px 6px;
    }

    .header .sub{
        font-size:12px;
        letter-spacing:6px;
        color:var(--accent-2);
        text-transform:uppercase;
        opacity:.9;
    }

    .header h1{
        font-family:''Ma Shan Zheng'', cursive;
        font-size:clamp(30px,8vw,46px);
        color:var(--title);
        margin:6px 0 4px;
        text-shadow:0 2px 0 rgba(255,255,255,.8), 0 6px 18px rgba(142,92,196,.22);
        font-weight:400;
        letter-spacing:2px;
    }

    .header .line{
        width:120px;
        height:2px;
        margin:10px auto 8px;
        background:linear-gradient(90deg,transparent,var(--accent-2),transparent);
        border-radius:2px;
    }

    .header .desc{
        font-size:13px;
        color:var(--text-soft);
        letter-spacing:1px;
    }

    /* ============ 卡片通用 ============ */
    .card{
        background:var(--card-bg);
        backdrop-filter:blur(14px);
        -webkit-backdrop-filter:blur(14px);
        border:1px solid var(--card-border);
        border-radius:20px;
        padding:22px 20px;
        margin-bottom:22px;
        box-shadow:var(--shadow);
        position:relative;
        overflow:hidden;
        transition:transform .25s ease, box-shadow .25s ease;
    }

    .card::before{
        content:"";
        position:absolute;
        top:0;left:0;right:0;
        height:3px;
        background:linear-gradient(90deg,transparent,var(--accent),var(--accent-2),transparent);
        opacity:.7;
    }

    .card:hover{
        transform:translateY(-2px);
        box-shadow:0 12px 28px rgba(142,92,196,0.22);
    }

    .card-title{
        display:flex;
        align-items:center;
        gap:8px;
        font-size:17px;
        font-weight:700;
        color:var(--title);
        margin-bottom:14px;
        padding-bottom:8px;
        border-bottom:1px dashed rgba(168,120,214,.35);
    }

    .card-title .dot{
        width:9px;height:9px;border-radius:50%;
        background:linear-gradient(135deg,var(--accent),var(--accent-2));
        box-shadow:0 0 8px rgba(224,104,154,.6);
        flex-shrink:0;
    }

    .card-title small{
        font-size:11px;
        color:var(--text-soft);
        font-weight:400;
        margin-left:auto;
        letter-spacing:1px;
    }

    /* ============ 玩家设定 ============ */
    .player-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(200px,1fr));
        gap:10px 14px;
    }

    .field{
        display:flex;
        align-items:flex-start;
        gap:6px;
        font-size:13.5px;
    }

    .field .label{
        color:var(--accent-2);
        font-weight:600;
        flex-shrink:0;
        min-width:62px;
        padding-top:8px;
    }

    /* 可编辑控件统一风格 */
    .field input,
    .field textarea{
        flex:1;
        min-width:0;
        width:100%;
        border:1px solid rgba(176,122,214,.35);
        border-radius:12px;
        padding:8px 12px;
        font-family:var(--font);
        font-size:13px;
        color:var(--text);
        background:rgba(255,255,255,.7);
        outline:none;
        transition:border .2s, box-shadow .2s, background .2s;
        line-height:1.7;
    }

    .field input::placeholder,
    .field textarea::placeholder{
        color:#b8a8cc;
    }

    .field input:hover,
    .field textarea:hover{
        border-color:rgba(224,104,154,.55);
        background:rgba(255,255,255,.85);
    }

    .field input:focus,
    .field textarea:focus{
        border-color:var(--accent);
        background:#fff;
        box-shadow:0 0 0 3px rgba(224,104,154,.15);
    }

    .field textarea{
        resize:vertical;
        min-height:64px;
    }

    .field.full{
        grid-column:1/-1;
    }

    .note{
        font-size:12px;
        color:var(--text-soft);
        margin-top:12px;
        padding-left:4px;
        border-left:2px solid var(--accent-2);
        padding-top:2px;
        padding-bottom:2px;
        line-height:1.7;
    }

    /* ============ 开场白 ============ */
    .opening-list{
        display:flex;
        flex-direction:column;
        gap:12px;
    }

    .opening-item{
        display:flex;
        gap:10px;
        align-items:flex-start;
        background:rgba(255,255,255,.55);
        border:1px solid rgba(224,104,154,.22);
        border-radius:14px;
        padding:12px 14px;
        cursor:pointer;
        transition:all .22s ease;
        position:relative;
    }

    .opening-item:hover{
        background:rgba(255,238,247,.9);
        border-color:var(--accent);
        transform:translateX(3px);
    }

    .opening-item.active{
        background:linear-gradient(135deg,rgba(253,231,243,.95),rgba(238,227,251,.95));
        border-color:var(--accent-2);
        box-shadow:0 4px 14px rgba(176,122,214,.25);
    }

    .opening-item.active::after{
        content:"✓";
        position:absolute;
        top:8px;right:10px;
        font-size:12px;
        color:#fff;
        background:var(--accent-2);
        width:18px;height:18px;
        border-radius:50%;
        display:flex;align-items:center;justify-content:center;
        font-weight:700;
    }

    .opening-num{
        flex-shrink:0;
        width:24px;height:24px;
        border-radius:50%;
        background:linear-gradient(135deg,var(--accent),var(--accent-2));
        color:#fff;
        font-size:12px;
        font-weight:700;
        display:flex;align-items:center;justify-content:center;
        margin-top:2px;
        box-shadow:0 2px 6px rgba(224,104,154,.4);
    }

    .opening-text{
        font-size:13.5px;
        color:var(--text);
        line-height:1.72;
        flex:1;
    }

    .opening-text em{
        color:var(--accent);
        font-style:normal;
        font-weight:600;
    }

    .custom-opening{
        margin-top:14px;
    }

    .custom-opening label{
        font-size:12.5px;
        color:var(--accent-2);
        font-weight:600;
        display:block;
        margin-bottom:6px;
    }

    .custom-opening textarea{
        width:100%;
        min-height:72px;
        resize:vertical;
        border:1px solid rgba(176,122,214,.35);
        border-radius:12px;
        padding:10px 12px;
        font-family:var(--font);
        font-size:13px;
        color:var(--text);
        background:rgba(255,255,255,.7);
        outline:none;
        transition:border .2s, box-shadow .2s;
        line-height:1.7;
    }

    .custom-opening textarea:focus{
        border-color:var(--accent);
        box-shadow:0 0 0 3px rgba(224,104,154,.15);
    }

    .custom-opening textarea::placeholder{
        color:#b8a8cc;
    }

    /* ============ 总结区 ============ */
    .summary{
        background:linear-gradient(145deg,rgba(255,246,252,.95),rgba(245,238,255,.95));
        border:1.5px solid var(--card-border);
        border-radius:20px;
        padding:20px 20px 18px;
        margin-bottom:22px;
        box-shadow:0 8px 26px rgba(142,92,196,.18);
        position:relative;
    }

    .summary::before{
        content:"";
        position:absolute;
        inset:0;
        border-radius:20px;
        padding:1.5px;
        background:linear-gradient(135deg,var(--accent),var(--accent-2),var(--gold));
        -webkit-mask:linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
        -webkit-mask-composite:xor;
        mask-composite:exclude;
        opacity:.55;
        pointer-events:none;
    }

    .summary-title{
        display:flex;
        align-items:center;
        gap:8px;
        font-size:16px;
        font-weight:700;
        color:var(--title);
        margin-bottom:12px;
    }

    .summary-title .icon{
        font-size:16px;
    }

    .summary-content{
        font-size:13.5px;
        line-height:1.9;
        color:var(--text);
        white-space:pre-wrap;
        word-break:break-word;
        max-height:320px;
        overflow-y:auto;
        padding-right:6px;
    }

    .summary-content::-webkit-scrollbar{
        width:5px;
    }
    .summary-content::-webkit-scrollbar-thumb{
        background:rgba(176,122,214,.45);
        border-radius:6px;
    }

    .summary-content .s-label{
        color:var(--accent-2);
        font-weight:700;
    }

    .summary-content .s-opening{
        color:var(--accent);
    }

    .summary-empty{
        font-size:13px;
        color:#b8a8cc;
        text-align:center;
        padding:14px 0;
        font-style:italic;
    }

    /* ============ 按钮组 ============ */
    .btn-row{
        display:flex;
        gap:12px;
        margin-top:16px;
        flex-wrap:wrap;
    }

    .btn{
        flex:1;
        min-width:140px;
        border:none;
        border-radius:14px;
        padding:13px 18px;
        font-family:var(--font);
        font-size:15px;
        font-weight:700;
        letter-spacing:2px;
        cursor:pointer;
        transition:all .25s ease;
        position:relative;
        overflow:hidden;
    }

    .btn-primary{
        background:linear-gradient(135deg,var(--accent),var(--accent-2));
        color:#fff;
        box-shadow:0 6px 18px rgba(224,104,154,.4);
    }

    .btn-primary:hover{
        transform:translateY(-2px);
        box-shadow:0 10px 24px rgba(224,104,154,.55);
    }

    .btn-primary:active{
        transform:translateY(0) scale(.98);
    }

    .btn-copy{
        background:linear-gradient(135deg,#a06cd5,#c58ad9);
        color:#fff;
        box-shadow:0 6px 18px rgba(160,108,213,.4);
    }

    .btn-copy:hover{
        transform:translateY(-2px);
        box-shadow:0 10px 24px rgba(160,108,213,.55);
    }

    .btn-copy:active{
        transform:translateY(0) scale(.98);
    }

    .btn-copy.copied{
        background:linear-gradient(135deg,#7ec48f,#9bd8a8);
        box-shadow:0 6px 18px rgba(126,196,143,.4);
    }

    /* ============ 背景故事 / 人物介绍 ============ */
    .story-text{
        font-size:13.5px;
        line-height:2;
        color:var(--text);
    }

    .story-text p{
        margin-bottom:12px;
        text-indent:2em;
    }

    .story-text p:last-child{
        margin-bottom:0;
    }

    .highlight{
        color:var(--accent);
        font-weight:600;
    }

    .highlight-2{
        color:var(--title);
        font-weight:600;
    }

    /* 人物卡美化 */
    .char-block{
        background:rgba(255,255,255,.5);
        border-radius:16px;
        padding:16px 16px 14px;
        margin-bottom:16px;
        border:1px solid rgba(168,120,214,.2);
        position:relative;
    }

    .char-block:last-child{
        margin-bottom:0;
    }

    .char-block .char-name{
        display:flex;
        align-items:center;
        gap:8px;
        font-size:15.5px;
        font-weight:700;
        color:var(--title);
        margin-bottom:10px;
    }

    .char-block .char-name .tag{
        font-size:10.5px;
        font-weight:600;
        color:#fff;
        padding:2px 9px;
        border-radius:20px;
        letter-spacing:1px;
        background:linear-gradient(135deg,var(--accent),var(--accent-2));
        box-shadow:0 2px 6px rgba(224,104,154,.3);
    }

    .char-block .char-name .tag.gold{
        background:linear-gradient(135deg,#c99a4b,#e0b96a);
        box-shadow:0 2px 6px rgba(201,154,75,.3);
    }

    .char-block .char-name .tag.blue{
        background:linear-gradient(135deg,#5b8def,#7fa8f5);
        box-shadow:0 2px 6px rgba(91,141,239,.3);
    }

    .char-row{
        font-size:13px;
        line-height:1.9;
        margin-bottom:4px;
        display:flex;
        gap:6px;
        align-items:flex-start;
    }

    .char-row .label{
        color:var(--accent-2);
        font-weight:600;
        flex-shrink:0;
        min-width:62px;
    }

    .char-row .val{
        color:var(--text);
        word-break:break-word;
        flex:1;
    }

    .char-row .val em{
        color:var(--accent);
        font-style:normal;
        font-weight:600;
    }

    .char-quote{
        margin-top:10px;
        padding:9px 12px;
        background:rgba(253,231,243,.6);
        border-left:3px solid var(--accent);
        border-radius:0 10px 10px 0;
        font-size:12.5px;
        color:var(--text-soft);
        line-height:1.8;
    }

    .char-quote .q{
        color:var(--accent);
        font-weight:600;
    }

    /* ============ 数值/路线 ============ */
    .value-grid{
        display:grid;
        grid-template-columns:1fr 1fr;
        gap:14px;
        margin-bottom:16px;
    }

    @media (max-width:520px){
        .value-grid{
            grid-template-columns:1fr;
        }
    }

    .value-box{
        background:rgba(255,255,255,.6);
        border-radius:16px;
        padding:14px 16px;
        border:1px solid rgba(168,120,214,.22);
    }

    .value-box .v-name{
        font-size:12.5px;
        font-weight:700;
        color:var(--title);
        letter-spacing:1px;
        margin-bottom:8px;
        display:flex;
        align-items:center;
        gap:6px;
    }

    .value-box .v-name .v-dot{
        width:8px;height:8px;border-radius:50%;
        flex-shrink:0;
    }
    .value-box .v-name .v-dot.red{
        background:#e0689a;
        box-shadow:0 0 6px rgba(224,104,154,.7);
    }
    .value-box .v-name .v-dot.green{
        background:#7ec48f;
        box-shadow:0 0 6px rgba(126,196,143,.7);
    }

    .value-bar{
        height:10px;
        background:rgba(168,120,214,.15);
        border-radius:10px;
        overflow:hidden;
        margin-bottom:6px;
    }

    .value-bar span{
        display:block;
        height:100%;
        border-radius:10px;
        transition:width .8s ease;
    }

    .value-bar .fill-red{
        background:linear-gradient(90deg,#e0689a,#c9557f);
        width:10%;
    }

    .value-bar .fill-green{
        background:linear-gradient(90deg,#7ec48f,#5bb37a);
        width:0%;
    }

    .value-box .v-desc{
        font-size:11.5px;
        color:var(--text-soft);
        line-height:1.7;
        margin-top:4px;
    }

    .route-title{
        font-size:14px;
        font-weight:700;
        color:var(--title);
        margin:18px 0 10px;
        display:flex;
        align-items:center;
        gap:8px;
    }

    .route-title .r-line{
        flex:1;
        height:1px;
        background:linear-gradient(90deg,rgba(176,122,214,.4),transparent);
    }

    .route-list{
        display:flex;
        flex-direction:column;
        gap:10px;
    }

    .route-item{
        display:flex;
        gap:10px;
        align-items:flex-start;
        padding:11px 14px;
        border-radius:14px;
        background:rgba(255,255,255,.5);
        border:1px solid rgba(168,120,214,.2);
        transition:all .2s ease;
    }

    .route-item:hover{
        background:rgba(255,238,247,.75);
        border-color:var(--accent-2);
    }

    .route-icon{
        flex-shrink:0;
        width:28px;height:28px;
        border-radius:50%;
        display:flex;align-items:center;justify-content:center;
        font-size:14px;
        margin-top:1px;
    }

    .route-icon.green{
        background:linear-gradient(135deg,#e3f6e6,#c9eccd);
    }
    .route-icon.red{
        background:linear-gradient(135deg,#fde3ee,#f7c6dc);
    }
    .route-icon.purple{
        background:linear-gradient(135deg,#efe3fb,#e0ccf7);
    }

    .route-item .r-text{
        font-size:13px;
        line-height:1.8;
        color:var(--text);
    }

    .route-item .r-text b{
