  ];

  /* ---------- 开场白选择 ---------- */
  function updateOpeningSelection(){
    var items = openingList.querySelectorAll(''.opening-item'');
    for(var i=0;i<items.length;i++){
      if(parseInt(items[i].getAttribute(''data-index''),10) === selectedOpeningIndex){
        items[i].classList.add(''selected'');
      } else {
        items[i].classList.remove(''selected'');
      }
    }
    /* 如果选中了内置项，清空自定义输入框的选中态（视觉上） */
    if(selectedOpeningIndex >= 0){
      customOpening.style.borderColor = '''';
    }
  }

  openingList.addEventListener(''click'', function(e){
    var item = e.target.closest(''.opening-item'');
    if(!item) return;
    selectedOpeningIndex = parseInt(item.getAttribute(''data-index''),10);
    customOpening.value = ''''; /* 选内置时清空自定义 */
    updateOpeningSelection();
  });

