      selectedOpeningIndex = -1;
      updateOpeningSelection();
      customOpening.style.borderColor = ''var(--accent)'';
    } else {
      selectedOpeningIndex = 0;
      updateOpeningSelection();
      customOpening.style.borderColor = '''';
    }
  });

  /* ---------- 生成 ---------- */
  function escapeHTML(str){
    if(!str) return '''';
    return String(str)
      .replace(/&/g,''&amp;'')
      .replace(/</g,''&lt;'')
      .replace(/>/g,''&gt;'')
      .replace(/"/g,''&quot;'')
      .replace(/''/g,''&#39;'');
  }

  function getSelectedOpeningText(){
    var custom = customOpening.value.trim();
    if(selectedOpeningIndex === -1 && custom !== ''''){
      return custom;
    }
    if(selectedOpeningIndex >= 0 && selectedOpeningIndex < openings.length){
      return openings[selectedOpeningIndex];
    }
    /* fallback */
    return openings[0];
  }

  function buildSummaryHTML(){
    var name       = escapeHTML(playerName.value.trim() || ''（未填写）'');
    var age        = escapeHTML(playerAge.value.trim() || ''（未填写）'');
    var gender     = escapeHTML(playerGender.value);
    var identity   = escapeHTML(playerIdentity.value.trim() || ''（未填写）'');
    var appearance = escapeHTML(playerAppearance.value.trim() || ''（未填写）'');
    var personality= escapeHTML(playerPersonality.value.trim() || ''（未填写）'');
    var dick       = escapeHTML(playerDick.value.trim() || ''（未填写）'');
    var other      = escapeHTML(playerOther.value.trim() || ''（未填写）'');
    var opening    = escapeHTML(getSelectedOpeningText());

    var html = '''';
    html += ''<div class="field-line"><span class="label">姓名：</span><span class="value">'' + name + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">年龄：</span><span class="value">'' + age + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">性别：</span><span class="value">'' + gender + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">身份背景：</span><span class="value">'' + identity + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">外貌：</span><span class="value">'' + appearance + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">性格：</span><span class="value">'' + personality + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">肉棒设定：</span><span class="value">'' + dick + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">其他设定：</span><span class="value">'' + other + ''</span></div>'';
    html += ''<div class="opening-preview">'' + opening + ''</div>'';

    return html;
  }

  generateBtn.addEventListener(''click'', function(){
    summaryContent.innerHTML = buildSummaryHTML();
    /* 滚动到总结区 */
    var summarySection = document.getElementById(''summarySection'');
    if(summarySection){
      summarySection.scrollIntoView({behavior:''smooth'', block:''start''});
    }
  });

  /* ---------- 一键复制 ---------- */
  function buildCopyText(){
    var name       = playerName.value.trim() || ''（未填写）'';
    var age        = playerAge.value.trim() || ''（未填写）'';
    var gender     = playerGender.value;
    var identity   = playerIdentity.value.trim() || ''（未填写）'';
    var appearance = playerAppearance.value.trim() || ''（未填写）'';
    var personality= playerPersonality.value.trim() || ''（未填写）'';
    var dick       = playerDick.value.trim() || ''（未填写）'';
    var other      = playerOther.value.trim() || ''（未填写）'';
    var opening    = getSelectedOpeningText();

    var lines = [];
    lines.push(''【玩家设定】'');
    lines.push(''姓名：'' + name);
    lines.push(''年龄：'' + age);
    lines.push(''性别：'' + gender);
    lines.push(''身份背景：'' + identity);
    lines.push(''外貌：'' + appearance);
    lines.push(''性格：'' + personality);
    lines.push(''肉棒设定：'' + dick);
    lines.push(''其他设定：'' + other);
    lines.push('''');
    lines.push(''【开场白】'');
    lines.push(opening);

    return lines.join(''\n'');
  }

  function showToast(msg){
    toast.textContent = msg || ''已复制'';
    toast.classList.add(''show'');
    clearTimeout(toast._timer);
    toast._timer = setTimeout(function(){
      toast.classList.remove(''show'');
    }, 1800);
  }

  function fallbackCopy(text){
    var ta = document.createElement(''textarea'');
    ta.value = text;
    ta.style.position = ''fixed'';
    ta.style.left = ''-9999px'';
    ta.style.top = ''0'';
    ta.style.opacity = ''0'';
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    try{
      var ok = document.execCommand(''copy'');
      document.body.removeChild(ta);
      return ok;
    } catch(e){
      document.body.removeChild(ta);
      return false;
    }
  }

  copyBtn.addEventListener(''click'', function(){
    var text = buildCopyText();

    /* 优先使用 Clipboard API */
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(text).then(function(){
