<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>
身份录入
</button>
</div>
<div class="panel-container">
<div id="intro-panel" class="panel">
<div class="intro-text">
<!-- 【★ 3. 修改作品简介内容 ★】 (使用 <p> 标签分段) -->
<p>在这个欲望横流的架空都市，你通过一家口碑暧昧的家政公司，雇佣了一位保洁阿姨。然而，门铃响起，站在门外的却是一位足以让任何男人瞬间窒息的绝色尤物——她拥有惊心动魄的巨乳、纤细如柳的腰肢、浑圆挺翘的蜜桃臀，以及一双笔直修长的美腿，完美的沙漏体型被一套过分紧身的保洁制服勾勒得淋漓尽致。她自称是一位单亲妈妈，需要这份工作抚养女儿。起初，你只是沉醉于她打扫时弯腰翘臀的无限春光，以及那对在抹桌时颤巍巍晃动的硕大乳球。但通过一次次日常接触，你慢慢走进了这位外表性感、内心却藏着故事的女人世界。直到有一天，她带着她年仅十五岁、却已出落得亭亭玉立、青春胴体散发着诱人芬芳的女儿一同上门。这位巨乳家政母亲看穿了你在她们母女身上流连的炽热目光，温柔一笑，从此，你的生活被这对极品母女花彻底填满，享受着一人独占母女二人的欢愉。</p>
</div>
</div>
<div id="custom-panel" class="panel">
<form id="char-form">
<div class="form-group"><label>姓名</label><input type="text" id="f-name" placeholder="输入你的名字或化名..." oninput="updatePreview()"></div>
<div class="form-group"><label>性别</label><select id="f-gender" onchange="updateGender()"><option value="男">男</option><option value="女">女</option></select></div>
<div class="form-group"><label>年龄</label><input type="number" id="f-age" placeholder="输入年龄..." oninput="updatePreview()"></div>
<div class="form-group"><label>性格</label><input type="text" id="f-personality" placeholder="如：好色、狡诈、控制欲强..." oninput="updatePreview()"></div>
<div class="form-group full-width"><label>外貌</label><textarea id="f-appearance" placeholder="描述你的长相、穿着打扮..." oninput="updatePreview()"></textarea></div>
<div class="form-group"><label id="dynamic-label">肉棒设定</label><input type="text" id="f-body" placeholder="尺寸、形状、持久度等..." oninput="updatePreview()"></div>
<div class="form-group"><label>财富</label><input type="text" id="f-wealth" placeholder="如：暴发户、富二代..." oninput="updatePreview()"></div>
<div class="form-group full-width"><label>其他设定</label><textarea id="f-other" placeholder="补充你的特殊XP、常去的地点、或是随身携带的道具..." oninput="updatePreview()"></textarea></div>
</form>
<div class="preview-box" id="preview">请填写上方信息以生成角色设定...</div>
<button id="copy-button" onclick="copyToClipboard()">录入并复制设定</button>
</div>
</div>
<div id="toast" style="display: none;"><p>系统提示：信息已成功复制入剪贴板</p><button onclick="document.getElementById(''toast'').style.display=''none''">关闭</button></div>
<footer>推荐新人模型deepseek-v4</footer>
<script>
// 【★ 4. 修改打字机标题 ★】 (这里修改窗口左上角打字机效果显示的文字)
const titleStr = "《赤裸家政母女花》";
const titleEl = document.getElementById(''typewriter'');
let charIdx = 0;
function typeTitle() {
if(charIdx < titleStr.length){
titleEl.textContent += titleStr[charIdx];
charIdx++;
setTimeout(typeTitle, 200);
}
}
window.onload = () => { typeTitle(); startCarousel(); };
let currentImg = 0;

const imgs = document.querySelectorAll(''.carousel img'');
const dots = document.querySelectorAll(''.dot'');

/*
 * 播放器外框元素
 */
const playerContent = document.querySelector(''.player-content'');
/*
 * 根据当前图片的真实宽高比例，
 * 自动调整播放器外框比例
 */
function resizePlayerToImage(index) {
    const img = imgs[index];

    function applyRatio() {
        /*
         * naturalWidth 和 naturalHeight
         * 是图片加载完成后的真实尺寸
         */
        if (img.naturalWidth && img.naturalHeight) {
            playerContent.style.aspectRatio =
                `${img.naturalWidth} / ${img.naturalHeight}`;
        }
    }

    /*
     * 如果图片已经加载完成，直接读取比例
     */
    if (img.complete && img.naturalWidth) {
        applyRatio();
    } else {
        /*
         * 如果图片还没有加载完成，
         * 等待加载完成后再读取比例
         */
        img.addEventListener(''load'', applyRatio, {
            once: true
        });
    }
}

/*
 * 启动轮播
 */
function startCarousel() {
    /*
     * 页面打开时，先根据第一张 GIF 调整播放器比例
     */
    resizePlayerToImage(currentImg);

    /*
     * 定时切换图片
     */
    setInterval(() => {
        /*
         * 移除当前图片和指示点的 active 状态
         */
        imgs[currentImg].classList.remove(''active'');
        dots[currentImg].classList.remove(''active'');

        /*
         * 切换到下一张图片
         */
        currentImg = (currentImg + 1) % imgs.length;

        /*
         * 添加新的 active 状态
         */
        imgs[currentImg].classList.add(''active'');
        dots[currentImg].classList.add(''active'');

        /*
         * 根据新图片的比例调整外部播放器高度
         */
        resizePlayerToImage(currentImg);
    }, 2800);
}
function togglePanel(panelId, btn) {
const panel = document.getElementById(panelId);
const isActive = panel.classList.contains(''active'');
document.querySelectorAll(''.panel'').forEach(p => p.classList.remove(''active''));
document.querySelectorAll(''.taskbar-btn'').forEach(b => b.classList.remove(''active''));
if(!isActive) {
panel.classList.add(''active'');
btn.classList.add(''active'');
}
}
function selectIcon(el, event) {
event.stopPropagation();
document.querySelectorAll(''.icon-item'').forEach(i => i.classList.remove(''selected''));
el.classList.add(''selected'');
}
function updateGender() {
const isMale = document.getElementById(''f-gender'').value === ''男'';
const label = document.getElementById(''dynamic-label'');
const input = document.getElementById(''f-body'');
if(isMale){
label.textContent = ''肉棒设定'';
input.placeholder = ''尺寸、形状、持久度等...'';
}else{
label.textContent = ''三围设定'';
input.placeholder = ''胸围、腰围、臀围等...'';
}
updatePreview();
}
function updatePreview() {
const name = document.getElementById(''f-name'').value || ''未命名'';
const gender = document.getElementById(''f-gender'').value;
const age = document.getElementById(''f-age'').value || ''未知'';
const personality = document.getElementById(''f-personality'').value || ''未设定'';
const appearance = document.getElementById(''f-appearance'').value || ''未设定'';
const bodyLabel = document.getElementById(''dynamic-label'').textContent;
const bodyVal = document.getElementById(''f-body'').value || ''未设定'';
const wealth = document.getElementById(''f-wealth'').value || ''未设定'';
const other = document.getElementById(''f-other'').value || ''无'';
// 【★ 5. 修改复制出来的最终提示词后缀 ★】 (修改 \n\n 后面的文字，用于适配不同剧情的开场)
const previewText = `【玩家角色设定】\n姓名：${name}\n性别：${gender}\n年龄：${age}\n性格：${personality}\n外貌：${appearance}\n${bodyLabel}：${bodyVal}\n财富状态：${wealth}\n其他设定：${other}\n\n请根据设定，玩家角色，开始游戏。`;
document.getElementById(''preview'').textContent = previewText;
}
function copyToClipboard() {
const text = document.getElementById(''preview'').textContent;
const textarea = document.createElement(''textarea'');
textarea.value = text;
document.body.appendChild(textarea);
textarea.select();
document.execCommand(''copy'');
document.body.removeChild(textarea);
const toast = document.getElementById(''toast'');
toast.style.display = ''flex'';
setTimeout(() => { toast.style.display = ''none''; }, 3000);
}
document.addEventListener(''click'', function(event) {
const isClickInsidePanel = event.target.closest(''.panel-container'');
const isClickOnBtn = event.target.closest(''.taskbar-btn'');
const isClickOnIcon = event.target.closest(''.icon-item'');
if (!isClickOnIcon) {
document.querySelectorAll(''.icon-item'').forEach(i => i.classList.remove(''selected''));
}
if (!isClickInsidePanel && !isClickOnBtn) {
document.querySelectorAll(''.panel'').forEach(p => p.classList.remove(''active''));
document.querySelectorAll(''.taskbar-btn'').forEach(b => b.classList.remove(''active''));
}
});
</script>
</body>', '都市', '2026-09-14 07:45:17', '2026-09-14 07:45:17', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_succubus_wife', '❤帮兄弟喂养她的新婚魅魔妻子❤（NTL）【配套瑟瑟CG】', '人妻魅魔 · NTL喂养', '😈', '喂养兄弟妻子', '新婚魅魔妻子莉莉 · NTL喂养', '😈', '#e85a8a', 'linear-gradient(135deg, #e85a8a 0%, #fd79a8 100%)', '{"desc": "你的挚爱亲朋大强兄弟，要去海上油田出差3个月，他拜托你照顾他的新婚魅魔妻子莉莉。莉莉每天都有摄入精气的需求，大强走前给你留了个飞机杯，并嘱咐你如果不想用可以拜托你嫂子用手...同居屋檐下的身体诱惑与禁忌伦理。", "author": "AI风月精选"}', '[{"name": "莉莉", "role": "新婚魅魔娇妻 (20岁 / 164cm / H罩杯)", "desc": "大强的新婚妻子，银白长发、紫瞳娇媚。拥有极致水滴型H罩杯与纤细柳腰，天生魅魔体质极度敏感多汁，每天必须摄入浓郁精气维持身体活力。在大强封闭出差后身体空虚难耐，身心在对丈夫的愧疚与对兄弟的生理渴望间剧烈摇摆沉沦。"}, {"name": "兄弟大强", "role": "海上油田封闭出差的亲兄弟", "desc": "主角多年的挚爱亲朋，远赴海上钻井平台工作，每月只能偶尔打电话联系，毫无保留地将新婚娇妻与家门钥匙托付给主角。"}]', '[{"title": "大强婚房 · 客厅沙发", "desc": "工字背心下激凸饱满的H罩杯巨乳与泛红的大腿根部，弥漫着甜腻魅魔体香"}, {"title": "主卧大床 · 深夜喂精", "desc": "夜深人静时身体燥热发颤，跪伏在床头等待吸吮浓精的娇喘诱惑"}, {"title": "浴室氤氲 · 贴身洗浴", "desc": "湿漉漉的银发贴在雪白背脊上，滑腻沐浴泡沫中打破最后伦理防线"}]', '{}', '{"location": "兄弟大强的温馨婚房 · 客厅玄关", "story": "拖着沉重的行李箱，你拿着大强交到你手中的备用钥匙，轻轻拧开了防盗门锁。\n客厅里弥漫着一股淡淡的香甜奶香与魅魔独有的温热诱人气息。大强昨晚刚乘直升机前往封闭的海上油田，临走前塞给你飞机杯和几千块生活费，千叮咛万嘱咐让你照顾好他的新婚妻子莉莉。\n玄关地毯上，刚刚洗漱完的莉莉正穿着一件单薄微透的白色工字背心与粉白条纹纯棉小内裤坐在地毯上发呆。一头柔顺的银白色长发散落在她泛着潮红的香肩上，那对沉甸甸的H罩杯水滴巨乳随着微弱的呼吸轻轻晃动，胸前两点深粉色的乳晕在单薄的白背心下若隐若现，甚至顶出了明显的激凸。听到开门声，她那双湿漉漉的淡紫色眸子慌乱地抬起，修长丰腴的大腿下意识微微并拢，但眼角泛着一丝难以自抑的空虚潮红：“啊……是……是大强的好兄弟你来啦……大强昨天刚走……我……我的身体今天就有点……开始发热难受了……”", "branches": [{"tag": "A", "title": "拿出大强留下的飞机杯，提出先按规矩在洗手间采精后喂给她", "desc": "遵守大强留下的安全预案，去卫生间用飞机杯收集精液倒进小碗喂食【规矩执行: 表面克制，以飞机杯采精破冰】"}, {"tag": "B", "title": "走近居高临下注视她激凸的双峰，关切询问身体发热的饥渴程度", "desc": "缩短距离坐在沙发边缘，用关怀之名直视她微透白背心下的诱惑线条【细微试探: 缩短距离，以关怀之名击穿心防】"}, {"tag": "C", "title": "递出纸巾并坐在沙发旁，提出如果飞机杯不习惯也可以拜托嫂子直接用手", "desc": "提及大强临走前的第二种许可，试探她是否愿意用柔嫩手掌直接帮自己排精【言语推拉: 试探底线，引导大强留下的第二选择】"}, {"tag": "D", "title": "顺手反锁防盗大门，单膝跪地伸手抚摸她微颤的银白长发与滚烫脸颊", "desc": "当面断绝外界打扰，直接展开肢体接触，抚摸她因缺乏精气而滚烫娇颤的身躯【强势侵入: 挑破道德遮羞布，直接展开肢体升温】"}]}', '/* =========================================================
   莉莉 插图引擎 + 回复结构
   立绘 A01-A09 → 状态栏
   CG   CG01-CG37 → 正文剧情图
   ========================================================= */

/* ---------- 每轮顶部：场景 / 同居天数 ---------- */

.sv-meta {
  display: block !important;
  width: 100% !important;
  margin: 0 0 14px !important;
  padding: 10px 12px !important;
  background: #fff !important;
  border: 3px solid #111 !important;
  box-shadow: 5px 5px 0 #d6d6d6 !important;
  font-size: 14px !important;
  line-height: 1.7 !important;
}

.sv-meta .sv-meta-row {
  display: block !important;
}

