        }
        .card-title .icon {
            font-size: 1.1rem;
        }

        .intro-text {
            font-size: 0.95rem;
            color: var(--text-light);
            text-align: center;
            line-height: 1.9;
            letter-spacing: 0.04em;
        }
        .intro-text .highlight {
            color: var(--accent);
            font-weight: 600;
        }

        .story-block p {
            margin-bottom: 12px;
            text-indent: 2em;
            font-size: 0.95rem;
            color: var(--text);
        }
        .story-block p:last-child {
            margin-bottom: 0;
        }
        .story-highlight {
            display: inline-block;
            background: var(--tag-bg);
            color: var(--tag-text);
            padding: 2px 10px;
            border-radius: 20px;
            font-size: 0.85rem;
            font-weight: 500;
            margin: 0 2px;
        }

        .tag-row {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            margin-bottom: 16px;
        }
        .tag {
            display: inline-block;
            background: var(--tag-bg);
            color: var(--tag-text);
            padding: 4px 12px;
            border-radius: 20px;
            font-size: 0.82rem;
            font-weight: 500;
            white-space: nowrap;
        }

        .char-section {
            margin-bottom: 16px;
        }
        .char-section h3 {
            font-family: var(--font-heading);
            font-size: 1rem;
            font-weight: 600;
            color: var(--accent);
            margin-bottom: 8px;
            letter-spacing: 0.05em;
        }
        .char-section p,
        .char-section li {
            font-size: 0.9rem;
            color: var(--text);
            margin-bottom: 6px;
            line-height: 1.8;
        }
        .char-section ul {
            list-style: none;
            padding-left: 0;
        }
        .char-section ul li::before {
            content: "✦";
            color: var(--accent-light);
            margin-right: 8px;
            font-size: 0.7rem;
        }
        .char-section .detail-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 4px 16px;
        }
        .char-section .detail-item {
            font-size: 0.88rem;
            color: var(--text);
            padding: 3px 0;
            border-bottom: 1px dotted var(--border);
        }
        .char-section .detail-label {
            color: var(--text-light);
            font-size: 0.8rem;
        }

        .jealousy-box {
            background: linear-gradient(135deg, #fdf2f2, #fef9f5);
            border-radius: 12px;
            padding: 16px;
            border: 1px solid #f0d8d4;
            margin-top: 10px;
        }
        .jealousy-box .jealousy-title {
            font-weight: 600;
            color: #b8534a;
            margin-bottom: 8px;
            font-size: 0.92rem;
        }
        .jealousy-box ul {
            list-style: none;
            padding-left: 0;
        }
        .jealousy-box ul li {
            font-size: 0.88rem;
            margin-bottom: 5px;
            padding-left: 16px;
            position: relative;
        }
        .jealousy-box ul li::before {
            content: "🔥";
            position: absolute;
            left: 0;
            font-size: 0.7rem;
        }

        .player-section {
            margin-bottom: 8px;
        }
        .player-section .form-group {
            margin-bottom: 12px;
        }
        .player-section label {
            display: block;
            font-size: 0.85rem;
            font-weight: 600;
            color: var(--text);
            margin-bottom: 4px;
            letter-spacing: 0.04em;
        }
        .player-section input,
        .player-section select,
        .player-section textarea {
            width: 100%;
            padding: 10px 14px;
            border: 1px solid var(--border);
            border-radius: 10px;
            font-size: 0.9rem;
            font-family: var(--font-body);
            background: #fffefb;
            color: var(--text);
            transition: border 0.2s;
            resize: vertical;
        }
        .player-section input:focus,
        .player-section textarea:focus,
        .player-section select:focus {
            outline: none;
            border-color: var(--accent);
            box-shadow: 0 0 0 3px rgba(199, 139, 122, 0.1);
        }
        .player-section .form-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 12px;
        }
        @media (max-width: 480px) {
            .player-section .form-row {
                grid-template-columns: 1fr;
            }
        }

        .opening-options {
            display: flex;
            flex-direction: column;
            gap: 8px;
            margin-bottom: 14px;
        }
        .opening-option {
            display: flex;
            align-items: flex-start;
            gap: 10px;
            padding: 12px 14px;
            border: 1px solid var(--border);
            border-radius: 10px;
            cursor: pointer;
            transition: all 0.2s;
            background: #fffefb;
        }
        .opening-option:hover {
            border-color: var(--accent);
