            background: #fef7f4;
            box-shadow: 0 0 0 3px rgba(199, 139, 122, 0.08);
        }
        .opening-option input[type="radio"] {
            accent-color: var(--accent);
            margin-top: 3px;
            flex-shrink: 0;
        }
        .opening-option .opening-text {
