const allCharacters = Object.values(database).flatMap(loc => loc.characters || []);
// --- Music Control ---
const audio = document.getElementById(''bg-music'');
const musicControl = document.getElementById(''music-control'');
const playIcon = document.getElementById(''play-icon'');
const pauseIcon = document.getElementById(''pause-icon'');
let isPlaying = false;
const promise = audio.play();
if (promise !== undefined) {
promise.then(_ => {
isPlaying = true;
updateMusicIcons();
}).catch(error => {
console.log("Autoplay prevented by browser.");
isPlaying = false;
updateMusicIcons();
});
}
function updateMusicIcons() {
playIcon.style.display = isPlaying %s ''none'' : ''block'';
pauseIcon.style.display = isPlaying %s ''block'' : ''none'';
}
musicControl.addEventListener(''click'', () => {
if (isPlaying) {
audio.pause();
} else {
audio.play();
}
isPlaying = !isPlaying;
updateMusicIcons();
});
// --- Modal Control ---
const settingModal = document.getElementById(''setting-modal'');
const gameStartModal = document.getElementById(''game-start-modal'');
function openModal(modal) { modal.style.display = ''block''; }
function closeModal(modal) { modal.style.display = ''none''; }
document.getElementById(''open-setting-modal'').addEventListener(''click'', () => openModal(settingModal));
document.getElementById(''open-game-start-modal'').addEventListener(''click'', () => openModal(gameStartModal));
document.getElementById(''close-setting-modal'').addEventListener(''click'', () => closeModal(settingModal));
document.getElementById(''close-game-start-modal'').addEventListener(''click'', () => closeModal(gameStartModal));
window.addEventListener(''click'', (event) => {
if (event.target == settingModal) closeModal(settingModal);
if (event.target == gameStartModal) closeModal(gameStartModal);
});
// --- Setting Modal Population ---
const settingTabs = document.getElementById(''setting-tabs'');
const settingContent = document.getElementById(''setting-content'');
function generateCharacterCard(char) {
let nameHTML = `<div class="char-name">${char.name}</div>`;
if (char.link) {
nameHTML = `<div class="char-name"><a href="${char.link}" target="_blank">${char.name} →</a></div>`;
}
let statusHTML = '''';
if (char.status) {
statusHTML = `<div class="char-status">${char.status}</div>`;
}
return `
<div class="character-card">
<div class="char-header">
${nameHTML}
${statusHTML}
</div>
<div class="char-info">
<p><strong>归属:</strong> ${char.faction || ''无''}</p>
<p><strong>属性:</strong> ${char.attribute || ''无''}</p>
<p><strong>位置:</strong> ${char.location || ''未知''}</p>
<p>${char.desc || ''''}</p>
</div>
</div>
`;
}
Object.keys(database).forEach((locationName, index) => {
const button = document.createElement(''button'');
button.className = ''tab-button'';
if (index === 0) button.classList.add(''active'');
button.textContent = locationName;
button.dataset.tab = locationName;
settingTabs.appendChild(button);
const content = document.createElement(''div'');
content.className = ''tab-content'';
if (index === 0) content.classList.add(''active'');
content.id = locationName;
const locationData = database[locationName];
let factionsHTML = '''';
if (locationData.factions) {
factionsHTML = Object.entries(locationData.factions).map(([name, desc]) =>
`<li><strong>${name}:</strong> ${desc}</li>`
).join('''');
}
let charactersHTML = '''';
if (locationData.characters) {
charactersHTML = locationData.characters.map(generateCharacterCard).join('''');
}
content.innerHTML = `
<div class="location-intro">
<h3>地点简介</h3>
<p>${locationData.intro}</p>
</div>
${factionsHTML %s `<div class="faction-info"><h3>势力分布</h3><ul>${factionsHTML}</ul></div>` : ''''}
<h3>归属角色</h3>
<div class="character-grid">${charactersHTML}</div>
`;
settingContent.appendChild(content);
});
settingTabs.addEventListener(''click'', (e) => {
if (e.target.classList.contains(''tab-button'')) {
document.querySelectorAll(''#setting-tabs .tab-button'').forEach(btn => btn.classList.remove(''active''));
document.querySelectorAll(''#setting-content .tab-content'').forEach(cont => cont.classList.remove(''active''));
e.target.classList.add(''active'');
document.getElementById(e.target.dataset.tab).classList.add(''active'');
}
});
// --- Game Start Wizard ---
const wizardPages = document.querySelectorAll(''.wizard-page'');
const characterSelect = document.getElementById(''character-select'');
let gameData = {};
allCharacters
.filter(char => char.name && char.name !== ''哲'' && char.name !== ''铃'')
.forEach(char => {
const option = document.createElement(''option'');
option.value = char.name;
option.textContent = `${char.name} (${char.faction})`;
characterSelect.appendChild(option);
});
function goToPage(pageId) {
wizardPages.forEach(page => page.classList.remove(''active''));
const targetPage = document.getElementById(pageId);
if (targetPage) {
targetPage.classList.add(''active'');
} else {
console.error("Wizard page not found:", pageId);
}
}
document.querySelectorAll(''.wizard-container .btn[data-next]'').forEach(button => {
button.addEventListener(''click'', () => {
if(button.dataset.path) gameData.path = button.dataset.path;
if(button.dataset.name) gameData.name = button.dataset.name;
goToPage(button.dataset.next);
});
});
document.getElementById(''confirm-sibling-scenario'').addEventListener(''click'', () => {
const customOpening = document.getElementById(''sibling-custom-scenario'').value.trim();
gameData.opening = customOpening || document.getElementById(''sibling-scenario'').value;
goToPage(''page8'');
});
document.getElementById(''confirm-preset-scenario'').addEventListener(''click'', () => {
gameData.name = document.getElementById(''character-select'').value;
gameData.opening = document.getElementById(''preset-char-opening'').value.trim();
goToPage(''page8'');
});
const customNameInput = document.getElementById(''custom-char-name'');
const easterEggZone = document.getElementById(''easter-egg-zone'');
const achievementPopup = document.getElementById(''achievement-popup'');
const sameNameEggs = {
"Fairy": "服务器繁忙，请稍后再试。", "艾莲": "你看上去不像鲨希人。", "祈礼": "哥们你谁？", "11": "对不起，我不会唱玛卡巴卡",
"橘福福": "这个不好吃。", "妮可": "嘿，这个名字是要花钱的", "铃": "嗯，这个名字应该是我的（委屈）",
"哲": "可能，也许，应该，这是我的名字？", "柳": "我感觉这不太好。", "月城柳": "我感觉这不太好。", "sans": "这是哪？"
};
const specialNameEggs = {
"法厄同": { title: "君临天下", desc: "🏆新成就", tip: "我托马莱伊拉" },
"史蒂夫": { title: "CREEPER%s", desc: "🏆新成就", tip: "太好了，是方块人，我们有救了！" },
"天命人": { title: "不如大圣", desc: "🏆新成就", tip: "这是移动，这是闪避，这是杨戬……" },
"荧": { title: "xx，启动！", desc: "🏆新成就", tip: "你说的对，但是原始是由……" },
"空": { title: "xx，启动！", desc: "🏆新成就", tip: "你说的对，但是原始是由……" },
"空条承太郎": { title: "砸瓦鲁多！", desc: "🏆新成就", tip: "赛高泥high↗铁鸭子哒" },
"DIO": { title: "砸瓦鲁多！", desc: "🏆新成就", tip: "赛高泥high↗铁鸭子哒" },
"迪奥": { title: "砸瓦鲁多！", desc: "🏆新成就", tip: "赛高泥high↗铁鸭子哒" },
};
function showAchievement(egg) {
document.getElementById(''achievement-title'').textContent = egg.title;
document.getElementById(''achievement-desc'').textContent = egg.desc;
document.getElementById(''achievement-tip'').textContent = egg.tip;
achievementPopup.classList.add(''show'');
setTimeout(() => {
achievementPopup.classList.remove(''show'');
}, 4000);
}
document.getElementById(''save-custom-info'').addEventListener(''click'', () => {
const name = customNameInput.value.trim();
easterEggZone.textContent = '''';
if (specialNameEggs[name]) {
showAchievement(specialNameEggs[name]);
}
if (sameNameEggs[name]) {
easterEggZone.textContent = sameNameEggs[name];
customNameInput.value = '''';
setTimeout(() => { easterEggZone.textContent = ''''; }, 2000);
return;
}
if (!name) {
easterEggZone.textContent = "名字是必须的！";
return;
}
gameData.name = name;
gameData.identity = document.getElementById(''custom-char-identity'').value;
gameData.sex = document.getElementById(''custom-char-sex'').value;
gameData.objective = document.getElementById(''custom-char-objective'').value;
gameData.ability = document.getElementById(''custom-char-ability'').value;
gameData.opening = document.getElementById(''custom-char-opening'').value;
goToPage(''page8'');
});
// --- Start Game Logic (No Captcha & Robust Copy) ---
document.getElementById(''start-game-btn'').addEventListener(''click'', (e) => {
e.preventDefault();
proceedStartGame();
});
async function proceedStartGame() {
let outputText = '''';
if (gameData.path === ''sibling'' || gameData.path === ''preset'') {
outputText = `——user——\nRole: ${gameData.name}\nOpening Message: ${gameData.opening}\n——end——`;
} else {
outputText = `——user——\nname: ${gameData.name}\nidentity: ${gameData.identity}\nsex: ${gameData.sex}\nobjective: ${gameData.objective}\nAbility: ${gameData.ability}\nOpening message: ${gameData.opening}\n——end——`;
}
// Native copy method with fallback for restricted environments
let copySuccess = false;
try {
// Try Modern API first
await navigator.clipboard.writeText(outputText);
copySuccess = true;
} catch (err) {
console.warn(''Clipboard API failed, trying execCommand fallback:'', err);
// Fallback: execCommand
try {
const textArea = document.createElement("textarea");
textArea.value = outputText;
// Ensure textarea is not visible but part of DOM
textArea.style.position = "fixed";
textArea.style.left = "-9999px";
textArea.style.top = "0";
document.body.appendChild(textArea);
textArea.focus();
textArea.select();
const successful = document.execCommand(''copy'');
document.body.removeChild(textArea);
if (successful) copySuccess = true;
} catch (err2) {
console.error(''All copy methods failed:'', err2);
}
}
if (copySuccess) {
showToast();
closeModal(gameStartModal);
setTimeout(() => goToPage(''page1''), 500);
gameData = {};
} else {
alert(''复制失败！请手动复制：\n\n'' + outputText);
}
}
function showToast() {
const toast = document.getElementById(''clipboard-toast'');
toast.classList.add(''show'');
setTimeout(() => { toast.classList.remove(''show''); }, 3000);
}
});
</script>
</body>
