    ];
    const femaleAppearances = [
        ''白衣飘飘，宛若谪仙'', ''红裙如火，妖娆妩媚'', ''素衣素颜，清丽脱俗'', ''紫衣高贵，倾国倾城'',
        ''青衣素雅，温婉可人'', ''黑衣冷艳，生人勿近'', ''罗裙翩翩，婀娜多姿'', ''道袍加身，出尘绝世'',
        ''明眸皓齿，肤若凝脂'', ''娇小玲珑，楚楚动人'', ''身姿曼妙，风情万种'', ''冰肌玉骨，不染纤尘'',
        ''朱唇皓齿，美艳不可方物'', ''眉如远山，眸似秋水'', ''云鬓堆雪，容华绝代'', ''长发及腰，温柔如水'',
        ''相貌平平，难入法眼'', ''面容冷峻，拒人千里'', ''眉心花钿，异域风情'', ''银发碧眸，诡异绝美''
    ];
    const origins = [
        ''边陲小城一介凡人，家境贫寒'', ''修仙世家旁系子弟，不受重视'', ''名门大派真传弟子，天资聪颖'',
        ''散修之后，自小孤苦无依'', ''凡俗皇族血脉，享尽荣华'', ''妖兽化形，初通人性'',
        ''魔门余孽，背负血仇'', ''古老氏族嫡系传人，底蕴深厚'', ''偏远山村樵夫之子'',
        ''江湖帮派少主，侠肝胆'', ''商贾之家，富甲一方'', ''书香门第，诗书传家'',
        ''医道世家，悬壶济世'', ''工匠之后，巧夺天工'', ''军伍之家，忠义传承'',
        ''乞儿出身，饱经风霜'', ''孤儿，为宗门所救'', ''前世仙人转世，记忆未醒'',
        ''上古遗族后裔，血脉稀薄'', ''夺舍重生，借尸还魂''
    ];
    const realmAgeRanges = {
        ''炼气'': { min: 16, max: 150 },
        ''筑基'': { min: 20, max: 300 },
        ''金丹'': { min: 80, max: 800 },
        ''元婴'': { min: 200, max: 2000 },
        ''化神'': { min: 600, max: 5000 },
        ''返虚'': { min: 1500, max: 10000 },
        ''合体'': { min: 3000, max: 20000 },
        ''大乘'': { min: 8000, max: 50000 }
    };
    const realms = [''炼气'', ''筑基'', ''金丹'', ''元婴'', ''化神'', ''返虚'', ''合体'', ''大乘''];
    const realmLevels = [''初期'',''初期巅峰'',''中期'',''中期巅峰'',''后期'',''后期巅峰'',''大圆满''];
    const races = [''人族'', ''妖族'', ''魔族'', ''龙族'', ''仙族'', ''灵族'', ''鬼族''];
    const form = document.getElementById(''character-form'');
    const inputs = form.querySelectorAll(''input[type="text"], textarea'');
    const profileDiv = document.getElementById(''character-profile'');
    const copyBtn = document.getElementById(''btn-copy'');
    const selectionDiv = document.getElementById(''selection-display'');
    const charName = document.getElementById(''char-name'');
    const charGender = document.getElementById(''char-gender'');
    const charRace = document.getElementById(''char-race'');
    const charAge = document.getElementById(''char-age'');
    const charPersonality = document.getElementById(''char-personality'');
    const charAppearance = document.getElementById(''char-appearance'');
    const charRealm = document.getElementById(''char-realm'');
    const charOrigin = document.getElementById(''char-origin'');
    const charSpiritRoot = document.getElementById(''char-spirit-root'');
    const charSect = document.getElementById(''char-sect'');
    const charTechnique = document.getElementById(''char-technique'');
    function randomChoice(arr) {
        return arr[Math.floor(Math.random() * arr.length)];
    }
    function randomInt(min, max) {
        return Math.floor(Math.random() * (max - min + 1)) + min;
    }
    window.randomGender = function() {
        if (isLocked(''char-gender'')) return;
        const gender = randomChoice([''男'', ''女'']);
        document.getElementById(''char-gender'').value = gender;
        updateProfile();
    }
    window.randomName = function() {
        if (isLocked(''char-name'')) return;
        const gender = document.getElementById(''char-gender'').value || randomChoice([''男'', ''女'']);
        const surname = randomChoice(surnames);
        const givenName = gender === ''女'' %s randomChoice(femaleNames) : randomChoice(maleNames);
        document.getElementById(''char-name'').value = surname + givenName;
        updateProfile();
    }
    window.randomPersonality = function() {
        if (isLocked(''char-personality'')) return;
        document.getElementById(''char-personality'').value = randomChoice(personalities);
        updateProfile();
    }
    window.randomAppearance = function() {
        if (isLocked(''char-appearance'')) return;
        const gender = document.getElementById(''char-gender'').value || ''男'';
        if (gender === ''女'') {
            document.getElementById(''char-appearance'').value = randomChoice(femaleAppearances);
        } else {
            document.getElementById(''char-appearance'').value = randomChoice(maleAppearances);
        }
        updateProfile();
    }
    window.randomOrigin = function() {
        if (isLocked(''char-origin'')) return;
        document.getElementById(''char-origin'').value = randomChoice(origins);
        updateProfile();
    }
    function randomRealm() {
        const realm = randomChoice(realms);
        const level = randomChoice(realmLevels);
        return `${realm}${level}`;
    }
function getAgeForRealm(realmStr) {
    let baseRealm = '''';
    for (const r of realms) {
        if (realmStr.startsWith(r)) {
            baseRealm = r;
            break; 
        }
    }
    const range = realmAgeRanges[baseRealm] || { min: 16, max: 150 };
    return randomInt(range.min, range.max);
}
    function getRealmsForAge(age) {
        const possibleRealms = [];
        for (const realm in realmAgeRanges) {
            const range = realmAgeRanges[realm];
            if (age >= range.min && age <= range.max) {
                possibleRealms.push(realm);
            }
        }
        if (possibleRealms.length === 0) {
            return [''练气''];
        }
        return possibleRealms;
    }
    function randomAllCharacter() {
        let gender = charGender.value;
        if (!isLocked(''char-gender'')) {
            gender = randomChoice([''男'', ''女'']);
            charGender.value = gender;
        }
        if (!isLocked(''char-name'')) {
            const surname = randomChoice(surnames);
            const givenName = gender === ''女'' %s randomChoice(femaleNames) : randomChoice(maleNames);
            charName.value = surname + givenName;
        }
        if (!isLocked(''char-race'')) charRace.value = randomChoice(races);
        if (!isLocked(''char-personality'')) charPersonality.value = randomChoice(personalities);
        if (!isLocked(''char-appearance'')) charAppearance.value = gender === ''女'' %s randomChoice(femaleAppearances) : randomChoice(maleAppearances);
        if (!isLocked(''char-origin'')) charOrigin.value = randomChoice(origins);
                // --- 这是新的逻辑代码 ---
        const ageLocked = isLocked(''char-age'');
        const realmLocked = isLocked(''char-realm'');
        let finalRealm = charRealm.value;
        let finalAge = charAge.value;
        if (ageLocked && !realmLocked) {
            const currentAge = parseInt(charAge.value) || 16; // 获取锁定的年龄
            const possibleRealms = getRealmsForAge(currentAge); // 获取该年龄可能的境界
            const chosenRealmBase = randomChoice(possibleRealms); // 从可能列表中随机选一个
            finalRealm = `${chosenRealmBase}${randomChoice(realmLevels)}`; // 组合成完整境界
            charRealm.value = finalRealm;
        } else if (!ageLocked && realmLocked) {
            finalAge = getAgeForRealm(finalRealm);
            charAge.value = finalAge;
        } else if (!ageLocked && !realmLocked) {
            finalRealm = randomRealm();
            finalAge = getAgeForRealm(finalRealm);
            charRealm.value = finalRealm;
            charAge.value = finalAge;
        }
        if (!isLocked(''char-spirit-root'')) {
            const root = randomChoice(spiritRoots);
            charSpiritRoot.value = `${root.name} (${root.grade}) - 效果：${root.effect}`;
        }
        if (!isLocked(''char-sect'')) {
            const sect = randomChoice(sects);
            charSect.value = `${sect.name} (${sect.level})`;
            if (!isLocked(''char-technique'')) {
                const techInfo = techniques.find(t => t.name === sect.default_tech.split(''('')[0].trim()) || randomChoice(techniques);
                charTechnique.value = `${techInfo.name} (${techInfo.grade}) - 效果：${techInfo.info}`;
            }
        } else if (!isLocked(''char-technique'')) {
            const techInfo = randomChoice(techniques);
            charTechnique.value = `${techInfo.name} (${techInfo.grade}) - 效果：${techInfo.info}`;
        }
        selectionDiv.innerHTML = ''''; // 清空选择区
        updateProfile(); // 最后统一更新
    } 
    function isLocked(fieldId) {
        const lockBtn = document.querySelector(`.lock-btn[data-field-id="${fieldId}"]`);
        return lockBtn && lockBtn.classList.contains(''locked'');
    }
    function updateProfile() {
        let profileText = `
【名号】：${charName.value || ''待定''}
【性别】：${charGender.value || ''待定''}
【种族】：${charRace.value || ''待定''}
【年龄】：${charAge.value || ''待定''}
【心性】：${charPersonality.value || ''待定''}
【样貌】：${charAppearance.value || ''待定''}
【境界】：${charRealm.value || ''炼气一层''}
【出身】：${charOrigin.value || ''待定''}
【灵根】：${charSpiritRoot.value || ''待定''}
【宗门】：${charSect.value || ''待定''}
【主修功法】：${charTechnique.value || ''待定''}
        `;
        profileDiv.textContent = profileText.trim();
    }
    function createCard(item, type) {
        const card = document.createElement(''div'');
        card.className = `card ${item.tierClass}`;
        const scrollOptions = { behavior: ''smooth'', block: ''center'' };
        if (type === ''root'') {
            card.innerHTML = `<h5>${item.name} <span class="grade">(${item.grade})</span></h5><p>${item.effect}</p>`;
            card.onclick = () => {
                if (isLocked(''char-spirit-root'')) return;
                charSpiritRoot.value = `${item.name} (${item.grade}) - 效果：${item.effect}`;
                selectionDiv.innerHTML = '''';
                updateProfile();
                charSpiritRoot.scrollIntoView(scrollOptions);
            };
        } else if (type === ''sect'') {
            card.innerHTML = `<h5>${item.name} <span class="level">(${item.level})</span></h5><p>${item.info}</p><p class="info">预设功法: ${item.default_tech}</p>`;
            card.onclick = () => {
                if (isLocked(''char-sect'')) return;
                charSect.value = `${item.name} (${item.level})`;
                if (!isLocked(''char-technique'')) {
                    const techInfo = techniques.find(t => t.name === item.default_tech.split(''('')[0].trim()) || { grade: ''未知'', info: '''' };
                    charTechnique.value = `${techInfo.name} (${techInfo.grade}) - 效果：${techInfo.info}`;
                }
                selectionDiv.innerHTML = '''';
                updateProfile();
                charSect.scrollIntoView(scrollOptions);
            };
        } else if (type === ''tech'') {
            card.innerHTML = `<h5>${item.name} <span class="grade">(${item.grade})</span></h5><p>${item.info}</p>`;
            card.onclick = () => {
                if (isLocked(''char-technique'')) return;
                charTechnique.value = `${item.name} (${item.grade}) - 效果：${item.info}`;
                selectionDiv.innerHTML = '''';
                updateProfile();
                charTechnique.scrollIntoView(scrollOptions);
            };
        }
        return card;
    }
    inputs.forEach(input => input.addEventListener(''input'', updateProfile));
    document.querySelectorAll(''.lock-btn'').forEach(btn => {
        btn.addEventListener(''click'', () => {
            btn.classList.toggle(''locked'');
            const isNowLocked = btn.classList.contains(''locked'');
            btn.textContent = isNowLocked %s ''🔒'' : ''🔓'';
            const randomBtn = btn.closest(''.input-container'').querySelector(''.random-btn'');
            if (randomBtn) {
                randomBtn.disabled = isNowLocked;
            }
        });
    });
    document.getElementById(''btn-draw-root'').addEventListener(''click'', () => {
        if (isLocked(''char-spirit-root'')) return;
        selectionDiv.innerHTML = ''<h4 class="selection-title">请从以下九项天命中择一：</h4>'';
        const shuffled = [...spiritRoots].sort(() => 0.5 - Math.random());
        shuffled.slice(0, 9).forEach(root => selectionDiv.appendChild(createCard(root, ''root'')));
        selectionDiv.scrollIntoView({ behavior: ''smooth'', block: ''start'' });
    });
    document.getElementById(''btn-select-sect'').addEventListener(''click'', () => {
        if (isLocked(''char-sect'')) return;
        selectionDiv.innerHTML = ''<h4 class="selection-title">请从以下九大道统中择一：</h4>'';
        const shuffled = [...sects].sort(() => 0.5 - Math.random());
        shuffled.slice(0, 9).forEach(sect => selectionDiv.appendChild(createCard(sect, ''sect'')));
        selectionDiv.scrollIntoView({ behavior: ''smooth'', block: ''start'' });
    });
    document.getElementById(''btn-select-tech'').addEventListener(''click'', () => {
        if (isLocked(''char-technique'')) return;
        selectionDiv.innerHTML = ''<h4 class="selection-title">请从以下九大法门中择一：</h4>'';
        const shuffled = [...techniques].sort(() => 0.5 - Math.random());
        shuffled.slice(0, 9).forEach(tech => selectionDiv.appendChild(createCard(tech, ''tech'')));
        selectionDiv.scrollIntoView({ behavior: ''smooth'', block: ''start'' });
    });
    document.getElementById(''btn-random-all'').addEventListener(''click'', randomAllCharacter);
    copyBtn.addEventListener(''click'', () => {
        navigator.clipboard.writeText(profileDiv.textContent).then(() => {
            copyBtn.textContent = ''【拓印成功！】'';
            setTimeout(() => {
                copyBtn.textContent = ''【一键拓印档案】'';
            }, 2000);
        }).catch(err => {
            console.error(''无法复制: '', err);
            copyBtn.textContent = ''【拓印失败】'';
        });
    });
    updateProfile();
});
</script>
</body>
</html>', 'R18', '2026-10-11 11:21:47', '2026-10-11 11:21:47', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_rebellious_stepsister', '爹妈将管教不了的妹妹交给了你', '家庭 · 叛逆管教', '👧', '爹妈将管教不了的妹妹交给了你', '家庭 · 叛逆管教', '👧', '#ff1493', 'linear-gradient(135deg, #ff1493 0%, #c71585 100%)', '{"title": "爹妈将管教不了的妹妹交给了你", "desc": "你的家庭是一个重组家庭。近期，你的继妹夏茉迎来了极其严重的青春期叛逆，染发抽烟甚至对父母满嘴恶言。极度失望的父母断绝了她的生活费并打包送上了高铁塞到你家，给你下了死命令：不管用什么手段，替我们狠狠管教她！", "bg_image": "https://catai.wiki/2d0465c2-18a6-48c4-3d07-c565e7c2a100/cover", "opening_options": ["【玄关对峙·立下规矩】：“夏茉嚼着口香糖，戴着耳机将行李箱往你脚边一踢，伸手找你要钱点外卖。你面色冷淡地打掉她的手……”", "【没收手机·断网制裁】：“进门第一件事，你要求她交出手机并拔掉WiFi电源，她瞬间像被踩了尾巴的小猫一样尖叫起来……”", "【冷眼旁观·任性碰壁】：“你没有多说什么，自顾自做饭吃晚餐，看她能在又饿又没钱的情况下硬撑到几点……”"]}', '[{"name": "夏茉", "role": "继妹 (16岁 / 地雷系穿搭 / 叛逆嘴臭 / 初恋脸)", "desc": "重组家庭的继妹。表面嚣张跋扈、满嘴网络抽象梗，把你当成免费佣人和老登；内心极度敏感脆弱、渴望被在意，防备心极强。"}, {"name": "哥哥 (玩家)", "role": "管教者与监护人", "desc": "独自居住的大学毕业生/青年，受父母之托对夏茉进行生活上的管教与心理上的引导。"}]', '[{"title": "单身公寓门厅 · 杂乱的玄关前", "desc": "狭窄但整洁的公寓门口，弥漫着少女身上淡淡的电子烟香气。"}]', '{"dialogue_style": "张力十足的生活化情感博弈，生动的神态捕捉与心理推拉", "format": "AI风月标准双栏规范及.custom-ui样式"}', '{"index": 1, "isUser": false, "scene": "单身公寓门厅 · 杂乱的玄关前", "story": "<tl>📅时间：周五傍晚 18:00 | 🌏地点：单身公寓门厅 | 🚪氛围：针锋相对</tl>\n\n<article>\n<p>砰的一声，门铃响得急促而暴躁。</p>\n\n<p>你拉开防盗门，一股混杂着劣质草莓味电子烟与少女微弱香水的气味迎面扑来。站在门外台阶上的，正是那个让全家头疼欲裂的继妹——夏茉。</p>\n\n<p>她头戴一副硕大的粉黑配色降噪耳机，身上套着一件快要盖过百褶裙的宽大破洞T恤，细瘦白皙的长腿上踩着厚底松糕鞋。她嘴里正漫不经心地嚼着口香糖，鼻腔里哼出一声冷气，抬起脚把那个沉重的行李箱直接踢到了你的鞋柜边上。</p>\n\n<p><w>“看什么看啊虾头男？”</w>夏茉摘下一侧耳机挂在脖子上，抱着双臂斜眼上下打量着你，语气刻薄又带着挑衅，<w>“别以为那两个老登把你搬出来本小姐就会怕你。赶紧爆点金币给我点个外卖，本小姐坐了一下午高铁快饿死了，别逼我急眼啊！”</w></p>\n</article>", "branches": [{"tag": "A", "title": "立下规矩", "desc": "严厉制止她的无礼行为，勒令收起香烟与耳机"}, {"tag": "B", "title": "经济制裁", "desc": "明确告知这里由你做主，交出手机才给饭吃"}, {"tag": "C", "title": "冷漠无视", "desc": "无视她的叫嚣，关上房门看她能嘴硬多久"}]}', '', '<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>继妹管教计划</title>
<style>
:root {--primary-pink:#ff1493;--dark-pink:#c71585;--bg-black:#0f0f14;--card-bg:#1a1a24;--text-main:#e0e0e0;--text-muted:#888899;--border-color:#333344;}
* {box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent;}
body {font-family:''Microsoft YaHei'', sans-serif;background-color:var(--bg-black);color:var(--text-main);line-height:1.6;font-size:15px;background-image:linear-gradient(45deg, rgba(255,20,147,0.03) 25%, transparent 25%, transparent 75%, rgba(255,20,147,0.03) 75%, rgba(255,20,147,0.03)), linear-gradient(45deg, rgba(255,20,147,0.03) 25%, transparent 25%, transparent 75%, rgba(255,20,147,0.03) 75%, rgba(255,20,147,0.03));background-size:40px 40px;background-position:0 0, 20px 20px;}
.container {max-width:700px;margin:0 auto;padding:15px;min-height:100vh;}
.header {text-align:center;padding:30px 0 20px;border-bottom:2px dashed var(--primary-pink);margin-bottom:25px;}
.title {font-size:2.2em;color:var(--primary-pink);font-weight:900;text-shadow:2px 2px 5px rgba(255,20,147,0.4);letter-spacing:3px;margin-bottom:10px;text-transform:uppercase;}
.subtitle {font-size:1em;color:var(--text-muted);font-style:italic;}
.card {background:var(--card-bg);border:1px solid var(--border-color);border-left:4px solid var(--primary-pink);border-radius:8px;padding:20px;margin-bottom:20px;box-shadow:0 4px 15px rgba(0,0,0,0.5);position:relative;overflow:hidden;}
.card::before {content:''🖤'';position:absolute;top:10px;right:15px;font-size:1.5em;opacity:0.2;}
.card-title {color:var(--primary-pink);font-size:1.3em;margin-bottom:15px;display:flex;align-items:center;font-weight:bold;}
.card-title::before {content:'''';display:inline-block;width:8px;height:8px;background:var(--primary-pink);border-radius:50%;margin-right:10px;}
.tags-container {display:flex;flex-wrap:wrap;gap:8px;margin-bottom:15px;}
.tag {background:rgba(255,20,147,0.1);color:var(--primary-pink);border:1px solid rgba(255,20,147,0.3);padding:4px 10px;border-radius:15px;font-size:0.85em;}
.desc-text {margin-bottom:10px;color:#ccc;}
.highlight {color:var(--primary-pink);font-weight:bold;}
.warning-box {background:rgba(255,0,0,0.1);border:1px solid #ff4444;border-left:4px solid #ff4444;padding:15px;border-radius:6px;margin-top:15px;}
.warning-title {color:#ff4444;font-weight:bold;margin-bottom:8px;display:flex;align-items:center;}
.warning-title::before {content:''⚠️'';margin-right:5px;}
.warning-text {font-size:0.9em;color:#ffaaaa;margin-bottom:5px;}
details {background:#111118;border:1px solid var(--border-color);border-radius:6px;margin-top:15px;overflow:hidden;}
summary {padding:12px 15px;font-weight:bold;color:var(--primary-pink);cursor:pointer;user-select:none;display:flex;align-items:center;background:rgba(255,20,147,0.05);}
summary::before {content:''▶'';display:inline-block;margin-right:10px;font-size:0.8em;transition:transform 0.2s;}
details[open] summary::before {transform:rotate(90deg);}
.details-content {padding:15px;font-size:0.95em;border-top:1px solid var(--border-color);color:#ffb3c1;}
.form-group {margin-bottom:20px;}
.form-label {display:block;font-weight:bold;color:var(--text-main);margin-bottom:8px;font-size:1em;}
.form-hint {font-size:0.8em;color:var(--text-muted);font-weight:normal;margin-left:5px;}
input[type="text"], textarea {width:100%;padding:12px;border:1px solid var(--border-color);background:#111118;color:var(--text-main);font-family:inherit;font-size:0.95em;border-radius:4px;transition:all 0.3s;}
input[type="text"]:focus, textarea:focus {outline:none;border-color:var(--primary-pink);box-shadow:0 0 8px rgba(255,20,147,0.3);}
textarea {height:80px;resize:vertical;}
.btn-submit {display:block;width:100%;padding:15px;background:transparent;color:var(--primary-pink);font-size:1.2em;font-weight:bold;border:2px solid var(--primary-pink);border-radius:6px;cursor:pointer;margin-top:30px;transition:all 0.3s;text-transform:uppercase;letter-spacing:2px;}
.btn-submit:hover {background:var(--primary-pink);color:#fff;box-shadow:0 0 15px rgba(255,20,147,0.5);}
#result-box {display:none;margin-top:25px;animation:fadeIn 0.5s;}
@keyframes fadeIn {from{opacity:0;transform:translateY(10px);} to{opacity:1;transform:translateY(0);}}
#output-text {width:100%;height:220px;background:#0a0a0d;color:#ffb3c1;border:1px dashed var(--primary-pink);padding:15px;font-family:monospace;font-size:0.95em;white-space:pre-wrap;resize:none;border-radius:6px;}
.footer {text-align:center;margin-top:40px;padding:20px 0;font-size:0.85em;color:var(--text-muted);border-top:1px solid var(--border-color);}
</style>
</head>
<body>
<div class="container">
<div class="header">
<h1 class="title">继妹管教计划</h1>
<div class="subtitle">"别逼我急眼啊，老登！" —— 绝对服从的调教之路</div>
</div>
<div class="card">
<div class="card-title">👧 目标档案：夏茉 (你的继妹)</div>
<div class="tags-container">
<span class="tag">地雷系亚逼</span>
<span class="tag">嚣张嘴臭</span>
<span class="tag">初恋脸</span>
<span class="tag">158cm/42kg</span>
<span class="tag">B罩杯微乳</span>
<span class="tag">降噪耳机</span>
<span class="tag">绝对处女</span>
</div>
<p class="desc-text">表面嚣张跋扈，把你当“爆金币的老登”和“免费佣人”。日常大码T恤配热裤/百褶裙、破洞网袜、厚底鞋，戴Choker。私下喜欢穿带骷髅或蕾丝元素的黑色内衣装成熟。</p>
<details>
<summary>💬 听听她怎么说</summary>
<div class="details-content">
「看什么看啊虾头男？尊嘟假嘟，你不会真以为老登把你当盘菜了吧？赶紧爆点金币给本小姐点个外卖，别逼我急眼啊，急了急了急了！」
</div>
</details>
</div>
<div class="card">
<div class="card-title">⚙️ 核心玩法与排雷指南</div>
<p class="desc-text" style="font-size:0.9em;color:var(--text-muted);">本作是高难度、慢热型、重惩罚的养成管教文字游戏。切勿开局硬上。</p>
<ul style="padding-left:20px;margin-bottom:15px;color:#ccc;font-size:0.95em;">
<li style="margin-bottom:8px;"><strong>管教与恩威并施：</strong>通过物理/心理管教(没收手机、断网、经济制裁等)打压【叛逆值】。破防哭泣时适时关怀，提升【服从值】和【依赖值】。</li>
<li style="margin-bottom:8px;"><strong>感官体验：</strong>高频描写气味(劣质电子烟混少女奶香)、白眼、耳机漏音等五感细节。服从值达标后描写极度直白肉欲。</li>
</ul>
<div class="warning-box">
<div class="warning-title">绝对的数值防线 (违反即GameOver)</div>
<div class="warning-text">• <strong>服从值 < 30</strong>：极度抗拒亲密接触。强行猥亵会报警/咬人。</div>
<div class="warning-text">• <strong>服从值 < 60</strong>：拒绝性交。执意强迫/下药将触发天降正义。</div>
</div>
</div>
<div class="card">
<div class="card-title">📝 建立你的威严 (开局设定)</div>
<div class="form-group">
<label class="form-label">1. 你的姓名 <span class="form-hint">(前期她多半叫你老登/虾头男)</span></label>
<input type="text" id="p-name" placeholder="如：林渊" value="林渊">
</div>
<div class="form-group">
<label class="form-label">2. 你的性格 <span class="form-hint">(影响管教手段)</span></label>
<input type="text" id="p-persona" placeholder="如：冷酷严厉的霸总 / 腹黑笑面虎..." value="冷酷严厉，底线极高，不容挑衅">
</div>
<div class="form-group">
<label class="form-label">3. 你的外貌 <span class="form-hint">(建立压迫感)</span></label>
<input type="text" id="p-appearance" placeholder="如：身高185，常年穿白衬衫，戴金丝眼镜..." value="身高185，常年穿黑衬衫，身形挺拔且具有压迫感">
</div>
<div class="form-group">
<label class="form-label">4. 你的肉棒 <span class="form-hint">(后期成人内容设定)</span></label>
<input type="text" id="p-dick" placeholder="如：18cm，粗壮，青筋暴起..." value="18cm，极其粗壮，青筋暴起，龟头巨大">
</div>
<div class="form-group">
<label class="form-label">5. 初始管教道具 <span class="form-hint">(你手头的筹码)</span></label>
<input type="text" id="p-item" placeholder="如：戒尺、她的生活费银行卡、备用钥匙..." value="她的生活费银行卡、家里的WiFi路由器控制权">
</div>
<div class="form-group">
<label class="form-label">6. 开场动作/场景 <span class="form-hint">(至关重要)</span></label>
<textarea id="p-scene" placeholder="描写你想开始的画面...">她刚提着行李箱被父母扔到我家门口，正嚼着口香糖，戴着耳机对我翻白眼，把行李箱往我脚边一踢，伸手找我要钱点外卖。而我决定给她立下第一条规矩……</textarea>
</div>
<button class="btn-submit" id="btn-gen">生成设定 · 开始管教</button>
<div id="result-box">
<textarea id="output-text" readonly></textarea>
</div>
</div>
<div class="footer">
©继妹管教计划<br>
</div>
</div>
<script>
document.getElementById(''btn-gen'').addEventListener(''click'', function() {
const name = document.getElementById(''p-name'').value || ''未命名'';
const persona = document.getElementById(''p-persona'').value || ''未设定'';
const appearance = document.getElementById(''p-appearance'').value || ''未设定'';
const dick = document.getElementById(''p-dick'').value || ''未设定'';
const item = document.getElementById(''p-item'').value || ''无'';
const scene = document.getElementById(''p-scene'').value || ''未设定'';
const output = `【管教者设定已确认】
姓名：${name}
性格：${persona}
外貌：${appearance}
肉棒：${dick}
初始道具：${item}
开场场景：${scene}
[系统提示：设定已锁定。地雷系继妹夏茉正站在你面前，空气中弥漫着劣质电子烟味。]
[初始数值生成中...]
👿叛逆值: 90 | 🛐服从值: 0 | 🥺依赖值: 5
[警告：当前服从值极低，严禁任何强迫性行为！请从基础管教开始。]
[请发送你的第一个行动指令...]`;
const resBox = document.getElementById(''result-box'');
const outText = document.getElementById(''output-text'');
resBox.style.display = ''block'';
outText.value = output;
outText.select();
try {
document.execCommand(''copy'');
this.innerText = ''设定已复制 · 准备接入'';
this.style.background = ''var(--primary-pink)'';
this.style.color = ''#fff'';
setTimeout(() => { 
this.innerText = ''生成设定 · 开始管教'';
this.style.background = ''transparent'';
this.style.color = ''var(--primary-pink)'';
}, 3000);
} catch(err) {
this.innerText = ''生成成功，请手动复制'';
}
});
</script>
</body>
</html>', '家庭情感', '2026-10-05 14:50:00', '2026-10-05 14:50:00', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('5119f313-38ab-4929-a614-9a242de30166', '原神大世界', '已破甲 · 角色扮演', '📖', '原神大世界', '欢迎来到提瓦特，一个不再受脚本束缚的真实世界！在这里，《原神》的经典世界观被赋予生命，每一个元素、每一段历史都栩栩如生。你不再是旁观者，而是提瓦特命运的“变数”', '📖', '#3b82f6', 'linear-gradient(135deg, #3b82f6 0%, #6366f1 100%)', '{"title": "原神大世界", "desc": "欢迎来到提瓦特，一个不再受脚本束缚的真实世界！在这里，《原神》的经典世界观被赋予生命，每一个元素、每一段历史都栩栩如生。你不再是旁观者，而是提瓦特命运的“变数”——你的选择、行动乃至存在本身，都将以真实世界的因果逻辑，自然而合理地塑造这个世界的未来。是附身名流，还是白手起家？是介入历史，还是开创新篇？提瓦特将因你而生，因你而变，创造独一无二的生命轨迹。准备好，亲手书写你的提瓦特史诗了吗？", "bg_image": "https://catai.wiki/09a40f4e-cabb-4921-1e01-17e4f92b4b00/bg"}', '[]', '[]', '{}', '[{"isUser": false, "story": "【序章 · 初临】\n\n欢迎来到提瓦特，一个不再受脚本束缚的真实世界！在这里，《原神》的经典世界观被赋予生命，每一个元素、每一段历史都栩栩如生。你不再是旁观者，而是提瓦特命运的“变数”——你的选择、行动乃至存在本身，都将以真实世界的因果逻辑，自然而合理地塑造这个世界的未来。是附身名流，还是白手起家？是介入历史，还是开创新篇？提瓦特将因你而生，因你而变，创造独一无二的生命轨迹。准备好，亲手书写你的提瓦特史诗了吗？\n\n阳光穿透微隙，周围的喧嚣渐渐清晰。你迈出脚步，开启了在这片天地间的全新篇章……", "branches": [{"tag": "A", "title": "环顾四周观察当前局势", "desc": "环顾四周观察当前局势"}, {"tag": "B", "title": "顺应眼前的指引前行", "desc": "顺应眼前的指引前行"}]}]', '/* 1. 整体字体与基础背景优化 */
body {
    background-color: #fafaf5; /* 更明亮纯色背景，减少暗色 */
    font-family: "HYWenHei", "Microsoft YaHei", sans-serif !important; /* 统一字体 */
    color: #333; /* 全局字体颜色增强可读性 */
}

/* 2. 旅行者对话框 - 白金简洁风格（优化显示效果） */
div.relative.inline-block.px-4.py-3.max-w-full.text-gray-900.bg-gray-100\/90.rounded-xl.text-sm {
    background: rgba(255, 255, 255, 0.95) !important; /* 让背景更接近纯白，减少半透明感 */
    color: #2e2e2e !important; /* 改用更深的文字颜色，增强对比 */
    border: 2px solid #d4b16a !important; /* 更饱和的金色边框，符合原神风格 */
    border-radius: 15px 2px 15px 15px !important;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.15) !important; /* 改善阴影，使其更柔和 */
    margin-left: auto;
    display: table;
    font-weight: bold; /* 提升字体清晰度和重要性 */
}

/* 3. AI回复框 - 派蒙/剧情对话风格（优化背景和字体明晰度） */
div.relative.inline-block.px-4.py-3.w-full.bg-gray-100\/90.rounded-xl.text-sm.text-gray-900 {
