<script>
function generateConfig() {
    const configData = {
        name: document.getElementById(''name'').value,
        gender: document.getElementById(''gender'').value,
        vision: document.getElementById(''vision'').value,
        appearance: document.getElementById(''appearance'').value,
        race: document.getElementById(''race'').value,
        background: document.getElementById(''background'').value,
        extra: document.getElementById(''extra'').value
    };
    let previewText = `我的化身设定：
- 姓名：${configData.name || ''未定''}
- 性别：${configData.gender}
- 神之眼/力量：${configData.vision}
- 种族：${configData.race}
- 身份背景：${configData.background}
- 外貌：${configData.appearance || ''未描述''}
- 其他设定：${configData.extra || ''无''}`;
    document.getElementById(''previewContent'').innerText = previewText;
    document.getElementById(''previewModal'').style.display = ''block'';
}

function copyFinalConfig() {
    const content = document.getElementById(''previewContent'').innerText;
    
    // 创建一个临时的 textarea 元素
    const textArea = document.createElement(''textarea'');
    textArea.value = content;
    
    // 把它设置到屏幕外，防止干扰页面
    textArea.style.position = ''fixed'';
    textArea.style.top = ''-9999px'';
    textArea.style.left = ''-9999px'';
    
    // 将它添加到页面中
    document.body.appendChild(textArea);
    
    // 选中 textarea 的内容
    textArea.select();
    
    try {
        // 执行复制命令
        const successful = document.execCommand(''copy'');
