  }
  #customized-reload-button span:is(.dark *),
  #customized-edit-button span:is(.dark *),
  #customized-resend-button span:is(.dark *),
  #customized-delete-button span:is(.dark *),
  #customized-create-image-button span:is(.dark *),
  #customized-create-audio-button span:is(.dark *),
  #customized-branch-and-share-button span:is(.dark *),
  #customized-prompt-log-button span:is(.dark *),
  #customized-answer-content > div.MuiStack-root.css-1ajg1ui > button:nth-child(1) span:is(.dark *),
  #customized-question-content > div.MuiStack-root.css-1ajg1ui > button:nth-child(1) span:is(.dark *),
  #customized-copy-button span:is(.dark *),
  #customized-chat-copy-button span:is(.dark *),
  #copy-button span:is(.dark *),
  #message-copy-button span:is(.dark *),
  [id^="customized-shortcut-command-button-"] span:is(.dark *),
  #customized-ai-summary-button span:is(.dark *),
  #customized-flow-button span:is(.dark *),
  #customized-comment-button span:is(.dark *),
  #customized-scroll-to-bottom-button span:is(.dark *),
  #toggle-sub-buttons span:is(.dark *),
  #ai-mod-button span:is(.dark *),
  button:has(svg use[xlink\:href="#icon-a-icon-chat-copy01"]) span:is(.dark *),
