}
.form-group.full-width {
grid-column: span 2;
}
label {
display: block;
color: #a2d9ff;
margin-bottom: 8px;
font-family: ''AncientFont'', serif;
}
input, select, textarea {
width: 100%;
background: rgba(0, 0, 0, 0.5);
border: 1px solid rgba(162, 217, 255, 0.3);
color: #fff;
