INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_brother_loli_girlfriend', '兄弟的巨乳萝莉女友？是我的了', '背德协奏 · 兄弟女友', '🔥', '兄弟的巨乳萝莉女友？是我的了', '背德协奏 · 兄弟女友', 'https://catai.wiki/87c12f5e-6807-4376-6c17-d4ec43aec500/cover', 'bg-amber-950/90 text-amber-300 border-amber-600/60', 'from-rose-600 to-amber-600', '{"title": "兄弟的巨乳萝莉女友？是我的了", "desc": "你受好兄弟之托前往空无一人的隔音音乐室送钥匙，却在门缝后撞破了兄弟平时清纯可人的娇小女友许晓娜，正瘫坐在琴凳上满脸潮红地自我慰藉。手握致命秘密与羞耻把柄的你，将步步击溃她的心理防线。", "bg_image": "https://catai.wiki/1a54b4c9-f1de-4ce4-d32a-8c542fdbb800/bg"}', '[{"name": "兄弟的巨乳萝莉女友？是我的了", "role": "核心角色", "desc": "你受好兄弟之托前往空无一人的隔音音乐室送钥匙，却在门缝后撞破了兄弟平时清纯可人的娇小女友许晓娜，正瘫坐在琴凳上满脸潮红地自我慰藉。手握致命秘密与羞耻把柄的你，将步步击溃她的心理防线。"}]', '[{"title": "艺术楼深处 · 废弃隔音钢琴琴房 · 昏暗黄昏", "desc": "顺着幽暗走廊推开沉重的琴房门，微弱的喘息声与水渍黏腻声让你脚步顿住。斜阳穿透积灰的百叶窗，好兄弟陈伟那平日里乖巧单纯、身高仅一米五出头却生着极其丰满H罩杯的萝莉女友许晓娜，正瘫坐在钢琴长凳上。她的水手服裙摆被高高撩起堆在腰间，蕾丝底裤褪至膝弯，纤细的手指正沉溺在湿透泛滥的蜜核上剧烈动作，小嘴微张吐着灼热的甜香春气。听到开门声，她惊恐地回过头，正对上你居高临下的视线，整个人如遭雷击般僵在原地，娇躯止不住地瑟瑟发抖……"}]', '{"dialogue_style": "沉浸式感官细节描写，兼顾心理摩擦、禁断张力与高潮爆发", "format": "AI风月标准双栏规范"}', '[{"index": 1, "isUser": false, "scene": "艺术楼深处 · 废弃隔音钢琴琴房 · 昏暗黄昏", "story": "顺着幽暗走廊推开沉重的琴房门，微弱的喘息声与水渍黏腻声让你脚步顿住。斜阳穿透积灰的百叶窗，好兄弟陈伟那平日里乖巧单纯、身高仅一米五出头却生着极其丰满H罩杯的萝莉女友许晓娜，正瘫坐在钢琴长凳上。她的水手服裙摆被高高撩起堆在腰间，蕾丝底裤褪至膝弯，纤细的手指正沉溺在湿透泛滥的蜜核上剧烈动作，小嘴微张吐着灼热的甜香春气。听到开门声，她惊恐地回过头，正对上你居高临下的视线，整个人如遭雷击般僵在原地，娇躯止不住地瑟瑟发抖……", "branches": [{"tag": "A", "title": "顺应当前情境小心周旋应对", "desc": "保持镇定，仔细观察对方微表情与防备程度，稳步推进私密关系"}, {"tag": "B", "title": "出人意料反客为主试探底线", "desc": "打破被动，抓住对方破防或羞怯的瞬间，采取大胆主动的动作颠覆局势"}, {"tag": "C", "title": "制造独处私密借口深入交流", "desc": "将二人引向更隐秘的私密环境，拉开深层次互动帷幕"}, {"tag": "D", "title": "直接挑明自身真实意图与欲望", "desc": "撕开所有伪装与客套，直言不讳地掌控局面并主导节奏"}]}]', '', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>背德协奏曲：角色档案系统</title>
<style>
:root {
--bg-primary: #0a0a0c;
--bg-secondary: #16161e;
--bg-overlay: rgba(0, 0, 0, 0.85);
--color-primary: #e91e63;
--color-primary-hover: #ff4081;
--color-accent: #9c27b0;
--text-primary: #e0e0e0;
--text-secondary: #9494b8;
--text-on-primary: #ffffff;
--border-color: #303046;
--shadow-card: 0 8px 32px rgba(0, 0, 0, 0.5);
--spacing-md: 16px;
--radius-md: 8px;
--transition-normal: all 0.3s ease;
}
* { box-sizing: border-box; margin: 0; padding: 0; outline: none; -webkit-tap-highlight-color: transparent; }
body { font-family: ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif; background: var(--bg-primary); color: var(--text-primary); line-height: 1.6; overflow-x: hidden; }
.container { max-width: 600px; margin: 0 auto; padding: 20px; min-height: 100vh; display: flex; flex-direction: column; }
.header { text-align: center; padding: 40px 0; background: linear-gradient(180deg, #1a1a2e 0%, var(--bg-primary) 100%); border-bottom: 1px solid var(--border-color); margin-bottom: 20px; }
.header h1 { font-size: 24px; color: var(--color-primary); text-transform: uppercase; letter-spacing: 2px; text-shadow: 0 0 10px rgba(233, 30, 99, 0.5); }
.header p { font-size: 14px; color: var(--text-secondary); margin-top: 8px; }
.tab-list { display: flex; background: var(--bg-secondary); border-radius: var(--radius-md); padding: 4px; margin-bottom: 20px; border: 1px solid var(--border-color); }
.tab-btn { flex: 1; padding: 10px; border: none; background: transparent; color: var(--text-secondary); cursor: pointer; border-radius: 6px; font-weight: bold; transition: var(--transition-normal); }
.tab-btn.active { background: var(--color-primary); color: var(--text-on-primary); box-shadow: 0 4px 12px rgba(233, 30, 99, 0.3); }
.panel { background: var(--bg-secondary); border-radius: var(--radius-md); padding: 20px; border: 1px solid var(--border-color); box-shadow: var(--shadow-card); display: none; animation: fadeIn 0.4s ease; }
.panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
fieldset { border: none; margin-bottom: 20px; }
legend { font-size: 18px; font-weight: bold; color: var(--color-accent); margin-bottom: 15px; display: flex; align-items: center; }
legend::after { content: ''''; flex: 1; height: 1px; background: var(--border-color); margin-left: 15px; }
.form-group { margin-bottom: 15px; }
label { display: block; font-size: 13px; color: var(--text-secondary); margin-bottom: 6px; margin-left: 4px; }
input, select, textarea { width: 100%; padding: 12px; background: #0f0f15; border: 1px solid var(--border-color); border-radius: 6px; color: var(--text-primary); font-size: 15px; transition: var(--transition-normal); }
input:focus, select:focus, textarea:focus { border-color: var(--color-primary); box-shadow: 0 0 0 2px rgba(233, 30, 99, 0.2); background: #161620; }
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 15px; }
.btn-group { display: grid; grid-template-columns: 1fr 1fr; gap: 15px; margin-top: 10px; }
.btn { padding: 14px; border: none; border-radius: var(--radius-md); cursor: pointer; font-weight: bold; font-size: 15px; transition: var(--transition-normal); display: flex; align-items: center; justify-content: center; gap: 8px; }
.btn-primary { background: var(--color-primary); color: var(--text-on-primary); }
.btn-primary:hover { background: var(--color-primary-hover); transform: translateY(-2px); }
.btn-secondary { background: #2d2d3f; color: var(--text-primary); border: 1px solid var(--border-color); }
.btn-secondary:hover { background: #3d3d55; }
.random-tag { display: inline-block; padding: 4px 10px; border-radius: 20px; font-size: 12px; margin: 4px; cursor: pointer; border: 1px solid var(--border-color); background: #1a1a26; transition: var(--transition-normal); }
.random-tag:hover { border-color: var(--color-primary); color: var(--color-primary); }
.tag-rare { color: #00e5ff; border-color: #00e5ff; }
.tag-epic { color: #d500f9; border-color: #d500f9; }
.tag-legend { color: #ffab00; border-color: #ffab00; text-shadow: 0 0 5px rgba(255, 171, 0, 0.5); }
footer { text-align: center; padding: 20px; font-size: 12px; color: var(--text-secondary); margin-top: auto; }
footer a { color: var(--color-primary); text-decoration: none; }
#intro-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: #000; z-index: 9999; display: flex; flex-direction: column; align-items: center; justify-content: center; transition: opacity 0.8s ease; cursor: pointer; }
.svg-logo { width: 120px; height: 120px; margin-bottom: 20px; animation: pulse 2s infinite; }
@keyframes pulse { 0% { transform: scale(1); opacity: 0.8; } 50% { transform: scale(1.1); opacity: 1; } 100% { transform: scale(1); opacity: 0.8; } }
@media (max-width: 480px) { .grid-2 { grid-template-columns: 1fr; } .header h1 { font-size: 20px; } }
@media (prefers-reduced-motion: reduce) { * { animation: none !important; transition: none !important; } #intro-overlay { display: none; } }
</style>
</head>
<body>
<div id="intro-overlay" role="dialog" aria-label="开场动画">
<svg class="svg-logo" viewBox="0 0 100 100">
<circle cx="50" cy="50" r="45" fill="none" stroke="#e91e63" stroke-width="2" stroke-dasharray="280" stroke-dashoffset="280">
<animate attributeName="stroke-dashoffset" from="280" to="0" dur="2s" fill="freeze" />
</circle>
<path d="M30 50 L45 65 L70 35" fill="none" stroke="#e91e63" stroke-width="5" stroke-linecap="round" stroke-linejoin="round">
<animate attributeName="stroke-dashoffset" from="100" to="0" dur="1s" begin="1.5s" fill="freeze" />
</path>
</svg>
<div style="color:#e91e63; font-weight:bold; letter-spacing:4px;">DEEP ABYSS</div>
<div style="color:#666; font-size:12px; margin-top:10px;">点击任意位置进入深渊</div>
</div>
<div class="header">
<h1>背德协奏曲</h1>
<p>DEBAUCHERY CONCERTO: CHARACTER CREATOR</p>
</div>
<div class="container">
<div class="tab-list" role="tablist">
<button class="tab-btn active" role="tab" aria-selected="true" aria-controls="panel-player" id="tab-player">玩家设定</button>
<button class="tab-btn" role="tab" aria-selected="false" aria-controls="panel-world" id="tab-world">世界/目标</button>
</div>
<div class="panel active" id="panel-player" role="tabpanel" aria-labelledby="tab-player">
<fieldset>
<legend>身份核验</legend>
<div class="form-group">
<label for="p-name">玩家代号</label>
<input type="text" id="p-name" placeholder="请输入你的姓名..." aria-required="true">
</div>
<div class="grid-2">
<div class="form-group">
<label for="p-age">生理年龄</label>
<input type="number" id="p-age" value="20" min="18">
</div>
<div class="form-group">
<label for="p-job">社会身份</label>
<select id="p-job">
<option value="陈伟的好兄弟">陈伟的好兄弟</option>
<option value="暗处的窥视者">暗处的窥视者</option>
<option value="家族资助人">家族资助人</option>
<option value="音乐学院导师">音乐学院导师</option>
</select>
</div>
</div>
</fieldset>
<fieldset>
<legend>特质抽取</legend>
<div class="form-group">
<label>已觉醒天赋 (点击选择)</label>
<div id="random-pool">
<span class="random-tag tag-legend" onclick="selectTag(this)">催眠低语</span>
<span class="random-tag tag-epic" onclick="selectTag(this)">绝对掌控</span>
<span class="random-tag tag-rare" onclick="selectTag(this)">器大活好</span>
<span class="random-tag" onclick="selectTag(this)">摄影大师</span>
</div>
<button class="btn btn-secondary" style="width:auto; padding:8px 15px; font-size:12px; margin-top:10px;" onclick="rerollTags()">重新抽取</button>
</div>
<div class="form-group">
<label for="p-trait">核心特质描述</label>
<textarea id="p-trait" rows="3" placeholder="描述你的性格、外貌特征或特殊性癖..."></textarea>
</div>
</fieldset>
</div>
<div class="panel" id="panel-world" role="tabpanel" aria-labelledby="tab-world">
<fieldset>
<legend>目标锁定</legend>
<div class="form-group">
<label>锁定目标</label>
<input type="text" value="许晓娜 (陈伟女友)" readonly style="background:#1a1a26; color:var(--color-primary);">
</div>
<div class="form-group">
<label for="w-start">开场设定</label>
<textarea id="w-start" rows="4">你推开了音乐室的门，看到许晓娜正夹着震动的跳蛋，满脸潮红地瘫坐在钢琴椅上。陈伟的口信被你揉成一团，你反手锁上了门...</textarea>
</div>
</fieldset>
<fieldset>
<legend>系统倾向</legend>
<div class="grid-2">
<div class="form-group">
<label for="sys-type">主导系统</label>
<select id="sys-type">
<option value="恶堕/服从">恶堕/服从 (高主动性)</option>
<option value="催眠/改造">催眠/改造 (人格重塑)</option>
<option value="公开/羞辱">公开/羞辱 (社会崩坏)</option>
</select>
</div>
<div class="form-group">
<label for="sys-hard">攻略难度</label>
<select id="sys-hard">
<option value="简单-肉欲横流">简单-肉欲横流</option>
<option value="普通-背德挣扎">普通-背德挣扎</option>
<option value="困难-冰山校花">困难-冰山校花</option>
</select>
</div>
</div>
</fieldset>
</div>
<div class="btn-group">
<button class="btn btn-secondary" onclick="resetForm()">重置数据</button>
<button class="btn btn-primary" onclick="copyData()">开启深渊剧情</button>
</div>
<footer>
<a href="https://aiaha.xyz/zh/explore/installed/786829f3-8fab-4f09-85fa-cbf839b79123%spreview=1&ref_id=e62df45e-f7e4-4887-b950-8e30e7b3d8f2" target="_blank">本页面采用【万能生成器】生成</a>
</footer>
</div>
<div id="toast" style="position:fixed; bottom:30px; left:50%; transform:translateX(-50%); background:var(--color-primary); color:#white; padding:10px 20px; border-radius:20px; display:none; z-index:10000; box-shadow:0 4px 15px rgba(0,0,0,0.5);" role="alert" aria-live="polite"></div>
<script>
const tabs = document.querySelectorAll(''.tab-btn'');
const panels = document.querySelectorAll(''.panel'');
tabs.forEach(tab => {
tab.addEventListener(''click'', () => {
tabs.forEach(t => { t.classList.remove(''active''); t.setAttribute(''aria-selected'', ''false''); });
panels.forEach(p => p.classList.remove(''active''));
tab.classList.add(''active'');
tab.setAttribute(''aria-selected'', ''true'');
document.getElementById(tab.getAttribute(''aria-controls'')).classList.add(''active'');
});
});
function selectTag(el) {
const traitArea = document.getElementById(''p-trait'');
if(!traitArea.value.includes(el.innerText)) {
traitArea.value += (traitArea.value %s ''，'' : '''') + el.innerText;
}
}
function rerollTags() {
const pool = document.getElementById(''random-pool'');
const tags = [
{n:''视奸成瘾'', q:''''}, {n:''言语凌辱'', q:''tag-rare''}, {n:''钞能力'', q:''tag-epic''},
{n:''体能怪物'', q:''tag-rare''}, {n:''触手操控'', q:''tag-legend''}, {n:''纯爱战神(伪)'', q:''tag-epic''},
{n:''道具专家'', q:''''}, {n:''录像怪癖'', q:''tag-rare''}
];
pool.innerHTML = '''';
for(let i=0; i<4; i++) {
const r = tags[Math.floor(Math.random()*tags.length)];
pool.innerHTML += `<span class="random-tag ${r.q}" onclick="selectTag(this)">${r.n}</span>`;
}
}
function copyData() {
const name = document.getElementById(''p-name'').value;
if(!name) {
showToast(''请输入玩家代号！'');
document.getElementById(''p-name'').focus();
document.getElementById(''p-name'').setAttribute(''aria-invalid'', ''true'');
return;
}
const data = `【用户信息】\n姓名：${name}\n年龄：${document.getElementById(''p-age'').value}\n身份：${document.getElementById(''p-job'').value}\n特质：${document.getElementById(''p-trait'').value}\n系统：${document.getElementById(''sys-type'').value}\n难度：${document.getElementById(''sys-hard'').value}\n【开场设定】\n${document.getElementById(''w-start'').value}`;
const tempInput = document.createElement(''textarea'');
tempInput.value = data;
document.body.appendChild(tempInput);
tempInput.select();
try {
document.execCommand(''copy'');
showToast(''✅ 档案已加密复制，准备进入深渊...'');
} catch (err) {
showToast(''❌ 复制失败，请手动选择'');
}
document.body.removeChild(tempInput);
}
function showToast(msg) {
const t = document.getElementById(''toast'');
t.innerText = msg;
t.style.display = ''block'';
setTimeout(() => { t.style.display = ''none''; }, 2000);
}
function resetForm() {
if(confirm(''确定要清除所有档案数据吗？'')) {
location.reload();
}
}
document.getElementById(''intro-overlay'').addEventListener(''click'', function() {
this.style.opacity = ''0'';
setTimeout(() => { this.style.display = ''none''; }, 800);
});
setTimeout(() => {
const overlay = document.getElementById(''intro-overlay'');
if(overlay.style.display !== ''none'') {
overlay.style.opacity = ''0'';
setTimeout(() => { overlay.style.display = ''none''; }, 800);
}
}, 4000);
</script>
</body>', '都市', '2026-09-16 11:22:22', '2026-09-16 11:22:22', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_sister_late_night_return', '✨ 妹妹最近总是和她的小姐妹玩到深夜才回来', '家庭 · 叛逆反差', '✨', '✨ 妹妹最近总是和她的小姐妹玩到深夜才回来', '家庭 · 叛逆反差', '✨', '#ec4899', 'linear-gradient(135deg, #db2777 0%, #f472b6 100%)', '{"title": "✨ 妹妹最近总是和她的小姐妹玩到深夜才回来", "desc": "✨ 妹妹最近总是和她的小姐妹玩到深夜才回来", "bg_image": "https://catai.wiki/fd84c923-c169-453e-419b-1e317df8e500/cover", "opening_options": ["【深夜客厅·留灯守候】：“午夜零点门锁轻响，苏浅浅换鞋进门，宽大旧T恤领口斜露着香肩，带着微弱烟酒气皱眉：‘这么晚不睡……看我干嘛？烦死了。’”", "【闺蜜留宿·双人微醺】：“妹妹今晚把黑长直闺蜜星见遥带回了家，两人躺在沙发上咬耳朵说悄悄话，星见遥紫眸深邃地打量着你……”", "【房间对质·手机秘密】：“你推开妹妹虚掩的房门想找她谈谈，她正趴在床上玩手机，惊慌锁屏翻身坐起，胸口剧烈起伏：‘进门前不知道敲门啊？！’”"]}', '[{"name": "苏浅浅", "role": "妹妹 (16岁 / 蓝发蓝瞳 / 叛逆期 / 口嫌体正直)", "desc": "你的亲妹妹。小时候寸步不离黏着你，如今进入青春叛逆期，在家穿着大码旧T恤露出雪白香肩，嘴硬嫌弃你管得宽，在外却时刻关注着哥哥对自己的态度。"}, {"name": "星见遥", "role": "小姐妹闺蜜 (17岁 / 黑长直紫瞳 / 耳钉不良少女)", "desc": "苏浅浅最好的闺蜜。腰身收紧的短裙校服，修长大腿上贴着创可贴，身上带着淡淡烟草香。眼神极具压迫感，却对你和浅浅的关系抱有极深的好奇。"}, {"name": "哥哥 (玩家)", "role": "家庭守护者", "desc": "独守冷清客厅、为深夜归来的妹妹留一盏灯的哥哥。"}]', '[{"title": "昏暗客厅 · 电视荧幕微光中", "desc": "零点已过的冷清公寓，电视无声闪烁，玄关突然传来了钥匙摸索门孔的声响。"}]', '{"dialogue_style": "沉浸式细腻小说叙事，富有张力的肉体与情感博弈", "format": "AI风月标准双栏规范及.custom-ui样式"}', '{"index": 1, "isUser": false, "scene": "昏暗客厅 · 电视荧幕微光中", "story": "<tl>📅时间：深夜 00:15 | 🌏地点：家中客厅沙发 | 🌙光线：电视幽蓝微光</tl>\n\n<article>\n<p>电视里的深夜节目静音播放着，蓝白色的荧幕冷光在静悄悄的客厅里忽明忽暗。墙上的挂钟指针已经悄然滑过了零点一刻。</p>\n\n<p>咔嚓——</p>\n\n<p>门把手终于被小心翼翼地拧动。防盗门推开一道窄缝，苏浅浅像只做贼心虚的小猫一样悄悄溜了进来。她脚上踩着松松垮垮的帆布鞋，身上套着一件你的旧白T恤当作外穿罩衫，领口松垮地歪向一边，露出一整片细白无瑕的精致香肩和锁骨。空气里除了她身上特有的少女甜香，还混着一丝淡淡的街头烟味。</p>\n\n<p>当她换好鞋抬起头，一眼撞见端坐在沙发上注视着她的你时，那对漂亮的浅蓝色眼瞳明显慌乱地颤了一下，随即立刻像被踩了尾巴一样紧紧蹙起柳眉：</p>\n\n<p><w>“……你怎么还没睡啊？！”</w>她抱着自己的小双肩包快步从你面前走过，故意不看你的眼睛，嘴硬地嘟囔道，<w>“都说了跟同学在外面复习功课……你干嘛像审犯人一样瞪着我？烦死了！”</w></p>\n</article>", "branches": [{"tag": "A", "title": "强势主动", "desc": "把握主导权，将局势引向最深层的欲望试探"}, {"tag": "B", "title": "细致观察", "desc": "审视对方微小的呼吸与神态变化，步步为营"}, {"tag": "C", "title": "言语挑逗", "desc": "用暧昧低沉的耳语彻底击溃对方的心防防线"}]}', '', '<!DOCTYPE html>
<html lang="zh">
<head>
