INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, cover_image, image_tag, badge_type, is_featured, category, created_at) VALUES ('136535c4-5b02-4938-b30d-6631d2218653', '136535c4-5b02-4938-b30d-6631d2218653', '趁老婆产检，我把小姨子操成了性奴', '多角色 · 乱伦', '#ec4899', 'ailuolidedashu', '老婆怀孕禁欲三个月，我憋得快发疯。那天她去医院做产检，小姨子带着胎教CD上门，却手贱打开了影碟机里那两张A片。她脸红着夹紧腿，嘴上逞强说不是小孩子了。挂掉老婆说晚归的电话，整个下午就剩我们两个人。从破处的第一次调教，到臣服度一点点涨满，怀孕三个月产检回来的老婆站在门口，看着连在一起的我们，反手把门锁上了——她不是来撕破脸的，她是来入伙的。一个关于姐夫、小姨子、孕妇老婆的长期家庭调教养成。', '10', '["多角色", "乱伦", "姐妹花", "开局即可色", "纯爱", "后宫", "调教"]', '1807 玩过', 0, 'https://catai.wiki/0ef5da04-ebcb-4a8e-4898-dac56d7c5200/cover', 'HOT', 'fire', 1, '多角色', '2026-10-12 22:00:07') ON CONFLICT (title) DO NOTHING;
