INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, cover_image, image_tag, badge_type, is_featured, category, created_at) VALUES ('5395361a-9dbb-41fc-bbfb-aa67e229a434', '5395361a-9dbb-41fc-bbfb-aa67e229a434', '被父母抛弃的失明少女要拿处女身抵房租', '都市 · 视觉剥夺', '#06b6d4', 'AI风月官方', '和平里六号楼302室的房租已逾期半个月，电话始终无法接通。

